use crate::compact::{CompactError, compact};
use crate::types::AmConfig;

/// Pre-split text chunk with its own KV slice and global position offset.
///
/// Used as input to [`ChunkedCompactor::compact_text_based`].
#[derive(Clone, Debug)]
pub struct TextChunk {
    /// Flat `(chunk_len, d)` keys for this chunk.
    pub keys: Vec<f32>,
    /// Flat `(chunk_len, d)` values for this chunk.
    pub values: Vec<f32>,
    /// Global position offset (token index) where this chunk begins.
    pub start_pos: usize,
    /// Number of tokens in this chunk.
    pub chunk_len: usize,
}

/// Per-chunk metadata in a [`ChunkedCompactOutput`].
#[derive(Clone, Copy, Debug, Default)]
pub struct ChunkMeta {
    /// Original global position where this chunk began.
    pub chunk_start: usize,
    /// Number of original tokens in this chunk (post-overlap if KV-based).
    pub chunk_len: usize,
    /// Number of tokens after compaction for this chunk.
    pub compact_len: usize,
    /// Relative attention-output reconstruction error for this chunk.
    pub reconstruction_error: f32,
}

/// Concatenated output of a chunked compaction run.
#[derive(Clone, Debug, Default)]
pub struct ChunkedCompactOutput {
    /// Concatenated compact keys, flat `(sum_t, d)`.
    pub compact_keys: Vec<f32>,
    /// Concatenated per-token β, length `sum_t`.
    pub beta: Vec<f32>,
    /// Concatenated compact values, flat `(sum_t, d)`.
    pub compact_values: Vec<f32>,
    /// `sum_t` — total tokens across all compacted chunks.
    pub total_compact_len: usize,
    /// Per-chunk metadata, length = number of chunks processed.
    pub per_chunk: Vec<ChunkMeta>,
}

/// Chunked compactor that splits long KV caches and compacts each chunk.
#[derive(Clone, Copy, Debug)]
pub struct ChunkedCompactor {
    /// Tokens per chunk (excluding overlap).
    pub chunk_size: usize,
    /// Overlap tokens between adjacent chunks (KV-based mode).
    pub overlap: usize,
}

impl ChunkedCompactor {
    /// Create a new chunked compactor.
    ///
    /// Panics iff `chunk_size == 0` or `overlap >= chunk_size` (overlap must
    /// be strictly smaller than the chunk so each chunk has unique tokens).
    pub fn new(chunk_size: usize, overlap: usize) -> Self {
        assert!(chunk_size > 0, "chunk_size must be > 0");
        assert!(
            overlap < chunk_size,
            "overlap ({overlap}) must be < chunk_size ({chunk_size})"
        );
        Self {
            chunk_size,
            overlap,
        }
    }

impl ChunkedCompactOutput {
    /// Mean per-chunk reconstruction error.
    pub fn mean_reconstruction_error(&self) -> f32 {
        if self.per_chunk.is_empty() {
            return 0.0;
        }
        let sum: f32 = self.per_chunk.iter().map(|c| c.reconstruction_error).sum();
        sum / self.per_chunk.len() as f32
    }

    /// Boundary reconstruction error — mean of the first and last chunk only.
    ///
    /// Useful for comparing overlap vs no-overlap: with overlap, boundary
    /// chunks should have lower error because they "see" context from the
    /// adjacent chunk.
    pub fn boundary_reconstruction_error(&self) -> f32 {
        match self.per_chunk.len() {
            0 => 0.0,
            1 => self.per_chunk[0].reconstruction_error,
            _ => {
                let n = self.per_chunk.len();
                (self.per_chunk[0].reconstruction_error
                    + self.per_chunk[n - 1].reconstruction_error)
                    / 2.0
            }
        }
    }
}

impl HeadSensitivityCurve {
    /// Construct a curve, validating that ratios are sorted ascending and
    /// parallel in length to deltas.
    pub fn new(head_id: usize, ratios: Vec<f32>, deltas: Vec<f32>) -> Self {
        assert_eq!(
            ratios.len(),
            deltas.len(),
            "ratios and deltas must be parallel"
        );
        assert!(!ratios.is_empty(), "curve must have at least one point");
        for w in ratios.windows(2) {
            assert!(
                w[0] <= w[1],
                "ratios must be sorted ascending (got {ratios:?})"
            );
        }
        Self {
            head_id,
            ratios,
            deltas,
        }
    }

    /// Linear interpolation of the quality delta at the given ratio.
    ///
    /// - Below `ratios[0]`, returns `deltas[0]` (flat extrapolation).
    /// - Above `ratios[last]`, returns `deltas[last]` (flat extrapolation).
    /// - Within range, linear interpolation between the two surrounding points.
    #[inline]
    pub fn interpolate(&self, ratio: f32) -> f32 {
        let n = self.ratios.len();
        if n == 1 {
            return self.deltas[0];
        }
        if ratio <= self.ratios[0] {
            return self.deltas[0];
        }
        if ratio >= self.ratios[n - 1] {
            return self.deltas[n - 1];
        }
        // Binary search would be faster for large curves, but the typical
        // curve has 5–10 points, so a linear scan is cache-friendly and
        // branch-predictable.
        let mut i = 0usize;
        while i + 1 < n && self.ratios[i + 1] < ratio {
            i += 1;
        }
        let r0 = self.ratios[i];
        let r1 = self.ratios[i + 1];
        let d0 = self.deltas[i];
        let d1 = self.deltas[i + 1];
        let span = r1 - r0;
        if span.abs() < STABILITY_EPS {
            return d0;
        }
        let t = (ratio - r0) / span;
        d0 + t * (d1 - d0)
    }

    /// Marginal quality gain when increasing this head's ratio from
    /// `r_from` to `r_from + step` (i.e., quality recovered by giving the
    /// head more budget). Positive = more quality recovered.
    ///
    /// `interpolate(r_from) - interpolate(r_from + step)` because deltas are
    /// quality *losses*: a larger ratio → smaller delta → less loss → gain.
    #[inline]
    pub fn marginal_gain(&self, r_from: f32, step: f32) -> f32 {
        self.interpolate(r_from) - self.interpolate(r_from + step)
    }

    /// Number of measured points.
    #[inline]
    pub fn len(&self) -> usize {
        self.ratios.len()
    }

    /// Whether the curve is empty (always false after `new` since we assert
    /// non-empty, but provided for clippy).
    #[inline]
    pub fn is_empty(&self) -> bool {
        self.ratios.is_empty()
    }
}

use serde::{Deserialize, Serialize};

/// A solved per-head budget schedule, ready for serialization and deployment.
///
/// # Tamper detection
/// `blake3_hash` covers `model_id` (UTF-8 bytes) and `shares` (little-endian
/// f32 bytes), in that order. `verify()` recomputes the hash and compares;
/// any mismatch indicates corruption or tampering.
///
/// # Versioning
/// `version` starts at 1 and is bumped by callers when they re-solve with
/// new sensitivity data. The hash does not cover `version` (changing the
/// version alone is a metadata update, not a content change).
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct HeadBudgetSchedule {
    /// Model identifier this schedule applies to (e.g., "llama-3-8b").
    pub model_id: String,
    /// Per-head budget shares. Length = num_layers × num_heads. Each entry is
    /// the ratio (in `[0, 1]`) allocated to that head.
    pub shares: Vec<f32>,
    /// Schedule version (bumped on re-solve).
    pub version: u32,
    /// BLAKE3 hash of `(model_id, shares)` for tamper detection.
    pub blake3_hash: [u8;

impl HeadBudgetSchedule {
    /// Construct a schedule from a solved shares vector. Computes the BLAKE3
    /// hash automatically and sets `version = 1`.
    pub fn new(model_id: String, shares: Vec<f32>) -> Self {
        let blake3_hash = compute_hash(&model_id, &shares);
        Self {
            model_id,
            shares,
            version: 1,
            blake3_hash,
        }
    }

    /// Construct a schedule with an explicit version. Recomputes the hash.
    pub fn with_version(model_id: String, shares: Vec<f32>, version: u32) -> Self {
        let blake3_hash = compute_hash(&model_id, &shares);
        Self {
            model_id,
            shares,
            version,
            blake3_hash,
        }
    }

    /// Recompute the BLAKE3 hash from `model_id` and `shares`, and verify it
    /// matches the stored `blake3_hash`. Returns `true` if the schedule is
    /// intact (not tampered with).
    pub fn verify(&self) -> bool {
        let recomputed = compute_hash(&self.model_id, &self.shares);
        // Constant-time comparison via BLAKE3's own equality (it's a fixed
        // 32-byte array; we use a simple loop to avoid early-exit timing
        // side channels, though for non-secret data this is overkill).
        let mut diff: u8 = 0;
        for i in 0..32 {
            diff |= recomputed[i] ^ self.blake3_hash[i];
        }
        diff == 0
    }

    /// Serialize to postcard bytes.
    pub fn to_postcard(&self) -> Result<Vec<u8>, postcard::Error> {
        postcard::to_allocvec(self)
    }

    /// Deserialize from postcard bytes.
    pub fn from_postcard(bytes: &[u8]) -> Result<Self, postcard::Error> {
        postcard::from_bytes(bytes)
    }
}

