use crate::compact::{CompactError, compact};
use crate::types::{AmConfig, AmResult};

/// Result of a single online compaction pass.
#[derive(Clone, Debug)]
pub struct OnlineCompactResult {
    /// Compacted older tokens (the prefix). `compact_prefix.compact_len` is
    /// the logical contribution of the prefix.
    pub compact_prefix: AmResult,
    /// Uncompacted recent keys (raw, bit-identical to input slice).
    /// Flat `(recent_window, d)`.
    pub recent_keys: Vec<f32>,
    /// Uncompacted recent values (raw, bit-identical to input slice).
    /// Flat `(recent_window, d)`.
    pub recent_values: Vec<f32>,
    /// Global position where the recent window starts in the original
    /// sequence. Equal to `current_pos - recent_window` at compaction time.
    pub recent_start_pos: usize,
    /// Total logical length = `compact_prefix.compact_len + recent_window`.
    /// This is the sequence length the model sees after this compaction.
    pub total_logical_len: usize,
}

/// Mid-trajectory compactor for unbounded generation.
#[derive(Clone, Copy, Debug)]
pub struct OnlineCompactor {
    /// Maximum compacted tokens before triggering compaction.
    pub phys_budget: usize,
    /// Number of most-recent tokens to always preserve uncompacted.
    pub recent_window: usize,
}

impl OnlineCompactor {
    /// Create a new online compactor.
    ///
    /// Panics iff `phys_budget == 0` or `recent_window == 0` (both must be
    /// positive — a zero recent window would mean compacting the active token,
    /// and a zero budget would trigger every step).
    pub fn new(phys_budget: usize, recent_window: usize) -> Self {
        assert!(phys_budget > 0, "phys_budget must be > 0");
        assert!(recent_window > 0, "recent_window must be > 0");
        Self {
            phys_budget,
            recent_window,
        }
    }

impl OnlineCompactResult {
    /// Total bytes used by the post-compaction cache (f32 storage).
    ///
    /// Compact prefix: `compact_len * (2*d + 1)` f32 (Ck, β, Cv).
    /// Recent suffix: `recent_window * 2 * d` f32 (raw K, V).
    pub fn total_bytes(&self, d: usize) -> usize {
        let prefix_bytes =
            self.compact_prefix.compact_len * (2 * d + 1) * std::mem::size_of::<f32>();
        let recent_bytes = self.recent_keys.len() * std::mem::size_of::<f32>()
            + self.recent_values.len() * std::mem::size_of::<f32>();
        prefix_bytes + recent_bytes
    }

    /// Bytes saved by this compaction vs. the un-compacted prefix.
    ///
    /// Original prefix storage: `prefix_original_len * 2 * d * sizeof(f32)`.
    pub fn bytes_saved(&self, d: usize) -> usize {
        let original_prefix_bytes =
            self.compact_prefix.original_len * 2 * d * std::mem::size_of::<f32>();
        original_prefix_bytes.saturating_sub(
            self.total_bytes(d)
                - self.recent_keys.len() * std::mem::size_of::<f32>()
                - self.recent_values.len() * std::mem::size_of::<f32>(),
        )
    }
}

impl SolverBackend {
    /// Human-readable name for logging.
    #[inline]
    pub fn as_str(self) -> &'static str {
        match self {
            Self::CpuScalar => "cpu_scalar",
            Self::CpuSimd => "cpu_simd",
            Self::CpuRayon => "cpu_rayon",
            Self::Gpu => "gpu",
            Self::Ane => "ane",
        }
    }
}

impl SolverRouter {
    /// Construct a router with the given config. No prior decision history.
    #[inline]
    pub fn new(config: SolverRouterConfig) -> Self {
        Self {
            config,
            last_backend: None,
            last_t: None,
        }
    }

    /// Router configuration (read-only view).
    #[inline]
    pub fn config(&self) -> &SolverRouterConfig {
        &self.config
    }

    /// Pick the best backend for the current problem.
    ///
    /// # Arguments
    /// * `t` - Compact size (number of tokens to retain).
    /// * `T` - Original sequence length (unused now; reserved for future
    ///   memory-bandwidth-aware routing — see plan T2.5).
    /// * `gpu_available` - Whether a GPU backend is dispatchable right now.
    ///
    /// # Hysteresis
    /// If `last_backend` exists and the relative change in `t` since the last
    /// decision is less than `hysteresis_pct`, the prior backend is retained
    /// (no flapping). First call always returns the freshly-decided backend.
    ///
    /// # Determinism
    /// Given fixed `(t, T, gpu_available)` and an empty history, the returned
    /// backend is deterministic. With history, the hysteresis rule is also
    /// deterministic. (GOAT G6.)
    pub fn pick_backend(
        &mut self,
        t: usize,
        _original_len: usize,
        gpu_available: bool,
    ) -> SolverBackend {
        let target = self.target_backend(t, gpu_available);

        // Hysteresis: if the relative change in t since the last decision is
        // less than `hysteresis_pct`, retain the prior backend regardless of
        // what the fresh target would be. This avoids flapping when t hovers
        // near a threshold. First call always follows the target.
        //
        // Note: device availability changes (e.g., GPU going online) do NOT
        // bypass hysteresis — callers should invoke `reset()` when the device
        // topology changes to force a fresh decision.
        let kept = match (self.last_backend, self.last_t) {
            (Some(_), Some(last_t)) if last_t > 0 => {
                let diff = t.abs_diff(last_t);
                let rel = (diff as f32) / (last_t as f32);
                rel < self.config.hysteresis_pct
            }
            _ => false,
        };

        let chosen = if kept {
            self.last_backend.unwrap_or(target)
        } else {
            target
        };

        self.last_backend = Some(chosen);
        self.last_t = Some(t);
        chosen
    }

    /// Decide the target backend ignoring hysteresis.
    ///
    /// Rules (evaluated in order, first match wins):
    /// 1. `t <= ane_max_t` → `Ane` (output-role override).
    /// 2. `t <= cpu_max_t` → `CpuScalar`.
    /// 3. `t <= simd_max_t` → `CpuSimd`.
    /// 4. `t >= gpu_min_t && gpu_available` → `Gpu`.
    /// 5. `t >= simd_max_t && !gpu_available` → `CpuRayon`.
    /// 6. Otherwise → `CpuSimd`.
    ///
    /// Note rule 1 overrides rule 2 — `ane_max_t` is the output-role override,
    /// not a strict size threshold. Both default to small-t regimes; if the
    /// user configures them apart (e.g., `ane_max_t=16`, `cpu_max_t=64`),
    /// the ANE rule only triggers for the smallest roles.
    #[inline]
    fn target_backend(&self, t: usize, gpu_available: bool) -> SolverBackend {
        // Output-role override: ANE handles small compact sizes best.
        if t <= self.config.ane_max_t {
            return SolverBackend::Ane;
        }
        if t <= self.config.cpu_max_t {
            return SolverBackend::CpuScalar;
        }
        if t <= self.config.simd_max_t {
            return SolverBackend::CpuSimd;
        }
        if t >= self.config.gpu_min_t && gpu_available {
            return SolverBackend::Gpu;
        }
        if t >= self.config.simd_max_t && !gpu_available {
            return SolverBackend::CpuRayon;
        }
        // Fallback: between simd_max_t and gpu_min_t with no GPU.
        SolverBackend::CpuSimd
    }

    /// Reset hysteresis state (useful when workload regime changes sharply).
    #[inline]
    pub fn reset(&mut self) {
        self.last_backend = None;
        self.last_t = None;
    }
}

use crate::STABILITY_EPS;

/// Compute the score matrix `S = Q·K^T · inv_sqrt_d` for `(n, d)` queries and
/// `(T, d)` keys. Output is row-major `(n, T)` written into the caller-provided
/// `out` buffer (length `n * T`).
///
/// The output is NOT stabilized — callers must apply max-shift before `exp()`.
/// Use [`compute_softmax_attention`] for the stabilized softmax version.
///
/// # Panics
/// Panics if `out.len() != n * T` or if dimension mismatches.
#[inline]
pub fn compute_score_matrix(
    queries: &[f32], // (n, d) row-major
    keys: &[f32],    // (T, d) row-major
    n: usize,
    t_len: usize,
    d: usize,
    out: &mut [f32], // (n, T) row-major
) {
    assert_eq!(queries.len(), n * d, "queries buffer size mismatch");
    assert_eq!(keys.len(), t_len * d, "keys buffer size mismatch");
    assert_eq!(out.len(), n * t_len, "output buffer size mismatch");

    let inv_sqrt_d = 1.0f32 / (d as f32).sqrt();

    // Reuse the shared `dot_8wide` kernel (8-wide chunked FMA, auto-vectorizes
    // on AVX2/NEON) instead of a duplicated manual unroll. Keeps the scalar and
    // SIMD paths in `score_matrix_simd` bit-identical by construction (DRY).
    use crate::score_matrix_simd::dot_8wide;
    for i in 0..n {
        let q_row = &queries[i * d..(i + 1) * d];
        let out_row = &mut out[i * t_len..(i + 1) * t_len];
        for j in 0..t_len {
            let k_row = &keys[j * d..(j + 1) * d];
            out_row[j] = dot_8wide(q_row, k_row, d) * inv_sqrt_d;
        }
    }
}

impl std::error::Error for GpuDispatchError {}

/// Attempt to compute the score matrix `S = Q·K^T · inv_sqrt_d` on GPU.
///
/// This is the entry point invoked by
/// `crate::compact::dispatch_score_matrix` when the router
/// selects `SolverBackend::Gpu`. On success, `out` is fully written. On
/// failure, `out` is left untouched and the caller falls back to the
/// rayon-parallel CPU kernel.
///
/// # Current behavior
///
/// **Stub**: always returns [`GpuDispatchError::ShaderNotAvailable`]. The
/// router still records `SolverBackend::Gpu` in the trace, but the actual
/// compute happens on the CPU via the rayon fallback. This keeps the
/// dispatch path tested end-to-end (router → stub → fallback → correct
/// output) without requiring a Metal shader to be present.
///
/// # Future work
///
/// 1. Bundle an MSL shader for `(n, d) × (T, d)^T → (n, T)` matmul with
///    pre-applied `1/√d` scaling.
/// 2. Compile the pipeline lazily on first dispatch and cache it on the
///    device.
/// 3. Profile the cross-over point vs rayon on Apple Silicon (the paper's
///    4× AVX2 SIMD target suggests GPU wins above some `T`).
pub fn try_compute_score_matrix_gpu(
    _queries: &[f32],
    _keys: &[f32],
    _n: usize,
    _t_len: usize,
    _d: usize,
    _out: &mut [f32],
) -> Result<(), GpuDispatchError> {
