        let original_bytes = self.original_len * self.head_dim * 2 * std::mem::size_of::<f32>();
        let compact_bytes = self.compact_len * (self.head_dim * 2 + 1) * std::mem::size_of::<f32>();
        original_bytes.saturating_sub(compact_bytes)
    }
