impl WelfordVariance {
    /// Observe one sample. O(1), 3 flops.
    #[inline]
    pub fn observe(&mut self, x: f32) {
        self.count += 1;
        let x = x as f64;
        let delta = x - self.mean;
        self.mean += delta / self.count as f64;
        let delta2 = x - self.mean;
        self.m2 += delta * delta2;
    }

    /// Number of observations.
    #[inline]
    pub fn count(&self) -> u64 {
        self.count
    }

    /// Sample mean. Returns 0.0 if no observations.
    #[inline]
    pub fn mean(&self) -> f32 {
        self.mean as f32
    }

    /// Sample variance (n-1 denominator). Returns 0.0 for < 2 observations.
    pub fn variance(&self) -> f32 {
        if self.count < 2 {
            return 0.0;
        }
        (self.m2 / (self.count as f64 - 1.0)) as f32
    }

    /// Sample standard deviation.
    #[inline]
    pub fn std_dev(&self) -> f32 {
        self.variance().sqrt()
    }

    /// Reset to empty state.
    pub fn reset(&mut self) {
        *self = Self::default();
    }
}

impl ChiarRegimeGate {
    /// Create a new regime gate with the given thresholds.
    pub fn new(min_prompt_tokens: usize, naturalistic_variance: f32) -> Self {
        Self {
            prompt_tokens: 0,
            h_variance: WelfordVariance::default(),
            min_prompt_tokens,
            naturalistic_variance,
        }
    }

    /// Observe one token's H(x). Updates variance tracker and token count.
    #[inline]
    pub fn observe_h(&mut self, h_x: f32) {
        self.prompt_tokens += 1;
        self.h_variance.observe(h_x);
    }

    /// Observe a raw key embedding — computes H(x) and updates state.
    #[inline]
    pub fn observe_key(&mut self, key: &[f32]) {
        let h = spectral_entropy_dct(key);
        self.observe_h(h);
    }

    /// Whether CHIAR spectral preprocessing should be applied.
    ///
    /// Returns true iff prompt is large enough AND H(x) variance is high enough.
    /// Uses **sigmoid smoothing** so the decision isn't a sharp cliff:
    ///
    /// ```text
    /// p_length = σ(α · (prompt_tokens - min_prompt_tokens))
    /// p_variance = σ(β · (variance - naturalistic_variance))
    /// apply = (p_length > 0.5) AND (p_variance > 0.5)
    /// ```
    ///
    /// Sigmoid (not softmax) per project constraint.
    pub fn should_apply_chiar(&self) -> bool {
        if self.prompt_tokens == 0 {
            return false;
        }
        // Sigmoid smoothness constants — steepness of transition.
        let alpha = 0.01; // gentle — 100-token window for transition
        let beta = 1000.0; // sharp — variance is small in absolute terms

        let length_signal =
            sigmoid(alpha * (self.prompt_tokens as f32 - self.min_prompt_tokens as f32));
        let variance_signal =
            sigmoid(beta * (self.h_variance.variance() - self.naturalistic_variance));

        // AND gate: both signals must individually cross 0.5 (their respective thresholds).
        // This avoids the case where variance = 0 still passes because length signal ≈ 1.
        length_signal > 0.5 && variance_signal > 0.5
    }

    /// Sigmoid-smoothed probability of applying CHIAR. ∈ (0, 1).
    ///
    /// Useful for cost-aware routing where partial activation makes sense.
    pub fn apply_probability(&self) -> f32 {
        if self.prompt_tokens == 0 {
            return 0.0;
        }
        let alpha = 0.01;
        let beta = 1000.0;
        let length_signal =
            sigmoid(alpha * (self.prompt_tokens as f32 - self.min_prompt_tokens as f32));
        let variance_signal =
            sigmoid(beta * (self.h_variance.variance() - self.naturalistic_variance));
        length_signal * variance_signal
    }

    /// Number of tokens observed so far.
    #[inline]
    pub fn prompt_tokens(&self) -> usize {
        self.prompt_tokens
    }

    /// Current H(x) variance estimate.
    #[inline]
    pub fn h_variance(&self) -> f32 {
        self.h_variance.variance()
    }

    /// Current H(x) mean.
    #[inline]
    pub fn h_mean(&self) -> f32 {
        self.h_variance.mean()
    }

    /// Reset for a new prompt.
    pub fn reset(&mut self) {
        self.prompt_tokens = 0;
        self.h_variance.reset();
    }
}

use crate::chiaroscuro::entropy::spectral_entropy_dct;

/// Default τ_lo when too few samples have been observed.
pub const DEFAULT_TAU_LO: f32 = 0.855;

impl StreamingTauCalibrator {
    /// Create a new calibrator with default window size.
    pub fn new(min_samples: usize, window_size: usize) -> Self {
        let window_size = window_size.max(8);
        Self {
            ring: vec![0.0; window_size],
            sorted: Vec::with_capacity(window_size),
            head: 0,
            len: 0,
            window_size,
            min_samples,
            total_count: 0,
            dirty: true,
        }
    }

    /// Observe a single H(x) value. O(log W) due to sorted-view maintenance
    /// (lazy — only rebuilt on quantile read).
    pub fn observe(&mut self, h: f32) {
        self.total_count += 1;
        // Write to ring buffer at head position.
        self.ring[self.head] = h;
        self.head = (self.head + 1) % self.window_size;
        if self.len < self.window_size {
            self.len += 1;
        }
        self.dirty = true;
    }

    /// Convenience: observe H(x) computed from a raw embedding.
    ///
    /// Equivalent to `self.observe(spectral_entropy_dct(x))`.
    pub fn observe_embedding(&mut self, x: &[f32]) {
        let h = spectral_entropy_dct(x);
        self.observe(h);
    }

    /// Rebuild the sorted view from the ring buffer. O(W log W).
    fn rebuild_sorted(&mut self) {
        self.sorted.clear();
        self.sorted.extend_from_slice(&self.ring[..self.len]);
        // Unstable sort is faster for primitives and doesn't allocate.
        // total_cmp gives a consistent total ordering (handles NaN safely).
        self.sorted.sort_unstable_by(f32::total_cmp);
        self.dirty = false;
    }

    /// Quantile estimate from sorted window. `q ∈ [0, 1]`.
    fn quantile(&mut self, q: f32) -> f32 {
        if self.dirty {
            self.rebuild_sorted();
        }
        if self.sorted.is_empty() {
            return DEFAULT_TAU_LO;
        }
        let idx =
            ((q * (self.sorted.len() as f32 - 1.0)).round() as usize).min(self.sorted.len() - 1);
        self.sorted[idx]
    }

    /// Current τ_lo estimate (33rd percentile), or default if cold start.
    pub fn tau_lo(&self) -> f32 {
        if (self.total_count as usize) < self.min_samples
            || self.len < 8
            || self.dirty
            || self.sorted.is_empty()
        {
            DEFAULT_TAU_LO
        } else {
            // Mutate-free read: we know sorted is up-to-date if not dirty,
            // otherwise we'd need &mut. Use a small trick: re-check dirty.
            // For correctness, we expose tau_lo_mut below for hot loops.
            // The non-mut version assumes sorted is current (rebuild on observe
            // is deferred, but a previous tau_lo_mut/tau_hi_mut call would have
            // rebuilt). For safety, return default if dirty.
            let idx = ((0.33 * (self.sorted.len() as f32 - 1.0)).round() as usize)
                .min(self.sorted.len() - 1);
            self.sorted[idx]
        }
    }

    /// Current τ_hi estimate (67th percentile), or default if cold start.
    pub fn tau_hi(&self) -> f32 {
        if (self.total_count as usize) < self.min_samples
            || self.len < 8
            || self.dirty
            || self.sorted.is_empty()
        {
            DEFAULT_TAU_HI
        } else {
            let idx = ((0.67 * (self.sorted.len() as f32 - 1.0)).round() as usize)
                .min(self.sorted.len() - 1);
            self.sorted[idx]
        }
    }

    /// Refresh sorted view and return τ_lo. Use this in hot loops where you
    /// can take `&mut self` — guarantees fresh estimate after `observe`.
    pub fn tau_lo_mut(&mut self) -> f32 {
        if (self.total_count as usize) < self.min_samples || self.len < 8 {
            return DEFAULT_TAU_LO;
        }
        self.quantile(0.33)
    }

    /// Refresh sorted view and return τ_hi.
    pub fn tau_hi_mut(&mut self) -> f32 {
        if (self.total_count as usize) < self.min_samples || self.len < 8 {
            return DEFAULT_TAU_HI;
        }
        self.quantile(0.67)
    }

    /// Total number of observations seen (cumulative, not window size).
    #[inline]
    pub fn count(&self) -> u64 {
        self.total_count
    }

    /// Number of samples currently in the window.
    #[inline]
    pub fn window_len(&self) -> usize {
        self.len
    }

    /// Reset calibrator to cold-start state.
    pub fn reset(&mut self) {
        self.head = 0;
        self.len = 0;
        self.total_count = 0;
        self.dirty = true;
        self.sorted.clear();
    }
}

