impl VortexFlow for EntmaxRouter {
    type Cache = EntmaxCache;

    fn forward_cache(
        &self,
        cache: &mut Self::Cache,
        keys: &[f32],
        _values: &[f32],
        block_idx: usize,
        head_dim: usize,
    ) {
        // Extend summaries vec if needed
        if block_idx >= cache.summaries.len() {
            cache
                .summaries
                .resize_with(block_idx + 1, || vec![0.0; head_dim]);
        }

        let block_size = keys.len() / head_dim;
        if block_size == 0 {
            cache.summaries[block_idx].fill(0.0);
            return;
        }

        // Mean pooling of keys → summary (same as zero-init ChunkSummaryQuery).
        // Uses the crate SIMD add + scale kernels (matches ChannelAwareRouter's
        // mean-pool) instead of a scalar nested loop.
        let summary = &mut cache.summaries[block_idx];
        summary.resize(head_dim, 0.0);
        summary.fill(0.0);
        for t in 0..block_size {
            let k_start = t * head_dim;
            katgpt_core::simd::simd_add_inplace(summary, &keys[k_start..k_start + head_dim]);
        }
        let inv = 1.0 / block_size as f32;
        katgpt_core::simd::simd_scale_inplace(summary, inv);
    }

    fn forward_indexer(
        &self,
        query: &[f32],
        cache: &Self::Cache,
        n_blocks: usize,
        top_k: usize,
        scratch: &mut VortexScratch,
    ) -> RoutingDecision {
        if n_blocks == 0 {
            return RoutingDecision::new();
        }

        let n = n_blocks.min(cache.summaries.len());
        let summaries = &cache.summaries[..n];

        // Delegate to existing entmax routing, reusing the scratch's
        // RoutingScratch buffers (avoids 5 Vec allocations per call).
        let result =
            score_blocks_entmax_into(query, summaries, &self.config, &mut scratch.routing_scratch);

        // Convert RoutingResult → RoutingDecision
        // Take top_k from active indices (already sorted by entmax support)
        let k = top_k.min(result.active_indices.len());
        let mut decision = RoutingDecision::with_capacity(k);
        for &idx in &result.active_indices[..k] {
            decision.blocks.push(idx);
            decision.weights.push(result.probs[idx]);
        }

        decision
    }

    fn cache_new(&self, n_blocks_capacity: usize, head_dim: usize) -> Self::Cache {
        EntmaxCache::with_capacity(n_blocks_capacity, head_dim)
    }
}

use katgpt_core::simd::{simd_dot_f32, simd_exp_sum_inplace, simd_fused_scale_acc, simd_max_f32};

use super::vortex_flow::{RoutingDecision, VortexFlow, VortexRouter, VortexScratch};

// ---------------------------------------------------------------------------
// KvOuterIndex — reverse index: KV block → list of query indices
// ---------------------------------------------------------------------------

/// Reverse index: for each KV block, which queries selected it.
///
/// Built from the forward (Q-outer) routing decisions. Each query selects
/// top-k blocks; the reverse index inverts this to "for each block, which
/// queries need it". This enables KV-outer iteration: load each KV block
/// once and compute attention for all gathered queries.
#[derive(Debug, Clone)]
pub struct KvOuterIndex {
    /// `queries_for_block[b]` = list of query indices that selected block `b`.
    pub queries_for_block: Vec<Vec<usize>>,
}

impl KvOuterIndex {
    /// Create an empty index with `n_blocks` slots.
    pub fn new(n_blocks: usize) -> Self {
        Self {
            queries_for_block: vec![Vec::new(); n_blocks],
        }
    }

impl KvOuterPrefill {
    /// Create a new KV-outer prefill driver.
    pub fn new(router: VortexRouter, block_size: usize, head_dim: usize) -> Self {
        Self {
            router,
            block_size,
            head_dim,
        }
    }

    /// Run sparse prefill: route queries → build reverse index → compute attention.
    ///
    /// # Algorithm
    ///
    /// 1. **Phase 1 — Route**: Populate router cache, then run Q-outer routing
    ///    for each query to collect `RoutingDecision`s.
    /// 2. **Phase 2 — Reverse index**: Build `KvOuterIndex` from decisions.
    /// 3. **Phase 3 — Attend**: For each hot KV block, compute attention for
    ///    all gathered queries (dot-product scores + local softmax + weighted
    ///    value accumulation).
    /// 4. **Phase 4 — Combine**: Online LSE-based merge of partial outputs.
    ///
    /// # Arguments
    /// * `queries` — flat `[n_queries * head_dim]`
    /// * `keys` — flat `[n_blocks * block_size * head_dim]`
    /// * `values` — flat `[n_blocks * block_size * head_dim]`
    /// * `n_queries` — number of query tokens
    /// * `n_blocks` — number of KV blocks
    /// * `top_k` — blocks per query to select
    #[allow(clippy::needless_range_loop)] // stride math: t indexes scores[t] AND t*hd offset into block_vals
    pub fn prefill_sparse(
        &self,
        queries: &[f32],
        keys: &[f32],
        values: &[f32],
        n_queries: usize,
        n_blocks: usize,
        top_k: usize,
    ) -> SparsePrefillResult {
        let hd = self.head_dim;
        let bs = self.block_size;
        let scale = 1.0 / (hd as f32).sqrt();

        // Phase 1: Build router cache and route all queries.
        let mut cache = self.router.cache_new(n_blocks, hd);
        for b in 0..n_blocks {
            let k_start = b * bs * hd;
            let k_end = k_start + bs * hd;
            let v_start = b * bs * hd;
            let v_end = v_start + bs * hd;
            let block_keys = &keys[k_start..k_end];
            let block_vals = &values[v_start..v_end];
            self.router
                .forward_cache(&mut cache, block_keys, block_vals, b, hd);
        }

        // Phase 1b + Phase 2 fused: invert each routing decision into the
        // reverse index as soon as it is produced, instead of buffering all
        // `n_queries` decisions first. `build_from_decisions` performs exactly
        // this q-ascending / block-order push sequence, so `queries_for_block`
        // ends up identical — but the `Vec<RoutingDecision>` (plus the two
        // owned Vecs each decision holds, all live simultaneously) is gone.
        // Each decision is dropped right after use, so the allocator recycles
        // one small block instead of holding O(n_queries · top_k).
        let mut scratch = VortexScratch::new(n_blocks);
        let mut rev_idx = KvOuterIndex::new(n_blocks);
        for q in 0..n_queries {
            let q_start = q * hd;
            let query = &queries[q_start..q_start + hd];
            let dec = self
                .router
                .forward_indexer(query, &cache, n_blocks, top_k, &mut scratch);
            for &b in &dec.blocks {
                if b < n_blocks {
                    rev_idx.queries_for_block[b].push(q);
                }
            }
        }

        // Phase 3 + 4: Initialize output and LSE, then attend per-block.
        let mut output = vec![0.0f32; n_queries * hd];
        let mut lse = vec![f32::NEG_INFINITY; n_queries];

        let hot = rev_idx.hot_blocks();
        let n_blocks_used = hot.len();

        // Per-(block, query) scratch hoisted out of both loops. Previously both
        // 256-f32 arrays were re-declared inside the inner loop, costing two
        // 1 KB stack memsets per (block, query) pair. `scores` is fully
        // overwritten by `compute_scores` before any read, so it never needs
        // re-zeroing; `local_out` is an accumulator, so only its live
        // `actual_hd` prefix is cleared each iteration (the tail is never read).
        let mut scores = [0.0f32; 256];
        let mut local_out = [0.0f32; 256];

        for (block_idx, _query_count) in &hot {
            let b = *block_idx;
            let block_keys = &keys[b * bs * hd..(b + 1) * bs * hd];
            let block_vals = &values[b * bs * hd..(b + 1) * bs * hd];

            for &q in &rev_idx.queries_for_block[b] {
                let q_start = q * hd;
                let query = &queries[q_start..q_start + hd];

                // Compute attention scores: query · keys^T / sqrt(d)
                // Fixed 256-f32 stack buffer covers head_dim ≤ 256 and
                // block_size ≤ 256 (both hold for all current configs). The
                // debug_assert makes silent truncation visible in tests.
                debug_assert!(bs <= 256, "block_size {bs} exceeds 256-f32 score buffer");
                debug_assert!(hd <= 256, "head_dim {hd} exceeds 256-f32 local_out buffer");
                let actual_bs = bs.min(256);
                compute_scores(
                    query,
                    block_keys,
                    actual_bs,
                    hd,
                    scale,
                    &mut scores[..actual_bs],
                );

                // Local softmax: max, exp, sum — SIMD fused subtract+exp+sum
                let max_score = simd_max_f32(&scores[..actual_bs]);
                // Shift by max in-place, then fused exp + sum via SIMD.
                for s in scores[..actual_bs].iter_mut() {
                    *s -= max_score;
                }
                let sum_exp = simd_exp_sum_inplace(&mut scores[..actual_bs]);
                let inv_sum = 1.0 / sum_exp;

                // Local LSE: log(sum exp(scores))
                let lse_local = max_score + sum_exp.ln();

                // Weighted value accumulation: local_out = sum(w_j * v_j)
                let actual_hd = hd.min(256);
                local_out[..actual_hd].fill(0.0);
                for t in 0..actual_bs {
                    let w = scores[t] * inv_sum;
                    let v_start = t * hd;
                    simd_fused_scale_acc(
                        &mut local_out[..actual_hd],
                        &block_vals[v_start..v_start + actual_hd],
                        w,
                        actual_hd,
                    );
                }

                // Online LSE combine (logaddexp trick):
                // lse_new = logaddexp(lse[q], lse_local)
                // output[q] = output[q] * exp(lse[q] - lse_new) + local_out * exp(lse_local - lse_new)
                match lse[q] {
                    l if l == f32::NEG_INFINITY => {
                        // First block for this query — set directly.
                        lse[q] = lse_local;
                        output[q_start..q_start + actual_hd]
                            .copy_from_slice(&local_out[..actual_hd]);
                    }
                    lse_prev => {
                        let lse_new = logaddexp(lse_prev, lse_local);
                        use katgpt_core::simd::fast_exp;
                        let old_scale = fast_exp(lse_prev - lse_new);
                        let new_scale = fast_exp(lse_local - lse_new);

                        let out_slice = &mut output[q_start..q_start + actual_hd];
                        for (o, &l) in out_slice.iter_mut().zip(local_out[..actual_hd].iter()) {
                            *o = *o * old_scale + l * new_scale;
                        }
                        lse[q] = lse_new;
                    }
                }
            }
        }

        SparsePrefillResult {
            output,
            lse,
            n_blocks_used,
        }
    }
}

use super::block_topk::{BlockTopKCache, BlockTopKRouter};
use super::channel_aware::ChannelAwareCache;
use super::entmax_router::{EntmaxCache, EntmaxRouter};
use super::value_energy::{ValueEnergyCache, ValueEnergyRouter};
use super::vortex_flow::{RoutingDecision, VortexFlow, VortexScratch};

// ---------------------------------------------------------------------------
// DynRoutingCache — T17
// ---------------------------------------------------------------------------

/// Dynamic routing cache: one variant per router cache type.
///
/// This enables `MetaRouter` to own multiple policies with different cache types
/// behind a single enum. The `Meta` variant holds all policy caches for the
/// meta-router's internal use.
#[derive(Debug)]
pub enum DynRoutingCache {
    /// BlockTopK cache.
    BlockTopK(BlockTopKCache),
    /// Entmax cache.
    Entmax(EntmaxCache),
    /// ValueEnergy cache.
    ValueEnergy(ValueEnergyCache),
    /// Channel-aware cache.
    ChannelAware(ChannelAwareCache),
    /// Meta-router composite: all policy caches.
    Meta(Vec<DynRoutingCache>),
}

impl DynRoutingCache {
    /// Number of blocks currently cached (variant-dependent).
    pub fn n_blocks(&self) -> usize {
        match self {
            Self::BlockTopK(c) => c.n_blocks,
            Self::Entmax(c) => c.n_blocks(),
            Self::ValueEnergy(c) => c.n_blocks,
            Self::ChannelAware(c) => c.n_blocks,
            Self::Meta(caches) => caches.first().map_or(0, |c| c.n_blocks()),
        }
    }

impl DynPolicy {
    /// Dispatch `forward_cache` to the concrete router.
    pub fn forward_cache(
        &self,
        cache: &mut DynRoutingCache,
        keys: &[f32],
        values: &[f32],
        block_idx: usize,
        head_dim: usize,
    ) {
        match (self, cache) {
            (Self::BlockTopK(r), DynRoutingCache::BlockTopK(c)) => {
                r.forward_cache(c, keys, values, block_idx, head_dim);
            }
            (Self::Entmax(r), DynRoutingCache::Entmax(c)) => {
                r.forward_cache(c, keys, values, block_idx, head_dim);
            }
            (Self::ValueEnergy(r), DynRoutingCache::ValueEnergy(c)) => {
                r.forward_cache(c, keys, values, block_idx, head_dim);
            }
            _ => panic!("DynPolicy/Cache variant mismatch in forward_cache"),
        }
    }

    /// Dispatch `forward_indexer` to the concrete router.
    pub fn forward_indexer(
        &self,
        query: &[f32],
        cache: &DynRoutingCache,
        n_blocks: usize,
        top_k: usize,
        scratch: &mut VortexScratch,
    ) -> RoutingDecision {
        match (self, cache) {
            (Self::BlockTopK(r), DynRoutingCache::BlockTopK(c)) => {
                r.forward_indexer(query, c, n_blocks, top_k, scratch)
            }
            (Self::Entmax(r), DynRoutingCache::Entmax(c)) => {
                r.forward_indexer(query, c, n_blocks, top_k, scratch)
            }
            (Self::ValueEnergy(r), DynRoutingCache::ValueEnergy(c)) => {
                r.forward_indexer(query, c, n_blocks, top_k, scratch)
            }
            _ => panic!("DynPolicy/Cache variant mismatch in forward_indexer"),
        }
    }

    /// Create a new cache for this policy.
    pub fn cache_new(&self, n_blocks_capacity: usize, head_dim: usize) -> DynRoutingCache {
        match self {
            Self::BlockTopK(r) => {
                DynRoutingCache::BlockTopK(r.cache_new(n_blocks_capacity, head_dim))
            }
            Self::Entmax(r) => DynRoutingCache::Entmax(r.cache_new(n_blocks_capacity, head_dim)),
            Self::ValueEnergy(r) => {
                DynRoutingCache::ValueEnergy(r.cache_new(n_blocks_capacity, head_dim))
            }
        }
    }

    /// Human-readable policy name.
    pub fn name(&self) -> &'static str {
        match self {
            Self::BlockTopK(_) => "BlockTopK",
            Self::Entmax(_) => "Entmax",
            Self::ValueEnergy(_) => "ValueEnergy",
        }
    }
}

impl MetaRouter {
    /// Create a new MetaRouter with the given policies and bandit strategy.
    ///
    /// The bandit will have `policies.len()` arms, one per policy.
    pub fn new(policies: Vec<DynPolicy>, strategy: BanditStrategy) -> Self {
        let n_arms = policies.len();
        let bandit = BanditPruner::new(NoScreening, strategy, n_arms);
        Self { policies, bandit }
    }

    /// Create with default EpsilonGreedy strategy (ε=0.1, decay=0.995).
    pub fn new_default(policies: Vec<DynPolicy>) -> Self {
        Self::new(
            policies,
            BanditStrategy::EpsilonGreedy {
                epsilon: 0.1,
                decay: 0.995,
            },
        )
    }

    /// Update bandit reward after observing a decode step outcome.
    ///
    /// Call this after each decode step with the selected policy's performance.
    ///
    /// # Arguments
    /// * `arm` — index of the policy that was selected
    /// * `reward` — reward signal: `acceptance_rate * latency_improvement`
    pub fn update_reward(&mut self, arm: usize, reward: f32) {
        self.bandit.update(arm, reward);
    }

    /// Select which policy arm to use for this decode step.
    ///
    /// Uses the bandit strategy (UCB1, ε-greedy, Thompson, etc.) to balance
    /// exploration and exploitation.
    pub fn select_arm(&self) -> usize {
        self.bandit.best_arm()
    }

    /// Index of the best policy (highest Q-value).
    pub fn best_arm(&self) -> usize {
        self.bandit.best_arm()
    }

    /// Q-values for all policy arms.
    pub fn q_values(&self) -> &[f32] {
        self.bandit.q_values()
    }

    /// Visit counts for all policy arms.
    pub fn visits(&self) -> &[u32] {
        self.bandit.visits()
    }

    /// Total number of arm pulls.
    pub fn total_pulls(&self) -> u32 {
        self.bandit.total_pulls()
    }

    /// Get the bandit stats for inspection.
    pub fn bandit_stats(&self) -> &BanditStats {
        // Access internal stats through the pruner's public interface
        // We expose q_values/visits/best_arm directly
        // For full stats access, we'd need BanditPruner to expose &BanditStats
        // For now, use the individual accessors
        unreachable!("use individual accessors instead")
    }

    /// Decay epsilon after an episode (EpsilonGreedy only).
    pub fn decay_epsilon(&mut self) {
        self.bandit.decay_epsilon();
    }

    /// Number of policies.
    pub fn n_policies(&self) -> usize {
        self.policies.len()
    }

    /// Get policy name by index.
    pub fn policy_name(&self, idx: usize) -> &'static str {
        match self.policies.get(idx) {
            Some(p) => p.name(),
            None => "unknown",
        }
    }
}

impl VortexFlow for MetaRouter {
    type Cache = DynRoutingCache;

    fn forward_cache(
        &self,
        cache: &mut Self::Cache,
        keys: &[f32],
        values: &[f32],
        block_idx: usize,
        head_dim: usize,
    ) {
        // Delegate to ALL policies (maintain all caches)
        let caches = match cache {
            DynRoutingCache::Meta(caches) => caches,
            _ => panic!("MetaRouter expects DynRoutingCache::Meta variant"),
        };

        for (i, policy) in self.policies.iter().enumerate() {
            if let Some(c) = caches.get_mut(i) {
                policy.forward_cache(c, keys, values, block_idx, head_dim);
            }
        }
    }

    fn forward_indexer(
        &self,
        query: &[f32],
        cache: &Self::Cache,
        n_blocks: usize,
        top_k: usize,
        scratch: &mut VortexScratch,
    ) -> RoutingDecision {
        let caches = match cache {
            DynRoutingCache::Meta(caches) => caches,
            _ => panic!("MetaRouter expects DynRoutingCache::Meta variant"),
        };

        // Bandit selects policy arm
        let arm = self.select_arm();

        match (self.policies.get(arm), caches.get(arm)) {
            (Some(policy), Some(c)) => policy.forward_indexer(query, c, n_blocks, top_k, scratch),
            _ => RoutingDecision::new(),
        }
    }

    fn cache_new(&self, n_blocks_capacity: usize, head_dim: usize) -> Self::Cache {
        let caches: Vec<DynRoutingCache> = self
            .policies
            .iter()
            .map(|p| p.cache_new(n_blocks_capacity, head_dim))
            .collect();
        DynRoutingCache::Meta(caches)
    }
}

use super::block_topk::{argtopk_with_scratch, sigmoid};
use super::vortex_flow::{RoutingDecision, VortexFlow, VortexScratch};
use katgpt_core::simd::{simd_dot_f32, simd_sum_sq};

// ---------------------------------------------------------------------------
// MSA cache — max-pool scores + key statistics per block
// ---------------------------------------------------------------------------

/// Cache for MSA-distilled routers: per-block max-pool score + key statistics.
///
/// Unlike `BlockTopKCache` which stores mean centroids, this stores the raw
/// key matrix for each block so we can compute max(q·k_j) at query time.
/// For efficiency, we also precompute per-block key norm statistics (mean, std_dev).
#[derive(Debug, Clone)]
pub struct MsaBlockCache {
    /// Flattened key matrices: `[n_blocks * block_size * head_dim]`.
    /// Stored densely so we can iterate over keys per block at query time.
    pub keys: Vec<f32>,
    /// Per-block key norm mean: `[n_blocks]`.
    pub key_norm_mean: Vec<f32>,
    /// Per-block key norm std_dev: `[n_blocks]`.
    pub key_norm_stddev: Vec<f32>,
    /// Block size (tokens per block). Fixed at construction.
    pub block_size: usize,
    /// Number of blocks currently cached.
    pub n_blocks: usize,
    /// Head dimension.
    pub head_dim: usize,
}

impl MsaBlockCache {
    /// Create a pre-allocated cache.
    ///
    /// `block_size` must match the KV block granularity used during decode.
    pub fn new(n_blocks_capacity: usize, block_size: usize, head_dim: usize) -> Self {
        Self {
            keys: vec![0.0; n_blocks_capacity * block_size * head_dim],
            key_norm_mean: vec![0.0; n_blocks_capacity],
            key_norm_stddev: vec![0.0; n_blocks_capacity],
            block_size,
            n_blocks: 0,
            head_dim,
        }
    }

impl MaxPoolBlockScorer {
    /// Create with the given block size.
    pub fn new(block_size: usize) -> Self {
        Self { block_size }
    }
}

impl VortexFlow for MaxPoolBlockScorer {
    type Cache = MsaBlockCache;

    fn forward_cache(
        &self,
        cache: &mut Self::Cache,
        keys: &[f32],
        _values: &[f32],
        block_idx: usize,
        head_dim: usize,
    ) {
        let block_size = keys.len() / head_dim;
        debug_assert_eq!(
            block_size, self.block_size,
            "block_size mismatch: expected {}, got {}",
            self.block_size, block_size
        );

        cache.ensure_capacity(block_idx + 1);

        // Store raw keys for max-pool scoring at query time
        let start = block_idx * self.block_size * head_dim;
        let end = start + block_size * head_dim;
        cache.keys[start..end].copy_from_slice(keys);

        // Precompute key norm statistics for potential StdDev scoring
        let mut norm_sum = 0.0f32;
        let mut norm_sq_sum = 0.0f32;
        for t in 0..block_size {
            let k_start = t * head_dim;
            let norm_sq = simd_sum_sq(&keys[k_start..k_start + head_dim], head_dim);
            let norm = norm_sq.sqrt();
            norm_sum += norm;
            norm_sq_sum += norm_sq; // norm*norm == norm_sq (avoid sqrt→square round trip)
        }

        let inv = 1.0 / block_size.max(1) as f32;
        cache.key_norm_mean[block_idx] = norm_sum * inv;
        // std_dev = sqrt(E[X^2] - E[X]^2)
        let variance = norm_sq_sum * inv - (norm_sum * inv).powi(2);
        cache.key_norm_stddev[block_idx] = variance.max(0.0).sqrt();

        cache.n_blocks = cache.n_blocks.max(block_idx + 1);
    }

    fn forward_indexer(
        &self,
        query: &[f32],
        cache: &Self::Cache,
        n_blocks: usize,
        top_k: usize,
        scratch: &mut VortexScratch,
    ) -> RoutingDecision {
        if n_blocks == 0 {
            return RoutingDecision::new();
        }

        let hd = query.len();
        scratch.ensure_capacity(n_blocks);
        let scores = &mut scratch.scores[..n_blocks];

        // Exp-free max-pool scoring — MSA §4.1
        // softmax is order-preserving, so argmax(raw) == argmax(softmax(raw))
        for (i, score) in scores.iter_mut().enumerate().take(n_blocks) {
            let block_keys = cache.block_keys(i);
            *score = max_qk_score(query, block_keys, self.block_size, hd);
        }

        // Top-k selection (exp-free: no softmax needed)
        let k = top_k.min(n_blocks);
        scratch.indices.clear();
        argtopk_with_scratch(scores, k, &mut scratch.indices, &mut scratch.argtopk_pairs);

        let mut decision = RoutingDecision::with_capacity(k);
        for &idx in &scratch.indices[..k] {
            decision.blocks.push(idx);
            decision.weights.push(sigmoid(scores[idx]));
        }

        decision
    }

    fn cache_new(&self, n_blocks_capacity: usize, head_dim: usize) -> Self::Cache {
        MsaBlockCache::new(n_blocks_capacity, self.block_size, head_dim)
    }
}

impl MaxStdDevBlockScorer {
    /// Create with block size and default lambda=1.0.
    pub fn new(block_size: usize) -> Self {
        Self {
            block_size,
