            Self::Entmax(c) => c.summaries.len(),
            Self::ValueEnergy(c) => c.n_blocks,
            Self::ChannelAware(c) => c.n_blocks,
            Self::Meta(c) => c.n_blocks(),
            #[cfg(feature = "msa_sparse")]
