        self.blocks.is_empty()
    }
}

impl VortexScratch {
    /// Create scratch buffers sized for `max_blocks` blocks.
    pub fn new(max_blocks: usize) -> Self {
        Self {
            scores: vec![0.0; max_blocks],
            indices: Vec::with_capacity(max_blocks),
            argtopk_pairs: Vec::with_capacity(max_blocks),
            routing_query_buf: Vec::new(),
            routing_scratch: RoutingScratch::new(0, 0),
        }
    }

    /// Ensure buffers can hold at least `n` blocks, growing if needed.
    pub fn ensure_capacity(&mut self, n: usize) {
        if self.scores.len() < n {
            self.scores.resize(n, 0.0);
        }
        if self.indices.capacity() < n {
            // Reserve enough for n total elements
            let additional = n.saturating_sub(self.indices.len());
            self.indices.reserve(additional);
        }
        if self.argtopk_pairs.capacity() < n {
            self.argtopk_pairs
                .reserve(n.saturating_sub(self.argtopk_pairs.capacity()));
        }
    }
}

impl Gdn2DiagonalGate {
    /// Create a new GDN2 diagonal gate with default decay (0.99).
    pub fn new(dim: usize) -> Self {
        Self {
            alpha: vec![GDN2_DEFAULT_DECAY; dim],
        }
    }

    /// Create from existing decay values.
    pub fn from_alpha(alpha: Vec<f32>) -> Self {
        Self { alpha }
    }
}

impl DiagonalGate for Gdn2DiagonalGate {
    #[inline]
    fn dim(&self) -> usize {
        self.alpha.len()
    }

    /// GDN2 uses fixed decay_alpha (not projected from input).
    /// Fills `out` with the current alpha values.
    #[inline]
    fn compute_gate(&self, _input: &[f32], _weights: &[f32], _bias: f32, out: &mut [f32]) {
        let d = self.dim();
        out[..d].copy_from_slice(&self.alpha);
    }

    /// Apply decay: `target[i] *= alpha[i]`.
    #[inline]
    fn apply(&self, gate_values: &[f32], target: &mut [f32]) {
        let d = self.dim();
        debug_assert_eq!(gate_values.len(), d);
        debug_assert!(target.len() >= d);
        simd_scale_mul_inplace(&mut target[..d], gate_values, 1.0);
    }

    /// Apply inverse: `target[i] /= alpha[i]` (for backward pass).
    /// Uses reciprocal-multiply (1 div + N muls) instead of N divisions.
    #[inline]
    fn apply_inverse(&self, gate_values: &[f32], target: &mut [f32]) {
        let d = self.dim();
        debug_assert_eq!(gate_values.len(), d);
        debug_assert!(target.len() >= d);
        for i in 0..d {
            target[i] *= 1.0 / gate_values[i];
        }
    }

    /// Reset to default decay (0.99).
    #[inline]
    fn reset(&mut self) {
        self.alpha.fill(GDN2_DEFAULT_DECAY);
    }
}

impl WallDiagonalGate {
    /// Create a new Wall diagonal gate with zeroed prefix sums.
    pub fn new(dim: usize) -> Self {
        Self {
            prefix: vec![0.0; dim],
            gate_max: WALL_DEFAULT_GATE_MAX,
        }
    }

    /// Create with custom gate_max.
    pub fn with_gate_max(dim: usize, gate_max: f32) -> Self {
        Self {
            prefix: vec![0.0; dim],
            gate_max,
        }
    }

    /// Compute gate from key projection: log-sigmoid clamped to (-gate_max, 0].
    ///
    /// Matches `WallPrefixState::compute_gate_from_key` logic:
    /// 1. gate = key ⊙ weights + bias
    /// 2. gate = -gate (negate logits)
    /// 3. gate = exp(gate)
    /// 4. gate = ln(1 + gate) → softplus
    /// 5. gate = -gate → log_sigmoid
    /// 6. clamp(-gate_max, 0.0)
    #[inline]
    pub fn compute_gate_from_projection(
        &self,
        input: &[f32],
        weights: &[f32],
        bias: f32,
        out: &mut [f32],
    ) {
        let hd = input.len();
        debug_assert_eq!(weights.len(), hd);
        debug_assert!(out.len() >= hd);

        // Step 1: out = input ⊙ weights
        out[..hd].copy_from_slice(&input[..hd]);
        simd_scale_mul_inplace(&mut out[..hd], weights, 1.0);

        // Step 2: out += bias
        simd_add_scalar_inplace(&mut out[..hd], bias);

        // Step 3: out = -out (negate logits)
        simd_scale_inplace(&mut out[..hd], -1.0);

        // Step 4: out = exp(-logits)
        simd_exp_inplace(&mut out[..hd]);

        // Step 5: out = ln(1 + exp(-logit)) → softplus(-logit), then negate
        // log_sigmoid(logit) = -ln(1 + exp(-logit)) = -softplus(-logit)
        simd_add_scalar_inplace(&mut out[..hd], 1.0);
        for v in out[..hd].iter_mut() {
            let log_sig = -(*v).ln();
            *v = log_sig.clamp(-self.gate_max, 0.0);
        }
    }
}

use crate::gdn2::kernel::{gdn2_state_readout, gdn2_state_update, l2_normalize};
use crate::gdn2::types::MultiLayerGdn2Cache;
use katgpt_core::types::{self, Config};
use katgpt_forward::ForwardContext;
use katgpt_transformer::TransformerWeights;

// ── GDN2 Forward Pass ──────────────────────────────────────────

/// Forward pass using GDN2 recurrent attention.
///
/// Replaces the growing KV cache with constant-size O(d_k × d_v) recurrent state.
/// The attention output is computed via a single recurrent step per head:
///
/// ```text
/// S ← Diag(α) · S + k ⊗ (w⊙v − Sᵀ(b⊙k))   [update]
/// o = Sᵀ q                                    [readout]
/// ```
///
/// # vs `forward_base()`
///
/// | Step | `forward_base` | `forward_gdn2` |
/// |------|----------------|----------------|
/// | QKV projection | Same | Same + L2 normalize q, k |
/// | Cache store | `layer_cache.key[pos] = k` | **Skip** (state update instead) |
/// | Attention | Loop over past positions O(N·d) | **Recurrent step** O(d²) constant |
/// | Gates | None | Erase b, write w, decay α |
/// | MLP | Same | Same |
/// | Memory per layer | O(block_size × kv_dim) growing | O(d_k × d_v) constant |
///
/// # Arguments
/// * `ctx` — Pre-allocated forward context with Q/K/V buffers
/// * `weights` — Transformer weights (same as `forward_base`)
/// * `cache` — GDN2 cache (constant-size, no `block_size` dependency)
/// * `token` — Input token index
/// * `pos` — Position in sequence (used for position embedding only, not cache sizing)
/// * `config` — Model configuration
pub fn forward_gdn2<'a>(
    ctx: &'a mut ForwardContext,
    weights: &TransformerWeights,
    cache: &mut MultiLayerGdn2Cache,
    token: usize,
    pos: usize,
    config: &Config,
) -> &'a mut [f32] {
    let n = config.n_embd;

impl Gdn2HeadState {
    /// Allocate zeroed state for one head.
    pub fn new(dk: usize, dv: usize) -> Self {
        Self {
            s: vec![0.0; dk * dv],
        }
    }

    /// Reset to zeroed state (reuse allocations).
    pub fn reset(&mut self) {
        self.s.fill(0.0);
    }
}

impl Gdn2LayerState {
    /// Allocate zeroed state for one layer given config.
    pub fn new(config: &Config, gate_config: Gdn2GateConfig) -> Self {
        let dk = config.head_dim;
        let dv = config.head_dim;
        let mut heads = Vec::with_capacity(config.n_kv_head);
        for _ in 0..config.n_kv_head {
            heads.push(Gdn2HeadState::new(dk, dv));
        }
        Self {
            heads,
            gate_config,
            out_buf: vec![0.0; dv],
            temp_buf: vec![0.0; dv],
            erase_b: vec![0.5; dv],
            decay_alpha: vec![0.99; dk],
            write_w_channel: vec![1.0; dv],
            delta: vec![0.0; dv],
            #[cfg(feature = "hippocampal_cache")]
            hippocampal_caches: Vec::new(), // empty = disabled
            #[cfg(feature = "hippocampal_cache")]
            cache_scratch: vec![0.0; dv],
            #[cfg(feature = "hippocampal_cache")]
            cache_alpha: 1.0,
        }
    }

    /// Reset to zeroed state (reuse allocations).
    ///
    /// Only resets the head state matrices; scratch buffers are zeroed
    /// on each use so they don't need resetting here.
    /// HOLA caches are also reset (heap_len → 0) when present.
    pub fn reset(&mut self) {
        for h in &mut self.heads {
            h.reset();
        }
        #[cfg(feature = "hippocampal_cache")]
        for cache in &mut self.hippocampal_caches {
            cache.reset();
        }
    }

    /// KV group index for a given Q head.
    #[inline]
    pub fn kv_group(head_idx: usize, config: &Config) -> usize {
        head_idx * config.n_kv_head / config.n_head
    }
}

impl MultiLayerGdn2Cache {
    /// Allocate zeroed cache for all layers with default gate config.
    pub fn new(config: &Config) -> Self {
        Self {
            layers: (0..config.n_layer)
                .map(|_| Gdn2LayerState::new(config, Gdn2GateConfig::default()))
                .collect(),
            eps: 1e-6,
        }
    }

    /// Allocate with custom gate config for all layers.
    pub fn with_gate_config(config: &Config, gate_config: Gdn2GateConfig) -> Self {
        Self {
            layers: (0..config.n_layer)
                .map(|_| Gdn2LayerState::new(config, gate_config))
                .collect(),
            eps: 1e-6,
        }
    }

    /// Allocate with HOLA hippocampal cache enabled for all layers.
    ///
    /// Each KV head in each layer gets a `HippocampalCacheDyn` with capacity
    /// `w` and head dimension `config.head_dim`. The cache observes
    /// (k, v, β·‖delta‖) after each state update and the read is added to the
    /// GDN2 readout via `forward_gdn2`.
    ///
    /// Only available when the `hippocampal_cache` feature is enabled.
    #[cfg(feature = "hippocampal_cache")]
    pub fn with_hippocampal_cache(config: &Config, w: usize) -> Self {
        let mut cache = Self::new(config);
        for layer in &mut cache.layers {
            layer.hippocampal_caches = (0..config.n_kv_head)
                .map(|_| HippocampalCacheDyn::new_with_ones_gamma(config.head_dim, w))
                .collect();
        }
        cache
    }

    /// Reset all layers to zeroed state (reuse allocations).
    pub fn reset(&mut self) {
        for layer in &mut self.layers {
            layer.reset();
        }
    }

    /// Total cache size in bytes.
    pub fn memory_bytes(&self) -> usize {
        let mut total = 0;
        for layer in &self.layers {
            for head in &layer.heads {
                total += head.s.len() * 4;
            }
        }
        total
    }
}

impl StaticCalTable {
    /// Create a new empty calibration table.
    /// All scales initialize to 1.0 (neutral — no correction).
    pub fn new(num_layers: usize, num_heads: usize) -> Self {
        let total = num_layers * num_heads;
        let mut table = Self {
            scales: vec![1.0; total],
            num_layers,
            num_heads,
            calibration_prompts: 0,
            commitment: [0u8; 32],
        };
        table.commit();
        table
    }

    /// O(1) lookup for a specific head's scale.
    #[inline]
    pub fn get_scale(&self, layer: usize, head: usize) -> f32 {
        debug_assert!(layer < self.num_layers);
        debug_assert!(head < self.num_heads);
        // SAFETY: index is bounds-checked by debug_assert above; in release this is pure indexing.
        unsafe { *self.scales.get_unchecked(layer * self.num_heads + head) }
    }

    /// Set scale for a specific head.
    pub fn set_scale(&mut self, layer: usize, head: usize, scale: f32) {
        debug_assert!(layer < self.num_layers);
        debug_assert!(head < self.num_heads);
        self.scales[layer * self.num_heads + head] = scale;
    }

    /// Total number of entries in the table.
    pub fn len(&self) -> usize {
        self.scales.len()
    }

    /// Whether the table is empty.
    pub fn is_empty(&self) -> bool {
        self.scales.is_empty()
    }

    /// Calibrate from activation statistics.
    ///
    /// Takes per-head activation statistics and computes scale factors.
    /// Uses sigmoid (not softmax) to normalize each head's scale to [0.5, 1.5] range.
    /// Updates via EMA (α=0.1) for stability across calibration passes.
    pub fn calibrate_from_stats(&mut self, stats: &[HeadStats]) {
        self.calibration_prompts += 1;
        for stat in stats {
            let idx = stat.layer * self.num_heads + stat.head;
            if idx < self.scales.len() {
                // Sigmoid-normalized scale: 1.0 + 0.5 * sigmoid(mean_activation - offset)
                // Heads with high activation get slightly boosted, low activation slightly dampened
                let normalized = sigmoid(stat.mean_activation * 0.1);
                let scale = 0.5 + normalized; // [0.5, 1.5]
                // EMA update: smooth convergence, never jumps
                let prev = self.scales[idx];
                self.scales[idx] = 0.9 * prev + 0.1 * scale;
            }
        }
        self.commit();
    }

    /// Compute BLAKE3 commitment hash over all scales.
    ///
    /// Hashes the raw `f32` bytes of `scales` as a single contiguous slice rather
    /// than per-element `update()` calls — lets BLAKE3's internal buffer absorb
    /// a large chunk in one go (fewer merge rounds).
    pub fn commit(&mut self) {
        self.commitment = hash_scales(&self.scales);
    }

    /// Verify BLAKE3 commitment matches current scales.
    pub fn verify(&self) -> bool {
        hash_scales(&self.scales) == self.commitment
    }
}

