use katgpt_core::simd::simd_sum_f32;

/// MGPO sampling weight: `exp(-γ * |2p - 1|)`.
///
/// Peaks at `p = 0.5` (maximum-entropy / calibration boundary), decays toward
/// `p = 0` (too hard) and `p = 1` (saturated). The caller maintains an EMA `p`
/// per sampling seed.
///
/// # Arguments
///
/// * `p` — per-seed success rate (EMA), typically in `[0, 1]`.
/// * `gamma` — decay exponent `γ` (from [`crate::clr::ClrConfig::gamma_mgpo`]).
///
/// # Returns
///
/// Weight in `(0, 1]`. `p = 0.5` always returns `1.0` regardless of `γ`.
#[inline]
pub fn mgpo_sampling_weight(p: f32, gamma: f32) -> f32 {
    katgpt_core::simd::fast_exp(-gamma * (2.0 * p - 1.0).abs())
}

impl ClrScratch {
    /// Allocate scratch sized for `K * M` verdicts + `M * embedding_dim` claim embeddings.
    ///
    /// Uses `with_capacity` so the first [`Self::reset_for`] is the only
    /// allocation; later `reset_for` calls with `k <= K, m <= M, embedding_dim`
    /// within bounds do not reallocate.
    #[inline]
    pub fn new(k: usize, m: usize, embedding_dim: usize) -> Self {
        assert!(k > 0, "ClrScratch::new: k must be > 0");
        assert!(m > 0, "ClrScratch::new: m must be > 0");
        assert!(embedding_dim > 0, "ClrScratch::new: embedding_dim must be > 0");
        assert!(
            k <= 256,
            "ClrScratch::new: k={k} exceeds Vec<u8> cluster_id limit (256)"
        );
        Self {
            verdicts: Vec::with_capacity(k * m),
            reliability: Vec::with_capacity(k),
            cluster_id: Vec::with_capacity(k),
            claim_embeddings: Vec::with_capacity(m * embedding_dim),
        }
    }

    /// Zero and size the buffers for one CLR cycle of shape `(k, m, embedding_dim)`.
    ///
    /// After this call:
    ///   - `verdicts.len() == k * m`, all `0.0`
    ///   - `reliability.len() == k`, all `0.0`
    ///   - `cluster_id.len() == k`, all `0`
    ///   - `claim_embeddings.len() == m * embedding_dim`, all `0.0`
    ///
    /// No allocation occurs if `k * m <= verdicts.capacity()` etc., which holds
    /// when `k, m, embedding_dim` are within the values passed to [`Self::new`].
    #[inline]
    pub fn reset_for(&mut self, k: usize, m: usize, embedding_dim: usize) {
        self.verdicts.clear();
        self.verdicts.resize(k * m, 0.0);
        self.reliability.clear();
        self.reliability.resize(k, 0.0);
        self.cluster_id.clear();
        self.cluster_id.resize(k, 0);
        self.claim_embeddings.clear();
        self.claim_embeddings.resize(m * embedding_dim, 0.0);
    }
}

use crate::clr::traits::{ClaimVerifier, DirectionVectorSource};
use crate::clr::types::Verdict;

/// Sigmoid-projection verifier: `sigmoid(dot(emb, dir[idx]))`.
///
/// Borrows a [`DirectionVectorSource`] for the lifetime of the verifier.
/// Generic over the claim payload `T` because the verdict computation only
/// touches `claim.embedding`.
pub struct SigmoidProjectionVerifier<'a> {
    /// Borrowed direction-vector pool.
    pub directions: &'a dyn DirectionVectorSource,
    /// Expected dimension `k` of each direction vector (and each claim embedding).
    pub direction_dim: usize,
}

impl<'a> SigmoidProjectionVerifier<'a> {
    /// Construct a new verifier backed by `directions` with claim/dir dim `k`.
    #[inline]
    pub fn new(directions: &'a dyn DirectionVectorSource, direction_dim: usize) -> Self {
        assert!(
            direction_dim > 0,
            "SigmoidProjectionVerifier: direction_dim must be > 0"
        );
        Self {
            directions,
            direction_dim,
        }
    }

impl<T> ClaimVerifier<T> for SigmoidProjectionVerifier<'_> {
    /// Compute the sigmoid verdict for `embedding` projected onto direction `idx`.
    ///
    /// This is the core computation. [`Self::verify`] delegates here via
    /// `claim.embedding`.
    #[inline(always)]
    fn verify_embedding(&self, embedding: &[f32], direction_idx: usize) -> Verdict {
        let d = self.directions.direction(direction_idx);
        debug_assert_eq!(
            d.len(),
            self.direction_dim,
            "SigmoidProjectionVerifier: direction dim mismatch (got {}, expected {})",
            d.len(),
            self.direction_dim
        );
        debug_assert_eq!(
            embedding.len(),
            self.direction_dim,
            "SigmoidProjectionVerifier: embedding dim mismatch (got {}, expected {})",
            embedding.len(),
            self.direction_dim
        );
        // SIMD dot on the full k-dim vectors.
        let dot = katgpt_core::simd::simd_dot_f32(embedding, d, self.direction_dim);
        // Scalar sigmoid — single value, not a vector path; f32::exp is fine.
        sigmoid(dot)
    }

