counting_allocator!();

// ─── Test signal & analytical derivatives ───────────────────────────────────

const TAU: f32 = std::f32::consts::TAU;

/// Sample `sin(2π·j/N)` for j = 0..N — one full period, exactly periodic.
fn sine_period(n: usize) -> Vec<f32> {
    (0..n)
        .map(|j| ((TAU * j as f32) / n as f32).sin())
        .collect()
}

/// Analytical first derivative of `sine_period`: `(2π/N)·cos(2π·j/N)`.
fn sine_first_deriv(n: usize) -> Vec<f32> {
    let omega = TAU / n as f32;

fn gate_g2_perf() -> GateResult {
    const SIZES: &[usize] = &[64, 256, 1024];
    const TARGET_US: f64 = 50.0;
    const WARMUP: usize = 20;
    const ITERS: usize = 1000;

    let mut all_pass = true;
    let mut details: Vec<String> = Vec::with_capacity(SIZES.len());

    for &n in SIZES {
        let x = sine_period(n);
        let mut out = vec![0.0f32; n];
        let mut scratch = SpecDiffScratch::new();
        scratch.ensure_capacity(n);
        let cfg = SpecDiffConfig::DEFAULT;

        // Warmup — populate the FFT planner cache for this size.
        for _ in 0..WARMUP {
            let _ = spectral_differentiate_into(&x, &mut out, &mut scratch, &cfg);
        }

        let start = Instant::now();
        for _ in 0..ITERS {
            let _ = spectral_differentiate_into(&x, &mut out, &mut scratch, &cfg);
        }
        let elapsed = start.elapsed();
        let mean_ns = elapsed.as_nanos() as f64 / ITERS as f64;
        let mean_us = mean_ns / 1000.0;

        let pass = mean_us <= TARGET_US;
        if !pass {
            all_pass = false;
        }
        let mark = if pass { "OK" } else { "X" };
        details.push(format!("N={n}: {mean_us:.2}us [{mark}]"));
    }

    if all_pass {
        GateResult::pass(
            "G2",
            format!(
                "all sizes <= {TARGET_US}us target ({ITERS} iters each): {}",
                details.join(", ")
            ),
        )
    } else {
        GateResult::fail(
            "G2",
            format!(
                "one or more sizes exceed {TARGET_US}us: {}",
                details.join(", ")
            ),
        )
    }
}

fn gate_g3_no_regression() -> GateResult {
    // G3: at order=0, the operator is identity (multiplier is 1, round-trip
    // IFFT(FFT(x)) = x up to f32 rounding from rustfft's butterflies).
    let n = 64usize;
    // Non-trivial input so any error is visible.
    let x: Vec<f32> = (0..n)
        .map(|i| (i as f32 * 0.1).sin() + 0.3 * (i as f32 * 0.07).cos())
        .collect();
    let mut out = vec![f32::NAN; n];
    let mut scratch = SpecDiffScratch::new();
    scratch.ensure_capacity(n);

    match spectral_differentiate_into(
        &x,
        &mut out,
        &mut scratch,
        &SpecDiffConfig::default_order(0),
    ) {
        Ok(()) => {
            let max_err = max_abs_error(&out, &x);
            // rustfft's round-trip is bit-exact for small real inputs in
            // our size range; allow a tiny epsilon to absorb platform jitter.
            // Bar matches the unit test (test_order_zero_is_identity).
            let epsilon = 1e-5;
            if max_err < epsilon {
                GateResult::pass(
                    "G3",
                    format!("order=0 is identity, max|err|={max_err:.2e} (<{epsilon})"),
                )
            } else {
                GateResult::fail(
                    "G3",
                    format!("order=0 NOT identity, max|err|={max_err:.2e} (>= {epsilon})"),
                )
            }
        }
        Err(e) => GateResult::fail("G3", format!("order=0 returned error: {e:?}")),
    }
}

fn gate_g4_zero_alloc() -> GateResult {
    let n = 256usize;
    let x = sine_period(n);
    let mut out = vec![0.0f32; n];
    let mut scratch = SpecDiffScratch::new();
    scratch.ensure_capacity(n);
    let cfg = SpecDiffConfig::DEFAULT;

    // Warmup: ensure scratch buffer is at capacity AND the FFT planner cache
    // is populated for this size (both are first-call allocations).
    for _ in 0..10 {
        let _ = spectral_differentiate_into(&x, &mut out, &mut scratch, &cfg);
    }

    // Measure allocations over a tight loop of steady-state calls.
    let iters = 100usize;
    let (_, allocs) = alloc_delta(|| {
        for _ in 0..iters {
            let _ = spectral_differentiate_into(&x, &mut out, &mut scratch, &cfg);
        }
    });

    if allocs == 0 {
        GateResult::pass(
            "G4",
            format!("0 allocations over {iters} steady-state calls"),
        )
    } else {
        GateResult::fail(
            "G4",
            format!(
                "{allocs} allocations over {iters} steady-state calls (expected 0; ~{} per call)",
                allocs / iters
            ),
        )
    }
}

fn g2_perf() -> bool {
    let shape = [8usize, 8, 8];
    let total = 512usize;
    let x: Vec<f32> = (0..total)
        .map(|i| {
            let v = (i as f32) * 0.01 - 2.5;
            v.sin() + 0.5 * (2.0 * v).cos()
        })
        .collect();
    let cfg = TuckerConfig::new(&shape, &[4, 4, 4]).expect("valid config");
    let mut scratch = TuckerScratch::with_capacity(&cfg);
    let mut result = TuckerResultScratch::with_capacity(&cfg);
    let mut recon = vec![0.0f32; total];

    // Warmup (first call may touch cold caches / page in scratch buffers).
    for _ in 0..10 {
        tucker_decompose_into(&x, &cfg, &mut scratch, &mut result).expect("decompose");
        tucker_reconstruct_into(&result, &shape, &mut recon, &mut scratch).expect("reconstruct");
    }

    let n_iters = 1000;
    let start = Instant::now();
    for _ in 0..n_iters {
        tucker_decompose_into(&x, &cfg, &mut scratch, &mut result).expect("decompose");
        tucker_reconstruct_into(&result, &shape, &mut recon, &mut scratch).expect("reconstruct");
    }
    let elapsed = start.elapsed();
    let mean_us = elapsed.as_secs_f64() * 1e6 / (n_iters as f64);

    // Cold-tier archival budget. The dominant cost is 3 small SVDs + 3 tensor
    // contractions on a 512-element tensor. Target is generous to stay stable
    // across CI machines; the actual perf is typically much lower.
    let target_us = 500.0;
    let pass = mean_us <= target_us;
    println!(
        "G2 (perf, (8,8,8) ranks (4,4,4)): mean = {mean_us:.2}µs over {n_iters} iters (target ≤ {target_us}µs) → {}",
        if pass { "PASS" } else { "FAIL" }
    );
    pass
}

fn g3_no_regression() -> bool {
    let shape = [4usize, 4, 4];
    let total = 64usize;
    let x: Vec<f32> = (0..total)
        .map(|i| ((i as f32) * 0.5 - 15.0).sin())
        .collect();
    // Full rank: ranks = shape. Reconstruction must be near-identity (f32 round-off).
    let cfg = TuckerConfig::new(&shape, &shape).expect("valid config");
    let mut scratch = TuckerScratch::with_capacity(&cfg);
    let mut result = TuckerResultScratch::with_capacity(&cfg);
    tucker_decompose_into(&x, &cfg, &mut scratch, &mut result).expect("decompose");
    let mut recon = vec![0.0f32; total];
    tucker_reconstruct_into(&result, &shape, &mut recon, &mut scratch).expect("reconstruct");

    let err = max_abs_error(&x, &recon);
    let pass = err < 1e-4;
    println!(
        "G3 (full-rank lossless): max abs error = {err:.3e} (target < 1e-4) → {}",
        if pass { "PASS" } else { "FAIL" }
    );
    pass
}

fn g4_alloc_free() -> bool {
    let shape = [8usize, 8, 8];
    let total = 512usize;
    let x: Vec<f32> = (0..total)
        .map(|i| {
            let v = (i as f32) * 0.01 - 2.5;
            v.sin() + 0.5 * (2.0 * v).cos()
        })
        .collect();
    let cfg = TuckerConfig::new(&shape, &[4, 4, 4]).expect("valid config");
    let mut scratch = TuckerScratch::with_capacity(&cfg);
    let mut result = TuckerResultScratch::with_capacity(&cfg);

    // Warmup: ensure all internal buffers are sized and any one-time setup is done.
    for _ in 0..5 {
        tucker_decompose_into(&x, &cfg, &mut scratch, &mut result).expect("decompose");
    }

    // Measure: 100 steady-state decompose calls must allocate 0 times.
    let n_calls = 100;
    let (_, allocs) = alloc_delta(|| {
        for _ in 0..n_calls {
            tucker_decompose_into(&x, &cfg, &mut scratch, &mut result).expect("decompose");
        }
    });

    let pass = allocs == 0;
    println!(
