impl LossKernel for MatmulKernel {
    fn short_prefix_loss(&self, theta: &[f32], z_prefix: &[f32]) -> f32 {
        let d = self.d.min(theta.len());
        let n_tokens = z_prefix.len() / d;
        let mut sum = 0.0_f32;
        for t in 0..n_tokens {
            let mut dot = 0.0_f32;
            for i in 0..d {
                dot += theta[i] * z_prefix[t * d + i];
            }
            sum += dot;
        }
        sum
    }
}

