        N_SEEDS,
        N_PROBLEMS * modes.len() * N_SEEDS
    );
    println!(
        "  Config: g_max={}, k={}, rsw={} (single-layer, λ degenerate)",
        config.g_max, config.k, config.rsw_len
    );
    println!();

    // Accumulate per-mode across all seeds
    let mut all_results: Vec<Vec<EvalResult>> = modes.iter().map(|_| Vec::new()).collect();

    for seed_idx in 0..N_SEEDS {
        let model_seed = 1000 + seed_idx as u64 * 7777;
        let problem_seed = 2000 + seed_idx as u64 * 3333;
        let model = MicroGpt::new(model_seed);
        let problems = gen_problems(problem_seed, N_PROBLEMS);

        for (mi, &mode) in modes.iter().enumerate() {
            // Each mode gets its own RNG for reproducibility
            let mut rng = SimpleRng::new(5000 + seed_idx as u64 * 111 + mi as u64 * 99);
            for problem in &problems {
                let result = evaluate(&model, problem, mode, &config, &mut rng);
                all_results[mi].push(result);
            }
        }
    }

    // Print results table
    println!(
        "{:<30} {:<8} {:<10} {:<10} {:<10} {:<8}",
        "Competitor", "EM_rate", "Token_acc", "Mean_NLL", "DigitMass", "N_consol"
    );
    println!("{}", "-".repeat(86));

    let mut agg_metrics = Vec::new();
    for (mi, &mode) in modes.iter().enumerate() {
        let agg = aggregate(&all_results[mi]);
        println!(
            "{:<30} {:<8.4} {:<10.4} {:<10.4} {:<10.4} {:<8.1}",
            mode.label(),
            agg.exact_match_rate,
            agg.token_accuracy,
            agg.mean_nll,
            agg.mean_digit_mass,
            agg.mean_consolidation_count
        );
        agg_metrics.push(agg);
    }
    println!();

    // ── T1.4: Verdict gate ──
    let baseline = &agg_metrics[0];
    let consolidation = &agg_metrics[1];
    let random_rewrite = &agg_metrics[2];

    let em_gain = consolidation.exact_match_rate - baseline.exact_match_rate;
    let ta_gain = consolidation.token_accuracy - baseline.token_accuracy;
    let nll_gain = consolidation.mean_nll - baseline.mean_nll; // negative = better
    let em_vs_random = consolidation.exact_match_rate - random_rewrite.exact_match_rate;
    let ta_vs_random = consolidation.token_accuracy - random_rewrite.token_accuracy;
    let nll_vs_random = consolidation.mean_nll - random_rewrite.mean_nll;

    println!("─── T1.4 Verdict Gate ───");
    println!();
    println!("  Consolidation vs Baseline:");
    println!(
        "    Exact-match gain:  {:+.4} ({:+.2}pp)",
        em_gain,
        em_gain * 100.0
    );
    println!(
        "    Token-acc gain:    {:+.4} ({:+.2}pp)",
        ta_gain,
        ta_gain * 100.0
    );
    println!("    NLL change:        {nll_gain:+.4} (negative = better)");
    println!();
    println!("  Consolidation vs Random-rewrite:");
    println!(
        "    EM difference:     {:+.4} ({:+.2}pp)",
        em_vs_random,
        em_vs_random * 100.0
    );
    println!(
        "    Token-acc diff:    {:+.4} ({:+.2}pp)",
        ta_vs_random,
        ta_vs_random * 100.0
    );
    println!("    NLL difference:    {nll_vs_random:+.4} (negative = consolidation better)");
    println!();

    // Verdict (≥2pp EM gain AND beats random-rewrite → GOAT confirmed)
    let em_gain_pp = em_gain * 100.0;
    let em_vs_random_pp = em_vs_random * 100.0;

    let goat_confirmed = em_gain_pp >= 2.0 && em_vs_random_pp > 0.0;
    let refuted = em_gain_pp.abs() < 1.0;
    let direction_matters = ta_vs_random.abs() > 0.005;

    println!("  Verdict:");
    if goat_confirmed {
        println!(
            "    ✅ GOAT CONFIRMED — consolidation beats baseline by ≥2pp AND beats random-rewrite."
        );
        println!("    Proceed to Phase 2 (feature flag).");
    } else if refuted {
        println!("    ❌ QUALITY GAIN REFUTED — consolidation ≈ baseline (<1pp difference).");
        println!("    The modelless mean-shift does not improve quality on this task.");
        println!("    This is expected on an untrained model: the IB argument applies to");
        println!("    TRAINED models whose KV cache carries learned extraneous detail.");
        println!("    Record raw numbers in Research 401 §PoC Addendum. Demote or shelve.");
    } else {
        println!("    ⚠️ INCONCLUSIVE — gain is between 1pp and 2pp. Needs more data or");
        println!("    a trained model to reach a definitive verdict.");
    }
    println!();

    if !direction_matters && !refuted {
        println!("    ⚠️ Mean-shift DIRECTION does not matter (consolidation ≈ random-rewrite).");
        println!("    Any gain is from noise injection, not IB-consistent consolidation.");
    } else if direction_matters {
        println!(
            "    ℹ️ Mean-shift direction matters (Δtoken_acc vs random = {ta_vs_random:+.4})."
        );
    }
    println!();

    // ── T1.5: Hyperparameter sweep ──
    // Use model seed 0, problems seed 1 for the sweep
    let sweep_model = MicroGpt::new(1000);
    let sweep_problems = gen_problems(2000, N_PROBLEMS);
    run_sweep(&sweep_model, &sweep_problems);

    println!("==============================================================");
    if goat_confirmed {
        println!("  OVERALL: GOAT CONFIRMED — eligible for Phase 2.");
        std::process::exit(0);
    } else {
        println!("  OVERALL: Quality claim NOT confirmed by this PoC.");
        println!("  (Architectural coverage stands; quality needs a trained model.)");
        std::process::exit(1);
    }
}

use katgpt_core::tilr::{TilrScratch, tilr_refine_into};
use std::hint::black_box;
use std::time::Instant;

#[path = "../tests/common/mod.rs"]
mod common;
counting_allocator!();

// ─── Helpers ────────────────────────────────────────────────────────────────

/// Deterministic xorshift PRNG (no `rand` dep — matches the lib-test pattern).
struct Rng {
    state: u32,
}
impl Rng {
    fn new(seed: u32) -> Self {
        Self {
            state: if seed == 0 { 0xDEAD_BEEF } else { seed },
        }
    }

#[inline(never)]
fn bb<T>(x: T) -> T {
    black_box(x)
}

// ─── Gate runner ────────────────────────────────────────────────────────────

struct GateResult {
    name: &'static str,
    passed: bool,
    detail: String,
}

impl GateResult {
    fn pass(name: &'static str, detail: impl Into<String>) -> Self {
        Self {
            name,
            passed: true,
            detail: detail.into(),
        }
    }

fn gate_g1_no_harm_bit_identity() -> GateResult {
    // For each (d, r), construct an orthonormal basis, pick a direction
    // orthogonal to it (lying in the complement), and verify γ = 0.0 exactly
    // and out == state bit-identically.
    let mut max_gamma_at_orthogonal: f32 = 0.0;
    let mut bit_mismatches: usize = 0;

    for &(d, r) in &[(8usize, 3usize), (64, 12)] {
        let mut rng = Rng::new(0xC0FFEE ^ (d as u32));
        let basis = gram_schmidt_basis(d, r, &mut rng);
        let mut scratch = TilrScratch::with_capacity(d, r);

        for _ in 0..100 {
            // Construct a direction in the complement of span(basis):
            // random vector, then subtract its projection onto span(basis).
            let mut direction = vec![0.0f32; d];
            rng.fill(&mut direction);
            for k in 0..r {
                let coeff: f32 = (0..d).map(|x| direction[x] * basis[k * d + x]).sum();
                for x in 0..d {
                    direction[x] -= coeff * basis[k * d + x];
                }
            }
            // Now direction ⊥ span(basis) → γ must be 0.

            let state: Vec<f32> = (0..d).map(|_| rng.next_f32()).collect();
            let mut out = vec![0.0f32; d];

            let gamma = tilr_refine_into(
                &state,
                &direction,
                &basis,
                r,
                0.5,
                1e-12,
                &mut scratch,
                &mut out,
            )
            .expect("tilr_refine_into failed on orthogonal direction");

            max_gamma_at_orthogonal = max_gamma_at_orthogonal.max(gamma);
            for i in 0..d {
                if state[i].to_bits() != out[i].to_bits() {
                    bit_mismatches += 1;
                }
            }
        }
    }

    let gamma_ok = max_gamma_at_orthogonal == 0.0;
    let bits_ok = bit_mismatches == 0;

    let detail = format!(
        "max γ at orthogonal: {max_gamma_at_orthogonal:.3e} (must be exactly 0.0); \
         bit mismatches: {bit_mismatches} (must be 0)"
    );

    if gamma_ok && bits_ok {
        GateResult::pass("G1", detail)
    } else {
        GateResult::fail("G1", detail)
    }
}

fn gate_g2_full_correction_and_boundedness() -> GateResult {
    let mut gamma_oob_count: usize = 0;
    let mut gamma_nan_count: usize = 0;
    let mut max_full_correction_err: f32 = 0.0;

    for &(d, r) in &[(8usize, 3usize), (64, 12)] {
        let mut rng = Rng::new(0xBEEF ^ (d as u32));
        let basis = gram_schmidt_basis(d, r, &mut rng);
        let mut scratch = TilrScratch::with_capacity(d, r);

        for _ in 0..500 {
            // Boundedness: random direction, check γ ∈ [0, 1].
            let direction: Vec<f32> = (0..d).map(|_| rng.next_f32()).collect();
            let state: Vec<f32> = (0..d).map(|_| rng.next_f32()).collect();
            let mut out = vec![0.0f32; d];

            let gamma = tilr_refine_into(
                &state,
                &direction,
                &basis,
                r,
                0.5,
                1e-12,
                &mut scratch,
                &mut out,
            )
            .unwrap();

            if !gamma.is_finite() {
                gamma_nan_count += 1;
            }
            if !(0.0..=1.0).contains(&gamma) {
                gamma_oob_count += 1;
            }
        }

        // Full-correction parity: direction = a basis vector (γ = 1).
        // out = state + eta_base * 1.0 * d_proj = state + eta_base * basis[k].
        let eta_base = 0.5_f32;
        for k in 0..r {
            let direction: Vec<f32> = basis[k * d..(k + 1) * d].to_vec();
            let state: Vec<f32> = (0..d).map(|_| rng.next_f32()).collect();
            let mut out = vec![0.0f32; d];

            let gamma = tilr_refine_into(
                &state,
                &direction,
                &basis,
                r,
                eta_base,
                1e-12,
                &mut scratch,
                &mut out,
            )
            .unwrap();

            // γ should be ~1.0.
            if (gamma - 1.0).abs() > 1e-4 {
                gamma_oob_count += 1;
            }

            // out = state + eta_base * basis[k].
            for i in 0..d {
                let expected = state[i] + eta_base * basis[k * d + i];
                let err = (out[i] - expected).abs();
                max_full_correction_err = max_full_correction_err.max(err);
            }
        }
    }

    let bounded_ok = gamma_oob_count == 0 && gamma_nan_count == 0;
    let parity_ok = max_full_correction_err < 1e-4;

    let detail = format!(
        "γ OOB: {gamma_oob_count}, NaN: {gamma_nan_count}; \
         full-correction max err: {max_full_correction_err:.3e} (budget 1e-4)"
    );

    if bounded_ok && parity_ok {
        GateResult::pass("G2", detail)
    } else {
        GateResult::fail("G2", detail)
    }
}

fn gate_g3_latency() -> GateResult {
    const ITERS: usize = 1024;
    const BATCHES: usize = 256;
    const TARGET_BELIEF_NS: f64 = 50.0; // d=8, r=3
    const TARGET_SHARD_NS: f64 = 200.0; // d=64, r=12

    // belief scale: d=8, r=3.
    let d_belief = 8;
    let r_belief = 3;
    let mut rng_belief = Rng::new(0xC0DE_0008);
    let basis_belief = gram_schmidt_basis(d_belief, r_belief, &mut rng_belief);
    let state_belief: Vec<f32> = (0..d_belief).map(|i| (i as f32) * 0.1).collect();
    let direction_belief: Vec<f32> = (0..d_belief).map(|i| (i as f32) * 0.05 - 0.2).collect();
    let mut out_belief = vec![0.0f32; d_belief];
    let mut scratch_belief = TilrScratch::with_capacity(d_belief, r_belief);

    let belief_ns = timed_median_ns(ITERS, BATCHES, || {
        let _ = bb(tilr_refine_into(
            bb(&state_belief),
            bb(&direction_belief),
            bb(&basis_belief),
            bb(r_belief),
            bb(0.5),
            bb(1e-12),
            &mut scratch_belief,
            &mut out_belief,
        ));
        bb(out_belief[0]);
    });

    // Shard scale: d=64, r=12.
    let d_shard = 64;
    let r_shard = 12;
    let mut rng_shard = Rng::new(0xC0DE_0040);
    let basis_shard = gram_schmidt_basis(d_shard, r_shard, &mut rng_shard);
    let state_shard: Vec<f32> = (0..d_shard).map(|i| (i as f32) * 0.01).collect();
    let direction_shard: Vec<f32> = (0..d_shard)
        .map(|i| ((i * 7) as f32) * 0.02 - 0.5)
        .collect();
    let mut out_shard = vec![0.0f32; d_shard];
    let mut scratch_shard = TilrScratch::with_capacity(d_shard, r_shard);

    let shard_ns = timed_median_ns(ITERS, BATCHES, || {
        let _ = bb(tilr_refine_into(
            bb(&state_shard),
            bb(&direction_shard),
            bb(&basis_shard),
            bb(r_shard),
            bb(0.5),
            bb(1e-12),
            &mut scratch_shard,
            &mut out_shard,
        ));
        bb(out_shard[0]);
    });

    let belief_pass = belief_ns < TARGET_BELIEF_NS;
    let shard_pass = shard_ns < TARGET_SHARD_NS;

    let detail = format!(
        "Belief (d={d_belief},r={r_belief}): {belief_ns:.1} ns (target <{TARGET_BELIEF_NS:.0}, {}); \
         Shard (d={d_shard},r={r_shard}): {shard_ns:.1} ns (target <{TARGET_SHARD_NS:.0}, {})",
        if belief_pass { "PASS" } else { "FAIL" },
        if shard_pass { "PASS" } else { "FAIL" },
    );

    if belief_pass && shard_pass {
        GateResult::pass("G3", detail)
    } else {
        GateResult::fail("G3", detail)
    }
}

fn gate_g4_zero_alloc() -> GateResult {
    let d = 64;
    let r = 12;
    let mut rng = Rng::new(0xA110C);
    let basis = gram_schmidt_basis(d, r, &mut rng);
    let state: Vec<f32> = (0..d).map(|i| (i as f32) * 0.05).collect();
    let direction: Vec<f32> = (0..d).map(|i| (i as f32) * 0.03 - 1.0).collect();
    let mut out = vec![0.0f32; d];
    let mut scratch = TilrScratch::with_capacity(d, r);

    // Warmup.
    for _ in 0..10 {
        let _ = tilr_refine_into(
            &state,
            &direction,
            &basis,
            r,
            0.5,
            1e-12,
            &mut scratch,
            &mut out,
        );
    }

    let iters = 100usize;
    let (_, allocs) = alloc_delta(|| {
        for _ in 0..iters {
            let _ = tilr_refine_into(
                &state,
                &direction,
                &basis,
                r,
                0.5,
                1e-12,
                &mut scratch,
                &mut out,
            );
        }
    });

    if allocs == 0 {
        GateResult::pass(
            "G4",
            format!("0 allocations over {iters} steady-state calls"),
        )
    } else {
        GateResult::fail(
            "G4",
            format!(
                "{allocs} allocations over {iters} steady-state calls (expected 0; ~{} per call)",
                allocs / iters
            ),
        )
    }
}

