            &format!("{allocs} allocs over 100 calls (expected 0)"),
        );
    }

    // Verify the result is non-degenerate (not just copying x).
    let diff = (0..d).map(|i| out[i] - x[i]).collect::<Vec<_>>();
    let disp = simd_dot_f32(&diff, &diff, d).sqrt();
