    let mut cache = ManceTangentCache::with_capacity(d, config.k, config.r);
    let mut out = vec![0.0; d];

    // Warmup
    for _ in 0..10 {
        let _ = manifold_erasure_step_cached_into(
            &x,
            &gradient,
            &pool,
            n,
            &config,
            &mut scratch,
            &mut cache,
            &mut out,
        );
    }

    let (_, allocs) = alloc_delta(|| {
        for _ in 0..100 {
            let _ = manifold_erasure_step_cached_into(
