    let labels = ["A (15,5)", "B (3,1)", "C (30,18)", "D (8,2)", "E (2,0)"];

    let eps = 0.05_f32;
    let scores = best_belief_scores(candidates, eps);

    println!("  Candidate evaluation at ε={eps} (95% confidence floor):");
    println!();
    println!("  {:>4} {:>12} {:>10} {:>10} {:>14}", "idx", "label", "empirical", "BB floor", "floor/empirical");
    println!("  ──── ──────────── ────────── ────────── ──────────────");
    for (i, &(s, f)) in candidates.iter().enumerate() {
        let empirical = s as f32 / (s + f) as f32;
        let ratio = scores[i] / empirical;
        println!(
            "  {:>4} {:>12} {:>10.4} {:>10.4} {:>14.3}",
            i,
            labels[i],
            empirical,
            scores[i],
            ratio
        );
    }
    println!();

    // Naive argmax: highest empirical rate.
    let naive_idx = candidates
        .iter()
        .enumerate()
        .max_by(|(_, a), (_, b)| {
            let ra = a.0 as f32 / (a.0 + a.1) as f32;
            let rb = b.0 as f32 / (b.0 + b.1) as f32;
            ra.partial_cmp(&rb).unwrap_or(core::cmp::Ordering::Equal)
        })
        .map(|(i, _)| i)
        .unwrap();

    // Conservative best_belief pick.
    let conservative_idx = select_best_belief(candidates, eps, None);

    println!(
        "  Naive argmax (highest empirical):     candidate {naive_idx} ({})",
        labels[naive_idx]
    );
    println!(
        "  Conservative best_belief (ε={eps}): candidate {conservative_idx} ({})",
        labels[conservative_idx]
    );
    println!();
    if naive_idx != conservative_idx {
        println!("  → The two rules DISAGREE. The naive rule picks the candidate with");
        println!("    the highest point estimate; best_belief picks the one whose");
        println!("    worst-case (at 95% confidence) is highest. For freeze/thaw");
        println!("    promotion, the conservative pick is the safer default — it");
        println!("    won't promote a candidate just because it got lucky on few");
        println!("    samples.");
    } else {
        println!("  → The two rules AGREE here — the well-evidenced candidate wins");
        println!("    under both rules.");
    }
    println!();
}

impl Lcg {
    fn new(seed: u64) -> Self {
        Self(seed.wrapping_mul(6_364_136_223_846_793_005).wrapping_add(1))
    }
    fn next_u64(&mut self) -> u64 {
        self.0 = self
            .0
            .wrapping_mul(6_364_136_223_846_793_005)
            .wrapping_add(1_442_695_040_888_963_407);
        self.0
    }
    /// Uniform in `[0, 1)`.
    fn next_f32(&mut self) -> f32 {
        ((self.next_u64() >> 40) as f32) / ((1u32 << 24) as f32)
    }
    fn below(&mut self, n: usize) -> usize {
        (self.next_u64() % (n as u64)) as usize
    }
}

fn cell_xy(i: usize, j: usize, n: usize) -> (f32, f32) {
    (i as f32 / (n - 1) as f32, j as f32 / (n - 1) as f32)
}

fn sigmoid(z: f32) -> f32 {
    1.0 / (1.0 + (-z).exp())
}

/// The latent score field `g`; validity probability is `p = sigmoid(g)`.
fn g_field(w: World, x: f32, y: f32) -> f32 {
    match w {
        World::Checkerboard => {
            const AMP: f32 = 3.0;
            const K: f32 = 1.0; // one full period across the unit square
            AMP * (std::f32::consts::TAU * K * x).cos() * (std::f32::consts::TAU * K * y).cos()
        }
        World::Corridor => {
            // A diagonal corridor of half-width `w` — smooth, and narrow
            // enough that its area is a small fraction of the square.
            const AMP: f32 = 3.0;
            const WIDTH: f32 = 0.10;
            let perp = (y - x) / std::f32::consts::SQRT_2; // signed distance to y = x
            AMP * (1.0 - 2.0 * (perp / WIDTH).powi(2))
        }
    }

impl Frontier {
    fn new(w: World, n: usize) -> Self {
        let mut p_true = vec![0.0f32; n * n];
        for j in 0..n {
            for i in 0..n {
                let (x, y) = cell_xy(i, j, n);
                p_true[j * n + i] = sigmoid(g_field(w, x, y));
            }
        }
        // Measure L exactly on the grid: the largest probability change
        // between 4-neighbours, per unit distance. Dilation only ever hops
        // between neighbours, so this constant makes the hop rule sound by
        // construction (see the module doc's caveat).
        let spacing = 1.0 / (n - 1) as f32;
        let mut max_step = 0.0f32;
        for j in 0..n {
            for i in 0..n {
                let p = p_true[j * n + i];
                if i + 1 < n {
                    max_step = max_step.max((p - p_true[j * n + i + 1]).abs());
                }
                if j + 1 < n {
                    max_step = max_step.max((p - p_true[(j + 1) * n + i]).abs());
                }
            }
        }
        Self {
            p_true,
            valid: vec![0; n * n],
            invalid: vec![0; n * n],
            cb: vec![f32::NEG_INFINITY; n * n],
            lipschitz: max_step / spacing,
            spacing,
            n,
            cert_direct: 0,
            cert_dilated: 0,
        }
    }

    /// The per-hop cost of the Lipschitz relaxation: how much certified
    /// lower bound a cell forfeits per grid step. Equals the largest
    /// adjacent probability change on this grid.
    fn hop_decrement(&self) -> f32 {
        self.lipschitz * self.spacing
    }

    /// Beta-Bernoulli posterior mean and standard deviation (plan item 2).
    fn beta_mean_sd(&self, c: usize) -> (f32, f32) {
        let a = 1.0 + self.valid[c] as f32;
        let b = 1.0 + self.invalid[c] as f32;
        let n = a + b;
        (a / n, ((a * b) / (n * n * (n + 1.0))).sqrt())
    }

    /// Union bound over (cells x rounds) — monotone in `t`. A stand-in for
    /// the paper's Eq 31; see the module doc.
    fn beta_t(&self, t: usize, delta: f32) -> f32 {
        let t = t.max(1) as f32;
        (2.0 * ((self.n * self.n) as f32 * t * t / delta).ln()).sqrt()
    }

    fn lcb(&self, c: usize, beta: f32) -> f32 {
        let (m, s) = self.beta_mean_sd(c);
        m - beta * s
    }

    /// Query the verifier once at `c`. The verifier is BINARY and
    /// stochastic — the algorithm never sees `p_true`.
    fn query(&mut self, c: usize, rng: &mut Lcg) {
        if rng.next_f32() < self.p_true[c] {
            self.valid[c] += 1;
        } else {
            self.invalid[c] += 1;
        }
    }

    fn neighbours(&self, z: usize) -> ([usize; 4], usize) {
        let (i, j, n) = (z % self.n, z / self.n, self.n);
        let mut out = [usize::MAX; 4];
        let mut k = 0;
        if i > 0 {
            out[k] = z - 1;
            k += 1;
        }
        if i + 1 < n {
            out[k] = z + 1;
            k += 1;
        }
        if j > 0 {
            out[k] = z - n;
            k += 1;
        }
        if j + 1 < n {
            out[k] = z + n;
            k += 1;
        }
        (out, k)
    }

    /// Eq 15 / Eq 32: relax the certified lower bound outward from `c`.
    /// `cb` only ever increases, so this terminates and the certified set is
    /// monotone.
    fn relax_from(&mut self, c: usize) {
        let dec = self.hop_decrement();
        let mut stack = vec![c];
        while let Some(z) = stack.pop() {
            let base = self.cb[z];
            if !base.is_finite() {
                continue;
            }
            let (nb, k) = self.neighbours(z);
            for &w in &nb[..k] {
                let cand = base - dec;
                if cand > self.cb[w] {
                    let was = self.cb[w] >= H;
                    self.cb[w] = cand;
                    if !was && cand >= H {
                        self.cert_dilated += 1;
                    }
                    stack.push(w);
                }
            }
        }
    }

    fn observe(&mut self, c: usize, rng: &mut Lcg, t: usize, delta: f32) {
        self.query(c, rng);
        let l = self.lcb(c, self.beta_t(t, delta));
        if l > self.cb[c] {
            let was = self.cb[c] >= H;
            self.cb[c] = l;
            if !was && l >= H {
                self.cert_direct += 1;
            }
            self.relax_from(c);
        }
    }

    fn is_certified(&self, c: usize) -> bool {
        self.cb[c] >= H
    }
    fn cells(&self) -> usize {
        self.n * self.n
    }
    fn certified_count(&self) -> usize {
        (0..self.cells()).filter(|&c| self.is_certified(c)).count()
    }
    /// Cells the algorithm claims are valid but which actually are not —
    /// the soundness scoreboard.
    fn violations(&self) -> usize {
        (0..self.cells())
            .filter(|&c| self.is_certified(c) && self.p_true[c] < H)
            .count()
    }
    fn truly_valid_count(&self) -> usize {
        (0..self.cells()).filter(|&c| self.p_true[c] >= H).count()
    }
    /// The best certified lower bound reached anywhere — the "headroom"
    /// numerator in the dilation-feasibility law.
    fn best_cb(&self) -> f32 {
        (0..self.cells()).fold(f32::NEG_INFINITY, |m, c| m.max(self.cb[c]))
    }

    /// Candidate query set: the certified set plus its immediate boundary.
    /// "Safe uncertainty sampling" (Eq 33) — only look where you can already
    /// stand, or one hop out.
    fn candidates(&self) -> Vec<usize> {
        let mut out = Vec::new();
        for c in 0..self.cells() {
            if self.is_certified(c) {
                out.push(c);
                continue;
            }
            let (nb, k) = self.neighbours(c);
            if nb[..k].iter().any(|&w| self.is_certified(w)) {
                out.push(c);
            }
        }
        out
    }

    fn ascii_map(&self) -> String {
        let mut s = String::new();
        for j in (0..self.n).rev() {
            for i in 0..self.n {
                let c = j * self.n + i;
                s.push(match (self.is_certified(c), self.p_true[c] >= H) {
                    (true, true) => '#',
                    (true, false) => 'X', // VIOLATION
                    (false, true) => '.',
                    (false, false) => ' ',
                });
            }
            s.push('\n');
        }
        let _ = write!(s, "  legend: '#' certified-correct  'X' VIOLATION  '.' valid-uncertified");
        s
    }
}

fn main() {
    const DELTA: f32 = 0.05;
    const BUDGET: usize = 6000;
    const N0: usize = 32;

    println!("=== Plan 580 Phase 0 — certified frontier PoC ===");
    println!("h = {H}, delta = {DELTA}, budget = {BUDGET} queries\n");

    // ── T0.1: dense world, soundness + growth ──────────────────────────────
    println!("--- T0.1  dense (smooth block checkerboard), grid {N0}x{N0} ---");
    let d = run(World::Checkerboard, N0, Strategy::Frontier, BUDGET, 0xC0FFEE, DELTA);
    println!(
        "certified {}/{} truly-valid | violations {} | by-cause: direct {} dilated {} | monotone {}",
        d.certified, d.truly_valid, d.violations, d.cert_direct, d.cert_dilated, d.monotone_ok
    );
    println!("{}", d.map);

    // ── T0.2: sparse corridor, passive vs frontier at equal budget ─────────
    println!("\n--- T0.2  sparse (narrow corridor): passive vs frontier, grid {N0}x{N0} ---");
    let (mut pt, mut ft, mut pv, mut fv) = (0usize, 0usize, 0usize, 0usize);
    let seeds = [1u64, 2, 3, 4, 5];
    for &s in &seeds {
        let p = run(World::Corridor, N0, Strategy::Passive, BUDGET, s, DELTA);
        let fr = run(World::Corridor, N0, Strategy::Frontier, BUDGET, s, DELTA);
        println!(
            "  seed {s}: passive {:>4} (viol {})   frontier {:>4} (viol {})",
            p.certified, p.violations, fr.certified, fr.violations
        );
        pt += p.certified;
        ft += fr.certified;
        pv += p.violations;
        fv += fr.violations;
    }
    let k = seeds.len() as f32;
    let (pass_avg, front_avg) = (pt as f32 / k, ft as f32 / k);
    println!(
        "\n  mean certified @ {BUDGET}: passive {pass_avg:.1}  frontier {front_avg:.1}  \
         separation {:.1}x",
        if pass_avg > 0.0 { front_avg / pass_avg } else { f32::INFINITY }
    );
    println!("  total violations: passive {pv}, frontier {fv}");

    // ── T0.3 (added): does the Lipschitz dilation contribute anything? ─────
    //
    // The plan's exit criterion does not ask this, but it decides whether
    // functions 4 + 5 (reachability_dilation / expand_certified) are worth
    // building at all: if every certified cell had to be queried anyway, a
    // plain per-cell Beta bound is the whole primitive.
    //
    // The law under test: a hop is admissible iff the achievable certified
    // lower bound clears the threshold by at least one hop's decrement,
    //     best_cb - H  >=  L * spacing,
    // and L*spacing is just the largest adjacent |dp| on the grid — so it
    // shrinks with resolution while the headroom does not.
    println!("\n--- T0.3  resolution sweep: is dilation feasible? ---");
    println!("  {:>7} {:>10} {:>10} {:>10} {:>8} {:>9} {:>6}", "grid", "hop_decr", "headroom", "certified", "direct", "dilated", "viol");
    for &n in &[16usize, 32, 64, 96] {
        let r = run(World::Checkerboard, n, Strategy::Frontier, BUDGET, 0xC0FFEE, DELTA);
        println!(
            "  {:>7} {:>10.4} {:>10.4} {:>10} {:>8} {:>9} {:>6}",
            format!("{n}x{n}"),
            r.hop_decrement,
            r.best_cb - H,
            r.certified,
            r.cert_direct,
            r.cert_dilated,
            r.violations
        );
    }

    // ── the Phase 0 exit criterion, evaluated ──────────────────────────────
    println!("\n=== Phase 0 exit criterion (plan-stated) ===");
    let sound = d.violations == 0 && fv == 0 && pv == 0;
    println!("  zero violations ............. {}", if sound { "PASS" } else { "FAIL" });
    println!(
        "  certified growth, monotone .. {}",
        if d.certified > 1 && d.monotone_ok { "PASS" } else { "FAIL" }
    );
    println!(
        "  passive/frontier separation . {}",
        if front_avg > pass_avg { "PASS" } else { "FAIL" }
    );
}

use katgpt_core::{BlobId, ChunkedContentStore, FixedSizeChunker, InMemoryChunkedStore};

/// Hex-encode the first 8 bytes of a BlobId for compact printing.
fn short_hex(id: &BlobId) -> String {
    let bytes = &id.as_bytes()[..8];

fn main() {
    println!("=== ChunkedContentStore Basic Example (Plan 272) ===\n");

    // Small chunk size so dedup is visible at small blob scale.
    let chunk_size = 32;
    let store = InMemoryChunkedStore::with_chunker(FixedSizeChunker::new(chunk_size));

    // --- Synthetic blob construction --------------------------------------
    //
    // Simulate two sword assets that share geometry but differ in the handle.
    // 64 bytes each = 2 chunks of 32 bytes per blob.
    //
    //   sword_base    = [blade_chunk (32B)] [handle_v1_chunk (32B)]
    //   sword_variant = [blade_chunk (32B)] [handle_v2_chunk (32B)]
    //
    // The blade chunk is shared → 1 dedup hit, 3 unique chunks total.
    let mut blade = [0u8; 32];
    for (i, b) in blade.iter_mut().enumerate() {
        *b = (i as u8).wrapping_mul(7);
    }
    let mut handle_v1 = [0u8; 32];
    for (i, b) in handle_v1.iter_mut().enumerate() {
        *b = (i as u8).wrapping_mul(11);
    }
    let mut handle_v2 = [0u8; 32];
    for (i, b) in handle_v2.iter_mut().enumerate() {
        *b = (i as u8).wrapping_mul(13);
    }

    let mut sword_base = Vec::with_capacity(64);
    sword_base.extend_from_slice(&blade);
    sword_base.extend_from_slice(&handle_v1);

    let mut sword_variant = Vec::with_capacity(64);
    sword_variant.extend_from_slice(&blade);
    sword_variant.extend_from_slice(&handle_v2);

    println!("Blob layout: chunk_size = {chunk_size} bytes; each sword = 2 chunks = 64 bytes");
    println!(
        "sword_base    = [blade | handle_v1]   ({} bytes)",
        sword_base.len()
    );
    println!(
        "sword_variant = [blade | handle_v2]   ({} bytes)\n",
        sword_variant.len()
    );

    // --- Put both blobs ----------------------------------------------------
    let id_base = store.put(&sword_base);
    let id_variant = store.put(&sword_variant);

    println!("Put sword_base    → BlobId {}", short_hex(&id_base));
    println!(
        "Put sword_variant → BlobId {}{}\n",
        short_hex(&id_variant),
        if id_base == id_variant {
            "  [IDENTICAL — unexpected]"
        } else {
            "  [different — expected, handles differ]"
        }
    );

    // --- Stats -------------------------------------------------------------
    let stats = store.stats();
    println!("StoreStats:");
    println!("  n_chunks_stored     = {}", stats.n_chunks_stored);
    println!("  n_blobs_indexed     = {}", stats.n_blobs_indexed);
    println!("  total_bytes_stored  = {}", stats.total_bytes_stored);
    println!("  total_bytes_logical = {}", stats.total_bytes_logical);
    println!(
        "  dedup_ratio         = {:.3}  (logical / stored; 1.0 = no dedup)\n",
        stats.dedup_ratio
    );

    // Expected: 3 unique chunks (blade, handle_v1, handle_v2) for 4 logical
    // chunk slots (2 per blob × 2 blobs). dedup_ratio = 128 / 96 ≈ 1.333.
    assert_eq!(
        stats.n_chunks_stored, 3,
        "expected 3 unique chunks (1 shared + 2 unique handles)"
    );
    assert_eq!(stats.n_blobs_indexed, 2);
    assert!(
        (stats.dedup_ratio - (128.0 / 96.0)).abs() < 1e-3,
        "expected dedup_ratio ≈ 1.333"
    );

    // --- Inclusion proof for chunk 0 (the shared blade) ------------------
    println!("--- Inclusion proof: chunk 0 of sword_variant (the blade) ---");
    let proof = store
        .prove_chunk(&id_variant, 0)
        .expect("leaf 0 must be provable");
    println!(
        "Proof: leaf_index = {}, siblings.len() = {}, expected_root = {}",
        proof.leaf_index,
        proof.siblings.len(),
        short_hex(&BlobId(proof.expected_root))
    );

    // The leaf hash for chunk 0 is BLAKE3(blade_chunk).
    let leaf_0_hash: [u8; 32] = blake3::hash(&blade).into();

    // --- Light-client verify (G4) -----------------------------------------
    //
    // verify_proof is an ASSOCIATED function — no `&self`. A light client
    // (browser, curator, anti-cheat) can verify the chunk is part of the
    // blob with ONLY the proof + the chunk it already has. No store access.
    let verified = InMemoryChunkedStore::verify_proof(&proof, &leaf_0_hash);
    println!("Light-client verify_proof(blade_hash, proof) = {verified}  [G4: no &self]\n");
    assert!(verified, "verify_proof must succeed for the correct leaf");

    // --- Negative control: wrong leaf hash must fail ----------------------
    let wrong_leaf_hash: [u8; 32] = blake3::hash(&handle_v2).into();
    let rejected = InMemoryChunkedStore::verify_proof(&proof, &wrong_leaf_hash);
    println!(
        "Negative control: verify_proof(handle_v2_hash, proof_for_leaf_0) = {rejected}  [must be false]"
    );
    assert!(!rejected, "wrong leaf hash must NOT verify");

    println!("\n=== All assertions passed. Plan 272 Phase 1 reference impl is operational. ===");
}

impl AggressiveField {
    fn new(scale: f32, axis: usize) -> Self {
        let mut hasher = blake3::Hasher::new();
        hasher.update(b"aggressive");
        hasher.update(&scale.to_le_bytes());
        hasher.update(&(axis as u32).to_le_bytes());
        Self {
            scale,
            axis,
            commitment: *hasher.finalize().as_bytes(),
        }
    }
}

impl CautiousField {
    fn new(i: usize, j: usize, angle_rad: f32) -> Self {
        let mut hasher = blake3::Hasher::new();
        hasher.update(b"cautious");
        hasher.update(&(i as u32).to_le_bytes());
        hasher.update(&(j as u32).to_le_bytes());
        hasher.update(&angle_rad.to_le_bytes());
        Self {
            i,
            j,
            cos_a: angle_rad.cos(),
            sin_a: angle_rad.sin(),
            commitment: *hasher.finalize().as_bytes(),
        }
    }
}

impl ArchetypeFieldSource<32> for CautiousField {
    fn evolve<'a>(&self, z: &[f32], dz_scratch: &'a mut [f32]) -> &'a mut [f32] {
        for k in 0..32 {
            dz_scratch[k] = 0.0;
        }
        // f(z) = (cos·z_i − sin·z_j − z_i,  sin·z_i + cos·z_j − z_j) on axes (i,j).
        // This is a small-angle rotation minus identity → a damping-like field.
        let zi = z[self.i];
        let zj = z[self.j];
        dz_scratch[self.i] = self.cos_a * zi - self.sin_a * zj - zi;
        dz_scratch[self.j] = self.sin_a * zi + self.cos_a * zj - zj;
        &mut dz_scratch[..32]
    }

