    // Show three sample entities (first, middle, last).
    let sample_indices = [0usize, N_ENTITIES / 2, N_ENTITIES - 1];
    println!("── Sample entities (first / middle / last) ──");
    for &i in &sample_indices {
        let r = &reports[i];
        println!("entity {:3}:", r.idx);
        println!(
            "    pi_dense  = [{:+.4}, {:+.4}, {:+.4}]",
            r.pi_dense[0], r.pi_dense[1], r.pi_dense[2]
        );
        println!(
            "    pi_sparse = [{:+.4}, {:+.4}, {:+.4}]",
            r.pi_sparse[0], r.pi_sparse[1], r.pi_sparse[2]
        );
        println!(
            "    max |Δpi|     = {:.2e}   max |Δtraj| = {:.2e}   L_pi = {:.4}",
            r.max_pi_diff, r.max_traj_diff, r.lipschitz
        );
        println!("    blake3        = {}", hex_short(&r.blake3));
    }

    // Population verdict.
    println!("\n── Population verdict ({N_ENTITIES} entities) ──");
    println!(
        "  sampling invariance on pi:     {n_pi_pass}/{N_ENTITIES} pass ({:.1}%)",
        100.0 * (n_pi_pass as f32) / (N_ENTITIES as f32)
    );
    println!(
        "  trajectory invariance:         {n_traj_pass}/{N_ENTITIES} pass ({:.1}%)",
        100.0 * (n_traj_pass as f32) / (N_ENTITIES as f32)
    );
    println!("  worst-case max |Δpi|     over population: {max_pi_diff_all:.2e}");
    println!("  worst-case max |Δtraj|   over population: {max_traj_diff_all:.2e}");

    // Sanity asserts (also catch a regression in the primitive).
    assert!(
        n_pi_pass == N_ENTITIES,
        "all entities must pass the pi invariance gate, only {n_pi_pass}/{N_ENTITIES} did"
    );
    assert!(
        n_traj_pass == N_ENTITIES,
        "all entities must pass the trajectory invariance gate, only {n_traj_pass}/{N_ENTITIES} did"
    );

    // Population diversity sanity: entities should NOT all commit identical pi
    // (they have distinct hidden trajectories → distinct personalities). If
    // they did, the test would be vacuous.
    let mut distinct_pi = std::collections::HashSet::new();
    for r in &reports {
        // Quantize to 4 decimal places for the distinctness check.
        let key = (
            (r.pi_dense[0] * 1e4).round() as i64,
            (r.pi_dense[1] * 1e4).round() as i64,
            (r.pi_dense[2] * 1e4).round() as i64,
        );
        distinct_pi.insert(key);
    }
    println!(
        "\n  distinct committed pi vectors: {}/{}",
        distinct_pi.len(),
        N_ENTITIES
    );
    assert!(
        distinct_pi.len() >= 50,
        "expected ≥50 distinct personalities across 100 entities, got {} — \
         test would be vacuous otherwise",
        distinct_pi.len()
    );

    println!("\n✓ FAME Proposition 3 holds: every entity's committed personality");
    println!("  is invariant under fog-of-war observation gaps (dense vs sparse");
    println!("  summaries of the same underlying trajectory → identical pi and");
    println!("  identical post-commit dynamics).");
    println!("\n=== Demo complete ===");
}

impl LinearField {
    fn new(scale: f32, axis: usize) -> Self {
        let mut h = blake3::Hasher::new();
        h.update(b"linear");
        h.update(&scale.to_le_bytes());
        h.update(&(axis as u32).to_le_bytes());
        Self {
            scale,
            axis,
            commitment: *h.finalize().as_bytes(),
        }
    }
}

impl RotationField {
    fn new(i: usize, j: usize, angle_rad: f32) -> Self {
        let mut h = blake3::Hasher::new();
        h.update(b"rotation");
        h.update(&(i as u32).to_le_bytes());
        h.update(&(j as u32).to_le_bytes());
        h.update(&angle_rad.to_le_bytes());
        Self {
            i,
            j,
            cos_a: angle_rad.cos(),
            sin_a: angle_rad.sin(),
            commitment: *h.finalize().as_bytes(),
        }
    }
}

impl ArchetypeFieldSource<32> for RotationField {
    fn evolve<'a>(&self, z: &[f32], dz: &'a mut [f32]) -> &'a mut [f32] {
        for k in 0..32 {
            dz[k] = 0.0;
        }
        let zi = z[self.i];
        let zj = z[self.j];
        dz[self.i] = self.cos_a * zi - self.sin_a * zj - zi;
        dz[self.j] = self.sin_a * zi + self.cos_a * zj - zj;
        &mut dz[..32]
    }

fn main() {
    println!("=== CommittedFieldBlend — Re-commit on Major Event ===");
    println!("=== Plan 321 T4.2 — version-bumped personality swap ===\n");

    // Three archetype fields — same family as the 01 example.
    let aggressive = LinearField::new(0.8, 0);
    let cautious = RotationField::new(8, 16, 0.3);
    let mut social_bias = [0.0f32; 32];
    for j in 0..32 {
        social_bias[j] = 0.02 + 0.003 * (j as f32);
    }
    let social = ConstantField::new(social_bias);
    let fields: [&dyn ArchetypeFieldSource<32>; 3] = [&aggressive, &cautious, &social];

    let dirs = make_direction_vectors();

    // ─── v=1: initial commit — "cautious" personality ──────────────────────
    //
    // Initial trajectory summary: weak on aggressive axis, strong on cautious
    // axis, weak on social axis.
    let mut initial_summary = [0.0f32; 32];
    for j in 0..32 {
        // DC 0.05 everywhere, plus an extra +0.3 on the cautious band [11..22).
        initial_summary[j] = 0.05 + if (11..22).contains(&j) { 0.3 } else { 0.0 };
    }

    let mut blend = TriArchetypeBlend::uncommitted();
    let hash_v1 = blend.commit(&initial_summary, &dirs, &fields, 1);

    println!("── v=1: initial commit (cautious personality) ──");
    println!(
        "  pi        = [{:+.4}, {:+.4}, {:+.4}]",
        blend.pi[0], blend.pi[1], blend.pi[2]
    );
    println!("  version   = {}", blend.version);
    println!("  blake3    = {}", hex_short(&blend.blake3));
    println!("  L_pi      = {:.4}", blend.lipschitz_bound(&fields));
    assert!(
        blend.verify_commitment(&fields),
        "v=1 commitment must verify"
    );

    // Snapshot the v=1 hash — an observer (sync layer, audit log) would cache
    // this for later comparison.
    let cached_hash_v1 = hash_v1;

    // ─── Major personality event: predator encounter ───────────────────────
    //
    // The host observes a NEW recent trajectory: the NPC fled. Flight
    // dominates the aggressive direction (axes 0..11) negatively — the NPC
    // retreated. The new summary dots strongly NEGATIVE on aggressive and
    // POSITIVE on social (it ran toward its pack).
    let mut post_encounter_summary = [0.0f32; 32];
    for j in 0..32 {
        post_encounter_summary[j] = 0.05;
    }
    for j in 0..11 {
        post_encounter_summary[j] -= 0.4; // strong negative on aggressive axis
    }
    for j in 22..32 {
        post_encounter_summary[j] += 0.4; // strong positive on social axis
    }

    // ─── v=2: re-commit on the major event ─────────────────────────────────
    //
    // Same `commit()` call, but with `version = 2`. This produces:
    //   - a new `pi` (from the new summary)
    //   - a new `blake3` (because both pi and version are part of the input)
    //   - a new audit event that the sync layer can record
    let pi_before = blend.pi;
    let hash_v2 = blend.commit(&post_encounter_summary, &dirs, &fields, 2);

    println!("\n── v=2: re-commit after predator encounter ──");
    println!(
        "  pi (old)  = [{:+.4}, {:+.4}, {:+.4}]",
        pi_before[0], pi_before[1], pi_before[2]
    );
    println!(
        "  pi (new)  = [{:+.4}, {:+.4}, {:+.4}]",
        blend.pi[0], blend.pi[1], blend.pi[2]
    );
    println!("  version   = {}", blend.version);
    println!("  blake3    = {}", hex_short(&blend.blake3));
    println!("  L_pi      = {:.4}", blend.lipschitz_bound(&fields));

    // ─── Assertions: re-commit semantics ───────────────────────────────────

    // (1) version IS part of the BLAKE3 input → distinct audit events.
    assert_ne!(
        hash_v1, hash_v2,
        "v=1 and v=2 must produce distinct BLAKE3 commitments"
    );
    assert_ne!(
        cached_hash_v1, blend.blake3,
        "the cached v=1 hash must NOT match the live v=2 hash"
    );
    println!("\n✓ v=1 and v=2 produce distinct BLAKE3 commitments (version IS part of the hash).");

    // (2) The new commitment verifies.
    assert!(
        blend.verify_commitment(&fields),
        "v=2 commitment must verify"
    );
    println!("✓ v=2 commitment verifies against the frozen fields.");

    // (3) The committed personality actually changed: aggressive gate dropped,
    // social gate rose. This is the behavioral consequence of re-commit.
    let g = |pi_k: f32| katgpt_core::personality_sigmoid(pi_k / blend.tau);
    let g_aggr_old = g(pi_before[0]);
    let g_aggr_new = g(blend.pi[0]);
    let g_social_old = g(pi_before[2]);
    let g_social_new = g(blend.pi[2]);
    println!(
        "\n  aggressive gate: {:.4} → {:.4}  (Δ = {:+.4})",
        g_aggr_old,
        g_aggr_new,
        g_aggr_new - g_aggr_old
    );
    println!(
        "  social gate:     {:.4} → {:.4}  (Δ = {:+.4})",
        g_social_old,
        g_social_new,
        g_social_new - g_social_old
    );
    assert!(
        g_aggr_new < g_aggr_old,
        "aggressive gate should drop after fleeing"
    );
    assert!(
        g_social_new > g_social_old,
        "social gate should rise after running to the pack"
    );
    println!("✓ personality changed in the expected direction.");

    // ─── Anti-tamper: detect a forged pi after commit ──────────────────────
    //
    // An attacker (or a buggy sync layer) flips a bit of pi[1]. The stored
    // hash no longer matches the recomputed one — verify_commitment catches
    // it. This is the thaw-time anti-tamper check.
    let pre_tamper_hash = blend.blake3;
    let pi1_original = blend.pi[1];
    let mut bytes = blend.pi[1].to_le_bytes();
    bytes[0] ^= 0x01;
    blend.pi[1] = f32::from_le_bytes(bytes);

    println!("\n── Anti-tamper check (flip 1 bit of pi[1]) ──");
    println!("  pi[1]: {:+.4} → {:+.4}", pi1_original, blend.pi[1]);
    assert!(
        !blend.verify_commitment(&fields),
        "tampered pi must fail verify_commitment"
    );
    println!("✓ verify_commitment returns false after pi tamper.");
    println!(
        "  (stored blake3 {} no longer matches recomputed hash)",
        hex_short(&pre_tamper_hash)
    );

    // Restore pi[1] so the commitment verifies again — demonstrating recovery.
    blend.pi[1] = pi1_original;
    assert!(
        blend.verify_commitment(&fields),
        "restored pi must verify again"
    );
    println!("✓ after restoring pi[1], verify_commitment passes again.");

    // ─── Observer view: cached-hash comparison detects the swap ────────────
    //
    // An observer that cached hash_v1 (e.g. the chain quorum layer, an audit
    // log) sees that the live hash differs from its cache → it knows a
    // re-commit happened. This is the sync-boundary audit semantics: the K
    // raw pi scalars + the new version cross the wire as a commitment event.
    println!("\n── Observer view (sync layer / audit log) ──");
    println!("  cached v=1 hash: {}", hex_short(&cached_hash_v1));
    println!("  live   v=2 hash: {}", hex_short(&blend.blake3));
    assert_ne!(
        cached_hash_v1, blend.blake3,
        "observer detects the personality swap via hash mismatch"
    );
    println!("✓ observer detects the re-commit via hash mismatch.");
    println!("  → the host would emit a SyncBlock with the new (pi, version, blake3)");
    println!("    as a commitment event (riir-chain R003 LatCal recipe, deferred).");

    println!("\n=== Demo complete ===");
}

fn main() {
    // Seed for the synthetic AirPassengers proxy. Deterministic → bit-reproducible.
    let series = generate_airpassengers_proxy(0xA175_1949_1960_u64);
    let n = series.len();
    let m = 12_usize;
    let h_forecast = 12_usize; // Forecast 12 months ahead (1 full season).
    let alpha = 0.05_f32;

    // Split: train on the first n − h_forecast, test on the last h_forecast.
    let n_train = n - h_forecast;
    let train = &series[..n_train];
    let test = &series[n_train..];

    println!("=== Conformal AirPassengers CRPS (Plan 340 T1.12) ===");
    println!("n_total = {n} (proxy), n_train = {n_train}, h_forecast = {h_forecast}, m = {m}");
    println!();

    // --- Conformal overlay on SeasonalPoolForecaster ---
    let forecaster_conf = SeasonalPoolForecaster::new(8 * m, m, 0.0, 0.0);
    let mut cal = ConformalIntervalCalibrator::new(
        forecaster_conf,
        1,
        h_forecast,
        m,
        256,
        0.0,
        DecayUnit::Step,
        ResidualMode::HStep,
        false,
    );
    // Fit on the training set.
    for &y in train.iter() {
        // Forecast at h=1 (next step), observe, update residual.
        let mut fc = 0.0_f32;
        cal.forecaster.forecast_into(&[], 1, &mut fc);
        cal.update_residual(y, fc, 0, 1);
        cal.forecaster.observe(y);
        cal.step();
    }
    // Rolling-origin forecast on the test set.
    let mut conf_intervals = Vec::with_capacity(h_forecast);
    let mut conf_actuals = Vec::with_capacity(h_forecast);
    let mut conf_crps_values = Vec::with_capacity(h_forecast);
    for (h, &y) in test.iter().enumerate() {
        let mut iv = PredictiveInterval::new(0.0, 0.0, 0.0, alpha);
        cal.interval_into(0, h + 1, alpha, &mut iv);
        conf_intervals.push(iv);
        conf_actuals.push(y);
        conf_crps_values.push(crps_interval(&iv, y));
        // Online update: observe the realized value.
        cal.forecaster.observe(y);
        let mut fc = 0.0_f32;
        cal.forecaster.forecast_into(&[], 1, &mut fc);
        cal.update_residual(y, fc, 0, 1);
        cal.step();
    }

    // --- Baseline: pure Seasonal-Naive (no conformal overlay) ---
    // For the baseline interval, use ±2σ from the training residuals.
    let mut baseline_forecaster = SeasonalPoolForecaster::new(8 * m, m, 0.0, 0.0);
    for &y in train {
        baseline_forecaster.observe(y);
    }
    // Compute residual std on the training set.
    let mut baseline_residuals = Vec::new();
    for &y in train.iter().take(n_train).skip(m) {
        let mut fc = 0.0_f32;
        baseline_forecaster.forecast_into(&[], 1, &mut fc);
        baseline_residuals.push(y - fc);
        baseline_forecaster.observe(y);
    }
    let mean_res: f32 = baseline_residuals.iter().sum::<f32>() / baseline_residuals.len() as f32;
    let var_res: f32 = baseline_residuals
        .iter()
        .map(|r| (r - mean_res).powi(2))
        .sum::<f32>()
        / baseline_residuals.len() as f32;
    let std_res = var_res.sqrt();
    let mut baseline_intervals = Vec::with_capacity(h_forecast);
    let mut baseline_actuals = Vec::with_capacity(h_forecast);
    // Reset the baseline forecaster with just the training data.
    let mut baseline_forecaster2 = SeasonalPoolForecaster::new(8 * m, m, 0.0, 0.0);
    for &y in train {
        baseline_forecaster2.observe(y);
    }
    for (h, &y) in test.iter().enumerate() {
        let mut fc = 0.0_f32;
        baseline_forecaster2.forecast_into(&[], h + 1, &mut fc);
        let iv = PredictiveInterval::new(fc - 1.96 * std_res, fc, fc + 1.96 * std_res, alpha);
        baseline_intervals.push(iv);
        baseline_actuals.push(y);
        baseline_forecaster2.observe(y);
    }

    // --- Report ---
    let conf_cov = empirical_coverage(&conf_intervals, &conf_actuals);
    let base_cov = empirical_coverage(&baseline_intervals, &baseline_actuals);
    let conf_crps = mean_crps_interval(&conf_intervals, &conf_actuals);
    let base_crps = mean_crps_interval(&baseline_intervals, &baseline_actuals);
    let conf_winkler = mean_winkler(&conf_intervals, &conf_actuals);
    let base_winkler = mean_winkler(&baseline_intervals, &baseline_actuals);

    // RMSE of the point forecasts.
    let conf_rmse: f32 = {
        let mut se = 0.0_f32;
        for (iv, &y) in conf_intervals.iter().zip(conf_actuals.iter()) {
            se += (iv.point - y).powi(2);
        }
        (se / conf_intervals.len() as f32).sqrt()
    };
    let base_rmse: f32 = {
        let mut se = 0.0_f32;
        for (iv, &y) in baseline_intervals.iter().zip(baseline_actuals.iter()) {
            se += (iv.point - y).powi(2);
        }
        (se / baseline_intervals.len() as f32).sqrt()
    };

    println!("Metric                  | Conformal Overlay | Seasonal-Naive ±2σ");
    println!("------------------------|-------------------|--------------------");
    println!("Empirical coverage (α=.05) | {conf_cov:>17.4} | {base_cov:>18.4}");
    println!("Mean interval CRPS      | {conf_crps:>17.4} | {base_crps:>18.4}");
    println!("Mean Winkler score      | {conf_winkler:>17.4} | {base_winkler:>18.4}");
    println!("Point-forecast RMSE     | {conf_rmse:>17.4} | {base_rmse:>18.4}");
    println!();
    println!("Training residual σ     = {std_res:.4}");
    println!(
        "Per-step CRPS (conformal) min/mean/max = {:.4} / {:.4} / {:.4}",
        conf_crps_values
            .iter()
            .cloned()
            .fold(f32::INFINITY, f32::min),
        conf_crps_values.iter().sum::<f32>() / conf_crps_values.len() as f32,
        conf_crps_values
            .iter()
            .cloned()
            .fold(f32::NEG_INFINITY, f32::max)
    );

    // Verdict: conformal overlay should have coverage closer to 0.95 than the
    // ±2σ baseline (which assumes Gaussian residuals — a poor fit for
    // multiplicative data), and competitive CRPS.
    println!();
    let _ = winkler_score; // sink — prove the import is used
    let target_coverage = 1.0 - alpha;
    let conf_cov_err = (conf_cov - target_coverage).abs();
    let base_cov_err = (base_cov - target_coverage).abs();
    if conf_cov_err < base_cov_err {
        println!(
            "✅ Conformal overlay coverage ({conf_cov:.4}) is closer to target ({target_coverage:.4}) than ±2σ baseline ({base_cov:.4})"
        );
    } else {
        println!(
            "⚠ Conformal overlay coverage ({conf_cov:.4}) is NOT closer to target ({target_coverage:.4}) than ±2σ baseline ({base_cov:.4}) — investigate"
        );
    }
    if conf_crps <= 2.0 * base_crps {
        println!(
            "✅ Conformal CRPS ({conf_crps:.4}) is within 2× of baseline ({base_crps:.4}) — Report-the-Floor gate holds"
        );
    } else {
        println!(
            "⚠ Conformal CRPS ({conf_crps:.4}) exceeds 2× baseline ({base_crps:.4}) — investigate"
        );
    }
}

fn main() {
    println!("KARC Phase 2 benchmark: higher-order + low-rank on double-scroll");
    println!("  params: D={D}, M={M}, K={K}, R={R}, r={LR_RANK}");
    println!("  N_train={N_TRAIN}, dt={DT}, Lyapunov time ≈ {LYAPUNOV_TIME_UNITS} units");

    // Generate trajectory.
    let traj_raw = generate_double_scroll(N_TRAIN + K + 50, DT, 1000, SUBSTEPS);
    // Per-coordinate normalize to [-1,1] (Chebyshev stability).
    let mut traj = traj_raw.clone();
    let mut scale = [1.0f32; D];
    let mut offset = [0.0f32; D];
    for d in 0..D {
        let mut lo = f32::INFINITY;
        let mut hi = f32::NEG_INFINITY;
        for i in 0..(traj.len() / D) {
            let v = traj[i * D + d];
            if v < lo {
                lo = v;
            }
            if v > hi {
                hi = v;
            }
        }
        let range = (hi - lo).max(1e-6);
        offset[d] = (hi + lo) * 0.5;
        scale[d] = 2.0 / range;
        for i in 0..(traj.len() / D) {
            traj[i * D + d] = (traj[i * D + d] - offset[d]) * scale[d];
        }
    }
    let n_total = traj.len() / D;
    println!("  accumulated {n_total} samples (normalized)");

    // ── Config 1: First-order full-rank baseline ──
    println!("\n── Config 1: first-order full-rank (Phase 1 baseline) ──");
    let basis = ChebyshevBasis::<M>::new();
    let mut f1: KarcForecaster<ChebyshevBasis<M>, D, M, K> =
        KarcForecaster::with_capacity(basis, N_TRAIN);
    for t in (K - 1)..(n_total - 1) {
        let mut delay = [0.0f32; K * D];
        for lag in 0..K {
            let idx = t - lag;
            for d in 0..D {
                delay[lag * D + d] = traj[idx * D + d];
            }
        }
        let mut target = [0.0f32; D];
        for d in 0..D {
            target[d] = traj[(t + 1) * D + d];
        }
        f1.accumulate_pair(&delay, &target);
    }
    let lambda = 5e-3f32;
    f1.fit_ridge(lambda).expect("fit_ridge");
    let nrmse_1 = autonomous_rollout_nrmse(&mut f1, &traj, &traj_raw, &scale, &offset, n_total);
    println!("  d_h = {}, NRMSE(1 LT) = {:.6e}", K * D * M, nrmse_1);

    // ── Config 2: Higher-order R=2 full-rank ──
    println!("\n── Config 2: higher-order R=2 full-rank (chunked Gram) ──");
    let d_h_1 = K * D * M;
    let d_h_ho = higher_order_feature_count(d_h_1, R);
    println!("  d_h_1 = {d_h_1}, d_h(R=2) = {d_h_ho}");
    // Build Gram and Cov via streaming (chunked_gram_into for G, manual for Cov).
    let lambda64 = lambda as f64;
    let mut gram_ho = vec![0.0f64; d_h_ho * d_h_ho];
    let mut cov_ho = vec![0.0f64; d_h_ho * D];
    // Feature buffer: we need to expand each delay state into higher-order features.
    // To stream into chunked_gram_into, we build an iterator of expanded rows.
    // For efficiency, expand all rows once into a buffer (N × d_h_ho) — at
    // N=2000, d_h_ho=4752, this is 2000×4752×4 = 38 MB (f32). Feasible.
    let n_pairs = n_total - K;
    let mut features_ho = vec![0.0f32; n_pairs * d_h_ho];
    let mut targets_ho = vec![0.0f32; n_pairs * D];
    let mut row_buf = vec![0.0f32; d_h_ho];
    {
        let basis = ChebyshevBasis::<M>::new();
        for (pair_idx, t) in ((K - 1)..(n_total - 1)).enumerate() {
            let mut delay = [0.0f32; K * D];
            for lag in 0..K {
                let idx = t - lag;
                for d in 0..D {
                    delay[lag * D + d] = traj[idx * D + d];
                }
            }
            feature_expand_higher_order::<ChebyshevBasis<M>, M, R>(&delay, &basis, &mut row_buf);
            features_ho[pair_idx * d_h_ho..(pair_idx + 1) * d_h_ho].copy_from_slice(&row_buf);
            for d in 0..D {
                targets_ho[pair_idx * D + d] = traj[(t + 1) * D + d];
            }
        }
    }
    // Chunked Gram (no lambda — low_rank_fit / the direct solve adds it).
    let feature_iter = (0..n_pairs).map(|i| &features_ho[i * d_h_ho..(i + 1) * d_h_ho] as &[f32]);
    chunked_gram_into(feature_iter, &mut gram_ho, 0.0, d_h_ho);
    // Cov = X^T Y.
    for i in 0..d_h_ho {
        for d in 0..D {
            cov_ho[i * D + d] = 0.0;
        }
    }
    for p in 0..n_pairs {
        let row = &features_ho[p * d_h_ho..(p + 1) * d_h_ho];
        let target = &targets_ho[p * D..(p + 1) * D];
        for i in 0..d_h_ho {
            let ri = row[i] as f64;
            for d in 0..D {
                cov_ho[i * D + d] += ri * target[d] as f64;
            }
        }
    }
    // Direct ridge solve: W^T = (G + λI)^{-1} Cov  (f64).
    for i in 0..d_h_ho {
        gram_ho[i * d_h_ho + i] += lambda64;
    }
    let mut chol_ho = vec![0.0f64; d_h_ho * d_h_ho];
    let mut z_ho = vec![0.0f64; d_h_ho * D];
    let mut wt_ho = vec![0.0f64; d_h_ho * D];
    ridge_solve_direct_f64(
        &mut wt_ho,
        &mut chol_ho,
        &mut z_ho,
        &gram_ho,
        &cov_ho,
        d_h_ho,
        D,
    );
    // Wout (D × d_h_ho, f32) = transpose of W^T.
    let mut wout_ho = vec![0.0f32; D * d_h_ho];
    for d in 0..D {
        for j in 0..d_h_ho {
            wout_ho[d * d_h_ho + j] = wt_ho[j * D + d] as f32;
        }
    }
    // Autonomous rollout with the higher-order Wout — 20 LT horizon for
    // full G1 gate (NRMSE over 1 LT + threshold at ε=0.1).
    let horizon_20lt = (20.0 * SAMPLES_PER_LT).ceil() as usize;
    let (pred_ho, truth_ho) = autonomous_rollout_higher_order(
        &wout_ho,
        &traj,
        &traj_raw,
        &scale,
        &offset,
        n_total,
        d_h_ho,
        horizon_20lt,
    );
    let n_one_lt = (1.0 * SAMPLES_PER_LT).ceil() as usize;
    let nrmse_2 = nrmse(&pred_ho[..n_one_lt * D], &truth_ho[..n_one_lt * D], D);
    let sigma_ho = mean_sigma(&truth_ho, D);
    let thr_sample_ho = threshold_time(&pred_ho, &truth_ho, D, 0.1, sigma_ho);
    let thr_lt_ho = thr_sample_ho as f64 / SAMPLES_PER_LT;
    println!("  NRMSE(1 LT) = {nrmse_2:.6e}");
    println!("  threshold (ε=0.1): {thr_sample_ho} samples = {thr_lt_ho:.2} LT");
    println!("  σ(u) mean per-coord: {sigma_ho:.4}");
    println!(
        "  G1 NRMSE  ≤ 1.0e-3 : {}",
        if nrmse_2 <= 1.0e-3 {
            "PASS ✅"
        } else {
            "FAIL ❌"
        }
    );
    println!(
        "  G1 thresh ≥ 8 LT   : {}",
        if thr_lt_ho >= 8.0 {
            "PASS ✅"
        } else {
            "FAIL ❌"
        }
    );
    println!("  paper reference: NRMSE 5.3e-4, threshold 16.7 LT");

    // ── Config 3: First-order low-rank r=8 ──
    println!("\n── Config 3: first-order low-rank r={LR_RANK} (ALS) ──");
    f1.fit_low_rank(LR_RANK, lambda, 100, 1e-10)
        .expect("fit_low_rank");
    let nrmse_3 = autonomous_rollout_low_rank(&mut f1, &traj, &traj_raw, &scale, &offset, n_total);
    println!(
        "  d_h = {}, r = {}, NRMSE(1 LT) = {:.6e}",
        K * D * M,
        LR_RANK,
        nrmse_3
    );

    // ── Summary ──
    println!("\n── T2.5 summary ────────────────────────────────────────────");
    println!("  first-order full-rank:  NRMSE = {nrmse_1:.6e}");
    println!("  higher-order R=2 full:  NRMSE = {nrmse_2:.6e}  (paper headline 5.3e-4)");
    println!("  first-order low-rank:   NRMSE = {nrmse_3:.6e}  (r={LR_RANK})");
    let ratio = nrmse_3 / nrmse_1.max(1e-12);
    println!("  low-rank / full-rank ratio: {ratio:.3}× (target ≤ 1.5×)");
    if ratio <= 1.5 {
        println!("  T2.5 gate: PASS ✅");
    } else {
        println!("  T2.5 gate: FAIL ❌ (low-rank NRMSE > 1.5× full-rank)");
    }
}

