    for &n in ns {
        let (base_logits, gold_idx) = build_retrieval_task(n, DELTA);
        let base_mass = softmax_gold_mass(&base_logits, gold_idx);

        let mut adapt_logits = base_logits.clone();
        let log_n = (n as f32).ln();
        let mode = SsmaxMode::Adaptive {
