fn section_4_api_surface() {
    println!("┌─────────────────────────────────────────────────────────────────────┐");
    println!("│ Section 4: API surface (SsmaxConfig caching vs per-call)          │");
    println!("└─────────────────────────────────────────────────────────────────────┘");
    println!();

    let mode_fixed = SsmaxMode::Fixed { s_l: 1.0 };
    let mode_adapt = SsmaxMode::Adaptive {
