use katgpt_core::{
    JacobianSvdScratch, jacobian_svd_at, numerical_rank, participation_ratio, phase_transition_gate,
};

// ── Setup (Plan 301 §Phase 2) ─────────────────────────────────────────────

const AMBIENT_DIM: usize = 48; // D
const INTRINSIC_DIM: usize = 6; // d
const NUM_SUBSPACES: usize = 3; // K
const SAMPLE_SIZES: [usize; 7] = [3, 5, 6, 7, 10, 50, 200];
const SEED: u64 = 0x3015EED_301C0FFEE;

/// N < d: error must exceed this for G1 PASS on the "fail" side.
const FAIL_THRESHOLD: f32 = 0.5;
/// N ≥ d: error must be below this for G1 PASS on the "recover" side.
const PASS_THRESHOLD: f32 = 0.1;
/// Empirical "recovery succeeded" cutoff for T2.6 gate-vs-empirical check.
const EMPIRICAL_RECOVERY_THRESHOLD: f32 = 0.15;

// ── Deterministic PRNG (PCG-XSH-RR 32-bit; zero external deps) ────────────

struct Rng {
    state: u64,
}

impl Rng {
    fn new(seed: u64) -> Self {
        Self {
            // Odd seeds required by PCG's LCG; force odd.
            state: seed | 1,
        }
    }

fn main() {
    let mut rng = Rng::new(SEED);

    println!();
    println!("═══════════════════════════════════════════════════════════════");
    println!("  Plan 301 Phase 2 — G1 GOAT: Subspace Phase Transition");
    println!("  Paper: arXiv:2409.02426 (Wang et al., Theorem 4)");
    println!(
        "  Setup: D={AMBIENT_DIM}  K={NUM_SUBSPACES}  d={INTRINSIC_DIM}  subspaces,  N ∈ {SAMPLE_SIZES:?}"
    );
    println!("═══════════════════════════════════════════════════════════════");
    println!();

    // T2.2 — generate ground-truth subspaces.
    let subspaces = generate_subspaces(&mut rng);

    // Sanity: each basis is orthonormal, and the K bases are mutually orthogonal.
    for (k, basis) in subspaces.iter().enumerate() {
        for i in 0..INTRINSIC_DIM {
            for j in 0..INTRINSIC_DIM {
                let mut dot = 0.0_f32;
                for r in 0..AMBIENT_DIM {
                    dot += basis[r * INTRINSIC_DIM + i] * basis[r * INTRINSIC_DIM + j];
                }
                let expected = if i == j { 1.0 } else { 0.0 };
                assert!(
                    (dot - expected).abs() < 1e-4,
                    "subspace {k} not orthonormal at ({i},{j}): got {dot}"
                );
            }
        }
    }
    println!(
        "✓ T2.2: K={NUM_SUBSPACES} mutually-orthogonal d={INTRINSIC_DIM} orthonormal bases in R^{AMBIENT_DIM}"
    );
    println!();

    // T2.3 + T2.4 — sweep N, run PCA per subspace, emit CSV.
    println!("── T2.3/T2.4: Recovery error vs N (mean over K subspaces) ──");
    println!("N,d,mean_err,min_err,max_err,gate(N,d),pr_mean,nr99_mean");

    struct NRow {
        n: usize,
        mean_err: f32,
        pr_mean: f32,
        nr_mean: f32,
    }

    let mut rows: Vec<NRow> = Vec::with_capacity(SAMPLE_SIZES.len());
    for &n in &SAMPLE_SIZES {
        let mut errors = Vec::with_capacity(NUM_SUBSPACES);
        let mut prs = Vec::with_capacity(NUM_SUBSPACES);
        let mut nrs = Vec::with_capacity(NUM_SUBSPACES);
        for subspace in subspaces.iter() {
            let r = run_single(subspace, n, &mut rng);
            errors.push(r.error);
            prs.push(r.pr_estimate);
            nrs.push(r.nr_estimate as f32);
        }
        let mean_err = errors.iter().sum::<f32>() / NUM_SUBSPACES as f32;
        let min_err = errors.iter().cloned().fold(f32::INFINITY, f32::min);
        let max_err = errors.iter().cloned().fold(f32::NEG_INFINITY, f32::max);
        let pr_mean = prs.iter().sum::<f32>() / NUM_SUBSPACES as f32;
        let nr_mean = nrs.iter().sum::<f32>() / NUM_SUBSPACES as f32;
        let gate = phase_transition_gate(n, INTRINSIC_DIM);
        println!(
            "{n},{INTRINSIC_DIM},{mean_err:.6},{min_err:.6},{max_err:.6},{gate},{pr_mean:.3},{nr_mean:.1}"
        );
        rows.push(NRow {
            n,
            mean_err,
            pr_mean,
            nr_mean,
        });
    }
    println!();

    // T2.5 — verify phase transition: N<d → err>0.5, N≥d → err<0.1.
    println!("── T2.5: Phase-transition check ──");
    println!("  Rule: N<d → err>{FAIL_THRESHOLD},  N≥d → err<{PASS_THRESHOLD}");
    let mut t25_pass = true;
    for r in &rows {
        let expect_high = r.n < INTRINSIC_DIM;
        let ok = if expect_high {
            r.mean_err > FAIL_THRESHOLD
        } else {
            r.mean_err < PASS_THRESHOLD
        };
        if !ok {
            t25_pass = false;
        }
        let mark = if ok { "✓" } else { "✗" };
        let side = if expect_high { "fail" } else { "recover" };
        println!(
            "  {} N={:>3}: mean_err={:.4}  (expected {} side)",
            mark, r.n, r.mean_err, side
        );
    }
    println!("  T2.5 verdict: {}", if t25_pass { "PASS" } else { "FAIL" });
    println!();

    // T2.6 — phase_transition_gate matches empirical recovery.
    println!("── T2.6: phase_transition_gate(N, d) vs empirical ──");
    let mut t26_pass = true;
    for r in &rows {
        let gate = phase_transition_gate(r.n, INTRINSIC_DIM);
        let empirical = r.mean_err < EMPIRICAL_RECOVERY_THRESHOLD;
        let ok = gate == empirical;
        if !ok {
            t26_pass = false;
        }
        let mark = if ok { "✓" } else { "✗" };
        println!(
            "  {} N={:>3}: gate={}, empirical={}, err={:.4}",
            mark, r.n, gate, empirical, r.mean_err
        );
    }
    println!("  T2.6 verdict: {}", if t26_pass { "PASS" } else { "FAIL" });
    println!();

    // T2.7 — participation_ratio vs numerical_rank as intrinsic-dim estimators.
    println!("── T2.7: Intrinsic-dim estimation (true d={INTRINSIC_DIM}) ──");
    println!(
        "  {:>4}  {:>10}  {:>10}  {:>8}",
        "N", "PR_round", "NR99", "winner"
    );
    let mut pr_wins = 0u32;
    let mut nr_wins = 0u32;
    for r in &rows {
        let pr_round = r.pr_mean.round();
        let nr_est = r.nr_mean;
        let pr_err = (pr_round - INTRINSIC_DIM as f32).abs();
        let nr_err = (nr_est - INTRINSIC_DIM as f32).abs();
        let winner = if pr_err < nr_err {
            pr_wins += 1;
            "PR"
        } else if nr_err < pr_err {
            nr_wins += 1;
            "NR"
        } else {
            "tie"
        };
        println!(
            "  {:>4}  {:>10.1}  {:>10.1}  {:>8}",
            r.n, pr_round, nr_est, winner
        );
    }
    println!();
    println!("  Summary: PR wins {pr_wins} row(s), NR wins {nr_wins} row(s).");
    println!("  On this synthetic MoLRG, NR tracks the true d better than PR");
    println!("  (sharp spectral elbow). For N<d, both correctly report N — the");
    println!("  true d is information-theoretically unrecoverable. NR is the");
    println!("  better production pick (discrete, threshold-tunable, immune to");
    println!("  continuous-valued drift); PR is the better diagnostic (shows");
    println!("  the effective dimensionality even when no clear elbow exists).");
    println!();

    // Final G1 verdict.
    let g1_pass = t25_pass && t26_pass;
    println!("═══════════════════════════════════════════════════════════════");
    if g1_pass {
        println!("  G1: PASS — phase transition reproduces on synthetic MoLRG.");
    } else {
        println!("  G1: FAIL — phase transition does NOT match theory.");
    }
    println!("═══════════════════════════════════════════════════════════════");
    println!();

    // Exit code so CI / `cargo run` callers can detect failure.
    if !g1_pass {
        std::process::exit(1);
    }
}

use super::{AcPrefix, AcPrefixMask};

/// Plug-in trait for any causal Transformer forward pass that can apply an
/// AC-GPT-style three-region attention mask.
///
/// `forward_for_ac_prefix` runs the model once over the augmented sequence and
/// returns per-position logprobs for the *actual* token at each slot
/// (i.e. `logprobs[i] = log p(token[i] | attended_context_i)`). The caller is
/// responsible for RoPE rotation using `augmented_positions`, for respecting
/// `mask.attends(i, j)`, and for the LM-head log-softmax (the AGENTS.md "sigmoid
/// not softmax" rule applies to blending/decision gates — the LM-head log-softmax
/// over vocab is standard and exempt).
pub trait ForwardForAcPrefix {
    /// Per-position logprobs over the augmented sequence.
    ///
    /// `augmented_tokens`, `augmented_positions`, `mask`, `loss_mask` are as
    /// described in [`AcPrefix::conditional_logprob`]. Returns a `Vec<f32>` of
    /// length `augmented_tokens.len()` — the model's logprob for the *actual*
    /// token at each position.
    fn forward_for_ac_prefix(
        &mut self,
        augmented_tokens: &[u32],
        augmented_positions: &[usize],
        mask: &AcPrefixMask,
        loss_mask: &[f32],
    ) -> Vec<f32>;

impl<'a> AcPrefix<'a> {
    /// Convenience wrapper around [`Self::conditional_logprob`] that takes a
    /// `&mut impl ForwardForAcPrefix` instead of a bare closure.
    pub fn conditional_logprob_via<F: ForwardForAcPrefix>(&self, fwd: &mut F) -> f32 {
        let n = self.augmented_len();
        let mut augmented_tokens = vec![0u32; n];
        let mut augmented_positions = vec![0usize; n];
        let mut loss_mask = vec![0.0f32; n];
        self.augmented_tokens_into(&mut augmented_tokens);
        self.original_positions_into(&mut augmented_positions);
        self.loss_mask_into(&mut loss_mask);
        let mask = AcPrefixMask::materialize_from(self);
        let logprobs =
            fwd.forward_for_ac_prefix(&augmented_tokens, &augmented_positions, &mask, &loss_mask);
        debug_assert_eq!(
            logprobs.len(),
            n,
            "forward_for_ac_prefix must return one logprob per augmented slot"
        );
        let mut acc = 0.0f32;
        for (lp, m) in logprobs.iter().zip(loss_mask.iter()) {
            acc += *lp * *m;
        }
        acc
    }

impl<'a> AcPrefix<'a> {
    /// Empty conditioning set — degenerates to a vanilla causal forward (this
    /// is the G3 invariant: `AcPrefix::empty(tokens)` must be bit-identical to
    /// a forward without `AcPrefix` at all).
    pub fn empty(base_tokens: &'a [u32]) -> Self {
        Self {
            base_tokens,
            conditioning_positions: &[],
        }
    }

impl AcPrefixMask {
    /// Bit-pack the [`AcPrefix::attends`] rule over the full
    /// `augmented_len × augmented_len` grid into a `Box<[u64]>` of size
    /// `ceil(augmented_len² / 64)`.
    ///
    /// This is the only allocating call in the module — run it once per
    /// augmented sequence for batched attention kernels that want a
    /// materialized mask. Hot-path callers should prefer
    /// [`AcPrefix::attends`] directly.
    pub fn materialize_from(prefix: &AcPrefix<'_>) -> Self {
        Self::materialize_with(prefix, |p, i, j| p.attends(i, j))
    }

    /// Bit-pack the [`AcPrefix::attends_dedup`] rule — the §3.5 modelless
    /// bias-correction variant (Issue 003 Phase 0 Path 2). See
    /// [`AcPrefix::attends_dedup`] for the doubled-signal-bias argument.
    ///
    /// Same allocation profile as [`Self::materialize_from`] (one `Box<[u64]>`
    /// per augmented sequence).
    pub fn materialize_dedup_from(prefix: &AcPrefix<'_>) -> Self {
        Self::materialize_with(prefix, |p, i, j| p.attends_dedup(i, j))
    }

    fn materialize_with<F: Fn(&AcPrefix<'_>, usize, usize) -> bool>(
        prefix: &AcPrefix<'_>,
        rule: F,
    ) -> Self {
        let n = prefix.augmented_len();
        let total_bits = n.checked_mul(n).expect("augmented_len squared overflows");
        let words = total_bits.div_ceil(64);
        let mut bits = vec![0u64; words].into_boxed_slice();
        // Word-stride outer loop so the compiler can hoist the row base.
        for i in 0..n {
            let row_base = i * n;
            for j in 0..n {
                if rule(prefix, i, j) {
                    let bit = row_base + j;
                    // SAFETY: bit < n*n <= words*64, so bit/64 is in bounds.
                    bits[bit / 64] |= 1u64 << (bit % 64);
                }
            }
        }
        Self { bits }
    }

    /// Number of 64-bit words in the packed buffer.
    #[inline]
    pub fn len(&self) -> usize {
        self.bits.len()
    }

    #[inline]
    pub fn is_empty(&self) -> bool {
        self.bits.is_empty()
    }

    /// Read the `attends(i, j)` bit. `row_len` must equal the `augmented_len`
    /// passed to [`Self::materialize_from`].
    #[inline]
    pub fn get(&self, i: usize, j: usize, row_len: usize) -> bool {
        let bit = i * row_len + j;
        (self.bits[bit / 64] >> (bit % 64)) & 1 != 0
    }
}

use std::fmt;

/// AND-OR tree node for hierarchical goal decomposition.
///
/// # Type parameters
///
/// - `G`: Goal descriptor (subgoal, strategy subgoal, etc.)
/// - `S`: Solution type (token path, action sequence, etc.)
///
/// # Invariants
///
/// - `Or` nodes: `best` is always `< children.len()` when `Some`
/// - `And` nodes: `solved_bits` bit i tracks child i solved status (up to 64 children)
/// - `Leaf` nodes: no children
#[derive(Debug, Clone)]
#[repr(u8)]
pub enum AndOrNode<G, S> {
    /// OR node: any child can succeed. Represents alternative strategies.
    Or {
        goal: G,
        children: Vec<AndOrNode<G, S>>,
        /// Index of best child so far (highest cumulative relevance).
        best: Option<usize>,
    },
    /// AND node: all children must succeed. Represents a decomposition.
    And {
        goal: G,
        children: Vec<AndOrNode<G, S>>,
        /// Bitfield: bit i = child i is solved. Avoids heap allocation for ≤64 children.
        solved_bits: u64,
        /// Number of set bits in `solved_bits`. Maintained incrementally for O(1) `is_solved`.
        /// u8 suffices: `solved_bits` is u64 so count ≤ 64.
        solved_count: u8,
        /// Partial solution assuming subgoals succeed.
        sketch: Option<S>,
    },
    /// Leaf: a solved or unsolved atomic goal.
    Leaf { goal: G, solution: Option<S> },
}

impl<G, S> AndOrNode<G, S> {
    // ── Constructors ─────────────────────────────────────────────

    /// Create an OR node with no children.
    #[inline]
    pub fn or(goal: G) -> Self {
        Self::Or {
            goal,
            children: Vec::new(),
            best: None,
        }
    }

