impl RedirectTable {
    /// Construct an empty redirect table.
    pub fn new() -> Self {
        RedirectTable {
            map: HashMap::new(),
        }
    }

    /// Register a redirect `old → new`. Chain-compresses: if `new` is itself
    /// redirected, the inserted value is the terminal target so future lookups
    /// are one-hop. Keeps chain depth ≤3 (ARG-aligned: prevents pathological
    /// redirect chains during repeated refactors).
    pub fn insert_redirect(&self, old: LabelId, new: LabelId) {
        let mut target = new;
        let mut depth = 0u8;
        let max_depth = 3;
        // Walk up to max_depth hops to find the terminal target.
        loop {
            if depth >= max_depth {
                break;
            }
            let pin = self.map.pin();
            match pin.get(&target) {
                Some(&next) if next != target => {
                    target = next;
                    depth += 1;
                }
                _ => break,
            }
        }
        let pin = self.map.pin();
        pin.insert(old, target);
    }

    /// Follow the redirect chain for `id` up to depth 3. Returns:
    /// - `Some(replacement)` if `id` redirects somewhere.
    /// - `None` if `id` is not in the table.
    ///
    /// Because inserts compress to the terminal target, most lookups are
    /// one-hop. The 3-hop ceiling is a safety net against races between
    /// concurrent inserts.
    pub fn redirect(&self, id: LabelId) -> Option<LabelId> {
        let mut cursor = id;
        let mut depth = 0u8;
        loop {
            if depth >= 3 {
                return Some(cursor); // ceiling reached; return what we have
            }
            let pin = self.map.pin();
            match pin.get(&cursor) {
                Some(&next) if next != cursor => {
                    cursor = next;
                    depth += 1;
                }
                _ => return if cursor == id { None } else { Some(cursor) },
            }
        }
    }

    /// Walk the full redirect chain (for audit). Allocates a Vec; use
    /// [`RedirectTable::redirect`] for hot-path lookups.
    pub fn redirect_chain(&self, id: LabelId) -> Vec<LabelId> {
        let mut chain = Vec::with_capacity(4);
        let mut cursor = id;
        chain.push(cursor);
        let mut depth = 0u8;
        while depth < 3 {
            let pin = self.map.pin();
            match pin.get(&cursor) {
                Some(&next) if next != cursor && !chain.contains(&next) => {
                    chain.push(next);
                    cursor = next;
                    depth += 1;
                }
                _ => break,
            }
        }
        chain
    }

    /// Returns `true` if `id` has a registered redirect.
    pub fn contains(&self, id: LabelId) -> bool {
        self.map.pin().contains_key(&id)
    }

    /// Returns the number of registered redirects (for diagnostics).
    pub fn len(&self) -> usize {
        self.map.pin().len()
    }

    /// Returns `true` if there are no redirects registered.
    pub fn is_empty(&self) -> bool {
        self.map.pin().is_empty()
    }
}

impl PolicyState {
    /// Returns `true` when this state mandates an immediate stop (ARG §2.1: `BLOCK → stop`).
    #[inline]
    pub fn must_stop(self) -> bool {
        matches!(self, PolicyState::Block)
    }

    /// Returns `true` when constraints MUST be applied to all downstream steps
    /// (ARG §2.1: `RESTRICT → proceed under constraints`).
    #[inline]
    pub fn requires_constraints(self) -> bool {
        matches!(self, PolicyState::Restrict | PolicyState::AllowWithRefocus)
    }
}

impl<'a> PolicyConstraints<'a> {
    /// Returns `true` if `label` is explicitly forbidden.
    #[inline]
    pub fn is_forbidden(&self, label: LabelId) -> bool {
        // Linear scan is correct here: forbidden lists are typically small (≤32).
        // For larger lists, the caller should pre-build a sorted slice + binary search.
        self.forbidden_labels.contains(&label)
    }

impl Default for ShouldProceed {
    #[inline]
    fn default() -> Self {
        ShouldProceed::Continue
    }
}

impl<'a> PolicyEnvelope<'a> {
    /// Evaluate the envelope against a request context (zero-alloc).
    ///
    /// `requested_label` is the candidate primary label from initial
    /// classification (Step 2). If `None`, allow/forbid checks are skipped
    /// (the constraints still apply via `requires_constraints`).
    #[inline]
    pub fn evaluate(&self, requested_label: Option<LabelId>) -> PolicyDecision {
        // Fast path: BLOCK is always Stop.
        if self.state.must_stop() {
            return PolicyDecision {
                proceed: ShouldProceed::Stop,
                enforce_constraints: false,
            };
        }

        // Label-level gates (if a primary label was provided).
        if let Some(label) = requested_label {
            // Forbidden label under any state forces Stop (policy gate is hard).
            if self.constraints.is_forbidden(label) {
                return PolicyDecision {
                    proceed: ShouldProceed::Stop,
                    enforce_constraints: false,
                };
            }
            // Allowlist enforcement: a non-allowed label under Restrict forces Refocus.
            if !self.constraints.is_allowed(label) && matches!(self.state, PolicyState::Restrict) {
                return PolicyDecision {
                    proceed: ShouldProceed::Refocus,
                    enforce_constraints: true,
                };
            }
        }

        match self.state {
            PolicyState::Allow => PolicyDecision {
                proceed: ShouldProceed::Continue,
                enforce_constraints: false,
            },
            PolicyState::AllowWithRefocus => PolicyDecision {
                proceed: ShouldProceed::Refocus,
                enforce_constraints: true,
            },
            PolicyState::Restrict => PolicyDecision {
                proceed: ShouldProceed::Continue,
                enforce_constraints: true,
            },
            PolicyState::Block => PolicyDecision {
                proceed: ShouldProceed::Stop,
                enforce_constraints: false,
            },
        }
    }

