impl<'a> TaxonomyValidator<'a> {
    /// Construct from a (possibly unsorted) slice of taxonomy nodes. Sorts by
    /// `id`. Panics on duplicate ids.
    pub fn new(mut nodes: Vec<TaxonomyNode<'a>>) -> Self {
        nodes.sort_by_key(|n| n.id);
        // Detect duplicates.
        for w in nodes.windows(2) {
            if w[0].id == w[1].id {
                panic!("TaxonomyValidator: duplicate LabelId {:?}", w[0].id);
            }
        }
        TaxonomyValidator { nodes }
    }

static LUT: std::sync::OnceLock<LutTable> = std::sync::OnceLock::new();

/// Build the LUT by calling the closed form for every `(eps, S, F)` triple.
/// One-time cost: ~5_120 × ~500 ns ≈ 2.5 ms on first call. After init, every
/// subsequent lookup is a single indexed array read.
fn build_lut() -> LutTable {
    let mut table = [[[0.0_f32; LUT_F]; LUT_S]; 5];
    for (e, &eps) in LUT_EPS.iter().enumerate() {
        for (s, table_s) in table[e].iter_mut().enumerate().take(LUT_S) {
            for (f, table_sf) in table_s.iter_mut().enumerate().take(LUT_F) {
                *table_sf = best_belief_score_cf(s as u32, f as u32, eps);
            }
        }
    }
    table
}

impl DotProductRouter {
    /// Construct from a direction slice. The direction is copied once into
    /// a `Box<[f32]>`; hot-path methods are zero-allocation.
    #[inline]
    pub fn new(direction: &[f32]) -> Self {
        Self {
            direction: direction.to_vec().into_boxed_slice(),
        }
    }

    /// Construct from an already-boxed direction (avoids the copy when the
    /// caller already owns the data).
    #[inline]
    pub fn from_boxed(direction: Box<[f32]>) -> Self {
        Self { direction }
    }

    /// Borrow the frozen direction.
    #[inline]
    pub fn direction(&self) -> &[f32] {
        &self.direction
    }

    /// Score a single candidate by dot-product with the direction. Truncates
    /// to the shorter of `candidate` / `self.direction` — callers should
    /// ensure matching dimensionality.
    #[inline]
    fn score(&self, candidate: &[f32]) -> f32 {
        let len = candidate.len().min(self.direction.len());
        crate::simd::simd_dot_f32(&candidate[..len], &self.direction[..len], len)
    }
}

