mod t42_clr_composition {
    use super::{VerifierGate, WriteDecision};
    use crate::branching::bank::BranchBank;

    /// Local stand-in for CLR's `should_write_memory(r_k, S_LP)`.
    /// Returns `true` iff both reward and curiosity exceed their CLR
    /// thresholds (the two-sided gate). This mirrors the contract documented
    /// in `verifier.rs` line 4.
    fn clr_should_write_memory(reward: f32, curiosity: f32) -> bool {
        let tau_reliable = 0.5;
        let tau_curiosity = 0.3;
        reward > tau_reliable && curiosity > tau_curiosity
    }

    /// CLR reject short-circuits the VerifierGate: the centroid check is
    /// never reached. This is the upstream-gate-rejects-fast-path contract.
    #[test]
    fn clr_reject_short_circuits_before_centroid_check() {
        let gate = VerifierGate::default();
        // CLR rejects (reward too low).
        let clr_allows = clr_should_write_memory(0.2, 0.9);
        assert!(!clr_allows);
        // Even with a perfect centroid, the composed gate Rejects.
        let decision = gate.should_write_composed(clr_allows, 0.99);
        assert_eq!(decision, WriteDecision::Reject);
    }

    /// CLR accept + on-centroid → Write. The downstream centroid check passes.
    #[test]
    fn clr_accept_plus_on_centroid_writes() {
        let gate = VerifierGate::default();
        let clr_allows = clr_should_write_memory(0.8, 0.5);
        assert!(clr_allows);
        let decision = gate.should_write_composed(clr_allows, 0.9);
        assert_eq!(decision, WriteDecision::Write);
    }

    /// CLR accept + off-centroid → Quarantine. The downstream centroid check
    /// catches a potential contamination that CLR's reward+curiosity gate
    /// alone would have admitted. This is the RIZZ value-add: CLR is
    /// necessary but not sufficient; the centroid quarantine adds a
    /// branch-local non-interference guard.
    #[test]
    fn clr_accept_but_off_centroid_quarantines() {
        let gate = VerifierGate::default();
        let clr_allows = clr_should_write_memory(0.8, 0.5);
        assert!(clr_allows);
        let decision = gate.should_write_composed(clr_allows, 0.3);
        assert_eq!(decision, WriteDecision::Quarantine);
    }

    /// Compositional equivalence: `should_write_composed(clr_allows, sim)`
    /// equals `should_write(r, c, sim)` when `clr_allows` is computed from
    /// the SAME `(r, c)` via the CLR gate. This proves the two API surfaces
    /// agree on the decision — the composition is consistent, not ad hoc.
    #[test]
    fn composed_gate_equivalent_to_direct_gate_under_same_inputs() {
        let gate = VerifierGate::default();
        for (r, c, sim) in [
            (0.8_f32, 0.5_f32, 0.9_f32), // all pass → Write
            (0.2, 0.9, 0.9),             // reward low → Reject
            (0.8, 0.1, 0.9),             // curiosity low → Reject
            (0.8, 0.5, 0.3),             // off-centroid → Quarantine
            (0.5, 0.5, 0.9),             // boundary reward (==) → Reject
            (0.8, 0.3, 0.9),             // boundary curiosity (==) → Reject
        ] {
            let clr_allows = clr_should_write_memory(r, c);
            let composed = gate.should_write_composed(clr_allows, sim);
            let direct = gate.should_write(r, c, sim);
            assert_eq!(
                composed, direct,
                "mismatch at (r={r}, c={c}, sim={sim}): composed={composed:?} direct={direct:?}"
            );
        }
    }

    /// End-to-end pipeline: CLR gate → VerifierGate → BranchBank write.
    /// Only writes that pass BOTH gates reach the branch's episodic store.
    /// This is the full RIZZ §"verifier-gated memory" composition.
    #[test]
    fn clr_plus_verifier_plus_bank_end_to_end() {
        let gate = VerifierGate::default();
        let mut bank: BranchBank<()> = BranchBank::new(8);
        let branch = bank.spawn(vec![1.0, 0.0, 0.0]).expect("spawn");

        // Case 1: CLR + Verifier both pass → write admitted.
        let r = 0.8_f32;
        let c = 0.5_f32;
        let sim = 0.9_f32;
        let clr_ok = clr_should_write_memory(r, c);
        let decision = gate.should_write_composed(clr_ok, sim);
        assert_eq!(decision, WriteDecision::Write);
        assert!(decision.is_write());
        let wrote = bank.write_episodic(branch, vec![1.0, 0.0, 0.0], (), r, None, 0);
        assert!(wrote, "write should succeed when decision is Write");
        assert_eq!(bank.get(branch).unwrap().episodic.len(), 1);

        // Case 2: CLR rejects → write NOT admitted (we check the gate, skip
        // the bank call — the runtime pattern is "ask the gate, then write").
        let r_bad = 0.2_f32;
        let clr_bad = clr_should_write_memory(r_bad, c);
        let decision_bad = gate.should_write_composed(clr_bad, sim);
        assert_eq!(decision_bad, WriteDecision::Reject);
        assert!(decision_bad.is_blocked());
        // Runtime would skip bank.write_episodic here. Episodic count stays 1.
        assert_eq!(bank.get(branch).unwrap().episodic.len(), 1);
    }
}

impl BranchRouter {
    /// Construct with custom thresholds.
    #[inline]
    #[must_use]
    pub const fn new(tau_snap: f32, tau_jaccard: f32, tau_spawn: f32) -> Self {
        Self {
            tau_snap,
            tau_jaccard,
            tau_spawn,
        }
    }

    /// Route a query embedding to a branch (dot-product snap only).
    ///
    /// This is the primary hot-path entry point. The caller pre-normalizes the
    /// query embedding so dot-product == cosine similarity. If the max
    /// dot-product ≥ `tau_snap`, snaps to the best branch; otherwise falls
    /// through to spawn/frozen.
    ///
    /// Zero allocation on the hot path.
    #[inline]
    pub fn route<E: Clone>(&self, query_embedding: &[f32], bank: &BranchBank<E>) -> RouteResult {
        // Primary: dot-product snap.
        if let Some(id) = self.snap_dot(query_embedding, bank) {
            return RouteResult::reuse(id);
        }

        // No snap. Spawn if capacity remains, else frozen.
        if bank.can_spawn() {
            RouteResult::spawn()
        } else {
            RouteResult::frozen()
        }
    }

    /// Route a query embedding AND query tokens (dot-product snap + Jaccard
    /// fallback).
    ///
    /// Use this when the caller can supply hash tokens (e.g., from an Engram
    /// query). The Jaccard fallback runs only when the primary dot-product snap
    /// fails AND both the query and at least one branch have non-empty token
    /// signatures.
    ///
    /// `query_tokens` MUST be sorted + deduplicated by the caller (same contract
    /// as `CognitiveBranch::token_signature`).
    ///
    /// Zero allocation on the hot path (the Jaccard merge-walk is scratch-free).
    #[inline]
    pub fn route_with_tokens<E: Clone>(
        &self,
        query_embedding: &[f32],
        query_tokens: &[u64],
        bank: &BranchBank<E>,
    ) -> RouteResult {
        // Primary: dot-product snap.
        if let Some(id) = self.snap_dot(query_embedding, bank) {
            return RouteResult::reuse(id);
        }

        // Secondary: Jaccard fallback (only if query has tokens).
        if !query_tokens.is_empty()
            && let Some(id) = self.snap_jaccard(query_tokens, bank)
        {
            return RouteResult::reuse(id);
        }

        // No snap. Spawn if capacity remains, else frozen.
        if bank.can_spawn() {
            RouteResult::spawn()
        } else {
            RouteResult::frozen()
        }
    }

    /// Dot-product snap: find the active branch with the highest
    /// `dot(query, spawn_anchor)`. Returns `Some(best_id)` if max ≥ `tau_snap`.
    ///
    /// Branch-free max-reduction over the active branch iterator. Zero alloc.
    ///
    /// # Issue 636 optimization
    ///
    /// When the bank's flat anchor cache is populated (`anchor_dim > 0`),
    /// reads directly from the contiguous `anchor_flat` buffer with a tight
    /// slot-scan loop instead of going through the `active_anchor_slices()`
    /// iterator. The contiguous buffer lets LLVM emit a NEON-vectorized
    /// dot-product loop (~28% faster than the AoS pointer-chase path at the
    /// production 8-branch shape, measured by `branch_router_cache_miss_bench`).
    /// The lifecycle filter (`is_routable()`) is still applied per-slot but
    /// inline in the hot loop — no iterator-closure overhead.
    #[inline]
    fn snap_dot<E: Clone>(
        &self,
        query_embedding: &[f32],
        bank: &BranchBank<E>,
    ) -> Option<BranchId> {
        // Fast path: flat anchor cache populated. Scan slots directly.
        if let Some((best_id, best_score)) = bank.snap_dot_flat(query_embedding, self.tau_snap) {
            return (best_score >= self.tau_snap).then_some(best_id);
        }

        // Fallback: no flat cache (empty bank or all-zero-dim anchors). Use the
        // original per-branch iterator path.
        let mut best_id = None;
        let mut best_score = f32::NEG_INFINITY;
        for branch in bank.active_branches() {
            let score = dot(query_embedding, &branch.spawn_anchor);
            if score > best_score {
                best_score = score;
                best_id = Some(branch.id);
            }
        }
        if best_score >= self.tau_snap {
            best_id
        } else {
            None
        }
    }

    /// Jaccard fallback: find the active branch with the highest token-overlap
    /// Jaccard similarity. Returns `Some(best_id)` if max ≥ `tau_jaccard`.
    ///
    /// Skips branches with empty `token_signature`. Zero alloc.
    #[inline]
    fn snap_jaccard<E: Clone>(
        &self,
        query_tokens: &[u64],
        bank: &BranchBank<E>,
    ) -> Option<BranchId> {
        let mut best_id = None;
        let mut best_jaccard = self.tau_jaccard; // start at threshold

        for branch in bank.active_branches() {
            if branch.token_signature.is_empty() {
                continue;
            }
            let j = jaccard(query_tokens, &branch.token_signature);
            if j > best_jaccard {
                best_jaccard = j;
                best_id = Some(branch.id);
            }
        }

        best_id
    }
}

