impl ProceduralRule {
    /// Net credit (`helpful - harmful`). Positive = keep; negative = prune candidate.
    #[inline]
    #[must_use]
    pub fn net_credit(&self) -> i64 {
        self.helpful as i64 - self.harmful as i64
    }

    /// Increment the helpful counter (rule fired and outcome improved).
    #[inline]
    pub fn record_helpful(&mut self) {
        self.helpful = self.helpful.saturating_add(1);
    }

    /// Increment the harmful counter (rule fired and outcome worsened).
    #[inline]
    pub fn record_harmful(&mut self) {
        self.harmful = self.harmful.saturating_add(1);
    }
}

impl BranchStats {
    /// Record a write and update the incremental average reward.
    #[inline]
    pub fn record_write(&mut self, reward: f32, tick: u64) {
        self.n_writes = self.n_writes.saturating_add(1);
        let n = self.n_writes as f32;
        self.avg_reward += (reward - self.avg_reward) / n;
        self.last_touch_tick = tick;
    }

    /// Record a read (snap-to-this-branch event).
    #[inline]
    pub fn record_read(&mut self, tick: u64) {
        self.n_reads = self.n_reads.saturating_add(1);
        self.last_touch_tick = tick;
    }

    /// True if this branch is stale (no touch within `stale_window` ticks of `now`).
    #[inline]
    #[must_use]
    pub fn is_stale(&self, now: u64, stale_window: u64) -> bool {
        now.saturating_sub(self.last_touch_tick) > stale_window
    }
}

#[inline]
fn write_vec_f32(out: &mut Vec<u8>, v: &[f32]) {
    out.extend_from_slice(&(v.len() as u32).to_le_bytes());

#[inline]
fn write_vec_u64(out: &mut Vec<u8>, v: &[u64]) {
    out.extend_from_slice(&(v.len() as u32).to_le_bytes());

impl ProceduralRule {
    /// Append the canonical encoding of this rule to `out`.
    #[inline]
    pub fn encode_to(&self, out: &mut Vec<u8>) {
        write_vec_f32(out, &self.direction);
        out.extend_from_slice(&self.antecedent);
        out.extend_from_slice(&self.strategy);
        out.extend_from_slice(&self.helpful.to_le_bytes());
        out.extend_from_slice(&self.harmful.to_le_bytes());
    }

    /// Decode a `ProceduralRule` from `bytes`, returning the rule and tail.
    #[inline]
    pub fn from_bytes_tail(bytes: &[u8]) -> Option<(Self, &[u8])> {
        let (direction, rest) = read_vec_f32(bytes)?;
        let (antecedent, rest) = rest.split_first_chunk::<32>()?;
        let (strategy, rest) = rest.split_first_chunk::<32>()?;
        let (helpful, rest) = read_u32_le(rest)?;
        let (harmful, rest) = read_u32_le(rest)?;
        Some((
            Self {
                direction,
                antecedent: *antecedent,
                strategy: *strategy,
                helpful,
                harmful,
            },
            rest,
        ))
    }
}

impl BranchStats {
    /// Append the canonical encoding of these stats to `out`. 20 bytes.
    #[inline]
    pub fn encode_to(&self, out: &mut Vec<u8>) {
        out.extend_from_slice(&self.n_writes.to_le_bytes());
        out.extend_from_slice(&self.n_reads.to_le_bytes());
        out.extend_from_slice(&self.avg_reward.to_le_bytes());
        out.extend_from_slice(&self.last_touch_tick.to_le_bytes());
    }

    /// Decode `BranchStats` from `bytes`, returning the stats and tail.
    /// Exactly 20 bytes consumed.
    #[inline]
    pub fn from_bytes_tail(bytes: &[u8]) -> Option<(Self, &[u8])> {
        let (n_writes, rest) = read_u32_le(bytes)?;
        let (n_reads, rest) = read_u32_le(rest)?;
        let (avg_reward, rest) = read_f32_le(rest)?;
        let (last_touch_tick, rest) = read_u64_le(rest)?;
        Some((
            Self {
                n_writes,
                n_reads,
                avg_reward,
                last_touch_tick,
            },
            rest,
        ))
    }
}

impl<E: EpisodicCodec> CognitiveBranch<E> {
    /// Append the canonical encoding of this branch to `out`.
    ///
    /// The 9 fields are written in declaration order: id, spawn_anchor,
    /// token_signature, episodic, procedural, failures, scope_ctx, stats,
    /// lifecycle. Each `Vec<T>` is length-prefixed;

//! Shared hot-path numeric helpers for the `branching` module.
//!
//! Previously `dot` was duplicated verbatim in `bank.rs`, `router.rs`, and
//! `projection.rs` (as `dot_fixed`). Centralising here removes the DRY
//! violation while keeping the same codegen contract: zero-allocation,
//! auto-vectorizable inner loop, `#[inline]` so each call site still
//! specialises to its actual slice length.

/// Dot product of two f32 slices.
///
/// Uses the shorter length when dimensions mismatch — callers are expected to
/// pre-normalise dimensions.
///
/// Session 32 (Bench 636 Phase 4): switched from `sum += a[i] * b[i]`
/// (double-rounding: mul then add) to `a[i].mul_add(b[i], sum)` (single-
/// rounding FMA). This matches the SIMD paths in `katgpt_types::simd::dot`
/// which already use NEON `vfmaq` / AVX2 `_mm256_fmadd_ps` — both are FMA.
/// The routing decision uses threshold comparisons (`>= tau_snap`); the
/// last-ULP difference between FMA and non-FMA does not flip any threshold.
/// At 8-dim HLA (the production case), this gives the compiler the FMA
/// contraction hint it needs on targets without hardware FMA (or when
/// `-C contraction=off`). On aarch64 (which has hardware FMA), the scalar
/// loop was already contracting to `fmadd` — this change is a no-op on
/// aarch64 but helps x86_64 / WASM / debug builds.
#[inline]
pub(crate) fn dot(a: &[f32], b: &[f32]) -> f32 {
    let n = a.len().min(b.len());
    let mut sum = 0.0f32;
    for i in 0..n {
        sum = a[i].mul_add(b[i], sum);
    }
    sum
}

/// Dot product of a fixed-size `D`-array with a (possibly shorter) slice.
///
/// Const-generic specialisation: when `b.len() >= D`, LLVM can fully unroll
/// the `D`-length inner loop. Falls back to `D.min(b.len())` if the caller
/// passes a shorter vector (defensive — callers should pre-normalise).
///
/// Session 32 (Bench 636 Phase 4): same FMA switch as `dot` above.
#[inline]
pub(crate) fn dot_fixed<const D: usize>(a: &[f32; D], b: &[f32]) -> f32 {
    let n = D.min(b.len());
    let mut sum = 0.0f32;
    for i in 0..n {
        sum = a[i].mul_add(b[i], sum);
    }
    sum
}

impl CompressionLevel {
    /// All levels from highest to lowest fidelity.
    pub const ALL: [CompressionLevel; 5] = [
        CompressionLevel::None,
        CompressionLevel::Bit8,
        CompressionLevel::Bit4,
        CompressionLevel::Bit3,
        CompressionLevel::Bit2,
    ];

    /// Bits per element.
    pub const fn bits(&self) -> u8 {
        match self {
            Self::None => 32,
            Self::Bit8 => 8,
            Self::Bit4 => 4,
            Self::Bit3 => 3,
            Self::Bit2 => 2,
        }
    }

    /// Compression ratio vs full precision.
    pub const fn compression_ratio(&self) -> f64 {
        32.0 / self.bits() as f64
    }
}

impl FidelityMatcher {
    /// Create with target perplexity delta.
    ///
    /// `target_delta` = acceptable increase in perplexity over full attention.
    /// 0.0 = lossless, 0.1 = ~10% perplexity increase acceptable.
    pub fn new(target_delta: f64) -> Self {
        Self {
            target_delta,
            calibration: CalibrationProfile::default(),
            sweep: CompressionSweep::default(),
        }
    }

    /// Whether calibration data is available.
    pub fn is_calibrated(&self) -> bool {
        !self.calibration.baseline_ce.is_empty()
    }

    /// T13: Record baseline cross-entropy for a single position.
    ///
    /// Call this after running forward() with full attention (CompressionLevel::None).
    /// `logits` = output logits from forward pass, `target_token` = ground-truth next token.
    pub fn record_baseline(&mut self, pos: usize, logits: &[f32], target_token: usize) {
        let ce = cross_entropy(logits, target_token);
        let buf = &mut self.calibration.baseline_ce;
        if pos >= buf.len() {
            buf.resize(pos + 1, 0.0f32);
        }
        buf[pos] = ce;
    }

    /// T13: Finalize baseline calibration (trim to actual length, validate).
    ///
    /// Returns number of positions calibrated.
    pub fn finalize_baseline(&mut self) -> usize {
        let buf = &mut self.calibration.baseline_ce;
        // Trim trailing zeros that were allocated but never recorded.
        while buf.last() == Some(&0.0f32) && !buf.is_empty() {
            buf.pop();
        }
        buf.len()
    }

    /// T14: Record compressed cross-entropy delta for a single position + level.
    ///
    /// `level` = compression level used, `logits` = output logits, `target_token` = ground-truth.
    /// Computes delta = compressed_CE - baseline_CE for this position.
    /// Does nothing if baseline is not available at this position.
    pub fn record_compressed(
        &mut self,
        pos: usize,
        level: CompressionLevel,
        logits: &[f32],
        target_token: usize,
    ) {
        let baseline_ce = match self.calibration.baseline_ce.get(pos) {
            Some(&ce) if ce != 0.0f32 => ce,
            _ => return, // No baseline at this position
        };

        let compressed_ce = cross_entropy(logits, target_token);
        let delta = compressed_ce - baseline_ce;

        let level_idx = level as usize;
        let deltas = &mut self.sweep.deltas;
        if deltas.is_empty() {
            deltas.resize_with(CompressionLevel::ALL.len(), Vec::new);
        }
        let level_buf = &mut deltas[level_idx];
        if pos >= level_buf.len() {
            level_buf.resize(pos + 1, 0.0f32);
        }
        level_buf[pos] = delta;
    }

    /// T14: Finalize compression sweep. Returns number of levels swept.
    pub fn finalize_sweep(&mut self) -> usize {
        let deltas = &mut self.sweep.deltas;
        // Trim trailing zeros from each level, then remove empty levels.
        for level_buf in deltas.iter_mut() {
            while level_buf.last() == Some(&0.0f32) && !level_buf.is_empty() {
                level_buf.pop();
            }
        }
        deltas.retain(|buf| !buf.is_empty());
        deltas.len()
    }

    /// Get the error-matched compression level for a given position.
    ///
    /// Decision logic:
    /// 1. If not calibrated → return `Bit4` (stub behavior)
    /// 2. If calibrated but no sweep data → return `Bit8` (safe default)
    /// 3. If calibrated + swept → find highest compression where `delta[pos] <= target_delta`.
    ///    Positions beyond calibration length extrapolate using the last known value.
    pub fn error_matched_level(&self, pos: usize) -> CompressionLevel {
        if !self.is_calibrated() {
            return CompressionLevel::Bit4;
        }

        let deltas = &self.sweep.deltas;
        if deltas.is_empty() {
            return CompressionLevel::Bit8;
        }

        // Clamp position to calibration length for extrapolation.
        let cal_len = self.calibration.baseline_ce.len();
        let effective_pos = if pos >= cal_len {
            cal_len.saturating_sub(1)
        } else {
            pos
        };

        // Find highest compression (lowest fidelity) where delta <= target_delta.
        // Iterate from highest compression (Bit2) down to None.
        for &level in CompressionLevel::ALL.iter().rev() {
            let level_idx = level as usize;
            let level_deltas = match deltas.get(level_idx) {
                Some(d) => d,
                None => continue,
            };
            let delta = match level_deltas.get(effective_pos) {
                Some(&d) => d,
                None => continue,
            };
            if delta as f64 <= self.target_delta {
                return level;
            }
        }

        // No compression level meets the delta target — return None (full precision).
        CompressionLevel::None
    }

    /// Target perplexity delta.
    #[inline]
    pub fn target_delta(&self) -> f64 {
        self.target_delta
    }

    /// Reference to calibration profile (for testing/inspection).
    pub fn calibration(&self) -> &CalibrationProfile {
        &self.calibration
    }

    /// Reference to compression sweep (for testing/inspection).
    pub fn sweep(&self) -> &CompressionSweep {
        &self.sweep
    }
}

impl CalibrationProfile {
    /// Baseline cross-entropy values.
    pub fn baseline_ce(&self) -> &[f32] {
        &self.baseline_ce
    }
}

impl CompressionSweep {
    /// Deltas for a specific compression level. Returns empty slice if not available.
    pub fn deltas_for_level(&self, level: CompressionLevel) -> &[f32] {
        self.deltas
            .get(level as usize)
            .map(|d| d.as_slice())
            .unwrap_or(&[])
    }
}

impl BreakevenTierPair {
    /// All tier pairs as a slice.
    pub const ALL: [BreakevenTierPair; 4] = [
        BreakevenTierPair::CpuToGpu,
        BreakevenTierPair::GpuToAne,
        BreakevenTierPair::CpuToSpeculative,
        BreakevenTierPair::GpuToSpeculative,
    ];

    /// Source (lower) tier.
    pub const fn source_tier(&self) -> ComputeTier {
        match self {
            Self::CpuToGpu | Self::CpuToSpeculative => ComputeTier::CpuOnly,
            Self::GpuToAne | Self::GpuToSpeculative => ComputeTier::CpuGpu,
        }
    }

    /// Target (higher) tier.
    pub const fn target_tier(&self) -> ComputeTier {
        match self {
            Self::CpuToGpu => ComputeTier::CpuGpu,
            Self::GpuToAne => ComputeTier::CpuGpuAne,
            // Speculative stays on the same hardware but adds draft model.
            Self::CpuToSpeculative => ComputeTier::CpuOnly,
            Self::GpuToSpeculative => ComputeTier::CpuGpu,
        }
    }

