            gpu_to_spec_n: self.breakeven_n(BreakevenTierPair::GpuToSpeculative),
            cpu_to_gpu_amortized: self.is_amortized(BreakevenTierPair::CpuToGpu),
            gpu_to_ane_amortized: self.is_amortized(BreakevenTierPair::GpuToAne),
        }
