/// Gate activation function for fused MLP kernels.
///
/// Different model architectures use different activations:
/// - Generic: ReLU (standard 2-layer MLP)
/// - LLaMA-family: SiLU (SwiGLU variant)
/// - Gemma 2: tanh-approximated GELU (GeGLU variant)
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
#[repr(u8)]
pub enum GateActivation {
    /// ReLU: max(0, x). Used in standard 2-layer MLP.
    #[default]
    Relu,
    /// SiLU/Swish: x * sigmoid(x). Used in LLaMA, Mistral SwiGLU.
    Silu,
    /// Tanh-approximated GELU: 0.5 * x * (1 + tanh(sqrt(2/π) * (x + 0.044715 * x³))).
    /// Used in Gemma 2 GeGLU.
    GegeluTanh,
    /// Approximated GELU using sigmoid: x * sigmoid(1.702 * x).
    /// Used in standard GeGLU.
    Gegelu,
}

impl GateActivation {
    /// Apply the activation function to a single value.
    #[inline(always)]
    pub fn activate(&self, x: f32) -> f32 {
        use crate::simd::{fast_sigmoid, fast_tanh};
        match self {
            Self::Relu => x.max(0.0),
            Self::Silu => {
                // SiLU = x · σ(x). Uses Cephes-backed fast_sigmoid.
                x * fast_sigmoid(x)
            }
            Self::GegeluTanh => {
                // sqrt(2/π) — f32 cannot represent more than ~7 significant digits.
                const SQRT_2_OVER_PI: f32 = 0.797_884_6;
                // Cubic via mul_add for FMA fusion: 0.044715 * x³ + x.
                let x_sq = x * x;
                let inner = SQRT_2_OVER_PI * 0.044_715_f32.mul_add(x * x_sq, x);
                0.5 * x * (1.0 + fast_tanh(inner))
            }
            Self::Gegelu => {
                // GELU sigmoid approximation: x · σ(1.702 · x).
                x * fast_sigmoid(1.702 * x)
            }
        }
    }

#[cfg(feature = "moa_inference")]
impl MoaActivation {
    /// Apply the MoA activation function to a single value.
    #[inline(always)]
    pub fn activate(&self, x: f32) -> f32 {
        use crate::simd::{fast_sigmoid, fast_tanh};
        match self {
            Self::Id => x,
            Self::Relu => x.max(0.0),
            Self::Relu2 => {
                let r = x.max(0.0);
                r * r
            }
            Self::LeakyRelu => {
                const ETA: f32 = 0.01;
                if x >= 0.0 { x } else { ETA * x }
            }
            Self::Gelu => {
                // Sigmoid approximation: x * sigmoid(1.702 * x).
                x * fast_sigmoid(1.702 * x)
            }
            Self::Silu => {
                // SiLU = x · σ(x). Uses Cephes-backed fast_sigmoid.
                x * fast_sigmoid(x)
            }
            Self::Tanh => fast_tanh(x),
        }
    }

