impl Backstop {
    /// Construct a `TokenPct` backstop, clamping `pct` to `[0.0, 1.0]`.
    ///
    /// `pct <= 0.0` degenerates to "always force" (use `TokenPct(0.0)`
    /// deliberately if that's intended); `pct >= 1.0` to "force only at the
    /// full window". Values outside the range are silently clamped (this is
    /// the documented behavior — callers may pass sloppy bounds).
    #[inline]
    #[must_use]
    pub fn token_pct(pct: f32) -> Self {
        debug_assert!(
            pct.is_finite(),
            "Backstop::token_pct: pct must be finite, got {pct}"
        );
        Self::TokenPct(pct.clamp(0.0, 1.0))
    }

    /// Returns `true` iff the backstop forces compaction at the given
    /// `prompt_len` / `ctx_window`.
    ///
    /// - [`Backstop::None`] / [`Backstop::Never`] → always `false`.
    /// - `Backstop::TokenPct(p)` → `prompt_len >= (p * ctx_window) as usize`.
    ///
    /// Zero-allocation: a single comparison on the hot path.
    #[inline]
    #[must_use]
    pub fn should_force(&self, prompt_len: usize, ctx_window: usize) -> bool {
        match self {
            Self::None | Self::Never => false,
            Self::TokenPct(pct) => {
                // Avoid f64 promotion: compute the threshold in usize via
                // `(pct * ctx_window as f32) as usize`. Float rounding at the
                // boundary is acceptable — the backstop is a coarse safety
                // net, not a precise trigger.
                let threshold = (*pct * ctx_window as f32) as usize;
                prompt_len >= threshold
            }
        }
    }

    /// Returns the configured pct, or `None` for [`Backstop::None`] /
    /// [`Backstop::Never`].
    #[inline]
    #[must_use]
    pub const fn pct(&self) -> Option<f32> {
        match self {
            Self::TokenPct(p) => Some(*p),
            Self::None | Self::Never => None,
        }
    }
}

impl FireRule {
    /// Evaluate the rule against a packed `yes_mask`.
    ///
    /// `yes_mask` bit `i` is set iff predicate `i` is `Yes` (see
    /// [`RubricVerdict::yes_mask`](super::RubricVerdict::yes_mask)).
    #[inline]
    #[must_use]
    pub fn evaluate_mask(&self, yes_mask: u8) -> bool {
        match self {
            Self::And(mask) => *mask & yes_mask == *mask,
            Self::Or(mask) => *mask & yes_mask != 0,
            // `Not` takes a *single-bit* index mask (1 << index). If a caller
            // passes a multi-bit mask, only the lowest set bit is negated —
            // debug-assert so the misuse is caught.
            Self::Not(bit) => {
                debug_assert!(
                    (*bit).is_power_of_two() || *bit == 0,
                    "FireRule::Not expects a single-bit index mask (1 << i); got {bit:#010b}"
                );
                yes_mask & bit == 0
            }
            Self::Box(op, a, b) => {
                let lhs = a.evaluate_mask(yes_mask);
                let rhs = b.evaluate_mask(yes_mask);
                match op {
                    CombineOp::And => lhs && rhs,
                    CombineOp::Or => lhs || rhs,
                }
            }
        }
    }

    /// Convenience: evaluate against a full [`RubricVerdict`].
    ///
    /// Debug-asserts `N <= 8` (the bitmask width).
    #[inline]
    #[must_use]
    pub fn evaluate<const N: usize>(&self, verdict: &RubricVerdict<N>) -> bool {
        self.evaluate_mask(verdict.yes_mask())
    }

    /// Construct the paper's search rule: `C1 ∧ C2 ∧ C3 ∧ ¬N1` over a
    /// 4-predicate rubric. Indices: C1=0, C2=1, C3=2, N1=3.
    ///
    /// `Box(And, And(C1|C2|C3), Not(N1))`: COMPRESS iff (all of C1,C2,C3
    /// are Yes) AND (N1 is No).
    #[must_use]
    pub fn search_rule_4() -> Self {
        // C1|C2|C3 mask = 0b0111. N1 bit = 0b1000.
        Self::Box(
            CombineOp::And,
            Box::new(Self::And(0b0111)),
            Box::new(Self::Not(0b1000)),
        )
    }

    /// Construct the paper's math rule: `Q1 ∨ (Q2 ∧ Q3)` over a 3-predicate
    /// rubric. Indices: Q1=0, Q2=1, Q3=2.
    ///
    /// `Box(Or, Or(Q1), And(Q2|Q3))`: COMPRESS iff Q1 is Yes OR (Q2 and Q3
    /// both Yes).
    #[must_use]
    pub fn math_rule_3() -> Self {
        // Q1 mask = 0b001. Q2|Q3 mask = 0b110.
        Self::Box(
            CombineOp::Or,
            Box::new(Self::Or(0b001)),
            Box::new(Self::And(0b110)),
        )
    }

    /// Construct the shard-freeze rule (G7 isomorphism target): `P0 ∧ P1`
    /// over a 2-predicate rubric. Indices: P0 (input_sufficient)=0,
    /// P1 (output_converged)=1.
    ///
    /// `And(0b0011)`: COMPRESS iff both predicates are Yes. This mirrors
    /// `ConsolidationPipeline::can_freeze`'s `input_sufficient &&
    /// output_converged`.
    #[must_use]
    pub fn shard_freeze_rule_2() -> Self {
        Self::And(0b0011)
    }
}

impl CacheReuseProbe {
    /// Construct a default probe manager.
    #[inline]
    #[must_use]
    pub fn new() -> Self {
        Self {}
    }

    /// Append `rubric_prompt` to `trajectory` (preserving the KV cache of
    /// `y_{1:t}`), returning a [`ProbeToken`] that records the pre-probe
    /// length for later [`revert`](Self::revert).
    ///
    /// # Allocation
    ///
    /// `O(k)` where `k = rubric_prompt.len()` — the cost of extending the
    /// `Vec`. This is NOT `O(L)` (the existing trajectory is not touched).
    /// The KV cache prefill of the appended prompt is the caller's engine
    /// responsibility and is `O(k²)` (prompt self-attention) + `O(L·k)`
    /// (cross-attention to the cached prefix) — both are `k`-dependent, not
    /// `L`-dominated.
    ///
    /// # Returns
    ///
    /// A [`ProbeToken`] whose [`ProbeToken::pre_len`] is the trajectory
    /// length *before* the append.
    #[inline]
    pub fn probe_append(&self, trajectory: &mut Vec<u8>, rubric_prompt: &[u8]) -> ProbeToken {
        let pre_len = trajectory.len();
        trajectory.extend_from_slice(rubric_prompt);
        ProbeToken(pre_len)
    }

    /// Revert the trajectory to its pre-probe length on a CONTINUE decision.
    ///
    /// After this, `trajectory.len() == token.pre_len()` and the KV cache is
    /// uncontaminated (the caller's engine is responsible for dropping the
    /// probe's KV entries; this method only manages the byte buffer).
    ///
    /// # Panics
    ///
    /// Debug-asserts `token.pre_len() <= trajectory.len()` (a token from a
    /// longer trajectory applied to a shorter one is a programmer bug).
    #[inline]
    pub fn revert(&self, trajectory: &mut Vec<u8>, token: ProbeToken) {
        debug_assert!(
            token.pre_len() <= trajectory.len(),
            "ProbeToken pre_len {} > trajectory len {} — wrong token or already reverted",
            token.pre_len(),
            trajectory.len()
        );
        // truncate is O(1) — it just adjusts the len, no per-element drop
        // for u8 (Copy, no Drop impl). The dropped bytes' KV entries are
        // the caller's engine to reclaim.
        trajectory.truncate(token.pre_len());
    }

    /// The byte range the probe occupied, for audit / KV-cache-reclaim
    /// bookkeeping. Returns `[pre_len, pre_len + prompt_len]`.
    ///
    /// Pure function of the token + the prompt length; no allocation.
    #[inline]
    #[must_use]
    pub const fn probe_range(token: ProbeToken, prompt_len: usize) -> Range<usize> {
        token.pre_len()..(token.pre_len() + prompt_len)
    }
}

