use super::super::rubric::{
    PredicateReason, PredicateResult, Rubric, RubricScratch, RubricVerdict,
};

/// The output-convergence threshold, mirroring
/// `riir-neuron-db::phase_gate::FREEZE_FLATNESS_THRESHOLD`. A shard's
/// `style_weights` are "converged" (single dominant mode) when
/// `spectral_flatness < SHARD_FREEZE_FLATNESS_THRESHOLD`.
///
/// **This constant MUST stay in sync with the riir-neuron-db value.** The G7
/// isomorphism breaks if the two thresholds diverge.
pub const SHARD_FREEZE_FLATNESS_THRESHOLD: f32 = 0.3;

/// Caller-supplied scalar features for the [`ShardFreezeRubric`].
///
/// These mirror the inputs to
/// `riir-neuron-db::ConsolidationPipeline::can_freeze`:
/// - `n_wake_events` — wake-event count (raw or compressed post-sleep)
/// - `intrinsic_dim` — participation ratio / numerical rank of `style_weights`
/// - `spectral_flatness` — spectral flatness of `style_weights`
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct ShardFreezeFeatures {
    /// P0 source — number of wake events feeding consolidation.
    pub n_wake_events: usize,
    /// P0 source — intrinsic dimension `d` of `style_weights` (Wang et al.
    /// Thm 4: subspace recovery needs `n >= d` samples).
    pub intrinsic_dim: usize,
    /// P1 source — spectral flatness of `style_weights`. Lower = more
    /// converged (single dominant mode).
    pub spectral_flatness: f32,
}

impl ShardFreezeFeatures {
    /// Construct a feature triple.
    #[inline]
    #[must_use]
    pub const fn new(n_wake_events: usize, intrinsic_dim: usize, spectral_flatness: f32) -> Self {
        Self {
            n_wake_events,
            intrinsic_dim,
            spectral_flatness,
        }
    }

impl ShardFreezeRubric {
    /// Construct with paper-default config (flatness threshold 0.3).
    #[inline]
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    /// Construct with custom config.
    #[inline]
    #[must_use]
    pub const fn with_config(config: ShardFreezeRubricConfig) -> Self {
        Self { config }
    }

    /// Evaluate the rubric against caller-supplied features, producing the
    /// 2-predicate verdict (P0, P1).
    #[inline]
    #[must_use]
    pub fn evaluate_features(&self, f: &ShardFreezeFeatures) -> RubricVerdict<2> {
        // P0: input-sufficient. Yes iff n_wake_events >= intrinsic_dim.
        // This mirrors subspace_phase_gate::phase_transition_gate(n, d) and
        // can_freeze's input_sufficient field.
        let p0 = if f.n_wake_events >= f.intrinsic_dim {
            PredicateResult::Yes {
                quote_start: f.n_wake_events as u32,
                quote_len: 1,
            }
        } else {
            PredicateResult::No {
                reason: PredicateReason::Custom(20), // P0: input insufficient
            }
        };
        // P1: output-converged. Yes iff spectral_flatness < threshold.
        // This mirrors can_freeze's output_converged field.
        // NaN-safe: NaN flatness → No (don't freeze on unknown data).
        let p1 = if !f.spectral_flatness.is_nan()
            && f.spectral_flatness < self.config.flatness_threshold
        {
            PredicateResult::Yes {
                quote_start: 0,
                quote_len: 1,
            }
        } else {
            PredicateResult::No {
                reason: PredicateReason::Custom(21), // P1: not converged
            }
        };
        RubricVerdict::new([p0, p1])
    }

    /// Compute the `FreezeGateReport`-equivalent fields from a verdict, for
    /// audit-trail parity with riir-neuron-db. This is the bridge that makes
    /// the CUCG audit record carry the same information as
    /// `FreezeGateReport`.
    #[inline]
    #[must_use]
    pub fn freeze_report_fields(
        &self,
        f: &ShardFreezeFeatures,
        verdict: &RubricVerdict<2>,
    ) -> FreezeReportFields {
        FreezeReportFields {
            n_wake_events: f.n_wake_events,
            intrinsic_dim: f.intrinsic_dim,
            input_sufficient: verdict.is_yes(0),
            output_flatness: f.spectral_flatness,
            output_converged: verdict.is_yes(1),
            can_freeze: verdict.is_yes(0) && verdict.is_yes(1),
        }
    }
}

impl PredictiveOutput {
    /// Samples-only output.
    #[inline]
    pub fn from_samples(samples: Vec<f32>) -> Self {
        Self {
            samples: Some(samples),
            interval: None,
        }
    }

    /// Interval-only output.
    #[inline]
    pub fn from_interval(interval: PredictiveInterval) -> Self {
        Self {
            samples: None,
            interval: Some(interval),
        }
    }

    /// Both samples and an interval.
    #[inline]
    pub fn from_both(samples: Vec<f32>, interval: PredictiveInterval) -> Self {
        Self {
            samples: Some(samples),
            interval: Some(interval),
        }
    }

    /// An empty output — the primitive produced no prediction for this step.
    /// The harness will count this as unscorable.
    #[inline]
    pub fn empty() -> Self {
        Self {
            samples: None,
            interval: None,
        }
    }

    /// Convert to an interval. If the primitive provided an interval, use it
    /// directly. Otherwise, convert samples → interval via empirical quantile.
    /// Returns `None` if the primitive produced neither.
    pub fn into_interval(&self, alpha: f32) -> Option<PredictiveInterval> {
        if let Some(iv) = self.interval {
            return Some(iv);
        }
        if let Some(samples) = &self.samples {
            if samples.is_empty() {
                return None;
            }
            return Some(empirical_quantile_interval(samples, alpha));
        }
        None
    }
}

impl FloorAdapter {
    /// Construct the canonical floor at miscoverage level `alpha`
    /// (e.g. `0.05` for a 95% interval).
    #[inline]
    pub fn new(alpha: f32) -> Self {
        debug_assert!((0.0..=0.5).contains(&alpha), "alpha must be in [0, 0.5]");
        let forecaster = seasonal_naive_floor(FLOOR_CAPACITY);
        let calibrator = ConformalIntervalCalibrator::new(
            forecaster,
            1,       // n_channels
            1,       // max_h
            FLOOR_M, // m=1 (canonical floor)
            FLOOR_CAPACITY,
            0.0, // exp_lambda (no recency decay)
            DecayUnit::Step,
            ResidualMode::HStep,
            false, // orientation
        );
        Self { calibrator, alpha }
    }
}

impl UqPrimitiveUnderTest for FloorAdapter {
    #[inline]
    fn name(&self) -> &str {
        "conformal-naive floor (SeasonalNaive m=1)"
    }

    #[inline]
    fn predict_next(&mut self) -> PredictiveOutput {
        let mut iv = PredictiveInterval::new(0.0, 0.0, 0.0, self.alpha);
        // ch=0 (single channel), h=1 (next step).
        self.calibrator.interval_into(0, 1, self.alpha, &mut iv);
        PredictiveOutput::from_interval(iv)
    }

    #[inline]
    fn observe(&mut self, y: f32) {
        // Lifecycle: forecast → update residual → push to history → step tick.
        let mut fc = 0.0_f32;
        self.calibrator.forecaster.forecast_into(&[], 1, &mut fc);
        self.calibrator.update_residual(y, fc, 0, 1);
        self.calibrator.forecaster.observe(y);
        self.calibrator.step();
    }
}

impl FloorComparisonReport {
    /// `true` iff the verdict is [`OverallVerdict::BeatsFloor`].
    #[inline]
    pub fn primitive_wins(&self) -> bool {
        matches!(self.overall, OverallVerdict::BeatsFloor)
    }

    /// `true` iff the verdict is [`OverallVerdict::NotApplicable`].
    #[inline]
    pub fn is_not_applicable(&self) -> bool {
        matches!(self.overall, OverallVerdict::NotApplicable { .. })
    }

    /// Print a human-readable summary table. For benchmark logs / examples.
    pub fn pretty_print(&self) {
        let nominal = 1.0 - self.alpha;
        println!("=== Floor Comparison: {} ===", self.primitive_name);
        println!(
            "Corpus: {} (n_scored={}, n_unscorable={}, α={:.2})",
            self.corpus_name, self.n_scored, self.n_unscorable, self.alpha
        );
        println!();
        println!("Metric             | Primitive  | Floor      | Ratio (prim/floor) | Verdict");
        println!("-------------------|------------|------------|--------------------|---------");
        let crps_v = if self.crps_ratio < 1.0 - BEAT_THRESHOLD {
            "WIN"
        } else if self.crps_ratio > 1.0 + BEAT_THRESHOLD {
            "LOSE"
        } else {
            "tie"
        };
        let winkler_v = if self.winkler_ratio < 1.0 - BEAT_THRESHOLD {
            "WIN"
        } else if self.winkler_ratio > 1.0 + BEAT_THRESHOLD {
            "LOSE"
        } else {
            "tie"
        };
        let cov_v = if self.primitive_cov_err < self.floor_cov_err - COVERAGE_TOL {
            "WIN"
        } else if self.primitive_cov_err > self.floor_cov_err + COVERAGE_TOL {
            "LOSE"
        } else {
            "tie"
        };
        println!(
            "Mean CRPS          | {:>10.4} | {:>10.4} | {:>18.4} | {}",
            self.primitive.mean_crps_interval,
            self.floor.mean_crps_interval,
            self.crps_ratio,
            crps_v
        );
        println!(
            "Mean Winkler       | {:>10.4} | {:>10.4} | {:>18.4} | {}",
            self.primitive.mean_winkler, self.floor.mean_winkler, self.winkler_ratio, winkler_v
        );
        println!(
            "Coverage (nom={:.2}) | {:>10.4} | {:>10.4} | {:>18} | {}",
            nominal,
            self.primitive.coverage,
            self.floor.coverage,
            format!(
                "err {:.4} vs {:.4}",
                self.primitive_cov_err, self.floor_cov_err
            ),
            cov_v
        );
        println!();
        let verdict_str = match &self.overall {
            OverallVerdict::BeatsFloor => "✅ BEATS FLOOR — primitive adds UQ value".to_string(),
            OverallVerdict::TiesFloor => {
                "🟡 TIES FLOOR — no UQ gain, but may be valuable for other reasons".to_string()
            }
            OverallVerdict::LosesToFloor => {
                "❌ LOSES TO FLOOR — primitive does not add UQ value".to_string()
            }
            OverallVerdict::Mixed => {
                "🟠 MIXED — better on some metrics, worse on others (judgment call)".to_string()
            }
            OverallVerdict::NotApplicable { reason } => format!("⚪ N/A — {reason}"),
        };
        println!("Overall: {verdict_str}");
    }
}

impl TrajectoryCorpus {
    /// Stationary seasonal: `y_t = sin(2πt/m) + N(0, σ)`. The canonical G1
    /// fixture from Plan 340. Default warmup = 4·m.
    pub fn stationary_seasonal(m: usize, sigma: f32, n: usize, seed: u64) -> Self {
        let mut rng = SplitMix64::new(seed);
        let mut values = Vec::with_capacity(n);
        for t in 0..n {
            let phase = 2.0 * core::f32::consts::PI * (t as f32) / (m as f32);
            let noise = rng.gaussian(sigma);
            values.push(phase.sin() + noise);
        }
        Self {
            name: format!("stationary_seasonal_m{m}_sigma{sigma}_n{n}"),
            values,
            recommended_warmup: (4 * m).min(n / 4),
        }
    }

    /// Pure white noise: `y_t ~ N(0, σ)`. The degenerate case where the floor
    /// (forecast = last observation) is worst-case — the optimal forecast is
    /// the mean (0), not the last value. Useful for stress-testing primitives
    /// that should beat the floor by learning the mean. Default warmup = 64.
    pub fn white_noise(sigma: f32, n: usize, seed: u64) -> Self {
        let mut rng = SplitMix64::new(seed);
        let mut values = Vec::with_capacity(n);
        for _ in 0..n {
            values.push(rng.gaussian(sigma));
        }
        Self {
            name: format!("white_noise_sigma{sigma}_n{n}"),
            values,
            recommended_warmup: 64.min(n / 4),
        }
    }

    /// Construct a corpus from a precomputed trajectory slice (for Lorenz-63,
    /// real data, etc.).
    pub fn from_slice(name: impl Into<String>, values: &[f32], warmup: usize) -> Self {
        Self {
            name: name.into(),
            values: values.to_vec(),
            recommended_warmup: warmup,
        }
    }
}

impl SplitMix64 {
    #[inline]
    fn new(seed: u64) -> Self {
        Self { state: seed }
    }

    #[inline]
    fn next_u64(&mut self) -> u64 {
        self.state = self.state.wrapping_add(0x9E37_79B9_7F4A_7C15);
        let mut z = self.state;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        z ^ (z >> 31)
    }

    /// Approximate Gaussian via central-limit sum of 12 uniforms.
    /// Matches `examples/conformal_airpassengers.rs`.
    #[inline]
    fn gaussian(&mut self, sigma: f32) -> f32 {
        let mut sum = 0.0_f32;
        for _ in 0..12 {
            sum += (self.next_u64() >> 40) as f32 * (1.0_f32 / (1u64 << 24) as f32);
        }
        (sum - 6.0) * sigma
    }
}

use crate::conformal::PredictiveInterval;

/// Compute the interval-CRPS for a single `(interval, actual)` pair.
///
/// Uses the uniform-on-interval closed form. Lower is better.
#[inline]
pub fn crps_interval(interval: &PredictiveInterval, actual: f32) -> f32 {
    let lower = interval.lower;
    let upper = interval.upper;
    let width = upper - lower;
    if actual < lower {
        width + 2.0 * (lower - actual)
    } else if actual > upper {
        width + 2.0 * (actual - upper)
    } else {
        // Inside the interval — CRPS reduces to the width (the "sharpness").
        width
    }
}

