        }
    }

    /// `true` iff `actual` is within `[lower, upper]` (inclusive).
    #[inline]
    pub fn contains(&self, actual: f32) -> bool {
        actual >= self.lower && actual <= self.upper
    }

    /// Interval half-width `(upper − lower) / 2`.
