impl FastCdcChunker {
    /// Construct with FastCDC paper defaults (see module-level "Defaults").
    #[must_use]
    pub fn new() -> Self {
        Self::with_config(ChunkerConfig::default())
    }

    /// Construct with a custom [`ChunkerConfig`].
    ///
    /// # Panics
    ///
    /// Panics if `min_size == 0`, `max_size <= min_size`, `normal_level >= 64`,
    /// or `max_level >= normal_level` (the large-phase mask must be looser).
    #[must_use]
    pub fn with_config(config: ChunkerConfig) -> Self {
        assert!(config.min_size > 0, "FastCdcChunker: min_size must be > 0");
        assert!(
            config.max_size > config.min_size,
            "FastCdcChunker: max_size must be > min_size"
        );
        assert!(
            config.normal_level < 64,
            "FastCdcChunker: normal_level must be < 64"
        );
        assert!(
            config.max_level < config.normal_level,
            "FastCdcChunker: max_level must be < normal_level (looser phase needs fewer bits)"
        );
        Self {
            min_size: config.min_size,
            max_size: config.max_size,
            normal_mask: (1u64 << config.normal_level).wrapping_sub(1),
            min_mask: (1u64 << config.min_level).wrapping_sub(1),
            max_mask: (1u64 << config.max_level).wrapping_sub(1),
        }
    }

    /// Find the next cut point at or after `start`.
    ///
    /// Returns the exclusive end offset of the next chunk, in
    /// `(start, bytes.len()]`. Algorithm:
    /// 1. If `≤ MIN` bytes remain, return the tail as one chunk.
    /// 2. Phase 0 (skip): `[start, start+MIN)` — prime the rolling hash, no cuts.
    /// 3. Phase 1 (normal): `[start+MIN, start+MAX/2)` — check `normal_mask`.
    /// 4. Phase 2 (large): `[start+MAX/2, start+MAX)` — check `max_mask` (looser).
    /// 5. No cut found: return `start+MAX` (force-cut).
    #[inline]
    fn find_cut_point(&self, bytes: &[u8], start: usize) -> usize {
        let bytes_remaining = bytes.len() - start;
        // Short tail — emit as one final chunk (paper: "if n <= MIN, return n").
        if bytes_remaining <= self.min_size {
            return bytes.len();
        }

        let max_end = (start + self.max_size).min(bytes.len());
        let mid_end = (start + self.max_size / 2).min(max_end);
        let skip_end = (start + self.min_size).min(max_end);

        let mut fp: u64 = 0;
        let mut i = start;

        // Safety: all loop bounds below are clamped to `max_end`, which is
        // `≤ bytes.len()` by construction. `bytes[i]` for `i ∈ [start, max_end)`
        // is therefore always in-bounds, and `GEAR_TABLE` is indexed by `u8`
        // (0..256). The `get_unchecked` calls elide the per-byte bounds check
        // in this hot byte-scanning loop.
        // Phase 0: prime fp, no cuts allowed.
        while i < skip_end {
            fp = (fp << 1) ^ GEAR_TABLE[*unsafe { bytes.get_unchecked(i) } as usize];
            i += 1;
        }
        // Phase 1: normal mask (stricter → expected chunk ≈ 2^normal_level).
        while i < mid_end {
            fp = (fp << 1) ^ GEAR_TABLE[*unsafe { bytes.get_unchecked(i) } as usize];
            if (fp & self.normal_mask) == 0 {
                return i + 1;
            }
            i += 1;
        }
        // Phase 2: looser mask (force a cut before MAX).
        while i < max_end {
            fp = (fp << 1) ^ GEAR_TABLE[*unsafe { bytes.get_unchecked(i) } as usize];
            if (fp & self.max_mask) == 0 {
                return i + 1;
            }
            i += 1;
        }
        max_end
    }

    /// Chunk into owned `Vec<u8>` — convenience for callers that need owned
    /// bytes (e.g. write paths where borrowed slices can't outlive the input).
    /// The `InMemoryChunkedStore::put` path already works correctly via the
    /// borrowed `chunk()` interface; this method is a convenience, not a
    /// requirement.
    #[must_use]
    pub fn chunk_into_owned(&self, bytes: &[u8]) -> Vec<Vec<u8>> {
        let avg = (self.min_size + self.max_size) / 2;
        let cap = bytes.len() / avg.max(1) + 1;
        let mut out: Vec<Vec<u8>> = Vec::with_capacity(cap);
        let mut offset = 0usize;
        while offset < bytes.len() {
            let end = self.find_cut_point(bytes, offset);
            out.push(bytes[offset..end].to_vec());
            offset = end;
        }
        out
    }
}

impl ChunkingStrategy for FastCdcChunker {
    fn chunk<'a>(&self, bytes: &'a [u8]) -> Vec<&'a [u8]> {
        if bytes.is_empty() {
            return Vec::new();
        }
        // Pre-size based on estimated chunk count (avg of MIN and MAX).
        let avg = (self.min_size + self.max_size) / 2;
        let cap = bytes.len() / avg.max(1) + 1;
        let mut out: Vec<&'a [u8]> = Vec::with_capacity(cap);
        let mut offset = 0usize;
        while offset < bytes.len() {
            let end = self.find_cut_point(bytes, offset);
            out.push(&bytes[offset..end]);
            offset = end;
        }
        out
    }
}

impl FsChunkFetcher {
    /// Construct a fetcher rooted at `root`. The directory is created lazily
    /// on first `put` (not eagerly — allows constructing a read-only fetcher
    /// against a store populated by another process).
    #[must_use]
    pub fn new(root: impl Into<PathBuf>) -> Self {
        Self { root: root.into() }
    }

    /// Compute the sharded on-disk path for a chunk hash.
    ///
    /// Per Plan 272 T3.2: `<root>/<hash[0..2]>/<hash[2..4]>/<hash>.chunk` where
    /// `hash[0..2]` and `hash[2..4]` are 2-byte slices (hex-encoded to 4 chars
    /// each) and `<hash>` is the full 32-byte hash (hex-encoded to 64 chars).
    ///
    /// Sharding: 2 bytes per level → 65 536 dirs per level → 65 536² ≈ 4 B leaf
    /// capacity. A 1 M-chunk store averages ~15 entries per leaf dir.
    ///
    /// Exposed for tests (T3.5 sharded-path assertion) and for callers that
    /// need to pre-create shard dirs in bulk.
    #[must_use]
    pub fn sharded_path(&self, chunk_hash: &[u8; 32]) -> PathBuf {
        let hex = hex_encode(chunk_hash);
        // hash[0..2] → hex[0..4], hash[2..4] → hex[4..8], filename = full hex.
        let shard1 = &hex[0..4];
        let shard2 = &hex[4..8];
        self.root
            .join(shard1)
            .join(shard2)
            .join(format!("{hex}.chunk"))
    }

    /// Write a chunk to disk at its sharded path. Creates parent dirs as
    /// needed. Overwrites any existing file (content-addressed — same hash
    /// implies same bytes).
    ///
    /// Errors propagate as `std::io::Result`; the caller decides retry policy.
    pub fn put(&self, chunk_hash: &[u8; 32], bytes: &[u8]) -> std::io::Result<()> {
        let path = self.sharded_path(chunk_hash);
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent)?;
        }
        // Write to a temp file in the same dir, then rename — atomic on the
        // same filesystem, avoids partial reads if a `fetch` races a `put`.
        let tmp = path.with_extension("chunk.tmp");
        std::fs::write(&tmp, bytes)?;
        std::fs::rename(&tmp, &path)?;
        Ok(())
    }

    /// Read a chunk from disk. Returns `None` if the file does not exist
    /// (honest-miss — caller may try a fallback). Other IO errors propagate.
    fn read(&self, chunk_hash: &[u8; 32]) -> std::io::Result<Option<Vec<u8>>> {
        let path = self.sharded_path(chunk_hash);
        match std::fs::read(&path) {
            Ok(bytes) => Ok(Some(bytes)),
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(None),
            Err(e) => Err(e),
        }
    }
}

impl<L, F> TieredChunkFetcher<L, F>
where
    L: ChunkFetcher,
    F: ChunkFetcher,
{
    /// Construct a tiered fetcher.
    #[must_use]
    pub fn new(local: L, fallback: F) -> Self {
        Self { local, fallback }
    }

use super::r#trait::ChunkedContentStore;

// ────────────────────────────────────────────────────────────────────────────
// G1 — Dedup ratio ≥ 5.0
// ────────────────────────────────────────────────────────────────────────────

/// G1: 50 blobs × 10 chunks each (FixedSizeChunker, 64 KiB), where each blob
/// after the first shares 9 chunks with blob 0 and has 1 unique chunk.
///
/// Expected dedup ratio = N×C / (C + N - 1) = 50×10 / (10 + 49) = 500/59 ≈ 8.47.
/// Target: ≥ 5.0.
///
/// Uses FixedSizeChunker (default, 64 KiB) rather than FastCdcChunker for
/// deterministic chunk boundaries — the GOAT gate measures the *store's* dedup
/// capability, not the chunker's boundary stability (that's G2).
#[test]
fn g1_dedup_ratio_meets_target() {
    const N_BLOBS: usize = 50;
    const N_CHUNKS: usize = 10;
    const CHUNK_SIZE: usize = 64 * 1024; // 64 KiB — matches FixedSizeChunker default

    // Blob 0: N_CHUNKS distinct 64 KiB blocks, each filled with a distinct byte.
    let blob0: Vec<u8> = (0..N_CHUNKS)
        .flat_map(|i| std::iter::repeat_n(i as u8, CHUNK_SIZE))
        .collect();
    assert_eq!(blob0.len(), N_CHUNKS * CHUNK_SIZE);

    let store = InMemoryChunkedStore::new();

    // Put blob 0.
    let _id0 = store.put(&blob0);

    // For each subsequent blob: copy blob 0, replace the last 64 KiB chunk
    // with a unique fill byte. This guarantees 9 shared chunks + 1 new.
    for n in 1..N_BLOBS {
        let mut blob = blob0.clone();
        // Overwrite the last CHUNK_SIZE bytes with a unique fill.
        let fill = (N_CHUNKS + n) as u8; // distinct from 0..N_CHUNKS
        let start = (N_CHUNKS - 1) * CHUNK_SIZE;
        blob[start..start + CHUNK_SIZE].fill(fill);
        let _id = store.put(&blob);
    }

    let stats = store.stats();
    let expected_ratio = (N_BLOBS * N_CHUNKS) as f32 / (N_CHUNKS + N_BLOBS - 1) as f32;
    assert!(
        stats.dedup_ratio >= 5.0,
        "G1 FAIL: dedup ratio {} < 5.0 (expected ~{expected_ratio:.2})",
        stats.dedup_ratio
    );
    // Sanity: the ratio should be close to the theoretical value.
    assert!(
        (stats.dedup_ratio - expected_ratio).abs() < 1.0,
        "G1 sanity: ratio {} far from expected {}",
        stats.dedup_ratio,
        expected_ratio
    );
}

impl InMemoryChunkedStore {
    /// Construct with the default chunker ([`FixedSizeChunker`], 64 KiB).
    #[must_use]
    pub fn new() -> Self {
        Self::with_chunker(FixedSizeChunker::default())
    }

    /// Construct with a caller-supplied chunker. The chunker must be
    /// `'static` because `put` may be called from any thread. (`Send + Sync`
    /// are already implied by the `ChunkingStrategy` supertrait — clippy
    /// `implied_bounds_in_impls`.)
    #[must_use]
    pub fn with_chunker(chunker: impl ChunkingStrategy + 'static) -> Self {
        Self {
            chunks: HashMap::new(),
            blobs: HashMap::new(),
            chunker: Box::new(chunker),
            n_chunks_stored: AtomicU64::new(0),
            n_blobs_indexed: AtomicU64::new(0),
            total_bytes_stored: AtomicU64::new(0),
            total_bytes_logical: AtomicU64::new(0),
        }
    }

    /// Insert a chunk into the chunk map if not already present.
    /// Returns `true` if this was a new insertion (dedup miss), `false` if
    /// the chunk was already stored (dedup hit).
    ///
    /// Leaks the `Vec<u8>` into a `&'static [u8]` via `Box::leak`. The leaked
    /// allocation is reclaimed on [`Drop`].
    #[inline]
    fn insert_chunk_if_absent(&self, hash: [u8; 32], chunk: &[u8]) -> bool {
        let guard = self.chunks.pin();
        match guard.get(&hash) {
            // Dedup hit — already stored.
            Some(_) => false,
            // Dedup miss — leak and insert.
            None => {
                // Box<[u8]> → leak → &'static [u8]. The allocation is tracked
                // for reclamation in Drop by walking `chunks`.
                let boxed: Box<[u8]> = chunk.to_vec().into_boxed_slice();
                let leaked: &'static mut [u8] = Box::leak(boxed);
                let leaked_shared: &'static [u8] = leaked;
                // Note: there's a benign race here — another thread may insert
                // the same hash concurrently. In that case, both leaks are
                // valid; the loser's reference is overwritten in the map and
                // will be reclaimed when its inserting store Drops. For
                // content-addressed data this is sound (same hash → same bytes).
                guard.insert(hash, leaked_shared);
                true
            }
        }
    }

    /// Test-only: insert a raw chunk by its pre-computed hash, bypassing the
    /// chunker. Used by GOAT gate G5 (hot-path read benchmark) to populate the
    /// store with N distinct chunks without constructing N separate blobs.
    #[cfg(test)]
    pub(crate) fn insert_chunk_for_test(&self, hash: [u8; 32], chunk: &[u8]) {
        let is_new = self.insert_chunk_if_absent(hash, chunk);
        if is_new {
            self.n_chunks_stored.fetch_add(1, Ordering::Relaxed);
            self.total_bytes_stored
                .fetch_add(chunk.len() as u64, Ordering::Relaxed);
        }
    }
}

impl ChunkedContentStore for InMemoryChunkedStore {
    fn put(&self, bytes: &[u8]) -> BlobId {
        // 1. Chunk the input via the pluggable strategy. Borrowed slices.
        let borrowed_chunks: Vec<&[u8]> = self.chunker.chunk(bytes);

        // 2. Hash each chunk, dedup-insert into the chunks map, collect hashes.
        //    Pre-size to avoid reallocation (AGENTS.md).
        let mut chunk_hashes: Vec<[u8; 32]> = Vec::with_capacity(borrowed_chunks.len());
        for chunk in &borrowed_chunks {
            let hash: [u8; 32] = blake3::hash(chunk).into();
            let is_new = self.insert_chunk_if_absent(hash, chunk);
            if is_new {
                self.n_chunks_stored.fetch_add(1, Ordering::Relaxed);
                self.total_bytes_stored
                    .fetch_add(chunk.len() as u64, Ordering::Relaxed);
            }
            chunk_hashes.push(hash);
        }

        // 3. Compute the Merkle root = BlobId. Cache all levels for O(log n)
        //    proof generation (Plan 272 G3 fix — avoids O(n) tree rebuild per proof).
        let merkle_levels = build_merkle_levels(&chunk_hashes);
        let root = merkle_levels
            .last()
            .and_then(|lvl| lvl.first().copied())
            .unwrap_or_else(|| blake3::hash(b"").into());
        let blob_id = BlobId(root);

        // 4. Insert blob metadata (idempotent — same root → same metadata).
        //    `papaya`'s `insert` returns the old value if present; we drop it.
        let total_bytes = bytes.len() as u64;
        let metadata = BlobMetadata {
            n_chunks: u32::try_from(chunk_hashes.len()).unwrap_or(u32::MAX),
            chunk_hashes: chunk_hashes.into_boxed_slice(),
            merkle_levels,
            total_bytes,
        };
        let is_new_blob = {
            let guard = self.blobs.pin();
            // `insert` returns Some(old) if the key was present, None if fresh.
            // We only need the bool, not the reference, so we drop the borrow
            // immediately.
            guard.insert(root, metadata).is_none()
        };
        if is_new_blob {
            self.n_blobs_indexed.fetch_add(1, Ordering::Relaxed);
        }
        // Always bump logical bytes — even on idempotent re-put, the caller
        // handed us `bytes.len()` bytes; we're tracking total logical traffic,
        // not unique logical bytes. (For unique logical bytes, see `stats()`
        // which can be refined in Phase 4 if G1 needs it.)
        self.total_bytes_logical
            .fetch_add(total_bytes, Ordering::Relaxed);

        blob_id
    }

    fn get(&self, blob_id: &BlobId) -> Option<Vec<u8>> {
        let guard = self.blobs.pin();
        let metadata = guard.get(&blob_id.0)?;
        // Pre-allocate the output buffer to the exact logical size (AGENTS.md).
        let mut out = Vec::with_capacity(metadata.total_bytes as usize);
        let chunk_guard = self.chunks.pin();
        for chunk_hash in metadata.chunk_hashes.iter() {
            let chunk_bytes: &[u8] = chunk_guard.get(chunk_hash)?;
            out.extend_from_slice(chunk_bytes);
        }
        Some(out)
    }

    /// Hash-only verification — chunks and hashes `bytes` to compute the
    /// Merkle root, then compares to `blob_id`. Skips all storage side
    /// effects of [`Self::put`]: no papaya chunk-map inserts, no
    /// `BlobMetadata` allocation, no stats bumps.
    ///
    /// Produces the same result as `self.put(bytes) == *blob_id` but without
    /// the O(n) papaya operations and metadata allocation that `put` performs
    /// for dedup tracking. The BLAKE3 hashing (the dominant cost) is
    /// unavoidable — verification requires re-hashing the bytes.
    fn verify_blob(&self, blob_id: &BlobId, bytes: &[u8]) -> bool {
        let borrowed_chunks = self.chunker.chunk(bytes);
        let mut chunk_hashes: Vec<[u8; 32]> = Vec::with_capacity(borrowed_chunks.len());
        for chunk in &borrowed_chunks {
            chunk_hashes.push(blake3::hash(chunk).into());
        }
        let root = build_binary_merkle_root(&chunk_hashes);
        root == blob_id.0
    }

    // ZERO-ALLOC: no Vec/String/Box/format!/to_vec() in this body. Returns a
    // borrowed slice via papaya's `.copied()` on the Option<&'static [u8]> —
    // copies the *reference* (8 bytes), not the chunk bytes.
    fn get_chunk(&self, chunk_hash: &[u8; 32]) -> Option<&[u8]> {
        self.chunks.pin().get(chunk_hash).copied()
    }

    fn prove_chunk(&self, blob_id: &BlobId, leaf_index: usize) -> Option<MerkleProof> {
        let guard = self.blobs.pin();
        let metadata = guard.get(&blob_id.0)?;
        if leaf_index >= metadata.chunk_hashes.len() {
            return None;
        }
        // O(log n) sibling lookup from cached levels — ZERO BLAKE3 calls.
        // (Previous implementation called build_binary_merkle_proof which is
        //  O(n) — rebuilds the entire tree per proof. G3 fix.)
        let siblings = build_proof_from_levels(&metadata.merkle_levels, leaf_index);
        Some(MerkleProof {
            leaf_index,
            siblings,
            expected_root: blob_id.0,
        })
    }

    /// **Associated fn** (G4 light-client gate) — no `&self`. Delegates to the
    /// pure-BLAKE3 verifier.
    fn verify_proof(proof: &MerkleProof, leaf_hash: &[u8; 32]) -> bool {
        verify_binary_merkle_proof(
            leaf_hash,
            proof.leaf_index,
            &proof.siblings,
            &proof.expected_root,
        )
    }

    fn stats(&self) -> StoreStats {
        let total_bytes_stored = self.total_bytes_stored.load(Ordering::Relaxed);
        let total_bytes_logical = self.total_bytes_logical.load(Ordering::Relaxed);
        let mut s = StoreStats {
            n_chunks_stored: self.n_chunks_stored.load(Ordering::Relaxed),
            n_blobs_indexed: self.n_blobs_indexed.load(Ordering::Relaxed),
            total_bytes_stored,
            total_bytes_logical,
            dedup_ratio: 1.0,
        };
        s.compute_dedup_ratio();
        s
    }
}

impl Drop for InMemoryChunkedStore {
    fn drop(&mut self) {
        // Reclaim all leaked `Box<[u8]>` chunks. Walk the chunk map, reconstruct
        // each Box from its raw pointer + length, and let it drop.
        let guard = self.chunks.pin();
        for (_, leaked_slice) in guard.iter() {
            let len = leaked_slice.len();
            let ptr = leaked_slice.as_ptr() as *mut u8;
            // SAFETY: `leaked_slice` was produced by `Box::leak(Box<[u8]>)` in
            // `insert_chunk_if_absent`. The pointer is the start of a heap
            // allocation owned solely by this store (no aliasing — papaya's
            // map is the only reference holder after insert, and we're tearing
            // the store down). `len` matches the original Box's length.
            unsafe {
                let _ = Box::from_raw(std::ptr::slice_from_raw_parts_mut(ptr, len));
            }
        }
    }
}

use bytemuck::{Pod, Zeroable};

/// A blob's content-addressed identity = Merkle root over its chunk hashes.
///
/// 32 bytes (BLAKE3 output). Two blobs with byte-identical content always share
/// a `BlobId`. Two blobs that share *some* chunks (e.g. two sword variants with
/// a common texture) share chunk hashes but differ in `BlobId`.
///
/// `#[repr(transparent)]` so it can be `bytemuck::cast_ref` / reinterpreted as
/// `&[u8; 32]` with zero overhead, and so it round-trips through `transmute`
/// for FFI / sync wire formats.
#[repr(transparent)]
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Pod, Zeroable)]
pub struct BlobId(pub [u8; 32]);

impl BlobId {
    /// The zero BlobId — corresponds to the Merkle root of an empty leaf set,
    /// i.e. `blake3::hash(b"").into()`. Used as the canonical id of an
    /// empty blob and as the zero-padding leaf in
    /// [`crate::content_store::merkle::build_binary_merkle_root`].
    #[inline]
    #[must_use]
    pub fn zero() -> Self {
        // Cache the empty-hash at compile time? blake3 doesn't expose a const
        // fn, so compute once via a helper. For hot paths, callers should pass
        // `&BlobId` rather than reconstructing.
        Self(*blake3::hash(b"").as_bytes())
    }

impl StoreStats {
    /// Recompute `dedup_ratio` from `total_bytes_logical / total_bytes_stored`.
    ///
    /// Returns `1.0` when `total_bytes_stored == 0` (empty store: trivially no
    /// dedup, no division by zero).
    #[inline]
    pub fn compute_dedup_ratio(&mut self) {
        self.dedup_ratio = if self.total_bytes_stored == 0 {
            1.0
        } else {
            // u64 → f32 cast is exact for any realistic byte count (< 2^53);
            // the division is the only lossy step, which is acceptable for a
            // summary statistic. Use `as f64` for the division to retain
            // precision before f32 narrowing.
            (self.total_bytes_logical as f64 / self.total_bytes_stored as f64) as f32
        };
    }
}

impl ContrastiveScoreBuilder {
    /// New builder over a `vocab`-sized dictionary with smoothing `alpha > 0`.
    #[must_use]
    pub fn new(vocab: usize, alpha: f32) -> Self {
        assert!(alpha > 0.0, "alpha=0 makes unseen words log2(0/0) NaN");
        Self {
            vocab,
            alpha,
            counts_in: vec![0; vocab],
            counts_out: vec![0; vocab],
            n_in: 0,
            n_out: 0,
        }
    }

    /// One in-scope document's tokens.
    pub fn observe_in(&mut self, tokens: &[u32]) {
        for &w in tokens {
            debug_assert!((w as usize) < self.vocab);
            self.counts_in[w as usize] = self.counts_in[w as usize].saturating_add(1);
            self.n_in = self.n_in.saturating_add(1);
        }
    }

    /// One out-scope document's tokens.
    pub fn observe_out(&mut self, tokens: &[u32]) {
        for &w in tokens {
            debug_assert!((w as usize) < self.vocab);
            self.counts_out[w as usize] = self.counts_out[w as usize].saturating_add(1);
            self.n_out = self.n_out.saturating_add(1);
        }
    }

    /// Smoothed contrastive log2-odds for one word:
    /// `log2 P_B(w) − log2 P_I(w)` (positive ⇒ B-characteristic).
    #[must_use]
    pub fn score(&self, w: u32) -> f32 {
        let v = self.vocab as f32;
        let p_out = (self.counts_out[w as usize] as f32 + self.alpha)
            / (self.n_out as f32 + self.alpha * v);
        let p_in = (self.counts_in[w as usize] as f32 + self.alpha)
            / (self.n_in as f32 + self.alpha * v);
        p_out.log2() - p_in.log2()
    }

    /// Freeze into the immutable read table (computes the full score vector
    /// once — the `log_ratio_vec` the document scorer consumes).
    #[must_use]
    pub fn finish(self) -> ContrastiveScoreTable {
        let scores = (0..self.vocab as u32).map(|w| self.score(w)).collect::<Vec<_>>();
        let frozen = self.freeze_bytes();
        let commitment = *blake3::hash(&frozen).as_bytes();
        ContrastiveScoreTable {
            scores,
            alpha: self.alpha,
            n_in: self.n_in,
            n_out: self.n_out,
            commitment,
        }
    }

    /// Canonical freeze layout (BLAKE3-committed): `[vocab u32][alpha f32
    /// bits u32][n_in u64][n_out u64][counts_in u32×V][counts_out u32×V]`,
    /// all little-endian.
    fn freeze_bytes(&self) -> Vec<u8> {
        let mut bytes = Vec::with_capacity(20 + self.vocab * 8);
        bytes.extend_from_slice(&(self.vocab as u32).to_le_bytes());
        bytes.extend_from_slice(&self.alpha.to_bits().to_le_bytes());
        bytes.extend_from_slice(&self.n_in.to_le_bytes());
        bytes.extend_from_slice(&self.n_out.to_le_bytes());
        for &c in &self.counts_in {
            bytes.extend_from_slice(&(c as u32).to_le_bytes());
        }
        for &c in &self.counts_out {
            bytes.extend_from_slice(&(c as u32).to_le_bytes());
        }
        bytes
    }
}

impl ContrastiveScoreTable {
    /// The smoothed contrastive log2-odds for one word (positive ⇒
    /// out-scope-characteristic).
    #[inline]
    #[must_use]
    pub fn score(&self, w: u32) -> f32 {
        self.scores[w as usize]
    }

    /// The full `log_ratio_vec` (sparse-GEMV operand for [`scope_score`]).
    #[inline]
    #[must_use]
    pub fn scores(&self) -> &[f32] {
        &self.scores
    }

    /// Corpus sizes at build time.
    #[must_use]
    pub fn corpus_sizes(&self) -> (u64, u64) {
        (self.n_in, self.n_out)
    }

    /// BLAKE3 commitment over the canonical builder serialization.
    #[must_use]
    pub fn commitment(&self) -> &[u8; 32] {
        &self.commitment
    }

    /// The smoothing α used at build time.
    #[must_use]
    pub fn alpha(&self) -> f32 {
        self.alpha
    }

    /// Freeze to canonical bytes (layout identical to the builder's
    /// `freeze_bytes`; the commitment is over exactly these bytes).
    #[must_use]
    pub fn freeze(&self) -> Vec<u8> {
        // The table stores derived scores, not counts; re-deriving counts
        // from scores is not possible. For freeze/thaw we serialize the
        // table itself: scores ARE the committed payload for the thaw side.
        let mut bytes = Vec::with_capacity(24 + self.scores.len() * 4);
        bytes.extend_from_slice(&(self.scores.len() as u32).to_le_bytes());
        bytes.extend_from_slice(&self.alpha.to_bits().to_le_bytes());
        bytes.extend_from_slice(&self.n_in.to_le_bytes());
        bytes.extend_from_slice(&self.n_out.to_le_bytes());
        bytes.extend_from_slice(&self.commitment);
        for &s in &self.scores {
            bytes.extend_from_slice(&s.to_bits().to_le_bytes());
        }
        bytes
    }

    /// Thaw from [`ContrastiveScoreTable::freeze`] bytes. Verifies the
    /// length layout; the inner commitment is the builder-side count
    /// commitment (carried, not recomputed — scores are not invertible to
    /// counts).
    ///
    /// # Errors
    /// `None` on truncated / malformed input.
    #[must_use]
    pub fn thaw(bytes: &[u8]) -> Option<Self> {
        if bytes.len() < 24 {
            return None;
        }
        let n = u32::from_le_bytes(bytes[0..4].try_into().ok()?) as usize;
        let alpha = f32::from_bits(u32::from_le_bytes(bytes[4..8].try_into().ok()?));
        let n_in = u64::from_le_bytes(bytes[8..16].try_into().ok()?);
        let n_out = u64::from_le_bytes(bytes[16..24].try_into().ok()?);
        let commitment: [u8; 32] = bytes[24..56].try_into().ok()?;
        if bytes.len() != 56 + n * 4 {
            return None;
        }
        let mut scores = Vec::with_capacity(n);
        for i in 0..n {
            let off = 56 + i * 4;
            scores.push(f32::from_bits(u32::from_le_bytes(
                bytes[off..off + 4].try_into().ok()?,
            )));
        }
        Some(Self {
            scores,
            alpha,
            n_in,
            n_out,
            commitment,
        })
    }
}

impl CrossResolutionBases {
    /// Construct a basis pair, computing the BLAKE3 commitment.
    ///
    /// Returns [`CrossResolutionError::RankDeficient`] if `k > min(d_src, d_dst)`.
    /// Returns [`CrossResolutionError::ShapeMismatch`] if the slice lengths
    /// don't match `(d_src * k, d_dst * k)`.
    ///
    /// **Does not** enforce column-orthonormality — caller responsibility
    /// (offline training produces orthonormal bases; check with
    /// [`Self::verify_orthonormal`] if provenance is uncertain).
    pub fn new(
        phi_src: Vec<f32>,
        psi_dst: Vec<f32>,
        d_src: usize,
        d_dst: usize,
        k: usize,
    ) -> Result<Self, CrossResolutionError> {
        if phi_src.len() != d_src * k || psi_dst.len() != d_dst * k {
            return Err(CrossResolutionError::ShapeMismatch);
        }
        if k > d_src.min(d_dst) {
            return Err(CrossResolutionError::RankDeficient);
        }
        let commitment = compute_commitment(&phi_src, &psi_dst, d_src, d_dst, k);
        // Build the transposed encode cache (Plan 417). phi_src is (d_src, k)
        // row-major; phi_src_t is (k, d_src) row-major so each basis vector
        // (column of phi_src) becomes a contiguous row. Cold path — runs once
        // per basis construction, never on the encode hot path.
        let phi_src_t = transpose_phi_src(&phi_src, d_src, k);
        Ok(Self {
            phi_src,
            psi_dst,
            d_src,
            d_dst,
            k,
            commitment,
            phi_src_t,
        })
    }

    /// Re-check that the stored commitment matches the current basis contents.
    /// Returns `false` if either matrix was mutated after construction.
    pub fn verify_commitment(&self) -> bool {
        compute_commitment(&self.phi_src, &self.psi_dst, self.d_src, self.d_dst, self.k)
            == self.commitment
    }

    /// Check `Φ_src^T Φ_src ≈ I_k` and `Ψ_dst^T Ψ_dst ≈ I_k` to within `tol`.
    /// Diagonals must be ≈ 1.0, off-diagonals ≈ 0.0.
    pub fn verify_orthonormal(&self, tol: f32) -> bool {
        orthonormal_check(&self.phi_src, self.d_src, self.k, tol)
            && orthonormal_check(&self.psi_dst, self.d_dst, self.k, tol)
    }
}

impl CrossResScratch {
    /// Allocate scratch for the given rank.
    pub fn new(k: usize) -> Self {
        Self {
            spectral: vec![0.0; k],
            spectral_dst: vec![0.0; k],
            cached_k: k,
        }
    }

    /// Resize buffers if `k` changed. No-op on the hot path.
    pub fn ensure_capacity(&mut self, k: usize) {
        if self.cached_k == k {
            return;
        }
        self.spectral.resize(k, 0.0);
        self.spectral_dst.resize(k, 0.0);
        self.cached_k = k;
    }
}

impl ClaimCard {
    /// Compute the overall verdict from internal and external validity.
    ///
    /// Logic:
    /// - IV = TransferAccepted + EV = TransferAccepted → TransferAccepted
    /// - IV = TransferAccepted + EV ≠ TransferAccepted → ProbeLocal
    /// - IV ≠ TransferAccepted → Rejected
    pub fn verdict(&self) -> ValidityVerdict {
        match self.internal_validity {
            Some(ValidityVerdict::TransferAccepted) => match self.external_validity {
                Some(ValidityVerdict::TransferAccepted) => ValidityVerdict::TransferAccepted,
                _ => ValidityVerdict::ProbeLocal,
            },
            _ => ValidityVerdict::Rejected,
        }
    }
}

use super::markov::MarkovChain;

/// Average NLL of sequence against Markov chain: -log p(x^n)/n.
///
/// Returns `f32::INFINITY` for empty sequences.
/// Uses natural log internally, matching information-theoretic convention.
pub fn average_nll(chain: &MarkovChain, sequence: &[usize]) -> f32 {
    if sequence.is_empty() {
        return f32::INFINITY;
    }
    let total: f32 = sequence
        .iter()
        .enumerate()
        .map(|(t, &state)| {
            let prob = if t == 0 {
                chain.stationary[state]
            } else {
                chain.transition[sequence[t - 1]][state]
            };
            if prob > 0.0 {
                -prob.ln()
            } else {
                f32::INFINITY
            }
        })
        .sum();
    total / sequence.len() as f32
}

impl CochainFreezeEnvelope {
    /// Freeze a [`CochainField`] into a self-contained envelope.
    ///
    /// Serializes `dim` + `rank` + `data` into a byte buffer and computes a
    /// BLAKE3 commitment over it. The envelope commitment is an independent
    /// integrity layer over the serialized form.
    pub fn freeze(cf: &CochainField) -> Self {
        let dim = cf.dim as u32;
        let mut payload = Vec::with_capacity(4 + 1 + cf.data.len() * 4);
        payload.extend_from_slice(&dim.to_le_bytes());
        payload.push(cf.rank);
        for &f in &cf.data {
            payload.extend_from_slice(&f.to_le_bytes());
        }
        let commitment = *blake3::hash(&payload).as_bytes();
        Self {
            commitment,
            payload,
        }
    }

    /// Verify that the envelope's commitment matches its payload.
    ///
    /// Returns `false` if the payload has been tampered with after freezing.
    #[inline]
    pub fn verify(&self) -> bool {
        *blake3::hash(&self.payload).as_bytes() == self.commitment
    }

    /// Thaw the envelope back into a [`CochainField`].
    ///
    /// Verifies the commitment first; returns `None` if verification fails
    /// (tampered envelope) or if the payload is malformed (truncated,
    /// dim=0 with data, NaN values).
    pub fn thaw(&self) -> Option<CochainField> {
        if !self.verify() {
            return None;
        }
        Self::deserialize(&self.payload)
    }

    /// The BLAKE3 commitment over the serialized payload.
    #[inline]
    pub fn commitment(&self) -> [u8; 32] {
        self.commitment
    }

    /// Serialized payload bytes (for external persistence / network transport).
    #[inline]
    pub fn payload(&self) -> &[u8] {
        &self.payload
    }

    /// Deserialize a payload into a [`CochainField`].
    ///
    /// Returns `None` on any malformation: truncated buffer, data length not
    /// divisible by 4, dim=0 with non-empty data, data length not divisible
    /// by dim, or NaN in the data.
    fn deserialize(payload: &[u8]) -> Option<CochainField> {
        // Header: dim (u32 LE, 4 bytes) + rank (u8, 1 byte) = 5 bytes minimum.
        if payload.len() < 5 {
            return None;
        }
        let dim = u32::from_le_bytes(payload[..4].try_into().ok()?) as usize;
        let rank = payload[4];
        let data_bytes = payload.len() - 5;
        // Data must be a whole number of f32s.
        if !data_bytes.is_multiple_of(4) {
            return None;
        }
        let n_floats = data_bytes / 4;
        // dim=0 with non-empty data is a malformation; non-zero dim requires
        // data length divisible by dim for a well-formed cochain.
        if dim == 0 {
            if n_floats != 0 {
                return None;
            }
        } else if !n_floats.is_multiple_of(dim) {
            return None;
        }
        let mut data = Vec::with_capacity(n_floats);
        for chunk in payload[5..].chunks_exact(4) {
            let f = f32::from_le_bytes(chunk.try_into().ok()?);
            if f.is_nan() {
                return None;
            }
            data.push(f);
        }
        Some(CochainField::from_vec(rank, dim, data))
    }
}

impl FeatureHasher {
    /// Create a new feature hasher with random projection.
    ///
    /// Uses Kaiming-like initialization scaled by sqrt(2/rank).
    ///
    /// The RNG sequence is consumed column-major (matching the historical
    /// katgpt-core bit-pattern) and then transposed to row-major storage
    /// so the hot path can use contiguous SIMD dot products.
    pub fn new(rank: usize, feature_dim: usize, seed: u64) -> Self {
        let mut rng = fastrand::Rng::with_seed(seed);
        let scale = (2.0 / rank as f32).sqrt();

        // Generate column-major: cm[j * rank + i] = rng_call(j * rank + i) = logical(i, j).
        // This matches the historical katgpt-core bit-pattern exactly.
        let cm: Vec<f32> = (0..(rank * feature_dim))
            .map(|_| rng.f32() * 2.0 * scale - scale)
            .collect();

        // Transpose to row-major: rm[i * feature_dim + j] = cm[j * rank + i] = logical(i, j).
        // Row-major storage lets `project_into` use contiguous SIMD dots.
        let mut projection = vec![0.0f32; rank * feature_dim];
        for i in 0..rank {
            for j in 0..feature_dim {
                projection[i * feature_dim + j] = cm[j * rank + i];
            }
        }

        Self {
            rank,
            feature_dim,
            projection,
            seed,
        }
    }

    /// Hash to L2-normalized key/query vector.
    /// `L2_norm(tanh(projection · features))` — same as paper Eq 4.
    pub fn hash_key(&self, features: &[f32]) -> Vec<f32> {
        let mut result = vec![0.0; self.rank];
        self.hash_key_into(features, &mut result);
        result
    }

    /// Hash key into pre-allocated buffer. Zero-alloc for hot path.
    /// `L2_norm(tanh(projection · features))` — same as paper Eq 4.
    ///
    /// Produces output bit-identical to [`Self::hash_key`] when called with
    /// the same `features` and an equally-sized `out` buffer.
    pub fn hash_key_into(&self, features: &[f32], out: &mut [f32]) {
        self.project_into(features, out);
        // tanh in-place (SIMD-vectorized Padé [2/2] — pure f32 arithmetic,
        // more deterministic across platforms than libm tanh which can differ
        // in the last ULP).
        crate::simd::simd_tanh_inplace(out);
        // L2 normalize in-place (prevents state explosion — verified from source).
        // SIMD-accelerated sum-of-squares for the norm denominator.
        let norm: f32 = crate::simd::simd_sum_sq(out, out.len()).sqrt().max(1e-8);
        for val in out.iter_mut() {
            *val /= norm;
        }
    }

    /// Hash to raw value vector (no normalization, same as paper).
    /// `projection · features`
    pub fn hash_value(&self, features: &[f32]) -> Vec<f32> {
        let mut result = vec![0.0; self.rank];
        self.hash_value_into(features, &mut result);
        result
    }

    /// Hash value into pre-allocated buffer. Zero-alloc for hot path.
    /// `projection · features` — no normalization, same as paper.
    ///
    /// Produces output bit-identical to [`Self::hash_value`].
    pub fn hash_value_into(&self, features: &[f32], out: &mut [f32]) {
        self.project_into(features, out);
    }

    /// Project into pre-allocated buffer. Zero-alloc for hot path.
    /// Matrix-vector multiply: projection · features
    ///
    /// Uses SIMD dot product for each row when feature_dim is large enough.
    /// Row-major storage means each row is contiguous — ideal for SIMD.
    #[inline]
    fn project_into(&self, features: &[f32], out: &mut [f32]) {
        assert_eq!(out.len(), self.rank, "output dimension must match rank");
        // Issue 669: a caller passing features.len() != feature_dim made
        // simd_dot_f32 read past the features slice (silent UB in release,
        // debug-precondition abort). The row length comes from the projection
        // layout, so only this guard catches the mismatch.
        assert_eq!(
            features.len(),
            self.feature_dim,
            "features dimension must match feature_dim"
        );
        let fd = self.feature_dim;
        if fd == 0 {
            out.fill(0.0);
            return;
        }
        // No `out.fill(0.0)` pre-pass: every slot is unconditionally overwritten
        // below, so zeroing first was a dead store over the whole buffer.
        // `chunks_exact` also drops the per-row `projection[off..off+fd]` bounds
        // check. Bit-identical output.
        for (slot, row) in out.iter_mut().zip(self.projection.chunks_exact(fd)) {
            *slot = crate::simd::simd_dot_f32(row, features, fd);
        }
    }

    /// Get the rank dimension.
    #[inline]
    pub fn rank(&self) -> usize {
        self.rank
    }

    /// Get the input feature dimension.
    #[inline]
    pub fn feature_dim(&self) -> usize {
        self.feature_dim
    }

    /// Get the seed used for initialization.
    #[inline]
    pub fn seed(&self) -> u64 {
        self.seed
    }
}

impl ContextFeatures {
    /// Feature vector dimension (always 8).
    pub const FEATURE_DIM: usize = 8;

    /// Convert to feature vector for hashing.
    pub fn to_vec(&self) -> Vec<f32> {
        vec![
            (self.domain & 0xFF) as f32 / 255.0, // Low byte of domain hash
            ((self.domain >> 8) & 0xFF) as f32 / 255.0,
            ((self.domain >> 16) & 0xFF) as f32 / 255.0,
            ((self.domain >> 24) & 0xFF) as f32 / 255.0,
            self.depth_normalized,
            self.token_entropy,
            self.path_length_normalized,
            self.parent_relevance,
        ]
    }

    /// Convert to feature vector into pre-allocated buffer. Zero-alloc for hot path.
    /// Buffer is cleared and resized if needed.
    pub fn to_vec_into(&self, buf: &mut Vec<f32>) {
        buf.clear();
        buf.extend_from_slice(&[
            (self.domain & 0xFF) as f32 / 255.0,
            ((self.domain >> 8) & 0xFF) as f32 / 255.0,
            ((self.domain >> 16) & 0xFF) as f32 / 255.0,
            ((self.domain >> 24) & 0xFF) as f32 / 255.0,
            self.depth_normalized,
            self.token_entropy,
            self.path_length_normalized,
            self.parent_relevance,
        ]);
    }

    /// Convert to fixed-size feature array. Zero-alloc, no Vec needed.
    /// Preferred for hot paths where the caller has stack space.
    pub fn to_array(&self) -> [f32; 8] {
        [
            (self.domain & 0xFF) as f32 / 255.0,
            ((self.domain >> 8) & 0xFF) as f32 / 255.0,
            ((self.domain >> 16) & 0xFF) as f32 / 255.0,
            ((self.domain >> 24) & 0xFF) as f32 / 255.0,
            self.depth_normalized,
            self.token_entropy,
            self.path_length_normalized,
            self.parent_relevance,
        ]
    }

    /// Extract from DDTree context during build.
    pub fn from_tree_context(depth: usize, _token_idx: usize, parent_tokens: &[usize]) -> Self {
        let max_depth = 32.0f32; // Typical DDTree max depth
        let max_path = 256.0f32; // Typical max path length

        Self {
            domain: 0, // Set by caller based on PromptRouter
            depth_normalized: (depth as f32 / max_depth).min(1.0),
            token_entropy: 0.0, // Would be filled from model marginals
            path_length_normalized: (parent_tokens.len() as f32 / max_path).min(1.0),
            parent_relevance: 1.0, // Default: no parent info
        }
    }
}

