impl SurjectiveMap {
    /// Number of raw tokens in the map (= vocab size of the source tokenizer).
    #[inline]
    pub fn vocab_size(&self) -> usize {
        self.raw_to_canonical.len()
    }

    /// Number of distinct canonical ids (= size of the compressed vocab V').
    ///
    /// O(V) scan — for diagnostics only, not on the hot path.
    pub fn canonical_vocab_size(&self) -> usize {
        let mut distinct = std::collections::HashSet::new();
        for &c in self.raw_to_canonical.iter() {
            distinct.insert(c);
        }
        distinct.len()
    }

    /// Compression ratio = `1 - canonical / raw` (paper Appendix C target: 0.23).
    pub fn compression_ratio(&self) -> f32 {
        let raw = self.vocab_size();
        if raw == 0 {
            return 0.0;
        }
        let canon = self.canonical_vocab_size();
        1.0 - (canon as f32 / raw as f32)
    }

    /// Serialize to postcard bytes with a BLAKE3 commitment prepended.
    ///
    /// Layout: `[32-byte BLAKE3 commitment] || [postcard-serialized Vec<u64>]`.
    /// The commitment is over the postcard bytes only (not self-inclusive).
    /// On load, `load_from_bytes` recomputes the BLAKE3 over the payload
    /// and compares — tampered maps are rejected.
    pub fn save_to_bytes(&self) -> Vec<u8> {
        // Extract the raw u64s — CanonicalId is #[repr(transparent)] over u64
        // so this is a zero-cost reinterpretation in spirit (we copy here
        // for serialization simplicity; the hot-path lookup uses the
        // Box<[CanonicalId]> directly without copy).
        let u64s: Vec<u64> = self.raw_to_canonical.iter().map(|c| c.0).collect();
        let payload = postcard::to_allocvec(&u64s).expect("postcard serialize");

        // BLAKE3 commitment over the payload.
        let mut hasher = blake3::Hasher::new();
        hasher.update(&payload);
        let commit = *hasher.finalize().as_bytes();

        let mut out = Vec::with_capacity(32 + payload.len());
        out.extend_from_slice(&commit);
        out.extend_from_slice(&payload);
        out
    }

    /// Deserialize from postcard bytes; verify the BLAKE3 commitment.
    ///
    /// Returns `Err` if the commitment does not match the payload (tampered
    /// or corrupted map) or if postcard deserialization fails.
    pub fn load_from_bytes(bytes: &[u8]) -> Result<Self, SurjectiveMapLoadError> {
        if bytes.len() < 32 {
            return Err(SurjectiveMapLoadError::TooShort);
        }
        let (stored_commit, payload) = bytes.split_at(32);

        // Recompute BLAKE3 over the payload.
        let mut hasher = blake3::Hasher::new();
        hasher.update(payload);
        let recomputed = *hasher.finalize().as_bytes();
        if recomputed.as_slice() != stored_commit {
            return Err(SurjectiveMapLoadError::CommitmentMismatch);
        }

        let u64s: Vec<u64> =
            postcard::from_bytes(payload).map_err(SurjectiveMapLoadError::Postcard)?;
        let raw_to_canonical: Box<[CanonicalId]> = u64s.into_iter().map(CanonicalId).collect();
        Ok(Self { raw_to_canonical })
    }
}

impl EntropyThresholdGate {
    /// Create with explicit threshold and slope.
    ///
    /// Validates `lambda > 0` — required for the hot-path math
    /// (`sigmoid(λ·(u−τ)) > 0.5 ⟺ u > τ` only holds when `λ > 0`).
    #[inline]
    pub fn new(tau: f32, lambda: f32) -> Self {
        debug_assert!(
            lambda > 0.0,
            "EntropyThresholdGate::new: lambda must be > 0 (got {lambda}), \
             else the hot-path boolean collapses incorrectly"
        );
        Self { tau, lambda }
    }

    /// Full sigmoid value `sigmoid(λ · (u − τ)) ∈ (0, 1)`.
    ///
    /// Opt-in soft-gating accessor — pays the `exp()` cost. Use this when
    /// you want to scale the memory contribution by the sigmoid value rather
    /// than hard-skip. For the boolean inject/skip decision, use
    /// [`TriggeredInjectionGate::should_inject`] instead — it collapses to a
    /// single compare and is ~10× faster.
    #[inline]
    pub fn sigmoid_value(&self, uncertainty: f32) -> f32 {
        sigmoid(self.lambda * (uncertainty - self.tau))
    }
}

use std::path::Path;

/// Save a `repr(C)` struct to disk as raw bytes.
///
/// Creates parent directories if needed. Overwrites existing files.
pub fn save_frozen<T>(path: &Path, data: &T) -> Result<(), String> {
    if let Some(parent) = path.parent()
        && !parent.as_os_str().is_empty()
    {
        std::fs::create_dir_all(parent)
            .map_err(|e| format!("Failed to create directory {parent:?}: {e}"))?;
    }
    let bytes = unsafe {
        std::slice::from_raw_parts(data as *const T as *const u8, std::mem::size_of::<T>())
    };
    std::fs::write(path, bytes).map_err(|e| format!("Failed to write {path:?}: {e}"))
}

impl FuncAttnScratch {
    /// Allocate scratch for the given dimensions.
    pub fn new(n: usize, d: usize, k: usize) -> Self {
        let nk = n.checked_mul(k).expect("n*k overflow");
        let kd = k.checked_mul(d).expect("k*d overflow");
        let dd = d.checked_mul(d).expect("d*d overflow");
        let kk = k.checked_mul(k).expect("k*k overflow");
        Self {
            phi: vec![0.0; nk],
            slice_token: vec![0.0; kd],
            q_slice: vec![0.0; kd],
            k_slice: vec![0.0; kd],
            v_slice: vec![0.0; kd],
            reg: vec![0.0; dd],
            z_op_t: vec![0.0; kd],
            c_op: vec![0.0; kk],
            out_slice: vec![0.0; kd],
            col_sum: vec![0.0; k],
            solve_y: vec![0.0; d],
            cached_n: n,
            cached_d: d,
            cached_k: k,
        }
    }

    /// Resize buffers if any dimension changed. No-op on the hot path.
    pub fn ensure_capacity(&mut self, n: usize, d: usize, k: usize) {
        if self.cached_n == n && self.cached_d == d && self.cached_k == k {
            return;
        }
        let nk = n * k;
        let kd = k * d;
        let dd = d * d;
        let kk = k * k;
        self.phi.resize(nk, 0.0);
        self.slice_token.resize(kd, 0.0);
        self.q_slice.resize(kd, 0.0);
        self.k_slice.resize(kd, 0.0);
        self.v_slice.resize(kd, 0.0);
        self.reg.resize(dd, 0.0);
        self.z_op_t.resize(kd, 0.0);
        self.c_op.resize(kk, 0.0);
        self.out_slice.resize(kd, 0.0);
        self.col_sum.resize(k, 0.0);
        self.solve_y.resize(d, 0.0);
        self.cached_n = n;
        self.cached_d = d;
        self.cached_k = k;
    }
}

