impl Sched {
    /// The effective third-order coefficient (physical jerk units) this
    /// schedule contributes for one channel, or `None` for the drag family
    /// (not a jerk rollout — it has its own closed form).
    #[inline]
    fn jerk_for(&self, vel_ch: f32, measured_jerk: f32) -> Option<f32> {
        match *self {
            Sched::ZeroJerk => Some(0.0),
            Sched::ConstJerk { j } => Some(j),
            Sched::Measured => Some(measured_jerk),
            Sched::ClampedCorrection { j_max, lambda } => {
                Some(j_max * (lambda * vel_ch.abs()).tanh())
            }
            Sched::GeometricDrag { .. } => None,
        }
    }
}

impl RegimeSnapshot {
    /// Build a snapshot from a kinematic state plus the caller-tracked
    /// previous velocity (for the impulse statistic), the running-|acc| EMA,
    /// and the extent channel (if any).
    #[allow(clippy::needless_range_loop)] // ch indexes parallel vel/acc/jerk arrays
    pub fn from_state<const D: usize>(
        state: &KinState<D>,
        prev_vel: &[f32; D],
        running_acc: f32,
        sigma: f32,
        sigma_rate: f32,
    ) -> Self {
        let mut speed2 = 0.0f32;
        let mut acc2 = 0.0f32;
        let mut jerk2 = 0.0f32;
        let mut dv2 = 0.0f32;
        let mut av_dot = 0.0f32;
        let mut ja_dot = 0.0f32;
        for ch in 0..D {
            speed2 += state.vel[ch] * state.vel[ch];
            acc2 += state.acc[ch] * state.acc[ch];
            jerk2 += state.jerk[ch] * state.jerk[ch];
            let dv = (state.vel[ch] - prev_vel[ch]) / state.dt;
            dv2 += dv * dv;
            av_dot += state.acc[ch] * state.vel[ch];
            ja_dot += state.jerk[ch] * state.acc[ch];
        }
        Self {
            dt: state.dt,
            speed: speed2.sqrt(),
            acc_mag: acc2.sqrt(),
            jerk_mag: jerk2.sqrt(),
            dv_dt: dv2.sqrt(),
            running_acc,
            acc_vel_dot: av_dot,
            jerk_acc_dot: ja_dot,
            sigma,
            sigma_rate,
        }
    }
}

