impl ManceTangentCache {
    /// Allocate a cache sized for dimension `d`, `k` neighbors, and `r`
    /// tangent basis components.
    pub fn with_capacity(d: usize, k: usize, r: usize) -> Self {
        Self {
            neighbor_indices: vec![0; k],
            tangent_basis: vec![0.0; d * r],
            singular_values: vec![0.0; r],
            valid: false,
            d,
            k,
            r,
            #[cfg(feature = "manifold_erasure")]
            cache_hits: 0,
            #[cfg(feature = "manifold_erasure")]
            cache_misses: 0,
        }
    }

    /// Check whether the cache is valid for the given neighbor indices.
    ///
    /// Returns `true` if the cache has been populated AND all k indices match.
    /// The k-NN function sorts indices by index after selection (since Plan 427),
    /// so the same neighbor set always produces the same ordering — a simple
    /// slice equality suffices.
    #[inline]
    fn is_valid_for(&self, indices: &[usize]) -> bool {
        if !self.valid {
            return false;
        }
        let k = indices.len().min(self.k);
        self.neighbor_indices[..k] == indices[..k]
    }

    /// Update the cache with fresh tangent data from scratch buffers.
    ///
    /// Copies neighbor indices, tangent basis, and singular values from the
    /// provided slices into the cache's internal buffers.
    #[inline]
    fn update(&mut self, indices: &[usize], basis: &[f32], sigma: &[f32]) {
        let k = indices.len().min(self.k);
        let d_r = basis.len().min(self.d * self.r);
        let r = sigma.len().min(self.r);
        self.neighbor_indices[..k].copy_from_slice(&indices[..k]);
        self.tangent_basis[..d_r].copy_from_slice(&basis[..d_r]);
        self.singular_values[..r].copy_from_slice(&sigma[..r]);
        self.valid = true;
    }

    /// Copy cached tangent data into scratch buffers (cache hit path).
    #[inline]
    fn copy_to(&self, basis: &mut [f32], sigma: &mut [f32]) {
        let d_r = basis.len().min(self.d * self.r);
        let r = sigma.len().min(self.r);
        basis[..d_r].copy_from_slice(&self.tangent_basis[..d_r]);
        sigma[..r].copy_from_slice(&self.singular_values[..r]);
    }

    /// Reset the cache to invalid state. Useful when the natural pool changes.
    #[inline]
    pub fn invalidate(&mut self) {
        self.valid = false;
    }
}

use crate::traits::{GameState, RandomRolloutPolicy, RolloutPolicy, StateHeuristic};

/// UCB1 exploration constant. sqrt(2) is standard; tuned lower for games
/// with high branching factor where exploitation matters more.
const UCB1_C: f32 = 1.414;

/// Maximum tree nodes before stopping. Prevents unbounded memory growth.
const MAX_TREE_SIZE: usize = 10_000;

/// Maximum number of unexpanded actions per node (ArrayVec capacity).
/// Must accommodate the highest branching factor across all game domains.
/// Bomber=6, Grid=5, Raid=~9, Go 9×9=82 (81 points + pass),
/// Go 13×13=170, Go 19×19=362. 362 covers standard Go board sizes.
///
/// Ported from riir-engine (Plan 008 Phase 2.6, 2026-06-28): switching
/// `children`/`unexpanded` from `Vec<usize>` to `ArrayVec<usize, MAX_UNEXPANDED>`
/// eliminates per-node heap allocation — a genuine hot-path win because the
/// tree allocates one node per MCTS iteration. Bit-identical values; only the
/// backing storage changes. Callers whose `available_actions()` can exceed
/// this const will hit the `assert!` in `new_root`/`new_child` — bump it if a
/// new game domain needs more headroom.
///
/// 2026-06-28: raised from 16 → 362 after `go_01_mcts` / `go_02_tournament`
/// panicked on a 9×9 board (82 actions). 362 covers 19×19 Go (standard
/// tournament size) with no margin needed since pass is the only +1.
const MAX_UNEXPANDED: usize = 362;

// ── Tree Node ──────────────────────────────────────────────────

/// A single node in the MCTS search tree.
///
/// Uses index-based parent/child links into a flat `Vec<MCTSNode>`
/// for cache-friendly traversal. Action indices refer to the parent
/// node's `available_actions()` list — the inline state tracker
/// maintains the correct action list at each level.
///
/// Fields ordered by size/alignment (u32 → usize → Vec → Option) to minimize padding.
pub(crate) struct MCTSNode {
    /// Accumulated reward from backpropagation.
    total_reward: f32,
    /// Number of visits through this node.
    visits: usize,
    /// Action index that led to this node (None for root).
    action_index: Option<usize>,
    /// Parent node index (None for root).
    parent: Option<usize>,
    /// Child node indices. Stack-allocated (no heap) — capacity MAX_UNEXPANDED.
    children: ArrayVec<usize, { MAX_UNEXPANDED }

impl MCTSNode {
    fn new_root(action_count: usize) -> Self {
        assert!(
            action_count <= MAX_UNEXPANDED,
            "MCTSNode::new_root: action_count ({action_count}) exceeds unexpanded capacity ({MAX_UNEXPANDED})"
        );
        Self {
            total_reward: 0.0,
            visits: 0,
            action_index: None,
            parent: None,
            children: ArrayVec::new(),
            unexpanded: (0..action_count).collect(),
        }
    }

    fn new_child(action_index: usize, parent: usize, action_count: usize) -> Self {
        assert!(
            action_count <= MAX_UNEXPANDED,
            "MCTSNode::new_child: action_count ({action_count}) exceeds unexpanded capacity ({MAX_UNEXPANDED})"
        );
        Self {
            total_reward: 0.0,
            visits: 0,
            action_index: Some(action_index),
            parent: Some(parent),
            children: ArrayVec::new(),
            unexpanded: (0..action_count).collect(),
        }
    }

    fn is_fully_expanded(&self) -> bool {
        self.unexpanded.is_empty()
    }
}

impl MctsSearchBudget {
    /// Construct from an explicit `(budget, rollout_depth)` pair.
    ///
    /// Prefer the struct literal (`MctsSearchBudget { budget, rollout_depth }`)
    /// at call sites you control — this constructor has the same transposable
    /// argument order as the raw search functions, and exists for adapters
    /// that already receive the two values positionally.
    #[inline]
    pub const fn new(budget: usize, rollout_depth: usize) -> Self {
        Self {
            budget,
            rollout_depth,
        }
    }
}

impl MeanFieldOverlap {
    /// Allocate scratch sized for HLA dimension `D`. Pre-allocates both
    /// scratch buffers; reuse the [`MeanFieldOverlap`] across calls to keep
    /// the hot path zero-allocation.
    pub fn with_capacity(dim: usize) -> Self {
        Self {
            kappa: 0.0,
            kappa_a: 0.0,
            q: 0.0,
            scratch_dot: Vec::with_capacity(dim),
            scratch_sq: Vec::with_capacity(dim),
        }
    }

    /// One-pass aggregation over K NPCs' HLA states `{h_i}` + adaptation
    /// currents `{a_i}`, projected onto direction vector `n`.
    ///
    /// All slices must have equal length `K`, and each inner slice must have
    /// length `D` matching the capacity passed to [`Self::with_capacity`].
    /// Mismatched lengths trigger a `debug_assert!` (release builds proceed
    /// with the minimum-length prefix — defensive but not a security boundary).
    ///
    /// After this call, [`Self::kappa`], [`Self::kappa_a`], [`Self::q`] hold
    /// the crowd-average `(κ, κ_a, Q)`. [`Self::estimate_chaos_intensity`]
    /// returns the heuristic `g` estimate derived from `Q`.
    ///
    /// # Hot-path contract
    ///
    /// Zero allocation: writes into the pre-allocated `scratch_dot` /
    /// `scratch_sq` buffers (which are `clear()`-ed at the start — capacity
    /// is preserved). Chunk-4 inner loop for SIMD auto-vectorisation per
    /// AGENTS.md optimization rules.
    pub fn aggregate_into(&mut self, hlas: &[&[f32]], adapt: &[&[f32]], n: &[f32]) {
        let k = hlas.len().min(adapt.len());
        debug_assert!(
            hlas.len() == adapt.len(),
            "hlas.len() = {} != adapt.len() = {} — proceeding with min",
            hlas.len(),
            adapt.len()
        );
        if k == 0 {
            self.kappa = 0.0;
            self.kappa_a = 0.0;
            self.q = 0.0;
            return;
        }

        // Reset accumulators (no realloc — fixed capacity from construction).
        self.scratch_dot.clear();
        self.scratch_sq.clear();

        let d = n.len();
        // Reserve exactly D slots; capacity is already >= D from with_capacity.
        // Use resize so the chunk-4 indexing is safe even if D < capacity.
        self.scratch_dot.resize(d, 0.0);
        self.scratch_sq.resize(d, 0.0);

        let inv_k = 1.0f32 / (k as f32);
        let inv_d = if d > 0 { 1.0f32 / (d as f32) } else { 0.0 };

        // Per-dimension crowd averages of (tanh(h_i)) and (tanh(h_i))²,
        // computed in one pass over the K NPCs. The final dot-products with
        // n happen after the loop (one D-dim dot, not K).
        //
        // The κ_a = ⟨n, a⟩ dot-product is fused into the same chunk-4 loop to
        // avoid a second pass over D per NPC (saves loop overhead).
        let mut kappa_a_acc: f32 = 0.0;
        for i in 0..k {
            let h = hlas[i];
            let a = adapt[i];
            debug_assert!(
                h.len() >= d && a.len() >= d,
                "NPC {i} h.len()={} a.len()={} < d={d}",
                h.len(),
                a.len()
            );
            // Chunk-4 fused accumulation: tanh(h), tanh(h)², and n·a in one pass.
            let mut dot_na = 0.0f32;
            let mut j = 0;
            while j + 4 <= d {
                let th0 = fast_tanh(h[j]);
                let th1 = fast_tanh(h[j + 1]);
                let th2 = fast_tanh(h[j + 2]);
                let th3 = fast_tanh(h[j + 3]);
                self.scratch_dot[j] += th0;
                self.scratch_dot[j + 1] += th1;
                self.scratch_dot[j + 2] += th2;
                self.scratch_dot[j + 3] += th3;
                self.scratch_sq[j] += th0 * th0;
                self.scratch_sq[j + 1] += th1 * th1;
                self.scratch_sq[j + 2] += th2 * th2;
                self.scratch_sq[j + 3] += th3 * th3;
                dot_na +=
                    n[j] * a[j] + n[j + 1] * a[j + 1] + n[j + 2] * a[j + 2] + n[j + 3] * a[j + 3];
                j += 4;
            }
            while j < d {
                let th = fast_tanh(h[j]);
                self.scratch_dot[j] += th;
                self.scratch_sq[j] += th * th;
                dot_na += n[j] * a[j];
                j += 1;
            }
            kappa_a_acc += dot_na;
        }

        // Final contractions with the direction vector n, then crowd-average.
        let mut kappa_acc = 0.0f32;
        let mut q_acc = 0.0f32;
        let mut j = 0;
        while j + 4 <= d {
            kappa_acc += n[j] * self.scratch_dot[j]
                + n[j + 1] * self.scratch_dot[j + 1]
                + n[j + 2] * self.scratch_dot[j + 2]
                + n[j + 3] * self.scratch_dot[j + 3];
            q_acc += self.scratch_sq[j]
                + self.scratch_sq[j + 1]
                + self.scratch_sq[j + 2]
                + self.scratch_sq[j + 3];
            j += 4;
        }
        while j < d {
            kappa_acc += n[j] * self.scratch_dot[j];
            q_acc += self.scratch_sq[j];
            j += 1;
        }

        self.kappa = kappa_acc * inv_k;
        self.kappa_a = kappa_a_acc * inv_k;
        // Q is per-dimension-averaged (see struct doc): bounded [0,1], O(1),
        // matching the paper's g_c ≈ 1 chaos threshold.
        self.q = q_acc * inv_k * inv_d;
    }

    /// Coherent-mode overlap `κ = ⟨n, tanh(h)⟩` (crowd average).
    ///
    /// Raw scalar (paper §2.4) — synced across quorum nodes for crowd-belief
    /// agreement. Bridge to the synced "crowd coherence" scalar via
    /// `crate::sigmoid(κ)` clamped to `[0,1]`.
    #[inline]
    pub fn kappa(&self) -> f32 {
        self.kappa
    }

    /// Adaptation overlap `κ_a = ⟨n, a⟩` (crowd average; slow leaky
    /// integrator of κ). Latent — never synced directly (semantic-domain).
    #[inline]
    pub fn kappa_a(&self) -> f32 {
        self.kappa_a
    }

    /// Incoherent variance `Q = ⟨tanh(h)²⟩` (crowd average). Latent — never
    /// synced directly. Drives [`Self::estimate_chaos_intensity`].
    #[inline]
    pub fn q(&self) -> f32 {
        self.q
    }

    /// Heuristic chaos-intensity estimate `g ≈ sqrt(Q / (1 − Q))`.
    ///
    /// The paper's `Q` (incoherent variance) grows monotonically with `g`
    /// above the chaos threshold `g_c(β)`. This is a **rough** estimator —
    /// the precise relationship depends on the closed-form `Q_fp(Σ²_h, β)`
    /// (paper Eq. 55c) which the caller may compute and inject via
    /// [`RegimeClassifier::classify_with_g`] instead. Returns `0.0` when
    /// `Q ≥ 1` (degenerate — clamp-style guard against div-by-zero).
    ///
    /// Refined in Phase 3 by the regime classifier; here it is the default
    /// estimator.
    #[inline]
    pub fn estimate_chaos_intensity(&self) -> f32 {
        if self.q >= 1.0 {
            return 0.0;
        }
        (self.q / (1.0 - self.q)).sqrt()
    }
}

impl Regime {
    /// Sync-boundary serialization. Bit-stable across platforms (the enum is
    /// `#[repr(u8)]`). Use this for quorum agreement — never serialize the
    /// Rust enum discriminant directly (layout is not guaranteed without
    /// `#[repr(...)]`, which we have here, but `as_u8` is the documented
    /// stable surface).
    #[inline]
    pub fn as_u8(self) -> u8 {
        self as u8
    }

    /// Inverse of [`Self::as_u8`]. Returns `None` for values outside the
    /// enum range (defensive — sync-layer deserialization).
    #[inline]
    pub fn from_u8(v: u8) -> Option<Self> {
        match v {
            0 => Some(Self::Static),
            1 => Some(Self::NoiseSustainedOscillation),
            2 => Some(Self::IrregularSwitching),
            3 => Some(Self::GlobalLimitCycle),
            _ => None,
        }
    }
}

impl RegimeClassifier {
    /// Construct with explicit margins. See [`Self::default`] for paper-
    /// anchored defaults.
    pub fn new(
        hopf_margin: f32,
        switching_margin: f32,
        chaos_threshold: f32,
        saddle_margin: f32,
        spinodal_margin: f32,
    ) -> Self {
        Self {
            hopf_margin,
            switching_margin,
            chaos_threshold,
            saddle_margin,
            spinodal_margin,
        }
    }

    /// Classify the regime from the crowd overlap + Hopf params.
    ///
    /// Uses [`MeanFieldOverlap::estimate_chaos_intensity`] as the default `g`
    /// estimate. Callers with a calibrated `g` (e.g. from `cgsp_runtime`
    /// curiosity exploration intensity, or the closed-form `Q_fp` from paper
    /// Eq. 55c) should use [`Self::classify_with_g`] instead.
    ///
    /// # Decision tree
    ///
    /// 1. Compute the planar Jacobian trace `T` from `params`.
    /// 2. [`hopf_boundary`] returns `Some(ω)` ⟺ complex eigenvalues with
    ///    positive real part (`Δ < 0` AND `T > 0`):
    ///    - `T > hopf_margin` → [`Regime::GlobalLimitCycle`] (Hopf bifurcation
    ///      occurred, stable limit cycle).
    ///    - `switching_margin < T ≤ hopf_margin` AND `g > chaos_threshold` →
    ///      [`Regime::IrregularSwitching`] (near-Hopf, noise kicks across
    ///      separatrix).
    /// 3. [`hopf_boundary`] returns `None` but [`static_boundary`] returns
    ///    `true` (real-eigenvalue instability — saddle or unstable node):
    ///    - [`saddle_strength`] `> saddle_margin` (strong saddle):
    ///      - `β·G_eff > spinodal_margin` (near spinodal pole) →
    ///        [`Regime::GlobalLimitCycle`] (nonlinear trapping creates limit
    ///        cycle — Issue 034 T1-followup-2).
    ///      - `g > chaos_threshold` → [`Regime::IrregularSwitching`] (saddle
    ///        drives switching between ±κ basins — Issue 034 T1 finding).
    ///      - `g ≤ chaos_threshold` → [`Regime::NoiseSustainedOscillation`].
    ///    - [`saddle_strength`] `≤ saddle_margin` (weak saddle — instability
    ///      grows too slowly to matter in finite observation) →
    ///      [`Regime::Static`] (Issue 034 T1 follow-up: weak saddles present
    ///      as Static because dissipation wins over the tiny `λ₊`).
    /// 4. Both boundaries return `None`/`false` (truly stable):
    ///    - `g > chaos_threshold` → [`Regime::NoiseSustainedOscillation`]
    ///      (stable focus driven by chaotic bulk — paper's key novel Regime II).
    ///    - `g ≤ chaos_threshold` → [`Regime::Static`] (stable node, no chaos).
    ///
    /// # Determinism
    ///
    /// Pure f32 arithmetic. Bit-identical across platforms (anti-cheat — the
    /// [`Regime`] enum crosses the sync boundary).
    pub fn classify(&self, overlap: &MeanFieldOverlap, params: &HopfParams) -> Regime {
        let g = overlap.estimate_chaos_intensity();
        self.classify_with_g(overlap, params, g)
    }

    /// Classify with a caller-injected `g` (calibrated chaos intensity).
    ///
    /// Use this when the caller has a better `g` estimate than the heuristic
    /// [`MeanFieldOverlap::estimate_chaos_intensity`] — e.g. from the
    /// closed-form `Q_fp(Σ²_h, β)` (paper Eq. 55c), or from `cgsp_runtime`
    /// curiosity exploration intensity. The `overlap` argument is currently
    /// taken for API symmetry and future hooks (e.g. κ-magnitude gating);
    /// its current fields are not read in this path beyond what
    /// [`hopf_boundary`] uses internally (which is `params` only).
    pub fn classify_with_g(
        &self,
        _overlap: &MeanFieldOverlap,
        params: &HopfParams,
        g: f32,
    ) -> Regime {
        let t = jacobian_trace(params);
        if hopf_boundary(params).is_some() {
            // Complex eigenvalues with positive real part — Hopf regime.
            if t > self.hopf_margin {
                Regime::GlobalLimitCycle
            } else if t > self.switching_margin && g > self.chaos_threshold {
                Regime::IrregularSwitching
            } else if g > self.chaos_threshold {
                // Trace barely positive, low g — still switching per paper
                // Fig. 1 near-Hopf band.
                Regime::IrregularSwitching
            } else {
                // Trace positive but g below chaos threshold — the bulk
                // cannot sustain switching; treat as noise-sustained (the
                // coherent mode is oscillatory but the bulk is quiescent).
                Regime::NoiseSustainedOscillation
            }
        } else {
            // No Hopf (complex-eigenvalue) instability.
            // Check for real-eigenvalue instability (saddle) — Issue 034 T1:
            // at high β, the symmetric fixed point κ=0 can undergo a saddle
            // bifurcation (real eigenvalue crossing zero). The saddle drives
            // switching between ±κ basins. Without this check, the classifier
            // misses saddle-mediated IrregularSwitching and incorrectly falls
            // through to NoiseSustainedOscillation or Static.
            //
            // Weak-saddle gating (Issue 034 T1 follow-up): a saddle with
            // tiny `λ₊` (e.g. ≈0.005 at g=1.0, β=1.4) grows too slowly to
            // produce visible dynamics in finite simulation. Critically, the
            // presence of a saddle signals high β (strong adaptation), which
            // suppresses bulk-driven oscillations too — so weak-saddle points
            // present as [`Regime::Static`] regardless of g. Only strong
            // saddles (`λ₊ > saddle_margin`) drive IrregularSwitching.
            //
            // Spinodal-pole check (Issue 034 T1-followup-2): when a strong
            // saddle coincides with spinodal proximity (`β·G_eff` large),
            // the denominator `1−β·χ̄` is near zero and the linearized
            // Jacobian eigenvalues are unreliable. Near the spinodal pole,
            // tanh saturation bounds trajectories into a trapping region →
            // a limit cycle (GLC) rather than switching (IS). The threshold
            // `spinodal_margin = 9.0` corresponds to recovered denominator
            // `1/(1+β·G_eff) < 0.10`, matching the `safe_g_eff` clamp at
            // 0.1 — it flags points where G_eff was likely clamped.
            let s = saddle_strength(params);
            if s > self.saddle_margin {
                // Strong real-eigenvalue instability.
                if params.beta * params.g_eff > self.spinodal_margin {
                    // Near spinodal pole → nonlinear trapping → limit cycle.
                    Regime::GlobalLimitCycle
                } else if g > self.chaos_threshold {
                    // Strong saddle, chaotic bulk → drives switching.
                    Regime::IrregularSwitching
                } else {
                    Regime::NoiseSustainedOscillation
                }
            } else if s > 0.0 {
                // Weak saddle: instability too slow + strong adaptation
                // suppresses the chaotic bulk → Static (dissipation wins).
                Regime::Static
            } else if g > self.chaos_threshold {
                // Truly stable planar subsystem + chaotic bulk.
                Regime::NoiseSustainedOscillation
            } else {
                Regime::Static
            }
        }
    }
}

impl CompressionRatio {
    /// Number of input tokens per latent slot.
    pub fn span_size(&self) -> usize {
        *self as usize
    }
}

impl MuxLatentConfig {
    /// Creates a config optimized for speed (aggressive compression).
    pub fn fast() -> Self {
        Self {
            compression_ratio: CompressionRatio::X16,
            mux_decay: 0.85,
            ..Default::default()
        }
    }

    /// Creates a config optimized for quality (conservative compression).
    pub fn quality() -> Self {
        Self {
            compression_ratio: CompressionRatio::X4,
            mux_decay: 0.95,
            ..Default::default()
        }
    }

    /// Number of latent slots produced from a given input length.
    pub fn latent_slot_count(&self, input_len: usize) -> usize {
        let total_spans = input_len.div_ceil(self.compression_ratio.span_size());
        if self.max_latent_slots > 0 {
            total_spans.min(self.max_latent_slots)
        } else {
            total_spans
        }
    }

    /// Number of windows for the encoder (each window processes window_size tokens).
    pub fn window_count(&self, input_len: usize) -> usize {
        input_len.div_ceil(self.window_size)
    }
}

impl LatentSegment {
    /// Number of latent slots this segment occupies.
    pub fn latent_count(&self) -> usize {
        match self {
            Self::Compressed { .. } => 1,
            Self::Raw { tokens } => tokens.len(),
        }
    }

    /// Number of original tokens represented by this segment.
    pub fn original_token_count(&self) -> usize {
        match self {
            Self::Compressed {
                original_tokens, ..
            } => original_tokens.len(),
            Self::Raw { tokens } => tokens.len(),
        }
    }

    /// Segment ID, if this is a compressed segment.
    pub fn segment_id(&self) -> Option<u32> {
        match self {
            Self::Compressed { segment_id, .. } => Some(*segment_id),
            Self::Raw { .. } => None,
        }
    }
}

impl CompressedContext {
    /// Effective compression ratio achieved.
    pub fn compression_ratio(&self) -> f32 {
        if self.latent_slot_count == 0 {
            return 1.0;
        }
        // Ratio of original tokens to (latent slots + raw token count)
        let total_after = self
            .segments
            .iter()
            .map(|s| s.latent_count())
            .sum::<usize>();
        self.original_token_count as f32 / total_after.max(1) as f32
    }

    /// Retrieve original tokens for a compressed segment by ID (EXPAND).
    ///
    /// This is the inference-time analog of LCLM's EXPAND(i) tool.
    /// Returns None if segment_id doesn't exist or segment is raw.
    pub fn expand(&self, segment_id: u32) -> Option<&[u32]> {
        self.segments.iter().find_map(|seg| match seg {
            LatentSegment::Compressed {
                segment_id: id,
                original_tokens,
                ..
            } if *id == segment_id => Some(original_tokens.as_slice()),
            _ => None,
        })
    }

    /// Total decoder-side token budget (latent slots + raw tokens).
    pub fn decoder_budget(&self) -> usize {
        self.segments.iter().map(|s| s.latent_count()).sum()
    }

    /// Memory savings: original tokens vs decoder budget.
    pub fn memory_savings(&self) -> f32 {
        let budget = self.decoder_budget();
        if budget == 0 {
            return 0.0;
        }
        1.0 - (budget as f32 / self.original_token_count as f32)
    }
}

impl MuxLatentEncoder {
    /// Create a new encoder with the given configuration.
    pub fn new(config: MuxLatentConfig) -> Self {
        Self { config }
    }

    /// Create with default configuration.
    pub fn default_encoder() -> Self {
        Self::new(MuxLatentConfig::default())
    }

    /// Compress a full token sequence into a `CompressedContext`.
    ///
    /// The input is split into windows (per config.window_size), each window
    /// is further split into spans (per config.compression_ratio), and each
    /// span is encoded into a single latent slot via MUX superposition.
    ///
    /// Instructions (first window when preserve_instructions is true) are
    /// kept as raw tokens.
    pub fn encode(&self, tokens: &[u32]) -> CompressedContext {
        let span_size = self.config.compression_ratio.span_size();
        // window_size=0 means no windowing — encode all tokens in one pass.
        let window_size = if self.config.window_size == 0 {
            tokens.len()
        } else {
            self.config.window_size
        };
        let original_count = tokens.len();

        // Upper bound on segment count: ceil(tokens.len() / span_size) + 1
        // (the +1 covers the optional preserve_instructions raw window).
        let max_segments = tokens.len().div_ceil(span_size.max(1)) + 1;
        let mut segments = Vec::with_capacity(max_segments);
        let mut segment_id: u32 = 0;
        let mut pos = 0;

        while pos < tokens.len() {
            let window_end = (pos + window_size).min(tokens.len());

            // Preserve first window as raw tokens (typically system prompt + instructions)
            if self.config.preserve_instructions && pos == 0 && window_end < tokens.len() {
                segments.push(LatentSegment::Raw {
                    tokens: tokens[pos..window_end].to_vec(),
                });
                pos = window_end;
                continue;
            }

            // Encode spans within the window
            while pos < window_end {
                let span_end = (pos + span_size).min(window_end);
                let span_tokens = &tokens[pos..span_end];

                if span_tokens.len() <= 2 {
                    // Too short to compress meaningfully — keep raw
                    segments.push(LatentSegment::Raw {
                        tokens: span_tokens.to_vec(),
                    });
                } else {
                    let weights = self.encode_span(span_tokens);
                    segments.push(LatentSegment::Compressed {
                        segment_id,
                        weights,
                        original_tokens: span_tokens.to_vec(),
                    });
                    segment_id += 1;
                }

                pos = span_end;
            }
        }

        let latent_slot_count = segments
            .iter()
            .filter(|s| matches!(s, LatentSegment::Compressed { .. }))
            .count();

        CompressedContext {
            segments,
            original_token_count: original_count,
            latent_slot_count,
            config: self.config.clone(),
        }
    }

    /// Encode a single span of tokens into MUX superposition weights.
    ///
    /// Each position gets a weight of `decay^j` where j is the position index.
    /// This creates a causal ordering that preserves positional information
    /// (matching LCLM's finding that causal encoding outperforms bidirectional).
    ///
    /// The weights are normalized to sum to 1.0 for stable injection.
    pub(crate) fn encode_span(&self, tokens: &[u32]) -> Vec<f32> {
        let decay = self.config.mux_decay;
        let mut weights = Vec::with_capacity(tokens.len());

        let mut total_weight = 0.0f32;
        for j in 0..tokens.len() {
            let w = decay.powi(j as i32);
            weights.push(w);
            total_weight += w;
        }

        // Normalize to unit sum for stable decoder-side injection
        if total_weight > 0.0 {
            for w in &mut weights {
                *w /= total_weight;
            }
        }

        weights
    }

    /// Encode only the latent slots (no raw segments) for tight inner loops.
    ///
    /// Returns (weights_per_span, segment_count) where each weights vec
    /// has `span_size` elements.
    pub fn encode_latents_only(&self, tokens: &[u32]) -> Vec<Vec<f32>> {
        let span_size = self.config.compression_ratio.span_size();
        let mut result = Vec::with_capacity(tokens.len().div_ceil(span_size));

        for chunk in tokens.chunks(span_size) {
            if chunk.len() > 2 {
                result.push(self.encode_span(chunk));
            }
        }

        result
    }

    /// Compute the superposition logit vector for a span (for MUX verification).
    ///
    /// This produces the vocabulary-space representation:
    ///   `logit[v] = Σ weights[j] for all j where tokens[j] == v`
    ///
    /// Useful for integration with existing MUX verification infrastructure.
    pub fn superposition_logits(&self, tokens: &[u32], vocab_size: usize) -> Vec<f32> {
        let weights = self.encode_span(tokens);
        let mut logits = vec![0.0f32; vocab_size];

        for (j, &token_id) in tokens.iter().enumerate() {
            if (token_id as usize) < vocab_size {
                logits[token_id as usize] += weights[j];
            }
        }

        logits
    }

    /// Get the configuration.
    pub fn config(&self) -> &MuxLatentConfig {
        &self.config
    }
}

impl LatentPrefillAdapter {
    /// Create a new adapter with the given configuration.
    pub fn new(config: MuxLatentConfig) -> Self {
        Self { config }
    }

    /// Convert a `CompressedContext` into a mixed prefill sequence.
    ///
    /// Raw segments are expanded into individual `PrefillEntry::Raw` entries.
    /// Compressed segments become single `PrefillEntry::Latent` entries.
    ///
    /// The effective prefill length is the count of entries, which should be
    /// much smaller than `original_token_count` when compression is active.
    pub fn to_prefill_sequence(&self, ctx: &CompressedContext) -> MixedPrefillSequence {
        // Lower bound on entries: one per segment. Avoids realloc churn when
        // raw segments expand into many entries.
        let mut entries = Vec::with_capacity(ctx.segments.len());
        let mut original_pos = 0usize;
        let mut compressed_pos = 0usize;

        for segment in &ctx.segments {
            match segment {
                LatentSegment::Raw { tokens } => {
                    for &token_id in tokens {
                        entries.push(PrefillEntry::Raw {
                            token_id,
                            original_pos,
                        });
                        original_pos += 1;
                        compressed_pos += 1;
                    }
                }
                LatentSegment::Compressed {
                    segment_id,
                    weights,
                    original_tokens,
                } => {
                    entries.push(PrefillEntry::Latent {
                        segment_id: *segment_id,
                        weights: weights.clone(),
                        original_tokens: original_tokens.clone(),
                        compressed_pos,
                    });
                    original_pos += original_tokens.len();
                    compressed_pos += 1;
                }
            }
        }

        let effective_prefill_len = entries.len();

        MixedPrefillSequence {
            entries,
            original_token_count: ctx.original_token_count,
            effective_prefill_len,
        }
    }

    /// Extract only the raw token IDs from a mixed sequence.
    ///
    /// Useful for the embedding lookup — latent slots need special handling.
    pub fn raw_token_ids(seq: &MixedPrefillSequence) -> Vec<u32> {
        seq.entries
            .iter()
            .filter_map(|e| match e {
                PrefillEntry::Raw { token_id, .. } => Some(*token_id),
                PrefillEntry::Latent {
                    original_tokens, ..
                } => {
                    // Use the first original token as the embedding anchor
                    original_tokens.first().copied()
                }
            })
            .collect()
    }

    /// Count the KV cache savings compared to uncompressed prefill.
    ///
    /// Returns (original_kv_entries, compressed_kv_entries, savings_fraction).
    pub fn kv_savings(seq: &MixedPrefillSequence) -> (usize, usize, f32) {
        let original = seq.original_token_count;
        let compressed = seq.effective_prefill_len;
        let savings = if original > 0 {
            1.0 - (compressed as f32 / original as f32)
        } else {
            0.0
        };
        (original, compressed, savings)
    }

    /// Get indices of latent entries in the sequence (for mid-layer injection).
    pub fn latent_indices(seq: &MixedPrefillSequence) -> Vec<usize> {
        seq.entries
            .iter()
            .enumerate()
            .filter_map(|(i, e)| match e {
                PrefillEntry::Latent { .. } => Some(i),
                PrefillEntry::Raw { .. } => None,
            })
            .collect()
    }

    /// Get the configuration.
    pub fn config(&self) -> &MuxLatentConfig {
        &self.config
    }
}

impl CompressionSummary {
    /// Compute summary from a mixed prefill sequence.
    pub fn from_sequence(seq: &MixedPrefillSequence) -> Self {
        let mut latent_slots = 0usize;
        let mut raw_tokens = 0usize;

        for entry in &seq.entries {
            match entry {
                PrefillEntry::Latent { .. } => latent_slots += 1,
                PrefillEntry::Raw { .. } => raw_tokens += 1,
            }
        }

        let (original, compressed, kv_savings) = LatentPrefillAdapter::kv_savings(seq);

        let estimated_ttft_reduction = if original > 0 {
            compressed as f32 / original as f32
        } else {
            1.0
        };

        Self {
            original_tokens: original,
            effective_entries: compressed,
            latent_slots,
            raw_tokens,
            kv_savings,
            estimated_ttft_reduction,
        }
    }

    /// Compression ratio as a scalar `>= 1.0` (`1.0` = no compression).
    ///
    /// `original_tokens / effective_entries` — how many original tokens each
    /// effective prefill entry (raw or latent slot) represents. This is the
    /// signal consumed by the Plan 310 active-state bridge: a high ratio means
    /// the MUX-Latent compressor is working hard, which (per HarnessBridge
    /// Fig 4) correlates with active-state-rate and predicts weight staleness.
    ///
    /// Returns `1.0` when `effective_entries` is zero (guard against
    /// div-by-zero on an empty sequence).
    #[inline]
    pub fn compression_ratio(&self) -> f32 {
        let denom = self.effective_entries.max(1) as f32;
        self.original_tokens as f32 / denom
    }
}

