impl SpecDiffScratch {
    /// Construct an empty scratch (lazy-allocates on first call).
    pub fn new() -> Self {
        Self::default()
    }

    /// Ensure the internal frequency buffer has capacity for at least `n`
    /// complex samples, AND pre-warm the cached FFT plans + scratch for size
    /// `n`. Plans are cached as `Arc<dyn Fft<f32>>` handles so the hot path
    /// clones them (refcount bump, allocation-free) instead of calling
    /// `FftPlanner::plan_fft_*` (which allocates per call). Call once with
    /// the expected input size to make the first [`spectral_differentiate_into`]
    /// call allocation-free. If the size later changes, plans are rebuilt
    /// lazily on the next `spectral_differentiate_into`.
    pub fn ensure_capacity(&mut self, n: usize) {
        if self.freq_buf.capacity() < n {
            // Reserve with a bit of slack to absorb small size variations
            // without re-allocating.
            self.freq_buf
                .reserve_exact(n.saturating_sub(self.freq_buf.capacity()) + n / 4 + 8);
        }
        if self.cached_size != n {
            // Build + cache the plans for this size. Returns `Arc<dyn Fft<f32>>`;
            // we store the Arc so the hot path clones it instead of recalling
            // the planner.
            self.fwd_plan = Some(self.planner.plan_fft_forward(n));
            self.inv_plan = Some(self.planner.plan_fft_inverse(n));
            self.cached_size = n;
        }
        // Size the FFT scratch to the larger of the two cached plans' scratch
        // requirements (used by `process_with_scratch`).
        let needed = self
            .fwd_plan
            .as_ref()
            .map_or(0, |p| p.get_inplace_scratch_len())
            .max(
                self.inv_plan
                    .as_ref()
                    .map_or(0, |p| p.get_inplace_scratch_len()),
            );
        if self.fft_scratch.capacity() < needed {
            self.fft_scratch
                .reserve_exact(needed.saturating_sub(self.fft_scratch.capacity()) + needed / 4 + 8);
        }
        // Keep length == capacity so the slice we hand to rustfft is the full
        // allocation. The contents are garbage (overwritten by rustfft); only
        // the length matters.
        if self.fft_scratch.len() < self.fft_scratch.capacity() {
            self.fft_scratch
                .resize(self.fft_scratch.capacity(), Complex::new(0.0, 0.0));
        }
    }

    /// Hand rustfft two disjoint mutable sub-borrows: the frequency buffer
    /// (the actual signal) and the FFT scratch (rustfft's working space).
    /// Used between the forward and inverse FFT calls so the caller can still
    /// re-borrow `freq_buf` mutably to apply the `(iω)^m` multiplier.
    #[inline]
    fn split_buffers(&mut self) -> (&mut [Complex<f32>], &mut [Complex<f32>]) {
        // `split_first_mut` would also work; `split_at_mut(0)` is cleaner here
        // because the two slices are independent (not contiguous segments).
        // We use the safe reborrow pattern: split `freq_buf` off first, then
        // take `fft_scratch` separately. The borrow checker accepts this
        // because the two fields are disjoint.
        let freq_buf = &mut self.freq_buf[..];
        let fft_scratch = &mut self.fft_scratch[..];
        (freq_buf, fft_scratch)
    }
}

impl LatticeQmc {
    /// Construct from a 64-bit seed (SplitMix64-mixed per [`Rng::new`]).
    #[inline]
    pub fn new(seed: u64) -> Self {
        Self {
            rng: Rng::new(seed),
        }
    }
}

impl QmcSource for LatticeQmc {
    #[inline]
    fn draw(&mut self, k: usize, out: &mut [f32]) {
        assert!(
            out.len() >= k,
            "LatticeQmc::draw: out.len() {} < k {}",
            out.len(),
            k
        );
        if k == 0 {
            return;
        }
        let delta = self.rng.uniform();
        let inv_k = 1.0 / k as f32;
        // Each point: (i/k + Δ) mod 1. The `fract` is a single `% 1.0` —
        // numerically stable since i/k ∈ [0,1) and Δ ∈ [0,1), so i/k+Δ ∈ [0,2).
        for (i, slot) in out.iter_mut().enumerate().take(k) {
            let v = i as f32 * inv_k + delta;
            *slot = if v >= 1.0 { v - 1.0 } else { v };
        }
    }
}

impl StratifiedQmc {
    /// Construct from a 64-bit seed.
    #[inline]
    pub fn new(seed: u64) -> Self {
        Self {
            rng: Rng::new(seed),
        }
    }
}

impl QmcSource for StratifiedQmc {
    #[inline]
    fn draw(&mut self, k: usize, out: &mut [f32]) {
        assert!(
            out.len() >= k,
            "StratifiedQmc::draw: out.len() {} < k {}",
            out.len(),
            k
        );
        if k == 0 {
            return;
        }
        let inv_k = 1.0 / k as f32;
        // Step 1: draw one uniform per stratum: out[i] ~ Unif[i/k, (i+1)/k).
        for (i, slot) in out.iter_mut().enumerate().take(k) {
            let lo = i as f32 * inv_k;
            *slot = lo + self.rng.uniform() * inv_k;
        }
        // Step 2: Fisher-Yates shuffle — each permutation equally likely.
        // Index i drawn uniformly from [0, i] via next_u64 % (i+1).
        for i in (1..k).rev() {
            let j = (self.rng.next() % (i as u64 + 1)) as usize;
            out.swap(i, j);
        }
    }
}

impl SobolQmc {
    /// Construct a 1-dimensional Sobol source (Van der Corput + Owen shift).
    ///
    /// This is the most common case: each `draw(k, out)` produces k scalar
    /// points suitable for the [`QmcSource`] trait. For multi-dimensional
    /// coverage, use [`new_multi`](Self::new_multi).
    #[inline]
    pub fn new(seed: u64) -> Self {
        Self::new_multi(seed, 1)
    }

    /// Construct a `dim`-dimensional Sobol source.
    ///
    /// `dim` is clamped to [`SOBOL_MAX_DIM`]. Each dimension uses a distinct
    /// primitive polynomial over GF(2), computed at construction via the
    /// `find_primitive_poly` search.
    ///
    /// The trait method [`QmcSource::draw`] outputs only dimension 0 (for
    /// 1D compatibility). Use [`draw_nd`](Self::draw_nd) for multi-dimensional
    /// output.
    pub fn new_multi(seed: u64, dim: usize) -> Self {
        let dim = dim.clamp(1, SOBOL_MAX_DIM);
        let mut rng = Rng::new(seed);

        // Compute direction numbers for each dimension.
        let mut direction_numbers = [[0u32; SOBOL_BITS]; SOBOL_MAX_DIM];

        // Dimension 0: Van der Corput in base 2 — v[j] = 1 << (BITS-1-j).
        // This is the canonical first Sobol dimension (trivially "primitive").
        for (j, slot) in direction_numbers[0].iter_mut().enumerate() {
            *slot = 1u32 << (SOBOL_BITS - 1 - j);
        }

        // Dimensions 1..dim: find primitive polynomials and compute direction
        // numbers via the recurrence.
        for (d, row) in direction_numbers.iter_mut().enumerate().take(dim).skip(1) {
            let (poly, degree) = find_primitive_poly(d as u32);
            *row = compute_direction_numbers(poly, degree);
        }

        // Digital-shift scramble: one random u32 per dimension.
        //
        // Each scramble is the upper 32 bits of one `rng.next()` call (u64).
        // Upper bits of xorshift64 have better statistical distribution
        // than the lower bits (lower bits have shorter LFSR periods).
        // (Phase 5 GOAT gate G1 catch: the original code OR'd two 32-bit
        // halves from two separate draws — OR(a,b) is NOT uniform:
        // P(bit=1) = 0.75, not 0.5 — which biased the Sobol output and broke
        // marginal exactness. G1 fail rate dropped from 98% to ~1%.)
        let mut scramble = [0u32; SOBOL_MAX_DIM];
        for s in &mut scramble[..dim] {
            *s = (rng.next() >> 32) as u32;
            // Ensure nonzero (a zero scramble is valid but boring).
            if *s == 0 {
                *s = 0xDEAD_BEEF;
            }
        }

        Self {
            dim,
            index: 0,
            point: [0u32; SOBOL_MAX_DIM],
            direction_numbers,
            scramble,
        }
    }

    /// Multi-dimensional draw: fill `out` with `k` points, each `dim` f32s.
    ///
    /// Output layout: `[p0c0, p0c1, ..., p0c(dim-1), p1c0, ...]`.
    /// `out.len()` must be `>= k * self.dim`.
    ///
    /// This is the method for token-level Sobol where each rollout uses
    /// coordinate j as the initial `u` for token position j.
    pub fn draw_nd(&mut self, k: usize, out: &mut [f32]) {
        let needed = k * self.dim;
        assert!(
            out.len() >= needed,
            "SobolQmc::draw_nd: out.len() {} < k*dim {}",
            out.len(),
            needed
        );
        for i in 0..k {
            self.advance();
            let base = i * self.dim;
            for d in 0..self.dim {
                out[base + d] = u32_to_unit_f32(self.point[d] ^ self.scramble[d]);
            }
        }
    }

    /// Advance the internal state by one Sobol point (incremental XOR).
    #[inline]
    fn advance(&mut self) {
        self.index = self.index.wrapping_add(1);
        // The bit to flip is the position of the lowest set bit of the new index.
        // For index 1 → bit 0; index 2 → bit 1; index 3 → bit 0; etc.
        // This follows from Gray(n) XOR Gray(n-1) having exactly one bit set
        // at position trailing_zeros(n).
        let l = (self.index.trailing_zeros() as usize).min(SOBOL_BITS - 1);
        for d in 0..self.dim {
            self.point[d] ^= self.direction_numbers[d][l];
        }
    }
}

impl BootstrapEstimate {
    /// Wilson score confidence interval for the pass@m proportion.
    ///
    /// Preferred over the normal-approximation (`p̂ ± z·√(p̂(1-p̂)/n)`) for
    /// binary indicators because it has correct coverage at small n and near
    /// the 0/1 boundaries (Brown, Cai & DasGupta 2001).
    ///
    /// `z` is the two-sided critical value (1.96 for 95%, 2.576 for 99%).
    /// Returns `(low, high)` clamped to `[0, 1]`. For `n_resamples == 0`, the
    /// uninformative `(0.0, 1.0)` is returned.
    #[inline]
    pub fn wilson_ci(&self, z: f64) -> (f64, f64) {
        let n = self.n_resamples as f64;
        if n == 0.0 {
            return (0.0, 1.0);
        }
        let p_hat = self.point_estimate;
        let z2 = z * z;
        let denom = 1.0 + z2 / n;
        let center = (p_hat + z2 / (2.0 * n)) / denom;
        let margin = (z / denom) * (p_hat * (1.0 - p_hat) / n + z2 / (4.0 * n * n)).sqrt();
        let lo = (center - margin).max(0.0);
        let hi = (center + margin).min(1.0);
        (lo, hi)
    }

    /// Convenience: Wilson score 95% CI (z = 1.959963984540054, Φ⁻¹(0.975)).
    #[inline]
    pub fn wilson_ci_95(&self) -> (f64, f64) {
        self.wilson_ci(1.959_963_984_540_054)
    }

    /// Sample standard deviation across resamples (√ of [`sample_variance`](Self::sample_variance)).
    #[inline]
    pub fn std_dev(&self) -> f64 {
        self.sample_variance.sqrt()
    }
}

use super::*;

// ── KS test (marginal uniformity) ──────────────────────────────────────

/// Kolmogorov–Smirnov one-sample test against Unif[0,1).
/// Returns (D statistic, p-value).
fn ks_uniform(samples: &[f32]) -> (f64, f64) {
    let n = samples.len();
    assert!(n > 0);
    let mut sorted: Vec<f32> = samples.to_vec();
    sorted.sort_by(|a, b| a.partial_cmp(b).unwrap());

    let mut d_max = 0.0f64;
    let nf = n as f64;
    for (i, &x) in sorted.iter().enumerate() {
        let xf = x as f64;
        let f_lower = i as f64 / nf;
        let f_upper = (i + 1) as f64 / nf;
        d_max = d_max.max((f_lower - xf).abs()).max((f_upper - xf).abs());
    }

    // p-value via the Kolmogorov distribution complementary CDF
    // (Numerical Recipes formula):
    //   λ = (√N + 0.12 + 0.11/√N) · D
    //   Q = 2 · Σ_{j=1}^∞ (−1)^{j−1} exp(−2j²λ²)
    let en = nf.sqrt();
    let lambda = (en + 0.12 + 0.11 / en) * d_max;
    let mut q = 0.0f64;
    for j in 1..=100 {
        let sign = if j % 2 == 1 { 1.0 } else { -1.0 };
        let term = sign * (-2.0 * (j as f64) * (j as f64) * lambda * lambda).exp();
        q += term;
        if term.abs() < 1e-12 {
            break;
        }
    }
    q = (2.0 * q).clamp(0.0, 1.0);
    (d_max, q)
}

impl QmcHalter {
    /// Construct a halter with explicit config.
    ///
    /// - `target_coverage` — desired `P(at least one success)`. Clamped to
    ///   `(0.0, 1.0]`. A value > 1.0 is clamped to 1.0; a value ≤ 0.0 is
    ///   clamped to the smallest positive f32 (otherwise the halter would
    ///   fire immediately with `TargetMet` on k=0).
    /// - `k_min` — minimum batch before halting (≥ 1 enforced).
    /// - `k_max` — maximum batch cap. Clamped to `k_min.max(1)` so the cap
    ///   is never below the floor.
    #[inline]
    pub fn new(target_coverage: f32, k_min: usize, k_max: usize) -> Self {
        let target_coverage = if target_coverage.is_finite() && target_coverage > 0.0 {
            target_coverage.min(1.0)
        } else {
            f32::MIN_POSITIVE
        };
        let k_min = k_min.max(1);
        let k_max = k_max.max(k_min);
        Self {
            target_coverage,
            k_min,
            k_max,
        }
    }

    /// Target coverage accessor (for diagnostics / serialization).
    #[inline]
    pub fn target_coverage(&self) -> f32 {
        self.target_coverage
    }

    /// k_min accessor.
    #[inline]
    pub fn k_min(&self) -> usize {
        self.k_min
    }

    /// k_max accessor.
    #[inline]
    pub fn k_max(&self) -> usize {
        self.k_max
    }

    /// Decide whether to draw more QMC rollouts.
    ///
    /// # Arguments
    /// - `k` — number of QMC points drawn so far (current batch size).
    /// - `p` — per-rollout success probability (marginal, from the LM).
    ///   NaN-safe: a NaN p is treated as `0.0` (ceiling = 0, no halt on
    ///   TargetMet, halt only if k_max reached).
    /// - `n_hits` — number of the k points that fell in the success region
    ///   (caller computes; use [`count_hits_1d`] for the common 1D case).
    ///
    /// # Evaluation order
    /// 1. **k_min floor** — if `k < k_min`, return [`RefusedFloor`].
    /// 2. **k_max cap** — if `k >= k_max`, return [`Halt`](QmcHaltDecision::Halt) with [`KMaxReached`](QmcHaltReason::KMaxReached).
    /// 3. **Hit observed** — if `n_hits > 0`, return [`Halt`] with
    ///    [`HitObserved`] (early termination — pass@k objective met).
    /// 4. **Ceiling saturated** — if `ceiling ≥ 1.0`, return [`Halt`] with
    ///    [`CeilingSaturated`] (k·p ≥ 1 but no hit; event geometry mismatch).
    /// 5. **Target met** — if `ceiling ≥ target_coverage`, return [`Halt`]
    ///    with [`TargetMet`] (budget sufficient per union bound).
    /// 6. Otherwise [`Continue`] with the current ceiling and gap.
    ///
    /// [`RefusedFloor`]: QmcHaltDecision::RefusedFloor
    /// [`Halt`]: QmcHaltDecision::Halt
    /// [`HitObserved`]: QmcHaltReason::HitObserved
    /// [`CeilingSaturated`]: QmcHaltReason::CeilingSaturated
    /// [`TargetMet`]: QmcHaltReason::TargetMet
    /// [`Continue`]: QmcHaltDecision::Continue
    #[inline]
    pub fn evaluate(&self, k: usize, p: f32, n_hits: usize) -> QmcHaltDecision {
        // 1. k_min floor — refuse to halt below minimum batch.
        if k < self.k_min {
            return QmcHaltDecision::RefusedFloor;
        }

        // 2. k_max cap — safety halt.
        if k >= self.k_max {
            let ceiling = union_bound_ceiling(k, p);
            return QmcHaltDecision::Halt {
                reason: QmcHaltReason::KMaxReached,
                ceiling,
                coverage: if n_hits > 0 { 1.0 } else { ceiling },
            };
        }

        // NaN-safe ceiling: NaN p → 0.0 (no halt on TargetMet, continue).
        let ceiling = union_bound_ceiling(k, p);

        // 3. Hit observed — early termination (pass@k objective met).
        if n_hits > 0 {
            return QmcHaltDecision::Halt {
                reason: QmcHaltReason::HitObserved,
                ceiling,
                coverage: 1.0,
            };
        }

        // 4. Ceiling saturated — k·p ≥ 1 but no hit. Event geometry mismatch;
        //    more rollouts cannot raise the bound above 1.0.
        if ceiling >= 1.0 {
            return QmcHaltDecision::Halt {
                reason: QmcHaltReason::CeilingSaturated,
                ceiling: 1.0,
                coverage: ceiling,
            };
        }

        // 5. Target met — budget sufficient per union bound.
        if ceiling >= self.target_coverage {
            return QmcHaltDecision::Halt {
                reason: QmcHaltReason::TargetMet,
                ceiling,
                coverage: ceiling,
            };
        }

        // 6. Continue — ceiling below target, no hit yet.
        let gap = (self.target_coverage - ceiling).max(0.0);
        QmcHaltDecision::Continue { ceiling, gap }
    }
}

