    fn posterior_into(&self, i: usize, x: &[usize], out: &mut [f32]) {
        let mut m0 = 0usize;
        let mut j = 0usize;
        for (l, &v) in x.iter().enumerate() {
            if l != i && v != UGC_MASK {
                j += 1;
                if v == 0 {
                    m0 += 1;
                }
            }
        }
        let p0 = self.post_u0(m0, j);
        // P(Z_i = 0 | x) = (1−η)·P(U=0|x) + η·P(U=1|x).
        out[0] = ((1.0 - self.eta) * p0 + self.eta * (1.0 - p0)) as f32;
        out[1] = 1.0 - out[0];
    }
