        Self {
            latent_dim,
            compact_length,
            kv_dim,
            ..Default::default()
        }
    }

    /// Dimension per cross-attention head.
    #[inline]
    fn cross_head_dim(&self) -> usize {
        self.latent_dim / self.cross_attn_heads
    }

    /// Dimension per self-attention head.
    #[inline]
    fn self_head_dim(&self) -> usize {
        self.latent_dim / self.self_attn_heads
    }
}

use half::f16;

/// Compactor that operates in position-free (RoPE-removed) space.
///
/// The key insight: RoPE encodes absolute position via rotation. If we un-rotate
/// keys before compaction, the compactor sees "pure semantic" keys without position
/// interference. After compaction, we re-rotate with adjusted positions.
#[derive(Debug, Clone)]
pub struct PositionFreeCompactor {
    /// RoPE base frequency (theta).
    pub rope_theta: f32,
    /// Head dimension.
    pub head_dim: usize,
    /// Pre-computed RoPE frequency table: `freq[i] = 1.0 / (theta^(2i / head_dim))`.
    /// Cached at construction so per-call un-rotate/re-rotate avoid recomputing it.
    freqs: Vec<f32>,
}

impl PositionFreeCompactor {
    /// Create a new position-free compactor with the given RoPE parameters.
    pub fn new(rope_theta: f32, head_dim: usize) -> Self {
        let freqs = Self::compute_freq_table(rope_theta, head_dim);
        Self {
            rope_theta,
            head_dim,
            freqs,
        }
    }

    /// Build the RoPE frequency table.
    ///
    /// `freq[i] = 1.0 / (theta^(2i / head_dim))` for `i` in `0..half`.
    /// Pure function of `(rope_theta, head_dim)` — safe to cache once.
    fn compute_freq_table(rope_theta: f32, head_dim: usize) -> Vec<f32> {
        let half = head_dim / 2;
        let mut freqs = Vec::with_capacity(half);
        for i in 0..half {
            let exponent = 2.0 * i as f32 / head_dim as f32;
            freqs.push(1.0 / rope_theta.powf(exponent));
        }
        freqs
    }

    /// Un-rotate RoPE from keys, returning position-free key buffer.
    ///
    /// # Arguments
    /// * `keys` - Flat f16 key buffer, shape `[seq_len * head_dim]`
    /// * `start_pos` - Starting position index of this key sequence
    ///
    /// # Returns
    /// Position-free keys in f32 for compaction processing.
    ///
    /// Inverse rotation (un-rotate):
    ///   x_new = x*cos(θ) + y*sin(θ)
    ///   y_new = -x*sin(θ) + y*cos(θ)
    pub fn un_rotate_keys(&self, keys: &[f16], start_pos: usize) -> Vec<f32> {
        if self.head_dim == 0 || keys.is_empty() {
            return Vec::new();
        }

        let head_dim = self.head_dim;
        let half = head_dim / 2;
        let seq_len = keys.len() / head_dim;

        // Convert f16 → f32
        let mut out = Vec::with_capacity(keys.len());
        for &v in keys {
            out.push(v.to_f32());
        }

        // Use cached frequency table (built once at construction).
        let freqs = &self.freqs;

        // For each token at position p, un-rotate pairs (i, i+half)
        for t in 0..seq_len {
            let pos = (start_pos + t) as f32;
            let base = t * head_dim;

            // Process in chunks of 4 for auto-vectorization
            let chunks = half / 4;
            let remainder = half % 4;

            for c in 0..chunks {
                let i = c * 4;

                // Unroll 4 pairs
                for j in 0..4 {
                    let idx = i + j;
                    let angle = pos * freqs[idx];
                    let cos_a = angle.cos();
                    let sin_a = angle.sin();

                    let x = out[base + idx];
                    let y = out[base + idx + half];

                    // Inverse rotation
                    out[base + idx] = x * cos_a + y * sin_a;
                    out[base + idx + half] = -x * sin_a + y * cos_a;
                }
            }

            // Handle remainder
            for j in 0..remainder {
                let idx = chunks * 4 + j;
                let angle = pos * freqs[idx];
                let cos_a = angle.cos();
                let sin_a = angle.sin();

                let x = out[base + idx];
                let y = out[base + idx + half];

                out[base + idx] = x * cos_a + y * sin_a;
                out[base + idx + half] = -x * sin_a + y * cos_a;
            }
        }

        out
    }

    /// Re-rotate keys with new positions after compaction.
    ///
    /// # Arguments
    /// * `keys` - Position-free keys in f32, shape `[seq_len * head_dim]`
    /// * `new_start_pos` - New starting position for the compacted sequence
    ///
    /// # Returns
    /// Re-rotated keys in f16.
    ///
    /// Forward rotation:
    ///   x_new = x*cos(θ) - y*sin(θ)
    ///   y_new = x*sin(θ) + y*cos(θ)
    pub fn re_rotate_keys(&self, keys: &[f32], new_start_pos: usize) -> Vec<f16> {
        if self.head_dim == 0 || keys.is_empty() {
            return Vec::new();
        }

        let head_dim = self.head_dim;
        let half = head_dim / 2;
        let seq_len = keys.len() / head_dim;

        // Work in f32, convert to f16 at the end
        let mut buf = keys.to_vec();

        // Use cached frequency table (built once at construction).
        let freqs = &self.freqs;

        // For each token at position p, apply forward rotation
        for t in 0..seq_len {
            let pos = (new_start_pos + t) as f32;
            let base = t * head_dim;

            let chunks = half / 4;
            let remainder = half % 4;

            for c in 0..chunks {
                let i = c * 4;

                for j in 0..4 {
                    let idx = i + j;
                    let angle = pos * freqs[idx];
                    let cos_a = angle.cos();
                    let sin_a = angle.sin();

                    let x = buf[base + idx];
                    let y = buf[base + idx + half];

                    // Forward rotation
                    buf[base + idx] = x * cos_a - y * sin_a;
                    buf[base + idx + half] = x * sin_a + y * cos_a;
                }
            }

            for j in 0..remainder {
                let idx = chunks * 4 + j;
                let angle = pos * freqs[idx];
                let cos_a = angle.cos();
                let sin_a = angle.sin();

                let x = buf[base + idx];
                let y = buf[base + idx + half];

                buf[base + idx] = x * cos_a - y * sin_a;
                buf[base + idx + half] = x * sin_a + y * cos_a;
            }
        }

        // Convert f32 → f16
        buf.iter().map(|&v| f16::from_f32(v)).collect()
    }

    /// Compute the position offset for the compacted cache.
    ///
    /// After compaction, compacted tokens occupy positions `[new_start_pos..new_start_pos+compact_len]`.
    /// For RoPE continuation, new tokens should start at `original_start + original_len`.
    /// Therefore: `position_offset = original_start + original_len - compact_len`.
    ///
    /// This is the `position_offset` field in `CompactKVCache`.
    pub fn compute_position_offset(
        &self,
        original_start: usize,
        original_len: usize,
        compact_len: usize,
    ) -> usize {
        if compact_len == 0 {
            return original_start;
        }
        original_start
            .saturating_add(original_len)
            .saturating_sub(compact_len)
    }
}

impl QueryBank for ClusterQueryBank {
    fn generate_queries(&self, kv_cache: &[f32], budget: usize) -> Vec<f32> {
        let kv_dim = self.latent_dim;
        let seq_len = if kv_dim == 0 {
            0
        } else {
            kv_cache.len() / kv_dim
        };

        if seq_len == 0 || budget == 0 || kv_dim == 0 {
            return vec![0.0f32; budget * self.latent_dim];
        }

        let n = budget.min(seq_len);

        // --- k-means++ initialization ---
        let mut centroids: Vec<Vec<f32>> = Vec::with_capacity(n);

        // First centroid: token 0
        centroids.push(token_to_latent(kv_cache, 0, kv_dim, self.latent_dim));

        // For deterministic results without RNG, use a simple linear congruential
        // generator seeded from the data.
        let mut seed: u64 = 42;
        for _ in 1..n {
            // Compute squared distance from each point to its nearest centroid.
            // Use borrowed slices (no per-token Vec allocation) — this is the hot
            // k-means++ init loop.
            let min_dists: Vec<f32> = (0..seq_len)
                .map(|t| {
                    let point = token_slice(kv_cache, t, kv_dim);
                    centroids
                        .iter()
                        .map(|c| sq_dist(point, c))
                        .fold(f32::INFINITY, f32::min)
                })
                .collect();

            // Convert to cumulative distribution
            let total: f32 = min_dists.iter().sum();
            if total < 1e-12 {
                // All points coincident — pick next token linearly
                centroids.push(token_to_latent(
                    kv_cache,
                    centroids.len().min(seq_len - 1),
                    kv_dim,
                    self.latent_dim,
                ));
                continue;
            }

            // Simple LCG for deterministic "random" selection
            seed = seed.wrapping_mul(6_364_136_223_846_793_005).wrapping_add(1);
            let r = (seed as f32 / u64::MAX as f32) * total;

            let mut cumsum = 0.0f32;
            let mut chosen = seq_len - 1;
            for (i, &d) in min_dists.iter().enumerate() {
                cumsum += d;
                if cumsum >= r {
                    chosen = i;
                    break;
                }
            }
            centroids.push(token_to_latent(kv_cache, chosen, kv_dim, self.latent_dim));
        }

        // --- k-means iterations (max 10) ---
        let max_iters = 10;
        let mut assignments = vec![0usize; seq_len];
        // Reusable scratch buffers — allocated once, zeroed each iteration.
        // Avoids `vec![vec![0.0; latent_dim]; n]` allocation every iteration.
        let mut sums = vec![0.0f32; n * self.latent_dim];
        let mut counts = vec![0usize; n];

        for _ in 0..max_iters {
            // Assign each point to nearest centroid (borrowed slices, no alloc)
            let mut changed = false;
            for (t, slot) in assignments.iter_mut().enumerate() {
                let point = token_slice(kv_cache, t, kv_dim);
                let (best_idx, _) = centroids
                    .iter()
                    .enumerate()
                    .map(|(i, c)| (i, sq_dist(point, c)))
                    .fold(
                        (0, f32::INFINITY),
                        |acc, (i, d)| if d < acc.1 { (i, d) } else { acc },
                    );
                if *slot != best_idx {
                    changed = true;
                    *slot = best_idx;
                }
            }

            if !changed {
                break;
            }

            // Update centroids as mean of assigned points
            sums.fill(0.0);
            counts.fill(0);
            for (t, &c) in assignments.iter().enumerate() {
                let point = token_slice(kv_cache, t, kv_dim);
                let sum_row = &mut sums[c * self.latent_dim..(c + 1) * self.latent_dim];
                for (s, p) in sum_row.iter_mut().zip(point.iter()) {
                    *s += p;
                }
                counts[c] += 1;
            }
            for (c, cnt) in counts.iter().enumerate() {
                if *cnt > 0 {
                    let inv = 1.0f32 / *cnt as f32;
                    let sum_row = &sums[c * self.latent_dim..(c + 1) * self.latent_dim];
                    for (cent, sum_val) in centroids[c].iter_mut().zip(sum_row.iter()) {
                        *cent = sum_val * inv;
                    }
                }
            }
        }

        // Flatten centroids into output
        let mut out = Vec::with_capacity(budget * self.latent_dim);
        for c in &centroids {
            out.extend_from_slice(c);
        }
        // Pad if budget > n (shouldn't happen but be safe)
        while out.len() < budget * self.latent_dim {
            out.extend_from_slice(&centroids[out.len() / self.latent_dim % n]);
        }
        out
    }
}

impl QueryBank for AttentionQueryBank {
    fn generate_queries(&self, kv_cache: &[f32], budget: usize) -> Vec<f32> {
        let kv_dim = self.latent_dim;
        let seq_len = if kv_dim == 0 {
            0
        } else {
            kv_cache.len() / kv_dim
        };

        if seq_len == 0 || budget == 0 || kv_dim == 0 {
            return vec![0.0f32; budget * self.latent_dim];
        }

        // Compute importance = sum of absolute values per token
        let mut importance: Vec<f32> = (0..seq_len)
            .map(|t| {
                let start = t * kv_dim;
                let end = (start + kv_dim).min(kv_cache.len());
                kv_cache[start..end].iter().map(|x| x.abs()).sum()
            })
            .collect();

        // Normalize to probability distribution
        let total: f32 = importance.iter().sum();
        if total < 1e-12 {
            // Uniform sampling fallback
            return sample_uniform(kv_cache, budget, seq_len, kv_dim, self.latent_dim);
        }

        let inv_total = 1.0 / total;
        for w in &mut importance {
            *w *= inv_total;
        }

        // Sample `budget` tokens proportional to importance using deterministic LCG.
        // `remaining_importance` is never mutated (importance stays — see comment below),
        // so `rem_total` is constant across iterations and can be hoisted out of the loop.
        // This also lets us drop the `importance.clone()` allocation.
        let rem_total: f32 = importance.iter().sum();
        if rem_total < 1e-12 {
            // Uniform sampling fallback
            return sample_uniform(kv_cache, budget, seq_len, kv_dim, self.latent_dim);
        }

        let mut seed: u64 = 12345;
        let mut chosen = Vec::with_capacity(budget);

        for _ in 0..budget {
            seed = seed.wrapping_mul(6_364_136_223_846_793_005).wrapping_add(1);
            let r = (seed as f32 / u64::MAX as f32) * rem_total;

            let mut cumsum = 0.0f32;
            let mut idx = seq_len - 1;
            for (i, &w) in importance.iter().enumerate() {
                cumsum += w;
                if cumsum >= r {
                    idx = i;
                    break;
                }
            }
            chosen.push(idx);
            // Don't remove — allow re-sampling for simplicity (importance stays)
        }

        // Pad if we didn't get enough (edge case)
        while chosen.len() < budget {
            chosen.push(chosen.len() % seq_len);
        }

        let mut out = Vec::with_capacity(budget * self.latent_dim);
        for &idx in &chosen[..budget] {
            out.extend_from_slice(&token_to_latent(kv_cache, idx, kv_dim, self.latent_dim));
        }
        out
    }
}

impl QueryBank for SpectralQueryBank {
    fn generate_queries(&self, kv_cache: &[f32], budget: usize) -> Vec<f32> {
        let kv_dim = self.latent_dim;
        let seq_len = if kv_dim == 0 {
            0
        } else {
            kv_cache.len() / kv_dim
        };

        if seq_len == 0 || budget == 0 || kv_dim == 0 {
            return vec![0.0f32; budget * self.latent_dim];
        }

        // Compute per-token variance across kv_dim
        let mut variances: Vec<(usize, f32)> = (0..seq_len)
            .map(|t| {
                let start = t * kv_dim;
                let end = (start + kv_dim).min(kv_cache.len());
                let slice = &kv_cache[start..end];
                let n = slice.len() as f32;
                if n < 1.0 {
                    (t, 0.0)
                } else {
                    let mean: f32 = slice.iter().sum::<f32>() / n;
                    let var: f32 = slice.iter().map(|x| (x - mean) * (x - mean)).sum::<f32>() / n;
                    (t, var)
                }
            })
            .collect();

        // Sort descending by variance
        variances.sort_by(|a, b| b.1.total_cmp(&a.1));

        // Take top `budget` tokens and normalize each to unit length
        let mut out = Vec::with_capacity(budget * self.latent_dim);
        for i in 0..budget {
            let token_idx = variances[i % seq_len].0;
            let mut vec = token_to_latent(kv_cache, token_idx, kv_dim, self.latent_dim);
            let norm = sq_norm(&vec).sqrt().max(1e-8);
            let inv_norm = 1.0 / norm;
            for v in &mut vec {
                *v *= inv_norm;
            }
            out.extend_from_slice(&vec);
        }
        out
    }
}

impl QueryBank for BfcfQueryBank {
    fn generate_queries(&self, kv_cache: &[f32], budget: usize) -> Vec<f32> {
        let kv_dim = self.latent_dim;
        let seq_len = if kv_dim == 0 {
            0
        } else {
            kv_cache.len() / kv_dim
        };

        if seq_len == 0 || budget == 0 || kv_dim == 0 {
            return vec![0.0f32; budget * self.latent_dim];
        }

        let num_regions = budget.min(seq_len);
        let chunk_size = seq_len.div_ceil(num_regions); // ceil div

        // Compute centroid for each region
        let mut regions: Vec<Vec<f32>> = Vec::with_capacity(num_regions);
        for r in 0..num_regions {
            let start_tok = r * chunk_size;
            let end_tok = (start_tok + chunk_size).min(seq_len);
            if start_tok >= seq_len {
                break;
            }
            let count = (end_tok - start_tok) as f32;
            let mut centroid = vec![0.0f32; self.latent_dim];
            for t in start_tok..end_tok {
                let token = token_slice(kv_cache, t, kv_dim);
                for (c, v) in centroid.iter_mut().zip(token.iter()) {
                    *c += v;
                }
            }
            if count > 0.0 {
                let inv = 1.0 / count;
                for c in &mut centroid {
                    *c *= inv;
                }
            }
            regions.push(centroid);
        }

        // Build output: if fewer regions than budget, cycle; if more, take top by magnitude
        let mut out = Vec::with_capacity(budget * self.latent_dim);

        if regions.len() >= budget {
            // Sort regions by magnitude (L2 norm) descending, take top budget
            let mut indexed: Vec<(usize, f32)> = regions
                .iter()
                .enumerate()
                .map(|(i, r)| (i, sq_norm(r)))
                .collect();
            indexed.sort_by(|a, b| b.1.total_cmp(&a.1));
            for &(idx, _) in &indexed[..budget] {
                out.extend_from_slice(&regions[idx]);
            }
        } else {
            // Cycle through available regions to fill budget
            for i in 0..budget {
                out.extend_from_slice(&regions[i % regions.len()]);
            }
        }

        out
    }
}

impl QueryBank for MuxQueryBank {
    fn generate_queries(&self, _kv_cache: &[f32], budget: usize) -> Vec<f32> {
        if budget == 0 || self.latent_dim == 0 {
            return vec![0.0f32; budget * self.latent_dim];
        }

        let scale = 1.0 / (self.latent_dim as f32).sqrt();
        let mut out = Vec::with_capacity(budget * self.latent_dim);

        for i in 0..budget {
            for j in 0..self.latent_dim {
                // Deterministic sign pattern using FNV-like mixing:
                // hash = i ^ (i >> 3) ^ (j << 5) ^ j
                // Then use bit parity for the sign.
                // This decorrelates different (i, j) pairs more effectively
                // than simple multiplication.
                let mut h: u64 = (i as u64)
                    .wrapping_mul(0x9E3779B97F4A7C15)
                    .wrapping_add(j as u64)
                    .wrapping_mul(0xC6EF43637C9E1B5A);
                h ^= h >> 33;
                h = h.wrapping_mul(0xFF51AFD7ED558CCD);
                h ^= h >> 33;
                let sign: f32 = if h.count_ones().is_multiple_of(2) {
                    scale
                } else {
                    -scale
                };
                out.push(sign);
            }
        }

        out
    }
}

impl PrecisionBudget {
    /// Create uniform budget: all heads get the same bit-width.
    pub fn uniform(num_layers: usize, num_heads: usize, bits_per_head: u8) -> Self {
        let total = num_layers * num_heads;
        Self {
            head_bits: vec![bits_per_head; total],
            budget: bits_per_head as f32,
            num_layers,
            num_heads,
            sensitivity: vec![1.0; total],
        }
    }

    /// Get bits for a specific head.
    pub fn get_bits(&self, layer: usize, head: usize) -> u8 {
        self.head_bits[layer * self.num_heads + head]
    }

    /// Compute budget from sensitivity analysis.
    /// Greedy allocation: sort heads by sensitivity, allocate budget to most sensitive first.
    /// Total bits must equal budget * total_heads (same total as uniform).
    pub fn compute_budget(
        num_layers: usize,
        num_heads: usize,
        sensitivity: &[f32],
        target_budget: f32,
    ) -> Self {
        let total = num_layers * num_heads;
        let total_bits = (target_budget * total as f32) as u32;

        // Sort heads by sensitivity (descending)
        let mut indices: Vec<usize> = (0..total).collect();
        indices.sort_by(|&a, &b| sensitivity[b].total_cmp(&sensitivity[a]));

        // Greedy allocation: min 1 bit, max 8 bits per head
        let mut head_bits = vec![1u8; total];
        let mut allocated: u32 = total as u32; // 1 bit per head minimum

        // Distribute remaining bits greedily
        for &idx in &indices {
            if allocated >= total_bits {
                break;
            }
            let remaining = total_bits - allocated;
            let max_extra = 7u8.min(remaining as u8); // max 8 total, already have 1
            let extra = if sensitivity[idx] > 0.5 {
                max_extra.min(3) // high sensitivity: up to 4 bits
            } else if sensitivity[idx] > 0.2 {
                max_extra.min(2) // medium: up to 3 bits
            } else {
                max_extra.min(1) // low: up to 2 bits
            };
            head_bits[idx] += extra;
            allocated += extra as u32;
        }

        // Clamp total to budget
        let actual_budget = allocated as f32 / total as f32;

        Self {
            head_bits,
            budget: actual_budget,
            num_layers,
            num_heads,
            sensitivity: sensitivity.to_vec(),
        }
    }

    /// Compute total KV cache size in bits.
    pub fn total_kv_bits(&self, seq_len: usize, head_dim: usize) -> u64 {
        let per_bit = seq_len as u64 * head_dim as u64;
        self.head_bits
            .iter()
            .map(|&bits| bits as u64 * per_bit)
            .sum()
    }

    /// Verify budget constraint: average bits <= budget.
    pub fn verify_budget(&self) -> bool {
        let avg: f32 =
            self.head_bits.iter().map(|&b| b as f32).sum::<f32>() / self.head_bits.len() as f32;
        avg <= self.budget * 1.01 // 1% tolerance for rounding
    }
}

impl MicroRecurrentBeliefState for AttractorKernel {
    #[inline]
    fn dim(&self) -> usize {
        self.dim
    }

    /// Advance one tick: `state[i] = clamp(2·σ(W_s[i]·s + W_x[i]·x + b[i]) − 1, ±clamp)`.
    ///
    /// # Hot-path properties
    ///
    /// - Zero allocation: writes in-place to `state`.
    /// - Deterministic: `simd_dot_f32` and `fast_sigmoid` are both deterministic
    ///   across runs (G1.1).
    /// - Auto-vectorisable: each row is a length-`dim` dot product dispatched to
    ///   `simd_dot_f32`; the outer loop over `dim` rows is chunkable.
    ///
    /// # Range
    ///
    /// Output is in `(−1, 1)` (modulo the no-op clamp at `±6`). See the
    /// module-level docs for why this range was chosen.
    #[inline]
    fn step(&self, state: &mut [f32], input: &[f32]) {
        debug_assert_eq!(state.len(), self.dim, "state/dim mismatch");
        debug_assert_eq!(input.len(), self.dim, "input/dim mismatch");
        let dim = self.dim;
        let clamp = self.clamp;

        // We must not mutate `state` in-place while reading it for the matvec,
        // because row i reads state[j] for all j (including j != i). The
        // dim=32 f32 vector (128 bytes) fits comfortably on the stack.
        //
        // `next` serves double duty: first as the pre-sigmoid activation
        // buffer (dot_ws + dot_wx + b), then as the output of the
        // sigmoid→tanh→clamp pass. The matvec addition order
        // (dot_ws + dot_wx + b) is preserved bit-for-bit. The SIMD sigmoid
        // helper reads a[i] and writes out[i] in the same 4-wide chunk, so
        // in-place aliasing is safe (read completes before write per chunk).
        // Uninitialized 4KB stack buffer — we overwrite next[..dim] via the
        // matvec before any read (the sigmoid pass). Skipping the O(dim) zero-
        // init saves ~40ns/step at dim=32 (Issue 024). Matches the pattern in
        // `katgpt-rs/src/cumprodsum.rs::segsum`.
        let mut next_buf = uninit_stack::<1024>();
        // SAFETY: we write next[..dim] via the matvec below before any read.
        let next: &mut [f32] = unsafe { assume_init_slice(&mut next_buf, dim) };

        // Process rows in chunks of 4 to give LLVM a clear auto-vec hint on
        // the outer loop. The inner reductions are dispatched to simd_dot_f32.
        // Four independent accumulators per pass hide FMA pipeline latency.
        let mut i = 0;
        while i + 4 <= dim {
            // Row slices for W_s and W_x — computed once per row.
            let ws_r0 = &self.ws[i * dim..(i + 1) * dim];
            let ws_r1 = &self.ws[(i + 1) * dim..(i + 2) * dim];
            let ws_r2 = &self.ws[(i + 2) * dim..(i + 3) * dim];
            let ws_r3 = &self.ws[(i + 3) * dim..(i + 4) * dim];
            let wx_r0 = &self.wx[i * dim..(i + 1) * dim];
            let wx_r1 = &self.wx[(i + 1) * dim..(i + 2) * dim];
            let wx_r2 = &self.wx[(i + 2) * dim..(i + 3) * dim];
            let wx_r3 = &self.wx[(i + 3) * dim..(i + 4) * dim];

            // 4 independent dot products over state, 4 over input — FMA-bound.
            let dot_ws_0 = simd_dot_f32(state, ws_r0, dim);
            let dot_ws_1 = simd_dot_f32(state, ws_r1, dim);
            let dot_ws_2 = simd_dot_f32(state, ws_r2, dim);
            let dot_ws_3 = simd_dot_f32(state, ws_r3, dim);
            let dot_wx_0 = simd_dot_f32(input, wx_r0, dim);
            let dot_wx_1 = simd_dot_f32(input, wx_r1, dim);
            let dot_wx_2 = simd_dot_f32(input, wx_r2, dim);
            let dot_wx_3 = simd_dot_f32(input, wx_r3, dim);

            // Pre-sigmoid activation = W_s·s + W_x·x + b.
            // Addition order MUST stay (dot_ws + dot_wx) + b — do not rearrange
            // (Plan 281 G1.3 bit-identical degeneracy with sample_k_states).
            next[i] = dot_ws_0 + dot_wx_0 + self.b[i];
            next[i + 1] = dot_ws_1 + dot_wx_1 + self.b[i + 1];
            next[i + 2] = dot_ws_2 + dot_wx_2 + self.b[i + 2];
            next[i + 3] = dot_ws_3 + dot_wx_3 + self.b[i + 3];
            i += 4;
        }
        // Tail: remaining rows (dim mod 4).
        while i < dim {
            let ws_row = &self.ws[i * dim..(i + 1) * dim];
            let wx_row = &self.wx[i * dim..(i + 1) * dim];
            let dot_ws = simd_dot_f32(state, ws_row, dim);
            let dot_wx = simd_dot_f32(input, wx_row, dim);
            next[i] = dot_ws + dot_wx + self.b[i];
            i += 1;
        }

        // Apply the state-writeback chain: (2·σ(·) − 1).clamp(−clamp, clamp).
        //
        // Under `simd_sigmoid`: a single fused NEON/AVX2 pass over `dim`
        // elements replaces `dim` scalar fast_sigmoid calls. `next` is both
        // the input (pre-sigmoid activation) and output — safe because the
        // SIMD helper reads a[i] and writes out[i] within the same chunk
        // (the vld1q completes before vst1q per 4-element group). q is zero
        // in step() (no noise query) — ZERO_BUF makes the call signature
        // identical to sample_k_states with zero queries, preserving G1.3.
        //
        // Under the default (scalar) path: per-element fast_sigmoid, bit-for-bit
        // unchanged from the pre-simd_sigmoid implementation.
        #[cfg(feature = "simd_sigmoid")]
        {
            // SAFETY: `next` aliases as both `a` (read) and `out` (write). The
            // SIMD helper processes 4 (NEON) or 8 (AVX2) elements per chunk:
            // it loads a[i..i+W] into a register, computes, then stores to
            // out[i..i+W]. No chunk reads elements written by a later chunk,
            // so the aliasing is data-race-free.
            let len = dim;
            let ptr = next.as_mut_ptr();
            let a_slice: &[f32] = unsafe { core::slice::from_raw_parts(ptr, len) };
            let out_slice: &mut [f32] = unsafe { core::slice::from_raw_parts_mut(ptr, len) };
            simd_sigmoid_tanh_clamp_inplace(out_slice, a_slice, &ZERO_BUF[..dim], clamp);
        }
        #[cfg(not(feature = "simd_sigmoid"))]
        {
            for v in next[..dim].iter_mut() {
                *v = (2.0 * fast_sigmoid(*v) - 1.0).clamp(-clamp, clamp);
            }
        }

        // Write back in one pass — avoids read-after-write hazards on `state`
        // (we read all of `state` to compute each row; mutating in place would
        // poison later rows).
        state[..dim].copy_from_slice(&next[..dim]);
    }

    #[inline(always)]
    fn project_to_scalars(&self, state: &[f32], directions: &[f32], dim: usize, out: &mut [f32]) {
        bridge_project(state, directions, dim, out);
    }

    #[inline]
    fn family(&self) -> RecurrenceFamily {
        RecurrenceFamily::Attractor
    }
}

impl BoMSampler for AttractorKernel {
    /// Single-pass K-hypothesis sampling for Family A.
    ///
    /// Computes the base activation `act[i] = W_s[i]·s + W_x[i]·x + b[i]` once
    /// (mirroring [`AttractorKernel::step`] exactly — same chunked-4 outer
    /// loop, same `simd_dot_f32` reductions), then perturbs elementwise for
    /// each of K queries.
    ///
    /// # G1.3 (σ=0 degeneracy)
    ///
    /// With all-zero `queries`, the output is bit-identical to `step()` because
    /// `act[i] + 0.0 == act[i]` (f32 addition with +0.0 is exact) and the
    /// sigmoid/clamp chain is the same deterministic path.
    #[inline]
    fn sample_k_states(
        &self,
        s_prev: &[f32],
        x: &[f32],
        queries: &[f32],
        out: &mut [f32],
        cfg: &NoiseQueryConfig,
    ) {
        let dim = self.dim;
        let clamp = self.clamp;
        let k = cfg.k;

        debug_assert_eq!(s_prev.len(), dim, "s_prev/dim mismatch");
        debug_assert_eq!(x.len(), dim, "x/dim mismatch");
        debug_assert!(
            queries.len() >= k * dim,
            "queries too short: need {} have {}",
            k * dim,
            queries.len()
        );
        debug_assert!(
            out.len() >= k * dim,
            "out too short: need {} have {}",
            k * dim,
            out.len()
        );

        // ── Phase 1: base activation (computed ONCE, bit-identical to step()) ──
        //
        // Stack buffer — supports dim ≤ 1024 (same cap as AttractorKernel::step).
        // Uninit (matches cumprodsum.rs pattern) — act[..dim] is written by
        // the matvec below before the Phase 2 sigmoid reads it.
        let mut act_buf = uninit_stack::<1024>();
        // SAFETY: act[..dim] is fully written by the matvec below before any read.
        let act: &mut [f32] = unsafe { assume_init_slice(&mut act_buf, dim) };

        // Chunked-4 outer loop — mirrors AttractorKernel::step exactly so the
        // dot-product reductions and FMA scheduling produce the same f32
        // intermediates. Four independent dot-pairs hide FMA latency.
        let mut i = 0usize;
        while i + 4 <= dim {
            let ws_r0 = &self.ws[i * dim..(i + 1) * dim];
            let ws_r1 = &self.ws[(i + 1) * dim..(i + 2) * dim];
            let ws_r2 = &self.ws[(i + 2) * dim..(i + 3) * dim];
            let ws_r3 = &self.ws[(i + 3) * dim..(i + 4) * dim];
            let wx_r0 = &self.wx[i * dim..(i + 1) * dim];
            let wx_r1 = &self.wx[(i + 1) * dim..(i + 2) * dim];
            let wx_r2 = &self.wx[(i + 2) * dim..(i + 3) * dim];
            let wx_r3 = &self.wx[(i + 3) * dim..(i + 4) * dim];

            let dot_ws_0 = simd_dot_f32(s_prev, ws_r0, dim);
            let dot_ws_1 = simd_dot_f32(s_prev, ws_r1, dim);
            let dot_ws_2 = simd_dot_f32(s_prev, ws_r2, dim);
            let dot_ws_3 = simd_dot_f32(s_prev, ws_r3, dim);
            let dot_wx_0 = simd_dot_f32(x, wx_r0, dim);
            let dot_wx_1 = simd_dot_f32(x, wx_r1, dim);
            let dot_wx_2 = simd_dot_f32(x, wx_r2, dim);
            let dot_wx_3 = simd_dot_f32(x, wx_r3, dim);

            // Same addition order as step(): (dot_ws + dot_wx) + b.
            act[i] = dot_ws_0 + dot_wx_0 + self.b[i];
            act[i + 1] = dot_ws_1 + dot_wx_1 + self.b[i + 1];
            act[i + 2] = dot_ws_2 + dot_wx_2 + self.b[i + 2];
            act[i + 3] = dot_ws_3 + dot_wx_3 + self.b[i + 3];
            i += 4;
        }
        // Tail: remaining rows (dim mod 4).
        while i < dim {
            let ws_row = &self.ws[i * dim..(i + 1) * dim];
            let wx_row = &self.wx[i * dim..(i + 1) * dim];
            let dot_ws = simd_dot_f32(s_prev, ws_row, dim);
            let dot_wx = simd_dot_f32(x, wx_row, dim);
            act[i] = dot_ws + dot_wx + self.b[i];
            i += 1;
        }

        // ── Phase 2: K elementwise perturbations ──
        //
        // For each hypothesis k, add the noise query to the pre-sigmoid
        // activation, apply 2·σ(·)−1, clamp.
        //
        // Under `simd_sigmoid`: a single fused NEON/AVX2 pass per k replaces
        // the inner dim-loop. The call signature
        //   simd_sigmoid_tanh_clamp_inplace(out, act, queries, clamp)
        // is bit-identical to step()'s call when queries is all-zero (q[i]=0.0,
        // f32 addition is exact) — preserving Plan 281 G1.3.
        //
        // Under the default (scalar) path: per-element fast_sigmoid loop,
        // bit-for-bit unchanged from the pre-simd_sigmoid implementation.
        #[cfg(feature = "simd_sigmoid")]
        for k_idx in 0..k {
            let q_base = k_idx * dim;
            let out_base = k_idx * dim;
            simd_sigmoid_tanh_clamp_inplace(
                &mut out[out_base..out_base + dim],
                &act[..dim],
                &queries[q_base..q_base + dim],
                clamp,
            );
        }
        #[cfg(not(feature = "simd_sigmoid"))]
        for k_idx in 0..k {
            let q_base = k_idx * dim;
            let out_base = k_idx * dim;
            for j in 0..dim {
                let a = act[j] + queries[q_base + j];
                out[out_base + j] = (2.0 * fast_sigmoid(a) - 1.0).clamp(-clamp, clamp);
            }
        }
    }

    #[inline]
    fn select_best(&self, hypotheses: &[f32], scorer: impl Fn(&[f32]) -> f32, k: usize) -> usize {
        select_best_generic(hypotheses, scorer, k, self.dim)
    }
}

impl ArenaAction {
    /// All action variants, in discriminant order. Used by exhaustive planners.
    pub const ALL: [Self; 5] = [
        Self::Hold,
        Self::EvadePosX,
        Self::EvadeNegX,
        Self::EvadePosY,
        Self::EvadeNegY,
    ];

    /// Map an action to a 2-D unit evade vector (used by the synthetic arena).
    #[inline]
    pub fn evade_vec(self) -> [f32; 2] {
        match self {
            Self::Hold => [0.0, 0.0],
            Self::EvadePosX => [1.0, 0.0],
            Self::EvadeNegX => [-1.0, 0.0],
            Self::EvadePosY => [0.0, 1.0],
            Self::EvadeNegY => [0.0, -1.0],
        }
    }
}

