impl SyntheticThreatArena {
    /// Construct with `dim` and `max_ticks`. `max_hits` defaults to
    /// `max_ticks / 2` (so the NPC can survive if it evades ~half the threats).
    pub fn new(dim: usize, max_ticks: usize) -> Self {
        assert!(dim >= 2, "SyntheticThreatArena requires dim >= 2");
        // Guard against max_ticks == 0 to avoid div-by-zero in the cached reciprocal.
        let inv_max_ticks = if max_ticks == 0 {
            0.0
        } else {
            1.0 / max_ticks as f32
        };
        Self {
            obs: vec![0.0; dim],
            tick_idx: 0,
            max_ticks,
            inv_max_ticks,
            hits_taken: 0,
            max_hits: (max_ticks / 2).max(1) as u32,
            current_threat: [0.0, 0.0],
            last_action: ArenaAction::Hold,
            rng: fastrand::Rng::with_seed(0),
            reward: 0.0,
        }
    }

    /// Override `max_hits`.
    pub fn with_max_hits(mut self, max_hits: u32) -> Self {
        self.max_hits = max_hits;
        self
    }
}

impl ArenaEnvironment for SyntheticThreatArena {
    fn observe(&self) -> &[f32] {
        &self.obs
    }

    #[inline]
    fn apply_action(&mut self, action: ArenaAction) {
        self.last_action = action;
    }

    fn tick(&mut self) {
        // Score the prior action: if the true threat this tick had positive
        // dot with the action's evade, the NPC evaded; otherwise it was hit.
        let evade = self.last_action.evade_vec();
        let evasion_dot = evade[0] * self.current_threat[0] + evade[1] * self.current_threat[1];
        if evasion_dot <= 0.0 && (self.current_threat[0] != 0.0 || self.current_threat[1] != 0.0) {
            self.hits_taken += 1;
        } else if evasion_dot > 0.0 {
            // Successfully evaded a real threat. Use cached reciprocal to
            // replace `divss` with `mulss` on the hot tick path.
            self.reward += self.inv_max_ticks;
        }

        self.tick_idx += 1;

        // Generate next observation: noisy estimate of the *next* threat.
        // Threats are temporally correlated (Markov: 80% chance the next
        // threat matches the current direction, 20% random). This is what
        // makes the kernel's belief state predictive — a single-tick kernel
        // can learn "current threat direction is sticky", and BoM's K
        // hypotheses become K plausible continuations of that direction.
        // Without correlation the kernel has no predictive signal and BoM
        // degenerates to noise (the harness would be measuring noise, not
        // planning quality).
        let r = self.rng.f32();
        let (tx, ty) = if r < 0.20 {
            // 20%: pick a fresh random cardinal direction.
            match self.rng.u32(0..4) {
                0 => (1.0, 0.0),
                1 => (-1.0, 0.0),
                2 => (0.0, 1.0),
                _ => (0.0, -1.0),
            }
        } else if self.current_threat[0] == 0.0 && self.current_threat[1] == 0.0 {
            // Currently no threat — pick a fresh one.
            match self.rng.u32(0..4) {
                0 => (1.0, 0.0),
                1 => (-1.0, 0.0),
                2 => (0.0, 1.0),
                _ => (0.0, -1.0),
            }
        } else {
            // 80%: keep the current direction (temporal correlation).
            (self.current_threat[0], self.current_threat[1])
        };
        // 25% chance of no threat at all (Hold should be safe sometimes).
        let threat_mag = if self.rng.f32() < 0.75 { 1.0 } else { 0.0 };
        let tx = tx * threat_mag;
        let ty = ty * threat_mag;
        // Store the TRUE next threat (used when scoring the NEXT tick).
        self.current_threat = [tx, ty];
        // Observation: noisy estimate (±0.3 jitter per axis, clamped to [-1,1]).
        // Tuned for harness-mechanics validation — deterministic and BoM both
        // produce non-degenerate scores. The real G2 quality gate runs in
        // riir-ai against a richer arena where BoM's K-hypothesis denoising
        // and multi-tick integration genuinely add value.
        let jx = (tx + (self.rng.f32() * 0.6 - 0.3)).clamp(-1.0, 1.0);
        let jy = (ty + (self.rng.f32() * 0.6 - 0.3)).clamp(-1.0, 1.0);
        self.obs[0] = jx;
        self.obs[1] = jy;
        // Remaining dims: low-magnitude signal (so the kernel's full input
        // is exercised but doesn't dominate the threat signal).
        for v in self.obs[2..].iter_mut() {
            *v = self.rng.f32() * 0.2 - 0.1;
        }
    }

    fn episode_score(&self) -> f32 {
        // Score in [0, 1]: 1 = no hits, 0 = max_hits taken. Combine with
        // accumulated evasion reward so partial-credit episodes rank.
        let hit_penalty = self.hits_taken as f32 / self.max_hits as f32;
        (1.0 - hit_penalty).max(0.0) * 0.5 + self.reward.clamp(0.0, 1.0) * 0.5
    }

    fn is_terminal(&self) -> bool {
        self.tick_idx >= self.max_ticks || self.hits_taken >= self.max_hits
    }

    fn reset(&mut self, seed: u64) {
        self.tick_idx = 0;
        self.hits_taken = 0;
        self.reward = 0.0;
        self.last_action = ArenaAction::Hold;
        self.current_threat = [0.0, 0.0];
        self.rng = fastrand::Rng::with_seed(seed);
        // First observation is generated by the first `tick()` call; seed the
        // obs buffer with zeros so `observe()` is well-defined before tick.
        self.obs.fill(0.0);
        // Run one tick to produce the initial observation.
        self.tick();
        // Reset tick_idx to 0 (the priming tick above bumped it to 1).
        self.tick_idx = 0;
    }
}

impl PlannerOutcome {
    /// Throughput in episodes per second.
    pub fn eps(&self) -> f32 {
        if self.total_us == 0 {
            0.0
        } else {
            (self.n_episodes as f32) * 1e6 / self.total_us as f32
        }
    }
}

impl ComparisonResult {
    /// Human-readable summary.
    pub fn summary(&self) -> String {
        format!(
            "G2 arena comparison: {} vs {}\n  \
             baseline:   mean={:.4}  win_rate={:.4}  eps={:.1}\n  \
             candidate:  mean={:.4}  win_rate={:.4}  eps={:.1}\n  \
             Δ score:    {:+.3} pp\n  \
             Δ win_rate: {:+.3} pp\n  \
             latency:    {:.3}× baseline (candidate)",
            self.baseline.name,
            self.candidate.name,
            self.baseline.mean_score,
            self.baseline.win_rate,
            self.baseline.eps(),
            self.candidate.mean_score,
            self.candidate.win_rate,
            self.candidate.eps(),
            self.delta_pp,
            self.win_rate_delta_pp,
            self.latency_ratio,
        )
    }

    /// Whether the candidate cleared the G2 gate (≥ +5pp win-rate or score).
    pub fn passes_g2(&self, threshold_pp: f32) -> bool {
        self.delta_pp >= threshold_pp || self.win_rate_delta_pp >= threshold_pp
    }
}

use crate::types::project_to_scalars_bridge as impl_bridge;

/// Project a belief vector to K bounded scalars via sigmoid(dot).
///
/// For each `k` in `0..out.len()`:
///
/// ```text
/// out[k] = fast_sigmoid( simd_dot_f32(state, &directions[k*dim .. (k+1)*dim], dim) )
/// ```
///
/// # Arguments
///
/// - `state` — the belief vector `s_t`, length `dim`. Latent.
/// - `directions` — flattened `[K * dim]` row-major slice of projection
///   direction vectors. Latent, caller-owned, never synced.
/// - `dim` — the belief-vector dimension (must equal `state.len()` and the row
///   stride of `directions`).
/// - `out` — output buffer of length `K`. Raw, syncable.
///
/// # Zero-allocation
///
/// Reads `state` / `directions`, writes `out`. No `Vec`, no iterator chains
/// that allocate.
///
/// # Bridge ranking preservation (G1.3)
///
/// Because `fast_sigmoid` is strictly monotonically increasing, the bridge
/// preserves belief ranking: `dot_a > dot_b ⟺ sigmoid(dot_a) > sigmoid(dot_b)`.
/// This is the G1.3 property — verified in `tests.rs`.
#[inline(always)]
pub fn project_to_scalars(state: &[f32], directions: &[f32], dim: usize, out: &mut [f32]) {
    impl_bridge(state, directions, dim, out);
}

impl CoherenceReport {
    /// Pretty-print a verdict table to stderr. Used by the test for visibility;
    /// callers can also use it from a future `[[bench]]` harness.
    pub fn print_verdict_table(&self) {
        eprintln!();
        eprintln!("┌────────────────────────────────────────────────────────────────────────────┐");
        eprintln!("│ G2.1 long-horizon coherence benchmark — Plan 276 Phase 5 T5.0              │");
        eprintln!(
            "├──────────────────────┬───────────────┬───────────────┬──────────────────────┤"
        );
        eprintln!(
            "│ Kernel               │ flip-flops    │ ambig-window  │ diverged?            │"
        );
        eprintln!(
            "│                      │ (lower=better)│ argmax-var    │ (G1.2 invariant)     │"
        );
        eprintln!(
            "├──────────────────────┼───────────────┼───────────────┼──────────────────────┤"
        );
        self.print_row(&self.leaky);
        self.print_row(&self.attractor);
        self.print_row(&self.latent_thought);
        eprintln!(
            "└──────────────────────┴───────────────┴───────────────┴──────────────────────┘"
        );

        // Verdict line.
        let l = self.leaky.flip_flop_count;
        let a = self.attractor.flip_flop_count;
        let b = self.latent_thought.flip_flop_count;
        let verdict = match (a.cmp(&l), b.cmp(&l)) {
            (core::cmp::Ordering::Less, _) | (_, core::cmp::Ordering::Less) => {
                "GOAT PASS (T5.1): attractor family flips LESS than leaky — promote opt-in variant"
            }
            (core::cmp::Ordering::Equal, core::cmp::Ordering::Equal) => {
                "TIE (T5.2): attractor family does NOT beat leaky — demote to Gain"
            }
            _ => "G2.1 FAIL (T5.2): attractor family flips MORE than leaky — demote to Gain",
        };
        eprintln!("│ leaky={l}  attractor={a}  latent_thought={b}");
        eprintln!("│ VERDICT: {verdict}");
        eprintln!();
    }

    fn print_row(&self, r: &KernelRunReport) {
        eprintln!(
            "│ {:<20} │ {:<13} │ {:<13.4} │ {:<20} │",
            r.name,
            r.flip_flop_count,
            r.ambiguous_window_argmax_variance,
            if r.diverged { "YES (HARD FAIL)" } else { "no" }
        );
    }
}

impl LatentThoughtKernel {
    /// Construct a latent-thought kernel with the given seed, dimension, and K.
    ///
    /// The inner attractor weights come from `AttractorKernel::from_seed(seed, dim)`,
    /// so two kernels built with the same `(seed, dim, k_iters)` are bit-identical
    /// (G1.1 determinism inherited from Family A).
    pub fn from_seed(seed: u64, dim: usize, k_iters: u8) -> Self {
        Self {
            inner: AttractorKernel::from_seed(seed, dim),
            k_iters,
        }
    }

    /// Builder: override the number of inner attractor iterations.
    #[inline]
    pub fn with_k_iters(mut self, k: u8) -> Self {
        self.k_iters = k;
        self
    }
}

impl MicroRecurrentBeliefState for LatentThoughtKernel {
    #[inline]
    fn dim(&self) -> usize {
        self.inner.dim()
    }

    /// Advance one tick: apply `inner.step(state, input)` exactly `k_iters`
    /// times with the SAME `input` each iteration.
    ///
    /// # K > 1 precompute optimization
    ///
    /// For `k_iters > 1`, the input `x` is invariant across iterations — only
    /// `state` changes. We precompute `W_x · x` once via [`AttractorKernel::precompute_wx_dot`],
    /// then call [`AttractorKernel::step_with_precomputed_wx`] K times. This
    /// saves (K-1)×dim `simd_dot_f32` calls — at dim=32, K=3 that's ~64 saved
    /// dots ≈ 90ns/tick.
    ///
    /// The precomputed path is bit-identical to calling `inner.step()` K times
    /// (see `step_with_precomputed_wx_matches_step_bit_identical` in
    /// `attractor.rs` — same `simd_dot_f32` reductions, same addition order).
    ///
    /// # Zero allocation
    ///
    /// The `wx_x` scratch is a fixed `[f32; 1024]` stack buffer (4KB). K=1
    /// skips the buffer entirely (delegates directly to `inner.step`).
    ///
    /// # `K = 0`
    ///
    /// `k_iters == 0` is a no-op (state left unchanged). See the module-level
    /// docs for the rationale.
    #[inline]
    fn step(&self, state: &mut [f32], input: &[f32]) {
        // Match-style dispatch: K=0 noop, K=1 direct (no precompute overhead),
        // K>1 uses precomputed W_x·x across all iterations.
        match self.k_iters {
            0 => {} // no-op
            1 => self.inner.step(state, input),
            _ => {
                // Precompute W_x · x ONCE (bit-identical to the dot_wx inside
                // inner.step()). Reused across all K iterations.
                // Uninit stack buffer (matches cumprodsum.rs pattern) — wx_x[..dim]
                // is written by precompute_wx_dot before any read.
                let mut wx_x_buf = uninit_stack::<WX_X_BUF_LEN>();
                // SAFETY: wx_x[..dim] is fully written by precompute_wx_dot.
                let wx_x: &mut [f32] = unsafe { assume_init_slice(&mut wx_x_buf, self.inner.dim) };
                let dim = self.inner.dim;
                self.inner.precompute_wx_dot(input, &mut wx_x[..dim]);
                for _ in 0..self.k_iters {
                    self.inner.step_with_precomputed_wx(state, &wx_x[..dim]);
                }
            }
        }
    }

    #[inline(always)]
    fn project_to_scalars(&self, state: &[f32], directions: &[f32], dim: usize, out: &mut [f32]) {
        bridge_project(state, directions, dim, out);
    }

    #[inline]
    fn family(&self) -> RecurrenceFamily {
        RecurrenceFamily::LatentThought
    }
}

impl LeakyIntegrator {
    /// Construct a new leaky integrator.
    ///
    /// Defaults that match `ReconstructionConfig::default()`:
    /// - `lr = 0.1`
    /// - `max_delta = 0.2`
    pub fn new(lr: f32, max_delta: f32, dim: usize) -> Self {
        Self { lr, max_delta, dim }
    }

    /// Construct with belief-default config (`lr=0.1`, `max_delta=0.2`).
    pub fn belief_default(dim: usize) -> Self {
        Self::new(0.1, 0.2, dim)
    }

    /// Recursively advance the kernel for `inputs.len()` ticks and classify the
    /// resulting belief-vector chain with [`katgpt_types::depth_invariance::classify_chain`].
    ///
    /// The chain `s_0, s_1, …, s_k` (where `s_0 = initial_state` and
    /// `k = inputs.len()`) is captured into a flattened buffer and classified.
    /// Each input `inputs[t]` drives one [`MicroRecurrentBeliefState::step`]
    /// invocation producing `s_{t+1}`.
    ///
    /// **Zero per-step allocation** — double-buffered `s_a` / `s_b` plus a
    /// single up-front `Vec::with_capacity` for the chain. The depth-invariance
    /// `Scratch` is allocated inside this call; tight-loop callers should reuse
    /// one via the raw [`katgpt_types::depth_invariance::classify_chain`] primitive.
    ///
    /// # Plan 306 Phase 4 (G3 — T4.3 caveat)
    ///
    /// `LeakyIntegrator::step` clamps the state to `[-1, 1]` on every tick
    /// (per-element `.clamp(-1.0, 1.0)` in `crate::leaky_core::leaky_step`).
    /// It therefore **also classifies as `DepthInvariant`** by construction,
    /// like the attractor. The T4.3 negative control builds an *unclamped*
    /// leaky update inline in the test (no kernel-level support needed) so the
    /// diagnostic can demonstrate its discriminating power on a real drift
    /// kernel — see `tests/depth_invariance_micro_belief.rs::leaky_*_depth_specific`.
    #[cfg(feature = "depth_invariance")]
    pub fn audit_depth_invariance(
        &self,
        initial_state: &[f32],
        inputs: &[&[f32]],
        cfg: &katgpt_types::depth_invariance::DepthInvarianceConfig,
    ) -> katgpt_types::depth_invariance::DepthInvarianceDiagnostic {
        let dim = self.dim;
        assert_eq!(
            initial_state.len(),
            dim,
            "initial_state must have length dim"
        );
        for (i, inp) in inputs.iter().enumerate() {
            assert_eq!(inp.len(), dim, "inputs[{i}] must have length dim");
        }

        let k = inputs.len();
        let k_plus_1 = k + 1;

        let mut chain: Vec<f32> = Vec::with_capacity(k_plus_1 * dim);
        chain.extend_from_slice(initial_state);

        // Double-buffered state — see AttractorKernel::audit_depth_invariance
        // for the aliasing rationale.
        let mut s_a: Vec<f32> = initial_state.to_vec();
        let mut s_b: Vec<f32> = initial_state.to_vec();

        for inp in inputs {
            s_b.copy_from_slice(&s_a);
            MicroRecurrentBeliefState::step(self, &mut s_b, inp);
            chain.extend_from_slice(&s_b);
            std::mem::swap(&mut s_a, &mut s_b);
        }

        let mut scratch = katgpt_types::depth_invariance::Scratch::with_capacity(k_plus_1, dim);
        katgpt_types::depth_invariance::classify_chain(&chain, dim, cfg, &mut scratch)
    }
}

impl MicroRecurrentBeliefState for LeakyIntegrator {
    #[inline]
    fn dim(&self) -> usize {
        self.dim
    }

    /// Advance one tick using the leaky-integrator update.
    ///
    /// Delegates to the shared `crate::leaky_core::leaky_step` primitive —
    /// the same body used by `ReconstructionState::evolve_belief`. Here `total` is
    /// `Σ input[0..dim]` (no KIND_MAP wrap); see the module docs for why
    /// `evolve_belief` passes a different `total`.
    #[inline]
    fn step(&self, state: &mut [f32], input: &[f32]) {
        debug_assert_eq!(state.len(), self.dim, "state/dim mismatch");
        debug_assert_eq!(input.len(), self.dim, "input/dim mismatch");

        // Generic Family C kernel: normalize over the full dim-length input.
        let total: f32 = input.iter().copied().sum();
        katgpt_types::leaky_core::leaky_step(state, input, total, self.lr, self.max_delta);
    }

    #[inline(always)]
    fn project_to_scalars(&self, state: &[f32], directions: &[f32], dim: usize, out: &mut [f32]) {
        bridge_project(state, directions, dim, out);
    }

    #[inline]
    fn family(&self) -> RecurrenceFamily {
        RecurrenceFamily::DeltaRule
    }
}

impl MicroRecurrentKernelSnapshot {
    /// Build a snapshot from a kernel and a caller-provided weights blob.
    ///
    /// The caller is responsible for serialising the kernel's weights into
    /// `weights_blob` (e.g. via `AttractorKernel::to_snapshot_blob`). This
    /// function records `family` + `dim` from the kernel, stores the blob, and
    /// computes the BLAKE3 commitment.
    ///
    /// `version` is caller-managed — typically incremented by the hot-swap
    /// layer on each swap.
    pub fn from_kernel<K: MicroRecurrentBeliefState>(
        kernel: &K,
        weights_blob: Vec<u8>,
        version: u64,
    ) -> Self {
        let mut snap = Self {
            family: kernel.family(),
            dim: kernel.dim(),
            weights_blob,
            blake3: [0u8; 32],
            version,
        };
        snap.commit();
        snap
    }

    /// Build a snapshot from raw parts WITHOUT computing the commitment.
    ///
    /// Useful for deserialisation paths where the commitment is already known
    /// (e.g. loading from disk). Call [`commit`](Self::commit) afterwards if
    /// you need to recompute, or [`verify`](Self::verify) to check integrity.
    pub fn from_parts(
        family: RecurrenceFamily,
        dim: usize,
        weights_blob: Vec<u8>,
        blake3: [u8; 32],
        version: u64,
    ) -> Self {
        Self {
            family,
            dim,
            weights_blob,
            blake3,
            version,
        }
    }

    /// Compute (or recompute) the BLAKE3 commitment over
    /// `(family, dim, weights_blob)`.
    ///
    /// Idempotent: calling twice produces the same hash. The existing
    /// `self.blake3` is zeroed internally before hashing so the commitment
    /// never feeds back into itself.
    pub fn commit(&mut self) -> [u8; 32] {
        let mut hasher = blake3::Hasher::new();
        hasher.update(&[self.family as u8]);
        hasher.update(&(self.dim as u64).to_le_bytes());
        hasher.update(&self.weights_blob);
        let hash = *hasher.finalize().as_bytes();
        self.blake3 = hash;
        hash
    }

    /// Recompute the commitment and compare with the stored `self.blake3`.
    ///
    /// Returns `true` iff the stored weights produce the stored hash. A `false`
    /// result indicates tampering or corruption.
    pub fn verify(&self) -> bool {
        let mut hasher = blake3::Hasher::new();
        hasher.update(&[self.family as u8]);
        hasher.update(&(self.dim as u64).to_le_bytes());
        hasher.update(&self.weights_blob);
        let recomputed = *hasher.finalize().as_bytes();
        recomputed == self.blake3
    }

    /// Serialize to a flat byte buffer (Issue 456 Phase 2 — FreezeTrigger
    /// migration artifact).
    ///
    /// Layout (all LE, length-prefixed because `weights_blob` is variable):
    /// `family (1) || dim (8) || weights_blob_len (8) || weights_blob (N) ||
    /// blake3 (32) || version (8)` = `57 + N` bytes.
    ///
    /// Deterministic by construction: no pointers, no padding, no implicit
    /// struct layout. The outer `MerkleFrozenEnvelope` provides tamper
    /// detection at the bundle level; the per-block `verify()` is the
    /// integrity check at the snapshot level.
    pub fn to_bytes(&self) -> Vec<u8> {
        let mut buf = Vec::with_capacity(1 + 8 + 8 + self.weights_blob.len() + 32 + 8);
        buf.push(self.family as u8);
        buf.extend_from_slice(&(self.dim as u64).to_le_bytes());
        buf.extend_from_slice(&(self.weights_blob.len() as u64).to_le_bytes());
        buf.extend_from_slice(&self.weights_blob);
        buf.extend_from_slice(&self.blake3);
        buf.extend_from_slice(&self.version.to_le_bytes());
        buf
    }

    /// Deserialize from a flat byte buffer produced by [`to_bytes`](Self::to_bytes).
    ///
    /// Returns `None` on any structural malformation:
    /// - Truncated header (< 17 bytes for family + dim + length)
    /// - Truncated `weights_blob` (declared length exceeds remaining bytes)
    /// - Truncated tail (< 40 bytes after blob for blake3 + version)
    /// - Unknown `family` discriminant
    ///
    /// Does NOT re-verify the BLAKE3 — call [`verify`](Self::verify) afterwards
    /// to check integrity.
    pub fn from_bytes(buf: &[u8]) -> Option<Self> {
        // Header: family (1) + dim (8) + blob_len (8) = 17 bytes minimum.
        if buf.len() < 17 {
            return None;
        }
        let family = RecurrenceFamily::from_u8(buf[0])?;
        let dim = u64::from_le_bytes(buf[1..9].try_into().ok()?) as usize;
        let blob_len = u64::from_le_bytes(buf[9..17].try_into().ok()?) as usize;
        // Need blob_len + 32 (blake3) + 8 (version) after the 17-byte header.
        let needed = 17 + blob_len + 32 + 8;
        if buf.len() != needed {
            return None;
        }
        let weights_blob = buf[17..17 + blob_len].to_vec();
        let blake3: [u8; 32] = buf[17 + blob_len..17 + blob_len + 32].try_into().ok()?;
        let version = u64::from_le_bytes(
            buf[17 + blob_len + 32..17 + blob_len + 32 + 8]
                .try_into()
                .ok()?,
        );
        Some(Self {
            family,
            dim,
            weights_blob,
            blake3,
            version,
        })
    }
}

use crate::types::MicroRecurrentBeliefState;

// ─── helpers ──────────────────────────────────────────────────────────────

/// Deterministic input generator: `x[i] = sin(i + step) * cos(step)`-ish.
///
/// No RNG — the input sequence itself is bit-identical across runs (G1.1
/// requires that the WHOLE pipeline `(s_0, x_1..x_T) → s_T` is deterministic,
/// not just the kernel).
fn deterministic_input(step: usize, dim: usize) -> Vec<f32> {
    let s = step as f32;
    (0..dim)
        .map(|i| {
            let f = i as f32;
            // Smooth, bounded signal in [-1, 1]. f32::sin/cos are deterministic
            // per IEEE-754 (libm is deterministic for the same input).
            (f * 0.1 + s * 0.01).sin() * 0.5 * (s * 0.003).cos()
        })
        .collect()
}

impl RecurrenceFamily {
    /// Deserialize from a raw `u8` discriminant.
    ///
    /// Returns `None` for unknown values. Used by
    /// `MicroRecurrentKernelSnapshot::from_bytes` (Issue 456 Phase 2 — FreezeTrigger
    /// migration). Symmetric with the `#[repr(u8)]` cast `family as u8`.
    #[inline]
    pub const fn from_u8(b: u8) -> Option<Self> {
        match b {
            0 => Some(Self::Attractor),
            1 => Some(Self::LatentThought),
            2 => Some(Self::DeltaRule),
            _ => None,
        }
    }
}

