            legal_count: instance.get_typed_func(store, "wasmi_arena_legal_count").expect("wasmi_arena_legal_count"),
            legal_move: instance.get_typed_func(store, "wasmi_arena_legal_move").expect("wasmi_arena_legal_move"),
            search_puct: instance.get_typed_func(store, "wasmi_arena_search_puct").expect("wasmi_arena_search_puct"),
            search_greedy: instance.get_typed_func(store, "wasmi_arena_search_greedy").expect("wasmi_arena_search_greedy"),
            is_over: instance.get_typed_func(store, "wasmi_arena_is_over").expect("wasmi_arena_is_over"),
            to_play: instance.get_typed_func(store, "wasmi_arena_to_play").expect("wasmi_arena_to_play"),
            reward: instance.get_typed_func(store, "wasmi_arena_reward").expect("wasmi_arena_reward"),
        }
    }

    /// Play `n` random legal opening moves (mirrors `GO_OPENING_MOVES=4` in the
    /// native arena — both players are deterministic, so without this every game
    /// with the same color assignment replays identically). Uses a simple
    /// xorshift seeded per-game for reproducibility.
    fn random_opening(&self, store: &mut Store<()>, n: usize, seed: u64) {
        let mut rng = seed.max(1);
        for _ in 0..n {
            if self.is_over.call(&mut *store, ()).expect("is_over") == 1 {
                break;
            }
            let count = self.legal_count.call(&mut *store, ()).expect("legal_count");
            if count == 0 {
                continue;
            }
            // xorshift64
            rng ^= rng << 13;
            rng ^= rng >> 7;
            rng ^= rng << 17;
            let pick = (rng % count as u64) as u32;
            let idx = self.legal_move.call(&mut *store, pick).expect("legal_move");
            if idx != 255 {
                self.play.call(&mut *store, idx).expect("play opening");
            }
        }
    }

    /// Run one full game. `puct_color` is 0 (black) or 1 (white); greedy plays
    /// the other color. Returns true if `puct_color` won.
    fn play_game(&self, store: &mut Store<()>, puct_color: u32, seed: u64) -> bool {
        self.reset.call(&mut *store, ()).expect("reset");
        self.random_opening(store, OPENING_MOVES, seed);

        for _ in 0..MAX_MOVES {
            if self.is_over.call(&mut *store, ()).expect("is_over") == 1 {
                break;
            }
            let to_play = self.to_play.call(&mut *store, ()).expect("to_play");
            if to_play == puct_color {
                let _ = self.search_puct.call(&mut *store, ()).expect("puct search");
            } else {
                let _ = self.search_greedy.call(&mut *store, ()).expect("greedy search");
            }
        }

        // Reward is 1 if `color` is ahead after komi. (If MAX_MOVES hit without
        // a double-pass, we score the current position — passes don't change
        // the area score, so this matches the native arena's forced-pass path.)
        self.reward.call(&mut *store, puct_color).expect("reward") == 1
    }
}

use katgpt_types::simd::simd_dot_f32;

// ── Dot product helper ────────────────────────────────────────────────────

/// Bias-aware dot product: `init + dot(a, b)`.
///
/// This is the one function that directly calls the shared SIMD primitive
/// (`simd_dot_f32`). All higher-level operations (`conv2d_into`, `linear_into`)
/// route through this helper.
#[inline]
pub fn dot_lanes(a: &[f32], b: &[f32], init: f32) -> f32 {
    debug_assert_eq!(a.len(), b.len());
    init + simd_dot_f32(a, b, a.len().min(b.len()))
}

impl Vec2 {
    pub fn new(x: f32, y: f32) -> Self {
        Self { x, y }
    }

    /// Dot product — the core attention score in 2D.
    #[inline]
    pub fn dot(&self, other: &Self) -> f32 {
        self.x * other.x + self.y * other.y
    }

    /// Z-component of cross product AB × AC.
    /// Positive = left turn, Negative = right turn, Zero = collinear.
    #[inline]
    pub fn cross_z(a: &Self, b: &Self, c: &Self) -> f32 {
        (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x)
    }
}

impl KVCache2D {
    pub fn new() -> Self {
        Self {
            keys: Vec::new(),
            values: Vec::new(),
            upper_hull: Vec::new(),
        }
    }

    pub fn with_capacity(capacity: usize) -> Self {
        Self {
            keys: Vec::with_capacity(capacity),
            values: Vec::with_capacity(capacity),
            upper_hull: Vec::with_capacity(capacity),
        }
    }

    pub fn len(&self) -> usize {
        self.keys.len()
    }

    pub fn is_empty(&self) -> bool {
        self.keys.is_empty()
    }

    pub fn hull_len(&self) -> usize {
        self.upper_hull.len()
    }

    /// Append a key-value pair. Amortized O(1) hull maintenance via Graham Scan.
    ///
    /// For keys with monotonically increasing X:
    /// - Points creating non-right turns (collinear or concave) are removed
    /// - The upper hull captures the "skyline" of the key distribution
    pub fn append(&mut self, key: Vec2, value: usize) {
        let idx = self.keys.len();
        self.keys.push(key);
        self.values.push(value);

        // Maintain upper convex hull: pop points violating convexity
        while self.upper_hull.len() >= 2 {
            let len = self.upper_hull.len();
            let a = &self.keys[self.upper_hull[len - 2]];
            let b = &self.keys[self.upper_hull[len - 1]];
            let c = &key;

            // Right turn (cross < 0) preserves convexity. Remove otherwise.
            if Vec2::cross_z(a, b, c) >= 0.0 {
                self.upper_hull.pop();
            } else {
                break;
            }
        }
        self.upper_hull.push(idx);
    }

    /// Standard O(N) attention: linear scan over all keys.
    /// Baseline for correctness verification.
    pub fn linear_attention(&self, query: &Vec2) -> (f32, usize) {
        if self.keys.len() == 0 { (f32::NEG_INFINITY, 0) } else {
                let mut max_score = f32::NEG_INFINITY;
                let mut best_idx = 0;
                for (i, key) in self.keys.iter().enumerate() {
                    let score = query.dot(key);
                    if score > max_score {
                        max_score = score;
                        best_idx = i;
                    }
                }
                (max_score, self.values[best_idx])
            }
    }

    /// O(log N) attention via ternary search over the convex hull.
    ///
    /// The dot product of a fixed query against points on a convex hull
    /// forms a unimodal (bitonic) sequence: it rises to a peak then falls.
    /// Ternary search finds the peak in O(log H) where H = hull size.
    pub fn fast_attention(&self, query: &Vec2) -> (f32, usize) {
        let n = self.upper_hull.len();
        match n {
            0 => (f32::NEG_INFINITY, 0),
            1 => {
                let idx = self.upper_hull[0];
                (query.dot(&self.keys[idx]), self.values[idx])
            }
            2 => {
                let idx0 = self.upper_hull[0];
                let idx1 = self.upper_hull[1];
                let s0 = query.dot(&self.keys[idx0]);
                let s1 = query.dot(&self.keys[idx1]);
                if s0 >= s1 { (s0, self.values[idx0]) } else { (s1, self.values[idx1]) }
            }
            _ => {
                let mut left = 0usize;
                let mut right = n - 1;

                // Ternary search on unimodal dot-product sequence
                while right - left > 2 {
                    let third = (right - left) / 3;
                    let m1 = left + third;
                    let m2 = right - third;

                    let s1 = query.dot(&self.keys[self.upper_hull[m1]]);
                    let s2 = query.dot(&self.keys[self.upper_hull[m2]]);

                    if s1 < s2 { left = m1 } else { right = m2 }
                }

                // Scan the remaining 1–3 candidates
                let mut max_score = f32::NEG_INFINITY;
                let mut best_idx = self.upper_hull[left];

                for i in left..=right {
                    let idx = self.upper_hull[i];
                    let score = query.dot(&self.keys[idx]);
                    if score > max_score {
                        max_score = score;
                        best_idx = idx;
                    }
                }

                (max_score, self.values[best_idx])
            }
        }
    }

    /// Get hull indices (for debugging/testing).
    pub fn hull_indices(&self) -> &[usize] {
        &self.upper_hull
    }

    /// Reset the cache.
    pub fn reset(&mut self) {
        self.keys.clear();
        self.values.clear();
        self.upper_hull.clear();
    }

    /// Get all keys (for debugging/testing).
    pub fn keys(&self) -> &[Vec2] {
        &self.keys
    }

    /// Get all values (for debugging/testing).
    pub fn values(&self) -> &[usize] {
        &self.values
    }
}

impl SymbolicValidator {
    /// Filter drafted (digit, log_prob) pairs through Sudoku constraints.
    /// Returns only valid moves, sorted by probability descending.
    ///
    /// In a real system: the fast draft model proposes logits,
    /// this intercept prunes invalid branches *before* target verification.
    pub fn prune_drafts(
        state: &Sudoku9x9,
        row: usize,
        col: usize,
        logits: &[(u8, f32)],
    ) -> Vec<(u8, f32)> {
        let mut valid: Vec<(u8, f32)> = logits
            .iter()
            .filter(|(digit, _)| state.is_valid_move(row, col, *digit))
            .copied()
            .collect();
        valid.sort_by(|a, b| b.1.total_cmp(&a.1));
        valid
    }
}

