// ── ShardTierBandit (freq_bandit integration, Plan 218 Phase 5) ────

/// UCB1 bandit that adapts shard tier decisions based on cache hit rewards.
///
/// Arms: `[Hot, Warm, Cold]` (indices 0, 1, 2 matching `FreqTier` repr).
/// The bandit starts with no preference and learns which tier assignment
/// yields the best cache performance over time.
///
/// Usage: after computing the static `FreqTier` from LFU frequency counts,
/// feed the reward signal (hit/miss) to `update_reward`, then use
/// `refine_tier` to let the bandit promote or demote the tier.
#[cfg(feature = "freq_bandit")]
pub struct ShardTierBandit {
    bandit: FrequencyBandit,
}

#[cfg(feature = "freq_bandit")]
impl ShardTierBandit {
    /// Create a new shard tier bandit with default exploration constant.
    pub fn new() -> Self {
        Self {
            bandit: FrequencyBandit::new(),
        }
    }

impl BfcpLfuShard {
    /// Create all components with given cache capacity and shard count.
    pub fn new(cache_capacity: usize, num_shards: usize) -> Self {
        Self {
            cache: BfcpRegionCache::new(cache_capacity),
            shard_map: RegionShardMap::new(num_shards),
            batcher: RegionBatcher::new(),
            #[cfg(feature = "freq_bandit")]
            tier_bandit: ShardTierBandit::new(),
        }
    }

    /// Main pipeline: hash → lookup → compute on miss → insert → return partition.
    pub fn process(
        &mut self,
        logits: &[f32],
        mut compute_fn: impl FnMut(&[f32]) -> BFCP,
    ) -> Arc<BFCP> {
        self.process_with_hash(logits, &mut compute_fn).0
    }

    /// Like [`process`](Self::process) but also returns the BLAKE3 hash of `logits`
    /// so callers that need the hash for downstream cache operations (e.g. tier
    /// lookup) can avoid recomputing it (Issue 001 H-28).
    ///
    /// Returns `(partition, hash)`. The hash is computed exactly once per call.
    pub fn process_with_hash(
        &mut self,
        logits: &[f32],
        compute_fn: &mut impl FnMut(&[f32]) -> BFCP,
    ) -> (Arc<BFCP>, [u8; 32]) {
        let hash = blake3_logit_hash(logits);

        // Try cache hit first.
        if let Some(partition) = self.cache.lookup(&hash) {
            return (partition, hash);
        }

        // Cache miss — compute new partition.
        let partition = Arc::new(compute_fn(logits));
        self.cache.insert(hash, Arc::clone(&partition));
        (partition, hash)
    }

    /// Like `process` but also returns shard assignments for each region.
    ///
    /// Returns `(partition, Vec<(shard_index, FreqTier)>)`.
    ///
    /// With `freq_bandit` feature: after deriving the static tier from LFU
    /// counts, the bandit may refine the tier based on learned rewards.
    pub fn process_and_shard(
        &mut self,
        logits: &[f32],
        mut compute_fn: impl FnMut(&[f32]) -> BFCP,
    ) -> (Arc<BFCP>, Vec<(usize, FreqTier)>) {
        // Reuse the hash computed inside process_with_hash instead of
        // recomputing blake3_logit_hash a second time (Issue 001 H-28).
        let (partition, hash) = self.process_with_hash(logits, &mut compute_fn);

        // Derive frequency tier from cache for each region.
        let static_tier = self.cache.freq_tier(&hash).unwrap_or(FreqTier::Cold);

        // Bandit-refined tier (no-op without freq_bandit feature).
        #[cfg(feature = "freq_bandit")]
        let tier = self.tier_bandit.refine_tier(static_tier);
        #[cfg(not(feature = "freq_bandit"))]
        let tier = static_tier;

        let mut assignments: Vec<(usize, FreqTier)> = Vec::with_capacity(partition.regions.len());
        for region in &partition.regions {
            let shard = self.shard_map.assign_shard(region.label, tier);
            assignments.push((shard, tier));
        }

        (partition, assignments)
    }

    /// Batch accept tokens from partition regions (up to `max_tokens`).
    pub fn batch_process(&self, partition: &BFCP, max_tokens: usize) -> Vec<usize> {
        let mut regions: Vec<&BorelRegion> = Vec::with_capacity(partition.regions.len());
        regions.extend(partition.regions.iter());
        self.batcher.batch_accept(&regions, max_tokens)
    }

    /// Whether sharding should activate for given region count.
    pub fn should_shard(&self, region_count: usize) -> bool {
        self.shard_map.should_shard(region_count)
    }

    /// Cache hit rate — delegates to BfcpRegionCache.
    pub fn cache_hit_rate(&self) -> f64 {
        self.cache.hit_rate()
    }

    /// Decay cache frequencies by λ — delegates to BfcpRegionCache.
    pub fn decay(&mut self, lambda: f32) {
        self.cache.decay(lambda);
    }

    /// Feed reward signal to the tier bandit (hit=1.0, miss=0.0, or any `[0,1]`).
    ///
    /// Only available with `freq_bandit` feature. No-op otherwise.
    #[cfg(feature = "freq_bandit")]
    pub fn update_bandit_reward(&mut self, tier: FreqTier, reward: f64) {
        self.tier_bandit.update_reward(tier, reward);
    }

    /// Access the tier bandit (for direct queries like `total_pulls`).
    #[cfg(feature = "freq_bandit")]
    pub fn tier_bandit(&self) -> &ShardTierBandit {
        &self.tier_bandit
    }

    /// Access the underlying LFU cache.
    pub fn cache(&self) -> &BfcpRegionCache {
        &self.cache
    }

    /// Access the underlying shard map.
    pub fn shard_map(&self) -> &RegionShardMap {
        &self.shard_map
    }

    /// Access the underlying batcher.
    pub fn batcher(&self) -> &RegionBatcher {
        &self.batcher
    }

    /// Derive `FreqTier` from cache, optionally refined by bandit.
    ///
    /// With `freq_bandit`: returns bandit-refined tier.
    /// Without: returns static tier directly.
    pub fn derive_tier(&self, hash: &[u8; 32]) -> FreqTier {
        let static_tier = self.cache.freq_tier(hash).unwrap_or(FreqTier::Cold);

        #[cfg(feature = "freq_bandit")]
        {
            self.tier_bandit.refine_tier(static_tier)
        }
        #[cfg(not(feature = "freq_bandit"))]
        {
            static_tier
        }
    }
}

use super::roaring_membership::{CompactBitmap, RoaringBatching, RoaringMembership};

// ── BfcpLshCms ─────────────────────────────────────────────────

/// Top-level fusion: LSH approximate cache + CMS frequency + Roaring membership.
///
/// Three-level cache hierarchy:
/// - **L0**: BLAKE3 exact match → O(1), zero recomputation
/// - **L1**: LSH SimHash approximate → warm-start from cached partition
/// - **L2**: Full compute from scratch
///
/// Frequency tracking via Count-Min Sketch (O(1) update/estimate/decay).
/// Batch operations via CompactBitmap (Roaring-like compressed membership).
pub struct BfcpLshCms {
    /// Three-level cache: exact + LSH approximate.
    cache: BfcpLshCache,
    /// Count-Min Sketch for O(1) frequency estimation.
    sketch: CountMinSketch,
    /// Shard map for frequency-aware region assignment.
    shard_map: RegionShardMap,
    /// Roaring-backed membership for batch operations.
    membership: RoaringMembership,
    /// Hot tier threshold (for CMS-based classification).
    hot_threshold: u32,
    /// Warm tier threshold (for CMS-based classification).
    warm_threshold: u32,
    /// Last partition processed by `update_membership`. Compared by `Arc::as_ptr`
    /// identity so repeated calls with the same cached partition short-circuit
    /// the bitmap rebuild (Issue 001 H-23). L0/L1 hits return the *same* `Arc`,
    /// so this skips the O(regions × tokens) rebuild on every cache hit.
    last_membership_partition: Option<Arc<BFCP>>,
}

impl BfcpLshCms {
    /// Create a new fused cache with all components.
    pub fn new(
        exact_capacity: usize,
        logit_dim: usize,
        num_buckets: usize,
        bucket_capacity: usize,
        hamming_radius: u32,
        num_shards: usize,
    ) -> Self {
        Self {
            cache: BfcpLshCache::new(
                exact_capacity,
                logit_dim,
                num_buckets,
                bucket_capacity,
                hamming_radius,
            ),
            sketch: CountMinSketch::new(),
            shard_map: RegionShardMap::new(num_shards),
            membership: RoaringMembership::new(),
            hot_threshold: 100,
            warm_threshold: 10,
            last_membership_partition: None,
        }
    }

impl BFCPPruner {
    /// Build a BFCPPruner by partitioning tokens via the inner pruner.
    ///
    /// Each token gets a label:
    /// - `relevance >= 0.7` → Accept
    /// - `relevance <= 0.3` → Reject
    /// - otherwise → Maybe
    ///
    /// Tokens are grouped into up to 3 BorelRegion instances (one per label).
    pub fn from_logits(pruner: &dyn ScreeningPruner, _logits: &[f32], vocab_size: usize) -> Self {
        let mut accept_tokens = Vec::with_capacity(vocab_size / 2);
        let mut reject_tokens = Vec::with_capacity(vocab_size / 2);
        let mut maybe_tokens = Vec::with_capacity(vocab_size / 4);

        for token_idx in 0..vocab_size {
            let relevance = pruner.relevance(0, token_idx, &[]);
            match classify(relevance) {
                RegionLabel::Accept => {
                    accept_tokens.push(token_idx);
                }
                RegionLabel::Reject => {
                    reject_tokens.push(token_idx);
                }
                RegionLabel::Maybe => {
                    maybe_tokens.push(token_idx);
                }
            }
        }

        let skip_count = reject_tokens.len();

        // Build regions — one per label with non-zero tokens.
        let mut regions = Vec::with_capacity(3);
        if !accept_tokens.is_empty() {
            regions.push(BorelRegion::new(
                RegionLabel::Accept,
                Vec::new(),
                accept_tokens.len(),
            ));
        }
        if !reject_tokens.is_empty() {
            regions.push(BorelRegion::new(
                RegionLabel::Reject,
                Vec::new(),
                reject_tokens.len(),
            ));
        }
        if !maybe_tokens.is_empty() {
            regions.push(BorelRegion::new(
                RegionLabel::Maybe,
                Vec::new(),
                maybe_tokens.len(),
            ));
        }

        let mut kept_tokens = Vec::with_capacity(accept_tokens.len() + maybe_tokens.len());
        kept_tokens.extend_from_slice(&accept_tokens);
        kept_tokens.extend_from_slice(&maybe_tokens);

        let partition = BFCP::from_regions(regions);

        Self {
            partition,
            kept_tokens,
            skip_count,
        }
    }

    /// Token IDs that survive screening (accept + maybe regions).
    pub fn pruned_token_ids(&self) -> Vec<usize> {
        self.kept_tokens.clone()
    }

    /// Number of tokens in reject regions — work saved by region-level skip.
    #[inline]
    pub fn skip_count(&self) -> usize {
        self.skip_count
    }

    /// Reference to the underlying BFCP partition.
    pub fn partition(&self) -> &BFCP {
        &self.partition
    }
}

impl KlBoundaryAligner {
    pub fn new(epsilon: f32) -> Self {
        Self { epsilon }
    }
}

impl BoundaryAlignment for KlBoundaryAligner {
    fn kl_divergence(&self, local: &[f32], ensemble: &[f32]) -> f32 {
        let kl_forward: f32 = local
            .iter()
            .zip(ensemble.iter())
            .map(|(l, e)| {
                let l_safe = l.max(self.epsilon);
                let e_safe = e.max(self.epsilon);
                l_safe * (l_safe / e_safe).ln()
            })
            .sum();

        let kl_reverse: f32 = ensemble
            .iter()
            .zip(local.iter())
            .map(|(e, l)| {
                let e_safe = e.max(self.epsilon);
                let l_safe = l.max(self.epsilon);
                e_safe * (e_safe / l_safe).ln()
            })
            .sum();

        // Symmetric KL (Jensen-Shannon proxy)
        (kl_forward + kl_reverse) / 2.0
    }

    fn coupling_weight(&self, domain: &str, _neighbors: &[&str]) -> f32 {
        // Default: uniform coupling. Domain-specific weights can be
        // learned from bandit Q-values in a real deployment.
        let _ = domain;
        1.0
    }
}

impl BtComparison {
    /// Create a new comparison result.
    #[inline]
    pub const fn new(winner: usize, loser: usize) -> Self {
        Self { winner, loser }
    }
}

impl BtScores {
    /// Return candidate indices ranked by score (best first).
    ///
    /// Ties are broken by index (lower index first for stability).
    pub fn rank(&self) -> Vec<usize> {
        let mut ranked: Vec<usize> = (0..self.scores.len()).collect();
        ranked.sort_by(|&a, &b| self.scores[b].total_cmp(&self.scores[a]).then(a.cmp(&b)));
        ranked
    }

    /// Return top-k candidate indices (best first).
    ///
    /// Returns fewer than `k` if there are fewer than `k` candidates.
    pub fn top_k(&self, k: usize) -> Vec<usize> {
        self.rank().into_iter().take(k).collect()
    }

    /// Get score for a specific candidate.
    #[inline]
    pub fn score(&self, idx: usize) -> f32 {
        self.scores[idx]
    }

    /// Number of candidates.
    #[inline]
    pub fn len(&self) -> usize {
        self.scores.len()
    }

    /// Whether there are no candidates.
    #[inline]
    pub fn is_empty(&self) -> bool {
        self.scores.is_empty()
    }
}

use katgpt_core::closure::{
    NodeId, OperatorKind, PrimitiveKind, PrimitiveTransitionGraph, PtgRecorder,
};
use katgpt_core::traits::ScreeningPruner;

#[cfg(feature = "bandit")]
use crate::absorb_compress::AbsorbCompress;

/// Reserved primitive id emitted on every `compress()` event.
///
/// 254 is below `PrimitiveKind::USER_DEFINED_MAX` (256) and intentionally
/// near the top of the user-defined space so it cannot collide with bandit
/// arm ids in any reasonable vocabulary (≤ 254 arms). If your bandit has
/// ≥ 255 arms, call [`PtgTracedPruner::trace`] manually with a non-conflicting id.
pub const COMPRESS_PRIMITIVE_ID: u32 = 254;

/// Reserved primitive id emitted on `prepare_episode`-style trace events
/// that mark the root of an episode (e.g. `BanditPruner::prepare_episode`).
pub const PREPARE_PRIMITIVE_ID: u32 = 253;

/// Zero-cost decorator that turns any [`ScreeningPruner`] into a
/// [`PrimitiveTransitionGraph`] source.
///
/// See the [module docs](self) for the full event table and lifecycle.
///
/// # Example
///
/// ```ignore
/// use katgpt_pruners::closure_wire::{PtgTracedPruner, COMPRESS_PRIMITIVE_ID};
/// use katgpt_rs::pruners::{AbsorbCompressLayer, CompressConfig};
/// use katgpt_rs::speculative::types::NoScreeningPruner;
///
/// let inner = AbsorbCompressLayer::new(NoScreeningPruner, 4, CompressConfig::default());
/// let mut traced = PtgTracedPruner::new(inner);
///
/// traced.start_episode(42);
/// traced.absorb(0, 0.7);   // emits UserDefined(0) node, Sequence edge
/// traced.absorb(1, 0.1);   // emits UserDefined(1) node, Sequence edge
/// let _promoted = traced.compress();  // emits UserDefined(254) node, Branch edge
/// let ptg = traced.finish_episode().expect("non-empty episode");
/// assert_eq!(ptg.task_family_id, 42);
/// ```
pub struct PtgTracedPruner<P: ScreeningPruner> {
    /// The wrapped pruner. All trait methods delegate here.
    inner: P,
    /// Active recorder. `None` outside an episode bracket.
    recorder: Option<PtgRecorder>,
    /// Id of the most recently entered node — used to attach edges.
    last_node: Option<NodeId>,
    /// Monotonic per-episode tick counter. Used as the `tick` field on each
    /// emitted [`katgpt_core::closure::PtgNode`].
    tick: u32,
}

impl<P: ScreeningPruner> PtgTracedPruner<P> {
    /// Wrap `inner` with PTG tracing. No episode is active until
    /// [`start_episode`](Self::start_episode) is called.
    #[inline]
    #[must_use]
    pub fn new(inner: P) -> Self {
        Self {
            inner,
            recorder: None,
            last_node: None,
            tick: 0,
        }
    }

#[cfg(feature = "bandit")]
impl<P: AbsorbCompress> AbsorbCompress for PtgTracedPruner<P> {
    /// Delegate to the inner pruner, then emit a
    /// `UserDefined(arm)` node linked with [`OperatorKind::Sequence`].
    ///
    /// Arm ids ≥ 256 are clamped into the user-defined space by
    /// [`PrimitiveKind::UserDefined`] (its `to_u32` keeps only the low byte).
    /// For corpora where distinct arms share a low byte, supply your own
    /// primitive mapping via [`PtgTracedPruner::trace`].
    #[inline]
    fn absorb(&mut self, arm: usize, reward: f32) {
        self.inner.absorb(arm, reward);
        let prim = PrimitiveKind::UserDefined(arm.min(255) as u32);
        self.trace(prim, OperatorKind::Sequence);
    }

