impl TemplateGrounding {
    /// Template confidence: `sigmoid(1.0) ≈ 0.7310585`.
    /// Pre-computed because `f32::exp` is not `const fn`.
    const TEMPLATE_CONFIDENCE: f32 = 0.7310586;

    /// Create a new `TemplateGrounding` with the default template table.
    pub fn new() -> Self {
        Self {
            templates: Vec::new(), // vocab-dependent templates filled by caller
        }
    }

    /// Create with custom template table.
    pub fn with_templates(templates: Vec<(&'static str, &'static str)>) -> Self {
        Self { templates }
    }

    /// Interpret a pruner score into a semantic label.
    fn interpret_score(score: f32) -> &'static str {
        match score {
            s if s > 0.8 => "high confidence",
            s if s > 0.5 => "moderate confidence",
            _ => "low confidence / rejected",
        }
    }

    /// Interpret tree depth into a semantic label.
    fn interpret_depth(depth: usize) -> &'static str {
        match depth {
            0 => "top-level declaration",
            1 => "type annotation or parameter",
            2 => "function body or expression",
            _ => "nested expression",
        }
    }
}

impl ConceptGrounding for TemplateGrounding {
    fn ground(&self, state: &PrunerState) -> Vec<ConceptMapping> {
        let mut mappings = Vec::with_capacity(state.pruner_scores.len() + 2);
        let conf = Self::TEMPLATE_CONFIDENCE;

        // Depth-based grounding
        let depth_semantic = Self::interpret_depth(state.depth);
        mappings.push(ConceptMapping {
            variable: "depth".to_string(),
            semantic: depth_semantic.to_string(),
            confidence: conf,
            source: GroundingSource::Template,
        });

        // Token-based grounding — vocab-dependent, use feature names from caller
        // Only produce a mapping if templates are populated
        for (pattern, semantic) in &self.templates {
            // Match against token_idx as a proxy for vocab position
            if state.token_idx > 0 {
                mappings.push(ConceptMapping {
                    variable: pattern.to_string(),
                    semantic: semantic.to_string(),
                    confidence: conf,
                    source: GroundingSource::Template,
                });
                break; // one token mapping per grounding
            }
        }

        // Score-based grounding for each pruner
        for (name, score) in &state.pruner_scores {
            let interpretation = Self::interpret_score(*score);
            mappings.push(ConceptMapping {
                variable: format!("pruner_{name}_score"),
                semantic: interpretation.to_string(),
                confidence: sigmoid(*score), // sigmoid-bound the raw score
                source: GroundingSource::Template,
            });
        }

        mappings
    }

    fn explain_chain(&self, state: &PrunerState, mappings: &[ConceptMapping]) -> Vec<String> {
        let mut chain = Vec::with_capacity(mappings.len() + 1);

        // Template: "Token at depth {depth} was {action} because {reason}"
        let action = if state.accepted {
            "accepted"
        } else {
            "rejected"
        };
        let reason = match state.depth {
            0 => "top-level declaration — always evaluated",
            1 => "type-level context — structural relevance",
            2 => "body-level context — semantic relevance",
            _ => "deep nesting — cumulative relevance check",
        };
        chain.push(format!(
            "Token {} at depth {} was {} because {}",
            state.token_idx, state.depth, action, reason
        ));

        // Template: "Pruner '{name}' scored {score:.2} ({interpretation})"
        for (name, score) in &state.pruner_scores {
            let interpretation = Self::interpret_score(*score);
            chain.push(format!(
                "Pruner '{name}' scored {score:.2} ({interpretation})"
            ));
        }

        // Template: "Combined relevance: {combined} → {decision}"
        if !state.pruner_scores.is_empty() {
            let combined: f32 = state.pruner_scores.iter().map(|(_, s)| *s).sum::<f32>()
                / state.pruner_scores.len() as f32;
            let decision = if state.accepted {
                "accepted"
            } else {
                "rejected"
            };
            chain.push(format!("Combined relevance: {combined:.2} → {decision}"));
        }

        // Append mapping-driven insights
        for m in mappings {
            if m.variable.starts_with("pruner_") {
                continue; // already covered above
            }
            chain.push(format!(
                "{} → {} (confidence: {:.2})",
                m.variable, m.semantic, m.confidence
            ));
        }

        chain
    }

    fn summarize(&self, mappings: &[ConceptMapping], chain: &[String]) -> String {
        if mappings.is_empty() && chain.is_empty() {
            return "No grounding available — empty pruner state.".to_string();
        }

        let accepted_count = mappings
            .iter()
            .filter(|m| m.semantic.contains("high confidence"))
            .count();
        let total_scorers = mappings
            .iter()
            .filter(|m| m.variable.starts_with("pruner_"))
            .count();

        let confidence_summary = match (accepted_count, total_scorers) {
            (0, 0) => "no scorer data".to_string(),
            (a, t) if a == t && t > 0 => "all scorers agree".to_string(),
            (0, t) => format!("unanimously rejected ({t} scorers)"),
            (a, t) => format!("{a}/{t} scorers confident"),
        };

        // Extract depth semantic if present
        let depth_desc = mappings
            .iter()
            .find(|m| m.variable == "depth")
            .map_or("unknown depth", |m| m.semantic.as_str());

        format!(
            "Decision at {} ({}): {}. {} reasoning steps.",
            depth_desc,
            confidence_summary,
            match chain.last() {
                Some(s) => s.clone(),
                None => "no reasoning".to_string(),
            },
            chain.len(),
        )
    }
}

impl ContextStats {
    fn new() -> Self {
        Self {
            q_values: [0.0; NUM_ARMS],
            visits: [0; NUM_ARMS],
            total_pulls: 0,
        }
    }

    /// UCB1 score for a given arm.
    /// Returns `f32::MAX` for unvisited arms (must explore first).
    #[inline]
    fn ucb1_score(&self, arm: usize) -> f32 {
        match (self.visits[arm], self.total_pulls) {
            (0, _) | (_, 0) => f32::MAX,
            (n, total) => {
                let q = self.q_values[arm];
                let ln_total = (total as f32).ln();
                q + (UCB1_C * ln_total / n as f32).sqrt()
            }
        }
    }

    /// Update Q-value for `arm` after observing `reward`.
    /// Uses incremental mean: `Q(a) += (reward - Q(a)) / n(a)`.
    #[inline]
    fn update(&mut self, arm: usize, reward: f32) {
        self.visits[arm] += 1;
        self.total_pulls += 1;
        let n = self.visits[arm] as f32;
        self.q_values[arm] += (reward - self.q_values[arm]) / n;
    }

    /// Select best arm by UCB1 score. Ties broken by lower index.
    fn best_ucb1_arm(&self) -> usize {
        let mut best_arm = 0;
        let mut best_score = self.ucb1_score(0);
        for arm in 1..NUM_ARMS {
            let score = self.ucb1_score(arm);
            if score > best_score {
                best_score = score;
                best_arm = arm;
            }
        }
        best_arm
    }
}

impl ConfiguratorBandit {
    /// Create a new configurator bandit with empty Q-table.
    pub fn new() -> Self {
        Self {
            stats: HashMap::new(),
        }
    }

    /// Get or create stats for a given context.
    fn get_or_create_stats(&mut self, context: ConfiguratorContext) -> &mut ContextStats {
        let key = (
            context.domain,
            context.entropy_bin,
            context.desperation_bin,
            context.epiplexity_bin,
        );
        self.stats.entry(key).or_insert_with(ContextStats::new)
    }

    /// Select a planning decision using UCB1 for the given context.
    ///
    /// UCB1 balances exploration (try new planning depths) vs exploitation
    /// (use known-good depth). Unvisited arms get `f32::MAX` score, ensuring
    /// each arm is tried at least once before exploiting.
    ///
    /// # Arguments
    ///
    /// * `context` — `(domain, entropy_bin)` context key
    ///
    /// # Returns
    ///
    /// The selected `PlanningDecision` arm.
    pub fn select(&mut self, context: ConfiguratorContext) -> PlanningDecision {
        let stats = self.get_or_create_stats(context);
        let arm = stats.best_ucb1_arm();
        from_arm_index(arm)
    }

    /// Update Q-value for a context-decision pair after observing reward.
    ///
    /// Uses incremental mean: `Q(a) += (reward - Q(a)) / n(a)`.
    ///
    /// # Arguments
    ///
    /// * `context` — `(domain, entropy_bin)` context key
    /// * `decision` — The arm that was selected
    /// * `reward` — Observed reward signal
    pub fn update(
        &mut self,
        context: ConfiguratorContext,
        decision: PlanningDecision,
        reward: f32,
    ) {
        let stats = self.get_or_create_stats(context);
        let arm = arm_index(decision);
        stats.update(arm, reward);
    }

    /// Discretize entropy into a coarse bin index.
    ///
    /// `floor(entropy * 10.0)`, clamped to `0..NUM_ENTROPY_BINS`.
    /// This provides 10 bins covering entropy range [0, ~3+):
    /// - Bin 0: entropy < 0.1 (very confident)
    /// - Bin 1: entropy 0.1..0.2
    /// - ...
    /// - Bin 9: entropy >= 0.9 (highly uncertain)
    ///
    /// # Arguments
    ///
    /// * `entropy` — Shannon entropy in nats (>= 0)
    ///
    /// # Returns
    ///
    /// Bin index in `0..10`.
    pub fn entropy_bin(entropy: f32) -> usize {
        let bin = (entropy * 10.0).floor() as usize;
        bin.min(NUM_ENTROPY_BINS - 1)
    }

    /// Compute reward signal for Q-value updates.
    ///
    /// `reward = quality_gain - β * token_cost`
    ///
    /// Encourages quality improvement while penalizing excessive token usage.
    /// Default β=0.1 provides mild cost regularization.
    ///
    /// # Arguments
    ///
    /// * `quality_gain` — Change in screening relevance (positive = improvement)
    /// * `token_cost` — Normalized token usage `tokens_used / tree_budget` in [0, 1]
    /// * `beta` — Cost regularization weight (default 0.1)
    ///
    /// # Returns
    ///
    /// Scalar reward signal.
    pub fn reward_signal(quality_gain: f32, token_cost: f32, beta: f32) -> f32 {
        quality_gain - beta * token_cost
    }

    /// Number of unique contexts seen so far.
    pub fn num_contexts(&self) -> usize {
        self.stats.len()
    }

    /// Get Q-value for a specific context and decision.
    /// Returns `None` if context has never been visited.
    pub fn q_value(&self, context: ConfiguratorContext, decision: PlanningDecision) -> Option<f32> {
        let key = (
            context.domain,
            context.entropy_bin,
            context.desperation_bin,
            context.epiplexity_bin,
        );
        self.stats
            .get(&key)
            .map(|s| s.q_values[arm_index(decision)])
    }

    /// Get visit count for a specific context and decision.
    /// Returns `0` if context has never been visited.
    pub fn visit_count(&self, context: ConfiguratorContext, decision: PlanningDecision) -> usize {
        let key = (
            context.domain,
            context.entropy_bin,
            context.desperation_bin,
            context.epiplexity_bin,
        );
        match self.stats.get(&key) {
            Some(s) => s.visits[arm_index(decision)],
            None => 0,
        }
    }

    /// Get total pulls for a specific context.
    /// Returns `0` if context has never been visited.
    pub fn total_pulls(&self, context: ConfiguratorContext) -> usize {
        let key = (
            context.domain,
            context.entropy_bin,
            context.desperation_bin,
            context.epiplexity_bin,
        );
        match self.stats.get(&key) {
            Some(s) => s.total_pulls,
            None => 0,
        }
    }
}

#[cfg(feature = "epiplexity_bandit")]
impl ConfiguratorBandit {
    /// Select with epiplexity-aware warm-start.
    ///
    /// For unvisited contexts, uses the S_T/H_T heuristic to suggest an arm.
    /// For visited contexts, falls back to standard UCB1.
    /// This accelerates convergence by guiding initial exploration toward
    /// theoretically-motivated arm choices.
    pub fn select_with_epiplexity(&mut self, context: ConfiguratorContext) -> PlanningDecision {
        let key = (
            context.domain,
            context.entropy_bin,
            context.desperation_bin,
            context.epiplexity_bin,
        );

        // If context has been visited, use UCB1.
        // Single hash lookup: `contains_key` + `get_mut().unwrap()` hashed the
        // key twice.
        if let Some(stats) = self.stats.get_mut(&key) {
            let arm = stats.best_ucb1_arm();
            return from_arm_index(arm);
        }

        // Unvisited context: use heuristic warm-start
        EpiplexityArmHeuristic::suggest(context.epiplexity_bin, context.entropy_bin)
    }

impl ExplorationOutcome {
    /// Convert to a scalar reward for bandit Q-value updates.
    ///
    /// | Outcome | Reward |
    /// |---------|--------|
    /// | `WinConfirmed` | +1.0 |
    /// | `StateReachedNoWin` | 0.0 |
    /// | `NotReached` | -0.5 |
    /// | `InvalidState` | -1.0 |
    pub fn to_reward(&self) -> f32 {
        match self {
            Self::WinConfirmed => 1.0,
            Self::StateReachedNoWin => 0.0,
            Self::NotReached => -0.5,
            Self::InvalidState => -1.0,
        }
    }
}

impl PrunerSchedule {
    /// Returns true if this schedule uses FrozenBaseGuard semantics.
    #[inline]
    pub fn is_frozen_base(&self) -> bool {
        matches!(self, Self::FrozenBaseGuard)
    }

    /// Returns true if this schedule applies full screening at every step.
    #[inline]
    pub fn is_uniform(&self) -> bool {
        matches!(self, Self::Uniform)
    }

    /// Determine if the given step should apply full screening.
    ///
    /// For `FrozenBaseGuard`: only true when `hop_index == total_hops - 1`.
    /// For `Uniform`: always true.
    /// For `EntropyRouted`: always true (routing happens at pruner level).
    #[inline]
    pub fn should_screen_full(&self, hop_index: usize, total_hops: usize) -> bool {
        match self {
            Self::Uniform => true,
            Self::FrozenBaseGuard => hop_index >= total_hops.saturating_sub(1),
            #[cfg(feature = "directional_credit")]
            Self::EntropyRouted { .. } => true,
        }
    }

    /// Get the entropy threshold as `f32` (only meaningful for `EntropyRouted`).
    #[cfg(feature = "directional_credit")]
    #[inline]
    pub fn threshold_f32(&self) -> Option<f32> {
        match self {
            Self::EntropyRouted { threshold } => Some(f32::from_bits(*threshold)),
            _ => None,
        }
    }

    /// Construct an `EntropyRouted` schedule from an `f32` threshold.
    #[cfg(feature = "directional_credit")]
    #[inline]
    pub fn entropy_routed(threshold: f32) -> Self {
        Self::EntropyRouted {
            threshold: threshold.to_bits(),
        }
    }
}

impl Pattern {
    /// Compute acceptance rate from support and total occurrences.
    ///
    /// Returns `support / total` clamped to [0, 1].
    pub fn acceptance_rate(&self, total_occurrences: usize) -> f32 {
        if total_occurrences == 0 {
            return 0.0;
        }
        self.support as f32 / total_occurrences as f32
    }
}

impl SequenceConstraint {
    /// Convert a mined pattern to a constraint.
    ///
    /// Returns `None` if the pattern has fewer than 2 tokens or
    /// acceptance_rate < `min_acceptance`.
    pub fn from_pattern(pattern: &Pattern, min_acceptance: f32) -> Option<Self> {
        match pattern.tokens.len() {
            2 if pattern.acceptance_rate >= min_acceptance => Some(Self {
                first: pattern.tokens[0],
                second: pattern.tokens[1],
                third: None,
                acceptance_rate: pattern.acceptance_rate,
            }),
            3 if pattern.acceptance_rate >= min_acceptance => Some(Self {
                first: pattern.tokens[0],
                second: pattern.tokens[1],
                third: Some(pattern.tokens[2]),
                acceptance_rate: pattern.acceptance_rate,
            }),
            _ => None,
        }
    }

    /// blake3 hash of the constraint for integrity audit.
    pub fn blake3_hash(&self) -> [u8; 32] {
        let mut hasher = blake3::Hasher::new();
        hasher.update(&self.first.to_le_bytes());
        hasher.update(&self.second.to_le_bytes());
        if let Some(t) = self.third {
            hasher.update(&t.to_le_bytes());
        } else {
            hasher.update(&[0u8; 8]);
        }
        hasher.update(&self.acceptance_rate.to_le_bytes());
        *hasher.finalize().as_bytes()
    }
}

impl CountMinSketch {
    /// Initialize all counters to zero.
    pub fn new() -> Self {
        Self {
            counters: Box::new([[0u16; COLS]; ROWS]),
            total_updates: 0,
        }
    }

    /// Derive column index for row `i` from a 32-byte key, in two halves:
    /// [`Self::fold_key`] (row-invariant) then [`Self::col_from_folded`].
    ///
    /// The key is already a BLAKE3 hash, so we XOR-fold 4×8-byte chunks to get
    /// a single u64, then multiply by the row seed and take modulo 256.
    ///
    /// The row-INVARIANT half: XOR-fold the 32-byte key into a single `u64`.
    /// Split out so `update` / `estimate` do the 4 unaligned loads + 3 XORs
    /// once instead of once per row.
    #[inline]
    fn fold_key(key: &[u8; 32]) -> u64 {
        let k0 = u64::from_le_bytes(key[0..8].try_into().unwrap());
        let k1 = u64::from_le_bytes(key[8..16].try_into().unwrap());
        let k2 = u64::from_le_bytes(key[16..24].try_into().unwrap());
        let k3 = u64::from_le_bytes(key[24..32].try_into().unwrap());
        k0 ^ k1 ^ k2 ^ k3
    }

    /// The row-DEPENDENT half: mix the folded key with the row seed.
    #[inline]
    fn col_from_folded(folded: u64, row: usize) -> usize {
        let mixed = folded.wrapping_mul(SEEDS[row]);
        (mixed as usize) % COLS
    }

    /// Increment counters for `key`. Saturates at `u16::MAX` per cell.
    pub fn update(&mut self, key: &[u8; 32]) {
        let folded = Self::fold_key(key);
        for row in 0..ROWS {
            let col = Self::col_from_folded(folded, row);
            self.counters[row][col] = self.counters[row][col].saturating_add(1);
        }
        self.total_updates = self.total_updates.saturating_add(1);
    }

    /// Minimum counter across all 4 rows → upper-bound estimate of true frequency.
    ///
    /// Returns `u32` to avoid overflow when callers compare against `u32` thresholds.
    #[inline]
    pub fn estimate(&self, key: &[u8; 32]) -> u32 {
        let folded = Self::fold_key(key);
        let mut min = u16::MAX;
        for row in 0..ROWS {
            let col = Self::col_from_folded(folded, row);
            min = min.min(self.counters[row][col]);
        }
        min as u32
    }

    /// Multiply all 1024 counters by `lambda`, truncating to u16.
    ///
    /// O(1024) constant time — no per-key iteration. Typical lambda ∈ [0.5, 1.0]
    /// for gradual aging.
    ///
    /// Uses Q16 fixed-point integer math to avoid f32 arithmetic on hot path.
    /// `lambda_fixed = round(lambda * 65536)`, then `new_v = (v * lambda_fixed) >> 16`.
    pub fn decay(&mut self, lambda: f32) {
        let lambda_fixed = (lambda * 65536.0) as u32;
        for row in 0..ROWS {
            for col in 0..COLS {
                let v = self.counters[row][col] as u32;
                self.counters[row][col] = ((v * lambda_fixed) >> 16) as u16;
            }
        }
    }

    /// Zero all counters and reset update count.
    pub fn reset(&mut self) {
        *self.counters = [[0u16; COLS]; ROWS];
        self.total_updates = 0;
    }

    /// Total number of `update()` calls since creation or last reset.
    #[inline]
    pub fn total_updates(&self) -> u64 {
        self.total_updates
    }

    /// Number of counter cells (always 1024 = 4 × 256).
    pub fn cell_count() -> usize {
        ROWS * COLS
    }
}

impl EosProxyScorer {
    /// Create a new scorer for `num_groups` depth positions.
    ///
    /// `ema_rate` controls smoothing (0.1 = slow, 0.5 = fast).
    pub fn new(num_groups: usize, ema_rate: f32) -> Self {
        let ema_rate = ema_rate.clamp(0.01, 1.0);
        Self {
            persistence: vec![0.0; num_groups],
            alignment: vec![0.0; num_groups],
            ema_rate,
            loss_mean: vec![0.0; num_groups],
            influence: vec![0.0; num_groups],
            softmax_scratch: Vec::new(),
            influence_dirty: false,
        }
    }

    /// Return the alignment (score concentration) for group `k`.
    pub fn alignment(&self, group: usize) -> f32 {
        match self.alignment.get(group) {
            Some(&v) => v,
            None => 0.0,
        }
    }

    /// Return the persistence (loss residual) for group `k`.
    pub fn persistence(&self, group: usize) -> f32 {
        match self.persistence.get(group) {
            Some(&v) => v,
            None => 0.0,
        }
    }

    /// Ensure the influence cache is up-to-date, recomputing only when dirty.
    fn ensure_influence(&mut self) {
        if !self.influence_dirty {
            return;
        }
        let max_val = self
            .persistence
            .iter()
            .zip(self.alignment.iter())
            .map(|(&p, &a)| p * a)
            .fold(0.0f32, f32::max);

        for i in 0..self.influence.len() {
            let raw = self.persistence[i] * self.alignment[i];
            self.influence[i] = if max_val > 0.0 { raw / max_val } else { 0.0 };
        }
        self.influence_dirty = false;
    }
}

impl CurvatureInfluenceScorer for EosProxyScorer {
    fn curvature_influence(&mut self, group: usize) -> f32 {
        self.ensure_influence();
        match self.influence.get(group) {
            Some(&v) => v,
            None => 0.0,
        }
    }

    fn num_groups(&self) -> usize {
        self.persistence.len()
    }

    fn update_persistence(&mut self, group: usize, loss: f32) {
        if group >= self.persistence.len() {
            return;
        }
        let alpha = self.ema_rate;
        let residual = (loss - self.loss_mean[group]).abs();
        // EMA update of loss mean
        self.loss_mean[group] = (1.0 - alpha) * self.loss_mean[group] + alpha * loss;
        // EMA update of persistence (residual magnitude)
        self.persistence[group] = (1.0 - alpha) * self.persistence[group] + alpha * residual;
        self.influence_dirty = true;
    }

    fn update_alignment(&mut self, group: usize, scores: &[f32]) {
        if group >= self.alignment.len() || scores.is_empty() {
            return;
        }
        // Compute softmax entropy using pre-allocated scratch buffer
        let max_score = scores.iter().copied().fold(f32::NEG_INFINITY, f32::max);
        self.softmax_scratch.clear();
        self.softmax_scratch.extend(scores.iter().map(|&s| {
            use katgpt_core::simd::fast_exp;
            fast_exp(s - max_score)
        }));
        let sum: f32 = self.softmax_scratch.iter().sum();
        if sum <= 0.0 {
            self.alignment[group] = 0.0;
            self.influence_dirty = true;
            return;
        }
        let entropy: f32 = self
            .softmax_scratch
            .iter()
            .map(|&e| {
                let p = e / sum;
                if p > 0.0 { -p * p.ln() } else { 0.0 }
            })
            .sum();

        // Maximum entropy = ln(n)
        let max_entropy = (scores.len() as f32).ln();
        let normalized_entropy = if max_entropy > 0.0 {
            entropy / max_entropy
        } else {
            0.0
        };
        // Alignment = 1 − normalized_entropy (high when concentrated)
        self.alignment[group] = (1.0 - normalized_entropy).clamp(0.0, 1.0);
        self.influence_dirty = true;
    }
}

impl CurvatureWeightedBudget {
    /// Create with default parameters.
    pub fn new() -> Self {
        Self {
            floor_ratio: 0.1,
            max_boost: 0.5,
        }
    }

    /// Allocate `total_budget` tokens across `max_depth` positions.
    ///
    /// Each position gets weight = influence(depth) + floor_ratio.
    /// Weights are normalized, then budget is distributed proportionally.
    pub fn allocate(
        &self,
        total_budget: usize,
        max_depth: usize,
        scorer: &mut dyn CurvatureInfluenceScorer,
    ) -> Vec<usize> {
        if max_depth == 0 || total_budget == 0 {
            return vec![];
        }

        // Compute weights
        let mut weights: Vec<f32> = (0..max_depth)
            .map(|d| scorer.curvature_influence(d) + self.floor_ratio)
            .collect();

        // Cap weights by max_boost over uniform
        let uniform = 1.0 / max_depth as f32;
        let cap = uniform * (1.0 + self.max_boost);
        for w in &mut weights {
            *w = w.min(cap);
        }

        let weight_sum: f32 = weights.iter().sum();
        if weight_sum <= 0.0 {
            // Fallback: uniform
            let per = total_budget / max_depth;
            let mut alloc = vec![per; max_depth];
            let remainder = total_budget - per * max_depth;
            for item in alloc.iter_mut().take(remainder) {
                *item += 1;
            }
            return alloc;
        }

        // Proportional allocation
        let raw: Vec<f32> = weights
            .iter()
            .map(|w| w / weight_sum * total_budget as f32)
            .collect();

        // Round using largest-remainder method to preserve total
        let floored: Vec<usize> = raw.iter().map(|r| r.floor() as usize).collect();
        let allocated: usize = floored.iter().sum();
        let remainder = total_budget - allocated;

        // Distribute remainder to positions with largest fractional parts
        let mut fractional: Vec<(usize, f32)> = raw
            .iter()
            .zip(floored.iter())
            .enumerate()
            .map(|(i, (r, f))| (i, r - *f as f32))
            .collect();
        fractional.sort_by(|a, b| b.1.total_cmp(&a.1));

        let mut result = floored;
        for (idx, _) in fractional.into_iter().take(remainder) {
            result[idx] += 1;
        }

        result
    }
}

