impl CounterfactualEstimator {
    pub fn new(dropout_fraction: f32, mc_samples: usize) -> Self {
        Self {
            dropout_fraction,
            mc_samples,
        }
    }

    /// Estimate utility of each merged arm group in the replacement set.
    ///
    /// `utility(e) = U(S) − E[U(S\\{e})]` for random dropout.
    /// Uses the provided evaluator function as utility signal.
    pub fn estimate_utility(
        &self,
        replacement: &ReplacementSet,
        evaluator: &dyn Fn(&[usize]) -> f32,
        rng: &mut Rng,
    ) -> Vec<f32> {
        if replacement.merged.is_empty() {
            return Vec::new();
        }

        // Full set utility
        let all_indices: Vec<usize> = replacement
            .merged
            .iter()
            .flat_map(|(indices, _)| indices.iter().copied())
            .collect();
        let u_full = evaluator(&all_indices);

        // Per-group utility via counterfactual dropout
        let mut utilities = Vec::with_capacity(replacement.merged.len());
        // Reusable scratch buffers — cleared each iteration, never reallocated
        // after first use. Avoids per-MC-sample allocation in the inner loop.
        let mut without: Vec<usize> = Vec::with_capacity(all_indices.len());
        let mut without_dropped: Vec<usize> = Vec::with_capacity(all_indices.len());

        for (group_indices, _) in &replacement.merged {
            let mut utility_sum = 0.0f32;

            for _ in 0..self.mc_samples {
                // Create set without this group (reuse scratch)
                without.clear();
                without.extend(
                    all_indices
                        .iter()
                        .filter(|&&i| !group_indices.contains(&i))
                        .copied(),
                );

                // Randomly drop additional fraction of other arms (reuse scratch)
                without_dropped.clear();
                without_dropped.extend(
                    without
                        .iter()
                        .filter(|_| rng.uniform() > self.dropout_fraction)
                        .copied(),
                );

                let u_without = if without_dropped.is_empty() {
                    0.0
                } else {
                    evaluator(&without_dropped)
                };

                utility_sum += u_full - u_without;
            }

            utilities.push(utility_sum / self.mc_samples.max(1) as f32);
        }

        utilities
    }
}

impl MemoryDecay {
    pub fn new(policy: DecayPolicy) -> Self {
        Self { policy }
    }

    /// Apply decay to Q-values. Arms in the working region are exempt.
    ///
    /// Returns vec of `(index, decayed_q)` for arms not in region.
    pub fn apply(
        &self,
        q_values: &[f32],
        last_access: &[usize],
        region: &WorkingRegion,
        current_episode: usize,
    ) -> Vec<(usize, f32)> {
        let region_set: HashSet<usize> = region.arm_indices.iter().copied().collect();

        match self.policy {
            DecayPolicy::None => q_values
                .iter()
                .enumerate()
                .filter(|(i, _)| !region_set.contains(i))
                .map(|(i, &q)| (i, q))
                .collect(),
            DecayPolicy::Exponential { factor } => q_values
                .iter()
                .enumerate()
                .filter(|(i, _)| !region_set.contains(i))
                .map(|(i, &q)| (i, q * factor))
                .collect(),
            DecayPolicy::AccessBased { half_life } => q_values
                .iter()
                .enumerate()
                .filter(|(i, _)| !region_set.contains(i))
                .map(|(i, &q)| {
                    let age =
                        current_episode.saturating_sub(last_access.get(i).copied().unwrap_or(0));
                    let decay = 0.5f32.powi(age as i32 / half_life.max(1) as i32);
                    (i, q * decay)
                })
                .collect(),
        }
    }
}

use super::pipeline::DreamerPipeline;

// ---------------------------------------------------------------------------
// DreamerFrozenBank
// ---------------------------------------------------------------------------

/// Frozen snapshot of a Dreamer pipeline state.
///
/// `repr(C)` for stable binary layout across compilations.
/// Use `save_frozen_dreamer` / `load_frozen_dreamer` for disk I/O.
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct DreamerFrozenBank {
    /// Magic bytes: `b"DRMR"`.
    pub magic: [u8; 4],
    /// Format version (currently 1).
    pub version: u32,
    /// Episode counter at save time.
    pub current_episode: u64,
    /// Number of consolidations performed.
    pub consolidation_count: u64,
    /// Cumulative arms before consolidations.
    pub total_arms_before: u64,
    /// Cumulative arms after consolidations.
    pub total_arms_after: u64,
    /// Cumulative arms forgotten.
    pub total_forgotten: u64,
    /// Config cadence at save time.
    pub cadence: u64,
    /// Config decay factor at save time.
    pub decay_factor: f32,
    /// Reserved for future use (explicit padding).
    pub _reserved: [u8; 4],
}

impl DreamerFrozenBank {
    pub const MAGIC: [u8; 4] = *b"DRMR";
    pub const VERSION: u32 = 1;

    /// Create a frozen snapshot from a live pipeline.
    pub fn from_pipeline(pipeline: &DreamerPipeline) -> Self {
        let config = pipeline.config();
        Self {
            magic: Self::MAGIC,
            version: Self::VERSION,
            current_episode: pipeline.episode() as u64,
            consolidation_count: pipeline.consolidation_count() as u64,
            total_arms_before: 0,
            total_arms_after: 0,
            total_forgotten: 0,
            cadence: config.cadence as u64,
            decay_factor: config.decay_factor,
            _reserved: [0u8; 4],
        }
    }

    /// Create a frozen snapshot with cumulative stats from a pipeline and result history.
    pub fn from_pipeline_with_stats(
        pipeline: &DreamerPipeline,
        total_arms_before: u64,
        total_arms_after: u64,
        total_forgotten: u64,
    ) -> Self {
        let mut bank = Self::from_pipeline(pipeline);
        bank.total_arms_before = total_arms_before;
        bank.total_arms_after = total_arms_after;
        bank.total_forgotten = total_forgotten;
        bank
    }

    /// Validate magic bytes and version.
    pub fn validate(&self) -> Result<(), String> {
        match self.magic {
            m if m == Self::MAGIC => {}
            m => {
                return Err(format!(
                    "DreamerFrozenBank: bad magic {:?}, expected {:?}",
                    m,
                    Self::MAGIC
                ));
            }
        }
        match self.version {
            v if v == Self::VERSION => {}
            v => {
                return Err(format!(
                    "DreamerFrozenBank: bad version {v}, expected {}",
                    Self::VERSION
                ));
            }
        }
        Ok(())
    }

    /// Human-readable summary of the frozen bank state.
    pub fn summary(&self) -> String {
        let arms_delta = self.total_arms_before.saturating_sub(self.total_arms_after);
        format!(
            "DreamerFrozenBank(episode={}, consolidations={}, arms_before={}, arms_after={}, forgotten={}, delta={arms_delta}, cadence={}, decay={})",
            self.current_episode,
            self.consolidation_count,
            self.total_arms_before,
            self.total_arms_after,
            self.total_forgotten,
            self.cadence,
            self.decay_factor,
        )
    }

    /// Arms saved through consolidation (before - after).
    pub fn arms_saved(&self) -> u64 {
        self.total_arms_before.saturating_sub(self.total_arms_after)
    }

    /// Compression ratio (arms_after / arms_before). Returns 1.0 if no arms.
    pub fn compression_ratio(&self) -> f32 {
        match self.total_arms_before {
            0 => 1.0,
            before => self.total_arms_after as f32 / before as f32,
        }
    }
}

