// ── Type Aliases ──────────────────────────────────────────────

/// Stair traversal result: (stair_index, entrance_pos, exit_pos).
type StairTraversal = (usize, (usize, usize), (usize, usize));

/// Best stair candidate: (distance, stair_index, entrance_pos, exit_pos).
type StairCandidate = (u32, usize, (usize, usize), (usize, usize));

// ── Dungeon Action ────────────────────────────────────────────

/// An action in the multi-floor dungeon context.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum DungeonAction {
    /// A* path step (action 0-3: Up/Down/Left/Right).
    Move(usize),
    /// Attack monster on current tile.
    Attack,
    /// Use stairs, index into `DungeonMap::stairs`.
    UseStairs(usize),
}

impl DungeonAction {
    /// Returns the action name for display.
    pub fn name(&self) -> &'static str {
        match self {
            Self::Move(a) => match a {
                0 => "↑ Up",
                1 => "↓ Down",
                2 => "← Left",
                3 => "→ Right",
                _ => "???",
            },
            Self::Attack => "⚔ Attack",
            Self::UseStairs(_) => "🪜 Stairs",
        }
    }

impl MultiFloorTarget {
    /// Returns the 3D position `(floor, r, c)` of this target.
    pub fn pos(
        &self,
        monsters: &[(usize, usize, usize)],
        treasures: &[(usize, usize, usize)],
        goal: (usize, usize, usize),
    ) -> (usize, usize, usize) {
        match self {
            Self::Monster(i) => monsters[*i],
            Self::Treasure(j) => treasures[*j],
            Self::Goal => goal,
        }
    }
}

impl DungeonMap {
    /// Build precomputed lookup tables from raw components.
    /// Called by both `new` and `from_parts`.
    fn build_lookups(
        floors: &[FloorGrid],
        monsters: &[(usize, usize, usize)],
        treasures: &[(usize, usize, usize)],
    ) -> DungeonLookups {
        let floor_cols: Vec<usize> = floors
            .iter()
            .map(|grid| grid.first().map_or(0, |r| r.len()))
            .collect();
        let all_treasures_mask = if treasures.is_empty() {
            0
        } else {
            ((1u64 << treasures.len()) - 1) as u32
        };
        let mut monster_at = vec![Vec::new(); floors.len()];
        let mut treasure_at = vec![Vec::new(); floors.len()];
        for (f_idx, grid) in floors.iter().enumerate() {
            let cols = floor_cols[f_idx];
            let area = grid.len() * cols;
            monster_at[f_idx] = vec![NO_ENTITY; area];
            treasure_at[f_idx] = vec![NO_ENTITY; area];
        }
        for (i, &(f, mr, mc)) in monsters.iter().enumerate() {
            if f < monster_at.len() {
                let cols = floor_cols[f];
                let flat = mr * cols + mc;
                if flat < monster_at[f].len() {
                    monster_at[f][flat] = i as i32;
                }
            }
        }
        for (i, &(f, tr, tc)) in treasures.iter().enumerate() {
            if f < treasure_at.len() {
                let cols = floor_cols[f];
                let flat = tr * cols + tc;
                if flat < treasure_at[f].len() {
                    treasure_at[f][flat] = i as i32;
                }
            }
        }
        (floor_cols, all_treasures_mask, monster_at, treasure_at)
    }

    /// Construct a `DungeonMap` from pre-parsed components.
    ///
    /// Used by tests and code that already has grid data (avoids re-parsing).
    /// Computes floor adjacency and flat entity lookups.
    #[cfg_attr(not(test), allow(dead_code))]
    pub(crate) fn from_parts(
        floors: Vec<FloorGrid>,
        stairs: Vec<StairConnection>,
        start: (usize, usize, usize),
        goal: (usize, usize, usize),
        monsters: Vec<(usize, usize, usize)>,
        treasures: Vec<(usize, usize, usize)>,
    ) -> Self {
        let floor_adj = build_floor_adj(floors.len(), &stairs);
        let (floor_cols, all_treasures_mask, monster_at, treasure_at) =
            Self::build_lookups(&floors, &monsters, &treasures);
        Self {
            floors,
            stairs,
            floor_adj,
            start,
            goal,
            monsters,
            treasures,
            floor_cols,
            all_treasures_mask,
            monster_at,
            treasure_at,
        }
    }

    /// Parse multiple floor map strings into a dungeon.
    ///
    /// Map symbols:
    /// - `B` or `S` = Start (player) — only one across all floors
    /// - `M` = Monster
    /// - `T` = Treasure (locked, needs item)
    /// - `G` = Goal/Exit
    /// - `X` = Monster + Treasure on same tile
    /// - `#` = Wall
    /// - `.` = Floor
    /// - `~` = Sand (cost 2)
    /// - `w` = Water (cost 3)
    pub fn new(floor_maps: &[&str], stairs: Vec<StairConnection>) -> Self {
        let mut floors = Vec::new();
        let mut start = (0usize, 0usize, 0usize);
        let mut goal = (0usize, 0usize, 0usize);
        let mut monsters = Vec::new();
        let mut treasures = Vec::new();

        for (floor_idx, map_str) in floor_maps.iter().enumerate() {
            let mut grid = Vec::new();

            for (r, line) in map_str.lines().enumerate() {
                let mut row = Vec::new();
                for (c, ch) in line.split_whitespace().enumerate() {
                    let char_val = ch.chars().next().unwrap();
                    match char_val {
                        'B' | 'S' => {
                            start = (floor_idx, r, c);
                            row.push('.');
                        }
                        'M' => {
                            monsters.push((floor_idx, r, c));
                            row.push('.');
                        }
                        'T' => {
                            treasures.push((floor_idx, r, c));
                            row.push('.');
                        }
                        'G' => {
                            goal = (floor_idx, r, c);
                            row.push('.');
                        }
                        'X' => {
                            monsters.push((floor_idx, r, c));
                            treasures.push((floor_idx, r, c));
                            row.push('.');
                        }
                        _ => row.push(char_val),
                    }
                }
                grid.push(row);
            }
            floors.push(grid);
        }

        let (floor_cols, all_treasures_mask, monster_at, treasure_at) =
            Self::build_lookups(&floors, &monsters, &treasures);
        let floor_adj = build_floor_adj(floors.len(), &stairs);

        Self {
            floors,
            stairs,
            floor_adj,
            start,
            goal,
            monsters,
            treasures,
            floor_cols,
            all_treasures_mask,
            monster_at,
            treasure_at,
        }
    }

    /// The starting state before any actions are taken.
    pub fn initial_state(&self) -> DungeonState {
        DungeonState {
            floor: self.start.0,
            r: self.start.1,
            c: self.start.2,
            inventory: 0,
            killed_monsters: 0,
            collected_treasures: 0,
            dropped_items: 0,
            total_cost: 0,
        }
    }
}

impl DungeonState {
    /// Returns a compact summary string of the state for display.
    pub fn summary(&self) -> String {
        let floor = self.floor;
        let r = self.r;
        let c = self.c;
        let inventory = self.inventory;
        let total_cost = self.total_cost;
        let killed_monsters = self.killed_monsters;
        let collected_treasures = self.collected_treasures;
        let dropped_items = self.dropped_items;
        format!(
            "floor={floor} pos=({r}, {c}) inv={inventory} cost={total_cost} killed={killed_monsters:b} treasures={collected_treasures:b} dropped={dropped_items:b}"
        )
    }
}

impl DungeonPruner {
    /// Create a new DungeonPruner from a DungeonMap.
    pub fn new(map: DungeonMap) -> Self {
        Self { map }
    }

    /// Returns the terrain cost of stepping onto a tile on the given floor.
    ///
    /// Terrain costs:
    /// - `.` = Floor (cost 1)
    /// - `~` = Sand (cost 2)
    /// - `w` = Water (cost 3)
    pub fn terrain_cost(&self, floor: usize, r: usize, c: usize) -> u32 {
        match self.map.floors[floor][r][c] {
            '~' => 2,
            'w' => 3,
            _ => 1,
        }
    }

    /// O(1) flat lookup: monster index at `(floor, r, c)` or `NO_ENTITY`.
    #[inline]
    fn monster_at(&self, floor: usize, r: usize, c: usize) -> i32 {
        let cols = *self.map.floor_cols.get(floor).unwrap_or(&0);
        self.map
            .monster_at
            .get(floor)
            .and_then(|lut| lut.get(r * cols + c))
            .copied()
            .unwrap_or(NO_ENTITY)
    }

    /// O(1) flat lookup: treasure index at `(floor, r, c)` or `NO_ENTITY`.
    #[inline]
    fn treasure_at(&self, floor: usize, r: usize, c: usize) -> i32 {
        let cols = *self.map.floor_cols.get(floor).unwrap_or(&0);
        self.map
            .treasure_at
            .get(floor)
            .and_then(|lut| lut.get(r * cols + c))
            .copied()
            .unwrap_or(NO_ENTITY)
    }

    /// Applies a single action to the state.
    ///
    /// Actions:
    /// - 0 = Up
    /// - 1 = Down
    /// - 2 = Left
    /// - 3 = Right
    /// - 4 = Attack
    /// - 5 = Use Stairs
    ///
    /// Returns `None` if the action is impossible.
    pub fn apply_action(&self, state: &DungeonState, action: usize) -> Option<DungeonState> {
        let mut next = *state;

        match action {
            0..=3 => self.apply_move(&mut next, action)?,
            4 => self.apply_attack(&mut next)?,
            5 => self.apply_stairs(&mut next)?,
            _ => return None,
        }

        Some(next)
    }

    /// Apply movement action (0=Up, 1=Down, 2=Left, 3=Right).
    fn apply_move(&self, next: &mut DungeonState, action: usize) -> Option<()> {
        let (dr, dc): (isize, isize) = match action {
            0 => (-1, 0),
            1 => (1, 0),
            2 => (0, -1),
            3 => (0, 1),
            _ => return None,
        };

        let nr = next.r as isize + dr;
        let nc = next.c as isize + dc;

        // Grid bounds check
        let grid = &self.map.floors[next.floor];
        if nr < 0 || nc < 0 || nr >= grid.len() as isize {
            return None;
        }
        let nr = nr as usize;
        let nc = nc as usize;
        if nc >= grid[nr].len() {
            return None;
        }

        // Wall collision
        if grid[nr][nc] == '#' {
            return None;
        }

        // Goal validation (locked until all treasures collected) — precomputed mask
        if (next.floor, nr, nc) == self.map.goal
            && next.collected_treasures != self.map.all_treasures_mask
        {
            return None;
        }

        // Check for a LIVE monster at the target tile — O(1) flat lookup
        let m_idx = self.monster_at(next.floor, nr, nc);
        let live_monster_here = m_idx != NO_ENTITY && (next.killed_monsters & (1 << m_idx)) == 0;

        // Treasure collection (locked without item) — O(1) flat lookup
        if !live_monster_here {
            let t_idx = self.treasure_at(next.floor, nr, nc);
            if t_idx != NO_ENTITY && (next.collected_treasures & (1 << t_idx)) == 0 {
                if next.inventory > 0 {
                    next.inventory -= 1;
                    next.collected_treasures |= 1 << t_idx;
                } else {
                    return None; // Cannot walk onto locked treasure without item
                }
            }
        }

        // Update coordinates
        next.r = nr;
        next.c = nc;

        // Accumulate movement cost (terrain-dependent)
        next.total_cost += self.terrain_cost(next.floor, nr, nc);

        // Auto-pickup dropped items at new tile — O(1) flat lookup
        if m_idx != NO_ENTITY
            && (next.dropped_items & (1 << m_idx)) != 0
            && next.inventory < MAX_INVENTORY
        {
            next.inventory += 1;
            next.dropped_items &= !(1 << m_idx);
        }

        Some(())
    }

    /// Apply attack action — must be standing on a live monster's tile.
    fn apply_attack(&self, next: &mut DungeonState) -> Option<()> {
        let m_idx = self.monster_at(next.floor, next.r, next.c);

        if m_idx == NO_ENTITY || (next.killed_monsters & (1 << m_idx)) != 0 {
            return None; // No live monster here to attack
        }

        next.killed_monsters |= 1 << m_idx;
        next.dropped_items |= 1 << m_idx;

        // Auto-pickup if inventory allows
        if next.inventory < MAX_INVENTORY {
            next.inventory += 1;
            next.dropped_items &= !(1 << m_idx);
        }

        // Check for treasure underneath the killed monster — O(1) flat lookup
        let t_idx = self.treasure_at(next.floor, next.r, next.c);
        if t_idx != NO_ENTITY
            && (next.collected_treasures & (1 << t_idx)) == 0
            && next.inventory > 0
        {
            next.inventory -= 1;
            next.collected_treasures |= 1 << t_idx;
        }

        Some(())
    }

    /// Apply use stairs action — must be standing on a stair connection.
    ///
    /// Stairs are bidirectional: standing on either `from` or `to` transitions
    /// to the opposite end.
    fn apply_stairs(&self, next: &mut DungeonState) -> Option<()> {
        let current_pos = (next.floor, next.r, next.c);

        // Find a stair connection matching current position
        let stair = self
            .map
            .stairs
            .iter()
            .find(|s| s.from == current_pos || s.to == current_pos)?;

        // Determine destination (opposite end of the connection)
        let destination = if stair.from == current_pos {
            stair.to
        } else {
            stair.from
        };

        // Validate destination is within bounds and passable
        let (dest_floor, dest_r, dest_c) = destination;
        if dest_floor >= self.map.floors.len() {
            return None;
        }

        let grid = &self.map.floors[dest_floor];
        if dest_r >= grid.len() || dest_c >= grid[dest_r].len() {
            return None;
        }

        if grid[dest_r][dest_c] == '#' {
            return None;
        }

        // Transition to new floor
        next.floor = dest_floor;
        next.r = dest_r;
        next.c = dest_c;
        next.total_cost += 1; // Base stair traversal cost

        Some(())
    }

    /// Replays a sequence of actions from the starting position.
    pub fn replay_state(&self, actions: &[usize]) -> Option<DungeonState> {
        let mut state = self.map.initial_state();
        for &action in actions {
            state = self.apply_action(&state, action)?;
        }
        Some(state)
    }

    /// Returns the starting state.
    pub fn initial_state(&self) -> DungeonState {
        self.map.initial_state()
    }

    /// Returns the action name for display.
    pub fn action_name(action: usize) -> &'static str {
        match action {
            0 => "Up",
            1 => "Down",
            2 => "Left",
            3 => "Right",
            4 => "Attack",
            5 => "Use Stairs",
            _ => "?",
        }
    }
}

