#[cfg(test)]
mod tests {
    #![allow(clippy::float_cmp)]

    use super::*;
    use crate::future_probe::BehaviorForecast;

    /// Linearly-separable 1D signal: activation[0] = +2 ± noise for label=true,
    /// −2 ± noise for label=false. Mean-difference should recover direction[0] as
    /// the dominant axis and the probe should classify cleanly.
    #[test]
    fn mean_difference_recovers_linearly_separable_direction() {
        // 10 positive, 10 negative, signal only in dim 0.
        let acts_pos: Vec<Vec<f32>> = (0..10)
            .map(|i| vec![2.0 + 0.1 * (i as f32 - 5.0), 0.0, 0.0, 0.0])
            .collect();
        let acts_neg: Vec<Vec<f32>> = (0..10)
            .map(|i| vec![-2.0 + 0.1 * (i as f32 - 5.0), 0.0, 0.0, 0.0])
            .collect();
        let mut samples = Vec::with_capacity(acts_pos.len());
        for a in &acts_pos {
            samples.push(LabeledActivation {
                activation: a,
                label: true,
            });
        }
        for a in &acts_neg {
            samples.push(LabeledActivation {
                activation: a,
                label: false,
            });
        }

        let probe = construct_probe_via_mean_difference(&samples, 7, "test_behavior")
            .expect("linearly-separable data must construct cleanly");

        // Direction should be ~[±1, 0, 0, 0] (sign depends on which class is "pos").
        // We defined pos = label=true = +2, so direction[0] > 0 after normalization.
        assert!(
            probe.forecast(&[2.0, 0.0, 0.0, 0.0]).probability > 0.99,
            "positive-class activation should forecast > 0.99"
        );
        assert!(
            probe.forecast(&[-2.0, 0.0, 0.0, 0.0]).probability < 0.01,
            "negative-class activation should forecast < 0.01"
        );
        // probe.layer() round-trips.
        assert_eq!(probe.layer(), 7);
    }

    #[test]
    fn rejects_empty_samples() {
        let err = construct_probe_via_mean_difference(&[], 0, "x").unwrap_err();
        assert_eq!(err, MeanDifferenceError::NoSamples);
    }

    #[test]
    fn rejects_single_class() {
        let a = vec![1.0, 0.0];
        let samples = [LabeledActivation {
            activation: &a,
            label: true,
        }];
        let err = construct_probe_via_mean_difference(&samples, 0, "x").unwrap_err();
        assert_eq!(err, MeanDifferenceError::SingleClass { n_pos: 1, n_neg: 0 });
    }

    #[test]
    fn rejects_mismatched_dimension() {
        let a = vec![1.0, 0.0];
        let b = vec![1.0, 0.0, 0.0];
        let samples = [
            LabeledActivation {
                activation: &a,
                label: true,
            },
            LabeledActivation {
                activation: &b,
                label: false,
            },
        ];
        let err = construct_probe_via_mean_difference(&samples, 0, "x").unwrap_err();
        assert_eq!(
            err,
            MeanDifferenceError::MismatchedDimension {
                first: 2,
                at: 1,
                got: 3
            }
        );
    }

    #[test]
    fn rejects_identical_centroids() {
        // Same activation for both classes → centroids identical → zero norm.
        let a = vec![1.0, 2.0, 3.0];
        let b = vec![1.0, 2.0, 3.0];
        let samples = [
            LabeledActivation {
                activation: &a,
                label: true,
            },
            LabeledActivation {
                activation: &b,
                label: false,
            },
        ];
        let err = construct_probe_via_mean_difference(&samples, 0, "x").unwrap_err();
        assert_eq!(err, MeanDifferenceError::ZeroNormDirection);
    }

    /// Determinism: same samples in same order → bit-identical probe (same hash).
    #[test]
    fn deterministic_given_same_input_order() {
        let acts: Vec<Vec<f32>> = (0..8)
            .map(|i| {
                if i < 4 {
                    vec![2.0, 0.0, 0.0]
                } else {
                    vec![-2.0, 0.0, 0.0]
                }
            })
            .collect();
        let samples: Vec<_> = acts
            .iter()
            .map(|a| LabeledActivation {
                activation: a,
                label: a[0] > 0.0,
            })
            .collect();

        let p1 = construct_probe_via_mean_difference(&samples, 3, "det").unwrap();
        let p2 = construct_probe_via_mean_difference(&samples, 3, "det").unwrap();
        assert_eq!(
            p1.artifact_hash(),
            p2.artifact_hash(),
            "same input order must produce bit-identical probe"
        );
    }

    /// Order-sensitivity: swapping sample order changes the floating-point sum
    /// rounding, so the hash MAY differ. This is documented behavior — pass
    /// samples in a stable order for a stable hash. The test just verifies
    /// both orders produce a valid probe that classifies correctly.
    #[test]
    fn both_orders_classify_correctly() {
        let mut acts: Vec<Vec<f32>> = (0..8)
            .map(|i| {
                if i % 2 == 0 {
                    vec![2.0, 0.0, 0.0]
                } else {
                    vec![-2.0, 0.0, 0.0]
                }
            })
            .collect();
        let mk = |order: &Vec<Vec<f32>>| -> FutureBehaviorProbe {
            let samples: Vec<_> = order
                .iter()
                .map(|a| LabeledActivation {
                    activation: a,
                    label: a[0] > 0.0,
                })
                .collect();
            construct_probe_via_mean_difference(&samples, 1, "order").unwrap()
        };
        let p1 = mk(&acts);
        acts.reverse();
        let p2 = mk(&acts);
        // Both classify correctly regardless of order.
        let f: BehaviorForecast = p1.forecast(&[2.0, 0.0, 0.0]);
        assert!(f.probability > 0.99);
        let f: BehaviorForecast = p2.forecast(&[2.0, 0.0, 0.0]);
        assert!(f.probability > 0.99);
    }

    /// Noisy signal: mean-difference recovers the dominant axis even with noise
    /// in non-signal dimensions. Verifies robustness.
    #[test]
    fn recovers_direction_amid_noise_in_other_dims() {
        let d = 8;
        // 20 samples, signal in dim 0, noise in dims 1..8.
        let acts: Vec<Vec<f32>> = (0..20)
            .map(|i| {
                let mut act = vec![0.0_f32; d];
                let label = i % 2 == 0;
                act[0] = if label { 1.5 } else { -1.5 };
                // Noise: bounded, zero-mean across the class.
                for (j, slot) in act.iter_mut().enumerate().skip(1) {
                    *slot = ((i as f32 * 0.3 + j as f32) - 3.0) * 0.05;
                }
                act
            })
            .collect();
        let samples: Vec<_> = acts
            .iter()
            .map(|a| LabeledActivation {
                activation: a,
                label: a[0] > 0.0,
            })
            .collect();
        let probe = construct_probe_via_mean_difference(&samples, 2, "noisy").expect("noise case");
        // Direction[0] should dominate (signal is ~30× the noise magnitude).
        // Positive-class activation → high forecast.
        let mut act_pos = vec![0.0_f32; d];
        act_pos[0] = 1.5;
        assert!(probe.forecast(&act_pos).probability > 0.9);
        let mut act_neg = vec![0.0_f32; d];
        act_neg[0] = -1.5;
        assert!(probe.forecast(&act_neg).probability < 0.1);
    }
}

impl FrequencyBand {
    /// Number of arms in the frequency bandit.
    pub const NUM_ARMS: usize = 3;

    /// Convert to arm index.
    #[inline]
    pub fn as_index(self) -> usize {
        self as usize
    }

    /// Convert from arm index. Returns `None` if out of range.
    #[inline]
    pub fn from_index(i: usize) -> Option<Self> {
        match i {
            0 => Some(Self::Low),
            1 => Some(Self::Mid),
            2 => Some(Self::High),
            _ => None,
        }
    }

    /// Recommended compute tier for this frequency band.
    ///
    /// High-frequency decode → prefer GPU (faster verify iterations).
    /// Low-frequency decode → CPU acceptable (longer draft OK).
    pub fn recommended_tier(self) -> ComputeTier {
        match self {
            Self::Low => ComputeTier::CpuOnly,    // Deep draft OK on CPU
            Self::Mid => ComputeTier::CpuGpu,     // Balanced, GPU helps
            Self::High => ComputeTier::CpuGpuAne, // Fast verify needs all hardware
        }
    }
}

impl FrequencyBand {
    /// Map this band to speculative decode parameters.
    pub fn spec_config(self) -> SpecBandConfig {
        match self {
            // Long-range patterns: invest in deep speculative lookahead
            Self::Low => SpecBandConfig {
                draft_tree_width: 5,
                draft_tree_depth: 8,
                verify_iterations: 1,
            },
            // Medium patterns: balanced config
            Self::Mid => SpecBandConfig {
                draft_tree_width: 4,
                draft_tree_depth: 5,
                verify_iterations: 2,
            },
            // Short-range patterns: shallow tree, more verify passes
            Self::High => SpecBandConfig {
                draft_tree_width: 3,
                draft_tree_depth: 3,
                verify_iterations: 3,
            },
        }
    }
}

impl FrequencyBandit {
    /// Create a new frequency bandit with default exploration constant.
    pub fn new() -> Self {
        Self {
            arm_q_values: [0.0; 3],
            arm_counts: [0; 3],
            exploration_c: 2.0f32.sqrt(),
            total_pulls: 0,
            last_selected: None,
        }
    }

    /// Create with custom exploration constant.
    pub fn with_exploration(mut self, c: f32) -> Self {
        self.exploration_c = c;
        self
    }

    /// Select a frequency band using UCB1.
    ///
    /// Unvisited arms are prioritized (score = +∞).
    /// For visited arms: `Q(a) + c * sqrt(ln(N) / n(a))`.
    pub fn select_band(&mut self, _rng: &mut Rng) -> FrequencyBand {
        // First pass: any unvisited arm gets priority
        for i in 0..3 {
            if self.arm_counts[i] == 0 {
                let band = FrequencyBand::from_index(i).unwrap();
                self.last_selected = Some(band);
                return band;
            }
        }

        // All arms visited: pick highest UCB1 score.
        // Hoist invariants out of the 3-arm loop: `ln(total)` and the
        // exploration constant only depend on total pulls, not on the arm.
        let ln_total = (self.total_pulls as f64).ln();
        let c = self.exploration_c as f64;
        let coef = c * (2.0 * ln_total).sqrt();

        let mut best_idx = 0;
        let mut best_score = f64::NEG_INFINITY;

        for i in 0..3 {
            let q = self.arm_q_values[i];
            // exploration = c * sqrt(2 * ln(N) / n)
            //             = (c * sqrt(2 * ln(N))) / sqrt(n)
            // The numerator is loop-invariant; only `1/sqrt(n)` varies per arm.
            let exploration = coef / (self.arm_counts[i] as f64).sqrt();
            let score = q + exploration;

            if score > best_score {
                best_score = score;
                best_idx = i;
            }
        }

        let band = FrequencyBand::from_index(best_idx).unwrap();
        self.last_selected = Some(band);
        band
    }

    /// Update Q-value for a band after observing reward.
    ///
    /// Uses incremental mean: `Q(a) += (reward - Q(a)) / n(a)`.
    pub fn update(&mut self, band: FrequencyBand, reward: f64) {
        let i = band.as_index();
        self.arm_counts[i] += 1;
        self.total_pulls += 1;
        // Pre-compute the reciprocal so we multiply instead of divide below.
        let inv_n = 1.0 / self.arm_counts[i] as f64;
        self.arm_q_values[i] += (reward - self.arm_q_values[i]) * inv_n;
    }

    /// Map a frequency band to speculative decode configuration.
    #[inline]
    pub fn map_to_spec_config(&self, band: FrequencyBand) -> SpecBandConfig {
        band.spec_config()
    }

    /// Q-value for a given band.
    #[inline]
    pub fn q_value(&self, band: FrequencyBand) -> f64 {
        self.arm_q_values[band.as_index()]
    }

    /// Pull count for a given band.
    #[inline]
    pub fn count(&self, band: FrequencyBand) -> u32 {
        self.arm_counts[band.as_index()]
    }

    /// Total pulls across all arms.
    #[inline]
    pub fn total_pulls(&self) -> u32 {
        self.total_pulls
    }

    /// Last selected band.
    #[inline]
    pub fn last_selected(&self) -> Option<FrequencyBand> {
        self.last_selected
    }

    /// Best arm by Q-value.
    pub fn best_arm(&self) -> FrequencyBand {
        let mut best = 0;
        let mut best_q = f64::NEG_INFINITY;
        for i in 0..3 {
            if self.arm_q_values[i] > best_q {
                best_q = self.arm_q_values[i];
                best = i;
            }
        }
        FrequencyBand::from_index(best).unwrap()
    }

    /// Get compute tier recommendation based on current best arm.
    /// Uses the band with highest cumulative Q-value.
    pub fn tier_recommendation(&self) -> ComputeTier {
        self.best_arm().recommended_tier()
    }

    // ── RV Bandit Pruning (Plan 202, Phase 4) ─────────────────────

    /// Compute per-arm reward variance using Welford online statistics.
    ///
    /// Returns `[f64; 3]` variances for [Low, Mid, High] arms.
    /// Arms with < 2 samples have variance = 0.0.
    #[cfg(feature = "rv_bandit_pruning")]
    pub fn arm_variances(&self) -> [f64; 3] {
        // Welford online variance from Q-value updates.
        // Since we only track incremental mean (Q(a)), not raw samples,
        // we use Q-value spread as a proxy: variance ≈ (Q(a) - Q_mean)².
        // Preserve original semantics: exclude zero Q-values from the mean.
        let mut q_sum = 0.0_f64;
        for &q in &self.arm_q_values {
            if q != 0.0 {
                q_sum += q;
            }
        }
        let q_mean = q_sum / 3.0_f64;
        let mut variances = [0.0; 3];
        for (i, &q) in self.arm_q_values.iter().enumerate() {
            if let 0 | 1 = self.arm_counts[i] {
                variances[i] = 0.0;
            } else {
                let delta = q - q_mean;
                variances[i] = delta * delta;
            }
        }
        variances
    }

    /// Suppress arms below the `(1 - ρ)` quantile of variance.
    ///
    /// RAGEN-2 proves nucleus-style filtering > top-k > no filter.
    /// Suppressed arms are penalized (Q-value set to -∞) so UCB1 avoids them.
    ///
    /// # Arguments
    /// * `rho` — retention fraction (0.0–1.0). 1.0 = no suppression.
    #[cfg(feature = "rv_bandit_pruning")]
    pub fn suppress_low_rv_arms(&mut self, rho: f32) {
        let variances = self.arm_variances();

        // Compute threshold at (1 - ρ) quantile
        let threshold = match rho {
            rho if rho >= 1.0 => return,        // No suppression
            rho if rho <= 0.0 => f64::INFINITY, // Suppress all
            _ => {
                // Sort variances to find quantile
                let mut sorted = variances;
                sorted.sort_by(|a, b| a.total_cmp(b));
                // (1 - ρ) quantile index
                let idx = ((1.0 - rho) * 2.0) as usize;
                sorted[idx.min(2)]
            }
        };

        // Suppress arms below threshold
        for (i, &v) in variances.iter().enumerate() {
            if v < threshold && self.arm_counts[i] > 0 {
                self.arm_q_values[i] = f64::NEG_INFINITY;
            }
        }
    }

    /// Check if an arm is suppressed (Q = -∞).
    #[cfg(feature = "rv_bandit_pruning")]
    pub fn is_arm_suppressed(&self, band: FrequencyBand) -> bool {
        self.arm_q_values[band.as_index()] == f64::NEG_INFINITY
    }

    /// Unsuppress all arms (reset Q-values from -∞ to 0).
    #[cfg(feature = "rv_bandit_pruning")]
    pub fn unsuppress_all(&mut self) {
        for q in &mut self.arm_q_values {
            if *q == f64::NEG_INFINITY {
                *q = 0.0;
            }
        }
    }
}

