/// ε-greedy rollout policy guided by bandit Q-values.
///
/// Plan 067 (NFSP/MCTS Duality): wires backward signal (bandit Q-values
/// accumulated across episodes) into forward search (MCTS rollouts).
/// This is the AlphaZero pattern, but modelless — no neural net, just
/// bandit statistics.
///
/// # Type Parameters
/// * `S` — game state type
/// * `F` — action-to-index mapping closure
///
/// # Action Mapping
/// The `action_to_index` closure maps `S::Action` → bandit arm index.
/// For `BomberAction`, use
/// `|a: &BomberAction| a.as_usize()`.
///
/// # Exploration (ε)
/// - `ε = 0.0`: pure exploit (always pick highest Q-value action)
/// - `ε = 0.2`: 80% exploit, 20% explore (good default)
/// - `ε = 1.0`: pure random (equivalent to [`RandomRolloutPolicy`])
///
/// [`RandomRolloutPolicy`]: katgpt_core::traits::RandomRolloutPolicy
#[cfg(feature = "bandit")]
pub struct BanditRolloutPolicy<'a, S, F>
where
    S: GameState,
    F: Fn(&S::Action) -> usize,
{
    /// Bandit statistics with accumulated Q-values.
    stats: &'a BanditStats,
    /// Exploration probability ∈ [0.0, 1.0].
    epsilon: f32,
    /// Maps game actions to bandit arm indices.
    action_to_index: F,
    /// Marker for the game state type (no ownership implied).
    _phantom: PhantomData<fn() -> S>,
}

#[cfg(feature = "bandit")]
impl<'a, S, F> BanditRolloutPolicy<'a, S, F>
where
    S: GameState,
    F: Fn(&S::Action) -> usize,
{
    /// Create a new bandit-guided rollout policy.
    ///
    /// # Arguments
    /// * `stats` — bandit statistics with accumulated Q-values from prior episodes
    /// * `epsilon` — exploration probability (0.0 = pure exploit, 1.0 = pure random)
    /// * `action_to_index` — maps game actions to bandit arm indices
    ///
    /// # Panics
    /// Panics if `epsilon` is not in `[0.0, 1.0]`.
    pub fn new(stats: &'a BanditStats, epsilon: f32, action_to_index: F) -> Self {
        assert!(
            (0.0..=1.0).contains(&epsilon),
            "epsilon must be in [0.0, 1.0], got {epsilon}"
        );
        Self {
            stats,
            epsilon,
            action_to_index,
            _phantom: PhantomData,
        }
    }

#[cfg(feature = "bandit")]
impl<S, F> RolloutPolicy<S> for BanditRolloutPolicy<'_, S, F>
where
    S: GameState,
    F: Fn(&S::Action) -> usize,
{
    fn select(
        &mut self,
        _state: &S,
        actions: &[S::Action],
        _player_id: u8,
        rng: &mut Rng,
    ) -> usize {
        // ε-greedy: explore with probability ε, exploit with probability (1-ε)
        if rng.usize(0..1000) < (self.epsilon * 1000.0) as usize {
            // Explore: random action
            rng.usize(0..actions.len())
        } else {
            // Exploit: pick action with highest bandit Q-value
            let mut best_idx = 0;
            let mut best_q = f32::NEG_INFINITY;
            for (i, action) in actions.iter().enumerate() {
                let arm = (self.action_to_index)(action);
                let q = self.stats.q_value(arm);
                if q > best_q {
                    best_q = q;
                    best_idx = i;
                }
            }
            best_idx
        }
    }

impl ConfigVariant {
    /// Create a config variant from flat arm index.
    #[inline]
    pub fn from_arm(arm: usize) -> Self {
        let a = arm % NUM_ABSORB_THRESHOLDS;
        let rest = arm / NUM_ABSORB_THRESHOLDS;
        let t = rest % NUM_TEMPLATE_HINTS;
        let rest = rest / NUM_TEMPLATE_HINTS;
        let e = rest % NUM_EPSILON_VALUES;
        let r = rest / NUM_EPSILON_VALUES;
        Self {
            rubric_preset: r as u8,
            epsilon_index: e as u8,
            template_hint: t as u8,
            absorb_threshold_index: a as u8,
        }
    }

    /// Convert back to flat arm index.
    #[inline]
    pub fn to_arm(&self) -> usize {
        let r = self.rubric_preset as usize;
        let e = self.epsilon_index as usize;
        let t = self.template_hint as usize;
        let a = self.absorb_threshold_index as usize;
        ((r * NUM_EPSILON_VALUES + e) * NUM_TEMPLATE_HINTS + t) * NUM_ABSORB_THRESHOLDS + a
    }

    /// Resolved rubric weights for this variant.
    #[inline]
    pub fn rubric_weights(&self) -> [f32; 4] {
        RUBRIC_PRESETS[self.rubric_preset as usize % NUM_RUBRIC_PRESETS]
    }

    /// Resolved epsilon for this variant.
    #[inline]
    pub fn epsilon(&self) -> f32 {
        EPSILON_VALUES[self.epsilon_index as usize % NUM_EPSILON_VALUES]
    }

    /// Resolved absorb threshold for this variant.
    #[inline]
    pub fn absorb_threshold(&self) -> f32 {
        ABSORB_THRESHOLDS[self.absorb_threshold_index as usize % NUM_ABSORB_THRESHOLDS]
    }

    /// Default (balanced) config variant — arm 0.
    pub fn default_variant() -> Self {
        Self {
            rubric_preset: 0,
            epsilon_index: 0,
            template_hint: 0,
            absorb_threshold_index: 0,
        }
    }
}

impl ReflectionScore {
    /// Compute score from a [`ReflectionResult`].
    ///
    /// Formula: `verification_rate * 0.7 + pair_signal * 0.3`
    /// where `pair_signal = min(pairs.len() / 50.0, 1.0)`.
    /// This rewards both verified correctness and reflection breadth.
    ///
    /// O(1) — only reads `verification_rate` and `pairs.len()`.
    pub fn from_reflection(result: &ReflectionResult) -> Self {
        let vr = result.verification_rate as f32;
        let pair_signal = (result.pairs.len() as f32 / 50.0).min(1.0);
        Self((vr * 0.7 + pair_signal * 0.3).clamp(0.0, 1.0))
    }

    /// Compute score from [`ReviewMetrics`] benefit ratio when no
    /// reflection is available. Falls back to a capped benefit ratio.
    ///
    /// Uses `min(benefit_ratio / 10.0, 1.0)` so infinite ratios
    /// map to 1.0.
    pub fn from_metrics(metrics: &ReviewMetrics) -> Self {
        let br = metrics.benefit_ratio() as f32;
        Self((br / 10.0).min(1.0))
    }

    /// Compute score preferring reflection, falling back to metrics.
    pub fn from_reflection_or_metrics(
        result: Option<&ReflectionResult>,
        metrics: Option<&ReviewMetrics>,
    ) -> Self {
        if let Some(r) = result {
            Self::from_reflection(r)
        } else if let Some(m) = metrics {
            Self::from_metrics(m)
        } else {
            Self(0.0)
        }
    }

    /// Raw scalar value in [0.0, 1.0].
    #[inline]
    pub fn value(&self) -> f32 {
        self.0
    }
}

impl ParetoConfigFrontier {
    /// Create an empty frontier.
    pub fn new() -> Self {
        let mut free_slots = Vec::with_capacity(MAX_CONFIGS);
        for i in (0..MAX_CONFIGS).rev() {
            free_slots.push(i);
        }
        Self {
            entries: [FrontierEntry {
                config: ConfigVariant::default(),
                reward: 0.0,
                cost: 0.0,
                occupied: false,
            }; MAX_CONFIGS],
            len: 0,
            free_slots,
        }
    }

    /// Number of entries currently on the frontier.
    #[inline]
    pub fn len(&self) -> usize {
        self.len
    }

    /// Whether the frontier is empty.
    #[inline]
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// Insert a variant. Returns `true` if it was added (non-dominated).
    ///
    /// After insertion, removes any entries dominated by the new one.
    /// If the frontier is full and the new entry is dominated, returns `false`.
    pub fn insert(&mut self, config: ConfigVariant, reward: f32, cost: f32) -> bool {
        // Check if dominated by any existing entry.
        for i in 0..MAX_CONFIGS {
            let e = &self.entries[i];
            if !e.occupied {
                continue;
            }
            // Dominated: existing has >= reward AND <= cost with at least one strict.
            let dominated =
                e.reward >= reward && e.cost <= cost && (e.reward > reward || e.cost < cost);
            if dominated {
                return false;
            }
        }

        // Remove entries dominated by the new one.
        for i in 0..MAX_CONFIGS {
            let e = &self.entries[i];
            if !e.occupied {
                continue;
            }
            // New dominates existing: reward >= existing AND cost <= existing,
            // with at least one strict.
            let new_dominates =
                reward >= e.reward && cost <= e.cost && (reward > e.reward || cost < e.cost);
            if new_dominates {
                self.entries[i].occupied = false;
                self.len -= 1;
                self.free_slots.push(i);
            }
        }

        // Find an empty slot via free-list (O(1)) instead of linear scan.
        let slot = self.free_slots.pop();
        match slot {
            Some(i) => {
                self.entries[i] = FrontierEntry {
                    config,
                    reward,
                    cost,
                    occupied: true,
                };
                self.len += 1;
                true
            }
            None => false, // Frontier full and no dominated entries to evict.
        }
    }

    /// Return the config with the highest reward on the frontier.
    ///
    /// Returns `None` if the frontier is empty.
    pub fn best(&self) -> Option<ConfigVariant> {
        let mut best: Option<&FrontierEntry> = None;
        for e in &self.entries {
            if !e.occupied {
                continue;
            }
            if best.is_none_or(|b| e.reward > b.reward) {
                best = Some(e);
            }
        }
        best.map(|e| e.config)
    }

    /// Return the lowest-cost config on the frontier.
    ///
    /// Useful for selecting the most efficient variant when reward
    /// differences are marginal.
    pub fn cheapest(&self) -> Option<ConfigVariant> {
        let mut best: Option<&FrontierEntry> = None;
        for e in &self.entries {
            if !e.occupied {
                continue;
            }
            if best.is_none_or(|b| e.cost < b.cost) {
                best = Some(e);
            }
        }
        best.map(|e| e.config)
    }

    /// Iterate over occupied entries as `(config, reward, cost)`.
    pub fn iter(&self) -> impl Iterator<Item = (ConfigVariant, f32, f32)> + '_ {
        self.entries
            .iter()
            .filter(|e| e.occupied)
            .map(|e| (e.config, e.reward, e.cost))
    }
}

impl<P: ScreeningPruner> HotSwapPruner<P> {
    /// Create a new hot-swap pruner.
    ///
    /// Loads the initial pruner from `path` using `factory`.
    /// The `factory` closure is stored for future [`reload`](Self::reload) calls.
    pub fn new(path: &Path, factory: PrunerFactory<P>) -> Result<Self> {
        let bytes = fs::read(path)?;
        let hash: [u8; 32] = blake3::hash(&bytes).into();
        let pruner = factory(path)?;

        Ok(Self {
            inner: RwLock::new(HotSwapInner { pruner, hash }),
            path: path.to_path_buf(),
            factory,
            version: AtomicU64::new(1),
        })
    }

impl SkipBitmask {
    /// All-zero bitmask (no layers skipped).
    #[inline]
    pub const fn new() -> Self {
        Self { bits: [0; 2] }
    }

    /// Set bit `l` (skip layer `l`).
    #[inline]
    pub fn set(&mut self, l: usize) {
        let word = l / 64;
        if word < 2 {
            self.bits[word] |= 1 << (l % 64);
        }
    }

    /// Check bit `l`. Returns `false` for out-of-bounds indices.
    #[inline]
    pub fn get(&self, l: usize) -> bool {
        let word = l / 64;
        if word < 2 {
            (self.bits[word] >> (l % 64)) & 1 != 0
        } else {
            false
        }
    }

    /// Count set bits (number of skipped layers).
    #[inline]
    pub fn count(&self) -> usize {
        self.bits.iter().map(|w| w.count_ones() as usize).sum()
    }

    /// Total number of addressable layers.
    #[inline]
    pub const fn capacity(&self) -> usize {
        128
    }
}

impl IdeaDivergence {
    /// Create a new divergence filter with the given novelty threshold.
    ///
    /// A threshold of 0.0 accepts all arms; a higher threshold requires
    /// more strategic diversity.
    #[inline]
    pub fn new(novelty_threshold: f32) -> Self {
        Self {
            arm_scores: Vec::new(),
            novelty_threshold: novelty_threshold.max(0.0),
        }
    }

    /// Check if a new arm's score vector is novel (min distance > threshold).
    ///
    /// Returns `true` if no existing arm is within `novelty_threshold`
    /// L2 distance, or if no arms have been registered yet.
    #[inline]
    pub fn is_novel(&self, scores: &[f32]) -> bool {
        if self.arm_scores.is_empty() {
            return true;
        }
        let mut min_dist = f32::MAX;
        for existing in &self.arm_scores {
            let d = Self::divergence(scores, existing);
            if d < min_dist {
                min_dist = d;
            }
        }
        min_dist > self.novelty_threshold
    }

    /// Compute normalized L2 distance between two score vectors.
    ///
    /// If vectors have different lengths, only the overlapping prefix
    /// is compared. Returns 0.0 for identical vectors.
    #[inline]
    pub fn divergence(a: &[f32], b: &[f32]) -> f32 {
        let len = a.len().min(b.len());
        if len == 0 {
            return 0.0;
        }
        let sum_sq: f32 = (0..len)
            .map(|i| {
                let diff = a[i] - b[i];
                diff * diff
            })
            .sum();
        sum_sq.sqrt()
    }

    /// Add a new arm's score vector.
    ///
    /// Call this after confirming novelty via `is_novel()`.
    pub fn add_arm(&mut self, scores: Vec<f32>) {
        self.arm_scores.push(scores);
    }

    /// Number of registered arms.
    #[inline]
    pub fn arm_count(&self) -> usize {
        self.arm_scores.len()
    }

    /// Current novelty threshold.
    #[inline]
    pub fn threshold(&self) -> f32 {
        self.novelty_threshold
    }

    /// Reset all registered arms.
    pub fn clear(&mut self) {
        self.arm_scores.clear();
    }

    /// Compute the minimum divergence from `scores` to any registered arm.
    ///
    /// Returns `f32::MAX` if no arms are registered.
    pub fn min_divergence(&self, scores: &[f32]) -> f32 {
        if self.arm_scores.is_empty() {
            return f32::MAX;
        }
        self.arm_scores
            .iter()
            .map(|existing| Self::divergence(scores, existing))
            .fold(f32::MAX, f32::min)
    }
}

use crate::lattice_operad::expr::{PrunerExpr, PrunerResult};

/// A pruner that composes multiple sub-pruners via a PrunerExpr tree.
///
/// Instead of the ad-hoc `all(pruner.is_valid())` pattern, this uses
/// canonical DNF composition which can eliminate redundant evaluations
/// via absorption: if A is false, A∧B doesn't need to evaluate B.
pub struct ComposedPruner<'a> {
    /// The expression tree describing how pruners are composed.
    expr: PrunerExpr,
    /// The sub-pruners, indexed by their Atom IDs.
    pruners: Vec<&'a dyn ConstraintPruner>,
}

impl<'a> ComposedPruner<'a> {
    /// Create a new composed pruner with a single pruner.
    pub fn single(pruner: &'a dyn ConstraintPruner) -> Self {
        Self {
            expr: PrunerExpr::Atom(0),
            pruners: vec![pruner],
        }
    }

impl PrunerExpr {
    /// Create an atom expression.
    pub fn atom(id: usize) -> Self {
        Self::Atom(id)
    }

    /// Create an AND expression.
    pub fn and(lhs: PrunerExpr, rhs: PrunerExpr) -> Self {
        Self::And(Box::new(lhs), Box::new(rhs))
    }

    /// Create an OR expression.
    pub fn or(lhs: PrunerExpr, rhs: PrunerExpr) -> Self {
        Self::Or(Box::new(lhs), Box::new(rhs))
    }

    /// Evaluate this expression against per-atom boolean results.
    ///
    /// `atom_results` maps atom IDs to their evaluation result.
    /// Returns `Unknown` if any referenced atom is not in the map.
    pub fn eval(&self, atom_results: &[bool]) -> PrunerResult {
        match self {
            PrunerExpr::Atom(id) => match atom_results.get(*id) {
                Some(true) => PrunerResult::Accept,
                Some(false) => PrunerResult::Reject,
                None => PrunerResult::Unknown,
            },
            PrunerExpr::And(lhs, rhs) => match lhs.eval(atom_results) {
                PrunerResult::Reject => PrunerResult::Reject,
                PrunerResult::Unknown => match rhs.eval(atom_results) {
                    PrunerResult::Reject => PrunerResult::Reject,
                    _ => PrunerResult::Unknown,
                },
                PrunerResult::Accept => rhs.eval(atom_results),
            },
            PrunerExpr::Or(lhs, rhs) => match lhs.eval(atom_results) {
                PrunerResult::Accept => PrunerResult::Accept,
                PrunerResult::Unknown => match rhs.eval(atom_results) {
                    PrunerResult::Accept => PrunerResult::Accept,
                    _ => PrunerResult::Unknown,
                },
                PrunerResult::Reject => rhs.eval(atom_results),
            },
        }
    }

    /// Collect all atom IDs referenced in this expression.
    pub fn atom_ids(&self) -> Vec<usize> {
        match self {
            PrunerExpr::Atom(id) => vec![*id],
            PrunerExpr::And(l, r) | PrunerExpr::Or(l, r) => {
                let mut ids = l.atom_ids();
                ids.extend(r.atom_ids());
                ids
            }
        }
    }

    /// Count the number of nodes in the expression tree.
    pub fn node_count(&self) -> usize {
        match self {
            PrunerExpr::Atom(_) => 1,
            PrunerExpr::And(l, r) | PrunerExpr::Or(l, r) => 1 + l.node_count() + r.node_count(),
        }
    }
}

use crate::lattice_operad::expr::PrunerExpr;

/// Canonicalize a pruner expression using the distributive lattice word problem.
///
/// Converts to Disjunctive Normal Form (DNF) and simplifies using
/// idempotency and absorption laws.
pub fn canonicalize(expr: &PrunerExpr) -> PrunerExpr {
    let dnf = to_dnf(expr);
    let simplified = simplify_dnf(&dnf);
    dnf_to_expr(&simplified)
}

impl LodestarAutomaton {
    /// Create a builder for constructing the automaton.
    ///
    /// - `vocab_size`: number of distinct tokens in the vocabulary (alphabet Σ).
    /// - `n_states`: number of states in the DFA (including start and accept).
    /// - `start_state`: the initial state (must be < `n_states`).
    #[inline]
    pub fn builder(
        vocab_size: usize,
        n_states: usize,
        start_state: usize,
    ) -> LodestarAutomatonBuilder {
        assert!(
            start_state < n_states,
            "start_state ({start_state}) must be < n_states ({n_states})"
        );
        LodestarAutomatonBuilder {
            transitions: vec![NO_EDGE; n_states * vocab_size],
            accept_states: BitVec::new(n_states),
            vocab_size,
            n_states,
            start_state,
        }
    }

    /// Successor of `state` on `token`, or `None` if illegal.
    ///
    /// O(1) flat-array lookup — branch-free on the happy path.
    #[inline]
    pub fn transition(&self, state: usize, token: usize) -> Option<usize> {
        let idx = state * self.vocab_size + token;
        match self.transitions.get(idx) {
            Some(&ns) if ns != NO_EDGE => Some(ns),
            _ => None,
        }
    }

    /// Whether `state` is accepting (a complete, valid output ends here).
    #[inline]
    pub fn is_accept(&self, state: usize) -> bool {
        self.accept_states.get(state)
    }

    /// Precomputed shortest-accepting-distance `d(s)`.
    ///
    /// Returns [`UNREACHABLE`] if no accepting state is reachable from `state`.
    #[inline]
    pub fn distance(&self, state: usize) -> u32 {
        match self.distances.get(state) {
            Some(&d) => d,
            None => UNREACHABLE,
        }
    }

    /// Precomputed singular-span length from `state`.
    ///
    /// Number of consecutive forced (single-outgoing-edge) transitions starting
    /// from `state`, until a real branch (≥2 legal tokens) or an accepting state.
    #[inline]
    pub fn singular_span_len(&self, state: usize) -> u32 {
        match self.singular_spans.get(state) {
            Some(&s) => s,
            None => 0,
        }
    }

    /// Replay `parent_tokens` from the start state, returning the state reached.
    ///
    /// Returns `start_state` if the path is empty or if at any point δ returns None
    /// (i.e., the prefix is illegal).
    #[inline]
    pub fn follow_path(&self, parent_tokens: &[usize]) -> usize {
        let mut state = self.start_state;
        for &token in parent_tokens {
            match self.transition(state, token) {
                Some(next) => state = next,
                None => return self.start_state,
            }
        }
        state
    }

    /// The start state.
    #[inline]
    pub fn start_state(&self) -> usize {
        self.start_state
    }

    /// Number of states in the automaton.
    #[inline]
    pub fn n_states(&self) -> usize {
        self.n_states
    }

    /// Vocabulary size (alphabet cardinality).
    #[inline]
    pub fn vocab_size(&self) -> usize {
        self.vocab_size
    }
}

impl LodestarAutomatonBuilder {
    /// Add a transition δ(from, token) → to.
    ///
    /// Panics if any index is out of range.
    pub fn add_transition(&mut self, from: usize, token: usize, to: usize) -> &mut Self {
        assert!(
            from < self.n_states,
            "from state ({from}) out of range (n_states={})",
            self.n_states
        );
        assert!(
            to < self.n_states,
            "to state ({to}) out of range (n_states={})",
            self.n_states
        );
        assert!(
            token < self.vocab_size,
            "token ({token}) out of range (vocab_size={})",
            self.vocab_size
        );
        self.transitions[from * self.vocab_size + token] = to;
        self
    }

    /// Mark `state` as accepting (a complete, valid output ends here).
    ///
    /// Panics if `state` is out of range.
    pub fn add_accept(&mut self, state: usize) -> &mut Self {
        assert!(
            state < self.n_states,
            "accept state ({state}) out of range (n_states={})",
            self.n_states
        );
        self.accept_states.set(state, true);
        self
    }

    /// Finalize the automaton: precompute distances and singular spans.
    ///
    /// Runs reverse-BFS distance computation (O(|S|·|Σ|) per relaxation pass)
    /// and singular-span precomputation. Called exactly once.
    pub fn build(self) -> LodestarAutomaton {
        let distances = precompute_distances(
            &self.transitions,
            &self.accept_states,
            self.n_states,
            self.vocab_size,
        );
        let singular_spans = precompute_singular_spans(
            &self.transitions,
            &self.accept_states,
            self.n_states,
            self.vocab_size,
        );
        LodestarAutomaton {
            transitions: self.transitions,
            accept_states: self.accept_states,
            distances,
            singular_spans,
            vocab_size: self.vocab_size,
            n_states: self.n_states,
            start_state: self.start_state,
        }
    }
}

impl LodestarPruner {
    /// Wrap a precomputed automaton. No budget constraint.
    #[inline]
    pub fn new(automaton: LodestarAutomaton) -> Self {
        Self {
            automaton,
            budget: None,
        }
    }

    /// Wrap a precomputed automaton with a token budget.
    ///
    /// `is_valid` will reject tokens whose successor cannot complete
    /// within the remaining budget: `1 + d(δ(s, t)) <= budget - depth - 1`.
    #[inline]
    pub fn with_budget(automaton: LodestarAutomaton, budget: usize) -> Self {
        Self {
            automaton,
            budget: Some(budget),
        }
    }

    /// Borrow the underlying automaton (for distances, spans, etc.).
    #[inline]
    pub fn automaton(&self) -> &LodestarAutomaton {
        &self.automaton
    }

    /// The configured budget, if any.
    #[inline]
    pub fn budget(&self) -> Option<usize> {
        self.budget
    }

    /// Follow `parent_tokens` from the start state to get the current automaton state.
    /// Returns the start state if the prefix is illegal.
    #[inline]
    fn current_state(&self, parent_tokens: &[usize]) -> usize {
        self.automaton.follow_path(parent_tokens)
    }
}

impl ConstraintPruner for LodestarPruner {
    fn is_valid(&self, depth: usize, token_idx: usize, parent_tokens: &[usize]) -> bool {
        if token_idx >= self.automaton.vocab_size {
            return false;
        }
        let state = self.current_state(parent_tokens);
        let next = match self.automaton.transition(state, token_idx) {
            Some(ns) => ns,
            None => return false,
        };
        // Budget check: reject if the successor cannot complete within budget_remaining.
        match self.budget {
            Some(budget) => {
                let budget_remaining = match budget.checked_sub(depth + 1) {
                    Some(br) => br,
                    None => return false,
                };
                let d = self.automaton.distance(next);
                match d {
                    UNREACHABLE => false,
                    _ => (1 + d as usize) <= budget_remaining,
                }
            }
            None => true,
        }
    }

    fn batch_is_valid(
        &self,
        depth: usize,
        candidates: &[usize],
        parent_tokens: &[usize],
        results: &mut [bool],
    ) {
        let state = self.current_state(parent_tokens);
        let budget_remaining = self.budget.map(|b| b.saturating_sub(depth + 1));
        let len = candidates.len().min(results.len());
        for i in 0..len {
            let token = candidates[i];
            if token >= self.automaton.vocab_size {
                results[i] = false;
                continue;
            }
            let next = if let Some(ns) = self.automaton.transition(state, token) {
                ns
            } else {
                results[i] = false;
                continue;
            };
            results[i] = match budget_remaining {
                Some(br) => {
                    let d = self.automaton.distance(next);
                    match d {
                        UNREACHABLE => false,
                        _ => (1 + d as usize) <= br,
                    }
                }
                None => true,
            };
        }
    }
}

impl CompletionHorizon for LodestarPruner {
    fn min_completion_distance(
        &self,
        _depth: usize,
        token_idx: usize,
        parent_tokens: &[usize],
    ) -> u32 {
        if token_idx >= self.automaton.vocab_size {
            return UNREACHABLE;
        }
        let state = self.current_state(parent_tokens);
        match self.automaton.transition(state, token_idx) {
            Some(next) => self.automaton.distance(next),
            None => UNREACHABLE,
        }
    }

    fn singular_span_len(&self, _depth: usize, parent_tokens: &[usize]) -> u32 {
        let state = self.current_state(parent_tokens);
        self.automaton.singular_span_len(state)
    }
}

impl AdaptiveCoTBudget {
    /// Create a new adaptive CoT budget scaler with the given config.
    pub fn new(config: AdaptiveCoTConfig) -> Self {
        let stats = (0..NUM_DISTANCE_BINS)
            .map(|_| BanditStats::new(BUDGET_ARMS.len()))
            .collect();
        Self {
            stats,
            config,
            last_selection: None,
        }
    }

    /// Create with default config.
    pub fn default_config() -> Self {
        Self::new(AdaptiveCoTConfig::default())
    }

    /// Select the scaled budget for a given root completion distance.
    ///
    /// 1. Compute distance bin from `d_root`.
    /// 2. If bin has < `min_visits` total pulls, return `base * default_multiplier`.
    /// 3. Otherwise, select arm with highest Q-value (greedy after warmup).
    /// 4. Return `base * BUDGET_ARMS[arm]` clamped to `[min_budget, base * max_budget_scale]`.
    #[inline]
    pub fn select_budget(&mut self, d_root: u32, base_budget: usize) -> usize {
        let bin = Self::distance_bin(d_root);

        // Warmup: use default multiplier until we have enough data.
        if self.stats[bin].total_pulls() < self.config.min_visits {
            let budget = (base_budget as f32 * self.config.default_multiplier).round() as usize;
            return self.clamp_budget(budget, base_budget);
        }

        // Greedy arm selection — highest Q-value.
        let arm = self.stats[bin].best_arm();
        self.last_selection = Some((bin, arm));

        let budget = (base_budget as f32 * BUDGET_ARMS[arm]).round() as usize;
        self.clamp_budget(budget, base_budget)
    }

    /// Observe reward (0.0 or 1.0) for the last selection.
    ///
    /// Uses [`BanditStats::update`] incremental mean.
    pub fn observe_reward(&mut self, reward: f32) {
        let Some((bin, arm)) = self.last_selection.take() else {
            return;
        };
        self.stats[bin].update(arm, reward);
    }

    /// Observe reward using EMA update instead of incremental mean.
    ///
    /// `Q(a) = (1 - α) * Q(a) + α * reward`
    pub fn observe_reward_ema(&mut self, reward: f32) {
        let Some((bin, arm)) = self.last_selection.take() else {
            return;
        };
        let alpha = self.config.ema_alpha;
        let q = self.stats[bin].q_value(arm);
        let new_q = (1.0 - alpha) * q + alpha * reward;

        // Directly update the Q-value via incremental mean with synthetic count.
        // We still need to bump visit/total_pulls for warmup tracking.
        self.stats[bin].update(arm, new_q);
    }

    /// Map root completion distance to a bin index.
    ///
    /// ```text
    /// d=0-1  → bin 0 (nearly done)
    /// d=2-4  → bin 1 (medium)
    /// d=5-8  → bin 2 (far)
    /// d=9+   → bin 3 (very far)
    /// ```
    #[inline]
    pub fn distance_bin(d: u32) -> usize {
        match d {
            0..=1 => 0,
            2..=4 => 1,
            5..=8 => 2,
            _ => 3,
        }
    }

    /// Get a reference to bandit stats for a bin (for inspection/logging).
    pub fn stats_for_bin(&self, bin: usize) -> Option<&BanditStats> {
        self.stats.get(bin)
    }

    /// Get the config reference.
    pub fn config(&self) -> &AdaptiveCoTConfig {
        &self.config
    }

    /// Clamp budget to `[min_budget, base * max_budget_scale]`.
    #[inline]
    fn clamp_budget(&self, budget: usize, base_budget: usize) -> usize {
        let max_budget = (base_budget as f32 * self.config.max_budget_scale).round() as usize;
        budget.clamp(
            self.config.min_budget,
            max_budget.max(self.config.min_budget),
        )
    }
}

