impl PerceptRouter for SigmoidPerceptRouter {
    fn complexity(&self, bfcp: &BFCP) -> f32 {
        let region_count = bfcp.region_count();
        if region_count == 0 {
            return 0.0;
        }

        let entropy = label_entropy(bfcp);
        // sigmoid(region_count * entropy) — bounded [0, 1]
        sigmoid(region_count as f32 * entropy)
    }

    fn route(&self, bfcp: &BFCP) -> ComputePath {
        let c = self.complexity(bfcp);
        if c < self.config.fast_threshold {
            ComputePath::FastPath
        } else if c > self.config.deep_threshold {
            ComputePath::DeepThink
        } else {
            ComputePath::Standard
        }
    }
}

impl<P: ScreeningPruner> PhraseBoostPruner<P> {
    /// Create a new PhraseBoostPruner.
    ///
    /// - `inner`: the base pruner to delegate to.
    /// - `trie`: pre-built phrase trie.
    /// - `boost_score`: raw boost value;

impl PhraseTrie {
    /// Create an empty trie with root node pre-allocated for `vocab_size` children.
    pub fn new(vocab_size: usize) -> Self {
        Self {
            nodes: vec![PhraseTrieNode::new(vocab_size)],
            vocab_size,
        }
    }

    /// Insert a single phrase (token ID sequence) into the trie.
    pub fn insert(&mut self, token_ids: &[usize]) {
        let mut node_idx = 0; // root
        for &tok in token_ids {
            let next = self.nodes[node_idx].children[tok];
            node_idx = if let Some(child) = next {
                child
            } else {
                let child = self.nodes.len();
                self.nodes[node_idx].children[tok] = Some(child);
                self.nodes.push(PhraseTrieNode::new(self.vocab_size));
                child
            };
        }
        self.nodes[node_idx].is_terminal = true;
    }

    /// Bulk-build from phrases, applying an encoding function to each string.
    pub fn build(phrases: &[&str], encode_fn: impl Fn(&str) -> Vec<usize>) -> Self {
        let mut trie = None;
        for phrase in phrases {
            let ids = encode_fn(phrase);
            if trie.is_none() {
                // Heuristic: vocab_size at least max token + 1, default 256.
                let max_tok = ids.iter().copied().max().unwrap_or(0);
                let vocab_size = (max_tok + 1).max(256);
                trie = Some(Self::new(vocab_size));
            }
            trie.as_mut().unwrap().insert(&ids);
        }
        trie.unwrap_or_else(|| Self::new(256))
    }

    /// Return the union of all child token IDs reachable from the active set.
    ///
    /// Used to determine which tokens should receive a boost at the current position.
    ///
    /// O(active_nodes × vocab_width) with O(vocab_size) bitset for dedup.
    pub fn get_boosted_tokens(&self, active: &[usize]) -> Vec<usize> {
        let mut seen = vec![false; self.vocab_size];
        let mut result = Vec::new();
        for &node_idx in active {
            let node = &self.nodes[node_idx];
            for (tok, slot) in node.children.iter().enumerate() {
                if slot.is_some() && !seen[tok] {
                    seen[tok] = true;
                    result.push(tok);
                }
            }
        }
        result
    }

    /// Zero-alloc membership test: is `token_idx` reachable as a child of any
    /// active node?
    ///
    /// O(active_nodes) — short-circuits on the first match. Replaces the
    /// previous pattern of `get_boosted_tokens(active).contains(&token_idx)`
    /// which allocated a `vocab_size` bool array (potentially hundreds of KB)
    /// and a result Vec on every relevance() call.
    pub fn is_token_boosted(&self, active: &[usize], token_idx: usize) -> bool {
        if token_idx >= self.vocab_size {
            return false;
        }
        for &node_idx in active {
            if self.nodes[node_idx].children[token_idx].is_some() {
                return true;
            }
        }
        false
    }

    /// Advance the active set by one token. Returns the new set of active node indices.
    ///
    /// - For each active node, follow the edge `token_id` if it exists.
    /// - If an edge doesn't exist at root, root stays active (always track from start).
    /// - Always include root so new phrases can begin at any position.
    ///
    /// O(active_nodes) with O(nodes) bitset for dedup.
    pub fn advance(&self, active: &[usize], token_id: usize) -> Vec<usize> {
        let mut next = Vec::with_capacity(active.len() + 1);
        // `next` holds at most `active.len()` entries, so for a small active set
        // a linear dedup against `next` itself is far cheaper than allocating +
        // zeroing a `nodes.len()` bitset (one malloc/free dominates ≤ 528
        // in-cache compares). Output and ordering are identical either way.
        if active.len() <= SMALL_ACTIVE_DEDUP {
            for &node_idx in active {
                if let Some(child) = self.nodes[node_idx].children[token_id]
                    && !next.contains(&child)
                {
                    next.push(child);
                }
            }
            // Root (index 0) is always active — new phrases can start at any position.
            if !next.contains(&0) {
                next.push(0);
            }
            return next;
        }
        let mut seen = vec![false; self.nodes.len()];
        for &node_idx in active {
            if let Some(child) = self.nodes[node_idx].children[token_id]
                && !seen[child]
            {
                seen[child] = true;
                next.push(child);
            }
        }
        // Root (index 0) is always active — new phrases can start at any position.
        if !seen[0] {
            next.push(0);
        }
        next
    }

    /// Check if any active state is at a terminal node (complete phrase matched).
    #[allow(dead_code)]
    pub fn has_terminal(&self, active: &[usize]) -> bool {
        active.iter().any(|&idx| self.nodes[idx].is_terminal)
    }
}

impl PrecisionPolicy {
    /// Create with custom config.
    pub fn new(config: PrecisionPolicyConfig) -> Self {
        let surprise_computer = SurpriseComputer::new(config.surprise_beta, config.surprise_floor);
        Self {
            config,
            surprise_computer,
        }
    }

    /// Decide the lifecycle action for a pruner arm.
    ///
    /// Priority order (matching paper's Eq. 12):
    /// 1. EXPLORE: no observations yet
    /// 2. RETIRE: failure-dominant, low success probability
    /// 3. PATCH: repeated failure mode detected
    /// 4. SPLIT: precision diverges from peers (if peer provided)
    /// 5. COMPRESS: high precision, stable performance
    /// 6. EXPLORE: default (continue collecting evidence)
    pub fn decide(
        &self,
        precision: &PrecisionVector,
        surprise_kl: f32,
        peer_precision: Option<&PrecisionVector>,
    ) -> LifecycleAction {
        // 1. EXPLORE: no observations
        if precision.observations() == 0 {
            return LifecycleAction::Explore;
        }

        // 2. RETIRE: failure evidence dominates
        if precision.beta() >= self.config.retire_min_beta
            && precision.success_probability() < self.config.retire_max_success_prob
        {
            return LifecycleAction::Retire;
        }

        // 3. PATCH: repeated failure mode with surprise
        let (max_fm, max_fm_count) = precision.max_failure_mode_count();
        if max_fm_count >= self.config.patch_min_failure_count {
            let (_, gate) = self
                .surprise_computer
                .compute_surprise(precision, surprise_kl);
            if gate > self.config.patch_surprise_threshold {
                return LifecycleAction::Patch {
                    failure_mode: max_fm,
                };
            }
        }

        // 4. SPLIT: precision diverges from peers
        if precision.observations() >= self.config.split_min_observations
            && let Some(peer) = peer_precision
        {
            let divergence = precision.precision_divergence(peer);
            if divergence > self.config.split_divergence_threshold {
                return LifecycleAction::Split;
            }
        }

        // 5. COMPRESS: high precision, stable
        if precision.observations() >= self.config.compress_min_observations
            && precision.avg_precision() >= self.config.compress_precision_threshold
        {
            return LifecycleAction::Compress;
        }

        // 6. Default: continue exploring
        LifecycleAction::Explore
    }

    /// Get a reference to the surprise computer.
    pub fn surprise(&self) -> &SurpriseComputer {
        &self.surprise_computer
    }

    /// Get a reference to the config.
    pub fn config(&self) -> &PrecisionPolicyConfig {
        &self.config
    }
}

use crate::posterior::types::{EvidenceOutcome, FailureMode};

/// Default dimensionality for precision vectors.
/// 8 dimensions: context_similarity, failure_density, eval_rate,
/// latency_signal, reward_mean, reward_variance, exploration_bonus, domain_coverage.
pub const PRECISION_DIM: usize = 8;

/// A BAKE-style precision vector that tracks per-dimension certainty.
///
/// Each dimension has:
/// - `precision`: how certain we are (grows with observations)
/// - `mean`: the posterior mean (reward/signal in that dimension)
///
/// Update rule (sequential Bayesian):
/// ```text
/// precision_new = precision_old + observation_weight
/// mean_new = mean_old + (observation - mean_old) * (obs_weight / precision_new)
/// ```
#[derive(Debug, Clone)]
pub struct PrecisionVector {
    /// Per-dimension precision (certainty). Grows with observations.
    precision: [f32;

impl PrecisionVector {
    /// Create a new precision vector with uniform prior (precision = 1.0, mean = 0.5).
    pub fn new() -> Self {
        Self {
            precision: [1.0; PRECISION_DIM],
            mean: [0.5; PRECISION_DIM],
            total_observations: 0,
            alpha: 1.0,
            beta: 1.0,
            failure_mode_counts: [0; FailureMode::COUNT],
        }
    }

    /// Create with custom prior.
    pub fn with_prior(precision: f32, mean: f32) -> Self {
        Self {
            precision: [precision; PRECISION_DIM],
            mean: [mean; PRECISION_DIM],
            total_observations: 0,
            alpha: 1.0,
            beta: 1.0,
            failure_mode_counts: [0; FailureMode::COUNT],
        }
    }

    /// Update the precision vector with a new observation.
    ///
    /// Returns the KL divergence between posterior and prior (surprise signal).
    /// Zero-allocation: all updates in-place on fixed-size arrays.
    pub fn update(
        &mut self,
        outcome: EvidenceOutcome,
        observation: &[f32; PRECISION_DIM],
        failure_mode: Option<FailureMode>,
    ) -> f32 {
        self.total_observations += 1;

        // Beta-Bernoulli update (compatible with paper)
        match outcome {
            EvidenceOutcome::Success => self.alpha += 1.0,
            EvidenceOutcome::Failure => self.beta += 1.0,
        }

        // Track failure mode counts
        if let Some(fm) = failure_mode {
            self.failure_mode_counts[fm.as_index()] += 1;
        }

        // Sequential Bayesian update per dimension
        let mut total_kl = 0.0f32;
        let obs_weight = 1.0; // Uniform observation weight

        for ((prec, mean), obs) in self
            .precision
            .iter_mut()
            .zip(self.mean.iter_mut())
            .zip(observation.iter())
        {
            let prior_precision = *prec;
            let prior_mean = *mean;

            // Update precision
            *prec += obs_weight;
            let posterior_precision = *prec;

            // Update mean (precision-weighted)
            let innovation = obs - prior_mean;
            *mean = prior_mean + innovation * (obs_weight / posterior_precision);

            // KL divergence contribution (Gaussian approximation):
            // KL = 0.5 * (precision_ratio - 1 - ln(precision_ratio))
            //      + 0.5 * precision_old * (mean_new - mean_old)^2
            let precision_ratio = posterior_precision / prior_precision;
            let kl_dim = 0.5 * (precision_ratio - 1.0 - precision_ratio.ln())
                + 0.5 * prior_precision * innovation * innovation;
            total_kl += kl_dim;
        }

        // Clamp to prevent NaN from numerical issues
        total_kl.clamp(0.0, f32::MAX)
    }

    /// Overall success probability (Beta-Bernoulli posterior mean).
    pub fn success_probability(&self) -> f32 {
        self.alpha / (self.alpha + self.beta)
    }

    /// Get the precision for a specific dimension.
    pub fn precision_at(&self, dim: usize) -> f32 {
        self.precision[dim]
    }

    /// Get the posterior mean for a specific dimension.
    pub fn mean_at(&self, dim: usize) -> f32 {
        self.mean[dim]
    }

    /// Get the total precision (sum across dimensions).
    pub fn total_precision(&self) -> f32 {
        self.precision.iter().sum()
    }

    /// Get the average precision across dimensions.
    pub fn avg_precision(&self) -> f32 {
        self.total_precision() / PRECISION_DIM as f32
    }

    /// Total number of observations.
    #[inline]
    pub fn observations(&self) -> u32 {
        self.total_observations
    }

    /// Alpha (success count + prior).
    #[inline]
    pub fn alpha(&self) -> f32 {
        self.alpha
    }

    /// Beta (failure count + prior).
    #[inline]
    pub fn beta(&self) -> f32 {
        self.beta
    }

    /// Count of a specific failure mode.
    pub fn failure_mode_count(&self, fm: FailureMode) -> u32 {
        self.failure_mode_counts[fm.as_index()]
    }

    /// Max failure mode count (for PATCH trigger: paper uses failure_count >= 2).
    pub fn max_failure_mode_count(&self) -> (FailureMode, u32) {
        let mut best = FailureMode::FalseAccept;
        let mut best_count = 0;
        for (i, &count) in self.failure_mode_counts.iter().enumerate() {
            if count > best_count {
                best_count = count;
                // SAFETY: index is within enum range
                best = unsafe { std::mem::transmute::<u8, FailureMode>(i as u8) };
            }
        }
        (best, best_count)
    }

    /// Check if any failure mode exceeds the given threshold.
    pub fn has_repeated_failure(&self, threshold: u32) -> bool {
        self.failure_mode_counts.iter().any(|&c| c >= threshold)
    }

    /// Compute precision divergence between two vectors.
    /// Returns the max absolute difference in precision across dimensions.
    /// Used for SPLIT trigger: if two arms diverge, they should be split.
    pub fn precision_divergence(&self, other: &Self) -> f32 {
        let mut max_diff = 0.0f32;
        for i in 0..PRECISION_DIM {
            let diff = (self.precision[i] - other.precision[i]).abs();
            if diff > max_diff {
                max_diff = diff;
            }
        }
        max_diff
    }

    /// Check if precision has converged to uninformative (near-zero effective precision).
    /// Used for RETIRE trigger.
    pub fn is_precision_depleted(&self, threshold: f32) -> bool {
        // Effective precision = precision - prior (1.0)
        let effective = self.avg_precision() - 1.0;
        effective < threshold
    }
}

impl SurpriseComputer {
    /// Create with custom sensitivity.
    pub fn new(beta: f32, surprise_floor: f32) -> Self {
        Self {
            beta,
            surprise_floor,
        }
    }

    /// Sigmoid function. Delegates to
    /// `katgpt_core::simd::fast_sigmoid` (Cephes polynomial).
    #[inline]
    fn sigmoid(x: f32) -> f32 {
        katgpt_core::simd::fast_sigmoid(x)
    }

    /// Compute surprise gate from a KL divergence value.
    ///
    /// Returns a value in (0, 1) indicating how surprising the observation was.
    /// Uses sigmoid(β × max(0, KL - floor)) to gate the surprise.
    #[inline]
    pub fn surprise_gate(&self, kl_divergence: f32) -> f32 {
        let excess = (kl_divergence - self.surprise_floor).max(0.0);
        Self::sigmoid(self.beta * excess)
    }

    /// Check if the surprise exceeds the action trigger threshold.
    ///
    /// Paper uses fixed `failure_count >= 2`. We use:
    /// `sigmoid(β × max(0, KL - floor)) > threshold`
    #[inline]
    pub fn should_trigger(&self, kl_divergence: f32, threshold: f32) -> bool {
        self.surprise_gate(kl_divergence) > threshold
    }

    /// Compute precision-weighted surprise for an arm.
    ///
    /// Combines the precision state with a novel observation's KL divergence.
    /// Low-precision arms (uncertain) produce less surprise because we
    /// expect them to shift. High-precision arms (certain) produce more
    /// surprise because shifts are unexpected.
    ///
    /// Returns (raw_kl, gate_value).
    pub fn compute_surprise(&self, precision: &PrecisionVector, kl_divergence: f32) -> (f32, f32) {
        // Weight surprise by inverse precision: uncertain arms → less surprise
        let avg_precision = precision.avg_precision();
        let precision_weight = 1.0 / (1.0 + avg_precision); // Diminishes as precision grows
        let weighted_kl = kl_divergence * (1.0 - precision_weight);
        let gate = self.surprise_gate(weighted_kl);
        (weighted_kl, gate)
    }
}

