impl SketchEntry {
    /// Create a new sketch entry with default Elo (1200).
    ///
    /// # Arguments
    ///
    /// * `proof_state` — the current game/proof state
    /// * `pending_goals` — unresolved subgoals
    pub fn new(proof_state: ProofState, pending_goals: Vec<Goal>) -> Self {
        Self {
            id: SketchId::new(),
            proof_state,
            pending_goals: pending_goals.into_iter().take(MAX_PENDING_GOALS).collect(),
            lessons: VecDeque::new(),
            elo_rating: DEFAULT_ELO,
            visits: 0,
            created_at: Instant::now(),
        }
    }

    /// Create with initial Elo rating.
    pub fn with_elo(proof_state: ProofState, pending_goals: Vec<Goal>, elo: f64) -> Self {
        Self {
            elo_rating: elo,
            ..Self::new(proof_state, pending_goals)
        }
    }

    /// Add a lesson from an episode.
    ///
    /// Keeps only the last `MAX_LESSONS` entries (FIFO eviction).
    pub fn add_lesson(&mut self, lesson: String) {
        if self.lessons.len() >= MAX_LESSONS {
            self.lessons.pop_front();
        }
        self.lessons.push_back(lesson);
    }

    /// Record a visit (increment visit count).
    pub fn record_visit(&mut self) {
        self.visits += 1;
    }

    /// Update Elo rating.
    #[inline]
    pub fn update_elo(&mut self, new_elo: f64) {
        self.elo_rating = new_elo;
    }

    /// Number of pending (unresolved) goals.
    pub fn pending_goal_count(&self) -> usize {
        self.pending_goals.len()
    }

    /// Number of lessons learned.
    pub fn lesson_count(&self) -> usize {
        self.lessons.len()
    }

    /// Has this entry been visited at least once?
    pub fn is_explored(&self) -> bool {
        self.visits > 0
    }

    /// Age of this entry as elapsed time since creation.
    ///
    /// Returns `None` if the entry was deserialized (no Instant).
    /// Use `serde(skip)` note: deserialized entries have `Instant::now()`.
    pub fn age(&self) -> std::time::Duration {
        self.created_at.elapsed()
    }

    /// P-UCB score for this entry.
    ///
    /// `score = q + c * sqrt(total_visits / (visits + 1))`
    ///
    /// where `q` is the normalized Elo rating in [0, 1].
    ///
    /// # Arguments
    ///
    /// * `total_visits` — sum of visits across all entries in population
    /// * `min_elo` — minimum Elo in population (for normalization)
    /// * `max_elo` — maximum Elo in population (for normalization)
    /// * `c` — exploration constant (paper uses 0.2)
    pub fn p_ucb_score(&self, total_visits: usize, min_elo: f64, max_elo: f64, c: f64) -> f64 {
        let q = normalize_to_01(self.elo_rating, min_elo, max_elo);
        let exploration = c * (total_visits as f64 / (self.visits + 1) as f64).sqrt();
        q + exploration
    }
}

impl RegionBandit {
    /// Create a new RegionBandit with `arm_count` arms and `region_count` regions.
    pub fn new(arm_count: usize, region_count: usize, c: f64) -> Self {
        Self {
            arms: (0..arm_count)
                .map(|_| PWCValueFunction::new(region_count, 0.0))
                .collect(),
            visits: (0..arm_count).map(|_| vec![0u64; region_count]).collect(),
            arm_pulls: vec![0u64; arm_count],
            arm_count,
            region_count,
            c,
        }
    }

    /// Select the best arm for a given region using UCB1.
    ///
    /// Unvisited arms get priority (infinite upper bound). Among visited arms,
    /// selects `argmax(Q(a,r) + c * sqrt(ln(total_pulls) / n(a,r)))`.
    pub fn select(&self, region_idx: usize) -> usize {
        let total_pulls: u64 = self.arm_pulls.iter().sum();
        let ln_total = if total_pulls > 0 {
            (total_pulls as f64).ln()
        } else {
            0.0
        };

        let mut best_arm = 0;
        let mut best_score = f64::NEG_INFINITY;

        for arm in 0..self.arm_count {
            let visits = self.visits[arm][region_idx];
            let score = match visits {
                0 => f64::INFINITY, // Unvisited arms get priority
                n => {
                    let q = self.arms[arm].value(region_idx);
                    let exploration = self.c * (ln_total / n as f64).sqrt();
                    q + exploration
                }
            };

            if score > best_score {
                best_score = score;
                best_arm = arm;
            }
        }

        best_arm
    }

    /// Update arm value for a specific region using incremental mean.
    ///
    /// Maintains PWC closure: only the target region's value changes.
    pub fn update(&mut self, region_idx: usize, arm: usize, reward: f64) {
        if arm >= self.arm_count || region_idx >= self.region_count {
            return;
        }

        let visits = self.visits[arm][region_idx];
        let old_q = self.arms[arm].value(region_idx);

        // Incremental mean update
        let new_q = match visits {
            0 => reward,
            n => old_q + (reward - old_q) / (n as f64 + 1.0),
        };

        self.arms[arm].update(region_idx, new_q);
        self.visits[arm][region_idx] += 1;
        self.arm_pulls[arm] += 1;
    }

    /// Get the Q-value for a specific (arm, region) pair.
    pub fn q_value(&self, arm: usize, region_idx: usize) -> f64 {
        if arm >= self.arm_count || region_idx >= self.region_count {
            return 0.0;
        }
        self.arms[arm].value(region_idx)
    }

    /// Get visit count for a specific (arm, region) pair.
    pub fn visits(&self, arm: usize, region_idx: usize) -> u64 {
        if arm >= self.arm_count || region_idx >= self.region_count {
            return 0;
        }
        self.visits[arm][region_idx]
    }

    /// Total pulls across all arms.
    pub fn total_pulls(&self) -> u64 {
        self.arm_pulls.iter().sum()
    }

    /// Number of arms.
    #[inline]
    pub fn arm_count(&self) -> usize {
        self.arm_count
    }

    /// Number of regions.
    #[inline]
    pub fn region_count(&self) -> usize {
        self.region_count
    }

    /// Verify PWC closure across all arms.
    ///
    /// After any number of updates, each arm's value function must maintain
    /// piecewise-constant structure: one value per region, no duplicates.
    /// This is Theorem 2 (NS-CSG B-PWC closure).
    pub fn verify_pwc_closure(&self) -> bool {
        self.arms.iter().all(|arm| arm.verify_pwc_closure())
    }

    /// Compute UCB1 score for a specific (arm, region) pair.
    pub fn ucb1_score(&self, arm: usize, region_idx: usize) -> f64 {
        if arm >= self.arm_count || region_idx >= self.region_count {
            return f64::NEG_INFINITY;
        }
        let total = self.total_pulls();
        if total == 0 {
            return f64::INFINITY;
        }
        let visits = self.visits[arm][region_idx];
        if visits == 0 {
            return f64::INFINITY;
        }
        let q = self.arms[arm].value(region_idx);
        q + self.c * (total as f64).ln() / (visits as f64).sqrt()
    }
}

impl RegimeCollapseClassifier {
    /// Create a new classifier with the given tolerance.
    pub fn new(tolerance: f64) -> Self {
        Self { tolerance }
    }

    /// Compute the standard deviation of failure depths using Welford's one-pass algorithm.
    /// Returns 0.0 for empty or single-element sets.
    fn failure_depth_std(&self, stats: &DDTreeStats) -> f64 {
        if let 0 | 1 = stats.failure_depths.len() {
            0.0
        } else {
            let mut mean = 0.0f64;
            let mut m2 = 0.0f64;
            for (i, &d) in stats.failure_depths.iter().enumerate() {
                let x = d as f64;
                let delta = x - mean;
                mean += delta / (i as f64 + 1.0);
                let delta2 = x - mean;
                m2 += delta * delta2;
            }
            let n = stats.failure_depths.len() as f64;
            (m2 / n).sqrt()
        }
    }
}

impl RegimeTransitionGate {
    /// Create a new gate with the given admission cost threshold.
    pub fn new(admission_cost_bits: f64) -> Self {
        Self {
            admission_cost_bits,
        }
    }

    /// Evaluate a candidate pruner against a decision trace.
    ///
    /// `rules_explained` is the number of rules the candidate would explain
    /// (i.e., how many applied rules it can account for).
    pub fn evaluate(&self, trace: &DecisionTrace, rules_explained: usize) -> GateResult {
        // Correctness check: sandbox validation (placeholder — real impl would use wasmi).
        if !self.sandbox_check() {
            return GateResult::Reject;
        }

        // Information check: MDL gate.
        let dl_old = description_length(trace);
        let reduction = rules_explained as f64 * 16.0;
        let dl_new = dl_old - reduction;

        if dl_new < dl_old - self.admission_cost_bits {
            GateResult::Accept
        } else {
            GateResult::Reject
        }
    }

    /// Placeholder sandbox check — validates the candidate can process basic input.
    ///
    /// Real implementation would use wasmi (WASM sandboxing) for safe execution.
    /// For now, always returns `true` since we're feature-gated and don't have
    /// actual WASM sandboxing available.
    fn sandbox_check(&self) -> bool {
        true
    }
}

impl ProvenanceChain {
    /// Record a new step in the provenance chain.
    ///
    /// Creates a `ProvenanceStep` with a blake3 hash of the step data:
    /// `hash(episode_id || reward_bits || bandit_pull)`
    pub fn record(&mut self, episode_id: u64, reward: f32, bandit_pull: usize) {
        let mut hasher = Hasher::new();
        hasher.update(&episode_id.to_le_bytes());
        hasher.update(&reward.to_le_bytes());
        hasher.update(&(bandit_pull as u64).to_le_bytes());
        let hash = hasher.finalize();

        self.steps.push(ProvenanceStep {
            episode_id,
            reward,
            bandit_pull,
            blake3_hash: hash.into(),
        });
    }

    /// Compute the commitment hash of the entire chain.
    ///
    /// Concatenates all step hashes and returns the blake3 of the result.
    /// This provides a single digest covering the entire provenance history.
    pub fn commitment_hash(&self) -> [u8; 32] {
        let mut hasher = Hasher::new();
        for step in &self.steps {
            hasher.update(&step.blake3_hash);
        }
        hasher.finalize().into()
    }

    /// Verify all step hashes match their data.
    ///
    /// Returns `true` iff every step's blake3 hash is consistent with its
    /// episode_id, reward, and bandit_pull values.
    pub fn verify(&self) -> bool {
        for step in &self.steps {
            let mut hasher = Hasher::new();
            hasher.update(&step.episode_id.to_le_bytes());
            hasher.update(&step.reward.to_le_bytes());
            hasher.update(&(step.bandit_pull as u64).to_le_bytes());
            let expected: [u8; 32] = hasher.finalize().into();
            if expected != step.blake3_hash {
                return false;
            }
        }
        true
    }

    /// Transport this provenance chain to a new pruner schema.
    ///
    /// Placeholder implementation: marks all steps as valid.
    /// Real implementation would check parameter compatibility between
    /// the old schema and `new_schema`.
    pub fn transport(&self, _new_schema: &[PrunerType]) -> TransportResult {
        TransportResult::AllValid
    }
}

