// ── TreeNode ────────────────────────────────────────────────────────

/// Lightweight DDTree node for rule extraction.
///
/// Represents a single token choice at a depth in the tree.
/// This is a simplified view of the full DDTree — only the fields needed
/// for path extraction and rule synthesis.
#[derive(Clone, Debug)]
pub struct TreeNode {
    /// Depth in the tree (0 = root level).
    pub depth: usize,
    /// Token index at this node.
    pub token_idx: usize,
    /// Score (weight/marginal) of this branch.
    pub score: f32,
    /// Children nodes (next depth choices).
    pub children: Vec<TreeNode>,
}

impl ExtractedRule {
    /// Create a new extracted rule.
    pub fn new(
        conditions: Vec<(usize, usize)>,
        action: (usize, usize),
        score: f32,
        support: u32,
    ) -> Self {
        Self {
            conditions,
            action,
            score,
            support,
        }
    }
}

impl RuleExtractor {
    /// Create a new `RuleExtractor` with the given TOP-K and minimum score.
    pub fn new(top_k: usize, min_score: f32) -> Self {
        Self { top_k, min_score }
    }

    /// Extract logical rules from a DDTree forest.
    ///
    /// Walks each tree depth-first, collects complete root→leaf paths with
    /// cumulative scores (product of branch weights), filters by `min_score`,
    /// and returns the TOP-K rules sorted by descending score.
    ///
    /// For each path:
    /// - `conditions` = all nodes except the last
    /// - `action` = the last (deepest) node
    /// - `score` = cumulative product of node scores along the path
    /// - `support` = 1 (newly extracted, not yet deduplicated)
    pub fn extract(&self, trees: &[TreeNode]) -> Vec<ExtractedRule> {
        // Early return: empty forest → no rules.
        if trees.is_empty() {
            return Vec::new();
        }

        let mut paths: Vec<PathAccumulator> = Vec::new();
        let mut stack: Vec<WalkState> = Vec::new();

        // Seed the DFS stack with root-level trees.
        for tree in trees {
            if tree.children.is_empty() {
                let path = PathAccumulator {
                    nodes: vec![(tree.depth, tree.token_idx)],
                    score: tree.score,
                };
                paths.push(path);
            } else {
                stack.push(WalkState {
                    path: vec![(tree.depth, tree.token_idx)],
                    cumulative_score: tree.score,
                    children: &tree.children,
                });
            }
        }

        // DFS traversal with iterative stack (no recursion → no stack overflow).
        while let Some(state) = stack.pop() {
            for child in state.children {
                let child_score = state.cumulative_score * child.score;
                let mut child_path = state.path.clone();
                child_path.push((child.depth, child.token_idx));

                if child.children.is_empty() {
                    paths.push(PathAccumulator {
                        nodes: child_path,
                        score: child_score,
                    });
                } else {
                    stack.push(WalkState {
                        path: child_path,
                        cumulative_score: child_score,
                        children: &child.children,
                    });
                }
            }
        }

        // Filter by min_score threshold.
        let mut rules: Vec<ExtractedRule> = paths
            .into_iter()
            .filter_map(|path| {
                // A rule needs at least 2 nodes: conditions + action.
                if path.nodes.len() < 2 {
                    None
                } else if path.score < self.min_score {
                    None
                } else {
                    let action = path.nodes[path.nodes.len() - 1];
                    let conditions = path.nodes[..path.nodes.len() - 1].to_vec();
                    Some(ExtractedRule {
                        conditions,
                        action,
                        score: path.score,
                        support: 1,
                    })
                }
            })
            .collect();

        // Sort descending by score, keep TOP-K.
        rules.sort_by(|a, b| {
            b.score
                .partial_cmp(&a.score)
                .unwrap_or(std::cmp::Ordering::Equal)
        });
        rules.truncate(self.top_k);

        rules
    }
}

impl CoincidenceGate {
    /// Construct with a given simple-set-size estimate `τ`.
    ///
    /// Calibrate from domain knowledge: a small `τ` (e.g. 0.3) is conservative
    /// (only probe very simple objectives); a large `τ` (e.g. 0.9) is
    /// permissive but risks wasted probes on near-random objectives.
    #[inline]
    #[must_use]
    pub const fn new(simple_set_size_estimate: f32) -> Self {
        Self {
            simple_set_size_estimate,
        }
    }

    /// Should we probe objective `f2` whose estimated complexity is `k_tilde_of_f2`?
    ///
    /// Returns `true` when `k_tilde_of_f2 < simple_set_size_estimate` — i.e.
    /// the objective is "simple enough" for the theorem's exponential lift to
    /// apply. Complex `f2` (high `K̃`) are skipped.
    ///
    /// # Match over `if`
    ///
    /// Uses `match` per the project style guide, with a guard-free form that
    /// LLVM will compile to a single `ucomiss + jb`.
    #[inline]
    #[must_use]
    pub fn should_probe(&self, k_tilde_of_f2: f32) -> bool {
        k_tilde_of_f2 < self.simple_set_size_estimate
    }

    /// Probe `x*` against each objective `f2_k`, returning indices where `x*`
    /// ranks in the top-`r` of a random comparison sample.
    ///
    /// For each objective `f2_k`:
    /// 1. Score `x*` under `f2_k`: `score_star = f2_k(x_star)`.
    /// 2. Draw `sample_size = max(r · 2, 8)` random candidates by uniform
    ///    byte-slice synthesis (we use a caller-provided byte buffer of length
    ///    `x_star.len()` and fill it from `rng`).
    /// 3. Count how many random candidates score strictly higher than `x*`.
    /// 4. If at most `r - 1` random candidates beat `x*`, then `x*` is in the
    ///    top-`r` of the sample → include `k` in the result.
    ///
    /// **Allocation policy:** this is NOT the per-tick hot path (it runs at
    /// objective-evaluation cadence, much slower than the sampler). It returns
    /// `Vec<usize>` for ergonomic chaining. Per the project rule, SmallVec
    /// optimisation is deferred — Phase 1 returns `Vec<usize>`; a future plan
    /// may swap to `SmallVec` once that dep is added. The sampler's zero-alloc
    /// contract is preserved on its own hot path.
    ///
    /// # Determinism
    ///
    /// Pass `Rng::with_seed(N)` for deterministic test runs. Prod callers should
    /// use `Rng::new()` (thread-local entropy).
    ///
    /// # Arguments
    ///
    /// - `x_star`: the known optimum of objective `f1`.
    /// - `objectives`: slice of closures `f2_k(x) -> score` (higher = better).
    /// - `rank_threshold_r`: include `k` if `x*` is in the top-`r` of the random
    ///   comparison sample. `r >= 1`.
    /// - `rng`: caller-owned RNG.
    pub fn probe_transfer<F>(
        &self,
        x_star: &[u8],
        objectives: &[F],
        rank_threshold_r: usize,
        rng: &mut Rng,
    ) -> Vec<usize>
    where
        F: Fn(&[u8]) -> f32,
    {
        debug_assert!(
            rank_threshold_r >= 1,
            "rank_threshold_r must be >= 1, got {rank_threshold_r}"
        );
        let mut hits: Vec<usize> = Vec::with_capacity(objectives.len().min(8));
        if x_star.is_empty() {
            // Without state bytes, random synthesis is degenerate; return empty.
            return hits;
        }
        // Sample size: large enough to give the rank test statistical power,
        // small enough to bound per-objective cost. `max(2·r, 8)`.
        let sample_size = (rank_threshold_r * 2).max(8);
        // Reusable scratch buffer for random candidates.
        let mut scratch_candidate = vec![0u8; x_star.len()];
        for (k, f2_k) in objectives.iter().enumerate() {
            let score_star = f2_k(x_star);
            // Count how many random candidates BEAT x*.
            let mut beat_count: usize = 0;
            for _ in 0..sample_size {
                // Synthesise a random candidate of the same shape as x_star.
                rng.fill(&mut scratch_candidate);
                let score_rand = f2_k(&scratch_candidate);
                if score_rand > score_star {
                    beat_count += 1;
                }
            }
            // x* is in the top-r of the sample iff at most r-1 random candidates
            // beat it. Equivalent: beat_count < r.
            if beat_count < rank_threshold_r {
                hits.push(k);
            }
        }
        hits
    }
}

impl ComplexityProxy for RleComplexity {
    #[inline]
    fn k_tilde(&self, candidate: &[u8]) -> f32 {
        let raw = candidate.len();
        if raw == 0 {
            return 0.0;
        }
        rle_compressed_len(candidate) as f32 / raw as f32
    }
}

impl ComplexityProxy for L1Complexity {
    #[inline]
    fn k_tilde(&self, candidate: &[u8]) -> f32 {
        let n = candidate.len();
        if n == 0 {
            return 0.0;
        }
        let sum: u64 = candidate.iter().map(|&b| b as u64).sum();
        sum as f32 / (255.0 * n as f32)
    }
}

