impl EpisodeRewardComputer {
    /// Create a new reward computer with the given config.
    pub fn new(config: &SelfDistillingConfig) -> Self {
        Self {
            k: config.k,
            alpha: config.alpha,
        }
    }

    /// Compute combined reward from episode match and acceptance signal.
    ///
    /// - `match_ratio`: fraction of tokens matching reference (0.0..1.0)
    /// - `acceptance_reward`: the usual acceptance signal (0.0 or 1.0)
    ///
    /// Returns blended reward in (0.0, 1.0).
    #[inline]
    pub fn compute_reward(&self, match_ratio: f32, acceptance_reward: f32) -> f32 {
        let episode_reward = sigmoid(self.k * (match_ratio - 0.5));
        (1.0 - self.alpha) * episode_reward + self.alpha * acceptance_reward
    }

    /// Compute pure episode reward (no acceptance blend).
    #[inline]
    pub fn episode_reward_only(&self, match_ratio: f32) -> f32 {
        sigmoid(self.k * (match_ratio - 0.5))
    }
}

impl DomainQTable {
    fn new(num_arms: usize, max_domains: usize, min_domain_samples: usize) -> Self {
        let mut domains = Vec::with_capacity(max_domains);
        for _ in 0..max_domains {
            domains.push(None);
        }
        Self {
            domains,
            global: BanditStats::new(num_arms),
            num_arms,
            min_domain_samples,
        }
    }

    /// Get the effective Q-values for a domain.
    /// Returns domain-specific values if warm enough, else global.
    fn q_values_for_domain(&self, domain_hash: u64) -> &[f32] {
        let slot = (domain_hash as usize) % self.domains.len();
        match &self.domains[slot] {
            Some(stats) if u64::from(stats.total_pulls()) >= self.min_domain_samples as u64 => {
                stats.q_values()
            }
            _ => self.global.q_values(),
        }
    }

    /// Update reward for an arm in a specific domain.
    fn update(&mut self, domain_hash: u64, arm: usize, reward: f32) {
        // Always update global
        self.global.update(arm, reward);

        // Update domain-specific if slot is claimed by same domain
        let slot = (domain_hash as usize) % self.domains.len();
        if let Some(stats) = &mut self.domains[slot] {
            stats.update(arm, reward);
        } else {
            let mut stats = BanditStats::new(self.num_arms);
            stats.update(arm, reward);
            self.domains[slot] = Some(stats);
        }
    }

    /// Get global Q-values.
    #[allow(dead_code)]
    fn global_q_values(&self) -> &[f32] {
        self.global.q_values()
    }

    /// Number of domains with sufficient samples.
    fn warm_domain_count(&self) -> usize {
        self.domains
            .iter()
            .filter(|d| {
                d.as_ref().is_some_and(|s| {
                    u64::from(s.total_pulls()) >= self.min_domain_samples as u64
                })
            })
            .count()
    }
}

impl SoftRejectConfig {
    /// Construct a config, clamping `tau_low < tau_high` and both to `[0, 1]`.
    pub fn new(tau_low: f32, tau_high: f32) -> Self {
        let lo = tau_low.clamp(0.0, 1.0);
        let hi = tau_high.clamp(0.0, 1.0);
        // Preserve the invariant tau_low < tau_high; if invalid, fall back to defaults.
        if lo < hi {
            Self {
                tau_low: lo,
                tau_high: hi,
            }
        } else {
            Self::default()
        }
    }
}

use std::time::{SystemTime, UNIX_EPOCH};

use blake3::Hasher;

use super::types::{CompactBitmap, CompiledSpec, SpecRule};

/// Cryptographic proof that a compiled spec hasn't been tampered with.
///
/// The commitment covers all rule data (depth, is_allowlist, bitmap bytes,
/// prefix entries) plus the original spec hash. Verification recomputes
/// the commitment from the live spec and compares.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SpecProof {
    /// BLAKE3 hash of the compiled spec rules (not just the spec string).
    pub commitment: [u8;

impl SpecProof {
    /// Create a proof from a compiled spec and its original source string.
    ///
    /// Hashes all rule data through BLAKE3: depth, is_allowlist, bitmap
    /// bytes, prefix entries, plus the existing spec_hash.
    pub fn from_spec(spec: &CompiledSpec, source: &str) -> Self {
        let commitment = compute_commitment(spec);
        let mut total_allowed = 0usize;
        let mut total_blocked = 0usize;
        for rule in &spec.rules {
            if rule.is_allowlist {
                total_allowed += rule.allowed.len();
            } else {
                total_blocked += rule.allowed.len();
            }
        }
        SpecProof {
            commitment,
            spec_source: source.to_owned(),
            rule_count: spec.rules.len(),
            total_allowed,
            total_blocked,
        }
    }

    /// Verify that the compiled spec matches this proof's commitment.
    ///
    /// Recomputes the BLAKE3 commitment from the spec and compares.
    /// Returns `true` if the spec hasn't been tampered with.
    pub fn verify(&self, spec: &CompiledSpec) -> bool {
        let recomputed = compute_commitment(spec);
        self.commitment == recomputed
    }

    /// Verify that the given source string matches the stored spec source.
    ///
    /// Simple string equality check. For a stricter check, compare the
    /// BLAKE3 hash of the source against the spec's `spec_hash`.
    pub fn verify_source(&self, source: &str) -> bool {
        self.spec_source == source
    }

    /// Verify that the source hashes to the same value as the spec's `spec_hash`.
    pub fn verify_source_hash(&self, spec: &CompiledSpec) -> bool {
        let source_hash = blake3::hash(self.spec_source.as_bytes());
        source_hash == spec.spec_hash
    }
}

impl SpecCommitment {
    /// Create a new timestamped commitment from a proof.
    pub fn new(proof: SpecProof) -> Self {
        let timestamp = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map_or(0, |d| d.as_millis() as u64);
        SpecCommitment { proof, timestamp }
    }

    /// Create a commitment from a compiled spec and its source.
    pub fn from_spec(spec: &CompiledSpec, source: &str) -> Self {
        let proof = SpecProof::from_spec(spec, source);
        Self::new(proof)
    }

    /// Verify the enclosed proof against a compiled spec.
    pub fn verify(&self, spec: &CompiledSpec) -> bool {
        self.proof.verify(spec)
    }
}

impl ConstraintPruner for CompiledSpec {
    /// Check if `token_idx` at `depth` is valid according to compiled rules.
    ///
    /// Evaluation order (most specific first):
    /// 1. Depth-specific rules with matching prefix → use their bitmap
    /// 2. Depth-agnostic (global) rules → use their bitmap
    /// 3. Global blocked set → reject
    /// 4. Global allowed set → accept
    /// 5. Default: allow (no matching rule)
    #[inline]
    fn is_valid(&self, depth: usize, token_idx: usize, parent_tokens: &[usize]) -> bool {
        // Phase 1: Check depth-specific rules with prefix matching
        for rule in &self.rules {
            // Skip if depth doesn't match
            if let Some(rule_depth) = rule.depth
                && rule_depth != depth
            {
                continue;
            }

            // Check prefix constraint
            if !prefix_matches(&rule.prefix, parent_tokens) {
                continue;
            }

            // Apply the rule
            let in_bitmap = rule.allowed.contains(token_idx);
            return if rule.is_allowlist {
                in_bitmap // Allowlist: must be in the set
            } else {
                !in_bitmap // Blocklist: must NOT be in the set
            };
        }

        // Phase 2: Global blocked set
        if self.global_blocked.contains(token_idx) {
            return false;
        }

        // Phase 3: Global allowed set (if non-empty, must be in it)
        if !self.global_allowed.is_empty() {
            return self.global_allowed.contains(token_idx);
        }

        // Default: allow
        true
    }

    /// Batch validation: check multiple candidates at the same depth.
    ///
    /// Optimized to evaluate rules once per batch instead of per-token.
    fn batch_is_valid(
        &self,
        depth: usize,
        candidates: &[usize],
        parent_tokens: &[usize],
        results: &mut [bool],
    ) {
        // Find the applicable rule for this depth + prefix
        let applicable_rule = self.find_rule(depth, parent_tokens);

        if let Some((bitmap, is_allowlist)) = applicable_rule {
            let len = candidates.len().min(results.len());
            match bitmap {
                CompactBitmap::Empty => {
                    for i in 0..len {
                        results[i] = !is_allowlist; // Empty allowlist = all blocked
                    }
                }
                CompactBitmap::Sparse(a) => {
                    // Sparse: binary search per candidate
                    for i in 0..len {
                        let idx = candidates[i];
                        let in_bitmap = if idx <= u16::MAX as usize {
                            a.binary_search(&(idx as u16)).is_ok()
                        } else {
                            false
                        };
                        results[i] = if is_allowlist { in_bitmap } else { !in_bitmap };
                    }
                }
                CompactBitmap::Dense(bits) => {
                    // Dense: direct bit check — O(1) per candidate
                    for i in 0..len {
                        let idx = candidates[i];
                        let word = idx / 64;
                        let bit = idx % 64;
                        let in_bitmap = if word < 1024 {
                            (bits[word] >> bit) & 1 == 1
                        } else {
                            false
                        };
                        results[i] = if is_allowlist { in_bitmap } else { !in_bitmap };
                    }
                }
            }
        } else {
            // No applicable rule — check global sets, then default allow.
            // `global_allowed.is_empty()` does not depend on the candidate,
            // so hoist it out of the per-candidate loop.
            let len = candidates.len().min(results.len());
            let has_global_allowlist = !self.global_allowed.is_empty();
            for i in 0..len {
                let idx = candidates[i];
                if self.global_blocked.contains(idx) {
                    results[i] = false;
                } else if has_global_allowlist {
                    results[i] = self.global_allowed.contains(idx);
                } else {
                    results[i] = true;
                }
            }
        }
    }
}

impl ScreeningPruner for CompiledSpec {
    #[inline]
    fn relevance(&self, depth: usize, token_idx: usize, parent_tokens: &[usize]) -> f32 {
        if self.global_blocked.contains(token_idx) {
            return 0.0;
        }

        if !self.global_allowed.is_empty() {
            return if self.global_allowed.contains(token_idx) {
                1.0
            } else {
                0.0
            };
        }

        let mut match_count: usize = 0;
        let mut first_applicable: Option<&SpecRule> = None;

        for rule in &self.rules {
            if let Some(rule_depth) = rule.depth
                && rule_depth != depth
            {
                continue;
            }

            if !prefix_matches(&rule.prefix, parent_tokens) {
                continue;
            }

            match_count += 1;

            if first_applicable.is_none() {
                first_applicable = Some(rule);
            }
        }

        if match_count == 0 {
            return 1.0;
        }

        if let Some(rule) = first_applicable {
            let in_bitmap = rule.allowed.contains(token_idx);
            return if rule.is_allowlist {
                // Allowlist: binary relevance
                if in_bitmap { 1.0 } else { 0.0 }
            } else {
                // Blocklist: in-bitmap is hard 0.0, out-of-bitmap is sigmoid
                if in_bitmap {
                    0.0
                } else {
                    sigmoid(match_count as f32 - 0.5)
                }
            };
        }

        // Fallback (should not reach here when match_count > 0)
        1.0
    }
}

impl CompactBitmap {
    /// Create an empty bitmap.
    #[inline]
    pub const fn empty() -> Self {
        CompactBitmap::Empty
    }

    /// Create a bitmap from a sorted list of u16 indices.
    pub fn from_sorted_indices(indices: Vec<u16>) -> Self {
        if indices.is_empty() {
            CompactBitmap::Empty
        } else if indices.len() <= SPARSE_MAX_CARDINALITY {
            CompactBitmap::Sparse(indices)
        } else {
            let mut bits = Box::new([0u64; 1024]);
            for &idx in &indices {
                let word = idx as usize / 64;
                let bit = idx as usize % 64;
                bits[word] |= 1u64 << bit;
            }
            CompactBitmap::Dense(bits)
        }
    }

    /// Create a bitmap from token index iterators (u32 token IDs).
    /// Filters to u16 range [0, 65535].
    pub fn from_token_indices(indices: impl Iterator<Item = usize>) -> Self {
        let mut sorted: Vec<u16> = indices
            .filter(|&i| i <= u16::MAX as usize)
            .map(|i| i as u16)
            .collect();
        sorted.sort_unstable();
        sorted.dedup();
        Self::from_sorted_indices(sorted)
    }

    /// Create a dense bitmap with all bits set in range [0, count).
    pub fn all_set(count: usize) -> Self {
        if count == 0 {
            return CompactBitmap::Empty;
        }
        if count <= SPARSE_MAX_CARDINALITY {
            return CompactBitmap::Sparse((0..count as u16).collect());
        }
        let mut bits = Box::new([0u64; 1024]);
        let full_words = count / 64;
        let remainder = count % 64;
        for i in 0..full_words.min(1024) {
            bits[i] = u64::MAX;
        }
        if remainder > 0 && full_words < 1024 {
            bits[full_words] = (1u64 << remainder) - 1;
        }
        CompactBitmap::Dense(bits)
    }

    /// Check if a given index is set.
    #[inline]
    pub fn contains(&self, idx: usize) -> bool {
        match self {
            CompactBitmap::Empty => false,
            CompactBitmap::Sparse(a) => {
                if idx > u16::MAX as usize {
                    return false;
                }
                a.binary_search(&(idx as u16)).is_ok()
            }
            CompactBitmap::Dense(bits) => {
                let word = idx / 64;
                let bit = idx % 64;
                if word >= 1024 {
                    return false;
                }
                (bits[word] >> bit) & 1 == 1
            }
        }
    }

    /// Number of set bits (cardinality).
    pub fn len(&self) -> usize {
        match self {
            CompactBitmap::Empty => 0,
            CompactBitmap::Sparse(a) => a.len(),
            CompactBitmap::Dense(bits) => bits.iter().map(|w| w.count_ones() as usize).sum(),
        }
    }

    /// Is the bitmap empty?
    #[inline]
    pub fn is_empty(&self) -> bool {
        match self {
            CompactBitmap::Empty => true,
            CompactBitmap::Sparse(a) => a.is_empty(),
            CompactBitmap::Dense(_) => false,
        }
    }

    /// Insert an index into the bitmap.
    pub fn insert(&mut self, idx: usize) {
        if idx > u16::MAX as usize {
            return;
        }
        let lo = idx as u16;
        match self {
            CompactBitmap::Empty => {
                *self = CompactBitmap::Sparse(vec![lo]);
            }
            CompactBitmap::Sparse(a) => {
                if let Err(pos) = a.binary_search(&lo) {
                    a.insert(pos, lo);
                    if a.len() > SPARSE_MAX_CARDINALITY {
                        let old = std::mem::take(a);
                        *self = Self::from_sorted_indices(old);
                    }
                }
            }
            CompactBitmap::Dense(bits) => {
                let word = idx / 64;
                let bit = idx % 64;
                if word < 1024 {
                    bits[word] |= 1u64 << bit;
                }
            }
        }
    }

    /// Merge another bitmap into this one (union).
    pub fn union_with(&mut self, other: &CompactBitmap) {
        match (&mut *self, other) {
            (CompactBitmap::Empty, _) => {
                *self = other.clone();
            }
            (_, CompactBitmap::Empty) => {}
            (CompactBitmap::Dense(a), CompactBitmap::Dense(b)) => {
                for i in 0..1024 {
                    a[i] |= b[i];
                }
            }
            (CompactBitmap::Dense(a), CompactBitmap::Sparse(b)) => {
                for &lo in b {
                    let word = lo as usize / 64;
                    let bit = lo as usize % 64;
                    if word < 1024 {
                        a[word] |= 1u64 << bit;
                    }
                }
            }
            (CompactBitmap::Sparse(a), CompactBitmap::Dense(b)) => {
                let mut bits = Box::new([0u64; 1024]);
                for &lo in a.iter() {
                    let word = lo as usize / 64;
                    let bit = lo as usize % 64;
                    bits[word] |= 1u64 << bit;
                }
                for i in 0..1024 {
                    bits[i] |= b[i];
                }
                *self = CompactBitmap::Dense(bits);
            }
            (CompactBitmap::Sparse(a), CompactBitmap::Sparse(b)) => {
                for &lo in b {
                    if let Err(pos) = a.binary_search(&lo) {
                        a.insert(pos, lo);
                    }
                }
                if a.len() > SPARSE_MAX_CARDINALITY {
                    let old = std::mem::take(a);
                    *self = Self::from_sorted_indices(old);
                }
            }
        }
    }
}

impl fmt::Display for CompactBitmap {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            CompactBitmap::Empty => write!(f, "∅"),
            CompactBitmap::Sparse(a) => write!(f, "sparse({})", a.len()),
            CompactBitmap::Dense(bits) => {
                let count: usize = bits.iter().map(|w| w.count_ones() as usize).sum();
                write!(f, "dense({count})")
            }
        }
    }

use katgpt_core::ConstraintPruner;

/// Prunes DDTree branches based on cumulative temporal influence.
///
/// Uses the semiseparable structure of the SSM: if the cumulative influence
/// of a token at depth `from` on the current depth `to` falls below
/// `threshold`, the branch is pruned. This implements the theoretical
/// result that distant tokens in a diagonal SSM have exponentially
/// decaying influence.
pub struct SemiseparablePruner {
    /// Decay factors per depth position [T]. Typically sigmoid(gate) in [0, 1].
    decay_factors: Vec<f32>,
    /// Pruning threshold. Branches with influence below this are pruned.
    threshold: f32,
    /// Pre-computed influence cache: `influence_cache[i] = prod(decay_factors[1..=i])`.
    /// `influence_cache[0] = 1.0` (identity, no decay).
    /// This avoids recomputing the product each time.
    influence_cache: Vec<f32>,
}

impl SemiseparablePruner {
    /// Create a pruner from explicit per-position decay factors.
    ///
    /// Builds the influence cache eagerly: O(T) at construction, O(1) per query.
    pub fn new(decay_factors: Vec<f32>, threshold: f32) -> Self {
        let n = decay_factors.len();
        let mut influence_cache = Vec::with_capacity(n);
        influence_cache.push(1.0); // influence_cache[0] = 1.0 (no decay at depth 0)

        let mut prod = 1.0f32;
        for i in 1..n {
            prod *= decay_factors[i];
            influence_cache.push(prod);
        }

        Self {
            decay_factors,
            threshold,
            influence_cache,
        }
    }

    /// Convenience constructor: uniform decay factor across `seq_len` positions.
    ///
    /// `decay` should be in [0, 1] (typically `sigmoid(gate)`). With `decay = 1.0`,
    /// no pruning occurs. With `decay < 1.0`, influence decays exponentially:
    /// `influence(depth) = decay^depth`.
    pub fn from_uniform(decay: f32, seq_len: usize, threshold: f32) -> Self {
        Self::new(vec![decay; seq_len], threshold)
    }

    /// Returns the pruning threshold.
    #[inline]
    pub fn threshold(&self) -> f32 {
        self.threshold
    }

    /// Returns the per-position decay factors.
    #[inline]
    pub fn decay_factors(&self) -> &[f32] {
        &self.decay_factors
    }

    /// Returns the cached cumulative influence from depth 0 to `depth`.
    ///
    /// This is `prod(decay_factors[1..=depth])`, equivalent to
    /// `crate::cumprodsum::influence(&decay_factors, 0, depth)`.
    ///
    /// For `depth` beyond the cache range, returns 0.0 (influence has fully decayed
    /// for any `decay < 1.0`; the sequence has ended for `decay == 1.0`).
    #[inline]
    pub fn influence_at(&self, depth: usize) -> f32 {
        if depth < self.influence_cache.len() {
            // SAFETY: bounds checked above
            unsafe { *self.influence_cache.get_unchecked(depth) }
        } else {
            // Beyond the sequence: influence is negligible for decay < 1.0.
            0.0
        }
    }
}

impl<Dir, W> TickFaultSite<Dir, W> {
    /// Construct a fault site. `responsible_idx` MUST be a valid index into
    /// `responsibility`.
    pub fn new(
        tick_idx: usize,
        violated: impl Into<String>,
        responsibility: Vec<W>,
        responsible_idx: usize,
    ) -> Self {
        // `assert!` (not `debug_assert!`): this is a documented public API
        // contract ("`responsible_idx` MUST be a valid index into
        // `responsibility`"). A `debug_assert!` here would let release builds
        // construct an invalid `TickFaultSite` with an out-of-bounds index,
        // deferring the failure to whichever consumer next indexes into
        // `responsibility[responsible_idx]` — producing a generic panic
        // instead of this helpful message. The paired
        // `tick_fault_site_rejects_out_of_bounds_idx` `#[should_panic]` test
        // relies on this firing in release mode too.
        assert!(
            responsible_idx < responsibility.len(),
            "responsible_idx out of bounds"
        );
        Self {
            tick_idx,
            violated: violated.into(),
            responsibility,
            responsible_idx,
            _marker: PhantomData,
        }
    }

