            .iter()
            .map(|&node| ProcedureNode {
                id: node.id(),
                label: node.label().to_string(),
                is_start: matches!(node, GoNode::Start),
                is_terminal: node.is_terminal(),
            })
            .collect()
    }

    #[allow(clippy::type_complexity)]
    fn build_adjacency() -> (AdjacencyList, usize) {
        let mut adj = vec![Vec::new(); GoNode::all().len()];
        let mut count = 0usize;

        let add = |adj: &mut Vec<Vec<(u32, Option<String>)>>,
                   count: &mut usize,
                   from: GoNode,
                   to: GoNode,
                   cond: Option<&str>| {
            adj[from.id() as usize].push((to.id(), cond.map(String::from)));
            *count += 1;
        };

        // Start → Opening (first stone placed)
        add(&mut adj, &mut count, GoNode::Start, GoNode::Opening, None);

        // Opening → Opening (continue joseki/fuseki)
        add(
            &mut adj,
            &mut count,
            GoNode::Opening,
            GoNode::Opening,
            Some("continue_joseki"),
        );

        // Opening → Midgame (major fight begins)
        add(
            &mut adj,
            &mut count,
            GoNode::Opening,
            GoNode::Midgame,
            Some("fight_starts"),
        );

        // Opening → CaptureRace (early capturing race from invasion)
        add(
            &mut adj,
            &mut count,
            GoNode::Opening,
            GoNode::CaptureRace,
            Some("early_invasion"),
        );

        // Opening → Resigned (rare: early resignation after blunder)
        add(
            &mut adj,
            &mut count,
            GoNode::Opening,
            GoNode::Resigned,
            Some("opening_blunder"),
        );

        // Midgame → Midgame (continue fighting)
        add(
            &mut adj,
            &mut count,
            GoNode::Midgame,
            GoNode::Midgame,
            Some("continue_fight"),
        );

        // Midgame → Endgame (territories mostly settled)
        add(
            &mut adj,
            &mut count,
            GoNode::Midgame,
            GoNode::Endgame,
            Some("territories_settled"),
        );

        // Midgame → KoFight (ko situation arises)
        add(
            &mut adj,
            &mut count,
            GoNode::Midgame,
            GoNode::KoFight,
            Some("ko_situation"),
        );

        // Midgame → CaptureRace (semeai starts)
        add(
            &mut adj,
            &mut count,
            GoNode::Midgame,
            GoNode::CaptureRace,
            Some("semeai_starts"),
        );

        // Midgame → Resigned (resignation during fight)
        add(
            &mut adj,
            &mut count,
            GoNode::Midgame,
            GoNode::Resigned,
            Some("resign_fight"),
        );

        // Endgame → Endgame (continue boundary plays)
        add(
            &mut adj,
            &mut count,
            GoNode::Endgame,
            GoNode::Endgame,
            Some("boundary_play"),
        );

        // Endgame → Scoring (both players pass)
        add(
            &mut adj,
            &mut count,
            GoNode::Endgame,
            GoNode::Scoring,
            Some("both_pass"),
        );

        // Endgame → CaptureRace (late capturing race)
        add(
            &mut adj,
            &mut count,
            GoNode::Endgame,
            GoNode::CaptureRace,
            Some("late_semeai"),
        );

        // Endgame → Resigned (resignation after losing endgame)
        add(
            &mut adj,
            &mut count,
            GoNode::Endgame,
            GoNode::Resigned,
            Some("lost_endgame"),
        );

        // KoFight → Midgame (ko resolved, continue fighting)
        add(
            &mut adj,
            &mut count,
            GoNode::KoFight,
            GoNode::Midgame,
            Some("ko_resolved"),
        );

        // KoFight → Endgame (ko resolved, game near end)
        add(
            &mut adj,
            &mut count,
            GoNode::KoFight,
            GoNode::Endgame,
            Some("ko_resolved_late"),
        );

        // CaptureRace → Midgame (race resolved, continue fighting)
        add(
            &mut adj,
            &mut count,
            GoNode::CaptureRace,
            GoNode::Midgame,
            Some("race_won"),
        );

        // CaptureRace → Endgame (race resolved, into endgame)
        add(
            &mut adj,
            &mut count,
            GoNode::CaptureRace,
            GoNode::Endgame,
            Some("race_settled"),
        );

        // CaptureRace → Scoring (race ends game)
        add(
            &mut adj,
            &mut count,
            GoNode::CaptureRace,
            GoNode::Scoring,
            Some("race_decisive"),
        );

        // Scoring → BlackWins
        add(
            &mut adj,
            &mut count,
            GoNode::Scoring,
            GoNode::BlackWins,
            Some("black_ahead"),
        );

        // Scoring → WhiteWins
        add(
            &mut adj,
            &mut count,
            GoNode::Scoring,
            GoNode::WhiteWins,
            Some("white_ahead"),
        );

        // Scoring → Draw (jigo)
        add(
            &mut adj,
            &mut count,
            GoNode::Scoring,
            GoNode::Draw,
            Some("jigo"),
        );

        // Resigned → BlackWins (white resigned)
        add(
            &mut adj,
            &mut count,
            GoNode::Resigned,
            GoNode::BlackWins,
            Some("white_resigned"),
        );

        // Resigned → WhiteWins (black resigned)
        add(
            &mut adj,
            &mut count,
            GoNode::Resigned,
            GoNode::WhiteWins,
            Some("black_resigned"),
        );

        (adj, count)
    }
}

