impl RuliologyArm {
    pub fn new(strategy: FsmStrategy) -> Self {
        Self {
            strategy,
            payoff_estimate: 0.0,
            pull_count: 0,
        }
    }

    /// Update payoff with incremental mean.
    pub fn update(&mut self, reward: f64) {
        self.pull_count += 1;
        let n = self.pull_count as f64;
        self.payoff_estimate += (reward - self.payoff_estimate) / n;
    }

    /// Get the current payoff estimate.
    #[inline]
    pub fn payoff(&self) -> f64 {
        self.payoff_estimate
    }

    /// Number of pulls.
    #[inline]
    pub fn pulls(&self) -> u32 {
        self.pull_count
    }

    /// UCB1 score for this arm.
    pub fn ucb1_score(&self, total_pulls: u32) -> f64 {
        if self.pull_count == 0 {
            return f64::INFINITY;
        }
        let exploration = (2.0 * (total_pulls as f64).ln() / self.pull_count as f64).sqrt();
        self.payoff_estimate + exploration
    }
}

impl RuliologyBandit {
    /// Create from pre-enumerated FSM strategies.
    ///
    /// Runs tournament, extracts Pareto front, creates arms from optimal strategies.
    pub fn from_strategies(
        strategies: &[FsmStrategy],
        rounds: u32,
        payoff_fn: &dyn Fn(u8, u8) -> f64,
        payoff_threshold: f64,
        complexity_threshold: f32,
    ) -> Self {
        // Run tournament
        let win_matrix = FsmEnumerator::tournament(strategies, rounds, payoff_fn);

        // Compute complexities for Pareto front
        let complexities: Vec<f32> = strategies.iter().map(|s| s.complexity()).collect();

        // Extract Pareto-optimal strategies
        let pareto = win_matrix.pareto_front(&complexities);

        // Create arms from Pareto-optimal strategies
        // Index strategies by id once to avoid O(n²) find() inside the
        // pareto loop below (was strategies.iter().find() per pareto entry).
        use std::collections::HashMap;
        let by_id: HashMap<u64, &FsmStrategy> = strategies.iter().map(|s| (s.id(), s)).collect();
        let arms: Vec<RuliologyArm> = pareto
            .iter()
            .filter(|(_, payoff, _)| *payoff >= payoff_threshold)
            .filter_map(|(id, _, _)| by_id.get(id).copied())
            .map(|s| RuliologyArm::new(s.clone()))
            .collect();

        Self {
            arms,
            total_pulls: 0,
            payoff_threshold,
            complexity_threshold,
        }
    }

    /// Select best arm using UCB1.
    pub fn select_arm(&self) -> usize {
        let mut best = 0;
        let mut best_score = f64::NEG_INFINITY;
        for (i, arm) in self.arms.iter().enumerate() {
            let score = arm.ucb1_score(self.total_pulls);
            if score > best_score {
                best_score = score;
                best = i;
            }
        }
        best
    }

    /// Get the FSM strategy for an arm.
    pub fn strategy(&self, arm: usize) -> &FsmStrategy {
        &self.arms[arm].strategy
    }

    /// Update an arm's payoff after observing a reward.
    pub fn update(&mut self, arm: usize, reward: f64) {
        self.arms[arm].update(reward);
        self.total_pulls += 1;
    }

    /// Number of arms (Pareto-optimal strategies).
    #[inline]
    pub fn num_arms(&self) -> usize {
        self.arms.len()
    }

    /// Best arm by payoff estimate.
    pub fn best_arm(&self) -> usize {
        let mut best = 0usize;
        let mut best_payoff = f64::NEG_INFINITY;
        for (i, arm) in self.arms.iter().enumerate() {
            let p = arm.payoff();
            // total_cmp is NaN-deterministic and avoids the panic that
            // partial_cmp(...).unwrap() would trigger on a NaN payoff.
            if p.total_cmp(&best_payoff).is_gt() {
                best_payoff = p;
                best = i;
            }
        }
        best
    }

    /// Best arm by payoff, excluding already-promoted arms.
    pub fn best_unpromoted_arm(&self, promoted: &HashSet<usize>) -> usize {
        let mut best = 0usize;
        let mut best_payoff = f64::NEG_INFINITY;
        for (i, arm) in self.arms.iter().enumerate() {
            if promoted.contains(&i) {
                continue;
            }
            let p = arm.payoff();
            if p.total_cmp(&best_payoff).is_gt() {
                best_payoff = p;
                best = i;
            }
        }
        best
    }

    /// Get all arms.
    #[inline]
    pub fn arms(&self) -> &[RuliologyArm] {
        &self.arms
    }

    /// Total pulls across all arms.
    #[inline]
    pub fn total_pulls(&self) -> u32 {
        self.total_pulls
    }
}

impl RuliologyAbsorbCompress {
    /// Create new absorb-compress adapter wrapping a RuliologyBandit.
    pub fn new(bandit: RuliologyBandit, config: RuliologyPromoteConfig) -> Self {
        Self {
            bandit,
            config,
            total_absorbed: 0,
            promoted: HashSet::new(),
        }
    }

    /// Absorb an observation: update arm payoff.
    pub fn absorb(&mut self, arm: usize, reward: f64) {
        self.bandit.update(arm, reward);
        self.total_absorbed += 1;
    }

    /// Whether enough observations have been absorbed to trigger compression.
    pub fn should_compress(&self) -> bool {
        self.total_absorbed > 0
            && self
                .total_absorbed
                .is_multiple_of(self.config.check_interval)
    }

    /// Promote arms with stable positive payoff.
    ///
    /// Returns indices of newly promoted arms.
    pub fn compress(&mut self) -> Vec<usize> {
        let mut newly_promoted = Vec::new();

        for (i, arm) in self.bandit.arms().iter().enumerate() {
            if self.promoted.contains(&i) {
                continue;
            }
            if arm.pulls() < self.config.min_visits {
                continue;
            }
            if arm.payoff() >= self.config.payoff_threshold {
                self.promoted.insert(i);
                newly_promoted.push(i);
                if newly_promoted.len() >= self.config.max_promotions {
                    break;
                }
            }
        }

        newly_promoted
    }

    /// Get the best promoted arm (winner), if any.
    pub fn promoted_winner(&self) -> Option<usize> {
        if self.promoted.is_empty() {
            return None;
        }
        // Among promoted arms, find the one with highest payoff.
        self.promoted
            .iter()
            .filter(|&&i| i < self.bandit.arms().len())
            .max_by(|&&a, &&b| {
                let pa = self.bandit.arms()[a].payoff();
                let pb = self.bandit.arms()[b].payoff();
                pa.total_cmp(&pb)
            })
            .copied()
    }

    /// Access the inner bandit.
    pub fn bandit(&self) -> &RuliologyBandit {
        &self.bandit
    }

    /// Mutable access to the inner bandit.
    pub fn bandit_mut(&mut self) -> &mut RuliologyBandit {
        &mut self.bandit
    }

    /// Promoted arm indices.
    pub fn promoted_arms(&self) -> &HashSet<usize> {
        &self.promoted
    }

    /// Total observations absorbed.
    #[inline]
    pub fn total_absorbed(&self) -> u32 {
        self.total_absorbed
    }
}

impl CaStrategy {
    /// Create a new CA strategy with given rule number and tape width.
    ///
    /// `tape_width` should be odd so the center cell is unambiguous.
    #[inline]
    pub fn new(rule: u8, tape_width: usize) -> Self {
        let complexity = Self::compute_complexity(rule);
        let w = tape_width.max(3);
        let id = Self::compute_id(rule);
        Self {
            rule,
            tape_width: w,
            complexity,
            id,
            tape: vec![0u8; w],
            new_tape: vec![0u8; w],
        }
    }

    /// Rule number.
    #[inline]
    pub fn rule(&self) -> u8 {
        self.rule
    }

    /// Tape width.
    #[inline]
    pub fn tape_width(&self) -> usize {
        self.tape_width
    }

    /// Apply CA rule to a 3-cell neighborhood.
    ///
    /// `neighborhood` is packed as bits: `(left << 2) | (center << 1) | right`.
    /// The rule byte's bit at position `neighborhood` gives the output.
    #[inline]
    pub fn apply_rule(&self, neighborhood: u8) -> u8 {
        (self.rule >> neighborhood) & 1
    }

    /// Complexity = popcount(rule) / 8.0.
    ///
    /// Normalized to [0, 1]: 0 = rule 0 (always 0), 1 = rule 255 (always 1).
    /// Measures how many of the 8 possible neighborhood outputs are "on".
    fn compute_complexity(rule: u8) -> f32 {
        rule.count_ones() as f32 / 8.0
    }

    /// Blake3 hash of rule byte → u64 ID. Computed once at construction and
    /// cached in `self.id` to avoid blake3 calls on every `HashSet` lookup.
    fn compute_id(rule: u8) -> u64 {
        let hash = blake3::hash(&[rule]);
        let bytes: [u8; 8] = hash.as_bytes()[..8].try_into().unwrap_or([0u8; 8]);
        u64::from_le_bytes(bytes)
    }

    /// Enumerate all 256 elementary CA rules.
    pub fn enumerate_all() -> Vec<CaStrategy> {
        (0u8..=255)
            .map(|rule| CaStrategy::new(rule, DEFAULT_TAPE_WIDTH))
            .collect()
    }

    /// Enumerate only behaviorally distinct CA rules.
    ///
    /// Two rules are equivalent if one can be obtained from the other by:
    /// - Left-right reflection (swap L↔R in neighborhood)
    /// - Color complement (swap 0↔1 in output)
    /// - Both
    ///
    /// Wolfram identified ~88 distinct rules from the 256 elementary CAs.
    /// We use behavioral fingerprinting via blake3 hash of outputs over all
    /// possible input sequences, similar to FsmEnumerator's dedup.
    pub fn enumerate_distinct() -> Vec<CaStrategy> {
        let all = Self::enumerate_all();
        let mut seen: HashSet<[u8; 32]> = HashSet::with_capacity(all.len());
        let mut distinct: Vec<CaStrategy> = Vec::with_capacity(128);

        // Test all possible tape configurations up to tape_width.
        // For each tape config, run the CA and collect outputs.
        let w = DEFAULT_TAPE_WIDTH;
        let n_configs = 1usize << w;
        let mut fingerprint = Vec::with_capacity(n_configs * w);
        // Reusable scratch tapes — hoisted out of the inner loop to avoid
        // 256 * n_configs allocations (was vec![0u8; w] per config).
        let mut tape = vec![0u8; w];
        let mut new_tape = vec![0u8; w];

        for ca in all {
            fingerprint.clear();

            // For each possible initial tape configuration.
            for config in 0..n_configs {
                for (i, cell) in tape.iter_mut().enumerate() {
                    *cell = ((config >> i) & 1) as u8;
                }

                // Apply CA rule once into new_tape.
                Self::step_into(&tape, ca.rule, &mut new_tape);

                // Record the center cell output.
                fingerprint.push(new_tape[w / 2]);
            }

            let hash = blake3::hash(&fingerprint);
            if seen.insert(hash.into()) {
                distinct.push(ca);
            }
        }

        distinct
    }

    /// Single CA step into a caller-provided buffer: apply rule to each cell's
    /// neighborhood (wrap-around). `out` must be the same length as `tape`.
    ///
    /// This is the zero-alloc variant of [`step`](Self::step); used by hot
    /// enumeration paths that reuse a scratch buffer across many calls.
    #[inline]
    fn step_into(tape: &[u8], rule: u8, out: &mut [u8]) {
        let n = tape.len();
        debug_assert_eq!(out.len(), n);
        for i in 0..n {
            let left = tape[(i + n - 1) % n];
            let center = tape[i];
            let right = tape[(i + 1) % n];
            let neighborhood = (left << 2) | (center << 1) | right;
            out[i] = (rule >> neighborhood) & 1;
        }
    }
}

impl SimpleProgram for CaStrategy {
    /// Produce next action given opponent's action history.
    ///
    /// 1. If opponent_history is empty, output based on rule applied to all-zeros neighborhood.
    /// 2. Otherwise, take last `tape_width` opponent moves as tape (padded with 0s if shorter).
    /// 3. Apply the CA rule once to produce a new tape.
    /// 4. Return the center cell of the new tape.
    ///
    /// Zero-allocation: reuses `self.tape` / `self.new_tape` scratch buffers
    /// instead of allocating two `Vec<u8>` per call.
    fn next_action(&mut self, opponent_history: &[u8]) -> u8 {
        let w = self.tape_width;
        debug_assert_eq!(self.tape.len(), w);
        debug_assert_eq!(self.new_tape.len(), w);

        // Build initial tape from opponent history (zero-filled).
        self.tape.fill(0);
        if !opponent_history.is_empty() {
            // Fill tape: most recent moves go to the right side.
            let hist_len = opponent_history.len().min(w);
            let start = w - hist_len;
            for (i, &action) in opponent_history.iter().rev().take(w).enumerate() {
                self.tape[start + hist_len - 1 - i] = if action > 0 { 1 } else { 0 };
            }
        }

        // Apply CA rule once into the reusable output buffer.
        Self::step_into(&self.tape, self.rule, &mut self.new_tape);

        // Return center cell.
        self.new_tape[w / 2]
    }

    /// Blake3 hash of rule byte → u64 ID (cached at construction).
    #[inline]
    fn id(&self) -> u64 {
        self.id
    }

    /// Complexity score (cached at construction).
    #[inline]
    fn complexity(&self) -> f32 {
        self.complexity
    }
}

impl FsmStrategy {
    /// Create a new FSM from raw transition/output tables.
    ///
    /// `transitions[i][j]` = next state from state `i` on input `j`.
    /// `outputs[i]` = action (0 or 1) emitted in state `i`.
    /// `initial_state` = starting state (typically 0).
    #[inline]
    pub fn new(
        transitions: [[u8; 2]; MAX_STATES],
        outputs: [u8; MAX_STATES],
        n_states: u8,
        initial_state: u8,
    ) -> Self {
        debug_assert!(n_states as usize <= MAX_STATES);
        debug_assert!((initial_state as usize) < (n_states as usize));

        let complexity = Self::compute_complexity(n_states, &transitions, &outputs);
        let id = Self::compute_id(n_states, &transitions, &outputs);

        Self {
            transitions,
            outputs,
            state: initial_state,
            n_states,
            complexity,
            id,
        }
    }

    /// Complexity = log2(distinct transitions + distinct outputs) / log2(max theoretical).
    ///
    /// For an N-state FSM: at most 2*N transitions + N outputs = 3*N distinct values.
    /// Actual distinct values / max → normalized to [0, 1].
    fn compute_complexity(
        n_states: u8,
        transitions: &[[u8; 2]; MAX_STATES],
        outputs: &[u8; MAX_STATES],
    ) -> f32 {
        let n = n_states as usize;
        // Fixed-size stack buffer (3 * MAX_STATES = 12 bytes). Avoids a heap
        // allocation on every FsmStrategy::new — the enumerator builds up to
        // (n*n*2)^n strategies (e.g. ~1M for n=4), so this is on a hot path.
        // The manual stable sort + dedup below is bit-identical to Vec::sort +
        // Vec::dedup on the same byte sequence (total order on u8, equal runs
        // collapsed to the first occurrence).
        //
        // n=0 early return matches the original's `max_distinct == 0.0` branch
        // (kept here so the dedup logic below can assume len >= 1).
        if n == 0 {
            return 0.0;
        }
        let mut vals = [0u8; 3 * MAX_STATES];
        let mut len = 0usize;

        for s in 0..n {
            vals[len] = transitions[s][0];
            vals[len + 1] = transitions[s][1];
            vals[len + 2] = outputs[s];
            len += 3;
        }

        // Stable insertion-sort on the active prefix. Byte domain is tiny, so
        // the quadratic constant is negligible; the win is avoiding the heap
        // trip. Equality semantics match slice::sort (total order on u8).
        let active = &mut vals[..len];
        for i in 1..active.len() {
            let key = active[i];
            let mut j = i;
            while j > 0 && active[j - 1] > key {
                active[j] = active[j - 1];
                j -= 1;
            }
            active[j] = key;
        }

        // Dedup in-place (matches slice::dedup: collapse runs of equal
        // elements to a single occurrence).
        let mut write = 1usize;
        for read in 1..active.len() {
            if active[read] != active[write - 1] {
                active[write] = active[read];
                write += 1;
            }
        }
        let distinct = write as f32;
        let max_distinct = (3 * n) as f32;

        distinct / max_distinct
    }

    /// Blake3 hash of transitions + outputs → u64 ID. Computed once at
    /// construction and cached in `self.id` to avoid blake3 calls on every
    /// `HashSet` lookup (was 2 blake3 invocations per `contains`/`insert`).
    fn compute_id(
        n_states: u8,
        transitions: &[[u8; 2]; MAX_STATES],
        outputs: &[u8; MAX_STATES],
    ) -> u64 {
        let mut hasher = blake3::Hasher::new();
        for s in 0..n_states as usize {
            hasher.update(&[transitions[s][0], transitions[s][1], outputs[s]]);
        }
        hasher.update(&[n_states]);
        let hash = hasher.finalize();
        let bytes: [u8; 8] = hash.as_bytes()[..8].try_into().unwrap_or([0u8; 8]);
        u64::from_le_bytes(bytes)
    }

    /// Reset FSM to initial state for a new game.
    #[inline]
    pub fn reset(&mut self) {
        self.state = 0;
    }

    /// Current state index.
    #[inline]
    pub fn state(&self) -> u8 {
        self.state
    }

    /// Number of states.
    #[inline]
    pub fn n_states(&self) -> u8 {
        self.n_states
    }

    /// Get the transition table.
    #[inline]
    pub fn transitions(&self) -> &[[u8; 2]; MAX_STATES] {
        &self.transitions
    }

    /// Get the output table.
    #[inline]
    pub fn outputs(&self) -> &[u8; MAX_STATES] {
        &self.outputs
    }
}

impl SimpleProgram for FsmStrategy {
    /// Produce next action given opponent's action history.
    ///
    /// Reads the last opponent action as input, transitions to next state,
    /// and outputs the current state's action.
    fn next_action(&mut self, opponent_history: &[u8]) -> u8 {
        if let Some(&last_input) = opponent_history.last() {
            let input = if last_input > 0 { 1 } else { 0 };
            let ns = self.transitions[self.state as usize][input];
            // Clamp to valid range.
            self.state = if ns < self.n_states { ns } else { 0 };
        }
        self.outputs[self.state as usize]
    }

    /// Blake3 hash of transitions + outputs → u64 ID (cached at construction).
    #[inline]
    fn id(&self) -> u64 {
        self.id
    }

    /// Complexity score (cached at construction).
    #[inline]
    fn complexity(&self) -> f32 {
        self.complexity
    }
}

impl FsmEnumerator {
    /// Enumerate all distinct FSMs with `n_states` states.
    ///
    /// For N=2: 2 states, each has (next_0, next_1, output) = 2*2*2 = 8 configs,
    /// so 8^2 = 64 raw combinations. After dedup ~22 distinct.
    ///
    /// For N=3: 3 states, 18^3 = 5832 raw, dedup to ~956 distinct.
    ///
    /// Deduplication strategy: generate all raw FSMs, simulate each against
    /// all possible input sequences up to a test horizon (scaled by state count),
    /// hash the behavioral fingerprint with blake3, and keep only distinct ones.
    pub fn enumerate(n_states: u8) -> Vec<FsmStrategy> {
        let n = n_states as usize;
        debug_assert!((1..=MAX_STATES).contains(&n));

        let mut raw = Vec::new();
        Self::enumerate_raw(n_states, &mut raw);

        // Test horizon must exceed max period: N-state vs N-state max period = N².
        // Use N² + 2 to ensure full behavioral coverage.
        // N=2: horizon=6, N=3: horizon=11, N=4: horizon=18.
        let test_horizon = (n * n + 2).min(20);
        let n_sequences = 1usize << test_horizon;

        // Use blake3 hashes instead of raw fingerprints for O(1) lookup.
        let mut seen: HashSet<[u8; 32]> = HashSet::with_capacity(raw.len());
        let mut distinct: Vec<FsmStrategy> = Vec::with_capacity(raw.len());

        let mut fingerprint = Vec::with_capacity(n_sequences * test_horizon);
        // Hoisted out of the seq_idx loop — avoids n_sequences * raw.len()
        // allocations of a Vec<u8> per behavioral fingerprint test.
        let mut history: Vec<u8> = Vec::with_capacity(test_horizon);

        for mut fsm in raw {
            fingerprint.clear();

            for seq_idx in 0..n_sequences {
                fsm.reset();
                history.clear();

                for bit in 0..test_horizon {
                    let input = ((seq_idx >> bit) & 1) as u8;
                    let action = fsm.next_action(&history);
                    fingerprint.push(action);
                    history.push(input);
                }
            }

            let hash = blake3::hash(&fingerprint);
            if seen.insert(hash.into()) {
                distinct.push(fsm);
            }
        }

        distinct
    }

    /// Generate all raw FSM combinations without deduplication.
    fn enumerate_raw(n_states: u8, out: &mut Vec<FsmStrategy>) {
        let n = n_states as usize;
        // Each state has (next_0, next_1, output) = n * n * 2 possibilities.
        let configs_per_state = n * n * 2;
        let total = usize::pow(configs_per_state, n as u32);

        out.reserve(total);

        for raw_idx in 0..total {
            let mut idx = raw_idx;
            let mut transitions = [[0u8; 2]; MAX_STATES];
            let mut outputs = [0u8; MAX_STATES];

            for s in 0..n {
                let remainder = idx % configs_per_state;
                idx /= configs_per_state;

                transitions[s][0] = (remainder % n) as u8;
                transitions[s][1] = ((remainder / n) % n) as u8;
                outputs[s] = ((remainder / (n * n)) % 2) as u8;
            }

            out.push(FsmStrategy::new(transitions, outputs, n_states, 0));
        }
    }

    /// Run round-robin tournament: every strategy vs every other strategy.
    ///
    /// Each pair plays `rounds` rounds of the game. Returns complete
    /// win matrix with payoffs and rankings.
    ///
    /// Complexity: O(n² × rounds) where n = strategies.len().
    ///
    /// # Last-action-only hot path (FSM-specific)
    ///
    /// This tournament is monomorphic over `FsmStrategy`, whose `next_action`
    /// reads only `opponent_history.last()` (it has no memory beyond the prior
    /// opponent move). The hot loop exploits that by tracking the last action
    /// as a single `u8` per player and passing a 1-element slice — bit-identical
    /// to the prior Vec<push> implementation (FSM never observes history beyond
    /// `[len-1]`) but eliminates 2x Vec::push per round per pair.
    ///
    /// DO NOT copy this optimization into a generic `SimpleProgram` tournament
    /// without first verifying the impl's history contract: `CaStrategy`'s
    /// `next_action` reads up to `tape_width` (default 7) most-recent opponent
    /// moves, so a CA-tournament must keep the full Vec<u8> history per player.
    /// `TmStrategy` reads only `last()` (writes opponent's last move to the
    /// tape at the head) so the optimization would be safe for a TM-tournament.
    pub fn tournament(
        strategies: &[FsmStrategy],
        rounds: u32,
        payoff_fn: &dyn Fn(u8, u8) -> f64,
    ) -> WinMatrix {
        let n = strategies.len();
        let mut payoffs = vec![vec![0.0f64; n]; n];

        // First-round sentinel: empty slice (no prior opponent move).
        // Subsequent rounds pass a 1-element slice of the prior action.
        let empty: [u8; 0] = [];

        for i in 0..n {
            for j in 0..n {
                if i == j {
                    continue;
                }

                let mut si = strategies[i].clone();
                let mut sj = strategies[j].clone();
                si.reset();
                sj.reset();

                let mut total_payoff = 0.0f64;
                let mut last_action_i: u8 = 0; // only read after round 0
                let mut last_action_j: u8 = 0;
                let mut first_round = true;

                for _ in 0..rounds {
                    // Round k reads the opponent's action from round k-1.
                    let hist_j: &[u8] = if first_round { &empty } else { std::slice::from_ref(&last_action_j) };
                    let hist_i: &[u8] = if first_round { &empty } else { std::slice::from_ref(&last_action_i) };
                    let action_i = si.next_action(hist_j);
                    let action_j = sj.next_action(hist_i);

                    total_payoff += payoff_fn(action_i, action_j);

                    last_action_i = action_i;
                    last_action_j = action_j;
                    first_round = false;
                }

                payoffs[i][j] = total_payoff / rounds as f64;
            }
        }

        let ids: Vec<u64> = strategies.iter().map(|s| s.id()).collect();
        WinMatrix::new(payoffs, ids)
    }
}

use crate::types::WinMatrix;

// ── IrreducibilityResult ──────────────────────────────────────

/// Result of irreducibility analysis.
#[derive(Debug, Clone, Copy)]
pub struct IrreducibilityResult {
    /// Compression ratio of the win matrix (0.0 = fully compressible, 1.0 = fully random).
    /// Ratio = compressed_size / raw_size.
    pub compression_ratio: f32,
    /// Whether the game is considered irreducible (ratio above threshold).
    pub is_irreducible: bool,
    /// Mean absolute payoff in the matrix (indicator of game dynamics).
    pub mean_abs_payoff: f64,
    /// Payoff variance (high variance = complex dynamics).
    pub payoff_variance: f64,
}

impl IrreducibilityGate {
    /// Create a new gate with the given compression ratio threshold.
    #[inline]
    pub fn new(threshold: f32) -> Self {
        Self { threshold }
    }

    /// Analyze a win matrix for irreducibility.
    ///
    /// Returns compression ratio, irreducibility verdict, and payoff statistics.
    ///
    /// Uses Shannon entropy of the quantized byte distribution as the primary
    /// Kolmogorov complexity proxy. Low entropy = low complexity = reducible.
    /// For high-entropy matrices, falls back to RLE compression ratio.
    ///
    /// # Single-pass fusion
    ///
    /// The prior implementation iterated `matrix.payoffs` three times
    /// (quantize → payoff_stats → freq). Fused into one pass: quantize each
    /// payoff into a byte, accumulate `freq[byte]`, and accumulate
    /// `sum_abs` + `sum_abs_sq` for the (mean, variance) computation. The
    /// output is `Vec<u8>` plus the two scalar accumulators; the entropy
    /// + variance math runs once over the freq table + scalars, not over
    ///   the matrix again.
    pub fn analyze(&self, matrix: &WinMatrix) -> IrreducibilityResult {
        let n = matrix.payoffs.len();
        // Upper bound on raw byte count — actual may be less if rows are
        // short, but this avoids grow calls during the fused push loop.
        let mut raw = Vec::with_capacity(n.saturating_mul(n));
        let mut freq = [0u32; 256];
        // Payoff-stat accumulators (mean + variance of |payoff|).
        let mut sum_abs = 0.0f64;
        let mut sum_abs_sq = 0.0f64;
        let mut count = 0usize;

        for row in &matrix.payoffs {
            for &val in row {
                // Quantize [-1, 1] → [0, 255].
                let normalized = ((val + 1.0) * 127.5).clamp(0.0, 255.0);
                let q = normalized as u8;
                raw.push(q);
                freq[q as usize] += 1;
                // Payoff stats — |val| not quantized.
                let abs_val = val.abs();
                sum_abs += abs_val;
                sum_abs_sq += abs_val * abs_val;
                count += 1;
            }
        }

        let total = raw.len() as u32;

        // Shannon entropy of byte distribution (bits).
        let entropy = if total == 0 {
            0.0f32
        } else {
            let mut h = 0.0f32;
            let inv_total = 1.0 / total as f32;
            for &cnt in &freq {
                if cnt > 0 {
                    let p = cnt as f32 * inv_total;
                    h -= p * p.log2();
                }
            }
            h
        };

        // Normalized entropy: 0.0 = all same byte, 1.0 = uniform distribution.
        // Max entropy for byte data = 8 bits.
        let normalized_entropy = entropy / 8.0;

        // RLE compression ratio as secondary signal.
        // `rle_compressed_len` is the zero-alloc variant of `rle_compress`:
        // the analyzer only needs the LENGTH of the RLE output (to compute
        // the ratio), not the output bytes themselves. The original path
        // built a full Vec<u8> every call just to read its .len() afterward.
        let compressed_len = rle_compressed_len(&raw);
        let rle_ratio = if raw.is_empty() {
            0.0
        } else {
            compressed_len as f32 / raw.len() as f32
        };

        // Effective compression ratio: use entropy when it's low (structured data),
        // RLE when entropy is high (potentially compressible despite high entropy).
        let compression_ratio = if entropy < 4.0 {
            // Low entropy → highly structured, use normalized entropy as ratio.
            normalized_entropy
        } else if rle_ratio < normalized_entropy {
            // High entropy but RLE compresses → some structure exists.
            rle_ratio
        } else {
            // High entropy, RLE doesn't help → likely irreducible.
            normalized_entropy
        };

        let (mean, variance) = if count == 0 {
            (0.0, 0.0)
        } else {
            let mean = sum_abs / count as f64;
            let variance = sum_abs_sq / count as f64 - mean * mean;
            (mean, variance.max(0.0)) // numerical guard
        };

        IrreducibilityResult {
            compression_ratio,
            is_irreducible: compression_ratio > self.threshold,
            mean_abs_payoff: mean,
            payoff_variance: variance,
        }
    }

    /// Quick check: is the game irreducible?
    pub fn is_irreducible(&self, matrix: &WinMatrix) -> bool {
        self.analyze(matrix).is_irreducible
    }
}

