// ── FsmTemplateProposer ──────────────────────────────────────────

/// Mutation operator for FSM strategies.
///
/// Applies stochastic mutations to FSM transition/output tables:
/// - **Output flip**: toggle a state's output (0↔1)
/// - **Edge reroute**: redirect a random transition to a different state
///
/// Mutation rate controls the expected fraction of elements changed per proposal.
pub struct FsmTemplateProposer {
    /// Number of states in target FSMs.
    n_states: u8,
    /// Mutation probability per element (transition or output).
    mutation_rate: f32,
}

/// Result of a co-evolution run.
#[derive(Debug, Clone)]
pub struct CoEvolutionResult {
    /// Best FSM found (by average payoff).
    pub best_fsm: FsmStrategy,
    /// Average payoff of best FSM.
    pub best_payoff: f64,
    /// Number of generations elapsed.
    pub generations: u32,
    /// Mutation history: (generation, payoff) pairs.
    pub history: Vec<(u32, f64)>,
    /// Number of mutations accepted.
    pub accepted: u32,
    /// Number of mutations rejected (δ below threshold or not improving).
    pub rejected: u32,
}

/// Mutation types for FSM graphs.
#[derive(Debug, Clone, Copy, PartialEq)]
#[repr(u8)]
pub enum MutationType {
    /// Flip the output of a random state.
    OutputFlip,
    /// Change a random transition target.
    EdgeReroute,
}

impl FsmTemplateProposer {
    /// Create a new proposer with given state count and mutation rate.
    #[inline]
    pub fn new(n_states: u8, mutation_rate: f32) -> Self {
        debug_assert!(n_states as usize <= MAX_STATES);
        Self {
            n_states,
            mutation_rate,
        }
    }

impl SimulationGate {
    /// Create a new simulation gate with the given config.
    pub fn new(config: SimulationGateConfig) -> Self {
        let irreducibility = IrreducibilityGate::new(config.irreducible_threshold);
        Self {
            irreducibility,
            config,
        }
    }

    /// Analyze a win matrix and recommend a simulation strategy.
    ///
    /// Returns the recommended strategy, number of rounds, and irreducibility metrics.
    pub fn route(&self, matrix: &WinMatrix) -> SimulationGateResult {
        let result = self.irreducibility.analyze(matrix);

        let (strategy, recommended_rounds) =
            if result.compression_ratio < self.config.reducible_threshold {
                // Low irreducibility → game has predictable structure.
                // Analytical shortcuts exist: skip expensive simulation.
                (SimulationStrategy::AnalyticalShortcut, 0)
            } else if result.compression_ratio >= self.config.irreducible_threshold {
                // High irreducibility → must simulate.
                // Full bandit/MCTS/rollout required.
                (SimulationStrategy::FullSimulation, self.config.full_rounds)
            } else {
                // Borderline → lightweight simulation as compromise.
                (
                    SimulationStrategy::LightweightSimulation,
                    self.config.lightweight_rounds,
                )
            };

        SimulationGateResult {
            strategy,
            recommended_rounds,
            compression_ratio: result.compression_ratio,
            is_irreducible: result.is_irreducible,
            mean_abs_payoff: result.mean_abs_payoff,
            payoff_variance: result.payoff_variance,
        }
    }

    /// Quick check: should we skip simulation?
    ///
    /// Returns `true` if the game is reducible and analytical shortcuts are available.
    pub fn should_skip_simulation(&self, matrix: &WinMatrix) -> bool {
        let result = self.irreducibility.analyze(matrix);
        result.compression_ratio < self.config.reducible_threshold
    }

    /// Quick check: do we need full simulation?
    ///
    /// Returns `true` if the game is irreducible and full bandit/MCTS is required.
    pub fn needs_full_simulation(&self, matrix: &WinMatrix) -> bool {
        let result = self.irreducibility.analyze(matrix);
        result.compression_ratio >= self.config.irreducible_threshold
    }

    /// Get the routing configuration.
    pub fn config(&self) -> &SimulationGateConfig {
        &self.config
    }
}

#[cfg(test)]
use crate::tm::TmStrategy;

/// Play two SimpleProgram strategies against each other for `rounds` rounds.
///
/// Returns the total payoff for player A.
#[cfg(test)]
fn play_match<A: SimpleProgram, B: SimpleProgram>(
    a: &mut A,
    b: &mut B,
    rounds: u32,
    payoff_fn: &dyn Fn(u8, u8) -> f64,
) -> f64 {
    let mut hist_a: Vec<u8> = Vec::with_capacity(rounds as usize);
    let mut hist_b: Vec<u8> = Vec::with_capacity(rounds as usize);
    let mut total = 0.0f64;

    for _ in 0..rounds {
        let action_a = a.next_action(&hist_b);
        let action_b = b.next_action(&hist_a);
        total += payoff_fn(action_a, action_b);
        hist_a.push(action_a);
        hist_b.push(action_b);
    }

    total
}

impl TmStrategy {
    /// Create a new TM strategy.
    ///
    /// `transitions[0]` = (write, direction, next_state) for symbol 0.
    /// `transitions[1]` = (write, direction, next_state) for symbol 1.
    /// `n_states` = number of states (1 for simplest TMs).
    /// `tape_width` = initial tape size.
    pub fn new(transitions: [(u8, u8, u8); 2], n_states: u8, tape_width: usize) -> Self {
        let complexity = Self::compute_complexity(&transitions, n_states);
        let id = Self::compute_id(&transitions, n_states);
        let w = tape_width.max(3);
        Self {
            transitions,
            head: w / 2,
            tape: vec![0u8; w],
            state: 0,
            n_states,
            complexity,
            id,
        }
    }

    /// Transition table.
    #[inline]
    pub fn transitions(&self) -> &[(u8, u8, u8); 2] {
        &self.transitions
    }

    /// Current head position.
    #[inline]
    pub fn head(&self) -> usize {
        self.head
    }

    /// Current tape contents.
    #[inline]
    pub fn tape(&self) -> &[u8] {
        &self.tape
    }

    /// Current state.
    #[inline]
    pub fn state(&self) -> u8 {
        self.state
    }

    /// Number of states.
    #[inline]
    pub fn n_states(&self) -> u8 {
        self.n_states
    }

    /// Complexity = distinct transition behaviors / max possible.
    ///
    /// Each transition has (write, direction, next_state). We count distinct
    /// triplets across all symbol entries, normalized by total entries.
    fn compute_complexity(transitions: &[(u8, u8, u8); 2], n_states: u8) -> f32 {
        // Fixed-size stack buffer (6 bytes — exactly 2 transitions × 3 fields).
        // Avoids a heap allocation on every TmStrategy::new; the 1-state
        // enumerator builds 36 machines, but this same complexity calc runs
        // for every additional enumeration pass.
        //
        // Bit-identical to Vec::sort + Vec::dedup on the same byte sequence
        // (total order on u8; stable insertion sort preserves equal-run
        // ordering; dedup collapses runs to the first occurrence).
        let mut vals = [0u8; 6];
        let mut idx = 0usize;
        for &(w, d, ns) in transitions {
            vals[idx] = w;
            vals[idx + 1] = d;
            vals[idx + 2] = ns;
            idx += 3;
        }

        // Stable insertion-sort on the full 6-byte buffer.
        for i in 1..vals.len() {
            let key = vals[i];
            let mut j = i;
            while j > 0 && vals[j - 1] > key {
                vals[j] = vals[j - 1];
                j -= 1;
            }
            vals[j] = key;
        }

        // Dedup in-place (matches slice::dedup).
        let mut write = 1usize;
        for read in 1..vals.len() {
            if vals[read] != vals[write - 1] {
                vals[write] = vals[read];
                write += 1;
            }
        }
        let distinct = write as f32;
        // Max distinct: write has 2 values, direction has 3, next_state has n_states.
        let max_distinct = (2 + 3 + n_states as usize) as f32;
        if max_distinct == 0.0 {
            return 0.0;
        }
        distinct / max_distinct
    }

    /// Blake3 hash of transition table → u64 ID. Computed once at construction
    /// and cached in `self.id` to avoid blake3 calls on every `HashSet` lookup
    /// (was 2 blake3 invocations per `contains`/`insert`).
    fn compute_id(transitions: &[(u8, u8, u8); 2], n_states: u8) -> u64 {
        let mut hasher = blake3::Hasher::new();
        for &(w, d, ns) in transitions {
            hasher.update(&[w, d, ns]);
        }
        hasher.update(&[n_states]);
        let hash = hasher.finalize();
        let bytes: [u8; 8] = hash.as_bytes()[..8].try_into().unwrap_or([0u8; 8]);
        u64::from_le_bytes(bytes)
    }

    /// Enumerate all 1-state, 2-symbol Turing machines.
    ///
    /// For 1 state, 2 symbols:
    /// - Each symbol has: write ∈ {0,1}, direction ∈ {0,1,2}, next_state ∈ {0}
    /// - So each symbol has 2 × 3 × 1 = 6 configs
    /// - Total: 6 × 6 = 36 machines
    pub fn enumerate_1_state() -> Vec<TmStrategy> {
        let mut machines = Vec::with_capacity(36);

        for sym0_config in 0..6 {
            for sym1_config in 0..6 {
                let t0 = Self::decode_transition(sym0_config, 1);
                let t1 = Self::decode_transition(sym1_config, 1);
                machines.push(TmStrategy::new([t0, t1], 1, DEFAULT_TAPE_WIDTH));
            }
        }

        machines
    }

    /// Decode a packed config index into (write, direction, next_state).
    ///
    /// Encoding: config = write + direction * 2 + next_state * 6
    /// For 1 state: next_state is always 0.
    fn decode_transition(config: u8, n_states: u8) -> (u8, u8, u8) {
        let write = config % 2;
        let direction = (config / 2) % 3;
        let next_state = (config / 6) % n_states.max(1);
        (write, direction, next_state)
    }

    /// Reset TM to initial state for a new game.
    pub fn reset(&mut self) {
        self.state = 0;
        self.head = self.tape.len() / 2;
        self.tape.fill(0);
    }

    /// Ensure tape is large enough for head position.
    fn ensure_tape_size(&mut self) {
        if self.head >= self.tape.len() {
            // Double the tape, placing new cells (0) at the end.
            let old_len = self.tape.len();
            self.tape.resize(old_len * 2, 0);
        }
    }
}

impl SimpleProgram for TmStrategy {
    /// Produce next action given opponent's action history.
    ///
    /// 1. Write opponent's last move into the tape at the current head position
    ///    (or leave tape as-is if no history).
    /// 2. Read symbol at head position.
    /// 3. Apply transition: write symbol, move head, change state.
    /// 4. Return the symbol written.
    fn next_action(&mut self, opponent_history: &[u8]) -> u8 {
        // Ensure tape covers `head` before any indexed access below. Previously
        // this was called twice (once inside the `if let`, once unconditionally);
        // a single call upfront is sufficient — `head` does not change between
        // this point and the indexed reads/writes that follow.
        self.ensure_tape_size();

        // If there's opponent history, write the last move to the tape at head.
        // This initializes the tape from the game context.
        if let Some(&last) = opponent_history.last() {
            let val = if last > 0 { 1 } else { 0 };
            self.tape[self.head] = val;
        }

        // Read current symbol.
        let symbol = self.tape[self.head];

        // Look up transition for this symbol.
        let (write, direction, next_state) = self.transitions[symbol as usize];

        // Write new symbol.
        self.tape[self.head] = write;

        // Move head.
        let tape_len = self.tape.len();
        match direction {
            0 => {
                // Left.
                self.head = if self.head == 0 {
                    tape_len - 1
                } else {
                    self.head - 1
                };
            }
            1 => {
                // Right.
                self.head = (self.head + 1) % tape_len;
            }
            _ => {
                // Stay — no movement.
            }
        }

        // Change state (clamped to valid range).
        self.state = if next_state < self.n_states {
            next_state
        } else {
            0
        };

        write
    }

    /// Blake3 hash of transition table → u64 ID (cached at construction).
    #[inline]
    fn id(&self) -> u64 {
        self.id
    }

    /// Complexity score (cached at construction).
    #[inline]
    fn complexity(&self) -> f32 {
        self.complexity
    }
}

impl WinMatrix {
    /// Build a `WinMatrix` from raw payoff data and strategy IDs.
    ///
    /// Computes rankings as average payoff across all opponents.
    #[inline]
    pub fn new(payoffs: Vec<Vec<f64>>, ids: Vec<u64>) -> Self {
        let n = ids.len();
        debug_assert_eq!(payoffs.len(), n);

        let mut rankings: Vec<(u64, f64)> = ids
            .iter()
            .enumerate()
            .map(|(i, &id)| {
                let avg = if n > 1 {
                    payoffs[i].iter().sum::<f64>() / (n - 1) as f64
                } else {
                    0.0
                };
                (id, avg)
            })
            .collect();

        rankings.sort_by(|a, b| b.1.total_cmp(&a.1));

        Self {
            payoffs,
            ids,
            rankings,
        }
    }

    /// Return the Pareto front: strategies that are not dominated.
    ///
    /// A strategy dominates another if it has *higher payoff* and *lower complexity*.
    /// Returns `(id, avg_payoff, complexity)` for each Pareto-optimal strategy.
    pub fn pareto_front(&self, complexities: &[f32]) -> Vec<(u64, f64, f32)> {
        let n = self.ids.len();
        debug_assert_eq!(complexities.len(), n);

        // Reuse the precomputed avg payoff from `self.rankings` (built once at
        // `WinMatrix::new` construction). The prior form recomputed
        // `self.payoffs[i].iter().sum() / (n-1)` per i -- duplicating the
        // row-sum work `WinMatrix::new` already did.
        //
        // `rankings` carries `(id, avg_payoff)` pairs in payoff-descending
        // order. Build a small id → avg_payoff lookup so the per-strategy
        // tuple construction below stays O(1) per id. For the typical
        // ruliology n (tens to low-thousands), a flat Vec parallel to
        // `self.ids` (no HashMap allocation) is the right shape: the join
        // is one O(n) pass matching `self.ids[i]` against `rankings[i].0`
        // -- but `rankings` is shuffled by sort, so we still need the
        // per-id lookup. Cheapest correct shape: a one-shot HashMap build.
        use std::collections::HashMap;
        let mut avg_by_id: HashMap<u64, f64> = HashMap::with_capacity(n);
        for &(id, payoff) in &self.rankings {
            avg_by_id.insert(id, payoff);
        }

        // Build (idx, id, avg_payoff, complexity).
        let id_to_idx: Vec<(usize, u64, f64, f32)> = self
            .ids
            .iter()
            .enumerate()
            .map(|(i, &id)| {
                let avg = avg_by_id.get(&id).copied().unwrap_or(0.0);
                (i, id, avg, complexities[i])
            })
            .collect();

        let mut front: Vec<(u64, f64, f32)> = Vec::with_capacity(n);

        // Pareto dominance: strategy i is dominated if some j has strictly
        // higher payoff AND strictly lower complexity. O(n²) — acceptable for
        // the small strategy counts ruliology enumerates.
        //
        // Note: `id` is destructured directly here; the prior code dropped `id`
        // from the pattern and then did an O(n) `.find()` to recover it by
        // matching on complexity equality — which was both slower (O(n³) total)
        // and incorrect when two strategies shared the same complexity value
        // (the find returned the first match, not necessarily the current i).
        for &(_i, id, payoff_i, cx_i) in &id_to_idx {
            let dominated = id_to_idx
                .iter()
                .any(|&(_, _, payoff_j, cx_j)| payoff_j > payoff_i && cx_j < cx_i);
            if !dominated {
                front.push((id, payoff_i, cx_i));
            }
        }

        // Sort descending by payoff.
        front.sort_by(|a, b| b.1.total_cmp(&a.1));
        front
    }

    /// Average payoff for strategy at index `i`.
    #[inline]
    pub fn avg_payoff(&self, i: usize) -> f64 {
        let n = self.payoffs[i].len();
        if n == 0 {
            return 0.0;
        }
        self.payoffs[i].iter().sum::<f64>() / n as f64
    }
}

impl RuliologyPruner {
    /// Create a new pruner with given thresholds.
    #[inline]
    pub fn new(payoff_threshold: f64, complexity_threshold: f32) -> Self {
        Self {
            payoff_threshold,
            complexity_threshold,
        }
    }

    /// Filter rankings to strategies meeting both thresholds.
    ///
    /// Returns indices into the original strategy list.
    pub fn filter(&self, matrix: &WinMatrix, complexities: &[f32]) -> Vec<usize> {
        let mut result = Vec::new();
        for (i, &id) in matrix.ids.iter().enumerate() {
            let avg = matrix.avg_payoff(i);
            if avg >= self.payoff_threshold && complexities[i] <= self.complexity_threshold {
                // Also verify this strategy is on the Pareto front.
                result.push(i);
            }
            let _ = id; // suppress unused warning
        }
        result
    }
}

impl SenseLodLevel {
    /// Returns the set of active sense modules for this LOD level.
    pub fn module_mask(self) -> &'static [SenseKind] {
        use SenseKind::*;
        match self {
            Self::Full => &[
                CommonSense,
                FighterSense,
                GameTheorySense,
                SpatialSense,
                SocialSense,
                SkillSense,
            ],
            Self::Compressed => &[CommonSense, FighterSense, SpatialSense],
            Self::Minimal => &[SpatialSense],
        }
    }
}

impl SenseLodRouter {
    pub fn new(_boundaries: &[ScaleBoundary], sigma1: f32, sigma2: f32) -> Self {
        Self { sigma1, sigma2 }
    }

    pub fn route(&self, distance: f32) -> SenseLodLevel {
        match distance {
            d if d <= self.sigma1 => SenseLodLevel::Full,
            d if d <= self.sigma2 => SenseLodLevel::Compressed,
            _ => SenseLodLevel::Minimal,
        }
    }

    pub fn from_boundaries(boundaries: &[ScaleBoundary]) -> Option<Self> {
        if boundaries.len() < 2 {
            return None;
        }
        Some(Self {
            sigma1: boundaries[0].sigma,
            sigma2: boundaries[1].sigma,
        })
    }

    pub fn assign_lods(&self, distances: &[f32]) -> Vec<SenseLodLevel> {
        distances.iter().map(|&d| self.route(d)).collect()
    }

    /// Zero-alloc variant: writes LOD levels into a pre-allocated output buffer.
    ///
    /// `out` must have the same length as `distances`. Panics if lengths differ.
    pub fn assign_lods_into(&self, distances: &[f32], out: &mut [SenseLodLevel]) {
        assert_eq!(
            distances.len(),
            out.len(),
            "assign_lods_into: length mismatch"
        );
        for (out_val, &d) in out.iter_mut().zip(distances.iter()) {
            *out_val = self.route(d);
        }
    }
}

impl SenseLodMask {
    /// Pre-computed masks — one per LOD level, built once.
