impl SenseOctreeBuilder {
    pub fn new(max_depth: u8) -> Self {
        Self {
            max_depth: max_depth.min(3),
        }
    }

    /// Build a SenseModule from KG embeddings.
    ///
    /// Module confidence = mean of embedding confidences (KG weight bridge).
    /// Falls back to 0.5 when embeddings exist but have no confidence signal.
    pub fn build(&self, kind: SenseKind, embeddings: &[KgEmbedding]) -> SenseModule {
        let module_confidence = if embeddings.is_empty() {
            0.0
        } else {
            let mean: f32 =
                embeddings.iter().map(|e| e.confidence).sum::<f32>() / embeddings.len() as f32;
            if mean <= 0.0 { 0.5 } else { mean }
        };

        let mut module = SenseModule {
            kind,
            version: 1,
            octree_depth: self.max_depth,
            n_directions: 0,
            _reserved: 0,
            octree_bits: [0; 4],
            directions: [TernaryDir::zero(); 8],
            confidence: module_confidence,
            commitment: [0u8; 32],
        };

        if embeddings.is_empty() {
            module.commit();
            return module;
        }

        // Build octree occupancy from embeddings
        for emb in embeddings {
            self.insert_embedding(&mut module.octree_bits, &emb.embedding, emb.sign);
        }

        // Extract direction vectors from embeddings
        let n_dirs = embeddings.len().min(8);
        module.n_directions = n_dirs as u8;
        for (i, emb) in embeddings.iter().take(n_dirs).enumerate() {
            module.directions[i] = Self::embedding_to_ternary(&emb.embedding);
        }

        module.commit();
        module
    }

    fn insert_embedding(&self, bits: &mut [u64; 4], embedding: &[f32; 8], _sign: bool) {
        // dim 0..7 → word=0, bit=dim (8 dims fit in one u64)
        for (dim, &val) in embedding.iter().enumerate() {
            let mask = 1u64 << dim;
            // Branchless: set bit when |val| > 0.1
            bits[0] |= mask & ((val.abs() > 0.1) as u64).wrapping_neg();
        }
    }

    /// Build a SenseModule seeded from schema class centroids.
    ///
    /// Uses centroid-based embedding initialization (Plan 237) instead of
    /// raw embeddings. The centroid is quantized to ternary direction vectors.
    /// Falls back to random directions if no centroid is available.
    #[cfg(feature = "schema_centroid")]
    pub fn build_from_centroid(
        &self,
        kind: SenseKind,
        class_hashes: &[u64],
        cache: &super::schema_centroid::SchemaCentroidCache,
        rng: &mut fastrand::Rng,
    ) -> SenseModule {
        use super::schema_centroid::schema_init_entity;

        let embedding = schema_init_entity(class_hashes, cache, 0.3, rng);
        let module_confidence = 0.5; // Default for centroid-seeded modules

        let mut module = SenseModule {
            kind,
            version: 1,
            octree_depth: self.max_depth,
            n_directions: 1,
            _reserved: 0,
            octree_bits: [0; 4],
            directions: [TernaryDir::zero(); 8],
            confidence: module_confidence,
            commitment: [0u8; 32],
        };

        // Use centroid-derived embedding as the primary direction
        module.directions[0] = Self::embedding_to_ternary(&embedding);

        // Mark occupancy from the centroid embedding
        self.insert_embedding(&mut module.octree_bits, &embedding, true);

        module.commit();
        module
    }

    fn embedding_to_ternary(embedding: &[f32; 8]) -> TernaryDir {
        let mut pos_bits = 0u64;
        let mut neg_bits = 0u64;
        let mut scale_sum = 0.0f32;

        // Branchless: use bool-as-u64 to conditionally apply masks.
        // `is_pos | is_neg` is 0 (both false) or 1 (either true); the cast
        // chain `(u64) as u8 as f32` is preserved bit-for-bit but goes
        // through u8 unnecessarily — `(is_pos | is_neg) as f32` is the same
        // value (0.0 or 1.0) and skips the narrowing step.
        for (i, &val) in embedding.iter().enumerate() {
            let mask = 1u64 << i;
            let is_pos = (val > 0.01) as u64;
            let is_neg = (val < -0.01) as u64;
            pos_bits |= mask & is_pos.wrapping_neg();
            neg_bits |= mask & is_neg.wrapping_neg();
            scale_sum += val.abs() * (is_pos | is_neg) as f32;
        }

        let row_scale = if scale_sum > 0.0 {
            scale_sum / (pos_bits.count_ones() + neg_bits.count_ones()).max(1) as f32
        } else {
            0.0
        };

        TernaryDir {
            pos_bits,
            neg_bits,
            row_scale,
        }
    }

    /// Build a SenseModule with Merkle octree commitment.
    ///
    /// Replaces the flat BLAKE3 commitment with a hierarchical Merkle root.
    /// Each KG embedding is hashed into a leaf, then the full depth-3 Merkle
    /// tree is built bottom-up. The root hash replaces `commitment`.
    ///
    /// GOAT target: overhead < 2µs on top of existing `build()`.
    #[cfg(feature = "merkle_octree")]
    pub fn build_with_merkle(
        &self,
        kind: SenseKind,
        embeddings: &[KgEmbedding],
    ) -> (SenseModule, katgpt_types::MerkleOctree) {
        let mut module = self.build(kind, embeddings);
        let tree = Self::build_merkle_only(embeddings);

        // Replace flat BLAKE3 commitment with Merkle root
        module.commitment = *tree.root();

        (module, tree)
    }

    /// Build only the Merkle octree from KG embeddings (no SenseModule).
    ///
    /// Each embedding is serialized to bytes and BLAKE3-hashed as a leaf.
    /// Leaves beyond 64 are ignored. Unused leaves get zero hashes.
    ///
    /// Leaf data layout per embedding: entity_hash(8) || relation_hash(8) || embedding(32) || confidence(4) || sign(1) = 53 bytes.
    #[cfg(feature = "merkle_octree")]
    pub fn build_merkle_only(embeddings: &[KgEmbedding]) -> katgpt_types::MerkleOctree {
        use katgpt_types::merkle::{HASH_SIZE, MERKLE_OCTREE_LEAVES};

        let mut leaf_hashes = [[0u8; HASH_SIZE]; MERKLE_OCTREE_LEAVES];
        let mut scratch = [0u8; 53]; // entity_hash(8) + relation_hash(8) + embedding(32) + confidence(4) + sign(1)

        for (i, emb) in embeddings.iter().enumerate() {
            if i >= MERKLE_OCTREE_LEAVES {
                break;
            }
            scratch[0..8].copy_from_slice(&emb.entity_hash.to_le_bytes());
            scratch[8..16].copy_from_slice(&emb.relation_hash.to_le_bytes());
            // embedding: 8 x f32 = 32 bytes
            for (j, val) in emb.embedding.iter().enumerate() {
                scratch[16 + j * 4..20 + j * 4].copy_from_slice(&val.to_le_bytes());
            }
            scratch[48..52].copy_from_slice(&emb.confidence.to_le_bytes());
            scratch[52] = emb.sign as u8;
            leaf_hashes[i] = *blake3::hash(&scratch).as_bytes();
        }

        katgpt_types::MerkleOctree::build_from_leaves(&leaf_hashes)
    }
}

impl OctreeNodeId {
    /// Root node ID.
    pub const ROOT: Self = Self(0);

    /// Child index (0..8) at given depth.
    #[inline]
    pub fn child(&self, child_idx: u8) -> Self {
        // Octree: node n at depth d has children at indices 8*n+1 .. 8*n+8
        Self(self.0 * 8 + 1 + child_idx as u32)
    }

    /// Depth in the octree.
    #[inline]
    pub fn depth(&self) -> u8 {
        if self.0 == 0 {
            return 0;
        }
        // For octree: node 0=depth 0, nodes 1-8=depth 1, nodes 9-72=depth 2, etc.
        // Depth d has 8^d nodes. Cumulative nodes through depth d = (8^(d+1) - 1) / 7.
        // Node n has depth = floor(log_8(n * 7 + 1)) via leading zeros.
        let v = self.0.wrapping_mul(7).wrapping_add(1);
        // ilog gives floor(log_8(v)) via log2(v)/3
        let log2 = 32 - v.leading_zeros() - 1; // floor(log2(v))
        log2 as u8 / 3
    }

    /// Parent node ID, or None for root.
    #[inline]
    pub fn parent(&self) -> Option<Self> {
        if self.0 == 0 {
            None
        } else {
            Some(Self((self.0 - 1) / 8))
        }
    }
}

impl ReconstructionConfig {
    /// Adaptively reduce `max_steps` based on measured cycle latency.
    ///
    /// If the last cycle took > `LATENCY_BUDGET_NS`, reduces `max_steps` by 1
    /// (minimum 1). This prevents reconstruction from blowing the game tick budget.
    /// Returns a new config with the adjusted `max_steps`.
    ///
    /// Call this after each reconstruction cycle with the measured latency.
    #[inline]
    pub fn with_adaptive_budget(&self, last_cycle_ns: u64) -> Self {
        if last_cycle_ns <= LATENCY_BUDGET_NS {
            return *self;
        }
        let reduced = self.max_steps.saturating_sub(1).max(1);
        Self {
            max_steps: reduced,
            ..*self
        }
    }

    /// Check if SIMD path is beneficial for the current workload.
    ///
    /// SIMD overhead exceeds scalar for small arrays (< 16 elements).
    /// Our belief is 8-dim with 6 modules = 48-element matvec — borderline.
    /// Returns `true` if SIMD level is available and the workload justifies it.
    #[inline]
    pub fn simd_beneficial(&self) -> bool {
        let level = katgpt_types::simd::simd_level();
        // SIMD is beneficial when:
        // - NEON or AVX2 is available
        // - max_steps >= 3 (amortizes setup cost over multiple steps)
        !matches!(level, katgpt_types::simd::SimdLevel::Scalar) && self.max_steps >= 3
    }
}

impl TripleEvidence {
    /// Mean confidence of recovered evidence.
    #[inline]
    pub fn mean_confidence(&self) -> f32 {
        if self.count == 0 {
            return 0.0;
        }
        self.confidence_sum / self.count as f32
    }

    /// Entropy of kind activations — low entropy means focused evidence.
    /// Uses fast approximation: 1.0 - max_activation (0 = focused, 1 = uniform).
    #[inline]
    pub fn activation_entropy(&self) -> f32 {
        // Single pass: compute sum + max simultaneously
        let mut total = 0.0f32;
        let mut max_val = 0.0f32;
        for &v in &self.kind_activations {
            total += v;
            max_val = max_val.max(v);
        }
        if total < 1e-8 {
            return 1.0;
        }
        1.0 - max_val / total
    }

    /// Merge evidence from another source.
    #[inline]
    pub fn merge(&mut self, other: &Self) {
        self.count = self.count.saturating_add(other.count);
        self.confidence_sum += other.confidence_sum;
        // Direct indexing for fixed-size array — LLVM unrolls fully.
        for i in 0..6 {
            self.kind_activations[i] += other.kind_activations[i];
        }
    }

    /// Map belief dimension index (0..8) → source SenseKind index (0..6).
    ///
    /// The belief is 8-dimensional but only 6 SenseKinds feed it, so dims 6 and 7
    /// reuse kinds 0 and 1. This is the **single source of truth** for that
    /// gather — used by both [`ReconstructionState::evolve_belief`] and
    /// [`ReconstructionState::evolve_belief_simd`] via `kind_activations_padded`.
    ///
    /// (Plan 276 T2.1 — do NOT duplicate this constant elsewhere.)
    pub const KIND_MAP: [usize; 8] = [0, 1, 2, 3, 4, 5, 0, 1];

    /// Gather the 6 per-kind activations into the 8-element belief input vector.
    ///
    /// Returns `[k0,k1,k2,k3,k4,k5,k0,k1]` — the activations laid out per
    /// [`KIND_MAP`](Self::KIND_MAP). This is the `input` passed to the shared
    /// leaky-integrator core ([`katgpt_types::leaky_core::leaky_step`]).
    ///
    /// NOTE: the normalization `total` is NOT `Σ padded` — it is `Σ padded[..6]`
    /// (the 6 distinct source activations). See `evolve_belief` and the
    /// `leaky_core` module docs for why `total` is supplied separately.
    #[inline]
    pub fn kind_activations_padded(&self) -> [f32; 8] {
        let k = &self.kind_activations;
        // Direct indexing over a const LUT — fully unrolled, zero allocation.
        let m = Self::KIND_MAP;
        [
            k[m[0]], k[m[1]], k[m[2]], k[m[3]], k[m[4]], k[m[5]], k[m[6]], k[m[7]],
        ]
    }
}

impl ProjectionWeights {
    /// Pre-compute projection weights from brain modules.
    ///
    /// Extracts ternary signs and row scales into a contiguous `[f32; 48]` matrix
    /// suitable for `simd_matmul_rows`. Zero-cost per reconstruction step — compute
    /// once, use across all 3 steps.
    /// Issue 007 Phase C: renamed from from_brain.
    #[inline]
    pub fn from_modules(modules: &[SenseModule]) -> Self {
        let mut matrix = [0.0f32; 48];
        let mut confidence = [0.0f32; 6];

        for module in modules {
            let kind_idx = module.kind as usize;
            if kind_idx >= 6 {
                continue;
            }
            confidence[kind_idx] = module.confidence;

            let n = module.n_directions as usize;
            let row_off = kind_idx * 8;
            for i in 0..n {
                let dir = &module.directions[i];
                // Bit masked to 0/1 — `as u32` is redundant.
                let pos = ((dir.pos_bits >> i) & 1) as f32;
                let neg = ((dir.neg_bits >> i) & 1) as f32;
                matrix[row_off + i] = (pos - neg) * dir.row_scale;
            }
        }

        Self { matrix, confidence }
    }
}

impl BatchProjectionWeights {
    /// Create batch weights for N entities sharing the same brain.
    #[inline]
    pub fn new(modules: &[SenseModule], n_entities: usize) -> Self {
        Self {
            weights: ProjectionWeights::from_modules(modules),
            n_entities,
        }
    }

    /// Batch expand: project N belief states against shared weights.
    ///
    /// `belief_batch`: `[N × 8]` row-major (entity 0's belief, then entity 1's, etc.)
    /// `activations_out`: `[N × 6]` row-major output
    ///
    /// For each entity, computes `[6×8] × [8] → [6]` raw dots, then sigmoid + confidence.
    /// SIMD amortizes across all N × 6 = 6N dot products (each 8 elements).
    ///
    /// Wins when N ≥ 4: 24+ dot × 8 f32 = 192+ ops, NEON setup amortized.
    #[cfg(feature = "sense_composition")]
    pub fn expand_batch(
        &self,
        belief_batch: &[f32],           // [N × 8]
        activations_out: &mut [f32], // [N × 6]
    ) {
        let n = self.n_entities;
        debug_assert!(belief_batch.len() >= n * 8, "belief_batch too small");
        debug_assert!(activations_out.len() >= n * 6, "activations_out too small");

        for e in 0..n {
            let belief_off = e * 8;
            let act_off = e * 6;

            // One matvec: [6×8] × [8] → [6] raw dots
            let mut dots = [0.0f32; 6];
            katgpt_types::simd::simd_matmul_rows(
                &mut dots,
                &self.weights.matrix,
                &belief_batch[belief_off..belief_off + 8],
                6,
                8,
            );

            // Sigmoid + confidence. Uses katgpt_types::simd::fast_sigmoid for numerical
            // equivalence with scalar `SenseModule::project` (the rational
            // approximation overshoots (0,1) for |x| > 2.67 — see simd.rs docs).
            // NOTE: `simd_sigmoid_inplace` was benchmarked and rejected for the
            // 6-element expand path — see `expand_with_weights` for details.
            for m in 0..6 {
                activations_out[act_off + m] =
                    self.weights.confidence[m] * katgpt_types::simd::fast_sigmoid(dots[m]);
            }
        }
    }
}

use super::ReconstructionState;

/// Per-tick stimulus schedule for [`ReconstructionState::audit_depth_invariance`].
///
/// The leaky integrator inside `evolve_belief` consumes `evidence.kind_activations`
/// (the 6 distinct SenseKind activation strengths) as its input. The audit
/// overwrites that field each tick with the schedule's value — exercising the
/// actual leaky path faithfully (no shortcut).
///
/// `#[repr(u8)]` per AGENTS.md (field-less enum).
#[derive(Clone, Copy, Debug)]
#[repr(u8)]
pub enum AuditStimulus {
    /// Apply the same 6-kind activations every tick. Useful for probing the
    /// fixed-point / saturation behaviour under a sustained stimulus.
    Constant {
        /// Per-SenseKind activation strength, indexed by SenseKind discriminant.
        activations: [f32; 6],
    } = 0,
    /// Alternate between `positive` (even ticks) and `negative` (odd ticks)
    /// activations every tick. Plan 331 Phase 1 T1.2 canonical stimulus —
    /// exercises the leaky integrator in both directions to surface any
    /// unbounded accumulation under sign-flipping drive.
    AlternatingSign {
        /// Activations applied on even ticks (t = 0, 2, 4, …).
        positive: [f32; 6],
        /// Activations applied on odd ticks (t = 1, 3, 5, …).
        negative: [f32; 6],
    } = 1,
}

impl ReconstructionState {
    /// Audit `evolve_belief` for the attention-drift failure mode (Plan 331 T1.2).
    ///
    /// Runs `evolve_belief` for `k` ticks under the supplied `stimulus` schedule,
    /// capturing the belief chain (`h_0 … h_k`, each `[f32; 8]`) into the
    /// caller-owned `states_out` buffer, then classifies the chain via
    /// [`katgpt_types::classify_chain`].
    ///
    /// **Stimulus mechanism:** each tick, `evidence.kind_activations` is
    /// overwritten with the schedule's per-tick value (not accumulated — the
    /// audit controls the drive signal exactly). This exercises the actual
    /// leaky-integrator path inside `evolve_belief`, not a shortcut.
    ///
    /// **Zero allocation in the hot path** (per AGENTS.md): `states_out` and
    /// `scratch` are caller-owned. The method `clear()`s `states_out` on entry
    /// and writes `(k+1)*8` f32s into it. Pre-size with
    /// `states_out.reserve_exact((k+1)*8)` once for truly zero alloc across
    /// repeated calls.
    ///
    /// - `k`: number of ticks to evolve (chain length is `k+1`).
    /// - `stimulus`: per-tick drive schedule (see [`AuditStimulus`]).
    /// - `cfg`: classifier thresholds (see [`katgpt_types::DepthInvarianceConfig`]).
    /// - `scratch`: classifier scratch (cleared + filled; not read).
    /// - `states_out`: receives the flattened `[k+1][8]` belief chain (caller-owned).
    ///
    /// Returns the diagnostic. The chain in `states_out` is left populated so
    /// the caller can re-classify under alternative thresholds without re-running.
    pub fn audit_depth_invariance(
        &mut self,
        k: usize,
        stimulus: AuditStimulus,
        cfg: &katgpt_types::DepthInvarianceConfig,
        scratch: &mut katgpt_types::Scratch,
        states_out: &mut Vec<f32>,
    ) -> katgpt_types::DepthInvarianceDiagnostic {
        // ── Snapshot h_0 ──
        states_out.clear();
        // Pre-grow once to the exact final size. `reserve_exact` avoids any
        // over-allocation — `(k+1)*8` is the exact number of f32s we will write.
        // No-op if capacity already suffices. This is the only allocation; it is
        // amortized across calls — caller can pre-reserve to make it zero per call.
        states_out.reserve_exact((k + 1).saturating_mul(8));
        states_out.extend_from_slice(self.belief());

        // ── Drive the leaky integrator for k ticks ──
        for t in 0..k {
            // Overwrite the drive signal with the per-tick stimulus. This is
            // the only mutation to evidence — confidence_sum/count are left
            // untouched (they don't feed evolve_belief's math; only
            // kind_activations does).
            let activations = match stimulus {
                AuditStimulus::Constant { activations } => activations,
                AuditStimulus::AlternatingSign { positive, negative } => {
                    if t % 2 == 0 {
                        positive
                    } else {
                        negative
                    }
                }
            };
            self.set_kind_activations(activations);

            self.evolve_belief();
            states_out.extend_from_slice(self.belief());
        }

        // ── Classify the captured chain ──
        katgpt_types::classify_chain(states_out, /*d=*/ 8, cfg, scratch)
    }

    /// Regularized variant of `evolve_belief` (Plan 331 T1.3).
    ///
    /// Runs the raw [`Self::evolve_belief`] update unchanged, then applies
    /// [`katgpt_types::MagnitudeRegularization`] in-place to the 8-dim belief state.
    /// This is the modelless Layer-1 magnitude-hygiene fix per Research 151 /
    /// arXiv:2605.09992 §4.4.
    ///
    /// The raw path is byte-identical to `evolve_belief()` (the existing
    /// `evolve_belief_is_byte_identical_to_inline_reference` test still guards it).
    /// This method is an *additional* sibling — callers opt in per Plan 331's
    /// `magnitude_hygiene` feature (wired on the riir-engine side in Phase 1).
    ///
    /// **Zero allocation:** uses the caller-provided `scratch` slice for the
    /// RMS computation (reserved for future learned γ/β extensions in Plan 306;
    /// unused by pure RmsNorm in Phase 1 but required for API stability).
    ///
    /// - `regularization`: mode ([`katgpt_types::MagnitudeRegularization::RmsNorm`] is
    ///   the paper's prescription; `ScalarPinch` is a gentler alternative when
    ///   `RmsNorm` proves too aggressive — see Plan 331 T1.6 fallback).
    /// - `scratch`: length-`d` caller-owned scratch (length 8 for belief).
    #[inline]
    pub fn evolve_belief_regularized(
        &mut self,
        regularization: katgpt_types::MagnitudeRegularization,
        scratch: &mut [f32],
    ) {
        // Raw leaky-integrator update — byte-identical to evolve_belief().
        self.evolve_belief();
        // Apply magnitude regularization in-place on the 8-dim latent state.
        katgpt_types::apply_magnitude_regularization(self.belief_mut(), regularization, scratch);
    }
}

use super::octree::KgEmbedding;

/// Pre-computed centroid statistics for a KG schema class.
///
/// Computed once per KG snapshot update, O(d·|E_c|) per class.
/// Stored in `SchemaCentroidCache` keyed by blake3 class hash.
#[derive(Clone, Copy, Debug)]
pub struct CentroidStats {
    /// Mean embedding of all entities in this class: v_c = (1/|E_c|) Σ e_i
    pub mean: [f32; 8],
    /// Per-dimension standard deviation: `σ_c[d] = sqrt(Var(e[d]))`
    pub std_dev: [f32; 8],
    /// Number of entities used to compute this centroid
    pub count: usize,
}

impl SchemaCentroidCache {
    /// Create an empty centroid cache.
    pub fn new() -> Self {
        Self {
            centroids: papaya::HashMap::new(),
        }
    }

    /// Look up pre-computed centroid for a class hash.
    ///
    /// Returns a cloned `CentroidStats` (72 bytes, cheap to clone).
    pub fn get(&self, class_hash: u64) -> Option<CentroidStats> {
        self.centroids.pin().get(&class_hash).cloned()
    }

    /// Insert or update centroid stats for a class hash.
    pub fn insert(&self, class_hash: u64, stats: CentroidStats) {
        self.centroids.pin().insert(class_hash, stats);
    }

    /// Number of cached classes.
    pub fn len(&self) -> usize {
        self.centroids.pin().len()
    }

    /// Whether the cache is empty.
    pub fn is_empty(&self) -> bool {
        self.centroids.pin().is_empty()
    }

    /// Clear all cached centroids.
    pub fn clear(&self) {
        self.centroids.pin().clear();
    }

    /// Compute centroid from embeddings and insert into cache.
    ///
    /// Returns `true` if computation succeeded (non-empty embeddings),
    /// `false` if `embeddings` was empty and nothing was inserted.
    pub fn compute_and_insert(&self, class_hash: u64, embeddings: &[KgEmbedding]) -> bool {
        match compute_centroid(embeddings) {
            Some(stats) => {
                self.insert(class_hash, stats);
                true
            }
            None => false,
        }
    }
}

const VERSION: u8 = 1;

/// Save a SenseModule to a writer.
pub fn save_module(module: &SenseModule, mut w: impl Write) -> io::Result<()> {
    w.write_all(MAGIC)?;
    w.write_all(&[VERSION])?;
    w.write_all(&[module.kind as u8])?;
    // Stack buffer to zero padding — avoids cloning the full SenseModule.
    let mut copy: std::mem::MaybeUninit<SenseModule> = std::mem::MaybeUninit::uninit();
    unsafe {
        std::ptr::copy_nonoverlapping(module, copy.as_mut_ptr(), 1);
        // SAFETY: copy is now a valid SenseModule. Zero padding in directions.
        let copy_ref = copy.assume_init_mut();
        for dir in &mut copy_ref.directions {
            dir.zero_padding();
        }
        let bytes: &[u8] = std::slice::from_raw_parts(
            copy_ref as *const SenseModule as *const u8,
            std::mem::size_of::<SenseModule>(),
        );
        w.write_all(bytes)?;
        // SenseModule has no Drop impl — MaybeUninit drops as unit, no cleanup needed.
    }
    Ok(())
}

