use crate::sparse_task_vector::SparseTaskVector;

// ---------------------------------------------------------------------------
// compose_intersect — mask intersection + eta superposition
// ---------------------------------------------------------------------------

/// Compose two sparse task vectors by **mask intersection**.
///
/// Returns a new `SparseTaskVector` whose mask is the sorted intersection of
/// `a.mask` and `b.mask`. At each surviving coordinate `i`, the delta is
/// `a.deltas[a_pos] + b.deltas[b_pos]` (additive superposition of the two
/// task signals). The output `eta` is the **mean** of the two input etas:
/// `(a.eta + b.eta) / 2`.
///
/// # Paper grounding
///
/// arXiv 2606.13657 §4.3: intersection preserves the coordinates both adapters
/// agree on, which carry the shared structural signal. Mean-eta is the paper's
/// conservative superposition — neither adapter dominates. On paper-density
/// masks this preserves ≥2.21× the random-baseline overlap (GOAT G10).
///
/// # Panics
///
/// Panics with a clear message if `a.shape != b.shape`.
pub fn compose_intersect(a: &SparseTaskVector, b: &SparseTaskVector) -> SparseTaskVector {
    assert_shapes_match(a, b, "compose_intersect");

    // Both masks are sorted ascending (SparseTaskVector invariant). Standard
    // merge-join finds the intersection in O(|a| + |b|).
    let cap = a.mask.len().min(b.mask.len());
    let mut mask = Vec::with_capacity(cap);
    let mut deltas = Vec::with_capacity(cap);

    let (mut i, mut j) = (0usize, 0usize);
    while i < a.mask.len() && j < b.mask.len() {
        let ai = a.mask[i];
        let bj = b.mask[j];
        if ai == bj {
            mask.push(ai);
            deltas.push(a.deltas[i] + b.deltas[j]);
            i += 1;
            j += 1;
        } else if ai < bj {
            i += 1;
        } else {
            j += 1;
        }
    }

    let eta = (a.eta + b.eta) * 0.5;
    // from_parts validates the (mask, deltas) pair — masks built by merge-join
    // of two sorted masks are themselves sorted ascending, so this always
    // succeeds unless there's a logic bug above. Unwrap is safe.
    SparseTaskVector::from_parts(a.shape, mask, deltas, eta)
        .expect("compose_intersect: merge-join produced invalid mask (internal bug)")
}

impl SparseTaskVector {
    /// Build a sparse task vector from a dense delta slice.
    ///
    /// Coordinates with `|delta[i]| <= threshold` are dropped. The resulting mask
    /// is sorted ascending. Use `threshold = 1e-5` to match the paper's main
    /// sparsity tables (§4.1, Table 2).
    ///
    /// `shape.0 * shape.1` must equal `dense.len()`.
    pub fn from_dense(dense: &[f32], shape: (usize, usize), threshold: f32) -> Self {
        debug_assert_eq!(
            shape.0 * shape.1,
            dense.len(),
            "shape {:?} doesn't match dense.len() {}",
            shape,
            dense.len()
        );
        let mut mask = Vec::with_capacity(dense.len() / 4);
        let mut deltas = Vec::with_capacity(dense.len() / 4);
        for (i, &v) in dense.iter().enumerate() {
            if v.abs() > threshold {
                mask.push(i as u32);
                deltas.push(v);
            }
        }
        // No shrink_to_fit: the dense.len()/4 heuristic is already tuned to
        // paper-reported densities (10.5%–33.3%), so capacity ≈ length on
        // average. shrink_to_fit would force a realloc + copy with no win.
        Self {
            shape,
            mask,
            deltas,
            eta: 1.0,
        }
    }

    /// Build from explicit parallel `mask` + `deltas` (must be same length, mask sorted).
    ///
    /// Use this when the mask has already been discovered (e.g., by riir-ai's
    /// subnetwork training pipeline, Research 120 Fusion 1).
    pub fn from_parts(
        shape: (usize, usize),
        mask: Vec<u32>,
        deltas: Vec<f32>,
        eta: f32,
    ) -> Result<Self, SparseTaskVectorError> {
        if mask.len() != deltas.len() {
            return Err(SparseTaskVectorError::LengthMismatch {
                mask: mask.len(),
                deltas: deltas.len(),
            });
        }
        if !mask.is_empty() {
            let total = shape.0 * shape.1;
            if mask[0] as usize >= total {
                return Err(SparseTaskVectorError::IndexOutOfRange {
                    idx: mask[0],
                    total,
                });
            }
            if *mask.last().unwrap() as usize >= total {
                return Err(SparseTaskVectorError::IndexOutOfRange {
                    idx: *mask.last().unwrap(),
                    total,
                });
            }
            if !mask.windows(2).all(|w| w[0] <= w[1]) {
                return Err(SparseTaskVectorError::UnsortedMask);
            }
        }
        Ok(Self {
            shape,
            mask,
            deltas,
            eta,
        })
    }

    /// Number of active coordinates (non-zero deltas).
    #[inline]
    pub fn len(&self) -> usize {
        self.mask.len()
    }

    /// Whether the task vector is empty (no active coordinates).
    #[inline]
    pub fn is_empty(&self) -> bool {
        self.mask.is_empty()
    }

    /// Total number of coordinates in the dense equivalent.
    #[inline]
    pub fn dense_len(&self) -> usize {
        self.shape.0 * self.shape.1
    }

    /// Active fraction in `[0, 1]`. Paper §4.1 reports `1 − density` ∈ [0.667, 0.895]
    /// for OPD pairs, i.e., densities of 10.5% to 33.3%.
    #[inline]
    pub fn density(&self) -> f32 {
        if self.dense_len() == 0 {
            return 0.0;
        }
        self.mask.len() as f32 / self.dense_len() as f32
    }

    /// Relative Frobenius norm of the delta vs the given base, `‖ΔW‖_F / ‖W_src‖_F`.
    ///
    /// Paper §4.1 reports this in the range 0.036% to 0.142% for OPD pairs. Call this
    /// after `from_dense` to verify the task vector is small in the paper's sense.
    pub fn relative_norm_vs(&self, base: &[f32]) -> f32 {
        debug_assert_eq!(base.len(), self.dense_len());
        let eta = self.eta;
        // Delta sum of squares — sparse, scalar is fine (nnz is small).
        let mut delta_sq_sum = 0.0_f32;
        for &d in &self.deltas {
            let s = d * eta;
            delta_sq_sum += s * s;
        }
        // Base sum of squares — dense, use SIMD.
        let base_sq_sum = katgpt_core::simd::simd_sum_sq(base, base.len());
        if base_sq_sum <= f32::MIN_POSITIVE {
            return 0.0;
        }
        delta_sq_sum.sqrt() / base_sq_sum.sqrt()
    }

    /// Storage bytes used by this sparse representation.
    ///
    /// `mask` is `u32` (4 bytes), `deltas` is `f32` (4 bytes). Total = `8 * len()`
    /// plus the `shape + eta` header (24 bytes).
    pub fn sparse_bytes(&self) -> usize {
        24 + 4 * self.mask.len() + 4 * self.deltas.len()
    }

    /// Storage bytes the dense equivalent would use (`4 * dense_len`).
    pub fn dense_bytes(&self) -> usize {
        4 * self.dense_len()
    }

    /// Storage reduction ratio `dense_bytes / sparse_bytes`. Paper-shaped masks
    /// at 17.5% density yield ~2.9×, at 10.5% density ~5.7×.
    pub fn storage_reduction(&self) -> f32 {
        let s = self.sparse_bytes();
        if s == 0 {
            return 1.0;
        }
        self.dense_bytes() as f32 / s as f32
    }

    /// Scatter-add `eta * deltas[i]` into `base[mask[i]]` for every active coordinate.
    ///
    /// **Correctness invariant:** after `apply_to`, `base[mask[i]] += eta * deltas[i]`
    /// for every `i`, and all other coordinates are unchanged. This is the task
    /// arithmetic "add" operation (Ilharco et al. 2022).
    ///
    /// **Hot-path safety:** zero allocation. Safe to call inside decode loops.
    pub fn apply_to(&self, base: &mut [f32]) {
        debug_assert_eq!(base.len(), self.dense_len());
        let eta = self.eta;
        for (&idx, &d) in self.mask.iter().zip(self.deltas.iter()) {
            base[idx as usize] += eta * d;
        }
    }

    /// Apply into a caller-owned scratch buffer (alias for `apply_to` since we don't
    /// allocate either way — kept as a separate name for API clarity at call sites
    /// that pass a scratch base distinct from the source-of-truth base).
    ///
    /// Use this when the caller maintains a separate scratch base for in-flight
    /// computation and wants to leave the canonical base untouched.
    #[inline]
    pub fn apply_to_scratch(&self, scratch_base: &mut [f32]) {
        self.apply_to(scratch_base);
    }

    /// Subtract the task vector from `base` (negate `eta`). Useful for "task negation"
    /// in task arithmetic — removing a capability.
    pub fn subtract_from(&self, base: &mut [f32]) {
        debug_assert_eq!(base.len(), self.dense_len());
        let eta = self.eta;
        for (&idx, &d) in self.mask.iter().zip(self.deltas.iter()) {
            base[idx as usize] -= eta * d;
        }
    }

    /// In-place scale `eta`. Useful for annealing a task vector's contribution.
    #[inline]
    pub fn scale_eta(&mut self, factor: f32) {
        self.eta *= factor;
    }

    /// Iterate over `(flat_index, delta_value)` pairs.
    pub fn iter(&self) -> impl Iterator<Item = (u32, f32)> + '_ {
        self.mask
            .iter()
            .copied()
            .zip(self.deltas.iter().map(|&d| d * self.eta))
    }

    /// Reconstruct the dense delta into a caller-provided buffer (zeroed first).
    ///
    /// Mostly for diagnostics and GOAT proofs. The hot path should use `apply_to`.
    pub fn to_dense_into(&self, out: &mut [f32]) {
        debug_assert_eq!(out.len(), self.dense_len());
        out.fill(0.0);
        self.apply_to(out);
    }
}

impl JacobianSupportEstimator {
    /// Estimate the Jacobian image support as a sorted `Vec<u32>` of
    /// coordinate indices into the `d_hidden`-dimensional hidden state.
    ///
    /// - `hidden`: `d_hidden * n_samples` flattened hidden states (n_samples rows).
    /// - `task_emb`: `d_task`-long task embedding (the projection direction `g`).
    /// - `d_hidden`: hidden dimensionality (must divide `hidden.len()`).
    /// - `config`: epsilon + threshold.
    ///
    /// Returns at most `d_hidden` coordinates (paper Prop 2 cap).
    pub fn estimate(
        hidden: &[f32],
        task_emb: &[f32],
        d_hidden: usize,
        config: JacobianSupportConfig,
    ) -> Vec<u32> {
        let mut out = Vec::with_capacity(d_hidden);
        let mut mag = Vec::with_capacity(d_hidden);
        Self::estimate_into(hidden, task_emb, d_hidden, config, &mut out, &mut mag);
        out
    }

    /// Zero-alloc variant: writes the support into `out` (cleared first).
    /// `out` should be pre-allocated with capacity `d_hidden` for efficiency.
    ///
    /// `mag_scratch` is a caller-owned reusable buffer for per-coordinate
    /// magnitudes; it is cleared and resized to `d_hidden` on each call. Pass
    /// it in to avoid the per-call `vec![0.0; d_hidden]` allocation on the
    /// hot path.
    pub fn estimate_into(
        hidden: &[f32],
        task_emb: &[f32],
        d_hidden: usize,
        config: JacobianSupportConfig,
        out: &mut Vec<u32>,
        mag_scratch: &mut Vec<f32>,
    ) {
        out.clear();
        if d_hidden == 0 || hidden.is_empty() || task_emb.is_empty() {
            return;
        }
        debug_assert_eq!(
            hidden.len() % d_hidden,
            0,
            "hidden.len() {} must be a multiple of d_hidden {}",
            hidden.len(),
            d_hidden
        );
        let n_samples = hidden.len() / d_hidden;
        // Per-coordinate accumulated |Jv| magnitude (averaged over samples).
        // Reuse caller-owned scratch to keep this path allocation-free.
        mag_scratch.clear();
        mag_scratch.resize(d_hidden, 0.0_f32);
        let mag: &mut [f32] = mag_scratch;

        // Finite-difference Jv per sample.
        // f(h) = h projected onto task_emb via dot product (modelless readout).
        // Jv[i] = ∂/∂h_i [f(h)] = task_emb[i] if i < d_task, else 0.
        // To approximate the Jacobian *image* (not the linear map itself),
        // we perturb each coordinate and observe how the readout shifts.
        // For multi-sample inputs, we accumulate the perturbation response.
        let eps = config.eps;
        let two_eps = 2.0 * eps;
        for s in 0..n_samples {
            let row = &hidden[s * d_hidden..(s + 1) * d_hidden];
            // f(h) baseline (dot product with task_emb, truncated).
            let base = dot_truncated(row, task_emb);
            // Split the coordinate loop at `min(d_hidden, task_emb.len())` so
            // the bulk pass is a bounds-check-free, branch-free 3-way zip
            // (the old `task_emb.get(i)` did a length check + select per
            // coordinate). Arithmetic per coordinate is unchanged.
            let n_t = d_hidden.min(task_emb.len());
            for ((m, &h_i), &t_i) in mag[..n_t]
                .iter_mut()
                .zip(row[..n_t].iter())
                .zip(task_emb[..n_t].iter())
            {
                // Central finite difference on coordinate i.
                let hp = h_i + eps;
                let hm = h_i - eps;
                // Re-evaluate the readout with coordinate i perturbed.
                // We use a single-coordinate linear readout (the diagonal of
                // the Jacobian): this is the modelless approximation.
                let fp = base + (hp - h_i) * t_i;
                let fm = base + (hm - h_i) * t_i;
                let jv_i = (fp - fm) / two_eps;
                *m += jv_i.abs();
            }
            // Tail: coordinates past the end of `task_emb` behave as t_i = 0.
            for (m, &h_i) in mag[n_t..d_hidden].iter_mut().zip(row[n_t..].iter()) {
                let hp = h_i + eps;
                let hm = h_i - eps;
                let fp = base + (hp - h_i) * 0.0;
                let fm = base + (hm - h_i) * 0.0;
                let jv_i = (fp - fm) / two_eps;
                *m += jv_i.abs();
            }
        }
        // Average and threshold.
        let inv_n = if n_samples > 0 {
            1.0 / n_samples as f32
        } else {
            0.0
        };
        for (i, &m) in mag.iter().enumerate() {
            let avg = m * inv_n;
            if avg > config.threshold {
                out.push(i as u32);
            }
        }
        // Cap at d_hidden (paper Prop 2). Already guaranteed by construction,
        // but enforce defensively.
        out.sort_unstable();
        out.truncate(d_hidden);
    }
}

impl SpecialistMask {
    /// Build a SpecialistMask from per-sample supports.
    ///
    /// - `support`: `n_rows` supports, each a `Vec<u32>` of kept coords.
    /// - `shape`: `(n_rows, d_hidden)`.
    ///
    /// The internal `SparseTaskVector` stores the **union** of all supports
    /// as a single flat mask of length `n_rows * d_hidden`, with `1.0`
    /// deltas on kept coordinates. This matches the paper's
    /// `M_sparse ∈ {0,1}^{n_rows × d_hidden}`.
    pub fn from_support(support: &[Vec<u32>], shape: (usize, usize)) -> Self {
        let (n_rows, d_hidden) = shape;
        debug_assert_eq!(
            support.len(),
            n_rows,
            "support.len() {} must equal n_rows {}",
            support.len(),
            n_rows
        );
        let mut mask = Vec::with_capacity(n_rows * d_hidden);
        let mut deltas = Vec::with_capacity(n_rows * d_hidden);
        for (row, sup) in support.iter().enumerate() {
            for &coord in sup {
                let flat = row * d_hidden + coord as usize;
                mask.push(flat as u32);
                deltas.push(1.0);
            }
        }
        // SparseTaskVector::from_parts validates sorted + in-range; the union
        // construction above is row-major so already sorted within each row.
        let inner = SparseTaskVector::from_parts(shape, mask, deltas, 1.0)
            .expect("SpecialistMask union construction produced invalid SparseTaskVector");
        Self { inner }
    }

    /// Density of the mask: `|support| / (n_rows * d_hidden)`.
    pub fn density(&self) -> f32 {
        self.inner.density()
    }

    /// Number of kept coordinates.
    pub fn nnz(&self) -> usize {
        self.inner.len()
    }

    /// Hidden dimensionality.
    pub fn d_hidden(&self) -> usize {
        self.inner.shape.1
    }

    /// Number of rows.
    pub fn n_rows(&self) -> usize {
        self.inner.shape.0
    }

    /// In-place sparsity-bound projection: zero out every coordinate NOT in
    /// the support. Paper Theorem 2: `h_specialist = h · M_sparse`.
    ///
    /// - `hidden`: `n_rows * d_hidden` flattened hidden state (mutated).
    /// - `scratch`: caller-provided buffer. Currently unused — kept for API
    ///   stability and reserved for future SIMD gather/scatter. The current
    ///   implementation does gap-fills via `slice::fill` (auto-vectorized
    ///   memset), which beats a sentinel-bitmap sweep at every density.
    pub fn project(&self, hidden: &mut [f32], _scratch: &mut [f32]) {
        debug_assert_eq!(hidden.len(), self.inner.dense_len());
        // Strategy: walk the row-major sorted mask and zero the *gaps* between
        // consecutive kept coordinates via `slice::fill(0.0)`. Each fill is a
        // contiguous auto-vectorizable memset, so the per-row work is
        // `O(d_hidden)` memory writes but done in wide SIMD chunks — strictly
        // better than the prior `scratch`-bitmap sweep (which did a f32-fill
        // of `d_hidden`, a per-coord f32 store, and a per-coord f32 compare).
        //
        // mask is row-major flat sorted ascending, so per-row kept coords are
        // a contiguous run; we use a single advancing cursor across rows.
        let d_hidden = self.d_hidden();
        let mask = &self.inner.mask;
        let n_mask = mask.len();
        let mut idx = 0usize;
        for row in 0..self.n_rows() {
            let base = row * d_hidden;
            let row_end = base + d_hidden;
            // Advance idx past coords belonging to earlier rows.
            while idx < n_mask && (mask[idx] as usize) < base {
                idx += 1;
            }
            // Zero gaps between consecutive kept coords in this row.
            let mut prev = base;
            while idx < n_mask {
                let f = mask[idx] as usize;
                if f >= row_end {
                    break;
                }
                // Zero [prev, f) — kept coords in this row are strictly ascending.
                hidden[prev..f].fill(0.0);
                prev = f + 1;
                idx += 1;
            }
            // Zero the trailing gap [prev, row_end).
            hidden[prev..row_end].fill(0.0);
        }
    }

    /// Reference to the underlying sparse storage (for Plan 264 consumers).
    pub fn as_sparse_task_vector(&self) -> &SparseTaskVector {
        &self.inner
    }
}

