impl PassFail {
    fn new() -> Self {
        Self {
            passed: 0,
            failed: 0,
        }
    }
    fn pass(&mut self, msg: &str) {
        println!("  ✅ PASS: {msg}");
        self.passed += 1;
    }
    fn fail(&mut self, msg: &str) {
        println!("  ❌ FAIL: {msg}");
        self.failed += 1;
    }
    fn check(&mut self, cond: bool, msg: &str) {
        if cond {
            self.pass(msg);
        } else {
            self.fail(msg);
        }
    }
    fn summary(&self) {
        println!(
            "\n── Summary: {} passed, {} failed ──",
            self.passed, self.failed
        );
    }
}

