    // Two regimes, mirroring the paper's crossover story:
    //  - "slow decay": signal stays high (0.85→0.50 over 8 depths). Argmax
    //    is reliably correct at all depths → greedy should not hurt, may help
    //    by extending the chain deeper.
    //  - "fast decay": signal drops fast (0.70→0.07). Deep argmax is barely
    //    above decoys → the realistic regime where the crossover lives.
    let regimes: &[(&str, f32, f32, f32)] = &[
        ("slow-decay", 0.85, 0.05, 0.40),
        ("fast-decay", 0.70, 0.09, 0.05),
    ];

    let thresholds: &[Option<usize>] = &[None, Some(2), Some(4)];

    for &(name, base, slope, floor) in regimes {
        println!("║                                                                  ║");
        println!(
            "║  regime={name:12}  base={base:.2}  slope={slope:.2}  floor={floor:.2}  ({n_seeds} seeds)",
        );
        println!("║  ┌──────────────┬──────────────────┬──────────────────┬───────────┐");
        println!("║  │ threshold    │ mean accept len  │ mean tree depth  │ tree size │");
        println!("║  ├──────────────┼──────────────────┼──────────────────┼───────────┤");

        let mut best_accept = 0.0f64;
        let mut best_label = String::new();

        for &thresh in thresholds {
            let label = match thresh {
                None => "None".to_string(),
                Some(t) => format!("Some({t})"),
            };

            let mut sum_accept = 0usize;
            let mut sum_depth = 0.0f64;
            let mut sum_size = 0usize;

            for seed in 0..n_seeds as u32 {
                // Ground-truth sequence (target's greedy decode).
                let mut rs = seed.wrapping_mul(7919).wrapping_add(1);
                let gt: Vec<usize> = (0..config.draft_lookahead)
                    .map(|_| (xorshift32(&mut rs) as usize) % config.vocab_size)
                    .collect();

                let marginals = make_draft_marginals(
                    &gt,
                    config.vocab_size,
                    base,
                    slope,
                    floor,
                    n_decoys,
                    seed,
                );
                let mv: Vec<&[f32]> = marginals.iter().map(|s| s.as_slice()).collect();

                let tree = build_dd_tree_deep_argmax(&mv, &config, thresh);
                sum_accept += accepted_prefix_len(&tree, &gt);
                sum_depth += mean_depth(&tree);
                sum_size += tree.len();
            }

            let mean_accept = sum_accept as f64 / n_seeds as f64;
            let mean_d = sum_depth / n_seeds as f64;
            let mean_sz = sum_size as f64 / n_seeds as f64;

            if mean_accept > best_accept {
                best_accept = mean_accept;
                best_label = label.clone();
            }

            println!(
                "║  │ {label:10}   │ {mean_accept:14.3}   │ {mean_d:14.3}   │ {mean_sz:7.1}   │"
            );
        }
        println!("║  └──────────────┴──────────────────┴──────────────────┴───────────┘");
        println!("║  → best: {best_label:10}  (mean accept len = {best_accept:.3})",);
    }

    println!("║                                                                  ║");
    println!("╚══════════════════════════════════════════════════════════════════╝");
    println!();
    println!("VERDICT: No acceptance-length gain from deep_argmax_threshold on the");
    println!("DDTree best-first builder. The best-first heap scores nodes by cumulative");
    println!("log-prob, so the argmax token at each depth already dominates the pop");
    println!("order — the on-target chain extends as deep as budget allows regardless");
    println!("of whether siblings are also pushed. The threshold is a correct but");
    println!("redundant mechanism on this architecture.");
    println!();
    println!("The paper's §3.5 / Figure 6 argmax-vs-marginal crossover applies to tree");
    println!("builders that SAMPLE from the marginal (stochastic expansion), not to");
    println!("deterministic best-first expansion. A future sampling-based builder could");
    println!("benefit from the flag; the current best-first DDTree does not.");
    println!();
    println!("NOTE: This is a synthetic mechanism test. The argmax is always the");
    println!("ground-truth token (by construction), so this tests whether budget");
    println!("concentration alone extends the accepted prefix — a necessary (not");
    println!("sufficient) condition for the paper's claim under realistic draft noise.");
}

impl AcceptanceForecast {
    /// Sensible defaults: `a = 1.0`, `b = 0.0` (no entropy penalty until
    /// fitted), decay `0.1`. With these defaults the forecast always returns
    /// `1.0`, so callers that never fit behave as a no-op pass-through.
    #[inline]
    pub const fn new() -> Self {
        Self {
            a: 1.0,
            b: 0.0,
            ema_entropy: 0.0,
            ema_alpha: 1.0,
            alpha_decay: DEFAULT_ALPHA_DECAY,
        }
    }

    /// Custom intercept, slope, and decay.
    #[inline]
    pub const fn with_params(a: f32, b: f32, alpha_decay: f32) -> Self {
        Self {
            a,
            b,
            ema_entropy: 0.0,
            ema_alpha: a,
            alpha_decay,
        }
    }

    /// Fit `a, b` from warmup `(entropy, accept_rate)` samples via closed-form
    /// ordinary least squares on the model `α = a − b · H`.
    ///
    /// Internally fits `y = A + M·x` (standard OLS) and then sets `b = −M`
    /// so the public model reads `α = a − b · H`. Falls back to
    /// [`new()`](Self::new) on empty input, and to a slope-zero intercept
    /// (mean of `α` samples) on degenerate input (zero variance in `H`).
    ///
    /// O(n) — single folding pass over the samples.
    pub fn fit_from_warmup(samples: &[(f32, f32)]) -> Self {
        if samples.is_empty() {
            return Self::new();
        }
        let n = samples.len() as f32;
        // Fold: (Σx, Σy, Σxy, Σx²)
        let (sum_x, sum_y, sum_xy, sum_x2) = samples.iter().fold(
            (0.0f32, 0.0f32, 0.0f32, 0.0f32),
            |(sx, sy, sxy, sx2), &(x, y)| (sx + x, sy + y, sxy + x * y, sx2 + x * x),
        );
        let denom = n * sum_x2 - sum_x * sum_x;
        if denom.abs() < 1e-10 {
            // Degenerate: all entropies identical (e.g. warmup on a peaked
            // distribution). Slope is undefined; use the mean acceptance rate
            // as the intercept with zero slope.
            let mean_alpha = sum_y / n;
            return Self {
                a: mean_alpha.clamp(0.0, 1.0),
                b: 0.0,
                ema_entropy: 0.0,
                ema_alpha: mean_alpha.clamp(0.0, 1.0),
                alpha_decay: DEFAULT_ALPHA_DECAY,
            };
        }
        // Standard OLS slope for y = A + M·x.
        let m = (n * sum_xy - sum_x * sum_y) / denom;
        let a = (sum_y - m * sum_x) / n;
        // Our model: α = a − b · H  ⇒  b = −M.
        let b = -m;
        let clamped_a = a.clamp(0.0, 1.0);
        let b_nonneg = b.max(0.0); // entropy can only reduce acceptance
        Self {
            a: clamped_a,
            b: b_nonneg,
            ema_entropy: 0.0,
            ema_alpha: clamped_a,
            alpha_decay: DEFAULT_ALPHA_DECAY,
        }
    }

    /// Compute next-token entropy `H(p)` from `logits` in 2 zero-allocation
    /// iterator passes, update the EMA, and return the forecast acceptance
    /// rate `α = clamp(a − b · ema_entropy, 0, 1)`.
    ///
    /// # Zero-allocation proof
    ///
    /// Pass 1 scans `logits` to find the max (stability shift). Pass 2 fuses
    /// the normalizer `Z = Σ exp(xᵢ − x_max)` with the cross term
    /// `S₂ = Σ exp(xᵢ − x_max) · (xᵢ − x_max)`. Both passes use only
    /// stack-local accumulators — no `Vec`, no `Box`.
    ///
    /// Returns `1.0` (perfect acceptance) on empty input.
    #[inline]
    pub fn observe_and_forecast(&mut self, logits: &[f32]) -> f32 {
        let h = entropy_nats_zero_alloc(logits);
        self.ema_entropy = self.alpha_decay * h + (1.0 - self.alpha_decay) * self.ema_entropy;
        let alpha = (self.a - self.b * self.ema_entropy).clamp(ALPHA_FLOOR, 1.0);
        self.ema_alpha = alpha;
        alpha
    }

    /// Read the current EMA forecast `α` without a new observation.
    /// Returns the value cached by the last [`observe_and_forecast`](Self::observe_and_forecast).
    #[inline]
    pub const fn forecast_alpha_current(&self) -> f32 {
        self.ema_alpha
    }

    /// Adaptive draft length `γ` from the forecast acceptance rate.
    ///
    /// `γ = clamp(ceil(target_tokens / α), γ_min, γ_max)`
    ///
    /// When `α` is high (low entropy, predictable target) the drafter can
    /// safely aim for `target_tokens` accepted tokens. When `α` is low
    /// (high entropy) the formula *increases* `γ` to compensate — this is
    /// the paper §7.6 suggestion for batched-verification decode trees where
    /// the target forward cost is amortised over all drafted positions.
    /// Callers on non-batched verifiers should set `γ_max` tightly.
    #[inline]
    pub fn adaptive_gamma(
        &self,
        target_tokens: usize,
        forecast_alpha: f32,
        gamma_min: usize,
        gamma_max: usize,
    ) -> usize {
        let alpha = forecast_alpha.max(ALPHA_FLOOR);
        let gamma = ((target_tokens as f32) / alpha).ceil() as usize;
        gamma.clamp(gamma_min, gamma_max)
    }

    /// Reset the EMA state (e.g. at the start of a new trace).
    /// Keeps the fitted `(a, b)` — only the runtime state is cleared.
    #[inline]
    pub fn reset_ema(&mut self) {
        self.ema_entropy = 0.0;
        self.ema_alpha = self.a;
    }
}

use katgpt_core::traits::ScreeningPruner;

/// Check if solution `y` is consistent with current state `x`.
///
/// Consistent = every committed position in `x` matches the corresponding
/// position in `y`. Uncommitted positions (`None`) are wildcards.
pub fn is_consistent(current: &[Option<usize>], solution: &[usize]) -> bool {
    current
        .iter()
        .zip(solution.iter())
        .all(|(opt, &val)| opt.is_none_or(|v| v == val))
}

impl AlphaTarget {
    /// Create a new α-target tracker.
    ///
    /// - `len` — number of positions (e.g., puzzle size, path length)
    /// - `solutions` — K pre-computed valid solutions
    pub fn new(len: usize, solutions: Vec<Vec<usize>>) -> Self {
        Self {
            current: vec![None; len],
            solutions,
            cached_target: None,
            cached_prev: None,
        }
    }

    /// Commit a value at a position.
    pub fn commit(&mut self, pos: usize, val: usize) {
        if pos < self.current.len() {
            self.current[pos] = Some(val);
            self.cached_target = None; // invalidate cache
        }
    }

    /// Reset commitment at a position (uncommit).
    pub fn uncommit(&mut self, pos: usize) {
        if pos < self.current.len() {
            self.current[pos] = None;
            self.cached_target = None;
        }
    }

    /// Reset all commitments.
    pub fn reset(&mut self) {
        self.current.fill(None);
        self.cached_target = None;
        self.cached_prev = None;
    }

    /// Get the current α-target, recomputing if needed.
    ///
    /// When no solution remains consistent with the current state,
    /// returns the last valid target (LDT ŷ_prev stabilization, F3).
    /// If no previous target exists, returns the intersection result
    /// (which may have empty per-position sets).
    pub fn target(&mut self) -> &[HashSet<usize>] {
        if self.cached_target.is_none() {
            let new_target = alpha_intersect(&self.current, &self.solutions);

            // Single pass: determine whether the target has any non-empty set.
            // The original called `.iter().any(|s| !s.is_empty())` and then
            // `.iter().all(|s| s.is_empty())` — two full iterations. Since
            // `any(!empty)` is the exact logical inverse of `all(empty)`, we
            // only need a single short-circuiting scan.
            let has_content = new_target.iter().any(|s| !s.is_empty());

            // If the target has non-trivial content, cache it as ŷ_prev.
            if has_content {
                self.cached_prev = Some(new_target.clone());
            }

            // If the new target is entirely empty but we have a previous target,
            // use the previous target for stability.
            self.cached_target = Some(if has_content {
                new_target
            } else {
                match &self.cached_prev {
                    Some(prev) => prev.clone(),
                    None => new_target,
                }
            });
        }
        self.cached_target.as_ref().unwrap()
    }

    /// Check if a token at a position is consistent with the α-target.
    ///
    /// Returns `true` if the token appears in the target set for that position,
    /// meaning it's consistent with at least one remaining valid solution.
    pub fn is_allowed(&mut self, pos: usize, token: usize) -> bool {
        let target = self.target();
        target.get(pos).is_some_and(|set| set.contains(&token))
    }

    /// Count remaining consistent solutions.
    pub fn remaining_solutions(&self) -> usize {
        self.solutions
            .iter()
            .filter(|sol| is_consistent(&self.current, sol))
            .count()
    }

    /// Get the current commitment state.
    pub fn current(&self) -> &[Option<usize>] {
        &self.current
    }

    /// Get the number of positions.
    pub fn len(&self) -> usize {
        self.current.len()
    }

    /// Check if the tracker has no positions.
    pub fn is_empty(&self) -> bool {
        self.current.is_empty()
    }
}

impl AlphaScreeningPruner {
    /// Create a new α-screening pruner from an existing AlphaTarget.
    pub fn new(target: AlphaTarget) -> Self {
