use std::collections::HashMap;

// ── Prefix Hashing ────────────────────────────────────────────────

/// Compute a blake3-based prefix hash from a slice of sampled tokens, truncated to u64.
///
/// Tokens are serialized as little-ender u16 (sufficient for vocab < 65536).
/// The hash is deterministic: same prefix → same u64 key.
#[inline]
pub fn prefix_hash(tokens: &[usize]) -> u64 {
    let mut hasher = blake3::Hasher::new();
    for &t in tokens {
        hasher.update(&(t as u16).to_le_bytes());
    }
    let hash = hasher.finalize();
    u64::from_le_bytes(hash.as_bytes()[..8].try_into().unwrap())
}

impl PrefixCorrectionTable {
    /// Create an empty table with known vocab size.
    pub fn new(vocab_size: usize) -> Self {
        Self {
            corrections: HashMap::new(),
            vocab_size,
        }
    }

    /// Zero-alloc lookup: returns empty slice if not found.
    #[inline]
    pub fn lookup(&self, hash: u64) -> &[f32] {
        match self.corrections.get(&hash) {
            Some(v) => v,
            None => &[],
        }
    }

    /// Returns true if the table has no correction entries.
    #[inline]
    pub fn is_empty(&self) -> bool {
        self.corrections.is_empty()
    }

    /// Number of prefix entries in the table.
    pub fn len(&self) -> usize {
        self.corrections.len()
    }

    /// Vocab size of the correction vectors.
    #[inline]
    pub fn vocab_size(&self) -> usize {
        self.vocab_size
    }
}

impl PrefixCorrectionTableBuilder {
    /// Create a new builder with the given vocab size.
    pub fn new(vocab_size: usize) -> Self {
        Self {
            corrections: HashMap::new(),
            vocab_size,
        }
    }

    /// Add a correction vector for a given prefix.
    ///
    /// The prefix is hashed with blake3 internally. The correction vector
    /// must match `vocab_size` in length.
    ///
    /// Returns `&mut Self` for chaining.
    pub fn add_correction(mut self, prefix: &[usize], correction: &[f32]) -> Self {
        debug_assert_eq!(
            correction.len(),
            self.vocab_size,
            "Correction vector must match vocab_size"
        );
        let hash = prefix_hash(prefix);
        self.corrections.insert(hash, correction.to_vec());
        self
    }

    /// Add a correction from a pre-computed hash key.
    pub fn add_correction_raw(mut self, hash: u64, correction: Vec<f32>) -> Self {
        debug_assert_eq!(
            correction.len(),
            self.vocab_size,
            "Correction vector must match vocab_size"
        );
        self.corrections.insert(hash, correction);
        self
    }

    /// Build the immutable table.
    pub fn build(self) -> PrefixCorrectionTable {
        PrefixCorrectionTable {
            corrections: self.corrections,
            vocab_size: self.vocab_size,
        }
    }
}

impl PrefixCorrectionTable {
    /// Create a builder for this table.
    pub fn builder(vocab_size: usize) -> PrefixCorrectionTableBuilder {
        PrefixCorrectionTableBuilder::new(vocab_size)
    }
}

impl<F> ScreeningPruner for EnvPredictorPruner<F>
where
    F: Fn(usize, &[usize]) -> Vec<f32> + Send + Sync,
{
    fn relevance(&self, _depth: usize, token_idx: usize, parent_tokens: &[usize]) -> f32 {
        if self.n_observations == 0 {
            return 0.5; // No history yet — neutral score
        }

        // Run forward model to predict outcome features
        let predicted = (self.forward_model)(token_idx, parent_tokens);

        // Single fused pass: dot, ‖predicted‖², ‖avg‖² in one traversal.
        let mut dot = 0.0f32;
        let mut np = 0.0f32;
        let mut na = 0.0f32;
        for (&p, &a) in predicted.iter().zip(self.feature_avg.iter()) {
            dot += p * a;
            np += p * p;
            na += a * a;
        }
        let denom = (np.max(0.0).sqrt()).max(1e-8) * (na.max(0.0).sqrt()).max(1e-8);
        let cosine = dot / denom;
        fast_sigmoid(cosine / self.config.temperature)
    }

impl PredictionVerifier {
    pub fn new(config: EnvPredictorConfig) -> Self {
        Self {
            config,
            accuracy_ema: 0.5,
            total_verified: 0,
            total_correct: 0,
        }
    }

    /// Compare predicted features against actual features.
    /// Returns a PredictionRecord with accuracy score.
    pub fn verify(&mut self, predicted: &[f32], actual: &[f32], tick: u64) -> PredictionRecord {
        let accuracy = cosine_similarity(predicted, actual);
        let correct = accuracy >= self.config.accuracy_threshold;

        // Update EMA
        let alpha = 1.0 - self.config.ema_decay;
        self.accuracy_ema = self.config.ema_decay * self.accuracy_ema + alpha * accuracy;

        self.total_verified += 1;
        if correct {
            self.total_correct += 1;
        }

        PredictionRecord {
            accuracy,
            correct,
            tick,
        }
    }

    /// Returns the bandit reward based on current prediction accuracy.
    /// Higher accuracy → higher reward → promotion via AbsorbCompress.
    #[inline]
    pub fn bandit_reward(&self) -> f32 {
        self.accuracy_ema
    }

    /// Returns the fraction of correct predictions.
    pub fn correct_rate(&self) -> f32 {
        if self.total_verified == 0 {
            0.5
        } else {
            self.total_correct as f32 / self.total_verified as f32
        }
    }
}

impl PredictionConsistencyGate {
    pub fn new(config: EnvPredictorConfig) -> Self {
        Self {
            config,
            entropy_history: Vec::with_capacity(64),
        }
    }

    /// Compute Shannon entropy from a set of prediction feature vectors.
    /// Each row is a branch's predicted features. We compute per-feature
    /// variance across branches, then sum log-variances as entropy proxy.
    ///
    /// Uses the `E[x²] − E[x]²` identity so each feature is processed in a
    /// single fused pass over the branches (2 passes → 1).
    pub fn compute_branch_entropy(branch_features: &[Vec<f32>]) -> f32 {
        if branch_features.len() <= 1 {
            return 0.0; // Single branch = zero entropy
        }

        let n_features = branch_features[0].len();
        let n_branches = branch_features.len() as f32;
        let inv_n = 1.0 / n_branches;

        let mut total_entropy = 0.0f32;
        for j in 0..n_features {
            // E[x] and E[x²] in a single pass per feature.
            let mut sum = 0.0f32;
            let mut sum_sq = 0.0f32;
            for b in branch_features {
                let x = b[j];
                sum += x;
                sum_sq += x * x;
            }
            let mean = sum * inv_n;
            let mean_sq = sum_sq * inv_n;
            // var = E[x²] − E[x]² — algebraically identical to the prior
            // two-pass form, but touches each branch only once per feature.
            let var = (mean_sq - mean * mean).max(0.0);
            total_entropy += (1.0 + var).ln();
        }

        total_entropy
    }

    /// Get budget multiplier based on current entropy.
    /// High entropy → expand budget. Low entropy → contract.
    pub fn budget_multiplier(&mut self, entropy: f32) -> f32 {
        self.entropy_history.push(entropy);

        if entropy > self.config.consistency_entropy_threshold {
            // High entropy (inconsistent predictions) → expand
            self.config.budget_expand_factor
        } else {
            // Low entropy (consistent predictions) → contract
            self.config.budget_contract_factor
        }
    }

    /// Returns average entropy over last N observations.
    pub fn avg_entropy(&self, last_n: usize) -> f32 {
        let start = self.entropy_history.len().saturating_sub(last_n);
        let slice = &self.entropy_history[start..];
        if slice.is_empty() {
            0.0
        } else {
            slice.iter().sum::<f32>() / slice.len() as f32
        }
    }
}

use katgpt_core::traits::ScreeningPruner;

// ── FlowPruner ──────────────────────────────────────────────────

/// ScreeningPruner wrapper that adds GFlowNet flow-based exploration bonus.
///
/// High stop_prob = model wants to stop = low flow = no bonus needed.
/// Low stop_prob = model wants to continue = high flow = boost exploration.
///
/// # Formula
///
/// ```text
/// relevance_flow(depth, token, path) = inner_relevance * (1 + λ × (1 - stop_prob(depth)))
/// ```
///
/// Where:
/// - `inner_relevance` = the wrapped pruner's relevance score
/// - `λ` = flow regularization strength (paper: reg_coef)
/// - `stop_prob(depth)` = P(EOS | depth) from marginals
///
/// # Design
///
/// - Zero-alloc: just a multiplication on top of inner relevance
/// - Additive: wraps any ScreeningPruner without modifying it
/// - Revertible: set `lambda = 0.0` to disable
pub struct FlowPruner<P: ScreeningPruner> {
    /// Inner pruner to wrap.
    inner: P,
    /// Flow regularization strength (paper: reg_coef).
    /// Default: 0.3. Set to 0.0 to disable flow bonus.
    lambda: f32,
    /// Per-depth EOS probability from marginals.
    /// `stop_probs[depth]` = probability model assigns to stopping at that depth.
    stop_probs: Vec<f32>,
}

impl<P: ScreeningPruner> FlowPruner<P> {
    /// Create a new FlowPruner wrapping an inner pruner.
    ///
    /// # Arguments
    ///
    /// * `inner` — The ScreeningPruner to wrap
    /// * `lambda` — Flow regularization strength (default: 0.3)
    /// * `stop_probs` — Per-depth EOS probability from marginals.
    ///   Extract from `marginals[depth][eos_token_idx]`.
    ///   If no EOS token in vocab, use entropy as proxy:
    ///   `stop_probs[depth] = 1.0 - entropy(marginals[depth]) / max_entropy`
    pub fn new(inner: P, lambda: f32, stop_probs: Vec<f32>) -> Self {
        Self {
            inner,
            lambda,
            stop_probs,
        }
    }

impl AttentionImportance {
    /// Create a new attention importance scorer.
    #[inline]
    pub const fn new() -> Self {
        Self
    }

    /// Compute per-step importance scores from raw attention weights.
    ///
    /// `scores[i]` = attention weight at token position `i`.
    /// `boundaries` = step boundaries (sorted by token_pos).
    ///
    /// Returns `Vec<f32>` where `result[step_index]` = mean attention for that step.
    /// Uses sigmoid normalization to keep scores in [0, 1].
    pub fn score_steps(&self, scores: &[f32], boundaries: &[StepBoundary]) -> Vec<f32> {
        if boundaries.is_empty() || scores.is_empty() {
            return Vec::new();
        }

        let mut step_scores = Vec::with_capacity(boundaries.len());

        for (i, boundary) in boundaries.iter().enumerate() {
            let start = boundary.token_pos;
            let end = match boundaries.get(i + 1) {
                Some(next) => next.token_pos.min(scores.len()),
                None => scores.len(),
            };

            if start >= scores.len() || start >= end {
                step_scores.push(0.0);
                continue;
            }

            let slice = &scores[start..end];
            let mean = slice.iter().sum::<f32>() / slice.len() as f32;
            step_scores.push(sigmoid(mean));
        }

        step_scores
    }
}

impl FoldBandit {
    /// Create a new fold bandit with uniform priors.
    pub fn new() -> Self {
        Self {
            alphas: [1.0; 5],
            betas: [1.0; 5],
            pulls: [0; 5],
            decay: 0.995,
        }
    }

    /// Create a fold bandit with a specific decay rate.
    pub fn with_decay(decay: f32) -> Self {
        Self {
            decay: decay.clamp(0.9, 1.0),
            ..Self::new()
        }
    }

    /// Select a fold budget using Thompson sampling.
    ///
    /// Samples from Beta(α, β) for each arm and returns the budget
    /// corresponding to the highest sample.
    pub fn select_budget(&mut self, rng: &mut Rng) -> f32 {
        let mut best_arm = DEFAULT_ARM;
        let mut best_sample = f32::NEG_INFINITY;

        for i in 0..5 {
            let sample = sample_beta(self.alphas[i], self.betas[i], rng);
            if sample > best_sample {
                best_sample = sample;
                best_arm = i;
            }
        }

        self.pulls[best_arm] += 1;
        BUDGET_ARMS[best_arm]
    }

    /// Record the reward signal for a chosen budget.
    ///
    /// - `accepted`: whether the fold verification passed.
    /// - `tokens_saved_ratio`: fraction of tokens saved (0.0–1.0).
    ///
    /// Reward combines acceptance and savings; penalty applies when
    /// verification fails.
    pub fn record_reward(&mut self, budget: f32, accepted: bool, tokens_saved_ratio: f32) {
        let arm = match budget_to_arm(budget) {
            Some(idx) => idx,
            None => return,
        };

        let reward = if accepted {
            tokens_saved_ratio.max(0.0)
        } else {
            0.0
        };

        // Update Beta posterior.
        self.alphas[arm] += reward;
        self.betas[arm] += 1.0 - reward;

        // Apply decay to all arms to age out old observations.
        self.apply_decay();
    }

    /// Apply exponential decay to all arm observations.
    fn apply_decay(&mut self) {
        for i in 0..5 {
            self.alphas[i] = 1.0 + (self.alphas[i] - 1.0) * self.decay;
            self.betas[i] = 1.0 + (self.betas[i] - 1.0) * self.decay;
        }
    }

    /// Get total pulls across all arms.
    pub fn total_pulls(&self) -> u32 {
        self.pulls.iter().sum()
    }

    /// Get the arm index with the highest expected reward.
    pub fn best_arm(&self) -> usize {
        let mut best = DEFAULT_ARM;
        let mut best_mean = 0.0_f32;

        for i in 0..5 {
            let mean = self.alphas[i] / (self.alphas[i] + self.betas[i]);
            if mean > best_mean {
                best_mean = mean;
                best = i;
            }
        }

        best
    }

    /// Get the best fold budget based on observed rewards.
    pub fn best_budget(&self) -> f32 {
        BUDGET_ARMS[self.best_arm()]
    }

    /// Get the number of pulls for a specific arm.
    pub fn pulls(&self, arm: usize) -> u32 {
        self.pulls.get(arm).copied().unwrap_or(0)
    }

    /// Scale fold budget by precision confidence from BAKE embeddings.
    ///
    /// High confidence (precise embeddings) → can fold more aggressively → lower budget.
    /// Low confidence (uncertain embeddings) → keep more steps → higher budget.
    ///
    /// Bridge: `fold_budget = bandit.best_budget() * (1.0 - α * confidence)`
    /// where α controls how much precision influences folding (default 0.3).
    #[cfg(feature = "bake_precision")]
    pub fn precision_gated_budget(&self, precision_confidence: f32, alpha: f32) -> f32 {
        let base = self.best_budget();
        let gated = base * (1.0 - alpha * precision_confidence);
        gated.clamp(0.1, 1.0) // always keep at least 10%
    }
}

