// ── Agreement Counting ──────────────────────────────────────────

/// Count the number of token-level agreements between two variants.
///
/// Two tokens "agree" when they are identical at the same position.
/// Positions outside the resampled region should always agree (same base path).
///
/// Returns the raw count of matching positions.
///
/// ## Implementation
///
/// Uses chunked 4-at-a-time comparison via `u64` casts on 64-bit platforms,
/// enabling the compiler to auto-vectorize the equality checks.
#[inline]
fn count_agreements(a: &[usize], b: &[usize]) -> usize {
    let min_len = a.len().min(b.len());
    if min_len == 0 {
        return 0;
    }

    // Safety: usize and u64 have identical layout on 64-bit platforms.
    let a_u64 = unsafe { std::slice::from_raw_parts(a.as_ptr() as *const u64, min_len) };
    let b_u64 = unsafe { std::slice::from_raw_parts(b.as_ptr() as *const u64, min_len) };

    // Process 4 at a time — SIMD/auto-vectorization friendly
    let chunks = min_len / 4;
    let mut count = 0usize;

    for i in 0..chunks {
        let base = i * 4;
        count += (a_u64[base] == b_u64[base]) as usize;
        count += (a_u64[base + 1] == b_u64[base + 1]) as usize;
        count += (a_u64[base + 2] == b_u64[base + 2]) as usize;
        count += (a_u64[base + 3] == b_u64[base + 3]) as usize;
    }

    // Remainder (0–3 elements)
    for i in (chunks * 4)..min_len {
        count += (a_u64[i] == b_u64[i]) as usize;
    }

    count
}

impl TokenRule {
    /// Returns the number of defined rules (excluding `All`).
    pub const fn rule_count() -> usize {
        4 // Digit, Compare, Arithmetic, Augment
    }

    /// All strategy rules in canonical cycle order.
    pub const STRATEGIES: [TokenRule; 5] = [
        TokenRule::Digit,
        TokenRule::Arithmetic,
        TokenRule::Compare,
        TokenRule::Augment,
        TokenRule::All,
    ];

    /// Returns the support set (allowed token IDs) for this rule.
    ///
    /// For character-level tokenizers, these are direct mappings.
    /// For BPE tokenizers, use `PpotConfig::with_cached_support` to override.
    pub fn support(&self, vocab_size: usize) -> Vec<usize> {
        match self {
            TokenRule::Digit => (0..10.min(vocab_size)).collect(),
            TokenRule::Compare => {
                // '<' = 60, '>' = 62, '=' = 61, '!' = 33 in ASCII
                // For character-level (vocab < 256): use ASCII codes
                // For BPE (vocab >= 256): fall back to small range
                if vocab_size < 256 {
                    vec![33, 60, 61, 62]
                        .into_iter()
                        .filter(|&t| t < vocab_size)
                        .collect()
                } else {
                    // BPE fallback: can't reliably identify operator tokens
                    (0..vocab_size).collect()
                }
            }
            TokenRule::Arithmetic => {
                // '+' = 43, '-' = 45, '*' = 42, '/' = 47
                if vocab_size < 256 {
                    vec![42, 43, 45, 47]
                        .into_iter()
                        .filter(|&t| t < vocab_size)
                        .collect()
                } else {
                    (0..vocab_size).collect()
                }
            }
            TokenRule::Augment => {
                // Augmented assignment operators: same as arithmetic + '='
                if vocab_size < 256 {
                    vec![42, 43, 45, 47, 61]
                        .into_iter()
                        .filter(|&t| t < vocab_size)
                        .collect()
                } else {
                    (0..vocab_size).collect()
                }
            }
            TokenRule::All => (0..vocab_size).collect(),
        }
    }

    /// Returns the support as a bitmask-compatible slice for fast membership checks.
    /// For hot paths, prefer pre-computing support once via [`PpotConfig`].
    pub fn index(&self) -> usize {
        match self {
            TokenRule::Digit => 0,
            TokenRule::Compare => 1,
            TokenRule::Arithmetic => 2,
            TokenRule::Augment => 3,
            TokenRule::All => 4,
        }
    }

    /// Parse from string (for config file compatibility).
    pub fn from_str_ignore_case(s: &str) -> Option<Self> {
        match s.to_ascii_lowercase().as_str() {
            "digit" => Some(TokenRule::Digit),
            "compare" => Some(TokenRule::Compare),
            "arithmetic" => Some(TokenRule::Arithmetic),
            "augment" => Some(TokenRule::Augment),
            "all" => Some(TokenRule::All),
            _ => None,
        }
    }
}

