    #[inline]
    pub fn clamp_threshold(&self, threshold: f32) -> f32 {
        threshold.clamp(self.entropy_threshold_min, self.entropy_threshold_max)
    }

    /// Pre-compute and cache support sets for all 5 `TokenRule` variants.
    ///
    /// Call once after setting `enabled = true`. Avoids `rule.support(vocab_size)`
    /// allocating a new `Vec<usize>` on every resampling call.
    pub fn with_cached_support(mut self, vocab_size: usize) -> Self {
        let arr: [Vec<usize>; 5] = [
            TokenRule::Digit.support(vocab_size),
            TokenRule::Compare.support(vocab_size),
            TokenRule::Arithmetic.support(vocab_size),
            TokenRule::Augment.support(vocab_size),
            TokenRule::All.support(vocab_size),
        ];
        self.cached_support = Some(Box::new(arr));
        self
    }

    /// Returns `true` if cached support sets have been pre-computed via [`Self::with_cached_support`].
    #[inline]
    pub fn has_cached_support(&self) -> bool {
        self.cached_support.is_some()
    }

    /// Return the cached support set for `rule`.
    ///
    /// **Panics** if [`Self::with_cached_support`] was not called before this method.
    /// Zero-allocation hot path — returns a slice into the pre-computed array.
    #[inline]
    pub fn support_for(&self, rule: TokenRule) -> &[usize] {
        self.cached_support
            .as_ref()
            .expect("PpotConfig::support_for called before with_cached_support")[rule.index()]
        .as_slice()
    }
}

impl BoundaryPenalty {
    pub fn new(quant_levels: u32, quant_scale: f32) -> Self {
        Self {
            penalty_weight: 0.1,
            quant_scale,
            quant_levels,
            boundary_epsilon: 0.05,
        }
    }

    /// Compute how close a logit value is to the nearest quantization boundary.
    /// Returns 0.0 if far from boundary, 1.0 if exactly on boundary.
    ///
    /// This is the standalone entry point. Hot-path callers that score many
    /// logits from the same config should use [`Self::compute_boundary_score`],
    /// which lifts the per-instance invariants out of the per-logit loop.
    pub fn boundary_proximity(&self, logit: f32) -> f32 {
        let inv = self.invariants();
        Self::proximity_with(logit, &inv)
    }

    /// Pre-compute the per-instance invariants used by [`Self::proximity_with`].
    /// Done once per `compute_boundary_score` call instead of once per logit.
    #[inline]
    fn invariants(&self) -> BoundaryInvariants {
        let inv_scale = 1.0 / self.quant_scale;
        BoundaryInvariants {
            inv_scale,
            half_scale: self.quant_scale * 0.5,
            near_threshold: self.boundary_epsilon * self.quant_scale,
            inv_scale_20: inv_scale * 20.0,
            quant_scale: self.quant_scale,
        }
    }

    /// Branch-free proximity core operating on pre-computed invariants.
    #[inline]
    fn proximity_with(logit: f32, inv: &BoundaryInvariants) -> f32 {
        // Quantize to grid.
        let quantized = (logit * inv.inv_scale).round() * inv.quant_scale;
        // Distance to nearest grid point.
        let dist = (logit - quantized).abs();
        // How close to the midpoint between grid points (the boundary).
        let boundary_dist = (dist - inv.half_scale).abs();
        if boundary_dist < inv.near_threshold {
            // Original form was 1/(1+exp(X)) where X = boundary_dist*inv_scale_20 - 5;
            // that's sigmoid(-X) = sigmoid(5 - boundary_dist*inv_scale_20).
            // Higher boundary_dist → lower proximity (further from boundary midpoint).
            katgpt_core::simd::fast_sigmoid(5.0 - boundary_dist * inv.inv_scale_20)
        } else {
            0.0
        }
    }

    /// Compute boundary score for a single token's logits.
    /// Higher score = more penalty (closer to boundaries).
    ///
    /// Computes the per-instance invariants **once** and threads them through
    /// `Self::proximity_with` — avoids re-deriving `inv_scale`,
    /// `half_scale`, `near_threshold`, and `inv_scale * 20.0` for every logit.
    pub fn compute_boundary_score(&self, token_logits: &[f32]) -> f32 {
        if token_logits.is_empty() {
            return 0.0;
        }
        let inv = self.invariants();
        let total_proximity: f32 = token_logits
            .iter()
            .map(|&l| Self::proximity_with(l, &inv))
            .sum();
        total_proximity / token_logits.len() as f32
    }

    /// Apply boundary penalty to draft scores.
    /// Returns modified scores (higher is better, penalty reduces score).
    pub fn apply_penalty(&self, draft_scores: &mut [f32], logits_per_token: &[Vec<f32>]) {
        // Hoist per-instance invariants out of the loop — avoids recomputing
        // 1 division + 2 multiplications per token.
        let inv = self.invariants();
        for (score, token_logits) in draft_scores.iter_mut().zip(logits_per_token.iter()) {
            if token_logits.is_empty() {
                continue;
            }
            let total_proximity: f32 = token_logits
                .iter()
                .map(|&l| Self::proximity_with(l, &inv))
                .sum();
            let boundary_score = total_proximity / token_logits.len() as f32;
            // Penalty reduces the score proportionally
            *score -= self.penalty_weight * boundary_score * score.abs();
        }
    }
}

impl SpsCurve {
    /// Build the curve from a hardware profile.
    ///
    /// The profile MAY be unsorted; this constructor sorts it ascending by
    /// batch size. Duplicate batch sizes keep the LAST sample's SPS value
    /// (later samples override earlier ones — useful for hot-reload profiles).
    ///
    /// # Panics
    ///
    /// Debug-asserts that `samples` is non-empty. An empty profile has no
    /// meaningful SPS curve.
    pub fn from_profile(samples: &[(usize, f32)]) -> Self {
        debug_assert!(!samples.is_empty(), "SpsCurve profile must be non-empty");
        // Sort ascending by batch size (stable so original order is preserved
        // for ties, which matters for the override pass below).
        let mut sorted: Vec<(usize, f32)> = samples.to_vec();
        sorted.sort_by(|(b1, _), (b2, _)| b1.cmp(b2));
        // Collapse duplicates, keeping the LAST sample per batch size
        // (override semantics: a later sample overrides an earlier one).
        let mut deduped: Vec<(usize, f32)> = Vec::with_capacity(sorted.len());
        for (b, s) in sorted.into_iter() {
            if deduped.last().is_some_and(|(lb, _)| *lb == b) {
                if let Some((_, last_s)) = deduped.last_mut() {
                    *last_s = s;
                }
            } else {
                deduped.push((b, s));
            }
        }
        Self {
            samples: deduped.into_boxed_slice(),
        }
    }

    /// Construct a constant curve (single sample). Useful for tests and for
    /// "no engine-cost model" baselines where every batch size costs the same.
    pub fn constant(steps_per_second: f32) -> Self {
        Self {
            samples: Box::new([(1usize, steps_per_second)]),
        }
    }

    /// Linear-interpolated steps-per-second at batch size `B`.
    ///
    /// `O(log n)` binary search to find the bracketing samples `[lo, hi]`,
    /// then `sps(B) = sps_lo + (sps_hi - sps_lo) * (B - B_lo) / (B_hi - B_lo)`.
    ///
    /// Out-of-range `B` is clamped to the nearest endpoint (no extrapolation).
    #[inline]
    pub fn steps_per_second(&self, batch_size: usize) -> f32 {
        let s = &*self.samples;
        // Clamp at the lower end.
        if batch_size <= s[0].0 {
            return s[0].1;
        }
        // Clamp at the upper end.
        let last = s.len() - 1;
        if batch_size >= s[last].0 {
            return s[last].1;
        }
        // Binary search for the bracketing pair. We want the largest `lo`
        // such that s[lo].0 <= batch_size.
        let mut lo = 0usize;
        let mut hi = last;
        while hi - lo > 1 {
            let mid = lo + (hi - lo) / 2;
            if s[mid].0 <= batch_size {
                lo = mid;
            } else {
                hi = mid;
            }
        }
        // s[lo].0 <= batch_size < s[hi].0 by construction.
        let (b_lo, sps_lo) = s[lo];
        let (b_hi, sps_hi) = s[hi];
        if b_hi == b_lo {
            // Defensive: should not happen (dedup removes equal batch sizes),
            // but guard against division-by-zero anyway.
            return sps_lo;
        }
        let t = (batch_size - b_lo) as f32 / (b_hi - b_lo) as f32;
        sps_lo + (sps_hi - sps_lo) * t
    }

    /// Number of profile samples (for diagnostics / tests).
    #[inline]
    pub fn len(&self) -> usize {
        self.samples.len()
    }

    /// Whether the curve is empty (always false post-`from_profile` because
    /// empty profiles panic in debug, but provided for API completeness).
    #[inline]
    pub fn is_empty(&self) -> bool {
        self.samples.is_empty()
    }
}

impl std::fmt::Display for ProfileError {
    #[cold]
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ProfileError::InvalidMagic => write!(f, "invalid magic bytes"),
            ProfileError::VersionMismatch => write!(f, "version mismatch"),
            ProfileError::TruncatedData => write!(f, "truncated data"),
        }
    }

impl SelectivityRouter {
    /// Create a new router with default thresholds.
    ///
    /// Defaults: `kurtosis_threshold = 1.0`, `alpha = 0.1`.
    pub fn new() -> Self {
        Self {
            position_kurtosis: Vec::new(),
            kurtosis_threshold: 1.0,
            alpha: 0.1,
        }
    }

    /// Create with pre-allocated capacity for `max_positions` positions.
    pub fn with_capacity(max_positions: usize) -> Self {
        Self {
            position_kurtosis: Vec::with_capacity(max_positions),
            kurtosis_threshold: 1.0,
            alpha: 0.1,
        }
    }

    /// Should this position use CoT (thinking) mode?
    ///
    /// - Returns `true` if kurtosis is LOW → polysemantic → needs thinking.
    /// - Returns `false` if kurtosis is HIGH → monosemantic → direct answer.
    /// - Returns `false` if no data yet (optimistic direct mode).
    ///
    /// O(1) — single array lookup + comparison.
    pub fn should_think(&self, position: usize) -> bool {
        match self.position_kurtosis.get(position) {
            Some(&k) => k < self.kurtosis_threshold,
            None => false, // No data → optimistic direct mode.
        }
    }

    /// Observe kurtosis at a given position. Updates EMA.
    ///
    /// Call after each speculative decode step with the computed kurtosis.
    /// O(1) amortized — Vec resize only when new positions encountered.
    pub fn observe(&mut self, position: usize, kurtosis: f32) {
        if position >= self.position_kurtosis.len() {
            self.position_kurtosis.resize(position + 1, 0.0);
        }
        let prev = self.position_kurtosis[position];
        self.position_kurtosis[position] = self.alpha * kurtosis + (1.0 - self.alpha) * prev;
    }

    /// Get the current EMA kurtosis for a position.
    ///
    /// Returns `None` if position has never been observed.
    pub fn kurtosis_at(&self, position: usize) -> Option<f32> {
        self.position_kurtosis.get(position).copied()
    }

    /// Reset all tracking state. Use when switching domains or sessions.
    pub fn reset(&mut self) {
        self.position_kurtosis.clear();
    }

    /// Recommend compute route for a position.
    ///
    /// - High kurtosis → predictable → `CpuSpeculative`
    /// - Low kurtosis → complex → `GpuAutoregressive`
    /// - No data → `CpuSpeculative` (optimistic)
    pub fn recommend_route(&self, position: usize) -> ComputeRoute {
        if self.should_think(position) {
            ComputeRoute::GpuAutoregressive
        } else {
            ComputeRoute::CpuSpeculative
        }
    }

    /// Serialize kurtosis profile to bytes.
    ///
    /// Format: `[magic:4][version:4][len:4][f32_slice:len*4]`
    pub fn serialize(&self) -> Vec<u8> {
        let len = self.position_kurtosis.len() as u32;
        let mut buf = Vec::with_capacity(HEADER_SIZE + len as usize * 4);
        buf.extend_from_slice(&MAGIC);
        buf.extend_from_slice(&VERSION.to_le_bytes());
        buf.extend_from_slice(&len.to_le_bytes());
        let bytes = bytemuck::cast_slice::<f32, u8>(&self.position_kurtosis);
        buf.extend_from_slice(bytes);
        buf
    }

    /// Deserialize kurtosis profile from bytes (cold start recovery).
    pub fn deserialize(data: &[u8]) -> Result<Self, ProfileError> {
        if data.len() < HEADER_SIZE {
            return Err(ProfileError::TruncatedData);
        }

        // Length already validated above; the `try_into` calls below cannot
        // fail because each slice is exactly 4 bytes. Use `?` with a defensive
        // error mapping rather than `unwrap()` to keep the fallible surface
        // explicit and panic-free.
        let magic: [u8; 4] = data[0..4]
            .try_into()
            .map_err(|_| ProfileError::TruncatedData)?;
        if magic != MAGIC {
            return Err(ProfileError::InvalidMagic);
        }

        let version = u32::from_le_bytes(
            data[4..8]
                .try_into()
                .map_err(|_| ProfileError::TruncatedData)?,
        );
        if version != VERSION {
            return Err(ProfileError::VersionMismatch);
        }

        let len = u32::from_le_bytes(
            data[8..12]
                .try_into()
                .map_err(|_| ProfileError::TruncatedData)?,
        ) as usize;
        let expected = HEADER_SIZE + len * 4;
        if data.len() < expected {
            return Err(ProfileError::TruncatedData);
        }

        let f32_bytes = &data[HEADER_SIZE..expected];
        // bytemuck::cast_slice is infallible and zero-copy when the input is
        // properly aligned; otherwise it returns the original input. We use
        // `to_vec()` to materialize the owned Vec<f32>.
        let position_kurtosis = bytemuck::cast_slice::<u8, f32>(f32_bytes).to_vec();

        Ok(Self {
            position_kurtosis,
            kurtosis_threshold: 1.0,
            alpha: 0.1,
        })
    }

    /// Current number of tracked positions.
    pub fn len(&self) -> usize {
        self.position_kurtosis.len()
    }

    /// Whether any positions are tracked.
    pub fn is_empty(&self) -> bool {
        self.position_kurtosis.is_empty()
    }
}

