impl AdaptiveReconcilerFrozen {
    const MAGIC: [u8; 4] = *b"ADRC";
    const VERSION: u32 = 1;

    /// Validate frozen state.
    pub fn validate(&self) -> Result<(), String> {
        if self.magic != Self::MAGIC {
            return Err(format!(
                "AdaptiveReconcilerFrozen: bad magic {:?}, expected {:?}",
                self.magic,
                Self::MAGIC
            ));
        }
        if self.version != Self::VERSION {
            return Err(format!(
                "AdaptiveReconcilerFrozen: bad version {}, expected {}",
                self.version,
                Self::VERSION
            ));
        }
        Ok(())
    }
}

impl AdaptiveReconciler {
    /// Create a new adaptive reconciler.
    pub fn new(config: ReconciliationConfig) -> Self {
        Self {
            reconciler: SpecReconciler::new(config),
            q_values: [0.0; NUM_ARMS],
            visits: [0; NUM_ARMS],
            total_pulls: 0,
            last_arm: 1, // start with medium
            epsilon: 0.3,
        }
    }

    /// Create from frozen state.
    pub fn from_frozen(
        config: ReconciliationConfig,
        frozen: &AdaptiveReconcilerFrozen,
    ) -> Result<Self, String> {
        frozen.validate()?;
        Ok(Self {
            reconciler: SpecReconciler::new(config),
            q_values: frozen.q_values,
            visits: frozen.visits,
            total_pulls: frozen.total_pulls,
            last_arm: 1,
            epsilon: 0.3,
        })
    }

    /// Freeze bandit state for persistence.
    pub fn freeze(&self) -> AdaptiveReconcilerFrozen {
        AdaptiveReconcilerFrozen {
            magic: AdaptiveReconcilerFrozen::MAGIC,
            version: AdaptiveReconcilerFrozen::VERSION,
            q_values: self.q_values,
            visits: self.visits,
            total_pulls: self.total_pulls,
        }
    }

    /// Select an arm using ε-greedy.
    fn select_arm(&mut self, rng: &mut Rng) -> usize {
        if rng.uniform() < self.epsilon {
            rng.uniform() as usize * NUM_ARMS / (u8::MAX as usize + 1)
        } else {
            self.best_arm()
        }
    }

    /// Select arm deterministically (for testing).
    fn best_arm(&self) -> usize {
        self.q_values
            .iter()
            .enumerate()
            .max_by(|(_, a), (_, b)| a.total_cmp(b))
            .map_or(1, |(i, _)| i)
    }

    /// Update Q-value for the last chosen arm.
    fn update(&mut self, arm: usize, reward: f32) {
        self.visits[arm] += 1;
        self.total_pulls += 1;
        let n = self.visits[arm] as f32;
        self.q_values[arm] += (reward - self.q_values[arm]) / n;

        // Decay epsilon.
        self.epsilon *= 0.995;
        if self.epsilon < 0.01 {
            self.epsilon = 0.01;
        }
    }

    /// Reconcile with adaptive threshold selection.
    ///
    /// Returns the reconciliation result. Call `observe_outcome` afterward
    /// with the ground truth to update the bandit.
    pub fn reconcile(
        &mut self,
        h_last: &TrajectoryPoint,
        client_trajectory: &[TrajectoryPoint],
        q_goals: &[f32],
        steps: usize,
        rng: &mut Rng,
    ) -> ReconciliationResult {
        // Select threshold arm.
        self.last_arm = self.select_arm(rng);

        // Override the accept threshold.
        self.reconciler.config.accept_threshold = THRESHOLD_CANDIDATES[self.last_arm];

        self.reconciler
            .reconcile(h_last, client_trajectory, q_goals, steps, rng)
    }

    /// Observe the ground truth outcome and update the bandit.
    ///
    /// `was_legitimate` = true if the trajectory was actually legitimate.
    /// `verdict` = the verdict returned by `reconcile`.
    pub fn observe_outcome(&mut self, verdict: ReconciliationVerdict, was_legitimate: bool) {
        let reward = match (verdict, was_legitimate) {
            (ReconciliationVerdict::Accept, true) => 1.0, // correct accept
            (ReconciliationVerdict::Quarantine, false) => 1.0, // correct quarantine
            (ReconciliationVerdict::Uncertain, _) => 0.5, // uncertain = partial
            (ReconciliationVerdict::Accept, false) => 0.0, // missed hack
            (ReconciliationVerdict::Quarantine, true) => 0.0, // false positive
        };
        self.update(self.last_arm, reward);
    }

    /// Get the current best threshold (Q-value-weighted).
    pub fn best_threshold(&self) -> f32 {
        THRESHOLD_CANDIDATES[self.best_arm()]
    }

    /// Get the current epsilon (exploration rate).
    #[inline]
    pub fn epsilon(&self) -> f32 {
        self.epsilon
    }

    /// Get Q-values for inspection.
    pub fn q_values(&self) -> &[f32; NUM_ARMS] {
        &self.q_values
    }
}

impl DefaultManifoldGenerator {
    /// Create a new generator with the given config.
    #[inline]
    pub fn new(config: ReconciliationConfig) -> Self {
        Self { config }
    }

    /// Sample a goal direction from Q-value weights.
    ///
    /// Each Q-value corresponds to a direction bin (uniformly spaced over [0, 2π)).
    /// Returns the sampled direction angle in radians.
    ///
    /// Hot-path optimization: pre-compute shifted weights once in a small
    /// `Vec<f32>` instead of recomputing `exp(q - max_q)` twice per element
    /// (which dominates cost once `q_goals.len()` exceeds ~4).
    fn sample_goal_from_q(&self, q_goals: &[f32], rng: &mut Rng) -> f32 {
        if q_goals.is_empty() {
            return rng.uniform() * TAU;
        }

        // Shift by max_q for numerical stability (same as before — this is
        // categorical sampling, not an activation; the project sigmoid rule
        // applies to bounded mappings, not probability normalization).
        let max_q = q_goals.iter().copied().fold(f32::NEG_INFINITY, f32::max);

        // Compute weights once, reuse for total + sampling. Capacity hint
        // avoids the realloc-on-first-push.
        // (`fast_exp` = Cephes scalar exp; iterator `.map()` pattern per SIMD rule.)
        use katgpt_core::simd::fast_exp;
        let weights: Vec<f32> = q_goals.iter().map(|q| fast_exp(q - max_q)).collect();
        let total: f32 = weights.iter().copied().sum();
        if total <= 0.0 {
            return rng.uniform() * TAU;
        }

        // Weighted sample using cached weights — no recomputation.
        let mut r = rng.uniform() * total;
        let mut chosen = weights.len() - 1;
        for (i, &w) in weights.iter().enumerate() {
            r -= w;
            if r <= 0.0 {
                chosen = i;
                break;
            }
        }

        // Map bin to direction angle with jitter.
        let bin_count = weights.len();
        let bin_width = TAU / bin_count as f32;
        chosen as f32 * bin_width + rng.uniform() * bin_width
    }

    /// Clamp velocity to `max_speed`.
    ///
    /// Hot-path optimization: compare squared speed against the squared limit
    /// to avoid the `sqrt` on the fast (already-bounded) path. Only when we
    /// need to scale do we compute the actual magnitude.
    #[inline]
    fn clamp_velocity(vx: f32, vy: f32, max_speed: f32) -> (f32, f32) {
        let speed_sq = vx * vx + vy * vy;
        let max_sq = max_speed * max_speed;
        if speed_sq > max_sq && speed_sq > 0.0 {
            // scale = max_speed / sqrt(speed_sq)
            let inv_speed = max_speed / speed_sq.sqrt();
            (vx * inv_speed, vy * inv_speed)
        } else {
            (vx, vy)
        }
    }

    /// Clamp position within map bounds [min_x, min_y, max_x, max_y].
    #[inline]
    fn clamp_position(x: f32, y: f32, bounds: &[f32; 4]) -> (f32, f32) {
        (x.clamp(bounds[0], bounds[2]), y.clamp(bounds[1], bounds[3]))
    }
}

impl ManifoldGenerator for DefaultManifoldGenerator {
    fn generate(
        &self,
        h_last: &TrajectoryPoint,
        q_goals: &[f32],
        k: usize,
        dt: f32,
        steps: usize,
        rng: &mut Rng,
    ) -> Vec<Vec<TrajectoryPoint>> {
        let sigma = self.config.noise_sigma;
        let max_speed = self.config.max_speed;
        let map_bounds = &self.config.map_bounds;
        let sqrt_dt = dt.sqrt();

        let mut trajectories = Vec::with_capacity(k);

        for _ in 0..k {
            // Sample a goal direction for this trajectory.
            let goal_dir = self.sample_goal_from_q(q_goals, rng);
            let goal_vx = goal_dir.cos() * max_speed * 0.5;
            let goal_vy = goal_dir.sin() * max_speed * 0.5;

            let mut traj = Vec::with_capacity(steps);

            // Start from h_last.
            let mut pos_x = h_last.pos_x();
            let mut pos_y = h_last.pos_y();
            let mut vel_x = h_last.vel_x();
            let mut vel_y = h_last.vel_y();
            let mut kills = h_last.kills();
            let mut deaths = h_last.deaths();
            let mut assists = h_last.assists();
            let mut direction = h_last.direction();

            for _ in 0..steps {
                // Blend velocity toward goal direction with some noise.
                let noise_vx = gaussian_sample(rng) * sigma * sqrt_dt;
                let noise_vy = gaussian_sample(rng) * sigma * sqrt_dt;

                vel_x = vel_x * 0.8 + goal_vx * 0.2 + noise_vx;
                vel_y = vel_y * 0.8 + goal_vy * 0.2 + noise_vy;

                // Clamp velocity.
                (vel_x, vel_y) = Self::clamp_velocity(vel_x, vel_y, max_speed);

                // Advance position: pos += vel * dt + noise * sigma * sqrt(dt).
                let noise_px = gaussian_sample(rng) * sigma * sqrt_dt;
                let noise_py = gaussian_sample(rng) * sigma * sqrt_dt;

                pos_x += vel_x * dt + noise_px;
                pos_y += vel_y * dt + noise_py;

                // Clamp position within map bounds.
                (pos_x, pos_y) = Self::clamp_position(pos_x, pos_y, map_bounds);

                // Kills increase stochastically: with small probability, add max(0, noise).
                let kill_noise = gaussian_sample(rng);
                if kill_noise > 2.0 {
                    kills += (kill_noise - 2.0).max(0.0);
                }

                // Deaths stay stable with very small probability of increment.
                let death_noise = gaussian_sample(rng);
                if death_noise > 3.0 {
                    deaths += 1.0;
                }

                // Assists have small chance of incrementing.
                let assist_noise = gaussian_sample(rng);
                if assist_noise > 2.5 {
                    assists += 1.0;
                }

                // Direction updates smoothly toward velocity direction.
                let vel_dir = vel_y.atan2(vel_x);
                // Normalize delta to [-π, π] via one add + one remainder
                // rather than a `while` loop (cheap and bounded).
                let mut delta = (vel_dir - direction) % TAU;
                if delta > PI {
                    delta -= TAU;
                } else if delta < -PI {
                    delta += TAU;
                }
                direction += delta * 0.3;
                // Normalize to [0, 2π).
                direction = ((direction % TAU) + TAU) % TAU;

                traj.push(TrajectoryPoint::from_fields(
                    pos_x, pos_y, vel_x, vel_y, kills, deaths, assists, direction,
                ));
            }

            trajectories.push(traj);
        }

        trajectories
    }
}

impl ManifoldScorer {
    /// Create a new scorer with an empty manifold and thresholds from `config`.
    pub fn new(config: &ReconciliationConfig) -> Self {
        Self {
            manifold: Vec::new(),
            manifold_norms: Vec::new(),
            best_score: 0.0,
            accept_threshold: config.accept_threshold,
        }
    }

    /// Flatten K trajectories into the manifold for comparison.
    ///
    /// Each inner `Vec<TrajectoryPoint>` represents one speculative trajectory.
    /// All points are appended into a single flat vector so that scoring is a
    /// simple max over a contiguous slice. Manifold point norms are pre-computed
    /// here so the per-client-point scoring pass is a tight dot-product + divide.
    pub fn set_manifold(&mut self, trajectories: &[Vec<TrajectoryPoint>]) {
        self.manifold.clear();
        let total: usize = trajectories.iter().map(|t| t.len()).sum();
        self.manifold.reserve(total);
        self.manifold_norms.clear();
        self.manifold_norms.reserve(total);
        for traj in trajectories {
            for mp in traj {
                self.manifold.push(*mp);
                // Fixed 8-wide dot — LLVM vectorizes this cleanly.
                let d = &mp.data;
                let norm_sq = d[0] * d[0]
                    + d[1] * d[1]
                    + d[2] * d[2]
                    + d[3] * d[3]
                    + d[4] * d[4]
                    + d[5] * d[5]
                    + d[6] * d[6]
                    + d[7] * d[7];
                self.manifold_norms.push(norm_sq.sqrt());
            }
        }
    }

    /// Score a single client point against every manifold point.
    ///
    /// Returns `max_j(cosine_similarity(client_point.data, manifold[j].data))`.
    /// Returns `0.0` when the manifold is empty.
    #[inline]
    pub fn score_against_manifold(&self, client_point: &TrajectoryPoint) -> f32 {
        let n = self.manifold.len();
        if n == 0 {
            return 0.0;
        }
        let cd = &client_point.data;
        let client_norm_sq = cd[0] * cd[0]
            + cd[1] * cd[1]
            + cd[2] * cd[2]
            + cd[3] * cd[3]
            + cd[4] * cd[4]
            + cd[5] * cd[5]
            + cd[6] * cd[6]
            + cd[7] * cd[7];
        let client_norm = client_norm_sq.sqrt();
        if client_norm < f32::EPSILON {
            return 0.0;
        }
        // Single fused pass: dot + divide by pre-cached manifold norms.
        // No per-iteration norm computation and no inner iterator allocations.
        let mut best = f32::NEG_INFINITY;
        for (mp, &mn) in self.manifold.iter().zip(self.manifold_norms.iter()) {
            if mn < f32::EPSILON {
                continue;
            }
            let md = &mp.data;
            let dot = cd[0] * md[0]
                + cd[1] * md[1]
                + cd[2] * md[2]
                + cd[3] * md[3]
                + cd[4] * md[4]
                + cd[5] * md[5]
                + cd[6] * md[6]
                + cd[7] * md[7];
            let s = dot / (client_norm * mn);
            if s > best {
                best = s;
            }
        }
        if best.is_finite() { best } else { 0.0 }
    }

    /// Score an entire client trajectory against the manifold.
    ///
    /// For each client point, computes the max cosine similarity across the
    /// manifold, then returns the average of those maxima.
    ///
    /// Returns `0.0` when the manifold or client trajectory is empty.
    pub fn score_trajectory(&self, client_trajectory: &[TrajectoryPoint]) -> f32 {
        if self.manifold.is_empty() || client_trajectory.is_empty() {
            return 0.0;
        }
        let sum: f32 = client_trajectory
            .iter()
            .map(|cp| self.score_against_manifold(cp))
            .sum();
        sum / client_trajectory.len() as f32
    }
}

