impl TrajectoryPoint {
    // Field indices
    pub const POS_X: usize = 0;
    pub const POS_Y: usize = 1;
    pub const VEL_X: usize = 2;
    pub const VEL_Y: usize = 3;
    pub const KILLS: usize = 4;
    pub const DEATHS: usize = 5;
    pub const ASSISTS: usize = 6;
    pub const DIRECTION: usize = 7;

    /// Create a new trajectory point from raw data.
    #[inline]
    pub const fn new(data: [f32; 8]) -> Self {
        Self { data }
    }

    /// Create a trajectory point from named fields.
    #[inline]
    #[allow(clippy::too_many_arguments)] // Named-field constructor for 8-axis trajectory point
    pub fn from_fields(
        pos_x: f32,
        pos_y: f32,
        vel_x: f32,
        vel_y: f32,
        kills: f32,
        deaths: f32,
        assists: f32,
        direction: f32,
    ) -> Self {
        Self {
            data: [
                pos_x, pos_y, vel_x, vel_y, kills, deaths, assists, direction,
            ],
        }
    }

    #[inline]
    pub fn pos_x(&self) -> f32 {
        self.data[Self::POS_X]
    }

    #[inline]
    pub fn pos_y(&self) -> f32 {
        self.data[Self::POS_Y]
    }

    #[inline]
    pub fn vel_x(&self) -> f32 {
        self.data[Self::VEL_X]
    }

    #[inline]
    pub fn vel_y(&self) -> f32 {
        self.data[Self::VEL_Y]
    }

    #[inline]
    pub fn kills(&self) -> f32 {
        self.data[Self::KILLS]
    }

    #[inline]
    pub fn deaths(&self) -> f32 {
        self.data[Self::DEATHS]
    }

    #[inline]
    pub fn assists(&self) -> f32 {
        self.data[Self::ASSISTS]
    }

    #[inline]
    pub fn direction(&self) -> f32 {
        self.data[Self::DIRECTION]
    }

    /// Position as (x, y).
    #[inline]
    pub fn position(&self) -> (f32, f32) {
        (self.data[Self::POS_X], self.data[Self::POS_Y])
    }

    /// Velocity as (vx, vy).
    #[inline]
    pub fn velocity(&self) -> (f32, f32) {
        (self.data[Self::VEL_X], self.data[Self::VEL_Y])
    }

    /// Speed magnitude.
    #[inline]
    pub fn speed(&self) -> f32 {
        let (vx, vy) = self.velocity();
        (vx * vx + vy * vy).sqrt()
    }

    /// Euclidean distance to another point (position only).
    #[inline]
    pub fn distance_to(&self, other: &Self) -> f32 {
        let dx = self.pos_x() - other.pos_x();
        let dy = self.pos_y() - other.pos_y();
        (dx * dx + dy * dy).sqrt()
    }

    /// Delta (difference) from `prev` to `self`.
    #[inline]
    pub fn delta_from(&self, prev: &Self) -> Self {
        let mut data = [0.0f32; 8];
        for (dst, (&s, &p)) in data.iter_mut().zip(self.data.iter().zip(prev.data.iter())) {
            *dst = s - p;
        }
        Self { data }
    }
}

impl ReconciliationConfig {
    /// Validate configuration parameters.
    pub fn validate(&self) -> Result<(), String> {
        if self.k == 0 {
            return Err("k must be > 0".into());
        }
        if self.max_speed <= 0.0 {
            return Err("max_speed must be > 0".into());
        }
        if self.map_bounds[0] >= self.map_bounds[2] || self.map_bounds[1] >= self.map_bounds[3] {
            return Err("map_bounds must be (min_x, min_y, max_x, max_y) with min < max".into());
        }
        if self.accept_threshold <= self.quarantine_threshold {
            return Err("accept_threshold must be > quarantine_threshold".into());
        }
        if self.kill_rate_sigma <= 0.0 {
            return Err("kill_rate_sigma must be > 0".into());
        }
        Ok(())
    }
}

impl ThinkingConfig {
    /// Bias thinking mode selection based on entropy signal.
    /// High entropy (low top-1 prob) → bias toward Latent mode.
    /// Low entropy (high top-1 prob) → bias toward Direct mode.
    #[cfg(feature = "directional_credit")]
    pub fn entropy_bias(&self, top1_prob: f32) -> ThinkingMode {
        if top1_prob < self.confidence_threshold {
            ThinkingMode::Latent
        } else {
            ThinkingMode::Direct
        }
    }
}

impl ThinkingBandit {
    fn new() -> Self {
        Self {
            successes: [1.0; 4], // Beta(1,1) = Uniform prior
            failures: [1.0; 4],
            decay: 0.99,
            total_pulls: 0,
        }
    }

    /// Thompson sample from Beta posteriors to select an arm.
    fn sample(&mut self, exploration_rate: f32, rng: &mut impl Rng) -> usize {
        self.total_pulls += 1;
        // ε-greedy: with probability ε, pick a random arm
        if rng.next_f32() < exploration_rate {
            return (rng.next_u32() as usize) % 4;
        }
        // Thompson sampling: sample from Beta(α, β) for each arm, pick max
        let mut best_arm = 0;
        let mut best_score = 0.0f32;
        for arm in 0..4 {
            let alpha = self.successes[arm];
            let beta = self.failures[arm];
            // Sample from Beta(α, β) using the ratio of Gamma variates
            // Approximation: use a simple random score weighted by α/(α+β)
            let score = sample_beta(alpha, beta, rng);
            if score > best_score {
                best_score = score;
                best_arm = arm;
            }
        }
        best_arm
    }

    #[inline]
    fn total_pulls(&self) -> u32 {
        self.total_pulls
    }

    /// Record an observation for an arm.
    fn record(&mut self, arm: usize, success: bool) {
        if success {
            self.successes[arm] += 1.0;
        } else {
            self.failures[arm] += 1.0;
        }
    }

    /// Decay old observations for recency weighting.
    fn decay_observations(&mut self) {
        let d = self.decay;
        for arm in 0..4 {
            self.successes[arm] *= d;
            self.failures[arm] *= d;
        }
    }

    /// Freeze bandit state for persistence.
    fn freeze(&self) -> ThinkingBanditFrozen {
        ThinkingBanditFrozen {
            magic: ThinkingBanditFrozen::MAGIC,
            version: ThinkingBanditFrozen::VERSION,
            successes: self.successes,
            failures: self.failures,
            total_pulls: self.total_pulls,
        }
    }

    /// Thaw bandit state from frozen form.
    fn thaw(frozen: &ThinkingBanditFrozen) -> Result<Self, String> {
        frozen.validate()?;
        Ok(Self {
            successes: frozen.successes,
            failures: frozen.failures,
            decay: 0.99,
            total_pulls: frozen.total_pulls,
        })
    }
}

impl GpuLoadSignal {
    fn is_loaded(&self, threshold: f32) -> bool {
        match self {
            GpuLoadSignal::Unavailable => false,
            GpuLoadSignal::Threshold(t) => *t >= threshold,
            GpuLoadSignal::Dynamic(load) => *load >= threshold,
        }
    }

    fn load_value(&self) -> f32 {
        match self {
            GpuLoadSignal::Unavailable => 0.0,
            GpuLoadSignal::Threshold(t) => *t,
            GpuLoadSignal::Dynamic(load) => *load,
        }
    }
}

