/// Configuration for trust-region adaptive speculation.
#[derive(Clone, Copy, Debug)]
pub struct TrustRegionConfig {
    /// Trust threshold above which window expands. Default: 0.85
    pub trust_high: f32,
    /// Trust threshold below which window contracts to 1. Default: 0.5
    pub trust_low: f32,
    /// Window expansion factor when trust is high. Default: 1.5
    pub window_expand: f32,
    /// Number of recent tokens to track for running trust. Default: 16
    pub trust_window_size: usize,
    /// Maximum binary search iterations for β blend. Default: 10
    pub blend_search_iters: usize,
    /// Target KL divergence for blend: find β where KL(μ_β || πT) = target.
    /// Default: 0.1 nats
    pub blend_kl_target: f32,
    /// Trust threshold for routing hints — below this, prefer GPU/CoT. Default: 0.4
    pub route_trust_low: f32,
    /// Trust threshold for routing hints — above this, allow CPU tier-down. Default: 0.8
    pub route_trust_high: f32,
}

impl TrustTracker {
    /// Create a new tracker with the given window size.
    pub fn new(window_size: usize) -> Self {
        let size = window_size.max(1);
        Self {
            buffer: vec![0.0; size],
            cursor: 0,
            count: 0,
            running_sum: 0.0,
        }
    }

    /// Record an acceptance probability for a token.
    ///
    /// Incremental running-sum update: O(1) instead of re-scanning the buffer
    /// on every `trust_metric()` query.
    pub fn record(&mut self, p_accept: f32) {
        // If we're overwriting an existing slot, subtract the old value first.
        if self.count == self.buffer.len() {
            self.running_sum -= self.buffer[self.cursor];
        }
        self.buffer[self.cursor] = p_accept;
        self.running_sum += p_accept;
        self.cursor = (self.cursor + 1) % self.buffer.len();
        if self.count < self.buffer.len() {
            self.count += 1;
        }
    }

    /// Get the running average trust (acceptance rate) — O(1).
    pub fn trust_metric(&self) -> f32 {
        if self.count == 0 {
            return 1.0; // No data → assume full trust (optimistic cold start)
        }
        self.running_sum / self.count as f32
    }

    /// Number of recorded samples.
    #[inline]
    pub fn sample_count(&self) -> usize {
        self.count
    }

    /// Reset the tracker.
    pub fn reset(&mut self) {
        self.cursor = 0;
        self.count = 0;
        self.running_sum = 0.0;
    }
}

impl TrustRegionState {
    /// Create new trust region state with given config.
    pub fn new(config: TrustRegionConfig) -> Self {
        let tracker = TrustTracker::new(config.trust_window_size);
        Self { tracker, config }
    }

    /// Create with default config.
    pub fn default_state() -> Self {
        Self::new(TrustRegionConfig::default())
    }

    /// Record an acceptance probability and return updated trust metric.
    pub fn record_acceptance(&mut self, p_accept: f32) -> f32 {
        self.tracker.record(p_accept);
        self.tracker.trust_metric()
    }

    /// Get current trust metric.
    pub fn trust(&self) -> f32 {
        self.tracker.trust_metric()
    }

    /// Compute adaptive window size.
    pub fn window(&self, base: usize) -> usize {
        adaptive_window(self.trust(), base, &self.config)
    }

    /// Determine if trust is low enough to warrant tier-up (CPU → GPU).
    pub fn should_tier_up(&self) -> bool {
        self.trust() < self.config.route_trust_low
    }

    /// Determine if trust is high enough to allow tier-down (GPU → CPU).
    pub fn should_tier_down(&self) -> bool {
        self.trust() > self.config.route_trust_high
    }

    /// Sample a blended token on rejection.
    pub fn blend_on_reject(&self, p_dist: &[f32], q_dist: &[f32], rng: &mut Rng) -> usize {
        let beta = find_blend_beta(
            p_dist,
            q_dist,
            self.config.blend_kl_target,
            self.config.blend_search_iters,
        );
        blend_sample(p_dist, q_dist, beta, rng)
    }

    /// Reset the trust tracker.
    pub fn reset(&mut self) {
        self.tracker.reset();
    }
}

impl TrustArm {
    /// Create a new trust arm for a domain.
    pub fn new(domain: &str, window: usize) -> Self {
        Self {
            domain: domain.to_string(),
            window,
            observations: 0,
            avg_trust: 1.0, // Optimistic cold start
            tier: 0,
        }
    }

    /// Update with a new trust observation.
    ///
    /// Uses `match` for the threshold routing (project rule) and FMA-friendly
    /// incremental EMA: `μ_new = (μ·n + x) / (n+1)` reuses one mul + one add.
    pub fn observe(&mut self, trust: f32, success: bool) {
        let n = self.observations as f32;
        self.avg_trust = (self.avg_trust * n + trust) / (n + 1.0);
        self.observations += 1;

        // Auto-adjust window based on trust trend.
        match trust {
            t if t > 0.85 => self.window = (self.window + 1).min(32),
            t if t < 0.5 => self.window = self.window.saturating_sub(1).max(1),
            _ => {}
        }

        // Auto-adjust tier based on trust.
        match trust {
            t if t < 0.4 => self.tier = self.tier.saturating_add(1).min(2),
            t if t > 0.8 && self.tier > 0 => self.tier = self.tier.saturating_sub(1),
            _ => {}
        }

        let _ = success; // Track for future reward shaping
    }

    /// Serialize to bytes for freeze/thaw persistence.
    pub fn to_bytes(&self) -> Vec<u8> {
        let mut buf = Vec::with_capacity(self.domain.len() + 24);
        let domain_bytes = self.domain.as_bytes();
        buf.extend_from_slice(&(domain_bytes.len() as u32).to_le_bytes());
        buf.extend_from_slice(domain_bytes);
        buf.extend_from_slice(&self.avg_trust.to_le_bytes());
        buf.extend_from_slice(&(self.window as u32).to_le_bytes());
        buf.extend_from_slice(&self.tier.to_le_bytes());
        buf.extend_from_slice(&(self.observations as u32).to_le_bytes());
        buf
    }

    /// Deserialize from bytes.
    pub fn from_bytes(data: &[u8]) -> Option<Self> {
        if data.len() < 4 {
            return None;
        }
        let domain_len = u32::from_le_bytes(data[0..4].try_into().ok()?) as usize;
        let domain_start = 4;
        let domain_end = domain_start + domain_len;
        if data.len() < domain_end + 13 {
            return None;
        }
        let domain = std::str::from_utf8(&data[domain_start..domain_end])
            .ok()?
            .to_string();
        let avg_trust = f32::from_le_bytes(data[domain_end..domain_end + 4].try_into().ok()?);
        let window =
            u32::from_le_bytes(data[domain_end + 4..domain_end + 8].try_into().ok()?) as usize;
        let tier = data[domain_end + 8];
        let observations =
            u32::from_le_bytes(data[domain_end + 9..domain_end + 13].try_into().ok()?) as usize;
        Some(Self {
            domain,
            avg_trust,
            window,
            tier,
            observations,
        })
    }
}

use super::types::{BpeTokenizer, MergeRule};
use std::collections::HashMap;

/// BPE encoder/decoder implementation.
pub struct BpeTokenizerImpl;

impl BpeTokenizerImpl {
    /// Encode a string into token IDs using BPE merge rules.
    ///
    /// Hot-path design: operates on `Vec<usize>` (token IDs) end-to-end. The
    /// merge-rank lookup uses `merge_ranks_id: HashMap<(usize, usize), usize>`
    /// — no `String` allocation per pair. The replacement ID is resolved via
    /// `merge_target_id[rank]` — no `vocab_to_id` lookup per merge pass.
    ///
    /// Per AGENTS.md hot-loop rules: no allocation inside the merge loop.
    /// The only allocation is the initial char→ID map and the two ping-pong
    /// token buffers, both pre-sized.
    pub fn encode(tokenizer: &BpeTokenizer, text: &str) -> Vec<usize> {
        if text.is_empty() {
            return Vec::new();
        }

        // Map each char to its token ID up front. Unknown chars map to `unk`.
        // Uses a fixed-size stack buffer (`encode_utf8` writes ≤4 bytes) —
        // zero heap allocation for the entire char→ID map step.
        let unk = tokenizer.unk_id();
        let char_count = text.chars().count();
        let mut tokens: Vec<usize> = Vec::with_capacity(char_count);
        let mut buf = [0u8; 4];
        for c in text.chars() {
            let s = c.encode_utf8(&mut buf);
            let id = tokenizer.vocab_to_id.get(s).copied().unwrap_or(unk);
            tokens.push(id);
        }

        // Fast path: no merges configured (or tables not rebuilt).
        if tokenizer.merge_ranks_id.is_empty() {
            return tokens;
        }

        let mut new_tokens: Vec<usize> = Vec::with_capacity(tokens.len());

        // Iteratively merge the highest-priority (lowest-rank) pair.
        loop {
            // Find the lowest-rank applicable merge across all adjacent pairs.
            // `windows(2)` lets LLVM drop the per-iteration bounds check on
            // `tokens[i + 1]` that the manual index loop forces.
            let mut best: Option<(usize, usize)> = None; // (rank, left_idx)
            for (i, w) in tokens.windows(2).enumerate() {
                if let Some(&rank) = tokenizer.merge_ranks_id.get(&(w[0], w[1])) {
                    match best {
                        Some((best_rank, _)) if best_rank <= rank => {}
                        _ => best = Some((rank, i)),
                    }
                }
            }

            let Some((best_rank, left_idx)) = best else {
                break;
            };

            // Resolve the merged token ID via the rank-indexed table — no
            // hashmap lookup, just a slice index.
            let merged_id = tokenizer.merge_target_id[best_rank];
            let left_id = tokens[left_idx];
            let right_id = tokens[left_idx + 1];

            // Apply the merge to all adjacent occurrences of (left, right).
            // Indices are `usize` (Copy) — zero allocation in this loop.
            new_tokens.clear();
            let mut i = 0;
            while i < tokens.len() {
                if i + 1 < tokens.len() && tokens[i] == left_id && tokens[i + 1] == right_id {
                    new_tokens.push(merged_id);
                    i += 2;
                } else {
                    new_tokens.push(tokens[i]);
                    i += 1;
                }
            }
            std::mem::swap(&mut tokens, &mut new_tokens);
        }

        tokens
    }

use serde::{Deserialize, Serialize};
use std::collections::HashMap;

/// BPE tokenizer with vocabulary and merge rules.
#[derive(Clone, Serialize, Deserialize)]
pub struct BpeTokenizer {
    /// Token string → ID mapping.
    #[serde(with = "map_serde")]
    pub vocab_to_id: HashMap<String, usize>,
    /// ID → token string mapping.
    pub id_to_vocab: Vec<String>,
    /// Ordered merge rules: apply in this order during encoding.
    pub merges: Vec<MergeRule>,
    /// Merge rule → rank (index in merges vec) for fast lookup.
    #[serde(skip)]
    pub merge_ranks: HashMap<(String, String), usize>,
    /// ID-pair → merge rank (lower = higher priority). Hot-path lookup table
    /// for `encode`, which operates on `Vec<usize>` end-to-end and avoids
    /// per-pair `String` allocations. Kept in sync with `merge_ranks` by
    /// `rebuild_ranks`.
    #[serde(skip)]
    pub merge_ranks_id: HashMap<(usize, usize), usize>,
    /// `merge_target_id[rank]` = merged token ID for the rule at that rank.
    /// Indexed by rank so `encode` can resolve the replacement with a single
    /// indexed load instead of a `vocab_to_id` lookup per merge pass.
    #[serde(skip)]
    pub merge_target_id: Vec<usize>,
    /// Beginning-of-sequence token ID.
    pub bos_id: usize,
    /// End-of-sequence token ID.
    pub eos_id: usize,
    /// Padding token ID.
    pub pad_id: usize,
}

/// A single BPE merge rule.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct MergeRule {
    pub left: String,
    pub right: String,
    pub merged: String,
}

impl BpeTokenizer {
    /// Unknown token ID (last entry in vocabulary).
    pub fn unk_id(&self) -> usize {
        self.id_to_vocab.len().saturating_sub(1)
    }

