    /// Validate a code fragment for bracket balance.
    /// Returns `true` if the fragment is potentially valid (no obvious errors).
    /// Returns `false` if clearly broken (e.g., `}

impl SynPruner {
    pub fn new(tokenizer: Arc<BpeTokenizer>) -> Self {
        Self { tokenizer }
    }

    /// Validate a complete code string through both tiers.
    pub fn validate(&self, code: &str) -> PruneResult {
        // Tier 0: Bracket balance
        let tier0_ok = PARSER.with(|p| p.borrow_mut().is_valid(code));
        if !tier0_ok {
            return PruneResult {
                is_valid: false,
                error_kind: super::types::ErrorKind::UnbalancedBrackets,
            };
        }

        // Tier 1: syn parse
        match syn::parse_str::<syn::Stmt>(code) {
            Ok(_) => PruneResult {
                is_valid: true,
                error_kind: super::types::ErrorKind::None,
            },
            Err(e) => PruneResult {
                is_valid: false,
                error_kind: super::types::ErrorKind::SynError(e.to_string()),
            },
        }
    }

    /// Quick Tier 0 check only (for DDTree hot path).
    pub fn is_valid_quick(&self, code: &str) -> bool {
        PARSER.with(|p| p.borrow_mut().is_valid(code))
    }
}

impl CompilerFeedback {
    /// Extract a suggestion from a syn error message.
    pub fn extract_suggestion(error_msg: &str) -> Option<String> {
        // syn errors sometimes contain "expected X" patterns
        if error_msg.contains("expected") {
            let start = error_msg.find("expected")?;
            Some(error_msg[start..].to_string())
        } else {
            None
        }
    }

    /// Convert to context string for inclusion in prompt.
    pub fn to_context(&self) -> String {
        let mut ctx = format!("Error: {}", self.error_message);
        if let Some(suggestion) = &self.suggestion {
            ctx.push_str(&format!("\nSuggestion: {suggestion}"));
        }
        ctx
    }
}

