/// Saved activations from forward pass, needed for backward.
///
/// Borrows from `ForwardSaveContext` to avoid cloning all activations (Issue 110).
///
/// Field order: all references (8-byte) grouped, then usize to eliminate padding.
struct ForwardActivations<'a> {
    embeddings: &'a [f32],     // [seq_len * n]
    after_norm1: &'a [f32],    // [seq_len * n] (= xr residual)
    after_norm2: &'a [f32],    // [seq_len * n]
    q: &'a [f32],              // [seq_len * n]
    k: &'a [f32],              // [seq_len * kvd]
    v: &'a [f32],              // [seq_len * kvd]
    attn_weights: &'a [f32],   // [seq_len * n_head * seq_len]
    attn_out: &'a [f32],       // [seq_len * n]
    after_attn_res: &'a [f32], // [seq_len * n]
    after_mlp_norm: &'a [f32], // [seq_len * n]
    mlp_hidden: &'a [f32],     // [seq_len * mlp_hidden]
    hidden_final: &'a [f32],   // [seq_len * n]
    logits: &'a [f32],         // [seq_len * vocab_size]
    seq_len: usize,
}

/// Pre-allocated context for `forward_save`, avoiding per-call allocations.
///
/// Field order: all Vec<f32> (24-byte, 8-byte aligned) before usize fields
/// to eliminate inter-field padding.
struct ForwardSaveContext {
    // Vec fields grouped first (all 24 bytes, 8-byte aligned)
    embeddings: Vec<f32>,
    after_norm1: Vec<f32>,
    after_norm2: Vec<f32>,
    q_all: Vec<f32>,
    k_all: Vec<f32>,
    v_all: Vec<f32>,
    attn_weights_all: Vec<f32>,
    attn_out_all: Vec<f32>,
    after_attn_res: Vec<f32>,
    after_mlp_norm: Vec<f32>,
    mlp_hidden_all: Vec<f32>,
    hidden_final: Vec<f32>,
    logits_all: Vec<f32>,
    // Per-position scratch (reused each iteration)
    x_buf: Vec<f32>,
    x_proj_buf: Vec<f32>,
    x_mlp_buf: Vec<f32>,
    // Attention scratch (reused across positions, avoids per-position allocation)
    attn_scratch_out: Vec<f32>,
    attn_scratch_weights: Vec<f32>,
    attn_scratch_scores: Vec<f32>,
    // usize fields last (8-byte aligned)
    // Dimension constants cached from config
    n: usize,
    kvd: usize,
    vocab_size: usize,
    mlp_hidden: usize,
    n_head: usize,
    seq_len: usize,
}

impl ForwardSaveContext {
    fn new(config: &Config) -> Self {
        let n = config.n_embd;
        let kvd = kv_dim(config);
        let bs = config.block_size;
        Self {
            embeddings: vec![0.0f32; bs * n],
            after_norm1: vec![0.0f32; bs * n],
            after_norm2: vec![0.0f32; bs * n],
            q_all: vec![0.0f32; bs * n],
            k_all: vec![0.0f32; bs * kvd],
            v_all: vec![0.0f32; bs * kvd],
            attn_weights_all: vec![0.0f32; bs * config.n_head * bs],
            attn_out_all: vec![0.0f32; bs * n],
            after_attn_res: vec![0.0f32; bs * n],
            after_mlp_norm: vec![0.0f32; bs * n],
            mlp_hidden_all: vec![0.0f32; bs * config.mlp_hidden],
            hidden_final: vec![0.0f32; bs * n],
            logits_all: vec![0.0f32; bs * config.vocab_size],
            x_buf: vec![0.0f32; n],
            x_proj_buf: vec![0.0f32; n],
            x_mlp_buf: vec![0.0f32; n],
            attn_scratch_out: vec![0.0f32; n],
            attn_scratch_weights: vec![0.0f32; config.n_head * bs],
            attn_scratch_scores: vec![0.0f32; bs],
            n,
            kvd,
            vocab_size: config.vocab_size,
            mlp_hidden: config.mlp_hidden,
            n_head: config.n_head,
            seq_len: 0,
        }
    }

use plotters::prelude::*;

/// Plot benchmark results as a horizontal bar chart SVG.
///
/// Each bar is colored per `BenchResult::color` with throughput + μs/step annotation.
pub fn plot_results(
    results: &[BenchResult],
    path: &str,
    title: &str,
    x_label: &str,
) -> Result<(), Box<dyn std::error::Error>> {
    let n = results.len();
    if n == 0 {
        let root = SVGBackend::new(path, (800, 200)).into_drawing_area();
        root.fill(&WHITE)?;
        let style = TextStyle::from(("sans-serif", 18).into_font()).color(&BLACK);
        root.draw_text("No benchmark results", &style, (10, 80))?;
        root.present()?;
        return Ok(());
    }

    let max_tp = results.iter().map(|r| r.throughput).fold(0.0f64, f64::max);
    if max_tp <= 0.0 {
        let root = SVGBackend::new(path, (800, 200)).into_drawing_area();
        root.fill(&WHITE)?;
        root.present()?;
        return Ok(());
    }

    // Dynamic sizing: wider for labels, taller for more results
    let bar_px = 30;
    let gap_px = 10;
    let img_w = 1100;
    let img_h: u32 = (70 + n * (bar_px + gap_px) + 30) as u32;
    let max_val = max_tp * 1.45; // 45% room for annotations

    let root = SVGBackend::new(path, (img_w, img_h)).into_drawing_area();
    root.fill(&WHITE)?;

    // Y axis: bar i centered at integer y=i, labels at each integer tick
    let y_lo = -0.5f64;
    let y_hi = n as f64 - 0.5;

    let mut chart = ChartBuilder::on(&root)
        .caption(title, ("sans-serif", 22).into_font())
        .margin(10)
        .y_label_area_size(200)
        .x_label_area_size(45)
        .build_cartesian_2d(0f64..max_val, y_lo..y_hi)?;

    chart
        .configure_mesh()
        .y_label_formatter(&|&y: &f64| -> String {
            let idx = y.round() as i64;
            if idx >= 0 && (idx as usize) < n {
                results[idx as usize].label.clone()
            } else {
                String::new()
            }
        })
        .y_labels(n)
        .x_desc(x_label)
        .x_label_style(("sans-serif", 11).into_font())
        .y_label_style(("sans-serif", 11).into_font())
        .draw()?;

    for (i, result) in results.iter().enumerate() {
        let y = i as f64;
        let (cr, cg, cb) = result.color;
        let color = RGBColor(cr, cg, cb);

        // Draw horizontal bar (slightly narrower than full slot for visual gap)
        chart.draw_series(std::iter::once(Rectangle::new(
            [(0.0, y - 0.4), (result.throughput, y + 0.4)],
            color.filled(),
        )))?;

        // Format throughput with unit suffix into a single String (avoids
        // intermediate `tp_str` allocation before composing the label).
        let tp = result.throughput;
        let label = if tp >= 1_000_000.0 {
            format!(
                "{:.2}M  ({:.2} μs)",
                tp / 1_000_000.0,
                result.time_per_step_us
            )
        } else if tp >= 1_000.0 {
            format!("{:.0}K  ({:.2} μs)", tp / 1_000.0, result.time_per_step_us)
        } else {
            format!("{:.0}  ({:.2} μs)", tp, result.time_per_step_us)
        };

        // Place text just past the bar end
        let text_x = result.throughput + max_val * 0.012;
        chart.draw_series(std::iter::once(Text::new(
            label,
            (text_x, y),
            ("sans-serif", 12).into_font(),
        )))?;
    }

    root.present()?;
    Ok(())
}

