            #[cfg(feature = "retrieval")]
            retrieval: None,
        }
    }

    pub fn with_max_rounds(mut self, n: u32) -> Self {
        self.max_rounds = n;
        self
    }

    /// Attach a custom [`DirectionSource`] for context direction construction.
    ///
    /// When set, `run_to_completion` recomputes the context direction each
    /// round via `source.context_direction(&graph)` instead of the modelless
    /// `context_from_graph` free function. The task directions (`latent_dir`)
    /// are NOT affected — they're set at task construction time via
    /// [`crate::Task::new_todo_with_source`].
    pub fn with_direction_source(
        mut self,
        source: Box<dyn crate::latent::DirectionSource>,
    ) -> Self {
        self.direction_source = Some(source);
        self
    }

    /// Attach a [`RetrievalProvider`](crate::retrieval::RetrievalProvider) for
    /// RAG context retrieval (Plan 524 Phase 5). When set, the caller can use
    /// [`Agent::retrieve`] to fetch context chunks for a task before acting.
    ///
    /// Default `None` — most agents don't need RAG context. Only available
    /// behind the `retrieval` feature.
    #[cfg(feature = "retrieval")]
    pub fn with_retrieval(
        mut self,
        provider: Box<dyn crate::retrieval::RetrievalProvider>,
    ) -> Self {
        self.retrieval = Some(provider);
        self
    }

    /// Retrieve context chunks for a query (Plan 524 Phase 5). Returns `None`
    /// if no retrieval provider is attached. The caller typically does:
    /// 1. Agent emits `Action::Retrieve { task_id, query, budget }`
    /// 2. Caller calls `agent.retrieve(&query, budget)`
    /// 3. Caller pushes the results into `Context::retrieved_context`
    /// 4. Caller re-invokes `reason`.
    #[cfg(feature = "retrieval")]
    pub fn retrieve(
        &self,
        query: &crate::retrieval::LatentQuery,
        budget: crate::retrieval::TokenBudget,
    ) -> Option<Vec<crate::retrieval::RetrievedChunk>> {
        self.retrieval.as_ref().map(|p| p.retrieve(query, budget))
    }

    /// Run the agent to completion on a graph. Returns the final round count
    /// + whether all tasks reached a terminal state.
    ///
    /// The caller passes a `execute` closure that actually performs actions
    /// (e.g. marks tasks done, retries failed tasks). This keeps the agent
    /// pure — it doesn't touch the task store directly.
    pub fn run_to_completion<F>(
        &self,
        mut ctx: Context,
        mut execute: F,
    ) -> (u32, bool)
    where
        F: FnMut(&Action, &mut Context) -> bool,
    {
        let mut rounds = 0u32;
        loop {
            rounds += 1;
            if rounds > self.max_rounds {
                return (rounds, false); // budget exhausted — likely a cycle
            }

            ctx.graph.refresh_ready();
            ctx.context_dir = match &self.direction_source {
                Some(src) => src.context_direction(&ctx.graph),
                None => crate::latent::context_from_graph(&ctx.graph),
            };
            ctx.round = rounds;

            let output = self.reasoner.reason(&ctx);

            if output.actions.is_empty() || output.actions.iter().all(|a| *a == Action::Replan) {
                // No actionable output — either done or stuck.
                return (rounds, ctx.graph.active_count() == 0);
            }

            let mut any_progress = false;
            for action in &output.actions {
                if execute(action, &mut ctx) {
                    any_progress = true;
                }
            }

            if !any_progress {
                // No action made progress — stuck. Prevent infinite loop.
                return (rounds, false);
            }
        }
    }
}

