/// Agent identifier — stable across the communication graph (vertex index).
pub type AgentIdx = usize;

/// BLAKE3-committed receipt for a consensus-decided action. Crosses the sync
/// boundary as raw values (task_id, status, round, co-agent ids) + a 32-byte
/// commitment. The chain's quorum consensus validates the commitment.
///
/// **Domain classification (AGENTS.md §"Latent vs Raw Space Rules"):** the
/// receipt is RAW (deterministic, replayable, anti-cheat-checkable). The
/// latent reasoning that produced it (direction scoring, strategy deliberation)
/// stays local to the agent and never crosses the sync boundary.
///
/// **Bridge pattern:** latent → raw. The consensus direction (latent) is
/// projected to a discrete task id + status (raw) via argmax. Zero latent
/// information leaks — only the decision.
#[derive(Clone, Debug)]
pub struct AgentActionReceipt {
    /// The agent that committed (vertex index in the communication graph).
    pub agent_idx: AgentIdx,
    /// The task the agent will execute.
    pub task_id: TaskId,
    /// Encoded [`Action`] variant: 0 = StartTask, 1 = CompleteTask,
    /// 2 = FailTask, 3 = Replan. Raw u8 for compact wire format.
    pub action_code: u8,
    /// Consensus round when this receipt was produced.
    pub round: u32,
    /// All agents that participated in this consensus round (sorted ascending).
    /// Anti-cheat: a receipt claiming consensus among agents that weren't
    /// online is rejected by the quorum check.
    ///
    /// Stored as `Arc<[AgentIdx]>` rather than `Vec<AgentIdx>` because all
    /// receipts in a round share the same participant set — `Arc` lets the N
    /// receipts share one allocation (1 alloc/round, not N). `Arc<[T]>`
    /// auto-derefs to `&[T]` so readers (`verify_commitment`, hashing, debug)
    /// are unchanged. (Plan 523 T3.6 — alloc-free hot path.)
    pub participant_indices: Arc<[AgentIdx]>,
    /// BLAKE3 commitment of `(agent_idx, task_id, action_code, round,
    /// participant_indices)`. The chain validates this matches a recomputed
    /// hash — any field tampering invalidates the receipt.
    pub commitment: [u8;

impl Task {
    /// Convert to a ShardRow for persistence. The title + deps are stored
    /// separately (title is skipped on the row; deps are edge rows).
    pub fn to_row(&self) -> (AgentTaskRow, Vec<AgentEdgeRow>) {
        let row = AgentTaskRow {
            task_id: self.id,
            title: String::new(), // skipped on encode; recovered from external source
            kind_raw: self.kind as u8 as i64,
            status_raw: self.status as u8 as i64,
            priority: self.priority,
            effort: self.effort,
            latent_0: self.latent_dir[0],
            latent_1: self.latent_dir[1],
            latent_2: self.latent_dir[2],
            latent_3: self.latent_dir[3],
        };
        let edges: Vec<AgentEdgeRow> = self
            .deps
            .iter()
            .enumerate()
            .map(|(i, dep)| AgentEdgeRow {
                edge_id: self.id * 1000 + i as i64,
                from_id: *dep,
                to_id: self.id,
            })
            .collect();
        (row, edges)
    }

    /// Reconstruct a Task from a row + its dependency edges.
    /// The title is NOT stored in the shard (it's skipped) — pass it back
    /// in via the `titles` map (keyed by task_id). If missing, title = "".
    pub fn from_row(
        row: &AgentTaskRow,
        edges: &[AgentEdgeRow],
        titles: &std::collections::HashMap<TaskId, String>,
    ) -> Self {
        let kind = match row.kind_raw as u8 {
            1 => TaskKind::Todo,
            2 => TaskKind::TrainStep,
            3 => TaskKind::GameCommand,
            4 => TaskKind::CodeRefactor,
            _ => TaskKind::Custom,
        };
        let status = match row.status_raw as u8 {
            0 => TaskStatus::Pending,
            1 => TaskStatus::Ready,
            2 => TaskStatus::InProgress,
            3 => TaskStatus::Done,
            4 => TaskStatus::Failed,
            _ => TaskStatus::Blocked,
        };
        let deps: Vec<TaskId> = edges
            .iter()
            .filter(|e| e.to_id == row.task_id)
            .map(|e| e.from_id)
            .collect();
        let title = titles.get(&row.task_id).cloned().unwrap_or_default();
        // Reconstruct the latent direction. Only dims 0-3 are stored; dims 4-7
        // are reconstructed deterministically from the title (modelless path —
        // the full 8-dim direction is recoverable because the title hash
        // perturbation is deterministic).
        let latent_dir = if title.is_empty() {
            // No title — use the stored 4 dims + zeros for 4-7.
            let mut d = [0.0f32; 8];
            d[0] = row.latent_0;
            d[1] = row.latent_1;
            d[2] = row.latent_2;
            d[3] = row.latent_3;
            d
        } else {
            // Full reconstruction via the deterministic direction constructor.
            crate::latent::task_direction(kind, row.priority, row.effort, title.as_bytes())
        };
        Self {
            id: row.task_id,
            kind,
            status,
            latent_dir,
            title,
            deps,
            effort: row.effort,
            priority: row.priority,
        }
    }
}

impl TaskStore {
    /// Open an in-memory store (no persistence). Useful for tests + demos.
    pub fn open_in_memory() -> Self {
        // Tag-uniqueness startup check (Issue 025).
        let _ = (AgentTaskRow::ensure_tag_unique(), AgentEdgeRow::ensure_tag_unique());
        Self {
            index: riir_neuron_db::ShardIndex::from_shards(vec![]),
            session: LocalKvStore::open_in_memory(),
            titles: std::collections::HashMap::new(),
        }
    }

    /// Open a persistent store (encrypted WAL on disk).
    pub fn open_dir(dir: &std::path::Path, passphrase: &str) -> Self {
        let _ = (AgentTaskRow::ensure_tag_unique(), AgentEdgeRow::ensure_tag_unique());
        Self {
            index: riir_neuron_db::ShardIndex::from_shards(vec![]),
            session: LocalKvStore::open_dir(dir, passphrase).expect("open Warm tier"),
            titles: std::collections::HashMap::new(),
        }
    }

    /// Insert a task (encodes to shards + inserts into the index).
    pub fn put_task(&mut self, task: &Task) {
        let (row, edges) = task.to_row();
        self.titles.insert(task.id, task.title.clone());
        let guard = self.index.guard();
        self.index.insert(row.encode_to_shard(), &guard);
        for edge in edges {
            self.index.insert(edge.encode_to_shard(), &guard);
        }
    }

    /// Mark a task's status in the index.
    pub fn set_status(&mut self, id: TaskId, status: TaskStatus) {
        let guard = self.index.guard();
        // Fetch the row, update status, re-insert.
        if let Some(row) =
            neuron_db_sdk::ShardQuery::<AgentTaskRow>::pk(id).fetch_one(&self.index, &guard)
        {
            let mut updated = row;
            updated.status_raw = status as u8 as i64;
            self.index.insert(updated.encode_to_shard(), &guard);
        }
    }

    /// Load the full task graph from the index.
    pub fn load_graph(&self) -> TaskGraph {
        let guard = self.index.guard();
        let rows: Vec<AgentTaskRow> = self
            .index
            .iter_shards(&guard)
            .filter(|s| s.zone_hash[4] == AgentTaskRow::TAG)
            .map(AgentTaskRow::decode_from_shard)
            .collect();
        let edges: Vec<AgentEdgeRow> = self
            .index
            .iter_shards(&guard)
            .filter(|s| s.zone_hash[4] == AgentEdgeRow::TAG)
            .map(AgentEdgeRow::decode_from_shard)
            .collect();
        let tasks: Vec<Task> = rows
            .iter()
            .map(|row| Task::from_row(row, &edges, &self.titles))
            .collect();
        TaskGraph::with_tasks(tasks)
    }

    /// Save a reasoning record to the encrypted Warm tier.
    pub fn save_reasoning(&self, round: u32, output: &ReasoningOutput) {
        let strategy_tag = match output.strategy {
            crate::agent::Strategy::Serial => 0u8,
            crate::agent::Strategy::Parallel { .. } => 1,
            crate::agent::Strategy::Loop { .. } => 2,
            crate::agent::Strategy::Routine { .. } => 3,
        };
        let strategy_param = match output.strategy {
            crate::agent::Strategy::Parallel { width } => width as u8,
            crate::agent::Strategy::Loop { max_iters } => max_iters as u8,
            _ => 0,
        };
        let first_action_task_id = output
            .actions
            .iter()
            .find_map(|a| match a {
                crate::agent::Action::StartTask(id) => Some(*id),
                _ => None,
            })
            .unwrap_or(-1);
        let rationale_hash = rationale_blake3(&output.rationale);
        let record = ReasoningRecord {
            round,
            strategy_tag,
            strategy_param,
            action_count: output.actions.len() as u8,
            confidence_u8: (output.confidence * 255.0) as u8,
            first_action_task_id,
            rationale_hash,
        };
        let key = format!("reasoning\0{round}");
        self.session
            .put_pod(key.as_bytes(), &record)
            .expect("save reasoning record");
    }

    /// Load all reasoning records (sorted by round).
    pub fn load_reasoning_history(&self) -> Vec<ReasoningRecord> {
        self.session
            .scan_prefix_bytes(b"reasoning\0")
            .into_iter()
            .filter_map(|(_k, v)| {
                if v.len() >= std::mem::size_of::<ReasoningRecord>() {
                    let r: &ReasoningRecord = bytemuck::from_bytes(&v);
                    Some(*r)
                } else {
                    None
                }
            })
            .collect()
    }
}

