/// Task identifier. Stable across persistence (it's the ShardRow primary key).
pub type TaskId = i64;

impl TaskStatus {
    #[inline]
    pub fn is_terminal(self) -> bool {
        matches!(self, Self::Done | Self::Failed | Self::Blocked)
    }

    #[inline]
    pub fn is_ready_eligible(self) -> bool {
        self == Self::Ready
    }
}

impl TaskGraph {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn with_tasks(tasks: Vec<Task>) -> Self {
        Self { tasks }
    }

    pub fn add(&mut self, task: Task) {
        self.tasks.push(task);
    }

    /// Compute readiness: a task is Ready iff all its deps are Done.
    /// Updates `status` in place for all Pending tasks. O(T * D) where
    /// T = task count, D = max dep count.
    ///
    /// This is the constraint-intersection check — the `HyperplanePruner`
    /// pattern applied to the task graph. Each dependency is a constraint
    /// ("dep must be Done"); the task is ready iff ALL constraints hold.
    pub fn refresh_ready(&mut self) {
        let done_ids: Vec<TaskId> = self
            .tasks
            .iter()
            .filter(|t| t.status == TaskStatus::Done)
            .map(|t| t.id)
            .collect();

        for t in self.tasks.iter_mut() {
            if t.status != TaskStatus::Pending {
                continue;
            }
            // Intersection check: ALL deps must be in the done set.
            let all_deps_done = t.deps.iter().all(|dep| done_ids.contains(dep));
            if all_deps_done {
                t.status = TaskStatus::Ready;
            }
        }
    }

    /// Tasks currently in Ready status.
    pub fn ready_tasks(&self) -> Vec<&Task> {
        self.tasks
            .iter()
            .filter(|t| t.status.is_ready_eligible())
            .collect()
    }

    /// Tasks in Failed status (candidates for the Loop strategy).
    pub fn failed_tasks(&self) -> Vec<&Task> {
        self.tasks
            .iter()
            .filter(|t| t.status == TaskStatus::Failed)
            .collect()
    }

    /// Count of tasks NOT in a terminal state.
    pub fn active_count(&self) -> usize {
        self.tasks
            .iter()
            .filter(|t| !t.status.is_terminal())
            .count()
    }

    /// Get a task by ID (linear scan — task graphs are small for reasoning).
    pub fn get(&self, id: TaskId) -> Option<&Task> {
        self.tasks.iter().find(|t| t.id == id)
    }

    pub fn get_mut(&mut self, id: TaskId) -> Option<&mut Task> {
        self.tasks.iter_mut().find(|t| t.id == id)
    }

    /// Mark a task Done + return IDs of tasks that became ready as a result.
    /// Does NOT call `refresh_ready` — caller decides when to refresh.
    pub fn mark_done(&mut self, id: TaskId) -> Vec<TaskId> {
        if let Some(t) = self.get_mut(id) {
            t.status = TaskStatus::Done;
        }
        // Find tasks that were Pending and now have all deps Done.
        let done_ids: Vec<TaskId> = self
            .tasks
            .iter()
            .filter(|t| t.status == TaskStatus::Done)
            .map(|t| t.id)
            .collect();
        self.tasks
            .iter_mut()
            .filter(|t| t.status == TaskStatus::Pending)
            .filter(|t| t.deps.iter().all(|dep| done_ids.contains(dep)))
            .map(|t| {
                t.status = TaskStatus::Ready;
                t.id
            })
            .collect()
    }

    /// Mark a task Failed (candidate for retry via Loop strategy).
    pub fn mark_failed(&mut self, id: TaskId) {
        if let Some(t) = self.get_mut(id) {
            t.status = TaskStatus::Failed;
        }
    }

    /// Whether the ready set has independent tasks (no shared deps among them).
    /// Used by the strategy selector: independent ready tasks → Parallel.
    pub fn ready_are_independent(&self) -> bool {
        let ready: Vec<&Task> = self.ready_tasks();
        if ready.len() < 2 {
            return false;
        }
        // Collect all dep IDs across ready tasks. If any dep appears in 2+
        // ready tasks' dep lists, they share a dependency → not independent.
        let mut dep_set: Vec<TaskId> = Vec::new();
        for t in &ready {
            for dep in &t.deps {
                if dep_set.contains(dep) {
                    return false;
                }
                dep_set.push(*dep);
            }
        }
        true
    }
}

impl ThinkBrain for MerchantCognition {
    fn name(&self) -> &str {
        "merchant_cognition"
    }
    fn version(&self) -> (u8, u8, u8) {
        (1, 0, 0)
    }

    fn cog_init(&mut self) {
        *self = Self::default();
    }

    fn cog_observe(&mut self, target_id: u32, _x: f32, _y: f32, visible: bool) {
        // Fog-of-war contract: hidden targets are passed with sentinel
        // coordinates (0, 0). The module MUST NOT treat them as a real
        // observation — only `visible` gates the belief update.
        if visible {
            self.last_visible_target = Some(target_id);
            // Sigmoid-shaped increment: each visible encounter nudges calm
            // up by a small, bounded amount. Sigmoid not softmax (global rule).
            self.calm = (self.calm + 0.05).min(1.0);
        }
    }

    fn cog_tick(&mut self, _zone_attention: &mut [f32; 8], affect: &mut AffectScalars) {
        self.tick_count = self.tick_count.saturating_add(1);

        // Sigmoid projection of the calm baseline onto the affect scalar.
        // `affect.calm ∈ (0, 1)` by sigmoid's range.
        affect.calm = 1.0 / (1.0 + (-self.calm).exp());

        // Default the other 4 affect scalars to neutral 0.5 — the reference
        // module only models calm. Real modules would project each onto its
        // own direction vector.
        affect.valence = 0.5;
        affect.arousal = 0.5;
        affect.desperation = 0.5;
        affect.fear = 0.5;
    }

    fn cog_emit_kg_triple(&mut self) -> Option<KgTriple> {
        // Emit a "merchant met target" triple if we observed a visible
        // target this tick. Confidence is the current calm baseline.
        self.last_visible_target.take().map(|target| KgTriple {
            subject: 1,        // merchant (game-defined enum)
            predicate: 1,      // "met"
            object: target,    // the observed target
            confidence: self.calm,
        })
    }
}

