impl ComparisonReport {
    /// Check if ConvexTok result is a stub (feature was off or training failed).
    #[inline]
    pub fn is_convex_stub(&self) -> bool {
        self.convex.n_tokens == 0
    }

    /// Compute compression improvement ratio (BPE tokens / Convex tokens).
    /// Returns 0.0 if ConvexTok is a stub.
    pub fn compression_improvement(&self) -> f64 {
        match (self.bpe.n_tokens, self.convex.n_tokens) {
            (_, 0) | (0, _) => 0.0,
            (bpe_tokens, convex_tokens) => {
                let bpe_ratio = bpe_tokens as f64 / self.original_bytes as f64;
                let convex_ratio = convex_tokens as f64 / self.original_bytes as f64;
                if convex_ratio > 0.0 {
                    (bpe_ratio - convex_ratio) / bpe_ratio
                } else {
                    0.0
                }
            }
        }
    }
}

