/// Number of game LoRA models the corpus covers (Bomber, Go, Civ, FFT).
pub const N_GAME_DOMAINS: usize = 4;

/// Default samples per domain (Plan 297 T-D.1: "1000 (KV, Qref) pairs").
pub const DEFAULT_SAMPLES_PER_DOMAIN: usize = 1000;

/// Number of attention heads modeled per KV cache. Matches the 8-head
/// convention used by `crates/riir-games/tests/goat_297_phase_a_gates.rs`
/// and `DIRECTION_VECTOR_DIM / head_dim = 64 / 8`.
pub const N_HEADS: usize = 8;

/// Per-head key dimension. Real multi-head attention splits `d_model`
/// across heads; with `d_model = 64` and `N_HEADS = 8` this is `64/8 = 8`.
/// AM runs **per head** with `d = HEAD_DIM` — same convention as Phase A's
/// `KatgptTrajectoryCompactor` (per-head `compact()` calls, results
/// concatenated).
pub const HEAD_DIM: usize = 8;

/// Per-head feature dimension. Matches T-D.2 spec: "pooled KV statistics
/// (mean, variance, top-k attention scores per head)". With `TOP_K = 8`
/// this is `4 + 8 = 12` per head (Issue 304 fix #1: added `mean_qk`, `var_qk`
/// query-key cross statistics), so total LoRA input is
/// `N_HEADS * STATS_PER_HEAD = 96`.
///
/// Feature layout per head: `[mean_k, var_k, mean_qk, var_qk, top_attn_0..7]`.
pub const STATS_PER_HEAD: usize = 4 + TOP_K;

/// Number of top attention scores retained per head when pooling. Matches
/// `crates/riir-games/src/crowd_mcgs/retrieval::TOP_K = 8`.
pub const TOP_K: usize = 8;

/// Total LoRA input dimension.
pub const LORA_INPUT_DIM: usize = N_HEADS * STATS_PER_HEAD;

/// Total LoRA output dimension (one β per head). Matches T-D.2:
/// "Output: per-head β vector".
pub const LORA_OUTPUT_DIM: usize = N_HEADS;

/// Default compact size **per head** (paper-fitted β vector length per
/// head). AM's `compact()` returns `compact_size` per-token β values per
/// head; we aggregate them to a single per-head scalar for β_ref.
pub const DEFAULT_COMPACT_SIZE: usize = 16;

/// Number of query vectors per sample (Qref). AM requires `queries.len()
/// == n * d`; we use `n = 4` per the Phase A test fixtures.
pub const DEFAULT_N_QUERIES: usize = 4;

