impl KvStats {
    /// Expected feature vector length.
    pub const fn expected_len() -> usize {
        LORA_INPUT_DIM
    }

    /// Validate shape. Returns `Ok(())` if `features.len() == LORA_INPUT_DIM`
    /// and all entries are finite.
    pub fn validate(&self) -> Result<(), CorpusError> {
        if self.features.len() != Self::expected_len() {
            return Err(CorpusError::StatsShapeMismatch {
                got: self.features.len(),
                expected: Self::expected_len(),
            });
        }
        for &v in &self.features {
            if !v.is_finite() {
                return Err(CorpusError::NonFiniteStats);
            }
        }
        Ok(())
    }
}

impl Prng {
    /// Seed from a 32-byte BLAKE3 digest (we use the first 4 bytes; the
    /// remaining bytes are still mixed into the digest for commitment).
    fn from_blake3(digest: [u8; 32]) -> Self {
        let mut state = 0u32;
        for &b in &digest[..4] {
            state = (state << 8) | b as u32;
        }
        // xorshift32 requires non-zero state.
        if state == 0 {
            state = 0xDEAD_BEEF;
        }
        Self { state }
    }

    /// Next raw u32.
    #[inline]
    fn next_u32(&mut self) -> u32 {
        // Marsaglia xorshift32.
        let mut x = self.state;
        x ^= x << 13;
        x ^= x >> 17;
        x ^= x << 5;
        self.state = x;
        x
    }

    /// Uniform float in `[0, 1)`.
    #[inline]
    fn next_f32(&mut self) -> f32 {
        (self.next_u32() >> 8) as f32 / ((1u32 << 24) as f32)
    }

    /// Standard-normal sample via Box-Muller.
    #[inline]
    fn next_normal(&mut self) -> f32 {
        // Two uniforms → one normal. We discard the second for simplicity.
        let u1 = self.next_f32().max(1e-10);
        let u2 = self.next_f32();
        let r = (-2.0f32 * u1.ln()).sqrt();
        let theta = 2.0f32 * std::f32::consts::PI * u2;
        r * theta.cos()
    }

    /// Uniform integer in `[lo, hi]` inclusive.
    #[inline]
    fn next_int_range(&mut self, lo: usize, hi: usize) -> usize {
        if hi <= lo {
            return lo;
        }
        lo + (self.next_u32() as usize % (hi - lo + 1))
    }
}

