        Self {
            vocab_size,
            ..Self::default()
        }
    }

    /// Set maximum token length.
    pub fn with_max_token_len(mut self, max_token_len: usize) -> Self {
        self.max_token_len = max_token_len;
        self
    }

    /// Validate configuration.
    pub fn validate(&self) -> Result<(), String> {
        if self.vocab_size < 256 {
            return Err(format!(
                "vocab_size must be >= 256 (byte tokens), got {vocab_size}",
                vocab_size = self.vocab_size
            ));
        }
        if self.max_token_len == 0 {
            return Err(format!(
                "max_token_len must be > 0, got {max_token_len}",
                max_token_len = self.max_token_len
            ));
        }
        Ok(())
    }
}

impl BpeTokenizer {
    /// Create a byte-level tokenizer (256 tokens, no merges).
    ///
    /// Builds the 256-entry byte vocab in a single contiguous allocation
    /// then splits into individual `Vec<u8>` entries, avoiding 256 separate
    /// heap allocations.
    pub fn byte_level() -> Self {
        // Allocate one contiguous buffer for all 256 single-byte tokens,
        // then split into individual Vec<u8>s. This avoids 256 separate
        // heap allocations (one per vec![b]).
        let mut backing = Vec::with_capacity(256);
        backing.extend(0u8..=255);
        let vocab: Vec<Vec<u8>> = backing.into_iter().map(|b| vec![b]).collect();

        // Pre-build bytes_to_id with exact capacity — byte IDs are 0..=255, all single-byte.
        // Use the already-allocated vocab entries as keys to avoid duplicating them.
        let mut bytes_to_id: HashMap<Vec<u8>, usize> = HashMap::with_capacity(256);
        for (id, bytes) in vocab.iter().enumerate() {
            bytes_to_id.insert(bytes.clone(), id);
        }

        Self {
            vocab,
            merges: vec![],
            merge_ids: vec![],
            bytes_to_id,
            pair_to_id: HashMap::new(),
        }
    }

    /// Returns the vocabulary size.
    #[inline]
    pub fn vocab_size(&self) -> usize {
        self.vocab.len()
    }

    /// Tokenize a byte slice into token IDs.
    ///
    /// Applies merge rules in order, matching greedily left-to-right
    /// at each merge step.
    pub fn tokenize(&self, text: &[u8]) -> Vec<usize> {
        if text.is_empty() {
            return vec![];
        }

        // Start with individual byte tokens
        let mut tokens: Vec<usize> = Vec::with_capacity(text.len());
        tokens.extend(text.iter().map(|&b| b as usize));

        // Apply each merge rule in order using pre-computed triples
        for &(left_id, right_id, merged_id) in &self.merge_ids {
            apply_merge_in_place_single(&mut tokens, left_id, right_id, merged_id);
        }

        tokens
    }

    /// Tokenize a byte slice into a pre-allocated buffer.
    ///
    /// Reuses `buf` across calls to avoid per-tokenization allocation.
    /// Clears `buf` before writing.
    pub fn tokenize_into(&self, text: &[u8], buf: &mut Vec<usize>) {
        buf.clear();
        if text.is_empty() {
            return;
        }

        buf.extend(text.iter().map(|&b| b as usize));

        for &(left_id, right_id, merged_id) in &self.merge_ids {
            apply_merge_in_place_single(buf, left_id, right_id, merged_id);
        }
    }

    /// Tokenize pre-tokenized chunks into a flat list of token IDs.
    ///
    /// Each pretoken is tokenized independently (no merges across boundaries).
    /// Reuses an internal scratch buffer to avoid per-pretoken allocation.
    pub fn tokenize_pretokens(&self, pretokens: &[Vec<u8>]) -> Vec<usize> {
        let total_bytes: usize = pretokens.iter().map(|p| p.len()).sum();
        let mut result = Vec::with_capacity(total_bytes);
        // Size scratch to the longest pretoken so it never reallocates.
        let max_pretoken_len = pretokens.iter().map(|p| p.len()).max().unwrap_or(0);
        let mut scratch = Vec::with_capacity(max_pretoken_len);
        for pretoken in pretokens {
            self.tokenize_into(pretoken, &mut scratch);
            result.extend_from_slice(&scratch);
        }
        result
    }

    /// Reconstruct bytes from token IDs.
    pub fn decode(&self, token_ids: &[usize]) -> Vec<u8> {
        // Estimate ~4 bytes per token (typical BPE average) to avoid reallocation.
        let mut result = Vec::with_capacity(token_ids.len() * 4);
        for &id in token_ids {
            if let Some(bytes) = self.vocab.get(id) {
                result.extend_from_slice(bytes);
            } else {
                log::warn!("Invalid token ID {id}, skipping");
            }
        }
        result
    }

    /// Build a tokenizer from vocab and merges, constructing reverse indexes.
    pub(crate) fn build_from_parts(vocab: Vec<Vec<u8>>, merges: Vec<(Vec<u8>, Vec<u8>)>) -> Self {
        // Build bytes_to_id: map each vocab entry's bytes to its ID
        let mut bytes_to_id: HashMap<Vec<u8>, usize> = HashMap::with_capacity(vocab.len());
        for (id, bytes) in vocab.iter().enumerate() {
            bytes_to_id.insert(bytes.clone(), id);
        }

        // Build pair_to_id: for each merge at position i, map (left_id, right_id) → 256 + i
        let mut pair_to_id: HashMap<(usize, usize), usize> = HashMap::with_capacity(merges.len());
        let mut merge_ids: Vec<(usize, usize, usize)> = Vec::with_capacity(merges.len());
        for (i, (left_bytes, right_bytes)) in merges.iter().enumerate() {
            let merged_id = 256 + i;
            if let (Some(&lid), Some(&rid)) = (
                bytes_to_id.get(left_bytes.as_slice()),
                bytes_to_id.get(right_bytes.as_slice()),
            ) {
                pair_to_id.insert((lid, rid), merged_id);
                merge_ids.push((lid, rid, merged_id));
            }
        }

        Self {
            vocab,
            merges,
            merge_ids,
            bytes_to_id,
            pair_to_id,
        }
    }

    /// Find token ID for a byte sequence in the vocabulary.
    #[allow(dead_code)]
    fn find_token_id(&self, bytes: &[u8]) -> Option<usize> {
        match bytes.len() {
            1 => Some(bytes[0] as usize),
            _ => self.bytes_to_id.get(bytes).copied(),
        }
    }

    /// Find the merged token ID for a pair of byte sequences.
    #[allow(dead_code)]
    fn find_merged_token_id(&self, left: &[u8], right: &[u8]) -> Option<usize> {
        let left_id = self.find_token_id(left)?;
        let right_id = self.find_token_id(right)?;
        self.pair_to_id.get(&(left_id, right_id)).copied()
    }
}

impl BpeTrainer {
    /// Create a new trainer with the given configuration.
    pub fn new(config: BpeConfig) -> Self {
        Self { config }
    }

    /// Get a reference to the configuration.
    #[inline]
    pub fn config(&self) -> &BpeConfig {
        &self.config
    }

    /// Train a BPE tokenizer from pre-tokenized corpus.
    ///
    /// # Arguments
    /// * `pretokens` - Pre-tokenized byte chunks (from Pretokenizer or similar).
    ///
    /// # Returns
    /// A trained `BpeTokenizer` with vocabulary up to `vocab_size`.
    pub fn train(&self, pretokens: &[Vec<u8>]) -> BpeTokenizer {
        let n_merges = self.config.vocab_size.saturating_sub(256);

        if n_merges == 0 {
            log::info!("No merges requested, returning byte-level tokenizer");
            return BpeTokenizer::byte_level();
        }

        // Initialize: split each pretoken into individual bytes
        let mut sequences: Vec<Vec<usize>> = Vec::with_capacity(pretokens.len());
        for pretoken in pretokens {
            let mut byte_buf: Vec<usize> = Vec::with_capacity(pretoken.len());
            byte_buf.extend(pretoken.iter().map(|&b| b as usize));
            sequences.push(byte_buf);
        }

        // Filter empty sequences
        sequences.retain(|seq| !seq.is_empty());

        // Initialize pair counts once — updated incrementally per merge
        let mut pair_counts = count_pairs(&sequences);

        // Build a max-heap for O(log |pairs|) best-pair lookups.
        // Uses lazy deletion: stale entries (count mismatch) are skipped on pop.
        // Heap entry: (count, left_id, right_id) — max-heap by count.
        let mut pair_heap: BinaryHeap<(u64, usize, usize)> =
            pair_counts.iter().map(|(&(l, r), &c)| (c, l, r)).collect();

        /// Pop the best valid pair from the heap, skipping stale entries.
        fn pop_best(
            heap: &mut BinaryHeap<(u64, usize, usize)>,
            counts: &HashMap<(usize, usize), u64>,
        ) -> Option<(usize, usize)> {
            while let Some((count, left, right)) = heap.pop() {
                match counts.get(&(left, right)) {
                    Some(&c) if c == count && c > 0 => return Some((left, right)),
                    _ => continue, // stale or zero-count entry, skip
                }
            }
            None
        }

        // Initialize tokenizer with byte-level vocab
        // Allocate one contiguous buffer then split, avoiding 256 separate heap allocs.
        let mut backing = Vec::with_capacity(256);
        backing.extend(0u8..=255);
        let mut vocab: Vec<Vec<u8>> = backing.into_iter().map(|b| vec![b]).collect();
        let mut merges: Vec<(Vec<u8>, Vec<u8>)> = Vec::with_capacity(n_merges);

        log::info!(
            "Starting BPE training: {n_merges} target merges, {n_pretokens} pretokens",
            n_pretokens = pretokens.len()
        );

        let mut modified_buf: Vec<(usize, usize)> = Vec::with_capacity(256);
        let mut dirty_buf: Vec<usize> = Vec::with_capacity(256);

        for step in 0..n_merges {
            // Clean up zero-count entries and rebuild heap periodically.
            // Reuse heap allocation: clear() preserves capacity, avoiding
            // fresh allocation every 100 steps.
            if step.is_multiple_of(100) {
                pair_counts.retain(|_, count| *count > 0);
                pair_heap.clear();
                pair_heap.reserve(pair_counts.len());
                for (&(l, r), &c) in &pair_counts {
                    pair_heap.push((c, l, r));
                }
            }

            let best = pop_best(&mut pair_heap, &pair_counts);

            let (lid, rid) = match best {
                None => {
                    log::info!("No more pairs to merge at step {step}, stopping early");
                    break;
                }
                Some((left_id, right_id)) => {
                    // Check max token length constraint
                    let merged_len = vocab[left_id].len() + vocab[right_id].len();
                    if merged_len > self.config.max_token_len {
                        log::debug!(
                            "Skipping merge: result length {merged_len} > max {max}",
                            max = self.config.max_token_len
                        );
                        match find_best_pair_within_limit(
                            &pair_counts,
                            &vocab,
                            self.config.max_token_len,
                        ) {
                            None => {
                                log::info!("No valid merges within max_token_len at step {step}");
                                break;
                            }
                            Some(pair) => pair,
                        }
                    } else {
                        (left_id, right_id)
                    }
                }
            };

            let left_bytes = &vocab[lid];
            let right_bytes = &vocab[rid];
            let merge_entry = (left_bytes.to_vec(), right_bytes.to_vec());
            let new_id = vocab.len();
            let merged: Vec<u8> = left_bytes
                .iter()
                .chain(right_bytes.iter())
                .copied()
                .collect();

            vocab.push(merged);
            merges.push(merge_entry);
            // Fused pass: decrement affected pair counts AND apply the merge in
            // a single scan over all sequences (was two separate full scans).
            decrement_and_merge(
                &mut pair_counts,
                &mut sequences,
                lid,
                rid,
                new_id,
                &mut modified_buf,
                &mut dirty_buf,
            );

            // Push updated heap entries for decremented pairs
            flush_modified_to_heap(&mut modified_buf, &pair_counts, &mut pair_heap);
            increment_new_pairs(
                &mut pair_counts,
                &sequences,
                &dirty_buf,
                new_id,
                &mut modified_buf,
            );
            flush_modified_to_heap(&mut modified_buf, &pair_counts, &mut pair_heap);

            log::debug!("Step {step}: merged pair ({lid}, {rid}) → {new_id}");
        }

        log::info!(
            "BPE training complete: {vocab_size} tokens, {n_merges} merges",
            vocab_size = vocab.len(),
            n_merges = merges.len()
        );

        BpeTokenizer::build_from_parts(vocab, merges)
    }
}

use std::io::{BufRead, BufReader};
use std::path::PathBuf;

#[cfg(not(feature = "convex_training"))]
use anyhow::bail;
use anyhow::{Context, Result};

use crate::types::RoundingScheme;

// ── Defaults ───────────────────────────────────────────────────

/// Default vocabulary budget (256 non-byte tokens).
pub const DEFAULT_VOCAB_BUDGET: usize = 256;

/// Default maximum token length in bytes.
pub const DEFAULT_MAX_TOKEN_LEN: usize = 64;

/// Default minimum n-gram count for LP graph construction.
pub const DEFAULT_MIN_NGRAM_COUNT: u64 = 1;

/// Default output filename.
pub const DEFAULT_OUTPUT_PATH: &str = "tokenizer.json";

// ── Configuration ──────────────────────────────────────────────

/// ConvexTok training configuration.
///
/// Fields ordered by alignment to eliminate internal padding:
/// usize/u64 (8-byte) → Vec/PathBuf (24-byte) → RoundingScheme (1-byte, repr(u8)).
#[derive(Clone, Debug)]
pub struct ConvexTrainingConfig {
    /// Vocabulary budget K (number of non-byte tokens).
    pub vocab_budget: usize,
    /// Maximum token length in bytes.
    pub max_token_len: usize,
    /// Number of documents to use for LP graph construction (0 = all).
    pub n_documents: usize,
    /// Minimum n-gram count (prune low-frequency candidates).
    pub min_ngram_count: u64,
    /// Corpus file paths (text, one document per line).
    pub corpus_paths: Vec<PathBuf>,
    /// Output path for serialized tokenizer.
    pub output_path: PathBuf,
    /// Rounding scheme to use (1-byte, repr(u8) — placed last to avoid padding before fat pointers).
    pub rounding: RoundingScheme,
}

impl ConvexTrainingConfig {
    /// Create a new config with a single corpus path and defaults.
    pub fn new(corpus_path: PathBuf) -> Self {
        Self {
            vocab_budget: DEFAULT_VOCAB_BUDGET,
            max_token_len: DEFAULT_MAX_TOKEN_LEN,
            min_ngram_count: DEFAULT_MIN_NGRAM_COUNT,
            n_documents: 0,
            output_path: PathBuf::from(DEFAULT_OUTPUT_PATH),
            corpus_paths: vec![corpus_path],
            rounding: RoundingScheme::Det,
        }
    }

impl TrainingReport {
    /// Check if training achieved near-optimal results within threshold percent.
    pub fn is_near_optimal(&self, threshold_percent: f64) -> bool {
        self.optimality_gap_percent <= threshold_percent
    }
}

impl ConvexTrainer {
    /// Create a new trainer with the given configuration.
    pub fn new(config: ConvexTrainingConfig) -> Self {
        Self { config }
    }

    /// Access the training configuration.
    #[inline]
    pub fn config(&self) -> &ConvexTrainingConfig {
        &self.config
    }

    /// Run the full training pipeline.
    ///
    /// Steps:
    /// 1. Stream corpus → pre-tokenize → collect pretokenized documents
    /// 2. Count byte n-grams via `NgramCounter`
    /// 3. Build tokenisation graph (via katgpt-rs `GraphBuilder`)
    /// 4. Solve LP (via katgpt-rs `ConvexSolver`)
    /// 5. Round LP solution (via katgpt-rs `Rounder`)
    /// 6. Certify optimality (via katgpt-rs `Certifier`)
    /// 7. Build ToaST tokenizer (via katgpt-rs `ConvexToToastBridge`)
    /// 8. Wrap in `ConvexTokTokenizer` and serialize
    #[cfg(feature = "convex_training")]
    pub fn train(&self) -> Result<TrainingReport> {
        use katgpt_tokenizer::{
            Certifier, ConvexSolver, ConvexToToastBridge, GraphBuilder, Rounder, SpecialTokens,
        };

        // Step 1: Pre-tokenize corpus
        log::info!("Step 1/8: Pre-tokenizing corpus...");
        let pretokenizer =
            crate::pretok_regex::Pretokenizer::with_max_len(self.config.max_token_len);
        let pretokens = self.stream_and_pretokenize(&pretokenizer)?;
        log::info!("  Collected {} pretokens", pretokens.len());

        // Step 2: Count n-grams
        log::info!("Step 2/8: Counting byte n-grams...");
        let counter = crate::ngram_counter::NgramCounter::new(crate::ngram_counter::NgramConfig {
            max_len: self.config.max_token_len,
            min_count: self.config.min_ngram_count,
            n_threads: rayon::current_num_threads(),
            batch_size: 1000,
        });
        let ngram_counts = counter.count_pretokens(&pretokens);
        log::info!("  Found {} unique n-grams", ngram_counts.len());

        // Step 3: Build tokenisation graph
        log::info!("Step 3/8: Building tokenisation graph...");
        let graph = GraphBuilder::build(&pretokens, self.config.max_token_len);
        log::info!(
            "  Graph: {} vertices, {} free edges, {} priced edges, {} colours",
            graph.n_vertices,
            graph.n_free_edges(),
            graph.n_priced_edges(),
            graph.n_colours(),
        );

        // Step 4: Solve LP
        log::info!(
            "Step 4/8: Solving LP relaxation (budget K={})...",
            self.config.vocab_budget
        );
        let lp_solution = ConvexSolver::solve(&graph, self.config.vocab_budget)
            .map_err(|e| anyhow::anyhow!("LP solve failed: {e}"))?;
        log::info!(
            "  LP value={:.4}, integrality={:.1}%",
            lp_solution.lp_value,
            lp_solution.integrality_fraction() * 100.0,
        );

        // Step 5: Round LP solution
        log::info!(
            "Step 5/8: Rounding LP solution ({})...",
            self.config.rounding
        );
        let rounded = match self.config.rounding {
            RoundingScheme::Det => Rounder::det(&graph, &lp_solution),
            RoundingScheme::Bias => Rounder::bias(&graph, &lp_solution),
            RoundingScheme::Int => Rounder::int(&graph, &lp_solution),
        };
        log::info!(
            "  Selected {} tokens, compression={:.4}",
            rounded.n_selected,
            rounded.compression_value,
        );

        // Step 6: Certify optimality
        log::info!("Step 6/8: Certifying optimality...");
        let cert = Certifier::certify(&lp_solution, &rounded);
        log::info!("  {cert}");

        // Step 7: Build ToaST tokenizer
        log::info!("Step 7/8: Building ToaST tokenizer...");
        let special = SpecialTokens::default();
        let tokenizer = ConvexToToastBridge::to_toast_tokenizer(&rounded, &ngram_counts, &special);
        log::info!("  Vocabulary size: {}", tokenizer.vocab_size());

        // Step 8: Serialize
        log::info!(
            "Step 8/8: Serializing to {}...",
            self.config.output_path.display()
        );
        let convex_meta = crate::tokenizer_format::ConvexTokMeta::new(
            lp_solution.lp_value,
            rounded.compression_value,
            self.config.rounding,
            self.config.vocab_budget,
            pretokens.len(),
            unix_epoch_timestamp(),
        );

        let vocab: Vec<(Vec<u8>, usize)> = tokenizer
            .id_to_vocab
            .iter()
            .enumerate()
            .map(|(id, bytes)| (bytes.clone(), id))
            .collect();

        let merges: Vec<(Vec<u8>, Vec<u8>)> = rounded
            .selected_bytes
            .iter()
            .filter(|b| b.len() >= 2)
            .map(|bytes| {
                let mid = bytes.len() / 2;
                (bytes[..mid].to_vec(), bytes[mid..].to_vec())
            })
            .collect();

        let convex_tokenizer =
            crate::tokenizer_format::ConvexTokTokenizer::new_convex_tok(vocab, merges, convex_meta);
        convex_tokenizer.save(&self.config.output_path)?;

        let n_variables = lp_solution.f.len() + lp_solution.p.len() + lp_solution.c.len();
        let report = TrainingReport {
            n_pretokens: pretokens.len(),
            n_colours: graph.n_colours(),
            n_variables,
            vocab_size: convex_tokenizer.vocab_size(),
            n_selected_tokens: rounded.n_selected,
            lp_value: lp_solution.lp_value,
            compression: rounded.compression_value,
            optimality_gap_percent: cert.gap_percent,
            integrality_fraction: cert.integrality_fraction,
            rounding: self.config.rounding,
        };

        log::info!("Training complete. Report: {report:?}");
        Ok(report)
    }

    /// Train without katgpt-rs — returns a clear error message.
    #[cfg(not(feature = "convex_training"))]
    pub fn train(&self) -> Result<TrainingReport> {
        bail!(
            "ConvexTok training requires the `convex_training` feature. \
             Enable it with: cargo build --features convex_training"
        );
    }

    /// Stream corpus files, pre-tokenize, and collect all pretoken chunks.
    ///
    /// Respects `n_documents` limit (0 = all documents).
    #[allow(dead_code)] // Used by feature-gated train()
    fn stream_and_pretokenize(
        &self,
        pretokenizer: &crate::pretok_regex::Pretokenizer,
    ) -> Result<Vec<Vec<u8>>> {
        let mut all_pretokens: Vec<Vec<u8>> = Vec::with_capacity(1024);
        let mut pretok_buf: Vec<Vec<u8>> = Vec::with_capacity(32); // reusable buffer
        let mut docs_seen: usize = 0;

        for path in &self.config.corpus_paths {
            let file = std::fs::File::open(path)
                .with_context(|| format!("Failed to open corpus file: {}", path.display()))?;
            let reader = BufReader::new(file);

            for line in reader.lines() {
                let line = line.context("Failed to read line from corpus")?;
                if line.is_empty() {
                    continue;
                }

                pretokenizer.pretokenize_truncated_into(&line, &mut pretok_buf);
                all_pretokens.append(&mut pretok_buf);

                docs_seen += 1;
                if self.config.n_documents > 0 && docs_seen >= self.config.n_documents {
                    log::info!(
                        "Reached document limit ({}/{})",
                        docs_seen,
                        self.config.n_documents,
                    );
                    return Ok(all_pretokens);
                }
            }
        }

        log::info!("Processed {docs_seen} documents from corpus");
        Ok(all_pretokens)
    }
}

impl XorShift64 {
    fn new(seed: u64) -> Self {
        Self {
            state: if seed == 0 { 1 } else { seed },
        }
    }

    fn next_u64(&mut self) -> u64 {
        self.state ^= self.state << 13;
        self.state ^= self.state >> 7;
        self.state ^= self.state << 17;
        self.state
    }

    /// Uniform float in [-0.5, 0.5).
    ///
    /// Uses the top 24 bits of the u64 (full f32 mantissa precision) and a
    /// multiply by the precomputed reciprocal — both faster and more correct
    /// than the prior `as f32 / u64::MAX as f32`, which truncated the u64 to
    /// ~24 bits via the cast AND introduced bias because `u64::MAX as f32`
    /// rounds up to 2^64 (not u64::MAX).
    #[inline]
    fn next_f32(&mut self) -> f32 {
        // 2^-24 — precomputed constant; multiplication is ~10× faster than division.
        const INV_2_24: f32 = 1.0 / (1u32 << 24) as f32;
        (self.next_u64() >> 40) as f32 * INV_2_24 - 0.5
    }

    #[inline]
    fn next_u32(&mut self) -> u32 {
        self.next_u64() as u32
    }
}

impl LclmDataset {
    /// Create an empty dataset.
    pub fn new(config: LclmDataConfig) -> Self {
        Self {
            examples: Vec::new(),
            config,
        }
    }

    /// Create a dataset from pre-loaded examples.
    pub fn from_examples(examples: Vec<LclmExample>, config: LclmDataConfig) -> Self {
        Self { examples, config }
    }

    /// Number of examples in the dataset.
    #[inline]
    pub fn len(&self) -> usize {
        self.examples.len()
    }

    /// Whether the dataset is empty.
    #[inline]
    pub fn is_empty(&self) -> bool {
        self.examples.is_empty()
    }

    /// Load dataset from a binary `.lclm` file (postcard format).
    pub fn load(path: &std::path::Path, config: LclmDataConfig) -> Result<Self> {
        let data = std::fs::read(path)?;
        let examples: Vec<LclmExample> = postcard::from_bytes(&data)?;
        Ok(Self { examples, config })
    }

    /// Save dataset to a binary `.lclm` file (postcard format).
    pub fn save(&self, path: &std::path::Path) -> Result<()> {
        let data = postcard::to_allocvec(&self.examples)?;
        std::fs::write(path, data)?;
        Ok(())
    }

    /// Generate synthetic examples for testing.
    ///
    /// Creates `n` examples with deterministic pseudo-random soft tokens
    /// and token sequences using a simple xorshift PRNG seeded by `seed`.
    pub fn synthetic(n: usize, config: &LclmDataConfig, seed: u64) -> Self {
        let mut rng = XorShift64::new(seed);

        let mut examples = Vec::with_capacity(n);

        for _ in 0..n {
            let soft_tokens: Vec<f32> = (0..4 * config.encoder_hidden_dim)
                .map(|_| rng.next_f32())
                .collect();

            let compressed = LclmSegment::Compressed {
                soft_tokens,
                hidden_dim: config.encoder_hidden_dim,
            };

            let query_tokens: Vec<u32> = (0..64).map(|_| rng.next_u32() % 32000).collect();
            let uncompressed = LclmSegment::Uncompressed {
                token_ids: query_tokens,
            };

            examples.push(LclmExample {
                segments: vec![compressed, uncompressed],
                compression_ratio: config.compression_ratio,
            });
        }

        Self {
            examples,
            config: *config,
        }
    }
}

