impl Pretokenizer {
    /// Create a new Pretokenizer with default settings (max_len = 64).
    pub fn new() -> Self {
        Self {
            regex: &COMPILED_REGEX,
            max_len: DEFAULT_MAX_LEN,
        }
    }

    /// Create a Pretokenizer with a custom maximum pretoken length.
    pub fn with_max_len(max_len: usize) -> Self {
        Self {
            regex: &COMPILED_REGEX,
            max_len,
        }
    }

    /// Pre-tokenize a string into byte chunks.
    ///
    /// Returns non-empty byte vectors, one per regex match.
    /// Pre-allocates output based on estimated match count to avoid reallocation.
    pub fn pretokenize(&self, text: &str) -> Vec<Vec<u8>> {
        // Estimate: average word length ~5 bytes + 1 separator = ~6 bytes per token.
        let est_chunks = (text.len() / 5).max(1);
        let mut out = Vec::with_capacity(est_chunks);
        self.pretokenize_into(text, &mut out);
        out
    }

    /// Pre-tokenize a string into byte chunks, reusing caller-provided buffers.
    ///
    /// Writes chunks directly into `out`, clearing it first.
    /// Each chunk is still individually allocated via `to_vec()`,
    /// but the outer `Vec` is reused.
    pub fn pretokenize_into(&self, text: &str, out: &mut Vec<Vec<u8>>) {
        out.clear();
        for m in self.regex.find_iter(text).flatten() {
            let bytes = m.as_str().as_bytes();
            if !bytes.is_empty() {
                out.push(bytes.to_vec());
            }
        }
    }

    /// Pre-tokenize and truncate chunks to `max_len`.
    ///
    /// Long pretokens are split at `max_len` byte boundaries to stay
    /// within the LP variable length constraint.
    pub fn pretokenize_truncated(&self, text: &str) -> Vec<Vec<u8>> {
        let est_chunks = (text.len() / self.max_len).max(1);
        let mut out = Vec::with_capacity(est_chunks);
        self.pretokenize_truncated_into(text, &mut out);
        out
    }

    /// Pre-tokenize and truncate chunks into `out`, reusing caller-provided buffers.
    ///
    /// Combines pretokenization and truncation in a single pass,
    /// avoiding the intermediate `Vec<Vec<u8>>` from `pretokenize()`.
    pub fn pretokenize_truncated_into(&self, text: &str, out: &mut Vec<Vec<u8>>) {
        out.clear();
        for m in self.regex.find_iter(text).flatten() {
            let bytes = m.as_str().as_bytes();
            if bytes.is_empty() {
                continue;
            }
            if bytes.len() <= self.max_len {
                out.push(bytes.to_vec());
            } else {
                for chunk in bytes.chunks(self.max_len) {
                    out.push(chunk.to_vec());
                }
            }
        }
    }

    /// Pre-tokenize into string slices (zero-copy when possible).
    ///
    /// Useful for inspection and testing.
    /// Pre-allocates output based on estimated match count to avoid reallocation.
    pub fn pretokenize_strs<'a>(&self, text: &'a str) -> Vec<&'a str> {
        // Estimate: average word length ~5 bytes + 1 separator = ~6 bytes per token.
        let est_chunks = (text.len() / 5).max(1);
        let mut result = Vec::with_capacity(est_chunks);
        for m in self.regex.find_iter(text).flatten() {
            let s = m.as_str();
            if !s.is_empty() {
                result.push(s);
            }
        }
        result
    }

    /// Get the configured maximum pretoken length.
    #[inline]
    pub fn max_len(&self) -> usize {
        self.max_len
    }
}

