/// Worms action vocabulary — matches SSD-LoRA `output_dim` (default 16).
///
/// Layout (indices): 0-7 = aim angle (8 sectors), 8-11 = power (4 levels),
/// 12 = fire, 13 = move-left, 14 = move-right, 15 = wait/no-op.
///
/// Kept deliberately small (16) so the SSD readout projection stays thin and
/// the plasma-tier `ssd_lora_step` stays under 10μs.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[repr(u8)]
pub enum WormsAction {
    AimSector0 = 0,
    AimSector1 = 1,
    AimSector2 = 2,
    AimSector3 = 3,
    AimSector4 = 4,
    AimSector5 = 5,
    AimSector6 = 6,
    AimSector7 = 7,
    PowerLow = 8,
    PowerMed = 9,
    PowerHigh = 10,
    PowerMax = 11,
    Fire = 12,
    MoveLeft = 13,
    MoveRight = 14,
    Wait = 15,
}

impl WormsAction {
    /// Output dimension — number of action logits.
    pub const VOCAB_SIZE: usize = 16;

impl FeatureExtractor for RawStateExtractor {
    #[inline]
    fn input_dim(&self) -> usize {
        self.input_dim
    }

    fn extract(&self, state: &WormsState, out: &mut [f32]) {
        debug_assert_eq!(out.len(), self.input_dim);
        out.fill(0.0);

        // Worm slots: 16 features per worm, max_worms slots.
        let worm_stride = 16usize;
        let max_worm_features = self.max_worms * worm_stride;
        let active_idx = state.active_worm as usize;
        for (i, worm) in state.worms.iter().enumerate() {
            if i >= self.max_worms {
                break;
            }
            let base = i * worm_stride;
            if base + worm_stride > self.input_dim {
                break;
            }
            Self::write_worm(out, base, worm, i == active_idx);
        }

        // Terrain heightmap (next 32 slots after worm block).
        let terrain_base = max_worm_features.min(self.input_dim);
        let terrain_slots = 32.min(self.input_dim.saturating_sub(terrain_base));
        for (i, &h) in state.terrain_heightmap.iter().enumerate() {
            if i >= terrain_slots {
                break;
            }
            out[terrain_base + i] = Self::norm_pos(h, 1024.0);
        }

        // Global signals: wind + active worm count.
        let globals_base = terrain_base + terrain_slots;
        if globals_base + 4 <= self.input_dim {
            // Wind in [-1, 1] → sigmoid centered at 0.
            out[globals_base] = 1.0 / (1.0 + (-(state.wind * 4.0)).exp());
            // Normalized active worm index.
            let n_worms = state.worms.len().max(1) as f32;
            out[globals_base + 1] = (state.active_worm as f32 + 1.0) / (n_worms + 1.0);
            // Worm count normalized.
            out[globals_base + 2] = (state.worms.len() as f32) / 16.0;
            out[globals_base + 3] = 0.5; // reserved bias
        }
        // Remaining slots stay zero (reserved for CNN feature injection).
    }
}

impl SsdTrainingPair {
    /// Build a training pair from a tick slice + feature extractor.
    pub fn from_ticks(
        ticks: &[WormsTick],
        extractor: &dyn FeatureExtractor,
        output_dim: usize,
    ) -> Self {
        let input_dim = extractor.input_dim();
        let seq_len = ticks.len();
        let mut features = vec![0.0f32; seq_len * input_dim];
        let mut actions = vec![0.0f32; seq_len * output_dim];

        for (t, tick) in ticks.iter().enumerate() {
            let f_off = t * input_dim;
            extractor.extract(&tick.state, &mut features[f_off..f_off + input_dim]);
            let a_off = t * output_dim;
            if let Some(action) = WormsAction::from_u8(tick.action) {
                action.write_one_hot(&mut actions[a_off..a_off + output_dim]);
            } else {
                // Unknown action → uniform 0.5 (no signal).
                for slot in &mut actions[a_off..a_off + output_dim] {
                    *slot = 0.5;
                }
            }
        }

        Self {
            features,
            actions,
            seq_len,
            input_dim,
            output_dim,
        }
    }

    /// Validate buffer dimensions.
    #[inline]
    pub fn validate(&self) -> bool {
        self.features.len() == self.seq_len * self.input_dim
            && self.actions.len() == self.seq_len * self.output_dim
            && self.seq_len > 0
    }
}

