struct SeededRng(u64);

impl SeededRng {
    fn new(seed: u64) -> Self {
        // Avoid the all-zero state.
        Self(if seed == 0 { 0xDEADBEEF_CAFEBABE } else { seed })
    }

    #[inline]
    fn next_u64(&mut self) -> u64 {
        // xorshift64 — fast, deterministic, good enough for synthetic data.
        let mut x = self.0;
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        self.0 = x;
        x
    }

    #[inline]
    fn next_f32(&mut self) -> f32 {
        // Top 24 bits → full f32 mantissa precision; multiply by the
        // precomputed reciprocal (1.0 / 2^24) is ~10× faster than division.
        const INV_2_24: f32 = 1.0 / (1u32 << 24) as f32;
        (self.next_u64() >> 40) as f32 * INV_2_24
    }
}

