impl ConvexTokMeta {
    /// Create new certification metadata, computing optimality gap automatically.
    pub fn new(
        lp_lower_bound: f64,
        achieved_compression: f64,
        rounding_scheme: RoundingScheme,
        budget_k: usize,
        n_training_documents: usize,
        trained_at: String,
    ) -> Self {
        let optimality_gap_percent = if lp_lower_bound > 0.0 {
            ((achieved_compression - lp_lower_bound) / lp_lower_bound) * 100.0
        } else {
            0.0
        };
        Self {
            lp_lower_bound,
            achieved_compression,
            optimality_gap_percent,
            budget_k,
            n_training_documents,
            trained_at,
            rounding_scheme,
        }
    }

    /// Check if the optimizer achieved near-optimal within `gap_threshold_percent`.
    pub fn is_near_optimal(&self, gap_threshold_percent: f64) -> bool {
        self.optimality_gap_percent <= gap_threshold_percent
    }
}

impl ConvexTokTokenizer {
    /// Returns the vocabulary size (number of tokens).
    #[inline]
    pub fn vocab_size(&self) -> usize {
        self.vocab.len()
    }

    /// Save tokenizer to a JSON file.
    pub fn save(&self, path: &Path) -> Result<()> {
        let json = serde_json::to_string_pretty(self)
            .with_context(|| "Failed to serialize tokenizer to JSON")?;
        std::fs::write(path, json.as_bytes())
            .with_context(|| format!("Failed to write tokenizer to {}", path.display()))?;
        Ok(())
    }

    /// Load tokenizer from a JSON file.
    pub fn load(path: &Path) -> Result<Self> {
        let data = std::fs::read_to_string(path)
            .with_context(|| format!("Failed to read tokenizer from {}", path.display()))?;
        let mut tokenizer: Self = serde_json::from_str(&data)
            .with_context(|| format!("Failed to parse tokenizer JSON from {}", path.display()))?;
        tokenizer.build_indexes();
        Ok(tokenizer)
    }

    /// Create a minimal V1 BPE tokenizer (for testing / backward compat).
    pub fn new_bpe(vocab: Vec<(Vec<u8>, usize)>, merges: Vec<(Vec<u8>, Vec<u8>)>) -> Self {
        let mut tok = Self {
            bytes_to_id: HashMap::new(),
            id_to_idx: Vec::new(),
            vocab,
            merges,
            convex_meta: None,
            version: TokenizerFormatVersion::V1Bpe,
        };
        tok.build_indexes();
        tok
    }

    /// Create a V2 ToaST tokenizer (no ConvexTok meta).
    pub fn new_toast(vocab: Vec<(Vec<u8>, usize)>, merges: Vec<(Vec<u8>, Vec<u8>)>) -> Self {
        let mut tok = Self {
            bytes_to_id: HashMap::new(),
            id_to_idx: Vec::new(),
            vocab,
            merges,
            convex_meta: None,
            version: TokenizerFormatVersion::V2Toast,
        };
        tok.build_indexes();
        tok
    }

    /// Create a V3 ConvexTok tokenizer with certification metadata.
    pub fn new_convex_tok(
        vocab: Vec<(Vec<u8>, usize)>,
        merges: Vec<(Vec<u8>, Vec<u8>)>,
        meta: ConvexTokMeta,
    ) -> Self {
        let mut tok = Self {
            bytes_to_id: HashMap::new(),
            id_to_idx: Vec::new(),
            vocab,
            merges,
            convex_meta: Some(meta),
            version: TokenizerFormatVersion::V3ConvexTok,
        };
        tok.build_indexes();
        tok
    }

    /// Rebuild reverse-index HashMaps from the vocab.
    fn build_indexes(&mut self) {
        self.bytes_to_id = HashMap::with_capacity(self.vocab.len());
        for (bytes, id) in &self.vocab {
            self.bytes_to_id.insert(bytes.clone(), *id);
        }
        let max_id = self.vocab.iter().map(|(_, id)| *id).max().unwrap_or(0);
        self.id_to_idx = vec![0; max_id + 1];
        for (idx, (_, id)) in self.vocab.iter().enumerate() {
            self.id_to_idx[*id] = idx;
        }
    }

    /// Look up a token ID by its byte content.
    pub fn token_id(&self, bytes: &[u8]) -> Option<usize> {
        self.bytes_to_id.get(bytes).copied()
    }

    /// Look up token bytes by ID.
    pub fn token_bytes(&self, id: usize) -> Option<&[u8]> {
        if id < self.id_to_idx.len() {
            let idx = self.id_to_idx[id];
            if idx < self.vocab.len() {
                return Some(self.vocab[idx].0.as_slice());
            }
        }
        None
    }
}

