/// Default timeout for executor: 30 seconds.
const DEFAULT_TIMEOUT: Duration = Duration::from_secs(30);

/// Errors that can occur during GPU future execution.
#[derive(Debug)]
#[repr(u8)]
pub enum ExecutorError {
    /// The future did not complete within the configured timeout.
    Timeout,
}

impl std::fmt::Display for ExecutorError {
    #[cold]
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ExecutorError::Timeout => write!(f, "GPU future execution timed out"),
        }
    }

impl GpuExecutor {
    /// Create a new executor with the default timeout (30 seconds).
    pub fn new(device: wgpu::Device, queue: wgpu::Queue) -> Self {
        Self {
            device,
            queue,
            timeout: DEFAULT_TIMEOUT,
        }
    }

    /// Create a new executor with a custom timeout.
    pub fn with_timeout(device: wgpu::Device, queue: wgpu::Queue, timeout: Duration) -> Self {
        Self {
            device,
            queue,
            timeout,
        }
    }

    /// Block the current thread until the GPU future completes.
    ///
    /// Polls the future in a loop, calling `device.poll(wgpu::Maintain::Wait)`
    /// between polls to drive GPU work forward.
    ///
    /// # Returns
    ///
    /// - `Ok(output)` when the future completes
    /// - `Err(ExecutorError::Timeout)` if the future doesn't complete in time
    pub fn block_on<F: GpuFuture>(&self, future: F) -> Result<F::Output, ExecutorError> {
        let waker = Self::noop_waker();
        let mut cx = Context::from_waker(&waker);
        let mut future = std::pin::pin!(future);

        let deadline = Instant::now() + self.timeout;

        loop {
            match future.as_mut().poll(&mut cx) {
                Poll::Ready(output) => return Ok(output),
                Poll::Pending => {
                    // Cache `now` once — avoids a redundant timestamp syscall
                    // on the fast path where we time out before polling the device.
                    let now = Instant::now();
                    if now >= deadline {
                        return Err(ExecutorError::Timeout);
                    }
                    let remaining = deadline.saturating_duration_since(now);

                    // Drive the wgpu device to process submitted work,
                    // bounded by remaining executor timeout
                    let _ = self.device.poll(wgpu::PollType::Wait {
                        submission_index: None,
                        timeout: Some(remaining),
                    });

                    // Re-check after poll returns (poll may have blocked)
                    if Instant::now() >= deadline {
                        return Err(ExecutorError::Timeout);
                    }
                }
            }
        }
    }

    /// Create a no-op waker for the polling loop.
    ///
    /// Since `block_on` is a busy-poll loop, we don't need the waker
    /// to actually wake anything — we re-poll every iteration regardless.
    fn noop_waker() -> Waker {
        fn noop_clone(_: *const ()) -> RawWaker {
            RawWaker::new(std::ptr::null(), &VTABLE)
        }
        fn noop(_: *const ()) {}
        fn noop_wake_by_ref(_: *const ()) {}
        static VTABLE: RawWakerVTable =
            RawWakerVTable::new(noop_clone, noop, noop_wake_by_ref, noop);
        // Safety: the vtable functions are valid no-ops.
        unsafe { Waker::from_raw(RawWaker::new(std::ptr::null(), &VTABLE)) }
    }
}

