    B: GpuFuture,
{
    /// Create a new join future from two GPU futures.
    pub fn new(a: A, b: B) -> Self {
        Self {
            a: Some(a),
            b: Some(b),
            a_result: None,
            b_result: None,
        }
    }

fn main() {
    println!("cargo:rerun-if-changed=objc/ane_prefill_bridge.m");
    if std::env::var("CARGO_CFG_TARGET_OS").as_deref() != Ok("macos") {
        return;
    }
    if std::env::var("CARGO_FEATURE_ANE_PREFILL").is_err() {
        return;
    }
    let out = std::env::var("OUT_DIR").expect("OUT_DIR");
    let sdk = std::process::Command::new("xcrun")
        .args(["--show-sdk-path"])
        .output()
        .expect("xcrun");
    if !sdk.status.success() {
        panic!("xcrun --show-sdk-path failed (no Apple SDK?)");
    }
    let sdk = String::from_utf8_lossy(&sdk.stdout).trim().to_string();
    let dylib = format!("{out}/libane_prefill_bridge.dylib");
    let status = std::process::Command::new("xcrun")
        .args([
            "clang",
            "-O2",
            "-fobjc-arc",
            "-dynamiclib",
            "-isysroot",
            &sdk,
            "-framework",
            "Foundation",
            "-framework",
            "IOSurface",
            "-framework",
            "Metal",
            "-ldl",
            "-o",
            &dylib,
            "objc/ane_prefill_bridge.m",
        ])
        .status()
        .expect("clang");
    if !status.success() {
        panic!("ane_prefill_bridge.m compile failed ({status})");
    }
}

use crate::deltanet::weights::{DeltaNetLayerWeights, QwenDeltaNetWeights};
use crate::types::{self, Config, DeltaNetLayerType, rmsnorm_with_gamma_eps, swiglu};

/// Per-layer recurrent state for DeltaNet layers.
///
/// Each linear_attention layer maintains a fixed-size state matrix:
/// `[n_value_heads * key_head_dim * value_head_dim]` elements.
/// For Qwen3.5-0.8B: 16 heads × (128 × 128) = 262,144 floats = 1 MB per layer.
///
/// Full attention layers use standard KV cache (not stored here).
pub struct DeltaNetState {
    /// Per-layer recurrent state. Only populated for DeltaNet layers.
    /// `layers[i]` = `[n_v_heads * key_dim * value_dim]` for linear_attention layers,
    /// empty Vec for full_attention layers.
    pub recurrent_states: Vec<Vec<f32>>,
    /// Per-layer conv1d sliding window state.
    /// `conv_states[i]` = `[conv_dim * kernel_size]` for linear_attention layers,
    /// empty Vec for full_attention layers.
    pub conv_states: Vec<Vec<f32>>,
}

impl DeltaNetState {
    /// Create zero-initialized state for all layers.
    pub fn new(config: &Config, layer_types: &[DeltaNetLayerType]) -> Self {
        let n_v_heads = config.deltanet_linear_n_value_heads;
        let key_dim = config.deltanet_linear_head_dim;
        let val_dim = config.deltanet_linear_head_dim;
        let state_dim = n_v_heads * key_dim * val_dim;
        let conv_kernel = config.deltanet_conv_kernel_size;
        // conv_dim = n_q_heads * key_dim + n_k_heads * key_dim + n_v_heads * val_dim
        // But in Qwen3.5: Q and K share same head count, V has separate count
        // From weights: in_proj_qkv output dim = (linear_num_key_heads * key_dim + 2 * linear_num_value_heads * val_dim)
        // conv1d operates on the concatenated [q, k, v] channels
        let n_k_heads = config.deltanet_linear_n_heads;
        let conv_dim = (n_k_heads + n_k_heads + n_v_heads) * key_dim;

        let mut recurrent_states = Vec::with_capacity(config.n_layer);
        let mut conv_states = Vec::with_capacity(config.n_layer);

        for &lt in layer_types {
            if lt == DeltaNetLayerType::DeltaNet {
                recurrent_states.push(vec![0.0f32; state_dim]);
                conv_states.push(vec![0.0f32; conv_dim * conv_kernel]);
            } else {
                recurrent_states.push(Vec::new());
                conv_states.push(Vec::new());
            }
        }

        Self {
            recurrent_states,
            conv_states,
        }
    }

impl DeltanetMinimalActs {
    /// Split `qkv_expanded` into per-head q, k, v slices.
    ///
    /// Returns `(q_head, k_head, v_head)` each of length `head_dim`, for the
    /// given head index `h` in `0..n_v_heads`.
    pub fn head_qkv(&self, h: usize, n_v_heads: usize, head_dim: usize) -> (&[f32], &[f32], &[f32]) {
        let hd = head_dim;
        let per_head = n_v_heads * hd;
        let q_start = h * hd;
        let k_start = per_head + h * hd;
        let v_start = 2 * per_head + h * hd;
        (
            &self.qkv_expanded[q_start..q_start + hd],
            &self.qkv_expanded[k_start..k_start + hd],
            &self.qkv_expanded[v_start..v_start + hd],
        )
    }
}

impl MinimalLayerActivations {
    /// Construct an attention-layer entry (x_in + norm_x only).
    pub fn attention(x_in: Vec<f32>, norm_x: Vec<f32>) -> Self {
        Self {
            x_in,
            norm_x,
            deltanet: None,
        }
    }

    /// Construct a DeltaNet-layer entry (all 5 fields).
    pub fn deltanet(
        x_in: Vec<f32>,
        norm_x: Vec<f32>,
        qkv_expanded: Vec<f32>,
        beta: Vec<f32>,
        decay: Vec<f32>,
    ) -> Self {
        Self {
            x_in,
            norm_x,
            deltanet: Some(DeltanetMinimalActs {
                qkv_expanded,
                beta,
                decay,
            }),
        }
    }

    /// Returns `true` if this is a DeltaNet layer (has deltanet acts).
    pub fn is_deltanet(&self) -> bool {
        self.deltanet.is_some()
    }
}

impl MinimalActivationCache {
    /// Create a new minimal activation cache with known dimensions.
    ///
    /// `n_deltanet_layers` is the count of DeltaNet layers (used for memory
    /// estimation). Per-token layer arrays are pre-allocated via `begin_token`.
    pub fn new(n_deltanet_layers: usize, n_v_heads: usize, head_dim: usize, n_embd: usize) -> Self {
        Self {
            tokens: Vec::new(),
            x_pre_finalnorm: Vec::new(),
            n_deltanet_layers,
            n_v_heads,
            head_dim,
            n_embd,
        }
    }

    /// Prepare the cache for a new token position. `n_layer` is the TOTAL
    /// number of layers (DeltaNet + Attention) — pre-allocates the per-token
    /// layer array.
    pub fn begin_token(&mut self, n_layer: usize) {
        self.tokens.push(Vec::with_capacity(n_layer));
    }

    /// Push one layer's activations for the current (last) token.
    pub fn push_layer_activation(&mut self, acts: MinimalLayerActivations) {
        self.tokens
            .last_mut()
            .expect("begin_token not called")
            .push(acts);
    }

    /// Get the activations for token `t`, raw layer index `layer`.
    pub fn get(&self, t: usize, layer: usize) -> &MinimalLayerActivations {
        &self.tokens[t][layer]
    }

    /// Number of token positions collected.
    pub fn n_tokens(&self) -> usize {
        self.tokens.len()
    }

    /// Total memory used by the collected activations, in bytes.
    ///
    /// Includes: per-layer x_in + norm_x (ALL layers), DeltaNet extras
    /// (qkv_expanded + beta + decay), and the final `x_pre_finalnorm`.
    pub fn mem_usage_bytes(&self) -> usize {
        let per_float = std::mem::size_of::<f32>();
        let n_tokens = self.tokens.len();
        if n_tokens == 0 {
            return self.x_pre_finalnorm.len() * per_float;
        }
        let n_total_layers = self.tokens[0].len();
        let n_attn = n_total_layers.saturating_sub(self.n_deltanet_layers);
        // ALL layers: x_in + norm_x = 2 * n_embd floats
        let base_floats = 2 * self.n_embd;
        // DeltaNet extra: qkv_expanded + beta + decay
        let deltanet_extra = 3 * self.n_v_heads * self.head_dim + 2 * self.n_v_heads;
        n_tokens
            * (n_attn * base_floats + self.n_deltanet_layers * (base_floats + deltanet_extra))
            * per_float
            + self.x_pre_finalnorm.len() * per_float
    }

    /// Clear all collected activations (keep dimensions).
    pub fn clear(&mut self) {
        self.tokens.clear();
        self.x_pre_finalnorm.clear();
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_minimal_cache_push_and_get_deltanet() {
        let mut cache = MinimalActivationCache::new(1, 2, 16, 64);
        cache.begin_token(1);
        cache.push_layer_activation(MinimalLayerActivations::deltanet(
            vec![0.1; 64],
            vec![0.2; 64],
            vec![0.3; 3 * 2 * 16],
            vec![0.4; 2],
            vec![0.5; 2],
        ));
        assert_eq!(cache.n_tokens(), 1);
        let acts = cache.get(0, 0);
        assert!(acts.is_deltanet());
        assert_eq!(acts.x_in.len(), 64);
        assert_eq!(acts.norm_x.len(), 64);
        let dn = acts.deltanet.as_ref().unwrap();
        assert_eq!(dn.qkv_expanded.len(), 3 * 2 * 16);
        assert_eq!(dn.beta.len(), 2);
        assert_eq!(dn.decay.len(), 2);
    }

    #[test]
    fn test_minimal_cache_mixed_layers() {
        let mut cache = MinimalActivationCache::new(1, 2, 16, 64);
        cache.begin_token(2);
        cache.push_layer_activation(MinimalLayerActivations::deltanet(
            vec![0.1; 64],
            vec![0.2; 64],
            vec![0.3; 96],
            vec![0.4; 2],
            vec![0.5; 2],
        ));
        cache.push_layer_activation(MinimalLayerActivations::attention(
            vec![0.6; 64],
            vec![0.7; 64],
        ));
        assert_eq!(cache.n_tokens(), 1);
        assert!(cache.get(0, 0).is_deltanet());
        assert!(!cache.get(0, 1).is_deltanet());
    }

    #[test]
    fn test_minimal_cache_head_qkv_split() {
        let dn = DeltanetMinimalActs {
            qkv_expanded: (0..3 * 2 * 16).map(|i| i as f32).collect(),
            beta: vec![0.0; 2],
            decay: vec![0.0; 2],
        };
        let (q, k, v) = dn.head_qkv(1, 2, 16);
        assert_eq!(q.len(), 16);
        assert_eq!(k.len(), 16);
        assert_eq!(v.len(), 16);
        // head 1: q starts at 1*16=16, k at 2*16+1*16=48, v at 4*16+1*16=80
        assert_eq!(q[0], 16.0);
        assert_eq!(k[0], 48.0);
        assert_eq!(v[0], 80.0);
    }

    #[test]
    fn test_minimal_cache_mem_usage() {
        let mut cache = MinimalActivationCache::new(1, 2, 16, 64);
        cache.begin_token(1);
        cache.push_layer_activation(MinimalLayerActivations::deltanet(
            vec![0.0; 64],
            vec![0.0; 64],
            vec![0.0; 96],
            vec![0.0; 2],
            vec![0.0; 2],
        ));
        cache.x_pre_finalnorm = vec![0.0; 64];
        // Per token per DeltaNet layer: (64+64) + (96+2+2) = 228 floats
        // + x_pre_finalnorm: 64 floats
        // Total: 292 floats × 4 bytes = 1168 bytes
        assert_eq!(cache.mem_usage_bytes(), 292 * 4);
    }

    #[test]
    fn test_minimal_cache_clear() {
        let mut cache = MinimalActivationCache::new(1, 2, 16, 64);
        cache.begin_token(1);
        cache.push_layer_activation(MinimalLayerActivations::deltanet(
            vec![0.1; 64],
            vec![0.2; 64],
            vec![0.3; 96],
            vec![0.4; 2],
            vec![0.5; 2],
        ));
        cache.x_pre_finalnorm = vec![0.0; 64];
        assert_eq!(cache.n_tokens(), 1);
        assert!(!cache.x_pre_finalnorm.is_empty());
        cache.clear();
        assert_eq!(cache.n_tokens(), 0);
        assert!(cache.x_pre_finalnorm.is_empty());
        // Dimensions preserved
        assert_eq!(cache.n_deltanet_layers, 1);
    }
}

use crate::types::Rng;

// ─────────────────────────────────────────────────────────────────────────
// QvLora — one layer's Q+V LoRA adapter
// ─────────────────────────────────────────────────────────────────────────

/// Rank-`r` Q+V LoRA adapter for one DeltaNet layer.
///
/// `A_q` is `[r × n_embd]` (down-projection for Q), `B_q` is `[q_dim × r]`
/// (up-projection for Q). Similarly `A_v`, `B_v` for V.
///
/// `q_dim = n_k_heads · head_dim`, `v_dim = n_v_heads · head_dim`.
#[derive(Clone, Debug)]
pub struct QvLora {
    /// Down-projection for Q `[r × n_embd]` (row-major).
    pub a_q: Vec<f32>,
    /// Up-projection for Q `[q_dim × r]` (row-major).
    pub b_q: Vec<f32>,
    /// Down-projection for V `[r × n_embd]` (row-major).
    pub a_v: Vec<f32>,
    /// Up-projection for V `[v_dim × r]` (row-major).
    pub b_v: Vec<f32>,

    pub rank: usize,
    pub n_embd: usize,
    pub q_dim: usize,
    pub v_dim: usize,
    /// LoRA alpha (the adapter output is scaled by `alpha / rank`).
    pub alpha: f32,
}

impl QvLora {
    /// Create a new Q+V LoRA adapter with standard initialization.
    ///
    /// `A_q`, `A_v` are initialized with small Gaussian noise; `B_q`, `B_v` are
    /// zero — so the adapter produces zero output at step 0 (identity behavior).
    pub fn new(
        rank: usize,
        n_embd: usize,
        q_dim: usize,
        v_dim: usize,
        alpha: f32,
        rng: &mut Rng,
    ) -> Self {
        let std_a = 1.0 / (n_embd as f32).sqrt();
        let a_q = (0..rank * n_embd).map(|_| rng.normal() * std_a).collect();
        let b_q = vec![0.0; q_dim * rank];
        let a_v = (0..rank * n_embd).map(|_| rng.normal() * std_a).collect();
        let b_v = vec![0.0; v_dim * rank];

        Self {
            a_q,
            b_q,
            a_v,
            b_v,
            rank,
            n_embd,
            q_dim,
            v_dim,
            alpha,
        }
    }

    /// The LoRA scaling factor: `alpha / rank`.
    #[inline]
    pub fn scale(&self) -> f32 {
        self.alpha / self.rank as f32
    }

    /// Total parameter count (A_q + B_q + A_v + B_v).
    #[inline]
    pub fn n_params(&self) -> usize {
        2 * self.rank * self.n_embd + self.rank * (self.q_dim + self.v_dim)
    }

    /// Compute the Q+V LoRA deltas for one token.
    ///
    /// Writes `δq[i] = scale · Σ_r B_q[i,r] · ax_q[r]` into `delta_q`,
    /// and `δv[i] = scale · Σ_r B_v[i,r] · ax_v[r]` into `delta_v`.
    ///
    /// Also writes `ax_q = A_q @ norm_x` and `ax_v = A_v @ norm_x` into the
    /// scratch buffers (needed for the backward pass — caller should cache).
    ///
    /// `delta_q.len()` must equal `q_dim`; `delta_v.len()` must equal `v_dim`;
    /// `ax_q.len()` and `ax_v.len()` must equal `rank`.
    pub fn forward_qv_delta(
        &self,
        norm_x: &[f32],
        delta_q: &mut [f32],
        delta_v: &mut [f32],
        ax_q: &mut [f32],
        ax_v: &mut [f32],
    ) {
        debug_assert_eq!(norm_x.len(), self.n_embd);
        debug_assert_eq!(delta_q.len(), self.q_dim);
        debug_assert_eq!(delta_v.len(), self.v_dim);
        debug_assert_eq!(ax_q.len(), self.rank);
        debug_assert_eq!(ax_v.len(), self.rank);

        let scale = self.scale();
        let r = self.rank;
        let n = self.n_embd;

        // ax_q = A_q @ norm_x  [r]
        for ri in 0..r {
            let row = &self.a_q[ri * n..(ri + 1) * n];
            let mut sum = 0.0f32;
            for j in 0..n {
                sum += row[j] * norm_x[j];
            }
            ax_q[ri] = sum;
        }

        // ax_v = A_v @ norm_x  [r]
        for ri in 0..r {
            let row = &self.a_v[ri * n..(ri + 1) * n];
            let mut sum = 0.0f32;
            for j in 0..n {
                sum += row[j] * norm_x[j];
            }
            ax_v[ri] = sum;
        }

        // delta_q = scale * B_q @ ax_q  [q_dim]
        for i in 0..self.q_dim {
            let row = &self.b_q[i * r..(i + 1) * r];
            let mut sum = 0.0f32;
            for ri in 0..r {
                sum += row[ri] * ax_q[ri];
            }
            delta_q[i] = scale * sum;
        }

        // delta_v = scale * B_v @ ax_v  [v_dim]
        for i in 0..self.v_dim {
            let row = &self.b_v[i * r..(i + 1) * r];
            let mut sum = 0.0f32;
            for ri in 0..r {
                sum += row[ri] * ax_v[ri];
            }
            delta_v[i] = scale * sum;
        }
    }

    /// Apply the Q+V LoRA perturbation to a compact QKV buffer in-place.
    ///
    /// Layout of `qkv_compact`: `[q_dim | k_dim | v_dim]` where `k_dim` occupies
    /// the middle slice `[q_dim..q_dim+k_dim]`. Only the Q and V slices are
    /// perturbed; K is untouched.
    ///
    /// `k_dim = n_k_heads · head_dim` (= `q_dim` for Qwen3.5 DeltaNet, but passed
    /// explicitly for clarity).
    #[allow(clippy::too_many_arguments)]
    pub fn apply_to_qkv_compact(
        &self,
        norm_x: &[f32],
        qkv_compact: &mut [f32],
        k_dim: usize,
        ax_q: &mut [f32],
        ax_v: &mut [f32],
        delta_q_scratch: &mut [f32],
        delta_v_scratch: &mut [f32],
    ) {
        debug_assert_eq!(qkv_compact.len(), self.q_dim + k_dim + self.v_dim);

        self.forward_qv_delta(norm_x, delta_q_scratch, delta_v_scratch, ax_q, ax_v);

        // Add δq to the Q slice [0..q_dim]
        for i in 0..self.q_dim {
            qkv_compact[i] += delta_q_scratch[i];
        }

        // Add δv to the V slice [q_dim+k_dim .. q_dim+k_dim+v_dim]
        let v_start = self.q_dim + k_dim;
        for i in 0..self.v_dim {
            qkv_compact[v_start + i] += delta_v_scratch[i];
        }
    }

    // ── Flat parameter view (for AdamW) ──

    /// Flatten all params into a single contiguous slice (for AdamW).
    ///
    /// Layout: `[A_q | B_q | A_v | B_v]` — matches the gradient layout produced
    /// by [`lora_qv_backward_flat`].
    pub fn flatten_into(&self, out: &mut [f32]) {
        debug_assert_eq!(out.len(), self.n_params());
        let mut offset = 0;
        out[offset..offset + self.a_q.len()].copy_from_slice(&self.a_q);
        offset += self.a_q.len();
        out[offset..offset + self.b_q.len()].copy_from_slice(&self.b_q);
        offset += self.b_q.len();
        out[offset..offset + self.a_v.len()].copy_from_slice(&self.a_v);
        offset += self.a_v.len();
        out[offset..offset + self.b_v.len()].copy_from_slice(&self.b_v);
    }

    /// Unflatten from a contiguous slice back into the struct's fields.
    pub fn unflatten_from(&mut self, src: &[f32]) {
        debug_assert_eq!(src.len(), self.n_params());
        let mut offset = 0;
        let a_q_len = self.a_q.len();
        self.a_q.copy_from_slice(&src[offset..offset + a_q_len]);
        offset += a_q_len;
        let b_q_len = self.b_q.len();
        self.b_q.copy_from_slice(&src[offset..offset + b_q_len]);
        offset += b_q_len;
        let a_v_len = self.a_v.len();
        self.a_v.copy_from_slice(&src[offset..offset + a_v_len]);
        offset += a_v_len;
        let b_v_len = self.b_v.len();
        self.b_v.copy_from_slice(&src[offset..offset + b_v_len]);
    }
}

impl LorcCheckpoint {
    /// Consume into the single-layer (Arm B) adapter.
    ///
    /// Errors if the checkpoint holds anything other than exactly one target
    /// layer — the Issue 666 GPU decode path attaches one adapter at one layer.
    pub fn into_single_layer(mut self) -> anyhow::Result<(usize, QvLora)> {
        anyhow::ensure!(
            self.layers.len() == 1,
            "LORC checkpoint holds {} target layers; expected exactly 1 \
             (Arm B single-layer serving — the GPU decode path attaches one adapter)",
            self.layers.len()
        );
        Ok(self.layers.remove(0))
    }
}

