impl AgentControlEnvelope {
    /// Size of the signable portion (everything except the leading 64-byte
    /// `supervisor_signature`). Matches `SIGNABLE_SIZE` on the server-side
    /// `AgentControlExt` trait.
    pub const SIGNABLE_SIZE: usize = core::mem::size_of::<Self>() - 64;

    /// Create a zeroed envelope for testing.
    pub fn zeroed() -> Self {
        Self {
            supervisor_signature: [0u8; 64],
            target_zone_hash: [0u8; 16],
            action_code: 0,
            latcal_matrix: [[0.0; 2]; 2],
            structural_padding: [0u8; 32],
        }
    }

    /// Create a valid test envelope with det=1 matrix and `INJECT_VIBE` (0x99) action.
    pub fn dev_valid() -> Self {
        Self {
            supervisor_signature: [0u8; 64],
            target_zone_hash: [0u8; 16],
            action_code: 0x99,
            latcal_matrix: [[1.0, 0.0], [0.0, 1.0]], // identity matrix, det = 1
            structural_padding: [0u8; 32],
        }
    }

    /// Get the signable portion of the envelope (everything except
    /// `supervisor_signature`). Returns a stack-allocated array — zero
    /// allocation on the hot path.
    ///
    /// This is the message the supervisor Ed25519 signature covers. Both the
    /// client (for signing) and the server (for verification, via
    /// `AgentControlExt`) use this identical layout.
    #[inline]
    pub fn signable_bytes(&self) -> [u8; Self::SIGNABLE_SIZE] {
        // Skip first 64 bytes (supervisor_signature), sign the rest.
        let all: &[u8] = bytemuck::cast_slice(core::slice::from_ref(self));
        let mut buf = [0u8; Self::SIGNABLE_SIZE];
        buf.copy_from_slice(&all[64..]);
        buf
    }
}

