use bytemuck::{Pod, Zeroable};

use crate::AgentControlEnvelope;

/// Magic for sanity-checking byte slices before casting (defence in depth against
/// mis-framed WebTransport reads). Not part of the wire signature.
pub const ASSET_PROMOTE_MAGIC: [u8; 4] = *b"APR1";

/// Byte width of [`AssetPromoteEnvelope::gm_signable_bytes`] — mirrors
/// `riir_chain::asset_lifecycle::ix::PROMOTE_CANONICAL_LEN`.
pub const GM_SIGNABLE_LEN: usize = 138;

/// Action codes for the layered asset-promotion family. These mirror
/// `riir_chaind::mcp::action::{ASSET_PROMOTE, MINT_ASSET_NFT, DEMOTE_ASSET}`
/// (which are `u32` and live behind server features — see Plan 413 §4.4). Kept
/// here as `u32` so the leaf-crate `dev_promote` constructor can set
/// `base.action_code` without depending on the server.
pub const ASSET_PROMOTE_ACTION: u32 = 0x40;
pub const MINT_ASSET_NFT_ACTION: u32 = 0x41;
pub const DEMOTE_ASSET_ACTION: u32 = 0x42;

/// Fixed-size Pod envelope carrying a GM-signed asset promotion request.
///
/// See the module-level docs for the wire-format rationale, the raw-vs-latent
/// boundary note, and the data-vs-verification split.
#[repr(C, align(8))]
#[derive(Copy, Clone, Debug, Pod, Zeroable)]
pub struct AssetPromoteEnvelope {
    /// Base envelope — provides supervisor signature + latcal matrix invariant
    /// + action code (must be `ASSET_PROMOTE_ACTION` / `MINT_ASSET_NFT_ACTION` /
    ///   `DEMOTE_ASSET_ACTION`). Server verifies via `AgentControlExt`.
    pub base: AgentControlEnvelope,
    /// Alignment pad so `item_id` starts at offset 136 (8-byte aligned).
    pub _pad0: [u8;

impl AssetPromoteEnvelope {
    /// Create a zeroed envelope. Action code is 0 (invalid) — callers must
    /// populate `base.action_code` with one of the asset action constants
    /// (`ASSET_PROMOTE_ACTION` etc.) before dispatch.
    pub fn zeroed() -> Self {
        Self {
            base: AgentControlEnvelope::zeroed(),
            _pad0: [0; 4],
            item_id: 0,
            tick: 0,
            asset_blob_id: [0; 32],
            chunk_merkle_root: [0; 32],
            game_binding: [0; 32],
            nft_owner: [0; 32],
            gm_signature: [0; 64],
            from_status: 0,
            to_status: 0,
            nft_owner_present: 0,
            _pad1: [0; 5],
        }
    }

    /// Convenience: build a dev-mode envelope with `ASSET_PROMOTE` action,
    /// identity latcal matrix, non-zero supervisor signature, and the supplied
    /// payload. Useful for tests + early integration before real Ed25519 signing
    /// is wired through the GM tool.
    ///
    /// `chunk_merkle_root` is set equal to `asset_blob_id` (dev convention).
    pub fn dev_promote(
        asset_blob_id: [u8; 32],
        item_id: u64,
        from_status: u8,
        to_status: u8,
    ) -> Self {
        let mut sig = [0u8; 64];
        sig[0] = 1; // non-zero signature so verify_ed25519 passes in dev mode
        let mut env = Self::zeroed();
        env.base = AgentControlEnvelope {
            supervisor_signature: sig,
            target_zone_hash: [0u8; 16],
            action_code: ASSET_PROMOTE_ACTION,
            latcal_matrix: [[1.0, 0.0], [0.0, 1.0]],
            structural_padding: [0u8; 32],
        };
        env.asset_blob_id = asset_blob_id;
        env.chunk_merkle_root = asset_blob_id; // dev: same as blob_id
        env.item_id = item_id;
        env.tick = 0;
        env.from_status = from_status;
        env.to_status = to_status;
        env.nft_owner_present = 0;
        env.gm_signature = sig; // dev: same as supervisor sig
        env
    }

    /// The canonical signable bytes for the GM Ed25519 signature — reproduces
    /// `riir_chain::asset_lifecycle::ix::PromoteAssetIx::canonical_bytes()`
    /// exactly (the 138-byte layout the server's `GmSignatureVerifier` checks).
    ///
    /// Returns a fixed `[u8; GM_SIGNABLE_LEN]` (stack) — zero allocation on the
    /// sign/verify hot path, matching the ix implementation.
    ///
    /// # Why this is inlined here (not delegated to the ix)
    ///
    /// The leaf crate cannot depend on `riir-chain` (leaf-crate invariant), so it
    /// cannot call `PromoteAssetIx::canonical_bytes()`. The layout is reproduced
    /// from the raw envelope fields. A spec-match test in `riir-chaind`
    /// (`gm_signable_bytes_matches_ix_canonical`) asserts byte-identity, so any
    /// drift between the two definitions becomes a test failure.
    ///
    /// # Layout (138 bytes — mirrors `PromoteAssetIx::canonical_bytes`)
    ///
    /// `[asset_blob_id(32), chunk_merkle_root(32), item_id(8), game_binding(32),
    ///   from_status(1), to_status(1), nft_owner(32)]`
    #[inline]
    pub fn gm_signable_bytes(&self) -> [u8; GM_SIGNABLE_LEN] {
        let mut out = [0u8; GM_SIGNABLE_LEN];
        let mut off = 0usize;
        out[off..off + 32].copy_from_slice(&self.asset_blob_id);
        off += 32;
        out[off..off + 32].copy_from_slice(&self.chunk_merkle_root);
        off += 32;
        out[off..off + 8].copy_from_slice(&self.item_id.to_le_bytes());
        off += 8;
        out[off..off + 32].copy_from_slice(&self.game_binding);
        off += 32;
        out[off] = self.from_status;
        off += 1;
        out[off] = self.to_status;
        off += 1;
        // nft_owner: mirrors `PromoteAssetIx::canonical_bytes`, which encodes
        // `Some(owner)` as the owner bytes and `None` as all-zeros. We respect
        // `nft_owner_present` so a stale non-zero `nft_owner` field (present flag
        // == 0) does not diverge from the ix encoding — otherwise the GM
        // signature would fail to verify on the server.
        if self.nft_owner_present != 0 {
            out[off..off + 32].copy_from_slice(&self.nft_owner);
        }
        // else: leave all-zeros (out is zero-initialized).
        debug_assert_eq!(off + 32, GM_SIGNABLE_LEN, "gm_signable_bytes layout invariant");
        out
    }
}

const _: () = assert!(std::mem::size_of::<CommandBarEnvelope>() == 200);

impl CommandBarEnvelope {
    /// Create a new unsigned envelope from a command string.
    /// Text longer than 128 bytes is truncated.
    pub fn new(command: &str) -> Self {
        let mut command_text = [0u8; 128];
        let bytes = command.as_bytes();
        let len = bytes.len().min(128);
        command_text[..len].copy_from_slice(&bytes[..len]);

        Self {
            action: ACTION_COMMAND,
            command_len: len as u8,
            _pad: [0; 6],
            command_text,
            gm_signature: [0; 64],
        }
    }

    /// The command text as a borrowed `&str` (lossy UTF-8 decode).
    pub fn command_str(&self) -> &str {
        let len = self.command_len as usize;
        let end = len.min(128);
        std::str::from_utf8(&self.command_text[..end]).unwrap_or("")
    }
}

use crate::{EnvelopeError, GmEnvelope};

/// Action code: bulk-populate a new engram table.
///
/// **Shipped** (Plan 373) — dispatch builds a fresh table via
/// `EngramTableBuilder` from the multi-pattern bulk payload.
pub const ACTION_ENGRAM_CREATE_TABLE: u8 = 0x60;

/// Action code: replace one slot's pattern (maps to `StagingEngramTable::update_slot`).
pub const ACTION_ENGRAM_UPDATE_SLOT: u8 = 0x61;

/// Action code: zero out one slot (maps to `StagingEngramTable::delete_slot`).
pub const ACTION_ENGRAM_DELETE_SLOT: u8 = 0x62;

/// Action code: hot-swap the published table.
///
/// **Shipped** (Plan 373) — dispatch builds a fresh table from the bulk
/// payload (same logic as CREATE_TABLE); the semantic distinction is
/// preserved at the action-code level for forward-compat audit logs.
pub const ACTION_ENGRAM_SWAP_TABLE: u8 = 0x63;

/// Action code: freeze the table to the Cold tier (Vessel write).
///
/// **Deferred** — needs a `CognitiveVessel` integration.
pub const ACTION_ENGRAM_FREEZE: u8 = 0x64;

/// Action code: thaw a frozen table back to Hot (Vessel read).
///
/// **Deferred** — needs a `CognitiveVessel` integration.
pub const ACTION_ENGRAM_THAW: u8 = 0x65;

/// Action code: read the table's BLAKE3 commitment (`EngramTableId`).
pub const ACTION_ENGRAM_QUERY_ID: u8 = 0x66;

/// Inclusive upper bound of the reserved engram action range (`0x60..=0x6F`).
pub const ENGRAM_ACTION_RANGE_END: u8 = 0x6F;

/// Maximum pattern bytes the dispatch will accept for a single-pattern op
/// (UPDATE_SLOT): 256 × 4 = 1024 bytes.
///
/// Bounds the variable-length pattern buffer so a malicious envelope can't
/// request a multi-GB allocation. 256 covers all realistic `d_mem` values per
/// Research 147 §1.
pub const MAX_PATTERN_BYTES: u32 = 1024;

/// Maximum pattern bytes for multi-pattern ops (CREATE_TABLE / SWAP_TABLE):
/// 64 KiB.
///
/// At D=4 this covers ~2730 patterns; at D=64 it covers ~248 patterns. Both
/// are well above any realistic GM-driven table populate. The bulk payload
/// is a sequence of `(u64 hash, [f32; D] pattern)` entries — see
/// [`EngramControlEnvelope::new_create_table`].
pub const MAX_CREATE_TABLE_BYTES: u32 = 65_536;

/// Returns `true` if `action` is a multi-pattern op (CREATE_TABLE or SWAP_TABLE).
///
/// These ops use the higher [`MAX_CREATE_TABLE_BYTES`] cap in `verify_invariants`
/// because their payload carries N `(hash, pattern)` entries instead of a
/// single pattern. Single-pattern ops (UPDATE_SLOT) stay at [`MAX_PATTERN_BYTES`].
#[inline]
#[must_use]
pub const fn is_multi_pattern_op(action: u8) -> bool {
    action == ACTION_ENGRAM_CREATE_TABLE || action == ACTION_ENGRAM_SWAP_TABLE
}

/// Per-entry overhead in the multi-pattern payload: 8 bytes for the `EngramHash`
/// (u64 LE) preceding each `[f32; D]` pattern.
const BULK_PATTERN_HEADER_BYTES: usize = 8;

/// Client-side envelope for GM-driven engram CRUD operations.
///
/// Layout (144 bytes, 8-byte aligned):
/// ```text
/// offset  field              size  type
/// ------  -----              ----  ----
/// 0       action              1    u8   (0x60..=0x66)
/// 1       _pad                7    [u8;7]  (align entity_id to 8)
/// 8       entity_id           8    u64 LE  (target NPC / entity)
/// 16      slot_idx            4    u32 LE  (UPDATE_SLOT / DELETE_SLOT target)
/// 20      pattern_dim         4    u32 LE  (dimensionality, validated vs source on dispatch)
/// 24      pattern_bytes_len   4    u32 LE  (length of sidecar pattern bytes)
/// 28      _pad2               4    [u8;4]  (align next field)
/// 32      engram_table_id    32    [u8;32] (BLAKE3 anti-replay commitment)
/// 64      reserved           16    [u8;16] (future-proof)
/// 80      gm_signature       64    [u8;64] (Ed25519 over canonical_bytes)
/// ```
///
/// Total size = 144 bytes. The variable-length pattern payload travels as a
/// separate wire message (see crate docs).
#[repr(C)]
#[derive(Clone, Copy, Debug, bytemuck::Pod, bytemuck::Zeroable)]
pub struct EngramControlEnvelope {
    /// Action code — one of `ACTION_ENGRAM_*` (0x60..=0x66).
    pub action: u8,
    _pad: [u8;

const _: () = assert!(std::mem::size_of::<EngramControlEnvelope>() == 144);

impl EngramControlEnvelope {
    /// Build an unsigned UPDATE_SLOT envelope.
    ///
    /// `pattern_dim` MUST match the source table's `dim()`; the dispatch
    /// validates this. `pattern_bytes.len()` MUST equal `pattern_dim * 4`.
    pub fn new_update_slot(entity_id: u64, slot_idx: u32, pattern_dim: u32) -> Self {
        Self::from_action(ACTION_ENGRAM_UPDATE_SLOT, entity_id, slot_idx, pattern_dim, pattern_dim * 4)
    }

    /// Build an unsigned DELETE_SLOT envelope. `pattern_dim` should match the
    /// source table's `dim()` for the dispatch to validate the table identity;
    /// `pattern_bytes_len` is 0 (DELETE carries no payload).
    pub fn new_delete_slot(entity_id: u64, slot_idx: u32, pattern_dim: u32) -> Self {
        Self::from_action(ACTION_ENGRAM_DELETE_SLOT, entity_id, slot_idx, pattern_dim, 0)
    }

    /// Build an unsigned QUERY_ID envelope. Returns the source table's
    /// current BLAKE3 commitment; no mutation occurs.
    pub fn new_query_id(entity_id: u64) -> Self {
        Self::from_action(ACTION_ENGRAM_QUERY_ID, entity_id, 0, 0, 0)
    }

    /// Build an unsigned CREATE_TABLE envelope (Plan 373 — multi-pattern bulk).
    ///
    /// `slot_idx` carries `n_slots` (semantic stretch — the 144-byte envelope
    /// layout is frozen and this is the only u32 field that can host a table
    /// size hint without breaking wire compat). `pattern_bytes_len` is computed
    /// from `n_patterns × (8 + pattern_dim × 4)` — each entry is a `(u64 hash,
    /// [f32; D] pattern)` pair.
    ///
    /// The caller serializes the actual pattern entries into Message 2 of the
    /// two-message wire protocol (see crate docs). This constructor only fixes
    /// the envelope header fields.
    pub fn new_create_table(entity_id: u64, n_slots: u32, pattern_dim: u32, n_patterns: u32) -> Self {
        let entry_size = BULK_PATTERN_HEADER_BYTES
            .checked_add(pattern_dim as usize * 4)
            .expect("entry_size fits in usize");
        let payload_len = (n_patterns as usize).checked_mul(entry_size).expect("n_patterns*entry_size fits in usize");
        let payload_len_u32 = u32::try_from(payload_len).expect("payload_len fits in u32");
        Self::from_action(
            ACTION_ENGRAM_CREATE_TABLE,
            entity_id,
            n_slots,
            pattern_dim,
            payload_len_u32,
        )
    }

    /// Build an unsigned SWAP_TABLE envelope (Plan 373 — multi-pattern bulk).
    ///
    /// Same wire shape as [`Self::new_create_table`] — the dispatch builds a
    /// new table from the bulk payload and returns `TableMutated(new_table)`;
    /// the caller publishes via `McpSupervisor::publish_engram_outcome` (which
    /// calls `EngramHotSwap::swap`). The semantic distinction (CREATE = first
    /// publish, SWAP = subsequent publish) is preserved at the action-code
    /// level for forward-compat audit log purposes.
    pub fn new_swap_table(entity_id: u64, n_slots: u32, pattern_dim: u32, n_patterns: u32) -> Self {
        let entry_size = BULK_PATTERN_HEADER_BYTES
            .checked_add(pattern_dim as usize * 4)
            .expect("entry_size fits in usize");
        let payload_len = (n_patterns as usize).checked_mul(entry_size).expect("n_patterns*entry_size fits in usize");
        let payload_len_u32 = u32::try_from(payload_len).expect("payload_len fits in u32");
        Self::from_action(
            ACTION_ENGRAM_SWAP_TABLE,
            entity_id,
            n_slots,
            pattern_dim,
            payload_len_u32,
        )
    }

    /// Build an unsigned FREEZE envelope.
    ///
    /// **Deferred** — the dispatch will reject with NotImplemented.
    pub fn new_freeze(entity_id: u64) -> Self {
        Self::from_action(ACTION_ENGRAM_FREEZE, entity_id, 0, 0, 0)
    }

    /// Build an unsigned THAW envelope.
    ///
    /// **Deferred** — the dispatch will reject with NotImplemented.
    pub fn new_thaw(entity_id: u64) -> Self {
        Self::from_action(ACTION_ENGRAM_THAW, entity_id, 0, 0, 0)
    }

    /// Internal constructor — assembles from raw action + payload-length fields.
    fn from_action(
        action: u8,
        entity_id: u64,
        slot_idx: u32,
        pattern_dim: u32,
        pattern_bytes_len: u32,
    ) -> Self {
        Self {
            action,
            _pad: [0; 7],
            entity_id,
            slot_idx,
            pattern_dim,
            pattern_bytes_len,
            _pad2: [0; 4],
            engram_table_id: [0u8; 32],
            reserved: [0u8; 16],
            gm_signature: [0u8; 64],
        }
    }

    /// Returns `true` if `action` is in the reserved engram range `0x60..=0x6F`.
    #[inline]
    #[must_use]
    pub const fn is_engram_action(action: u8) -> bool {
        action >= ACTION_ENGRAM_CREATE_TABLE && action <= ENGRAM_ACTION_RANGE_END
    }

    /// Returns `true` if this envelope's action is one of the deferred ops
    /// (FREEZE, THAW) — the dispatch will reject these with NotImplemented
    /// until the `CognitiveVessel` integration (Issue 004) lands.
    ///
    /// CREATE_TABLE and SWAP_TABLE graduated in Plan 373 — they are no longer
    /// deferred.
    #[inline]
    #[must_use]
    pub const fn is_deferred_op(&self) -> bool {
        matches!(self.action, ACTION_ENGRAM_FREEZE | ACTION_ENGRAM_THAW)
    }
}

