impl TierHealthEnvelope {
    /// Build an unsigned report from the collector's raw counters.
    ///
    /// The authority signs it afterwards via
    /// [`GmSigner::sign_envelope`](crate::GmSigner::sign_envelope) (or any
    /// Ed25519 signer over [`GmEnvelope::canonical_bytes`]).
    #[must_use]
    pub fn new_report(
        report_tick: u64,
        wal_lag_ms: u32,
        pending_settlement_depth: u32,
        chain_last_error_age_ms: u32,
        flags: u32,
        disk_free_bytes: u64,
        warm_live_bytes: u64,
    ) -> Self {
        Self {
            action: ACTION_TIER_HEALTH,
            _pad: [0; 7],
            report_tick,
            wal_lag_ms,
            pending_settlement_depth,
            chain_last_error_age_ms,
            flags,
            disk_free_bytes,
            warm_live_bytes,
            reserved: [0u8; 16],
            signature: [0u8; 64],
        }
    }

    /// Returns `true` if `action` is in the reserved ops/cluster range
    /// `0x05..=0x0F`.
    #[inline]
    #[must_use]
    pub const fn is_tier_health_action(action: u8) -> bool {
        action >= ACTION_TIER_HEALTH && action <= TIER_HEALTH_ACTION_RANGE_END
    }

    /// Decode a report from raw wire bytes. Zero-copy: the slice is
    /// reinterpreted, not copied — `bytes.len()` must be exactly 128.
    pub fn from_wire(bytes: &[u8]) -> Result<&Self, EnvelopeError> {
        if bytes.len() != std::mem::size_of::<Self>() {
            return Err(EnvelopeError::Invariant(format!(
                "tier-health report is {} bytes, expected {}",
                bytes.len(),
                std::mem::size_of::<Self>()
            )));
        }
        Ok(bytemuck::from_bytes(bytes))
    }
}

