const _: () = assert!(std::mem::size_of::<LatentInjectEnvelope>() == 96);

impl LatentInjectEnvelope {
    /// Create a new unsigned "set emotion" envelope.
    ///
    /// `index` selects the emotion scalar (0=valence, 1=arousal, 2=desperation,
    /// 3=calm, 4=fear). `value` is the absolute set point; the reducer clamps
    /// to `[0,1]`.
    pub fn new_set_emotion(entity_id: u64, index: u8, value: f32) -> Self {
        let mut payload = [0u8; 8];
        payload[0] = index;
        payload[4..8].copy_from_slice(&value.to_le_bytes());
        Self::from_payload(ACTION_INJECT_SET_EMOTION, entity_id, payload)
    }

    /// Create a new unsigned "adjust zone" envelope.
    ///
    /// `index` selects the zone slot (0..=7). `delta` is added to the current
    /// zone-attention score; the reducer clamps to `[0,1]`.
    pub fn new_adjust_zone(entity_id: u64, index: u8, delta: f32) -> Self {
        let mut payload = [0u8; 8];
        payload[0] = index;
        payload[4..8].copy_from_slice(&delta.to_le_bytes());
        Self::from_payload(ACTION_INJECT_ADJUST_ZONE, entity_id, payload)
    }

    /// Build an envelope from a pre-encoded payload (advanced — used by
    /// integration tests that want to mirror the exact bytes the engine sends).
    pub fn from_payload(action: u8, entity_id: u64, payload: [u8; 8]) -> Self {
        Self {
            action,
            _pad: [0; 7],
            entity_id,
            payload,
            nonce: 0,
            gm_signature: [0; 64],
        }
    }

    /// Map the envelope's action code to the reducer ix byte consumed by
    /// `LatentSidecar::reduce` / `riir_engine::wasm_bridge::reduce`.
    ///
    /// Returns `None` for actions outside the latent range (`0x50..=0x5F`).
    /// The caller (chaind handler) uses this to forward the right ix byte.
    #[inline]
    #[must_use]
    pub const fn reducer_ix(&self) -> Option<u8> {
        match self.action {
            ACTION_INJECT_SET_EMOTION => Some(ACTION_INJECT_SET_EMOTION - ACTION_TO_IX_OFFSET),
            ACTION_INJECT_ADJUST_ZONE => Some(ACTION_INJECT_ADJUST_ZONE - ACTION_TO_IX_OFFSET),
            _ => None,
        }
    }

    /// Convenience accessor: which latent op variant this envelope carries.
    #[inline]
    #[must_use]
    pub fn op_kind(&self) -> LatentOpKind {
        match self.action {
            ACTION_INJECT_SET_EMOTION => LatentOpKind::SetEmotion,
            ACTION_INJECT_ADJUST_ZONE => LatentOpKind::AdjustZone,
            _ => LatentOpKind::Unknown,
        }
    }
}

