        batch_len: u32,
        commitment: [u8; 32],
    ) -> Self {
        Self {
            action,
            _pad0: [0; 7],
            from_map,
            to_map,
            npc_idx,
            batch_len,
            commitment,
            reserved: [0u8; 24],
            gm_signature: [0u8; 64],
        }
    }

    /// Returns `true` if `action` is in the reserved NPC-migration range
    /// `0x80..=0x8F`.
    #[inline]
    #[must_use]
    pub const fn is_npc_migration_action(action: u8) -> bool {
        action >= ACTION_NPC_MIGRATION_SHIP && action <= NPC_MIGRATION_ACTION_RANGE_END
    }

    /// Returns `true` if this is a single-NPC op (`SHIP` or `RECEIVE` with
    /// `batch_len == 1`).
    #[inline]
    #[must_use]
    pub const fn is_single_npc(&self) -> bool {
        (self.action == ACTION_NPC_MIGRATION_SHIP || self.action == ACTION_NPC_MIGRATION_RECEIVE)
            && self.batch_len == 1
    }

    /// Returns `true` if this op permits `from_map == to_map` (only
    /// `NIGHT_COHORT_FREEZE`).
    #[inline]
    #[must_use]
    pub const fn allows_same_map(&self) -> bool {
        self.action == ACTION_NPC_MIGRATION_NIGHT_COHORT_FREEZE
    }
}

impl GmSigner {
    /// Load signing key from the given private key path (SSH OpenSSH format,
    /// Ed25519, unencrypted).
    pub fn load(path: &Path) -> anyhow::Result<Self> {
        let content = std::fs::read_to_string(path)
            .map_err(|e| anyhow::anyhow!("reading {}: {e}", path.display()))?;
        let private_key = ssh_key::PrivateKey::from_openssh(&content)
            .map_err(|e| anyhow::anyhow!("parsing SSH private key: {e}"))?;
        if private_key.is_encrypted() {
            anyhow::bail!(
                "Private key is encrypted (has passphrase). \
                 Generate a new key: ssh-keygen -t ed25519 -N '' -f ~/.ssh/id_ed25519"
            );
        }
        let keypair = private_key
            .key_data()
            .ed25519()
            .ok_or_else(|| anyhow::anyhow!("key is not Ed25519"))?;
        Ok(Self {
            signing_key: ed25519_dalek::SigningKey::from(&keypair.private),
        })
    }

    /// Load from default path `~/.ssh/id_ed25519`.
    pub fn load_default() -> anyhow::Result<Self> {
        let home = std::env::var("HOME").map_err(|_| anyhow::anyhow!("$HOME not set"))?;
        Self::load(Path::new(&home).join(".ssh/id_ed25519").as_path())
    }

    /// Construct from a raw 32-byte seed (used by tests / dev tooling).
    pub fn from_seed(seed: [u8; 32]) -> Self {
        Self {
            signing_key: ed25519_dalek::SigningKey::from_bytes(&seed),
        }
    }

    /// Sign a byte slice, returning the 64-byte Ed25519 signature.
    pub fn sign(&self, message: &[u8]) -> [u8; 64] {
        use ed25519_dalek::Signer;
        self.signing_key.sign(message).to_bytes()
    }

    /// Get the verifying (public) key bytes (32 bytes).
    pub fn verifying_key_bytes(&self) -> [u8; 32] {
        self.signing_key.verifying_key().to_bytes()
    }

    /// Sign a `GmEnvelope` in place — writes the signature into the
    /// envelope's `signature_mut()` slot over the `canonical_bytes()`.
    pub fn sign_envelope<E: crate::GmEnvelope>(&self, env: &mut E) {
        let sig = self.sign(env.canonical_bytes());
        *env.signature_mut() = sig;
    }
}

impl InMemoryTransport {
    /// Create a new empty in-memory transport.
    pub fn new() -> Self {
        Self {
            sent: Mutex::new(Vec::new()),
            reject_next: AtomicBool::new(false),
        }
    }

    /// Inject a rejection for the next `send` call (useful for testing
    /// error paths in consumers).
    pub fn reject_next(&self) {
        self.reject_next.store(true, Ordering::SeqCst);
    }

    /// Number of envelopes sent so far.
    pub fn sent_count(&self) -> usize {
        self.sent.lock().unwrap().len()
    }

    /// Borrow the wire bytes of the i-th sent envelope (0-indexed).
    pub fn sent_bytes(&self, index: usize) -> Vec<u8> {
        self.sent.lock().unwrap()[index].clone()
    }

    /// Borrow all sent envelopes' wire bytes (one Vec per send).
    pub fn all_sent(&self) -> Vec<Vec<u8>> {
        self.sent.lock().unwrap().clone()
    }
}

