use crate::{TransportEnv, TransportTier};

/// Pick the best transport tier for the given environment.
///
/// **Gate order** — the order the arms below actually evaluate, NOT the
/// latency ladder. [`TransportTier`]'s discriminants rank ideal-conditions
/// latency (WT > WS > WebRTC > P2P > Local); the `multiplayer` arm
/// deliberately overrides that ordering, because a mesh scenario wants peer
/// connections even where a client-server WebSocket would benchmark faster
/// (scenario beats latency — pinned by the existing tests).
///
/// 1. CF Worker → `WebSocket` (hard gate — nothing else is possible on edge;
///    `workers-rs` 0.8.x has no `webtransport()` handler on `DurableObject`,
///    seal-online POC CRITICAL-1).
/// 2. Browser + WebTransport JS global + NOT multiplayer → `WebTransport`
///    (Chrome/Edge ~75% coverage — opt-in by the JS environment, not assumed).
/// 3. Native + WT impl compiled in (Issue 667 P1) → `WebTransport`. The
///    consumer sets `webtransport_available = true` when it links the
///    `webtransport` feature. WT is the primary transport per Issue 667 —
///    native prefers it over the unimplemented WebRTC/P2P tiers whenever
///    it's available.
/// 4. Multiplayer → `P2pMesh` at ≥3 peers (mesh becomes worthwhile),
///    else `WebRtc`.
/// 5. Everything else → `WebSocket` (universal fallback; the only tier
///    that works on every platform today).
///
/// `select_tier` itself NEVER returns `Local` — the offline floor is
/// appended only by [`tier_fallback_chain`]'s tail.
///
/// **Scope (Issue 753, resolved 2026-08-24 as option (c)):** this selector
/// routes the tier that carries *game-state sync*. Single-peer client-server
/// RTC sessions (WHIP ingest, OpenAI Realtime voice) are a media traffic
/// class, not game-state sync, and deliberately bypass it — such consumers
/// construct the peer connection directly. Revisit only if a `webrtc.rs`
/// transport lands in `riir-net` (game-sdk Proposal 028 Phase 4); the
/// topology-vs-peer-count vocabulary belongs with the implementation that
/// exercises it.
///
/// For PoCs (riir-mmorpg-examples today) the result is always `WebSocket`;
/// `Local` appears only as the fallback chain's floor, never as a selection.
///
/// **CF Worker constraint is non-negotiable.** If `is_cf_worker` is true,
/// the result is always `WebSocket` regardless of `webtransport_available`.
/// The selector does not lie about what's possible.
pub fn select_tier(env: &TransportEnv) -> TransportTier {
    // CF Worker always falls to WebSocket — WebTransport is structurally
    // impossible there today (workers-rs 0.8.x gap, seal-online POC confirmed).
    // Gate before everything else so future flag combinations never leak WT.
    if env.is_cf_worker {
        return TransportTier::WebSocket;
    }

