impl SearchResultItem {
    /// Extract token sequence from description if present.
    ///
    /// Expects format: "tokens:1,2,3,4" somewhere in the description.
    /// Returns `None` if no token sequence found.
    pub fn extract_token_sequence(&self) -> Option<Vec<usize>> {
        let marker = "tokens:";
        let marker_bytes = marker.as_bytes();
        // Find "tokens:" marker case-insensitively using windows() for zero-allocation scan.
        let start = self
            .description
            .as_bytes()
            .windows(marker_bytes.len())
            .position(|w| {
                w.iter()
                    .zip(marker_bytes)
                    .all(|(a, b)| a.eq_ignore_ascii_case(b))
            })?;
        let rest = &self.description[start + marker_bytes.len()..];

        let end = rest
            .find(|c: char| !c.is_ascii_digit() && c != ',')
            .unwrap_or(rest.len());
        let token_str = &rest[..end];

        if token_str.is_empty() {
            return None;
        }

        // Pre-allocate: count commas to estimate capacity exactly.
        let estimated = token_str.bytes().filter(|&b| b == b',').count() + 1;
        let mut tokens = Vec::with_capacity(estimated);
        for s in token_str.split(',') {
            match s.trim().parse::<usize>() {
                Ok(t) => tokens.push(t),
                Err(_) => return None,
            }
        }
        if tokens.is_empty() {
            None
        } else {
            Some(tokens)
        }
    }
}

impl AgentHints {
    /// Create hints for an interactive (user-facing) request.
    pub fn interactive() -> Self {
        Self {
            latency_sensitivity: 1.0,
            speculative_prefill: true,
            priority: 128,
        }
    }

    /// Create hints for a background (batch/tool-chain) request.
    pub fn background() -> Self {
        Self {
            latency_sensitivity: 0.0,
            speculative_prefill: false,
            priority: 0,
        }
    }

    /// Parse hints from a header value string.
    /// Format: `latency=0.8;prefill=true;priority=64`
    /// Unknown keys are ignored. Missing keys get defaults.
    pub fn from_header(value: &str) -> Self {
        let mut hints = Self::default();
        for part in value.split(';') {
            let part = part.trim();
            if let Some((key, val)) = part.split_once('=') {
                match key.trim() {
                    "latency" => {
                        if let Ok(v) = val.trim().parse::<f32>() {
                            hints.latency_sensitivity = v.clamp(0.0, 1.0);
                        }
                    }
                    "prefill" => {
                        hints.speculative_prefill = val.trim().eq_ignore_ascii_case("true");
                    }
                    "priority" => {
                        if let Ok(v) = val.trim().parse::<u8>() {
                            hints.priority = v;
                        }
                    }
                    _ => {} // ignore unknown keys
                }
            }
        }
        hints
    }
}

impl Validator for BomberValidator {
    fn name(&self) -> &str {
        "bomber_validator"
    }

    fn version(&self) -> (u8, u8, u8) {
        (1, 0, 0)
    }

    /// Check if `token_idx` (action) is safe given the game state
    /// packed into `parent_tokens`.
    ///
    /// Only `depth == 0` is meaningful. Returns `false` for all
    /// other depths.
    fn is_valid(&self, depth: usize, token_idx: usize, parent_tokens: &[usize]) -> bool {
        if depth != 0 || token_idx >= ACTION_COUNT {
            return false;
        }

        let Some((bomb_count, _bombs_end)) = Self::parse_buffer(parent_tokens) else {
            return false;
        };

        let px = parent_tokens[OFF_PLAYER_X] as i32;
        let py = parent_tokens[OFF_PLAYER_Y] as i32;

        match token_idx {
            // ── Movement actions ────────────────────────────────
            ACTION_UP | ACTION_DOWN | ACTION_LEFT | ACTION_RIGHT => {
                let (tx, ty) = Self::move_target(token_idx, px, py);
                if !Self::is_walkable(parent_tokens, tx, ty) {
                    return false;
                }
                // Don't walk into blast zone (walls block blast)
                !Self::in_blast_zone(parent_tokens, bomb_count, tx, ty)
            }

            // ── Bomb action ─────────────────────────────────────
            ACTION_BOMB => {
                // Don't place if already in blast zone
                if Self::in_blast_zone(parent_tokens, bomb_count, px, py) {
                    return false;
                }

                // Don't place if there's already a bomb here
                for i in 0..bomb_count {
                    if let Some((bx, by, _, _)) = Self::get_bomb(parent_tokens, i)
                        && bx == px
                        && by == py
                    {
                        return false;
                    }
                }

                // Must have at least one adjacent destructible wall
                if Self::count_adjacent_walls(parent_tokens, px, py) == 0 {
                    return false;
                }

                // Player will move to an adjacent cell next tick.
                // From that cell, BFS checks if safety is reachable
                // within blast_range+1 steps.
                [(0i32, -1i32), (0, 1), (-1, 0), (1, 0)]
                    .iter()
                    .any(|&(dx, dy)| {
                        let nx = px + dx;
                        let ny = py + dy;
                        Self::is_walkable(parent_tokens, nx, ny)
                            && Self::has_escape_route(
                                parent_tokens,
                                nx,
                                ny,
                                px,
                                py,
                                DEFAULT_BLAST_RANGE,
                                bomb_count,
                            )
                    })
            }

            // ── Detonate action ───────────────────────────────────
            // Matches native `is_safe_action::BomberAction::Detonate`:
            //   valid when active bombs exist AND player is not in any blast zone.
            //
            // Future: restrict to Remote bombs only once bomb_type is carried in
            // the WASM ABI (currently all bombs are treated as Timed). This is
            // intentionally permissive to match the native baseline byte-for-byte.
            ACTION_DETONATE => {
                bomb_count > 0 && !Self::in_blast_zone(parent_tokens, bomb_count, px, py)
            }

            // ── Wait action ─────────────────────────────────────
            ACTION_WAIT => {
                // Safe only if not in blast zone
                !Self::in_blast_zone(parent_tokens, bomb_count, px, py)
            }

            _ => false,
        }
    }

    /// Compute the relevance score for `token_idx` (action).
    ///
    /// Returns `0.0` for unsafe or invalid actions.
    /// Returns `0.2` for Wait (low priority).
    /// Returns `0.5–0.9` for movement actions (contextual).
    /// Returns `0.7–1.0` for bomb actions (contextual).
    fn relevance(&self, depth: usize, token_idx: usize, parent_tokens: &[usize]) -> f32 {
        if depth != 0 || token_idx >= ACTION_COUNT {
            return 0.0;
        }

        let Some((bomb_count, _bombs_end)) = Self::parse_buffer(parent_tokens) else {
            return 0.0;
        };

        let px = parent_tokens[OFF_PLAYER_X] as i32;
        let py = parent_tokens[OFF_PLAYER_Y] as i32;

        match token_idx {
            ACTION_UP | ACTION_DOWN | ACTION_LEFT | ACTION_RIGHT => {
                self.score_move(token_idx, parent_tokens, px, py, bomb_count)
            }
            ACTION_BOMB => self.score_bomb(parent_tokens, px, py, bomb_count),
            ACTION_WAIT => {
                if Self::in_blast_zone(parent_tokens, bomb_count, px, py) {
                    0.0
                } else {
                    0.2
                }
            }
            _ => 0.0,
        }
    }
}

impl BracketValidator {
    /// Count bracket balance deltas for a single token.
    ///
    /// Returns `(paren_delta, brace_delta, bracket_delta)`.
    /// Opening brackets add +1, closing brackets add -1, others add 0.
    fn token_delta(&self, token_idx: usize) -> (i32, i32, i32) {
        match token_idx {
            t if t == self.open_paren => (1, 0, 0),
            t if t == self.close_paren => (-1, 0, 0),
            t if t == self.open_brace => (0, 1, 0),
            t if t == self.close_brace => (0, -1, 0),
            t if t == self.open_bracket => (0, 0, 1),
            t if t == self.close_bracket => (0, 0, -1),
            _ => (0, 0, 0),
        }
    }

    /// Accumulate bracket depths for a slice of tokens.
    fn accumulate_depths(&self, tokens: &[usize], start: usize) -> (i32, i32, i32) {
        let (mut dp, mut db, mut dk) = (0i32, 0i32, 0i32);
        for &t in &tokens[start..] {
            let (dp2, db2, dk2) = self.token_delta(t);
            dp += dp2;
            db += db2;
            dk += dk2;
        }
        (dp, db, dk)
    }

    /// Check if adding this token would create an invalid state
    /// (any bracket depth going negative).
    ///
    /// Uses incremental depth caching: only scans new parent tokens beyond
    /// what was already computed in the previous call.
    fn would_be_valid(&self, token_idx: usize, parent_tokens: &[usize]) -> bool {
        let cached_len = self.cached_len.load(Ordering::Relaxed);
        let mut paren_depth = self.cached_paren.load(Ordering::Relaxed);
        let mut brace_depth = self.cached_brace.load(Ordering::Relaxed);
        let mut bracket_depth = self.cached_bracket.load(Ordering::Relaxed);

        if parent_tokens.len() >= cached_len {
            let (dp, db, dk) = self.accumulate_depths(parent_tokens, cached_len);
            paren_depth += dp;
            brace_depth += db;
            bracket_depth += dk;
        } else {
            // Parent tokens shrunk (e.g. backtrack) — recompute from scratch
            let (dp, db, dk) = self.accumulate_depths(parent_tokens, 0);
            paren_depth = dp;
            brace_depth = db;
            bracket_depth = dk;
        }
        self.cached_paren.store(paren_depth, Ordering::Relaxed);
        self.cached_brace.store(brace_depth, Ordering::Relaxed);
        self.cached_bracket.store(bracket_depth, Ordering::Relaxed);
        self.cached_len
            .store(parent_tokens.len(), Ordering::Relaxed);

        // Apply the candidate token
        let (dp, db, dk) = self.token_delta(token_idx);
        paren_depth += dp;
        brace_depth += db;
        bracket_depth += dk;

        // Reject if any depth goes negative (closing without opening)
        paren_depth >= 0 && brace_depth >= 0 && bracket_depth >= 0
    }
}

impl Validator for BracketValidator {
    fn name(&self) -> &str {
        "bracket_validator"
    }

    fn version(&self) -> (u8, u8, u8) {
        (1, 0, 0)
    }

    fn is_valid(&self, _depth: usize, token_idx: usize, parent_tokens: &[usize]) -> bool {
        self.would_be_valid(token_idx, parent_tokens)
    }

    fn validate_string(&self, code: &str) -> bool {
        let mut paren_depth: i32 = 0;
        let mut brace_depth: i32 = 0;
        let mut bracket_depth: i32 = 0;
        let mut in_string: bool = false;
        let mut in_char: bool = false;
        let mut in_line_comment: bool = false;
        let mut in_block_comment: bool = false;

        let bytes = code.as_bytes();
        let len = bytes.len();
        let mut i = 0;

        while i < len {
            let ch = bytes[i];

            // Handle string literals
            if in_string {
                match ch {
                    b'\\' => i += 1, // skip escaped char
                    b'"' => in_string = false,
                    _ => {}
                }
                i += 1;
                continue;
            }

            // Handle char literals
            if in_char {
                match ch {
                    b'\\' => i += 1,
                    b'\'' => in_char = false,
                    _ => {}
                }
                i += 1;
                continue;
            }

            // Handle line comments
            if in_line_comment {
                if ch == b'\n' {
                    in_line_comment = false;
                }
                i += 1;
                continue;
            }

            // Handle block comments
            if in_block_comment {
                if ch == b'*' && i + 1 < len && bytes[i + 1] == b'/' {
                    in_block_comment = false;
                    i += 2;
                    continue;
                }
                i += 1;
                continue;
            }

            // Check for comment starts
            if ch == b'/' && i + 1 < len {
                match bytes[i + 1] {
                    b'/' => {
                        in_line_comment = true;
                        i += 2;
                        continue;
                    }
                    b'*' => {
                        in_block_comment = true;
                        i += 2;
                        continue;
                    }
                    _ => {}
                }
            }

            // Track brackets
            match ch {
                b'(' => paren_depth += 1,
                b')' => {
                    paren_depth -= 1;
                    if paren_depth < 0 {
                        return false;
                    }
                }
                b'{' => brace_depth += 1,
                b'}' => {
                    brace_depth -= 1;
                    if brace_depth < 0 {
                        return false;
                    }
                }
                b'[' => bracket_depth += 1,
                b']' => {
                    bracket_depth -= 1;
                    if bracket_depth < 0 {
                        return false;
                    }
                }
                b'"' => in_string = true,
                b'\'' => {
                    // Heuristic: if followed by a char then ', it's a char literal
                    if i + 2 < len && bytes[i + 2] == b'\'' {
                        in_char = true;
                    } else if i + 1 < len
                        && (bytes[i + 1].is_ascii_alphabetic() || bytes[i + 1] == b'_')
                    {
                        // Likely a lifetime — skip
                    } else {
                        in_char = true;
                    }
                }
                _ => {}
            }

            i += 1;
        }

        // For partial code (DDTree context), allow unclosed brackets
        // Only reject if depth went negative (too many closing)
        paren_depth >= 0 && brace_depth >= 0 && bracket_depth >= 0
    }
}

impl GameActionValidator {
    /// Check if token is a command prefix (M, A, C, I).
    fn is_command(token: usize) -> bool {
        matches!(token, CMD_MOVE | CMD_ATTACK | CMD_CAST | CMD_IDLE)
    }

    /// Check if token is a direction (N, S, E, W).
    fn is_direction(token: usize) -> bool {
        matches!(token, DIR_NORTH | DIR_SOUTH | DIR_EAST | DIR_WEST)
    }

    /// Check if token is a spell type (F, I, H).
    fn is_spell(token: usize) -> bool {
        matches!(token, SPELL_FIRE | SPELL_ICE | SPELL_HEAL)
    }

    /// Check if token is a numeric parameter (1-9).
    fn is_numeric(token: usize) -> bool {
        (b'1'..=b'9').contains(&(token as u8))
    }

    /// Check if token is a separator or terminator (space, period, semicolon).
    fn is_separator(token: usize) -> bool {
        matches!(token, SEP_SPACE | TERM_CMD | TERM_SEQ)
    }

    /// Check if token is valid at depth 1 given a parent command.
    fn is_valid_depth1(parent_cmd: usize, token: usize) -> bool {
        match parent_cmd {
            CMD_MOVE | CMD_ATTACK => Self::is_direction(token),
            CMD_CAST => Self::is_spell(token),
            CMD_IDLE => Self::is_separator(token),
            _ => false,
        }
    }
}

impl Validator for GameActionValidator {
    fn name(&self) -> &str {
        "game_action_validator"
    }

    fn version(&self) -> (u8, u8, u8) {
        (1, 0, 0)
    }

    fn is_valid(&self, depth: usize, token_idx: usize, parent_tokens: &[usize]) -> bool {
        // Token 0 (padding) is always invalid
        if token_idx == PADDING {
            return false;
        }

        match depth {
            // Depth 0: must be a command prefix
            0 => Self::is_command(token_idx),

            // Depth 1: depends on parent command
            1 => match parent_tokens.first() {
                Some(&parent) => Self::is_valid_depth1(parent, token_idx),
                None => false,
            },

            // Depth 2: numeric parameter or separator/terminator
            2 => Self::is_numeric(token_idx) || Self::is_separator(token_idx),

            // Depth 3+: separator or terminator only
            _ => Self::is_separator(token_idx),
        }
    }

    fn relevance(&self, depth: usize, token_idx: usize, parent_tokens: &[usize]) -> f32 {
        // Invalid tokens always score 0.0
        if !self.is_valid(depth, token_idx, parent_tokens) {
            return 0.0;
        }

        // Score based on command type at depth 0
        if depth == 0 {
            return match token_idx {
                CMD_ATTACK => 0.9, // High priority near enemies
                CMD_CAST => 0.8,   // Useful spells
                CMD_MOVE => 0.7,   // Moving toward objective
                CMD_IDLE => 0.3,   // Valid but low priority
                _ => 0.5,
            };
        }

        // Score parameters contextually
        if depth == 1 {
            let parent = parent_tokens.first().copied().unwrap_or(0);
            return match parent {
                CMD_ATTACK => 0.9, // Attack direction is critical
                CMD_CAST => 0.8,   // Spell selection matters
                CMD_MOVE => 0.7,   // Movement direction
                CMD_IDLE => 0.2,   // Idle continuation
                _ => 0.5,
            };
        }

        // Default for valid tokens at deeper depths
        0.5
    }

    fn validate_string(&self, code: &str) -> bool {
        let code = code.trim();
        if code.is_empty() {
            return true;
        }

        // Split by semicolons for command sequences
        for command in code.split(';') {
            let command = command.trim();
            if command.is_empty() {
                continue;
            }

            let bytes = command.as_bytes();
            if bytes.is_empty() {
                continue;
            }

            // First byte must be a valid command prefix
            let prefix = bytes[0];
            if !Self::is_command(prefix as usize) {
                return false;
            }

            // Validate remaining bytes based on command type
            let params = &bytes[1..];
            match prefix {
                b'M' | b'A' => {
                    // MOVE/ATTACK: direction + optional numeric
                    if params.is_empty() {
                        continue; // Allow trailing/incomplete commands
                    }
                    if !Self::is_direction(params[0] as usize) {
                        return false;
                    }
                    // Optional numeric parameter
                    if params.len() > 1 && !Self::is_numeric(params[1] as usize) {
                        return false;
                    }
                }
                b'C' => {
                    // CAST: spell type + optional numeric
                    if params.is_empty() {
                        continue;
                    }
                    if !Self::is_spell(params[0] as usize) {
                        return false;
                    }
                    if params.len() > 1 && !Self::is_numeric(params[1] as usize) {
                        return false;
                    }
                }
                b'I' => {
                    // IDLE: no parameters expected
                }
                _ => return false,
            }
        }

        true
    }
}

impl KeywordValidator {
    /// Check if a token is an "identifier-like" character (letter or digit).
    fn is_identifier_like(token_idx: usize) -> bool {
        let ch = token_idx as u8;
        ch.is_ascii_alphabetic() || ch.is_ascii_digit() || ch == b'_'
    }

    /// Compute brace depth from parent tokens.
    fn brace_depth(&self, parent_tokens: &[usize]) -> i32 {
        let mut depth: i32 = 0;
        for &t in parent_tokens {
            if t == self.open_brace {
                depth += 1;
            } else if t == self.close_brace {
                depth -= 1;
            }
        }
        depth
    }
}

impl Validator for KeywordValidator {
    fn name(&self) -> &str {
        "keyword_validator"
    }

    fn version(&self) -> (u8, u8, u8) {
        (1, 0, 0)
    }

    fn is_valid(&self, depth: usize, token_idx: usize, parent_tokens: &[usize]) -> bool {
        // Rule 0: Reject padding token (index 0)
        if token_idx == 0 {
            return false;
        }

        // Rule 1: `=` must not appear at depth 0 without `let`
        if token_idx == self.equals && depth == 0 {
            return false;
        }

        // Rule 2: `;` must not follow another `;` (no empty statements)
        if token_idx == self.semicolon && parent_tokens.last() == Some(&self.semicolon) {
            return false;
        }

        // Rule 3: `{` should be preceded by `)` or an identifier
        if token_idx == self.open_brace
            && depth > 0
            && let Some(&last) = parent_tokens.last()
            && (last == self.semicolon || last == self.colon)
        {
            return false;
        }

        // Rule 4: `}` must not cause negative brace depth
        if token_idx == self.close_brace {
            let current_depth = self.brace_depth(parent_tokens);
            if current_depth <= 0 {
                return false;
            }
        }

        // Rule 5: `:` is only valid after an identifier-like token
        if token_idx == self.colon
            && depth > 0
            && let Some(&last) = parent_tokens.last()
            && !Self::is_identifier_like(last)
            && last != self.close_paren
        {
            return false;
        }

        true
    }

    fn validate_string(&self, code: &str) -> bool {
        // Simple keyword-aware string validation:
        // - No double semicolons
        // - Brackets don't go negative
        // - No top-level `=` without preceding `let`

        let bytes = code.as_bytes();
        let len = bytes.len();

        if len == 0 {
            return true;
        }

        let mut brace_depth: i32 = 0;
        let mut paren_depth: i32 = 0;
        let mut prev_was_semicolon: bool = false;

        for i in 0..len {
            let ch = bytes[i];

            match ch {
                b';' => {
                    if prev_was_semicolon {
                        return false;
                    }
                    prev_was_semicolon = true;
                }
                b'{' => {
                    brace_depth += 1;
                    prev_was_semicolon = false;
                }
                b'}' => {
                    brace_depth -= 1;
                    if brace_depth < 0 {
                        return false;
                    }
                    prev_was_semicolon = false;
                }
                b'(' => {
                    paren_depth += 1;
                    prev_was_semicolon = false;
                }
                b')' => {
                    paren_depth -= 1;
                    if paren_depth < 0 {
                        return false;
                    }
                    prev_was_semicolon = false;
                }
                b'=' => {
                    // Top-level assignment without `let` — check if preceded by "let "
                    if brace_depth == 0 && i >= 4 {
                        // Simple check: does "let " appear before this `=`?
                        let before = &code[..i];
                        if !before.contains("let ") && !before.contains("let\t") {
                            // Could be top-level assignment without let
                            // But we allow `==` comparison, so skip if next is `=`
                            if i + 1 < len && bytes[i + 1] == b'=' {
                                // It's `==`, which is fine
                            }
                            // For simplicity, allow all `=` at brace depth 0
                            // A real validator would be more strict
                        }
                    }
                    prev_was_semicolon = false;
                }
                _ => {
                    if ch != b' ' && ch != b'\t' && ch != b'\n' && ch != b'\r' {
                        prev_was_semicolon = false;
                    }
                }
            }
        }

        // Allow partial code (unclosed brackets OK, just no negative depth)
        brace_depth >= 0 && paren_depth >= 0
    }
}

