use riir_validator_sdk::Validator;

// ── Quest state tokens (depth 0) ─────────────────────────────────

/// NotStarted quest state token.
const STATE_NOT_STARTED: usize = b'N' as usize;

impl QuestFsmValidator {
    /// Check if token is a quest state prefix (N, I, C, F).
    fn is_state(token: usize) -> bool {
        matches!(
            token,
            STATE_NOT_STARTED | STATE_IN_PROGRESS | STATE_COMPLETED | STATE_FAILED
        )
    }

    /// Check if an action is valid for the given parent state.
    ///
    /// Uses direct match instead of linear scan for O(1) lookup.
    fn is_valid_action(parent_state: usize, action: usize) -> bool {
        match parent_state {
            STATE_NOT_STARTED => matches!(
                action,
                ACTION_GREET | ACTION_OFFER | ACTION_ACCEPT | ACTION_REJECT | ACTION_FAIL
            ),
            STATE_IN_PROGRESS => matches!(
                action,
                ACTION_REMIND | ACTION_UPDATE | ACTION_REJECT | ACTION_FAIL
            ),
            STATE_COMPLETED => matches!(action, ACTION_THANKS | ACTION_REWARD),
            STATE_FAILED => matches!(action, ACTION_OFFER | ACTION_ACCEPT),
            _ => false,
        }
    }

    /// Compute the resulting quest state after applying an action.
    ///
    /// Returns `None` if the action is invalid for the given state.
    fn apply_action(state: usize, action: usize) -> Option<usize> {
        match (state, action) {
            // NotStarted + Accept → InProgress
            (STATE_NOT_STARTED, ACTION_ACCEPT) => Some(STATE_IN_PROGRESS),
            // NotStarted + Fail → Failed
            (STATE_NOT_STARTED, ACTION_FAIL) => Some(STATE_FAILED),
            // NotStarted + other → stays NotStarted
            (STATE_NOT_STARTED, ACTION_GREET | ACTION_OFFER | ACTION_REJECT) => {
                Some(STATE_NOT_STARTED)
            }

            // InProgress + Fail → Failed
            (STATE_IN_PROGRESS, ACTION_FAIL) => Some(STATE_FAILED),
            // InProgress + Reject → Failed (abandoned)
            (STATE_IN_PROGRESS, ACTION_REJECT) => Some(STATE_FAILED),
            // InProgress + other → stays InProgress
            (STATE_IN_PROGRESS, ACTION_REMIND | ACTION_UPDATE) => Some(STATE_IN_PROGRESS),

            // Completed + Thanks/Reward → stays Completed
            (STATE_COMPLETED, ACTION_THANKS | ACTION_REWARD) => Some(STATE_COMPLETED),

            // Failed + Offer/Accept → NotStarted (re-offer)
            (STATE_FAILED, ACTION_OFFER | ACTION_ACCEPT) => Some(STATE_NOT_STARTED),

            _ => None,
        }
    }

    /// Compute relevance score for a quest state transition.
    ///
    /// Higher scores for productive transitions (accept, complete),
    /// lower for stalling (greet, remind) or negative (fail, reject).
    fn transition_relevance(state: usize, action: usize) -> f32 {
        match (state, action) {
            // Productive transitions — high relevance
            (STATE_NOT_STARTED, ACTION_ACCEPT) => 0.95,
            (STATE_IN_PROGRESS, ACTION_UPDATE) => 0.85,

            // Positive but not advancing — medium relevance
            (STATE_NOT_STARTED, ACTION_OFFER) => 0.7,
            (STATE_NOT_STARTED, ACTION_GREET) => 0.5,
            (STATE_IN_PROGRESS, ACTION_REMIND) => 0.6,
            (STATE_COMPLETED, ACTION_THANKS) => 0.6,
            (STATE_COMPLETED, ACTION_REWARD) => 0.8,

            // Recovery from failure — moderate relevance
            (STATE_FAILED, ACTION_OFFER) => 0.65,
            (STATE_FAILED, ACTION_ACCEPT) => 0.75,

            // Negative transitions — low relevance
            (STATE_NOT_STARTED, ACTION_REJECT) => 0.3,
            (STATE_IN_PROGRESS, ACTION_REJECT) => 0.25,
            (STATE_NOT_STARTED, ACTION_FAIL) => 0.15,
            (STATE_IN_PROGRESS, ACTION_FAIL) => 0.15,

            _ => 0.0,
        }
    }

    /// Compute the current FSM state by replaying parent tokens.
    ///
    /// Returns `None` if any prior action was invalid for its state.
    fn resolve_state(parent_tokens: &[usize]) -> Option<usize> {
        let &state = parent_tokens.first()?;
        let mut current_state = state;
        for &tok in &parent_tokens[1..] {
            if tok == SEP_END {
                continue;
            }
            current_state = Self::apply_action(current_state, tok)?;
        }
        Some(current_state)
    }
}

impl Validator for QuestFsmValidator {
    fn name(&self) -> &str {
        "quest_fsm"
    }

    fn version(&self) -> (u8, u8, u8) {
        (1, 0, 0)
    }

    fn is_valid(&self, depth: usize, token_idx: usize, parent_tokens: &[usize]) -> bool {
        // Padding is never valid.
        if token_idx == PADDING {
            return false;
        }

        match depth {
            // Depth 0: must be a quest state prefix.
            0 => Self::is_state(token_idx),

            // Depth 1: dialog action — must be valid for the parent state.
            1 => match parent_tokens.first() {
                Some(&state) => Self::is_valid_action(state, token_idx),
                None => false,
            },

            // Depth 2+: allow end-of-turn separator or more actions
            // if the previous action keeps the state unchanged.
            _ => {
                if token_idx == SEP_END {
                    return true;
                }
                match Self::resolve_state(parent_tokens) {
                    Some(current_state) => Self::is_valid_action(current_state, token_idx),
                    None => false,
                }
            }
        }
    }

    fn relevance(&self, depth: usize, token_idx: usize, parent_tokens: &[usize]) -> f32 {
        // Padding is never valid.
        if token_idx == PADDING {
            return 0.0;
        }

        match depth {
            // Depth 0: state prefixes get neutral score.
            0 if Self::is_state(token_idx) => 0.5,
            0 => 0.0,

            // Depth 1: score based on state transition quality.
            1 => match parent_tokens.first() {
                Some(&state) if Self::is_valid_action(state, token_idx) => {
                    Self::transition_relevance(state, token_idx)
                }
                _ => 0.0,
            },

            // Depth 2+: separator is neutral, actions use transition score.
            _ => {
                if token_idx == SEP_END {
                    return 0.3;
                }
                // Single traversal: resolve state, check validity, compute relevance.
                match Self::resolve_state(parent_tokens) {
                    Some(current_state) if Self::is_valid_action(current_state, token_idx) => {
                        Self::transition_relevance(current_state, token_idx)
                    }
                    _ => 0.0,
                }
            }
        }
    }

    fn validate_string(&self, code: &str) -> bool {
        let code = code.trim();
        if code.is_empty() {
            return true;
        }

        // Split by semicolons for multi-turn dialog.
        for turn in code.split(';') {
            let turn = turn.trim();
            if turn.is_empty() {
                continue;
            }

            let bytes = turn.as_bytes();
            if bytes.is_empty() {
                continue;
            }

            // First byte must be a valid state prefix.
            let state = bytes[0] as usize;
            if !Self::is_state(state) {
                return false;
            }

            // Validate remaining actions for this state.
            let mut current_state = state;
            for &b in &bytes[1..] {
                let action = b as usize;
                if action == SEP_END {
                    continue;
                }
                match Self::apply_action(current_state, action) {
                    Some(next) => current_state = next,
                    None => return false,
                }
            }
        }

        true
    }
}

