const BATCHES: usize = SINGLE_CALLS / BATCH_LEN; // 3125 batches

fn bench_batched(c: &mut Criterion) {
    let bytes = build_wasm();
    let mut group = c.benchmark_group("cog_batched_call");
    group.throughput(Throughput::Elements(SINGLE_CALLS as u64));
    group.sample_size(50);

    let states: Vec<f32> = (0..BATCH_LEN).map(|i| i as f32 * 0.001).collect();
    let dirs: Vec<f32> = vec![0.7; BATCH_LEN];
    let mut out_native = vec![0.0f32; BATCH_LEN];

    // Native baseline.
    group.bench_function(BenchmarkId::new("native", "batch"), |b| {
        b.iter(|| {
            for _ in 0..BATCHES {
                native_cognition_batch(black_box(&states), black_box(&dirs), &mut out_native);
            }
            black_box(out_native[0])
        });
    });

    // wasmtime — write inputs to linear memory once per batch, call cog_batch.
    {
        let (mut store, _step, batch, memory) = setup_wasmtime(&bytes);
        // Pre-allocate scratch in WASM linear memory: states@0, dirs@256, out@512.
        let states_ptr: u32 = 0;
        let dirs_ptr: u32 = (BATCH_LEN * 4) as u32;
        let out_ptr: u32 = (2 * BATCH_LEN * 4) as u32;
        group.bench_function(BenchmarkId::new("wasmtime", "batch"), |b| {
            b.iter(|| {
                store.set_fuel(1_000_000_000).unwrap();
                for _ in 0..BATCHES {
                    // Host→guest: write states + dirs (the per-NPC latent state).
                    memory
                        .write(&mut store, states_ptr as usize, bytemuck::cast_slice(black_box(&states)))
                        .unwrap();
                    memory
                        .write(&mut store, dirs_ptr as usize, bytemuck::cast_slice(black_box(&dirs)))
                        .unwrap();
                    let _ = batch
                        .call(&mut store, (BATCH_LEN as u32, states_ptr, dirs_ptr, out_ptr))
                        .unwrap();
                }
                let mut out = [0.0f32; 1];
                memory.read(&store, out_ptr as usize, bytemuck::cast_slice_mut(&mut out)).unwrap();
                black_box(out[0])
            });
        });
    }

    // wasmi — Memory::write(store, offset, slice) signature (1.0/1.1).
    {
        let (mut store, _step, batch, memory) = setup_wasmi(&bytes);
        let states_ptr: u32 = 0;
        let dirs_ptr: u32 = (BATCH_LEN * 4) as u32;
        let out_ptr: u32 = (2 * BATCH_LEN * 4) as u32;
        let states_bytes: &[u8] = bytemuck::cast_slice(&states);
        let dirs_bytes: &[u8] = bytemuck::cast_slice(&dirs);
        group.bench_function(BenchmarkId::new("wasmi", "batch"), |b| {
            b.iter(|| {
                store.set_fuel(1_000_000_000).unwrap();
                for _ in 0..BATCHES {
                    memory
                        .write(&mut store, states_ptr as usize, black_box(states_bytes))
                        .unwrap();
                    memory
                        .write(&mut store, dirs_ptr as usize, black_box(dirs_bytes))
                        .unwrap();
                    let _ = batch
                        .call(&mut store, (BATCH_LEN as u32, states_ptr, dirs_ptr, out_ptr))
                        .unwrap();
                }
                black_box(0.0f32)
            });
        });
    }

    group.finish();
}

