impl WasmProgressSignal {
    /// Create a new progress signal with the given minimum acceptance rate.
    ///
    /// `min_accept_rate` typically in [0.1, 0.5] — branches below this are
    /// considered dead ends.
    ///
    /// `window_size` controls the EMA responsiveness. Larger = more stable,
    /// smaller = more reactive.
    pub fn new(min_accept_rate: f32, window_size: usize) -> Self {
        Self {
            branch_rates: Vec::new(),
            min_accept_rate,
            alpha: 1.0 / window_size.max(1) as f32,
        }
    }

    /// Convenience constructor with default window size of 100.
    pub fn with_threshold(min_accept_rate: f32) -> Self {
        Self::new(min_accept_rate, 100)
    }

    /// Record a WASM validation result for a branch.
    pub fn record(&mut self, branch_id: usize, accepted: bool) {
        // Ensure branch slot exists — assume productive (1.0) until proven otherwise.
        while self.branch_rates.len() <= branch_id {
            self.branch_rates.push(1.0);
        }
        // Branch-free EMA update: target is 1.0 on accept, 0.0 on reject.
        //   rate += alpha * (target - rate)
        // is equivalent to the two-branch form but avoids a mispredicted branch
        // in the hot validation-recording path.
        let target = accepted as u8 as f32;
        let rate = self.branch_rates[branch_id];
        self.branch_rates[branch_id] = rate + self.alpha * (target - rate);
    }

    /// Check if a branch is making progress (acceptance rate >= threshold).
    pub fn is_productive(&self, branch_id: usize) -> bool {
        match self.branch_rates.get(branch_id) {
            Some(&rate) => rate >= self.min_accept_rate,
            None => true, // Unknown branch → assume productive
        }
    }

    /// Overall progress signal for the decomposition.
    ///
    /// Returns 0.0 (no branches productive) to 1.0 (all branches productive).
    pub fn overall_progress(&self) -> f32 {
        if self.branch_rates.is_empty() {
            return 1.0;
        }
        self.branch_rates.iter().sum::<f32>() / self.branch_rates.len() as f32
    }

    /// Get the acceptance rate for a specific branch.
    ///
    /// Returns 1.0 for unknown branches (assumed productive).
    pub fn branch_rate(&self, branch_id: usize) -> f32 {
        self.branch_rates.get(branch_id).copied().unwrap_or(1.0)
    }

    /// Number of branches currently tracked.
    #[inline]
    pub fn branch_count(&self) -> usize {
        self.branch_rates.len()
    }
}

