use std::collections::{HashMap, VecDeque};

use blake3::Hash;

// ── Versioning ─────────────────────────────────────────────────────────────

/// Current binary format version byte.
const FORMAT_VERSION: u8 = 1;

/// Serialized entry size: state_hash(8) + outcome(1) + latency_ns(4) + game_phase(1) + timestamp(8) = 22 bytes.
const ENTRY_SIZE: usize = 22;

/// Header size: version(1) + max_entries(8) + validator_hash(32) + entry_count(4) = 45 bytes.
const HEADER_SIZE: usize = 1 + 8 + 32 + 4;

// ── Types ──────────────────────────────────────────────────────────────────

/// Per-validator experience log. Binary format.
/// Bounded to `max_entries` (default 2048). Oldest entries evicted on overflow.
#[derive(Debug, Clone)]
pub struct ValidatorMemory {
    entries: VecDeque<MemoryEntry>,
    max_entries: usize,
    validator_hash: Hash,
    /// Secondary index: state_hash → Vec<logical_index> for O(1) lookup.
    /// Logical index = base_index + physical position in VecDeque.
    state_hash_index: HashMap<u64, Vec<usize>>,
    /// Logical index of `entries[0]`. Incremented on eviction so HashMap
    /// indices remain stable without rewriting the entire map.
    base_index: usize,
    // ── Incremental stats counters (O(1) stats() instead of O(n) scan) ──
    accepted_count: u32,
    rejected_count: u32,
    edge_case_count: u32,
    /// Sum of `latency_ns` across all entries (u64 to avoid overflow at 2048 entries).
    total_latency_ns: u64,
}

/// Single experience entry recording one validation outcome.
///
/// Field order minimizes padding: u64 → u64 → u32 → u8 → u8 (24 bytes vs 32 naive).
/// The serialized layout (ENTRY_SIZE) is independent of this struct layout.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct MemoryEntry {
    /// blake3 of game state truncated to u64.
    pub state_hash: u64,
    /// Monotonic timestamp (nanoseconds since epoch or session start).
    pub timestamp: u64,
    /// Validation latency in nanoseconds.
    pub latency_ns: u32,
    /// Whether the validator accepted, rejected, or hit an edge case.
    pub outcome: ValidationOutcome,
    /// Game phase (game-specific encoding).
    pub game_phase: u8,
}

/// Outcome of a single validation pass.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(u8)]
pub enum ValidationOutcome {
    /// Validator accepted the state.
    Accepted = 0,
    /// Validator rejected the state.
    Rejected = 1,
    /// Edge case — ambiguous or borderline.
    EdgeCase = 2,
}

impl ValidationOutcome {
    fn from_u8(v: u8) -> Option<Self> {
        match v {
            0 => Some(Self::Accepted),
            1 => Some(Self::Rejected),
            2 => Some(Self::EdgeCase),
            _ => None,
        }
    }

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum MemoryError {
    /// Deserialization version mismatch.
    VersionMismatch { expected: u8, found: u8 }

