// ── Inner State (requires mutable access) ────────────────────────

/// Mutable WASM components. Stored in a per-thread [`RefCell`] since each
/// thread exclusively owns its own instance — no locking needed.
///
/// All wasmi operations require `&mut Store`, so the per-thread
/// [`RefCell`] provides zero-overhead mutable access without contention.
struct WasmInner {
    // ── Hot-path fields (accessed every call) ───────────────────
    // Field order: small hot fields first (shared cache lines),
    // large cache array last (avoids pushing hot fields apart).
    /// TypedFunc is cheap to clone (handle index). Clone to release &self borrow.
    is_valid_fn: TypedFunc<(u32, u32, u32, u32), u32>,
    memory: Memory,
    /// Number of valid entries in `cached_parent_tokens`.
    cached_parent_len: usize,
    cached_parent_ptr: u32,
    cached_parent_written_len: u32,

    // ── Warm-path fields (optional exports, accessed per batch/relevance) ──
    /// Optional batch export: `(count, depths_ptr, tokens_ptr, parent_ptr, parent_len, results_ptr) -> u32`.
    batch_is_valid_fn: Option<BatchIsValidFn>,
    validate_string_fn: Option<TypedFunc<(u32, u32), u32>>,
    relevance_fn: Option<TypedFunc<(u32, u32, u32, u32), u32>>,
    /// Optional soft trust export: `(depth, token_idx, parent_ptr, parent_len) -> u32`.
    /// Returns Q16.16 fixed-point trust score for Plan 204 T4.
    soft_trust_fn: Option<TypedFunc<(u32, u32, u32, u32), u32>>,
    /// Optional batch soft trust export: `(count, depths_ptr, tokens_ptr, parent_ptr, parent_len, scores_ptr) -> u32`.
    soft_trust_batch_fn: Option<BatchIsValidFn>,

    // ── Cold field (large, accessed once per call for fuel) ─────
    store: Store<ValidatorState>,

    // ── Large cache array (last: 15 KB, doesn't evict hot fields) ──
    /// Fixed-size stack buffer for parent token caching.
    /// Avoids heap allocation — eliminates allocator overhead (~3.6× faster
    /// than `Vec::with_capacity` for the cache hit path).
    /// Placed last so its 15 KB footprint doesn't push the hot fields above
    /// out of the first few cache lines.
    cached_parent_tokens: [usize;

impl ConstraintPruner for WasmPruner {
    fn is_valid(&self, depth: usize, token_idx: usize, parent_tokens: &[usize]) -> bool {
        self.with_inner(|inner| inner.call_is_valid(depth, token_idx, parent_tokens))
    }

    fn batch_is_valid(
        &self,
        depth: usize,
        candidates: &[usize],
        parent_tokens: &[usize],
        results: &mut [bool],
    ) {
        self.with_inner(|inner| {
            inner.call_batch_is_valid(depth, candidates, parent_tokens, results)
        });
    }
}

