/// wasmi setup helper — mirrors the bench's setup_wasmi but for cognition
/// exports instead of validator exports.
type CogWasmiBundle = (
    wasmi::Store<()>,
    wasmi::Memory,
    wasmi::TypedFunc<(), ()>,
    wasmi::TypedFunc<(u32, f32, f32, u32), ()>,
    wasmi::TypedFunc<(u32, u32), ()>,
    wasmi::TypedFunc<u32, u32>,
);

fn setup_cog_wasmi(bytes: &[u8]) -> CogWasmiBundle {
    let mut config = wasmi::Config::default();

impl ComputeShader {
    fn load() -> Self {
        let wasm = wat::parse_str(COMPUTE_SHADER_WAT).expect("failed to parse WAT");
        let engine = Engine::default();
        let module = Module::new(&engine, &wasm[..]).expect("failed to compile module");
        let linker = Linker::new(&engine);
        let mut store = Store::new(&engine, ());
        let instance = linker
            .instantiate_and_start(&mut store, &module)
            .expect("failed to instantiate");

        let memory = instance
            .get_memory(&store, "memory")
            .expect("missing 'memory' export");

        // Verify function exports exist
        instance
            .get_typed_func::<(i32, i32), ()>(&store, "gemv")
            .expect("missing 'gemv' export");
        instance
            .get_typed_func::<(i32, i32), ()>(&store, "softmax")
            .expect("missing 'softmax' export");

        Self {
            memory,
            instance,
            store,
        }
    }

    fn write_f32(&mut self, offset: usize, data: &[f32]) {
        let bytes: Vec<u8> = data.iter().flat_map(|f| f.to_le_bytes()).collect();
        self.memory.data_mut(&mut self.store)[offset..offset + bytes.len()].copy_from_slice(&bytes);
    }

    fn read_f32(&self, offset: usize, count: usize) -> Vec<f32> {
        let data = &self.memory.data(&self.store)[offset..offset + count * 4];
        data.chunks_exact(4)
            .map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))
            .collect()
    }

    fn gemv(&mut self, m: usize, n: usize) {
        let gemv = self
            .instance
            .get_typed_func::<(i32, i32), ()>(&self.store, "gemv")
            .unwrap();
        gemv.call(&mut self.store, (m as i32, n as i32)).unwrap();
    }

    fn softmax(&mut self, rows: usize, cols: usize) {
        let softmax = self
            .instance
            .get_typed_func::<(i32, i32), ()>(&self.store, "softmax")
            .unwrap();
        softmax
            .call(&mut self.store, (rows as i32, cols as i32))
            .unwrap();
    }
}

