impl Error {
    /// Classify a wallet error, lifting program refusals out of
    /// [`riir_wallet::Error::Rejected`].
    ///
    /// Every `MarketplaceClient` method funnels through here so the
    /// classification lives in one place. Anything that is not a CPI rejection
    /// passes through untouched — this narrows the error, it never widens it.
    pub(crate) fn from_wallet(err: riir_wallet::Error) -> Self {
        let riir_wallet::Error::Rejected(TxRejection::CpiFailed {
            program_id,
            error_code,
        }) = err
        else {
            return Error::Wallet(err);
        };

        match program_error_from_code(error_code) {
            // Issue 036: keyed on `ProgramNotLinked`, not `InvalidInstruction`.
            //
            // This used to key on `InvalidInstruction`, which 23 programs also
            // return for ordinary bad arguments — so a caller who underpaid a
            // loan was told the node had no lending program and sent to
            // reconfigure a machine that was working correctly. The chain now
            // emits a distinct code from `dispatch`'s fallthrough, which is the
            // only place that genuinely means "nothing is linked for this
            // instruction".
            Some(ProgramError::ProgramNotLinked) => Error::ProgramUnavailable { program_id },
            Some(error) => Error::Program { program_id, error },
            // A code from a node running a newer chain build. Reported as the
            // program's own refusal with the closest honest stand-in rather
            // than silently mapped onto a plausible-looking wrong variant.
            None => Error::Program {
                program_id,
                error: ProgramError::InvalidInstruction,
            },
        }
    }
}

