// `CpiMessage` is what every encoder returns, and `LatCalMatrix` is how the
// chain spells an amount. A caller composing a message by hand — the escape
// hatch for an instruction this SDK has not wrapped yet — needs both.
pub use riir_chain::encoding::latcal::LatCalMatrix;
pub use riir_chain::programs::{
    CpiMessage, LatCalIx, ProgramError, hash_bytes_to_f32, identity_proof, program_ids,
};

/// An account identifier in the chain's CPI account store.
///
/// The same 16-byte width as a `player_id_hash`, and deliberately a plain
/// alias rather than a newtype: the caller is already holding these as
/// `[u8; 16]` from a registry, a database, or
/// [`riir_wallet::WalletClient::player_id_hash`], and a newtype would only add
/// conversions at every call site.
pub type AccountId = [u8; 16];

/// Prove knowledge of the identity `bytes` name.
///
/// Several programs store an identity — an escrow recipient, a bounty target,
/// an inheritance heir — folded into one cell, and a claimant proves they are
/// that party by presenting a matrix whose *determinant* equals the fold.
///
/// This is deliberately not [`amount`]. An amount matrix carries
/// `precision = 0.99`, so its determinant is `0.99 × value` — close enough to
/// look right and wrong enough to never match. The two are different shapes for
/// different jobs and the encoders that need a proof call this one.
#[inline]
pub fn identity_claim(bytes: &[u8]) -> LatCalMatrix {
    identity_proof(hash_bytes_to_f32(bytes))
}

/// Encode a positive amount as a [`LatCalMatrix`].
///
/// The chain represents a token amount as a 2×2 matrix whose `value` is the
/// magnitude and whose `sign` is the direction. Every encoder in this crate
/// takes a plain `f32` and calls this, so a caller never has to know that.
///
/// Amounts are always positive here: direction is the *instruction's* job
/// (`LendingRepay` subtracts, `RevenueDeposit` adds), not the amount's. An
/// encoder that accepted a negative amount would let a caller invert a
/// transfer by passing `-x`.
#[inline]
pub fn amount(value: f32) -> LatCalMatrix {
    LatCalMatrix::encode_amount(value.abs(), 1.0)
}

/// Encode a positive amount as wire micro-units (Plan 034 E3).
///
/// The i64 sibling of [`amount`] for the money fields, which are integer
/// micro-units on the wire (1 coin = 10⁶ micro). Same positivity contract:
/// direction is the instruction's job, so a negative input is taken by
/// magnitude — the chain's dispatch additionally refuses any negative that
/// reaches it by other means.
#[inline]
pub fn micro(value: f32) -> i64 {
    riir_chain::programs::to_micro_units(value.abs())
}

