        RpcOptions {
            rate_limit: Some((BENCH_RATE_LIMIT, Duration::from_secs(60))),
            ..Default::default()
        },
    );
    tokio::spawn(async move {
        let _ = axum::serve(
            listener,
            app.into_make_service_with_connect_info::<std::net::SocketAddr>(),
        )
        .await;
    });

    println!("networked RPC capacity re-measure — {TICK_MS}ms tick, rate limiter raised");
    println!("  endpoint: http://{addr}");
    println!(
        "  frames:   query={}B signed_response={}B tx={}B\n",
        riir_wallet::WalletQueryEnvelope::SIZE,
        riir_wallet::SignedResponse::SIZE,
        riir_wallet::WalletTxEnvelope::SIZE,
    );

    // ── Direct (the Bench 020 shape, re-measured) ────────────────────────
    let base = format!("http://{addr}");
    println!("── direct loopback (no relay) ──");
    report_latency(
        "read sequential",
        phase_sequential_read(&base, node_pubkey, pid, N_SEQ).await?,
    );
    let (done, el, err) = phase_concurrent_read(&base, node_pubkey, pid, N_CONC).await?;
    report_capacity("read concurrent (1 thread)", done, N_CONC, el, err);
    let (done, el, err) = phase_parallel_read(&base, node_pubkey, pid);
    report_capacity(
        &format!("read parallel ({N_THREADS} threads)"),
        done,
        N_THREADS * N_PER_THREAD,
        el,
        err,
    );
    report_latency(
        "write sequential (tx→committed)",
        phase_sequential_write(&base, node_pubkey, SEED, N_SEQ).await?,
    );

    // ── Relayed, at measured real-world RTTs ─────────────────────────────
    for rtt_ms in RTT_MS {
        let rtt = Duration::from_millis(rtt_ms);
        let port = spawn_delay_relay(addr, rtt).await?;
        let relayed = format!("http://127.0.0.1:{port}");
        let tag = match rtt_ms {
            0 => "relay overhead calibration".to_string(),
            _ => format!("emulated RTT {rtt_ms}ms"),
        };
        println!("\n── through delay relay — {tag} ──");
        report_latency(
            "read sequential",
            phase_sequential_read(&relayed, node_pubkey, pid, N_SEQ).await?,
        );
        let (done, el, err) = phase_concurrent_read(&relayed, node_pubkey, pid, N_CONC).await?;
        report_capacity("read concurrent (1 thread)", done, N_CONC, el, err);
        let (done, el, err) = phase_parallel_read(&relayed, node_pubkey, pid);
        report_capacity(
            &format!("read parallel ({N_THREADS} threads)"),
            done,
            N_THREADS * N_PER_THREAD,
            el,
            err,
        );
    }

    println!(
        "\nRead the CAPACITY rows for capacity-share arithmetic and the latency\n\
