impl ClusterState {
    /// Create a new cluster state for the given node ID.
    pub fn new(own_node_id: String) -> Self {
        Self {
            own_node_id,
            peers: papaya::HashMap::new(),
            wt_port_index: papaya::HashMap::new(),
        }
    }

    /// Get this node's ID.
    pub fn own_node_id(&self) -> &str {
        &self.own_node_id
    }

    /// Add or update a peer in the cluster.
    pub fn upsert_peer(&self, info: PeerInfo) {
        // Read the fields we need for the secondary index BEFORE moving `info`
        // into the primary map.
        let wt_port = info.wt_port;
        let resolved = info.node_config.unwrap_or(PeerNodeConfig::FAIL_CLOSED);
        let guard = self.peers.guard();
        self.peers.insert(info.node_id.clone(), info, &guard);
        // Keep the wt_port secondary index in sync (best-effort: a stale entry
        // for a re-used port is corrected on the next upsert for that port).
        let port_guard = self.wt_port_index.guard();
        self.wt_port_index.insert(wt_port, resolved, &port_guard);
    }

    /// Remove a peer from the cluster.
    ///
    /// Note: the `wt_port_index` entry is left in place — we don't know the
    /// peer's port here without an extra lookup, and a stale FAIL_CLOSED-ish
    /// entry is harmless (the next upsert for that port overwrites it). If we
    /// ever expose port-recycle semantics, sweep the index here.
    pub fn remove_peer(&self, node_id: &str) {
        let guard = self.peers.guard();
        self.peers.remove(node_id, &guard);
    }

    /// Get a peer's info by node ID.
    pub fn get_peer(&self, node_id: &str) -> Option<PeerInfo> {
        let guard = self.peers.guard();
        self.peers.get(node_id, &guard).cloned()
    }

    /// Get all known peer IDs.
    pub fn peer_ids(&self) -> Vec<String> {
        let pinned = self.peers.pin();
        pinned.keys().cloned().collect()
    }

    /// Get cluster size (including self).
    pub fn cluster_size(&self) -> usize {
        let pinned = self.peers.pin();
        pinned.len() + 1 // +1 for self
    }

    /// Mark a peer as verified.
    pub fn verify_peer(&self, node_id: &str) {
        let guard = self.peers.guard();
        if let Some(peer) = self.peers.get(node_id, &guard) {
            let mut updated = peer.clone();
            updated.verified = true;
            self.peers.insert(node_id.to_string(), updated, &guard);
        }
    }

    /// Plan 319 T6.4 — look up a peer's `PeerNodeConfig` by its WebTransport port.
    ///
    /// Returns [`PeerNodeConfig::FAIL_CLOSED`] if the peer is unknown or hasn't
    /// registered a config. This is the fail-closed default — a Peer that
    /// hasn't identified itself cannot bypass the Chain-Flow Gitflow tiers.
    ///
    /// Used by `handle_chunk_request` (in `asset_gate.rs`) to consult the
    /// visibility gate. O(1) via the `wt_port_index` secondary index — was
    /// previously an O(n) scan over all peers on every ChunkRequest.
    pub fn node_config_for_port(&self, wt_port: u16) -> PeerNodeConfig {
        let guard = self.wt_port_index.guard();
        self.wt_port_index
            .get(&wt_port, &guard)
            .copied()
            .unwrap_or(PeerNodeConfig::FAIL_CLOSED)
    }

    /// Plan 319 T6.4 — set or update a peer's `PeerNodeConfig` by its WT port.
    ///
    /// Used by tests + future JoinCluster payload extensions that carry role
    /// info. If the peer isn't yet registered, this is a no-op (caller should
    /// upsert_peer first). O(n) — rare mutation path, not hot.
    pub fn set_node_config_for_port(&self, wt_port: u16, config: PeerNodeConfig) {
        let guard = self.peers.guard();
        for (_, peer) in self.peers.iter(&guard) {
            if peer.wt_port == wt_port {
                let mut updated = peer.clone();
                updated.node_config = Some(config);
                self.peers.insert(peer.node_id.clone(), updated, &guard);
                // Keep the secondary index in sync.
                let port_guard = self.wt_port_index.guard();
                self.wt_port_index.insert(wt_port, config, &port_guard);
                return;
            }
        }
    }
}

