                quorum_power_mask: quorum::SUBMIT_GAME_STATE | quorum::SUBMIT_TRAINING_DATA,
                data_access_mask: data_access::GAME_STATE_READ
                    | data_access::GAME_STATE_WRITE
                    | data_access::TRAINING_DATA,
                feature_requirements: vec!["chain_gpu".to_string()],
