            NodeRole::Player => Self {
                stake_minimum: 0,
                quorum_power_mask: quorum::SUBMIT_GAME_STATE,
                data_access_mask: data_access::GAME_STATE_READ | data_access::GAME_STATE_WRITE,
                feature_requirements: vec![],
            },
        }
