    /// Check if this tier has a specific quorum permission.
    pub fn has_quorum_permission(&self, bit: u8) -> bool {
        self.quorum_power_mask & bit != 0
    }

    /// Check if this tier has a specific data access level.
    pub fn has_data_access(&self, bit: u8) -> bool {
        self.data_access_mask & bit != 0
    }
