// ── NodeHandle ─────────────────────────────────────────────────────────────

/// Handle to a single in-process node spawned by [`ClusterHarness`].
///
/// Carries shared references to the node's [`ClusterState`] (lock-free, safe
/// to read from the test thread) and [`SimRing`] (for tx submission + CQ
/// inspection). The actual WtServer + tick loop run as tokio tasks owned by
/// the parent [`ClusterHarness`] and are aborted on drop.
pub struct NodeHandle {
    port: u16,
    role: NodeHarnessRole,
    cluster: Arc<ClusterState>,
    ring: SimRing,
    /// Shared handle to this node's `ChainServer` (behind the same
    /// `Arc<Mutex<...>>` the tick loop uses). Exposed via [`Self::server`]
    /// so test helpers (register_player, submit_revoke_ix, etc.) can drive
    /// the server directly without going through WebTransport.
    ///
    /// `None` only if the harness was built without `chain_node` — that
    /// never happens today (the harness module is itself gated by
    /// `chain_node`), but the field is `Option` for future-proofing.
    server: Arc<Mutex<ChainServer>>,
    /// This node's WtServer cert hash, captured right after `bind_endpoint`
    /// runs (before the server moves into its `serve` task). Lets
    /// `join_peer` pin the peer's `WtClient` against the bootstrap's actual
    /// certificate instead of disabling TLS validation.
    cert_hash: Option<[u8;

impl NodeHandle {
    /// Port this node's WebTransport server listens on.
    pub fn port(&self) -> u16 {
        self.port
    }

    /// `"127.0.0.1:{port}"` — the address peers use to dial this node.
    pub fn addr(&self) -> String {
        format!("127.0.0.1:{}", self.port)
    }

    /// SHA-256 hash of this node's WebTransport TLS certificate. Feed to a
    /// joining peer's `WtClient::with_cert_hash` to pin the connection
    /// instead of disabling certificate validation.
    pub fn cert_hash(&self) -> Option<[u8; 32]> {
        self.cert_hash
    }

    /// Topology role (Bootstrap or Peer).
    pub fn role(&self) -> NodeHarnessRole {
        self.role
    }

    /// Shared handle to this node's cluster membership state.
    ///
    /// Lock-free (`papaya::HashMap` underneath); safe to read concurrently
    /// from the test thread while the WtServer's connection handlers write.
    pub fn cluster_state(&self) -> &Arc<ClusterState> {
        &self.cluster
    }

    /// Shared handle to this node's SimRing.
    ///
    /// Use to submit `RingEntry`s directly (bypassing the WT stream) and to
    /// `drain_cq()` for verifying `RingResult::Committed` outcomes — same
    /// inspection pattern as `e2e_two_process.rs`.
    pub fn ring(&self) -> &SimRing {
        &self.ring
    }

    /// Shared handle to this node's `ChainServer` (behind `Mutex`).
    ///
    /// Use this to register players, submit revoke ixs, and inspect
    /// `PenaltyTracker` state without going through WebTransport. The
    /// harness's tick loop also drains the `SimRing` through this same
    /// server, so mutations made via this handle are observed by the
    /// cluster's normal consensus path.
    ///
    /// # Locking contract
    ///
    /// The lock is shared with the harness's tick loop (which holds it
    /// briefly each tick to drain the ring). Long-running operations that
    /// hold the lock will starve the tick loop. Drop the guard as soon as
    /// the mutation is complete.
    ///
    /// # Re-entrancy hazard
    ///
    /// `process_*_revoke` calls invoke `PenaltySink::emit_slash_penalty`,
    /// which (in `PlayerMappedPenaltySink`) re-locks this server. **Drop
    /// the lock guard before invoking any verifier/sink that may re-enter
    /// the server** — `Mutex` is not reentrant.
    pub fn server(&self) -> &Arc<Mutex<ChainServer>> {
        &self.server
    }
}

impl ClusterHarnessBuilder {
    /// Set the bootstrap node's WebTransport port. Required.
    pub fn bootstrap_port(mut self, port: u16) -> Self {
        self.bootstrap_port = Some(port);
        self
    }

    /// Add a peer node that will dial the bootstrap on `join_all_peers`.
    pub fn peer_port(mut self, port: u16) -> Self {
        self.peer_ports.push(port);
        self
    }

    /// Skip the per-node WebTransport readiness probe in [`Self::build`].
    ///
    /// For in-process dispatch tests that only touch `NodeHandle::server()`
    /// (Plan 005's revoke E2E), the WtServer readiness probe is pure
    /// overhead and a flakiness source — it does a full QUIC+TLS connect
    /// that can take seconds and race the accept path. Tests that actually
    /// dial peers over WebTransport must NOT set this (they need the probe
    /// to guarantee the peer is accepting before they connect).
    pub fn skip_wt_readiness(mut self) -> Self {
        self.skip_wt_readiness = true;
        self
    }

    /// Override the default tick interval (default 50 ms).
    pub fn tick_interval(mut self, interval: Duration) -> Self {
        self.tick_interval = interval;
        self
    }

    /// Override the default `[0; 32]` MPC secret share.
    pub fn mpc_secret_share(mut self, share: [u8; 32]) -> Self {
        self.mpc_secret_share = share;
        self
    }

    /// Spawn all configured nodes (bootstrap first, then peers' WtServers).
    ///
    /// Does NOT join peers to the bootstrap yet — call
    /// [`ClusterHarness::join_all_peers`] after this returns. Splitting
    /// "spawn servers" from "join cluster" lets tests assert pre-join state
    /// (e.g. `cluster_size() == 1`) before triggering joins.
    pub async fn build(self) -> anyhow::Result<ClusterHarness> {
        let bootstrap_port = self
            .bootstrap_port
            .ok_or_else(|| anyhow::anyhow!("ClusterHarnessBuilder: bootstrap_port is required"))?;

        // Sanity: all ports distinct.
        let mut all_ports = vec![bootstrap_port];
        all_ports.extend(&self.peer_ports);
        all_ports.sort_unstable();
        for w in all_ports.windows(2) {
            if w[0] == w[1] {
                anyhow::bail!("ClusterHarnessBuilder: duplicate port {}", w[0]);
            }
        }

        let mut nodes = Vec::with_capacity(all_ports.len());
        let mut tasks = Vec::new();
        let mut endpoints = Vec::with_capacity(all_ports.len());

        // ── Bootstrap node ─────────────────────────────────────────────
        let (boot, boot_endpoint) = spawn_node(
            bootstrap_port,
            NodeHarnessRole::Bootstrap,
            self.mpc_secret_share,
            self.tick_interval,
            &mut tasks,
        )
        .await?;
        // Bootstrap has no ChainServer players registered by default — tests
        // that need tx submission register via `harness.register_player(...)`.
        nodes.push(boot);
        endpoints.push(boot_endpoint);

        // Wait for the bootstrap's WtServer to bind before spawning peers.
        // Skipped for in-process-only tests (see `skip_wt_readiness`).
        if !self.skip_wt_readiness {
            let boot_addr = format!("127.0.0.1:{bootstrap_port}");
            wait_for_server(&boot_addr, SERVER_READY_ATTEMPTS)
                .await
                .map_err(|e| anyhow::anyhow!("bootstrap WtServer not ready: {e}"))?;
        }

        // ── Peer nodes (servers only — not joined yet) ────────────────
        for &port in &self.peer_ports {
            let (peer, peer_endpoint) = spawn_node(
                port,
                NodeHarnessRole::Peer,
                self.mpc_secret_share,
                self.tick_interval,
                &mut tasks,
            )
            .await?;
            if !self.skip_wt_readiness {
                wait_for_server(&format!("127.0.0.1:{port}"), SERVER_READY_ATTEMPTS)
                    .await
                    .map_err(|e| anyhow::anyhow!("peer WtServer on {port} not ready: {e}"))?;
            }
            nodes.push(peer);
            endpoints.push(peer_endpoint);
        }

        let bootstrap_port_actual = bootstrap_port;
        Ok(ClusterHarness {
            nodes,
            tasks,
            endpoints,
            bootstrap_port: bootstrap_port_actual,
        })
    }
}

