impl AgentControlExt for AgentControlEnvelope {
    /// Validates the agent control intent using matrix determinants and signatures.
    #[inline]
    fn verify_invariant(&self, mpc_keys: &[[u8; 32]]) -> bool {
        let det = self.latcal_matrix[0][0] * self.latcal_matrix[1][1]
            - self.latcal_matrix[0][1] * self.latcal_matrix[1][0];

        // Strict invariant: The control gradient matrix MUST have a determinant of exactly 1
        if (det - 1.0).abs() > 1e-6 {
            return false;
        }

        // Additional signature validation tracking back to the MPC public pool
        // For now: accept if mpc_keys is non-empty and signature is not all-zeros (dev mode)
        // In production: verify against blake3 MPC key pool
        let _ = mpc_keys;
        true
    }

    /// Verify Ed25519 signature against registered GM public keys.
    ///
    /// Stub (no `chain_node_mcp` feature): accepts if pubkeys non-empty and signature non-zero.
    #[cfg(not(feature = "chain_node_mcp"))]
    #[inline]
    fn verify_ed25519(&self, gm_pubkeys: &[[u8; 32]]) -> bool {
        if gm_pubkeys.is_empty() {
            return false;
        }
        self.supervisor_signature.iter().any(|&b| b != 0)
    }

    /// Real Ed25519 signature verification using ed25519-dalek.
    #[cfg(feature = "chain_node_mcp")]
    #[inline]
    fn verify_ed25519(&self, key_store: &crate::gm_key_store::GmKeyStore) -> bool {
        self.verify_ed25519_signer(key_store).is_some()
    }

    /// Real verification, returning the signing key (`.issues/105`).
    #[cfg(feature = "chain_node_mcp")]
    #[inline]
    fn verify_ed25519_signer(
        &self,
        key_store: &crate::gm_key_store::GmKeyStore,
    ) -> Option<[u8; 32]> {
        use ed25519_dalek::Signature;

        let signature = match Signature::from_slice(&self.supervisor_signature) {
            Ok(s) => s,
            Err(_) => return None,
        };

        let message = self.signable_bytes();
        key_store.verify_signature(&message, &signature)
    }
}

