impl NeuroTx {
    /// Serialize to bytes — fixed-size, stack-allocated.
    pub fn to_bytes(&self) -> [u8; NEURO_TX_SIZE] {
        let mut buf = [0u8; NEURO_TX_SIZE];
        buf[0..16].copy_from_slice(&self.player_id_hash);
        buf[16] = self.action;
        buf[17..49].copy_from_slice(&self.delta);
        buf[49..57].copy_from_slice(&self.nonce.to_le_bytes());
        buf[57..89].copy_from_slice(&self.tx_commitment);
        buf[89..121].copy_from_slice(&self.alpha_key_hash);
        buf
    }

    /// Deserialize from bytes.
    pub fn from_bytes(data: &[u8]) -> Option<Self> {
        if data.len() != NEURO_TX_SIZE {
            return None;
        }
        let mut player_id_hash = [0u8; 16];
        player_id_hash.copy_from_slice(&data[0..16]);
        let action = data[16];
        let mut delta = [0u8; 32];
        delta.copy_from_slice(&data[17..49]);
        // Statically-known 8-byte slice — direct array literal avoids the
        // Result round-trip through try_into().ok()? (length is already checked).
        let nonce = u64::from_le_bytes([
            data[49], data[50], data[51], data[52], data[53], data[54], data[55], data[56],
        ]);
        let mut tx_commitment = [0u8; 32];
        tx_commitment.copy_from_slice(&data[57..89]);
        let mut alpha_key_hash = [0u8; 32];
        alpha_key_hash.copy_from_slice(&data[89..121]);
        Some(Self {
            player_id_hash,
            action,
            delta,
            nonce,
            tx_commitment,
            alpha_key_hash,
        })
    }

    /// Create a dev NeuroTx for testing.
    pub fn dev(player_id_hash: [u8; 16], action: u8, nonce: u64) -> Self {
        Self {
            player_id_hash,
            action,
            delta: [0u8; 32],
            nonce,
            tx_commitment: [0u8; 32],
            alpha_key_hash: [0u8; 32],
        }
    }
}

