impl JoinClusterPayload {
    /// Serialize to bytes.
    pub fn to_bytes(&self) -> Vec<u8> {
        let mut buf = Vec::with_capacity(self.node_id.len() + 2 + 32 + 2);
        buf.extend_from_slice(&(self.node_id.len() as u16).to_le_bytes());
        buf.extend_from_slice(self.node_id.as_bytes());
        buf.extend_from_slice(&self.wt_port.to_le_bytes());
        buf.extend_from_slice(&self.mpc_pubkey_share);
        buf
    }

    /// Deserialize from bytes.
    #[inline]
    pub fn from_bytes(data: &[u8]) -> Option<Self> {
        if data.len() < 2 {
            return None;
        }
        let id_len = u16::from_le_bytes([data[0], data[1]]) as usize;
        if data.len() < 2 + id_len + 2 + 32 {
            return None;
        }
        let node_id = String::from_utf8(data[2..2 + id_len].to_vec()).ok()?;
        // Direct array literals avoid the Result round-trip through try_into().ok()?.
        let base = 2 + id_len;
        let wt_port = u16::from_le_bytes([data[base], data[base + 1]]);
        let mut mpc_pubkey_share = [0u8; 32];
        mpc_pubkey_share.copy_from_slice(&data[base + 2..base + 2 + 32]);
        Some(Self {
            node_id,
            wt_port,
            mpc_pubkey_share,
        })
    }
}

impl ChunkRequestPayload {
    /// Serialize to a fixed-width byte array — zero heap allocation.
    pub fn to_bytes(&self) -> [u8; CHUNK_REQUEST_SIZE] {
