        buf[0..32].copy_from_slice(&self.asset_blob_id);
        buf[32..36].copy_from_slice(&self.chunk_index.to_le_bytes());
        buf[36..38].copy_from_slice(&self.requester_wt_port.to_le_bytes());
        buf[38] = self.requester_role;
        buf[39] = self.requester_beta_tester as u8;
        buf[40..48].copy_from_slice(&self.nonce.to_le_bytes());
        buf
    }

    /// Deserialize from bytes.
    #[inline]
    pub fn from_bytes(data: &[u8]) -> Option<Self> {
        if data.len() != CHUNK_REQUEST_SIZE {
            return None;
        }
        let mut asset_blob_id = [0u8; 32];
        asset_blob_id.copy_from_slice(&data[0..32]);
        // Direct array literals — lengths are statically known.
        let chunk_index = u32::from_le_bytes([data[32], data[33], data[34], data[35]]);
        let requester_wt_port = u16::from_le_bytes([data[36], data[37]]);
        let requester_role = data[38];
        let requester_beta_tester = data[39] != 0;
        let nonce = u64::from_le_bytes([
            data[40], data[41], data[42], data[43], data[44], data[45], data[46], data[47],
        ]);
        Some(Self {
            asset_blob_id,
            chunk_index,
            requester_wt_port,
            requester_role,
            requester_beta_tester,
            nonce,
        })
    }
}

impl ChunkResponsePayload {
    /// Verdict byte values.
    pub const DENIED: u8 = 0;
    pub const CHUNK: u8 = 1;

    /// Serialize to bytes.
    pub fn to_bytes(&self) -> Vec<u8> {
        match self {
            Self::Denied => vec![Self::DENIED],
            Self::Chunk(bytes) => {
                let mut buf = Vec::with_capacity(1 + 4 + bytes.len());
                buf.push(Self::CHUNK);
                buf.extend_from_slice(&(bytes.len() as u32).to_le_bytes());
                buf.extend_from_slice(bytes);
                buf
            }
        }
    }

    /// Deserialize from bytes.
    #[inline]
    pub fn from_bytes(data: &[u8]) -> Option<Self> {
        if data.is_empty() {
            return None;
        }
        match data[0] {
            Self::DENIED => Some(Self::Denied),
            Self::CHUNK => {
                if data.len() < 5 {
                    return None;
                }
                let len = u32::from_le_bytes([data[1], data[2], data[3], data[4]]) as usize;
                if data.len() != 5 + len {
                    return None;
                }
                Some(Self::Chunk(data[5..5 + len].to_vec()))
            }
            _ => None,
        }
    }
}

