impl SecurityVoteWire {
    /// Serialize to a fixed-width byte array — zero heap allocation.
    pub fn to_bytes(&self) -> [u8; SECURITY_VOTE_SIZE] {
        let mut buf = [0u8; SECURITY_VOTE_SIZE];
        let mut off = 0usize;
        buf[off..off + 32].copy_from_slice(&self.proposal_key);
        off += 32;
        buf[off..off + 32].copy_from_slice(&self.node_hash);
        off += 32;
        for f in &self.fingerprint {
            buf[off..off + 4].copy_from_slice(&f.to_le_bytes());
            off += 4;
        }
        buf[off] = self.voter_index;
        off += 1;
        buf[off] = self.vote;
        off += 1;
        buf[off] = self.voter_tier;
        off += 1;
        buf[off] = self.rejection_type;
        off += 1;
        buf[off] = self.proposed_tier;
        off += 1;
        // 3 bytes pad (already zero).
        off += 3;
        buf[off..off + 8].copy_from_slice(&self.voter_backoff.to_le_bytes());
        off += 8;
        buf[off..off + 8].copy_from_slice(&self.evidence_block.to_le_bytes());
        debug_assert_eq!(off + 8, SECURITY_VOTE_SIZE);
        buf
    }

    /// Deserialize from bytes. Returns `None` on wrong length.
    ///
    /// Discriminants (`voter_tier`, `proposed_tier`, `rejection_type`) are
    /// validated downstream by the daemon (which has the `riir-wasm` dep).
    #[inline]
    pub fn from_bytes(data: &[u8]) -> Option<Self> {
        if data.len() != SECURITY_VOTE_SIZE {
            return None;
        }
        let mut off = 0usize;
        let mut proposal_key = [0u8; 32];
        proposal_key.copy_from_slice(&data[off..off + 32]);
        off += 32;
        let mut node_hash = [0u8; 32];
        node_hash.copy_from_slice(&data[off..off + 32]);
        off += 32;
        let mut fingerprint = [0f32; 8];
        for f in &mut fingerprint {
            *f = f32::from_le_bytes([data[off], data[off + 1], data[off + 2], data[off + 3]]);
            off += 4;
        }
        let voter_index = data[off];
        off += 1;
        let vote = data[off];
        off += 1;
        let voter_tier = data[off];
        off += 1;
        let rejection_type = data[off];
        off += 1;
        let proposed_tier = data[off];
        off += 1;
        // Skip 3 bytes pad.
        off += 3;
        let voter_backoff = u64::from_le_bytes([
            data[off],
            data[off + 1],
            data[off + 2],
            data[off + 3],
            data[off + 4],
            data[off + 5],
            data[off + 6],
            data[off + 7],
        ]);
        off += 8;
        let evidence_block = u64::from_le_bytes([
            data[off],
            data[off + 1],
            data[off + 2],
            data[off + 3],
            data[off + 4],
            data[off + 5],
            data[off + 6],
            data[off + 7],
        ]);
        Some(Self {
            proposal_key,
            node_hash,
            fingerprint,
            voter_index,
            vote,
            voter_tier,
            rejection_type,
            proposed_tier,
            voter_backoff,
            evidence_block,
        })
    }
}

impl HeartbeatPayload {
    /// Serialize to a fixed-width byte array — zero heap allocation.
    pub fn to_bytes(&self) -> [u8; HEARTBEAT_PAYLOAD_SIZE] {
        let mut buf = [0u8; HEARTBEAT_PAYLOAD_SIZE];
        buf[0] = self.authority_index;
        buf[1..5].copy_from_slice(&self.queue_depth.to_le_bytes());
        buf[5..9].copy_from_slice(&self.processing_rate_deriv.to_le_bytes());
        buf[9..17].copy_from_slice(&self.sender_ts.to_le_bytes());
        buf
    }

    /// Deserialize from bytes. Returns `None` on wrong length.
    ///
    /// Returns `Some(legacy_ping)` with all-zero fields if `data` is empty
    /// (0 bytes) — callers can distinguish a legacy ping via
    /// [`HeartbeatPayload::is_legacy_ping`]. A non-empty payload MUST be
    /// exactly [`HEARTBEAT_PAYLOAD_SIZE`] bytes; anything else is rejected.
    #[inline]
    #[must_use]
    pub fn from_bytes(data: &[u8]) -> Option<Self> {
        if data.is_empty() {
            // Legacy liveness ping (pre-T2.8). Signal the caller to skip the
            // guard feedback path.
            return Some(Self::legacy_ping());
        }
        if data.len() != HEARTBEAT_PAYLOAD_SIZE {
            return None;
        }
        let authority_index = data[0];
        let queue_depth = f32::from_le_bytes([data[1], data[2], data[3], data[4]]);
        let processing_rate_deriv = f32::from_le_bytes([data[5], data[6], data[7], data[8]]);
        let sender_ts = u64::from_le_bytes([
            data[9], data[10], data[11], data[12], data[13], data[14], data[15], data[16],
        ]);
        Some(Self {
            authority_index,
            queue_depth,
            processing_rate_deriv,
            sender_ts,
        })
    }

    /// Construct the legacy-ping sentinel (all-zero fields).
    ///
    /// `processing_rate_deriv == 0.0` is the same sentinel
    /// `riir_wasm::guard::HeartbeatFeedback` uses for "no heartbeat yet" — so
    /// feeding a legacy ping into the guard is a no-op (the gradient falls back
    /// to the proxy formula). This is the correct behavior: a peer that hasn't
    /// upgraded to T2.8 contributes no DGD-LB feedback, and the receiver's
    /// routing stays on the proxy path for that authority.
    #[inline]
    #[must_use]
    pub const fn legacy_ping() -> Self {
        Self {
            authority_index: 0,
            queue_depth: 0.0,
            processing_rate_deriv: 0.0,
            sender_ts: 0,
        }
    }

    /// True iff this is the legacy-ping sentinel (no DGD-LB telemetry).
    #[inline]
    #[must_use]
    pub const fn is_legacy_ping(&self) -> bool {
        self.processing_rate_deriv == 0.0 && self.queue_depth == 0.0 && self.sender_ts == 0
    }
}

impl MpcState {
    /// Create a new MPC state for a 2-of-3 threshold.
    pub fn new_2of3(secret_share: [u8; 32]) -> Self {
        Self {
            secret_share,
            partial_sigs: Vec::with_capacity(3),
            threshold: 2,
            total_peers: 3,
        }
    }

    /// Add a partial signature from a peer.
    pub fn add_partial_sig(&mut self, sig: MpcPartialSig) {
        self.partial_sigs.push(sig);
    }

    /// Check if we have enough partial signatures to form a full signature.
    pub fn has_threshold(&self) -> bool {
        self.partial_sigs.len() >= self.threshold
    }

    /// Reset partial signatures for a new round.
    pub fn reset_round(&mut self) {
        self.partial_sigs.clear();
    }
}

