/// Deterministic ordering: Committed by tx_commitment, Rejected by player_id_hash,
/// Committed < Rejected.
///
/// Uses `sort_unstable_by` — faster than stable sort, and we don't need stability
/// since results are consumed once and discarded.
#[inline]
fn sort_results(results: &mut [RingResult]) {
    results.sort_unstable_by(|a, b| match (a, b) {
        (RingResult::Committed { receipt: r1, .. }, RingResult::Committed { receipt: r2, .. }) => {
            r1.tx_commitment.cmp(&r2.tx_commitment)
        }
        (
            RingResult::Rejected {
                player_id_hash: p1, ..
            },
            RingResult::Rejected {
                player_id_hash: p2, ..
            },
        ) => p1.cmp(p2),
        (RingResult::Committed { .. }, RingResult::Rejected { .. }) => std::cmp::Ordering::Less,
        (RingResult::Rejected { .. }, RingResult::Committed { .. }) => std::cmp::Ordering::Greater,
    }

