/// The node's Ed25519 identity — what signs every RPC response.
///
/// This is a **chain** identity, not a TLS identity. Pinning it in the wallet
/// authenticates the node itself, which is strictly stronger than pinning a
/// certificate: it survives cert rotation, works across a fleet sharing a key,
/// and is unaffected by whoever happens to hold a CA-signed cert for the
/// hostname.
pub struct NodeIdentity {
    signing_key: SigningKey,
    pubkey: [u8;

impl NodeIdentity {
    /// Load from an SSH Ed25519 private key.
    ///
    /// Reuses [`riir_chain::ssh_key::load_ed25519_signing_key`], the same loader
    /// the GM key path uses.
    pub fn from_ssh_path(path: &std::path::Path) -> anyhow::Result<Self> {
        let signing_key = riir_chain::ssh_key::load_ed25519_signing_key(path)
            .map_err(|e| anyhow::anyhow!("loading node key {}: {e}", path.display()))?;
        Ok(Self::from_signing_key(signing_key))
    }

    /// Derive a **deterministic dev key** from a node id.
    ///
    /// For local development only: the key is a pure function of `node_id`, so
    /// anyone who knows the node id can forge this node's responses. Callers must
    /// log that loudly — see `NodeIdentity::warn_if_dev`.
    pub fn dev_from_node_id(node_id: &str) -> Self {
        let mut hasher = blake3::Hasher::new();
        hasher.update(b"riir-chain-dev-node-key-v1");
        hasher.update(node_id.as_bytes());
        let seed = *hasher.finalize().as_bytes();
        Self::from_signing_key(SigningKey::from_bytes(&seed))
    }

    fn from_signing_key(signing_key: SigningKey) -> Self {
        let pubkey = signing_key.verifying_key().to_bytes();
        Self {
            signing_key,
            pubkey,
        }
    }

    /// The public key a wallet must pin.
    #[inline]
    pub fn pubkey(&self) -> [u8; 32] {
        self.pubkey
    }

    /// Lowercase hex of [`Self::pubkey`], for logs and `/node-info`.
    pub fn pubkey_hex(&self) -> String {
        hex_lower(&self.pubkey)
    }
}

