impl SignalingRelay {
    /// Create a new empty relay.
    pub fn new() -> Self {
        Self {
            peers: papaya::HashMap::new(),
        }
    }

    /// Register a peer's signaling channel.
    pub fn register(&self, peer_id: String, tx: mpsc::Sender<SignalFrame>) {
        let guard = self.peers.guard();
        self.peers.insert(peer_id, tx, &guard);
    }

    /// Unregister a peer (called on disconnect).
    pub fn unregister(&self, peer_id: &str) {
        let guard = self.peers.guard();
        self.peers.remove(peer_id, &guard);
    }

    /// Relay a signaling frame to the target peer.
    ///
    /// Looks up the peer's channel, clones the sender, drops the papaya
    /// guard (which is !Send), then awaits the send.
    pub async fn relay(&self, target_peer_id: &str, frame: SignalFrame) -> anyhow::Result<()> {
        let tx = {
            let guard = self.peers.guard();
            if let Some(tx) = self.peers.get(target_peer_id, &guard) {
                tx.clone()
            } else {
                tracing::warn!(target = target_peer_id, "signaling target not connected");
                return Ok(());
            }
        };
        // guard is dropped here; tx is owned and Send
        tx.send(frame)
            .await
            .map_err(|_| anyhow::anyhow!("peer channel closed"))
    }

    /// Get list of connected browser peer IDs.
    pub fn peer_ids(&self) -> Vec<String> {
        let pinned = self.peers.pin();
        pinned.keys().cloned().collect()
    }
}

