impl WtClient {
    /// Create a new P2P client.
    pub fn new(
        bootstrap_addr: String,
        own_node_id: String,
        own_wt_port: u16,
        mpc_pubkey_share: [u8; 32],
        cluster: Arc<ClusterState>,
    ) -> Self {
        Self {
            bootstrap_addr,
            own_node_id,
            own_wt_port,
            mpc_pubkey_share,
            cluster,
            server_cert_hash: None,
        }
    }

    /// Pin the bootstrap's TLS certificate by SHA-256 hash instead of
    /// disabling certificate validation. Get the hash from the bootstrap's
    /// [`crate::transport::WtServer::cert_hash`] (after it binds) and
    /// distribute it out-of-band (config file, CLI flag, invite link).
    pub fn with_cert_hash(&mut self, hash: [u8; 32]) -> &mut Self {
        self.server_cert_hash = Some(hash);
        self
    }

    /// Connect to bootstrap and perform JoinCluster handshake.
    ///
    /// Returns the JoinResponse from the bootstrap if accepted.
    pub async fn join_cluster(&self) -> anyhow::Result<JoinResponse> {
        tracing::info!(
            addr = %self.bootstrap_addr,
            "connecting to bootstrap via WebTransport"
        );

        let config = if let Some(hash) = self.server_cert_hash {
            ClientConfig::builder()
                .with_bind_default()
                .with_server_certificate_hashes([wtransport::tls::Sha256Digest::new(hash)])
                .build()
        } else {
            tracing::warn!(
                addr = %self.bootstrap_addr,
                "no bootstrap cert hash configured — TLS certificate validation is \
                 DISABLED for this connection (insecure; vulnerable to MITM). Use \
                 WtClient::with_cert_hash to pin the bootstrap's certificate instead."
            );
            ClientConfig::builder()
                .with_bind_default()
                .with_no_cert_validation()
                .build()
        };

        let endpoint = Endpoint::client(config)?;

        // Parse address — wtransport needs host:port. Use rsplit_once to
        // avoid the Vec<&str> allocation that `split(':').collect()` does.
        let (host, port) = match self.bootstrap_addr.rsplit_once(':') {
            Some((h, p)) => (h, p.parse::<u16>().unwrap_or(9001)),
            None => (self.bootstrap_addr.as_str(), 9001),
        };

        let connection = endpoint.connect(&format!("https://{host}:{port}")).await?;

        tracing::info!("connected to bootstrap, opening bidi stream for JoinCluster");

        // Open bidi stream for JoinCluster handshake
        let (mut send, mut recv) = connection.open_bi().await?.await?;

        // Send JoinCluster frame
        let join_payload = JoinClusterPayload {
            node_id: self.own_node_id.clone(),
            wt_port: self.own_wt_port,
            mpc_pubkey_share: self.mpc_pubkey_share,
        };
        let frame = p2p::encode_frame(P2pMessage::JoinCluster, &join_payload.to_bytes());
        send.write_all(&frame).await?;
        send.finish().await?;

        tracing::info!("JoinCluster sent, waiting for response");

        // Read response: [1 byte accepted] [4 bytes cluster_size] [2 bytes node_id_len] [node_id bytes]
        let mut resp_buf = [0u8; 512];
        let n = match recv.read(&mut resp_buf).await? {
            Some(0) | None => anyhow::bail!("empty JoinCluster response"),
            Some(n) => n,
        };

        let accepted = resp_buf[0] != 0;
        if !accepted {
            anyhow::bail!("JoinCluster rejected by bootstrap");
        }

        let cluster_size =
            u32::from_le_bytes([resp_buf[1], resp_buf[2], resp_buf[3], resp_buf[4]]) as usize;

        let node_id_len = u16::from_le_bytes([resp_buf[5], resp_buf[6]]) as usize;
        let node_id = if n >= 7 + node_id_len {
            String::from_utf8(resp_buf[7..7 + node_id_len].to_vec())
                .unwrap_or_else(|_| self.own_node_id.clone())
        } else {
            self.own_node_id.clone()
        };

        tracing::info!(
            cluster_size,
            assigned_id = %node_id,
            "JoinCluster accepted"
        );

        // Update local cluster state with bootstrap peer
        self.cluster.upsert_peer(crate::cluster::PeerInfo {
            node_id: format!("bootstrap-{port}"),
            wt_port: port,
            mpc_pubkey_share: [0u8; 32], // Bootstrap's share not exchanged yet
            verified: true,
            node_config: None,
        });

        Ok(JoinResponse {
            accepted,
            cluster_size,
            assigned_node_id: node_id,
        })
    }
}

