impl Harness {
    /// The full sign-in: challenge → sign → verify → session frame.
    ///
    /// Returns the frame *and* the nonce, because the caller needs the nonce to
    /// recompute the binding — which is the check that a session cannot be
    /// lifted from another login.
    async fn sign_in(&self, wallet: &WalletIdentity) -> (SiwrSessionFrame, String) {
        let (nonce, message) = self.challenge(&wallet.public_key().to_bytes()).await;
        let signature = wallet.try_sign(message.as_bytes()).expect("sign");

        let resp = self.verify(&nonce, &message, &signature).await;
        assert_eq!(resp.status(), 200, "a good sign-in must be accepted");
        let bytes = resp.bytes().await.expect("body");

        let frame = SignedResponse::from_bytes(&bytes).expect("SignedResponse");
        // Pinned key + binding, exactly as a relying party's client would.
        let session = frame
            .verify_session(&self.node_pubkey, &siwr_session_binding(&nonce))
            .expect("session frame must verify against the pinned key and this nonce");
        (session, nonce)
    }

    async fn challenge(&self, pubkey: &[u8; 32]) -> (String, String) {
        let hex: String = pubkey.iter().map(|b| format!("{b:02x}")).collect();
        let body: serde_json::Value = self
            .http
            .get(format!("{}/siwr/challenge?pubkey={hex}", self.base_url))
            .send()
            .await
            .expect("challenge request")
            .json()
            .await
            .expect("challenge json");
        (
            body["inputId"].as_str().expect("inputId").to_owned(),
            body["message"].as_str().expect("message").to_owned(),
        )
    }

    async fn verify(&self, nonce: &str, message: &str, signature: &[u8; 64]) -> reqwest::Response {
        let sig_hex: String = signature.iter().map(|b| format!("{b:02x}")).collect();
        self.http
            .post(format!("{}/siwr/verify", self.base_url))
            .json(&serde_json::json!({
                "inputId": nonce,
                "signedMessage": message,
                "signature": sig_hex,
            }))
            .send()
            .await
            .expect("verify request")
    }

    /// `POST /wallet/query`, optionally bearing a session token.
    async fn query(&self, player_id_hash: [u8; 16], token: Option<&[u8; 32]>) -> reqwest::Response {
        let envelope = WalletQueryEnvelope::with_challenge(WALLET_QUERY_BALANCE, player_id_hash);
        let mut req = self
            .http
            .post(format!("{}/wallet/query", self.base_url))
            .body(bytemuck::bytes_of(&envelope).to_vec());
        if let Some(token) = token {
            let hex: String = token.iter().map(|b| format!("{b:02x}")).collect();
            req = req.header("Authorization", format!("Bearer {hex}"));
        }
        req.send().await.expect("query request")
    }
}

