impl UnbondingQueue {
    pub fn new() -> Self {
        Self::default()
    }

    /// Add an entry to the unbonding queue.
    pub fn add_unbonding(&mut self, validator_pubkey: [u8; 32], amount: u64, current_tick: u64) {
        self.entries.push(DelegationEntry {
            validator_pubkey,
            amount,
            status: DelegationStatus::Unbonding,
            unbond_start_tick: current_tick,
        });
    }

    /// Advance unbonding entries — mark as Claimable if period elapsed.
    pub fn tick(&mut self, current_tick: u64) -> usize {
        let mut claimed = 0;
        for entry in &mut self.entries {
            if entry.status == DelegationStatus::Unbonding {
                let elapsed = current_tick.saturating_sub(entry.unbond_start_tick);
                if elapsed >= UNBONDING_PERIOD_TICKS {
                    entry.status = DelegationStatus::Claimable;
                    claimed += 1;
                }
            }
        }
        claimed
    }

    /// Remove and return all claimable entries for a given validator.
    /// Returns (claimed_amount, number_of_entries).
    pub fn claim(&mut self, validator_pubkey: &[u8; 32]) -> (u64, usize) {
        let mut total = 0u64;
        let mut count = 0;
        self.entries.retain(|e| {
            if e.status == DelegationStatus::Claimable && &e.validator_pubkey == validator_pubkey {
                total = total.saturating_add(e.amount);
                count += 1;
                false // remove
            } else {
                true // keep
            }
        });
        (total, count)
    }

    /// Number of entries in the unbonding queue.
    #[inline]
    pub fn len(&self) -> usize {
        self.entries.len()
    }

    /// Whether the queue is empty.
    #[inline]
    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }
}

