impl From<FrostError> for SignError {
    /// Narrows to the payload-free seam. `BelowThreshold` becomes
    /// [`SignError::Unavailable`] rather than `Backend` — it is retryable with
    /// more signers, which is exactly the distinction `Unavailable` exists to
    /// carry.
    fn from(e: FrostError) -> Self {
        match e {
            FrostError::BelowThreshold { .. } => SignError::Unavailable,
            _ => SignError::Backend,
        }
    }
