impl FrostGroup {
    /// Generate a `threshold`-of-`total` group with a trusted dealer.
    ///
    /// # The dealer is the weakness
    ///
    /// This process holds every share at once. That is acceptable for a first
    /// deployment and unacceptable as a steady state; see the module docs.
    ///
    /// # Errors
    ///
    /// [`FrostError::BadConfiguration`] for a degenerate configuration —
    /// `threshold` of 0 or 1, or `total` below `threshold`.
    /// [`FrostError::Protocol`] if the underlying implementation rejects it.
    ///
    /// A threshold of 1 is refused rather than allowed as a "convenience": a
    /// 1-of-n group is a single-signer account with extra latency and a false
    /// name, and the one thing worse than no cold tier is an account everybody
    /// believes is a cold tier.
    pub fn trusted_dealer<R: rand_core::RngCore + rand_core::CryptoRng>(
        threshold: u16,
        total: u16,
        rng: &mut R,
    ) -> Result<Self, FrostError> {
        if threshold < 2 {
            return Err(FrostError::BadConfiguration(
                "threshold must be at least 2 — a 1-of-n group is a \
                 single-signer account wearing a cold-tier name"
                    .to_string(),
            ));
        }
        if total < threshold {
            return Err(FrostError::BadConfiguration(
                "total participants must be >= threshold".to_string(),
            ));
        }

        let (shares, public) = frost::keys::generate_with_dealer(
            total,
            threshold,
            frost::keys::IdentifierList::Default,
            rng,
        )
        .map_err(|e| FrostError::Protocol(e.to_string()))?;

        let mut key_packages = BTreeMap::new();
        for (id, share) in shares {
            let pkg = frost::keys::KeyPackage::try_from(share)
                .map_err(|e| FrostError::Protocol(e.to_string()))?;
            key_packages.insert(identifier_to_u16(&id)?, pkg);
        }

        Ok(Self {
            key_packages,
            public,
        })
    }

    /// The group's Ed25519 public key — what the chain registers as the
    /// account's authority, indistinguishable from a personal key.
    pub fn group_public_key(&self) -> Result<[u8; 32], FrostError> {
        let bytes = self
            .public
            .verifying_key()
            .serialize()
            .map_err(|e| FrostError::Protocol(e.to_string()))?;
        bytes
            .as_slice()
            .try_into()
            .map_err(|_| FrostError::Protocol("group verifying key is not 32 bytes".to_string()))
    }
}

