impl LocalFrostSigner {
    /// Build a signer over `participants`, requiring `threshold` of them.
    ///
    /// # Errors
    ///
    /// [`SignError::Backend`] if fewer participants than the threshold are
    /// supplied — a signer that can never sign is a configuration error worth
    /// failing at construction rather than at the first payment.
    pub fn new(
        participants: Vec<FrostParticipant>,
        public: frost::keys::PublicKeyPackage,
        threshold: u16,
    ) -> Result<Self, FrostError> {
        if participants.len() < threshold as usize {
            return Err(FrostError::BadConfiguration(
                "signer has fewer participants than its threshold — it could \
                 never produce a signature"
                    .to_string(),
            ));
        }
        let bytes = public
            .verifying_key()
            .serialize()
            .map_err(|e| FrostError::Protocol(e.to_string()))?;
        let group_pubkey: [u8; 32] = bytes
            .as_slice()
            .try_into()
            .map_err(|_| FrostError::Protocol("group verifying key is not 32 bytes".to_string()))?;

        Ok(Self {
            participants,
            public,
            threshold,
            group_pubkey,
        })
    }

    /// Run both rounds and aggregate. The synchronous core of
    /// [`AsyncSigner::try_sign_async`], separated so it is testable without an
    /// executor.
    pub fn sign_blocking(&self, message: &[u8]) -> Result<[u8; 64], FrostError> {
        use rand_core::OsRng;

        // Round 1 — every available participant commits. Nonces stay local to
        // this call and are consumed exactly once; see `FrostParticipant`.
        let mut nonces = BTreeMap::new();
        let mut commitments = BTreeMap::new();
        for p in self.participants.iter().take(self.threshold as usize) {
            let (n, c) = p.commit(&mut OsRng);
            nonces.insert(p.id(), n);
            commitments.insert(p.id(), c);
        }

        let coordinator = FrostCoordinator::new(&self.public, self.threshold);
        let package = coordinator.signing_package(message, &commitments)?;

        // Round 2.
        let mut shares = BTreeMap::new();
        for p in self.participants.iter().take(self.threshold as usize) {
            let n = nonces
                .get(&p.id())
                .ok_or_else(|| FrostError::Protocol("missing nonce for participant".to_string()))?;
            shares.insert(p.id(), p.sign(&package, n)?);
        }

        coordinator.aggregate(&package, &shares)
    }
}

impl DkgRound2 {
    /// This participant's 1-based index.
    pub fn id(&self) -> ParticipantId {
        self.id
    }

    /// **Part 3** — verify each peer's share against its published commitment
    /// and sum them into this participant's long-lived key share.
    ///
    /// The verification is Feldman VSS: `g^{f_ℓ(i)}` must match the commitment
    /// `ℓ` broadcast in round 1. A participant that sends a share inconsistent
    /// with its own commitment is rejected and named
    /// ([`tests::a_tampered_round2_share_is_rejected`]), which is what makes
    /// this a *verifiable* secret sharing and not merely a distributed one.
    ///
    /// Returns a [`FrostParticipant`] — the same type the trusted-dealer path
    /// produces, holding the same `KeyPackage`/`PublicKeyPackage` shapes. That
    /// is why DKG costs the signing path nothing: from part 3 onward there is no
    /// difference to detect.
    ///
    /// # Errors
    ///
    /// [`FrostError::BelowThreshold`] if fewer than `total - 1` peers sent a
    /// share.
    ///
    /// [`FrostError::Protocol`] if any share fails its VSS check, or the sender
    /// set does not match round 1's.
    pub fn finish(
        self,
        peer_shares: &BTreeMap<ParticipantId, Round2Package>,
    ) -> Result<FrostParticipant, FrostError> {
        let expected = usize::from(self.total) - 1;
        if peer_shares.contains_key(&self.id) {
            return Err(FrostError::BadConfiguration(
                "a participant must not include its own round-2 share".to_string(),
            ));
        }
        if peer_shares.len() < expected {
            return Err(FrostError::BelowThreshold {
                got: peer_shares.len() + 1,
                need: usize::from(self.total),
            });
        }

        let mut by_identifier = BTreeMap::new();
        for (id, pkg) in peer_shares {
            by_identifier.insert(u16_to_identifier(*id)?, pkg.clone());
        }

        let (key_package, public) =
            frost::keys::dkg::part3(&self.secret, &self.round1_packages, &by_identifier)
                .map_err(|e| FrostError::Protocol(e.to_string()))?;

        Ok(FrostParticipant::new(self.id, key_package, public))
    }
}

impl TxSigningMessage {
    /// Build the canonical message for `(action, nonce, digest)`.
    ///
    /// `network_id` is the `u32` from `TxDelta::_reserved[1..5]` — see
    /// `riir_chain::wallet::NetworkId`. `digest` is BLAKE3 of the transaction's
    /// signable prefix; the module docs explain why the verifier must recompute
    /// it rather than trust a checksum field.
    ///
    /// `const fn`, so a fixture message can be a `const` in a test and the
    /// layout is checked at compile time.
    pub const fn new(action: u8, nonce: u64, network_id: u32, digest: &[u8; 32]) -> Self {
        let mut buf = [0u8; TX_MESSAGE_LEN];
        let mut at = 0;

        at = write_bytes(&mut buf, at, TX_MESSAGE_V3_DOMAIN);
        at = write_bytes(&mut buf, at, LABEL_NETWORK);
        at = write_hex_u32(&mut buf, at, network_id);
        at = write_bytes(&mut buf, at, b"\n");

        at = write_bytes(&mut buf, at, LABEL_ACTION);
        at = write_hex_u8(&mut buf, at, action);
        at = write_bytes(&mut buf, at, b"\n");

        at = write_bytes(&mut buf, at, LABEL_NONCE);
        at = write_hex_u64(&mut buf, at, nonce);
        at = write_bytes(&mut buf, at, b"\n");

        at = write_bytes(&mut buf, at, LABEL_DIGEST);
        at = write_hex_bytes(&mut buf, at, digest);
        at = write_bytes(&mut buf, at, b"\n");

        // A layout slip would silently change every signature in the network,
        // so it is a compile error rather than a runtime surprise.
        assert!(at == TX_MESSAGE_LEN, "TxSigningMessage layout drifted");
        Self { buf }
    }

    /// The signable bytes. This is what goes to [`crate::Signer::try_sign`].
    #[inline]
    pub const fn as_bytes(&self) -> &[u8; TX_MESSAGE_LEN] {
        &self.buf
    }

    /// The message as text, for wallets whose signing API takes a string.
    ///
    /// Infallible: every byte written is ASCII by construction, so the UTF-8
    /// check cannot fail. The `expect` documents that invariant rather than
    /// guarding a real failure mode.
    #[inline]
    pub fn as_str(&self) -> &str {
        core::str::from_utf8(&self.buf).expect("message is ASCII by construction")
    }
}

