impl Config {
    fn from_env() -> Self {
        // Empty means unset: the Container host (index.js envVars) passes
        // unset Worker vars as empty strings so /health can distinguish
        // "unset var" from "var set to empty" — without this filter the
        // empty string parses as a (refused) value and the agent exits 2 on
        // a perfectly default-configured deployment. Found by the first
        // real Cloudflare deploy (Bench 331).
        let max_sign = match std::env::var("MAX_SIGN_AMOUNT").ok().filter(|s| !s.is_empty()) {
            Some(raw) => {
                let v: f32 = raw.parse().unwrap_or_else(|_| {
                    refuse_max_sign(&raw);
                });
                if !v.is_finite() || v < 0.0 {
                    refuse_max_sign(&raw);
                }
                v
            }
            None => DEFAULT_MAX_SIGN_AMOUNT,
        };
        let amount: f32 = env_parse("WALLET_AGENT_AMOUNT", 1.0);
        // is_finite first: `amount <= 0.0` is false for NaN, so the finite
        // check must run before the sign check to refuse NaN outright.
        if !amount.is_finite() || amount <= 0.0 || amount > max_sign {
            eprintln!(
                "[edge_wallet_agent] amount {amount} refused: must be finite > 0 and <= MAX_SIGN_AMOUNT ({max_sign})"
            );
            std::process::exit(2);
        }
        // Same encoding as the worker's transfer_delta: f32 coins → i64 minor.
        let amount_minor = (amount * 1_000_000.0) as u64;
        Self {
            rpc_url: std::env::var("RIIR_RPC_URL").ok().filter(|s| !s.is_empty()),
            node_pubkey: std::env::var("NODE_PUBKEY_HEX").ok().and_then(|s| unhex32(&s)),
            iters: env_parse("WALLET_AGENT_ITERS", 10),
            amount_minor,
            interval: Duration::from_millis(env_parse("WALLET_AGENT_INTERVAL_MS", 1000)),
            port: env_parse("PORT", 8080),
        }
    }

    /// The loop's precondition: a node URL **and** a pinned node key. Mirrors
    /// the Worker's refusal to trust a response without `NODE_PUBKEY_HEX` —
    /// and `HttpTransport` itself, which has no unpinned constructor.
    fn round_trip_ready(&self) -> Result<(&str, [u8; 32]), String> {
        match (&self.rpc_url, self.node_pubkey) {
            (Some(url), Some(pk)) => Ok((url, pk)),
            (None, _) => Err(
                "RIIR_RPC_URL not configured — the round-trip loop refuses to guess a node".into(),
            ),
            (_, None) => Err(
                "NODE_PUBKEY_HEX not configured — refusing to trust responses (a pinned key is mandatory)"
                    .into(),
            ),
        }
    }
}

#[derive(Default)]
struct LoopStats {
    iterations: u64,
    successes: u64,
    failures: u64,
    /// Full sign→submit→verify→read wall time per successful iteration, µs.
    samples: Vec<u64>,
    last_error: Option<String>,
    last_nonce: Option<u64>,
}

impl LoopStats {
    fn summary(&self) -> String {
        let mut s = format!(
            "iterations={} successes={} failures={}",
            self.iterations, self.successes, self.failures
        );
        if let Some(n) = self.last_nonce {
            s += &format!(" last_nonce={n}");
        }
        if !self.samples.is_empty() {
            let mut sorted = self.samples.clone();
            sorted.sort_unstable();
            let n = sorted.len();
            let at = |p: usize| sorted[p.min(n - 1)];
            s += &format!(
                " latency_us p50={} p99={} min={} max={}",
                at(n * 50 / 100),
                at(n * 99 / 100),
                sorted[0],
                sorted[n - 1]
            );
        }
        if let Some(e) = &self.last_error {
            // This string is embedded in hand-rolled JSON below — keep it to
            // graphic ASCII minus the two characters that would break it.
            let clean: String = e
                .chars()
                .filter(|c| (c.is_ascii_graphic() || *c == ' ') && *c != '"' && *c != '\\')
                .collect();
            s += &format!(" last_error={clean}");
        }
        s
    }

fn main() {
    let mode = std::env::args().nth(1).unwrap_or_default();

    // Parity is offline + deterministic: no identities, no config, no env.
    // It must never depend on anything a deployment sets or forgets to.
    if mode == "parity" {
        let id = WalletIdentity::from_seed(PARITY_SEED);
        let envelope = parity_envelope(&id, PARITY_TOKEN_IDX, PARITY_AMOUNT, PARITY_NONCE);
        assert!(envelope.verify(), "the constructed envelope must verify");
        let bytes = envelope.as_bytes();
        println!(
            "edge_wallet_agent parity OK — envelope {} bytes, player_id_hash {}\nenvelope_hex {}",
            bytes.len(),
            hex(&id.player_id_hash()),
            hex(bytes)
        );
        return;
    }

    let cfg = Config::from_env();
    let (a, b) = load_identity_pair();

    match mode.as_str() {
        // (parity handled above — it must not load keys or config)
        "health" => {
            let (ia, ib) = (a.info(), b.info());
            println!("{}", health_json(&ia, &ib, &cfg));
        }
        "once" => {
            let stats = Arc::new(Mutex::new(LoopStats::default()));
            let (ia, ib) = (a.info(), b.info());
            let clients = build_clients(&cfg, a, b);
            // A Tokio reactor is mandatory for the reqwest-backed transport —
            // see the crate docs on the dev-dep. One runtime for the run.
            tokio::runtime::Runtime::new()
                .expect("tokio runtime")
                .block_on(run_loop(cfg, clients, ia, ib, Arc::clone(&stats)));
            let s = stats.lock().unwrap();
            if s.successes == 0 {
                // The reason is in the stats, not necessarily on stdout —
                // print it here so a failed `once` run is self-explaining.
                let reason = s
                    .last_error
                    .clone()
                    .unwrap_or_else(|| "no iterations recorded".into());
                eprintln!("no successful iteration: {reason}");
                std::process::exit(1);
            }
        }
        // Default: the Container shape — loop on a thread, serve HTTP after.
        _ => {
            let stats = Arc::new(Mutex::new(LoopStats::default()));
            let (ia, ib) = (a.info(), b.info());
            let health = health_json(&ia, &ib, &cfg);
            let port = cfg.port;
            {
                let stats = Arc::clone(&stats);
                thread::spawn(move || {
                    // Own reactor on the loop thread (main's std::net listener
                    // needs none) — reqwest cannot run without one. The
                    // clients are built INSIDE the thread, after the spawn:
                    // under `external-signer` a built `WalletClient` can be
                    // `!Send` (`Box<dyn AsyncSigner>`), and a spawn closure
                    // must be `Send` — while `KeyMat`/`Config` always are.
                    // `block_on` itself demands no `Send` of the future.
                    tokio::runtime::Runtime::new()
                        .expect("tokio runtime")
                        .block_on(async move {
                            let clients = build_clients(&cfg, a, b);
                            run_loop(cfg, clients, ia, ib, stats).await
                        })
                });
            }
            let listener = TcpListener::bind(("0.0.0.0", port)).expect("bind");
            println!("[edge_wallet_agent] serving /health + /parity + /stats on :{port}");
            let parity = parity_json();
            for conn in listener.incoming() {
                let Ok(stream) = conn else { continue };
                let health = health.clone();
                let parity = parity.clone();
                let stats = Arc::clone(&stats);
                thread::spawn(move || handle_conn(stream, health, parity, stats));
            }
        }
    }
}

fn main() {
    // Native smoke run: `cargo run -p riir-wallet --example wasm_abi_probe`.
    // Proves the exported functions actually work, not just that they link.
    let seed = [7u8; 32];
    // SAFETY: `seed` is 32 readable bytes, which is the ABI contract for both.
    let n = unsafe {
        assert_eq!(identity_from_seed(seed.as_ptr()), 16);
        sign_transfer(seed.as_ptr(), 0, 5.0, 1)
    };
    assert_eq!(n, WalletTxEnvelope::SIZE as i32);

    let bytes = unsafe {
        let buf = &*core::ptr::addr_of!(BUF);
        buf[..n as usize].to_vec()
    };
    let envelope = WalletTxEnvelope::from_bytes(&bytes).expect("round-trips");
    assert!(envelope.verify(), "the signed envelope must verify");

    // Printed so the Cloudflare POC can diff its Worker-produced envelope against
    // a native one for the same inputs. `envelope.verify()` above already passed,
    // so a matching hex means the Worker's bytes are valid on the chain's own
    // verifier — the cross-target check in .benchmarks/023.
    println!(
        "wasm_abi_probe OK — envelope {} bytes, player_id_hash {}\nenvelope_hex {}",
        n,
        hex(&envelope.player_id_hash()),
        hex(&bytes)
    );
}

