impl FloatPolicy {
    /// Construct a policy.
    ///
    /// # Errors
    ///
    /// See [`FloatPolicyError`]. Both cases are refused at construction rather
    /// than tolerated at evaluation, because a policy that silently never fires
    /// is indistinguishable from a policy that is working.
    pub fn new(floor: f32, ceiling: f32) -> Result<Self, FloatPolicyError> {
        if !floor.is_finite() || !ceiling.is_finite() || floor < 0.0 || ceiling < 0.0 {
            return Err(FloatPolicyError::NonFiniteBound);
        }
        if floor >= ceiling {
            return Err(FloatPolicyError::InvertedBand { floor, ceiling });
        }
        Ok(Self { ceiling, floor })
    }

    /// Decide what to do given the hot account's coin vector.
    ///
    /// Returns [`FloatAction::Hold`] for a non-finite total rather than
    /// inventing a sweep amount: a `NaN` balance means the account is already
    /// broken (Issue 026), and the correct response is to touch nothing and let
    /// the finiteness guards surface it, not to compute a transfer from a
    /// poisoned number.
    pub fn plan(&self, hot_balance: &[f32; 8]) -> FloatAction {
        let total: f32 = hot_balance.iter().sum();
        if !total.is_finite() {
            return FloatAction::Hold;
        }
        if total > self.ceiling {
            return FloatAction::Sweep {
                amount: total - self.ceiling,
            };
        }
        if total < self.floor {
            return FloatAction::TopUp {
                amount: self.ceiling - total,
            };
        }
        FloatAction::Hold
    }

    /// Whether `tier` is the one a sweep may be *authorised* by.
    ///
    /// Only a Hot account sweeps. Sweeping "from" a Cold account is a top-up
    /// wearing the wrong name, and would need the ceremony this call cannot
    /// perform — so it is refused here rather than discovered at signing time.
    pub fn may_sweep_from(tier: WalletTier) -> bool {
        matches!(tier, WalletTier::Hot)
    }
}

