    async fn submit_tx(&mut self, envelope: &WalletTxEnvelope) -> Result<TxReceipt, Error> {
        // Reconstruct (action, delta, target, gas) from the signed tx — the
        // RSM's submit_tx_to re-derives the alpha key internally.
        //
        // `target_hash` MUST be forwarded (Issue 018): dropping it here would
        // turn every transfer into a recipient-less transaction, which the
        // settlement check now rejects — so the bug would surface as a confusing
        // `TransferTargetMissing` on a transfer that plainly named a recipient.
        //
        // The gas tier is forwarded for the same reason (game-sdk T2.4): the
        // fields are inside the checksum the signature covers, so reading them
        // is reading what the submitter signed — and dropping them would
        // silently downgrade every in-process paid-tier submission to the free
        // tier while a wire server processing the same envelope charges the
        // burn. The two paths must agree on what a signed tx means.
        let action = envelope.signed.tx.action_slot;
        let delta = envelope.signed.tx.delta_vector;
        let target = envelope.signed.tx.target_hash;
        let gas = GasParams {
            limit: envelope.signed.tx.gas_limit,
            price: envelope.signed.tx.gas_price,
        };

        // CONTRACT: the RSM trusts the local caller, so `envelope.pubkey` and
        // `envelope.signed.signature` are deliberately ignored here — there is
        // no network boundary to authenticate across, and the RSM's existing
        // `submit_tx` contract has never taken a signature. Wire transports MUST
        // verify (see `SimRing::submit_wallet_stream`), which is why the
        // signature is carried in the envelope at all.
        self.rsm
            .submit_tx_to_with_gas(self.client_idx, action, delta, target, gas)
            .map_err(Error::from)
    }

const _: fn() = || {
    fn _assert_from(_e: TxRejection) -> Error {
        Error::from(_e)
