impl NativeWtTransport {
    /// Connect to a chain node, pinning its certificate by SHA-256 hash.
    ///
    /// `addr` is `host:port`; the `https://` scheme is added internally and a
    /// bare host defaults to port 9001. Get `cert_hash` from the node's
    /// `WtServer::cert_hash` and distribute it out-of-band (config file, CLI
    /// flag, invite link).
    pub async fn connect(addr: &str, cert_hash: [u8; 32]) -> Result<Self, Error> {
        let config = ClientConfig::builder()
            .with_bind_default()
            .with_server_certificate_hashes([wtransport::tls::Sha256Digest::new(cert_hash)])
            .build();
        Self::connect_with_config(addr, config).await
    }

    /// Connect without validating the server certificate. **Dev only.**
    ///
    /// Vulnerable to MITM: anyone on the path can present any certificate and
    /// read or rewrite every transaction. Prefer [`Self::connect`] with a pinned
    /// hash.
    pub async fn connect_insecure(addr: &str) -> Result<Self, Error> {
        warn_insecure(addr);
        let config = ClientConfig::builder()
            .with_bind_default()
            .with_no_cert_validation()
            .build();
        Self::connect_with_config(addr, config).await
    }

    async fn connect_with_config(addr: &str, config: ClientConfig) -> Result<Self, Error> {
        let endpoint = Endpoint::client(config)
            .map_err(|e| Error::Transport(format!("creating WebTransport client endpoint: {e}")))?;

        // Parse host:port. rsplit_once avoids the Vec<&str> that
        // `split(':').collect()` allocates (matches WtClient).
        let (host, port) = match addr.rsplit_once(':') {
            Some((h, p)) => (h, p.parse::<u16>().unwrap_or(DEFAULT_WT_PORT)),
            None => (addr, DEFAULT_WT_PORT),
        };

        let conn = endpoint
            .connect(format!("https://{host}:{port}"))
            .await
            .map_err(|e| Error::Transport(format!("connecting to {host}:{port}: {e}")))?;

        Ok(Self {
            conn,
            query_nonce: 0,
        })
    }

    /// The underlying connection (for lifecycle management / diagnostics).
    #[inline]
    pub fn connection(&self) -> &Connection {
        &self.conn
    }

    /// Open a bidi stream, write `[stream_type][payload]`, read exactly
    /// `out.len()` bytes back.
    ///
    /// The header byte and the payload go out in **one** `write_all` from a
    /// stack buffer. QUIC would coalesce them anyway, and a single write means
    /// the server never sees a partial frame between its two `read_exact` calls.
    async fn round_trip(
        &self,
        stream_type: u8,
        payload: &[u8],
        out: &mut [u8],
    ) -> Result<(), Error> {
        // The stack buffer is sized to the largest request this build can
        // send. Under `cpi` that is the 696-byte `CpiTxEnvelope`, not the
        // 288-byte `WalletTxEnvelope` — a budget that did not grow with the
        // frame set would reject every CPI at the client with a confusing
        // "exceeds the frame budget" instead of sending it.
        #[cfg(feature = "cpi")]
        const MAX_REQUEST: usize = 1 + CpiTxEnvelope::SIZE;
        #[cfg(not(feature = "cpi"))]
        const MAX_REQUEST: usize = 1 + WalletTxEnvelope::SIZE;
        let frame_len = 1 + payload.len();
        if frame_len > MAX_REQUEST {
            return Err(Error::Transport(format!(
                "wallet request payload {} exceeds the {MAX_REQUEST}-byte frame budget",
                payload.len()
            )));
        }
        let mut req = [0u8; MAX_REQUEST];
        req[0] = stream_type;
        req[1..frame_len].copy_from_slice(payload);

        let (mut send, mut recv) = self
            .conn
            .open_bi()
            .await
            .map_err(|e| Error::Transport(format!("opening wallet bidi stream: {e}")))?
            .await
            .map_err(|e| Error::Transport(format!("wallet bidi stream not ready: {e}")))?;

        send.write_all(&req[..frame_len])
            .await
            .map_err(|e| Error::Transport(format!("writing wallet request: {e}")))?;

        // Read the response BEFORE finishing the send half.
        //
        // `SendStream::finish` "completes when the peer has acknowledged all
        // sent data" — so if the server has already answered and returned (which
        // it does on every rejection path), it has stopped reading and `finish`
        // fails with `Stopped`. Blocking on it first turned every server-side
        // rejection into an opaque "stream stopped (code: 0)" and threw away the
        // `WalletReceiptFrame` that was sitting in the recv buffer explaining why.
        //
        // EOF is not needed for correctness in either direction: every frame in
        // this protocol is fixed-size and both sides use `read_exact`.
        recv.read_exact(out)
            .await
            .map_err(|e| Error::Transport(format!("reading wallet response: {e}")))?;

        // Best-effort graceful close now that we have the answer. A failure here
        // is not interesting — the response is already in hand, and the stream is
        // dropped immediately after.
        let _ = send.finish().await;

        Ok(())
    }

    /// Shared read path — one round-trip answers both balance and nonce.
    async fn query(
        &self,
        action: u8,
        player_id_hash: [u8; 16],
    ) -> Result<([u64; 8], u64), Error> {
        let envelope = WalletQueryEnvelope::new(action, player_id_hash, self.query_nonce);
        let mut out = [0u8; WalletQueryResponse::SIZE];
        self.round_trip(STREAM_WALLET_QUERY, bytemuck::bytes_of(&envelope), &mut out)
            .await?;
        WalletQueryResponse::from_bytes(&out)
            .ok_or_else(|| Error::Transport("short wallet query response".into()))?
            .into_result()
    }
}

impl WalletQueryEnvelope {
    /// Total size in bytes.
    pub const SIZE: usize = std::mem::size_of::<Self>();

    /// Create a query envelope with a **fresh random challenge** (Plan 020 T1.3).
    ///
    /// The challenge is what makes the read path non-replayable: the node echoes
    /// it inside the signed region of its response, and
    /// [`crate::signed_response::query_binding`] hashes this envelope into the
    /// binding the client then requires. A predictable or constant nonce would let
    /// an attacker replay a captured signed balance forever.
    ///
    /// Plan 019 stamped a caller-supplied counter here that was always `0`, which
    /// made the "replay protection" purely structural. This constructor removes
    /// that footgun by not offering the choice.
    ///
    /// # Availability
    ///
    /// Same gate as [`crate::WalletIdentity::generate`], and for the same
    /// reason: `OsRng` needs a randomness source, which `wasm32` only has under
    /// `wasm-fetch`. A non-browser wasm host must draw its own CSPRNG value and
    /// pass it to [`new`](Self::new) — the alternative would be handing it a
    /// silently weak challenge, which is worse than a compile error.
    #[cfg(any(not(target_arch = "wasm32"), feature = "wasm-fetch"))]
    #[inline]
    pub fn with_challenge(action: u8, player_id_hash: [u8; 16]) -> Self {
        Self::new(action, player_id_hash, random_challenge())
    }

    /// Create a new query envelope with an explicit nonce.
    ///
    /// Prefer [`Self::with_challenge`] for anything that will be verified — a
    /// caller-chosen nonce is only safe if the caller guarantees freshness. This
    /// constructor exists for tests and for replaying a known envelope.
    #[inline]
    pub fn new(action: u8, player_id_hash: [u8; 16], nonce: u64) -> Self {
        let mut env = Self {
            action,
            _pad0: [0u8; 7],
            nonce,
            player_id_hash,
            checksum: [0u8; 32],
        };
        env.recompute_checksum();
        env
    }

    /// Recompute the BLAKE3 checksum over all preceding fields.
    #[inline]
    pub fn recompute_checksum(&mut self) {
        let prefix: &[u8] = &bytemuck::bytes_of(self)[..Self::SIZE - 32];
        let hash = blake3::hash(prefix);
        self.checksum.copy_from_slice(hash.as_bytes());
    }

    /// Verify the checksum matches the current field contents.
    #[inline]
    pub fn verify_checksum(&self) -> bool {
        let prefix: &[u8] = &bytemuck::bytes_of(self)[..Self::SIZE - 32];
        let expected = blake3::hash(prefix);
        self.checksum == *expected.as_bytes()
    }
}

impl SignedWalletQueryEnvelope {
    /// Total size in bytes.
    pub const SIZE: usize = std::mem::size_of::<Self>();

    /// BLAKE3 over the query's checksummed prefix — the digest the signature
    /// commits to.
    ///
    /// **Recomputed, never read from `query.checksum`.** Trusting the stored field
    /// would let an attacker mutate the prefix and keep a valid signature; this is
    /// the same property [`crate::SignedTxDelta::verify`] documents, and it
    /// collapses checksum validation and signature validation into one check at
    /// the trust boundary.
    #[inline]
    pub fn digest(query: &WalletQueryEnvelope) -> [u8; 32] {
        let prefix = &bytemuck::bytes_of(query)[..WalletQueryEnvelope::SIZE - 32];
        *blake3::hash(prefix).as_bytes()
    }

    /// The exact bytes a signature must cover: `QUERY_SIGNING_DOMAIN ‖ digest`.
    ///
    /// Built into a stack buffer — no allocation, so this is usable on an
    /// alloc-free path.
    #[inline]
    pub fn signing_message(query: &WalletQueryEnvelope) -> [u8; QUERY_MESSAGE_LEN] {
        let mut msg = [0u8; QUERY_MESSAGE_LEN];
        let d = QUERY_SIGNING_DOMAIN.len();
        msg[..d].copy_from_slice(QUERY_SIGNING_DOMAIN);
        msg[d..].copy_from_slice(&Self::digest(query));
        msg
    }

    /// Build a signed query from a pubkey, a signature and a query.
    #[inline]
    pub fn from_parts(pubkey: [u8; 32], signature: [u8; 64], query: WalletQueryEnvelope) -> Self {
        Self {
            pubkey,
            signature,
            query,
        }
    }

    /// The frame's bytes, ready to write to a stream. Zero-copy.
    #[inline]
    pub fn as_bytes(&self) -> &[u8] {
        bytemuck::bytes_of(self)
    }

    /// Parse from exactly [`Self::SIZE`] bytes. `None` on a length mismatch.
    #[inline]
    pub fn from_bytes(bytes: &[u8]) -> Option<Self> {
        (bytes.len() == Self::SIZE).then(|| bytemuck::pod_read_unaligned(bytes))
    }

    /// The account id this frame's key derives to — `BLAKE3(pubkey)[..16]`.
    ///
    /// The same derivation `ChainClient::new` and `WalletTxEnvelope` perform. The
    /// node uses **this**, never `query.player_id_hash`, as the account to resolve
    /// from.
    #[inline]
    pub fn derived_player_id_hash(&self) -> [u8; 16] {
        let h = blake3::hash(&self.pubkey);
        let mut out = [0u8; 16];
        out.copy_from_slice(&h.as_bytes()[..16]);
        out
    }

    /// Verify the frame at the trust boundary. Three checks, in this order.
    ///
    /// 1. **Checksum**, recomputed from the received bytes and compared to
    ///    `query.checksum`. Cheap, and it fails before any curve work.
    /// 2. **Signature**, `verify_strict` over [`Self::signing_message`].
    /// 3. **Identity binding**: `query.player_id_hash == BLAKE3(pubkey)[..16]`.
    ///
    /// Check 3 is what keeps `player_id_hash` meaningful rather than ignored: the
    /// client names *itself*, the signature covers the name, and the node never
    /// takes a claimed identity. Without it the field would be dead weight on this
    /// stream, and a reader would reasonably assume it was being honoured.
    ///
    /// No `#[cfg]` on this method: `ed25519-dalek` is a **non-optional**
    /// dependency of this crate (`Cargo.toml:109`), so gating it on an `ed25519`
    /// feature — as `riir-wallet-signer` correctly does, because there it *is*
    /// optional — would compile the verifier out unconditionally and leave a frame
    /// type nothing can check.
    pub fn verify(&self) -> bool {
        use ed25519_dalek::{Signature, Verifier, VerifyingKey};

        if Self::digest(&self.query) != self.query.checksum {
            return false;
        }
        let Ok(vk) = VerifyingKey::from_bytes(&self.pubkey) else {
            return false;
        };
        let sig = Signature::from_bytes(&self.signature);
        if vk
            .verify(&Self::signing_message(&self.query), &sig)
            .is_err()
        {
            return false;
        }
        self.query.player_id_hash == self.derived_player_id_hash()
    }
}

impl WalletSigner {
    /// Wrap a connected external wallet.
    ///
    /// The signer must already know its public key — connecting is the
    /// bridge's job, not this type's. A wallet that cannot state its key is
    /// not connected yet.
    #[cfg(feature = "external-signer")]
    #[inline]
    pub fn external(signer: Box<dyn AsyncSigner>) -> Self {
        Self::External(signer)
    }

    /// The account's Ed25519 public key, which is also its `player_uuid`.
    #[inline]
    pub fn public_key(&self) -> [u8; 32] {
        match self {
            Self::Local(id) => riir_wallet_signer::Signer::public_key(id),
            #[cfg(feature = "external-signer")]
            Self::External(s) => s.public_key(),
        }
    }

    /// `BLAKE3(public_key)[..16]` — the on-chain account identifier.
    ///
    /// Cached for the local arm; recomputed for the external arm, where it is
    /// off the hot path by construction.
    #[inline]
    pub fn player_id_hash(&self) -> [u8; 16] {
        match self {
            Self::Local(id) => id.player_id_hash(),
            #[cfg(feature = "external-signer")]
            Self::External(s) => s.player_id_hash(),
        }
    }

    /// The local key, if this is one.
    ///
    /// `None` for an external wallet — which is the point: code that needs the
    /// private key (seed export, offline signing) must handle its absence
    /// rather than assume custody.
    #[inline]
    pub fn local(&self) -> Option<&WalletIdentity> {
        match self {
            Self::Local(id) => Some(id),
            #[cfg(feature = "external-signer")]
            Self::External(_) => None,
        }
    }

    /// Produce a signature over `message`.
    ///
    /// `message` is always [`riir_wallet_signer::TxSigningMessage::as_bytes`]
    /// — see [`crate::SignedTxDelta::signing_message`].
    ///
    /// # Errors
    ///
    /// Never, for the local arm. For the external arm, whatever the wallet
    /// reports: declined, locked, or a backend fault.
    #[inline]
    pub async fn sign(&self, message: &[u8]) -> Result<[u8; 64], SignError> {
        match self {
            // No `.await`: a local signature is available immediately, and
            // adding a suspension point here would be pure overhead.
            Self::Local(id) => Ok(id.sign(message).to_bytes()),
            #[cfg(feature = "external-signer")]
            Self::External(s) => s.try_sign_async(message).await,
        }
    }
}

