static GLOBAL: CountingAllocator = CountingAllocator;

/// G4: the LOCAL hot path (construct + sign SignedTxDelta) allocates zero
/// bytes after warm-up. Ed25519 signing + BLAKE3 hashing operate on
/// stack-allocated buffers.
#[test]
fn g4_wallet_local_hot_path_alloc_free() {
    let identity = WalletIdentity::from_test_seed(0x6A4);
    let chain_client = riir_chain::consensus::client::ChainClient::new(identity.player_uuid());

    // Warm-up. Also forces the thread-local counter's lazy init, so its own
    // first-touch allocation is not attributed to the measured window.
    let _ = alloc_count();
    for _ in 0..10 {
        let (tx, _) = chain_client.create_tx_with_nonce(0xA0, [1_000_000i64; 8], 0);
        let _ = SignedTxDelta::sign(&tx, &identity);
    }

    // Measure allocations over 100 steady-state iterations.
    const ITERATIONS: u32 = 100;
    let allocs_before = alloc_count();

    for i in 0..ITERATIONS {
        let (tx, _) = chain_client.create_tx_with_nonce(0xA0, [1_000_000i64; 8], i as u64);
        let _signed = SignedTxDelta::sign(&tx, &identity);
    }

    let allocs_during = alloc_count() - allocs_before;

    // Now that the count is this thread's own, the bar is **exactly zero** rather
    // than "fewer than one per iteration". The old tolerance existed to absorb
    // other tests' allocations; with that source removed, any allocation here is
    // a real regression in the signing path.
    assert_eq!(
        allocs_during, 0,
        "G4 FAIL: {allocs_during} allocations over {ITERATIONS} iterations (expected 0)"
    );

    println!(
        "G4 PASS: {} allocations over {} iterations ({:.2} per iter)",
        allocs_during,
        ITERATIONS,
        allocs_during as f64 / ITERATIONS as f64
    );
}

