    /// `epoch` — clears the `(viewer, target, old_epoch)` entries so they
    /// can be re-submitted under the new epoch.
    #[inline]
    pub fn reset(&mut self) {
        self.seen.clear();
    }

    /// Number of recorded pairs. For observability.
    #[inline]
    pub fn len(&self) -> usize {
        self.seen.len()
    }

    /// Is the limiter empty?
    #[inline]
    pub fn is_empty(&self) -> bool {
        self.seen.is_empty()
    }
}

