impl MapPos {
    #[inline]
    pub const fn new(x: f32, y: f32, z: f32) -> Self {
        Self { x, y, z }
    }

    /// 2D constructor (z = 0). Consumers with a flat world use this.
    #[inline]
    pub const fn new_2d(x: f32, y: f32) -> Self {
        Self { x, y, z: 0.0 }
    }

    /// Squared 3D distance to `other`. No `sqrt` — use this for comparisons.
    #[inline]
    pub fn dist_sq(&self, other: &Self) -> f32 {
        let dx = self.x - other.x;
        let dy = self.y - other.y;
        let dz = self.z - other.z;
        dx * dx + dy * dy + dz * dz
    }

    /// Squared 2D (xy-plane) distance to `other`. For AOI on a flat world;
    /// ignores z so a viewer on a high ledge still sees entities at ground
    /// level within the radius.
    #[inline]
    pub fn dist_sq_xy(&self, other: &Self) -> f32 {
        let dx = self.x - other.x;
        let dy = self.y - other.y;
        dx * dx + dy * dy
    }
}

