#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Default)]
struct CellKey(i32, i32, i32);

impl GridSpatialIndex {
    /// Construct with given cell size. `cell_size` MUST be > 0.
    #[inline]
    pub fn new(cell_size: f32) -> Self {
        assert!(cell_size > 0.0, "cell_size must be positive");
        Self {
            cell_size,
            cells: FxHashMap::default(),
            id_to_cell_pos: FxHashMap::default(),
        }
    }

    /// Walk every `(id, position)` inside `radius` of `center`, in the
    /// documented deterministic order (cell-lexicographic, then insertion
    /// order within a cell), handing each to `visit`.
    ///
    /// Shared by `query_into` / `query_pairs_into` so the bbox clamping and
    /// walk order can never drift between the two. Generic over the closure
    /// (not `&mut dyn FnMut`) so both callers monomorphise to the same code
    /// the hand-written loop produced.
    #[inline]
    fn walk_radius<F: FnMut(AoiEntityId, MapPos)>(&self, center: MapPos, radius: f32, mut visit: F) {
        // 2D bbox in cell coordinates. z collapses to layer 0.
        let min_x = ((center.x - radius) / self.cell_size).floor() as i32;
        let max_x = ((center.x + radius) / self.cell_size).floor() as i32;
        let min_y = ((center.y - radius) / self.cell_size).floor() as i32;
        let max_y = ((center.y + radius) / self.cell_size).floor() as i32;

        // `radius` (== `ViewerCfg::max_distance`) is not clamped upstream the
        // way `max_fov` is. An extreme value drives the f32->i32 cast above
        // to saturate to i32::MIN/MAX, which would make the walk below run
        // ~2^32 iterations — or, since `cx`/`cy` wrap past i32::MAX back to
        // i32::MIN while `cx <= max_x` (== i32::MAX) stays true, never
        // terminate at all. Clamp the span to a generous but bounded window
        // around the center cell so no radius can blow up the walk.
        const MAX_CELL_SPAN: i32 = 4096;
        let center_cx = (center.x / self.cell_size).floor() as i32;
        let center_cy = (center.y / self.cell_size).floor() as i32;
        let min_x = min_x.max(center_cx.saturating_sub(MAX_CELL_SPAN));
        let max_x = max_x.min(center_cx.saturating_add(MAX_CELL_SPAN));
        let min_y = min_y.max(center_cy.saturating_sub(MAX_CELL_SPAN));
        let max_y = max_y.min(center_cy.saturating_add(MAX_CELL_SPAN));

        let r_sq = radius * radius;

        // Walk cells in lexicographic order — deterministic output order.
        let mut cx = min_x;
        while cx <= max_x {
            let mut cy = min_y;
            while cy <= max_y {
                if let Some(vec) = self.cells.get(&CellKey(cx, cy, 0)) {
                    for &(id, p) in vec.iter() {
                        // Squared 2D distance check (z ignored — Phase 1).
                        if center.dist_sq_xy(&p) <= r_sq {
                            visit(id, p);
                        }
                    }
                }
                cy += 1;
            }
            cx += 1;
        }
    }

    /// Compute the cell key for a position. Floors toward negative infinity.
    #[inline]
    fn cell_of(&self, p: MapPos) -> CellKey {
        // `f32::floor` is IEEE-754 deterministic across arch.
        CellKey(
            (p.x / self.cell_size).floor() as i32,
            (p.y / self.cell_size).floor() as i32,
            // z ignored in Phase 1 queries — collapse all z into a single
            // cell layer to avoid splitting entities across z-cells.
            0,
        )
    }
}

impl LatentBatchCommitter {
    pub fn new() -> Self {
        Self {
            processor: LatentBatchProcessor::new(),
        }
    }

    /// Process a batch group atomically.
    ///
    /// Steps:
    /// 1. Validate all determinants (SIMD batch)
    /// 2. If any invalid → reject entire batch
    /// 3. If all valid → commit all entries
    ///
    /// Note: Actual ChainServer interaction (split-key combine, cipher decrypt)
    /// happens OUTSIDE the committer — the committer handles the matrix-level
    /// atomicity. The SimRing drain_batch_latent() wires them together.
    pub fn commit_group(&self, group: &BatchGroup, current_tick: u64) -> BatchCommitResult {
        // Step 1: Batch determinant validation
        let det_result = self.processor.validate_batch_det(group);

        if !det_result.all_valid {
            // Atomic rejection: all entries fail — pre-allocate to avoid realloc
            let mut results = Vec::with_capacity(group.entries.len());
            for e in &group.entries {
                results.push(EntryResult::Rejected {
                    player_id_hash: e.player_id_hash,
                    rejection: TxRejection::StructureInvalid,
                });
            }

            return BatchCommitResult {
                results,
                committed: false,
                det_checks: det_result.total,
            };
        }

        // Step 2: All determinants valid — commit all entries
        let mut results = Vec::with_capacity(group.entries.len());
        for entry in &group.entries {
            results.push(EntryResult::Committed {
                player_id_hash: entry.player_id_hash,
                receipt: TxReceipt {
                    tx_commitment: entry.tx.tx_commitment,
                    new_nonce: entry.tx.nonce + 1,
                    accepted_at_tick: current_tick,
                    ix_receipt: None,
                },
            });
        }

        BatchCommitResult {
            committed: true,
            det_checks: det_result.total,
            results,
        }
    }

    /// Process multiple groups, each atomically.
    pub fn commit_groups(
        &self,
        groups: &[BatchGroup],
        current_tick: u64,
    ) -> Vec<BatchCommitResult> {
        let mut out = Vec::with_capacity(groups.len());
        out.extend(groups.iter().map(|g| self.commit_group(g, current_tick)));
        out
    }
}

impl LatentBatchGrouper {
    pub fn new() -> Self {
        Self {
            groups: [const { None }; SLOT_COUNT],
            arrival_counter: 0,
        }
    }

    /// Add an entry to the appropriate group.
    ///
    /// Extracts LatCalMatrix from the delta_vector:
    /// - Matrix 0: `[delta[0], delta[1], delta[2], delta[3]]`
    /// - Matrix 1: `[delta[4], delta[5], delta[6], delta[7]]`
    #[inline]
    pub fn add_entry(&mut self, player_id_hash: [u8; 16], tx: TxDelta, alpha_key: AlphaKey) {
        let action_slot = tx.action_slot;
        let slot_idx = (action_slot as usize).min(SLOT_COUNT - 1);
        let program_id = action_slot_to_program_id(action_slot);

        // Extract 2 LatCalMatrix from 8-lane delta_vector (cast i64→f32, Plan 029 E1)
        let dv = tx.delta_vector;
        let m0 = LatCalMatrix {
            value: dv[0] as f32,
            overflow: dv[1] as f32,
            sign: dv[2] as f32,
            precision: dv[3] as f32,
        };
        let m1 = LatCalMatrix {
            value: dv[4] as f32,
            overflow: dv[5] as f32,
            sign: dv[6] as f32,
            precision: dv[7] as f32,
        };

        // Stamp arrival order before grouping so callers can recover the
        // global position after `drain_groups()` reorders by action_slot.
        let arrival_index = self.arrival_counter;
        self.arrival_counter += 1;

        // O(1) lookup by slot index
        let entry = GroupedEntry {
            player_id_hash,
            tx,
            alpha_key,
            action_slot,
            arrival_index,
        };

        match &mut self.groups[slot_idx] {
            Some(g) => {
                if g.entries.len() < MAX_BATCH_SIZE {
                    g.entries.push(entry);
                    g.matrix_batch.push(m0);
                    g.matrix_batch.push(m1);
                }
            }
            slot => {
                let mut group = BatchGroup {
                    program_id,
                    entries: Vec::with_capacity(MAX_BATCH_SIZE),
                    matrix_batch: Vec::with_capacity(MAX_BATCH_SIZE * 2),
                };
                group.entries.push(entry);
                group.matrix_batch.push(m0);
                group.matrix_batch.push(m1);
                *slot = Some(group);
            }
        }
    }

    /// Drain all groups. Returns groups sorted by program_id (ascending slot order)
    /// for deterministic processing. No sort needed — slot order is naturally sorted.
    pub fn drain_groups(&mut self) -> Vec<BatchGroup> {
        // Pre-allocate based on actual non-empty group count to avoid the
        // grow-and-copy dance inside `flatten().collect()`.
        let group_count = self.group_count();
        let taken = std::mem::replace(&mut self.groups, [const { None }; SLOT_COUNT]);
        let mut out = Vec::with_capacity(group_count);
        out.extend(taken.into_iter().flatten());
        out
    }

    /// Total entries across all groups.
    #[inline]
    pub fn total_entries(&self) -> usize {
        self.groups
            .iter()
            .map(|g| g.as_ref().map_or(0, |g| g.entries.len()))
            .sum()
    }

    /// Number of groups.
    #[inline]
    pub fn group_count(&self) -> usize {
        self.groups.iter().filter(|g| g.is_some()).count()
    }
}

