impl RotationTable {
    /// Identity rotation (no perturbation). Used for testing and as default.
    pub fn identity() -> Self {
        let mut m = [[0.0f32; 8]; 8];
        for (i, row) in m.iter_mut().enumerate() {
            row[i] = 1.0;
        }
        Self {
            matrix: m,
            inverse_matrix: m,
        }
    }

    /// Compute the transpose (inverse for orthogonal matrices).
    pub fn transpose(&self) -> Self {
        let inv = Self::transpose_matrix(&self.matrix);
        Self {
            matrix: inv,
            inverse_matrix: self.matrix,
        }
    }

    /// Transpose an 8×8 matrix — shared between `transpose()`, `test_fixture()`, and `derive_from_seed()`.
    pub(crate) fn transpose_matrix(m: &[[f32; 8]; 8]) -> [[f32; 8]; 8] {
        let mut out = [[0.0f32; 8]; 8];
        for i in 0..8 {
            for j in 0..8 {
                out[i][j] = m[j][i];
            }
        }
        out
    }

    /// Derive a per-account rotation table from an account seed using BLAKE3.
    ///
    /// Uses BLAKE3-XOF to produce 256 bytes (8×8×sizeof(f32)) for the rotation
    /// matrix, then orthonormalizes via Gram-Schmidt to guarantee orthogonality.
    ///
    /// Without the account seed, the rotation cannot be reproduced — providing
    /// information-theoretic hiding of account structure (8×8 orthogonal rotation
    /// preserves Frobenius norm, hides structure).
    #[cfg(feature = "chain")]
    pub fn derive_from_seed(account_seed: &[u8; 32]) -> Self {
        let key = blake3::derive_key("riir-chain-account-rotation-v1", account_seed);
        let mut reader = blake3::Hasher::new_keyed(&key).finalize_xof();
        let mut entropy = [0u8; 256]; // 8×8×4 bytes
        reader.fill(&mut entropy);

        // Build 8×8 matrix from BLAKE3 entropy.
        // Zero-cost cast: [u8; 256] → [[f32-equivalent bits]] eliminates
        // 64× slice arithmetic + runtime length checks + the unwrap() panic path.
        // Matches the pattern already used in encoding/shell.rs line 109.
        let bits: &[u32; 64] = bytemuck::cast_ref(&entropy);
        let inv_u32_max = 1.0 / u32::MAX as f32;
        let mut m = [[0.0f32; 8]; 8];
        for i in 0..8 {
            for j in 0..8 {
                let b = bits[i * 8 + j];
                // Map to [-1, 1] then scale to avoid near-zero entries
                m[i][j] = (b as f32 * inv_u32_max) * 2.0 - 1.0;
            }
        }

        // Gram-Schmidt orthonormalization to guarantee orthogonality
        for col in 0..8 {
            // Subtract projections onto previous columns
            for prev in 0..col {
                let dot: f32 = (0..8).map(|row| m[row][col] * m[row][prev]).sum();
                for row in m.iter_mut() {
                    row[col] -= dot * row[prev];
                }
            }
            // Normalize
            let norm: f32 = (0..8)
                .map(|row| m[row][col] * m[row][col])
                .sum::<f32>()
                .sqrt();
            if norm > 1e-12 {
                for row in m.iter_mut() {
                    row[col] /= norm;
                }
            } else {
                // Degenerate — use identity basis vector
                m[col][col] = 1.0;
            }
        }

        Self {
            matrix: m,
            inverse_matrix: Self::transpose_matrix(&m),
        }
    }

    /// Test fixture: simple rotation table with a known non-trivial matrix.
    pub fn test_fixture() -> Self {
        // A simple 8×8 orthogonal-ish matrix for testing.
        // In production, derived from RoleEmbeddingTable via Cayley transform.
        // Block-diagonal with 2×2 rotation blocks
        let angle = 0.5f32;
        let c = angle.cos();
        let s = angle.sin();
        let mut m = [[0.0f32; 8]; 8];
        m[0][0] = c;
        m[0][1] = -s;
        m[1][0] = s;
        m[1][1] = c;
        m[2][2] = c;
        m[2][3] = -s;
        m[3][2] = s;
        m[3][3] = c;
        m[4][4] = c;
        m[4][5] = -s;
        m[5][4] = s;
        m[5][5] = c;
        m[6][6] = c;
        m[6][7] = -s;
        m[7][6] = s;
        m[7][7] = c;
        Self {
            matrix: m,
            inverse_matrix: Self::transpose_matrix(&m),
        }
    }
}

