impl LatCalEncoder {
    /// Create a new encoder with the given projection matrix.
    pub fn new(projection: Vec<[f32; 8]>, sparsity: f32) -> Self {
        Self {
            projection,
            sparsity,
        }
    }

    /// Encode a transaction into 8-dim latent space.
    ///
    /// `value` — the numeric value to encode (e.g., coin amount).
    /// `action` — action slot index.
    /// `target_id` — target entity identifier (contributes to hash-based mixing).
    #[inline]
    pub fn encode(&self, value: f32, action: u8, target_id: u64) -> [f32; 8] {
        let mut result = [0.0f32; 8];

        // Compute target mix once — shared between both branches.
        // BLAKE3 is used for collision resistance — a simpler hash would
        // be faster but could increase collision rate.
        let target_mix = blake3::hash(&target_id.to_le_bytes());
        // Zero-cost cast: [u8; 32] → [u32; 8] eliminates per-element
        // u32::from_le_bytes + try_into + unwrap overhead.
        let mix_u32: &[u32; 8] = bytemuck::cast_ref(target_mix.as_bytes());

        let idx = action as usize;
        if idx < self.projection.len() {
            let row = &self.projection[idx];

            // Single-pass: projection + perturbation + sparsity threshold computation.
            // Caches abs values to avoid recomputing in the masking loop.
            let mut abs_vals = [0.0f32; 8];
            let mut max_abs = 0.0f32;
            for i in 0..8 {
                let val = value * row[i] + mix_u32[i] as f32 * PERTURBATION_SCALE;
                let abs_val = val.abs();
                abs_vals[i] = abs_val;
                max_abs = max_abs.max(abs_val);
                result[i] = val;
            }

            // Branchless sparsity: multiply by 0.0 or 1.0 mask — no branch in inner loop.
            let threshold = self.sparsity * max_abs;
            for i in 0..8 {
                result[i] *= (abs_vals[i] >= threshold) as usize as f32;
            }
        } else {
            // No projection row: still mix target_id perturbation
            for i in 0..8 {
                result[i] = mix_u32[i] as f32 * PERTURBATION_SCALE;
            }
        }

        result
    }

    /// Create a test fixture encoder with a known projection matrix.
    #[cfg(test)]
    pub fn test_fixture() -> Self {
        let mut projection = Vec::with_capacity(MAX_PROJECTION_SLOTS);
        for slot in 0..MAX_PROJECTION_SLOTS {
            let mut row = [0.0f32; 8];
            // Use unique weights per slot so value × weight differs
            let base = 1.0 + (slot as f32) * 0.1;
            row[0] = base;
            row[1] = base * 0.5;
            row[2] = base * 0.25;
            projection.push(row);
        }
        // Use lower sparsity threshold so value signal survives
        Self::new(projection, 0.05)
    }
}

impl LatCalDecoder {
    /// Create a decoder with the inverse projection.
    pub fn new(inverse_projection: Vec<[f32; 8]>) -> Self {
        Self { inverse_projection }
    }

    /// Attempt to decode a latent vector back to an approximate value.
    /// This is a simplified decoder; production uses HLA context.
    #[inline]
    pub fn decode_value(&self, latent: &[f32; 8], action: u8) -> Option<f32> {
        let idx = action as usize;
        if idx >= self.inverse_projection.len() {
            return None;
        }
        let row = &self.inverse_projection[idx];
        let mut value = 0.0f32;
        for i in 0..8 {
            value += latent[i] * row[i];
        }
        Some(value)
    }
}

impl LatCalMatrix {
    /// Convert f32 matrix to fixed-point for consensus commit.
    ///
    /// Checks for NaN/Inf and returns error if float is not representable.
    /// Uses epsilon gate to detect accumulated drift from clean scale points.
    pub fn to_fixed(
        &self,
    ) -> Result<
        crate::encoding::latcal_fixed::LatCalFixed,
        crate::encoding::latcal_fixed::BridgeError,
    > {
        use crate::encoding::latcal_fixed::{LatCalFixed, snap_to_fixed};
        Ok(LatCalFixed {
            value: snap_to_fixed(self.value).map_err(|e| name_error(e, "value"))?,
            overflow: snap_to_fixed(self.overflow).map_err(|e| name_error(e, "overflow"))?,
            sign: snap_to_fixed(self.sign).map_err(|e| name_error(e, "sign"))?,
            precision: snap_to_fixed(self.precision).map_err(|e| name_error(e, "precision"))?,
        })
    }

    /// Convert fixed-point back to f32 for game runtime.
    pub fn from_fixed(fixed: &crate::encoding::latcal_fixed::LatCalFixed) -> Self {
        let (value, overflow, sign, precision) = fixed.to_f32();
        Self {
            value,
            overflow,
            sign,
            precision,
        }
    }
}

impl LatCalFixed {
    /// Identity matrix in fixed-point: `[[1,0],[0,1]]`.
    pub const IDENTITY: Self = Self {
        value: SCALE,
        overflow: 0,
        sign: 0,
        precision: SCALE,
    };

    /// Zero matrix in fixed-point: `[[0,0],[0,0]]`.
    pub const ZERO: Self = Self {
        value: 0,
        overflow: 0,
        sign: 0,
        precision: 0,
    };

    /// Determinant in fixed-point: `value * precision - overflow * sign`.
    ///
    /// Result is in (10^6)² = 10^12 scale — always exact, no rounding.
    /// This is bit-identical across all platforms (pure i128 arithmetic).
    #[inline]
    pub fn det(&self) -> i128 {
        (self.value as i128) * (self.precision as i128)
            - (self.overflow as i128) * (self.sign as i128)
    }

    /// Matrix addition in fixed-point. No precision loss — pure i64 arithmetic.
    #[inline]
    pub fn add(&self, other: &Self) -> Self {
        Self {
            value: self.value + other.value,
            overflow: self.overflow + other.overflow,
            sign: self.sign + other.sign,
            precision: self.precision + other.precision,
        }
    }

    /// Convert back to f32 by dividing each field by SCALE.
    #[inline]
    pub fn to_f32(&self) -> (f32, f32, f32, f32) {
        let s = SCALE as f32;
        (
            self.value as f32 / s,
            self.overflow as f32 / s,
            self.sign as f32 / s,
            self.precision as f32 / s,
        )
    }
}

impl LatCalSpectralFixed {
    /// Zero spectral coefficient.
    pub const ZERO: Self = Self {
        frequency: 0,
        amplitude: 0,
        phase: 0,
    };

    /// Energy invariant: `amplitude × phase` in (10^6)² = 10^12 scale.
    ///
    /// Bit-identical across all platforms (pure i128 arithmetic).
    /// This is the cross-platform determinism guarantee.
    #[inline]
    pub fn energy_invariant(&self) -> i128 {
        (self.amplitude as i128) * (self.phase as i128)
    }

    /// Pack `(amplitude, phase)` into a `LatCalFixed` matrix for det check.
    ///
    /// ```text
    /// [[amplitude, 0], [0, phase]]
    /// ```
    /// `det() = amplitude × phase` — same as `energy_invariant()` but via
    /// the existing `LatCalFixed` path.
    #[inline]
    pub fn to_latcal_fixed(&self) -> LatCalFixed {
        LatCalFixed {
            value: self.amplitude,
            overflow: 0,
            sign: 0,
            precision: self.phase,
        }
    }

    /// Convert back to f32: `(frequency, amplitude, phase)` divided by SCALE.
    #[inline]
    pub fn to_f32(&self) -> (f32, f32, f32) {
        let s = SCALE as f32;
        (
            self.frequency as f32 / s,
            self.amplitude as f32 / s,
            self.phase as f32 / s,
        )
    }
}

