/// Bytes reserved for a variant's encoded fields inside a [`CpiIxFrame`].
///
/// Sized by the widest variant (`MultisigCreate`, 258 bytes) and rounded up
/// to a multiple of 8 for a stable, alignment-friendly frame size.
pub const CPI_IX_PAYLOAD: usize = 264;

/// Number of `LatCalIx` variants this codec knows how to encode — a COUNT,
/// not a tag. The tag space is NOT dense: 0..=84 encodable, 85 the
/// non-encodable `CpiChain` hole, then the 096-T2 append 86..=88 and the
/// DomainRegistry append 94..=96. Derived from [`CPI_CODEC_TAGS`], never
/// hand-maintained — do not use it as a tag bound.
///
/// Since 096 T8 the game-domain variants are cfg-gated behind their
/// `chain_prog_*` features, so the count SHRINKS in builds without them —
/// derived from [`CPI_CODEC_TAGS`], never hand-maintained.
///
/// `LatCalIx::CpiChain` is excluded: it holds `Box<LatCalIx>`, and a nested
/// CPI chain is not dispatched by [`super::dispatch::dispatch`] anyway.
pub const CPI_ENCODABLE_VARIANTS: u8 = CPI_CODEC_TAGS.len() as u8;

