#[derive(Clone, Copy, Debug, bytemuck::Pod, bytemuck::Zeroable)]
pub struct CpiIxFrame {
    /// The `LatCalIx` variant discriminant — the same value [`ix_tag`] reads.
    pub ix_tag: u8,
    /// Explicit padding. Always zero;

