impl CpiAccountStore {
    /// Create an empty account store.
    pub fn new() -> Self {
        Self {
            accounts: papaya::HashMap::new(),
        }
    }

    /// Get a snapshot of an account by ID.
    ///
    /// Copies ~240 bytes out of the map. Correct when the caller needs to own
    /// the account (dispatch loads it, mutates it, writes it back); wasteful
    /// when the caller only reads a field or two — use [`Self::with`] there.
    pub fn get(&self, id: &[u8; 16]) -> Option<MatrixAccount> {
        self.accounts.pin().get(id).copied()
    }

    /// Read an account **in place**, without copying it out of the map.
    ///
    /// The delegation hot path reads four cells and a nonce out of a 240-byte
    /// account on every delegated transaction, and [`Self::get`] made it pay for
    /// all 240. The guard is held for the closure's duration — the same guard
    /// `get` takes and drops — so this is lock-free on the same terms, with the
    /// memcpy deleted rather than moved.
    ///
    /// The closure takes `Option<&MatrixAccount>` rather than the method
    /// returning `Option<&_>`: papaya's reference is tied to a guard that cannot
    /// outlive this frame, so the borrow has to end here. Returning `R` lets the
    /// caller extract whatever it actually needs — a scalar, a 16-byte id, a
    /// small enum — which is the shape every read-only caller has.
    #[inline]
    pub fn with<R>(&self, id: &[u8; 16], f: impl FnOnce(Option<&MatrixAccount>) -> R) -> R {
        f(self.accounts.pin().get(id))
    }

    /// Insert or replace an account.
    pub fn put(&self, id: [u8; 16], account: MatrixAccount) {
        self.accounts.pin().insert(id, account);
    }

    /// Remove an account.
    pub fn remove(&self, id: &[u8; 16]) -> Option<MatrixAccount> {
        self.accounts.pin().remove(id).copied()
    }

    /// Remove every account (Issue 079's recovery precedence).
    ///
    /// Recovery adopts the checkpoint's program-state set wholesale — the
    /// store wins over stale RAM exactly as `register_player` lets a
    /// persisted wallet win over a slot that holds one. That requires
    /// dropping whatever the in-memory tier holds before inserting the
    /// restored rows, or the restored set would be a UNION of checkpoint and
    /// RAM (and its `commitment_root` would disagree with the checkpoint's,
    /// which is precisely what the recompute-verify gate is there to catch).
    pub fn clear(&self) {
        self.accounts.pin().clear();
    }

    /// Number of accounts in the store.
    pub fn len(&self) -> usize {
        self.accounts.pin().len()
    }

    /// Is the store empty?
    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }

    /// Deterministic root over all account commitments (Issue 048 T2).
    ///
    /// Sorts accounts by their `[u8; 16]` key before folding, because
    /// `papaya` iteration order is not deterministic across runs or across
    /// nodes — the sort is the load-bearing detail that makes two stores
    /// with the same contents produce the same root regardless of insertion
    /// order.
    ///
    /// Each account is committed via [`MatrixAccount::commitment`] (BLAKE3
    /// over canonical bytes), then the per-account commitments are folded
    /// into a single root via a sequential BLAKE3 hash. This is a flat fold,
    /// not a Merkle tree — split-head detection only needs equality
    /// comparison, not O(log n) proof generation, so the Merkle structure
    /// would add machinery without adding capability.
    ///
    /// Returns `[0u8; 32]` for an empty store.
    ///
    /// # Cost — read this before calling it per transaction
    ///
    /// **O(N) BLAKE3 hashes + one allocation + an O(N log N) sort per call**,
    /// with N = every account in the store. `RsmCluster::submit_cpi` calls it
    /// once per replica on **every CPI transaction** (the Issue 049
    /// accept-divergent check), so the per-transaction cost of that check grows
    /// linearly with the size of program state: at N accounts and R replicas it
    /// is N × R hashes per transaction.
    ///
    /// That is fine at the N these suites run (single digits) and is a scaling
    /// limit, not a bug. The fix, when it is needed, is not to memoise this
    /// function — the store is mutated by the very transaction being checked, so
    /// a generation-keyed cache misses every time — but to maintain the root
    /// **incrementally** as a homomorphic multiset hash (add on insert, subtract
    /// on overwrite/remove), which makes a write O(1) and the root free. That
    /// changes the root's *value*, which is safe only because every consumer
    /// compares roots computed in-process by the same binary
    /// (`consensus::rsm`, `consensus::split_head`) rather than persisting or
    /// transmitting them — verify that is still true before doing it.
    pub fn commitment_root(&self) -> [u8; 32] {
        let guard = self.accounts.pin();
        if guard.is_empty() {
            return [0u8; 32];
        }
        // Collect (key, commitment) pairs deterministically.
        // Pre-allocate once — no per-element allocation in the fold.
        let mut entries: Vec<([u8; 16], [u8; 32])> =
            Vec::with_capacity(guard.len());
        for (key, acct) in guard.iter() {
            entries.push((*key, acct.commitment()));
        }
        // Deterministic order: sort by key. This is why the root is stable
        // regardless of papaya's internal iteration order.
        entries.sort_unstable_by_key(|a| a.0);
        // Flat BLAKE3 fold over the sorted commitments.
        let mut hasher = blake3::Hasher::new();
        for (_, commitment) in &entries {
            hasher.update(commitment);
        }
        *hasher.finalize().as_bytes()
    }

    /// Every account, sorted by ID — the deterministic snapshot view.
    ///
    /// Issue 079: `cold_commit` persists the whole store inside the checkpoint
    /// transaction, and the persisted set (plus the fold over it) must be a
    /// function of the store's *contents*, never of papaya's iteration order —
    /// the same load-bearing detail [`Self::commitment_root`]'s sort provides
    /// for the root. This is that sort, minus the hashing, for callers that
    /// need the pairs themselves.
    ///
    /// Cold path (one alloc + one copy per account); never call it per
    /// transaction.
    pub fn iter_sorted(&self) -> Vec<([u8; 16], MatrixAccount)> {
        let guard = self.accounts.pin();
        let mut entries: Vec<([u8; 16], MatrixAccount)> =
            Vec::with_capacity(guard.len());
        for (key, acct) in guard.iter() {
            entries.push((*key, *acct));
        }
        entries.sort_unstable_by_key(|(key, _)| *key);
        entries
    }
}

impl CpiMessage {
    /// Construct a CPI message with the given instruction + account refs.
    pub fn new(ix: LatCalIx, account_ids: &[[u8; 16]]) -> Self {
        let count = account_ids.len().min(MAX_CPI_ACCOUNT_REFS);
        let mut ids = [[0u8; 16]; MAX_CPI_ACCOUNT_REFS];
        ids[..count].copy_from_slice(&account_ids[..count]);
        Self {
            ix,
            account_ids: ids,
            account_count: count as u8,
        }
    }
}

impl ProgramError {
    /// The explicit `#[repr(u8)]` discriminant — a wire-stable error code.
    ///
    /// Used to carry a program failure back to a client through
    /// `TxRejection::CpiFailed`, whose payload has to be plain integers (the
    /// receipt frame is `Pod`, and `InsufficientBalance`'s `f32`s have no place
    /// in it).
    ///
    /// Read from the representation rather than written out as a 25-arm match:
    /// the `= N` values in the declaration are the source of truth, and a
    /// hand-maintained second copy would be free to drift from them.
    #[inline]
    pub fn code(&self) -> u8 {
        // SAFETY: `ProgramError` is `#[repr(u8)]`, so the discriminant is the
        // first byte of the representation, and the value is always fully
        // initialized. Same technique as `dispatch::ix_tag`.
        unsafe { *(self as *const Self as *const u8) }
    }
}

impl AlphaKey {
    /// Generate from player identity and transaction intent.
    ///
    /// `player_uuid` — raw player UUID bytes.
    /// `action` — action slot index (0=deposit, 1=withdraw, ...).
    /// `delta_vector` — the 8-dim latent delta.
    /// `nonce` — transaction nonce for replay protection.
    #[inline]
    pub fn generate(player_uuid: &[u8], action: u8, delta_vector: &[i64; 8], nonce: u64) -> Self {
        // tx_hash = BLAKE3(action || delta_vector || nonce || player_uuid)
        let mut hasher = blake3::Hasher::new();
        hasher.update(&[action]);
        hasher.update(bytemuck::cast_slice(delta_vector));
        hasher.update(&nonce.to_le_bytes());
        hasher.update(player_uuid);
        let tx_hash = hasher.finalize();

        // α-seed = BLAKE3(tx_hash || "alpha" || player_uuid)
        let alpha_seed = {
            let mut h = blake3::Hasher::new();
            h.update(tx_hash.as_bytes());
            h.update(b"chain_alpha_v1");
            h.update(player_uuid);
            h.finalize()
        };

        // tx_commitment = BLAKE3(tx_hash) — hash of hash
        let tx_commitment = blake3::hash(tx_hash.as_bytes());

        Self {
            alpha_seed: *alpha_seed.as_bytes(),
            tx_commitment: *tx_commitment.as_bytes(),
        }
    }
}

impl BetaResolver {
    /// Create a new resolver with the server's master secret.
    #[inline]
    pub fn new(master_secret: &[u8; 32]) -> Self {
        Self {
            master_secret: *master_secret,
        }
    }

    /// Resolve β-seed from tx_hash + server master secret.
    ///
    /// The server stores a map of tx_commitment → tx_hash
    /// (commitment is sent by client, server looks up the preimage).
    #[inline]
    pub fn resolve(&self, tx_hash: &[u8; 32]) -> [u8; 32] {
        let mut h = blake3::Hasher::new();
        h.update(tx_hash);
        h.update(b"chain_beta_v1");
        h.update(&self.master_secret[..]);
        *h.finalize().as_bytes()
    }

    /// Combine α and β to produce the cipher seed.
    ///
    /// Only computable with both halves. Used to initialize TxCipher.
    ///
    /// Delegates to `katgpt_device_verify::fair_roll::combine_seed` — the same
    /// function a `Satellite` runs to re-derive the seed itself. A device that
    /// accepted a node-supplied combined seed would let the node pick any seed
    /// it liked, which makes the commit-reveal decorative; so the device
    /// recomputes, and it must recompute *this*.
    #[inline]
    pub fn combine(alpha: &[u8; 32], beta: &[u8; 32]) -> [u8; 32] {
        katgpt_device_verify::fair_roll::combine_seed(alpha, beta)
    }
}

impl FairRng {
    /// Create a `FairRng` from split-key halves.
    ///
    /// This is the commit-reveal: α was committed by the player,
    /// β was resolved by the server from its master secret.
    /// Neither party controls the combined outcome.
    #[inline]
    pub fn from_split_key(
        alpha: &AlphaKey,
        beta_resolver: &BetaResolver,
        tx_hash: &[u8; 32],
    ) -> Self {
        let beta = beta_resolver.resolve(tx_hash);
        let combined = BetaResolver::combine(&alpha.alpha_seed, &beta);
        Self {
            combined_seed: combined,
        }
    }

    /// Create from already-combined seed (for replay/verification).
    #[inline]
    pub fn from_combined_seed(combined_seed: [u8; 32]) -> Self {
        Self { combined_seed }
    }

    /// The shared `no_std` verifier over this seed.
    ///
    /// Every roll goes through here. `FairRollVerifier` is a `[u8; 32]` and
    /// nothing else, so constructing one per call is a copy, not an
    /// allocation — the indirection costs nothing and buys the single-
    /// implementation guarantee.
    #[inline]
    fn verifier(&self) -> katgpt_device_verify::fair_roll::FairRollVerifier {
        katgpt_device_verify::fair_roll::FairRollVerifier::from_combined_seed(self.combined_seed)
    }

    /// Provably fair roll in `[0, 1)` from combined seed.
    ///
    /// Deterministic. Auditable. Neither party controls this alone.
    #[inline]
    pub fn roll(&self) -> f32 {
        self.verifier().roll_unit()
    }

    /// Roll a single die with `sides` faces. Returns `1..=sides`.
    ///
    /// Delegates to the shared `no_std` verifier so this node and a
    /// `Satellite` cannot disagree. See the type-level note on [`FairRng`].
    ///
    /// # Exact uniformity (v2 — Issue 108 resolved 2026-08-24)
    ///
    /// Every draw is rejection-tested: the first hash byte below
    /// `threshold = sides * (256 / sides)` decides the roll
    /// (`byte % sides + 1`); a byte at or above the threshold rejects and
    /// the next is drawn (on full-hash exhaustion, ≤ ~2e-10, the keystream
    /// chains by hashing the hash). An accepted byte is uniform over a
    /// whole number of `sides`-blocks, so the reduction is exact and every
    /// face is reachable.
    ///
    /// v1 tested only the first byte and used the second unconditionally on
    /// rejection — the residual bias Issue 108 tracked. v2 (owner call,
    /// before the daily-claim loop shipped against real value) changed
    /// outcomes only for seeds whose first *two* bytes both reject; the
    /// fixture labels carry `v2` so the seams cannot be confused.
    /// [`Self::roll_dice`] draws from a different byte stream (keyed XOF)
    /// but is uniform by the same per-byte rejection rule.
    ///
    /// # Panics
    ///
    /// If `sides == 0`. Use
    /// `katgpt_device_verify::fair_roll::FairRollVerifier::checked_roll_die`
    /// on any path where `sides` is attacker-influenced.
    #[inline]
    pub fn roll_die(&self, sides: u8) -> u8 {
        self.verifier().roll_die(sides)
    }

    /// Roll `count` dice with `sides` faces using XOF keystream.
    ///
    /// Delegates to the shared verifier. Like [`Self::roll_die`] (v2) this
    /// path rejection-tests **every** byte, so both functions are exactly
    /// uniform; they remain different distributions because they draw from
    /// different byte streams — this one a keyed XOF keystream, `roll_die`
    /// the plain hash bytes chained on exhaustion.
    ///
    /// # Panics
    ///
    /// If `sides == 0`.
    #[inline]
    pub fn roll_dice(&self, sides: u8, count: usize) -> Vec<u8> {
        self.verifier().roll_dice(sides, count)
    }

    /// Expose the combined seed for verification/replay.
    #[inline]
    pub fn combined_seed(&self) -> &[u8; 32] {
        &self.combined_seed
    }
}

impl AlphaKey {
    /// Derive `[f32; 64]` spectral initialization weights from this alpha seed.
    ///
    /// Uses BLAKE3 XOF to expand the 32-byte alpha_seed into 64 f32 values,
    /// then normalizes to unit sphere (L2 norm = 1).
    ///
    /// Different `alpha_seed` → different weights (lottery ticket diversification).
    /// Same `alpha_seed` → same weights (deterministic).
    ///
    /// Used by `ShardQuorum::spectral_diversification()` to measure how
    /// well-distributed a node ensemble is in spectral space.
    #[inline]
    pub fn spectral_init_weights(&self) -> [f32; 64] {
        const STYLE_DIM: usize = 64;

        let mut hasher = blake3::Hasher::new();
        hasher.update(&self.alpha_seed);
        hasher.update(b"alpha_spectral_v1");
        let mut xof = hasher.finalize_xof();

        // Batched XOF fill: pull all 256 bytes (64 × 4) in one call instead of
        // 64 separate 4-byte fills. Matches the pattern in cipher.rs and shell.rs.
        // Bit-output identical — the XOF reader produces the same byte stream.
        let mut entropy = [0u8; 256];
        xof.fill(&mut entropy);
        let bits_arr: &[u32; 64] = bytemuck::cast_ref(&entropy);
        let inv_half_max = 1.0 / (u32::MAX as f32 * 0.5);

        let mut weights = [0.0f32; STYLE_DIM];
        for (w, &bits) in weights.iter_mut().zip(bits_arr.iter()) {
            // Branch-free sign extraction: bit 0 → +1 (0) or -1 (1).
            let sign = 1.0f32 - 2.0 * (bits & 1) as f32;
            let magnitude = (bits >> 1) as f32 * inv_half_max;
            *w = sign * magnitude;
        }

        // Normalize to unit sphere — chunk-4 for SIMD auto-vectorization
        let mut norm_sq: f32 = 0.0;
        let mut i = 0;
        while i + 4 <= STYLE_DIM {
            norm_sq += weights[i] * weights[i]
                + weights[i + 1] * weights[i + 1]
                + weights[i + 2] * weights[i + 2]
                + weights[i + 3] * weights[i + 3];
            i += 4;
        }

        let inv_norm = 1.0 / norm_sq.sqrt().max(1e-8);
        i = 0;
        while i + 4 <= STYLE_DIM {
            weights[i] *= inv_norm;
            weights[i + 1] *= inv_norm;
            weights[i + 2] *= inv_norm;
            weights[i + 3] *= inv_norm;
            i += 4;
        }

        weights
    }
}

impl TxIntent {
    /// The absent intent — every plain transaction carries this.
    ///
    /// `is_none()` is the dedup gate's first branch: zero-intent transactions
    /// never consult the ring.
    pub const NONE: Self = Self([0u8; 8]);

    /// Wrap 8 raw bytes. Use [`Self::from_event`] to derive from an event id.
    pub const fn from_bytes(bytes: [u8; 8]) -> Self {
        Self(bytes)
    }

    /// Derive the intent for an external event: `BLAKE3(event)[..8]`.
    ///
    /// The truncation is what bounds the id to `_reserved[5..13]`; two
    /// deliveries of one event hash identically, so they agree on the id with
    /// no coordination between the gateway and the ledger.
    pub fn from_event(event: &[u8]) -> Self {
        let h = blake3::hash(event);
        let mut id = [0u8; 8];
        id.copy_from_slice(&h.as_bytes()[..8]);
        Self(id)
    }

    /// The absent intent (zero bytes).
    #[inline]
    pub fn is_none(&self) -> bool {
        self.0 == [0u8; 8]
    }

    /// The raw 8 bytes (matches `TxDelta::_reserved[5..13]` exactly).
    #[inline]
    pub const fn as_bytes(&self) -> [u8; 8] {
        self.0
    }

    /// The ring-comparison key — little-endian `u64` view of the bytes.
    ///
    /// Any fixed interpretation works (the ring compares by equality), but one
    /// canonical mapping keeps the ring representation stable across
    /// platforms and makes the eviction tests writable as integers.
    #[inline]
    pub const fn key(&self) -> u64 {
        u64::from_le_bytes(self.0)
    }
}

impl TxDelta {
    /// The external-event intent this transaction carries, if any.
    ///
    /// [`TxIntent::NONE`] when absent — the common case, and the value every
    /// pre-GH-#4 producer still emits.
    #[inline]
    pub fn intent(&self) -> TxIntent {
        TxIntent::from_bytes(
            self._reserved[5..13]
                .try_into()
                .expect("_reserved[5..13] is 8 bytes"),
        )
    }

    /// Stamp the intent. Callers must `recompute_checksum()` afterwards —
    /// `_reserved` is inside the hashed prefix (see the module docs for why no
    /// `TxSigningMessage` change accompanies this).
    #[inline]
    pub fn set_intent(&mut self, intent: TxIntent) {
        self._reserved[5..13].copy_from_slice(&intent.as_bytes());
    }
}

impl IntentRing {
    /// Distinct intents remembered per account.
    pub const CAP: usize = 64;

    /// An empty ring — what every fresh account starts with.
    pub const fn new() -> Self {
        Self {
            slots: [0u64; Self::CAP],
            head: 0,
            len: 0,
        }
    }

    /// Has this intent been accepted within the retention window?
    ///
    /// A linear scan of at most 64 `u64`s — the ring is small enough that the
    /// scan beats any indexed structure at this size, and stays allocation-free
    /// and branch-light on the hot path.
    #[inline]
    pub fn contains(&self, key: u64) -> bool {
        // Early-out on the empty ring keeps the common no-intent-history case
        // (fresh accounts, plain-tx accounts) a length check.
        self.len > 0 && self.slots[..self.len].contains(&key)
    }

    /// Record an accepted intent. FIFO-evicts the oldest when full.
    ///
    /// Inserting the same id twice is permitted (replay accepts history whose
    /// ring it is rebuilding) — it costs one slot, never correctness.
    #[inline]
    pub fn insert(&mut self, key: u64) {
        self.slots[self.head] = key;
        self.head = (self.head + 1) % Self::CAP;
        if self.len < Self::CAP {
            self.len += 1;
        }
    }

    /// Number of live slots (`<= CAP`).
    #[inline]
    pub fn len(&self) -> usize {
        self.len
    }

    /// The empty ring — the state a fresh account starts from.
    #[inline]
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// The live keys, **oldest first** — the order [`Self::insert`] would
    /// replay them in.
    ///
    /// ⚠️ Not `slots[..len]`. Once the ring has wrapped, `head` is the oldest
    /// live slot and the raw array is in no useful order; serialising it
    /// directly would make two rings holding the same intents compare
    /// different, and eviction order would be lost on restore.
    pub fn iter_oldest_first(&self) -> impl Iterator<Item = u64> + '_ {
        let start = if self.len < Self::CAP {
            0
        } else {
            self.head
        };
        (0..self.len).map(move |i| self.slots[(start + i) % Self::CAP])
    }

    /// Serialize for the checkpoint's `intent_ring` column.
    ///
    /// ⛔ **This is what lets boot stop reading the whole log.** Before Plan 033
    /// Phase 2 the ring lived only in the log, so rebuilding it required a full
    /// pass over every entry ever written — the ≈2.06 s boot floor at 10⁶
    /// entries, paid even when every entry was already checkpointed.
    ///
    /// Eight bytes per live key, oldest first, little-endian. No header: the
    /// blob's length gives the count, and a ring is at most
    /// `CAP * 8` = 512 bytes.
    pub fn to_bytes(&self) -> Vec<u8> {
        let mut out = Vec::with_capacity(self.len * 8);
        for key in self.iter_oldest_first() {
            out.extend_from_slice(&key.to_le_bytes());
        }
        out
    }

    /// Rebuild from [`Self::to_bytes`].
    ///
    /// ⚠️ Rebuilt by *replaying* the keys through `insert` rather than by
    /// restoring `slots`/`head`/`len` directly, so the reconstructed ring is
    /// reachable by ordinary use and its eviction order is the same one the
    /// original had.
    ///
    /// # Errors
    ///
    /// A blob that is not a whole number of keys, or that holds more than
    /// [`Self::CAP`] of them, is refused rather than truncated: it did not come
    /// from this code, and silently keeping 64 of 70 keys would drop exactly
    /// the intents a replay attack would want dropped.
    pub fn from_bytes(bytes: &[u8]) -> anyhow::Result<Self> {
        if !bytes.len().is_multiple_of(8) {
            anyhow::bail!(
                "intent ring blob is {} bytes, which is not a whole number of 8-byte \
                 keys. This did not come from IntentRing::to_bytes.",
                bytes.len()
            );
        }
        let n = bytes.len() / 8;
        if n > Self::CAP {
            anyhow::bail!(
                "intent ring blob holds {n} keys but the ring caps at {}. Truncating \
                 would silently forget the oldest intents, which is precisely what a \
                 duplicate-delivery attack needs.",
                Self::CAP
            );
        }
        let mut ring = Self::new();
        for chunk in bytes.chunks_exact(8) {
            let mut k = [0u8; 8];
            k.copy_from_slice(chunk);
            ring.insert(u64::from_le_bytes(k));
        }
        Ok(ring)
    }
}

impl NetworkId {
    /// No network stamped. Invalid in a transaction; rejected by any server
    /// configured for a real network.
    pub const UNSET: Self = Self(0);

    /// Local development — in-process RSM, single-node `riir-chaind --dev`.
    pub const LOCAL: Self = Self(1);
    /// Shared development network.
    pub const DEVNET: Self = Self(2);
    /// Pre-production network.
    pub const TESTNET: Self = Self(3);
    /// Production.
    pub const MAINNET: Self = Self(4);

    /// Server-side wildcard: accept any network id, including [`Self::UNSET`].
    ///
    /// **For tests and in-process embedding only.** Chosen as `u32::MAX` so it
    /// cannot collide with a real network, and deliberately not reachable from
    /// [`Self::from_name`] — an operator cannot configure it by typing a name.
    pub const ANY: Self = Self(u32::MAX);

    /// Parse a human-facing name (`--network devnet`).
    ///
    /// Returns `None` for anything unrecognised, including `"any"` and `"unset"`,
    /// so a typo cannot silently produce a permissive node.
    pub fn from_name(name: &str) -> Option<Self> {
        match name.trim().to_ascii_lowercase().as_str() {
            "local" => Some(Self::LOCAL),
            "devnet" => Some(Self::DEVNET),
            "testnet" => Some(Self::TESTNET),
            "mainnet" => Some(Self::MAINNET),
            _ => None,
        }
    }

    /// The canonical name, or `None` for a private id.
    pub const fn name(self) -> Option<&'static str> {
        match self {
            Self::UNSET => Some("unset"),
            Self::LOCAL => Some("local"),
            Self::DEVNET => Some("devnet"),
            Self::TESTNET => Some("testnet"),
            Self::MAINNET => Some("mainnet"),
            Self::ANY => Some("any"),
            _ => None,
        }
    }

    /// `true` if this is a usable value in a transaction — i.e. not a sentinel.
    #[inline]
    pub const fn is_concrete(self) -> bool {
        self.0 != Self::UNSET.0 && self.0 != Self::ANY.0
    }

    /// Does a server configured for `self` accept a transaction stamped `tx`?
    ///
    /// [`Self::ANY`] accepts everything. Otherwise the ids must match exactly —
    /// notably [`Self::UNSET`] is **not** accepted by a real network, which is
    /// what closes the replay hole.
    #[inline]
    pub const fn accepts(self, tx: NetworkId) -> bool {
        self.0 == Self::ANY.0 || self.0 == tx.0
    }
}

