impl TxDelta {
    /// Size of `TxDelta` in bytes (fixed, `repr(C)`).
    pub const SIZE: usize = std::mem::size_of::<Self>();

    /// Create a new transaction delta.
    #[inline]
    pub fn new(action_slot: u8, delta_vector: [i64; 8], nonce: u64) -> Self {
        Self {
            magic: TXDELTA_MAGIC,
            version: TXDELTA_FORMAT_VERSION,
            action_slot,
            _pad0: 0,
            delta_vector,
            target_hash: [0u8; 16],
            tx_commitment: [0u8; 32],
            alpha_key_hash: [0u8; 32],
            nonce,
            _reserved: [0u8; 16],
            gas_limit: 0,
            gas_price: 0,
            checksum: [0u8; 32],
        }
    }

    /// Recompute the BLAKE3 checksum over all preceding fields.
    #[inline]
    pub fn recompute_checksum(&mut self) {
        // SAFETY: TxDelta is repr(C) and dense — `_pad0` makes every byte in
        // the prefix before `checksum` belong to an explicitly-initialized
        // field. Self::SIZE - 32 covers exactly those fields.
        let self_bytes = unsafe {
            std::slice::from_raw_parts(self as *const Self as *const u8, Self::SIZE - 32)
        };
        let hash = blake3::hash(self_bytes);
        self.checksum.copy_from_slice(hash.as_bytes());
    }

    /// Verify checksum integrity.
    #[inline]
    pub fn verify_checksum(&self) -> bool {
        // SAFETY: Same dense-prefix rationale as recompute_checksum.
        let self_bytes = unsafe {
            std::slice::from_raw_parts(self as *const Self as *const u8, Self::SIZE - 32)
        };
        let expected = blake3::hash(self_bytes);
        self.checksum == *expected.as_bytes()
    }
}

