impl Account {
    fn new(rng: &mut Rng) -> Self {
        // 1 active lane 70%, 2 lanes 20%, 3 lanes 10%.
        let n_lanes = match rng.next_f64() {
            x if x < 0.70 => 1,
            x if x < 0.90 => 2,
            _ => 3,
        };
        // Distinct lane choices from 0..8.
        let mut lanes = [0usize; 3];
        lanes[0] = (rng.next_u64() as usize) % 8;
        for slot in 1..n_lanes {
            let mut l = (rng.next_u64() as usize) % 8;
            while lanes[..slot].contains(&l) {
                l = (l + 1) % 8;
            }
            lanes[slot] = l;
        }
        // Base amount log-uniform in [10^2.3, 10^5] minor units (200..100k).
        let log_base = 2.3 + (5.0 - 2.3) * rng.next_f64();
        let cv = 0.05 + 0.10 * rng.next_f64();
        // Drift: 0..4% growth across the whole stream.
        let drift = 0.40 * rng.next_f64() / N_TX as f64;
        Self {
            lanes,
            n_lanes,
            base: 10f64.powf(log_base),
            cv,
            drift,
        }
    }

    fn pick_lane(&self, rng: &mut Rng) -> usize {
        if self.n_lanes == 1 || rng.next_f64() < 0.85 {
            self.lanes[0]
        } else {
            self.lanes[1 + (rng.next_u64() as usize) % (self.n_lanes - 1)]
        }
    }

    /// Two lanes the account never uses (for the mixed-channel class).
    fn quiet_lanes(&self) -> (usize, usize) {
        let mut q1 = 0;
        while self.lanes[..self.n_lanes].contains(&q1) {
            q1 += 1;
        }
        let mut q2 = q1 + 1;
        while self.lanes[..self.n_lanes].contains(&q2) {
            q2 += 1;
        }
        (q1, q2)
    }
}

