const MAD_TO_SIGMA: f64 = 1.4826;

fn median(vals: &mut [f64]) -> f64 {
    if vals.is_empty() {
        return 0.0;
    }
    vals.sort_by(|a, b| a.total_cmp(b));
    let n = vals.len();
    if n % 2 == 1 {
        vals[n / 2]
    } else {
        (vals[n / 2 - 1] + vals[n / 2]) / 2.0
    }
}

impl MadFloor {
    pub fn fit(calib: &[TxFixture]) -> Self {
        let groups = by_account(calib);
        // Pooled fallback.
        let mut pooled: Vec<f64> = calib.iter().map(|f| norm(&f.delta)).collect();
        let pooled_med = median(&mut pooled);
        let mut devs: Vec<f64> = pooled.iter().map(|v| (v - pooled_med).abs()).collect();
        let pooled_scale = (MAD_TO_SIGMA * median(&mut devs)).max(1.0);

        let mut med = vec![pooled_med; N_ACCOUNTS];
        let mut scale = vec![pooled_scale; N_ACCOUNTS];
        for (a, g) in groups.iter().enumerate() {
            if g.len() >= 8 {
                let mut norms: Vec<f64> = g.iter().map(|f| norm(&f.delta)).collect();
                let m = median(&mut norms);
                let mut d: Vec<f64> = norms.iter().map(|v| (v - m).abs()).collect();
                let mad = median(&mut d);
                med[a] = m;
                scale[a] = (MAD_TO_SIGMA * mad).max(1.0);
            }
        }
        Self { med, scale }
    }

    pub fn score(&self, x: &[i64; 8], acct: usize) -> f64 {
        (norm(x) - self.med[acct]).abs() / self.scale[acct]
    }
}

impl MahaFloor {
    pub fn fit(calib: &[TxFixture]) -> Self {
        let groups = by_account(calib);
        let (pooled_mean, pooled_cov_inv) = Self::fit_one(
            &calib.iter().map(|f| &f.delta).collect::<Vec<_>>(),
        );
        let mut mean = Vec::with_capacity(N_ACCOUNTS);
        let mut cov_inv = Vec::with_capacity(N_ACCOUNTS);
        for g in &groups {
            if g.len() >= 16 {
                let (m, c) =
                    Self::fit_one(&g.iter().map(|f| &f.delta).collect::<Vec<_>>());
                mean.push(m);
                cov_inv.push(c);
            } else {
                mean.push(pooled_mean);
                cov_inv.push(pooled_cov_inv);
            }
        }
        Self { mean, cov_inv }
    }

    fn fit_one(calib: &[&[i64; 8]]) -> ([f64; 8], [[f64; 8]; 8]) {
        let identity = || {
            let mut m = [[0.0f64; 8]; 8];
            for (j, row) in m.iter_mut().enumerate() {
                row[j] = 1.0;
            }
            m
        };
        if calib.is_empty() {
            return ([0.0; 8], identity());
        }
        let n = calib.len() as f64;
        let mut mean = [0.0f64; 8];
        for x in calib {
            for j in 0..8 {
                mean[j] += x[j] as f64;
            }
        }
        for m in &mut mean {
            *m /= n;
        }
        let mut cov = [[0.0f64; 8]; 8];
        for x in calib {
            let d = [
                x[0] as f64 - mean[0],
                x[1] as f64 - mean[1],
                x[2] as f64 - mean[2],
                x[3] as f64 - mean[3],
                x[4] as f64 - mean[4],
                x[5] as f64 - mean[5],
                x[6] as f64 - mean[6],
                x[7] as f64 - mean[7],
            ];
            for r in 0..8 {
                for c in 0..8 {
                    cov[r][c] += d[r] * d[c] / n;
                }
            }
        }
        // Ridge: quiet lanes can be exactly constant across the calibration
        // set; without a ridge the matrix is singular.
        let trace: f64 = (0..8).map(|j| cov[j][j]).sum();
        let ridge = 1e-6 * (trace / 8.0 + 1.0);
        for (j, row) in cov.iter_mut().enumerate() {
            row[j] += ridge;
        }
        (mean, invert8(&cov).unwrap_or_else(identity))
    }

    pub fn score(&self, x: &[i64; 8], acct: usize) -> f64 {
        let mean = &self.mean[acct];
        let ci = &self.cov_inv[acct];
        let d = [
            x[0] as f64 - mean[0],
            x[1] as f64 - mean[1],
            x[2] as f64 - mean[2],
            x[3] as f64 - mean[3],
            x[4] as f64 - mean[4],
            x[5] as f64 - mean[5],
            x[6] as f64 - mean[6],
            x[7] as f64 - mean[7],
        ];
        let mut s = [0.0f64; 8];
        for r in 0..8 {
            let mut acc = 0.0;
            for c in 0..8 {
                acc += ci[r][c] * d[c];
            }
            s[r] = acc * d[r];
        }
        s.iter().sum()
    }
}

impl ConformalFloor {
    pub fn fit(calib_scores: &[f64], alpha: f64) -> Self {
        let mut s: Vec<f64> = calib_scores.iter().copied().filter(|v| v.is_finite()).collect();
        s.sort_by(|a, b| a.total_cmp(b));
        if s.is_empty() {
            Self { cutoff: f64::INFINITY }
        } else {
            let k = (((s.len() + 1) as f64 * (1.0 - alpha)).ceil() as usize)
                .saturating_sub(1)
                .min(s.len() - 1);
            Self { cutoff: s[k] }
        }
    }

    pub fn flags(&self, scores: &[f64]) -> Vec<bool> {
        scores.iter().map(|s| *s > self.cutoff).collect()
    }
}

enum INode {
    Internal {
        feature: usize,
        split: f64,
        left: Box<INode>,
        right: Box<INode>,
    },
    Leaf { size: usize },
}

impl IForest {
    pub fn fit(calib: &[TxFixture], n_trees: usize, psi: usize, seed: u64) -> Self {
        let mut rng = Rng::new(seed);
        let groups = by_account(calib);
        let mut trees = Vec::with_capacity(N_ACCOUNTS);
        for (a, g) in groups.iter().enumerate() {
            let mut forest = Vec::with_capacity(n_trees);
            if g.len() >= 32 {
                let psi_a = psi.min(g.len());
                let height_cap = (psi_a as f64).log2().ceil() as usize;
                let deltas: Vec<&[i64; 8]> = g.iter().map(|f| &f.delta).collect();
                for _ in 0..n_trees {
                    let idx: Vec<usize> =
                        (0..psi_a).map(|_| (rng.next_u64() as usize) % deltas.len()).collect();
                    forest.push(Self::build(&deltas, &idx, 0, height_cap, &mut rng));
                }
            }
            let _ = a;
            trees.push(forest);
        }
        Self { trees, psi }
    }

    fn build(calib: &[&[i64; 8]], idx: &[usize], depth: usize, cap: usize, rng: &mut Rng) -> INode {
        if idx.len() <= 1 || depth >= cap {
            return INode::Leaf { size: idx.len() };
        }
        let feature = (rng.next_u64() as usize) % 8;
        let mut lo = f64::INFINITY;
        let mut hi = f64::NEG_INFINITY;
        for &i in idx {
            let v = calib[i][feature] as f64;
            lo = lo.min(v);
            hi = hi.max(v);
        }
        if hi <= lo {
            return INode::Leaf { size: idx.len() };
        }
        let split = lo + rng.next_f64() * (hi - lo);
        let mut left = Vec::new();
        let mut right = Vec::new();
        for &i in idx {
            if (calib[i][feature] as f64) < split {
                left.push(i);
            } else {
                right.push(i);
            }
        }
        // Guard: a pathological split can leave one side empty.
        if left.is_empty() || right.is_empty() {
            return INode::Leaf { size: idx.len() };
        }
        INode::Internal {
            feature,
            split,
            left: Box::new(Self::build(calib, &left, depth + 1, cap, rng)),
            right: Box::new(Self::build(calib, &right, depth + 1, cap, rng)),
        }
    }

    fn path_length(node: &INode, x: &[i64; 8], depth: usize) -> f64 {
        match node {
            INode::Leaf { size } => depth as f64 + c_factor(*size),
            INode::Internal { feature, split, left, right } => {
                if (x[*feature] as f64) < *split {
                    Self::path_length(left, x, depth + 1)
                } else {
                    Self::path_length(right, x, depth + 1)
                }
            }
        }
    }

    /// Higher = more anomalous (standard `2^(−E[h]/c(ψ))`). Accounts with no
    /// fitted forest (too little calibration data) score 0 — never anomalous.
    pub fn score(&self, x: &[i64; 8], acct: usize) -> f64 {
        let forest = &self.trees[acct];
        if forest.is_empty() {
            return 0.0;
        }
        let h: f64 = forest
            .iter()
            .map(|t| Self::path_length(t, x, 0))
            .sum::<f64>()
            / forest.len() as f64;
        2f64.powf(-h / c_factor(self.psi).max(1e-12))
    }
}

