/// Deterministic splittable PRNG — xorshift32 over a rolling state.
///
/// We need a deterministic PRNG that produces the same sequence on every
/// architecture (no `StdRng`, no `rand` dep — those pull in potentially
/// arch-sensitive code). Xorshift32 over `u32` is bit-identical everywhere.
struct XorShift32 {
    state: u32,
}

impl XorShift32 {
    fn new(seed: u32) -> Self {
        // Xorshift32 requires non-zero state; fold seed to avoid the 0-state.
        Self {
