#[global_allocator]
static GLOBAL: CountingAllocator = CountingAllocator;

/// G4: `resolve_delegated_account` allocates **zero** bytes on a hit and on a
/// miss, in steady state.
///
/// Measured, not asserted from inspection: `CpiAccountStore::get` returns a
/// `MatrixAccount` **by copy** and `cert_from_cells` is stack-only, so the
/// budget is exactly zero. This is on the per-transaction write path — one
/// allocation here is one allocation per transaction on every node.
#[test]
fn g4_resolve_is_allocation_free_on_hit_and_miss() {
    let auth = Authority::new(0xAD);
    let hit_session = [0x5Cu8; 32];
    let miss_session = [0x6Du8; 32];
    let s = server_with(&cert(hit_session, auth.account(), 1, NETWORK.0));

    let hit = ResolveInput::game_delta(hit_session);
    let miss = ResolveInput::game_delta(miss_session);

    // Warm-up, and forces the thread-local's lazy init out of the window.
    let _ = alloc_count();
    for _ in 0..64 {
        let _ = hit.resolve(&s, LIVE_TICK);
        let _ = miss.resolve(&s, LIVE_TICK);
    }

    const ITERATIONS: u32 = 1_000;

    let before = alloc_count();
    for _ in 0..ITERATIONS {
        let r = hit.resolve(&s, LIVE_TICK);
        std::hint::black_box(&r);
    }
    let hit_allocs = alloc_count() - before;

    let before = alloc_count();
    for _ in 0..ITERATIONS {
        let r = miss.resolve(&s, LIVE_TICK);
        std::hint::black_box(&r);
    }
    let miss_allocs = alloc_count() - before;

    assert_eq!(
        hit_allocs, 0,
        "G4 FAIL: {hit_allocs} allocations over {ITERATIONS} delegation HITS — \
         CpiAccountStore::get returns MatrixAccount by copy and cert_from_cells \
         is stack-only, so the budget is exactly zero"
    );
    assert_eq!(
        miss_allocs, 0,
        "G4 FAIL: {miss_allocs} allocations over {ITERATIONS} delegation MISSES"
    );
}

