impl Action {
    fn sample(x: &mut Xof) -> Self {
        match x.below(5) {
            0 => Action::Mint(x.amount()),
            1 => Action::Burn(x.amount()),
            2 => Action::Transfer(x.amount()),
            3 => Action::Stake(x.amount()),
            _ => {
                let from = x.below(8);
                let mut to = x.below(8);
                if to == from {
                    to = (to + 1) % 8;
                }
                Action::Swap(from, to, x.amount())
            }
        }
    }

    /// The action code and the delta this action submits.
    fn encode(self) -> (u8, [i64; 8]) {
        let mut d = [0i64; 8];
        match self {
            Action::Mint(a) => {
                d[0] = a;
                (settlement::WALLET_BRIDGE_LOCK, d)
            }
            Action::Burn(a) => {
                d[0] = -a;
                (settlement::WALLET_BRIDGE_THAW, d)
            }
            Action::Transfer(a) => {
                d[0] = -a;
                (settlement::WALLET_TRANSFER, d)
            }
            Action::Stake(a) => {
                d[0] = -a;
                (settlement::WALLET_STAKE, d)
            }
            Action::Swap(from, to, a) => {
                d[usize::from(from)] = -a;
                d[usize::from(to)] = a;
                (settlement::WALLET_SWAP, d)
            }
        }
    }

    fn is_transfer(self) -> bool {
        matches!(self, Action::Transfer(_))
    }

    /// Is this the action Plan 030 D12 denies outright?
    fn is_mint(self) -> bool {
        matches!(self, Action::Mint(_))
    }
}

impl Book {
    fn new() -> Self {
        Book([[0; 8]; 2])
    }

    /// Apply what the transaction was supposed to do.
    fn apply(&mut self, sender: usize, delta: &[i64; 8], transfer_to: Option<usize>) {
        for (slot, d) in self.0[sender].iter_mut().zip(delta.iter()) {
            *slot += i128::from(*d);
        }
        if let Some(r) = transfer_to {
            // The credit is the exact negation, per `settlement::credit_for`.
            for (slot, d) in self.0[r].iter_mut().zip(delta.iter()) {
                *slot -= i128::from(*d);
            }
        }
    }

    /// Record an opening balance — value that entered without a transaction
    /// (Plan 030 T4's genesis primitive), so there is no sender to debit and no
    /// counterparty to credit.
    fn credit(&mut self, account: usize, opening: &[i64; 8]) {
        for (slot, d) in self.0[account].iter_mut().zip(opening.iter()) {
            *slot += i128::from(*d);
        }
    }

    fn total(&self) -> i128 {
        self.0.iter().flat_map(|a| a.iter()).sum()
    }
}

impl Rng {
    fn next_i64(&mut self) -> i64 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        // Map into a wide range of both signs, avoiding i64::MIN (whose
        // negation overflows and would be rejected by try_apply_delta).
        let v = self.0 as i64;
        if v == i64::MIN { 0 } else { v }
    }

    fn next_delta(&mut self) -> [i64; 8] {
        let mut d = [0i64; 8];
        for slot in d.iter_mut() {
            *slot = self.next_i64();
        }
        d
    }
}

fn total(world: &([i64; 8], [i64; 8])) -> i128 {
    world.0.iter().map(|v| *v as i128).sum::<i128>()
        + world.1.iter().map(|v| *v as i128).sum::<i128>()
}

