impl WalletBackend {
    /// Errors: `token_idx >= TOKEN_LANES` (the wallet's delta width).
    pub fn new(token_idx: u8) -> Result<Self, DappError> {
        if token_idx >= TOKEN_LANES {
            return Err(DappError::Unencodable {
                backend: "wallet",
                reason: "token_idx out of range — the wallet's delta_vector \
                         has 8 lanes (0..8); pick the lane this deployment's \
                         currency lives in",
            });
        }
        Ok(Self { token_idx })
    }

    /// The lane this backend pays from.
    #[inline]
    pub const fn token_idx(&self) -> u8 {
        self.token_idx
    }
}

impl SettlementBackend for WalletBackend {
    type Encoded = WalletOp;

    fn name(&self) -> &'static str {
        "wallet"
    }

    fn encode(&self, settlement: &Settlement) -> Result<Vec<WalletOp>, DappError> {
        match settlement {
            // Not an error: most outcomes settle nothing.
            Settlement::None => Ok(Vec::new()),

            Settlement::Transfer { to, amount } => {
                // `validate()` catches this too; re-checked here for callers
                // that encode without validating (the escrow backend does
                // the same for its amounts).
                if *amount <= 0 {
                    return Err(DappError::NonPositiveReward(*amount));
                }
                // Lossless by construction: every positive i64 fits u64.
                Ok(vec![WalletOp::Transfer {
                    to: *to,
                    token_idx: self.token_idx,
                    amount_minor: *amount as u64,
                }])
            }

            // The escrow family is a CPI program call, not a wallet op.
            Settlement::EscrowOpen { .. }
            | Settlement::EscrowClaim { .. }
            | Settlement::EscrowExpire { .. } => Err(DappError::Unencodable {
                backend: "wallet",
                reason: "escrow settlements are CPI program calls, not wallet \
                         ops — encode them with backend::MultiClaimEscrowBackend \
                         (feature `chain_backend`)",
            }),

            // Token supply ops are program calls on registered mints.
            Settlement::TokenRegister { .. }
            | Settlement::TokenMint { .. }
            | Settlement::TokenBurn { .. } => Err(DappError::Unencodable {
                backend: "wallet",
                reason: "token-registry settlements are TokenRegistry program \
                         CPIs — encode them with backend::TokenRegistryBackend \
                         (feature `chain_backend`)",
            }),
        }
    }
}

