    /// the total can at least detect the shortfall.
    ///
    /// `None` also covers every non-currency contract — a FAME bounty funds
    /// no pool at all, which is the point.
    #[inline]
    pub fn total(&self) -> Option<MicroUnits> {
        self.reward
            .currency()?
            .checked_mul(i64::from(self.claims.get()))
    }
}

