/// The cadence this module's one **settling** event runs at (Plan 002):
/// paying a vendor. A chain-priced craft fee is a rare paid branch drained
/// in the background — Glacial. The craft itself settles nothing at any
/// cadence (`Stakes::Local` is fully local; `Stakes::Contested` asks for a
/// [`ChainService::FairRoll`], a service, not a settlement).
pub const CADENCE: Cadence = Cadence::Glacial;

/// How much the roll can be manipulated, which decides where it happens.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Stakes {
    /// Single-player, untradeable, cosmetic. Roll locally.
    ///
    /// Paying consensus latency for this is the mirror-image of the Issue 096
    /// mistake: not game logic in the ledger, but ledger cost in game logic.
    Local,
    /// PvP, tradeable output, or anything a player profits from steering.
    Contested,
}

/// A craft attempt as the game layer describes it.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Attempt {
    /// Recipe identity — game-layer content id. Never leaves the game layer
    /// except as part of a commitment.
    pub recipe_token: Vec<u8>,
    pub crafter: AccountId,
    pub stakes: Stakes,
}

/// Resolve a craft attempt.
///
/// Returns [`Composed::local`] for [`Stakes::Local`] — no chain contact of any
/// kind. For [`Stakes::Contested`], still **no settlement**: one
/// [`ChainService::FairRoll`] and nothing else. Crafting never settles here
/// because consuming materials and granting an item are inventory writes, and
/// inventory is game/store state.
pub fn attempt(a: &Attempt) -> Composed {
    match a.stakes {
        Stakes::Local => Composed::local(),
        Stakes::Contested => {
            let commitment = PredicateHash::commit(DOMAIN, &a.recipe_token);
            Composed::local().with_service(ChainService::FairRoll {
                commitment: *commitment.as_bytes(),
            })
        }
    }

impl Epoch {
    /// Derive the claim window from the chain's own block height.
    ///
    /// `blocks_per_epoch` is a chain parameter, not a request field. Zero is
    /// refused rather than divided by: on the node a panic is an outage, and
    /// a misconfigured constant should not take the claim path down.
    #[inline]
    pub const fn from_chain_height(height: u64, blocks_per_epoch: u64) -> Option<Self> {
        match blocks_per_epoch {
            0 => None,
            n => Some(Self(height / n)),
        }
    }

    /// The window index. Read-only — there is no inverse.
    #[inline]
    pub const fn get(self) -> u64 {
        self.0
    }
}

impl ClaimRequest {
    /// A well-formed request: authenticated account + commitment, no clocks.
    #[inline]
    pub fn new(account: AccountId, alpha_commitment: [u8; 32]) -> Self {
        Self { account, alpha_commitment, ..Self::default() }
    }

    /// Refuse the request if it carries any client-supplied time or key.
    ///
    /// Returns the offending field name in the error so an integrator sees
    /// *which* field they must stop sending — a bare "rejected" teaches
    /// nothing and gets retried.
    pub fn validate(&self) -> Result<(), DappError> {
        let offender = match self {
            Self { client_epoch: Some(_), .. } => Some("client_epoch"),
            Self { client_unix_time: Some(_), .. } => Some("client_unix_time"),
            Self { client_discriminator: Some(_), .. } => Some("client_discriminator"),
            _ => None,
        };
        match offender {
            Some(field) => Err(DappError::ClientSuppliedTime { field }),
            None => Ok(()),
        }
    }
}

