/// Unchanged from the retired chain-side encoder (`item_stats_bytes_into`):
/// a pre-migration GM signature and a post-migration commitment hash the same
/// stat block to the same bytes, so the migration is not also a silent
/// content change.
pub const ITEM_STATS_BYTES: usize = 60;

/// Raw stat block — **game-defined** (attack, defense, …).
///
/// Fixed layout so the canonical encoding is stable across platforms; the
/// commitment in [`CatalogEntry::binding`] is taken over exactly these bytes.
#[repr(C)]
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct ItemStats {
    /// Required player level to equip.
    pub required_level: u16,
    /// Rarity tier (0=common, 1=uncommon, 2=rare, 3=epic, 4=legendary).
    pub rarity: u8,
    /// Eight raw stat lanes — attack, defense, and whatever else the game
    /// assigns. This crate never interprets them.
    pub stats: [f32;

impl ItemStats {
    /// Canonical byte encoding (60 B), bit-identical to the retired chain
    /// encoder.
    ///
    /// ```text
    /// offset  field           size  encoding
    /// 0       required_level   2    LE u16
    /// 2       rarity           1    u8
    /// 3       (padding)        1    zero — aligns the f32 block to 4 bytes
    /// 4       stats           32    [f32; 8] each LE
    /// 36      bbox_min        12    [f32; 3] each LE
    /// 48      bbox_max        12    [f32; 3] each LE
    /// ```
    #[inline]
    pub fn canonical_bytes(&self) -> [u8; ITEM_STATS_BYTES] {
        let mut out = [0u8; ITEM_STATS_BYTES];
        out[0..2].copy_from_slice(&self.required_level.to_le_bytes());
        out[2] = self.rarity;
        out[3] = 0;
        let mut off = 4;
        for &v in self.stats.iter().chain(&self.bbox_min).chain(&self.bbox_max) {
            out[off..off + 4].copy_from_slice(&v.to_le_bytes());
            off += 4;
        }
        debug_assert_eq!(off, ITEM_STATS_BYTES);
        out
    }
}

impl Price {
    /// The amount, if this price is payable on-chain.
    #[inline]
    pub const fn chain_amount(&self) -> Option<MicroUnits> {
        match self {
            Self::Chain(a) => Some(*a),
            Self::Game(_) => None,
        }
    }

    /// Canonical 9-byte encoding: a 1-byte arm discriminant then the LE
    /// amount. The discriminant is inside the commitment so a game-gold price
    /// and a chain price of the same magnitude are different entries.
    #[inline]
    pub fn canonical_bytes(&self) -> [u8; 9] {
        let mut out = [0u8; 9];
        let (tag, amount) = match self {
            Self::Game(a) => (0u8, *a),
            Self::Chain(a) => (1u8, *a),
        };
        out[0] = tag;
        out[1..9].copy_from_slice(&amount.to_le_bytes());
        out
    }
}

impl CatalogEntry {
    /// The 32-byte opaque commitment the chain stores and the GM signs.
    ///
    /// Domain-separated and length-prefixed the same way
    /// [`crate::types::PredicateHash::commit`] is, for the same reason: two
    /// game systems must not be able to collide by accident.
    #[inline]
    pub fn binding(&self) -> [u8; 32] {
        let mut h = blake3::Hasher::new();
        h.update(b"riir-dapps-item-catalog-v1");
        h.update(&(DOMAIN.len() as u64).to_le_bytes());
        h.update(DOMAIN.as_bytes());
        h.update(&self.item_id.to_le_bytes());
        h.update(&self.asset_blob_id);
        h.update(&self.stats.canonical_bytes());
        h.update(&self.price.canonical_bytes());
        *h.finalize().as_bytes()
    }

    /// Does `binding` commit to this entry?
    ///
    /// The game-side mirror of the chain's GM-signature check: refuse a
    /// promotion whose commitment does not match the row about to be
    /// published, before paying for a round trip.
    #[inline]
    pub fn matches_binding(&self, binding: &[u8; 32]) -> bool {
        self.binding() == *binding
    }
}

impl ReleaseStage {
    /// Decode a chain-reported discriminant. `None` for an unknown value —
    /// an unrecognised stage must not silently read as `Live`.
    #[inline]
    pub const fn from_u8(v: u8) -> Option<Self> {
        match v {
            0 => Some(Self::Draft),
            1 => Some(Self::Candidate),
            2 => Some(Self::Live),
            3 => Some(Self::Retired),
            _ => None,
        }
    }

    /// Is the item for sale at this stage?
    ///
    /// `Live` and only `Live` — the exact predicate the retired
    /// `apply_promotion` step 3d used (`shop_visible = to_status == Live`),
    /// preserved so the migration changes where the rule lives and not what
    /// it decides.
    #[inline]
    pub const fn is_shop_visible(self) -> bool {
        matches!(self, Self::Live)
    }
}

impl ShopSlot {
    /// The slot a promotion to `stage` produces at `tick`.
    #[inline]
    pub const fn for_stage(item_id: ItemId, stage: ReleaseStage, tick: u64) -> Self {
        Self { item_id, visible: stage.is_shop_visible(), last_flipped_at_tick: tick }
    }
}

impl EquipSlotBounds {
    /// "Anything fits" — for an item id with no registered slot.
    pub const fn permissive() -> Self {
        Self {
            bbox_min_floor: [f32::NEG_INFINITY; 3],
            bbox_min_ceil: [f32::INFINITY; 3],
            bbox_max_floor: [f32::NEG_INFINITY; 3],
            bbox_max_ceil: [f32::INFINITY; 3],
        }
    }

    /// A centered cubic bound of half-extent `r`: `bbox_min ∈ [-r, 0]` and
    /// `bbox_max ∈ [0, r]` per axis.
    pub const fn centered_cube(r: f32) -> Self {
        Self {
            bbox_min_floor: [-r; 3],
            bbox_min_ceil: [0.0; 3],
            bbox_max_floor: [0.0; 3],
            bbox_max_ceil: [r; 3],
        }
    }

    /// Does this bbox fit the slot, and is the box non-inverted?
    #[inline]
    pub fn fits(&self, bbox_min: &[f32; 3], bbox_max: &[f32; 3]) -> bool {
        for axis in 0..3 {
            if bbox_min[axis] < self.bbox_min_floor[axis]
                || bbox_min[axis] > self.bbox_min_ceil[axis]
            {
                return false;
            }
            if bbox_max[axis] < self.bbox_max_floor[axis]
                || bbox_max[axis] > self.bbox_max_ceil[axis]
            {
                return false;
            }
            if bbox_max[axis] < bbox_min[axis] {
                return false;
            }
        }
        true
    }

    /// Does `entry`'s stat block fit this slot?
    #[inline]
    pub fn admits(&self, entry: &CatalogEntry) -> bool {
        self.fits(&entry.stats.bbox_min, &entry.stats.bbox_max)
    }
}

