/// Sentinel for "no chain error has been recorded" — the submitter either
/// never ran or has never failed. `u32::MAX` ms ≈ 49.7 days;

impl TierHealthSnapshot {
    /// Classify into the §4 alert names. Flags are authoritative when set
    /// (they are facts); the counter thresholds are the fallback when only
    /// counters are available (e.g. a snapshot relayed without flags).
    ///
    /// The table, row by row:
    ///
    /// | flags / counters | verdict |
    /// |---|---|
    /// | warm failing **and** chain failing (either source) | [`TierAlert::TierBlackout`] (row 3) |
    /// | warm failing alone (flag, or `wal_lag_ms > WARM_LAG_ALERT_MS`) | [`TierAlert::WarmDown`] (row 1) |
    /// | chain failing alone (flag, or error age ≤ `CHAIN_ERROR_RECENT_MS`) | [`TierAlert::ChainUnreachable`] (row 2) |
    /// | neither | [`TierAlert::Ok`] |
    #[must_use]
    pub fn classify(&self) -> TierAlert {
        let warm_flag = self.flags & tier_flag::WARM_FLUSH_FAILING != 0;
        let chain_flag = self.flags & tier_flag::CHAIN_UNREACHABLE != 0;
        let warm_counter = self.wal_lag_ms > WARM_LAG_ALERT_MS;
        let chain_counter = self.chain_last_error_age_ms != CHAIN_ERROR_NONE_MS
            && self.chain_last_error_age_ms <= CHAIN_ERROR_RECENT_MS;
        let warm = warm_flag || warm_counter;
        let chain = chain_flag || chain_counter;
        match (warm, chain) {
            (true, true) => TierAlert::TierBlackout,
            (true, false) => TierAlert::WarmDown,
            (false, true) => TierAlert::ChainUnreachable,
            (false, false) => TierAlert::Ok,
        }
    }

    /// Rows needing human eyes right now: manual holds or poison.
    #[must_use]
    pub fn needs_attention(&self) -> bool {
        self.flags & (tier_flag::MANUAL_HOLDS_PRESENT | tier_flag::POISONED_ROWS_PRESENT) != 0
    }
}

impl TierAlert {
    /// The proposal's alert string (the GM alert name).
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            TierAlert::Ok => "OK",
            TierAlert::WarmDown => "WARM_DOWN",
            TierAlert::ChainUnreachable => "CHAIN_UNREACHABLE",
            TierAlert::TierBlackout => "TIER_BLACKOUT",
        }
    }
}

