/// `BLAKE3(domain ‖ ":" ‖ name)[..16]` — the same derivation
/// `riir_chain_sdk::derive_account_id` uses, reproduced so the game layer can
/// name accounts without linking the ledger.
///
/// Pinned against the SDK by `tests/escrow_backend.rs::
/// account_derivation_agrees_with_the_sdk`, which is not ceremony: this
/// function was written from the SDK's *doc comment*, which says
/// `BLAKE3(domain ‖ name)[..16]` and omits the `":"` separator its code
/// actually writes. The test caught it on the first run. Every account a game
/// server named would otherwise have been a different account than the chain
/// used — silently, with matching types.
#[inline]
pub fn derive_account_id(domain: &str, name: &[u8]) -> AccountId {
    let mut h = blake3::Hasher::new();

impl IntentId {
    /// Derive the id. `discriminator` MUST be unique per logical intent —
    /// see the module doc; derive it from the game event, not from the
    /// settlement.
    pub fn of(settlement: &Settlement, discriminator: &[u8]) -> Self {
        let mut h = blake3::Hasher::new();
        h.update(b"riir-dapps-intent-v1");
        h.update(&(discriminator.len() as u64).to_le_bytes());
        h.update(discriminator);
        let mut canon = Vec::with_capacity(96);
        write_settlement(settlement, &mut canon);
        h.update(&canon);
        Self(*h.finalize().as_bytes())
    }

    #[inline]
    pub const fn from_bytes(bytes: [u8; 32]) -> Self {
        Self(bytes)
    }

    #[inline]
    pub const fn as_bytes(&self) -> &[u8; 32] {
        &self.0
    }

    /// Lowercase hex (64 chars) — the `<id>` in `pending_settlement:<id>`.
    pub fn to_hex(self) -> [u8; 64] {
        let mut out = [0u8; 64];
        const HEX: &[u8; 16] = b"0123456789abcdef";
        for (i, b) in self.0.iter().enumerate() {
            out[i * 2] = HEX[(b >> 4) as usize];
            out[i * 2 + 1] = HEX[(b & 0x0f) as usize];
        }
        out
    }
}

impl RetrySafety {
    /// Classify a settlement. `target_claims` is the **escrow's** claim
    /// count for a claim (`claims = 1` is the common quest case) — the claim
    /// itself cannot know it; composers do, because they opened the escrow.
    /// `None` (unknown) is conservatively [`NeedsReceipt`].
    #[must_use]
    pub fn classify(settlement: &Settlement, target_claims: Option<NonZeroU32>) -> Self {
        match settlement {
            // Never queued (`EnqueueRefusal::NothingToSettle` fires first);
            // total for the enum.
            Settlement::None => Self::BlindRetrySafe,
            // Unconditional move — a replay pays again.
            Settlement::Transfer { .. } => Self::NeedsReceipt,
            // Replay → AccountAlreadyInitialized, nothing moves.
            Settlement::EscrowOpen { .. } => Self::BlindRetrySafe,
            Settlement::EscrowClaim { .. } => match target_claims {
                Some(n) if n.get() == 1 => Self::BlindRetrySafe,
                _ => Self::NeedsReceipt,
            },
            // Replay refunds 0 — idempotent by program design.
            Settlement::EscrowExpire { .. } => Self::BlindRetrySafe,
            // Replay → AccountAlreadyInitialized, nothing moves — the
            // program's own one-shot registration is the dedupe.
            Settlement::TokenRegister { .. } => Self::BlindRetrySafe,
            // Replays mint/burn again while capacity/balance remain — the
            // measured queue.rs hazard class for value-moving ops.
            Settlement::TokenMint { .. } | Settlement::TokenBurn { .. } => Self::NeedsReceipt,
        }
    }
}

impl PendingSettlement {
    /// Build a fresh row. `discriminator` see [`IntentId::of`];
    /// `target_claims` see [`RetrySafety::classify`].
    pub fn new(
        settlement: &Settlement,
        discriminator: &[u8],
        target_claims: Option<NonZeroU32>,
        now: Tick,
    ) -> Result<Self, EnqueueRefusal> {
        if !settlement.needs_chain() {
            return Err(EnqueueRefusal::NothingToSettle);
        }
        // The queue itself is the Glacial-tier drain: obligations sit durably
        // and submit in the background, nothing in the live game waits on
        // them. Cadence gating happened at composition (each composer
        // declares its cadence); this re-validation only refuses settlements
        // the ledger would also refuse.
        crate::compose::validate(settlement, crate::types::Cadence::Glacial, now)
            .map_err(EnqueueRefusal::Invalid)?;
        Ok(Self {
            id: IntentId::of(settlement, discriminator),
            settlement: settlement.clone(),
            safety: RetrySafety::classify(settlement, target_claims),
            created_tick: now,
            attempts: 0,
            next_attempt_tick: now,
            ambiguous: false,
            poison: None,
        })
    }

    /// Mark an attempt as beginning — **the writer persists the row
    /// durably BEFORE calling submit**. Sets the write-ahead ambiguity flag
    /// and advances the backoff cursor optimistically (a definitive outcome
    /// overwrites it in [`finish_attempt`]).
    pub fn begin_attempt(&mut self, now: Tick, policy: &DrainPolicy) {
        self.attempts = self.attempts.saturating_add(1);
        self.ambiguous = true;
        self.next_attempt_tick = now.saturating_add(policy.next_delay(self.attempts));
    }

    /// Apply a definitive (or transport-classified) outcome. Pure: the
    /// writer persists whatever this returns asks for.
    pub fn finish_attempt(&mut self, outcome: SubmitOutcome, now: Tick, policy: &DrainPolicy) -> AfterEffect {
        match outcome {
            SubmitOutcome::Committed => AfterEffect::Settled(SettlementHow::Committed),
            // The ledger's current state makes a replay a provable permanent
            // no-op (drained single-claim escrow, already-open account) —
            // terminal success for the queue.
            SubmitOutcome::RefusedNoOp => AfterEffect::Settled(SettlementHow::RefusedNoOp),
            SubmitOutcome::RefusedRetryLater | SubmitOutcome::NotDelivered => {
                // RetryLater keeps the cursor; NotDelivered resets it to the
                // transport-failure backoff (both unambiguous).
                self.ambiguous = false;
                self.next_attempt_tick = now.saturating_add(policy.next_delay(self.attempts));
                AfterEffect::Retain
            }
            SubmitOutcome::RefusedPermanent { detail } => {
                self.ambiguous = false;
                self.poison = Some(Poisoned { reason: PoisonReason::PermanentRefusal, detail });
                AfterEffect::Poisoned
            }
            SubmitOutcome::Ambiguous => {
                // Keep the write-ahead flag; backoff was already set by
                // begin_attempt. For NeedsReceipt rows drain_action holds
                // this for manual resolution on the next pass.
                AfterEffect::Retain
            }
        }
    }

    // ── codec ────────────────────────────────────────────────────────

    /// Canonical row bytes (v1). Deterministic; `from_bytes` round-trips.
    pub fn to_bytes(&self) -> Vec<u8> {
        let mut out = Vec::with_capacity(128);
        out.push(1); // version
        out.extend_from_slice(self.id.as_bytes());
        out.push(self.safety as u8);
        out.extend_from_slice(&self.created_tick.to_le_bytes());
        out.extend_from_slice(&self.attempts.to_le_bytes());
        out.extend_from_slice(&self.next_attempt_tick.to_le_bytes());
        out.push(u8::from(self.ambiguous));
        match self.poison {
            None => out.push(0),
            Some(p) => {
                out.push(1);
                out.push(p.reason as u8);
                out.extend_from_slice(&p.detail.to_le_bytes());
            }
        }
        write_settlement(&self.settlement, &mut out);
        out
    }

    /// Decode a v1 row. Errors are typed so a corrupt row poisons loudly at
    /// the writer, never panics the drain.
    pub fn from_bytes(bytes: &[u8]) -> Result<Self, QueueCodecError> {
        let mut p = 0usize;
        let version = take_u8(bytes, &mut p)?;
        if version != 1 {
            return Err(QueueCodecError::Version(version));
        }
        let mut id = [0u8; 32];
        take_slice(bytes, &mut p, &mut id)?;
        let safety = match take_u8(bytes, &mut p)? {
            0 => RetrySafety::BlindRetrySafe,
            1 => RetrySafety::NeedsReceipt,
            other => return Err(QueueCodecError::Safety(other)),
        };
        let created_tick = take_u64(bytes, &mut p)?;
        let attempts = take_u32(bytes, &mut p)?;
        let next_attempt_tick = take_u64(bytes, &mut p)?;
        let ambiguous = take_u8(bytes, &mut p)? != 0;
        let poison = match take_u8(bytes, &mut p)? {
            0 => None,
            1 => {
                let reason = match take_u8(bytes, &mut p)? {
                    0 => PoisonReason::MaxAttempts,
                    1 => PoisonReason::PermanentRefusal,
                    other => return Err(QueueCodecError::Poison(other)),
                };
                let detail = take_u32(bytes, &mut p)?;
                Some(Poisoned { reason, detail })
            }
            other => return Err(QueueCodecError::PoisonFlag(other)),
        };
        let settlement = read_settlement(bytes, &mut p)?;
        Ok(Self {
            id: IntentId::from_bytes(id),
            settlement,
            safety,
            created_tick,
            attempts,
            next_attempt_tick,
            ambiguous,
            poison,
        })
    }
}

impl SettlementReceipt {
    pub fn new(id: IntentId, settled_tick: Tick, how: SettlementHow) -> Self {
        Self { id, settled_tick, how }
    }

    pub fn to_bytes(&self) -> Vec<u8> {
        let mut out = Vec::with_capacity(48);
        out.push(1); // version
        out.extend_from_slice(self.id.as_bytes());
        out.extend_from_slice(&self.settled_tick.to_le_bytes());
        out.push(self.how as u8);
        out
    }

    pub fn from_bytes(bytes: &[u8]) -> Result<Self, QueueCodecError> {
        let mut p = 0usize;
        let version = take_u8(bytes, &mut p)?;
        if version != 1 {
            return Err(QueueCodecError::Version(version));
        }
        let mut id = [0u8; 32];
        take_slice(bytes, &mut p, &mut id)?;
        let settled_tick = take_u64(bytes, &mut p)?;
        let how = match take_u8(bytes, &mut p)? {
            0 => SettlementHow::Committed,
            1 => SettlementHow::RefusedNoOp,
            other => return Err(QueueCodecError::How(other)),
        };
        Ok(Self { id: IntentId::from_bytes(id), settled_tick, how })
    }
}

impl Reward {
