}

impl Cadence {
    /// The tier's cadence in Hz, per `tick_tier_model.md`'s table.
    #[inline]
    pub const fn hz(self) -> f64 {
        match self {
            Self::Hot => 20.0,
            Self::Warm => 5.0,
            Self::Cold => 1.0,
            Self::Glacial => 0.1,
        }
    }

    /// Can an event at this cadence settle on the chain? Only Cold and
    /// Glacial fit; Hot and Warm are disqualified by rate alone.
    #[inline]
    pub const fn allows_settlement(self) -> bool {
        matches!(self, Self::Cold | Self::Glacial)
    }
}

impl PredicateHash {
    /// Domain-separated BLAKE3 over the game layer's completion token.
    ///
    /// `domain` keeps two game systems that happen to share a token
    /// (a mob id reused as an item id) from producing the same predicate.
    #[inline]
    pub fn commit(domain: &str, token: &[u8]) -> Self {
        let mut h = blake3::Hasher::new();
        h.update(b"riir-dapps-predicate-v1");
        h.update(&(domain.len() as u64).to_le_bytes());
        h.update(domain.as_bytes());
        h.update(token);
        Self(*h.finalize().as_bytes())
    }

    /// Wrap a hash computed elsewhere (a chain read-back, a stored quest row).
    #[inline]
    pub const fn from_bytes(bytes: [u8; 32]) -> Self {
        Self(bytes)
    }

    #[inline]
    pub const fn as_bytes(&self) -> &[u8; 32] {
        &self.0
    }

    /// Does `token` satisfy this predicate under `domain`?
    ///
    /// Game-layer convenience: the chain does its own check, but a dApp can
    /// refuse an impossible claim before paying for a round trip.
    #[inline]
    pub fn accepts(&self, domain: &str, token: &[u8]) -> bool {
        Self::commit(domain, token) == *self
    }
}

impl ClaimProof {
    #[inline]
    pub fn new(domain: impl Into<Cow<'static, str>>, token: impl Into<Vec<u8>>) -> Self {
        Self { domain: domain.into(), token: token.into() }
    }

    #[inline]
    pub fn predicate(&self) -> PredicateHash {
        PredicateHash::commit(&self.domain, &self.token)
    }
}

impl Settlement {
    /// Does this outcome touch the ledger at all?
    ///
    /// The one question the boundary rule turns on. A dApp that answers
    /// `false` here is finished — nothing else in this crate applies.
    #[inline]
    pub const fn needs_chain(&self) -> bool {
        !matches!(self, Self::None)
    }
}

impl Composed {
    /// A purely game-local outcome.
    #[inline]
    pub fn local() -> Self {
        Self { settlement: Settlement::None, services: Vec::new() }
    }

    #[inline]
    pub fn settled(settlement: Settlement) -> Self {
        Self { settlement, services: Vec::new() }
    }

    #[inline]
    pub fn with_service(mut self, service: ChainService) -> Self {
        self.services.push(service);
        self
    }

    /// True when nothing at all needs to leave the game layer.
    #[inline]
    pub fn is_fully_local(&self) -> bool {
        !self.settlement.needs_chain() && self.services.is_empty()
    }
}

