// ─── Constants ──────────────────────────────────────────────────────────────

const WARMUP: usize = 20;
const N_ITERS: usize = 200;

/// G4 workload: 256 events (matches MAX_WAKE_EVENTS and the bench_005 fixture).
const N_EVENTS: usize = 256;
/// G4 k_subset: 32 (matches the bench_005 fixture — the production default).
const K_SUBSET: usize = 32;

/// G4 metric set: 5 centroid-based + distributional metrics (the PoC's
/// recommended set for per-event scoring).
const BENCH_METRICS: &[TransferMetric] = &[
    TransferMetric::CentroidCosine,
    TransferMetric::Euclidean,
    TransferMetric::Correlation,
    TransferMetric::RbfMmd,
    TransferMetric::Wasserstein1d,
];

/// G4 metric set (lean): 3 centroid-based metrics only. For 1-sample
/// candidates, RbfMmd degenerates to RBF kernel and Wasserstein1d to L1
/// distance — both redundant with Euclidean (L2). The 3-metric set is the
/// recommended production default for per-event scoring; the 5-metric set is
/// reported for comparison.
const BENCH_METRICS_LEAN: &[TransferMetric] = &[
    TransferMetric::CentroidCosine,
    TransferMetric::Euclidean,
    TransferMetric::Correlation,
];

/// G4 latency target: same budget as `sleep_diverse` (500 µs). The sleep cycle
/// runs at per-zone cadence (not per-tick), so 500 µs is generous. The MAG
/// scoring is O(N·M·d) — 256×5×64 = 81,920 FMA-class ops — which should be
/// well under this budget.
const TARGET_FULL_US: f64 = 500.0;

