    }
    let (transfer_mean, transfer_p99) = bench_latency(|| {
        transfer_pipeline.sleep_transfer(&index, K_SUBSET, BENCH_METRICS);
    });

    // ── Path 2: baseline sleep(1) — uniform averaging ──────────────────────
    let mut baseline_pipeline = ConsolidationPipeline::new(zone);
    for evt in &events {
        baseline_pipeline.capture_wake(evt.clone());
    }
    let (baseline_mean, baseline_p99) = bench_latency(|| {
        baseline_pipeline.sleep(1);
    });

    // ── Path 2b: full sleep_transfer with 3 metrics (lean set) ────────────
    let mut lean_pipeline = ConsolidationPipeline::new(zone);
    for evt in &events {
        lean_pipeline.capture_wake(evt.clone());
    }
