        lean_pipeline.sleep_transfer(&index, K_SUBSET, BENCH_METRICS_LEAN);
    });

    // ── Path 3: transfer surcharge = full - baseline ───────────────────────
    // The MAG-specific cost over plain averaging = scoring + percentile + selection.
    // (Averaging is shared between both paths — the surcharge is the delta.)
    let surcharge_mean = transfer_mean - baseline_mean;
    let surcharge_p99 = transfer_p99 - baseline_p99;

    // ── G2-weak advantage check ────────────────────────────────────────────
    let (cosine_dist, multi_dist, multi_wins) = g2_weak_advantage_check();

    // ── G2 class-conditional advantage check (the headline gate) ──────────
    let (cos_top1, cc_top1, cc_advantage, g2_pass) = g2_class_conditional_advantage_check();

    // ── Report ─────────────────────────────────────────────────────────
    println!("┌──────────────────────────────────────┬────────────┬────────────┬───────────┐");
