    );
    println!(
        "G4 latency (5-metric, comparison):       {} ({:.2} µs vs {:.0} µs target)",
        if transfer_mean < TARGET_FULL_US {
            "PASS"
        } else {
            "FAIL"
        },
        transfer_mean,
        TARGET_FULL_US
    );
    println!(
        "G2-weak advantage: {} (multi-metric {:.2}× closer than cosine-only)",
