    if !g4_pass || !g2_pass {
        std::process::exit(1);
    }
}

fn main() {
    println!("── Issue 003: ZoneGeometry threat-cochain splat bench ──");
    println!("workload: {GRID_W}×{GRID_H} grid, {N_THREATS} threats");

    let shard = test_shard();
    let h = shard_hash(&shard);
    let threats = make_threats(N_THREATS, GRID_W, GRID_H);
    // Empty occupancy / interest / destroyed-faces — the bench isolates the
    // threat-cochain path. Occupancy is sized to (w-1)*(h-1) = 99*99 faces.
    let occupancy = vec![0.0f32; ((GRID_W - 1) * (GRID_H - 1)) as usize];
    let interest_anchors: Vec<(f32, f32, f32)> = Vec::new();

    // Sanity: regen must succeed and produce a pod with the expected grid dims.
    let pod = ZoneGeometryPod::regen_from_shard_and_raw(
        &shard,
        h,
        GRID_W,
        GRID_H,
        0,
        &[],
        &threats,
        &occupancy,
        &interest_anchors,
    );
    assert_eq!(pod.header.grid_w, GRID_W);
    assert_eq!(pod.header.grid_h, GRID_H);
    assert_eq!(
        pod.header.n_edges,
        (GRID_W - 1) * GRID_H + GRID_W * (GRID_H - 1)
    );

    let (mean_us, p99_us) = bench_latency(|| {
        let _ = ZoneGeometryPod::regen_from_shard_and_raw(
            &shard,
            h,
            GRID_W,
            GRID_H,
            0,
            &[],
            &threats,
            &occupancy,
            &interest_anchors,
        );
    });

    // Theoretical exp() counts for context (the actual win is wall-time).
    let n_edges = ((GRID_W - 1) * GRID_H + GRID_W * (GRID_H - 1)) as usize;
    let naive_exp_count = n_edges * N_THREATS;
    // Splat: per threat, ~(2·12)² = 576 H-edges + 576 V-edges = 1152 exp() calls
    // (clamped to grid bounds; for a 100×100 grid the boundary clamp is negligible).
    let splat_exp_count = N_THREATS * 2 * (2 * 12) * (2 * 12);
    let reduction = naive_exp_count as f64 / splat_exp_count as f64;

    println!();
    println!("┌─────────────────────────────────────────────────────────────┐");
    println!("│ regen_from_shard_and_raw latency (100×100, 100 threats)    │");
    println!("├─────────────────────────────────────────────────────────────┤");
    println!("│ mean: {mean_us:>10.2} µs                                          │");
    println!("│ p99 : {p99_us:>10.2} µs                                          │");
    println!("├─────────────────────────────────────────────────────────────┤");
    println!("│ exp() call count context (theoretical):                    │");
    println!("│   naive (per-edge × all threats): {naive_exp_count:>12}                  │");
    println!("│   splat (per-threat × 3σ window): {splat_exp_count:>12}                  │");
    println!("│   reduction factor            : {reduction:>8.2}×                   │");
    println!("└─────────────────────────────────────────────────────────────┘");

    // Soft gate: the splat path should keep regen well under the 1ms G5b budget.
    // We assert < 500 µs as a conservative upper bound (the budget is 1ms, and
    // pre-Issue-003 regen on this workload could exceed it on slower hosts).
    const G5B_BUDGET_US: f64 = 1_000.0;
    const SOFT_GATE_US: f64 = 500.0;
    assert!(
        mean_us < G5B_BUDGET_US,
        "mean latency {mean_us} µs exceeds G5b 1ms budget"
    );
    if mean_us < SOFT_GATE_US {
        println!(
            "✓ PASS: mean {mean_us} µs < soft gate {SOFT_GATE_US} µs (G5b 1ms budget has 2× headroom)"
        );
    } else {
        println!(
            "△ WARN: mean {mean_us} µs under G5b budget but above soft gate {SOFT_GATE_US} µs"
        );
    }
}

use riir_neuron_db::{BELIEF_DIM, NeuronShard, STYLE_DIM, ShardIndex};
use std::hint::black_box;
use std::time::Instant;

// ── Constants ─────────────────────────────────────────────────────────────

const N_CLUSTERS: usize = 10;
const N_PER_CLUSTER: usize = 100;
const N_SHARDS: usize = N_CLUSTERS * N_PER_CLUSTER; // 1000
const K: usize = 5;
const N_LATENCY_ITER: usize = 10_000;

/// Large population for the scaling test.
const N_SHARDS_LARGE: usize = 10_000;

/// G1 gate: recall@k must be ≥ this value (with ε tolerance).
const G1_MIN_RECALL: f64 = 0.95;
/// Tolerance for cosine value comparison in recall test.
/// Near-tie candidates (within ε) are considered interchangeable.
const RECALL_EPS: f32 = 1e-4;

/// G2 gate: fast_knn must be ≥ this multiple faster than brute-force.
const G2_MIN_SPEEDUP: f64 = 5.0;

// ── Shard construction ───────────────────────────────────────────────────
//
// Zone hashes MUST be unique per shard. The original `[zone_byte; 32]` pattern
// wraps at 256, causing collisions for populations > 256 (Issue 013;
// Issue 013 removed, see git history).
// Fix: encode the shard index as a u32 in the first 4 bytes.

fn make_shard(zone_idx: u32, hla: [f32; BELIEF_DIM], style_seed: f32) -> NeuronShard {
    let mut zone_hash = [0u8;

fn main() {
    println!("Issue 011 — Fast k-NN GOAT gate bench");
    println!(
        "Population: {N_CLUSTERS} clusters × {N_PER_CLUSTER} = {N_SHARDS} shards. k={K}, BELIEF_DIM={BELIEF_DIM}."
    );
    println!();

    // ── 1. Build population ──────────────────────────────────────────────
    let shards = build_population(N_SHARDS);

    // ── 2. Build ShardIndex (uses fast_knn path) ────────────────────────
    let index = ShardIndex::with_capacity(N_SHARDS);
    {
        let guard = index.guard();
        for s in &shards {
            index.insert(*s, &guard);
        }
    }

    // ── 3. G1: Recall test (100 queries) ────────────────────────────────
    println!("── G1: Recall@k (100 queries, ε={RECALL_EPS}) ──────────────────");
    let mut total_recall = 0.0f64;
    let mut total_recall_no_eps = 0.0f64;
    let n_recall_queries = 100;
    for q in 0..n_recall_queries {
        let query_shard = &shards[q * (N_SHARDS / n_recall_queries)];
        let guard = index.guard();

        let fast_results = index.query_k_nearest_cosine(
            &query_shard.hla_moments,
            &query_shard.zone_hash,
            K,
            &guard,
        );

        let brute_results = index.query_k_nearest_cosine_brute(
            &query_shard.hla_moments,
            &query_shard.zone_hash,
            K,
            &guard,
        );

        // Tolerance-based recall (standard ANN metric)
        let recall = recall_with_tolerance(&fast_results, &brute_results, RECALL_EPS);
        total_recall += recall;

        // Exact set recall (for diagnostics — shows the FP tie-breaking rate)
        let fast_zones: std::collections::HashSet<[u8; 32]> =
            fast_results.iter().map(|(s, _)| s.zone_hash).collect();
        let brute_zones: std::collections::HashSet<[u8; 32]> =
            brute_results.iter().map(|(s, _)| s.zone_hash).collect();
        let exact = fast_zones.intersection(&brute_zones).count();
        total_recall_no_eps += exact as f64 / brute_zones.len() as f64;
    }
    let avg_recall = total_recall / n_recall_queries as f64;
    let avg_recall_no_eps = total_recall_no_eps / n_recall_queries as f64;
    let g1_pass = avg_recall >= G1_MIN_RECALL;
    println!("  Recall@k (ε={RECALL_EPS}): {avg_recall:.4} (target ≥ {G1_MIN_RECALL:.2})");
    println!("  Recall@k (exact, no ε): {avg_recall_no_eps:.4} — shows FP tie-breaking rate");
    println!("  G1: {}", if g1_pass { "PASS ✅" } else { "FAIL ❌" });
    println!();

    // ── 4. G2: Latency comparison (1000 shards) ─────────────────────────
    println!("── G2: Latency ({N_SHARDS} shards, {N_LATENCY_ITER} iterations) ───────────");
    let guard = index.guard();

    // Warm up
    for i in 0..100 {
        let q = &shards[i % N_SHARDS];
        black_box(index.query_k_nearest_cosine(&q.hla_moments, &q.zone_hash, K, &guard));
        black_box(index.query_k_nearest_cosine_brute(&q.hla_moments, &q.zone_hash, K, &guard));
    }

    // Fast path
    let start = Instant::now();
    for iter in 0..N_LATENCY_ITER {
        let q = &shards[iter % N_SHARDS];
        let r = black_box(index.query_k_nearest_cosine(&q.hla_moments, &q.zone_hash, K, &guard));
        std::hint::black_box(&r);
    }
    let fast_elapsed = start.elapsed();
    let fast_mean_ns = fast_elapsed.as_nanos() as f64 / N_LATENCY_ITER as f64;

    // Brute-force path (through the same ShardIndex API)
    let start = Instant::now();
    for iter in 0..N_LATENCY_ITER {
        let q = &shards[iter % N_SHARDS];
        let r =
            black_box(index.query_k_nearest_cosine_brute(&q.hla_moments, &q.zone_hash, K, &guard));
        std::hint::black_box(&r);
    }
    let bf_elapsed = start.elapsed();
    let bf_mean_ns = bf_elapsed.as_nanos() as f64 / N_LATENCY_ITER as f64;

    let speedup = bf_mean_ns / fast_mean_ns;
    let g2_pass = speedup >= G2_MIN_SPEEDUP;

    println!("  Brute-force (old): {bf_mean_ns:>10.1} ns/query");
    println!("  Fast k-NN (new):   {fast_mean_ns:>10.1} ns/query");
    println!("  Speedup:           {speedup:>10.2}× (target ≥ {G2_MIN_SPEEDUP:.0}×)");
    println!("  G2: {}", if g2_pass { "PASS ✅" } else { "FAIL ❌" });
    println!();

    // ── 5. Scaling test: 10000 shards ───────────────────────────────────
    println!("── Scaling: {N_SHARDS_LARGE} shards ─────────────────────────────────────");
    let large_shards = build_population(N_SHARDS_LARGE);
    let large_index = ShardIndex::with_capacity(N_SHARDS_LARGE);
    {
        let guard = large_index.guard();
        for s in &large_shards {
            large_index.insert(*s, &guard);
        }
    }

    let large_guard = large_index.guard();
    let n_large_iter = 1000;

    // Warm up
    for q in large_shards.iter().take(10) {
        black_box(large_index.query_k_nearest_cosine(
            &q.hla_moments,
            &q.zone_hash,
            K,
            &large_guard,
        ));
        black_box(large_index.query_k_nearest_cosine_brute(
            &q.hla_moments,
            &q.zone_hash,
            K,
            &large_guard,
        ));
    }

    let start = Instant::now();
    for iter in 0..n_large_iter {
        let q = &large_shards[iter % N_SHARDS_LARGE];
        let r = black_box(large_index.query_k_nearest_cosine(
            &q.hla_moments,
            &q.zone_hash,
            K,
            &large_guard,
        ));
        std::hint::black_box(&r);
    }
    let large_fast_ns = start.elapsed().as_nanos() as f64 / n_large_iter as f64;

    let start = Instant::now();
    for iter in 0..n_large_iter {
        let q = &large_shards[iter % N_SHARDS_LARGE];
        let r = black_box(large_index.query_k_nearest_cosine_brute(
            &q.hla_moments,
            &q.zone_hash,
            K,
            &large_guard,
        ));
        std::hint::black_box(&r);
    }
    let large_bf_ns = start.elapsed().as_nanos() as f64 / n_large_iter as f64;
    let large_speedup = large_bf_ns / large_fast_ns;

    println!("  Brute-force (old): {large_bf_ns:>10.1} ns/query");
    println!("  Fast k-NN (new):   {large_fast_ns:>10.1} ns/query");
    println!("  Speedup:           {large_speedup:>10.2}×");
    println!();

    // ── 6. Verdict ──────────────────────────────────────────────────────
    println!("════════════════════════════════════════════════════════════");
    println!("GOAT Gate Summary:");
    println!(
        "  G1 (recall ≥ 0.95):  {} ({:.4})",
        if g1_pass { "PASS ✅" } else { "FAIL ❌" },
        avg_recall
    );
    println!(
        "  G2 (speedup ≥ 5×):   {} ({:.2}×)",
        if g2_pass { "PASS ✅" } else { "FAIL ❌" },
        speedup
    );
    if g1_pass && g2_pass {
        println!("  → GOAT PASS — promote to default-on");
    } else {
        println!("  → GOAT FAIL — keep opt-in, investigate further optimizations");
    }
}

use riir_neuron_db::{BELIEF_DIM, NeuronShard, STYLE_DIM, ShardIndex};
use std::hint::black_box;
use std::time::Instant;

// ── Constants ─────────────────────────────────────────────────────────────

const N_CLUSTERS: usize = 10;
const N_PER_CLUSTER: usize = 100;
const N_SHARDS: usize = N_CLUSTERS * N_PER_CLUSTER; // 1000
const K: usize = 5;
const N_LATENCY_ITER: usize = 10_000;

/// G1 gate: recall@k must be ≥ this value (with ε tolerance).
const G1_MIN_RECALL: f64 = 0.95;
/// Tolerance for cosine value comparison in recall test.
const RECALL_EPS: f32 = 1e-4;

/// T2 gate: fast_knn must be ≥ this multiple faster than brute-force (small drift).
const T2_MIN_SPEEDUP: f64 = 5.0;
/// T3 gate: fast_knn must be ≥ this multiple faster than brute-force (large drift).
const T3_MIN_SPEEDUP: f64 = 3.0;

/// T1 gate: total update latency for 1000 shards must be < this (cold path).
const T1_MAX_TOTAL_MS: f64 = 10.0;

