fn phase_c_tag_cardinality() {
    const N: usize = 10_000;
    const TAG_QUERIED: u8 = 0; // always scan for tag 0
    let iters = scan_iters(N);

    println!("  N = {N} (fixed), sweeping tag cardinality:");
    println!(
        "  {:>8}  {:>10}  {:>12}  {:>14}  {:>10}",
        "tags", "matching", "scan (ns)", "ns/match-row", "ceil(x)"
    );

    // u8 tag space caps at 255; 256 as u8 wraps to 0 and would panic in
    // make_tagged_shards. 128 is the highest power-of-2 cardinality that fits.
    for &num_tags in &[1usize, 2, 4, 8, 16, 64, 128] {
        let shards = make_tagged_shards(N, num_tags as u8);
        let index = ShardIndex::from_shards(shards);
        let guard = index.guard();

        let matching = N / num_tags;

        // S2-equivalent: traversal + tag filter (no payload read).
        let scan_ns = time_ns(iters, || {
            index
                .iter_shards(&guard)
                .filter(|s| s.zone_hash[4] == TAG_QUERIED)
                .count()
        });

        let ns_per_match = if matching > 0 {
            scan_ns / matching as f64
        } else {
            f64::INFINITY
        };

        println!(
            "  {num_tags:>8}  {matching:>10}  {scan_ns:>12.1}  {ns_per_match:>14.2}  {num_tags:>9.0}×"
        );
    }
    println!();
}

fn main() {
    println!("Bench 457 — scan-floor isolation profiler (Issue 021 T1)");
    println!("=========================================================");
    println!("ShardIndex type: papaya HashMap<[u8;32], NeuronShard>");
    println!(
        "NeuronShard size: {} bytes ({:.1} cache lines)",
        std::mem::size_of::<NeuronShard>(),
        std::mem::size_of::<NeuronShard>() as f64 / 64.0
    );
    println!("STYLE_DIM={STYLE_DIM}, BELIEF_DIM={BELIEF_DIM}");
    println!();

    // ── Phase A: scan-floor isolation at 3 scales ──────────────────────
    println!("── Phase A: scan-floor isolation ────────────────────────────");
    println!("Decomposes scan cost into: traversal (S1), +tag filter (S2),");
    println!("+payload read +accumulate (S3). Δtag and Δread isolate the");
    println!("aggregation overhead from the raw traversal floor.");
    println!();
    for &n in &[1_000usize, 10_000, 100_000] {
        phase_a_scan_floor(n);
    }

    // ── Phase B: papaya iteration order (Q1) ──────────────────────────
    println!("── Phase B: papaya iteration order (Q1) ────────────────────");
    println!("Measures pointer-address sortedness of iter_shards output.");
    println!("efficiency ≈ 1.0 + ascending_runs ≈ 1 → allocation order");
    println!("→ prefetch viable. efficiency → 0 + runs ≈ n/2 → hash order");
    println!("→ prefetch useless, need projection cache (Approach A).");
    println!();
    let mut reports = Vec::new();
    for &n in &[1_000usize, 10_000, 100_000] {
        reports.push(phase_b_iteration_order(n));
    }

    // ── Phase C: tag cardinality sweep (Q2) ───────────────────────────
    println!("── Phase C: tag cardinality sweep (Q2) ────────────────────");
    println!("Fixes N=10K, sweeps distinct tag counts. Confirms scan is");
    println!("O(N_total) not O(N_matching) — the core assumption behind");
    println!("zone-partitioned projection (Approach A). 'ceil(x)' = the");
    println!("theoretical partitioning speedup = N_total / N_matching.");
    println!();
    phase_c_tag_cardinality();

    // ── Phase D: write-path cost baseline (Q3) ────────────────────────
    println!("── Phase D: write-path cost baseline (Q3) ─────────────────");
    println!("Measures insert/update latency. breakeven = scan/insert");
    println!("gives the read:write ratio above which eager projection");
    println!("maintenance pays off. Compare to lazy build-on-first-scan.");
    println!();
    for &n in &[1_000usize, 10_000] {
        phase_d_write_path(n);
    }

    // ── Summary ───────────────────────────────────────────────────────
    println!("════════════════════════════════════════════════════════════");
    println!("Summary — answers to the three open questions:");
    println!();
    println!("Q1 (papaya iteration order):");
    let avg_eff = reports.iter().map(|r| r.efficiency).sum::<f64>() / reports.len() as f64;
    let last = reports.last().unwrap();
    println!("  avg efficiency = {avg_eff:.4} (1.0 = sequential, 0 = random)");
    println!(
        "  N={} ascending_runs = {} (1 = sorted, ~{} = random)",
        last.n,
        last.ascending_runs,
        last.n / 2
    );
    if avg_eff > 0.5 {
        println!("  → prefetch (Approach C) is VIABLE — iteration is near-allocation-order.");
    } else {
        println!("  → prefetch (Approach C) is NOT viable — iteration is hash-order.");
        println!("    Recommendation: zone-partitioned projection cache (Approach A).");
    }
    println!();
    println!("Q2 (tag cardinality): see Phase C table. Scan cost should be");
    println!("  flat across tag counts (O(N_total)), confirming partitioning");
    println!("  speedup = num_tags for uniform distributions.");
    println!();
    println!("Q3 (read:write ratio): see Phase D breakeven numbers.");
    println!("  High breakeven (e.g. >100) → lazy build-on-first-scan is better.");
    println!("  Low breakeven (e.g. <10) → eager maintenance is cheap, prefer it.");
    println!();
    println!("Record these findings in .benchmarks/457_scan_floor_profiler.md.");
}

use neuron_db_sdk::{ShardQuery, ShardRow};
use riir_neuron_db::{NeuronShard, STYLE_DIM, ShardIndex};

// ── Schema ─────────────────────────────────────────────────────────────────

#[derive(ShardRow, Clone, Debug, PartialEq)]
#[shard(tag = 1)]
struct Monster {
    #[shard(pk)]
    id: i64,
    #[shard(payload)]
    hp: i64,
    #[shard(payload)]
    atk: i64,
    #[shard(skip)]
    _name: String,
}

#[derive(ShardRow, Clone, Debug, PartialEq)]
#[shard(tag = 2)]
struct Item {
    #[shard(pk)]
    id: i64,
    #[shard(payload)]
    weight: i64,
    #[shard(payload)]
    value: i64,
    #[shard(skip)]
    _name: String,
}

fn build_index(n_per_tag: usize) -> ShardIndex {
    let monsters: Vec<Monster> = (0..n_per_tag as i64)
        .map(|i| Monster {
            id: i,
            hp: 100 + i * 7,
            atk: 10 + i * 3,
            _name: format!("m{i}"),
        }

fn main() {
    println!("╔══════════════════════════════════════════════════════════════╗");
    println!("║  Bench 458 — scan_projection GOAT gate (Issue 021 T4)        ║");
    println!("╚══════════════════════════════════════════════════════════════╝");
    println!();

    // ── T9: aggregation gate (N=1000) ──────────────────────────────
    println!("── T9: Aggregation gate at N=1000 (2 tags × 500 each) ──────");
    let n = 500; // 500 monsters + 500 items = 1000 total
    let index = build_index(n);
    let guard = index.guard();

