        100,
    );
    fmt_ns("T9b: avg_payload(0) [hp]", p50, p99);

    let (p50, p99) = measure_ns(
        || {
            black_box(ShardQuery::<Monster>::all().min_payload(0, &index, &guard));
        },
        1000,
        100,
    );
    fmt_ns("T9c: min_payload(0) [hp]", p50, p99);

    let (p50, p99) = measure_ns(
        || {
            black_box(ShardQuery::<Monster>::all().max_payload(0, &index, &guard));
        },
        1000,
        100,
    );
    fmt_ns("T9d: max_payload(0) [hp]", p50, p99);

    // With WHERE filter (exercises matches_weights in the projection path)
    let (p50, p99) = measure_ns(
        || {
            black_box(
                ShardQuery::<Monster>::where_payload_gt(0, 200.0).sum_payload(0, &index, &guard),
            );
        },
