    for &n in &[100, 1000, 10000] {
        let index = build_index(n);
        let guard = index.guard();
        let (p50, _) = measure_ns(
            || {
                black_box(ShardQuery::<Monster>::all().sum_payload(0, &index, &guard));
            },
            200,
            50,
        );
        println!("  N={n:>6} (per tag): sum_payload p50 = {p50:>8.0} ns");
    }
    println!();

    // ── T10: write-path regression (insert + update) ──────────────
    println!("── T10: Write-path regression (projection invalidation) ────");
    let index = build_index(500);
    let guard = index.guard();

    // Insert: adds a new monster shard, sets dirty=true
    let new_monster = Monster {
        id: 999_999,
        hp: 500,
        atk: 50,
        _name: "new".into(),
    };
    let shard = new_monster.encode_to_shard();
