    println!("  Update (invalidates proj):    p50={p50:>8.0} ns  p99={p99:>8.0} ns");

    // Read-after-write: should trigger rebuild, then return result
    let (p50, p99) = measure_ns(
        || {
            black_box(ShardQuery::<Monster>::all().sum_payload(0, &index, &guard));
        },
        200,
        50,
    );
    println!("  Read-after-update (rebuild):  p50={p50:>8.0} ns  p99={p99:>8.0} ns");

    println!();

    // ── Determinism check ─────────────────────────────────────────
    println!("── Determinism: repeated builds + reads are bit-identical ──");
    let index_a = build_index(500);
    let index_b = build_index(500);
    let guard_a = index_a.guard();
    let guard_b = index_b.guard();
    let sum_a = ShardQuery::<Monster>::all().sum_payload(0, &index_a, &guard_a);
    let sum_b = ShardQuery::<Monster>::all().sum_payload(0, &index_b, &guard_b);
    let avg_a = ShardQuery::<Monster>::all().avg_payload(1, &index_a, &guard_a);
    let avg_b = ShardQuery::<Monster>::all().avg_payload(1, &index_b, &guard_b);
    let min_a = ShardQuery::<Item>::all().min_payload(0, &index_a, &guard_a);
    let min_b = ShardQuery::<Item>::all().min_payload(0, &index_b, &guard_b);
    println!(
        "  sum(hp) A={:.4} B={:.4} match={}",
        sum_a,
        sum_b,
        sum_a == sum_b
    );
    println!(
        "  avg(atk) A={:?} B={:?} match={}",
        avg_a,
        avg_b,
        avg_a == avg_b
    );
    println!(
        "  min(weight) A={:?} B={:?} match={}",
        min_a,
        min_b,
        min_a == min_b
    );

    println!();
    println!("Done. STYLE_DIM={STYLE_DIM}");
}

use riir_neuron_db::{BELIEF_DIM, NeuronShard, STYLE_DIM, compute_support_diameter};
