// ── Constants ─────────────────────────────────────────────────────────────

/// Population sizes to measure. Includes the n=10000 case the original
/// `#[test]` skipped in debug (would take ~9s in debug; ~1-2s in release).
const SIZES: &[usize] = &[100, 1000, 10000];

/// Per-size release-mode budget (ms). ~3-5× observed mean to give
/// headroom for machine variance while still catching O(n³) regressions.
const BUDGET_MS: &[f64] = &[1.0, 50.0, 5000.0];

/// Number of measurement iterations per size. n=100 is fast enough for
/// 1000 iters; n=10000 is limited to 3 iters (each call is ~1-2 s).
fn iters_for(n: usize) -> usize {
    match n {
        100 => 1000,
        1000 => 50,
        10000 => 3,
        _ => 1,
    }

fn main() {
    println!("Issue 024 T1 — G9 perf gate: compute_support_diameter population scaling");
    println!("STYLE_DIM = {STYLE_DIM}");
    println!();

    let mut all_pass = true;

    println!("═══ G9 mean latency (release, warmup'd) ═══");
    println!("┌─────────┬───────────┬──────────────┬────────┬─────────┐");
    println!("│ n       │ mean (ms) │ budget (ms)  │ ratio  │ verdict │");
    println!("├─────────┼───────────┼──────────────┼────────┼─────────┤");

    for (i, &n) in SIZES.iter().enumerate() {
        let shards = build_population(n);
        let refs: Vec<&NeuronShard> = shards.iter().collect();
        let budget_ms = BUDGET_MS[i];

        // Warmup.
        for _ in 0..warmup_for(n) {
            let d = compute_support_diameter(&refs);
            black_box(d);
        }

        // Measurement.
        let iters = iters_for(n);
        let t0 = Instant::now();
        for _ in 0..iters {
            let d = compute_support_diameter(&refs);
            black_box(d);
        }
        let total = t0.elapsed();
        let mean_ms = total.as_secs_f64() * 1e3 / iters as f64;

        let pass = mean_ms <= budget_ms;
        let ratio = mean_ms / budget_ms;
        if !pass {
            all_pass = false;
        }

        println!(
            "│ {:<7} │ {:>9.3} │ {:>12.1} │ {:>6.2}× │ {:<7} │",
            n,
            mean_ms,
            budget_ms,
            ratio,
            if pass { "PASS ✅" } else { "FAIL ❌" }
        );
    }

    println!("└─────────┴───────────┴──────────────┴────────┴─────────┘");
    println!();
    println!(
        "Overall G9 verdict: {}",
        if all_pass { "PASS ✅" } else { "FAIL ❌" }
    );

    if !all_pass {
        // Exit non-zero on gate failure so CI catches it. The benchmark
        // results are still printed above for analysis.
        std::process::exit(1);
    }
}

