/// Soft gate for the execute path (regression catch — see module docs).
/// Set to 5 µs — ~15× the measured latency (~320 ns). The BLAKE3 hash of
/// 320 bytes is the dominant cost (~300 ns); the FMA blend adds ~10-20 ns.
/// 5 µs is generous enough to absorb cross-hardware variance + dyld/trustd
/// noise on macOS, while still catching a real regression (e.g., a per-call
/// allocation or a switch to a streaming hash).
const EXECUTE_BUDGET_NS: f64 = 5_000.0;
/// Warmup iterations to stabilize cache + BLAKE3 internals.
const WARMUP_ITER: usize = 5_000;

// ── Shard + goal construction ─────────────────────────────────────────────

/// Build a `NeuronShard` with deterministic style_weights (mirrors the
/// bench_316 / bench_464 `make_shard` pattern, but without HLA setup since
/// `execute()` does not read HLA moments).
fn make_shard(zone_byte: u8, style_seed: f32) -> NeuronShard {
    let mut shard = NeuronShard::new([zone_byte;

fn main() {
    println!("=== Bench 465 — MapeKLoop::execute() regression-guard + baseline ===\n");
    println!("STYLE_DIM            = {STYLE_DIM}");
    println!("N_SHARDS             = {N_SHARDS}");
    println!("N_LATENCY_ITER       = {N_LATENCY_ITER}");
    println!("ALPHA                = {ALPHA}");
    println!();

    // MapeKLoop is stateless for execute() — only plan*() reads its config.
    // We construct one to mirror the production call shape.
    let mk = MapeKLoop::new(2.0);

    // ── Correctness check: execute() applies the heal + changes commitment ──
    //
    // Build a fresh population, run execute() on every shard, verify:
    //   (1) execute() returns Ok (not ExternalEscalation),
    //   (2) the commitment changes (BLAKE3 reflects the new weights),
    //   (3) the weights moved toward the delta (L1 distance shrinks).
    let (mut pop_check, deltas_check) = build_population_with_deltas();
    let mut commitment_changed_count = 0usize;
    let mut distance_shrunk_count = 0usize;
    for i in 0..N_SHARDS {
        let commitment_before = pop_check[i].commitment;
        let pre_dist = l1_distance(&pop_check[i].style_weights, &deltas_check[i]);
        let goal = CorrectiveGoal::InternalHealing {
            delta: &deltas_check[i],
            alpha: ALPHA,
        };
        let result = mk.execute(&mut pop_check[i], &goal);
        assert!(result.is_ok(), "execute() should return Ok on InternalHealing");
        let new_commitment = result.unwrap();
        if new_commitment != commitment_before {
            commitment_changed_count += 1;
        }
        let post_dist = l1_distance(&pop_check[i].style_weights, &deltas_check[i]);
        if post_dist < pre_dist {
            distance_shrunk_count += 1;
        }
    }
    println!(
        "Correctness check: {commitment_changed_count}/{N_SHARDS} commitments changed, {distance_shrunk_count}/{N_SHARDS} L1 distances shrunk"
    );
    assert_eq!(
        commitment_changed_count, N_SHARDS,
        "every execute() call should change the commitment (BLAKE3 reflects new weights)"
    );
    assert_eq!(
        distance_shrunk_count, N_SHARDS,
        "every execute() call should move weights toward the delta (alpha-blend invariant)"
    );
    println!("  → all correctness assertions PASS\n");

    // ── Latency measurement ──────────────────────────────────────────────
    //
    // Build a fresh population for the latency loop (the correctness loop
    // already mutated the shards). We cycle through the population so the
    // bench exercises N_SHARDS distinct (shard, delta) pairs rather than
    // measuring one hot cache line repeatedly.
    let (mut pop, deltas) = build_population_with_deltas();

    // Warmup.
    for _ in 0..WARMUP_ITER {
        let i = 0;
        let goal = CorrectiveGoal::InternalHealing {
            delta: &deltas[i],
            alpha: ALPHA,
        };
        let _ = mk.execute(black_box(&mut pop[i]), black_box(&goal));
    }

    // Measure. We reset the shard every iteration so the blend doesn't
    // converge (otherwise later iterations would measure a no-op blend where
    // weights ≈ delta). The reset is OUTSIDE the timed region.
    let t0 = Instant::now();
    for j in 0..N_LATENCY_ITER {
        let i = j % N_SHARDS;
        // Snapshot the pre-execute weights so we can restore them after.
        // This is outside the measured cost — we measure ONLY execute().
        let weights_snapshot = pop[i].style_weights;
        let commitment_snapshot = pop[i].commitment;
        let goal = CorrectiveGoal::InternalHealing {
            delta: &deltas[i],
            alpha: ALPHA,
        };
        let result = mk.execute(black_box(&mut pop[i]), black_box(&goal));
        let _ = black_box(result);
        // Restore so the next iteration measures the same blend (not a
        // converged no-op). Also outside the measured cost.
        pop[i].style_weights = weights_snapshot;
        pop[i].commitment = commitment_snapshot;
    }
    let elapsed = t0.elapsed();
    let ns_per_call_execute = elapsed.as_nanos() as f64 / N_LATENCY_ITER as f64;

    println!(
        "Mean latency: {ns_per_call_execute:.2} ns/call (execute InternalHealing — FMA blend + BLAKE3 hash of 320 bytes)"
    );
    println!(
        "Soft gate: < {:.0} ns → {}",
        EXECUTE_BUDGET_NS,
        if ns_per_call_execute < EXECUTE_BUDGET_NS {
            "PASS ✅"
        } else {
            "FAIL ❌"
        }
    );
    println!();
    assert!(
        ns_per_call_execute < EXECUTE_BUDGET_NS,
        "execute() regression: {ns_per_call_execute} ns >= {EXECUTE_BUDGET_NS} ns budget"
    );

    // ── Summary ──────────────────────────────────────────────────────────
    println!("═══ Summary ═══");
    println!(
        "  execute (InternalHealing): {ns_per_call_execute:.2} ns/call (budget < {EXECUTE_BUDGET_NS:.0} ns)"
    );
    println!();
    println!("  Soft gate PASS — baseline established + regression guard in place.");
    println!("  Dominant cost: BLAKE3 hash of 320 bytes (compute_commitment).");
    println!("  FMA blend (chunk-4 over STYLE_DIM={STYLE_DIM}) is a small fraction of the total.");
}

use riir_neuron_db::{BELIEF_DIM, NeuronShard, STYLE_DIM};
use std::hint::black_box;
use std::time::Instant;

// ── Constants ─────────────────────────────────────────────────────────────

/// Population size — matches bench_464 / bench_465 realistic workload.
const N_SHARDS: usize = 1000;
/// Latency measurement iterations. At ~300 ns/call, 200K iters ≈ 60 ms total
/// (well within bench budget; long enough for a stable mean).
const N_LATENCY_ITER: usize = 200_000;
/// Soft gate for compute_commitment (regression catch — see module docs).
/// ~6× headroom over the measured ~300-320 ns baseline.
const COMPUTE_BUDGET_NS: f64 = 2_000.0;
/// Soft gate for verify_commitment (regression catch).
/// Same headroom — verify ≈ compute + ~1 ns memcmp.
const VERIFY_BUDGET_NS: f64 = 2_000.0;
/// Warmup iterations to stabilize cache + BLAKE3 internals.
const WARMUP_ITER: usize = 10_000;

// ── Shard construction ────────────────────────────────────────────────────

/// Build a `NeuronShard` with the given HLA moments + a deterministic
/// style_weights seed (mirrors the bench_464 / bench_465 `make_shard` pattern).
/// `compute_commitment()` is called to populate `shard.commitment` so
/// `verify_commitment()` returns true for the untampered population.
fn make_shard(zone_byte: u8, hla: [f32; BELIEF_DIM], style_seed: f32) -> NeuronShard {
    let mut shard = NeuronShard::new([zone_byte;

fn main() {
    println!("=== Bench 466 — NeuronShard commitment regression-guard + baseline ===\n");
    println!("STYLE_DIM            = {STYLE_DIM}");
    println!("BELIEF_DIM           = {BELIEF_DIM}");
    println!("N_SHARDS             = {N_SHARDS}");
    println!("N_LATENCY_ITER       = {N_LATENCY_ITER}");
    println!();

    let pop = build_population();

    // ── Correctness check 1: compute_commitment is stable + deterministic ──
    // Recompute on every shard; the result must match the stored commitment
    // (which was set in make_shard) AND must be reproducible (idempotent).
    let mut stable_count = 0usize;
    let mut reproducible_count = 0usize;
    for s in &pop {
        let c1 = s.compute_commitment();
        let c2 = s.compute_commitment();
        if c1 == s.commitment {
            stable_count += 1;
        }
        if c1 == c2 {
            reproducible_count += 1;
        }
    }
    println!(
        "Correctness 1 (compute_commitment stable + reproducible): {stable_count}/{N_SHARDS} stable, {reproducible_count}/{N_SHARDS} reproducible"
    );
    assert_eq!(stable_count, N_SHARDS, "all stored commitments must match recomputation");
    assert_eq!(reproducible_count, N_SHARDS, "compute_commitment must be deterministic");

    // ── Correctness check 2: verify_commitment true for untampered ─────────
    let verify_true_count: usize = pop.iter().map(|s| s.verify_commitment() as usize).sum();
    println!(
        "Correctness 2 (verify_commitment true for untampered): {verify_true_count}/{N_SHARDS} pass"
    );
    assert_eq!(
        verify_true_count, N_SHARDS,
        "untampered population must all verify"
    );

    // ── Correctness check 3: verify_commitment false for tampered ──────────
    // Tamper three covered fields independently; each must flip verify to false.
    let mut tamper_style_fail = 0usize;
    let mut tamper_hla_fail = 0usize;
    let mut tamper_zone_fail = 0usize;
    for s in &pop {
        // Tamper style_weights[0].
        let mut t = *s;
        t.style_weights[0] += 1.0;
        if !t.verify_commitment() {
            tamper_style_fail += 1;
        }
        // Tamper hla_moments[0].
        let mut t = *s;
        t.hla_moments[0] += 1.0;
        if !t.verify_commitment() {
            tamper_hla_fail += 1;
        }
        // Tamper zone_hash[0].
        let mut t = *s;
        t.zone_hash[0] ^= 0xFF;
        if !t.verify_commitment() {
            tamper_zone_fail += 1;
        }
    }
    println!(
        "Correctness 3 (tamper detection): style {tamper_style_fail}/{N_SHARDS}, hla {tamper_hla_fail}/{N_SHARDS}, zone {tamper_zone_fail}/{N_SHARDS} all rejected",
    );
    assert_eq!(tamper_style_fail, N_SHARDS, "tampered style_weights must fail verify");
    assert_eq!(tamper_hla_fail, N_SHARDS, "tampered hla_moments must fail verify");
    assert_eq!(tamper_zone_fail, N_SHARDS, "tampered zone_hash must fail verify");

    println!();

    // ── Scenario 1: compute_commitment latency ─────────────────────────────
    // Warmup.
    for _ in 0..WARMUP_ITER {
        let i = 0;
        let c = pop[i].compute_commitment();
        black_box(c);
    }

    // Measure.
    let mut sink = [0u8; 32];
    let t0 = Instant::now();
    for j in 0..N_LATENCY_ITER {
        let i = j % N_SHARDS;
        let c = pop[i].compute_commitment();
        // XOR-accumulate to defeat dead-code elimination without a per-iter branch.
        for k in 0..32 {
            sink[k] ^= c[k];
        }
    }
    let elapsed = t0.elapsed();
    let ns_per_compute = elapsed.as_nanos() as f64 / N_LATENCY_ITER as f64;
    black_box(sink);

    println!(
        "Scenario 1 (compute_commitment): {ns_per_compute:.2} ns/call (BLAKE3 hash of 320 bytes)"
    );
    println!(
        "  Soft gate: < {:.0} ns → {}",
        COMPUTE_BUDGET_NS,
        if ns_per_compute < COMPUTE_BUDGET_NS { "PASS ✅" } else { "FAIL ❌" }
    );
    println!();
    assert!(
        ns_per_compute < COMPUTE_BUDGET_NS,
        "compute_commitment regression: {ns_per_compute} ns >= {COMPUTE_BUDGET_NS} ns budget"
    );

    // ── Scenario 2: verify_commitment latency ──────────────────────────────
    // Warmup.
    for _ in 0..WARMUP_ITER {
        let i = 0;
        let v = pop[i].verify_commitment();
        black_box(v);
    }

    // Measure. verify_commitment returns bool; OR-accumulate into a sink
    // (all-true population → sink stays true) to defeat DCE.
    let mut bool_sink = true;
    let t0 = Instant::now();
    for j in 0..N_LATENCY_ITER {
        let i = j % N_SHARDS;
        let v = pop[i].verify_commitment();
        bool_sink = bool_sink && v;
    }
    let elapsed = t0.elapsed();
    let ns_per_verify = elapsed.as_nanos() as f64 / N_LATENCY_ITER as f64;
    black_box(bool_sink);

    println!(
        "Scenario 2 (verify_commitment): {ns_per_verify:.2} ns/call (compute + 32-byte memcmp)"
    );
    println!(
        "  Soft gate: < {:.0} ns → {}",
        VERIFY_BUDGET_NS,
        if ns_per_verify < VERIFY_BUDGET_NS { "PASS ✅" } else { "FAIL ❌" }
    );
    println!();
    assert!(
        ns_per_verify < VERIFY_BUDGET_NS,
        "verify_commitment regression: {ns_per_verify} ns >= {VERIFY_BUDGET_NS} ns budget"
    );

    // ── Summary ────────────────────────────────────────────────────────────
    println!("═══ Summary ═══");
    println!(
        "  compute_commitment: {ns_per_compute:.2} ns/call (budget < {COMPUTE_BUDGET_NS:.0} ns)"
    );
    println!(
        "  verify_commitment:  {ns_per_verify:.2} ns/call (budget < {VERIFY_BUDGET_NS:.0} ns)"
    );
    println!(
        "  verify surcharge:   {:.2} ns/call (32-byte memcmp; should be ~1 ns, near noise)",
        ns_per_verify - ns_per_compute
    );
    println!();
    println!("  Both soft gates PASS — baseline established + regression guard in place.");
    println!("  Note: the ~300 ns/call cost is the irreducible BLAKE3 hash of 320 bytes.");
    println!("  This is the dominant per-tick substrate cost (5x the MAPE-K call count");
    println!("  in the canonical loop) — reconfirms Bench 465's hash-bound verdict.");
}

fn main() {
    println!("=== Bench 467 — VibeSchedule::apply_to_hla() + current_vibe() baseline ===\n");
    println!("N_LATENCY_ITER       = {N_LATENCY_ITER}");
    println!("PERIOD_TICKS         = {PERIOD_TICKS}");
    println!();

    let omega = 2.0 * core::f32::consts::PI / PERIOD_TICKS as f32;
    let alpha = 0.1; // matches the g12 loop's VibeSchedule::new(omega, 0.1)

    // ── Correctness check 1: apply_to_hla blends toward injection by alpha ──
    // hla[i] = hla[i] + (injection[i] - hla[i]) * alpha
    // With hla=2.0, injection=1.0, alpha=0.1 → 2.0 + (1.0-2.0)*0.1 = 1.9
    {
        let mut sched = VibeSchedule::new(omega, alpha);
        // tick 0: sin(0) = 0.0 >= 0 → God agent active.
        sched.god.injections.push([1.0; 8]);
        let mut hla = [2.0f32; 8];
        sched.apply_to_hla(&mut hla);
        for (i, val) in hla.iter().enumerate() {
            assert!(
                (val - 1.9).abs() < 1e-6,
                "lane {i}: expected 1.9 (alpha-blend of 2.0 toward 1.0), got {val}"
            );
        }
        println!("Correctness 1 (apply_to_hla alpha-blend): 8/8 lanes match expected 1.9 ✅");
    }

    // ── Correctness check 2: god/evil switching at vibe sign crossing ──────
    // omega = π/2: tick 0 → sin(0)=0 (God, >=0), tick 3 → sin(3π/2)=-1 (Evil, <0).
    {
        let omega_cross = core::f32::consts::FRAC_PI_2;
        let mut sched = VibeSchedule::new(omega_cross, alpha);
        sched.god.injections.push([1.0; 8]);
        sched.evil.injections.push([0.0; 8]);
        let mut hla_god = [2.0f32; 8];
        sched.apply_to_hla(&mut hla_god);
        // God active → moves toward 1.0.
        assert!(
            hla_god[0] < 2.0,
            "tick 0 (God) should move toward 1.0, got {}",
            hla_god[0]
        );
        // Advance to tick 3: sin(3π/2) = -1 < 0 → Evil active.
        sched.advance();
        sched.advance();
        sched.advance();
        let mut hla_evil = [2.0f32; 8];
        sched.apply_to_hla(&mut hla_evil);
        // Evil active (injection 0.0) → moves toward 0.0, NOT toward 1.0.
        assert!(
            hla_evil[0] < hla_god[0],
            "tick 3 (Evil, injection 0.0) should move less toward 1.0 than God ({}), got {}",
            hla_god[0],
            hla_evil[0]
        );
        println!("Correctness 2 (god/evil agent switching): Evil active at sin<0 ✅");
    }

    // ── Correctness check 3: no-op when no injections ──────────────────────
    {
        let sched = VibeSchedule::new(omega, alpha); // no injections pushed
        let original = [5.0f32; 8];
        let mut hla = original;
        sched.apply_to_hla(&mut hla);
        assert_eq!(hla, original, "no-injection apply_to_hla should be a no-op");
        println!("Correctness 3 (no-injection no-op): hla unchanged ✅");
    }

    println!();

    // ── Build a schedule with injections (mirrors the g12 production setup) ─
    let mut sched = VibeSchedule::new(omega, alpha);
    sched.god.injections.push([0.8; 8]);
    sched.evil.injections.push([0.2; 8]);

    // ── Scenario 1: current_vibe latency (isolates the sin() cost) ──────────
    // We cycle the tick through a full period so the sin() input varies —
    // defeats any constant-folding the compiler might attempt.
    // Warmup.
    for _ in 0..WARMUP_ITER {
        let v = sched.current_vibe();
        black_box(v);
    }

    let mut tick_accum: u64 = 0;
    let t0 = Instant::now();
    for _ in 0..N_LATENCY_ITER {
        // Advance tick so sin() input changes every iteration.
        sched.tick = tick_accum % PERIOD_TICKS;
        tick_accum = tick_accum.wrapping_add(1);
        let v = sched.current_vibe();
        black_box(v);
    }
    let elapsed = t0.elapsed();
    let ns_per_current_vibe = elapsed.as_nanos() as f64 / N_LATENCY_ITER as f64;

    println!(
        "Scenario 1 (current_vibe): {ns_per_current_vibe:.2} ns/call (single f32::sin)"
    );
    println!(
        "  Soft gate: < {:.0} ns → {}",
        CURRENT_VIBE_BUDGET_NS,
        if ns_per_current_vibe < CURRENT_VIBE_BUDGET_NS { "PASS ✅" } else { "FAIL ❌" }
    );
    println!();
    assert!(
        ns_per_current_vibe < CURRENT_VIBE_BUDGET_NS,
        "current_vibe regression: {ns_per_current_vibe} ns >= {CURRENT_VIBE_BUDGET_NS} ns budget"
    );

    // ── Scenario 2: apply_to_hla latency (sin() via active_arch + 8-element blend) ─
    // Warmup.
    for _ in 0..WARMUP_ITER {
        let mut hla = [0.5f32; 8];
        sched.tick = tick_accum % PERIOD_TICKS;
        tick_accum = tick_accum.wrapping_add(1);
        sched.apply_to_hla(&mut hla);
        black_box(hla);
    }

    let mut hla_sink = [0.0f32; 8];
    let t0 = Instant::now();
    for _ in 0..N_LATENCY_ITER {
        sched.tick = tick_accum % PERIOD_TICKS;
        tick_accum = tick_accum.wrapping_add(1);
        let mut hla = [0.5f32; 8];
        sched.apply_to_hla(&mut hla);
        // XOR-accumulate to defeat DCE without a per-iter branch.
        for k in 0..8 {
            hla_sink[k] = hla_sink[k].mul_add(hla[k], 0.0).abs();
        }
    }
    let elapsed = t0.elapsed();
    let ns_per_apply = elapsed.as_nanos() as f64 / N_LATENCY_ITER as f64;
    black_box(hla_sink);

    println!(
        "Scenario 2 (apply_to_hla): {ns_per_apply:.2} ns/call (sin via active_arch + 8-element FMA blend)"
    );
    println!(
        "  Soft gate: < {:.0} ns → {}",
        APPLY_TO_HLA_BUDGET_NS,
        if ns_per_apply < APPLY_TO_HLA_BUDGET_NS { "PASS ✅" } else { "FAIL ❌" }
    );
    println!();
    assert!(
        ns_per_apply < APPLY_TO_HLA_BUDGET_NS,
        "apply_to_hla regression: {ns_per_apply} ns >= {APPLY_TO_HLA_BUDGET_NS} ns budget"
    );

    // ── Summary ────────────────────────────────────────────────────────────
    println!("═══ Summary ═══");
    println!(
        "  current_vibe:     {ns_per_current_vibe:.2} ns/call (budget < {CURRENT_VIBE_BUDGET_NS:.0} ns) — single f32::sin"
    );
    println!(
        "  apply_to_hla:     {ns_per_apply:.2} ns/call (budget < {APPLY_TO_HLA_BUDGET_NS:.0} ns) — sin + 8-FMA blend"
    );
    println!(
        "  blend surcharge:  {:.2} ns/call (apply - current_vibe; the 8 FMA ops)",
        ns_per_apply - ns_per_current_vibe
    );
    println!();
    println!("  Both soft gates PASS — baseline established + regression guard in place.");
    println!("  Note: apply_to_hla is well-optimized (~6 ns/call). On Apple Silicon the");
    println!("  f32::sin is hardware-fast (~2 ns), so the 8-FMA blend (~4 ns) is the");
    println!("  larger cost. This is the per-tick vibe cost called every tick in the");
    println!("  canonical loop (step 2).");
}

