    println!("N_LATENCY_ITER     = {N_LATENCY_ITER}");
    println!("WARMUP_ITER        = {WARMUP_ITER}");
    println!();

    // Use a realistic shard count: 1000 mirrors the per-map scale documented
    // in AGENTS.md ("ShardIndex is allocated per-map"). Larger counts exercise
    // a fuller bucket distribution; the papaya read is O(1) regardless.
    const N_SHARDS: usize = 1000;
    println!("N_SHARDS (fixture) = {N_SHARDS}");
    let (index, [present_hash, missing_hash]) = build_fixture(N_SHARDS);

    // ── Correctness check 1: HIT returns Some, MISS returns None ──────────
    let mut hit_ok = 0u32;
    let mut miss_ok = 0u32;
    for _ in 0..10 {
        let guard = index.guard();
        if index.get(&present_hash, &guard).is_some() {
            hit_ok += 1;
        }
        if index.get(&missing_hash, &guard).is_none() {
            miss_ok += 1;
        }
    }
    println!(
        "Correctness 1 (HIT returns Some / MISS returns None over 10 calls each): hit={}/10, miss={}/10 → {}",
        hit_ok,
        miss_ok,
        if hit_ok == 10 && miss_ok == 10 { "PASS ✅" } else { "FAIL ❌" }
    );
    assert_eq!(hit_ok, 10, "HIT path must return Some on all 10 calls");
    assert_eq!(miss_ok, 10, "MISS path must return None on all 10 calls");

    // ── Correctness check 2: returned shard has the expected zone_hash ────
    let guard = index.guard();
    let shard = index.get(&present_hash, &guard).expect("present");
    let returned_zone = shard.zone_hash;
    println!(
        "Correctness 2 (returned shard.zone_hash == present_hash): {} → {}",
        if returned_zone == present_hash { "match" } else { "MISMATCH" },
        if returned_zone == present_hash { "PASS ✅" } else { "FAIL ❌" }
    );
    assert_eq!(
        returned_zone, present_hash,
        "returned shard must carry the queried zone_hash"
    );
    drop(guard);

    println!();

    // ── Scenario 1: guard() alone ─────────────────────────────────────────
    // The papaya epoch guard acquisition. Called once per enter_zone; cheap
    // but not free (thread-local epoch bump + fence on some ISAs).
    for _ in 0..WARMUP_ITER {
        let g = index.guard();
        let _ = black_box(&g);
    }

    let t0 = Instant::now();
    for _ in 0..N_LATENCY_ITER {
        let g = index.guard();
        // Force the guard to be live across the black_box so the compiler
        // can't elide it. The guard's Drop runs at end of iteration.
        let _ = black_box(&g);
    }
    let elapsed = t0.elapsed();
    let ns_per_guard = elapsed.as_nanos() as f64 / N_LATENCY_ITER as f64;

    println!(
        "Scenario 1 (guard() alone): {ns_per_guard:.2} ns/call (papaya epoch guard acquisition)"
    );
    println!(
        "  Soft gate: < {:.0} ns → {}",
        GUARD_BUDGET_NS,
        if ns_per_guard < GUARD_BUDGET_NS { "PASS ✅" } else { "FAIL ❌" }
    );
    println!();
    assert!(
        ns_per_guard < GUARD_BUDGET_NS,
        "guard() regression: {ns_per_guard} ns >= {GUARD_BUDGET_NS} ns budget"
    );

    // ── Scenario 2: get() HIT path ────────────────────────────────────────
    // The per-tick leaf read. guard + hash([u8;32]) + bucket lookup + value
    // pointer read. This is the FIRST papaya op in enter_zone.
    for _ in 0..WARMUP_ITER {
        let g = index.guard();
        let s = index.get(&present_hash, &g);
        let _ = black_box(s);
    }

    let mut sink_zone = [0u8; 32];
    let t0 = Instant::now();
    for _ in 0..N_LATENCY_ITER {
        let g = index.guard();
        if let Some(s) = index.get(&present_hash, &g) {
            // Force a real read of the shard so the compiler can't elide it.
            sink_zone = s.zone_hash;
        }
    }
    let elapsed = t0.elapsed();
    let ns_per_get_hit = elapsed.as_nanos() as f64 / N_LATENCY_ITER as f64;
    black_box(sink_zone);

    println!(
        "Scenario 2 (get() HIT path, {N_SHARDS} shards in index): {ns_per_get_hit:.2} ns/call (guard + hash + bucket lookup + value read)"
    );
    println!(
        "  Soft gate: < {:.0} ns → {}",
        GET_HIT_BUDGET_NS,
        if ns_per_get_hit < GET_HIT_BUDGET_NS { "PASS ✅" } else { "FAIL ❌" }
    );
    assert!(
        ns_per_get_hit < GET_HIT_BUDGET_NS,
        "get() HIT path regression: {ns_per_get_hit} ns >= {GET_HIT_BUDGET_NS} ns budget"
    );

    // ── Scenario 3: get() MISS path ───────────────────────────────────────
    // The per-tick miss path. enter_zone returns Err(NotFound) here, but the
    // guard + lookup still run. Measured separately because the miss path
    // exercises the empty-bucket scan (no value pointer read), which can
    // diverge from the hit path under some papaya configurations.
    for _ in 0..WARMUP_ITER {
        let g = index.guard();
        let s = index.get(&missing_hash, &g);
        let _ = black_box(s);
    }

    let mut sink_count = 0u32;
    let t0 = Instant::now();
    for _ in 0..N_LATENCY_ITER {
        let g = index.guard();
        if index.get(&missing_hash, &g).is_none() {
            sink_count += 1;
        }
    }
    let elapsed = t0.elapsed();
    let ns_per_get_miss = elapsed.as_nanos() as f64 / N_LATENCY_ITER as f64;
    black_box(sink_count);

    println!(
        "Scenario 3 (get() MISS path, key absent): {ns_per_get_miss:.2} ns/call (guard + hash + empty-bucket scan)"
    );
    println!(
        "  Soft gate: < {:.0} ns → {}",
        GET_MISS_BUDGET_NS,
        if ns_per_get_miss < GET_MISS_BUDGET_NS { "PASS ✅" } else { "FAIL ❌" }
    );
    println!();
    assert!(
        ns_per_get_miss < GET_MISS_BUDGET_NS,
        "get() MISS path regression: {ns_per_get_miss} ns >= {GET_MISS_BUDGET_NS} ns budget"
    );

    // ── Summary ───────────────────────────────────────────────────────────
    println!("═══ Summary ═══");
    println!(
        "  guard() alone:     {ns_per_guard:>8.2} ns/call (budget < {GUARD_BUDGET_NS:.0} ns)"
    );
    println!(
        "  get() HIT path:    {ns_per_get_hit:>8.2} ns/call (budget < {GET_HIT_BUDGET_NS:.0} ns)"
    );
    println!(
        "  get() MISS path:   {ns_per_get_miss:>8.2} ns/call (budget < {GET_MISS_BUDGET_NS:.0} ns)"
    );
    println!();
    println!("  All 3 soft gates PASS — baseline established + regression guard in place.");
    println!();
    println!("  Per-enter_zone ShardIndex cost (one guard + one get on the HIT path):");
    println!("    ~{ns_per_get_hit:.1} ns (this is IN ADDITION to the ~46-66 ns ZoneGeometryCache cost measured by bench 469,");
    println!("     because ShardIndex and ZoneGeometryCache are two separate papaya maps).");
    let per_enter_zone_shard_cost = ns_per_get_hit;
    println!(
        "    = ~{per_enter_zone_shard_cost:.1} ns total for the ShardIndex layer alone (excludes the cache layer +"
    );
    println!("     ValidatedZoneView construction, both of which are measured by bench 469).");
}

use riir_neuron_db::experience_graph::graph::{ExperienceGraph, TraversalBudget};
use riir_neuron_db::experience_graph::node::{EMBED_DIM, ExperienceNode, SIBLING_FANOUT};

/// The online budget the OFFLINE-ONLY tag exists to protect (Plan 319 caveat 2).
const ONLINE_BUDGET_US: f64 = 50.0;
/// The offline budget G2b gated against.
const OFFLINE_BUDGET_MS: f64 = 50.0;

/// Queries per cell — T3 asks for query diversity, since one constant vector is
/// a best case (it lands in a fixed neighbourhood every time).
const N_QUERIES: usize = 8;

#[derive(Clone, Copy, PartialEq, Eq)]
enum Topology {
    /// Benchmark 319's shape: a near-linear parent→child chain with ONE sibling
    /// five nodes back. Sparse edges → the BFS frontier grows slowly. This is the
    /// topological best case T3 flags.
    Chain,
    /// A real branching lineage: `SIBLING_FANOUT`-wide levels, every node
    /// carrying a full resolvable sibling set. The BFS frontier expands much
    /// faster, which is what a production experience tree looks like.
    Branching,
}

impl Topology {
    fn label(self) -> &'static str {
        match self {
            Topology::Chain => "chain",
            Topology::Branching => "branching",
        }
    }

impl Rng {
    fn new(seed: u64) -> Self {
        Self(seed | 1)
    }
    fn next_u64(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        self.0 = x;
        x
    }
    /// Uniform in [-1, 1).
    fn signed(&mut self) -> f32 {
        (self.next_u64() >> 40) as f32 / (1u32 << 23) as f32 - 1.0
    }
    fn embedding(&mut self) -> [f32; EMBED_DIM] {
        let mut e = [0.0f32; EMBED_DIM];
        for slot in e.iter_mut() {
            *slot = self.signed();
        }
        e
    }
}

