        }
    }

    // ── T2: locate the online-budget crossing at the CHEAPEST config ──
    println!("\n── T2: crossing ladder, seed_k=4, depth_k=2 (cheapest config) ──");
    println!(
        "{:<11} {:>8} {:>12} {:>10}",
        "topology", "N", "µs/call", "≤50µs?"
    );
    println!("{}", "─".repeat(45));

    let mut crossings: Vec<(Topology, Option<usize>, usize)> = Vec::new();
    for topology in [Topology::Chain, Topology::Branching] {
        let mut last_under = None;
        let mut first_over = 0usize;
        for &n in &[100usize, 250, 500, 1_000, 2_000, 4_000, 8_000] {
            let graph = build_graph(n, topology);
