                topology.label(),
                n,
                us,
                if under { "yes" } else { "NO" }
            );
            if under {
                last_under = Some(n)
            } else if first_over == 0 {
                first_over = n
            }
            drop(graph);
        }
        crossings.push((topology, last_under, first_over));
    }

    // ── Verdicts ──
    println!("\n── T1/T2 verdict ───────────────────────────────────────────────");

    let worst = surface
        .iter()
        .max_by(|a, b| a.4.partial_cmp(&b.4).unwrap())
        .expect("surface non-empty");
    println!(
        "Worst cell: {} N={} seed_k={} depth_k={} → {:.1} µs ({:.3} ms, {:.0}× under the {:.0} ms offline budget)",
        worst.0.label(),
        worst.1,
        worst.2,
        worst.3,
        worst.4,
        worst.4 / 1000.0,
        OFFLINE_BUDGET_MS / (worst.4 / 1000.0),
        OFFLINE_BUDGET_MS
    );

    for (topology, last_under, first_over) in &crossings {
        match last_under {
            None => println!(
                "{:<11} crosses {ONLINE_BUDGET_US:.0} µs at or below the smallest N tested (100) \
                 → NO online sub-regime exists.",
                topology.label()
            ),
            Some(n) => println!(
                "{:<11} stays under {ONLINE_BUDGET_US:.0} µs up to N={n}; first over at N={first_over} \
                 → any online use is bounded by N≤{n} at seed_k=4, depth_k=2.",
                topology.label()
            ),
        }
    }

    // Scaling evidence: is the seed scan really the O(N) term that justifies
    // OFFLINE-ONLY? Compare the same config across N on the chain topology.
    let at = |t: Topology, n: usize, sk: usize, dk: u8| {
        surface
            .iter()
            .find(|r| r.0 == t && r.1 == n && r.2 == sk && r.3 == dk)
            .map(|r| r.4)
            .expect("cell present")
    };
    let (c1k, c10k, c100k) = (
        at(Topology::Chain, 1_000, 8, 3),
        at(Topology::Chain, 10_000, 8, 3),
        at(Topology::Chain, 100_000, 8, 3),
    );
    println!(
        "\nScaling at seed_k=8, depth_k=3 (chain, the G2b config):\n  \
         1k {c1k:.1} µs → 10k {c10k:.1} µs ({:.1}×) → 100k {c100k:.1} µs ({:.1}× vs 1k)",
        c10k / c1k,
        c100k / c1k
    );
    // Report the shape the data actually shows rather than asserting linearity.
    // Measured: sublinear 1k→10k (fixed BFS/dedup cost dominates at small N),
    // then superlinear 10k→100k (the O(N) scan goes memory-bound once the node
    // set exceeds cache — 100k × 696 B ≈ 70 MB).
    let r_1_10 = c10k / c1k;
    let r_10_100 = c100k / c10k;
    println!(
        "  1k→10k is {r_1_10:.1}× for 10× nodes (SUBlinear — fixed BFS/dedup cost dominates);\n  \
         10k→100k is {r_10_100:.1}× for 10× nodes ({}).",
        match r_10_100 > 10.0 {
            true => "SUPERlinear — the O(N) scan goes memory-bound past cache",
            false => "at or below linear",
        }
    );
    println!(
        "  Either way growth is large and real ({:.0}× from 1k to 100k), which is the\n  \
         scaling argument Issue 591 finding A kept — not the 65 µs point measurement.",
        c100k / c1k
    );

    // T3: how much does topology + query diversity move the number?
    println!("\n── T3: topology sensitivity (same cell, both topologies) ───────");
    for &n in &[1_000usize, 10_000, 100_000] {
        let c = at(Topology::Chain, n, 8, 3);
        let b = at(Topology::Branching, n, 8, 3);
        println!(
            "  N={n:<7} seed_k=8 depth_k=3:  chain {c:>9.1} µs   branching {b:>9.1} µs   ({:+.1}%)",
            (b - c) / c * 100.0
        );
    }
    println!(
        "\n  G2b's single-query, chain-topology 65 µs is therefore not a general\n  \
         number — see the benchmark writeup for the honest reading."
    );
}

