// ──────────────────────────────────────────────────────────────────────
// TABLE DEFINITION — explain the annotations
// ──────────────────────────────────────────────────────────────────────
// A NeuronShard is a fixed-size blob with two storage arrays inside it:
//
//   style_weights: [f32; 64]  ← PAYLOAD (raw data, up to 64 slots, 0-63)
//   hla_moments:   [f32; 8]   ← EMBEDDING (for similarity search, 8 slots, 0-7)
//
// The #[shard(...)] annotations tell the derive macro where to put each field:
//
//   payload(N)        → store the raw value at style_weights[N]
//   embed(N, max=M)   → also store a normalized copy (value/M, clamped [0,1])
//                        at hla_moments[N], for similarity queries
//
// The payload index and embed index are INDEPENDENT — they don't need to match.
// payload(0) + embed(3) is fine: raw at slot 0, embedding at slot 3.
// You can also have payload-only fields (no embed) for data you store but
// never search by similarity (e.g. model_num, pattern).

/// Each `#[shard(tag = N)]` must be unique across all ShardRow types in
/// the process — collisions produce silent data loss/corruption.
#[derive(ShardRow, Clone, Debug)]
#[shard(tag = 1)]
struct Zone {
    /// Primary key — stored in zone_hash, used for O(1) lookups by_id().
    #[shard(pk)]
    zone_id: i64,

    /// Raw vibe at style_weights[0], normalized (vibe/1.0) at hla_moments[0].
    /// Indices auto-assigned — no need to type the numbers manually.
    #[shard(payload, embed(max = 1.0))]
    vibe: f32,

    /// Raw heat at style_weights[1], normalized (heat/100.0) at hla_moments[1].
    #[shard(payload, embed(max = 100.0))]
    heat: f32,
}

