#[cfg(feature = "temp_loss_fingerprint")]
impl katgpt_core::diversity::temp::LossKernel for RavenSlotLossKernel {
    fn short_prefix_loss(&self, theta: &[f32], z_prefix: &[f32]) -> f32 {
        // The event's embedding IS its prefix (N = STYLE_DIM for single-event
        // RavenSlots; multi-tick trajectories would pass a longer prefix).
        let len = theta.len().min(z_prefix.len());
        let dot = katgpt_core::simd::simd_dot_f32(theta, z_prefix, len);
        // -log(sigmoid(dot)) = log(1 + exp(-dot)) — numerically stable softplus.
        // Clamped beyond ±40 (sigmoid saturates to 0/1 in f32).
        if dot > 40.0 {
            0.0
        } else if dot < -40.0 {
            -dot
        } else {
            (1.0 + (-dot).exp()).ln()
        }
    }

impl FixtureRng {
    fn new(seed: u64) -> Self {
        Self { state: seed }
    }

    #[inline]
    fn next_u64(&mut self) -> u64 {
        self.state = self.state.wrapping_add(0x9E3779B97F4A7C15);
        let mut z = self.state;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58476D1CE4E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D049BB133111EB);
        z ^ (z >> 31)
    }

    /// Uniform f32 in [0, 1).
    #[inline]
    fn next_f32(&mut self) -> f32 {
        (self.next_u64() >> 40) as f32 * (1.0 / (1u64 << 24) as f32)
    }

    /// Standard-normal f32 via Box-Muller.
    #[inline]
    fn next_gaussian(&mut self) -> f32 {
        let u1 = self.next_f32().max(1e-10);
        let u2 = self.next_f32();
        let r = (-2.0 * u1.ln()).sqrt();
        let theta = 2.0 * core::f32::consts::PI * u2;
        r * theta.cos()
    }
}

