/// Gaussian falloff sigma for projectile threat propagation.
const THREAT_SIGMA: f32 = 4.0;

/// Gaussian falloff sigma for POI anchor notability propagation (Plan 335 T1).
/// Distinct from `THREAT_SIGMA` so the two domains can be tuned independently.
const INTEREST_SIGMA: f32 = 4.0;

/// Sigmoid: `σ(x) = 1 / (1 + e^x)`.
///
/// Uses `e^x` (not `e^{-x}`), so `sigmoid(danger) = 1/(1 + e^{danger})`
/// maps high danger → low safety.
///
/// Only used in tests to validate the SIMD sigmoid output. Production code
/// uses [`simd_sigmoid_inplace`] (Cephes 6th-order polynomial,
/// NEON/AVX2/wasm128 — strictly in (0,1), matches libm to <5e-6).
#[cfg(test)]
#[inline]
fn sigmoid(x: f32) -> f32 {
    1.0 / (1.0 + x.exp())
}

// ---------------------------------------------------------------------------
// cochain_wrapper! — standard 7-method newtype accessor surface (Issue 009)
// ---------------------------------------------------------------------------
//
// All five wrappers below (`SafetyCochain`, `ThreatCochain`, `OccupancyCochain`,
// `DestructionCochain`, `InterestCohain`) are newtypes around `CochainField`
// that expose the same 7-method accessor surface, differing only in:
//   - the field name (`safety` / `threat` / `occupancy` / `destruction` / `interest`)
//   - the rank + dim constants passed to `CochainField::zeros(rank, n_cells, dim)`
//   - the cell-count accessor name on `CellComplex` (`n_vertices` / `n_edges` / `n_faces`)
//
// The macro generates the struct + the 7 accessors. Bespoke constructors
// (`from_projectile_threat`, `from_destroyed_faces`, `from_anchors`) stay as
// hand-written `impl` blocks after the macro invocation — the macro only
// eliminates the boilerplate accessor surface, not the IP-specific bridges.
//
// Why a macro and not a trait: a trait could only dedup 3 of the 7 methods
// (`as_cochain`, `into_cochain`, `n_cells`) — the field-named accessors
// (`<field>`, `set_<field>`, `n_<dim>`) need per-wrapper names. The macro
// dedups all 7, cutting ~30 lines × 5 wrappers = ~150 lines down to 5
// one-liner invocations + the 50-line macro definition.
//
// Why explicit getter+setter names (not `paste::paste!`): identifier
// concatenation in `macro_rules!` requires the `paste` crate. Adding a dep for
// one macro is overkill for a P3 cleanup — passing `set_safety` as an explicit
// token is just as readable and zero-dep.
///
/// Defines a newtype wrapper around `CochainField` with the standard 7-method
/// accessor surface. The wrapper enforces rank + dim invariants via
/// `debug_assert` in `from_cochain`.
///
/// # Arguments
///   - `$name`:      the wrapper struct name (e.g. `SafetyCochain`)
///   - `$get`:       the getter method name (e.g. `safety`)
///   - `$set`:       the setter method name (e.g. `set_safety`)
///   - `$n_cells`:   the `CellComplex` cell-count method (e.g. `n_vertices`)
///   - `$rank`:      the cochain rank (0=vertex, 1=edge, 2=face)
///   - `$dim`:       the per-cell dimension (always 1 for these scalar wrappers)
///
/// # Example
///   ```ignore
///   cochain_wrapper! {
///       #[doc = "Per-vertex safety field. Higher value = safer."]
///       SafetyCochain, safety, set_safety, n_vertices, rank = 0, dim = 1
///   }
///   ```
macro_rules! cochain_wrapper {
    (
        $(#[$meta:meta])*
        $name:ident,
        $get:ident,
        $set:ident,
        $n_cells:ident,
        rank = $rank:expr,
        dim = $dim:expr $(,)?
    ) => {
        $(#[$meta])*
        #[repr(transparent)]
        pub struct $name(CochainField);

        impl $name {
            /// Create a zero-initialized field over the given cell complex.
            #[inline]
            pub fn zeros(cx: &CellComplex) -> Self {
                Self(CochainField::zeros($rank, cx.$n_cells(), $dim))
            }

            /// Wrap an existing cochain. Panics (debug) if rank/dim mismatch.
            #[inline]
            pub fn from_cochain(field: CochainField) -> Self {
                debug_assert_eq!(
                    field.rank, $rank,
                    concat!(stringify!($name), " requires rank ", stringify!($rank))
                );
                debug_assert_eq!(
                    field.dim, $dim,
                    concat!(stringify!($name), " requires dim ", stringify!($dim))
                );
                Self(field)
            }

            /// Read the field value at index `idx`.
            #[inline]
            pub fn $get(&self, idx: usize) -> f32 {
                self.0.scalar(idx)
            }

            /// Write the field value at index `idx`.
            #[inline]
            pub fn $set(&mut self, idx: usize, val: f32) {
                self.0.set_scalar(idx, val);
            }

            /// Borrow the underlying cochain.
            #[inline]
            pub fn as_cochain(&self) -> &CochainField {
                &self.0
            }

            /// Consume and return the underlying cochain.
            #[inline]
            pub fn into_cochain(self) -> CochainField {
                self.0
            }

            /// Number of cells in this field.
            #[inline]
            pub fn $n_cells(&self) -> usize {
                self.0.n_cells()
            }
        }
    }

impl SafetyCochain {
    /// Raw→semantic bridge: convert projectile threats into vertex safety scores.
    ///
    /// For each vertex, accumulate Gaussian-weighted danger from all threat sources,
    /// then project to safety via `sigmoid(-danger)`.
    ///
    /// # Algorithm (spatially pruned splat, Issue riir-neuron-db/003 Layer C)
    ///
    /// The naive loop scanned every threat for every vertex, paying one `exp()`
    /// per (vertex × threat) pair regardless of distance. With `THREAT_SIGMA = 4`,
    /// contributions beyond `R = 3·THREAT_SIGMA = 12` cells are `<
    /// danger_level · exp(−R²/σ) = danger_level · exp(−9) ≈ danger_level ·
    /// 1.2e-4` — negligible after sigmoid saturation. This constructor inverts
    /// the loop nest: for each threat, splat its Gaussian contributions into
    /// the bounded `[tx−R, tx+R] × [ty−R, ty+R]` vertex window.
    ///
    /// For a 100×100 grid × 100 threats this drops the inner-loop `exp()` count
    /// from `10⁶` to `~100 · (2·12)² ≈ 6×10⁴` — a ~17× reduction.
    ///
    /// # Numerical tolerance vs the naive loop
    ///
    /// Output values differ from the naive `for vx, vy { for t in threats }`
    /// loop by at most `~danger_level · exp(−9) / 4 ≈ 3e-5` after sigmoid
    /// projection (worst case at the splat window boundary). This is below
    /// f32 epsilon at the sigmoid's operating point and well below the
    /// semantic resolution of a `[0, 1]` safety score. The existing tests
    /// (`test_safety_from_projectile_threat_*`) assert monotonicity (`near <
    /// far`) and the no-threat baseline (`== 0.5`), both of which are
    /// preserved by construction.
    ///
    /// # Arguments
    /// * `cx` — Cell complex (should be a 2D grid matching `grid_w × grid_h`)
    /// * `grid_w` — Grid width in vertices
    /// * `grid_h` — Grid height in vertices
    /// * `threats` — Slice of `(x, y, danger_level)` in grid coordinates
    pub fn from_projectile_threat(
        cx: &CellComplex,
        grid_w: usize,
        grid_h: usize,
        threats: &[(f32, f32, f32)],
    ) -> Self {
        let mut field = CochainField::zeros(0, cx.n_vertices(), 1);

        // No threats ⇒ danger stays 0 everywhere ⇒ sigmoid(0) = 0.5. Pre-fill
        // the baseline so we can skip the splat + sigmoid passes entirely.
        if threats.is_empty() {
            for v in &mut field.data {
                *v = 0.5;
            }
            return Self(field);
        }
        if grid_w == 0 || grid_h == 0 {
            return Self(field);
        }

        let inv_sigma = 1.0 / THREAT_SIGMA;
        // 3σ cutoff (Issue riir-neuron-db/003): beyond this radius the
        // Gaussian contribution is < exp(−9) ≈ 1.2e-4 × danger_level, which is
        // sigmoid-clamped below f32 epsilon for any plausible danger level.
        let r = 3.0 * THREAT_SIGMA; // = 12.0
        let data = &mut field.data;

        // Stack-allocated exp-factor LUT for the separable Gaussian kernel.
        // The 3σ window has integer width ≤ 2r + 1 = 25 cells; 32 gives
        // headroom for future σ bumps. See `build_threat_cochain` in
        // `zone_geometry.rs` for the full separable-kernel rationale — the
        // 2D Gaussian `exp(-(dx²+dy²)·k)` factors as `exp(-dx²·k)·exp(-dy²·k)`,
        // letting us precompute the x-axis factors once per threat and reuse
        // them across every row. The inner loop drops to a single multiply-add
        // with zero `exp()` calls (vs one per cell in the non-separable form).
        const SEPARABLE_LUT_CAP: usize = 32;
        let mut x_lut = [0.0f32; SEPARABLE_LUT_CAP];

        // Splat: for each threat, accumulate raw danger into the bounded
        // vertex window. Sigmoid is applied in a second pass so the inner
        // splat loop stays branch-free and amenable to auto-vectorization.
        for &(tx, ty, danger_level) in threats {
            // Vertex coords are integers, so the window is the integer range
            // within [tx−R, tx+R] × [ty−R, ty+R], clamped to the grid.
            let vx_lo = (tx - r).ceil().max(0.0) as usize;
            let vx_hi = ((tx + r).floor() as isize)
                .max(-1)
                .min((grid_w as isize) - 1) as usize;
            let vy_lo = (ty - r).ceil().max(0.0) as usize;
            let vy_hi = ((ty + r).floor() as isize)
                .max(-1)
                .min((grid_h as isize) - 1) as usize;

            if vx_hi < vx_lo || vy_hi < vy_lo {
                continue;
            }

            // Precompute x-axis exp factors once per threat: `exp(-dx²·k)`
            // depends only on vx (not vy), so it factors out of the inner loop.
            let x_width = vx_hi - vx_lo + 1;
            debug_assert!(
                x_width <= SEPARABLE_LUT_CAP,
                "safety splat window {x_width} exceeds LUT cap {SEPARABLE_LUT_CAP}"
            );
            for (i, slot) in x_lut[..x_width].iter_mut().enumerate() {
                let vxf = (vx_lo + i) as f32;
                let dx2 = (vxf - tx) * (vxf - tx);
                *slot = (-(dx2 * inv_sigma)).exp();
            }

            for vy in vy_lo..=vy_hi {
                let vyf = vy as f32;
                let dy2 = (vyf - ty) * (vyf - ty);
                // Per-row y factor — once per row instead of per cell.
                let y_factor = (-(dy2 * inv_sigma)).exp();
                let dl_y = -danger_level * y_factor;
                let row_base = vy * grid_w;
                // Branch-free inner loop: one indexed load + one FMA. No exp().
                // `mul_add` guarantees a single FMA instruction regardless of
                // `-C target-cpu` (plain `* +` only contracts under fast-math).
                for (i, vx) in (vx_lo..=vx_hi).enumerate() {
                    let idx = row_base + vx;
                    data[idx] = dl_y.mul_add(x_lut[i], data[idx]);
                }
            }
        }

        // Project raw danger → [0, 1] safety. The splat above accumulates
        // `-danger` (negated at the source via `dl_y`), so applying the
        // standard-polarity SIMD sigmoid `1/(1+e^{-x})` directly yields
        // `1/(1+e^{danger})` — reverse polarity: high danger → low safety.
        // (Cephes 6th-order polynomial, NEON / AVX2 / wasm128 — strictly in
        // (0,1), matches libm to <5e-6.)
        simd_sigmoid_inplace(&mut field.data);

        Self(field)
    }
}

impl DestructionCochain {
    /// Raw→semantic bridge: convert destroyed face set into per-vertex destruction ratio.
    ///
    /// For each vertex, computes `destroyed_incident_faces / max_incident_faces`.
    /// A vertex with no incident faces (degenerate grid) gets destruction = 0.0.
    ///
    /// # Grid layout
    /// Face index `f` maps to grid position `(fx, fy)` where `f = fy * (grid_w - 1) + fx`.
    /// Face `(fx, fy)` has 4 vertices at grid coordinates
    /// `(fx, fy)`, `(fx+1, fy)`, `(fx, fy+1)`, `(fx+1, fy+1)`.
    ///
    /// # Arguments
    /// * `cx` — Cell complex (should be a 2D grid matching `grid_w × grid_h`)
    /// * `grid_w` — Grid width in vertices
    /// * `grid_h` — Grid height in vertices
    /// * `destroyed_face_indices` — Face indices that are destroyed (any
    ///   iterator yielding `usize`; the prod path passes a `&[u32]`-widening
    ///   map without collecting, avoiding a heap alloc per zone AOI regen).
    pub fn from_destroyed_faces(
        cx: &CellComplex,
        grid_w: usize,
        grid_h: usize,
        destroyed_face_indices: impl IntoIterator<Item = usize>,
    ) -> Self {
        let n_vertices = cx.n_vertices();
        let mut field = CochainField::zeros(0, n_vertices, 1);

        // Degenerate grids have no faces — all destruction stays zero.
        if grid_w <= 1 || grid_h <= 1 {
            return Self(field);
        }

        let faces_per_row = grid_w - 1;
        // Loop-invariant grid edges — recomputing `grid_w - 1` / `grid_h - 1`
        // inside the per-vertex loop is pure waste (checklist: hoist
        // loop-invariants). After the `grid_w <= 1 || grid_h <= 1` early return
        // above, both are >= 1.
        let grid_w_m1 = grid_w - 1;
        let grid_h_m1 = grid_h - 1;

        // Count destroyed incident faces per vertex.
        let mut destroyed_count = vec![0u8; n_vertices];

        for f in destroyed_face_indices {
            let fx = f % faces_per_row;
            let fy = f / faces_per_row;

            // 4 corner vertices of face (fx, fy). Derive v10/v01/v11 from v00
            // via additions (one multiply vs four) — checklist: eliminate
            // repeated recomputation of loop-invariant sub-expressions.
            let v00 = fy * grid_w + fx;
            let v10 = v00 + 1;
            let v01 = v00 + grid_w;
            let v11 = v01 + 1;

            destroyed_count[v00] += 1;
            destroyed_count[v10] += 1;
            destroyed_count[v01] += 1;
            destroyed_count[v11] += 1;
        }

        for vy in 0..grid_h {
            // Hoist row base out of the inner vx loop (was `vy * grid_w + vx`
            // recomputed per cell). Now the inner loop is base + vx.
            let row_base = vy * grid_w;
            for vx in 0..grid_w {
                let vidx = row_base + vx;
                let destroyed = destroyed_count[vidx];

                // Max incident faces: vertex (vx, vy) touches faces with
                // fx ∈ {vx-1, vx} ∩ [0, w-2] and fy ∈ {vy-1, vy} ∩ [0, h-2].
                let n_x = (vx > 0) as u32 + (vx < grid_w_m1) as u32;
                let n_y = (vy > 0) as u32 + (vy < grid_h_m1) as u32;
                let max_incident = n_x * n_y;

                let ratio = destroyed as f32 / max_incident as f32;
                field.set_scalar(vidx, ratio);
            }
        }

        Self(field)
    }
}

impl InterestCohain {
    /// Raw→semantic bridge: convert POI anchors into vertex interest scores.
    ///
    /// For each vertex, accumulate Gaussian-weighted notability from all
    /// anchors, then project to interest via `sigmoid(-notability)`.
    ///
    /// The existing `sigmoid(x) = 1/(1 + e^x)` maps high input → low output,
    /// so we pass `-notability` to get the correct interest polarity: high
    /// notability → high interest. With no anchors, notability = 0 everywhere
    /// and interest = `sigmoid(0) = 0.5` — the same baseline convention as
    /// `SafetyCochain::from_projectile_threat`.
    pub fn from_anchors(
        cx: &CellComplex,
        grid_w: usize,
        grid_h: usize,
        anchors: &[(f32, f32, f32)],
    ) -> Self {
        let mut field = CochainField::zeros(0, cx.n_vertices(), 1);

        // No anchors ⇒ notability stays 0 everywhere ⇒ sigmoid(0) = 0.5.
        // Pre-fill the baseline so we can skip the splat + sigmoid passes.
        if anchors.is_empty() {
            for v in &mut field.data {
                *v = 0.5;
            }
            return Self(field);
        }
        if grid_w == 0 || grid_h == 0 {
            return Self(field);
        }

        // Separable Gaussian splat — the same optimization as
        // `SafetyCohain::from_projectile_threat`. The 2D Gaussian
        // `exp(-(dx²+dy²)/σ)` factors as `exp(-dx²/σ) · exp(-dy²/σ)`, letting us
        // precompute the x-axis factors once per anchor and reuse them across
        // every row. The inner loop drops to a single multiply-add with zero
        // `exp()` calls (vs one per cell per anchor in the naive nested loop).
        let inv_sigma = 1.0 / INTEREST_SIGMA;
        // 3σ cutoff: contributions beyond this radius are < exp(−9) ≈ 1.2e-4,
        // sigmoid-clamped below f32 epsilon for any plausible notability level.
        let r = 3.0 * INTEREST_SIGMA;
        const SEPARABLE_LUT_CAP: usize = 32;
        let mut x_lut = [0.0f32; SEPARABLE_LUT_CAP];
        let data = &mut field.data;

        // Splat raw notability into the bounded per-anchor window. Sigmoid is
        // applied in a second pass so the inner splat loop stays branch-free
        // and amenable to auto-vectorization.
        for &(ax, ay, notability_level) in anchors {
            let vx_lo = (ax - r).ceil().max(0.0) as usize;
            let vx_hi = ((ax + r).floor() as isize)
                .max(-1)
                .min((grid_w as isize) - 1) as usize;
            let vy_lo = (ay - r).ceil().max(0.0) as usize;
            let vy_hi = ((ay + r).floor() as isize)
                .max(-1)
                .min((grid_h as isize) - 1) as usize;

            if vx_hi < vx_lo || vy_hi < vy_lo {
                continue;
            }

            // Precompute x-axis exp factors once per anchor: `exp(-dx²·k)`
            // depends only on vx (not vy), so it factors out of the inner loop.
            let x_width = vx_hi - vx_lo + 1;
            debug_assert!(
                x_width <= SEPARABLE_LUT_CAP,
                "interest splat window {x_width} exceeds LUT cap {SEPARABLE_LUT_CAP}"
            );
            for (i, slot) in x_lut[..x_width].iter_mut().enumerate() {
                let vxf = (vx_lo + i) as f32;
                let dx2 = (vxf - ax) * (vxf - ax);
                *slot = (-(dx2 * inv_sigma)).exp();
            }

            for vy in vy_lo..=vy_hi {
                let vyf = vy as f32;
                let dy2 = (vyf - ay) * (vyf - ay);
                // Per-row y factor — once per row instead of per cell.
                let y_factor = (-(dy2 * inv_sigma)).exp();
                let nl_y = notability_level * y_factor;
                let row_base = vy * grid_w;
                // Branch-free inner loop: one indexed load + one FMA. No exp().
                // `mul_add` guarantees a single FMA instruction regardless of
                // `-C target-cpu` (plain `* +` only contracts under fast-math).
                for (i, vx) in (vx_lo..=vx_hi).enumerate() {
                    let idx = row_base + vx;
                    data[idx] = nl_y.mul_add(x_lut[i], data[idx]);
                }
            }
        }

        // Project raw notability → interest. `sigmoid(-x) = 1/(1+e^{-x})`
        // is standard polarity — high notability → high interest. The SIMD
        // sigmoid (Cephes 6th-order polynomial, NEON / AVX2 / wasm128) is a
        // clean 1:1 replacement for the scalar libm-exp loop.
        simd_sigmoid_inplace(&mut field.data);

        Self(field)
    }
}

impl TraversalBudget {
    /// Construct an offline traversal budget. Caller asserts they are NOT in
    /// the per-tick hot loop (caveat 2: 5–10ms BFS vs sub-50µs online budget).
    #[inline]
    pub const fn offline(max_depth: u8) -> Self {
        Self { max_depth }
    }
}

