/// Reward-bearing experience-graph node.
///
/// See the [module docs](self) for the raw vs latent layout explanation.
#[repr(C)]
#[derive(Clone, Copy, Debug, PartialEq, bytemuck::Pod, bytemuck::Zeroable)]
pub struct ExperienceNode {
    // ── raw + syncable (crosses chain quorum bit-identical) ──
    /// Tick at which this node was committed. Drives AS-OF queries.
    pub committed_tick: u64,
    /// Fitness / reward signal (running mean of observed rewards).
    /// Deterministic, replay-reconstructible.
    pub fitness: f32,
    /// UCB1 score (deterministic closed-form `mean + c·sqrt(ln(N)/n)`).
    pub ucb_score: f32,
    /// Visit count. Drives the UCB exploration term.
    pub visit_count: u32,
    /// Cached parent visit count — lets UCB recompute without a graph lookup.
    pub parent_visit_count: u32,
    // ── dual-stream TD value (Issue 592 / GAMER R473) ──
    /// Positive-stream value (TD on raw reward). Tracks success-rate.
    /// Initialized to `fitness` for back-compat; evolved by
    /// [`Self::dual_stream_td_update`]. Stays at `fitness`'s initial value
    /// (`0.0`) if only the single-stream [`Self::update_reward`] path is used.
    pub q_positive: f32,
    /// Negative-stream value (TD on thresholded binary violation `-1 if r<ε`).
    /// Tracks failure-rate independently of magnitude. A 50%/50% +1/−1 action
    /// has E[Q-] < 0 here, distinguishing it from a no-op action (Q- = 0).
    pub q_negative: f32,
    /// Count of observations with `r < ε`. Raw integer counter.
    pub violation_count: u32,
    /// Count of [`Self::dual_stream_td_update`] calls on this node. Distinct
    /// from `visit_count` (which counts single-stream [`Self::update_reward`]
    /// calls). Useful for analytics + future α-annealing. Also keeps the
    /// struct size a multiple of its 8-byte alignment.
    pub dual_stream_step_count: u32,
    /// Zone locator (BLAKE3 of the zone key). Mirrors NeuronShard::zone_hash.
    pub zone_hash: [u8; 32],
    /// Parent node's commitment hash. `[0u8; 32]` = root (no parent).
    /// This IS the NS edge: parent → child.
    pub parent_hash: [u8; 32],
    /// Up to [`SIBLING_FANOUT`] sibling (alternative-action) lineage edges.
    /// `[0u8; 32]` = empty slot. These ARE the NS edges: sibling ↔ sibling.
    pub sibling_hashes: [[u8; 32]; SIBLING_FANOUT],
    /// Reference to the executable artifact. `[0u8; 32]` = no artifact.
    pub artifact_ref: [u8; 32],
    /// BLAKE3 commitment over the raw prefix (fields above). Chain receipt.
    pub commitment: [u8; 32],
    // ── latent + local (NEVER crosses sync as full vector) ──
    /// LoRA-style vibe weights. Projected to scalar rankings at query time.
    pub style_weights: [f32; STYLE_DIM],
    /// Latent seed vector for `latent_seeded_ns_traversal`.
    pub task_embedding: [f32; EMBED_DIM],
}

use super::graph::{ExperienceGraph, TraversalBudget, TraversalHit};
#[cfg(test)]
use super::graph::reconstruct_path;
