/// Maximum node count for which the online envelope was measured safe.
///
/// Set below the measured crossing on purpose — see the module docs.
pub const ONLINE_MAX_NODES: usize = 1_000;

/// Maximum seed fanout inside the online envelope.
pub const ONLINE_MAX_SEED_K: usize = 4;

/// Maximum BFS depth inside the online envelope.
pub const ONLINE_MAX_DEPTH: u8 = 2;

/// The online budget this envelope protects (µs/call), for reference in docs and
/// tests. Not used as a runtime check — latency is not measurable per call
/// without adding cost to the hot path.
pub const ONLINE_BUDGET_US: u32 = 50;

/// A traversal budget that is *provably* inside the measured online envelope.
///
/// Unconstructible outside the envelope, so holding one is evidence the walk's
/// shape is online-safe. The graph's node count is still checked per call.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct OnlineTraversalBudget {
    seed_k: usize,
    max_depth: u8,
}

impl OnlineTraversalBudget {
    /// Build an online budget, or `None` if it falls outside the envelope
    /// measured in Benchmark 478.
    ///
    /// `seed_k == 0` is rejected too: it degenerates to an empty seed set, which
    /// is a caller bug rather than a cheap query.
    pub const fn new(seed_k: usize, max_depth: u8) -> Option<Self> {
        if seed_k >= 1 && seed_k <= ONLINE_MAX_SEED_K && max_depth <= ONLINE_MAX_DEPTH { Some(Self { seed_k, max_depth }) } else { None }
    }

impl std::error::Error for OnlineBudgetExceeded {}

impl ExperienceGraph {
    /// **ONLINE-SAFE** latent-seeded NS traversal, bounded to the envelope
    /// measured in Benchmark 478.
    ///
    /// Unlike [`ExperienceGraph::latent_seeded_ns_traversal`] — which is OFFLINE
    /// ONLY and trusts the caller's [`TraversalBudget`] tag — this checks the
    /// bound it depends on and refuses to run outside it.
    ///
    /// Returns [`OnlineBudgetExceeded`] when the graph has more than
    /// [`ONLINE_MAX_NODES`] nodes. That is not a soft warning: past the envelope
    /// the call costs 78 µs–4.7 ms depending on topology and walk shape, which
    /// would blow a per-tick budget.
    ///
    /// Results are **identical** to the offline entry point given the same
    /// `seed_k` / depth — the walk is shared, not duplicated.
    ///
    /// # Feature flag
    /// `experience_graph` — no new mechanism, so no separate gate: this is a
    /// strictly narrower, bound-enforcing wrapper over already-gated code. The
    /// envelope itself comes from Benchmark 478.
    pub fn latent_seeded_ns_traversal_online(
        &self,
        query: &[f32; EMBED_DIM],
        budget: &OnlineTraversalBudget,
        guard: &impl papaya::Guard,
    ) -> Result<Vec<TraversalHit>, OnlineBudgetExceeded> {
        let node_count = self.len();
        if node_count > ONLINE_MAX_NODES {
            return Err(OnlineBudgetExceeded {
                node_count,
                limit: ONLINE_MAX_NODES,
            });
        }
        // Delegate: one walk implementation, two entry points with different
        // bound-checking obligations.
        Ok(self.latent_seeded_ns_traversal(
            query,
            budget.seed_k(),
            &TraversalBudget::offline(budget.max_depth()),
            guard,
        ))
    }
}

impl MerkleFrozenEnvelope {
    /// Create a new frozen envelope by computing Merkle root over data blocks.
    ///
    /// Each block of `data_blocks` is treated as a leaf in the Merkle tree.
    /// The Merkle root is the tree root, and the envelope commitment is
    /// BLAKE3(magic || version || merkle_root || data_len).
    pub fn freeze(data_blocks: &[&[u8]]) -> Self {
        // Sum + hash leaves in a single pass: avoids a separate O(N) `sum()`
        // walk before the per-block hash walk (saves N iterations + an extra
        // scan over `data_blocks`).
        let mut data_len: u64 = 0;
        let mut leaves: Vec<[u8; 32]> = Vec::with_capacity(data_blocks.len());
        for block in data_blocks {
            data_len = data_len.wrapping_add(block.len() as u64);
            // `blake3::hash(...).as_bytes()` is `&[u8; 32]`; deref gives the
            // fixed array directly without going through `Hash::into()`.
            leaves.push(*blake3::hash(block).as_bytes());
        }

        // Compute Merkle root over data blocks via the shared helper.
        let merkle_root = compute_merkle_root(&leaves);

        // Compute envelope commitment over the 48-byte header prefix
        // (magic || version || merkle_root || data_len). The fields are not
        // contiguous in `self`, so we build a stack buffer and one-shot hash
        // it — same output as streaming `Hasher::update` x4 (BLAKE3 is
        // incremental for single-chunk inputs), with fewer call boundaries.
        let envelope_commitment = {
            let mut hdr = [0u8; 4 + 4 + 32 + 8];
            hdr[..4].copy_from_slice(&FREEZE_MAGIC);
            hdr[4..8].copy_from_slice(&FREEZE_VERSION.to_le_bytes());
            hdr[8..40].copy_from_slice(&merkle_root);
            hdr[40..48].copy_from_slice(&data_len.to_le_bytes());
            *blake3::hash(&hdr).as_bytes()
        };

        Self {
            magic: FREEZE_MAGIC,
            version: FREEZE_VERSION,
            merkle_root,
            data_len,
            envelope_commitment,
        }
    }

    /// Verify that the envelope's commitment matches its contents.
    ///
    /// Recomputes the commitment from the envelope fields and compares.
    pub fn verify_integrity(&self) -> bool {
        // One-shot BLAKE3 over the 48-byte header — identical output to the
        // streaming `update` x4 used by `freeze()`, with fewer call boundaries.
        let mut hdr = [0u8; 4 + 4 + 32 + 8];
        hdr[..4].copy_from_slice(&self.magic);
        hdr[4..8].copy_from_slice(&self.version.to_le_bytes());
        hdr[8..40].copy_from_slice(&self.merkle_root);
        hdr[40..48].copy_from_slice(&self.data_len.to_le_bytes());
        let expected = *blake3::hash(&hdr).as_bytes();
        self.envelope_commitment == expected
    }

    /// Verify that thawed data matches the frozen Merkle root.
    ///
    /// Rebuilds the Merkle tree from the thawed data blocks and compares
    /// the root against the envelope's merkle_root.
    pub fn verify_thaw(&self, data_blocks: &[&[u8]]) -> bool {
        // Fast path: cheap length pre-check using `Iterator::map().sum()`.
        // If lengths differ, root comparison can't possibly match — bail
        // before paying for any BLAKE3 hashing. The length scan is O(N)
        // integer additions (trivially fast vs the O(N) BLAKE3 hashes below).
        let thaw_data_len: u64 = data_blocks.iter().map(|b| b.len() as u64).sum();
        if thaw_data_len != self.data_len {
            return false;
        }

        // Hash leaves in a single walk, then compute the root via the shared
        // helper (same path as `freeze`).
        let mut leaves: Vec<[u8; 32]> = Vec::with_capacity(data_blocks.len());
        for block in data_blocks {
            leaves.push(*blake3::hash(block).as_bytes());
        }
        let thaw_root = compute_merkle_root(&leaves);

        thaw_root == self.merkle_root
    }
}

use crate::shard::{NeuronShard, STYLE_DIM};

// `BELIEF_DIM` is used only in tests (to seed the first 8 lanes with known values).
#[cfg(test)]
use crate::shard::BELIEF_DIM;

/// Number of `style_weights` lanes stored exactly in the frozen sketch.
///
/// Phase 1b MVP used `BELIEF_DIM` (8); G7 (Plan 316 T2.7) showed that the
/// 8-lane head + mean-filled tail overshoots per-shard (1.46× baseline
/// distance) because the mean-fill cannot capture tail variation. Extending
/// the exact head to 32 (half the vector) halves the approximated tail and
/// tightens the G7a quality margin. Still a low-rank sketch (rank-32 of 64),
/// still O(1), still deterministic. Full SVD/PCA remains a future upgrade
/// (Plan 316 Out of Scope) if rank-32 is still insufficient.
pub const SKETCH_DIM: usize = 32;

/// Tick sentinel for "never refreshed". Using 0 (rather than `Option<u64>`)
/// keeps the struct `#[repr(C)]`-friendly and avoids a discriminant byte.
pub const NEVER_REFRESHED: u64 = 0;

/// Frozen 1-layer LOD backup of a shard's last-known-healthy `style_weights`.
///
/// Low-rank sketch: first `BELIEF_DIM` lanes + scalar L2 magnitude. BLAKE3-
/// committed (the full healthy weights' commitment is stored for tamper-
/// evidence). Refreshed ONLY on verified-healthy state via
/// [`refresh_if_healthy`].
///
/// Not `#[repr(C)]` / Pod — this is an auxiliary structure, not part of the
/// zero-copy `NeuronShard` layout. Stored in a [`BackupIndex`] (papaya
/// HashMap) keyed by `zone_hash`.
#[derive(Clone, Debug)]
pub struct FrozenAttractorBackup {
    /// Low-rank sketch: first `SKETCH_DIM` (= 32) lanes of the healthy
    /// `style_weights`. The head `[0..BELIEF_DIM)` (8 lanes) are the
    /// individually-meaningful HLA dimensions;

impl FrozenAttractorBackup {
    /// Freeze a backup from a **verified-healthy** shard.
    ///
    /// **Caller responsibility:** this function does NOT check
    /// `verify_commitment()` or the anomaly flag. It trusts the caller to
    /// have already validated the shard's health. Use
    /// [`refresh_if_healthy`] for the safe refresh path that enforces the
    /// contract. This constructor is `pub` for testing and for callers that
    /// have already performed the health check out-of-band.
    #[inline]
    pub fn freeze_from(shard: &NeuronShard, tick: u64) -> Self {
        // Sketch: first SKETCH_DIM lanes (head = BELIEF_DIM individually-meaningful
        // + extended style lanes to reduce tail reconstruction error).
        let mut sketch = [0.0f32; SKETCH_DIM];
        sketch.copy_from_slice(&shard.style_weights[..SKETCH_DIM]);

        // Magnitude: L2 norm of the full 64-dim vector. FMA chain
        // (`w.mul_add(w, acc)` = `w*w + acc`) halves the op count vs the
        // prior `w * w` + `+=` shape (Rust's default FP-contraction does
        // NOT fuse a separate mul + add).
        let mut mag_sq = 0.0f32;
        for &w in &shard.style_weights {
            mag_sq = w.mul_add(w, mag_sq);
        }
        let magnitude = mag_sq.sqrt();

        // Cache the sketch mean so reconstruct_into doesn't re-scan.
        let sketch_sum: f32 = sketch.iter().copied().sum();
        let sketch_mean = sketch_sum / SKETCH_DIM as f32;

        Self {
            sketch,
            magnitude,
            source_commitment: shard.commitment,
            refresh_tick: tick,
            sketch_mean,
        }
    }

    /// Reconstruct the full `STYLE_DIM`-dim approximation into `out`.
    ///
    /// Head `[0..SKETCH_DIM)`: exact sketch values.
    /// Tail `[SKETCH_DIM..STYLE_DIM)`: sketch mean (constant fill).
    /// This preserves the heal *direction* (the first `SKETCH_DIM` lanes
    /// stored exactly) and approximates the remaining tail with the sketch
    /// mean for scale consistency.
    ///
    /// Zero-allocation: writes into caller-provided `out`.
    #[inline]
    pub fn reconstruct_into(&self, out: &mut [f32; STYLE_DIM]) {
        // Head: exact sketch.
        out[..SKETCH_DIM].copy_from_slice(&self.sketch);

        // Tail: sketch mean (constant fill). The mean of the exact head lanes
        // approximates the average tail lane value — preserves overall scale.
        // G7 showed this mean-fill overshoots when the tail varies (e.g.
        // sinusoidal damage), but the head extension to SKETCH_DIM=32 halves
        // the approximated tail, tightening the reconstruction error.
        let sketch_mean = self.sketch_mean;
        out[SKETCH_DIM..STYLE_DIM].fill(sketch_mean);
    }

    /// Check if this backup is stale relative to `current_tick` and `max_age`.
    ///
    /// A backup is stale if `current_tick - refresh_tick > max_age`. Stale
    /// backups trigger the k-NN refinement fallback in the two-tier dispatch.
    /// `NEVER_REFRESHED` backups are always stale (cold start).
    #[inline]
    pub fn is_stale(&self, current_tick: u64, max_age: u64) -> bool {
        if self.refresh_tick == NEVER_REFRESHED {
            return true;
        }
        current_tick.saturating_sub(self.refresh_tick) > max_age
    }
}

