impl ItemEntry {
    /// Construct from extracted catalog fields, computing the embedding via
    /// schema-centroid init (deterministic, modelless).
    ///
    /// `class_mask` is the raw `ClassMask::bits()` from the catalog; pass
    /// [`CLASS_MASK_UNRESTRICTED`] (0) when the source `class_requirement` was
    /// `None` (the binary loader treats `row.job == 0` as unrestricted).
    pub fn new_from_extract(
        item_id: u32,
        item_type: u32,
        class_mask: u32,
        stats: ItemStats,
    ) -> Self {
        let embedding = item_embedding(item_type, &stats);
        Self {
            embedding,
            item_id,
            item_type,
            class_mask,
            attack: stats.attack,
            defence: stats.defence,
            magic: stats.magic,
            level_req: stats.level_req,
            _pad: 0,
        }
    }

    /// Construct with an explicit embedding (advanced — used by tests that want
    /// to bypass the schema-centroid init to probe retrieval mechanics directly).
    pub fn with_embedding(
        item_id: u32,
        item_type: u32,
        class_mask: u32,
        embedding: [f32; ITEM_EMBED_DIM],
        stats: ItemStats,
    ) -> Self {
        Self {
            embedding,
            item_id,
            item_type,
            class_mask,
            attack: stats.attack,
            defence: stats.defence,
            magic: stats.magic,
            level_req: stats.level_req,
            _pad: 0,
        }
    }

    /// Compute a BLAKE3 commitment over the raw shell fields + the embedding.
    ///
    /// Covers every field except the commitment itself (callers store the result
    /// out-of-band, mirroring how `NeuronShard::commitment` is a separate field).
    pub fn compute_commitment(&self) -> [u8; 32] {
        let mut h = blake3::Hasher::new();
        // Order matters for determinism — keep it stable.
        h.update(&self.item_id.to_le_bytes());
        h.update(&self.item_type.to_le_bytes());
        h.update(&self.class_mask.to_le_bytes());
        h.update(&self.attack.to_le_bytes());
        h.update(&self.defence.to_le_bytes());
        h.update(&self.magic.to_le_bytes());
        h.update(&self.level_req.to_le_bytes());
        h.update(bytemuck::cast_slice::<f32, u8>(&self.embedding));
        *h.finalize().as_bytes()
    }
}

