impl AuditLog {
    /// New empty log with no pre-allocation. Use [`Self::with_capacity`] for
    /// hot paths.
    pub fn new() -> Self {
        Self::default()
    }

    /// New empty log pre-allocated for `cap` entries.
    pub fn with_capacity(cap: usize) -> Self {
        Self {
            entries: Vec::with_capacity(cap),
            #[cfg(feature = "phase_transition_subspace_phase_gate")]
            violation_count: 0,
        }
    }

    /// Append an entry. O(1) amortized; capacity is reused after `clear()`.
    #[inline]
    pub fn record(&mut self, entry: AuditEntry) {
        #[cfg(feature = "phase_transition_subspace_phase_gate")]
        if matches!(entry, AuditEntry::PhaseTransitionViolation(_)) {
            self.violation_count += 1;
        }
        self.entries.push(entry);
    }

    /// Record a phase-transition violation if `Some`. No-op on `None`. Saves
    /// callers a `match` at every call site.
    #[cfg(feature = "phase_transition_subspace_phase_gate")]
    #[inline]
    pub fn record_violation(&mut self, v: Option<PhaseTransitionViolation>) {
        if let Some(v) = v {
            self.violation_count += 1;
            self.entries.push(AuditEntry::PhaseTransitionViolation(v));
        }
    }

    /// Recorded entries, in insertion order.
    #[inline]
    pub fn entries(&self) -> &[AuditEntry] {
        &self.entries
    }

    /// Number of recorded entries.
    #[inline]
    pub fn len(&self) -> usize {
        self.entries.len()
    }

    /// Whether the log is empty.
    #[inline]
    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }

    /// Count of phase-transition violations recorded (T4.1 alerting metric).
    #[cfg(feature = "phase_transition_subspace_phase_gate")]
    pub fn violation_count(&self) -> usize {
        self.violation_count as usize
    }

    /// Clear all entries but keep the backing allocation (zero per-run
    /// allocation across consolidation rounds).
    #[inline]
    pub fn clear(&mut self) {
        self.entries.clear();
        #[cfg(feature = "phase_transition_subspace_phase_gate")]
        {
            self.violation_count = 0;
        }
    }
}

pub use katgpt_device_verify::merkle_verify::{
    EMPTY_HASH, compute_root_from_proof, hash_pair, verify_proof,
};

/// Maximum tree depth. Limits proof size and prevents unbounded allocation.
/// At depth 20, the tree holds up to 2^20 = 1,048,576 leaves (zones).
/// Game worlds rarely exceed 10K zones, so this is generous.
///
/// **This is a hard cap, enforced in every profile** (see [`MAX_LEAVES`]).
/// The level-layout tables are `[_; MAX_DEPTH + 1]` fixed arrays, so a tree
/// built past the cap indexes out of bounds inside `finalize()`. Not every
/// caller is zone-shaped: a per-entry freeze of a crowd-scale trajectory log
/// (10k NPCs × 256 entries = 2.56M leaves) exceeds it. Such callers must
/// chunk their leaves — see [`MerkleTree::extend`].
pub const MAX_DEPTH: usize = 20;

/// Maximum number of leaves a single [`MerkleTree`] can hold (`2^MAX_DEPTH`).
pub const MAX_LEAVES: usize = 1 << MAX_DEPTH;

/// Maximum proof size in hashes. A proof at depth D has D sibling hashes.
/// At MAX_DEPTH=20, a proof is 20 × 32 = 640 bytes.
pub const MAX_PROOF_SIZE: usize = MAX_DEPTH;

// The cap is stated in two places for two different reasons — here it sizes
// the `[_; MAX_DEPTH + 1]` level-layout arrays, upstream it bounds how long a
// path a device will walk before refusing. They must agree, or a proof this
// node can produce is one the device rejects as over-deep. Checked at compile
// time rather than left to a comment.
const _: () = assert!(
    MAX_DEPTH == katgpt_device_verify::merkle_verify::MAX_DEPTH,
    "MAX_DEPTH diverged from katgpt-device-verify: a proof this node produces \
     would be refused by the device as over-deep"
);

// `EMPTY_HASH` moved to `katgpt_device_verify::merkle_verify` and is
// re-exported above. Its correct provenance — it is an opaque pinned
// constant and NOT `BLAKE3("")`, despite what the comment here claimed for
// years — is documented on the definition, and asserted by
// `tests/merkle_device_vectors.rs`. See Issue 606.

/// Binary Merkle tree with pre-allocated internal node storage.
///
/// The tree is built by inserting leaf hashes sequentially, then finalizing
/// to compute the root. This supports the `SyncBlock` use case where zone
/// deltas are accumulated during a tick window and committed at the boundary.
///
/// For the `ShardQuorum` use case, the root is compared across nodes —
/// a mismatch proves Byzantine inconsistency in O(1) time.
pub struct MerkleTree {
    /// Leaf hashes in insertion order.
    leaves: Vec<Hash>,
    /// Pre-allocated internal node cache. Index 0 = root level, 1 = one below root, etc.
    /// Populated by `finalize()`.
    nodes: Vec<Hash>,
    /// Current depth (log2 of leaf count, rounded up). 0 = empty tree.
    depth: u8,
    /// Whether `finalize()` has been called since last insertion.
    finalized: bool,
    /// Cached per-level node counts (immutable post-finalize). Populated by
    /// `finalize()`;

impl MerkleProof {
    /// Verify this proof against an expected root hash.
    ///
    /// This is a pure function — no tree state needed. Can be used by
    /// light clients (BrowserCatchup) that only have the root and proof.
    pub fn verify(&self, leaf_hash: &Hash, root: &Hash) -> bool {
        let computed = compute_root_from_proof(leaf_hash, self.leaf_index, &self.siblings);
        &computed == root
    }

    /// Number of sibling hashes in this proof (= tree depth at insertion).
    pub fn len(&self) -> usize {
        self.siblings.len()
    }

    /// Whether this proof has no siblings (single-leaf tree).
    pub fn is_empty(&self) -> bool {
        self.siblings.is_empty()
    }
}

