use katgpt_core::speculative::types::HealConflictDetector;

/// Post-heal conflict detector for `NeuronShard` `style_weights`.
///
/// Validates that a neighborhood-healed `style_weights` vector is semantically
/// coherent: not degenerate (NaN, zero, uniform), not exploded, and (optionally)
/// close enough to at least one reference archetype.
///
/// # Checks (in order, early-return on first conflict)
///
/// 1. **NaN/Inf** → conflict (degenerate heal output — any lane that is NaN or
///    ±Inf makes the vector unusable).
/// 2. **L2 norm² too small** → conflict (degenerate zero vector — heal produced
///    nothing).
/// 3. **L2 norm² too large** → conflict (exploded vector — heal diverged).
/// 4. **Variance too low** → conflict (all values the same — heal collapsed to
///    uniform, lost all information).
/// 5. **Archetype distance** (optional, when archetypes provided) → conflict if
///    healed vector is too far from ALL reference archetypes (semantically
///    incoherent blend).
///
/// # GOAT Gate (Issue 133)
///
/// - **G1**: detects PoC conflict (blended vector 0.247 from nearest archetype,
///   threshold 0.15).
/// - **G2**: no false positives on normal heal targets.
/// - **G4**: zero-allocation (`is_heal_conflicted` takes `&[f32]`, iterates
///   slices, reads `&self` — no heap allocation on the hot path).
/// - **G5**: modelless (pure threshold checks, no training/backprop).
#[cfg(feature = "heal_validation")]
#[derive(Debug, Clone)]
pub struct ShardConflictDetector {
    /// Minimum L2 norm² (below = degenerate zero vector). Default 0.01 (norm > 0.1).
    min_norm_sq: f32,
    /// Maximum L2 norm² (above = exploded vector). Default 100.0 (norm < 10.0).
    max_norm_sq: f32,
    /// Minimum variance across lanes (below = uniform/degenerate). Default 1e-6.
    min_variance: f32,
    /// Reference archetype vectors for manifold distance check.
    /// Empty = skip archetype distance check (basic checks only).
    /// Allocated at construction (cold path); borrowed immutably on the hot path.
    archetypes: Vec<Vec<f32>>,
    /// Maximum squared L2 distance from nearest archetype.
    /// Healed vector must be within this distance of at least one archetype.
    /// Default 0.0225 (distance 0.15, from the PoC threshold).
    max_archetype_dist_sq: f32,
}

#[cfg(feature = "heal_validation")]
impl HealConflictDetector for ShardConflictDetector {
    /// Check if the healed `style_weights` is semantically conflicted.
    ///
    /// Zero-allocation hot path: iterates over `healed_state` and `&self.archetypes`
    /// slices only. No `Vec`, `String`, or `Box` allocation.
    ///
    /// Returns `true` if ANY check fails (degenerate, exploded, uniform, or
    /// too far from all archetypes).
    #[inline]
    fn is_heal_conflicted(&self, healed_state: &[f32]) -> bool {
        let n = match healed_state.len() {
            0 => return true, // empty = degenerate
            len => len,
        };

        // Single pass: detect NaN/Inf, accumulate sum + sum_of_squares.
        // Early-return on the first NaN/Inf lane — can't do meaningful math
        // with a poisoned vector.
        //
        // FMA: `v.mul_add(v, sum_sq)` = `v*v + sum_sq` — one instruction per
        // lane vs the prior `v * v` + `+=` (two ops, not fused under Rust's
        // default FP-contraction).
        let mut sum: f32 = 0.0;
        let mut sum_sq: f32 = 0.0;
        for &v in healed_state {
            if v.is_nan() || v.is_infinite() {
                return true;
            }
            sum += v;
            sum_sq = v.mul_add(v, sum_sq);
        }

        // Norm² checks (squared form avoids sqrt on the hot path).
        if sum_sq < self.min_norm_sq {
            return true;
        }
        if sum_sq > self.max_norm_sq {
            return true;
        }

        // Variance = E[x²] - E[x]². Computed from the single-pass accumulators.
        // Below threshold = all lanes identical (heal collapsed to uniform).
        let n_f = n as f32;
        let mean = sum / n_f;
        let mean_sq = sum_sq / n_f;
        let variance = mean_sq - mean * mean;
        if variance < self.min_variance {
            return true;
        }

        // Archetype manifold distance (optional). Empty = skip.
        // Compute min L2 distance² to any archetype. If the healed vector is
        // farther than max_archetype_dist_sq from ALL archetypes, it's a
        // semantically incoherent blend.
        if self.archetypes.is_empty() {
            return false;
        }

        let mut min_dist_sq = f32::MAX;
        for archetype in &self.archetypes {
            let len = archetype.len().min(n);
            let mut dist_sq: f32 = 0.0;
            for i in 0..len {
                let d = healed_state[i] - archetype[i];
                dist_sq = d.mul_add(d, dist_sq);
            }
            if dist_sq < min_dist_sq {
                min_dist_sq = dist_sq;
            }
            // Early exit: already within threshold — no conflict from archetypes.
            if min_dist_sq <= self.max_archetype_dist_sq {
                return false;
            }
        }

        // min_dist_sq > max_archetype_dist_sq → too far from all archetypes.
        true
    }

