impl Default for ReconQualityTracker {
    fn default() -> Self {
        Self {
            module_metrics: core::array::from_fn(|i| ModuleReconQuality {
                kind_disc: i as u8,
                ..Default::default()
            }),
            // Pre-allocate to MAX_ZONES: avoids ~8 reallocations (log2(256))
            // as the tracker fills toward capacity on the record() hot path.
            zone_metrics: Vec::with_capacity(MAX_ZONES),
            zone_index: HashMap::with_capacity(MAX_ZONES),
            // Field order: u64 first (8-aligned after HashMap), then the two
            // f32s packed together — eliminates 8 bytes of padding vs.
            // f32/u64/f32 ordering (280B vs 288B per tracker).
            total_evaluations: 0,
            global_avg_recall: 0.0,
            global_best_recall: 0.0,
        }
    }
}

impl ReconQualityTracker {
    /// Create a new empty tracker.
    pub fn new() -> Self {
        Self::default()
    }

    /// Record a reconstruction evaluation result.
    ///
    /// Updates per-module and global aggregates. O(1) for module update,
    /// O(Z) for zone lookup where Z = number of tracked zones.
    pub fn record(
        &mut self,
        kind_disc: u8,
        recall: f32,
        evidence: f32,
        steps: u8,
        zone_id: Option<u64>,
        epoch: u32,
    ) {
        let idx = kind_disc as usize;
        if idx >= MAX_MODULES {
            return;
        }

        let m = &mut self.module_metrics[idx];

        // Update running average via incremental mean (FMA contraction:
        // avg*n + recall → mul_add — single rounding, slightly more accurate).
        let n = m.n_evaluations as f32;
        let new_n = n + 1.0;
        let inv_new_n = 1.0 / new_n;
        m.avg_recall = m.avg_recall.mul_add(n, recall) * inv_new_n;
        m.avg_evidence = m.avg_evidence.mul_add(n, evidence) * inv_new_n;
        m.typical_steps = steps;
        m.n_evaluations += 1;
        m.epoch = epoch;

        m.best_recall = m.best_recall.max(recall);
        // Maintain the cached global running max so best_recall_any() is O(1).
        self.global_best_recall = self.global_best_recall.max(recall);

        // Update global average.
        let gn = self.total_evaluations as f32;
        let new_gn = gn + 1.0;
        let inv_new_gn = 1.0 / new_gn;
        self.global_avg_recall = self.global_avg_recall.mul_add(gn, recall) * inv_new_gn;
        self.total_evaluations += 1;

        // Update zone metric if provided.
        if let Some(zid) = zone_id {
            self.record_zone(zid, recall);
        }
    }

    /// Record zone-level reconstruction quality.
    //
    // O(1) lookup via `zone_index`. The previous `Vec::iter_mut().find()` was
    // O(Z) per record — at MAX_ZONES=256 this became the dominant cost when
    // the tracker filled. `zone_index` is updated in lockstep with
    // `zone_metrics.push` so the two never drift; new zones only land in the
    // index once they've been accepted (under the `MAX_ZONES` cap).
    fn record_zone(&mut self, zone_id: u64, recall: f32) {
        if let Some(&slot) = self.zone_index.get(&zone_id) {
            let zone = &mut self.zone_metrics[slot];
            let n = zone.n_reconstructions as f32;
            let new_n = n + 1.0;
            zone.avg_recall = zone.avg_recall.mul_add(n, recall) / new_n;
            zone.n_reconstructions += 1;
        } else if self.zone_metrics.len() < MAX_ZONES {
            let slot = self.zone_metrics.len();
            self.zone_metrics.push(ZoneReconQuality {
                zone_id,
                avg_recall: recall,
                n_reconstructions: 1,
            });
            self.zone_index.insert(zone_id, slot);
        }
    }

    /// Get quality metrics for a specific module. O(1).
    pub fn module_quality(&self, kind_disc: u8) -> Option<&ModuleReconQuality> {
        let idx = kind_disc as usize;
        if idx < MAX_MODULES && self.module_metrics[idx].n_evaluations > 0 {
            Some(&self.module_metrics[idx])
        } else {
            None
        }
    }

    /// Get quality metrics for a specific zone. O(1) via `zone_index`.
    pub fn zone_quality(&self, zone_id: u64) -> Option<&ZoneReconQuality> {
        self.zone_index
            .get(&zone_id)
            .map(|&slot| &self.zone_metrics[slot])
    }

    /// Global average recall across all modules and zones. O(1).
    #[inline]
    pub fn global_avg_recall(&self) -> f32 {
        self.global_avg_recall
    }

    /// Total number of tracked evaluations. O(1).
    #[inline]
    pub fn total_evaluations(&self) -> u64 {
        self.total_evaluations
    }

    /// Best recall across all modules. O(1) — reads the cached running max
    /// maintained in `record()`.
    #[inline]
    pub fn best_recall_any(&self) -> f32 {
        self.global_best_recall
    }

    /// Number of modules with at least one evaluation.
    pub fn active_module_count(&self) -> usize {
        self.module_metrics
            .iter()
            .filter(|m| m.n_evaluations > 0)
            .count()
    }

    /// Number of tracked zones.
    #[inline]
    pub fn zone_count(&self) -> usize {
        self.zone_metrics.len()
    }

    /// Check if reconstruction quality meets a threshold.
    ///
    /// Returns `true` if global average recall ≥ threshold.
    pub fn meets_threshold(&self, threshold: f32) -> bool {
        self.global_avg_recall >= threshold
    }

    /// Export a summary for logging/monitoring.
    pub fn summary(&self) -> ReconQualitySummary {
        // Single pass over module_metrics: collect active entries AND count
        // them. The prior implementation called `active_module_count()`
        // separately, which iterated module_metrics a second time. Inlining
        // the count saves one O(MAX_MODULES) walk per summary.
        let mut per_kind = Vec::with_capacity(MAX_MODULES);
        let mut active_modules = 0usize;
        for m in &self.module_metrics {
            if m.n_evaluations > 0 {
                per_kind.push((m.kind_disc, m.avg_recall, m.best_recall));
                active_modules += 1;
            }
        }

        ReconQualitySummary {
            global_avg_recall: self.global_avg_recall,
            total_evaluations: self.total_evaluations,
            active_modules,
            zones_tracked: self.zone_metrics.len(),
            per_kind,
        }
    }
}

