impl ShardSerializeBuf {
    /// Create a new zero-initialized serialization buffer.
    pub fn new() -> Self {
        Self {
            buf: [0u8; SHARD_BUF_SIZE],
            len: 0,
        }
    }

    /// Clear the buffer for reuse (zero allocation).
    /// Only resets the length — the underlying buffer is overwritten on next
    /// `serialize_into` call, so zeroing is unnecessary.
    pub fn clear(&mut self) {
        self.len = 0;
    }

    /// Get the written bytes.
    pub fn as_bytes(&self) -> &[u8] {
        &self.buf[..self.len]
    }

    /// Get a mutable reference to the underlying buffer.
    pub fn buf_mut(&mut self) -> &mut [u8; SHARD_BUF_SIZE] {
        &mut self.buf
    }

    /// Set the written length.
    pub fn set_len(&mut self, len: usize) {
        debug_assert!(len <= SHARD_BUF_SIZE);
        self.len = len;
    }
}

impl ShardDeserializeBuf {
    /// Create a new zero-initialized deserialization buffer.
    pub fn new() -> Self {
        Self {
            buf: [0u8; SHARD_BUF_SIZE],
            len: 0,
        }
    }

    /// Load bytes into the buffer for deserialization.
    pub fn load(&mut self, data: &[u8]) -> Result<(), ShardError> {
        if data.len() > SHARD_BUF_SIZE {
            return Err(ShardError::BufferTooSmall {
                need: data.len(),
                have: SHARD_BUF_SIZE,
            });
        }
        self.buf[..data.len()].copy_from_slice(data);
        self.len = data.len();
        Ok(())
    }

    /// Get the loaded bytes.
    pub fn as_bytes(&self) -> &[u8] {
        &self.buf[..self.len]
    }
}

impl ShardQuery for NeuronShard {
    fn query_into(&self, context: &[f32; BELIEF_DIM], out: &mut [f32; BELIEF_DIM]) {
        // Cosine similarity — delegates to the unrolled index::cosine_sim
        let sim = super::index::cosine_sim(context, &self.hla_moments);

        // Project style_weights to BELIEF_DIM via group averaging, scaled by similarity.
        // group_size = STYLE_DIM / BELIEF_DIM = 8. Fixed 8-iteration loop is fully
        // unrolled so each `avg * sim` becomes a single SIMD FMA lane with no
        // bounds checks.
        //
        // Fold the `/ GROUP_SIZE` and `* sim` into one per-lane multiplier
        // (`scale`) computed once. Without this, each lane would compile to
        // `sum * 0.125 * sim` (two muls); with it, each lane is `sum * scale`
        // (one mul). Saves 8 multiplies across the unroll.
        const GROUP_SIZE: usize = STYLE_DIM / BELIEF_DIM;
        let scale = sim * (1.0 / GROUP_SIZE as f32);
        let w = &self.style_weights;
        // Manual 8-way unroll (BELIEF_DIM=8 is fixed). Group offsets: 0, 8, 16, ...,
        // 56. Each lane sums 8 weights then multiplies by `scale`.
        out[0] = (w[0] + w[1] + w[2] + w[3] + w[4] + w[5] + w[6] + w[7]) * scale;
        out[1] = (w[8] + w[9] + w[10] + w[11] + w[12] + w[13] + w[14] + w[15]) * scale;
        out[2] = (w[16] + w[17] + w[18] + w[19] + w[20] + w[21] + w[22] + w[23]) * scale;
        out[3] = (w[24] + w[25] + w[26] + w[27] + w[28] + w[29] + w[30] + w[31]) * scale;
        out[4] = (w[32] + w[33] + w[34] + w[35] + w[36] + w[37] + w[38] + w[39]) * scale;
        out[5] = (w[40] + w[41] + w[42] + w[43] + w[44] + w[45] + w[46] + w[47]) * scale;
        out[6] = (w[48] + w[49] + w[50] + w[51] + w[52] + w[53] + w[54] + w[55]) * scale;
        out[7] = (w[56] + w[57] + w[58] + w[59] + w[60] + w[61] + w[62] + w[63]) * scale;
    }
}

