pub use crate::sense_training::*;

// ── Spectral Shard Initialization (Plan 269) ───────────────
// Note: spectral_flatness() utility lives in spectral_flatness.rs — same module.

#[cfg(feature = "spectral_shard")]
impl NeuronShard {
    /// Create a spectrally initialized shard from a zone hash.
    ///
    /// Derives `style_weights` deterministically from `zone_hash` via BLAKE3
    /// chain hashing, then normalizes to unit sphere (matching the paper's
    /// initialization on S^{|G|-1}). This is the "lottery ticket" mechanism:
    /// different zone_hashes → different spectral modes → ensemble diversification.
    ///
    /// The randomness is at initialization (committed on chain), not at runtime
    /// (which would break consensus). All nodes derive the SAME weights from the
    /// SAME zone_hash deterministically.
    ///
    /// `new()` keeps current behavior (all-zeros init) for backward compat.
    pub fn new_spectral(zone_hash: [u8; 32]) -> Self {
        // Derive STYLE_DIM f32 values from zone_hash via BLAKE3 XOF
        let mut hasher = blake3::Hasher::new();
        hasher.update(&zone_hash);
        hasher.update(b"spectral_shard_v1");
        let mut xof = hasher.finalize_xof();

        let mut style_weights = [0.0f32; STYLE_DIM];
        // One bulk XOF pull (STYLE_DIM * 4 bytes) instead of STYLE_DIM
        // per-element `xof.fill(&mut [0u8; 4])` calls. BLAKE3 XOF amortizes
        // the pull cost across the whole output. The LE-cast is byte-identical
        // to the per-element `u32::from_le_bytes` on a LE host (the crate-wide
        // `const _` assert in `load_sense_module` enforces LE).
        let mut rand_bytes = [0u8; STYLE_DIM * 4];
        xof.fill(&mut rand_bytes);
        let bits_slice: &[u32] = bytemuck::cast_slice(&rand_bytes);
        // Precomputed reciprocal — replaces a per-element division with a
        // (cheaper, FMA-able) multiplication. `u32::MAX as f32 * 0.5` is the
        // exact value the prior form recomputed every iteration.
        const INV_HALF_U32_MAX: f32 = 1.0 / (u32::MAX as f32 * 0.5);
        for (w, &bits) in style_weights.iter_mut().zip(bits_slice) {
            // Use sigmoid-like mapping: map [0, 2^32) → [-1, 1]
            // Using sign-magnitude: top bit = sign, rest = magnitude
            let sign = if bits & 1 == 0 { 1.0f32 } else { -1.0f32 };
            let magnitude = (bits >> 1) as f32 * INV_HALF_U32_MAX;
            *w = sign * magnitude;
        }

        // Normalize to unit sphere (L2 norm = 1)
        // Chunk-4 dot product for SIMD, then single sqrt + divide
        //
        // IMPORTANT: the exact association order is consensus-load-bearing —
        // `compute_commitment()` hashes `style_weights`, so any change in
        // rounding shifts every spectral shard's commitment. Keep the
        // `(... + ...) + (...) + acc` per-chunk form unchanged across
        // refactors unless you intend a hard chain-state fork.
        let mut norm_sq: f32 = 0.0;
        let mut i = 0;
        while i + 4 <= STYLE_DIM {
            norm_sq += style_weights[i] * style_weights[i]
                + style_weights[i + 1] * style_weights[i + 1]
                + style_weights[i + 2] * style_weights[i + 2]
                + style_weights[i + 3] * style_weights[i + 3];
            i += 4;
        }

        let inv_norm = 1.0 / norm_sq.sqrt().max(1e-8);
        i = 0;
        while i + 4 <= STYLE_DIM {
            style_weights[i] *= inv_norm;
            style_weights[i + 1] *= inv_norm;
            style_weights[i + 2] *= inv_norm;
            style_weights[i + 3] *= inv_norm;
            i += 4;
        }

        let mut shard = Self {
            zone_hash,
            style_weights,
            hla_moments: [0.0; BELIEF_DIM],
            wallet_snapshot: WALLET_NONE,
            dual_u_snapshot: DUAL_U_NONE,
            commitment: [0u8; 32],
            merkle_root: [0u8; 32],
            #[cfg(feature = "state_compression")]
            compressed_root: [0u8; 32],
        };
        shard.commitment = shard.compute_commitment();
        shard
    }
}

impl ArchAgent {
    /// Returns the number of injection patterns.
    #[inline]
    pub fn injection_count(&self) -> usize {
        self.injections.len()
    }
}

impl VibeSchedule {
    /// Create a new schedule with default zero-initialized agents.
    pub fn new(omega: f32, alpha: f32) -> Self {
        let default_agent = || ArchAgent {
            goal: [0.0; 8],
            injections: Vec::new(),
            rotation: 0.0,
        };
        Self {
            tick: 0,
            omega,
            alpha,
            god: default_agent(),
            evil: default_agent(),
        }
    }

    /// Current vibe value: `sin(tick * omega)`.
    #[inline]
    pub fn current_vibe(&self) -> f32 {
        (self.tick as f32 * self.omega).sin()
    }

    /// Map the current vibe value to a phase.
    #[inline]
    pub fn current_phase(&self) -> VibePhase {
        let v = self.current_vibe();
        if v >= 0.7 {
            VibePhase::God
        } else if v >= 0.0 {
            VibePhase::Awakening
        } else if v >= -0.7 {
            VibePhase::Evil
        } else {
            VibePhase::Darkening
        }
    }

    /// Return the active arch-agent based on current vibe sign.
    #[inline]
    pub fn active_arch(&self) -> &ArchAgent {
        if self.current_vibe() >= 0.0 {
            &self.god
        } else {
            &self.evil
        }
    }

    /// Blend the active agent's first injection into `hla` using alpha.
    ///
    /// `hla[i] = hla[i] + (injection[i] - hla[i]) * alpha`
    ///
    /// No-op when the active agent has no injections.
    ///
    /// Algebraically equivalent to `hla * (1-α) + injection * α`, but lowers
    /// to one FMA per lane via `f32::mul_add` instead of two muls + one add,
    /// and avoids the `(1-α)` cancellation hazard at small α. The 8-element
    /// blend is fully unrolled so LLVM emits a single SIMD FMA chain.
    pub fn apply_to_hla(&self, hla: &mut [f32; 8]) {
        let agent = self.active_arch();
        if let Some(injection) = agent.injections.first() {
            let a = self.alpha;
            hla[0] = (injection[0] - hla[0]).mul_add(a, hla[0]);
            hla[1] = (injection[1] - hla[1]).mul_add(a, hla[1]);
            hla[2] = (injection[2] - hla[2]).mul_add(a, hla[2]);
            hla[3] = (injection[3] - hla[3]).mul_add(a, hla[3]);
            hla[4] = (injection[4] - hla[4]).mul_add(a, hla[4]);
            hla[5] = (injection[5] - hla[5]).mul_add(a, hla[5]);
            hla[6] = (injection[6] - hla[6]).mul_add(a, hla[6]);
            hla[7] = (injection[7] - hla[7]).mul_add(a, hla[7]);
        }
    }

    /// Advance the world tick by 1.
    #[inline]
    pub fn advance(&mut self) {
        self.tick += 1;
    }

    /// Return the active agent's injections as a slice.
    #[inline]
    pub fn active_injections(&self) -> &[[f32; 8]] {
        self.active_arch().injections.as_slice()
    }
}

impl ZoneCohainKind {
    /// DEC rank of the underlying cochain (0/1/2). Used by readers to size
    /// per-cochain SoA slices via the cell counts in the header.
    #[inline]
    pub const fn rank(self) -> u8 {
        match self {
            ZoneCohainKind::Safety => 0,
            ZoneCohainKind::Threat => 1,
            ZoneCohainKind::Occupancy => 2,
            ZoneCohainKind::Destruction => 0,
            ZoneCohainKind::Interest => 0,
        }
    }

    /// Parse a discriminant byte back into the enum. Returns `None` for
    /// unknown values (forward-compat: future kinds are rejected rather
    /// than misinterpreted).
    #[inline]
    pub const fn from_u8(v: u8) -> Option<Self> {
        match v {
            0 => Some(ZoneCohainKind::Safety),
            1 => Some(ZoneCohainKind::Threat),
            2 => Some(ZoneCohainKind::Occupancy),
            3 => Some(ZoneCohainKind::Destruction),
            4 => Some(ZoneCohainKind::Interest),
            _ => None,
        }
    }
}

impl ZoneGeometryPod {
    /// Deterministic regen from chain-committed shard + info-brain raw state.
    ///
    /// Each node calls this at zone AOI entry. Output is bit-identical across
    /// nodes given identical `shard + raw state` (two-brain: info brain is
    /// ground truth; no think-brain / fog-of-war inputs cross this boundary).
    ///
    /// # Determinism contract
    /// Uses **sequential loops only** — no rayon, no FP reduction-order
    /// nondeterminism. The body bytes are written in a fixed order: cochains
    /// in `cochain_kinds` slot order, then the two eggshell matrices.
    ///
    /// # Arguments
    /// * `shard` — chain-committed source-of-truth shard (style_weights drive
    ///   the eggshell projection).
    /// * `shard_blake3` — precomputed BLAKE3 of `shard` (caller owns the hash
    ///   so the pod doesn't recompute it; the caller already had it from the
    ///   freeze/thaw envelope).
    /// * `grid_w`, `grid_h` — grid dimensions in vertices.
    /// * `topology_version` — caller-declared topology version. Bumped by the
    ///   caller when terrain destruction occurs; passed through verbatim so
    ///   readers can detect pod staleness without recomputing.
    /// * `destroyed_faces` — face indices removed from the grid (drive the
    ///   DestructionCohain). The underlying `CellComplex` topology itself is
    ///   NOT mutated in Phase 0 (face removal is a Phase 2 concern); only the
    ///   destruction *cochain* reflects this list.
    /// * `threats` — raw projectile triplets `(x, y, danger)` in grid coords.
    /// * `occupancy` — raw per-face NPC count. Length should equal
    ///   `(grid_w - 1) * (grid_h - 1)`; extra entries are ignored, missing
    ///   entries default to zero.
    /// * `interest_anchors` — raw POI triplets `(x, y, notability)`.
    #[allow(clippy::too_many_arguments)]
    pub fn regen_from_shard_and_raw(
        shard: &NeuronShard,
        shard_blake3: [u8; 32],
        grid_w: u32,
        grid_h: u32,
        topology_version: u32,
        destroyed_faces: &[u32],
        threats: &[(f32, f32, f32)],
        occupancy: &[f32],
        interest_anchors: &[(f32, f32, f32)],
    ) -> Self {
        // 1. Build the topology. Face removal is deferred to Phase 2 — Phase 0
        //    regen uses the pristine grid. The DestructionCochain still records
        //    the destroyed set so readers can reason about it; the topology
        //    version bump is the signal that the *grid* has diverged.
        let cx = CellComplex::grid_2d(grid_w as usize, grid_h as usize);

        let n_vertices = cx.n_vertices() as u32;
        let n_edges = cx.n_edges() as u32;
        let n_faces = cx.n_faces() as u32;

        // 2. Build the typed cochains. Order is fixed (Safety, Threat,
        //    Occupancy, Destruction, Interest) so the body byte layout is
        //    deterministic regardless of HashMap iteration order etc.
        let safety =
            SafetyCochain::from_projectile_threat(&cx, grid_w as usize, grid_h as usize, threats);

        let threat = build_threat_cochain(&cx, grid_w as usize, grid_h as usize, threats);

        let occupancy_field = build_occupancy_cochain(&cx, occupancy);

        let destruction = DestructionCochain::from_destroyed_faces(
            &cx,
            grid_w as usize,
            grid_h as usize,
            destroyed_faces.iter().map(|&f| f as usize),
        );

        // Interest cochain is wired in: `crate::dec_arena::InterestCohain::from_anchors`
        // (migrated from katgpt-dec on 2026-06-28, katgpt-rs Issue 008).
        let interest_field: Option<MaybeInterest> = {
            let interest = build_interest_cochain(&cx, grid_w, grid_h, interest_anchors);
            Some(interest)
        };

        // 3. Build the eggshell at vertex 0 (canonical sample — Phase 0 only
        //    packs one eggshell pair; per-vertex eggshells are a Phase 4
        //    hot-loop concern). Lanes are projected from `shard.style_weights`.
        let eggshell = LatCalEggshell::project_from(
            shard,
            &safety,
            &threat,
            &occupancy_field,
            &destruction,
            interest_field.as_ref(),
            0,
        );

        // 4. Pack the body in fixed order: cochains (in slot order) then
        //    the two eggshell `[f32; 4]` matrices. Sequential writes — no
        //    rayon — to guarantee byte-determinism.
        let mut cochain_kinds = [0u8; ZONEGEO_MAX_COCHAINS];
        let mut slot = 0usize;

        // Pre-size the body. Each cochain contributes `n_cells_of_rank * 4`
        // bytes; the eggshell contributes `2 * 4 * 4 = 32` bytes.
        let mut body_cap = 2 * 4 * 4; // eggshell
        body_cap += n_vertices as usize * 4; // safety
        body_cap += n_edges as usize * 4; // threat
        body_cap += n_faces as usize * 4; // occupancy
        body_cap += n_vertices as usize * 4; // destruction
        body_cap += n_vertices as usize * 4; // interest
        // `with_capacity` skips the empty-then-`reserve_exact` dance —
        // same final allocation, one fewer state transition.
        let mut body = Vec::with_capacity(body_cap);

        push_cochain_soa(&mut body, safety.as_cochain());
        cochain_kinds[slot] = ZoneCohainKind::Safety as u8;
        slot += 1;

        push_cochain_soa(&mut body, threat.as_cochain());
        cochain_kinds[slot] = ZoneCohainKind::Threat as u8;
        slot += 1;

        push_cochain_soa(&mut body, occupancy_field.as_cochain());
        cochain_kinds[slot] = ZoneCohainKind::Occupancy as u8;
        slot += 1;

        push_cochain_soa(&mut body, destruction.as_cochain());
        cochain_kinds[slot] = ZoneCohainKind::Destruction as u8;
        slot += 1;

        if let Some(ref ic) = interest_field {
            push_cochain_soa(&mut body, ic.as_cochain());
            cochain_kinds[slot] = ZoneCohainKind::Interest as u8;
            slot += 1;
        }

        // Eggshell lanes — fixed two `[f32; 4]` matrices.
        body.extend_from_slice(bytemuck::cast_slice(&eggshell.matrix[0]));
        body.extend_from_slice(bytemuck::cast_slice(&eggshell.matrix[1]));

        let cochain_count = slot as u8;

        let header = ZoneGeometryPodHeader {
            magic: ZONEGEO_MAGIC,
            format_version: ZONEGEO_FORMAT_VERSION,
            cochain_count,
            eggshell_count: 2,
            _pad0: [0; 4],
            topology_version,
            grid_w,
            grid_h,
            n_vertices,
            n_edges,
            n_faces,
            cochain_kinds,
            blake3_source_shard: shard_blake3,
            _pad1: [0; 32],
            _pad2: [0; 16],
        };

        Self { header, body }
    }
}

impl ZoneGeometryPod {
    /// Serialize header + body to a single contiguous byte buffer.
    ///
    /// Layout: `[header: 128 bytes][body: body.len() bytes]`. Cold-path only
    /// (zone save); the allocation here is acceptable.
    pub fn to_bytes(&self) -> Vec<u8> {
        let mut out = Vec::with_capacity(size_of::<ZoneGeometryPodHeader>() + self.body.len());
        out.extend_from_slice(bytemuck::bytes_of(&self.header));
        out.extend_from_slice(&self.body);
        out
    }

    /// Parse a pod from bytes. Validates magic and format version only.
    ///
    /// Body length is sanity-checked against the header's declared topology
    /// (it must be large enough to hold the declared cochain data + eggshell).
    /// Does NOT validate `blake3_source_shard` — callers do that separately
    /// via [`validate_source_shard`](Self::validate_source_shard) once they
    /// have the current shard hash in hand.
    pub fn from_bytes(bytes: &[u8]) -> Result<Self, ZoneValidationError> {
        let hdr_size = size_of::<ZoneGeometryPodHeader>();
        if bytes.len() < hdr_size {
            return Err(ZoneValidationError::BodyTooShort);
        }

        let header: &ZoneGeometryPodHeader = bytemuck::from_bytes(&bytes[..hdr_size]);

        if header.magic != ZONEGEO_MAGIC {
            return Err(ZoneValidationError::MagicMismatch);
        }
        if header.format_version != ZONEGEO_FORMAT_VERSION {
            return Err(ZoneValidationError::FormatVersionUnsupported(
                header.format_version,
            ));
        }

        let body = bytes[hdr_size..].to_vec();

        // Sanity-check: body must fit at least the two eggshell matrices
        // (2 × 4 × sizeof(f32) = 32 bytes). Deeper per-cochain sizing is
        // the consumer's responsibility (Phase 2 will add strict checks).
        let min_body = 2 * 4 * size_of::<f32>();
        if body.len() < min_body {
            return Err(ZoneValidationError::BodyTooShort);
        }

        Ok(Self {
            header: *header,
            body,
        })
    }

    /// Validate the embedded source-shard hash against the recomputed shard hash.
    ///
    /// Returns `true` iff the pod was generated from the shard the caller is
    /// currently holding. Mismatch ⇒ the pod is stale (the shard was frozen
    /// / thawed since the pod was generated) and should be regenerated.
    #[inline]
    pub fn validate_source_shard(&self, current_shard_hash: [u8; 32]) -> bool {
        self.header.blake3_source_shard == current_shard_hash
    }

    /// Cross-shard validation — full `Result` form of `validate_source_shard`.
    ///
    /// Checks (in order): magic, format version, embedded `blake3_source_shard`
    /// equality with `shard_blake3`. Returns the first failure as a typed
    /// [`ZoneValidationError`]. Used by the cache loader (T2.3) and any quorum
    /// validator that needs the typed error rather than a bool.
    ///
    /// Body integrity is intentionally NOT checked here — the body is a derived
    /// artifact; if the header hash matches, the body was produced from the
    /// matching shard by a deterministic regen, so a matching hash transitively
    /// vouches for the body. (Tamper tests confirm: tampering the *header*
    /// hash flips the verdict; tampering the body alone leaves the hash match
    /// intact, which is the designed contract — the hash is the commitment.)
    pub fn validate_against_shard(
        &self,
        shard_blake3: [u8; 32],
    ) -> Result<(), ZoneValidationError> {
        if self.header.magic != ZONEGEO_MAGIC {
            return Err(ZoneValidationError::MagicMismatch);
        }
        if self.header.format_version != ZONEGEO_FORMAT_VERSION {
            return Err(ZoneValidationError::FormatVersionUnsupported(
                self.header.format_version,
            ));
        }
        if self.header.blake3_source_shard != shard_blake3 {
            return Err(ZoneValidationError::SourceShardHashMismatch {
                expected: shard_blake3,
                found: self.header.blake3_source_shard,
            });
        }
        Ok(())
    }
}

impl ZoneGeometryPod {
    /// Atomic disk write — header + body as one contiguous buffer.
    ///
    /// Writes to a temp file in the same directory, then `rename`s over the
    /// target. Atomic on Unix (single-syscall rename); best-effort on Windows.
    /// The temp name embeds the process id + a counter to avoid collisions
    /// under concurrent saves of different pods.
    ///
    /// Cold path (zone save / freeze). Writes header + body directly to the
    /// file — no intermediate buffer allocation.
    pub fn save_to_path(&self, path: &std::path::Path) -> std::io::Result<()> {
        use std::io::Write;

        // Build a sibling temp path in the same directory so the rename stays
        // within one filesystem (atomic on Unix). Same-dir is required for
        // rename atomicity — cross-device rename would fall back to copy+unlink.
        let dir = path
            .parent()
            .ok_or_else(|| std::io::Error::other("save_to_path: path has no parent"))?;
        std::fs::create_dir_all(dir)?;

        static COUNTER: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
        let seq = COUNTER.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        let pid = std::process::id();
        let tmp_name = format!(
            ".zonegeo.tmp.{}.{pid}.{seq}",
            // Fall back to a fixed suffix if the OS refuses unusual chars in
            // file names; the rename target is what matters, not the temp name.
            path.file_name()
                .and_then(|s| s.to_str())
                .unwrap_or("pod")
                .replace(|c: char| std::path::is_separator(c), "_")
        );
        let tmp_path = dir.join(tmp_name);

        // Write + fsync the temp file before rename so a crash never leaves a
        // half-written pod at the final path. fsync-of-data, then rename, is
        // the standard durable-write recipe.
        {
            let mut f = std::fs::File::create(&tmp_path)?;
            f.write_all(bytemuck::bytes_of(&self.header))?;
            f.write_all(&self.body)?;
            f.flush()?;
            // Sync the file data. `sync_all` covers both data + metadata on
            // Unix; on Windows it's a no-op-ish flush. Acceptable for a cold
            // path where durability matters more than throughput.
            f.sync_all()?;
        }

        // Atomic rename over the target.
        std::fs::rename(&tmp_path, path)?;
        Ok(())
    }
}

impl LatCalEggshell {
    /// Project from shard `style_weights` + cochain combo → eggshell lanes.
    ///
    /// Deterministic given identical shard. The `x / y / z` projection is a
    /// deterministic weighted sum over `style_weights`:
    /// ```text
    ///   x = style_weights[0]
    ///   y = style_weights[1]
    ///   z = style_weights[2]
    /// ```
    /// Simple, fast, and deterministic. Phase 4 (hot-loop eggshell) may
    /// upgrade this to a learned direction-vector projection without
    /// breaking the on-disk layout (the projection is recomputed at load,
    /// not stored).
    ///
    /// When `interest` is `None`, the `matrix[1][0]` (interest) lane is zero
    /// — the determinant check then degenerates to `−occupancy · threat`.
    /// Destruction is threaded through (Issue 023 T2, 2026-07-17): the eggshell
    /// no longer hardcodes `destruction_v = 0.0`; callers must supply the
    /// same `DestructionCochain` they packed into the pod body so the eggshell
    /// lane reflects the actual per-vertex destruction ratio.
    pub fn project_from(
        shard: &NeuronShard,
        safety: &SafetyCochain,
        threat: &ThreatCochain,
        occupancy: &OccupancyCochain,
        destruction: &DestructionCochain,
        interest: Option<InterestCohainRef<'_>>,
        vertex_idx: usize,
    ) -> Self {
        // Style projection — first three components. `style_weights` is
        // `[f32; STYLE_DIM]` (STYLE_DIM=64), so direct indexing is safe and
        // lets LLVM elide the three `.get()` bounds checks that
        // `.first().copied().unwrap_or(...)` / `.get(n).copied().unwrap_or(...)`
        // emit. The `unwrap_or(0.0)` fallback can never fire (64 >= 3).
        let x = shard.style_weights[0];
        let y = shard.style_weights[1];
        let z = shard.style_weights[2];

        // Cochain scalars at the chosen vertex / incident cells. For
        // rank-mismatched lookups (threat is per-edge, occupancy is per-face)
        // we read at the cell index closest to `vertex_idx` — a degenerate
        // but deterministic choice for the Phase 0 single-vertex sample.
        // Phase 4 will replace this with proper vertex→incident-cell reduction.
        let safety_v = safety.safety(vertex_idx);

        let threat_v = if vertex_idx < threat.n_edges() {
            threat.threat(vertex_idx)
        } else {
            0.0
        };
        let occupancy_v = if vertex_idx < occupancy.n_faces() {
            occupancy.occupancy(vertex_idx)
        } else {
            0.0
        };

        // Destruction lives on `DestructionCochain` — threaded through
        // (Issue 023 T2, 2026-07-17) so the eggshell lane matches the pod
        // body's per-vertex destruction ratio instead of being hardcoded to
        // zero. Rank-mismatched read follows the same pattern as threat /
        // occupancy below (read at the vertex index, degenerate but
        // deterministic).
        let destruction_v = if vertex_idx < destruction.n_vertices() {
            destruction.destruction(vertex_idx)
        } else {
            0.0
        };

        // Interest lane: read the typed cochain scalar when present; zero
        // (determinant degenerates to `−occupancy · threat`) when absent.
        let interest_v = interest.map_or(0.0, |ic| {
            if vertex_idx < ic.n_vertices() {
                ic.interest(vertex_idx)
            } else {
                0.0
            }
        });

        Self {
            matrix: [
                [x, y, z, safety_v],
                [interest_v, occupancy_v, threat_v, destruction_v],
            ],
        }
    }

    /// `det[0] = matrix[0][0] · matrix[0][3] − matrix[0][1] · matrix[0][2]`.
    ///
    /// Commitment check: `x · safety − y · z`.
    #[inline]
    pub fn det0(&self) -> f32 {
        self.matrix[0][0] * self.matrix[0][3] - self.matrix[0][1] * self.matrix[0][2]
    }

    /// `det[1] = matrix[1][0] · matrix[1][3] − matrix[1][1] · matrix[1][2]`.
    ///
    /// Viability index: `interest · destruction − occupancy · threat`.
    /// Load-bearing — this is the determinant the validator checks.
    #[inline]
    pub fn det1(&self) -> f32 {
        self.matrix[1][0] * self.matrix[1][3] - self.matrix[1][1] * self.matrix[1][2]
    }

    /// Local LatCal determinant check. Matches the semantics of
    /// `riir_chain::encoding::latcal::validate_determinant`: the
    /// load-bearing viability index `det[1]` must equal `secret` within
    /// `1e-6` tolerance.
    ///
    /// Full LatCal fidelity (commitment proofs, quorum validation) is
    /// delegated to the chain layer when needed — this leaf crate does not
    /// pull a riir-chain dependency.
    #[inline]
    pub fn validate(&self, secret: f32) -> bool {
        (self.det1() - secret).abs() < 1e-6
    }
}

