fn full_rank_shard() -> NeuronShard {
    let mut weights = [0.0f32; STYLE_DIM];
    let n = STYLE_WEIGHTS_RESHAPE_N;
    for i in 0..n {
        weights[i * n + i] = (i as f32) * 2.0 + 1.0;
    }
    let mut s = NeuronShard::new([0x42; 32]);
    s.style_weights = weights;
    s.commitment = s.compute_commitment();
    s
}

fn g1_valid_runs_pass() -> bool {
    let dag = collimation_dag();
    let verifier = TrainingWorkflowVerifier;
    let mut pass_count = 0usize;
    for seed in 0..10u64 {
        let run = valid_run(seed);
        let result = verifier.verify(
            &dag,
            &[
                "raw_dataset",
                "curation_config",
                "adapter_config",
                "base_model",
                "sweep_config",
                "attribution_config",
                "validation_config",
            ],
            &run.initial_context,
            Some(&run),
        );
        if result.passed {
            pass_count += 1;
        } else {
            eprintln!("[G1] seed {seed} FAILED:\n{}", result.summary());
        }
    }
    let tpr = pass_count as f32 / 10.0;
    eprintln!("[G1] true_positive_rate = {tpr} ({pass_count}/10)");
    tpr == 1.0
}

