fn matvec_f32(w: &[f32], rows: usize, cols: usize, x: &[f32], out: &mut [f32]) {
    for r in 0..rows {
        let mut acc = 0.0f32;
        for c in 0..cols {
            acc += w[r * cols + c] * x[c];
        }
        out[r] = acc;
    }

fn matvec_f64(m: &[f64], rows: usize, cols: usize, v: &[f64], out: &mut [f64]) {
    for r in 0..rows {
        let mut acc = 0.0f64;
        for c in 0..cols {
            acc += m[r * cols + c] * v[c];
        }
        out[r] = acc;
    }

fn norm_f64(v: &[f64]) -> f64 {
    v.iter().map(|x| x * x).sum::<f64>().sqrt()
}

/// Top-k singular values via power iteration on a deflating f64 copy.
/// Start vectors are LCG-deterministic per component → before/after runs
/// are comparable to ~1e-4 relative (far under the 3 dB gate's resolution).
fn top_singular_values(w: &[f32], rows: usize, cols: usize, k: usize, iters: usize) -> Vec<f64> {
    let mut m: Vec<f64> = w.iter().map(|x| *x as f64).collect();

fn g1_function_preservation_gates() {
    // Fixed synthetic pair: W1 [8×5] → W2 [3×8]; deterministic values.
    let lcg = |s: &mut u64| -> f32 {
        *s = s
            .wrapping_mul(6364136223846793005)
            .wrapping_add(1442695040888963407);
        (((*s >> 33) as i32 as f32) / 2147483648.0) - 1.0
    };
    let mut st = 0x1234_5678_9ABC_DEF0u64;
    let rows1 = 8usize;
    let cols1 = 5usize;
    let mut w1 = Vec::with_capacity(rows1 * cols1);
    for _ in 0..rows1 * cols1 {
        w1.push(lcg(&mut st));
    }
    let rows2 = 3usize;
    let mut w2 = Vec::with_capacity(rows2 * rows1);
    for _ in 0..rows2 * rows1 {
        w2.push(lcg(&mut st));
    }
    let mut x = Vec::with_capacity(cols1);
    for _ in 0..cols1 {
        x.push(lcg(&mut st));
    }

    // Greedy row order on W1 → P
    let w1_rows: Vec<Vec<f32>> = (0..rows1)
        .map(|r| w1[r * cols1..(r + 1) * cols1].to_vec())
        .collect();
    let order = greedy_order_l1(&w1_rows);

    // Gate (a): row-permuted matvec is BIT-IDENTICAL per element (each
    // output is the same dot product over the same summation order,
    // relocated). P·(W1·x)[i] == (W1·x)[order[i]] bitwise.
    let w1p = permute_rows(&w1, rows1, cols1, &order);
    let mut y0 = vec![0.0f32; rows1];
    let mut yp = vec![0.0f32; rows1];
    matvec_f32(&w1, rows1, cols1, &x, &mut y0);
    matvec_f32(&w1p, rows1, cols1, &x, &mut yp);
    for i in 0..rows1 {
        assert!(
            yp[i].to_bits() == y0[order[i]].to_bits(),
            "G1(a) FAILED: row-permuted matvec not bit-identical at {i}"
        );
    }

    // Gate (b): materialized pair (P·W1, W2·Pᵀ) computes the same function
    // as (W1, W2) — exact-arithmetic identity (PᵀP = I); fp reassociation
    // bounds the check to a tight relative tolerance.
    let w2p = permute_cols(&w2, rows2, rows1, &order);
    let mut h = vec![0.0f32; rows1];
    let mut h_orig = vec![0.0f32; rows1];
    let mut out_orig = vec![0.0f32; rows2];
    let mut out_perm = vec![0.0f32; rows2];
    matvec_f32(&w1, rows1, cols1, &x, &mut h_orig);
    matvec_f32(&w2, rows2, rows1, &h_orig, &mut out_orig);
    matvec_f32(&w1p, rows1, cols1, &x, &mut h);
    matvec_f32(&w2p, rows2, rows1, &h, &mut out_perm);
    for i in 0..rows2 {
        let denom = out_orig[i].abs().max(1.0);
        assert!(
            ((out_perm[i] - out_orig[i]) / denom).abs() < 1e-4,
            "G1(b) FAILED: composed pair diverged at {i}: {} vs {}",
            out_perm[i],
            out_orig[i]
        );
    }

    // Gate (c): activation-reorder path is BIT-IDENTICAL — un-permute the
    // intermediate (pure index reorder) and reuse the ORIGINAL W2.
    let mut h_back = vec![0.0f32; rows1];
    for i in 0..rows1 {
        h_back[order[i]] = h[i]; // h = P·(W1·x) ⇒ h_back == W1·x bitwise
    }
    let mut out_reorder = vec![0.0f32; rows2];
    matvec_f32(&w2, rows2, rows1, &h_back, &mut out_reorder);
    for i in 0..rows2 {
        assert!(
            out_reorder[i].to_bits() == out_orig[i].to_bits(),
            "G1(c) FAILED: activation-reorder path not bit-identical at {i}"
        );
    }
    println!(
        "[G1] function-preservation gates: (a) row-permuted matvec bit-identical, (b) materialized pair == original (rel < 1e-4, exact-arithmetic identity), (c) activation-reorder path bit-identical — ALL PASS"
    );
}

