impl Lcg {
    fn new(seed: u64) -> Self {
        Self(seed)
    }
    /// Uniform in [0, 1).
    fn next_f32(&mut self) -> f32 {
        self.0 = self
            .0
            .wrapping_mul(1_664_525)
            .wrapping_add(1_013_904_223);
        // Take the high 24 bits so the mantissa is filled without touching the
        // exponent field (the LCG-leaks-into-exponent bug from riir-ai Issue 693).
        ((self.0 >> 40) as f32) / ((1u32 << 24) as f32)
    }
}

