fn arm6_destructive_edits() {
    println!("\n── Arm 6 — destructive edits: the WIN that should not count ──");
    println!(
        "  The T5.1 run surfaced a case that every shipped gate passes and no shipped gate\n  \
         should have passed:\n\n    \
         too_many_arguments:  fn f(a,b,c,d,e,f,g,h)  →  fn f(a,b,c,d,e,g,h)\n\n  \
         L4 DELETED parameter `f`. Seven args is under the lint threshold, so the lint\n  \
         clears and `ClippyVerifier` scores WIN — correctly, by its stated metric.\n  \
         `RustAnalyzerPruner` checks the output PARSES; `ClippyVerifier` checks the lint\n  \
         CLEARED. Neither checks that behaviour is preserved.\n"
    );

    // The asymmetry: a REGRESSION is caught (lint still fires), a DESTRUCTIVE edit
    // is not. So the measured WIN rate is an UPPER BOUND on the usable p_win.
    println!(
        "  Consequence for this model: the verifier cannot distinguish WIN from\n  \
         DESTRUCTIVE, so a measured win count is `p_win + p_dest`, i.e. an UPPER BOUND\n  \
         on the win rate the break-even surface may be fed.\n"
    );

    let c_esc = 900.0f32; // 15 min — the cheapest row where promotion was reachable
    let l = latencies()
        .into_iter()
        .find(|x| x.deployment)
        .expect("deployment latency defined")
        .secs;

    println!(
        "  At c_esc = {:.0} min and L = {l:.1}s, how many destructive edits sink a promotion?\n",
        c_esc / 60.0
    );
    println!(
        "  {:<26}{:>12}{:>14}{:>16}",
        "c_destructive / c_esc", "3 true wins", "+1 destructive", "verdict"
    );
    for ratio in [1.0f32, 2.0, 5.0, 10.0] {
        let c_dest = ratio * c_esc;
        let clean = net_benefit_with_destructive(
            3.0 / REACHABLE as f32,
            0.0,
            0.0,
            c_esc,
            0.0,
            c_dest,
            l,
        );
        let with_dest = net_benefit_with_destructive(
            3.0 / REACHABLE as f32,
            0.0,
            1.0 / REACHABLE as f32,
            c_esc,
            0.0,
            c_dest,
            l,
        );
        println!(
            "  {:<26}{:>12}{:>14}{:>16}",
            format!("{ratio:.0}×"),
            format!("{clean:+.0}s"),
            format!("{with_dest:+.0}s"),
            match with_dest > 0.0 {
                true => "still positive",
                false => "SUNK",
            }
        );
    }

    println!(
        "\n  At c_destructive = 5× the escalation cost, ONE destructive edit in nine cancels\n  \
         three genuine wins. Since the destructive class is invisible to both shipped\n  \
         gates, its rate is currently UNMEASURED — which is itself the finding.\n\n  \
         → T5.3 acceptance clause (added on this evidence): a WIN count is not admissible\n    \
         as `p_win` until it is decomposed into semantics-preserving vs destructive. A\n    \
         no-op (`output == input`) must not score, and neither may an edit that resolves a\n    \
         lint by removing code. Absent that decomposition the measured WIN rate is an\n    \
         upper bound and promotion cannot be justified from it."
    );

    // Guard the asymmetry claim the clause rests on.
    let c = 900.0f32;
    assert!(
        net_benefit_with_destructive(3.0 / 9.0, 0.0, 1.0 / 9.0, c, 0.0, 5.0 * c, l) < 0.0,
        "the destructive-edit penalty no longer sinks a 3-win promotion at 5× — \
         re-derive Arm 6's clause"
    );
}

