    println!(
        "\n  Warm vs cold daemon over the {REACHABLE}-case reachable set:\n    \
         warm (shipped: one spawn, {DAEMON_LOAD_SECS:.1}s amortised) : {:.0}s + {DAEMON_LOAD_SECS:.0}s load = {:.0}s\n    \
         cold (hypothetical spawn-per-fix)                : {:.0}s  ({:.1}× worse)\n  \
         The load is {:.1}× a single fix, so `DaemonL4` holding the process open is\n  \
         load-bearing for G2, not an optimisation.",
        warm_total,
        warm_total + DAEMON_LOAD_SECS,
        cold_total,
        cold_total / (warm_total + DAEMON_LOAD_SECS),
        DAEMON_LOAD_SECS / deploy
    );
}

use std::io::BufRead;

fn main() {
    let mut path = String::from("data/plan342/genrm_holdout.jsonl");
    let mut scores_path: Option<String> = None;
    // Plan 342 T1.2 closeout: label the scores column for what it IS — a
    // prompted judge, a trained verifier readout, a floor. The table lies
    // otherwise (a verifier's row labelled "prompted_judge" is a silent
    // misattribution).
    let mut name = String::from("prompted_judge");
    let args: Vec<String> = std::env::args().collect();
    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "--holdout" => {
                i += 1;
                path = args.get(i).cloned().unwrap_or_else(|| {
                    eprintln!("--holdout needs a path");
                    std::process::exit(2);
                });
            }
            "--scores" => {
                i += 1;
                scores_path = Some(args.get(i).cloned().unwrap_or_else(|| {
                    eprintln!("--scores needs a path");
                    std::process::exit(2);
                }));
            }
            "--name" => {
                i += 1;
                name = args.get(i).cloned().unwrap_or_else(|| {
                    eprintln!("--name needs a label");
                    std::process::exit(2);
                });
            }
            other => {
                eprintln!("unknown arg: {other}");
                std::process::exit(2);
            }
        }
        i += 1;
    }

    if let Some(sp) = scores_path {
        report_scores(&sp, &name);
        return;
    }

    let file = std::fs::File::open(&path).unwrap_or_else(|e| {
        eprintln!("failed to open {path}: {e}");
        std::process::exit(2);
    });

    let mut texts: Vec<String> = Vec::new();
    let mut labels: Vec<bool> = Vec::new();
    let mut unparseable = 0usize;
    for line in std::io::BufReader::new(file).lines().map_while(Result::ok) {
        if line.trim().is_empty() {
            continue;
        }
        let v: serde_json::Value = match serde_json::from_str(&line) {
            Ok(v) => v,
            Err(_) => continue,
        };
        let (Some(t), Some(l)) = (v["text"].as_str(), v["label"].as_str()) else {
            continue;
        };
        // Parse now so an unreadable row is COUNTED, never scored 0.5 — a
        // floor that invents a score for a row it could not read is reporting
        // itself rather than the data.
        if genrm_floors::parse_genrm_prompt(t).is_none() {
            unparseable += 1;
            continue;
        }
        texts.push(t.to_string());
        labels.push(l.eq_ignore_ascii_case("yes"));
    }

    let n = texts.len();
    let pos = labels.iter().filter(|l| **l).count();
    println!("Plan 342 G1 — MODELLESS FLOORS on {path}");
    println!("  rows scored : {n}  ({pos} Yes / {} No)", n - pos);
    println!("  unparseable : {unparseable} (excluded, not scored 0.5)");
    if n == 0 {
        eprintln!("no scoreable rows");
        std::process::exit(2);
    }

    // How much of the corpus a compile-gate floor could even speak to.
    let compilable = texts
        .iter()
        .filter_map(|t| genrm_floors::parse_genrm_prompt(t))
        .filter(genrm_floors::compile_gate_available)
        .count();
    println!(
        "  compile-gate applicable to {compilable}/{n} rows ({:.1}%) — the rest are\n\
         \x20   in-crate excerpts (Plan 341 Bench 490 measured v3 at 86.6% non-compiling\n\
         \x20   standalone), so a compile-gate accept rate here would describe the\n\
         \x20   HARNESS, not the fix.",
        100.0 * compilable as f64 / n as f64
    );
    println!();
    println!(
        "  {:<16}{:>8}{:>8}{:>10}{:>12}",
        "floor", "AUC", "ECE", "FAR@0.5", "thr@FAR<=2%"
    );

    for f in FLOORS {
        let scores: Vec<f32> = texts
            .iter()
            .map(|t| {
                let p = genrm_floors::parse_genrm_prompt(t).expect("pre-filtered");
                (f.score)(&p)
            })
            .collect();
        let auc = genrm::roc_auc(&scores, &labels);
        let ece = genrm::expected_calibration_error(&scores, &labels, 10);
        let far = genrm::false_accept_rate(&scores, &labels, 0.5);
        let thr = genrm::threshold_for_false_accept(&scores, &labels, 0.02);
        let thr_s = match thr.is_finite() {
            true => format!("{thr:.4}"),
            false => "none".to_string(),
        };
        println!("  {:<16}{auc:>8.4}{ece:>8.4}{far:>10.4}{thr_s:>12}", f.name);
    }

    // T1.4 asks for the reliability curve alongside ECE, and it is the half
    // that says WHY a number is what it is: `combined` has the best AUC and
    // nearly the worst ECE, which only reads as "ranks well, is not a
    // probability" once the per-bin gap is visible. Printed for the strongest
    // floor, since that is the one a trained verifier is measured against.
    if let Some(best) = FLOORS.last() {
        let scores: Vec<f32> = texts
            .iter()
            .map(|t| (best.score)(&genrm_floors::parse_genrm_prompt(t).expect("pre-filtered")))
            .collect();
        println!();
        println!(
            "  reliability curve — {} (10 bins; empty bins retained)",
            best.name
        );
        println!(
            "  {:>12}{:>8}{:>12}{:>12}{:>10}",
            "bin", "n", "confidence", "accuracy", "gap"
        );
        for b in genrm::reliability_curve(&scores, &labels, 10) {
            let gap = b.mean_accuracy - b.mean_confidence;
            let bin = format!("[{:.1},{:.1})", b.lo, b.hi);
            match b.count {
                // An empty bin is kept and shown as such: dropping it would
                // make a curve with three populated bins look like ten.
                0 => println!("  {bin:>12}{:>8}{:>12}{:>12}{:>10}", 0, "-", "-", "-"),
                n => println!(
                    "  {bin:>12}{n:>8}{:>12.4}{:>12.4}{gap:>+10.4}",
                    b.mean_confidence, b.mean_accuracy
                ),
            }
        }
        println!("  gap = observed accuracy − predicted confidence; + means UNDER-confident.");
    }

    println!();
    println!("  G1 bar: held-out AUC >= 0.90, false-accept <= 2% at the operating");
    println!("  threshold. A trained verifier that does not clear the best floor");
    println!("  above has not earned its GPU-hours.");
    for f in FLOORS {
        println!("    {:<16} {}", f.name, f.why);
    }
}

fn main() -> ExitCode {
    let argv: Vec<String> = std::env::args().collect();
    let cli = match parse_args(&argv) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("error: {e}");
            print_usage(&argv[0]);
            return ExitCode::from(2);
        }
    };

    // ── Query mode: identical retrieval at serve ──────────────────────────
    if let (Some(bank_path), Some(query)) = (&cli.bank, &cli.query) {
        let jsonl = match std::fs::read_to_string(bank_path) {
            Ok(s) => s,
            Err(e) => {
                eprintln!("error: failed to read {}: {e}", bank_path.display());
                return ExitCode::from(1);
            }
        };
        let cards = match cards_from_jsonl(&jsonl) {
            Ok(c) => c,
            Err(e) => {
                eprintln!("error: {e}");
                return ExitCode::from(1);
            }
        };
        let bank = SkillBank::new(cards);
        println!("Skill bank: {} card(s) from {}", bank.cards.len(), bank_path.display());
        let hits = bank.retrieve(query, cli.top_k);
        for (rank, (idx, score)) in hits.iter().enumerate() {
            let card = &bank.cards[*idx];
            println!(
            "#{rank} score {score:.4} — cluster [{}] (cluster_size {})",
            card.cluster.join(", "),
            card.cluster_size
        );
            println!("  exemplar completion ({} bytes):", card.exemplar_code.len());
            for line in card.exemplar_code.lines().take(8) {
                println!("    {line}");
            }
        }
        if hits.is_empty() {
            eprintln!("no cards retrieved (empty bank?)");
        }
        return ExitCode::SUCCESS;
    }

    // ── Build mode ─────────────────────────────────────────────────────────
    let dump_path = cli.dump.expect("parse_args enforces --dump");
    let jsonl = match std::fs::read_to_string(&dump_path) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("error: failed to read {}: {e}", dump_path.display());
            return ExitCode::from(1);
        }
    };
    let (records, malformed) = parse_dump(&jsonl);
    println!(
        "Passed-trajectory dump: {} record(s){}",
        records.len(),
        if malformed > 0 {
            format!(" ({malformed} malformed line(s) skipped)")
        } else {
            String::new()
        }
    );
    if records.is_empty() {
        eprintln!("error: no usable records — nothing to extract (kill-if-noise: an empty run ships no cards)");
        return ExitCode::from(1);
    }

    let cfg = ExtractConfig {
        per_cluster: cli.per_cluster,
        min_cluster: cli.min_cluster,
        saturate_at: cli.saturate_at,
    };
    let (cards, reports) = extract_cards(&records, &cfg);

    println!();
    println!("Cluster report (kill-if-noise verdicts included):");
    for r in &reports {
        match r.refused {
            Some(reason) => println!(
                "  [{}] {:>3} passed  REFUSED — {reason}",
                r.cluster.join(", "),
                r.n_passed
            ),
            None => println!(
                "  [{}] {:>3} passed  {} card(s)",
                r.cluster.join(", "),
                r.n_passed,
                r.cards
            ),
        }
    }
    println!();
    println!("Extracted {} card(s) from {} cluster(s)", cards.len(), reports.len());

    let out_path = cli
        .output
        .clone()
        .unwrap_or_else(|| PathBuf::from("output/skill_cards.jsonl"));
    if let Some(parent) = out_path.parent()
        && !parent.as_os_str().is_empty()
        && let Err(e) = std::fs::create_dir_all(parent)
    {
        eprintln!("error: failed to create {}: {e}", parent.display());
        return ExitCode::from(1);
    }
    if let Err(e) = std::fs::write(&out_path, cards_to_jsonl(&cards)) {
        eprintln!("error: failed to write {}: {e}", out_path.display());
        return ExitCode::from(1);
    }
    println!("Wrote {} ({} card(s))", out_path.display(), cards.len());
    ExitCode::SUCCESS
}

impl AdamW {
    fn new(n_params: usize) -> Self {
        Self {
            m: vec![0.0; n_params],
            v: vec![0.0; n_params],
            lr: LR,
            weight_decay: WEIGHT_DECAY,
            beta1: BETA1,
            beta2: BETA2,
            eps: EPS,
            grad_clip: GRAD_CLIP,
            step: 0,
        }
    }

    /// Cosine learning rate with linear warmup.
    fn lr_for_step(&self, global_step: usize) -> f32 {
        let warmup_steps = (TOTAL_STEPS as f32 * WARMUP_FRAC) as usize;
        if global_step < warmup_steps {
            // Linear warmup.
            self.lr * global_step as f32 / warmup_steps.max(1) as f32
        } else {
            // Cosine decay.
            let progress =
                (global_step - warmup_steps) as f32 / (TOTAL_STEPS - warmup_steps).max(1) as f32;
            self.lr * 0.5 * (1.0 + (std::f32::consts::PI * progress).cos())
        }
    }

    /// Core AdamW update with gradient clipping and cosine schedule.
    fn update_impl(
        &mut self,
        params: &mut [f32],
        grads: &[f32],
        global_step: usize,
        offset: usize,
    ) {
        let lr = self.lr_for_step(global_step);
        let bc1 = 1.0 - self.beta1.powi(self.step as i32 + 1);
        let bc2 = 1.0 - self.beta2.powi(self.step as i32 + 1);

        for i in 0..params.len() {
            let gi = offset + i;
            let g = if grads[i].abs() > self.grad_clip {
                grads[i].signum() * self.grad_clip
            } else {
                grads[i]
            };

            self.m[gi] = self.beta1 * self.m[gi] + (1.0 - self.beta1) * g;
            self.v[gi] = self.beta2 * self.v[gi] + (1.0 - self.beta2) * g * g;

            let m_hat = self.m[gi] / bc1;
            let v_hat = self.v[gi] / bc2;

            let upd = lr * (m_hat / (v_hat.sqrt() + self.eps) + self.weight_decay * params[i]);
            params[i] -= upd;
        }
    }

    /// Update first parameter group and advance step counter.
    fn update(&mut self, params: &mut [f32], grads: &[f32], global_step: usize) {
        self.update_impl(params, grads, global_step, 0);
        self.step += 1;
    }

    /// Update second parameter group without advancing step counter.
    /// `offset` is the size of the first group (w_down) so w_up moments are
    /// stored at indices `[offset, offset + params.len())`.
    fn update_no_step(
        &mut self,
        params: &mut [f32],
        grads: &[f32],
        global_step: usize,
        offset: usize,
    ) {
        self.update_impl(params, grads, global_step, offset);
    }
}

impl MockBaseModel {
    fn new(vocab_size: usize, n_embd: usize, embed_dim: usize) -> Self {
        let mut embeddings = Vec::with_capacity(vocab_size * embed_dim);
        for i in 0..vocab_size * embed_dim {
            let hash = (i as u64).wrapping_mul(2654435761) % 1000003;
            let t = (hash as f64 / 1000003.0) * 2.0 - 1.0;
            embeddings.push(t as f32 * 0.02);
        }
        let mut proj = Vec::with_capacity(vocab_size * n_embd);
        for i in 0..vocab_size * n_embd {
            let hash = (i as u64).wrapping_mul(1103515245) % 1000003;
            let t = (hash as f64 / 1000003.0) * 2.0 - 1.0;
            proj.push(t as f32 * 0.01);
        }
        Self { embeddings, proj }
    }

    /// Mock forward: project token embeddings → logits.
    /// Returns (hidden_states [seq_len × n_embd], base_logits [seq_len × vocab_size]).
    fn forward(&self, tokens: &[usize], n_embd: usize, embed_dim: usize) -> (Vec<f32>, Vec<f32>) {
        let seq_len = tokens.len();
        let mut hidden = vec![0.0f32; seq_len * n_embd];
        let mut logits = vec![0.0f32; seq_len * VOCAB_SIZE];

        for (pos, &tok) in tokens.iter().enumerate() {
            // Embed token.
            let emb_start = tok * embed_dim;
            let emb = &self.embeddings[emb_start..emb_start + embed_dim];

            // Simple hidden = average of embedding (mock).
            let h_start = pos * n_embd;
            for j in 0..n_embd.min(embed_dim) {
                hidden[h_start + j] = emb[j % embed_dim];
            }

            // Project hidden → logits via matmul.
            let l_start = pos * VOCAB_SIZE;
            riir_engine::types::matmul(
                &mut logits[l_start..l_start + VOCAB_SIZE],
                &self.proj,
                &hidden[h_start..h_start + n_embd],
                VOCAB_SIZE,
                n_embd,
            );
        }

        (hidden, logits)
    }
}

