impl AndOrLoraConfig {
    /// Total parameter count for the adapter given input/output dimensions.
    pub fn parameter_count(&self, in_dim: usize, out_dim: usize) -> usize {
        self.n_or_branches * self.n_and_gates * self.rank_per_gate * (in_dim + out_dim)
    }
}

impl AndOrLoraAdapter {
    /// Create a new AND-OR LoRA adapter.
    ///
    /// - A matrices: small random init via FNV-1a hash of domain + pair index.
    /// - B matrices: zero init (zero delta at init, same pattern as EgaLoraAdapter).
    pub fn new(domain: &str, in_dim: usize, out_dim: usize, config: AndOrLoraConfig) -> Self {
        let total_pairs = config.n_or_branches * config.n_and_gates;
        let rank = config.rank_per_gate;
        let seed = simple_hash(domain);

        let projections: Vec<LoraPair> = (0..total_pairs)
            .map(|pair_idx| {
                // Small deterministic pseudo-random init for A (training gradient diversity).
                let pair_seed = seed.wrapping_mul((pair_idx as u64).wrapping_add(1));
                let a: Vec<f32> = (0..rank * in_dim)
                    .map(|i| {
                        let v = pair_seed.wrapping_mul((i as u64).wrapping_add(1));
                        ((v as f32 / u64::MAX as f32) - 0.5) * 0.01
                    })
                    .collect();
                // B zero-init → zero delta at init (identity start).
                let b = vec![0.0f32; out_dim * rank];
                LoraPair { a, b }
            })
            .collect();

        Self {
            domain: domain.to_string(),
            config,
            projections,
            in_dim,
            out_dim,
        }
    }

    /// Apply the AND-OR LoRA adapter to a base output.
    ///
    /// Returns `base_output + (alpha / total_rank) * delta` where delta
    /// is computed through AND/OR gate topology.
    pub fn apply(&self, x: &[f32], base_output: &[f32]) -> Vec<f32> {
        assert_eq!(x.len(), self.in_dim, "input x length mismatch");
        assert_eq!(
            base_output.len(),
            self.out_dim,
            "base_output length mismatch"
        );
        let mut out = vec![0.0; self.out_dim];
        self.apply_into(x, base_output, &mut out);
        out
    }

    /// Zero-alloc variant of [`apply`](Self::apply).
    ///
    /// Writes result into the provided `out` buffer.
    pub fn apply_into(&self, x: &[f32], base_output: &[f32], out: &mut [f32]) {
        assert_eq!(x.len(), self.in_dim, "input x length mismatch");
        assert_eq!(
            base_output.len(),
            self.out_dim,
            "base_output length mismatch"
        );
        assert_eq!(out.len(), self.out_dim, "output buffer length mismatch");

        let n_branches = self.config.n_or_branches;
        let n_gates = self.config.n_and_gates;
        let rank = self.config.rank_per_gate;

        // Compute branch outputs via AND gates.
        let mut branch_outputs: Vec<Vec<f32>> = Vec::with_capacity(n_branches);

        for branch in 0..n_branches {
            let mut and_inputs: Vec<Vec<f32>> = Vec::with_capacity(n_gates);
            for gate in 0..n_gates {
                let pair_idx = branch * n_gates + gate;
                let pair = &self.projections[pair_idx];
                // z = A @ x  →  [rank]
                let ax = mat_vec_mul(&pair.a, x, rank, self.in_dim);
                // z = B @ (A @ x)  →  [out_dim]
                let bax = mat_vec_mul(&pair.b, &ax, self.out_dim, rank);
                and_inputs.push(bax);
            }
            let branch_out = apply_and_gate(&and_inputs, self.config.and_op);
            branch_outputs.push(branch_out);
        }

        // Combine branches via OR gate.
        let delta = apply_or_gate(&branch_outputs, self.config.or_op);

        // Scale and add to base.
        let total_rank = self.total_rank();
        let scale = self.config.lora_alpha / total_rank as f32;
        for j in 0..self.out_dim {
            out[j] = base_output[j] + scale * delta[j];
        }
    }

    /// Total number of learnable parameters across all projection pairs.
    pub fn parameter_count(&self) -> usize {
        self.projections.iter().map(|p| p.a.len() + p.b.len()).sum()
    }

    /// Total effective rank: `n_or_branches * n_and_gates * rank_per_gate`.
    pub fn total_rank(&self) -> usize {
        self.config.n_or_branches * self.config.n_and_gates * self.config.rank_per_gate
    }

    /// Equivalent standard LoRA rank that would have the same parameter count.
    ///
    /// For a standard LoRA with rank `r`: params = `r * (in_dim + out_dim)`.
    /// Solving: `equivalent_rank = total_params / (in_dim + out_dim)`.
    pub fn equivalent_standard_rank(&self) -> usize {
        let dim_sum = self.in_dim + self.out_dim;
        match dim_sum {
            0 => 0,
            _ => self.parameter_count() / dim_sum,
        }
    }
}

use blake3::Hasher;

/// Posterior snapshot from Phase 1 yo training.
///
/// Stores the mean (μ) and diagonal precision (λ = 1/var) of the LoRA weight
/// posterior after SDPG warmup. Used during Phase 2 yr training to prevent
/// catastrophic forgetting of yo-learned knowledge.
#[derive(Clone, Debug)]
pub struct BakePosterior {
    /// Posterior mean μ_d — trained weights after Phase 1.
    pub mu: Vec<f32>,
    /// Posterior precision λ_d — inverse variance (from Adam second moment).
    pub lambda: Vec<f32>,
    /// BLAKE3 commitment hash for integrity verification.
    commitment: [u8; 32],
}

impl BakePosterior {
    /// Create a new posterior from mean and precision vectors.
    ///
    /// Panics in debug mode if dimensions mismatch.
    pub fn new(mu: Vec<f32>, lambda: Vec<f32>) -> Self {
        debug_assert_eq!(
            mu.len(),
            lambda.len(),
            "mu and lambda must have same dimension"
        );
        let commitment = Self::compute_hash(&mu, &lambda);
        Self {
            mu,
            lambda,
            commitment,
        }
    }

    /// Create a uniform posterior with zero mean and constant precision.
    pub fn uniform(dim: usize, precision: f32) -> Self {
        Self::new(vec![0.0; dim], vec![precision; dim])
    }

    /// Dimension of the posterior.
    #[inline]
    pub fn dim(&self) -> usize {
        self.mu.len()
    }

    /// Verify commitment hash integrity.
    pub fn verify(&self) -> bool {
        Self::compute_hash(&self.mu, &self.lambda) == self.commitment
    }

    /// Compute BAKE regularization loss: 0.5 * Σ λ_d · (w_d − μ_d)².
    ///
    /// This is the precision-weighted L2 penalty. The 0.5 factor matches the
    /// standard Gaussian log-posterior derivation. The caller multiplies by
    /// `bake_weight` from `TrltPhaseConfig`.
    #[inline]
    pub fn regularization_loss(&self, current_weights: &[f32]) -> f32 {
        debug_assert_eq!(current_weights.len(), self.mu.len());
        let loss: f32 = current_weights
            .iter()
            .zip(self.mu.iter())
            .zip(self.lambda.iter())
            .map(|((&w, &mu), &lambda)| {
                let diff = w - mu;
                lambda * diff * diff
            })
            .sum();
        0.5 * loss
    }

    /// Compute per-weight regularization penalty for diagnostics.
    pub fn per_weight_penalty(&self, current_weights: &[f32]) -> Vec<f32> {
        debug_assert_eq!(current_weights.len(), self.mu.len());
        current_weights
            .iter()
            .zip(self.mu.iter())
            .zip(self.lambda.iter())
            .map(|((w, mu), lambda)| 0.5 * lambda * (w - mu).powi(2))
            .collect()
    }

    /// Extract posterior from trained weights and Adam optimizer second moment.
    ///
    /// Precision λ = 1/v where v is Adam's second moment (`E[g²]`).
    /// Clamped to `[min_prec, max_prec]` for numerical stability.
    pub fn from_adam_state(
        weights: &[f32],
        adam_second_moment: &[f32],
        min_prec: f32,
        max_prec: f32,
    ) -> Self {
        debug_assert_eq!(weights.len(), adam_second_moment.len());
        let mu = weights.to_vec();
        let lambda: Vec<f32> = adam_second_moment
            .iter()
            .map(|&v| (1.0 / v.max(1e-8)).clamp(min_prec, max_prec))
            .collect();
        Self::new(mu, lambda)
    }

    /// Serialize to bytes for checkpoint storage.
    pub fn to_bytes(&self) -> Vec<u8> {
        let dim = self.mu.len() as u32;
        let mut buf = Vec::with_capacity(4 + self.mu.len() * 8 + 32);
        buf.extend_from_slice(&dim.to_le_bytes());
        for &v in &self.mu {
            buf.extend_from_slice(&v.to_le_bytes());
        }
        for &v in &self.lambda {
            buf.extend_from_slice(&v.to_le_bytes());
        }
        buf.extend_from_slice(&self.commitment);
        buf
    }

    /// Deserialize from bytes.
    pub fn from_bytes(data: &[u8]) -> Result<Self, String> {
        if data.len() < 4 {
            return Err("too short".to_string());
        }
        let dim = u32::from_le_bytes(data[0..4].try_into().map_err(|_| "parse error")?) as usize;
        let expected_len = 4 + dim * 8 + 32;
        if data.len() < expected_len {
            return Err(format!(
                "truncated: expected {expected_len}, got {}",
                data.len()
            ));
        }

        let mu: Vec<f32> = (0..dim)
            .map(|i| f32::from_le_bytes(data[4 + i * 4..8 + i * 4].try_into().unwrap()))
            .collect();
        let lambda: Vec<f32> = (0..dim)
            .map(|i| {
                f32::from_le_bytes(
                    data[4 + dim * 4 + i * 4..8 + dim * 4 + i * 4]
                        .try_into()
                        .unwrap(),
                )
            })
            .collect();
        let commitment: [u8; 32] = data[4 + dim * 8..4 + dim * 8 + 32]
            .try_into()
            .map_err(|_| "hash error")?;

        let posterior = Self {
            mu,
            lambda,
            commitment,
        };
        if !posterior.verify() {
            return Err("commitment hash mismatch".to_string());
        }
        Ok(posterior)
    }

    fn compute_hash(mu: &[f32], lambda: &[f32]) -> [u8; 32] {
        let mut hasher = Hasher::new();
        // Explicit `to_le_bytes` per element keeps the commitment canonical
        // (architecture-independent). A single `cast_slice` absorb would be
        // faster but native-endian, breaking reproducibility on big-endian.
        for &v in mu {
            hasher.update(&v.to_le_bytes());
        }
        for &v in lambda {
            hasher.update(&v.to_le_bytes());
        }
        hasher.finalize().into()
    }
}

use riir_engine::bake_lora::{LoraPosterior, precision_from_adam};

/// BAKE Bayesian regularizer for LoRA training.
///
/// L_Bayes = Σ_i β · √(λ_old\[i\] · (θ\[i\] - μ_old\[i\])²)
///
/// Precision-weighted penalty: weights with high precision (well-determined by
/// previous game) are penalized more for drifting. Weights with low precision
/// (uncertain) are allowed to move freely.
#[derive(Clone, Debug)]
pub struct BakeRegularizer {
    /// Previous game's posterior (used as prior).
    pub prior: LoraPosterior,
    /// Regularization strength β. Default: 0.01.
    pub beta: f32,
}

impl BakeRegularizer {
    /// Create a new regularizer with the given prior and strength.
    pub fn new(prior: LoraPosterior, beta: f32) -> Self {
        Self { prior, beta }
    }

use crate::multifidelity::{MultiFidelityConfig, MultiFidelityStack, TrainingTier};

// ---------------------------------------------------------------------------
// T1: BreakevenConfig
// ---------------------------------------------------------------------------

/// Cost model inputs for breakeven N* computation.
///
/// All costs are in microseconds (wallclock or equivalent).
/// `quality_ratio` is sigmoid-gated: values > 1.0 mean LoRA produces higher quality
/// output than frozen inference for the same query.
#[derive(Clone, Copy, Debug)]
pub struct BreakevenConfig {
    /// Wall-clock cost of data curation/preparation (μs).
    pub data_curation_cost_us: u64,
    /// Wall-clock cost of LoRA training (μs).
    pub training_cost_us: u64,
    /// Per-query cost of frozen (base) model inference (μs).
    pub frozen_inference_cost_us: u64,
    /// Per-query cost of LoRA-augmented inference (μs).
    pub lora_inference_cost_us: u64,
    /// LoRA quality / frozen quality. Sigmoid-gated, > 1.0 = LoRA is better.
    pub quality_ratio: f64,
    /// Worst-case (minimum) quality ratio observed across evaluations.
    /// Used for pessimistic N* estimates.
    pub worst_quality_ratio: f64,
}

impl Default for BreakevenConfig {
    fn default() -> Self {
        Self {
            data_curation_cost_us: 0,
            training_cost_us: 0,
            frozen_inference_cost_us: 100,
            lora_inference_cost_us: 110,
            quality_ratio: 1.2,
            worst_quality_ratio: 1.0,
        }
    }

impl BreakevenConfig {
    /// Total one-time upfront cost: data curation + training.
    #[inline]
    #[must_use]
    pub fn upfront_cost_us(&self) -> u64 {
        self.data_curation_cost_us
            .saturating_add(self.training_cost_us)
    }

    // -----------------------------------------------------------------------
    // T2: compute_n_star
    // -----------------------------------------------------------------------

    /// Compute the breakeven query count N*.
    ///
    /// N* = (data_cost + training_cost) / (frozen_cost × quality_ratio − lora_cost)
    ///
    /// Returns `f64::INFINITY` when the denominator ≤ 0, meaning LoRA never amortizes
    /// (it is more expensive per-query even after accounting for quality).
    #[inline]
    #[must_use]
    pub fn compute_n_star(&self) -> f64 {
        let upfront = self.upfront_cost_us() as f64;
        let denominator = self.frozen_inference_cost_us as f64 * self.quality_ratio
            - self.lora_inference_cost_us as f64;
        if denominator <= 0.0 {
            f64::INFINITY
        } else {
            upfront / denominator
        }
    }

    // -----------------------------------------------------------------------
    // T4: Worst-case variant
    // -----------------------------------------------------------------------

    /// Compute N* using the worst-case (minimum) quality ratio.
    ///
    /// Always ≥ `compute_n_star()` because the denominator is smaller.
    #[inline]
    #[must_use]
    pub fn compute_n_star_worst_case(&self) -> f64 {
        let upfront = self.upfront_cost_us() as f64;
        let denominator = self.frozen_inference_cost_us as f64 * self.worst_quality_ratio
            - self.lora_inference_cost_us as f64;
        if denominator <= 0.0 {
            f64::INFINITY
        } else {
            upfront / denominator
        }
    }

    // -----------------------------------------------------------------------
    // T3: recommend_tier
    // -----------------------------------------------------------------------

    /// Recommend a training tier for the given expected query count.
    ///
    /// Uses sigmoid-gated decision boundaries between tiers based on the
    /// multi-fidelity cost model.
    #[must_use]
    pub fn recommend_tier(
        &self,
        expected_queries: u64,
        mf_config: &MultiFidelityConfig,
    ) -> TrainingTier {
        MultiFidelityStack::recommend(mf_config, expected_queries, self.quality_ratio)
    }
}

impl BreakevenReport {
    /// Run pre-training breakeven check.
    ///
    /// Returns a report with N* computation and tier recommendation.
    /// If N* > expected queries, the `amortized` flag is false and
    /// the caller should warn the user and consider tier downgrade.
    #[must_use]
    pub fn pre_training_check(
        config: &BreakevenConfig,
        expected_queries: u64,
        mf_config: &MultiFidelityConfig,
    ) -> Self {
        let n_star = config.compute_n_star();
        let n_star_worst = config.compute_n_star_worst_case();
        let recommended_tier = config.recommend_tier(expected_queries, mf_config);
        let amortized = (expected_queries as f64) >= n_star;

        Self {
            n_star,
            recommended_tier,
            expected_queries,
            amortized,
            n_star_worst_case: n_star_worst,
            actual_training_us: None,
        }
    }

    /// Create post-training report with actual training wall-clock.
    ///
    /// Recomputes N* using observed training cost instead of estimated.
    #[must_use]
    pub fn post_training_report(
        config: &BreakevenConfig,
        expected_queries: u64,
        mf_config: &MultiFidelityConfig,
        actual_training_us: u64,
    ) -> Self {
        let mut adjusted = *config;
        adjusted.training_cost_us = actual_training_us;

        let n_star = adjusted.compute_n_star();
        let n_star_worst = adjusted.compute_n_star_worst_case();
        let recommended_tier = adjusted.recommend_tier(expected_queries, mf_config);
        let amortized = (expected_queries as f64) >= n_star;

        Self {
            n_star,
            recommended_tier,
            expected_queries,
            amortized,
            n_star_worst_case: n_star_worst,
            actual_training_us: Some(actual_training_us),
        }
    }

    /// Whether the training should proceed given the breakeven analysis.
    #[inline]
    #[must_use]
    pub fn should_train(&self) -> bool {
        self.amortized
    }

    /// Suggest a tier downgrade if training doesn't amortize at current tier.
    ///
    /// Returns `None` if current tier is already the cheapest option.
    #[must_use]
    pub fn suggest_downgrade(&self, mf_config: &MultiFidelityConfig) -> Option<TrainingTier> {
        if self.amortized {
            return None;
        }
        let tiers = &mf_config.tiers;
        for tier_cfg in tiers {
            let n_star = Self::n_star_for_tier(tier_cfg);
            if (self.expected_queries as f64) >= n_star {
                return Some(tier_cfg.tier);
            }
        }
        Some(TrainingTier::FrozenCoT)
    }

    /// Compute N* for a single tier config.
    #[inline]
    fn n_star_for_tier(tier: &crate::multifidelity::TierConfig) -> f64 {
        let training = tier.training_cost_us as f64;
        let denominator = tier.quality_ratio * 100.0 - tier.inference_cost_us as f64;
        if denominator <= 0.0 {
            f64::INFINITY
        } else {
            training / denominator
        }
    }
}

