impl ParsedSafetensors {
    /// Extract a required f32 tensor.
    pub fn get_tensor(&self, name: &str) -> Result<Vec<f32>, CheckpointError> {
        match self.offsets.get(name) {
            Some(&(start, end)) => {
                let bytes = &self.data[start..end];
                if !bytes.len().is_multiple_of(4) {
                    return Err(CheckpointError::BadTensorLength {
                        name: name.into(),
                        bytes: bytes.len(),
                    });
                }
                Ok(f32_bytes_to_vec(bytes))
            }
            None => Err(CheckpointError::MissingTensor(name.into())),
        }
    }

    /// Extract an optional f32 tensor (returns `None` if absent).
    pub fn get_tensor_opt(&self, name: &str) -> Option<Vec<f32>> {
        self.offsets
            .get(name)
            .map(|&(start, end)| f32_bytes_to_vec(&self.data[start..end]))
    }

    /// Read a metadata field as a string (None if absent).
    pub fn meta(&self, key: &str) -> Option<&str> {
        self.metadata.get(key).map(|s| s.as_str())
    }

    /// Read a metadata field and parse it as a `usize`.
    pub fn meta_usize(&self, key: &str) -> Option<usize> {
        self.metadata.get(key).and_then(|s| s.parse().ok())
    }

    /// Read a metadata field and parse it as `bool` (`"true"` / `"false"`).
    pub fn meta_bool(&self, key: &str) -> Option<bool> {
        self.metadata.get(key).map(|s| s == "true")
    }
