impl GameLoraWeights {
    /// Xavier-initialized LoRA weights.
    pub fn new(in_dim: usize, out_dim: usize, rank: usize) -> Self {
        let scale = (2.0 / (in_dim + out_dim) as f32).sqrt();
        let mut a = vec![0.0f32; in_dim * rank];
        let mut b = vec![0.0f32; rank * out_dim];

        // Deterministic init with xorshift.
        let mut state: u64 = 0x1234_5678_9ABC_DEF0;
        for v in a.iter_mut() {
            state ^= state << 13;
            state ^= state >> 7;
            state ^= state << 17;
            let bits = (state >> 40) as u32;
            *v = ((bits as f32 / (1u32 << 24) as f32) * 2.0 - 1.0) * scale;
        }
        for v in b.iter_mut() {
            state ^= state << 13;
            state ^= state >> 7;
            state ^= state << 17;
            let bits = (state >> 40) as u32;
            *v = ((bits as f32 / (1u32 << 24) as f32) * 2.0 - 1.0) * scale;
        }

        Self {
            a,
            b,
            in_dim,
            out_dim,
            rank,
        }
    }

    /// Forward pass: output = input @ A @ B (approximated as elementwise).
    ///
    /// Loop order is chosen for sequential memory access of `a` and `b`
    /// (inner loop advances by 1) rather than the mathematical nesting.
    /// This is the hot path of numerical-gradient training (≥500 calls/step).
    ///
    /// Allocates `hidden` and `output` per call. Prefer `forward_into` in
    /// hot callers (e.g. numerical-gradient loops) to avoid per-call heap
    /// allocations — ~1024 allocs/step otherwise.
    pub fn forward(&self, input: &[f32]) -> Vec<f32> {
        let mut output = vec![0.0f32; self.out_dim];
        let mut hidden = vec![0.0f32; self.rank];
        self.forward_into(input, &mut hidden, &mut output);
        output
    }

    /// Zero-alloc forward pass. Writes hidden state to `hidden_scratch`
    /// (length `rank`) and output to `output_scratch` (length `out_dim`).
    /// Both buffers are fully overwritten (zeroed first then accumulated).
    ///
    /// This is the variant to call inside tight gradient loops.
    pub fn forward_into(
        &self,
        input: &[f32],
        hidden_scratch: &mut [f32],
        output_scratch: &mut [f32],
    ) {
        debug_assert_eq!(input.len(), self.in_dim);
        debug_assert_eq!(hidden_scratch.len(), self.rank);
        debug_assert_eq!(output_scratch.len(), self.out_dim);
        // hidden = A^T @ input  where A is [in_dim × rank] row-major.
        // For each input element i, scatter x[i] across all rank slots —
        // a[i*rank + r] is contiguous in r.
        hidden_scratch.fill(0.0);
        for (i, &x) in input.iter().enumerate() {
            let row = i * self.rank;
            for (r, h) in hidden_scratch.iter_mut().enumerate() {
                *h += x * self.a[row + r];
            }
        }
        // output = B^T @ hidden  where B is [rank × out_dim] row-major.
        // For each hidden element r, scatter h[r] across all out_dim slots —
        // b[r*out_dim + o] is contiguous in o.
        output_scratch.fill(0.0);
        for (r, &h) in hidden_scratch.iter().enumerate() {
            let row = r * self.out_dim;
            for (o, out) in output_scratch.iter_mut().enumerate() {
                *out += h * self.b[row + o];
            }
        }
    }

    /// BLAKE3 hash of the weight data.
    pub fn blake3_hash(&self) -> [u8; 32] {
        let mut hasher = Hasher::new();
        for v in &self.a {
            hasher.update(&v.to_le_bytes());
        }
        for v in &self.b {
            hasher.update(&v.to_le_bytes());
        }
        *hasher.finalize().as_bytes()
    }

    /// Total parameter count.
    pub fn param_count(&self) -> usize {
        self.a.len() + self.b.len()
    }
}

impl SimAdamW {
    fn new(a_len: usize, b_len: usize) -> Self {
        Self {
            m_a: vec![0.0; a_len],
            v_a: vec![0.0; a_len],
            m_b: vec![0.0; b_len],
            v_b: vec![0.0; b_len],
            step: 0,
        }
    }

    fn update(&mut self, a: &mut [f32], b: &mut [f32], grad_a: &[f32], grad_b: &[f32], lr: f32) {
        self.step += 1;
        let beta1 = 0.9f32;
        let beta2 = 0.999f32;
        let eps = 1e-8f32;
        let bc1 = 1.0 - beta1.powi(self.step as i32);
        let bc2 = 1.0 - beta2.powi(self.step as i32);

        for i in 0..a.len() {
            self.m_a[i] = beta1 * self.m_a[i] + (1.0 - beta1) * grad_a[i];
            self.v_a[i] = beta2 * self.v_a[i] + (1.0 - beta2) * grad_a[i] * grad_a[i];
            let mh = self.m_a[i] / bc1;
            let vh = self.v_a[i] / bc2;
            a[i] -= lr * mh / (vh.sqrt() + eps);
        }
        for i in 0..b.len() {
            self.m_b[i] = beta1 * self.m_b[i] + (1.0 - beta1) * grad_b[i];
            self.v_b[i] = beta2 * self.v_b[i] + (1.0 - beta2) * grad_b[i] * grad_b[i];
            let mh = self.m_b[i] / bc1;
            let vh = self.v_b[i] / bc2;
            b[i] -= lr * mh / (vh.sqrt() + eps);
        }
    }
}

