impl CollimationObjective {
    /// Create a pre-attribution objective with default hyperparameters.
    pub fn pre_attribution() -> Self {
        Self {
            regime: CollimationRegime::PreAttribution,
            ..Self::default()
        }
    }

    /// Create a post-attribution objective with default hyperparameters.
    pub fn post_attribution() -> Self {
        Self {
            regime: CollimationRegime::PostAttribution,
            ..Self::default()
        }
    }

    /// Compute the collimation loss for the current regime.
    ///
    /// Pre-attribution: `L = l_task + beta * KL(p_base || p_lora)`
    ///
    /// Post-attribution: `L = offline_kl + lambda_ce * ce + lambda_u * unmasked_kl`
    #[allow(clippy::too_many_arguments)]
    pub fn compute_loss(
        &self,
        l_task: f32,
        p_base: &[f32],
        p_lora: &[f32],
        // Post-attribution only:
        offline_kl: f32,
        ce: f32,
        unmasked_p_base: &[f32],
        unmasked_p_lora: &[f32],
    ) -> f32 {
        match self.regime {
            CollimationRegime::PreAttribution => {
                let kl = kl_forward_divergence(p_base, p_lora);
                l_task + self.beta * kl
            }
            CollimationRegime::PostAttribution => {
                let unmasked_kl = kl_forward_divergence(unmasked_p_base, unmasked_p_lora);
                offline_kl + self.lambda_ce * ce + self.lambda_u * unmasked_kl
            }
        }
    }
}

impl RelpAttribution {
    /// Return channel indices sorted by descending absolute relevance.
    ///
    /// Pre-computes `|score|` once per channel to avoid recomputing `.abs()`
    /// on every comparison during the sort (was O(n log n) abs calls → O(n)).
    pub fn ranked_indices(&self) -> Vec<usize> {
        // Cache |score| alongside the index so the sort comparator reads a
        // precomputed value instead of calling .abs() twice per comparison.
        let mut indexed: Vec<(f32, usize)> = self
            .channel_scores
            .iter()
            .enumerate()
            .map(|(i, &s)| (s.abs(), i))
            .collect();
        indexed.sort_unstable_by(|a, b| b.0.partial_cmp(&a.0).unwrap_or(std::cmp::Ordering::Equal));
        indexed.into_iter().map(|(_, i)| i).collect()
    }
}

impl SubstrateMask {
    /// Returns true if channel `idx` is in the mask (top-k).
    pub fn is_active(&self, idx: usize) -> bool {
        self.channel_indices.contains(&idx)
    }

    /// Apply the mask to activations, deactivating complement channels.
    pub fn apply(&self, activations: &mut [f32], mean_values: Option<&[f32]>) {
        // Build a Vec<bool> membership bitmask instead of a HashSet — O(n_total_channels)
        // to construct, O(1) lookup, no hashing overhead. Also memory-denser.
        let n = self.n_total_channels;
        let mut is_active = vec![false; n];
        for &idx in &self.channel_indices {
            if idx < n {
                is_active[idx] = true;
            }
        }

        for (i, act) in activations.iter_mut().enumerate() {
            if i < n && is_active[i] {
                continue;
            }
            *act = match self.operator {
                DeactivationOperator::ZeroIsolation => 0.0,
                DeactivationOperator::MeanAblation => mean_values.map_or(0.0, |m| m[i]),
                DeactivationOperator::CounterfactualPatching => {
                    // Counterfactual requires external values; fallback to mean or zero.
                    mean_values.map_or(0.0, |m| m[i])
                }
            };
        }
    }

    /// Pack the mask into a compact bitmask (1 bit per channel, 1 = active).
    pub fn to_bitmask(&self) -> Vec<u8> {
        let n_bytes = self.n_total_channels.div_ceil(8);
        let mut bitmask = vec![0u8; n_bytes];
        for &idx in &self.channel_indices {
            let byte_idx = idx / 8;
            let bit_idx = idx % 8;
            if byte_idx < bitmask.len() {
                bitmask[byte_idx] |= 1 << bit_idx;
            }
        }
        bitmask
    }
}

impl SubstrateMaskFile {
    /// Create a new SubstrateMaskFile from a list of per-layer masks.
    pub fn new(
        capability_name: String,
        model_id: String,
        regime: CollimationRegime,
        masks: Vec<Vec<u8>>,
        recovery_score: f32,
        adapter_blake3: [u8; 32],
    ) -> Self {
        Self {
            version: MASK_FILE_VERSION,
            capability_name,
            model_id,
            regime,
            masks,
            recovery_score,
            adapter_blake3,
        }
    }

    /// Serialize to bytes (bincode-compatible, deterministic layout).
    pub fn to_bytes(&self) -> Vec<u8> {
        let mut buf = Vec::new();

        // Version.
        buf.extend_from_slice(&self.version.to_le_bytes());

        // Capability name (length-prefixed).
        let name_bytes = self.capability_name.as_bytes();
        buf.extend_from_slice(&(name_bytes.len() as u32).to_le_bytes());
        buf.extend_from_slice(name_bytes);

        // Model ID (length-prefixed).
        let model_bytes = self.model_id.as_bytes();
        buf.extend_from_slice(&(model_bytes.len() as u32).to_le_bytes());
        buf.extend_from_slice(model_bytes);

        // Regime.
        buf.push(self.regime as u8);

        // Number of layers.
        buf.extend_from_slice(&(self.masks.len() as u32).to_le_bytes());

        // Per-layer masks.
        for mask in &self.masks {
            buf.extend_from_slice(&(mask.len() as u32).to_le_bytes());
            buf.extend_from_slice(mask);
        }

        // Recovery score.
        buf.extend_from_slice(&self.recovery_score.to_le_bytes());

        // Adapter BLAKE3 hash.
        buf.extend_from_slice(&self.adapter_blake3);

        buf
    }

    /// Deserialize from bytes.
    pub fn from_bytes(data: &[u8]) -> Result<Self, String> {
        let mut pos = 0;

        let read_u32 = |data: &[u8], pos: &mut usize| -> Result<u32, String> {
            if *pos + 4 > data.len() {
                return Err("unexpected end of data reading u32".into());
            }
            let val = u32::from_le_bytes(data[*pos..*pos + 4].try_into().unwrap());
            *pos += 4;
            Ok(val)
        };

        // Version.
        let version = read_u32(data, &mut pos)?;
        if version != MASK_FILE_VERSION {
            return Err(format!("unsupported version: {version}"));
        }

        // Capability name.
        let name_len = read_u32(data, &mut pos)? as usize;
        if pos + name_len > data.len() {
            return Err(format!(
                "unexpected end of data reading {name_len} bytes at pos {pos}"
            ));
        }
        let capability_name = String::from_utf8(data[pos..pos + name_len].to_vec())
            .map_err(|e| format!("invalid capability_name: {e}"))?;
        pos += name_len;

        // Model ID.
        let model_len = read_u32(data, &mut pos)? as usize;
        if pos + model_len > data.len() {
            return Err(format!(
                "unexpected end of data reading {model_len} bytes at pos {pos}"
            ));
        }
        let model_id = String::from_utf8(data[pos..pos + model_len].to_vec())
            .map_err(|e| format!("invalid model_id: {e}"))?;
        pos += model_len;

        // Regime.
        if pos + 1 > data.len() {
            return Err("unexpected end of data reading regime byte".into());
        }
        let regime_byte = data[pos];
        pos += 1;
        let regime = match regime_byte {
            0 => CollimationRegime::PreAttribution,
            1 => CollimationRegime::PostAttribution,
            _ => return Err(format!("invalid regime byte: {regime_byte}")),
        };

        // Number of layers.
        let n_layers = read_u32(data, &mut pos)? as usize;

        // Per-layer masks.
        let mut masks = Vec::with_capacity(n_layers);
        for _ in 0..n_layers {
            let mask_len = read_u32(data, &mut pos)? as usize;
            if pos + mask_len > data.len() {
                return Err(format!(
                    "unexpected end of data reading mask {mask_len} bytes at pos {pos}"
                ));
            }
            masks.push(data[pos..pos + mask_len].to_vec());
            pos += mask_len;
        }

        // Recovery score.
        if pos + 4 > data.len() {
            return Err("unexpected end of data reading recovery score".into());
        }
        let recovery_score = f32::from_le_bytes(data[pos..pos + 4].try_into().unwrap());
        pos += 4;

        // Adapter BLAKE3 hash.
        if pos + 32 > data.len() {
            return Err("unexpected end of data reading adapter blake3 hash".into());
        }
        let mut adapter_blake3 = [0u8; 32];
        adapter_blake3.copy_from_slice(&data[pos..pos + 32]);

        Ok(Self {
            version,
            capability_name,
            model_id,
            regime,
            masks,
            recovery_score,
            adapter_blake3,
        })
    }

    /// Compute BLAKE3 hash of the serialized file (integrity check).
    pub fn blake3_hash(&self) -> [u8; 32] {
        let bytes = self.to_bytes();
        *blake3::hash(&bytes).as_bytes()
    }
}

impl MaskedForwardPass {
    /// Create a new masked forward pass with the given mask.
    ///
    /// `matched_masking` controls whether the training operator matches evaluation.
    pub fn new(mask: SubstrateMask, matched_masking: bool) -> Self {
        let n = mask.n_total_channels;
        let mut is_active = vec![false; n];
        for &idx in &mask.channel_indices {
            if idx < n {
                is_active[idx] = true;
            }
        }
        Self {
            mask,
            mean_values: None,
            matched_masking,
            is_active,
        }
    }

    /// Set dataset mean values for mean-ablation deactivation.
    pub fn with_mean_values(mut self, means: Vec<f32>) -> Self {
        self.mean_values = Some(means);
        self
    }

    /// Apply mask to activations in-place. Returns the masked activations slice.
    ///
    /// Zero-isolation: sets complement channels to 0.
    /// Mean-ablation: replaces complement channels with dataset mean.
    /// Counterfactual patching: replaces complement with mean (fallback).
    pub fn apply(&self, activations: &mut [f32]) {
        // Use the cached membership bitmask (built once in `new`) — allocation-free.
        let n = self.mask.n_total_channels;
        let is_active = &self.is_active;

        // Hoist the operator match out of the per-element loop into
        // specialized loops — same numerics, no per-element branch on the
        // operator tag and no per-element `Option::map` for mean-ablation.
        // `MeanAblation` and `CounterfactualPatching` share the same body.
        match self.mask.operator {
            DeactivationOperator::ZeroIsolation => {
                for (i, act) in activations.iter_mut().enumerate() {
                    if i < n && is_active[i] {
                        continue;
                    }
                    *act = 0.0;
                }
            }
            DeactivationOperator::MeanAblation | DeactivationOperator::CounterfactualPatching => {
                // Hoist the `Option<Vec>` deref once before the loop.
                let means = self.mean_values.as_deref();
                for (i, act) in activations.iter_mut().enumerate() {
                    if i < n && is_active[i] {
                        continue;
                    }
                    // Bit-identical to `self.mean_values.as_ref().map(|m| m[i]).unwrap_or(0.0)`:
                    // panics on out-of-bounds when `Some`, yields 0.0 when `None`.
                    *act = match means {
                        Some(m) => m[i],
                        None => 0.0,
                    };
                }
            }
        }
    }

    /// Batch-apply mask to a sequence of activation vectors.
    ///
    /// `batch` is laid out as `[seq_len * n_channels]` in row-major order.
    /// Each row of `n_channels` elements is masked independently.
    ///
    /// Hoists the operator dispatch above the per-row loop so the match on
    /// `self.mask.operator` happens once per call rather than once per row.
    /// Specializes the per-element body for each operator variant — same
    /// numerics as `apply`, no per-row branch on the operator tag.
    pub fn apply_batch(&self, batch: &mut [f32], n_channels: usize) {
        assert_eq!(
            batch.len() % n_channels,
            0,
            "batch length must be a multiple of n_channels"
        );
        if batch.is_empty() {
            return;
        }
        let n = self.mask.n_total_channels;
        let is_active = &self.is_active;

        match self.mask.operator {
            DeactivationOperator::ZeroIsolation => {
                for row in batch.chunks_exact_mut(n_channels) {
                    for (i, act) in row.iter_mut().enumerate() {
                        if i < n && is_active[i] {
                            continue;
                        }
                        *act = 0.0;
                    }
                }
            }
            DeactivationOperator::MeanAblation | DeactivationOperator::CounterfactualPatching => {
                let means = self.mean_values.as_deref();
                for row in batch.chunks_exact_mut(n_channels) {
                    for (i, act) in row.iter_mut().enumerate() {
                        if i < n && is_active[i] {
                            continue;
                        }
                        // Bit-identical to the per-row `apply` body: panics on
                        // out-of-bounds when `Some`, yields 0.0 when `None`.
                        *act = match means {
                            Some(m) => m[i],
                            None => 0.0,
                        };
                    }
                }
            }
        }
    }
}

impl GkdAopdObjective {
    /// Create with Prism's default weights: (0.2, 0.8, 0.05).
    pub fn new() -> Self {
        Self {
            w_opd: 0.2,
            w_kl: 0.8,
            w_ce: 0.05,
        }
    }

    /// Compute positive-only advantage OPD loss.
    ///
    /// Only counts positive advantages (teacher > student), reinforcing where
    /// teacher agrees. Negative advantages are clipped to zero, removing value
    /// corruption from the Prism paper.
    ///
    /// `advantages`: per-token advantage scores (positive = reinforce).
    /// `logprobs_old`: reference log-probs (stop-gradient, detached).
    /// `logprobs_new`: current model log-probs.
    pub fn positive_opd_loss(
        &self,
        advantages: &[f32],
        logprobs_old: &[f32],
        logprobs_new: &[f32],
    ) -> f32 {
        assert_eq!(
            advantages.len(),
            logprobs_old.len(),
            "advantages and logprobs_old must have same length"
        );
        assert_eq!(
            advantages.len(),
            logprobs_new.len(),
            "advantages and logprobs_new must have same length"
        );

        let n = advantages.len();
        if n == 0 {
            return 0.0;
        }

        let mut total = 0.0f32;
        for i in 0..n {
            let adv = advantages[i];
            if adv > 0.0 {
                // Positive-only: reinforce where teacher agrees.
                let ratio = (logprobs_new[i] - logprobs_old[i]).exp();
                total -= adv * ratio;
            }
        }

        // Normalize by total tokens (not just positive ones) for stable gradients.
        if n > 0 { total / n as f32 } else { 0.0 }
    }

    /// Compute gold-prefix KL: KL(p_base || p_student) on teacher-forced tokens.
    ///
    /// Uses forward KL (mass-covering) to prevent the student from dropping
    /// base probability mass on gold-prefix positions.
    pub fn gold_prefix_kl(&self, p_base: &[f32], p_student: &[f32]) -> f32 {
        kl_forward_divergence(p_base, p_student)
    }

    /// Compute cross-entropy on gold labels.
    ///
    /// Standard softmax cross-entropy using sigmoid-based normalization.
    /// Each logit is independently normalized via sigmoid for numerical stability.
    pub fn cross_entropy(&self, logits: &[f32], gold_index: usize) -> f32 {
        assert!(gold_index < logits.len(), "gold_index out of bounds");

        // Numerically stable cross-entropy using log-sigmoid trick.
        // log(sigmoid(x)) = x - log(1 + exp(x)) = -log(1 + exp(-x))
        // We use the negative log-sigmoid of the gold logit as CE loss.
        let gold_logit = logits[gold_index];

        // log-sum-exp for normalization: log(sum(exp(logits)))
        let max_logit = logits.iter().cloned().fold(f32::NEG_INFINITY, f32::max);
        let log_sum_exp = max_logit
            + logits
                .iter()
                .map(|&l| (l - max_logit).exp())
                .sum::<f32>()
                .ln();

        // CE = -log(softmax(gold)) = -(gold_logit - log_sum_exp)
        -(gold_logit - log_sum_exp)
    }

    /// Compute full hybrid loss.
    ///
    /// Returns decomposed loss components for logging.
    #[allow(clippy::too_many_arguments)]
    pub fn compute(
        &self,
        advantages: &[f32],
        logprobs_old: &[f32],
        logprobs_new: &[f32],
        p_base: &[f32],
        p_student: &[f32],
        logits: &[f32],
        gold_index: usize,
    ) -> GkdAopdLossOutput {
        let opd_raw = self.positive_opd_loss(advantages, logprobs_old, logprobs_new);
        let kl_raw = self.gold_prefix_kl(p_base, p_student);
        let ce_raw = self.cross_entropy(logits, gold_index);

        let opd_component = self.w_opd * opd_raw;
        let kl_component = self.w_kl * kl_raw;
        let ce_component = self.w_ce * ce_raw;

        GkdAopdLossOutput {
            total: opd_component + kl_component + ce_component,
            opd_component,
            kl_component,
            ce_component,
        }
    }
}

impl RolloutState {
    /// Create a new rollout state with the given collapse detection threshold.
    pub fn new(collapse_threshold: f32) -> Self {
        Self {
            generated_tokens: Vec::new(),
            teacher_scores: Vec::new(),
            student_scores: Vec::new(),
            collapse_threshold,
            collapsed: false,
        }
    }

    /// Record a rollout step: student token, teacher score, student score.
    pub fn record_step(&mut self, token: usize, teacher_score: f32, student_score: f32) {
        self.generated_tokens.push(token);
        self.teacher_scores.push(teacher_score);
        self.student_scores.push(student_score);
    }

    /// Check for collapse: if recent rollout accuracy < threshold, mark as collapsed.
    ///
    /// Uses a sliding window of the last `window` steps. Accuracy is the fraction
    /// of steps where teacher_score >= student_score (teacher agrees with student).
    /// Returns true if collapse was detected.
    pub fn check_collapse(&mut self, window: usize) -> bool {
        let n = self.teacher_scores.len();
        if n == 0 {
            return false;
        }

        let start = n.saturating_sub(window);
        let window_len = n - start;
        if window_len == 0 {
            return false;
        }

        let agreements: usize = (start..n)
            .filter(|&i| self.teacher_scores[i] >= self.student_scores[i])
            .count();

        let accuracy = agreements as f32 / window_len as f32;
        self.collapsed = accuracy < self.collapse_threshold;
        self.collapsed
    }

    /// Compute positive-only advantages: max(0, teacher_score - student_score).
    ///
    /// Reinforces where teacher agrees with student direction, never subtracts.
    /// This removes value corruption (Prism: positive-only online advantages).
    pub fn positive_advantages(&self) -> Vec<f32> {
        assert_eq!(
            self.teacher_scores.len(),
            self.student_scores.len(),
            "teacher and student scores must have same length"
        );

        self.teacher_scores
            .iter()
            .zip(self.student_scores.iter())
            .map(|(&teacher, &student)| (teacher - student).max(0.0))
            .collect()
    }

    /// Fall back to offline training: clear rollout state.
    ///
    /// Called when collapse is detected. Resets accumulated tokens and scores
    /// so the training loop can switch to offline mode.
    pub fn fallback_offline(&mut self) {
        self.generated_tokens.clear();
        self.teacher_scores.clear();
        self.student_scores.clear();
        self.collapsed = false;
    }
}

#[cfg(feature = "rank_one_spectral")]
use crate::rank_one_spectral::{RankOneSpectralConfig, RankOneSpectralReg};

// ── Layer Filter (Plan 268 T2) ───────────────────────────────────────────

/// Specifies which LoRA layers to apply rank-one spectral regularization to.
#[derive(Debug, Clone, Default)]
pub enum LayerFilter {
    /// Apply to all layers.
    #[default]
    All,
    /// Apply only to layers at these indices.
    Indices(Vec<usize>),
}

impl LayerFilter {
    /// Returns `true` if the given layer index should be regularized.
    #[inline]
    pub fn should_apply(&self, layer_idx: usize) -> bool {
        match self {
            LayerFilter::All => true,
            LayerFilter::Indices(indices) => indices.contains(&layer_idx),
        }
    }

impl RankOneTrainingConfig {
    /// Create an enabled config with default values.
    pub fn enabled() -> Self {
        Self {
            enable: true,
            ..Self::default()
        }
    }

    /// Create an enabled config with custom λ and power iterations.
    pub fn with_params(lambda: f32, power_iters: usize) -> Self {
        Self {
            enable: true,
            lambda,
            power_iters,
            ..Self::default()
        }
    }

    /// Create an enabled config that only applies to specific layer indices.
    pub fn with_layer_filter(indices: Vec<usize>) -> Self {
        Self {
            enable: true,
            layer_filter: LayerFilter::Indices(indices),
            ..Self::default()
        }
    }

    /// Convert to the underlying `RankOneSpectralConfig`.
    #[cfg(feature = "rank_one_spectral")]
    pub fn to_spectral_config(&self) -> RankOneSpectralConfig {
        RankOneSpectralConfig {
            lambda: self.lambda,
            power_iters: self.power_iters,
        }
    }
}

impl ContinualLoraState {
    /// Create a new empty continual learning state.
    pub fn new() -> Self {
        Self {
            completed_games: Vec::new(),
            active_regularizer: None,
            current_game: None,
            default_beta: 0.01,
            #[cfg(feature = "rank_one_spectral")]
            spectral_reg: None,
        }
    }

    /// Create with custom default β.
    pub fn with_beta(beta: f32) -> Self {
        Self {
            default_beta: beta,
            ..Self::new()
        }
    }

    /// Register a completed game's posterior.
    ///
    /// This posterior becomes available as a prior for future game training.
    pub fn register_posterior(&mut self, game_id: impl Into<String>, posterior: LoraPosterior) {
        let game_id = game_id.into();
        // Replace if already exists
        if let Some(pos) = self
            .completed_games
            .iter()
            .position(|(id, _)| *id == game_id)
        {
            self.completed_games[pos] = (game_id, posterior);
        } else {
            self.completed_games.push((game_id, posterior));
        }
    }

    /// Start training a new game using all previous posteriors as priors.
    ///
    /// Creates a combined regularizer from all completed games' posteriors.
    /// Uses the most recent game's posterior as the primary prior.
    pub fn start_training(&mut self, game_id: impl Into<String>) -> usize {
        let game_id = game_id.into();
        self.current_game = Some(game_id);

        // Use the most recent posterior as prior
        if let Some((_, posterior)) = self.completed_games.last() {
            self.active_regularizer =
                Some(BakeRegularizer::new(posterior.clone(), self.default_beta));
        } else {
            self.active_regularizer = None;
        }

        self.completed_games.len()
    }

    /// Get the active regularizer for the current training session.
    #[inline]
    pub fn regularizer(&self) -> Option<&BakeRegularizer> {
        self.active_regularizer.as_ref()
    }

    /// Get mutable reference to the active regularizer.
    pub fn regularizer_mut(&mut self) -> Option<&mut BakeRegularizer> {
        self.active_regularizer.as_mut()
    }

    /// Compute BAKE loss for current weights using active regularizer.
    pub fn bake_loss(&self, weights: &[f32]) -> f32 {
        match &self.active_regularizer {
            Some(reg) => reg.loss(weights),
            None => 0.0,
        }
    }

    /// Compute combined loss: base_loss + BAKE regularizer.
    pub fn combined_loss(&self, base_loss: f32, weights: &[f32]) -> f32 {
        base_loss + self.bake_loss(weights)
    }

    /// Compute combined loss with rank-one spectral regularization (Plan 268).
    ///
    /// total = base_loss + BAKE + λ · (||A||²_F - σ₁²)
    /// Only available when `rank_one_spectral` feature is enabled.
    #[cfg(feature = "rank_one_spectral")]
    pub fn combined_loss_with_spectral(
        &mut self,
        base_loss: f32,
        weights: &[f32],
        a_matrix: &[f32],
        rows: usize,
        cols: usize,
    ) -> f32 {
        let after_bake = self.combined_loss(base_loss, weights);
        match &mut self.spectral_reg {
            Some(reg) => after_bake + reg.loss(a_matrix, rows, cols),
            None => after_bake,
        }
    }

    /// Set the rank-one spectral regularizer for the training session.
    #[cfg(feature = "rank_one_spectral")]
    pub fn set_spectral_reg(&mut self, reg: RankOneSpectralReg) {
        self.spectral_reg = Some(reg);
    }

    /// Get the spectral regularizer (if any).
    #[cfg(feature = "rank_one_spectral")]
    #[inline]
    pub fn spectral_reg(&self) -> Option<&RankOneSpectralReg> {
        self.spectral_reg.as_ref()
    }

    /// Get mutable spectral regularizer (if any).
    #[cfg(feature = "rank_one_spectral")]
    pub fn spectral_reg_mut(&mut self) -> Option<&mut RankOneSpectralReg> {
        self.spectral_reg.as_mut()
    }

    /// Configure rank-one spectral regularizer from training config.
    ///
    /// Creates and installs the regularizer, then preallocates the scratch
    /// buffer for the given matrix dimension (max of rows, cols of A matrices).
    /// This is a one-time setup call — zero alloc in the hot training path.
    ///
    /// Does nothing if `config.enable` is `false`.
    #[cfg(feature = "rank_one_spectral")]
    pub fn configure_spectral_reg(&mut self, config: &RankOneTrainingConfig, max_a_dim: usize) {
        if !config.enable {
            return;
        }
        let mut reg = RankOneSpectralReg::from_config(&config.to_spectral_config());
        reg.preallocate(max_a_dim);
        self.spectral_reg = Some(reg);
    }

    /// Finish training the current game.
    ///
    /// Returns the current game ID and removes the active regularizer.
    /// Also clears the spectral regularizer.
    pub fn finish_training(&mut self) -> Option<String> {
        self.active_regularizer = None;
        #[cfg(feature = "rank_one_spectral")]
        {
            self.spectral_reg = None;
        }
        self.current_game.take()
    }

    /// Get number of completed games.
    #[inline]
    pub fn completed_count(&self) -> usize {
        self.completed_games.len()
    }

    /// Get the current game being trained.
    #[inline]
    pub fn current_game(&self) -> Option<&str> {
        self.current_game.as_deref()
    }

    /// Check if currently training.
    #[inline]
    pub fn is_training(&self) -> bool {
        self.current_game.is_some()
    }

    /// Get posteriors for all completed games.
    pub fn completed_games(&self) -> &[(String, LoraPosterior)] {
        &self.completed_games
    }

    /// Get a specific game's posterior.
    pub fn get_posterior(&self, game_id: &str) -> Option<&LoraPosterior> {
        self.completed_games
            .iter()
            .find(|(id, _)| id == game_id)
            .map(|(_, p)| p)
    }
}

impl CreatedClassScorer {
    pub fn new() -> Self {
        Self {
            oracle: ClippyLintOracle::new(),
            baseline: HashMap::new(),
        }
    }

    pub fn with_oracle(oracle: ClippyLintOracle) -> Self {
        Self {
            oracle,
            baseline: HashMap::new(),
        }
    }

    /// False when `cargo` cannot be spawned — callers skip LOUDLY rather than
    /// emitting a `created_rate` of 0.0, which would read as "no regressions".
    pub fn is_available(&self) -> bool {
        self.oracle.is_available()
    }

    fn baseline_lints(&mut self, module: &str, target: &str) -> Option<BTreeSet<String>> {
        let key = (*blake3::hash(module.as_bytes()).as_bytes(), target.to_string());
        if let Some(hit) = self.baseline.get(&key) {
            return hit.clone();
        }
        let verdict = self.oracle.lints_for(module, Some(target));
        // A baseline that does not compile makes every difference meaningless
        // (the candidate's lints would be scored against an empty set, so a
        // healthy fix would look like it created everything).
        let value = match verdict.ran && verdict.compiles {
            true => Some(verdict.lints),
            false => None,
        };
        self.baseline.insert(key, value.clone());
        value
    }

    /// Score one completion against its row.
    pub fn score(&mut self, row: &RlvrRow, completion: &str) -> CreatedOutcome {
        let Some(target) = row.lints.first().cloned() else {
            return CreatedOutcome::Unscoreable("row names no lint".to_string());
        };
        let code = crate::rlvr_extract::extract_code_block(completion);
        if code.trim().is_empty() {
            return CreatedOutcome::Unscoreable("empty completion".to_string());
        }
        let module = prompt_module(&row.prompt).to_string();
        // Mirror the reward path's assembly, byte for byte.
        let candidate = match row.edit_style {
            true => match substitute_diag(&module, code) {
                Ok(merged) => merged,
                Err(e) => return CreatedOutcome::Unscoreable(format!("substitution: {e:?}")),
            },
            false => code.to_string(),
        };
        let Some(before) = self.baseline_lints(&module, &target) else {
            return CreatedOutcome::Unscoreable("baseline unavailable or non-compiling".to_string());
        };
        let after = self.oracle.lints_for(&candidate, Some(&target));
        match after.ran && after.compiles {
            // A non-compiling candidate is a format/correctness failure, which
            // `format_failure_rate` and `p_scored` already count. Counting it
            // here too would double-charge the same completion.
            false => CreatedOutcome::Unscoreable("candidate does not compile".to_string()),
            true => CreatedOutcome::Scored {
                created: after.lints.difference(&before).cloned().collect(),
                target_cleared: !after.lints.contains(&target),
            },
        }
    }
}

impl CreatedClassReport {
    pub fn record(&mut self, outcome: &CreatedOutcome) {
        self.attempts += 1;
        match outcome {
            CreatedOutcome::Unscoreable(_) => self.unscoreable += 1,
            CreatedOutcome::Scored {
                created,
                target_cleared,
            } => {
                self.scored += 1;
                if *target_cleared {
                    self.target_cleared += 1;
                }
                if !created.is_empty() {
                    self.created_any += 1;
                }
                self.created_total += created.len();
                for lint in created {
                    *self.by_lint.entry(lint.clone()).or_insert(0) += 1;
                }
            }
        }
    }

    /// `None` when nothing was scoreable — the gate must see "no measurement",
    /// never a 0.0 that reads as "no regressions".
    pub fn created_rate(&self) -> Option<f64> {
        match self.scored {
            0 => None,
            n => Some(self.created_any as f64 / n as f64),
        }
    }

    pub fn heal_rate(&self) -> Option<f64> {
        match self.scored {
            0 => None,
            n => Some(self.target_cleared as f64 / n as f64),
        }
    }

    pub fn summary(&self) -> String {
        let rate = match self.created_rate() {
            Some(r) => format!("{r:.4}"),
            None => "n/a".to_string(),
        };
        format!(
            "created: attempts {} scored {} unscoreable {} | created_any {} ({}), \
             created_total {}, target_cleared {}",
            self.attempts,
            self.scored,
            self.unscoreable,
            self.created_any,
            rate,
            self.created_total,
            self.target_cleared,
        )
    }
}

