/// Task domain — selects paper-aligned defaults for SC probability and t_act.
///
/// Mirrors `ScTaskType` from the training side but kept independent so this
/// crate's serialization boundary doesn't leak training-side enums.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[repr(u8)]
#[derive(Default)]
pub enum D2fTaskDomain {
    /// Code generation / completion. SC probability 0.95, t_act 0.4.
    #[default]
    Code = 0,
    /// General natural language text. SC probability 0.5, t_act 0.4.
    Text = 1,
    /// Game AI / decision sequences. SC probability 0.7, t_act 0.4.
    Game = 2,
}

impl D2fTaskDomain {
    /// Paper-aligned SC probability for this domain.
    pub fn default_sc_probability(&self) -> f32 {
        match self {
            Self::Code => 0.95,
            Self::Text => 0.50,
            Self::Game => 0.70,
        }
    }

impl SmoothLatentConfig {
