    }
}

impl D2fQualityConfig {
    /// Current config schema version.
    pub const CURRENT_VERSION: u32 = 1;

    /// Code-task defaults: SC on (p=0.95), q-sampling t_act=0.4, no smooth latent.
    ///
    /// This is the paper's recommended configuration for code LoRA training.
    /// SC + q-sampling have large quality gains with low/zero cost; smooth
    /// latent is opt-in because it needs a separate encoder checkpoint.
    pub fn for_code() -> Self {
        Self {
            domain: D2fTaskDomain::Code,
            sc_enabled: true,
            sc_probability: D2fTaskDomain::Code.default_sc_probability(),
            t_act: D2fTaskDomain::Code.default_t_act(),
            smooth_latent_enabled: false,
            smooth_latent: None,
            version: Self::CURRENT_VERSION,
        }
    }

    /// Text-task defaults: SC on (p=0.5), q-sampling t_act=0.4, no smooth latent.
    pub fn for_text() -> Self {
        Self {
            domain: D2fTaskDomain::Text,
            sc_enabled: true,
            sc_probability: D2fTaskDomain::Text.default_sc_probability(),
            t_act: D2fTaskDomain::Text.default_t_act(),
            smooth_latent_enabled: false,
            smooth_latent: None,
            version: Self::CURRENT_VERSION,
        }
    }

    /// Game-task defaults: SC on (p=0.7), q-sampling t_act=0.4, no smooth latent.
    pub fn for_game() -> Self {
        Self {
            domain: D2fTaskDomain::Game,
            sc_enabled: true,
            sc_probability: D2fTaskDomain::Game.default_sc_probability(),
            t_act: D2fTaskDomain::Game.default_t_act(),
            smooth_latent_enabled: false,
            smooth_latent: None,
            version: Self::CURRENT_VERSION,
        }
    }

    /// Custom config with manual tuning.
    ///
    /// Starts from the domain defaults, then overrides `sc_probability` and
    /// `t_act`. Smooth latent can be enabled with `.with_smooth_latent()`.
    pub fn custom(domain: D2fTaskDomain, sc_probability: f32, t_act: f32) -> Self {
        Self {
            domain,
            sc_enabled: true,
            sc_probability,
            t_act,
            smooth_latent_enabled: false,
            smooth_latent: None,
            version: Self::CURRENT_VERSION,
        }
    }

    /// Builder: enable smooth latent encoding with the given checkpoint config.
    #[must_use]
    pub fn with_smooth_latent(mut self, config: SmoothLatentConfig) -> Self {
        self.smooth_latent_enabled = true;
        self.smooth_latent = Some(config);
        self
    }

    /// Builder: disable self-conditioning (not recommended for code).
    #[must_use]
    pub fn without_sc(mut self) -> Self {
        self.sc_enabled = false;
        self
    }

    /// Serialize to JSON.
    pub fn to_json(&self) -> Result<String, serde_json::Error> {
        serde_json::to_string_pretty(self)
    }

    /// Deserialize from JSON.
    pub fn from_json(json: &str) -> Result<Self, serde_json::Error> {
        serde_json::from_str(json)
    }

    /// Whether this config's schema version is compatible with the current code.
    ///
    /// Returns `Ok(())` if the version is understood, `Err(message)` otherwise.
    /// Consumers should call this after deserialization to reject future
    /// schema versions they can't handle.
    pub fn check_version(&self) -> Result<(), String> {
        if self.version > Self::CURRENT_VERSION {
            return Err(format!(
                "D2fQualityConfig version {} is newer than supported (max {}); \
                 upgrade the consumer crate",
                self.version,
                Self::CURRENT_VERSION
            ));
        }
        Ok(())
    }

    /// Effective t_act clamped to valid range [0.0, 1.0].
    ///
    /// Defensive: guards against malformed configs from external sources.
    pub fn effective_t_act(&self) -> f32 {
        self.t_act.clamp(0.0, 1.0)
    }

    /// Whether q-sampling is active at the given denoising step ratio.
    ///
    /// `step_ratio` is `current_step / total_steps` ∈ [0.0, 1.0].
    /// Returns `true` when q-sampling should be used (at/after `t_act`).
    pub fn use_q_sampling_at(&self, step_ratio: f32) -> bool {
        step_ratio >= self.effective_t_act()
    }
}

impl RolloutSet {
    /// The Issue-717 live-rule accounting: every row in this set is a
    /// TEACHER-GENERATED novel continuation (the generator writes only
    /// rollouts it decoded itself), so the set's live share is 1.0 by
    /// construction — recorded explicitly because the mix validation
    /// refuses a training config whose live share is 0.
    pub const LIVE_SHARE: f32 = 1.0;

    /// Load + digest. Rows are validated (n_prompt < tokens.len() > 0).
    pub fn load(path: &Path) -> Result<Self, String> {
        let text =
            std::fs::read_to_string(path).map_err(|e| format!("read {}: {e}", path.display()))?;
        let mut rows = Vec::new();
        let mut hasher = blake3::Hasher::new();
        for (ln, line) in text.lines().enumerate() {
            if line.trim().is_empty() {
                continue;
            }
            let row: RolloutRow =
                serde_json::from_str(line).map_err(|e| format!("{}:{ln}: {e}", path.display()))?;
            if row.tokens.is_empty() || row.n_prompt == 0 || row.n_prompt >= row.tokens.len() {
                return Err(format!(
                    "{}:{ln}: degenerate row (n_prompt {}, {} tokens)",
                    path.display(),
                    row.n_prompt,
                    row.tokens.len()
                ));
            }
            // Canonical digest input: lengths + token bytes in file order.
            hasher.update(&(row.prompt.len() as u64).to_le_bytes());
            hasher.update(row.prompt.as_bytes());
            hasher.update(&(row.tokens.len() as u64).to_le_bytes());
            for t in &row.tokens {
                hasher.update(&t.to_le_bytes());
            }
            hasher.update(&(row.n_prompt as u64).to_le_bytes());
            rows.push(row);
        }
        if rows.is_empty() {
            return Err(format!("{}: no rows", path.display()));
        }
        Ok(Self {
            rows,
            digest: hasher.finalize().to_hex().to_string(),
        })
    }

    /// Append rows (the generator's resume path) — recompute-free append
    /// with the same canonical order; the digest is only finalized by
    /// [`RolloutSet::load`].
    pub fn append_row(path: &Path, row: &RolloutRow) -> Result<(), String> {
        use std::io::Write;
        let mut f = std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(path)
            .map_err(|e| format!("open {}: {e}", path.display()))?;
        let line = serde_json::to_string(row).map_err(|e| format!("json: {e}"))?;
        writeln!(f, "{line}").map_err(|e| format!("write: {e}"))
    }

    pub fn total_tokens(&self) -> usize {
        self.rows.iter().map(|r| r.tokens.len()).sum()
    }

    pub fn total_generated(&self) -> usize {
        self.rows.iter().map(|r| r.tokens.len() - r.n_prompt).sum()
    }
}

impl SelectorHead {
    /// Adopt loaded weights (the example loads them from the z-lab
    /// safetensors via `load_dflash2_safetensors`). Panics on shape
    /// mismatch — a silently reshaped head would train garbage.
    #[must_use]
    pub fn from_parts(
        cfg: SelectorConfig,
        sel_hidden: Vec<f32>,
        sel_prev: Vec<f32>,
        sel_next: Vec<f32>,
    ) -> Self {
        assert_eq!(sel_hidden.len(), cfg.rank * cfg.n_embd, "sel_hidden shape");
        assert_eq!(sel_prev.len(), cfg.vocab_size * cfg.rank, "sel_prev shape");
        assert_eq!(sel_next.len(), cfg.vocab_size * cfg.rank, "sel_next shape");
        Self {
            cfg,
            sel_hidden,
            sel_prev,
            sel_next,
        }
    }

    #[inline]
    fn code(&self, hidden_row: &[f32]) -> Vec<f32> {
        let r = self.cfg.rank;
        let e = self.cfg.n_embd;
        // Parallel over rank rows (the `gemv_into_par` convention of the
        // CPU oracle this head mirrors — each row is an independent
        // 5120-deep dot; 256 rows × 7 slots per anchor amortizes the
        // rayon fork).
        let c: Vec<f32> = self
            .sel_hidden
            .par_chunks_exact(e)
            .map(|row| {
                let mut acc = 0.0f32;
                for (ei, &hv) in row.iter().enumerate() {
                    acc += hv * hidden_row[ei];
                }
                acc
            })
            .collect();
        debug_assert_eq!(c.len(), r);
        c
    }

    /// One slot's candidate scores — the `lattice_walk` body verbatim
    /// (dot of the successor codebook row with `(pcode ⊙ code)`, plus the
    /// unary logit). `extra_candidates` are appended after the top-k (the
    /// teacher target, when absent — the loss needs its score computable;
    /// at inference it would never be selectable, which is exactly why the
    /// trainer tracks the in-top-k rate as the ceiling diagnostic).
    #[must_use]
    pub fn slot_scores(
        &self,
        pred_token: u32,
        code: &[f32],
        logits_row: &[f32],
        candidates: &[u32],
    ) -> Vec<f32> {
        let r = self.cfg.rank;
        let prow = pred_token as usize * r;
        let pcode = &self.sel_prev[prow..prow + r];
        let mut scores = Vec::with_capacity(candidates.len());
        for &tok in candidates {
            let nrow = tok as usize * r;
            let ncode = &self.sel_next[nrow..nrow + r];
            let mut dot = 0.0f32;
            for ri in 0..r {
                dot += ncode[ri] * (pcode[ri] * code[ri]);
            }
            scores.push(dot + logits_row[tok as usize]);
        }
        scores
    }

    /// One slot's greedy walk pick — the runtime `lattice_walk` argmax over
    /// the top-k candidate scores (dot + unary, first-index-ties convention
    /// matching `lattice_walk`'s `s > best_s` scan), with the `sel_hidden`
    /// code computed here from the slot's hidden row. The trainer's v2 chain
    /// policy consumes this to simulate the walk's own self-chaining (the
    /// Bench-820 lever: the runtime walk's slot-i predecessor is its OWN
    /// slot-(i-1) pick, never the teacher's token).
    #[must_use]
    pub fn walk_pick(
        &self,
        pred_token: u32,
        hidden_row: &[f32],
        logits_row: &[f32],
        candidates: &[u32],
    ) -> u32 {
        debug_assert_eq!(hidden_row.len(), self.cfg.n_embd);
        let code = self.code(hidden_row);
        let scores = self.slot_scores(pred_token, &code, logits_row, candidates);
        let mut best = 0usize;
        let mut best_s = f32::NEG_INFINITY;
        for (ki, &s) in scores.iter().enumerate() {
            if s > best_s {
                best_s = s;
                best = ki;
            }
        }
        candidates[best]
    }
}

impl SelectorHead {
    /// Forward + loss + backward for ONE anchor. Accumulates into `grads`
    /// (caller zeroes between micro-batches). Teacher-forced chain: each
    /// slot's `pred_token` comes from the teacher sequence, NOT the walk —
    /// see the module doc for why that is the honest objective.
    pub fn accumulate_anchor(&self, anchor: &TrainAnchor, grads: &mut SelectorGrads) -> AnchorLoss {
        let e = self.cfg.n_embd;
        let r = self.cfg.rank;
        let n_slots = anchor.slots.len();
        assert_eq!(
            anchor.hidden_rows.len(),
            n_slots * e,
            "hidden_rows flat len"
        );
        assert_eq!(
            anchor.logits.len(),
            n_slots * self.cfg.vocab_size,
            "logits flat len"
        );

        let mut out = AnchorLoss {
            n_slots,
            ..AnchorLoss::default()
        };

        // Dense per-anchor buffer for the sel_hidden grad contribution
        // (d code[r] accumulated across slots, scattered once below).
        let mut g_code_dense = vec![0.0f32; r];

        for (i, slot) in anchor.slots.iter().enumerate() {
            let hidden_row = &anchor.hidden_rows[i * e..(i + 1) * e];
            let logits_row = &anchor.logits[i * self.cfg.vocab_size..(i + 1) * self.cfg.vocab_size];

            let code = self.code(hidden_row);
            // Candidate set = top-k ∪ {target} (append if absent, keeping
            // top-k order first — the score math is order-independent but
            // the diagnostic wants to know membership).
            let target_in_topk = slot.candidates.contains(&slot.target_token);
            if target_in_topk {
                out.n_target_in_topk += 1;
            }
            let mut cands = slot.candidates.clone();
            if !target_in_topk {
                cands.push(slot.target_token);
            }

            let scores = self.slot_scores(slot.pred_token, &code, logits_row, &cands);
            debug_assert_eq!(scores.len(), cands.len());

            // CE over softmax(scores), target index located first.
            let t_idx = cands
                .iter()
                .position(|&t| t == slot.target_token)
                .expect("target appended above");
            let max = scores.iter().copied().fold(f32::NEG_INFINITY, f32::max);
            let mut sum = 0.0f32;
            for &s in &scores {
                sum += (s - max).exp();
            }
            let log_sum = max + sum.ln();
            out.loss += log_sum - scores[t_idx];

            // dL/dscore_k = p_k - 1{k==t}.
            let inv_sum = 1.0 / sum;
            let prow = slot.pred_token as usize * r;
            let pcode = &self.sel_prev[prow..prow + r];

            // Accumulate per-rank gradient parts across candidates, then
            // scatter once per tensor row (the pred row is shared by all
            // candidates of this slot).
            let mut d_code = vec![0.0f32; r];
            let mut d_pcode = vec![0.0f32; r];
            for (k, &tok) in cands.iter().enumerate() {
                let d_k = ((scores[k] - max).exp() * inv_sum) - if k == t_idx { 1.0 } else { 0.0 };
                if d_k == 0.0 {
                    continue;
                }
                let nrow = tok as usize * r;
                let ncode = &self.sel_next[nrow..nrow + r];
                let gnext_row = &mut grads.g_next[nrow..nrow + r];
                for (((((nc, &pc), &cc), gn), dc), dp) in ncode
                    .iter()
                    .zip(pcode.iter())
                    .zip(code.iter())
                    .zip(gnext_row.iter_mut())
                    .zip(d_code.iter_mut())
                    .zip(d_pcode.iter_mut())
                {
                    // d score_k/d sel_next[tok][r] = pcode[r]·code[r]
                    *gn += d_k * pc * cc;
                    // d score_k/d pcode[r] = ncode[r]·code[r]
                    *dp += d_k * nc * cc;
                    // d score_k/d code[r] = ncode[r]·pcode[r]
                    *dc += d_k * nc * pc;
                }
            }
            for (ri, gv) in grads.g_prev[prow..prow + r].iter_mut().enumerate() {
                *gv += d_pcode[ri];
            }

            // d code[r] -> sel_hidden grad row r: += d_code[r] · hidden_row.
            for (ri, &dc) in d_code.iter().enumerate() {
                if dc == 0.0 {
                    continue;
                }
                let grow = &mut grads.g_hidden[ri * e..(ri + 1) * e];
                for (ge, &hv) in grow.iter_mut().zip(hidden_row.iter()) {
                    *ge += dc * hv;
                }
            }
            g_code_dense.copy_from_slice(&d_code); // (kept for debug symmetry)
            let _ = g_code_dense;
        }

        out.loss /= n_slots as f32;
        out
    }
}

impl SelectorAdamW {
    #[must_use]
    pub fn new(head: &SelectorHead, lr: f32) -> Self {
        let n = head.cfg.rank * head.cfg.n_embd;
        let nv = head.cfg.vocab_size * head.cfg.rank;
        Self {
            lr,
            beta1: 0.9,
            beta2: 0.95,
            eps: 1.0e-8,
            weight_decay: 0.01,
            step: 0,
            m_hidden: vec![0.0; n],
            v_hidden: vec![0.0; n],
            m_prev: vec![0.0; nv],
            v_prev: vec![0.0; nv],
            m_next: vec![0.0; nv],
            v_next: vec![0.0; nv],
        }
    }

    /// One in-place AdamW step over all three tensors.
    #[allow(clippy::too_many_arguments)]
    pub fn step(&mut self, head: &mut SelectorHead, grads: &SelectorGrads) {
        self.step += 1;
        let t = self.step as f32;
        let bc1 = 1.0 - self.beta1.powf(t);
        let bc2 = 1.0 - self.beta2.powf(t);
        let lr = self.lr;

        fn apply(
            w: &mut [f32],
            g: &[f32],
            m: &mut [f32],
            v: &mut [f32],
            lr: f32,
            b1: f32,
            b2: f32,
            eps: f32,
            wd: f32,
            bc1: f32,
            bc2: f32,
        ) {
            // Production shape is 63.6M params per codebook — the step is
            // bandwidth-bound; the par zip keeps the exact per-element
            // update order irrelevant (element-independent math).
            w.par_iter_mut()
                .zip(g.par_iter())
                .zip(m.par_iter_mut())
                .zip(v.par_iter_mut())
                .for_each(|(((wi, &gi), mi), vi)| {
                    *mi = b1 * *mi + (1.0 - b1) * gi;
                    *vi = b2 * *vi + (1.0 - b2) * gi * gi;
                    let mh = *mi / bc1;
                    let vh = *vi / bc2;
                    // Decoupled weight decay (AdamW), on the weight.
                    *wi -= lr * (mh / (vh.sqrt() + eps) + wd * *wi);
                });
        }

        apply(
            &mut head.sel_hidden,
            &grads.g_hidden,
            &mut self.m_hidden,
            &mut self.v_hidden,
            lr,
            self.beta1,
            self.beta2,
            self.eps,
            self.weight_decay,
            bc1,
            bc2,
        );
        apply(
            &mut head.sel_prev,
            &grads.g_prev,
            &mut self.m_prev,
            &mut self.v_prev,
            lr,
            self.beta1,
            self.beta2,
            self.eps,
            self.weight_decay,
            bc1,
            bc2,
        );
        apply(
            &mut head.sel_next,
            &grads.g_next,
            &mut self.m_next,
            &mut self.v_next,
            lr,
            self.beta1,
            self.beta2,
            self.eps,
            self.weight_decay,
            bc1,
            bc2,
        );
    }
}

