use anyhow::{Result, bail};

// ── Config ────────────────────────────────────────────────────────

/// Configuration for DL-QAT decomposition.
#[derive(Debug, Clone, Copy)]
pub struct DlQatConfig {
    /// Number of weights per magnitude group (default: 128).
    pub group_size: usize,
    /// LoRA rank for direction adaptation.
    pub rank: usize,
    /// STE quantization enabled.
    pub ste_enabled: bool,
}

impl Default for DlQatConfig {
    fn default() -> Self {
        Self {
            group_size: 128,
            rank: 8,
            ste_enabled: true,
        }
    }

impl DlQatWeights {
    /// Decompose flat weights into magnitude + direction.
    ///
    /// - `magnitude[g]` = L2 norm of group g
    /// - `direction[g]` = `weights[g] / magnitude[g]` (normalized)
    ///
    /// Zero groups (all weights = 0) produce magnitude 0.0 and zero direction.
    pub fn decompose(weights: &[f32], group_size: usize) -> Result<Self> {
        if group_size == 0 {
            bail!("group_size must be > 0");
        }
        if weights.is_empty() {
            return Ok(Self {
                magnitudes: Vec::new(),
                directions: Vec::new(),
                lora_a: Vec::new(),
                lora_b: Vec::new(),
            });
        }

        if !weights.len().is_multiple_of(group_size) {
            bail!(
                "weights length ({}) must be divisible by group_size ({})",
                weights.len(),
                group_size
            );
        }

        let n_groups = weights.len() / group_size;
        let mut magnitudes = Vec::with_capacity(n_groups);
        let mut directions = Vec::with_capacity(n_groups);

        for g in 0..n_groups {
            let start = g * group_size;
            let group = &weights[start..start + group_size];

            // L2 norm = sqrt(sum of squares)
            let l2 = group.iter().map(|v| v * v).sum::<f32>().sqrt();
            magnitudes.push(l2);

            // Normalized direction: group / l2. Zero group → zero direction.
            let dir = if l2 < f32::EPSILON { vec![0.0; group_size] } else { group.iter().map(|&v| v / l2).collect() };
            directions.push(dir);
        }

        Ok(Self {
            magnitudes,
            directions,
            lora_a: Vec::new(),
            lora_b: Vec::new(),
        })
    }

    /// Reconstruct weights from magnitude + direction.
    ///
    /// `output[g][i] = magnitude[g] * direction[g][i]`
    ///
    /// `output` must have length equal to `n_groups * group_size`.
    pub fn reconstruct(&self, output: &mut [f32]) {
        let group_size = match self.directions.first() {
            Some(d) => d.len(),
            None => return, // empty decomposition
        };

        for (g, dir) in self.directions.iter().enumerate() {
            let start = g * group_size;
            let mag = self.magnitudes[g];
            for (i, &d) in dir.iter().enumerate() {
                output[start + i] = mag * d;
            }
        }
    }

    /// Merge into quantized base weights.
    ///
    /// For each element `i` in group `g`:
    /// ```text
    /// delta = round(magnitude[g] * direction[g][i] / q_scale)
    /// base_q[i] += delta
    /// base_q[i] = clamp(base_q[i], -128, 127)
    /// ```
    pub fn merge_to_quantized(&self, base_q: &mut [i8], q_scale: f32) {
        if q_scale.abs() < f32::EPSILON {
            return;
        }

        let group_size = match self.directions.first() {
            Some(d) => d.len(),
            None => return,
        };

        for (g, dir) in self.directions.iter().enumerate() {
            let mag = self.magnitudes[g];
            for (i, &d) in dir.iter().enumerate() {
                let idx = g * group_size + i;
                if idx >= base_q.len() {
                    break;
                }
                let delta = (mag * d / q_scale).round() as i32;
                let new_val = base_q[idx] as i32 + delta;
                base_q[idx] = new_val.clamp(-128, 127) as i8;
            }
        }
    }

    /// Apply LoRA direction refinement.
    ///
    /// For each element: `output[i] = input[i] + (B @ A @ input[i]) * scale`
    ///
    /// `lora_a` is `[rank × dim]`, `lora_b` is `[dim × rank]`.
    /// Falls back to identity if LoRA matrices are empty (not initialized).
    pub fn apply_direction_lora(&self, input: &[f32], output: &mut [f32]) {
        if self.lora_a.is_empty() || self.lora_b.is_empty() {
            // No LoRA — copy input directly.
            output.copy_from_slice(input);
            return;
        }

        let dim = input.len();
        let rank = match dim {
            0 => {
                output.copy_from_slice(input);
                return;
            }
            _ => self.lora_a.len() / dim,
        };

        let lora_scale = 1.0 / (rank as f32).sqrt();

        // Compute hidden = A @ input ONCE outside the i-loop — the original
        // code recomputed hidden[k] inside the i-loop, turning an
        // O(dim*rank) LoRA forward into O(dim^2*rank) (a dim-x slowdown
        // on this primitive; for dim=512 that's 512x).
        // hidden[k] = Σ_j A[k * dim + j] * input[j]
        // lora_out[i] = Σ_k B[i * rank + k] * hidden[k]
        let mut hidden: Vec<f32> = vec![0.0f32; rank];
        for (k, h_slot) in hidden.iter_mut().enumerate().take(rank) {
            let row_off = k * dim;
            let mut s = 0.0f32;
            for (j, &inp) in input.iter().enumerate() {
                s += self.lora_a[row_off + j] * inp;
            }
            *h_slot = s;
        }

        for i in 0..dim {
            let row_off = i * rank;
            let mut lora_out = 0.0f32;
            for (k, &h) in hidden.iter().enumerate().take(rank) {
                lora_out += self.lora_b[row_off + k] * h;
            }
            output[i] = input[i] + lora_out * lora_scale;
        }
    }
}

