impl FfXgbField {
    /// Nearest time level to `t` — the field is piecewise-constant in time by
    /// construction, which is what "one regressor per level" means.
    fn level_of(&self, t: f32) -> usize {
        let mut best = 0usize;
        let mut bd = f32::INFINITY;
        for (i, l) in self.levels.iter().enumerate() {
            let d = (l - t).abs();
            if d < bd {
                bd = d;
                best = i;
            }
        }
        best
    }

    #[must_use]
    pub fn n_levels(&self) -> usize {
        self.levels.len()
    }

    #[must_use]
    pub fn total_trees(&self) -> usize {
        self.banks
            .iter()
            .flat_map(|b| b.iter())
            .map(Gbm::n_trees)
            .sum()
    }
}

impl ZStats {
    #[must_use]
    pub fn fit(rows: &[Vec<f32>]) -> Self {
        let dim = rows[0].len();
        let n = rows.len() as f32;
        let mut mean = vec![0.0f32; dim];
        for r in rows {
            for (m, v) in mean.iter_mut().zip(r) {
                *m += v / n;
            }
        }
        let mut var = vec![0.0f32; dim];
        for r in rows {
            for ((s, v), m) in var.iter_mut().zip(r).zip(&mean) {
                *s += (v - m) * (v - m) / n;
            }
        }
        Self {
            mean,
            // Floor the scale: a constant lane has zero variance and would
            // divide to inf, turning an uninformative feature into the
            // dominant one.
            scale: var.iter().map(|v| v.sqrt().max(1e-6)).collect(),
        }
    }

    #[must_use]
    pub fn apply(&self, rows: &[Vec<f32>]) -> Vec<Vec<f32>> {
        rows.iter()
            .map(|r| {
                r.iter()
                    .zip(&self.mean)
                    .zip(&self.scale)
                    .map(|((v, m), s)| (v - m) / s)
                    .collect()
            })
            .collect()
    }
}

impl TimeEmbedding {
    /// Write `Emb(t)` into `out` (`dim` long, interleaved sin/cos pairs).
    ///
    /// # Panics
    /// If `out.len() != dim` or `dim` is odd (pairs would be truncated).
    pub fn embed_into(&self, t: f32, out: &mut [f32]) {
        assert_eq!(out.len(), self.dim, "time embedding width");
        assert!(self.dim.is_multiple_of(2), "time embedding dim must be even");
        let half = self.dim / 2;
        for i in 0..half {
            // Geometric frequency ladder, as in the usual positional encoding.
            let freq = (10_000f32).powf(-(i as f32) / half as f32);
            let a = t * freq * std::f32::consts::TAU;
            out[2 * i] = a.sin();
            out[2 * i + 1] = a.cos();
        }
    }
}

