impl Adam {
    fn new(n: usize) -> Self {
        Self {
            m: vec![0.0; n],
            v: vec![0.0; n],
            step: 0,
        }
    }

    fn apply(&mut self, p: &mut [f32], g: &[f32], lr: f32) {
        self.step += 1;
        let t = self.step as f32;
        let (b1, b2, eps) = (0.9f32, 0.999f32, 1e-8f32);
        let bc1 = 1.0 - b1.powf(t);
        let bc2 = 1.0 - b2.powf(t);
        for i in 0..p.len() {
            self.m[i] = b1 * self.m[i] + (1.0 - b1) * g[i];
            self.v[i] = b2 * self.v[i] + (1.0 - b2) * g[i] * g[i];
            p[i] -= lr * (self.m[i] / bc1) / ((self.v[i] / bc2).sqrt() + eps);
        }
    }
}

impl TccmField {
    /// He-initialized weights, zero biases.
    #[must_use]
    pub fn new(cfg: TccmConfig) -> Self {
        let mut rng = Rng::new(cfg.seed);
        let mut draw = |n: usize, fan_in: usize| -> Vec<f32> {
            let s = (2.0 / fan_in as f32).sqrt();
            (0..n)
                .map(|_| {
                    let u = (rng.next() >> 40) as f32 / (1u64 << 24) as f32;
                    (u * 2.0 - 1.0) * s
                })
                .collect()
        };
        let (i, h, o) = (cfg.in_dim(), cfg.hidden, cfg.feat_dim);
        Self {
            emb: TimeEmbedding { dim: cfg.time_dim },
            w1: draw(h * i, i),
            b1: vec![0.0; h],
            w2: draw(h * h, h),
            b2: vec![0.0; h],
            w3: draw(o * h, h),
            b3: vec![0.0; o],
            cfg,
        }
    }

    #[must_use]
    pub fn config(&self) -> TccmConfig {
        self.cfg
    }

    /// BLAKE3 over every parameter, in a fixed order — the freeze/thaw envelope
    /// checksum Plan 350 T1.2 requires for a frozen artifact.
    ///
    /// Bytes come from `to_le_bytes`, so the digest is architecture-independent
    /// and a snapshot checksummed on one box verifies on another.
    #[must_use]
    pub fn checksum(&self) -> String {
        let mut h = Hasher::new();
        for slab in [&self.w1, &self.b1, &self.w2, &self.b2, &self.w3, &self.b3] {
            for v in slab {
                h.update(&v.to_le_bytes());
            }
        }
        h.finalize().to_hex().to_string()
    }

    /// Forward, returning the two hidden pre-activations for the backward.
    fn forward_full(&self, x: &[f32], t: f32, h1: &mut [f32], h2: &mut [f32], out: &mut [f32]) {
        let (fd, td, hid) = (self.cfg.feat_dim, self.cfg.time_dim, self.cfg.hidden);
        let mut inp = vec![0.0f32; fd + td];
        inp[..fd].copy_from_slice(x);
        self.emb.embed_into(t, &mut inp[fd..]);

        for ((o, row), b) in h1
            .iter_mut()
            .zip(self.w1.chunks_exact(fd + td))
            .zip(&self.b1)
        {
            *o = (row.iter().zip(&inp).map(|(w, i)| w * i).sum::<f32>() + b).max(0.0);
        }
        // h1 is read while h2 is written, so take the slice split explicitly
        // rather than aliasing through a single iterator chain.
        let h1_ro: &[f32] = h1;
        for ((o, row), b) in h2
            .iter_mut()
            .zip(self.w2.chunks_exact(hid))
            .zip(&self.b2)
        {
            *o = (row.iter().zip(h1_ro).map(|(w, i)| w * i).sum::<f32>() + b).max(0.0);
        }
        let h2_ro: &[f32] = h2;
        for ((o, row), b) in out
            .iter_mut()
            .zip(self.w3.chunks_exact(hid))
            .zip(&self.b3)
        {
            *o = row.iter().zip(h2_ro).map(|(w, i)| w * i).sum::<f32>() + b;
        }
    }
}

impl Predicate {
    /// Human-readable FOL-like string for this predicate.
    pub fn to_fol_string(&self) -> String {
        match self {
            Self::StateEquals { field, value } => format!("{field} = {value:.2}"),
            Self::StateGreaterThan { field, threshold } => {
                format!("{field} > {threshold:.2}")
            }
            Self::StateLessThan { field, threshold } => {
                format!("{field} < {threshold:.2}")
            }
            Self::Not(inner) => format!("¬({})", inner.to_fol_string()),
        }
    }
}

impl GameRule {
    /// Human-readable FOL-like string for this rule.
    ///
    /// Format: `⟨cond1⟩ ∧ ⟨cond2⟩ → ⟨action⟩ [weight=0.87, support=142]`
    pub fn to_fol_string(&self) -> String {
        let cond_str = match self.conditions.len() {
            0 => "true".to_string(),
            1 => self.conditions[0].to_fol_string(),
            _ => self
                .conditions
                .iter()
                .map(|c| c.to_fol_string())
                .collect::<Vec<_>>()
                .join(" ∧ "),
        };
        format!(
            "{} → {} [weight={:.2}, support={}]",
            cond_str, self.action_name, self.weight, self.support
        )
    }
}

impl FeatureMapping {
    /// Discretize a continuous value into a bin index.
    ///
    /// Returns `None` if `n_bins == 0` or the range is degenerate.
    pub fn bin_index(&self, value: f32) -> Option<usize> {
        if self.n_bins == 0 { None } else {
                let range = self.max_val - self.min_val;
                if range <= 0.0 {
                    return None;
                }
                let normalized = (value - self.min_val) / range;
                let bin = (normalized * self.n_bins as f32) as usize;
                Some(bin.min(self.n_bins - 1))
            }
    }

    /// Convert a bin index back to a threshold value (bin center).
    pub fn bin_to_threshold(&self, bin: usize) -> f32 {
        let range = self.max_val - self.min_val;
        let bin = bin.min(self.n_bins.saturating_sub(1));
        self.min_val + (bin as f32 + 0.5) * range / self.n_bins.max(1) as f32
    }
}

