impl<'a> LoraWeightView<'a> {
    /// Validate internal consistency of dimensions vs slice lengths.
    pub fn validate(&self) -> anyhow::Result<()> {
        let expected_a = self.in_dim * self.rank;
        let expected_b = self.rank * self.out_dim;
        ensure!(
            self.a_matrix.len() == expected_a,
            "a_matrix len {} != in_dim {} * rank {} = {}",
            self.a_matrix.len(),
            self.in_dim,
            self.rank,
            expected_a,
        );
        ensure!(
            self.b_matrix.len() == expected_b,
            "b_matrix len {} != rank {} * out_dim {} = {}",
            self.b_matrix.len(),
            self.rank,
            self.out_dim,
            expected_b,
        );
        Ok(())
    }

impl FolRuleExtractor {
    /// Create a new extractor with custom parameters.
    pub fn new(weight_threshold: f32, top_k_rules: usize) -> Self {
        Self {
            weight_threshold,
            top_k_rules,
        }
    }

    /// Extract FOL-like game rules from a LoRA weight view.
    ///
    /// Algorithm:
    /// 1. Compute L2 norm for each B matrix column (one per action).
    /// 2. Sort columns by norm descending, take top-k.
    /// 3. For each top column j (action):
    ///    a. Find high-magnitude rows in B[:, j] above threshold.
    ///    b. For each active row k, look up the A matrix row norms for
    ///    each input dimension i where `A[i, k]` is significant.
    ///    c. Discretize into predicates using the state feature map.
    /// 4. Return rules sorted by weight descending.
    pub fn extract_rules(
        &self,
        view: &LoraWeightView,
        state_map: &StateFeatureMap,
    ) -> anyhow::Result<Vec<GameRule>> {
        view.validate()
            .context("LoRA weight view validation failed")?;
        state_map
            .validate(view)
            .context("state feature map validation failed")?;

        // Step 1: Compute column norms and sort by descending magnitude.
        let mut col_norms: Vec<(usize, f32)> = (0..view.out_dim)
            .map(|j| (j, view.b_column_norm(j)))
            .collect();
        col_norms.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));

        let max_norm = col_norms.first().map_or(0.0, |(_, n)| *n);

        if max_norm < f32::EPSILON {
            return Ok(vec![]);
        }

        let active_threshold = self.weight_threshold * max_norm;

        // Step 2: For each top-k column, extract a rule.
        let mut rules: Vec<GameRule> = Vec::with_capacity(self.top_k_rules);

        for &(col_j, col_norm) in col_norms.iter().take(self.top_k_rules) {
            if col_norm < active_threshold {
                break;
            }

            let action_name = match state_map.output_actions.get(col_j) {
                Some(name) => name.clone(),
                None => format!("action_{col_j}"),
            };

            // Step 3: Find high-magnitude elements in B[:, col_j].
            // Each rank index k that has |B[k, j]| above threshold
            // contributes to this rule.
            let mut b_values: Vec<(usize, f32)> = (0..view.rank)
                .map(|k| (k, view.b(k, col_j)))
                .filter(|(_, v)| v.abs() >= active_threshold)
                .collect();
            b_values.sort_by(|a, b| {
                b.1.abs()
                    .partial_cmp(&a.1.abs())
                    .unwrap_or(std::cmp::Ordering::Equal)
            });

            // Worst case: one condition per b_value (bounded by b_values.len()).
            let mut conditions: Vec<Predicate> = Vec::with_capacity(b_values.len());

            for &(rank_k, b_val) in &b_values {
                // For this rank index k, find which input dimensions
                // have high A[i, k] values.
                let a_col_max = (0..view.in_dim)
                    .map(|i| view.a(i, rank_k).abs())
                    .fold(0.0f32, f32::max);

                if a_col_max < f32::EPSILON {
                    continue;
                }

                let a_threshold = self.weight_threshold * a_col_max;

                for i in 0..view.in_dim {
                    let a_val = view.a(i, rank_k);
                    if a_val.abs() < a_threshold {
                        continue;
                    }

                    let feature = match state_map.input_features.get(i) {
                        Some(f) => f,
                        None => continue,
                    };

                    // Discretize: A row norm → bin → threshold → predicate.
                    let a_row_norm = view.a_row_norm(i);
                    let predicate = self.build_predicate(feature, a_row_norm, b_val);

                    // Deduplicate: skip if we already have a predicate for this field
                    // with the same kind.
                    let already_exists = conditions.iter().any(|p| {
                        matches!(p,
                            Predicate::StateGreaterThan { field, .. }
                            | Predicate::StateLessThan { field, .. }
                            | Predicate::StateEquals { field, .. }
                            if field == &feature.name
                        )
                    });
                    if !already_exists {
                        conditions.push(predicate);
                    }
                }
            }

            // Estimate support: proportional to column norm squared
            // relative to max, scaled by a heuristic factor.
            let support = self.estimate_support(col_norm, max_norm);

            rules.push(GameRule {
                conditions,
                action: col_j,
                action_name,
                weight: col_norm,
                support,
            });
        }

        // Sort rules by weight descending (already roughly sorted, but ensure).
        rules.sort_by(|a, b| {
            b.weight
                .partial_cmp(&a.weight)
                .unwrap_or(std::cmp::Ordering::Equal)
        });

        Ok(rules)
    }

    /// Build a predicate from a feature mapping, A row norm, and B value sign.
    ///
    /// The B value sign determines direction: positive → GreaterThan,
    /// negative → LessThan. The A row norm determines the threshold
    /// via discretization against the feature's bin range.
    fn build_predicate(&self, feature: &FeatureMapping, a_row_norm: f32, b_val: f32) -> Predicate {
        // Normalize A row norm to [0, 1] range using sigmoid-like clamping.
        let normalized = (a_row_norm / (1.0 + a_row_norm)).clamp(0.0, 1.0);
        let bin = if let Some(b) = feature
            .bin_index(feature.min_val + normalized * (feature.max_val - feature.min_val)) { b } else {
                return Predicate::StateEquals {
                    field: feature.name.clone(),
                    value: 0.0,
                };
            };
        let threshold = feature.bin_to_threshold(bin);

        if b_val >= 0.0 { Predicate::StateGreaterThan {
                field: feature.name.clone(),
                threshold,
            } } else { Predicate::StateLessThan {
                field: feature.name.clone(),
                threshold,
            } }
    }

    /// Heuristic support estimate from column norm ratio.
    ///
    /// Higher ratio → more training episodes drove this connection.
    /// The absolute numbers are synthetic but preserve relative ranking.
    fn estimate_support(&self, col_norm: f32, max_norm: f32) -> u32 {
        if max_norm < f32::EPSILON {
            return 0;
        }
        let ratio = col_norm / max_norm;
        // Sigmoid-like mapping: ratio ∈ [0, 1] → support ∈ [0, 1000].
        let raw = 1000.0 / (1.0 + (-6.0 * (ratio - 0.5)).exp());
        raw as u32
    }
}

impl FolToLoraConverter {
    /// Create a new converter with the given config and feature map.
    pub fn new(config: FolToLoraConfig, feature_map: StateFeatureMap) -> Self {
        Self {
            config,
            feature_map,
        }
    }

    /// Inject rule biases into mutable LoRA weight slices.
    ///
    /// For each rule (up to `max_rules`, filtered by `min_support`):
    /// 1. Map each predicate condition to one or more input feature indices.
    /// 2. Map the rule action to an output dimension index.
    /// 3. Compute bias value: `rule.weight * bias_strength * sigmoid(support)`.
    /// 4. Add bias to B matrix at `[rank_col, output_idx]` (rank column 0).
    /// 5. Add bias to A matrix at `[input_idx, rank_col]` (rank column 0).
    ///
    /// Layout: `a_matrix` is `[in_dim × rank]` row-major,
    ///          `b_matrix` is `[rank × out_dim]` row-major.
    ///
    /// Returns a `KnowledgeInitResult` with statistics.
    pub fn convert_rules_to_bias(
        &self,
        rules: &[GameRule],
        a_matrix: &mut [f32],
        b_matrix: &mut [f32],
        in_dim: usize,
        out_dim: usize,
        rank: usize,
    ) -> KnowledgeInitResult {
        let mut rules_applied = 0usize;
        let mut total_bias_connections = 0usize;
        let mut biased_outputs = vec![false; out_dim];

        let effective_rules: Vec<&GameRule> = rules
            .iter()
            .filter(|r| (r.support as usize) >= self.config.min_support)
            .take(self.config.max_rules)
            .collect();

        for rule in &effective_rules {
            let output_idx = rule.action;
            if output_idx >= out_dim {
                continue;
            }

            let input_indices = self.map_predicates_to_inputs(&rule.conditions, in_dim);
            if input_indices.is_empty() {
                continue;
            }

            let bias_value = rule.weight * self.config.bias_strength * sigmoid(rule.support as f32);

            // Use rank column 0 for all bias injection.
            let rank_col = 0usize;

            for &input_idx in &input_indices {
                // B[rank_col, output_idx] — row-major: B[k * out_dim + j]
                let b_idx = rank_col * out_dim + output_idx;
                b_matrix[b_idx] += bias_value;

                // A[input_idx, rank_col] — row-major: A[i * rank + k]
                let a_idx = input_idx * rank + rank_col;
                a_matrix[a_idx] += bias_value;

                total_bias_connections += 1;
            }

            biased_outputs[output_idx] = true;
            rules_applied += 1;
        }

        let biased_count = biased_outputs.iter().filter(|&&b| b).count();
        let coverage = if out_dim > 0 {
            biased_count as f32 / out_dim as f32
        } else {
            0.0
        };

        KnowledgeInitResult {
            rules_applied,
            total_bias_connections,
            coverage,
        }
    }

    /// Create fresh A and B matrices with rule-based initialization.
    ///
    /// - A matrix (`rank × in_dim`): Xavier-like init with rule biases on rank column 0.
    /// - B matrix (`out_dim × rank`): zero init with rule biases on first column.
    ///
    /// Returns `(A_data, B_data)` as flat row-major vectors.
    ///
    /// Note: `LoraWeightView` layout is A = `[in_dim × rank]`, B = `[rank × out_dim]`.
    /// We produce A as `in_dim * rank` and B as `rank * out_dim` to match that layout.
    pub fn init_from_game_rules(
        &self,
        rules: &[GameRule],
        in_dim: usize,
        out_dim: usize,
        rank: usize,
    ) -> (Vec<f32>, Vec<f32>) {
        // Xavier-like initialization scale for A.
        let xavier_scale = (2.0f32 / (in_dim as f32 + rank as f32)).sqrt();

        // Initialize A: Xavier-like random (using deterministic seed-like values).
        // Each element gets a small value proportional to xavier_scale.
        let mut a_data = vec![0.0f32; in_dim * rank];
        for i in 0..in_dim {
            for k in 0..rank {
                // Xavier init: small deterministic values.
                // Use a simple hash-like pattern for reproducibility (no RNG dependency).
                let seed = ((i * 31 + k * 17 + 7) % 1000) as f32 / 1000.0;
                a_data[i * rank + k] = (seed - 0.5) * xavier_scale * 2.0;
            }
        }

        // Initialize B: zeros (standard LoRA init — B starts at zero).
        let mut b_data = vec![0.0f32; rank * out_dim];

        // Apply rule biases via convert_rules_to_bias.
        self.convert_rules_to_bias(rules, &mut a_data, &mut b_data, in_dim, out_dim, rank);

        (a_data, b_data)
    }

    /// Map predicate conditions to input feature indices.
    ///
    /// Each predicate references a feature field name. We find the matching
    /// `FeatureMapping` in `feature_map.input_features` and return its index.
    fn map_predicates_to_inputs(&self, predicates: &[Predicate], in_dim: usize) -> Vec<usize> {
        let mut indices = Vec::with_capacity(predicates.len());

        for pred in predicates {
            let field_name = match pred {
                Predicate::StateEquals { field, .. } => field,
                Predicate::StateGreaterThan { field, .. } => field,
                Predicate::StateLessThan { field, .. } => field,
                Predicate::Not(inner) => match inner.as_ref() {
                    Predicate::StateEquals { field, .. } => field,
                    Predicate::StateGreaterThan { field, .. } => field,
                    Predicate::StateLessThan { field, .. } => field,
                    Predicate::Not(_) => continue, // Skip double negation.
                },
            };

            // Find the input feature index by name.
            if let Some(idx) = self.find_feature_index(field_name, in_dim)
                && !indices.contains(&idx)
            {
                indices.push(idx);
            }
        }

        indices
    }

    /// Find the input dimension index for a feature by name.
    fn find_feature_index(&self, name: &str, in_dim: usize) -> Option<usize> {
        for (i, feat) in self.feature_map.input_features.iter().enumerate() {
            if i >= in_dim {
                break;
            }
            if feat.name == name {
                return Some(i);
            }
        }
        None
    }
}

use anyhow::{Result, bail};
use serde::Deserialize;
use std::fmt;

// ---------------------------------------------------------------------------
// Enums
// ---------------------------------------------------------------------------

/// Relation types between game concepts.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, serde::Deserialize)]
#[repr(u8)]
pub enum RelationType {
    IsA,
    HasA,
    WeakTo,
    StrongAgainst,
    Drops,
    SpawnsIn,
}

/// Item classification within the concept graph.
#[derive(Clone, Debug, PartialEq, serde::Deserialize)]
#[repr(u8)]
pub enum ItemType {
    Weapon,
    Armor,
    Consumable,
    QuestItem,
    Bomb,
}

/// NPC behavioural state classification.
#[derive(Clone, Debug, PartialEq, serde::Deserialize)]
#[repr(u8)]
pub enum NpcStateType {
    Idle,
    Patrol,
    Combat,
    Fleeing,
    Dialog,
}

/// Concept classification for a named game concept.
#[derive(Clone, Debug, PartialEq)]
pub enum ConceptClass {
    Enemy { is_boss: bool, aggression: f32 }

impl GameConceptGraph {
    /// Parse a TOML string and construct the concept graph.
    ///
    /// Expected format:
    /// ```toml
    /// [concepts.bomber_basic]
    /// class = "Enemy"
    /// is_boss = false
    /// aggression = 0.5
    ///
    /// [[relations]]
    /// subject = "bomber_basic"
    /// relation = "SpawnsIn"
    /// object = "wall"
    /// ```
    pub fn load_from_toml(toml_str: &str) -> Result<Self> {
        let doc: GraphToml = toml::from_str(toml_str)?;

        let mut concepts: Vec<(String, ConceptClass)> = Vec::new();
        let mut concept_names: Vec<String> = Vec::new();

        // Parse concepts — sorted by key for determinism.
        let mut sorted_keys: Vec<&String> = doc.concepts.keys().collect();
        sorted_keys.sort();

        for key in sorted_keys {
            let value = match doc.concepts.get(key) {
                Some(v) => v,
                None => continue,
            };
            // Re-serialize the sub-table and deserialize as ConceptToml.
            let concept_raw: ConceptToml = serde::Deserialize::deserialize(value.clone())?;
            let class = parse_concept_class(&concept_raw)?;
            concepts.push((key.clone(), class));
            concept_names.push(key.clone());
        }

        // Parse relations.
        let mut relations: Vec<ConceptRelation> = Vec::new();
        for rel in &doc.relations {
            if !concept_names.contains(&rel.subject) {
                bail!(
                    "Relation references unknown subject concept: \"{}\"",
                    rel.subject
                );
            }
            if !concept_names.contains(&rel.object) {
                bail!(
                    "Relation references unknown object concept: \"{}\"",
                    rel.object
                );
            }
            relations.push(ConceptRelation {
                subject: rel.subject.clone(),
                relation: rel.relation,
                object: rel.object.clone(),
            });
        }

        Ok(Self {
            concepts,
            relations,
        })
    }
}

fn parse_item_type(s: &str) -> Result<ItemType> {
    match s {
        "Weapon" => Ok(ItemType::Weapon),
        "Armor" => Ok(ItemType::Armor),
        "Consumable" => Ok(ItemType::Consumable),
        "QuestItem" => Ok(ItemType::QuestItem),
        "Bomb" => Ok(ItemType::Bomb),
        "" => Ok(ItemType::Consumable), // default
        other => bail!("Unknown item type: \"{other}\""),
    }

fn parse_npc_state_type(s: &str) -> Result<NpcStateType> {
    match s {
        "Idle" => Ok(NpcStateType::Idle),
        "Patrol" => Ok(NpcStateType::Patrol),
        "Combat" => Ok(NpcStateType::Combat),
        "Fleeing" => Ok(NpcStateType::Fleeing),
        "Dialog" => Ok(NpcStateType::Dialog),
        "" => Ok(NpcStateType::Idle), // default
        other => bail!("Unknown NPC state type: \"{other}\""),
    }

impl GameConceptGraph {
    /// Walk graph relations and produce FOL constraints for training penalty injection.
    ///
    /// Derivation rules (deterministic, sorted by penalty weight descending):
    ///
    /// - `Enemy { is_boss=true }` + `WeakTo(Item)` → avoid attacking when under-levelled
    /// - `Terrain { is_chokepoint=true }` + `SpawnsIn(Enemy)` → avoid entering when enemies present
    /// - `Enemy { aggression > 0.8 }` → avoid attacking when low health
    pub fn derive_constraints(&self) -> Vec<FolConstraint> {
        let mut constraints: Vec<FolConstraint> = Vec::new();

        for rel in &self.relations {
            let Some(subject_class) = self.find_concept(&rel.subject) else {
                continue;
            };
            let Some(object_class) = self.find_concept(&rel.object) else {
                continue;
            };

            match (subject_class, rel.relation, object_class) {
                // Boss enemy weak to an item → avoid attacking when under-levelled.
                (
                    ConceptClass::Enemy {
                        is_boss: true,
                        aggression: _,
                    },
                    RelationType::WeakTo,
                    ConceptClass::Item { .. },
                ) => {
                    constraints.push(FolConstraint {
                        premises: vec![ConstraintPredicate::FeatureLessThan {
                            feature: "player_level".into(),
                            threshold: 10.0,
                        }],
                        consequent: ConstraintPredicate::Not(Box::new(
                            ConstraintPredicate::ActionEquals(0), // attack index
                        )),
                        penalty_weight: 2.0,
                        source: format!("{} --WeakTo--> {}", rel.subject, rel.object),
                    });
                }

                // Chokepoint terrain with spawning enemy → avoid entering when enemies present.
                (
                    ConceptClass::Enemy { .. },
                    RelationType::SpawnsIn,
                    ConceptClass::Terrain {
                        safety: _,
                        is_chokepoint: true,
                    },
                ) => {
                    constraints.push(FolConstraint {
                        premises: vec![ConstraintPredicate::FeatureGreaterThan {
                            feature: "enemy_count".into(),
                            threshold: 0.0,
                        }],
                        consequent: ConstraintPredicate::Not(Box::new(
                            ConstraintPredicate::ActionEquals(1), // move-into-chokepoint index
                        )),
                        penalty_weight: 1.5,
                        source: format!("{} --SpawnsIn--> {}", rel.subject, rel.object),
                    });
                }

                // High-aggression enemy → avoid attacking when low on health.
                (
                    ConceptClass::Enemy {
                        is_boss: _,
                        aggression,
                    },
                    RelationType::SpawnsIn,
                    _,
                ) if *aggression > 0.8 => {
                    constraints.push(FolConstraint {
                        premises: vec![ConstraintPredicate::FeatureLessThan {
                            feature: "player_health".into(),
                            threshold: 0.3,
                        }],
                        consequent: ConstraintPredicate::Not(Box::new(
                            ConstraintPredicate::ActionEquals(0), // attack index
                        )),
                        penalty_weight: 1.0,
                        source: format!(
                            "{} (aggression={:.1}) --SpawnsIn--> {}",
                            rel.subject, aggression, rel.object
                        ),
                    });
                }

                // Non-boss enemy drops item → encourage action when enemy present.
                (
                    ConceptClass::Enemy {
                        is_boss: false,
                        aggression: _,
                    },
                    RelationType::Drops,
                    ConceptClass::Item { rarity, .. },
                ) if *rarity > 0.5 => {
                    constraints.push(FolConstraint {
                        premises: vec![ConstraintPredicate::FeatureGreaterThan {
                            feature: "enemy_count".into(),
                            threshold: 0.0,
                        }],
                        consequent: ConstraintPredicate::FeatureGreaterThan {
                            feature: "loot_opportunity".into(),
                            threshold: 0.5,
                        },
                        penalty_weight: 0.5,
                        source: format!("{} --Drops--> {}", rel.subject, rel.object),
                    });
                }

                _ => {}
            }
        }

        // Sort by penalty_weight descending (deterministic order).
        constraints.sort_by(|a, b| {
            b.penalty_weight
                .partial_cmp(&a.penalty_weight)
                .unwrap_or(std::cmp::Ordering::Equal)
        });

        constraints
    }

    /// Compute total penalty for the current game state + chosen action.
    ///
    /// A constraint is *violated* when all premises are true but the consequent is false.
    /// Returns the sum of `penalty_weight` for all violated constraints.
    pub fn compute_penalty(
        constraints: &[FolConstraint],
        action_idx: usize,
        features: &[(String, f32)],
    ) -> f32 {
        let mut total: f32 = 0.0;

        for constraint in constraints {
            let all_premises_hold = constraint
                .premises
                .iter()
                .all(|p| p.evaluate(action_idx, features));

            if !all_premises_hold {
                continue;
            }

            // Premises hold — consequent must also hold, otherwise violation.
            if !constraint.consequent.evaluate(action_idx, features) {
                total += constraint.penalty_weight;
            }
        }

        total
    }
}

impl ConstraintPredicate {
    /// Evaluate whether this predicate is true given the current action and feature state.
    pub fn evaluate(&self, action_idx: usize, features: &[(String, f32)]) -> bool {
        match self {
            ConstraintPredicate::ActionEquals(idx) => action_idx == *idx,

            ConstraintPredicate::FeatureGreaterThan { feature, threshold } => {
                match lookup_feature(features, feature) {
                    Some(val) => val > *threshold,
                    None => false,
                }
            }

            ConstraintPredicate::FeatureLessThan { feature, threshold } => {
                match lookup_feature(features, feature) {
                    Some(val) => val < *threshold,
                    None => false,
                }
            }

            ConstraintPredicate::FeatureEquals { feature, value } => {
                match lookup_feature(features, feature) {
                    Some(val) => (val - value).abs() < f32::EPSILON,
                    None => false,
                }
            }

            ConstraintPredicate::Not(inner) => !inner.evaluate(action_idx, features),
        }
    }
}

impl fmt::Display for ConstraintPredicate {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ConstraintPredicate::ActionEquals(idx) => write!(f, "action={idx}"),
            ConstraintPredicate::FeatureGreaterThan { feature, threshold } => {
                write!(f, "{feature} > {threshold:.1}")
            }
            ConstraintPredicate::FeatureLessThan { feature, threshold } => {
                write!(f, "{feature} < {threshold:.1}")
            }
            ConstraintPredicate::FeatureEquals { feature, value } => {
                write!(f, "{feature} = {value:.1}")
            }
            ConstraintPredicate::Not(inner) => write!(f, "¬({inner})"),
        }
    }

impl fmt::Display for FolConstraint {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let premises: Vec<String> = self.premises.iter().map(|p| p.to_string()).collect();
        write!(
            f,
            "{} → {} [weight={:.1}, source=\"{}\"]",
            premises.join(" ∧ "),
            self.consequent,
            self.penalty_weight,
            self.source
        )
    }

impl AucCi {
    /// Whether the interval clears a bar — the only honest way to read an AUC
    /// against a gate. Plan 342's bar is explicit that "a 5-vs-4 coin flip is
    /// a FAIL", i.e. a point estimate above a bar with an interval spanning it
    /// has not cleared it.
    pub fn clears(&self, bar: f32) -> bool {
        self.lo > bar
    }

    /// True when the interval contains 0.5 — the verifier is not
    /// distinguishable from chance at this sample size.
    pub fn spans_chance(&self) -> bool {
        self.lo <= 0.5 && self.hi >= 0.5
    }
}

use blake3::Hasher;

/// GPart partition: deterministic assignment of N weight elements to d groups.
///
/// Pre-computed from a seed via BLAKE3 hash chain. The partition is isometric:
/// `P^T P = I_d` by construction, meaning `‖Pθ_d‖ = ‖θ_d‖` for any θ_d.
///
/// Storage: only `seed` and `d` are needed to regenerate. The `group_assignments`
/// and `inv_sqrt_scales` are pre-computed for runtime performance.
#[derive(Debug, Clone)]
pub struct GpartPartition {
    /// Seed for deterministic partition regeneration.
    pub seed: u64,
    /// Number of groups (d). Must be ≤ N (total weight elements).
    pub d: usize,
    /// Group assignment per weight element: g(i) ∈ {0,...,d-1}.
    /// Length = N (total weight elements).
    pub group_assignments: Vec<u32>,
    /// Pre-computed 1/√|g⁻¹(k)| for each group k ∈ {0,...,d-1}.
    /// Length = d.
    pub inv_sqrt_scales: Vec<f32>,
}

impl GpartPartition {
    /// Total number of weight elements (N).
    #[inline]
    pub fn n(&self) -> usize {
        self.group_assignments.len()
    }

    /// Generate a deterministic isometric partition from a seed.
    ///
    /// Uses BLAKE3 hash chain to assign each of N elements to one of d groups.
    /// Group sizes are approximately equal (floor(N/d) or ceil(N/d)).
    ///
    /// # Arguments
    /// * `seed` — deterministic seed (same seed → same partition across devices)
    /// * `n` — total number of weight elements (N = rows × cols)
    /// * `d` — number of groups (typically d = rank × (in_dim + out_dim) for matched budget)
    ///
    /// # Panics
    /// If d == 0 or n == 0 or d > n.
    pub fn generate(seed: u64, n: usize, d: usize) -> Self {
        assert!(d > 0, "GPart: d must be > 0");
        assert!(n > 0, "GPart: n must be > 0");
        assert!(d <= n, "GPart: d ({d}) must be ≤ n ({n})");

        // Generate group assignments via BLAKE3 hash chain.
        // Each element i gets assigned to hash(seed || i) mod d.
        let mut hasher = Hasher::new();
        hasher.update(&seed.to_le_bytes());
        let base_hash = hasher.finalize();

        let group_assignments: Vec<u32> = (0..n)
            .map(|i| {
                let mut h = Hasher::new();
                h.update(base_hash.as_bytes());
                h.update(&(i as u64).to_le_bytes());
                let out = h.finalize();
                // Use first 8 bytes as u64, mod d
                let mut bytes = [0u8; 8];
                bytes.copy_from_slice(&out.as_bytes()[..8]);
                let val = u64::from_le_bytes(bytes);
                (val % d as u64) as u32
            })
            .collect();

        let inv_sqrt_scales = compute_inv_sqrt_scales(&group_assignments, d);

        Self {
            seed,
            d,
            group_assignments,
            inv_sqrt_scales,
        }
    }

    /// Forward pass: broadcast θ_d → ΔW via partition lookup.
    ///
    /// `delta_w[i] = theta_d[g(i)] * inv_sqrt_scales[g(i)]`
    ///
    /// # Arguments
    /// * `theta_d` — parameter vector of length d
    /// * `delta_w` — output weight delta of length N (must be pre-allocated)
    ///
    /// # Panics
    /// If lengths mismatch.
    pub fn forward(&self, theta_d: &[f32], delta_w: &mut [f32]) {
        debug_assert_eq!(theta_d.len(), self.d);
        debug_assert_eq!(delta_w.len(), self.n());

        for (i, dw) in delta_w.iter_mut().enumerate() {
            let g = self.group_assignments[i] as usize;
            *dw = theta_d[g] * self.inv_sqrt_scales[g];
        }
    }

    /// Backward pass: grouped gradient accumulation ∇ΔW → ∇θ_d.
    ///
    /// `∇θ_k = Σ_{i ∈ g⁻¹(k)} ∇ΔW[i] * inv_sqrt_scales[k]`
    ///
    /// # Arguments
    /// * `grad_delta_w` — upstream gradient w.r.t. ΔW, length N
    /// * `grad_theta_d` — output gradient w.r.t. θ_d, length d (must be zeroed or pre-allocated)
    ///
    /// # Panics
    /// If lengths mismatch.
    pub fn backward(&self, grad_delta_w: &[f32], grad_theta_d: &mut [f32]) {
        debug_assert_eq!(grad_delta_w.len(), self.n());
        debug_assert_eq!(grad_theta_d.len(), self.d);

        // Zero output first
        grad_theta_d.fill(0.0);

        // Accumulate grouped gradients
        for (i, &gdw) in grad_delta_w.iter().enumerate() {
            let g = self.group_assignments[i] as usize;
            grad_theta_d[g] += gdw * self.inv_sqrt_scales[g];
        }
    }

    /// Verify isometry: P^T P ≈ I_d (for non-empty groups).
    ///
    /// The partition matrix P has shape (N, d) with entries:
    ///   P[i, g(i)] = inv_sqrt_scales[g(i)]
    ///   P[i, j] = 0 for j ≠ g(i)
    ///
    /// Then `(P^T P)[j, k] = Σ_i P[i,j] · P[i,k]`
    ///   = Σ_{i ∈ g⁻¹(j)} inv_sqrt²  if j == k (diagonal)
    ///   = 0                            if j ≠ k (orthogonal columns)
    ///
    /// Diagonal entries = |g⁻¹(j)| × (1/√|g⁻¹(j)|)² = |g⁻¹(j)| / |g⁻¹(j)| = 1.
    /// Empty groups have diagonal = 0, which means P is rank-deficient (not full I_d).
    /// This is expected when n/d is small — some groups are simply unused.
    ///
    /// Returns the number of empty groups and the maximum deviation from 1.0
    /// among non-empty groups.
    pub fn verify_isometry(&self) -> (usize, f32) {
        let group_sizes = compute_group_sizes(&self.group_assignments, self.d);

        let mut empty_count = 0usize;
        let mut max_deviation = 0.0f32;
        for k in 0..self.d {
            if group_sizes[k] == 0 {
                empty_count += 1;
                continue;
            }
            let inv_sq = self.inv_sqrt_scales[k] * self.inv_sqrt_scales[k];
            let diag_entry = group_sizes[k] as f32 * inv_sq;
            let deviation = (diag_entry - 1.0).abs();
            max_deviation = max_deviation.max(deviation);
        }
        (empty_count, max_deviation)
    }

    /// Verify norm preservation: ‖Pθ_d‖ = ‖θ_d‖.
    ///
    /// Returns (‖Pθ_d‖, ‖θ_d‖) for comparison.
    pub fn verify_norm_preservation(&self, theta_d: &[f32]) -> (f32, f32) {
        debug_assert_eq!(theta_d.len(), self.d);

        let theta_norm: f32 = theta_d.iter().map(|x| x * x).sum::<f32>().sqrt();

        let mut delta_w = vec![0.0f32; self.n()];
        self.forward(theta_d, &mut delta_w);
        let delta_norm: f32 = delta_w.iter().map(|x| x * x).sum::<f32>().sqrt();

        (delta_norm, theta_norm)
    }
}

use riir_engine::bake_lora::LoraPosterior;

/// BAKE regularizer specialized for GPart's θ_d parameter vector.
///
/// Wraps the existing `BakeRegularizer` (which operates on `&[f32]`) with
/// GPart-specific semantics: per-group precision, isometry-aware penalty
/// interpretation, and cross-game posterior management.
#[derive(Clone, Debug)]
pub struct GpartBakeRegularizer {
    /// Inner BAKE regularizer operating on θ_d.
    inner: BakeRegularizer,
}

impl GpartBakeRegularizer {
    /// Create a new GPart BAKE regularizer from a previous game's θ_d posterior.
    ///
    /// # Arguments
    /// * `prior_theta_d` — posterior mean (μ) from previous game's trained θ_d
    /// * `prior_precision` — per-group precision (λ) from previous game's training
    /// * `beta` — regularization strength (default: 0.01)
    pub fn new(prior_theta_d: Vec<f32>, prior_precision: Vec<f32>, beta: f32) -> Self {
        let prior = LoraPosterior::new(prior_theta_d, prior_precision);
        Self {
            inner: BakeRegularizer::new(prior, beta),
        }
    }

    /// Create with default β = 0.01.
    pub fn default_regularizer(prior_theta_d: Vec<f32>, prior_precision: Vec<f32>) -> Self {
        Self::new(prior_theta_d, prior_precision, 0.01)
    }

    /// Compute BAKE loss on the adapter's current θ_d.
    ///
    /// L_Bake_GPart = β · Σ_k √(λ_k · (θ_k - μ_k)²)
    ///
    /// Thanks to isometry, this penalty exactly controls ‖ΔW‖ perturbation.
    pub fn loss(&self, adapter: &GpartLoraAdapter) -> f32 {
        self.inner.loss(&adapter.theta_d)
    }

    /// Compute per-group penalty for diagnostics.
    pub fn per_group_penalty(&self, adapter: &GpartLoraAdapter) -> Vec<f32> {
        self.inner.per_weight_penalty(&adapter.theta_d)
    }

    /// Extract posterior from a trained adapter for use as prior in next game.
    ///
    /// Precision is estimated from oscillator velocity magnitude — groups that
    /// oscillate rapidly have high gradient variance → low precision (uncertain).
    /// Groups with settled velocity → high precision (well-determined).
    pub fn extract_posterior(adapter: &GpartLoraAdapter) -> LoraPosterior {
        let mu = adapter.theta_d.clone();
        // Precision heuristic: 1 / (1 + |velocity|) — settled groups get high precision
        let lambda: Vec<f32> = adapter
            .theta_vel
            .iter()
            .map(|&v| 1.0 / (1.0 + v.abs()))
            .collect();
        LoraPosterior::new(mu, lambda)
    }

    /// Extract precision from per-group gradient variance (if tracked externally).
    pub fn precision_from_gradient_variance(
        grad_variance: &[f32],
        min_precision: f32,
        max_precision: f32,
    ) -> Vec<f32> {
        BakeRegularizer::precision_from_adam(grad_variance, min_precision, max_precision)
    }
}

use crate::gpart::GpartLoraAdapter;

/// Cross-game concept mining result for one parameter group.
#[derive(Debug, Clone, Copy)]
pub struct ConceptCorrelation {
    /// Group index k.
    pub k: usize,
    /// Correlation coefficient |θ_k^A · θ_k^B| / (‖θ_A‖ · ‖θ_B‖).
    pub correlation: f32,
    /// Magnitude in game A.
    pub magnitude_a: f32,
    /// Magnitude in game B.
    pub magnitude_b: f32,
    /// Whether this group is a shared concept (correlation above threshold).
    pub is_shared: bool,
}

//! GPU dispatch trait for batched dense linear ops (Plan 343 T1.11).
//!
//! The maglev drafter's forward/backward is dominated by per-token GEMVs
//! against the same weight matrices — above all the tied LM head
//! `[V×d]` (Bench 505/515: forward + backward ≈ 96% of a post-T1.12 step,
//! and the head is the single largest slice of both). This trait lets a
//! GPU handler take those projections as **batched GEMMs over the whole
//! sequence** while the scalar parts (attention, RoPE, norms, gating,
//! injection mixing, losses) stay on the CPU.
//!
//! Mirrors [`crate::gpu_muon_dispatch`] (Issue 402): always compiled, no
//! feature gate, so `riir-train-gpu` (which depends on this crate) can
//! implement it without a feature cycle, and consumers can accept
//! `&mut dyn GpuLinearDispatch` unconditionally.
//!
//! ## Contract
//!
//! Every method returns `false` when the handler declines (unsupported
//! shape, no device, …) and the caller MUST then run the identical CPU
//! loop — the fallback is bit-exact by construction, which is what keeps
//! the plain CPU step bit-reproducible (the T1.4-i gate) while a handler
//! is a per-run opt-in.
//!
//! ## Precision
//!
//! The concrete implementation (`DenseLinearCuda`, cuBLAS TF32) is NOT
//! bit-identical to the CPU fallback — same class as the Issue 402 Muon
//! substrate: TF32 tensor-core GEMM carries ~1e-3 relative error per
//! element. Handlers route whole projections, never mix with the CPU
//! result for the same matrix, so a step is either fully dispatched or
//! fully CPU for any given call site.

/// Batched dense-linear dispatch for the drafter's forward/backward
/// projections (Plan 343 T1.11).
///
/// All matrices are row-major `[rows × cols]` (`m[i * cols + j]`), all
/// batched operands are `[T × width]`. `t_len` is the sequence length.
pub trait GpuLinearDispatch {
    /// Batched forward projection: for every `t`, `y[t] = W · x[t]`.
    ///
    /// `x` is `[T×k]`, `w` is `[n×k]` (`y = x·Wᵀ`), `y_out` is `[T×n]`
    /// and is **overwritten**. Returns `false` → the caller runs the
    /// per-token CPU `matvec` loop (bit-identical fallback).
    fn proj_forward(
        &mut self,
        x: &[f32],
        w: &[f32],
        t_len: usize,
        n: usize,
        y_out: &mut [f32],
    ) -> bool {
        let _ = (x, w, t_len, n, y_out);
        false
    }

    /// Batched backward for one projection:
    /// `dw[n×k] += Σ_t dy_t ⊗ x_t` and `dx[T×k] += Σ_t dy_t · W`.
    ///
    /// `dy` is `[T×n]`, `x` is `[T×k]`, `w` is `[n×k]`; BOTH `dw_out`
    /// (`[n×k]`) and `dx_out` (`[T×k]`) **accumulate** (the CPU fallback's
    /// `outer_accum` + `matvec_t_accum` semantics). Returns `false` → the
    /// caller runs the per-token CPU loop.
    ///
    /// (8 operands — the op's full data layout; grouping them into a struct
    /// would obscure the one-to-one mapping to the fallback loops.)
    #[allow(clippy::too_many_arguments)]
    fn proj_backward(
        &mut self,
        dy: &[f32],
        x: &[f32],
        w: &[f32],
        t_len: usize,
        n: usize,
        dw_out: &mut [f32],
        dx_out: &mut [f32],
    ) -> bool {
        let _ = (dy, x, w, t_len, n, dw_out, dx_out);
        false
    }

    /// Outer-only accumulation: `dw[n×k] += Σ_t dy_t ⊗ x_t` (the
    /// `proj_backward` weight-grad half alone, for sites with no input
    /// gradient — detached operands).
    ///
    /// `dy` is `[T×n]`, `x` is `[T×k]`. Returns `false` → the caller runs
    /// the per-token CPU `outer_accum` loop.
    fn outer_dw_accum(
        &mut self,
        dy: &[f32],
        x: &[f32],
        t_len: usize,
        n: usize,
        dw_out: &mut [f32],
    ) -> bool {
        let _ = (dy, x, t_len, n, dw_out);
        false
    }
}

//! GPU dispatch trait for the dense Muon optimizer (Issue 402).
//!
//! This module is always compiled (no feature gate) so that both:
//! - `riir-train-engine` (the training loop in `kimi_k3_train.rs`, feature-gated
//!   behind `kimi_k3_train`) can accept a `&mut dyn GpuMuonDispatch` parameter.
//! - `riir-train-gpu` (the GPU impl `MuonDenseGpu`, feature-gated behind
//!   `muon_dense_gpu`) can implement the trait.
//!
//! The concrete GPU implementation lives in `riir_train_gpu::muon_dense_gpu`.
//! The trait is intentionally minimal (2 methods) to keep the abstraction clean.

/// Minimum `min(rows, cols)` (d_min) for a 2D Muon param to be routed to the
/// GPU handler.
///
/// The Newton-Schulz cost scales as `d_min³` (5 iters × ~4 GEMMs of `[d_min ×
/// d_min]`). d_min is therefore the load-bearing routing signal — NOT max(rows,
/// cols) which was the Phase 4 metric.
///
/// Phase 6 update (2026-08-05): with the Phase 2 GPU-resident Newton-Schulz
/// eliminating the ~6s CPU NS round-trip, small params no longer pay the CPU
/// round-trip penalty that made the Phase 4 threshold=2048 necessary. The
/// Phase 4 measurement showing small params SLOWER on GPU was specific to the
/// CPU-NS round-trip path — it no longer applies.
///
/// At d_min=128: CPU NS on [128×128] ≈ 5 × 4 × 128³ = 33M FLOP ≈ 7ms per
/// param. GPU NS on [128×128] ≈ 0.3ms. GPU wins by ~20×.
/// At d_min=256: CPU NS on [256×256] ≈ 5 × 4 × 256³ = 670M FLOP ≈ 67ms per
/// param. GPU NS ≈ 1ms. GPU wins by ~67×.
/// At d_min=64: CPU NS on [64×64] ≈ 0.9ms. GPU NS ≈ 0.2ms. GPU barely wins;
/// launch overhead dominates.
/// At d_min=32: CPU NS on [32×32] ≈ 0.1ms. GPU NS ≈ 0.2ms. CPU wins.
///
/// Set to 128 — catches all KDA/MLA/MoE projections (d_min ≥ 128) while
/// skipping the trivially-cheap conv weights (d_min=4), biases (d_min=8),
/// and small projections (d_min=32). The Kimi-K3-0.40B model has ~225 params
/// with d_min=256 that were previously on CPU (~15s total NS) — now all go to
/// GPU (~150ms total).
pub const MUON_GPU_THRESHOLD: usize = 128;

/// GPU dispatch trait for the dense Muon Gram + NS + ortho phases (Issue 402).
///
/// The trait is called AFTER the EMA momentum update (step 2 of `muon_step_dense`)
/// has run on CPU. It receives the post-EMA momentum `m` and writes the
/// orthogonalized momentum `O = m·(mᵀm)^{-1/2}` into `o_out`. The caller then
/// applies step 6 (scale + weight decay + update) on CPU.
///
/// The concrete implementation (`MuonDenseGpu`) lives in `riir-train-gpu` and
/// uses WGSL matmul kernels for the Gram + ortho GEMMs, with a CPU round-trip
/// for the Newton-Schulz iteration (Phase 1 pragmatic shortcut).
pub trait GpuMuonDispatch {
    /// Run GPU Gram + CPU NS + GPU ortho on the momentum matrix.
    ///
    /// # Arguments
    /// * `m` — post-EMA momentum `[rows × cols]` row-major (read).
    /// * `o_out` — orthogonalized momentum `[rows × cols]` row-major (written).
    /// * `rows`, `cols` — matrix dimensions.
    /// * `ns_iters` — Newton-Schulz iterations.
    ///
    /// # Panics
    /// Implementations may panic on non-finite NS output or dimension mismatch.
    fn gram_ns_ortho(
        &mut self,
        m: &[f32],
        o_out: &mut [f32],
        rows: usize,
        cols: usize,
        ns_iters: u8,
    );

    /// Whether this handler is configured for the given shape.
    ///
    /// The training loop creates one handler per large param shape. This method
    /// lets the optimizer check if the handler matches the current param without
    /// downcasting.
    fn matches_shape(&self, rows: usize, cols: usize) -> bool;

    /// Plan 339 T3.1 — device ℓ1 norms along the `d_min` side of the momentum,
    /// for the sampled (row-selection) Muon variant.
    ///
    /// `norms_out.len()` must be `rows.min(cols)`. Implementations that return
    /// `true` should leave the uploaded momentum resident so the matching
    /// [`Self::gram_ns_ortho_slab`] call can gather from it without a second
    /// upload. Returns `false` when unsupported — the caller falls back to the
    /// CPU reduction with identical semantics.
    fn slab_l1_norms(
        &mut self,
        m: &[f32],
        rows: usize,
        cols: usize,
        norms_out: &mut [f32],
    ) -> bool {
        let _ = (m, rows, cols, norms_out);
        false
    }

    /// Plan 339 T3.2 — orthogonalise a selected slab of the momentum on the
    /// device.
    ///
    /// Gathers `M[:, sel]` (tall, `rows >= cols`) / `M[sel, :]` (wide), runs
    /// the same Gram + NS + ortho pipeline the dense entry runs on the
    /// `[d_max × k]` / `[k × d_max]` slab, and downloads the orthogonalised
    /// slab `O` into `o_slab_out`. `sel` must be sorted ascending (the engine's
    /// `select_slabs` guarantees it; at `f = 1` the gather is then the identity
    /// permutation and the result matches the dense entry exactly).
    ///
    /// Implementations must not assume a prior [`Self::slab_l1_norms`] call —
    /// if the resident momentum is stale they re-upload from `m`. Returns
    /// `false` when unsupported; the caller falls back to the CPU slab
    /// pipeline.
    fn gram_ns_ortho_slab(
        &mut self,
        m: &[f32],
        sel: &[usize],
        o_slab_out: &mut [f32],
        rows: usize,
        cols: usize,
        ns_iters: u8,
    ) -> bool {
        let _ = (m, sel, o_slab_out, rows, cols, ns_iters);
        false
    }
}

impl RadiusStrategy {
    /// Resolve the strategy to a concrete radius given the weight matrix.
    ///
    /// - [`RadiusStrategy::Init`] → `‖w‖_F` (caller passes the matrix at the
    ///   step where the radius is being initialized; this is what fixes `R`
    ///   once, before any update).
    /// - [`RadiusStrategy::Fixed(r)`] → `r` (the matrix is not read).
    /// - [`RadiusStrategy::Shape { sqrt_d_out }`] → `√rows` or `√cols`
    ///   depending on the flag, interpreting `w` as a row-major `[rows × cols]`
    ///   matrix with `rows = w.len() / cols`.
    ///
    /// Returns `0.0` for empty slices or non-finite norms — the caller should
    /// treat `0.0` as "skip projection" (the projection itself is a no-op on
    /// a zero-norm input; see [`project_to_frobenius_radius`]'s NaN policy).
    pub fn resolve(&self, w: &[f32], rows: usize, cols: usize) -> f32 {
        match *self {
            RadiusStrategy::Init => norm_frobenius(w),
            RadiusStrategy::Fixed(r) => r,
            RadiusStrategy::Shape { sqrt_d_out } => {
                if sqrt_d_out {
                    // W is [rows × cols], d_out = cols.
                    (cols as f32).sqrt()
                } else {
                    (rows as f32).sqrt()
                }
            }
        }
    }
}

impl HyperplaneConstraint {
    /// Create a new constraint.
    pub fn new(game_id: impl Into<String>, normal: Vec<f32>, bias: f32) -> Self {
        Self {
            game_id: game_id.into(),
            normal,
            bias,
        }
    }

    /// Compute the residual: `normal · weights - bias`.
    /// Zero when weights satisfy the constraint.
    pub fn residual(&self, weights: &[f32]) -> f32 {
        debug_assert_eq!(weights.len(), self.normal.len());
        self.normal
            .iter()
            .zip(weights.iter())
            .map(|(n, w)| n * w)
            .sum::<f32>()
            - self.bias
    }

    /// Get the dimension of this constraint.
    #[inline]
    pub fn dim(&self) -> usize {
        self.normal.len()
    }
}

impl HyperplaneProjector {
    /// Create a new projector with given constraints.
    pub fn new(constraints: Vec<HyperplaneConstraint>, relaxation: f32, trust_radius: f32) -> Self {
        Self {
            constraints,
            relaxation,
            trust_radius,
            max_iterations: 10,
        }
    }

    /// Create with hard constraints (no relaxation).
    pub fn strict(constraints: Vec<HyperplaneConstraint>) -> Self {
        Self::new(constraints, 0.0, 1.0)
    }

    /// Create with soft constraints (relaxation for conflicting games).
    pub fn soft(constraints: Vec<HyperplaneConstraint>, relaxation: f32) -> Self {
        Self::new(constraints, relaxation, 1.0)
    }

    /// Get the number of game constraints.
    #[inline]
    pub fn game_count(&self) -> usize {
        self.constraints.len()
    }

    /// Check if any constraints exist.
    pub fn has_constraints(&self) -> bool {
        !self.constraints.is_empty()
    }

    /// Project weights onto the intersection of all hyperplanes.
    ///
    /// Iterative projection: for each constraint, if the residual exceeds relaxation,
    /// move weights toward satisfying the constraint. The step is clipped to trust_radius.
    ///
    /// Returns the projected weights (modifies in-place).
    pub fn project(&self, weights: &mut [f32]) {
        if self.constraints.is_empty() {
            return;
        }

        // Precompute ‖n‖² for each constraint once — the normals are immutable
        // across iterations, so recomputing inside the iteration loop was
        // O(max_iterations × N × dim) redundant work. Done in a single pass,
        // the loop below pays only O(N × dim) for this quantity total.
        let norm_sq_cache: Vec<f32> = self
            .constraints
            .iter()
            .map(|c| c.normal.iter().map(|n| n * n).sum())
            .collect();

        for _ in 0..self.max_iterations {
            let mut max_violation = 0.0f32;

            for (constraint, &norm_sq) in self.constraints.iter().zip(&norm_sq_cache) {
                let residual = constraint.residual(weights);
                let violation = (residual.abs() - self.relaxation).max(0.0);

                if violation > 0.0 {
                    if norm_sq < 1e-10 {
                        continue;
                    }

                    // Project: w = w - (residual / ||n||²) * n
                    // Clipped by trust_radius
                    let step_size = (residual / norm_sq).abs().min(self.trust_radius);
                    let sign = if residual > 0.0 { -1.0f32 } else { 1.0f32 };

                    for (w, n) in weights.iter_mut().zip(constraint.normal.iter()) {
                        *w += sign * step_size * n;
                    }

                    max_violation = max_violation.max(violation);
                }
            }

            // Converged if no constraint violated beyond relaxation
            if max_violation < 1e-6 {
                break;
            }
        }
    }

    /// Compute total constraint violation (sum of squared residuals beyond relaxation).
    pub fn total_violation(&self, weights: &[f32]) -> f32 {
        self.constraints
            .iter()
            .map(|c| {
                let r = c.residual(weights);
                let excess = (r.abs() - self.relaxation).max(0.0);
                excess * excess
            })
            .sum()
    }

    /// Check if weights satisfy all constraints within tolerance.
    pub fn is_satisfied(&self, weights: &[f32], tolerance: f32) -> bool {
        self.constraints
            .iter()
            .all(|c| c.residual(weights).abs() < tolerance + self.relaxation)
    }

    /// Add a new game constraint.
    pub fn add_constraint(&mut self, constraint: HyperplaneConstraint) {
        self.constraints.push(constraint);
    }

    /// Remove a game constraint by game_id.
    pub fn remove_constraint(&mut self, game_id: &str) {
        self.constraints.retain(|c| c.game_id != game_id);
    }
}

impl EntityCluster {
    /// Create a new cluster.
    pub fn new(cluster_id: usize, entities: Vec<String>, dim: usize, momentum: f32) -> Self {
        Self {
            cluster_id,
            entities,
            centroid: vec![0.0; dim],
            momentum,
        }
    }

    /// Update centroid using momentum: c_new = (1-η)·c_old + η·mean(embeddings).
    pub fn update_centroid(&mut self, embeddings: &[Vec<f32>]) {
        if embeddings.is_empty() {
            return;
        }
        let dim = self.centroid.len();

        // Accumulate embedding-outer / dim-inner. The transposed form (dim-outer)
        // re-walked all `n` embeddings for every dimension — `dim × n` strided
        // touches consuming one f32 per cache line. This form reads each
        // embedding sequentially and auto-vectorizes; the `zip` truncation
        // reproduces the old `get(d).unwrap_or(0.0)` zero-padding for
        // embeddings shorter than the centroid.
        let mut sum = vec![0.0f32; dim];
        for e in embeddings {
            for (s, &x) in sum.iter_mut().zip(e.iter()) {
                *s += x;
            }
        }

        let keep = 1.0 - self.momentum;
        let scale = self.momentum / embeddings.len() as f32;
        for (c, &s) in self.centroid.iter_mut().zip(sum.iter()) {
            *c = keep * *c + scale * s;
        }
    }

    /// Get cluster size.
    #[inline]
    pub fn size(&self) -> usize {
        self.entities.len()
    }
}

impl EntityClusterer {
    /// Create a new clusterer.
    pub fn new(cluster_size: usize, momentum: f32, dim: usize) -> Self {
        Self {
            cluster_size,
            momentum,
            dim,
        }
    }

    /// Cluster entities by importance score.
    ///
    /// Sorts entities by importance (descending), then groups into fixed-size clusters.
    /// Most important entities are in the first cluster.
    pub fn cluster(&self, entities: &[EntityImportance]) -> Vec<EntityCluster> {
        let mut sorted: Vec<&EntityImportance> = entities.iter().collect();
        sorted.sort_by(|a, b| {
            b.importance
                .partial_cmp(&a.importance)
                .unwrap_or(std::cmp::Ordering::Equal)
        });

        let mut clusters = Vec::new();
        let chunks = sorted.chunks(self.cluster_size.max(1));

        for (idx, chunk) in chunks.enumerate() {
            let entity_ids: Vec<String> = chunk.iter().map(|e| e.entity_id.clone()).collect();
            clusters.push(EntityCluster::new(idx, entity_ids, self.dim, self.momentum));
        }

        clusters
    }

    /// Compute fixed-size cluster contrastive loss (L_FCC).
    ///
    /// For each pair of clusters: minimize within-cluster distance,
    /// maximize between-cluster distance.
    ///
    /// L_FCC = Σ_c Σ_{i,j∈c} ||e_i - e_j||² - α · Σ_{c1≠c2} ||μ_c1 - μ_c2||²
    pub fn contrastive_loss(
        &self,
        clusters: &[EntityCluster],
        embeddings: &std::collections::HashMap<String, Vec<f32>>,
        alpha: f32,
    ) -> f32 {
        let mut within_loss = 0.0f32;
        let mut within_count = 0usize;

        // Scratch reused across clusters: the mean buffer for `pairwise_sq_dist_sum`
        // and the per-cluster embedding view. Both are refilled, never regrown.
        let mut mean_scratch: Vec<f32> = Vec::new();
        let mut cluster_embeds: Vec<&[f32]> = Vec::new();

        for cluster in clusters {
            cluster_embeds.clear();
            cluster_embeds.extend(
                cluster
                    .entities
                    .iter()
                    .filter_map(|id| embeddings.get(id).map(Vec::as_slice)),
            );

            // Within-cluster: minimize pairwise distance
            let m = cluster_embeds.len();
            within_loss += pairwise_sq_dist_sum(&cluster_embeds, &mut mean_scratch);
            within_count += m * m.saturating_sub(1) / 2;
        }

        // Between-cluster: maximize centroid distance
        let centroids: Vec<&[f32]> = clusters.iter().map(|c| c.centroid.as_slice()).collect();
        let between_loss = pairwise_sq_dist_sum(&centroids, &mut mean_scratch);

        let normalized_within = if within_count > 0 {
            within_loss / within_count as f32
        } else {
            0.0
        };
        let normalized_between = if clusters.len() > 1 {
            between_loss / (clusters.len() * (clusters.len() - 1) / 2) as f32
        } else {
            0.0
        };

        normalized_within - alpha * normalized_between
    }
}

impl MockAdapter {
    fn new(dim: usize, seed: u64) -> Self {
        let mut rng = fastrand::Rng::with_seed(seed);
        let weights: Vec<f32> = (0..dim).map(|_| rng.f32() * 2.0 - 1.0).collect();
        Self { weights, dim }
    }

    /// Forward pass: input · weights → sigmoid
    fn forward(&self, input: &[f32]) -> Vec<f32> {
        let mut out = Vec::with_capacity(self.dim);
        for i in 0..self.dim {
            let val = if i < input.len() {
                input[i] * self.weights[i % self.weights.len()]
            } else {
                self.weights[i % self.weights.len()]
            };
            // sigmoid
            out.push(1.0 / (1.0 + (-val).exp()));
        }
        out
    }

    /// Simple SGD update: push weights toward reducing loss direction.
    fn update(&mut self, grad: &[f32], lr: f32) {
        for (w, g) in self.weights.iter_mut().zip(grad.iter()) {
            *w -= lr * g;
        }
    }
}

impl MockAdapterStore {
    fn new(num_adapters: usize, dim: usize) -> Self {
        let adapters: HashMap<u32, MockAdapter> = (0..num_adapters)
            .map(|i| (i as u32, MockAdapter::new(dim, (i as u64) * 7919 + 31)))
            .collect();
        Self { adapters, dim }
    }

    fn forward(&self, handle: u32, input: &[f32]) -> Vec<f32> {
        self.adapters
            .get(&handle)
            .map_or_else(|| vec![0.5; self.dim], |a| a.forward(input))
    }
}

