impl OperadicCurriculum {
    pub fn new(num_adapters: usize, steps_per_stage: u64) -> Self {
        assert!(num_adapters >= 2);
        Self {
            current_step: 0,
            steps_per_stage,
            num_adapters,
            seed: 42,
        }
    }
    pub fn with_seed(num_adapters: usize, steps_per_stage: u64, seed: u64) -> Self {
        assert!(num_adapters >= 2);
        Self {
            current_step: 0,
            steps_per_stage,
            num_adapters,
            seed,
        }
    }
    pub fn stage(&self) -> CurriculumStage {
        let idx = (self.current_step / self.steps_per_stage) as usize;
        CurriculumStage::all()[idx.min(CurriculumStage::all().len() - 1)]
    }
    pub fn generate_expr(&mut self) -> AdapterExpr<u32> {
        let _ = self.stage();
        self.advance_seed();
        match self.stage() {
            CurriculumStage::SimpleAnd => {
                let (a, b) = self.pick_two_distinct();
                AdapterExpr::and(vec![AdapterExpr::single(a), AdapterExpr::single(b)])
            }
            CurriculumStage::MediumAnd => {
                let h = self.pick_distinct(4.min(self.num_adapters));
                AdapterExpr::and(h.into_iter().map(AdapterExpr::single).collect())
            }
            CurriculumStage::SimpleOr => {
                let (a, b) = self.pick_two_distinct();
                AdapterExpr::or(vec![AdapterExpr::single(a), AdapterExpr::single(b)])
            }
            CurriculumStage::MixedShallow => {
                let h = self.pick_distinct(3.min(self.num_adapters));
                let c = h.get(2).copied().unwrap_or(h[0]);
                AdapterExpr::and(vec![
                    AdapterExpr::or(vec![AdapterExpr::single(h[0]), AdapterExpr::single(h[1])]),
                    AdapterExpr::single(c),
                ])
            }
            CurriculumStage::MixedDeep => {
                let h = self.pick_distinct(4.min(self.num_adapters));
                let c = h.get(2).copied().unwrap_or(h[0]);
                let d = h.get(3).copied().unwrap_or(h[1 % h.len()]);
                let inner =
                    AdapterExpr::and(vec![AdapterExpr::single(h[0]), AdapterExpr::single(h[1])]);
                AdapterExpr::and(vec![
                    AdapterExpr::or(vec![inner, AdapterExpr::single(c)]),
                    AdapterExpr::single(d),
                ])
            }
            CurriculumStage::Full => self.gen_random_expr(4),
        }
    }
    pub fn step(&mut self) {
        self.current_step += 1;
    }
    pub fn current_step_val(&self) -> u64 {
        self.current_step
    }
    pub fn reset(&mut self) {
        self.current_step = 0;
        self.seed = 42;
    }

    fn gen_random_expr(&mut self, max_depth: usize) -> AdapterExpr<u32> {
        if max_depth == 0 {
            return AdapterExpr::single(self.pick_adapter());
        }
        self.advance_seed();
        let mut rng = fastrand::Rng::with_seed(self.seed);
        let roll = rng.u32(0..100);
        if roll < 20 {
            return AdapterExpr::single(self.pick_adapter());
        }
        let is_and = roll < 60;
        let n = rng.usize(2..=3);
        let ch: Vec<AdapterExpr<u32>> = (0..n)
            .map(|_| self.gen_random_expr(max_depth - 1))
            .collect();
        if is_and {
            AdapterExpr::and(ch)
        } else {
            AdapterExpr::or(ch)
        }
    }
    fn advance_seed(&mut self) {
        let mut s = self.seed;
        s ^= s << 13;
        s ^= s >> 7;
        s ^= s << 17;
        self.seed = s;
    }
    fn pick_adapter(&mut self) -> u32 {
        self.advance_seed();
        let mut rng = fastrand::Rng::with_seed(self.seed);
        rng.u32(0..self.num_adapters as u32)
    }
    fn pick_two_distinct(&mut self) -> (u32, u32) {
        let a = self.pick_adapter();
        let mut b = self.pick_adapter();
        let mut retries = 0;
        while b == a && retries < 20 {
            b = self.pick_adapter();
            retries += 1;
        }
        if b == a {
            // Fallback: deterministic complement for small adapter pools
            b = (a + 1) % self.num_adapters as u32;
        }
        (a, b)
    }
    fn pick_distinct(&mut self, n: usize) -> Vec<u32> {
        let mut r = Vec::with_capacity(n);
        let mut att = 0;
        while r.len() < n && att < n * 10 {
            let h = self.pick_adapter();
            if !r.contains(&h) {
                r.push(h);
            }
            att += 1;
        }
        while r.len() < n {
            r.push(r.len() as u32 % self.num_adapters as u32);
        }
        r
    }
}

use std::fmt;

/// A term in the free distributive lattice on n adapter generators.
///
/// This is the core algebraic type for operadic LoRA composition.
/// The free distributive lattice on n generators has:
/// - Identity: `Single(i)` for each generator i
/// - Meet: `And(vec![...])` — conjunction (AND)
/// - Join: `Or(vec![...])` — disjunction (OR)
///
/// Canonical form is achieved by applying the distributive lattice identities:
/// - Idempotency: `A ∧ A = A`, `A ∨ A = A`
/// - Commutativity: `A ∧ B = B ∧ A`, `A ∨ B = B ∨ A`
/// - Associativity: `(A ∧ B) ∧ C = A ∧ (B ∧ C)` (handled by flat Vec)
/// - Absorption: `A ∧ (A ∨ B) = A`, `A ∨ (A ∧ B) = A`
/// - Distributivity: `A ∧ (B ∨ C) = (A ∧ B) ∨ (A ∧ C)`
#[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum AdapterExpr<L> {
    /// Atomic adapter reference — a generator in the free distributive lattice.
    Single(L),
    /// Meet (∧) — conjunction of sub-expressions.
    /// After canonicalization: sorted, deduplicated, no nested And/Or of same type.
    And(Vec<AdapterExpr<L>>),
    /// Join (∨) — disjunction of sub-expressions.
    /// After canonicalization: sorted, deduplicated, no nested And/Or of same type.
    Or(Vec<AdapterExpr<L>>),
}

impl<L: Clone + Copy + PartialEq + Eq + std::hash::Hash + Ord> AdapterExpr<L> {
    /// Create a single (atomic) expression.
    pub fn single(handle: L) -> Self {
        Self::Single(handle)
    }

