impl GoalQValue {
    /// Create a new `GoalQValue`.
    #[inline]
    pub fn new(goal_id: u32, q_value: f32, confidence: f32) -> Self {
        // Confidence is expected in [0, 1]; we store it as-is and apply sigmoid
        // at read time. The caller should pass a pre-sigmoid logit if they want
        // the raw path, or a clamped [0,1] value if they already sigmoid'd.
        Self {
            goal_id,
            q_value,
            confidence_logit: confidence,
        }
    }

    /// Confidence ∈ [0, 1] via sigmoid.
    #[inline]
    pub fn confidence(&self) -> f32 {
        sigmoid(self.confidence_logit)
    }
}

impl LeoQValue {
    /// Create an empty `LeoQValue` with no goals.
    pub fn empty() -> Self {
        Self { goals: Vec::new() }
    }

    /// Create from a slice of per-goal Q-values.
    pub fn from_goals(goals: Vec<GoalQValue>) -> Self {
        Self { goals }
    }

    /// Compute the combined Q-value across all goals.
    ///
    /// Each goal contributes `q_value * confidence * weight` where `weight` is
    /// `1.0 / goals.len()` for uniform weighting. The caller can pre-weight
    /// individual `q_value`s via `MultiObjectiveWeights` before calling this.
    ///
    /// Returns 0.0 if there are no goals.
    pub fn combined_q(&self, alpha: f32) -> f32 {
        if self.goals.is_empty() {
            return 0.0;
        }
        let n = self.goals.len() as f32;
        let sum: f32 = self.goals.iter().map(|g| g.q_value * g.confidence()).sum();
        alpha * sum / n
    }

    /// Compute per-goal contribution fractions (for Pareto validation).
    ///
    /// Returns a `Vec<(goal_id, fraction)>` where each fraction ∈ [0, 1] and
    /// fractions sum to 1.0 (or empty if total is zero).
    pub fn contribution_fractions(&self) -> Vec<(u32, f32)> {
        let contributions: Vec<(u32, f32)> = self
            .goals
            .iter()
            .map(|g| (g.goal_id, g.q_value.abs() * g.confidence()))
            .collect();
        let total: f32 = contributions.iter().map(|(_, c)| c).sum();
        if total <= 0.0 {
            return Vec::new();
        }
        contributions
            .into_iter()
            .map(|(id, c)| (id, c / total))
            .collect()
    }
}

