impl LeoGuidedRefinement {
    /// Create with custom alpha.
    pub fn new(alpha: f32) -> Self {
        Self {
            alpha,
            goals: RefinementGoal::standard_goals(),
        }
    }

    /// Create with custom alpha and goals.
    pub fn with_goals(alpha: f32, goals: Vec<RefinementGoal>) -> Self {
        Self { alpha, goals }
    }

    /// Modify policy logits by adding the LEO Q-value bonus.
    ///
    /// For each action slot:
    ///   `combined_score[i] = policy_logits[i] + alpha * q_values.combined_q(alpha)`
    ///
    /// **Important**: the `q_values` should contain Q(s, a_i) for each action.
    /// If only a single combined Q-value is available (same bonus for all
    /// actions), all logits get the same additive term, which preserves the
    /// argmax ordering — no-op for argmax but useful when combined with
    /// per-action Q-values downstream.
    ///
    /// Returns the modified logits. Sampling happens elsewhere.
    pub fn refine_yr(
        &self,
        policy_logits: &[f32],
        q_values: &LeoQValue,
        _actions: &[usize],
    ) -> Vec<f32> {
        let q_bonus = q_values.combined_q(self.alpha);
        policy_logits.iter().map(|&logit| logit + q_bonus).collect()
    }

    /// Per-action variant: each action gets its own Q bonus.
    ///
    /// `per_action_q[i]` = combined Q-value for action i.
    /// `combined[i] = policy_logits[i] + alpha * per_action_q[i]`
    pub fn refine_yr_per_action(&self, policy_logits: &[f32], per_action_q: &[f32]) -> Vec<f32> {
        assert_eq!(
            policy_logits.len(),
            per_action_q.len(),
            "policy_logits and per_action_q must have same length"
        );
        policy_logits
            .iter()
            .zip(per_action_q.iter())
            .map(|(&logit, &q)| logit + self.alpha * q)
            .collect()
    }
}

impl MultiObjectiveWeights {
    /// All weights as an array indexed by standard goal_id.
    #[inline]
    pub fn as_slice(&self) -> [f32; 4] {
        [self.win, self.score, self.survival, self.exploration]
    }

    /// Get weight by goal_id (0=win, 1=score, 2=survival, 3=exploration).
    ///
    /// Returns 0.0 for unknown goal ids.
    pub fn weight_for_goal(&self, goal_id: u32) -> f32 {
        match goal_id {
            0 => self.win,
            1 => self.score,
            2 => self.survival,
            3 => self.exploration,
            _ => 0.0,
        }
    }

    /// Normalize weights so they sum to 1.0.
    ///
    /// If all weights are zero, leaves them unchanged (avoids division by zero).
    pub fn normalize(&mut self) {
        let total = self.win + self.score + self.survival + self.exploration;
        if total <= 0.0 {
            return;
        }
        self.win /= total;
        self.score /= total;
        self.survival /= total;
        self.exploration /= total;
    }

    /// Apply these weights to a `LeoQValue`, returning a single scalar.
    ///
    /// `combined = Σ_i weight_i * q_value_i * confidence_i`
    pub fn weighted_q(&self, q_values: &LeoQValue) -> f32 {
        q_values
            .goals
            .iter()
            .map(|g| self.weight_for_goal(g.goal_id) * g.q_value * g.confidence())
            .sum()
    }
}

impl ParetoCheck {
    pub fn new(min_goal_contribution: f32, dominance_threshold: f32) -> Self {
        Self {
            min_goal_contribution,
            dominance_threshold,
        }
    }

    /// Validate multi-objective balance of Q-values.
    ///
    /// Checks that:
    /// 1. No single goal exceeds `dominance_threshold` of combined signal.
    /// 2. Every goal with non-zero weight contributes at least `min_goal_contribution`.
    pub fn validate(&self, q_values: &LeoQValue, weights: &MultiObjectiveWeights) -> ParetoResult {
        // Weighted contributions: weight_i * |q_i| * confidence_i
        let contributions: Vec<(u32, f32)> = q_values
            .goals
            .iter()
            .map(|g| {
                (
                    g.goal_id,
                    weights.weight_for_goal(g.goal_id) * g.q_value.abs() * g.confidence(),
                )
            })
            .collect();

        let total: f32 = contributions.iter().map(|(_, c)| c).sum();
        if total <= 0.0 {
            // All contributions are zero — degenerate but not dominated.
            return ParetoResult::Balanced;
        }

        // Check for any single goal dominating (> threshold).
        for &(goal_id, contrib) in &contributions {
            let frac = contrib / total;
            if frac > self.dominance_threshold {
                return ParetoResult::Dominated(goal_id);
            }
        }

        ParetoResult::Balanced
    }

    /// Convenience: validate with default weights and standard Pareto check.
    pub fn validate_default(q_values: &LeoQValue) -> ParetoResult {
        Self::default().validate(q_values, &MultiObjectiveWeights::default())
    }
}

impl InsertOutcome {
    /// True when the entry was stored (with or without an eviction).
    #[must_use]
    pub fn accepted(self) -> bool {
        matches!(self, Self::Accepted(_) | Self::AcceptedEvicted(_))
    }
}

impl PrivilegedBank {
    /// Create an empty bank.
    #[must_use]
    pub fn new(config: BankConfig) -> Self {
        Self {
            entries: Vec::with_capacity(config.capacity.min(4096)),
            config,
            write_head: 0,
            rejected_low_reward: 0,
            rejected_eval_split: 0,
            rejected_dim_mismatch: 0,
        }
    }

    /// Admit a rollout, enforcing the reward threshold, the train-split-only
    /// invariant, and the embedding dimension.
    ///
    /// At capacity the oldest entry is overwritten (ring), so a long run has
    /// bounded memory.
    pub fn insert(
        &mut self,
        task: impl Into<String>,
        trace: impl Into<String>,
        reward: f32,
        doc_embedding: Vec<f32>,
        split: Split,
    ) -> InsertOutcome {
        // Order matters for observability: the leakage guard is checked first so
        // an eval entry is never counted as merely low-reward.
        if split == Split::Eval {
            self.rejected_eval_split += 1;
            return InsertOutcome::RejectedEvalSplit;
        }
        // `partial_cmp` rather than `!(reward >= t)`: NaN yields `None` and is
        // refused, and the intent (incomparable => reject) is explicit instead of
        // hiding in a negated float comparison.
        if !matches!(
            reward.partial_cmp(&self.config.reward_threshold),
            Some(Ordering::Greater | Ordering::Equal)
        ) {
            self.rejected_low_reward += 1;
            return InsertOutcome::RejectedLowReward;
        }
        if doc_embedding.len() != self.config.dim {
            self.rejected_dim_mismatch += 1;
            return InsertOutcome::RejectedDimMismatch;
        }

        let entry = BankEntry {
            task: task.into(),
            trace: trace.into(),
            reward,
            doc_embedding,
        };

        if self.entries.len() < self.config.capacity {
            self.entries.push(entry);
            InsertOutcome::Accepted(self.entries.len() - 1)
        } else {
            let idx = self.write_head;
            self.entries[idx] = entry;
            self.write_head = (self.write_head + 1) % self.config.capacity.max(1);
            InsertOutcome::AcceptedEvicted(idx)
        }
    }

    /// Retrieve the top-`j` entries by cosine similarity against `query`.
    ///
    /// `out` is cleared and reused, so a steady-state training loop can retrieve
    /// without allocating. Ordering is descending by score with **index as a
    /// deterministic tie-break**, so equal-scoring entries never reorder between
    /// runs (a reproducibility requirement, not a nicety).
    pub fn retrieve_top_j(&self, query: &[f32], j: usize, out: &mut Vec<Retrieved>) {
        out.clear();
        if j == 0 || self.entries.is_empty() || query.len() != self.config.dim {
            return;
        }
        for (idx, e) in self.entries.iter().enumerate() {
            out.push(Retrieved {
                idx,
                score: cosine(query, &e.doc_embedding),
            });
        }
        out.sort_by(|a, b| match b.score.partial_cmp(&a.score) {
            Some(Ordering::Equal) | None => a.idx.cmp(&b.idx),
            Some(o) => o,
        });
        out.truncate(j);
    }

    /// BLAKE3 commitment over the bank's logical contents, for freeze/thaw
    /// versioning.
    ///
    /// Committed in **stored order** over `(task, trace, reward, doc_embedding)`
    /// with explicit length prefixes, so the digest cannot be spoofed by moving a
    /// separator between adjacent fields. Reward and embedding bytes come from
    /// `to_le_bytes`/`to_bits`, so the commitment is bit-exact rather than
    /// format-dependent.
    #[must_use]
    pub fn commitment(&self) -> [u8; 32] {
        let mut h = blake3::Hasher::new();
        h.update(b"LOPD-BANK-v1");
        h.update(&(self.entries.len() as u64).to_le_bytes());
        for e in &self.entries {
            h.update(&(e.task.len() as u64).to_le_bytes());
            h.update(e.task.as_bytes());
            h.update(&(e.trace.len() as u64).to_le_bytes());
            h.update(e.trace.as_bytes());
            h.update(&e.reward.to_bits().to_le_bytes());
            h.update(&(e.doc_embedding.len() as u64).to_le_bytes());
            for v in &e.doc_embedding {
                h.update(&v.to_bits().to_le_bytes());
            }
        }
        *h.finalize().as_bytes()
    }

    /// Entries currently stored.
    #[must_use]
    pub fn len(&self) -> usize {
        self.entries.len()
    }

    /// True when empty.
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }

    /// Configured capacity.
    #[must_use]
    pub fn capacity(&self) -> usize {
        self.config.capacity
    }

    /// Borrow the stored entries in ring order.
    #[must_use]
    pub fn entries(&self) -> &[BankEntry] {
        &self.entries
    }

    /// Refusal counts as `(low_reward, eval_split, dim_mismatch)`.
    #[must_use]
    pub fn rejection_counts(&self) -> (usize, usize, usize) {
        (
            self.rejected_low_reward,
            self.rejected_eval_split,
            self.rejected_dim_mismatch,
        )
    }
}

use katgpt_core::engram::{sigmoid_fuse_scaled_into, SigmoidFusionConfig};

/// Paper default number of learned query slots (Research 419 §F8).
pub const DEFAULT_K_QUERIES: usize = 32;

/// Snapshot/param format version. Bump on any change to the parameter layout or
/// to the composition math — a φ₀ snapshot taken under a different version is not
/// interchangeable, and the anchor term would silently pull toward a different
/// construction.
pub const COMPOSER_VERSION: u32 = 1;

/// Why a composer operation was refused.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ComposerError {
    /// `k_queries`, `d_model` or `e_embed` was zero.
    ZeroDimension,
    /// A document embedding's length did not match `e_embed`.
    DocDimMismatch { expected: usize, got: usize }

fn next_unit(state: &mut u64) -> f32 {
    // Map to [-1, 1). 24 bits of mantissa is plenty for an init.
    let v = (next_u64(state) >> 40) as f32 / (1u64 << 24) as f32;

impl Composer {
    /// Build φ₀ — the deterministic cold-start construction.
    ///
    /// Query slots are seeded pseudo-randomly and then RMS-normalised per slot.
    /// The normalisation is not cosmetic: `sigmoid_fuse_scaled_into` divides the
    /// normalised dot by `tau`, so slots with wildly different norms would start
    /// saturated at 0 or 1 and the `K` capacity knob would be dead on arrival.
    pub fn cold_start(config: ComposerConfig) -> Result<Self, ComposerError> {
        if config.k_queries == 0 || config.d_model == 0 || config.e_embed == 0 {
            return Err(ComposerError::ZeroDimension);
        }
        let d = config.d_model;
        // xorshift64 dies on a zero state, but `seed | 1` would be wrong: it maps
        // every even seed onto its odd successor, so 340 and 341 would produce
        // byte-identical query slots. Substitute only the degenerate value.
        let mut state = if config.seed == 0 {
            0xDEAD_BEEF_CAFE_BABE
        } else {
            config.seed
        };
        let mut queries = vec![0.0f32; config.k_queries * d];
        for slot in queries.chunks_mut(d) {
            for v in slot.iter_mut() {
                *v = next_unit(&mut state);
            }
            let ms = slot.iter().map(|v| v * v).sum::<f32>() / d as f32;
            let inv = 1.0 / (ms + 1e-6).sqrt();
            for v in slot.iter_mut() {
                *v *= inv;
            }
        }
        let tau = config.tau.unwrap_or_else(|| (d as f32).sqrt());
        Ok(Self {
            fusion: SigmoidFusionConfig {
                tau,
                rmsnorm_eps: 1e-6,
            },
            adapted: vec![0.0; d],
            queries,
            config,
        })
    }

    /// Load a cold-start (NLL-pretrained) parameter blob into φ₀'s slots.
    ///
    /// Validates version, length and finiteness. Finiteness is checked because a
    /// single NaN slot would produce a NaN gate, and a NaN latent injected into
    /// the teacher poisons the whole conditioned forward while still "working".
    pub fn load_cold_start(
        config: ComposerConfig,
        version: u32,
        params: &[f32],
    ) -> Result<Self, ComposerError> {
        if version != COMPOSER_VERSION {
            return Err(ComposerError::VersionMismatch {
                expected: COMPOSER_VERSION,
                got: version,
            });
        }
        let mut me = Self::cold_start(config)?;
        let expected = me.queries.len();
        if params.len() != expected {
            return Err(ComposerError::ParamLenMismatch {
                expected,
                got: params.len(),
            });
        }
        if params.iter().any(|v| !v.is_finite()) {
            return Err(ComposerError::NonFiniteParam);
        }
        me.queries.copy_from_slice(params);
        Ok(me)
    }

    /// Freeze the current parameters as a φ₀ snapshot.
    #[must_use]
    pub fn snapshot(&self) -> Phi0 {
        Phi0 {
            version: COMPOSER_VERSION,
            queries: self.queries.clone(),
            k_queries: self.config.k_queries,
            d_model: self.config.d_model,
        }
    }

    /// Number of floats one entry composes to: `K * D`.
    #[must_use]
    pub fn latents_len(&self) -> usize {
        self.config.k_queries * self.config.d_model
    }

    /// Config accessor.
    #[must_use]
    pub fn config(&self) -> &ComposerConfig {
        &self.config
    }

    /// Adapt an `E`-dim document embedding to `D` dims, in place into scratch.
    ///
    /// `E == D` copies. Otherwise the vector is **cyclically tiled** (or
    /// truncated), which is deterministic, allocation-free and norm-preserving up
    /// to the repeat count. Deliberately not a learned projection: φ₀ is the
    /// *deterministic* construction, and an `E × D` dense matrix would add
    /// millions of parameters to a cold start that is supposed to have none.
    fn adapt_into(&mut self, doc: &[f32]) {
        let d = self.config.d_model;
        let e = doc.len();
        if e == d {
            self.adapted.copy_from_slice(doc);
            return;
        }
        for (i, o) in self.adapted[..d].iter_mut().enumerate() {
            *o = doc[i % e];
        }
    }

    /// Compose one retrieved document into `K` latent tokens.
    ///
    /// `out` must be exactly `K * D` and is fully overwritten, so the caller owns
    /// the buffer and the steady state allocates nothing.
    pub fn compose_entry_into(
        &mut self,
        doc: &[f32],
        out: &mut [f32],
    ) -> Result<(), ComposerError> {
        if doc.len() != self.config.e_embed {
            return Err(ComposerError::DocDimMismatch {
                expected: self.config.e_embed,
                got: doc.len(),
            });
        }
        let want = self.latents_len();
        if out.len() != want {
            return Err(ComposerError::OutLenMismatch {
                expected: want,
                got: out.len(),
            });
        }
        self.adapt_into(doc);
        let d = self.config.d_model;
        for (k, slot_out) in out.chunks_mut(d).enumerate() {
            let q = &self.queries[k * d..(k + 1) * d];
            // gate * adapted -> slot_out, and the gate comes back so the
            // prototype residual can be added.
            let gate = sigmoid_fuse_scaled_into(
                q,
                &self.adapted,
                &self.adapted,
                slot_out,
                &self.fusion,
                1.0,
            );
            let keep = 1.0 - gate;
            for (o, &qi) in slot_out.iter_mut().zip(q.iter()) {
                *o += keep * qi;
            }
        }
        Ok(())
    }
}

impl Composer {
    /// Apply `scale * d_queries` to the query slots (an SGD step when
    /// `scale = -lr`).
    ///
    /// Separate from the backward so a caller can accumulate gradient over the
    /// `J` retrieved entries of a step and apply once — applying per entry would
    /// make the effective step size depend on how many entries happened to be
    /// retrieved.
    pub fn apply_query_grad(&mut self, scale: f32, d_queries: &[f32]) {
        for (q, g) in self.queries.iter_mut().zip(d_queries.iter()) {
            *q += scale * g;
        }
    }

    /// Backward through one entry's composition.
    ///
    /// Given `d_out` = dL/d(latents) laid out `[K × D]` — which is exactly what
    /// katgpt-rs's `kimi_k3_backward_sequence_with_input_grad` now delivers per
    /// injected latent — accumulate dL/d(query slots) into `d_queries` (`K·D`).
    ///
    /// This is the only gradient path the composer has: its parameters live
    /// upstream of the frozen backbone, so nothing reaches them except through the
    /// injected hidden states (prefix-tuning, Research 419 §A.4).
    ///
    /// Forward, per slot: `out = gate·a + (1−gate)·q` with
    /// `gate = σ(dot(q/‖q‖_rms, a/‖a‖_rms)/τ)`, so
    ///
    /// ```text
    /// dL/dgate = <d_out, a − q>
    /// dL/dq    = (1 − gate)·d_out            (direct path)
    ///          + dL/dgate · gate(1−gate) · dz/dq
    /// dz/dq    = ( a_n/r − <q, a_n>·q/(D·r³) ) / τ
    /// ```
    ///
    /// where `r` is `q`'s RMS and `a_n` is the RMS-normalised document. The second
    /// term is the one that is easy to drop: without it the gate looks constant to
    /// the optimiser and the slots can only ever move along `d_out`, which is a
    /// strictly weaker composer. A finite-difference test covers both terms.
    ///
    /// `d_out` is NOT consumed and `d_queries` is accumulated into, so a caller can
    /// sum over the `J` retrieved entries of one step.
    pub fn compose_entry_backward_into(
        &mut self,
        doc: &[f32],
        d_out: &[f32],
        d_queries: &mut [f32],
    ) -> Result<(), ComposerError> {
        if doc.len() != self.config.e_embed {
            return Err(ComposerError::DocDimMismatch {
                expected: self.config.e_embed,
                got: doc.len(),
            });
        }
        let want = self.latents_len();
        if d_out.len() != want {
            return Err(ComposerError::OutLenMismatch {
                expected: want,
                got: d_out.len(),
            });
        }
        if d_queries.len() != want {
            return Err(ComposerError::OutLenMismatch {
                expected: want,
                got: d_queries.len(),
            });
        }
        self.adapt_into(doc);
        let d = self.config.d_model;
        let tau = self.fusion.tau;
        let eps = self.fusion.rmsnorm_eps;

        // RMS-normalised document, shared across slots.
        let a_ms = self.adapted.iter().map(|v| v * v).sum::<f32>() / d as f32;
        let a_inv = 1.0 / (a_ms + eps).sqrt();

        for k in 0..self.config.k_queries {
            let q = &self.queries[k * d..(k + 1) * d];
            let go = &d_out[k * d..(k + 1) * d];

            let q_ms = q.iter().map(|v| v * v).sum::<f32>() / d as f32;
            let r = (q_ms + eps).sqrt();
            let q_inv = 1.0 / r;

            // z = dot(q_n, a_n)/tau, gate = sigmoid(z)
            let dot_qa = q
                .iter()
                .zip(self.adapted.iter())
                .map(|(x, y)| x * y)
                .sum::<f32>();
            let z = dot_qa * q_inv * a_inv / tau;
            let gate = 1.0 / (1.0 + (-z).exp());

            // dL/dgate = <d_out, a - q>
            let d_gate = go
                .iter()
                .zip(self.adapted.iter().zip(q.iter()))
                .map(|(g, (a, qi))| g * (a - qi))
                .sum::<f32>();
            let dz = d_gate * gate * (1.0 - gate);

            // <q, a_n> where a_n = adapted * a_inv
            let dot_q_an = dot_qa * a_inv;
            let coef = dz / tau;
            let r3 = r * r * r;

            let dq = &mut d_queries[k * d..(k + 1) * d];
            for i in 0..d {
                let an_i = self.adapted[i] * a_inv;
                // dz/dq_i = ( a_n_i / r - <q,a_n> * q_i / (D * r^3) )
                let dz_dq = an_i * q_inv - dot_q_an * q[i] / (d as f32 * r3);
                dq[i] += (1.0 - gate) * go[i] + coef * dz_dq;
            }
        }
        Ok(())
    }
}

impl Phi0Cache {
    /// Allocate for `capacity` entries of `stride = K * D` floats each.
    #[must_use]
    pub fn new(capacity: usize, stride: usize) -> Self {
        Self {
            latents: vec![0.0; capacity * stride],
            valid: vec![false; capacity],
            stride,
            hits: 0,
            misses: 0,
        }
    }

    /// Capacity in entries.
    #[must_use]
    pub fn capacity(&self) -> usize {
        self.valid.len()
    }

    /// `(hits, misses)` — so a caller can assert the cache is actually working
    /// rather than silently recomputing.
    #[must_use]
    pub fn stats(&self) -> (usize, usize) {
        (self.hits, self.misses)
    }

    /// Invalidate one entry (e.g. after the bank evicted and reused the slot).
    pub fn invalidate(&mut self, idx: usize) {
        if let Some(v) = self.valid.get_mut(idx) {
            *v = false;
        }
    }

    /// Drop every cached latent — required when φ₀ itself is replaced, otherwise
    /// the anchor would pull toward a construction that no longer exists.
    pub fn invalidate_all(&mut self) {
        self.valid.iter_mut().for_each(|v| *v = false);
    }

    /// Cached `cφ₀` for `idx`, composing on a miss.
    pub fn get_or_compute(
        &mut self,
        idx: usize,
        doc: &[f32],
        composer: &mut Composer,
    ) -> Result<&[f32], ComposerError> {
        if idx >= self.valid.len() {
            return Err(ComposerError::CacheIndexOutOfRange {
                capacity: self.valid.len(),
                got: idx,
            });
        }
        if self.stride != composer.latents_len() {
            return Err(ComposerError::OutLenMismatch {
                expected: composer.latents_len(),
                got: self.stride,
            });
        }
        let lo = idx * self.stride;
        let hi = lo + self.stride;
        if self.valid[idx] {
            self.hits += 1;
        } else {
            composer.compose_entry_into(doc, &mut self.latents[lo..hi])?;
            self.valid[idx] = true;
            self.misses += 1;
        }
        Ok(&self.latents[lo..hi])
    }
}

impl MarginConfig {
    /// Reject a configuration that cannot produce a meaningful dual variable.
    ///
    /// Validated up front rather than defended per-step: a NaN `margin` or an
    /// `ema` of 1.0 (which freezes `Delta` at its initial value forever) yields
    /// a monitor that reports confident numbers and tracks nothing.
    pub fn validate(&self) -> Result<(), String> {
        match () {
            _ if !self.margin.is_finite() => Err(format!("margin must be finite, got {}", self.margin)),
            _ if !self.dual_lr.is_finite() || self.dual_lr < 0.0 => {
                Err(format!("dual_lr must be finite and >= 0, got {}", self.dual_lr))
            }
            _ if !(0.0..1.0).contains(&self.ema) => {
                Err(format!("ema must be in [0, 1), got {} (1.0 would freeze Delta forever)", self.ema))
            }
            _ if self.beta_max.is_nan() || self.beta_max < 0.0 => {
                Err(format!("beta_max must be >= 0, got {}", self.beta_max))
            }
            _ => Ok(()),
        }
    }
}

impl PrivilegeMarginMonitor {
    pub fn new(cfg: MarginConfig) -> Result<Self, String> {
        cfg.validate()?;
        Ok(Self {
            cfg,
            delta: None,
            beta: 0.0,
            steps: 0,
            violations: 0,
        })
    }

    /// Smoothed privilege margin `Delta`. `None` before the first observation.
    pub fn delta(&self) -> Option<f32> {
        self.delta
    }

    /// The dual variable `beta` (>= 0). Rising means the retrieved context has
    /// been failing to earn its margin.
    pub fn beta(&self) -> f32 {
        self.beta
    }

    pub fn steps(&self) -> u64 {
        self.steps
    }

    pub fn violations(&self) -> u64 {
        self.violations
    }

    /// Fraction of observed steps that violated the margin. 0.0 before any step.
    pub fn violation_rate(&self) -> f32 {
        match self.steps {
            0 => 0.0,
            n => self.violations as f32 / n as f32,
        }
    }

    /// `true` once the contract has been satisfied on the smoothed reading.
    ///
    /// This is the consumer-facing predicate: a fuse gate asks "is the retrieved
    /// context still earning its keep?" and gets one bool.
    pub fn margin_satisfied(&self) -> bool {
        match self.delta {
            Some(d) => d >= self.cfg.margin,
            None => false,
        }
    }

    /// The margin loss term `beta * (m - Delta)` for this step.
    ///
    /// Zero before the first observation (no constraint reading exists yet) and
    /// zero whenever `beta` is 0 (the constraint has been comfortably met), so a
    /// satisfied contract contributes nothing to the objective.
    pub fn margin_loss(&self) -> f32 {
        match self.delta {
            Some(d) => self.beta * (self.cfg.margin - d),
            None => 0.0,
        }
    }

    /// Observe one step from raw per-token privileges and a scalar reward.
    ///
    /// `privileges` are the per-token gaps `log pi_T - sg[log pi_S]` over the
    /// masked tokens; `reward` is the verified outcome in `[0, 1]`, mapped to
    /// the advantage `A(tau) = 2r - 1`.
    ///
    /// Non-finite privileges are SKIPPED rather than propagated: one NaN token
    /// would otherwise poison `Delta` permanently through the EMA, and a dual
    /// variable driven by NaN is silently dead. Returns the raw (unsmoothed)
    /// step privilege actually used, or `None` if the step carried no usable
    /// token.
    pub fn observe(&mut self, privileges: &[f32], reward: f32) -> Option<f32> {
        let mut sum = 0.0f32;
        let mut n = 0u32;
        for &p in privileges {
            if p.is_finite() {
                sum += p;
                n += 1;
            }
        }
        if n == 0 || !reward.is_finite() {
            return None;
        }
        let advantage = 2.0 * reward - 1.0;
        let step_delta = advantage * (sum / n as f32);
        self.observe_scalar(step_delta);
        Some(step_delta)
    }

    /// Observe one already-reduced outcome-weighted privilege.
    ///
    /// Split out so a caller that computes `Delta` on GPU can feed the dual
    /// variable without materializing per-token privileges on the host.
    pub fn observe_scalar(&mut self, step_delta: f32) {
        if !step_delta.is_finite() {
            return;
        }
        // Seed from the first real reading rather than decaying from 0.0, which
        // would otherwise take ~1/(1-ema) steps to stop being an artifact of the
        // initial value.
        let smoothed = match self.delta {
            None => step_delta,
            Some(prev) => self.cfg.ema * prev + (1.0 - self.cfg.ema) * step_delta,
        };
        self.delta = Some(smoothed);
        self.steps += 1;

        let gap = self.cfg.margin - smoothed;
        if gap > 0.0 {
            self.violations += 1;
        }
        // Projected dual ascent: beta <- [beta + eta * (m - Delta)]_+, then
        // clamped. The projection is what makes beta a valid Lagrange
        // multiplier for an inequality constraint — a satisfied constraint
        // must relax it toward 0, never drive it negative.
        self.beta = (self.beta + self.cfg.dual_lr * gap).clamp(0.0, self.cfg.beta_max);
    }

    /// Reset the dual state, keeping the configuration. Used when the bank is
    /// re-ingested and the prior constraint history no longer describes it.
    pub fn reset(&mut self) {
        self.delta = None;
        self.beta = 0.0;
        self.steps = 0;
        self.violations = 0;
    }
}

impl LoraMatrix {
    /// Create a zero-initialized LoRA pair.
    /// `B` starts at zero so the initial delta is zero (standard LoRA init).
    /// `A` starts with small random values (Kaiming uniform on rank dim).
    pub fn new(rank: usize, in_dim: usize, out_dim: usize, seed: u64) -> Self {
        let mut state = seed.max(1);
        let bound = (6.0_f32 / rank.max(1) as f32).sqrt();

        let a: Vec<f32> = (0..rank * in_dim)
            .map(|_| {
                // xorshift64* for uniform [0,1)
                state ^= state >> 12;
                state ^= state << 25;
                state ^= state >> 27;
                let u = ((state.wrapping_mul(0x2545_F491_4F6C_DD1D)) >> 32) as f32
                    / u32::MAX as f32;
                (u * 2.0 - 1.0) * bound
            })
            .collect();

        // B = 0 (standard LoRA init: delta starts at zero)
        let b = vec![0.0; out_dim * rank];

        Self { a, b, rank, in_dim, out_dim }
    }

    /// Compute the LoRA delta `(alpha/rank) * B @ A` and add it into `weight`.
    ///
    /// `weight` is `[out_dim, in_dim]` row-major (same as the model weight).
    #[inline]
    #[allow(clippy::needless_range_loop)]
    pub fn merge_into(&self, weight: &mut [f32], scaling: f32) {
        debug_assert_eq!(weight.len(), self.out_dim * self.in_dim);
        // delta[i,j] += scaling * sum_k B[i,k] * A[k,j]
        for i in 0..self.out_dim {
            let b_row = &self.b[i * self.rank..(i + 1) * self.rank];
            let w_row = &mut weight[i * self.in_dim..(i + 1) * self.in_dim];
            for k in 0..self.rank {
                let bk = b_row[k];
                if bk == 0.0 {
                    continue; // skip zero B entries (common at init)
                }
                let scaled_bk = scaling * bk;
                let a_row = &self.a[k * self.in_dim..(k + 1) * self.in_dim];
                for j in 0..self.in_dim {
                    w_row[j] += scaled_bk * a_row[j];
                }
            }
        }
    }

    /// Subtract the LoRA delta from `weight` (inverse of `merge_into`).
    #[inline]
    #[allow(clippy::needless_range_loop)]
    pub fn unmerge_from(&self, weight: &mut [f32], scaling: f32) {
        debug_assert_eq!(weight.len(), self.out_dim * self.in_dim);
        for i in 0..self.out_dim {
            let b_row = &self.b[i * self.rank..(i + 1) * self.rank];
            let w_row = &mut weight[i * self.in_dim..(i + 1) * self.in_dim];
            for k in 0..self.rank {
                let bk = b_row[k];
                if bk == 0.0 {
                    continue;
                }
                let scaled_bk = scaling * bk;
                let a_row = &self.a[k * self.in_dim..(k + 1) * self.in_dim];
                for j in 0..self.in_dim {
                    w_row[j] -= scaled_bk * a_row[j];
                }
            }
        }
    }

    /// Project a weight gradient `grad_w` to LoRA gradients.
    ///
    /// - `grad_a[k,j] += scaling * sum_i B[i,k] * grad_w[i,j]`
    /// - `grad_b[i,k] += scaling * sum_j grad_w[i,j] * A[k,j]`
    #[inline]
    #[allow(clippy::needless_range_loop)]
    pub fn project_grad(
        &self,
        grad_w: &[f32],
        grad_a: &mut [f32],
        grad_b: &mut [f32],
        scaling: f32,
    ) {
        debug_assert_eq!(grad_w.len(), self.out_dim * self.in_dim);
        debug_assert_eq!(grad_a.len(), self.rank * self.in_dim);
        debug_assert_eq!(grad_b.len(), self.out_dim * self.rank);

        // Both projections in ONE i-major pass over `grad_w`:
        //   grad_b[i,k] += scaling * sum_j grad_w[i,j] * A[k,j]   (grad_w @ A^T)
        //   grad_a[k,j] += scaling * sum_i B[i,k] * grad_w[i,j]   (B^T @ grad_w)
        //
        // The grad_a term used to loop k,j,i, walking `grad_w` down a column
        // with an `in_dim * 4`-byte stride — a cache miss per element. Fusing it
        // into the i,k,j order makes every access row-sequential (dot + axpy over
        // the same `gw_row`) and lets LLVM emit FMA. Measured 1.9–5.2x on
        // 1024x1024 .. 1024x2816 shapes.
        for i in 0..self.out_dim {
            let gw_row = &grad_w[i * self.in_dim..(i + 1) * self.in_dim];
            let b_row = &self.b[i * self.rank..(i + 1) * self.rank];
            let gb_row = &mut grad_b[i * self.rank..(i + 1) * self.rank];
            for k in 0..self.rank {
                let a_row = &self.a[k * self.in_dim..(k + 1) * self.in_dim];
                let ga_row = &mut grad_a[k * self.in_dim..(k + 1) * self.in_dim];
                let scaled_bk = scaling * b_row[k];
                let mut sum = 0.0_f32;
                for j in 0..self.in_dim {
                    let gw = gw_row[j];
                    sum += gw * a_row[j];
                    ga_row[j] += scaled_bk * gw;
                }
                gb_row[k] += scaling * sum;
            }
        }
    }

    /// Count of trainable parameters in this adapter (A + B).
    pub fn param_count(&self) -> usize {
        self.a.len() + self.b.len()
    }
}

impl LoraGradPair {
    pub fn zeros_like(m: &LoraMatrix) -> Self {
        Self {
            grad_a: vec![0.0; m.a.len()],
            grad_b: vec![0.0; m.b.len()],
        }
    }

    /// Project a weight gradient `grad_w` into this grad pair.
    /// Uses the LoRA matrix `m` (for B^T in grad_A and A^T in grad_B).
    #[inline]
    #[allow(clippy::needless_range_loop)]
    pub fn project_grad_pair(&mut self, grad_w: &[f32], m: &LoraMatrix, scaling: f32) {
        let rank = m.rank;
        let in_dim = m.in_dim;
        let out_dim = m.out_dim;
        debug_assert_eq!(grad_w.len(), out_dim * in_dim);
        debug_assert_eq!(self.grad_a.len(), rank * in_dim);
        debug_assert_eq!(self.grad_b.len(), out_dim * rank);

        // Both projections in ONE i-major pass over `grad_w` (see
        // `LoraMatrix::project_grad` for why — the grad_a term used to walk
        // `grad_w` column-wise at an `in_dim * 4`-byte stride):
        //   grad_b[i,k] += scaling * sum_j grad_w[i,j] * A[k,j]
        //   grad_a[k,j] += scaling * sum_i B[i,k] * grad_w[i,j]
        //
        // NaN/inf in grad_w or B (from KDA backward f32 overflow) are treated
        // as 0. The guard is a branch-free select so the fused dot+axpy still
        // vectorizes.
        for i in 0..out_dim {
            let gw_row = &grad_w[i * in_dim..(i + 1) * in_dim];
            let b_row = &m.b[i * rank..(i + 1) * rank];
            let gb_row = &mut self.grad_b[i * rank..(i + 1) * rank];
            for k in 0..rank {
                let a_row = &m.a[k * in_dim..(k + 1) * in_dim];
                let ga_row = &mut self.grad_a[k * in_dim..(k + 1) * in_dim];
                let bk = b_row[k];
                let scaled_bk = if bk.is_finite() { scaling * bk } else { 0.0 };
                let mut sum = 0.0_f32;
                for j in 0..in_dim {
                    let gw = gw_row[j];
                    let gw = if gw.is_finite() { gw } else { 0.0 };
                    sum += gw * a_row[j];
                    ga_row[j] += scaled_bk * gw;
                }
                let val = scaling * sum;
                if val.is_finite() {
                    gb_row[k] += val;
                }
            }
        }
    }
}

impl MergeStats {
    /// Fraction of attempted moves the grid refused, in `[0, 1]`.
    ///
    /// `0.0` means the merge was lossless in the full LoTA-QAF sense — every
    /// update landed. Anything above that is adapter signal the base could not
    /// absorb.
    pub fn saturation_ratio(&self) -> f32 {
        match self.moved {
            0 => 0.0,
            n => self.saturated as f32 / n as f32,
        }
    }
}

impl KgTriple {
    pub fn new(head: Vec<f32>, relation: Vec<f32>, tail: Vec<f32>) -> Self {
        debug_assert_eq!(head.len(), tail.len());
        Self {
            head,
            relation,
            tail,
        }
    }

    /// Compute translational score: ||h + r - t||²
    pub fn translational_score(&self) -> f32 {
        self.head
            .iter()
            .zip(self.relation.iter())
            .zip(self.tail.iter())
            .map(|((h, r), t)| (h + r - t).powi(2))
            .sum()
    }

    /// Compute hyperplane score: normal_r · (h - t)
    /// Uses relation as the normal vector.
    pub fn hyperplane_score(&self) -> f32 {
        self.head
            .iter()
            .zip(self.tail.iter())
            .zip(self.relation.iter())
            .map(|((h, t), n)| n * (h - t))
            .sum()
    }
}

impl ManifoldKgLoss {
    /// Create a new KG manifold loss.
    pub fn new(manifold_fn: ManifoldFunction, radius: f32, weight: f32) -> Self {
        Self {
            manifold_fn,
            radius,
            weight,
            per_relation_radii: Vec::new(),
        }
    }

    /// Create default sphere KG loss.
    pub fn default_sphere() -> Self {
        Self::new(ManifoldFunction::Sphere, 0.0, 0.1)
    }

    /// Create default hyperplane KG loss.
    pub fn default_hyperplane() -> Self {
        Self::new(ManifoldFunction::Hyperplane, 0.0, 0.1)
    }

    /// Score a single triple using the configured manifold function.
    ///
    /// M(h,r,t) = ||h + r - t||² (sphere) or normal_r · (h - t) (hyperplane)
    pub fn score_triple(&self, triple: &KgTriple) -> f32 {
        match self.manifold_fn {
            ManifoldFunction::Sphere => triple.translational_score(),
            ManifoldFunction::Hyperplane => triple.hyperplane_score(),
        }
    }

    /// Compute loss for a single triple.
    ///
    /// L = (M(h,r,t) - D_r²)²
    pub fn triple_loss(&self, triple: &KgTriple) -> f32 {
        let score = self.score_triple(triple);
        let d_r = self.radius;
        let residual = score - d_r * d_r;
        residual * residual
    }

    /// Compute loss for a batch of triples.
    ///
    /// L_KG = Σ_i (M(h_i,r_i,t_i) - D_r²)²
    pub fn batch_loss(&self, triples: &[KgTriple]) -> f32 {
        triples.iter().map(|t| self.triple_loss(t)).sum()
    }

    /// Compute weighted batch loss for combined training.
    ///
    /// Returns: weight * L_KG
    pub fn weighted_batch_loss(&self, triples: &[KgTriple]) -> f32 {
        self.weight * self.batch_loss(triples)
    }

    /// Combine with base loss: L_total = base + weight * L_KG
    pub fn combined_loss(&self, base_loss: f32, triples: &[KgTriple]) -> f32 {
        base_loss + self.weighted_batch_loss(triples)
    }

    /// Check well-posedness: embedding_dim >= num_triples / (num_entities + num_relations).
    ///
    /// ManifoldE requires enough dimensions for the KG to be representable.
    /// Returns true if well-posed, false with warning if under-determined.
    pub fn check_well_posedness(
        &self,
        embedding_dim: usize,
        num_triples: usize,
        num_entities: usize,
        num_relations: usize,
    ) -> bool {
        let denominator = num_entities + num_relations;
        if denominator == 0 {
            return true; // trivial case
        }
        embedding_dim >= num_triples / denominator
    }

    /// Set per-relation manifold radii.
    pub fn set_per_relation_radii(&mut self, radii: Vec<f32>) {
        self.per_relation_radii = radii;
    }
}

impl ManifoldLoraLoss {
    /// Create a new manifold loss with the given parameters.
    ///
    /// - `param_count`: number of parameters in the LoRA adapter (A + B flattened)
    /// - `lambda`: weight for manifold loss (default: 0.01)
    /// - `ema_decay`: EMA decay for running mean (default: 0.999)
    pub fn new(param_count: usize, lambda: f32, ema_decay: f32) -> Self {
        let radius = 0.1 * (param_count as f32).sqrt();
        Self {
            lambda,
            radius,
            ema_decay,
            weight_mean: vec![0.0; param_count],
        }
    }

    /// Create with default parameters.
    pub fn default_for(param_count: usize) -> Self {
        Self::new(param_count, 0.01, 0.999)
    }

    /// Compute the sphere constraint loss for the given weights.
    ///
    /// L = (||W - W_mean||² - D_r²)²
    pub fn sphere_loss(&self, weights: &[f32]) -> f32 {
        debug_assert_eq!(weights.len(), self.weight_mean.len());
        let d = self.sphere_distance(weights);
        d * d
    }

    /// Compute sphere distance: ||W - W_mean||² - D_r²
    pub fn sphere_distance(&self, weights: &[f32]) -> f32 {
        let dist_sq: f32 = weights
            .iter()
            .zip(self.weight_mean.iter())
            .map(|(w, m)| (w - m).powi(2))
            .sum();
        dist_sq - self.radius * self.radius
    }

    /// Update the running mean (W_mean) via EMA.
    ///
    /// Call this after each training batch with the updated weights.
    /// W_mean = (1 - decay) * W_mean + decay * weights
    pub fn update_mean(&mut self, weights: &[f32]) {
        debug_assert_eq!(weights.len(), self.weight_mean.len());
        for (mean, w) in self.weight_mean.iter_mut().zip(weights.iter()) {
            *mean = (1.0 - self.ema_decay) * *mean + self.ema_decay * w;
        }
    }

    /// Compute the weighted manifold loss for the combined training objective.
    ///
    /// Returns: λ * sphere_loss(weights)
    pub fn weighted_loss(&self, weights: &[f32]) -> f32 {
        self.lambda * self.sphere_loss(weights)
    }

    /// Compute combined loss: base_loss + λ * manifold_loss.
    ///
    /// This is the standard way to add manifold loss to any training loop.
    pub fn combined_loss(&self, base_loss: f32, weights: &[f32]) -> f32 {
        base_loss + self.weighted_loss(weights)
    }

    /// Get the current manifold radius D_r.
    #[inline]
    pub fn radius(&self) -> f32 {
        self.radius
    }

    /// Set the manifold radius D_r. Useful for curriculum: start large, anneal.
    #[inline]
    pub fn set_radius(&mut self, radius: f32) {
        self.radius = radius;
    }

    /// Get the current weight mean.
    pub fn weight_mean(&self) -> &[f32] {
        &self.weight_mean
    }

    /// Get the number of parameters.
    #[inline]
    pub fn param_count(&self) -> usize {
        self.weight_mean.len()
    }
}

impl ManifoldRosettaMetric {
    /// Create with default parameters.
    pub fn new(sigma: f32) -> Self {
        Self {
            sigma,
            shared_weight: 1.0,
            specific_weight: 0.5,
        }
    }

    /// Default metric with σ = 1.0.
    pub fn default_metric() -> Self {
        Self::new(1.0)
    }

    /// Compute Gaussian RKHS distance between two adapter weight vectors.
    ///
    /// d(A, B) = ||φ(A) - φ(B)||²_H = K(A,A) + K(B,B) - 2·K(A,B)
    ///
    /// Where K is the Gaussian kernel. Returns 0 for identical, positive for different.
    pub fn rkhs_distance(&self, a: &[f32], b: &[f32]) -> f32 {
        let k_aa = 1.0; // K(a,a) = exp(0) = 1 for Gaussian kernel
        let k_bb = 1.0; // K(b,b) = exp(0) = 1
        let dist_sq: f32 = a.iter().zip(b.iter()).map(|(x, y)| (x - y).powi(2)).sum();
        let k_ab = (-dist_sq / (2.0 * self.sigma * self.sigma)).exp();
        k_aa + k_bb - 2.0 * k_ab
    }

    /// Compute manifold alignment loss for a batch of neuron pairs.
    ///
    /// For shared neurons: minimize RKHS distance.
    /// For game-specific neurons: maximize RKHS distance (negative weight).
    ///
    /// `shared_pairs`: (neuron_A, neuron_B) pairs that should be aligned.
    /// `specific_pairs`: (neuron_A, neuron_B) pairs that should be differentiated.
    pub fn alignment_loss(
        &self,
        shared_pairs: &[(Vec<f32>, Vec<f32>)],
        specific_pairs: &[(Vec<f32>, Vec<f32>)],
    ) -> f32 {
        // Shared: minimize distance
        let shared_loss: f32 = shared_pairs
            .iter()
            .map(|(a, b)| self.rkhs_distance(a, b))
            .sum::<f32>()
            * self.shared_weight;

        // Specific: maximize distance (penalize being too close)
        let specific_loss: f32 = specific_pairs
            .iter()
            .map(|(a, b)| {
                let d = self.rkhs_distance(a, b);
                // Penalize if too close (distance < threshold)
                let threshold = 0.1; // Minimum desired separation
                (threshold - d).max(0.0)
            })
            .sum::<f32>()
            * self.specific_weight;

        shared_loss + specific_loss
    }

    /// Compute kernel similarity between two weight vectors.
    ///
    /// K(a, b) = exp(-||a - b||² / (2σ²))
    pub fn kernel_similarity(&self, a: &[f32], b: &[f32]) -> f32 {
        let dist_sq: f32 = a.iter().zip(b.iter()).map(|(x, y)| (x - y).powi(2)).sum();
        (-dist_sq / (2.0 * self.sigma * self.sigma)).exp()
    }

    /// Compute raw MSE between two vectors (baseline for comparison).
    pub fn mse_distance(&self, a: &[f32], b: &[f32]) -> f32 {
        let n = a.len().max(1);
        a.iter()
            .zip(b.iter())
            .map(|(x, y)| (x - y).powi(2))
            .sum::<f32>()
            / n as f32
    }

    /// Get σ value.
    #[inline]
    pub fn sigma(&self) -> f32 {
        self.sigma
    }

    /// Set σ value (kernel bandwidth).
    #[inline]
    pub fn set_sigma(&mut self, sigma: f32) {
        self.sigma = sigma;
    }
}

impl MetaBlock {
    /// Create a new MetaBlock with small random-ish initialization.
    ///
    /// `flip` controls the alternating permutation — even blocks use identity,
    /// odd blocks flip the two halves before coupling.
    pub fn new(dim: usize, coupling_hidden: usize, flip: bool) -> Self {
        let half_dim = dim / 2;

        // Initialize with small values for stable training start.
        // Use a simple deterministic pattern: w[i] = INIT_SCALE * sin(index).
        let s_weight = (0..coupling_hidden * half_dim)
            .map(|i| INIT_SCALE * ((i as f32 * 0.1f32).sin()))
            .collect();
        let s_bias = vec![0.0f32; coupling_hidden];
        let t_weight = (0..coupling_hidden * half_dim)
            .map(|i| INIT_SCALE * ((i as f32 * 0.1f32 + 1.0).sin()))
            .collect();
        let t_bias = vec![0.0f32; half_dim];

        Self {
            s_weight,
            s_bias,
            t_weight,
            t_bias,
            flip,
            dim,
            coupling_hidden,
        }
    }

    /// Forward pass: (e + noise) → u
    ///
    /// Returns `(output, log_det)` where output is the transformed vector
    /// and log_det is the log-absolute-determinant of the Jacobian.
    pub fn forward(&self, input: &[f32]) -> (Vec<f32>, f32) {
        match input.len() {
            0 => return (Vec::new(), 0.0),
            n if n != self.dim => return (input.to_vec(), 0.0),
            _ => {}
        }

        let half = self.dim / 2;

        // Split into two halves (with optional flip)
        let (x1, x2) = if self.flip {
                // Flip: first half becomes second and vice versa
                (&input[half..], &input[..half])
            } else { (&input[..half], &input[half..]) };

        // Compute scale and translation from x1
        let s = self.compute_s(x1);
        let t = self.compute_t(x1);

        // Affine coupling: y1 = x1, y2 = x2 * exp(s) + t
        let mut output = Vec::with_capacity(self.dim);
        output.extend_from_slice(x1);

        let mut log_det: f32 = 0.0;
        for i in 0..half {
            let exp_s = s[i].exp();
            let y2 = x2[i] * exp_s + t[i];
            output.push(y2);
            log_det += s[i]; // log|det J| = sum of s values
        }

        (output, log_det)
    }

    /// Inverse pass: u → e (needed for RL log-prob computation).
    ///
    /// Reconstructs the original input from the transformed output.
    pub fn inverse(&self, output: &[f32]) -> Vec<f32> {
        match output.len() {
            0 => return Vec::new(),
            n if n != self.dim => return output.to_vec(),
            _ => {}
        }

        let half = self.dim / 2;

        // Forward always writes: output = [x1, transformed_x2]
        // So y1 = output[0..half] is always x1, y2 = output[half..] is always the transformed part.
        let x1 = &output[..half];
        let y2 = &output[half..];

        // Recover s, t from x1
        let s = self.compute_s(x1);
        let t = self.compute_t(x1);

        // x2 = (y2 - t) / exp(s)
        let mut x2 = Vec::with_capacity(half);
        for i in 0..half {
            let x2_val = (y2[i] - t[i]) * (-s[i]).exp();
            x2.push(x2_val);
        }

        // Unflip: if forward flipped (x1=input[half..], x2=input[0..half]),
        // then the original input = [x2, x1]. Otherwise [x1, x2].
        let mut result = Vec::with_capacity(self.dim);
        if self.flip {
                result.extend_from_slice(&x2);
                result.extend_from_slice(x1);
            } else {
                result.extend_from_slice(x1);
                result.extend_from_slice(&x2);
            }

        result
    }

    /// Compute scale vector s from the first half of the input.
    fn compute_s(&self, x1: &[f32]) -> Vec<f32> {
        let half = self.dim / 2;
        let mut hidden = vec![0.0f32; self.coupling_hidden];
        linear_forward(
            x1,
            &self.s_weight,
            &self.s_bias,
            half,
            self.coupling_hidden,
            &mut hidden,
        );

        // Tanh activation (bounded scale for stability)
        hidden.iter_mut().for_each(|h| *h = h.tanh());

        // Project back to half_dim
        let mut s = vec![0.0f32; half];
        linear_forward(
            &hidden,
            &self.t_weight,
            &self.t_bias,
            self.coupling_hidden,
            half,
            &mut s,
        );

        // Scale down with tanh to prevent exp blow-up
        s.iter_mut().for_each(|v| *v = v.tanh() * 2.0f32);
        s
    }

    /// Compute translation vector t from the first half of the input.
    fn compute_t(&self, x1: &[f32]) -> Vec<f32> {
        let half = self.dim / 2;
        let mut hidden = vec![0.0f32; self.coupling_hidden];
        linear_forward(
            x1,
            &self.s_weight,
            &self.s_bias,
            half,
            self.coupling_hidden,
            &mut hidden,
        );

        // GELU activation for translation network
        hidden.iter_mut().for_each(|h| *h = gelu(*h));

        let mut t = vec![0.0f32; half];
        linear_forward(
            &hidden,
            &self.t_weight,
            &self.t_bias,
            self.coupling_hidden,
            half,
            &mut t,
        );
        t
    }
}

impl MetaBlockCascade {
    /// Create a 5-block cascade with alternating flip pattern.
    ///
    /// Flip pattern: [false, true, false, true, false]
    pub fn new(dim: usize, coupling_hidden: usize) -> Self {
        Self {
            blocks: (0..5)
                .map(|i| MetaBlock::new(dim, coupling_hidden, i % 2 == 1))
                .collect(),
        }
    }

    /// Forward through all 5 blocks. Returns (output, total_log_det).
    pub fn forward(&self, input: &[f32]) -> (Vec<f32>, f32) {
        let mut current = input.to_vec();
        let mut total_log_det = 0.0f32;

        for block in &self.blocks {
            let (output, log_det) = block.forward(&current);
            current = output;
            total_log_det += log_det;
        }

        (current, total_log_det)
    }

    /// Inverse through all 5 blocks (reversed order).
    pub fn inverse(&self, output: &[f32]) -> Vec<f32> {
        let mut current = output.to_vec();

        for block in self.blocks.iter().rev() {
            current = block.inverse(&current);
        }

        current
    }
}

impl MetaBlock {
    /// Gradient w.r.t. this block's input.
    ///
    /// `g_output` is `dL/d(output)` (length `dim`) and `g_log_det` is
    /// `dL/d(log_det)` — a scalar, because `log_det = Σᵢ sᵢ` so every `sᵢ`
    /// receives the same upstream derivative.
    ///
    /// Returns `dL/d(input)`. Mirrors [`MetaBlock::forward`]'s degenerate
    /// cases: a wrong-length input is passed through untouched there, so its
    /// gradient is the identity here.
    pub fn backward(&self, input: &[f32], g_output: &[f32], g_log_det: f32) -> Vec<f32> {
        match input.len() {
            0 => return Vec::new(),
            n if n != self.dim => return g_output.to_vec(),
            _ => {}
        }
        let half = self.dim / 2;

        // Re-derive the forward's intermediates (cheap; avoids a saved-state
        // struct and keeps this in lockstep with `forward` by construction).
        let (x1, x2) = if self.flip { (&input[half..], &input[..half]) } else { (&input[..half], &input[half..]) };

        // Layer-1 pre-activation is SHARED by both nets (they reuse
        // s_weight/s_bias), so it is computed once.
        let mut h_pre = vec![0.0f32; self.coupling_hidden];
        linear_forward(x1, &self.s_weight, &self.s_bias, half, self.coupling_hidden, &mut h_pre);
        let h_tanh: Vec<f32> = h_pre.iter().map(|v| v.tanh()).collect();

        let mut s_pre = vec![0.0f32; half];
        linear_forward(&h_tanh, &self.t_weight, &self.t_bias, self.coupling_hidden, half, &mut s_pre);
        let s: Vec<f32> = s_pre.iter().map(|v| v.tanh() * 2.0).collect();

        // ── output = [x1, y2],  y2 = x2·exp(s) + t,  log_det = Σ s ──
        let g_y1 = &g_output[..half];
        let g_y2 = &g_output[half..];

        let mut g_x1 = g_y1.to_vec();
        let mut g_x2 = vec![0.0f32; half];
        let mut g_s = vec![0.0f32; half];
        let mut g_t = vec![0.0f32; half];

        for i in 0..half {
            let exp_s = s[i].exp();
            g_x2[i] = g_y2[i] * exp_s;
            // From y2, plus the log_det path (log_det = Σ s ⇒ ds/dlog_det = 1).
            g_s[i] = g_y2[i] * x2[i] * exp_s + g_log_det;
            g_t[i] = g_y2[i];
        }

        // ── back through the scale net: s = tanh(W_t·tanh(W_s·x1+b_s)+b_t)·2 ──
        let mut g_h_tanh = vec![0.0f32; self.coupling_hidden];
        {
            // s = 2·tanh(s_pre) ⇒ ds/ds_pre = 2·(1 − tanh²(s_pre)) = 2 − s²/2
            let g_s_pre: Vec<f32> = (0..half)
                .map(|i| {
                    let th = s[i] * 0.5; // tanh(s_pre)
                    g_s[i] * 2.0 * (1.0 - th * th)
                })
                .collect();
            linear_backward_input(
                &g_s_pre, &self.t_weight, self.coupling_hidden, half, &mut g_h_tanh,
            );
        }

        // ── back through the translation net: t = W_t·gelu(W_s·x1+b_s)+b_t ──
        let mut g_h_gelu = vec![0.0f32; self.coupling_hidden];
        linear_backward_input(&g_t, &self.t_weight, self.coupling_hidden, half, &mut g_h_gelu);

        // Both nets share layer 1, so their contributions sum at h_pre.
        let mut g_h_pre = vec![0.0f32; self.coupling_hidden];
        for k in 0..self.coupling_hidden {
            let tanh_grad = 1.0 - h_tanh[k] * h_tanh[k];
            g_h_pre[k] = g_h_tanh[k] * tanh_grad + g_h_gelu[k] * gelu_grad(h_pre[k]);
        }
        linear_backward_input(&g_h_pre, &self.s_weight, half, self.coupling_hidden, &mut g_x1);

        // ── undo the split/flip ──
        let mut g_input = vec![0.0f32; self.dim];
        if self.flip {
                g_input[half..].copy_from_slice(&g_x1);
                g_input[..half].copy_from_slice(&g_x2);
            } else {
                g_input[..half].copy_from_slice(&g_x1);
                g_input[half..].copy_from_slice(&g_x2);
            }
        g_input
    }
}

impl MetaBlockCascade {
    /// Gradient of a loss w.r.t. the cascade's input.
    ///
    /// `g_output` is `dL/d(u)` and `g_log_det` is `dL/d(total_log_det)`. Since
    /// the total is a plain sum over blocks, every block sees the same
    /// `g_log_det`.
    ///
    /// ## Scope — read before trusting an NF-CoT result
    ///
    /// This differentiates w.r.t. the **input only**, not w.r.t. the flow's own
    /// weights. That is exactly what an [`AuxHiddenLoss`] needs (it returns
    /// `dL/d(hidden)`), and it is enough to make the flow's NLL a training
    /// signal for the LoRA. It is **not** enough to make NF-CoT the method in
    /// Research 089: there the flow is trained jointly, and here it stays at
    /// its deterministic `MetaBlock::new` initialization. Pushing hidden states
    /// toward Gaussianity under a *fixed, untrained* flow is a regularizer, not
    /// NF-CoT — see Plan 330 T5.3 for what still has to land.
    ///
    /// [`AuxHiddenLoss`]: crate::train_shared::AuxHiddenLoss
    pub fn backward(&self, input: &[f32], g_output: &[f32], g_log_det: f32) -> Vec<f32> {
        // Replay the forward to recover each block's input, then walk back.
        let mut inputs = Vec::with_capacity(self.blocks.len());
        let mut current = input.to_vec();
        for block in &self.blocks {
            inputs.push(current.clone());
            let (out, _) = block.forward(&current);
            current = out;
        }

        let mut g = g_output.to_vec();
        for (block, blk_in) in self.blocks.iter().zip(inputs.iter()).rev() {
            g = block.backward(blk_in, &g, g_log_det);
        }
        g
    }
}

