impl ClippyLintOracle {
    /// Scratch root defaults UNDER THE REPO'S `target/` (compile-time
    /// manifest walk) — NOT `std::env::temp_dir()`. The macOS temp cleaner
    /// deletes `/tmp` scratch crates mid-run on this box, which surfaced as
    /// phantom `skipped_broken` verdicts in the determinism gate (the
    /// riir-clippy “/tmp is UNRELIABLE here” lesson, re-hit). Override with
    /// [`Self::with_work_root`] when the repo is not on disk.
    pub fn new() -> Self {
        let repo_target = Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("..")
            .join("..")
            .join("target")
            .join("miss_shape_oracle");
        Self {
            cargo_bin: "cargo".to_string(),
            work_root: repo_target,
        }
    }

    /// Override the scratch-crate root (tests pin it under target/ so a
    /// parallel run never collides with a sibling's temp cleaner).
    pub fn with_work_root(mut self, root: impl Into<PathBuf>) -> Self {
        self.work_root = root.into();
        self
    }

    /// Cheap availability probe — oracle-dependent paths skip loudly on
    /// `false` rather than silently emitting nothing.
    pub fn is_available(&self) -> bool {
        Command::new(&self.cargo_bin)
            .arg("--version")
            .output()
            .is_ok_and(|o| o.status.success())
    }

    /// Report every clippy lint that fires on `code`. When `target` is
    /// given, `-W clippy::<target>` is passed EXPLICITLY in addition to the
    /// three groups — several Bench-037 lints are allow-by-default in
    /// current clippy (`or_fun_call` restriction, `box_collection`) and
    /// never fire under `-W clippy::all` alone. This mirrors the reward
    /// path, which always scans `-W clippy::<lint>` per named lint.
    pub fn lints_for(&self, code: &str, target: Option<&str>) -> OracleVerdict {
        let crate_dir = self.prepare_crate(code);
        let manifest = crate_dir.join("Cargo.toml");
        let mut cmd = Command::new(&self.cargo_bin);
        cmd.arg("clippy")
            .arg("--manifest-path")
            .arg(&manifest)
            .arg("--message-format=json")
            .arg("--")
            .arg("-W")
            .arg("clippy::all")
            .arg("-W")
            .arg("clippy::pedantic")
            .arg("-W")
            .arg("clippy::nursery");
        if let Some(lint) = target {
            cmd.arg("-W").arg(format!("clippy::{lint}"));
        }
        let output = match cmd.output() {
            Ok(o) => o,
            Err(e) => {
                return OracleVerdict {
                    ran: false,
                    compiles: false,
                    lints: BTreeSet::new(),
                    error: Some(format!("spawn failed: {e}")),
                };
            }
        };
        // A nonzero exit WITH JSON diagnostics is a genuine compile error.
        // A nonzero exit with EMPTY stdout is infrastructural (cargo lock
        // contention under parallel probes, manifest-level errors): retry
        // once, then surface as ran=false — under parallel `cargo test` two
        // oracle-driven tests race on cargo's locks and the loser sees
        // exactly this signature (found live; single-threaded runs pass).
        let output = if !output.status.success() && output.stdout.is_empty() {
            // Contended cargo lock: back off briefly, then retry once.
            std::thread::sleep(std::time::Duration::from_millis(120));
            match cmd.output() {
                Ok(retry) => retry,
                Err(e) => {
                    return OracleVerdict {
                        ran: false,
                        compiles: false,
                        lints: BTreeSet::new(),
                        error: Some(format!("retry spawn failed: {e}")),
                    };
                }
            }
        } else {
            output
        };
        if !output.status.success() && output.stdout.is_empty() {
            let stderr = String::from_utf8_lossy(&output.stderr);
            return OracleVerdict {
                ran: false,
                compiles: false,
                lints: BTreeSet::new(),
                error: Some(format!(
                    "clippy exited {:?} with no diagnostics (stderr tail): {}",
                    output.status.code(),
                    stderr.lines().rev().take(3).collect::<Vec<_>>().join(" | ")
                )),
            };
        }
        let stdout = String::from_utf8_lossy(&output.stdout);
        parse_verdict(&stdout)
    }

    /// Write the module into a BLAKE3-keyed scratch crate (keyed so
    /// identical modules reuse the crate dir and cargo's cache). The
    /// manifest carries an EMPTY `[workspace]` table: without it a crate
    /// rooted under the repo's `target/` is auto-adopted by the riir-train
    /// workspace manifest and cargo hard-errors ("believes it's in a
    /// workspace when it's not") — found live on the first target/-rooted
    /// oracle run.
    fn prepare_crate(&self, code: &str) -> PathBuf {
        // Key covers BOTH the module and the manifest template: the crates
        // must be reused only when the whole probe (content + how it's
        // driven) is identical — a manifest change with a content-only key
        // reuses stale dirs whose build state disagrees with the new flags
        // (found live: pre-[workspace] crates kept hard-erroring after the
        // template gained the empty workspace table).
        const MANIFEST: &str = "[package]\nname = \"miss_shape_probe\"\nversion = \"0.0.0\"\nedition = \"2021\"\n\
             [lib]\npath = \"src/lib.rs\"\n\n[workspace]\n";
        let mut hasher = blake3::Hasher::new();
        hasher.update(MANIFEST.as_bytes());
        hasher.update(code.as_bytes());
        let key = hasher.finalize().to_hex();
        let dir = self.work_root.join(format!("ms_{}", &key[..16]));
        let src = dir.join("src");
        let _ = std::fs::create_dir_all(&src);
        let _ = std::fs::write(dir.join("Cargo.toml"), MANIFEST);
        let _ = std::fs::write(src.join("lib.rs"), code);
        dir
    }
}

impl MsaWarmupPhase {
    /// Create warmup phase with given number of steps.
    pub fn new(warmup_steps: usize) -> Self {
        match warmup_steps {
            0 => MsaWarmupPhase::Sparse,
            n => MsaWarmupPhase::Warmup { remaining: n },
        }
    }

    /// Advance one step. Returns the phase after stepping.
    pub fn step(&mut self) -> MsaWarmupPhase {
        match self {
            MsaWarmupPhase::Warmup { remaining } => {
                *remaining = remaining.saturating_sub(1);
                match remaining {
                    0 => {
                        *self = MsaWarmupPhase::Sparse;
                        MsaWarmupPhase::Sparse
                    }
                    _ => MsaWarmupPhase::Warmup {
                        remaining: *remaining,
                    },
                }
            }
            MsaWarmupPhase::Sparse => MsaWarmupPhase::Sparse,
        }
    }

    /// Whether currently in warmup phase.
    pub fn is_warmup(&self) -> bool {
        matches!(self, MsaWarmupPhase::Warmup { .. })
    }
}

impl EmotionKBudget {
    /// Compute adaptive k from emotion vector.
    ///
    /// `emotion_vector`: `[valence, arousal, desperation, calm, fear]` (5 scalars).
    /// Returns k in `[k_min, k_max]` range.
    ///
    /// Per Latent vs Raw Space rules: emotion_vector comes from bridge function
    /// (raw → latent projection → 5 scalars). These are the synced scalar outputs,
    /// not the 64-dim HLA vector.
    pub fn compute_k(&self, emotion_vector: &[f32; 5]) -> usize {
        let logits: f32 = self
            .weights
            .iter()
            .zip(emotion_vector.iter())
            .map(|(w, e)| w * e)
            .sum::<f32>()
            + self.bias;

        let frac = sigmoid(logits);
        let k = self.k_min as f32 + (self.k_max - self.k_min) as f32 * frac;
        k.round() as usize
    }

    /// Recommend execution path based on k value (optimization.md: CPU/GPU auto-route).
    ///
    /// Returns `ExecutionHint` indicating optimal compute path for the given k.
    pub fn execution_hint(k: usize) -> ExecutionHint {
        match k {
            0..=8 => ExecutionHint::Simd,
            9..=16 => ExecutionHint::CpuParallel,
            _ => ExecutionHint::GpuBatch,
        }
    }
}

use crate::breakeven::sigmoid;

// ---------------------------------------------------------------------------
// T9: TrainingTier enum
// ---------------------------------------------------------------------------

/// Training fidelity tiers, ordered from most expensive (0) to cheapest (4).
///
/// Higher tiers require less training compute but produce lower quality output.
/// The tier recommendation is sigmoid-gated — never softmax.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
#[repr(u8)]
pub enum TrainingTier {
    /// Full LoRA: rank 64, all layers. Highest quality, highest training cost.
    FullLoRA = 0,
    /// LoRA Compact: rank 16, attention layers only.
    LoRACompact = 1,
    /// IA³: 3 learned vectors per layer (key, value, feedforward).
    IA3 = 2,
    /// Prompt Tuning: virtual token prefix only.
    PromptTuning = 3,
    /// Frozen + Chain-of-Thought: no training, rely on base model + prompting.
    FrozenCoT = 4,
}

impl MultiFidelityStack {
    /// Recommend the optimal training tier.
    ///
    /// For each tier, computes total cost = training_cost + N × inference_cost / quality_ratio.
    /// Picks the tier with lowest total cost that satisfies the quality requirement.
    /// Quality gating uses sigmoid boundary: tier is viable iff sigmoid(quality_ratio − quality_requirement) >= 0.5.
    ///
    /// Time complexity: O(tiers) — single pass, no allocation.
    #[must_use]
    pub fn recommend(
        config: &MultiFidelityConfig,
        expected_queries: u64,
        quality_requirement: f64,
    ) -> TrainingTier {
        let n = expected_queries as f64;
        let mut best_tier = TrainingTier::FrozenCoT;
        let mut best_cost = f64::INFINITY;

        for tier_cfg in &config.tiers {
            let quality_gate = sigmoid(tier_cfg.quality_ratio - quality_requirement);
            if quality_gate < 0.5 {
                continue;
            }

            let total_cost = tier_cfg.training_cost_us as f64
                + n * tier_cfg.inference_cost_us as f64 / tier_cfg.quality_ratio;

            if total_cost < best_cost {
                best_cost = total_cost;
                best_tier = tier_cfg.tier;
            }
        }

        best_tier
    }

    /// Compute total cost for a given tier at a given query count.
    #[inline]
    #[must_use]
    pub fn total_cost(tier: &TierConfig, expected_queries: u64) -> f64 {
        let n = expected_queries as f64;
        tier.training_cost_us as f64 + n * tier.inference_cost_us as f64 / tier.quality_ratio
    }

    /// Compute breakeven query count between two tiers.
    ///
    /// Returns the N where tier_b becomes cheaper than tier_a.
    /// Returns `f64::INFINITY` if tier_b never catches up.
    #[inline]
    #[must_use]
    pub fn breakeven_between(tier_a: &TierConfig, tier_b: &TierConfig) -> f64 {
        let slope_a = tier_a.inference_cost_us as f64 / tier_a.quality_ratio;
        let slope_b = tier_b.inference_cost_us as f64 / tier_b.quality_ratio;
        let denominator = slope_a - slope_b;
        if denominator <= 0.0 {
            return f64::INFINITY;
        }
        let numerator = tier_b.training_cost_us as f64 - tier_a.training_cost_us as f64;
        if numerator <= 0.0 {
            return 0.0;
        }
        numerator / denominator
    }
}

impl NeuroSymbolicFusion {
    /// Create a new fusion resolver with the given strategy.
    pub fn new(strategy: FusionStrategy) -> Self {
        Self {
            strategy,
            min_precision_trust: 0.01,
            default_rule_precision: 1.0,
        }
    }

    /// Set minimum precision threshold for trusting a source.
    pub fn with_min_precision_trust(mut self, threshold: f32) -> Self {
        self.min_precision_trust = threshold;
        self
    }

    /// Set default rule precision when no BAKE posterior is available.
    pub fn with_default_rule_precision(mut self, precision: f32) -> Self {
        self.default_rule_precision = precision;
        self
    }

    /// Sigmoid activation: 1 / (1 + exp(-x)). Delegates to `crate::math::sigmoid_f32`.
    #[inline]
    fn sigmoid(x: f32) -> f32 {
        crate::math::sigmoid_f32(x)
    }

    /// Fuse neural prediction with rule output using precision as trust signal.
    ///
    /// - `neural_pred`: output from neural network (raw, unbounded).
    /// - `rule_output`: output from symbolic rule (FOL), raw.
    /// - `neural_precision`: λ from BAKE posterior (1/σ²).
    /// - `has_rule`: whether a symbolic rule is available for this prediction.
    pub fn fuse(
        &self,
        neural_pred: f32,
        rule_output: f32,
        neural_precision: f32,
        has_rule: bool,
    ) -> FusionResult {
        match self.strategy {
            FusionStrategy::PrecisionWeighted => {
                self.fuse_precision_weighted(neural_pred, rule_output, neural_precision, has_rule)
            }
            FusionStrategy::WinnerTakeAll => {
                self.fuse_winner_take_all(neural_pred, rule_output, neural_precision, has_rule)
            }
            FusionStrategy::RulePriority => {
                self.fuse_rule_priority(neural_pred, rule_output, neural_precision, has_rule)
            }
        }
    }

    fn fuse_precision_weighted(
        &self,
        neural_pred: f32,
        rule_output: f32,
        neural_precision: f32,
        has_rule: bool,
    ) -> FusionResult {
        let lambda_neural = neural_precision.max(self.min_precision_trust);

        if !has_rule {
            return FusionResult {
                output: Self::sigmoid(neural_pred).clamp(0.0, 1.0),
                effective_precision: lambda_neural,
                source_used: FusionSource::Neural,
            };
        }

        let lambda_rule = self.default_rule_precision;
        let total_precision = lambda_neural + lambda_rule;

        // Precision-weighted average, clamped to [0, 1]
        let weighted = (lambda_neural * neural_pred + lambda_rule * rule_output) / total_precision;
        let output = Self::sigmoid(weighted).clamp(0.0, 1.0);

        FusionResult {
            output,
            effective_precision: total_precision,
            source_used: FusionSource::Fused,
        }
    }

    fn fuse_winner_take_all(
        &self,
        neural_pred: f32,
        rule_output: f32,
        neural_precision: f32,
        has_rule: bool,
    ) -> FusionResult {
        let lambda_neural = neural_precision.max(self.min_precision_trust);

        if !has_rule {
            return FusionResult {
                output: Self::sigmoid(neural_pred).clamp(0.0, 1.0),
                effective_precision: lambda_neural,
                source_used: FusionSource::Neural,
            };
        }

        let lambda_rule = self.default_rule_precision;

        if lambda_neural >= lambda_rule {
            FusionResult {
                output: Self::sigmoid(neural_pred).clamp(0.0, 1.0),
                effective_precision: lambda_neural,
                source_used: FusionSource::Neural,
            }
        } else {
            FusionResult {
                output: Self::sigmoid(rule_output).clamp(0.0, 1.0),
                effective_precision: lambda_rule,
                source_used: FusionSource::Rule,
            }
        }
    }

    fn fuse_rule_priority(
        &self,
        neural_pred: f32,
        rule_output: f32,
        neural_precision: f32,
        has_rule: bool,
    ) -> FusionResult {
        let lambda_neural = neural_precision.max(self.min_precision_trust);

        if has_rule && self.default_rule_precision >= self.min_precision_trust {
            return FusionResult {
                output: Self::sigmoid(rule_output).clamp(0.0, 1.0),
                effective_precision: self.default_rule_precision,
                source_used: FusionSource::Rule,
            };
        }

        FusionResult {
            output: Self::sigmoid(neural_pred).clamp(0.0, 1.0),
            effective_precision: lambda_neural,
            source_used: FusionSource::Neural,
        }
    }

    /// Batch fusion for multiple predictions with their precisions.
    ///
    /// Each tuple is `(neural_pred, rule_output, neural_precision)`.
    pub fn fuse_batch(&self, predictions: &[(f32, f32, f32)]) -> Vec<FusionResult> {
        predictions
            .iter()
            .map(|&(neural, rule, precision)| self.fuse(neural, rule, precision, true))
            .collect()
    }

    /// Detect conflicts where neural and rule disagree beyond precision-weighted tolerance.
    ///
    /// A conflict occurs when `|neural_pred - rule_output| > threshold / sqrt(λ_neural)`.
    /// Higher precision → tighter tolerance (more confident = less disagreement allowed).
    ///
    /// Returns indices of conflicting predictions.
    pub fn detect_conflicts(&self, predictions: &[(f32, f32, f32)], threshold: f32) -> Vec<usize> {
        predictions
            .iter()
            .enumerate()
            .filter_map(|(i, &(neural, rule, precision))| {
                let tolerance = threshold / precision.max(self.min_precision_trust).sqrt();
                let disagreement = (neural - rule).abs();
                if disagreement > tolerance {
                    Some(i)
                } else {
                    None
                }
            })
            .collect()
    }
}

