impl NfCurriculumScheduler {
    /// Create a new scheduler from the curriculum config.
    pub fn new(config: &NfCurriculumConfig) -> Self {
        Self {
            config: config.clone(),
            current_stage: TrainingStage::WarmUp,
            current_step: 0,
            total_steps_stage1: config.stage1.total_steps(),
            total_steps_stage2: config.stage2.total_steps(),
        }
    }

    /// Current training stage.
    #[inline]
    pub fn current_stage(&self) -> TrainingStage {
        self.current_stage
    }

    /// Whether the backbone should be frozen at the current stage.
    pub fn should_freeze_backbone(&self) -> bool {
        match self.current_stage {
            TrainingStage::WarmUp => true,
            TrainingStage::JointTraining => false,
        }
    }

    /// Current learning rate with linear warmup schedule.
    ///
    /// lr = base_lr * min(1, step / warmup_steps)
    pub fn current_learning_rate(&self) -> f32 {
        let stage_config = match self.current_stage {
            TrainingStage::WarmUp => &self.config.stage1,
            TrainingStage::JointTraining => &self.config.stage2,
        };

        match stage_config.warmup_steps {
            0 => stage_config.learning_rate,
            ws => {
                let warmup_factor = (self.current_step as f32) / (ws as f32);
                stage_config.learning_rate * warmup_factor.min(1.0f32)
            }
        }
    }

    /// Advance one training step. Auto-transitions from Stage 1 → Stage 2.
    pub fn advance(&mut self) {
        self.current_step += 1;

        match self.current_stage {
            TrainingStage::WarmUp => {
                if self.current_step >= self.total_steps_stage1 {
                    self.current_stage = TrainingStage::JointTraining;
                    self.current_step = 0;
                }
            }
            TrainingStage::JointTraining => {
                // Stay in Stage 2 until complete
            }
        }
    }

    /// Whether the entire curriculum (both stages) is complete.
    pub fn is_complete(&self) -> bool {
        match self.current_stage {
            TrainingStage::WarmUp => false,
            TrainingStage::JointTraining => self.current_step >= self.total_steps_stage2,
        }
    }

    /// Steps remaining in the current stage.
    pub fn steps_remaining(&self) -> usize {
        let total = match self.current_stage {
            TrainingStage::WarmUp => self.total_steps_stage1,
            TrainingStage::JointTraining => self.total_steps_stage2,
        };
        total.saturating_sub(self.current_step)
    }

    /// Total steps across both stages.
    pub fn total_steps(&self) -> usize {
        self.total_steps_stage1 + self.total_steps_stage2
    }
}

