impl NfOutputHead {
    /// Create a new NF output head with zero-initialized weights.
    ///
    /// Zero-init on the final linear layers ensures the head starts as
    /// exact identity: with zero w_sigma/w_mu the raw logits are the bias
    /// constants, giving σ = squareplus(0.75) = 1.0 exactly, μ = 0.
    /// The caller may add a small bias to shift σ if desired.
    pub fn new(hidden_dim: usize, mlp_hidden: usize) -> Self {
        Self {
            gamma: vec![1.0f32; hidden_dim],
            beta: vec![0.0f32; hidden_dim],
            w1: vec![0.0f32; hidden_dim * mlp_hidden],
            b1: vec![0.0f32; mlp_hidden],
            w_sigma: vec![0.0f32; mlp_hidden],
            w_mu: vec![0.0f32; mlp_hidden],
            hidden_dim,
            mlp_hidden,
        }
    }

    /// Forward pass: LayerNorm → Linear → GELU → Linear → (squareplus(σ), tanh(μ)/4)
    ///
    /// Returns `(σ, μ)` where σ > 0 and μ ∈ [-4, 4].
    pub fn forward(&self, input: &[f32]) -> NfOutput {
        match input.len() {
            0 => {
                return NfOutput {
                    sigma: 1.0,
                    mu: 0.0,
                };
            }
            n if n != self.hidden_dim => {
                return NfOutput {
                    sigma: 1.0,
                    mu: 0.0,
                };
            }
            _ => {}
        }

        // Step 1: LayerNorm
        let normed = layer_norm(input, &self.gamma, &self.beta);

        // Step 2: Linear [hidden_dim] → [mlp_hidden]
        let mut hidden = vec![0.0f32; self.mlp_hidden];
        linear_forward(
            &normed,
            &self.w1,
            &self.b1,
            self.hidden_dim,
            self.mlp_hidden,
            &mut hidden,
        );

        // Step 3: GELU activation
        for h in hidden.iter_mut() {
            *h = gelu(*h);
        }

        // Step 4: Linear → scalar logits for σ and μ
        let sigma_param = dot_product(&hidden, &self.w_sigma) + SIGMA_BIAS; // squareplus⁻¹(1) so σ₀ = 1
        let mu_logit = dot_product(&hidden, &self.w_mu);

        // Step 5: Activation (Issue 472 T3: squareplus positivity)
        let sigma = squareplus(sigma_param);
        let mu = mu_logit.tanh() * 4.0f32;

        NfOutput { sigma, mu }
    }
}

