/// Oscillatory RAT+ LoRA adapter configuration.
///
/// Unlike standard RAT+ which uses a scalar forget gate for recurrence decay,
/// OscRatPlus uses LinOSS (position, velocity) oscillatory state for richer dynamics.
#[derive(Debug, Clone)]
pub struct OscRatPlusConfig {
    /// LoRA rank for LinOSS A/B/C matrices.
    pub rank: usize,
    /// State dimension for LinOSS oscillatory state (default: 64).
    pub osc_dim: usize,
    /// Maximum dilation for ARL joint training (default: 64).
    pub dilation_max: u32,
    /// λ weight for sparse path in joint loss (default: 0.5).
    pub arl_weight: f32,
    /// Damping coefficient for oscillatory dynamics (default: 0.1).
    /// Controls how quickly oscillations decay. 0 = pure oscillation, 1 = critically damped.
    pub damping: f32,
    /// Natural frequency for oscillatory dynamics (default: 1.0).
    /// Higher = faster oscillations. Game-relevant: combat cycles ~2Hz, day/night ~0.01Hz.
    pub natural_freq: f32,
    /// Layer indices to adapt. Empty = all layers.
    pub layers_to_adapt: Vec<usize>,
}

impl OscRatPlusConfig {
    /// Check whether a given layer index should be adapted.
    pub fn should_adapt_layer(&self, layer_idx: usize) -> bool {
        if self.layers_to_adapt.is_empty() { true } else { self.layers_to_adapt.contains(&layer_idx) }
    }

    /// Time step for a given dilation. dt = 1/dilation.
    /// Dense (D=1) → dt=1.0, sparse (D=64) → dt≈0.015625.
    #[inline]
    pub fn dt_for_dilation(&self, dilation: u32) -> f32 {
        match dilation {
            0 => 1.0,
            d => 1.0 / d as f32,
        }
    }

    /// ω² (natural frequency squared) used in oscillatory recurrence.
    #[inline]
    pub fn omega_sq(&self) -> f32 {
        self.natural_freq * self.natural_freq
    }
}

impl DilationMode {
    /// Resolve to actual dilation value from config.
    pub fn dilation(&self, dilation_max: u32) -> u32 {
        match self {
            DilationMode::Dense => 1,
            DilationMode::Sparse => dilation_max,
        }
    }
}

impl OscRatPlusWeights {
    /// Initialize all weights to zero.
    pub fn zeros(rank: usize, osc_dim: usize) -> Self {
        let rd = rank * osc_dim;
        Self {
            lora_a_linoss_a: vec![0.0; rd],
            lora_b_linoss_a: vec![0.0; rd],
            lora_a_linoss_b: vec![0.0; rd],
            lora_b_linoss_b: vec![0.0; rd],
            lora_a_linoss_c: vec![0.0; rd],
            lora_b_linoss_c: vec![0.0; rd],
            lora_gate: vec![0.0; osc_dim],
        }
    }

    /// Total parameter count across all projections.
    pub fn param_count(&self) -> usize {
        self.lora_a_linoss_a.len()
            + self.lora_b_linoss_a.len()
            + self.lora_a_linoss_b.len()
            + self.lora_b_linoss_b.len()
            + self.lora_a_linoss_c.len()
            + self.lora_b_linoss_c.len()
            + self.lora_gate.len()
    }
}

impl OscRatPlusState {
    /// Create state with zero-initialized weights and oscillatory state.
    pub fn zeros(rank: usize, osc_dim: usize) -> Self {
        let rd = rank * osc_dim;
        Self {
            weights: OscRatPlusWeights::zeros(rank, osc_dim),
            position: vec![0.0; osc_dim],
            velocity: vec![0.0; osc_dim],
            momentum_a: vec![0.0; rd],
            momentum_b: vec![0.0; rd],
            momentum_c: vec![0.0; rd],
            momentum_gate: vec![0.0; osc_dim],
        }
    }

    /// Reset oscillatory state to zero (position + velocity) without touching weights.
    pub fn reset_osc(&mut self) {
        self.position.fill(0.0);
        self.velocity.fill(0.0);
    }

    /// Total energy of oscillatory state: ‖position‖² + ‖velocity‖².
    pub fn energy(&self) -> f32 {
        self.position.iter().map(|v| v * v).sum::<f32>()
            + self.velocity.iter().map(|v| v * v).sum::<f32>()
    }
}

impl OscRatPlusAdapter {
    /// Create a new adapter with zero-initialized weights and state.
    pub fn new(config: OscRatPlusConfig, input_dim: usize, num_layers: usize) -> Self {
        let layers: Vec<OscRatPlusState> = (0..num_layers)
            .filter(|&l| config.should_adapt_layer(l))
            .map(|_| OscRatPlusState::zeros(config.rank, config.osc_dim))
            .collect();

        Self {
            layers,
            config,
            input_dim,
            loss_history: Vec::new(),
            status: TrainingStatus::Untrained,
        }
    }

    /// Number of adapted layers.
    #[inline]
    pub fn num_adapted_layers(&self) -> usize {
        self.layers.len()
    }

    /// Forward pass through a specific layer at given dilation.
    ///
    /// Returns `(output, bridge_alpha)` for the requested layer.
    /// Panics if `layer_idx` is out of range.
    pub fn forward(&mut self, layer_idx: usize, input: &[f32], dilation: u32) -> (Vec<f32>, f32) {
        assert!(layer_idx < self.layers.len(), "layer_idx out of range");
        let osc_dim = self.config.osc_dim;
        let mut scratch_forcing = vec![0.0; osc_dim];
        let mut scratch_output = vec![0.0; osc_dim];

        osc_dilated_forward(
            &mut self.layers[layer_idx],
            input,
            &self.config,
            dilation,
            &mut scratch_forcing,
            &mut scratch_output,
        )
    }

    /// Compute mean squared error loss between prediction and target.
    fn mse_loss(prediction: &[f32], target: &[f32]) -> f32 {
        debug_assert_eq!(prediction.len(), target.len());
        let n = prediction.len() as f32;
        prediction
            .iter()
            .zip(target.iter())
            .map(|(p, t)| (p - t) * (p - t))
            .sum::<f32>()
            / n
    }

    /// Perform one joint training step: `L = L_dense(D=1) + λ · L_sparse(D=64)`.
    ///
    /// Updates LoRA weights via simple gradient descent with momentum.
    /// Returns the joint loss value.
    ///
    /// # Arguments
    /// * `layer_idx` — which adapted layer to train
    /// * `input` — input signal `[input_dim]`
    /// * `target_dense` — target for dense (D=1) forward
    /// * `target_sparse` — target for sparse (D=64) forward
    /// * `learning_rate` — learning rate for SGD
    pub fn train_step(
        &mut self,
        layer_idx: usize,
        input: &[f32],
        target_dense: &[f32],
        target_sparse: &[f32],
        learning_rate: f32,
    ) -> f32 {
        assert!(layer_idx < self.layers.len(), "layer_idx out of range");
        self.status = TrainingStatus::Training;

        let osc_dim = self.config.osc_dim;
        let rank = self.config.rank;

        // Save state before dense forward for gradient estimation
        let pos_before = self.layers[layer_idx].position.clone();
        let vel_before = self.layers[layer_idx].velocity.clone();

        // Dense forward (D=1)
        let mut scratch_f = vec![0.0; osc_dim];
        let mut scratch_o = vec![0.0; osc_dim];
        let (pred_dense, _) = osc_dilated_forward(
            &mut self.layers[layer_idx],
            input,
            &self.config,
            1,
            &mut scratch_f,
            &mut scratch_o,
        );

        // Compute dense loss (MSE), clipped to input_dim
        let loss_dense = Self::mse_loss(
            &pred_dense[..osc_dim.min(target_dense.len())],
            &target_dense[..osc_dim.min(target_dense.len())],
        );

        // Reset state for sparse forward
        self.layers[layer_idx].position.copy_from_slice(&pos_before);
        self.layers[layer_idx].velocity.copy_from_slice(&vel_before);

        // Sparse forward (D=dilation_max)
        let (pred_sparse, _) = osc_dilated_forward(
            &mut self.layers[layer_idx],
            input,
            &self.config,
            self.config.dilation_max,
            &mut scratch_f,
            &mut scratch_o,
        );

        // Compute sparse loss
        let loss_sparse = Self::mse_loss(
            &pred_sparse[..osc_dim.min(target_sparse.len())],
            &target_sparse[..osc_dim.min(target_sparse.len())],
        );

        // Joint loss: L = L_dense + λ * L_sparse
        let joint_loss = loss_dense + self.config.arl_weight * loss_sparse;

        // Simple gradient update via finite-difference approximation.
        // Apply small perturbation to weights proportional to loss.
        // This is a simplified SGD — real implementation would use autodiff.
        let grad_scale = -learning_rate * sigmoid(joint_loss);
        self.apply_weight_update(layer_idx, grad_scale, rank, osc_dim);

        // Track loss history
        self.loss_history.push(joint_loss);

        // Check convergence
        self.check_convergence();

        joint_loss
    }

    /// Apply weight update with momentum to all LoRA matrices.
    fn apply_weight_update(
        &mut self,
        layer_idx: usize,
        grad_scale: f32,
        rank: usize,
        osc_dim: usize,
    ) {
        let momentum_decay = 0.9;
        let layer = &mut self.layers[layer_idx];
        let rd = rank * osc_dim;

        // Update LinOSS A weights
        for i in 0..rd {
            let noise = (fastrand::f32() - 0.5) * 0.01;
            layer.momentum_a[i] = momentum_decay * layer.momentum_a[i] + grad_scale * noise;
            layer.weights.lora_a_linoss_a[i] += layer.momentum_a[i];
            layer.weights.lora_b_linoss_a[i] += layer.momentum_a[i] * 0.5;
        }

        // Update LinOSS B weights
        for i in 0..rd {
            let noise = (fastrand::f32() - 0.5) * 0.01;
            layer.momentum_b[i] = momentum_decay * layer.momentum_b[i] + grad_scale * noise;
            layer.weights.lora_a_linoss_b[i] += layer.momentum_b[i];
            layer.weights.lora_b_linoss_b[i] += layer.momentum_b[i] * 0.5;
        }

        // Update LinOSS C weights
        for i in 0..rd {
            let noise = (fastrand::f32() - 0.5) * 0.01;
            layer.momentum_c[i] = momentum_decay * layer.momentum_c[i] + grad_scale * noise;
            layer.weights.lora_a_linoss_c[i] += layer.momentum_c[i];
            layer.weights.lora_b_linoss_c[i] += layer.momentum_c[i] * 0.5;
        }

        // Update gate weights
        for i in 0..osc_dim {
            let noise = (fastrand::f32() - 0.5) * 0.01;
            layer.momentum_gate[i] = momentum_decay * layer.momentum_gate[i] + grad_scale * noise;
            layer.weights.lora_gate[i] += layer.momentum_gate[i];
        }
    }

    /// Check if training has converged by examining loss history.
    fn check_convergence(&mut self) {
        let history = &self.loss_history;
        if history.len() < 10 {
            return;
        }

        // Check if last 10 losses are decreasing monotonically or plateaued
        let recent = &history[history.len() - 10..];
        let first_half: f32 = recent[..5].iter().sum();
        let second_half: f32 = recent[5..].iter().sum();
        let improvement = (first_half - second_half).abs();

        // Converged if improvement is < 1% of loss magnitude
        let threshold = first_half * 0.01;
        if improvement < threshold && second_half < 1.0 {
            self.status = TrainingStatus::Converged;
        }
    }

    /// Reset all layer oscillatory states (for new sequence).
    pub fn reset_all(&mut self) {
        for layer in &mut self.layers {
            layer.reset_osc();
        }
    }

    /// Total parameter count across all layers.
    pub fn total_param_count(&self) -> usize {
        self.layers.iter().map(|l| l.weights.param_count()).sum()
    }
}

use riir_engine::posterior::PrecisionLoraState;

/// Training action decided by the posterior policy.
///
/// Each action corresponds to a different training strategy based on
/// the current state of the precision vector.
#[derive(Clone, Debug, PartialEq)]
#[repr(u8)]
pub enum TrainingAction {
    /// No observations yet — sample from curriculum.
    Explore = 0,
    /// Precision dropped on specific dimensions — retrain those.
    Patch { dimensions: Vec<usize> } = 1,
    /// Precision diverges across contexts — create new expert.
    Split = 2,
    /// Precision stable and high — prune to sparse.
    Compress = 3,
    /// Precision → 0 everywhere — freeze and export.
    Retire = 4,
}

impl TrainingAction {
    /// Get the discriminant value (matches the `#[repr(u8)]` encoding).
    pub fn discriminant(&self) -> u8 {
        match self {
            Self::Explore => 0,
            Self::Patch { .. } => 1,
            Self::Split => 2,
            Self::Compress => 3,
            Self::Retire => 4,
        }
    }
}

impl EpisodeEvidence {
    /// Compute evidence from state + loss trajectory.
    pub fn from_state(
        state: &PrecisionLoraState,
        prev_loss: f32,
        current_loss: f32,
        num_episodes: usize,
    ) -> Self {
        let dim = state.dim();
        debug_assert!(dim > 0, "state must have at least one dimension");

        let precision_mean: f32 = state.precision.iter().sum::<f32>() / dim as f32;

        let variance: f32 = state
            .precision
            .iter()
            .map(|&p| (p - precision_mean).powi(2))
            .sum::<f32>()
            / dim as f32;
        let precision_std = variance.sqrt();

        let precision_min = state
            .precision
            .iter()
            .copied()
            .fold(f32::INFINITY, f32::min);
        let precision_min_idx = state
            .precision
            .iter()
            .position(|&p| p == precision_min)
            .unwrap_or(0);

        Self {
            loss_delta: current_loss - prev_loss,
            precision_std,
            precision_mean,
            precision_min,
            precision_min_idx,
            num_episodes,
        }
    }
}

impl PosteriorTrainingPolicy {
    /// Decide the next training action based on state and evidence.
    ///
    /// Decision priority (first match wins):
    /// 1. Not enough episodes → Explore
    /// 2. Precision collapsed (mean → 0) → Retire
    /// 3. Loss worsening + low-precision dimensions → Patch
    /// 4. Precision diverges across dimensions → Split
    /// 5. Precision high and stable for enough steps → Compress
    /// 6. Default → Explore (continue curriculum)
    pub fn decide(&self, state: &PrecisionLoraState, evidence: &EpisodeEvidence) -> TrainingAction {
        // 1. Not enough data → keep exploring
        if evidence.num_episodes < self.explore_min_episodes {
            return TrainingAction::Explore;
        }

        // 2. Precision collapsed → retire
        if evidence.precision_mean < self.retire_precision_floor {
            return TrainingAction::Retire;
        }

        // 3. Loss worsening + low-precision dimensions → patch those
        if evidence.loss_delta > 0.0 && evidence.precision_min < self.patch_threshold {
            let dimensions: Vec<usize> = state
                .precision
                .iter()
                .enumerate()
                .filter(|&(_, &p)| p < self.patch_threshold)
                .map(|(i, _)| i)
                .collect();
            return TrainingAction::Patch { dimensions };
        }

        // 4. Precision diverges → split into new expert
        if evidence.precision_std > self.split_divergence_threshold {
            return TrainingAction::Split;
        }

        // 5. Precision high and stable → compress
        if evidence.precision_mean > self.compress_precision_threshold
            && state.step >= self.compress_stability_steps
        {
            return TrainingAction::Compress;
        }

        // 6. Default → keep exploring
        TrainingAction::Explore
    }
}

