impl FixedScheduleBaseline {
    fn new(dim: usize, learning_rate: f32) -> Self {
        Self {
            weights: vec![0.0; dim],
            learning_rate,
        }
    }

    /// One gradient step toward target: w -= lr * 2 * (w - target) / n.
    fn sgd_step(&mut self, target: &[f32]) {
        let lr = self.learning_rate;
        let n = self.weights.len() as f32;
        for (w, &t) in self.weights.iter_mut().zip(target.iter()) {
            *w -= lr * 2.0 * (*w - t) / n;
        }
    }
}

impl RankOneSpectralReg {
    /// Create a new regularizer with given λ and power iterations.
    pub fn new(lambda: f32, power_iters: usize) -> Self {
        Self {
            lambda,
            power_iters,
            scratch: Vec::new(),
        }
    }

    /// Create with default config values.
    pub fn from_config(config: &RankOneSpectralConfig) -> Self {
        Self::new(config.lambda, config.power_iters)
    }

    /// Pre-allocate scratch buffer for a given matrix size.
    /// Call once before training to avoid allocations in hot loops.
    pub fn preallocate(&mut self, max_dim: usize) {
        self.scratch = vec![0.0f32; max_dim];
    }

    /// Compute the rank-one penalty for a LoRA A matrix.
    ///
    /// Returns λ · (||A||²_F - σ₁²), which is λ times the sum of squares
    /// of non-dominant singular values. Zero when A is rank-1.
    ///
    /// - `a_matrix`: [rows × cols] row-major (head_dim × rank)
    /// - `rows`: number of rows (head_dim)
    /// - `cols`: number of columns (rank)
    pub fn loss(&mut self, a_matrix: &[f32], rows: usize, cols: usize) -> f32 {
        debug_assert_eq!(a_matrix.len(), rows * cols);
        let (sigma1_sq, frob_sq) =
            sigma1_and_frobenius_sq(a_matrix, rows, cols, &mut self.scratch, self.power_iters);
        let residual = frob_sq - sigma1_sq;
        self.lambda * residual.max(0.0)
    }

    /// Compute combined loss: base_loss + λ · rank_one_loss.
    pub fn combined_loss(
        &mut self,
        base_loss: f32,
        a_matrix: &[f32],
        rows: usize,
        cols: usize,
    ) -> f32 {
        base_loss + self.loss(a_matrix, rows, cols)
    }

    /// Compute per-weight penalty contribution for diagnostics.
    ///
    /// Returns a vector of the same size as `a_matrix`, showing each weight's
    /// approximate contribution to the rank-one penalty. Uses the gradient of
    /// the Frobenius norm residual w.r.t. each weight, scaled by λ.
    pub fn per_weight_penalty(&mut self, a_matrix: &[f32], rows: usize, cols: usize) -> Vec<f32> {
        debug_assert_eq!(a_matrix.len(), rows * cols);
        let n = a_matrix.len();
        if n == 0 {
            return Vec::new();
        }

        let (sigma1_sq, frob_sq) =
            sigma1_and_frobenius_sq(a_matrix, rows, cols, &mut self.scratch, self.power_iters);
        let residual = (frob_sq - sigma1_sq).max(0.0);
        if residual < 1e-12 {
            return vec![0.0f32; n];
        }

        // Per-weight penalty ≈ λ · (||A||²_F - σ₁²) · (aᵢⱼ² / ||A||²_F)
        // This distributes the total penalty proportionally to each weight's squared magnitude.
        let frob_sq_safe = frob_sq.max(1e-12);
        let scale = self.lambda * residual / frob_sq_safe;
        a_matrix.iter().map(|&w| scale * w * w).collect()
    }

    /// Compute BLAKE3 commitment hash of config for reproducibility.
    pub fn commitment_hash(&self) -> [u8; 32] {
        let mut hasher = Hasher::new();
        hasher.update(&self.lambda.to_le_bytes());
        hasher.update(&(self.power_iters as u64).to_le_bytes());
        *hasher.finalize().as_bytes()
    }
}

impl TwoStageSchedule {
    /// Create a new schedule with given total epochs and default split.
    pub fn new(total_epochs: usize) -> Self {
        let stage2_start = total_epochs / 2;
        Self {
            total_epochs,
            stage2_start,
            stage1_lr: 1e-3,
            stage2_lr: 1e-4,
        }
    }

    /// Create with custom stage-2 start epoch.
    pub fn with_stage2_start(mut self, epoch: usize) -> Self {
        self.stage2_start = epoch.min(self.total_epochs);
        self
    }

    /// Which stage is active at the given epoch?
    pub fn stage(&self, epoch: usize) -> TrainingStage {
        if epoch < self.stage2_start { TrainingStage::Direction } else { TrainingStage::Scale }
    }

    /// Get the learning rate for the given epoch.
    ///
    /// Stage I: cosine decay from `stage1_lr` → 0.
    /// Stage II: log-linear growth from `stage2_lr` → `stage2_lr * log(1 + epoch - stage2_start)`.
    pub fn learning_rate(&self, epoch: usize) -> f32 {
        match self.stage(epoch) {
            TrainingStage::Direction => {
                let progress = if self.stage2_start > 0 {
                    epoch as f32 / self.stage2_start as f32
                } else {
                    1.0
                };
                // Cosine decay: lr = stage1_lr * 0.5 * (1 + cos(π * progress))
                let cos_val = libm::cosf(std::f32::consts::PI * progress);
                self.stage1_lr * 0.5 * (1.0 + cos_val)
            }
            TrainingStage::Scale => {
                let elapsed = (epoch - self.stage2_start) as f32;
                let remaining = (self.total_epochs - self.stage2_start) as f32;
                // Log-linear: scale grows logarithmically
                let log_factor = libm::log1pf(elapsed).max(1.0);
                let decay = if remaining > 0.0 {
                    1.0 - (elapsed / remaining) * 0.5
                } else {
                    0.5
                };
                self.stage2_lr * log_factor * decay
            }
        }
    }

    /// Whether to normalize LoRA A/B at this epoch (Stage I only).
    pub fn should_normalize(&self, epoch: usize) -> bool {
        matches!(self.stage(epoch), TrainingStage::Direction)
    }

    /// Whether to fix directions at this epoch (Stage II only).
    pub fn should_fix_directions(&self, epoch: usize) -> bool {
        matches!(self.stage(epoch), TrainingStage::Scale)
    }

    /// Normalize a weight matrix in-place: each column → unit norm.
    /// For LoRA A [head_dim × rank], normalize each column (rank direction).
    pub fn normalize_columns(a_matrix: &mut [f32], rows: usize, cols: usize) {
        debug_assert_eq!(a_matrix.len(), rows * cols);
        for k in 0..cols {
            let mut col_norm_sq = 0.0f32;
            for i in 0..rows {
                col_norm_sq += a_matrix[i * cols + k] * a_matrix[i * cols + k];
            }
            let inv_norm = if col_norm_sq > 1e-12 {
                1.0 / libm::sqrtf(col_norm_sq)
            } else {
                1.0
            };
            for i in 0..rows {
                a_matrix[i * cols + k] *= inv_norm;
            }
        }
    }
}

impl RefinementArm {
    /// All arms as a slice.
    pub const fn all() -> [RefinementArm; 3] {
        [
            RefinementArm::SkipRefine,
            RefinementArm::Refine1Step,
            RefinementArm::RefineMultiStep,
        ]
    }

    /// Convert to index.
    #[inline]
    pub fn index(self) -> usize {
        self as usize
    }
}

impl BetaState {
    const fn initial() -> Self {
        Self {
            alpha: 1.0,
            beta_param: 1.0,
        }
    }

    /// Sample from Beta(alpha, beta_param) using gamma approximation.
    ///
    /// Uses the identity: if X ~ Gamma(α, 1) and Y ~ Gamma(β, 1),
    /// then X / (X + Y) ~ Beta(α, β).
    ///
    /// We approximate Gamma(k, 1) via Marsaglia & Tsang's method for k >= 1,
    /// and the Ahrens-Dieter method for k < 1.
    fn sample(&self, rng: &mut fastrand::Rng) -> f64 {
        let x = sample_gamma(self.alpha, rng);
        let y = sample_gamma(self.beta_param, rng);
        if x + y == 0.0 {
            return 0.5;
        }
        x / (x + y)
    }

    fn observe_success(&mut self) {
        self.alpha += 1.0;
    }

    fn observe_failure(&mut self) {
        self.beta_param += 1.0;
    }
}

impl RefinementBandit {
    /// Create a new bandit with uniform Beta(1, 1) priors.
    pub fn new() -> Self {
        Self {
            arms: [
                BetaState::initial(),
                BetaState::initial(),
                BetaState::initial(),
            ],
            rng: fastrand::Rng::new(),
        }
    }

    /// Seed the RNG for reproducible testing.
    pub fn with_seed(seed: u64) -> Self {
        let mut bandit = Self::new();
        bandit.rng.seed(seed);
        bandit
    }

    /// Select an arm using contextual Thompson sampling.
    ///
    /// Context rules:
    /// - q_confidence > 0.8 → bias toward SkipRefine (model is confident)
    /// - q_confidence < 0.3 → bias toward RefineMultiStep (uncertain, need more refinement)
    /// - Otherwise → standard Thompson sampling from posterior
    pub fn select(&mut self, context: RefinementContext) -> RefinementArm {
        // High confidence → strongly prefer SkipRefine
        if context.q_confidence > 0.8 {
            // Sample SkipRefine with high probability, but allow exploration
            let skip_sample = self.arms[RefinementArm::SkipRefine.index()].sample(&mut self.rng);
            if skip_sample > 0.3 {
                return RefinementArm::SkipRefine;
            }
        }

        // Low confidence → strongly prefer RefineMultiStep
        if context.q_confidence < 0.3 {
            let multi_sample =
                self.arms[RefinementArm::RefineMultiStep.index()].sample(&mut self.rng);
            if multi_sample > 0.3 {
                return RefinementArm::RefineMultiStep;
            }
        }

        // Standard Thompson sampling: draw from each arm's posterior, pick max.
        let mut best_arm = RefinementArm::SkipRefine;
        let mut best_sample = self.arms[0].sample(&mut self.rng);

        for arm in RefinementArm::all() {
            if arm == RefinementArm::SkipRefine {
                continue; // already sampled
            }
            let sample = self.arms[arm.index()].sample(&mut self.rng);
            if sample > best_sample {
                best_sample = sample;
                best_arm = arm;
            }
        }

        best_arm
    }

    /// Observe a reward for the selected arm and update posterior.
    ///
    /// Reward mapping:
    /// - `+1` → success (yr passes validator)
    /// - `0` → neutral (yr same as yo, slight failure update)
    /// - `-1` → failure (yr degrades: pass→fail)
    pub fn observe(&mut self, arm: RefinementArm, reward: i8) {
        match reward {
            1 => self.arms[arm.index()].observe_success(),
            -1 => self.arms[arm.index()].observe_failure(),
            0 => {
                // Neutral: tiny nudge toward failure to avoid getting stuck
                // but don't penalize as hard as explicit failure.
                // This is a common bandit trick for zero-reward observations.
                self.arms[arm.index()].observe_failure();
            }
            _ => {}
        }
    }

    /// Reset all arm posteriors to uniform Beta(1, 1).
    pub fn reset(&mut self) {
        self.arms = [
            BetaState::initial(),
            BetaState::initial(),
            BetaState::initial(),
        ];
    }

    /// Get the Beta posterior parameters for an arm (alpha, beta).
    ///
    /// Useful for diagnostics and logging.
    pub fn arm_posterior(&self, arm: RefinementArm) -> (f64, f64) {
        let state = &self.arms[arm.index()];
        (state.alpha, state.beta_param)
    }

    /// Get the empirical success rate for an arm.
    pub fn arm_success_rate(&self, arm: RefinementArm) -> f64 {
        let state = &self.arms[arm.index()];
        let successes = state.alpha - 1.0;
        let total = state.alpha + state.beta_param - 2.0;
        if total <= 0.0 {
            return 0.5; // uniform prior
        }
        successes / total
    }
}

impl<'de> Deserialize<'de> for RlvrRow {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        #[derive(Deserialize)]
        struct Raw {
            prompt: String,
            #[serde(default)]
            tests: Option<String>,
            #[serde(default)]
            lint: Option<String>,
            #[serde(default)]
            lints: Option<Vec<String>>,
        }
        let raw = Raw::deserialize(d)?;
        // Reject both-absent / both-present / empty loudly: a malformed row
        // must skip at load time, not silently score wrong.
        let (lints, edit_style) = match (raw.lint, raw.lints) {
            (Some(l), None) => (vec![l], false),
            (None, Some(v)) if !v.is_empty() => (v, true),
            _ => {
                return Err(serde::de::Error::custom(
                    "row must carry exactly one of `lint: String` or a non-empty `lints: [String]`",
                ));
            }
        };
        Ok(RlvrRow {
            prompt: raw.prompt,
            tests: raw.tests,
            lints,
            edit_style,
        })
    }

impl ScoreDiag {
    pub fn record(&mut self, outcome: &Result<RewardVerdict, NoScore>) {
        match outcome {
            Ok(RewardVerdict::Pass) => self.pass += 1,
            Ok(RewardVerdict::Fail) => self.fail += 1,
            Ok(RewardVerdict::Unscoreable(_)) => self.unscoreable_lint += 1,
            Err(NoScore::EmptyCompletion) => self.empty_completion += 1,
            Err(NoScore::Substitution(SubstFail::NotAFnItem { block })) => {
                self.not_a_fn_item += 1;
                self.push_sample(format!("not_a_fn: {block}"));
            }
            Err(NoScore::Substitution(SubstFail::FnNotInModule { name })) => {
                self.fn_not_in_module += 1;
                self.push_sample(format!("fn_absent: {name}"));
            }
        }
    }

    fn push_sample(&mut self, s: String) {
        if self.samples.len() < DIAG_SAMPLE_CAP && !self.samples.contains(&s) {
            self.samples.push(s);
        }
    }

    /// Total rollouts recorded.
    pub fn attempts(&self) -> usize {
        self.pass
            + self.fail
            + self.unscoreable_lint
            + self.empty_completion
            + self.not_a_fn_item
            + self.fn_not_in_module
    }

    /// Rollouts that actually reached clippy — the ONLY ones that say anything
    /// about difficulty. `p` should be read over this denominator, not
    /// `attempts()`.
    pub fn scored(&self) -> usize {
        self.pass + self.fail
    }

    /// Rollouts that failed before scoring because of the response format.
    pub fn format_failures(&self) -> usize {
        self.empty_completion + self.not_a_fn_item + self.fn_not_in_module
    }

    /// `p` over the scored denominator, or `None` when nothing was scored (the
    /// smoke2 state — where a `0.0` would be a lie).
    pub fn p_scored(&self) -> Option<f64> {
        (self.scored() > 0).then(|| self.pass as f64 / self.scored() as f64)
    }

    pub fn summary(&self) -> String {
        let p = match self.p_scored() {
            Some(v) => format!("{v:.4}"),
            None => "n/a (nothing reached clippy)".to_string(),
        };
        format!(
            "attempts={} scored={} (pass={} fail={}) p_scored={} | \
unscored: empty={} not_a_fn={} fn_absent={} unknown_lint={}",
            self.attempts(),
            self.scored(),
            self.pass,
            self.fail,
            p,
            self.empty_completion,
            self.not_a_fn_item,
            self.fn_not_in_module,
            self.unscoreable_lint,
        )
    }
}

impl RewardVerdict {
    /// The reward the policy receives. Unscoreable pays 0 — never inflate.
    pub fn reward(&self) -> f32 {
        match self {
            RewardVerdict::Pass => 1.0,
            RewardVerdict::Fail | RewardVerdict::Unscoreable(_) => 0.0,
        }
    }

    pub fn passed(&self) -> bool {
        matches!(self, RewardVerdict::Pass)
    }
}

impl RewardCache {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn get(&mut self, code: &str, lint_names: &[String], verify_root: &Path) -> RewardVerdict {
        let mut hasher = blake3::Hasher::new();
        hasher.update(code.as_bytes());
        hasher.update(b"|");
        for l in lint_names {
            hasher.update(l.as_bytes());
            hasher.update(b"\x1f");
        }
        let key = *hasher.finalize().as_bytes();
        if let Some(v) = self.cache.get(&key) {
            self.hits += 1;
            return v.clone();
        }
        self.misses += 1;
        let v = clippy_reward(code, lint_names, verify_root);
        self.cache.insert(key, v.clone());
        v
    }

    pub fn stats(&self) -> (usize, usize, f32) {
        let total = self.hits + self.misses;
        let hit_rate = if total > 0 {
            100.0 * self.hits as f32 / total as f32
        } else {
            0.0
        };
        (self.hits, self.misses, hit_rate)
    }
}

