/// A best-buddy pair: two neurons across adapters with high Pearson correlation.
///
/// Mutual nearest neighbors — neuron_a's most correlated partner in B is neuron_b,
/// AND neuron_b's most correlated partner in A is neuron_a.
#[derive(Clone, Debug)]
pub struct LoraNeuronPair {
    /// Domain name of adapter A (e.g., "bomber").
    pub domain_a: String,
    /// LoRA neuron index in adapter A.
    pub neuron_idx_a: usize,
    /// Domain name of adapter B (e.g., "go").
    pub domain_b: String,
    /// LoRA neuron index in adapter B.
    pub neuron_idx_b: usize,
    /// Pearson r correlation between the two neurons' activation patterns.
    pub correlation: f32,
}

impl RosettaLoraMiner {
    /// Create a new miner with the given Pearson correlation threshold.
    ///
    /// Pairs with r < threshold are discarded. Default: 0.7.
    pub fn new(threshold: f32) -> Self {
        Self {
            adapters: HashMap::new(),
            probe_activations: HashMap::new(),
            correlation_threshold: threshold,
        }
    }

    /// Register a trained LoRA adapter's flat weight vector.
    ///
    /// The weights are stored for dimension validation and future warm-start.
    pub fn register_adapter(&mut self, domain: &str, weights: Vec<f32>) {
        self.adapters.insert(domain.to_string(), weights);
    }

    /// Set per-probe-state activation vectors for a domain.
    ///
    /// `activations[i]` = activation vector of neuron i across all probe states.
    /// Length of `activations` = number of neurons in the adapter.
    /// Length of each inner vec = number of probe states.
    pub fn set_probe_activations(&mut self, domain: &str, activations: Vec<Vec<f32>>) {
        self.probe_activations
            .insert(domain.to_string(), activations);
    }

    /// Mine Pearson correlations across all registered adapter pairs.
    ///
    /// For each unordered pair (A, B), computes the full correlation matrix
    /// between their neuron activations, then finds mutual nearest neighbors
    /// ("best buddies") above the correlation threshold.
    ///
    /// Returns all best-buddy pairs across all adapter pairs.
    pub fn mine_correlations(&self) -> Vec<LoraNeuronPair> {
        let domains: Vec<&str> = self.probe_activations.keys().map(|s| s.as_str()).collect();
        if domains.len() < 2 {
            return Vec::new();
        }

        // Pre-count pairs for capacity estimate: C(n, 2) pairs × ~100 buddies each.
        let estimated_pairs = (domains.len() * (domains.len() - 1) / 2) * 64;
        let mut all_pairs = Vec::with_capacity(estimated_pairs);

        // All unordered pairs of domains.
        for i in 0..domains.len() {
            for j in (i + 1)..domains.len() {
                let domain_a = domains[i];
                let domain_b = domains[j];

                let activations_a = match self.probe_activations.get(domain_a) {
                    Some(a) => a,
                    None => continue,
                };
                let activations_b = match self.probe_activations.get(domain_b) {
                    Some(b) => b,
                    None => continue,
                };

                let pairs = find_best_buddies(
                    domain_a,
                    activations_a,
                    domain_b,
                    activations_b,
                    self.correlation_threshold,
                );
                all_pairs.extend(pairs);
            }
        }

        all_pairs
    }

    /// Build a Rosetta dictionary from mined best-buddy pairs.
    ///
    /// Clusters transitive best-buddy chains into universal `GameConcept`s.
    /// The centroid of each concept is the mean activation pattern of all member neurons.
    pub fn build_dictionary(&self, pairs: Vec<LoraNeuronPair>) -> RosettaLoraDictionary {
        // Build activation lookup for centroid computation.
        let activation_refs: HashMap<&str, &Vec<Vec<f32>>> = self
            .probe_activations
            .iter()
            .map(|(k, v)| (k.as_str(), v))
            .collect();

        let concepts = cluster_into_concepts(&pairs, &activation_refs);

        RosettaLoraDictionary {
            pairs,
            universal_concepts: concepts,
        }
    }

    /// Verify dictionary integrity with blake3 hash.
    ///
    /// Returns the blake3 hash of the serialized pairs + concepts.
    /// Used for `.rosetta.bin` file integrity checks.
    pub fn dictionary_fingerprint(dictionary: &RosettaLoraDictionary) -> [u8; 32] {
        let mut hasher = blake3::Hasher::new();

        // Hash pairs count.
        hasher.update(&(dictionary.pairs.len() as u64).to_le_bytes());
        for pair in &dictionary.pairs {
            hasher.update(pair.domain_a.as_bytes());
            hasher.update(&(pair.neuron_idx_a as u64).to_le_bytes());
            hasher.update(pair.domain_b.as_bytes());
            hasher.update(&(pair.neuron_idx_b as u64).to_le_bytes());
            hasher.update(&pair.correlation.to_le_bytes());
        }

        // Hash concepts count.
        hasher.update(&(dictionary.universal_concepts.len() as u64).to_le_bytes());
        for concept in &dictionary.universal_concepts {
            hasher.update(&(concept.id as u64).to_le_bytes());
            for (domain, idx) in &concept.neurons {
                hasher.update(domain.as_bytes());
                hasher.update(&(*idx as u64).to_le_bytes());
            }
            // Hash centroid as raw bytes.
            for &v in &concept.centroid {
                hasher.update(&v.to_le_bytes());
            }
        }

        *hasher.finalize().as_bytes()
    }
}

impl ConceptEvolutionTracker {
    /// Create a new tracker with the given stability threshold.
    ///
    /// Neurons whose earliest-to-latest Pearson r >= threshold are "stable".
    pub fn new(threshold: f32) -> Self {
        Self {
            checkpoint_activations: Vec::new(),
            stable_neurons: Vec::new(),
            frontier_neurons: Vec::new(),
            stability_threshold: threshold,
        }
    }

    /// Record a training checkpoint snapshot.
    ///
    /// - `step`: training step number.
    /// - `activations`: per-neuron activation vectors across probe states.
    /// - `correlations`: cross-game Rosetta correlations at this step.
    pub fn record_checkpoint(
        &mut self,
        step: usize,
        activations: Vec<Vec<f32>>,
        correlations: Vec<f32>,
    ) {
        self.checkpoint_activations.push(CheckpointSnapshot {
            step,
            activations,
            rosetta_correlations: correlations,
        });
    }

    /// Classify all neurons as stable or frontier.
    ///
    /// Compares earliest checkpoint activations vs latest checkpoint activations
    /// using Pearson correlation. Must have >= 2 checkpoints recorded.
    ///
    /// Clears previous classification and recomputes from scratch.
    pub fn classify_neurons(&mut self) {
        self.stable_neurons.clear();
        self.frontier_neurons.clear();

        match self.checkpoint_activations.len() {
            n if n < 2 => return,
            _ => {}
        }

        let first = &self.checkpoint_activations.first().unwrap().activations;
        let last = &self.checkpoint_activations.last().unwrap().activations;
        let n_neurons = first.len().min(last.len());

        self.stable_neurons = Vec::with_capacity(n_neurons);
        self.frontier_neurons = Vec::with_capacity(n_neurons);

        for i in 0..n_neurons {
            let r = pearson_correlation(&first[i], &last[i]);
            if r >= self.stability_threshold { self.stable_neurons.push(i) } else { self.frontier_neurons.push(i) }
        }
    }

    /// Neurons whose activations are stable across training (universal concepts).
    pub fn stable_neurons(&self) -> &[usize] {
        &self.stable_neurons
    }

    /// Neurons still evolving (game-specific adaptations).
    pub fn frontier_neurons(&self) -> &[usize] {
        &self.frontier_neurons
    }

    /// True when all neurons are stable (frontier is empty).
    ///
    /// Implies training has converged on the probe states.
    pub fn is_converged(&self) -> bool {
        if self.frontier_neurons.is_empty() { !self.stable_neurons.is_empty() } else { false }
    }

    /// Fraction of total neurons that are stable: stable / (stable + frontier).
    ///
    /// Returns 0.0 if no neurons have been classified.
    pub fn stability_ratio(&self) -> f32 {
        let total = self.stable_neurons.len() + self.frontier_neurons.len();
        match total {
            0 => 0.0,
            n => self.stable_neurons.len() as f32 / n as f32,
        }
    }
}

const ROSETTA_VERSION: u32 = 1;

/// Header size: magic(4) + version(4) + n_pairs(4) + n_concepts(4) = 16 bytes.
const HEADER_SIZE: usize = 16;

impl RosettaLoraDictionary {
    /// Serialize the dictionary to a binary `.rosetta.bin` format.
    ///
    /// Layout:
    /// ```text
    /// [MAGIC 4B][VERSION 4B][n_pairs 4B][n_concepts 4B]
    /// [pair data...]
    /// [concept data...]
    /// [blake3_hash 32B]
    /// ```
    ///
    /// All integers are little-endian. `usize` fields are serialized as `u64`.
    pub fn to_bytes(&self) -> Vec<u8> {
        // Pre-estimate capacity: header + pairs + concepts + hash.
        let pairs_est = self.pairs.len() * 64; // rough estimate per pair
        let concepts_est = self.universal_concepts.len() * 128;
        let cap = HEADER_SIZE + pairs_est + concepts_est + HASH_SIZE;
        let mut buf = Vec::with_capacity(cap);

        // Header.
        buf.extend_from_slice(ROSETTA_MAGIC);
        buf.extend_from_slice(&ROSETTA_VERSION.to_le_bytes());
        buf.extend_from_slice(&(self.pairs.len() as u32).to_le_bytes());
        buf.extend_from_slice(&(self.universal_concepts.len() as u32).to_le_bytes());

        // Pairs.
        for pair in &self.pairs {
            Self::write_string(&mut buf, &pair.domain_a);
            buf.extend_from_slice(&(pair.neuron_idx_a as u64).to_le_bytes());
            Self::write_string(&mut buf, &pair.domain_b);
            buf.extend_from_slice(&(pair.neuron_idx_b as u64).to_le_bytes());
            buf.extend_from_slice(&pair.correlation.to_le_bytes());
        }

        // Concepts.
        for concept in &self.universal_concepts {
            buf.extend_from_slice(&(concept.id as u64).to_le_bytes());
            buf.extend_from_slice(&(concept.neurons.len() as u32).to_le_bytes());
            for (domain, idx) in &concept.neurons {
                Self::write_string(&mut buf, domain);
                buf.extend_from_slice(&(*idx as u64).to_le_bytes());
            }
            buf.extend_from_slice(&(concept.centroid.len() as u32).to_le_bytes());
            for &v in &concept.centroid {
                buf.extend_from_slice(&v.to_le_bytes());
            }
        }

        // blake3 hash of everything so far, appended as trailer.
        let hash = blake3::hash(&buf);
        buf.extend_from_slice(hash.as_bytes());

        buf
    }

    /// Deserialize a dictionary from `.rosetta.bin` binary data.
    ///
    /// Verifies magic, version, and blake3 hash integrity.
    pub fn from_bytes(data: &[u8]) -> anyhow::Result<Self> {
        anyhow::ensure!(
            data.len() >= HEADER_SIZE + HASH_SIZE,
            "Rosetta data too short: {} bytes",
            data.len()
        );

        // Verify blake3 hash (trailer).
        let payload_end = data.len() - HASH_SIZE;
        let expected_hash = blake3::hash(&data[..payload_end]);
        let stored_hash = &data[payload_end..];
        anyhow::ensure!(
            expected_hash.as_bytes() == stored_hash,
            "Rosetta blake3 hash mismatch — data corrupted"
        );

        let mut cursor = 0usize;

        // Magic.
        let magic = &data[cursor..cursor + 4];
        anyhow::ensure!(
            magic == ROSETTA_MAGIC,
            "Invalid magic: expected {:?}, got {:?}",
            ROSETTA_MAGIC,
            &data[cursor..cursor + 4]
        );
        cursor += 4;

        // Version.
        let version = u32::from_le_bytes(data[cursor..cursor + 4].try_into()?);
        anyhow::ensure!(
            version == ROSETTA_VERSION,
            "Unsupported version: {version}"
        );
        cursor += 4;

        // Counts.
        let n_pairs = u32::from_le_bytes(data[cursor..cursor + 4].try_into()?) as usize;
        cursor += 4;
        let n_concepts = u32::from_le_bytes(data[cursor..cursor + 4].try_into()?) as usize;
        cursor += 4;

        // Pairs.
        let mut pairs = Vec::with_capacity(n_pairs);
        for _ in 0..n_pairs {
            let domain_a = Self::read_string(data, &mut cursor)?;
            let neuron_idx_a = u64::from_le_bytes(data[cursor..cursor + 8].try_into()?) as usize;
            cursor += 8;
            let domain_b = Self::read_string(data, &mut cursor)?;
            let neuron_idx_b = u64::from_le_bytes(data[cursor..cursor + 8].try_into()?) as usize;
            cursor += 8;
            let correlation = f32::from_le_bytes(data[cursor..cursor + 4].try_into()?);
            cursor += 4;
            pairs.push(LoraNeuronPair {
                domain_a,
                neuron_idx_a,
                domain_b,
                neuron_idx_b,
                correlation,
            });
        }

        // Concepts.
        let mut universal_concepts = Vec::with_capacity(n_concepts);
        for _ in 0..n_concepts {
            let id = u64::from_le_bytes(data[cursor..cursor + 8].try_into()?) as usize;
            cursor += 8;
            let n_neurons = u32::from_le_bytes(data[cursor..cursor + 4].try_into()?) as usize;
            cursor += 4;
            let mut neurons = Vec::with_capacity(n_neurons);
            for _ in 0..n_neurons {
                let domain = Self::read_string(data, &mut cursor)?;
                let idx = u64::from_le_bytes(data[cursor..cursor + 8].try_into()?) as usize;
                cursor += 8;
                neurons.push((domain, idx));
            }
            let centroid_len = u32::from_le_bytes(data[cursor..cursor + 4].try_into()?) as usize;
            cursor += 4;
            anyhow::ensure!(
                cursor + centroid_len * 4 <= data.len(),
                "Centroid data extends past buffer"
            );
            let mut centroid = Vec::with_capacity(centroid_len);
            for _ in 0..centroid_len {
                let v = f32::from_le_bytes(data[cursor..cursor + 4].try_into()?);
                cursor += 4;
                centroid.push(v);
            }
            universal_concepts.push(GameConcept {
                id,
                neurons,
                centroid,
            });
        }

        Ok(Self {
            pairs,
            universal_concepts,
        })
    }

    /// Write a length-prefixed string: [len u32][bytes].
    fn write_string(buf: &mut Vec<u8>, s: &str) {
        let bytes = s.as_bytes();
        buf.extend_from_slice(&(bytes.len() as u32).to_le_bytes());
        buf.extend_from_slice(bytes);
    }

    /// Read a length-prefixed string, advancing the cursor.
    fn read_string(data: &[u8], cursor: &mut usize) -> anyhow::Result<String> {
        anyhow::ensure!(
            *cursor + 4 <= data.len(),
            "String length extends past buffer"
        );
        let len = u32::from_le_bytes(data[*cursor..*cursor + 4].try_into()?) as usize;
        *cursor += 4;
        anyhow::ensure!(
            *cursor + len <= data.len(),
            "String data extends past buffer (len={len})"
        );
        let s = std::str::from_utf8(&data[*cursor..*cursor + len])?.to_string();
        *cursor += len;
        Ok(s)
    }
}

impl SftTargets {
    /// Build targets from a tokenized response, appending `eos`.
    ///
    /// # Errors
    ///
    /// [`DegenerateTarget::Empty`] when `response_ids` is empty, and
    /// [`DegenerateTarget::VerdictNeverTrained`] when it is a single token —
    /// see the module docs for why the second case is a hard error rather than
    /// a warning.
    pub fn build(response_ids: &[u32], eos: u32) -> Result<Self, DegenerateTarget> {
        match response_ids.len() {
            0 => Err(DegenerateTarget::Empty),
            1 => Err(DegenerateTarget::VerdictNeverTrained { response_tokens: 1 }),
            n => {
                let mut tokens = Vec::with_capacity(n + 1);
                tokens.extend_from_slice(response_ids);
                tokens.push(eos);
                Ok(Self { tokens, response_len: n })
            }
        }
    }

    /// The full target sequence (`response ++ [eos]`).
    #[inline]
    pub fn tokens(&self) -> &[u32] {
        &self.tokens
    }

    /// `target_len` — what the drivers call `sample.target_tokens.len()`.
    #[inline]
    pub fn len(&self) -> usize {
        self.tokens.len()
    }

    /// Always `false` — a built `SftTargets` has at least 3 tokens.
    #[inline]
    pub fn is_empty(&self) -> bool {
        false
    }

    /// `target_len - 1`, the drivers' `n_loss_tokens`. Always `>= 2`.
    #[inline]
    pub fn n_loss_tokens(&self) -> usize {
        self.tokens.len() - 1
    }

    /// The target indices the loss actually covers: `1..len`.
    ///
    /// Index 0 is excluded because nothing in the target sequence predicts it.
    #[inline]
    pub fn loss_indices(&self) -> Range<usize> {
        1..self.tokens.len()
    }

    /// Index of the last response token — the one carrying the verdict for a
    /// `"<prefix>: <verdict>"` shaped target. Guaranteed to be inside
    /// [`loss_indices`](Self::loss_indices).
    #[inline]
    pub fn verdict_index(&self) -> usize {
        self.response_len - 1
    }

    /// Does the loss actually cover the verdict token? `true` by construction —
    /// exposed so a test can assert the invariant rather than trust the docs.
    #[inline]
    pub fn trains_verdict(&self) -> bool {
        self.loss_indices().contains(&self.verdict_index())
    }

    /// Do two label variants differ at a **loss-bearing** index?
    ///
    /// This is the property that actually makes an objective label-dependent,
    /// and the one the shipped `"Yes"`/`"No"` corpus failed: the two targets
    /// differed only at index 0, which the loss never reads. A corpus whose
    /// labels are indistinguishable here cannot be learned no matter how long
    /// it trains.
    pub fn differ_at_loss_index(a: &Self, b: &Self) -> bool {
        if a.len() != b.len() {
            return true;
        }
        a.loss_indices().any(|i| a.tokens[i] != b.tokens[i])
    }
}

