impl SkillBank {
    /// Build the bank (indexes both retrieval axes over the exemplar
    /// prompt + code — retrieval must find the card by the PROBLEM shape).
    pub fn new(cards: Vec<SkillCard>) -> Self {
        let docs: Vec<DocIndex> = cards
            .iter()
            .map(|c| {
                let text = format!("{}\n{}", c.exemplar_prompt, c.exemplar_code);
                let tokens = tokenize(&text);
                let mut tf = BTreeMap::new();
                for t in &tokens {
                    *tf.entry(t.clone()).or_insert(0usize) += 1;
                }
                DocIndex {
                    len: tokens.len() as f64,
                    tf,
                    latent: embed8(&text),
                }
            })
            .collect();
        let avg_doc_len = docs.iter().map(|d| d.len).sum::<f64>() / docs.len().max(1) as f64;
        let n_docs = docs.len() as f64;
        Self {
            cards,
            docs,
            avg_doc_len,
            n_docs,
        }
    }

    fn idf(&self, term: &str) -> f64 {
        let df = self.docs.iter().filter(|d| d.tf.contains_key(term)).count() as f64;
        // BM25+ style smoothing: a term in every doc still carries a hair of
        // mass (1 + ln) so common-token-only queries rank deterministically.
        1.0 + ((self.n_docs - df + 0.5) / (df + 0.5)).ln().max(0.0)
    }

    fn bm25(&self, query: &str, doc: &DocIndex) -> f64 {
        const K1: f64 = 1.2;
        const B: f64 = 0.75;
        let mut score = 0.0;
        for qt in tokenize(query) {
            let Some(&tf) = doc.tf.get(&qt) else { continue };
            let idf = self.idf(&qt);
            let tf = tf as f64;
            let denom = tf + K1 * (1.0 - B + B * doc.len / self.avg_doc_len.max(1.0));
            score += idf * tf * (K1 + 1.0) / denom;
        }
        score
    }

    /// Dual retrieval: rank by 0.7 · normalized-BM25 + 0.3 · latent cosine.
    /// Deterministic (BTreeMap tf, stable sort, id tie-break) — the
    /// fine-tune/serve parity contract ("identical retrieval at serve")
    /// rests on this.
    pub fn retrieve(&self, query: &str, top_k: usize) -> Vec<(usize, f32)> {
        if self.cards.is_empty() {
            return Vec::new();
        }
        let q_latent = embed8(query);
        let mut bm25_scores: Vec<f64> = self.docs.iter().map(|d| self.bm25(query, d)).collect();
        let bm25_max = bm25_scores.iter().cloned().fold(0.0f64, f64::max);
        if bm25_max > 0.0 {
            for s in &mut bm25_scores {
                *s /= bm25_max;
            }
        }
        let mut ranked: Vec<(usize, f32)> = self
            .cards
            .iter()
            .enumerate()
            .zip(bm25_scores.iter())
            .map(|((i, _), &bm)| {
                let cos = cosine(&q_latent, &self.docs[i].latent);
                (i, (0.7 * bm + 0.3 * f64::from(cos)) as f32)
            })
            .collect();
        ranked.sort_by(|a, b| {
            b.1.total_cmp(&a.1)
                .then_with(|| self.cards[a.0].id.cmp(&self.cards[b.0].id))
        });
        ranked.truncate(top_k);
        ranked
    }
}

use riir_engine::ssd_lora::{SsdLoraConfig, SsdLoraWeights};

/// Numerically stable sigmoid (delegates to `crate::math::sigmoid_f32`).
#[inline]
fn sigmoid(x: f32) -> f32 {
    crate::math::sigmoid_f32(x)
}

