// Trainer
// ---------------------------------------------------------------------------

/// Cosine-decayed learning rate at `progress` in `[0, 1]`.
///
/// `progress = 0` -> `peak`, `progress = 1` -> `min_lr`. Progress is CLAMPED:
/// past 1 the cosine turns back upward, so a run that overshoots its planned
/// step count would otherwise silently re-warm.
///
/// Shared so the interpolation has ONE implementation. [`SsdLoraTrainer`] had
/// it first (no warmup); `deltanet::qv_lora_train::QvLoraAdamW` gained a
/// warmup-then-decay schedule for Plan 342 T1.2 and calls this rather than
/// carrying a second copy.
#[inline]
pub fn cosine_lr(peak: f32, min_lr: f32, progress: f32) -> f32 {
    let p = progress.clamp(0.0, 1.0);

impl SsdLoraTrainer {
    /// Create a new trainer for the given SSD-LoRA config and training hyperparameters.
    pub fn new(config: &SsdLoraConfig, train_config: &TrainConfig) -> Self {
        let n_a = config.state_dim;
        let n_b = config.state_dim * config.input_dim;
        let n_c = config.output_dim * config.state_dim;

        Self {
            config: *config,
            m_a: vec![0.0; n_a],
            v_a: vec![0.0; n_a],
            m_b: vec![0.0; n_b],
            v_b: vec![0.0; n_b],
            m_c: vec![0.0; n_c],
            v_c: vec![0.0; n_c],
            step: 0,
            lr: train_config.lr,
            min_lr: train_config.min_lr,
            weight_decay: train_config.weight_decay,
            beta1: train_config.beta1,
            beta2: train_config.beta2,
            eps: train_config.eps,
            max_steps: train_config.max_steps,
        }
    }

    /// Current learning rate with cosine decay schedule.
    pub fn current_lr(&self) -> f32 {
        if self.max_steps == 0 {
            return self.lr;
        }
        cosine_lr(self.lr, self.min_lr, (self.step as f32) / (self.max_steps as f32))
    }

    /// Number of optimizer steps taken.
    #[inline]
    pub fn step_count(&self) -> u32 {
        self.step
    }

    /// Execute one training step: forward → loss → backward → AdamW update.
    ///
    /// # Arguments
    /// * `features` - Input features `[seq_len * input_dim]`
    /// * `targets` - Binary target labels `[seq_len * output_dim]` (values in [0, 1])
    /// * `weights` - SSD-LoRA weights (modified in-place)
    ///
    /// # Returns
    /// Average binary cross-entropy loss per output element.
    pub fn train_step(
        &mut self,
        features: &[f32],
        targets: &[f32],
        weights: &mut SsdLoraWeights,
    ) -> f32 {
        let seq_len = self.config.seq_len(features.len());
        let state_dim = self.config.state_dim;
        let input_dim = self.config.input_dim;
        let output_dim = self.config.output_dim;

        debug_assert_eq!(targets.len(), seq_len * output_dim);
        debug_assert!(weights.validate(&self.config));

        // Pre-allocate caches.
        let mut states = vec![0.0f32; (seq_len + 1) * state_dim]; // +1 for initial state
        let mut outputs = vec![0.0f32; seq_len * output_dim];

        // Initialize state[0] = h_init.
        states[..state_dim].copy_from_slice(&weights.h_init);

        // ── Forward pass with cache ──────────────────────────────────
        let loss = forward_with_cache(
            features,
            weights,
            &self.config,
            &mut states,
            &mut outputs,
            targets,
        );

        // ── Backward pass (BPTT) ─────────────────────────────────────
        let mut grad_a = vec![0.0f32; state_dim];
        let mut grad_b = vec![0.0f32; state_dim * input_dim];
        let mut grad_c = vec![0.0f32; output_dim * state_dim];

        backward_bptt(
            features,
            targets,
            outputs.as_slice(),
            states.as_slice(),
            weights,
            &self.config,
            &mut grad_a,
            &mut grad_b,
            &mut grad_c,
        );

        // ── AdamW update ─────────────────────────────────────────────
        self.step += 1;
        let lr = self.current_lr();
        let bc1 = 1.0 - self.beta1.powi(self.step as i32);
        let bc2 = 1.0 - self.beta2.powi(self.step as i32);

        // A: no weight decay (bounded by sigmoid + clamp).
        adamw_update(
            &mut weights.a,
            &mut self.m_a,
            &mut self.v_a,
            &grad_a,
            lr,
            0.0,
            self.beta1,
            self.beta2,
            self.eps,
            bc1,
            bc2,
        );
        // Clamp A to [0, 1].
        for v in &mut weights.a {
            *v = v.clamp(0.0, 1.0);
        }

        // B: L2 weight decay.
        adamw_update(
            &mut weights.b,
            &mut self.m_b,
            &mut self.v_b,
            &grad_b,
            lr,
            self.weight_decay,
            self.beta1,
            self.beta2,
            self.eps,
            bc1,
            bc2,
        );

        // C: L2 weight decay.
        adamw_update(
            &mut weights.c,
            &mut self.m_c,
            &mut self.v_c,
            &grad_c,
            lr,
            self.weight_decay,
            self.beta1,
            self.beta2,
            self.eps,
            bc1,
            bc2,
        );

        loss
    }
}

