impl QValidationLoop {
    /// Create a new validation loop with the given config.
    pub fn new(config: QValidationConfig) -> Self {
        Self {
            config,
            attempt: 0,
            history: Vec::new(),
        }
    }

    /// Process a validation check result. Returns the action to take.
    ///
    /// - If validation passed → `Pass`
    /// - If failed and retries remain → `RetrySuggested`
    /// - If failed and no retries → `FailedMaxRetries`
    ///
    /// When `config.enabled` is false, always returns `Pass` (no retry).
    pub fn process_check(&mut self, passed: bool) -> ValidationResult {
        // Disabled → short-circuit, no recording.
        if !self.config.enabled {
            return ValidationResult::Pass;
        }

        if passed {
                self.history.push(ValidationResult::Pass);
                ValidationResult::Pass
            } else {
                self.attempt += 1;
                if self.attempt <= self.config.max_retries {
                        self.history.push(ValidationResult::RetrySuggested);
                        ValidationResult::RetrySuggested
                    } else {
                        self.history.push(ValidationResult::FailedMaxRetries);
                        ValidationResult::FailedMaxRetries
                    }
            }
    }

    /// Whether q-sampling should be activated for the current retry.
    ///
    /// Only activates after the first failure — standard denoising gets the
    /// first chance. This ensures we don't waste q-sampling compute on code
    /// that might pass on a standard draft.
    pub fn should_activate_q_sampling(&self) -> bool {
        self.attempt > 0
    }

    /// Reset for a new code generation attempt.
    pub fn reset(&mut self) {
        self.attempt = 0;
        self.history.clear();
    }

    /// Current attempt number (0 = first draft, 1+ = retries).
    #[inline]
    pub fn attempt(&self) -> usize {
        self.attempt
    }

    /// History of validation results.
    pub fn history(&self) -> &[ValidationResult] {
        &self.history
    }

    /// The configured activation ratio.
    #[inline]
    pub fn activation_ratio(&self) -> f32 {
        self.config.activation_ratio
    }

    /// Whether the validation loop is enabled.
    #[inline]
    pub fn is_enabled(&self) -> bool {
        self.config.enabled
    }

    /// Compute a report summarizing validation loop performance.
    pub fn report(&self) -> QValidationReport {
        let total_attempts = self.history.len();

        let first_pass_count = match self.history.first() {
            Some(ValidationResult::Pass) => 1,
            _ => 0,
        };

        let overall_pass_count = self
            .history
            .iter()
            .filter(|r| matches!(r, ValidationResult::Pass))
            .count();

        // Q-sampling recovery: cases where first attempt failed but a later attempt passed.
        let q_recovery_count = if let Some(ValidationResult::Pass) = self.history.first() {
                // First attempt already passed — no recovery needed.
                0
            } else {
                // First attempt failed — did any subsequent attempt pass?
                if self
                    .history
                    .iter()
                    .skip(1)
                    .any(|r| matches!(r, ValidationResult::Pass))
                {
                    1
                } else {
                    0
                }
            };

        let first_pass_rate = match total_attempts {
            0 => 0.0,
            _ => first_pass_count as f32 / total_attempts as f32,
        };

        let q_sampling_recovery_rate = match total_attempts {
            0 => 0.0,
            _ => q_recovery_count as f32 / total_attempts as f32,
        };

        let overall_pass_rate = match total_attempts {
            0 => 0.0,
            _ => overall_pass_count as f32 / total_attempts as f32,
        };

        QValidationReport {
            total_attempts,
            first_pass_rate,
            q_sampling_recovery_rate,
            overall_pass_rate,
        }
    }
}

impl ScProbabilityConfig {
    pub fn new(task_type: ScTaskType) -> Self {
        Self {
            sc_probability: task_type.default_sc_probability(),
            task_type,
        }
    }

    /// During training: decides whether to use previous prediction or zero.
    /// `if rng < sc_probability { use_prev_prediction } else { use_zero }`
    /// During inference: always use previous prediction (100%).
    pub fn should_self_condition(&self, rng_val: f32) -> bool {
        rng_val < self.sc_probability
    }
}

impl ScTrainingStep {
    /// Create a new SC training step with the given config and RNG seed.
    pub fn new(config: ScProbabilityConfig, seed: u64) -> Self {
        Self {
            config,
            rng: Rng::with_seed(seed),
        }
    }

    /// Decide whether to condition on previous predictions for this step.
    ///
    /// Draws a fresh `f32` from the RNG and compares against `sc_probability`.
    /// Returns `true` when the model should use its previous prediction.
    pub fn should_condition(&mut self) -> bool {
        let rng_val = self.rng.f32();
        self.config.should_self_condition(rng_val)
    }

    /// Apply SC mask to previous predictions in-place.
    ///
    /// For each position, independently decides whether to keep the prediction
    /// or zero it out. Positions where `should_condition()` returns false
    /// get zeroed, simulating "no conditioning" for that slot.
    ///
    /// Returns the number of positions that were conditioned (not zeroed).
    pub fn apply_sc_mask(&mut self, prev_predictions: &mut [f32]) -> usize {
        let mut conditioned = 0;
        for val in prev_predictions.iter_mut() {
            if self.should_condition() {
                    conditioned += 1;
                } else {
                    *val = 0.0;
                }
        }
        conditioned
    }

    /// Returns the task type for this training step.
    #[inline]
    pub fn task_type(&self) -> ScTaskType {
        self.config.task_type
    }

    /// Returns the configured SC probability.
    #[inline]
    pub fn sc_probability(&self) -> f32 {
        self.config.sc_probability
    }
}

impl ScTrainingReport {
    /// Create a new empty report.
    pub fn new() -> Self {
        Self {
            total_steps: 0,
            conditioned_steps: 0,
            conditioning_rate: 0.0,
        }
    }

    /// Record a conditioning decision for one step.
    pub fn record(&mut self, was_conditioned: bool) {
        self.total_steps += 1;
        if was_conditioned {
            self.conditioned_steps += 1;
        }
        self.conditioning_rate = match self.total_steps {
            0 => 0.0,
            _ => self.conditioned_steps as f32 / self.total_steps as f32,
        };
    }

    /// Returns the empirical conditioning rate.
    #[inline]
    pub fn conditioning_rate(&self) -> f32 {
        self.conditioning_rate
    }
}

