/// Filesystem paths required by the canonical Collimation DAG's symbolic
/// conditions (`DatasetExists`, `BaseModelLoadable`, `AdapterLoadable`).
///
/// In a real pipeline these point to actual artifacts on disk. For
/// integration tests or in-memory game training, use [`CollimationPaths::temp`]
/// to create empty placeholder files that satisfy the existence checks.
#[derive(Debug, Clone)]
pub struct CollimationPaths {
    /// Raw dataset file (input to step 1 — Data Curation).
    pub raw_dataset: PathBuf,
    /// Curated dataset output path (written by step 1).
    pub curated_dataset: PathBuf,
    /// Base model file (input to steps 2 and 3).
    pub base_model: PathBuf,
    /// Trained adapter weights (written by step 2, read by step 3).
    pub adapter: PathBuf,
    /// Merged model after sweep (written by step 3, read by step 4).
    pub merged_model: PathBuf,
    /// Attribution mask output (written by step 4, read by step 5).
    pub attribution_mask: PathBuf,
}

impl CollimationPaths {
    /// Create temp-file fixtures for all required paths.
    ///
    /// Each file is touched (empty) so existence-based symbolic conditions
    /// pass. The returned [`tempfile::TempDir`] owns the files — drop it to
    /// clean up.
    pub fn temp() -> (tempfile::TempDir, Self) {
        let dir = tempfile::tempdir().expect("failed to create temp dir for CollimationPaths");
        let raw = dir.path().join("raw.jsonl");
        let curated = dir.path().join("curated.jsonl");
        let base = dir.path().join("base.safetensors");
        let adapter = dir.path().join("adapter.safetensors");
        let merged = dir.path().join("merged.safetensors");
        let mask = dir.path().join("mask.bin");
        for p in [&raw, &curated, &base, &adapter, &merged, &mask] {
            std::fs::write(p, b"").expect("failed to touch fixture file");
        }
        let paths = Self {
            raw_dataset: raw,
            curated_dataset: curated,
            base_model: base,
            adapter,
            merged_model: merged,
            attribution_mask: mask,
        };
        (dir, paths)
    }

