impl TrainingStep {
    /// Evaluate all preconditions against a run context. Returns one
    /// [`ConditionResult`] per precondition, in declaration order.
    pub fn check_preconditions(&self, ctx: &TrainingRunContext) -> Vec<ConditionResult> {
        self.preconditions.iter().map(|c| c.evaluate(ctx)).collect()
    }

    /// Evaluate all postconditions against a step output. Returns one
    /// [`ConditionResult`] per postcondition.
    pub fn check_postconditions(&self, out: &StepOutput) -> Vec<ConditionResult> {
        self.postconditions
            .iter()
            .map(|c| c.evaluate_with_output(out))
            .collect()
    }

    /// Apply this step's writes to the context, marking the output
    /// variables as produced. The training loop calls this between steps
    /// so downstream preconditions can see the produced variables.
    pub fn apply_postconditions(&self, ctx: &mut TrainingRunContext) {
        for w in &self.writes {
            ctx.produced.insert(w.clone(), w.clone());
        }
    }

    /// Returns `true` iff this step reads and writes the same variable
    /// (a structural error — a step should consume its inputs and produce
    /// distinct outputs).
    pub fn has_read_write_collision(&self) -> bool {
        self.reads.iter().any(|r| self.writes.contains(r))
    }
}

