impl TrainingDAG {
    /// Create an empty DAG.
    pub fn new() -> Self {
        Self::default()
    }

    /// Create a linear DAG from an ordered list of steps. Edges are
    /// `Sequential { i, i+1 }` for consecutive pairs. This is the shape
    /// the Collimation pipeline uses today.
    pub fn linear(steps: Vec<TrainingStep>) -> Self {
        let edges = (0..steps.len().saturating_sub(1))
            .map(|i| TrainingEdge::Sequential { from: i, to: i + 1 })
            .collect();
        Self { steps, edges }
    }

    /// Append a step and connect it as the successor of the current tail
    /// (if any). Returns the index of the appended step.
    pub fn append_linear(&mut self, step: TrainingStep) -> usize {
        let idx = self.steps.len();
        if idx > 0 {
            self.edges.push(TrainingEdge::Sequential {
                from: idx - 1,
                to: idx,
            });
        }
        self.steps.push(step);
        idx
    }

    /// Topological ordering of step indices via Kahn's algorithm.
    ///
    /// Returns `Err(cycle_nodes)` if a cycle is detected. The returned
    /// vector on success is a valid linearization (not necessarily unique).
    pub fn step_order(&self) -> Result<Vec<usize>, Vec<usize>> {
        let n = self.steps.len();
        // Build adjacency + in-degree.
        let mut adj: Vec<Vec<usize>> = vec![Vec::new(); n];
        let mut in_deg = vec![0usize; n];
        for edge in &self.edges {
            let (from, to) = match edge {
                TrainingEdge::Sequential { from, to } => (*from, *to),
            };
            if from >= n || to >= n {
                continue; // malformed edge — caught by verify_structural
            }
            adj[from].push(to);
            in_deg[to] += 1;
        }
        // Seed with zero-in-degree nodes.
        let mut queue: std::collections::VecDeque<usize> =
            (0..n).filter(|&i| in_deg[i] == 0).collect();
        let mut order = Vec::with_capacity(n);
        while let Some(node) = queue.pop_front() {
            order.push(node);
            for &succ in &adj[node] {
                in_deg[succ] -= 1;
                if in_deg[succ] == 0 {
                    queue.push_back(succ);
                }
            }
        }
        if order.len() == n {
            Ok(order)
        } else {
            // Nodes still with in_deg > 0 are in a cycle.
            let cycle: Vec<usize> = (0..n).filter(|&i| in_deg[i] > 0).collect();
            Err(cycle)
        }
    }

    /// Indices of steps that are direct predecessors of `step_idx`
    /// (i.e. have an edge into `step_idx`).
    pub fn predecessors_of(&self, step_idx: usize) -> Vec<usize> {
        self.edges
            .iter()
            .filter_map(|e| match e {
                TrainingEdge::Sequential { from, to } if *to == step_idx => Some(*from),
                _ => None,
            })
            .collect()
    }

    /// Verify structural well-formedness.
    ///
    /// `initial_inputs` are variable names available before step 0
    /// (e.g. `["raw_dataset", "curation_config", "base_model"]`).
    ///
    /// Checks:
    /// 1. All edge indices are in bounds.
    /// 2. No cycles (topological sort succeeds).
    /// 3. No step reads and writes the same variable.
    /// 4. Every `reads` variable is produced by a predecessor or is an
    ///    initial input.
    pub fn verify_structural(&self, initial_inputs: &[&str]) -> StructuralResult {
        let mut errors = Vec::new();
        let n = self.steps.len();

        // Check 1: edge bounds.
        for edge in &self.edges {
            let (from, to) = match edge {
                TrainingEdge::Sequential { from, to } => (*from, *to),
            };
            if from >= n || to >= n {
                errors.push(format!("edge {edge:?} references out-of-bounds step"));
            }
        }

        // Check 2: cycle detection.
        if let Err(cycle) = self.step_order() {
            errors.push(format!("cycle detected involving steps {cycle:?}"));
        }

        // Check 3: read-write collisions.
        for (i, step) in self.steps.iter().enumerate() {
            if step.has_read_write_collision() {
                errors.push(format!(
                    "step {i} ({}) reads and writes the same variable",
                    step.name
                ));
            }
        }

        // Check 4: every reads variable has a producer.
        // Build the set of all produced variables from initial inputs +
        // all steps' writes (a step may read from any predecessor in a
        // valid topological order, so we use the union of all producers).
        let initial: std::collections::HashSet<&str> = initial_inputs.iter().copied().collect();
        let mut all_writes: std::collections::HashSet<&str> = initial;
        for step in &self.steps {
            for w in &step.writes {
                all_writes.insert(w.as_str());
            }
        }
        for (i, step) in self.steps.iter().enumerate() {
            for r in &step.reads {
                if !all_writes.contains(r.as_str()) {
                    errors.push(format!(
                        "step {i} ({}) reads '{}' which no predecessor or initial input produces",
                        step.name, r
                    ));
                }
            }
        }

        let valid = errors.is_empty();
        StructuralResult { valid, errors }
    }

    /// BLAKE3 hash of the DAG structure for provenance attestation.
    /// Serializes `(step_names, reads, writes, edges)` — stable across
    /// cosmetic edits (comments, whitespace).
    pub fn graph_hash(&self) -> [u8; 32] {
        let mut hasher = blake3::Hasher::new();
        for step in &self.steps {
            hasher.update(step.name.as_bytes());
            hasher.update(b"\x00");
            for r in &step.reads {
                hasher.update(r.as_bytes());
                hasher.update(b",");
            }
            hasher.update(b"\x01");
            for w in &step.writes {
                hasher.update(w.as_bytes());
                hasher.update(b",");
            }
            hasher.update(b"\x02");
        }
        for edge in &self.edges {
            let (from, to) = match edge {
                TrainingEdge::Sequential { from, to } => (*from, *to),
            };
            hasher.update(&from.to_le_bytes());
            hasher.update(&to.to_le_bytes());
        }
        *hasher.finalize().as_bytes()
    }
}

