    /// Build a `RepairRecord` for a hint that was applied and then verified.
    #[inline]
    pub fn applied(hint: TrainingRepairHint, outcome: ConditionResult) -> Self {
        Self {
            hint,
            applied: true,
            outcome: Some(outcome),
        }
    }

    /// Build a `RepairRecord` for a hint that was suggested but not applied.
    #[inline]
    pub fn suggested(hint: TrainingRepairHint) -> Self {
        Self {
            hint,
            applied: false,
            outcome: None,
        }
    }

    /// `true` iff the repair was applied and its outcome was `Satisfied`.
    #[inline]
    pub fn resolved(&self) -> bool {
        self.applied && self.outcome.as_ref().is_some_and(|r| r.passed())
    }
}

impl TrainingProvenance {
    /// Build a provenance record for a just-completed run.
    ///
    /// The diagnosis is `None` if the run passed; for failing runs the caller
    /// should pass the [`diagnose`](super::repair::diagnose) output. No
    /// repairs are recorded initially — use [`with_repairs`](Self::with_repairs)
    /// or mutate `repairs_applied` after applying repairs.
    ///
    /// The commitment is computed over the other fields.
    pub fn new(
        verification_result: TrainingVerificationResult,
        diagnosis: Option<TrainingDiagnosis>,
        timestamp: u64,
    ) -> Self {
        let dag_hash = verification_result.graph_hash;
        let run_id = Uuid::now_v7();
        let mut record = Self {
            dag_hash,
            verification_result,
            diagnosis,
            repairs_applied: Vec::new(),
            timestamp,
            run_id,
            // Placeholder — recomputed below after all fields are set.
            commitment: [0u8; 32],
        };
        record.commitment = record.compute_commitment();
        record
    }

    /// Attach the list of repairs that were applied.
    ///
    /// Recomputes the commitment (because `repairs_applied` is in the
    /// commitment scope).
    pub fn with_repairs(mut self, repairs: Vec<RepairRecord>) -> Self {
        self.repairs_applied = repairs;
        self.commitment = self.compute_commitment();
        self
    }

    /// Recompute the BLAKE3 commitment over all fields except `commitment`.
    ///
    /// The canonical form is `serde_json` with a fixed key order (serde's
    /// default — struct field declaration order). This is deterministic for a
    /// given `TrainingProvenance` value because all constituent types derive
    /// `Serialize` with stable field order.
    fn compute_commitment_inner(&self) -> [u8; 32] {
        // Serialize a view that excludes the `commitment` field. We do this by
        // serializing each committed field separately and feeding them into
        // the hasher in declaration order. This avoids a derive-less
        // "everything but commitment" mirror struct.
        let mut hasher = blake3::Hasher::new();
        hasher.update(b"dag_hash=");
        hasher.update(bytemuck::cast_slice::<u8, u8>(&self.dag_hash));

        // Verification result: serialize to JSON bytes (stable field order).
        hasher.update(b";verification_result=");
        // Serializing can fail only for non-finite floats (NaN/Inf). Our
        // conditions produce finite f32; if somehow NaN slips through we
        // fall back to an empty payload (the commitment will still be
        // deterministic for the same NaN — serde_json serializes NaN as null).
        if let Ok(bytes) = serde_json::to_vec(&self.verification_result) {
            hasher.update(&bytes);
        }

        hasher.update(b";diagnosis=");
        if let Some(d) = &self.diagnosis
            && let Ok(bytes) = serde_json::to_vec(d)
        {
            hasher.update(&bytes);
        }

        hasher.update(b";repairs_applied=");
        if let Ok(bytes) = serde_json::to_vec(&self.repairs_applied) {
            hasher.update(&bytes);
        }

        hasher.update(b";timestamp=");
        hasher.update(&self.timestamp.to_le_bytes());

        hasher.update(b";run_id=");
        hasher.update(self.run_id.as_bytes());

        let hash = hasher.finalize();
        let mut out = [0u8; 32];
        out.copy_from_slice(hash.as_bytes());
        out
    }

    /// Public recompute entry point (delegates to inner). Kept separate so
    /// future fields can be added to the commitment scope in one place.
    #[inline]
    pub fn compute_commitment(&self) -> [u8; 32] {
        self.compute_commitment_inner()
    }

    /// Verify that the stored commitment matches the current field values.
    ///
    /// Returns `true` iff the record has not been modified since the
    /// commitment was computed (i.e. since [`new`](Self::new) or
    /// [`with_repairs`](Self::with_repairs) was called).
    #[inline]
    pub fn verify(&self) -> bool {
        self.compute_commitment() == self.commitment
    }

    /// Recompute and store the commitment. Use after mutating fields that are
    /// in the commitment scope (e.g. editing `repairs_applied` in place).
    pub fn recommit(&mut self) {
        self.commitment = self.compute_commitment();
    }

    /// Serialize to a JSON file at `path`.
    ///
    /// Creates or truncates the file. Returns an error if the file cannot be
    /// written or serialization fails (e.g. non-finite float in a condition).
    pub fn export(&self, path: &Path) -> Result<(), ProvenanceError> {
        let json = serde_json::to_string_pretty(self).map_err(ProvenanceError::Serialize)?;
        std::fs::write(path, json).map_err(|e| ProvenanceError::Write {
            path: path.to_path_buf(),
            source: e,
        })
    }

    /// Load a provenance record from a JSON file.
    ///
    /// Verifies the commitment after deserialization. Returns
    /// [`ProvenanceError::Tampered`] if the stored commitment does not match
    /// the recomputed commitment over the file's contents.
    pub fn load(path: &Path) -> Result<Self, ProvenanceError> {
        let bytes = std::fs::read(path).map_err(|e| ProvenanceError::Read {
            path: path.to_path_buf(),
            source: e,
        })?;
        let record: Self =
            serde_json::from_slice(&bytes).map_err(|e| ProvenanceError::Deserialize {
                path: path.to_path_buf(),
                source: e,
            })?;
        if !record.verify() {
            return Err(ProvenanceError::Tampered {
                stored: record.commitment,
                recomputed: record.compute_commitment(),
            });
        }
        Ok(record)
    }

    /// Human-readable summary for logging.
    pub fn summary(&self) -> String {
        let mut lines = Vec::with_capacity(8);
        lines.push(format!("Run ID:        {}", self.run_id));
        lines.push(format!("Timestamp:     {}", self.timestamp));
        lines.push(format!("DAG hash:      {}", hex::encode(&self.dag_hash)));
        lines.push(format!(
            "Passed:        {}",
            if self.verification_result.passed {
                "YES"
            } else {
                "NO"
            }
        ));
        if let Some(d) = &self.diagnosis {
            lines.push(format!("Root cause:    {}", d.root_cause.summary()));
        } else {
            lines.push("Diagnosis:     n/a (run passed)".into());
        }
        let applied = self.repairs_applied.iter().filter(|r| r.applied).count();
        lines.push(format!(
            "Repairs:       {} applied, {} total",
            applied,
            self.repairs_applied.len()
        ));
        lines.push(format!("Commitment:    {}", hex::encode(&self.commitment)));
        lines.join("\n")
    }
}

impl std::error::Error for ProvenanceError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::Serialize(e) => Some(e),
            Self::Write { source, .. } => Some(source),
            Self::Read { source, .. } => Some(source),
            Self::Deserialize { source, .. } => Some(source),
            Self::Tampered { .. } => None,
        }
    }

mod hex {
    /// Encode a byte slice as lowercase hex. No allocation beyond the String.
    pub(crate) fn encode(bytes: &[u8]) -> String {
        const HEX: &[u8; 16] = b"0123456789abcdef";
        let mut out = String::with_capacity(bytes.len() * 2);
        for &b in bytes {
            out.push(HEX[(b >> 4) as usize] as char);
            out.push(HEX[(b & 0x0f) as usize] as char);
        }
        out
    }
}

impl TrainingRepairHint {
    /// Which step this hint applies to.
