        match self {
            Self::MissingData { step, .. }
            | Self::ConfigInvalid { step, .. }
            | Self::LossDidNotConverge { step, .. }
            | Self::KLExceeded { step, .. }
            | Self::RecoveryBelowThreshold { step, .. }
            | Self::MaskDimensionMismatch { step, .. } => step,
        }
    }

