            } => format!("[{step}] missing data '{missing_var}': {hint}"),
            Self::ConfigInvalid {
                step,
                field,
                expected,
            } => format!("[{step}] config '{field}' expected {expected}"),
            Self::LossDidNotConverge {
                step,
                final_loss,
                threshold,
                ..
            } => format!("[{step}] loss {final_loss:.4} > threshold {threshold:.4}"),
            Self::KLExceeded {
                step, actual_kl, ..
            } => format!("[{step}] KL {actual_kl:.4} exceeded leash"),
            Self::RecoveryBelowThreshold { step, actual, .. } => {
                format!("[{step}] recovery {actual:.4} below threshold")
            }
            Self::MaskDimensionMismatch { step, expected, .. } => {
                format!("[{step}] mask shape expected {expected:?}")
            }
        }
    }
