use serde::{Deserialize, Serialize};

use super::conditions::{ConditionResult, StepOutput, TrainingCondition, TrainingRunContext};
use super::dag::{StructuralResult, TrainingDAG};

// ── Semantic result ────────────────────────────────────────────────

/// A single semantic violation: a step's precondition was not entailed by
/// the accumulated postconditions of its predecessors.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct SemanticViolation {
    /// Name of the step whose precondition failed.
    pub step: String,
    /// The precondition that was not satisfied.
    pub missing: TrainingCondition,
    /// Conditions that were available at that point (for debugging).
    pub available: Vec<String>,
}

/// Result of semantic verification.
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
pub struct SemanticResult {
    /// `true` iff all preconditions are entailed by upstream postconditions.
    pub valid: bool,
    /// Violations (empty iff `valid`).
    pub violations: Vec<SemanticViolation>,
}

// ── Trajectory result ──────────────────────────────────────────────

/// Trajectory verification for a single step.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct StepTrajectoryResult {
    /// Step name.
    pub step_name: String,
    /// Per-precondition results (evaluated against accumulated context).
    pub preconditions_met: Vec<ConditionResult>,
    /// Per-postcondition results (evaluated against step output metrics).
    pub postconditions_met: Vec<ConditionResult>,
    /// `true` if the step was skipped because an upstream step failed.
    pub skipped: bool,
}

impl StepTrajectoryResult {
    /// `true` iff all preconditions AND postconditions passed and not skipped.
    pub fn passed(&self) -> bool {
        !self.skipped
            && self.preconditions_met.iter().all(|r| r.passed())
            && self.postconditions_met.iter().all(|r| r.passed())
    }

impl TrainingVerificationResult {
    /// Human-readable summary of the verification.
    pub fn summary(&self) -> String {
        let mut lines = Vec::new();
        lines.push(format!(
            "Overall: {}",
            if self.passed { "PASSED" } else { "FAILED" }
        ));
        lines.push(format!(
            "  Structural: {} ({} errors)",
            if self.structural.valid { "OK" } else { "FAIL" },
            self.structural.errors.len()
        ));
        if !self.structural.valid {
            for e in &self.structural.errors {
                lines.push(format!("    - {e}"));
            }
        }
        lines.push(format!(
            "  Semantic: {} ({} violations)",
            if self.semantic.valid { "OK" } else { "FAIL" },
            self.semantic.violations.len()
        ));
        for v in &self.semantic.violations {
            lines.push(format!("    - step '{}' missing precondition", v.step));
        }
        lines.push(format!(
            "  Trajectory: {} ({} steps)",
            if self.trajectory.valid { "OK" } else { "FAIL" },
            self.trajectory.step_results.len()
        ));
        for sr in &self.trajectory.step_results {
            let status = if sr.skipped {
                "SKIPPED"
            } else if sr.passed() {
                "PASSED"
            } else {
                "FAILED"
            };
            lines.push(format!("    - {}: {}", sr.step_name, status));
        }
        lines.join("\n")
    }
}

impl TrainingWorkflowVerifier {
    /// **T6**: Structural verification. Delegates to
    /// [`TrainingDAG::verify_structural`].
    pub fn verify_structural(
        &self,
        dag: &TrainingDAG,
        initial_inputs: &[&str],
    ) -> StructuralResult {
        dag.verify_structural(initial_inputs)
    }

    /// **T7**: Semantic verification — do each step's preconditions get
    /// entailed by the accumulated postconditions of upstream steps?
    ///
    /// We simulate the context propagation: start with `initial_context`,
    /// then for each step in topological order, check that every
    /// precondition evaluates to `Satisfied` against the current context,
    /// then add the step's writes to the context.
    ///
    /// Note: this does NOT check postconditions — postconditions are
    /// checked against actual step outputs in trajectory verification.
    /// Semantic verification only checks that the *declared* preconditions
    /// form a valid propagation chain.
    pub fn verify_semantic(
        &self,
        dag: &TrainingDAG,
        initial_context: &TrainingRunContext,
    ) -> SemanticResult {
        let order = match dag.step_order() {
            Ok(o) => o,
            Err(cycle) => {
                return SemanticResult {
                    valid: false,
                    violations: vec![SemanticViolation {
                        step: format!("<cycle: {cycle:?}>"),
                        missing: TrainingCondition::Deduplicated, // sentinel
                        available: vec![],
                    }],
                };
            }
        };

        let mut ctx = initial_context.clone();
        let mut violations = Vec::with_capacity(order.len());

        for &idx in &order {
            let step = &dag.steps[idx];
            let results = step.check_preconditions(&ctx);
            for (cond, result) in step.preconditions.iter().zip(results.iter()) {
                if !result.passed() {
                    violations.push(SemanticViolation {
                        step: step.name.clone(),
                        missing: cond.clone(),
                        available: ctx.produced.keys().cloned().collect(),
                    });
                }
            }
            // Propagate this step's writes.
            step.apply_postconditions(&mut ctx);
        }

        SemanticResult {
            valid: violations.is_empty(),
            violations,
        }
    }

    /// **T8**: Trajectory verification — check actual run results.
    ///
    /// `run.step_outputs` must be in the same order as `dag.steps`.
    /// For each step: evaluate preconditions against the accumulated
    /// context, then evaluate postconditions against the step's output.
    /// If a step fails, subsequent steps are marked `skipped`.
    pub fn verify_trajectory(&self, run: &TrainingRun, dag: &TrainingDAG) -> TrajectoryResult {
        let n = dag.steps.len();
        let mut step_results = Vec::with_capacity(n);
        let mut ctx = run.initial_context.clone();
        let mut upstream_failed = false;

        for i in 0..n {
            let step = &dag.steps[i];
            let output = run.step_outputs.get(i);

            if upstream_failed || output.is_none() {
                step_results.push(StepTrajectoryResult {
                    step_name: step.name.clone(),
                    preconditions_met: vec![],
                    postconditions_met: vec![],
                    skipped: true,
                });
                continue;
            }

            let out = output.unwrap();
            let pre_results = step.check_preconditions(&ctx);
            let post_results = step.check_postconditions(out);

            let step_passed = pre_results.iter().all(|r| r.passed())
                && post_results.iter().all(|r| r.passed())
                && out.success;

            if !step_passed {
                upstream_failed = true;
            }

            // Merge the step's metrics into the context so downstream
            // numeric preconditions can see them.
            for (k, v) in &out.metrics {
                ctx.metrics.insert(k.clone(), *v);
            }
            step.apply_postconditions(&mut ctx);

            step_results.push(StepTrajectoryResult {
                step_name: step.name.clone(),
                preconditions_met: pre_results,
                postconditions_met: post_results,
                skipped: false,
            });
        }

        let valid = step_results.iter().all(|s| !s.skipped && s.passed());
        TrajectoryResult {
            valid,
            step_results,
        }
    }

    /// Full verification pipeline: structural → semantic → trajectory.
    /// Returns the composite [`TrainingVerificationResult`].
    pub fn verify(
        &self,
        dag: &TrainingDAG,
        initial_inputs: &[&str],
        initial_context: &TrainingRunContext,
        run: Option<&TrainingRun>,
    ) -> TrainingVerificationResult {
        let structural = self.verify_structural(dag, initial_inputs);
        let semantic = self.verify_semantic(dag, initial_context);
        let trajectory = match run {
            Some(r) => self.verify_trajectory(r, dag),
            None => TrajectoryResult::default(),
        };
        let graph_hash = dag.graph_hash();
        let passed = structural.valid && semantic.valid && trajectory.valid;
        TrainingVerificationResult {
            passed,
            structural: StructuralSerializable::from(&structural),
            semantic,
            trajectory,
            graph_hash,
        }
    }
}

impl TrainingRun {
    /// Create a run with the given initial context and step outputs.
    pub fn new(initial_context: TrainingRunContext) -> Self {
