#[inline]
fn sigmoid(x: f32) -> f32 {
    crate::math::sigmoid_f32(x)
}

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

/// A single action within a game trajectory.
#[derive(Debug, Clone)]
pub struct TrajectoryAction {
    pub action_id: u64,
    pub pre_state_values: Vec<f32>,
    pub post_state_values: Vec<f32>,
    pub reward: f32,
    pub tick: u64,
}

/// Outcome of a complete game trajectory.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(u8)]
pub enum TrajectoryOutcome {
    Win = 0,
    Loss = 1,
    Draw = 2,
}

/// A complete game trajectory — sequence of actions with final outcome.
#[derive(Debug, Clone)]
pub struct GameTrajectory {
    pub actions: Vec<TrajectoryAction>,
    pub outcome: TrajectoryOutcome,
    pub total_reward: f32,
}

/// Why a particular action was flagged as a failure point.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(u8)]
pub enum FailureReason {
    PreconditionViolated = 0,
    PostconditionNotEstablished = 1,
    RewardBelowThreshold = 2,
}

/// A detected failure in a losing trajectory.
#[derive(Debug, Clone)]
pub struct FailurePoint {
    pub action_idx: usize,
    pub action_id: u64,
    pub reason: FailureReason,
    /// Sigmoid-scored severity ∈ (0, 1).
    pub severity: f32,
}

/// A training pair generated from failure analysis.
/// In production, `better_action` comes from DDTree sibling alternatives.
#[derive(Debug, Clone)]
pub struct TrainingPair {
    pub state: Vec<f32>,
    pub wrong_action: u64,
    pub better_action: u64,
    /// Confidence ∈ [0, 1] — how confident we are in this pair.
    pub confidence: f32,
}

// ---------------------------------------------------------------------------
// Analysis thresholds
// ---------------------------------------------------------------------------

/// Threshold below which state improvement is considered "not established".
/// If post_state has lower sum than pre_state by this ratio, postcondition fails.
const POST_IMPROVEMENT_MIN: f32 = 0.0;

/// Reward threshold multiplier: action reward must be at least this fraction
/// of the trajectory mean reward to not be flagged.
const REWARD_FLOOR_FACTOR: f32 = 0.5;

// ---------------------------------------------------------------------------
// Functions
// ---------------------------------------------------------------------------

/// Analyze a trajectory and find failure points.
///
/// Only analyzes LOSING trajectories — winning ones have no failures to learn from.
/// For each action, checks:
/// - **Precondition satisfaction**: state values must be non-negative (no critically low resources)
/// - **Postcondition establishment**: post-state should not regress from pre-state
/// - **Reward quality**: action reward should not be far below trajectory average
pub fn analyze_trajectory(trajectory: &GameTrajectory) -> Vec<FailurePoint> {
    // Only losing trajectories carry actionable failures.
    match trajectory.outcome {
        TrajectoryOutcome::Loss => {}
        TrajectoryOutcome::Win | TrajectoryOutcome::Draw => return Vec::new(),
    }

impl ViolationStats {
    fn record(&mut self, loss: f32) {
        self.prev_loss = self.current_loss;
        self.loss_sum += loss;
        self.count += 1;
        self.current_loss = loss;
    }

    #[allow(dead_code)]
    fn mean_loss(&self) -> f32 {
        match self.count {
            0 => 0.0,
            n => self.loss_sum / n as f32,
        }
    }

    fn improvement(&self) -> f32 {
        if self.count < 2 {
            return 0.0;
        }
        self.prev_loss - self.current_loss
    }
}

impl ConvergenceMetrics {
    /// Overall loss reduction across both violation types.
    pub fn total_loss_reduction(&self) -> f32 {
        (self.precondition_initial_loss - self.precondition_final_loss)
            + (self.postcondition_initial_loss - self.postcondition_final_loss)
    }
}

impl TrajectoryLoraFineTuner {
    /// Create a new fine-tuner with given LoRA weight dimension.
    ///
    /// `weight_dim` — number of LoRA weight parameters (must match state dimension).
    /// `violation_lr` — learning rate for predicate-violation pairs (default: 0.01).
    /// `baseline_lr` — learning rate for non-violation pairs (default: 0.001).
    pub fn new(weight_dim: usize, violation_lr: f32, baseline_lr: f32) -> Self {
        Self {
            violation_lr,
            baseline_lr,
            convergence_threshold: 1e-4,
            weights: vec![0.0; weight_dim],
            precondition_stats: ViolationStats::default(),
            postcondition_stats: ViolationStats::default(),
            step_count: 0,
            filtered_out_count: 0,
            initial_captured: false,
            precondition_initial_loss: 0.0,
            postcondition_initial_loss: 0.0,
        }
    }

    /// Create with default hyperparameters: violation_lr=0.01, baseline_lr=0.001.
    pub fn new_default(weight_dim: usize) -> Self {
        Self::new(weight_dim, 0.01, 0.001)
    }

    /// Process a batch of training pairs with their associated failure reasons.
    ///
    /// Only pairs with `PreconditionViolated` or `PostconditionNotEstablished` reasons
    /// are processed with the high learning rate. `RewardBelowThreshold` pairs are
    /// filtered out entirely (not predicate violations).
    ///
    /// Returns the number of pairs actually processed (not filtered).
    pub fn fine_tune_step(&mut self, pairs: &[TrainingPair], reasons: &[FailureReason]) -> usize {
        assert_eq!(
            pairs.len(),
            reasons.len(),
            "pairs and reasons must have same length"
        );

        let mut processed = 0;

        for (pair, reason) in pairs.iter().zip(reasons.iter()) {
            match reason {
                FailureReason::PreconditionViolated => {
                    let loss = self.compute_and_update(pair, self.violation_lr);
                    self.precondition_stats.record(loss);
                    processed += 1;
                }
                FailureReason::PostconditionNotEstablished => {
                    let loss = self.compute_and_update(pair, self.violation_lr);
                    self.postcondition_stats.record(loss);
                    processed += 1;
                }
                FailureReason::RewardBelowThreshold => {
                    // Not a predicate violation — filter out.
                    self.filtered_out_count += 1;
                }
            }

            // Capture initial losses on first step.
            if !self.initial_captured && processed > 0 {
                self.precondition_initial_loss = self.precondition_stats.current_loss;
                self.postcondition_initial_loss = self.postcondition_stats.current_loss;
                self.initial_captured = true;
            }
        }

        self.step_count += 1;
        processed
    }

    /// Whether the fine-tuner has converged (loss improvement below threshold).
    pub fn is_converged(&self) -> bool {
        let pre_imp = self.precondition_stats.improvement();
        let post_imp = self.postcondition_stats.improvement();
        // Converged when both violation types show negligible improvement.
        let pre_done =
            self.precondition_stats.count < 2 || pre_imp.abs() < self.convergence_threshold;
        let post_done =
            self.postcondition_stats.count < 2 || post_imp.abs() < self.convergence_threshold;
        pre_done && post_done
    }

    /// Generate a convergence report showing improvement metrics.
    pub fn convergence_report(&self) -> ConvergenceMetrics {
        ConvergenceMetrics {
            precondition_initial_loss: self.precondition_initial_loss,
            precondition_final_loss: self.precondition_stats.current_loss,
            postcondition_initial_loss: self.postcondition_initial_loss,
            postcondition_final_loss: self.postcondition_stats.current_loss,
            total_steps: self.step_count,
            pairs_processed: self.precondition_stats.count + self.postcondition_stats.count,
            pairs_filtered_out: self.filtered_out_count,
        }
    }

    /// Current simulated LoRA weights (for inspection).
    pub fn weights(&self) -> &[f32] {
        &self.weights
    }

    /// Current loss for precondition violations.
    #[inline]
    pub fn precondition_loss(&self) -> f32 {
        self.precondition_stats.current_loss
    }

    /// Current loss for postcondition violations.
    #[inline]
    pub fn postcondition_loss(&self) -> f32 {
        self.postcondition_stats.current_loss
    }

    // -----------------------------------------------------------------------
    // Internal
    // -----------------------------------------------------------------------

    /// Simulate a single LoRA weight update and return the resulting loss.
    ///
    /// Loss = MSE between state values and target (better_action projected onto state space).
    /// The weight update is: w_i += lr * (target_i - state_i) * state_i.
    fn compute_and_update(&mut self, pair: &TrainingPair, lr: f32) -> f32 {
        if pair.state.len() != self.weights.len() {
            // Dimension mismatch — skip update, return current loss estimate.
            return self.estimate_loss(pair);
        }

        // Simulated target: use better_action as a scaling factor on state.
        // In production, this would come from the DDTree sibling's actual state prediction.
        let scale = (pair.better_action as f32).max(1.0);
        let target: Vec<f32> = pair.state.iter().map(|&s| s * scale).collect();

        // Compute MSE loss before update.
        let loss = self.estimate_loss(pair);

        // Simulated gradient descent on LoRA weights.
        for (w, (&s, &t)) in self
            .weights
            .iter_mut()
            .zip(pair.state.iter().zip(target.iter()))
        {
            let gradient = 2.0 * (t - s) * s;
            *w += lr * gradient;
        }

        loss
    }

    /// Estimate loss as MSE between state and a target derived from better_action.
    fn estimate_loss(&self, pair: &TrainingPair) -> f32 {
        if pair.state.is_empty() {
            return 0.0;
        }
        let scale = (pair.better_action as f32).max(1.0);
        let mse: f32 = pair
            .state
            .iter()
            .map(|&s| {
                let t = s * scale;
                (t - s).powi(2)
            })
            .sum::<f32>()
            / pair.state.len() as f32;
        mse
    }
}

