impl TrltBufferLayout {
    /// Compute buffer layout for given sequence length and vocabulary size.
    pub fn new(seq_len: usize, vocab_size: usize) -> Self {
        Self {
            student_logits_bf16: BufferDescriptor::new(
                "student_logits",
                BufferDtype::Bf16,
                &[seq_len, vocab_size],
            ),
            teacher_logits_bf16: BufferDescriptor::new(
                "teacher_logits",
                BufferDtype::Bf16,
                &[seq_len, vocab_size],
            ),
            sdar_gates_f32: BufferDescriptor::new("sdar_gates", BufferDtype::F32, &[seq_len]),
            response_mask: BufferDescriptor::new("response_mask", BufferDtype::Bool, &[seq_len]),
            kl_accumulator: BufferDescriptor::new("kl_accumulator", BufferDtype::F32, &[1]),
        }
    }

    /// Total VRAM required for all buffers.
    pub fn total_bytes(&self) -> usize {
        self.student_logits_bf16.bytes
            + self.teacher_logits_bf16.bytes
            + self.sdar_gates_f32.bytes
            + self.response_mask.bytes
            + self.kl_accumulator.bytes
    }

    /// VRAM savings (MB) of yr training vs yo training.
    ///
    /// yr is ~9× shorter than yo, so peak VRAM is *lower*.
    /// Savings = (yo_seq_len - yr_seq_len) × vocab_size × 2 (bf16) / 1e6 MB.
    pub fn vram_savings_vs_yo(yo_seq_len: usize, yr_seq_len: usize, vocab_size: usize) -> f64 {
        let savings_elements = yo_seq_len.saturating_sub(yr_seq_len) * vocab_size;
        // Two bf16 logit buffers saved per token row
        let savings_bytes = savings_elements * 2usize * 2usize; // 2 buffers × 2 bytes/bf16
        savings_bytes as f64 / 1e6
    }
}

