impl TrltPhaseTracker {
    /// Create a new phase tracker with the given config.
    pub fn new(config: TrltPhaseConfig) -> Self {
        Self {
            config,
            phase: TrltTrainingPhase::Warmup,
            epoch_in_phase: 0,
            total_epochs: 0,
            best_warmup_loss: f64::MAX,
            loss_threshold_met: false,
        }
    }

    /// Create with default configuration.
    pub fn default_tracker() -> Self {
        Self::new(TrltPhaseConfig::default())
    }

    /// Get the current training phase.
    #[inline]
    pub fn phase(&self) -> TrltTrainingPhase {
        self.phase
    }

    /// Get the phase configuration.
    #[inline]
    pub fn config(&self) -> &TrltPhaseConfig {
        &self.config
    }

    /// Get the current epoch within the phase.
    #[inline]
    pub fn epoch_in_phase(&self) -> u32 {
        self.epoch_in_phase
    }

    /// Get the total epochs across all phases.
    #[inline]
    pub fn total_epochs(&self) -> u32 {
        self.total_epochs
    }

    /// Get the best warmup loss seen so far.
    #[inline]
    pub fn best_warmup_loss(&self) -> f64 {
        self.best_warmup_loss
    }

    /// Check if the loss threshold has been met.
    #[inline]
    pub fn loss_threshold_met(&self) -> bool {
        self.loss_threshold_met
    }

    /// Record a training step with the given loss value.
    ///
    /// Returns the (possibly updated) current phase after the step.
    /// Automatically transitions phases when conditions are met.
    pub fn step(&mut self, loss: f64) -> TrltTrainingPhase {
        self.total_epochs += 1;
        self.epoch_in_phase += 1;

        match self.phase {
            TrltTrainingPhase::Warmup => {
                // Track best loss
                if loss < self.best_warmup_loss {
                    self.best_warmup_loss = loss;
                }
                // Check loss threshold
                if loss < self.config.phase_switch_threshold {
                    self.loss_threshold_met = true;
                }
                // Switch to Refinement if both conditions met:
                // 1. Enough warmup epochs
                // 2. Loss below threshold at some point
                if self.epoch_in_phase >= self.config.phase1_epochs && self.loss_threshold_met {
                    self.transition_to(TrltTrainingPhase::Refinement);
                }
            }
            TrltTrainingPhase::Refinement => {
                // Switch to Complete after enough refinement epochs
                if self.epoch_in_phase >= self.config.phase2_epochs {
                    self.transition_to(TrltTrainingPhase::Complete);
                }
            }
            TrltTrainingPhase::Complete => {
                // No-op: training is done
            }
        }

        self.phase
    }

    /// Force a phase transition (for manual control or testing).
    ///
    /// Only allows forward transitions: Warmup → Refinement → Complete.
    /// Returns false if the transition is invalid.
    pub fn force_transition(&mut self, target: TrltTrainingPhase) -> bool {
        match (self.phase, target) {
            (TrltTrainingPhase::Warmup, TrltTrainingPhase::Refinement) => {
                self.transition_to(target);
                true
            }
            (TrltTrainingPhase::Refinement, TrltTrainingPhase::Complete) => {
                self.transition_to(target);
                true
            }
            (TrltTrainingPhase::Warmup, TrltTrainingPhase::Complete) => {
                self.transition_to(target);
                true
            }
            _ => false,
        }
    }

    /// Reset the tracker to initial state.
    pub fn reset(&mut self) {
        self.phase = TrltTrainingPhase::Warmup;
        self.epoch_in_phase = 0;
        self.total_epochs = 0;
        self.best_warmup_loss = f64::MAX;
        self.loss_threshold_met = false;
    }

    /// Check if BAKE regularization should be active (Phase 2 only).
    #[inline]
    pub fn should_apply_bake(&self) -> bool {
        matches!(self.phase, TrltTrainingPhase::Refinement)
    }

    /// Check if the bandit should be consulted for refinement depth (Phase 2 only).
    #[inline]
    pub fn should_consult_bandit(&self) -> bool {
        matches!(self.phase, TrltTrainingPhase::Refinement)
    }

    /// Get the BAKE weight for the current phase.
    #[inline]
    pub fn current_bake_weight(&self) -> f32 {
        if self.should_apply_bake() {
            self.config.bake_weight
        } else {
            0.0
        }
    }

    fn transition_to(&mut self, phase: TrltTrainingPhase) {
        log::info!(
            "TRLT phase transition: {:?} → {:?} at total_epoch={}",
            self.phase,
            phase,
            self.total_epochs
        );
        self.phase = phase;
        self.epoch_in_phase = 0;
    }
}

