impl ZeroQatCalibrator {
    /// Create a new calibrator with `n_groups` scale groups, all initialized to scale=1.0, zero_point=0.0.
    pub fn new(config: ZeroQatConfig, n_groups: usize) -> Self {
        let scales = (0..n_groups)
            .map(|group_idx| QuantScaleGroup {
                group_idx,
                scale: 1.0,
                zero_point: 0.0,
            })
            .collect();

        let calibration_steps = config.calibration_steps;

        Self {
            config,
            scales,
            step: 0,
            loss_history: Vec::with_capacity(calibration_steps),
        }
    }

    /// Estimate gradient via central finite differences.
    ///
    /// ```text
    /// gradient ≈ (loss(scale + ε) - loss(scale - ε)) / (2ε)
    /// ```
    ///
    /// `loss_fn` receives a perturbed scale value and returns the scalar loss.
    /// Only needs forward passes — same cost as inference.
    pub fn estimate_gradient(&self, group_idx: usize, loss_fn: &dyn Fn(f32) -> f32) -> f32 {
        match self.scales.get(group_idx) {
            None => 0.0,
            Some(group) => {
                let eps = self.config.perturbation_scale;
                let loss_plus = loss_fn(group.scale + eps);
                let loss_minus = loss_fn(group.scale - eps);
                (loss_plus - loss_minus) / (2.0 * eps)
            }
        }
    }

    /// Run one calibration step:
    /// 1. For each group, estimate gradient via finite differences
    /// 2. Update scale: `scale -= lr * gradient`
    /// 3. Clamp scale to valid range `[MIN_SCALE, MAX_SCALE]`
    ///
    /// Returns the loss value at the current scales before the update.
    pub fn calibrate_step(&mut self, loss_fn: &dyn Fn(&[QuantScaleGroup]) -> f32) -> f32 {
        let lr = self.config.learning_rate;
        let n_groups = self.scales.len();

        // Evaluate loss at current scales.
        let current_loss = loss_fn(&self.scales);
        self.loss_history.push(current_loss);

        // Estimate gradient and update each group.
        for i in 0..n_groups {
            // Capture current scale for the perturbed loss closure.
            let perturbed_loss =
                |group_idx: usize, delta: f32, scales: &[QuantScaleGroup]| -> f32 {
                    let mut perturbed = scales.to_vec();
                    if let Some(g) = perturbed.get_mut(group_idx) {
                        g.scale += delta;
                    }
                    loss_fn(&perturbed)
                };

            let eps = self.config.perturbation_scale;
            let loss_plus = perturbed_loss(i, eps, &self.scales);
            let loss_minus = perturbed_loss(i, -eps, &self.scales);
            let gradient = (loss_plus - loss_minus) / (2.0 * eps);

            // Gradient descent update.
            if let Some(group) = self.scales.get_mut(i) {
                group.scale -= lr * gradient;
                // Clamp to valid range.
                group.scale = group.scale.clamp(MIN_SCALE, MAX_SCALE);
            }
        }

        self.step += 1;
        current_loss
    }

    /// Run full calibration loop.
    ///
    /// Returns final loss value.
    pub fn calibrate(&mut self, loss_fn: &dyn Fn(&[QuantScaleGroup]) -> f32) -> f32 {
        let steps = self.config.calibration_steps;
        let mut final_loss = match self.loss_history.last() {
            Some(&l) => l,
            None => f32::MAX,
        };

        for _ in 0..steps {
            final_loss = self.calibrate_step(loss_fn);
        }

        final_loss
    }

    /// Check convergence: average loss change over last `window` steps < `threshold`.
    ///
    /// Returns `false` if loss history has fewer than `window + 1` entries.
    pub fn is_converged(&self, window: usize, threshold: f32) -> bool {
        let len = self.loss_history.len();
        match len {
            0 => false,
            n if n < window + 1 => false,
            _ => {
                let recent = &self.loss_history[len - window..];
                let mut total_change = 0.0f32;
                for i in 1..recent.len() {
                    total_change += (recent[i] - recent[i - 1]).abs();
                }
                let avg_change = total_change / (window as f32).max(1.0);
                avg_change < threshold
            }
        }
    }
}

