        &mut w_uk_grad_old,
        l,
    );
    backward_mla_loop_new(
        &saved,
        &d_attn_out_flat,
        &base_uv_all,
        &base_uk_all,
        &w_uk_cpu_per_head,
        &mut w_uv_grad_new,
        &mut w_uk_grad_new,
        l,
    );

    // ── G1: numerical equivalence check ──
    let uv_max = w_uv_grad_old
        .iter()
        .zip(w_uv_grad_new.iter())
        .map(|(a, b)| (a - b).abs())
        .fold(0.0f32, f32::max);
    let uk_max = w_uk_grad_old
        .iter()
        .zip(w_uk_grad_new.iter())
        .map(|(a, b)| (a - b).abs())
        .fold(0.0f32, f32::max);
    let uv_scale = w_uv_grad_old.iter().map(|x| x.abs()).fold(0.0f32, f32::max);
    let uk_scale = w_uk_grad_old.iter().map(|x| x.abs()).fold(0.0f32, f32::max);
    println!("=== G1: Numerical equivalence (old vs new) ===");
    println!("  w_uv: max_abs_diff={uv_max:.6} (scale={uv_scale:.4})");
    println!("  w_uk: max_abs_diff={uk_max:.6} (scale={uk_scale:.4})");
    let g1_pass =
        uv_max <= 1e-2 * uv_scale.max(1e-3) + 1e-3 && uk_max <= 1e-2 * uk_scale.max(1e-3) + 1e-3;
    println!("  G1: {}", if g1_pass { "PASS" } else { "FAIL" });

    // ── G2: performance comparison ──
    let n_iters = 3;
    println!("\n=== G2: Performance (l={l}, n_h={N_H}, d_c={D_C}, d_h={D_H}) ===");

    let t_old_start = std::time::Instant::now();
    for _ in 0..n_iters {
        backward_mla_loop_old(
            &saved,
            &d_attn_out_flat,
            &base_uv_all,
            &base_uk_all,
            &w_uk_cpu_per_head,
            &mut w_uv_grad_old,
            &mut w_uk_grad_old,
            l,
        );
    }
    let t_old = t_old_start.elapsed();

    let t_new_start = std::time::Instant::now();
    for _ in 0..n_iters {
        backward_mla_loop_new(
            &saved,
            &d_attn_out_flat,
            &base_uv_all,
            &base_uk_all,
            &w_uk_cpu_per_head,
            &mut w_uv_grad_new,
            &mut w_uk_grad_new,
            l,
        );
    }
    let t_new = t_new_start.elapsed();

    let old_ms = t_old.as_secs_f64() / n_iters as f64 * 1000.0;
    let new_ms = t_new.as_secs_f64() / n_iters as f64 * 1000.0;
    let speedup = old_ms / new_ms;
    println!("  OLD: {old_ms:.1} ms / iter");
    println!("  NEW: {new_ms:.1} ms / iter");
    println!("  Speedup: {speedup:.1}x");
    println!(
        "  G2 (>2x target): {}",
        if speedup >= 2.0 { "PASS" } else { "FAIL" }
    );

    // Also benchmark at l=256 (the dataset median).
    let l2 = 256;
    let saved2 = make_saved(l2, 0xDEAD_BEEF_CAFE_BABE);
    let d_attn2: Vec<f32> = (0..l2 * proj_size)
        .map(|i| ((i as u64).wrapping_mul(2654435761) >> 40) as f32 / (1 << 24) as f32 - 0.5)
        .collect();
    let base_uv2: Vec<Vec<f32>> = (0..N_H)
        .map(|h| {
            (0..l2 * D_C)
                .map(|i| {
                    ((i as u64 + h as u64 * 1000).wrapping_mul(2654435761) >> 40) as f32
                        / (1 << 24) as f32
                })
                .collect()
        })
        .collect();
    let base_uk2: Vec<Vec<f32>> = (0..N_H)
        .map(|h| {
            (0..l2 * D_C)
                .map(|i| {
                    ((i as u64 + h as u64 * 2000).wrapping_mul(2654435761) >> 40) as f32
                        / (1 << 24) as f32
                })
                .collect()
        })
        .collect();
    let mut wuv2 = vec![0.0f32; N_H * V_H * D_C];
    let mut wuk2 = vec![0.0f32; N_H * D_H * D_C];

    let t_old2 = {
        let s = std::time::Instant::now();
        for _ in 0..n_iters {
            backward_mla_loop_old(
                &saved2,
                &d_attn2,
                &base_uv2,
                &base_uk2,
                &w_uk_cpu_per_head,
                &mut wuv2,
                &mut wuk2,
                l2,
            );
        }
        s.elapsed()
    };
    let t_new2 = {
        let s = std::time::Instant::now();
        for _ in 0..n_iters {
            backward_mla_loop_new(
                &saved2,
                &d_attn2,
                &base_uv2,
                &base_uk2,
                &w_uk_cpu_per_head,
                &mut wuv2,
                &mut wuk2,
                l2,
            );
        }
        s.elapsed()
    };
    let old2_ms = t_old2.as_secs_f64() / n_iters as f64 * 1000.0;
    let new2_ms = t_new2.as_secs_f64() / n_iters as f64 * 1000.0;
    let speedup2 = old2_ms / new2_ms;
    println!("\n  l={l2}: OLD={old2_ms:.1}ms NEW={new2_ms:.1}ms Speedup={speedup2:.1}x");
}

