fn main() {
    // Config::game() — matches Plan 300 TJS-LoRA Bomber training workload.
    // seq_len = 170 (169 board cells + 1 action), vocab=10, n_embd=32, n_layer=1.
    let config = Config::game();
    let seq_len = config.block_size;

    eprintln!("Issue 016 chunk_size throughput sweep");
    // Print backend info from the first successful context.
    let probe_ctx = build_ctx(2);
    if let Some(ctx) = &probe_ctx {
        eprintln!("  backend:  {:?}", ctx.adapter_info.backend);
        eprintln!("  device:   {}", ctx.adapter_info.name);
    }
    eprintln!(
        "  config:   Config::game()  seq_len={seq_len}  n_embd={}  n_layer={}",
        config.n_embd, config.n_layer
    );
    eprintln!("  iters:    {ITERS} forward+backward passes per chunk_size");
    eprintln!();
    eprintln!(
        "  {:>10}  {:>14}  {:>14}  {:>10}  {:>10}",
        "chunk_size", "ms/iter", "submits/iter", "speedup", "verdict"
    );
    eprintln!("  {}", "-".repeat(70));

    // Deterministic token / target sequences (avoids RNG inside the hot loop).
    let tokens: Vec<usize> = (0..seq_len).map(|i| i % config.vocab_size).collect();
    let targets: Vec<usize> = (0..seq_len).map(|i| (i + 1) % config.vocab_size).collect();

    let mut baseline_ms_per_iter: Option<f32> = None;

    for &chunk_size in CHUNK_SIZES {
        let Some(ctx) = build_ctx(chunk_size) else {
            eprintln!("  {chunk_size:>10}  no GPU adapter");
            continue;
        };

        let mut rng = Rng::new(42);
        let weights = TransformerWeights::new(&config, &mut rng);
        let lora = GpuLoraBuffers::new(
            &ctx.device,
            &ctx.queue,
            &config,
            config.lora_rank,
            config.lora_alpha,
            &mut rng,
        );
        let pipelines = Arc::new(GpuPipelines::new(&ctx.device));

        let forward_pass = match GpuForwardPass::new(
            ctx.clone(),
            config.clone(),
            &weights,
            lora,
            seq_len,
        ) {
            Ok(fp) => fp,
            Err(e) => {
                eprintln!("  {chunk_size:>10}  FAILED to build forward pass: {e:?}");
                continue;
            }
        };
        let backward = GpuBackwardPass::new(ctx.clone(), config.clone(), Arc::clone(&pipelines));

        // Warmup: 1 iteration not counted in timing (first submit pays one-time
        // pipeline / shader compilation cost).
        if let Err(e) = forward_pass.forward(&tokens) {
            eprintln!("  {chunk_size:>10}  warmup forward FAILED: {e:?}  (Metal stall?)");
            continue;
        }
        if let Err(e) = backward.backward_pass(&forward_pass, &tokens, &targets) {
            eprintln!("  {chunk_size:>10}  warmup backward FAILED: {e:?}  (Metal stall?)");
            continue;
        }

        // Drain any pending GPU work so it doesn't bleed into iter 0 timing.
        // Downloading a small buffer forces a sync.
        let adapter = &forward_pass.lora.adapters[0];
        let _ = download_f32(
            &ctx.device,
            &ctx.queue,
            &adapter.grad_b,
            adapter.out_dim * adapter.rank,
        );

        let start = Instant::now();
        let mut last_err: Option<riir_gpu::GpuError> = None;
        for _ in 0..ITERS {
            if let Err(e) = forward_pass.forward(&tokens) {
                last_err = Some(e);
                break;
            }
            if let Err(e) =
                backward.backward_pass_accumulate(&forward_pass, &tokens, &targets, false)
            {
                last_err = Some(e);
                break;
            }
        }
        if let Some(e) = last_err {
            eprintln!("  {chunk_size:>10}  FAILED mid-iteration: {e:?}  (Metal stall?)");
            continue;
        }

        // Force a final sync so elapsed time includes all GPU work.
        let _ = download_f32(
            &ctx.device,
            &ctx.queue,
            &adapter.grad_b,
            adapter.out_dim * adapter.rank,
        );
        let elapsed = start.elapsed();
        let ms_per_iter = elapsed.as_secs_f32() * 1000.0 / ITERS as f32;

        let submits_per_iter = seq_len.div_ceil(chunk_size) * 2; // forward + backward
        let speedup = baseline_ms_per_iter.map_or(1.0, |b| b / ms_per_iter);
        if baseline_ms_per_iter.is_none() {
            baseline_ms_per_iter = Some(ms_per_iter);
        }

        let verdict = if chunk_size == 2 {
            "baseline"
        } else if speedup >= 1.5 {
            "use this"
        } else if speedup >= 1.1 {
            "marginal"
        } else {
            "no gain"
        };

        eprintln!(
            "  {chunk_size:>10}  {ms_per_iter:>10.2} ms   {submits_per_iter:>6}            {speedup:>6.2}x   {verdict}"
        );
    }

    eprintln!();
    eprintln!("Production usage:");
    eprintln!("  RIIR_GPU_CHUNK_SIZE=<best> cargo run --release -p riir-train-gpu \\");
    eprintln!("      --example train_bomber_tjs --features tjs_lora -- ...");
    eprintln!();
    eprintln!("Issue 016 acceptance criteria:");
    eprintln!("  - Smoke run (156 steps) < 5 min        needs ms/step < 1920 ms");
    eprintln!("  - Production (7800 steps) < 60 min/arm needs ms/step < 462 ms");
    eprintln!("  Per-step = batch_size x ms/sample (batch_size=32 in Plan 300).");
}

