impl ActionDistribution {
    fn from_samples(samples: &[GameSample]) -> Self {
        let mut counts = [0usize; 6];
        for s in samples {
            let idx = s.action as usize;
            if idx < 6 {
                counts[idx] += 1;
            }
        }
        Self {
            counts,
            total: samples.len(),
        }
    }

    fn fraction(&self, action: usize) -> f32 {
        if self.total == 0 {
            0.0
        } else {
            self.counts[action] as f32 / self.total as f32
        }
    }
}

