            .map(|s| format!("{}.dlat", s.to_string_lossy()))
            .unwrap_or_else(|| "domain_latent.dlat".to_string());
        let dlat_path = output_parent.join(&dlat_filename);

        match write_domain_latent(&dlat_path, kv_dim, &dl_params) {
            Ok(()) => {
                println!("✓ Saved domain latent → {}", dlat_path.display());
                println!();
                println!("  ✅ Domain latent training complete");
                println!();
                println!("  To use in riir-engine:");
                println!("    DomainLatent::load(\"{}\")", dlat_path.display(),);
            }
            Err(e) => {
                eprintln!("  ✗ Failed to write domain latent: {e}");
            }
        }
    }

    println!();
}

impl ActionConstraint {
    /// Ban exactly one action index (the `ban-one-action` primitive).
    #[must_use]
    pub fn ban_one(idx: usize) -> Self {
        Self::BanIds(vec![idx])
    }

    /// Ban an arbitrary set (sorted + deduped into canonical form).
    #[must_use]
    pub fn ban_ids(mut ids: Vec<usize>) -> Self {
        ids.sort_unstable();
        ids.dedup();
        if ids.is_empty() {
            Self::Unconstrained
        } else {
            Self::BanIds(ids)
        }
    }

    /// Ban the `k` highest-ranked entries of a **pre-measured** ranking —
    /// the `mask-top-k-actions` primitive, and the paper's "ban the dominant
    /// shortcut action self-play policies overfit to".
    ///
    /// The ranking is an INPUT, produced by [`ActionFrequency`] from a
    /// profiling pass over the arena. It is deliberately not read from live
    /// logits: [`ConstraintPruner::is_valid`] sees `(depth, idx, path)` and no
    /// policy scores, and a constraint that moves with the policy every step
    /// is not a per-task parameter a search can sweep. Measure, then fix, then
    /// sweep — that is what makes this a parameter and not a controller.
    #[must_use]
    pub fn ban_top_k(ranking: &[usize], k: usize) -> Self {
        Self::ban_ids(ranking.iter().copied().take(k).collect())
    }

    /// Number of banned indices.
    #[must_use]
    pub fn banned_count(&self) -> usize {
        match self {
            Self::Unconstrained => 0,
            Self::BanIds(ids) => ids.len(),
        }
    }

    /// Short canonical label for tables/logs.
    #[must_use]
    pub fn label(&self) -> String {
        match self {
            Self::Unconstrained => "none".to_string(),
            Self::BanIds(ids) if ids.len() <= 3 => {
                format!("ban{:?}", ids)
            }
            Self::BanIds(ids) => format!("ban×{}", ids.len()),
        }
    }
}

impl ConstraintPruner for ActionConstraint {
    /// `depth` and `parent_tokens` are unused: these constraints are
    /// per-TASK parameters (fixed for the episode), which is exactly the
    /// EnvHarness Rule's shape. A path-dependent constraint is expressible
    /// through the same trait — that is why the DSL compiles to
    /// `ConstraintPruner` rather than to a bare `HashSet`.
    fn is_valid(&self, _depth: usize, token_idx: usize, _parent_tokens: &[usize]) -> bool {
        match self {
            Self::Unconstrained => true,
            Self::BanIds(ids) => ids.binary_search(&token_idx).is_err(),
        }
    }
}

impl FilterReport {
    /// Fraction of the action space removed (0.0 when it fell back).
    #[must_use]
    pub fn pruned_fraction(&self) -> f32 {
        match self.legal_before {
            0 => 0.0,
            n => 1.0 - (self.legal_after as f32 / n as f32),
        }
    }
}

impl BranchingProfile {
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    /// Record one filtered step. `state` feeds the shipped log (the before
    /// half); `report` feeds the after half.
    pub fn record<S: GameState>(&mut self, state: &S, player: u8, report: FilterReport) {
        self.log.record(state, player);
        self.before_sum += f64::from(report.legal_before as u32);
        self.after_sum += f64::from(report.legal_after as u32);
        self.after_count += 1;
        if report.fell_back {
            self.fallbacks += 1;
        }
    }

    /// Mean legal-action count the env OFFERED. Authoritative (f64) — see the
    /// struct doc on why this does not read `ActionSpaceLog::avg_action_space`.
    #[must_use]
    pub fn mean_before(&self) -> f64 {
        match self.after_count {
            0 => 0.0,
            n => self.before_sum / n as f64,
        }
    }

    /// The shipped log's own mean, kept for comparison. Drifts low past ~2^24
    /// accumulated actions (katgpt-rs Issue 690) — do not report this as the branching
    /// factor; use [`Self::mean_before`].
    #[must_use]
    pub fn log_mean_before(&self) -> f32 {
        self.log.avg_action_space()
    }

    /// Mean legal-action count the policy actually saw.
    #[must_use]
    pub fn mean_after(&self) -> f64 {
        match self.after_count {
            0 => 0.0,
            n => self.after_sum / n as f64,
        }
    }

    /// Fraction of the offered action space the constraint removed, from the
    /// f64 accumulators. Exactly 0.0 for an unconstrained run.
    #[must_use]
    pub fn pruned_fraction(&self) -> f64 {
        let before = self.mean_before();
        match before {
            b if b <= 0.0 => 0.0,
            b => 1.0 - self.mean_after() / b,
        }
    }

    /// Steps where the constraint pruned everything and was rolled back.
    #[must_use]
    pub fn fallbacks(&self) -> usize {
        self.fallbacks
    }

    #[must_use]
    pub fn steps(&self) -> usize {
        self.after_count
    }
}

impl ActionFrequency {
    #[must_use]
    pub fn with_action_count(n: usize) -> Self {
        Self {
            counts: vec![0; n],
            total: 0,
        }
    }

    /// Count one chosen action index (grows the table if the space is larger
    /// than declared).
    pub fn observe(&mut self, idx: usize) {
        if idx >= self.counts.len() {
            self.counts.resize(idx + 1, 0);
        }
        self.counts[idx] += 1;
        self.total += 1;
    }

    #[must_use]
    pub fn total(&self) -> u64 {
        self.total
    }

    #[must_use]
    pub fn count(&self, idx: usize) -> u64 {
        self.counts.get(idx).copied().unwrap_or(0)
    }

    /// Share of all observations taken by `idx`.
    #[must_use]
    pub fn share(&self, idx: usize) -> f32 {
        match self.total {
            0 => 0.0,
            t => self.count(idx) as f32 / t as f32,
        }
    }

    /// Action indices, most-frequent first. Ties broken by ascending index.
    /// Zero-count actions are included at the tail so `ban_top_k` always has
    /// `k` entries to take.
    #[must_use]
    pub fn ranking(&self) -> Vec<usize> {
        let mut idx: Vec<usize> = (0..self.counts.len()).collect();
        idx.sort_by(|&a, &b| self.counts[b].cmp(&self.counts[a]).then(a.cmp(&b)));
        idx
    }
}

