// ── Route pairing guard (Issue 486) ────────────────────────────────
/// Whether [`GpuBackwardPass::backward_pass`] auto-routes to the **batched**
/// path. Mirrors [`riir_gpu::forward::FORWARD_ROUTE_IS_BATCHED`]; keep the
/// expression in sync with the `cfg` guards in `backward_pass` and
/// `backward_pass_accumulate`.
pub const BACKWARD_ROUTE_IS_BATCHED: bool = cfg!(all(
    feature = "gpu_batched_forward",
    not(any(
        feature = "moa_training",
        feature = "oft_training",
        feature = "speft_training",
        feature = "dllm",
        feature = "gdsd_loss",
        feature = "interventional_sft",
    ))
));

// Issue 486: the forward and backward routes MUST match. The batched forward
// populates batched saved buffers that only the batched backward reads, and the
// per-position backward reads per-position buffers the batched forward never
// writes — a mismatched pair runs clean and leaves every LoRA gradient at
// exactly zero, so training is a silent no-op at any learning rate and every
// `train_toy` smoke test still "passes".
//
// The two routes are selected by the same cfg expression but over DIFFERENT
// feature sets: `feature = "gpu_batched_forward"` here reads this crate's flag,
// while the forward reads riir-gpu's independent same-named flag. Those two
// disagreed for the whole life of the feature — riir-gpu has it in `default`,
// this crate did not — so a plain `cargo build -p riir-train-gpu` produced the
// broken pair. Aligning this crate's `default` fixed the symptom; this assert
// is what makes the class impossible to reintroduce, because a divergence now
// fails the BUILD instead of the training run.
//
// If this fires: enable/disable `gpu_batched_forward` on BOTH crates, or check
// whether an extension feature (moa/oft/speft/dllm/gdsd/interventional_sft)
// was added on one side only — each of those flips both routes to per-position
// and every one of them forwards to riir-gpu, which is why they are safe.
const _: () = assert!(
    BACKWARD_ROUTE_IS_BATCHED == riir_gpu::forward::FORWARD_ROUTE_IS_BATCHED,
    "Issue 486: forward/backward route mismatch — the batched forward and the \
     per-position backward (or vice versa) do not share saved buffers, so LoRA \
     gradients would be silently zero. Align the `gpu_batched_forward` feature \
     between riir-gpu and riir-train-gpu."
);

