// ── Public types ───────────────────────────────────────────────────

/// Multi-stage filter for preference pairs.
///
/// Removes low-quality pairs that would harm DPO training:
/// - Reward hacking (verbose hints, repetitive outputs)
/// - Template leakage (role markers in responses)
/// - Distribution mismatch (echo responses, extreme length ratios)
///
/// All thresholds are configurable for domain-specific tuning.
///
/// Fields ordered by alignment: usize first, then f32 pairs.
#[derive(Debug, Clone)]
pub struct DeltaFilter {
    /// Maximum chosen response length in characters. Default: 10_000
    pub chosen_max_chars: usize,
    /// Minimum chosen response length in characters. Default: 100
    pub chosen_min_chars: usize,
    /// Number of characters to check for prompt echo. Default: 30
    pub echo_prefix_len: usize,
    /// Percentile range for δ retention (low, high). Default: (0.0, 0.5)
    /// Lower half retention: pairs where hints helped most.
    pub delta_percentile: (f32, f32),
    /// Maximum chosen/rejected length ratio. Default: 2.5
    /// Prevents length-inflation reward hacking.
    pub length_ratio_max: f32,
    /// Minimum zlib compression ratio. Default: 0.15
    /// Low ratio indicates repetitive content (e.g., "ha ha ha ha...").
    pub zlib_threshold: f32,
}

impl DeltaFilter {
    pub fn new() -> Self {
        Self::default()
    }

    /// Filter preference pairs in-place through all stages.
    ///
    /// # Arguments
    /// - `pairs`: mutable vector of preference pairs to filter
    /// - `all_deltas`: all delta values from the round (for percentile computation)
    ///
    /// # Returns
    /// `FilterStats` with counts of pairs removed at each stage.
    pub fn filter(&self, pairs: &mut Vec<PreferencePair>, all_deltas: &[f32]) -> FilterStats {
        let initial_count = pairs.len();
        let mut stats = FilterStats {
            initial_count,
            ..Default::default()
        };

        // Stage 1: δ percentile filter
        let before = pairs.len();
        let mut scratch = Vec::with_capacity(all_deltas.len());
        let (d_low, d_high) = self.delta_bounds(all_deltas, &mut scratch);
        pairs.retain(|p| p.delta >= d_low && p.delta <= d_high);
        stats.delta_percentile_removed = before - pairs.len();

        // Stage 2: Length quality (min/max)
        let before = pairs.len();
        pairs.retain(|p| {
            let len = p.chosen.len();
            len >= self.chosen_min_chars && len <= self.chosen_max_chars
        });
        stats.length_quality_removed = before - pairs.len();

        // Stage 3: Length ratio (chosen/rejected)
        let before = pairs.len();
        let ratio_max = self.length_ratio_max;
        pairs.retain(|p| {
            let rejected_len = p.rejected.len().max(1);
            (p.chosen.len() as f32 / rejected_len as f32) <= ratio_max
        });
        stats.length_ratio_removed = before - pairs.len();

        // Stage 4: Zlib repetition filter
        let before = pairs.len();
        let threshold = self.zlib_threshold;
        pairs.retain(|p| zlib_ratio(&p.chosen) >= threshold);
        stats.zlib_repetition_removed = before - pairs.len();

        // Stage 5: Prompt echo filter
        let before = pairs.len();
        let prefix_len = self.echo_prefix_len;
        pairs.retain(|p| {
            let prefix_end = prefix_len.min(p.query.len());
            if prefix_end == 0 {
                return true;
            }
            let query_prefix = &p.query[..prefix_end];
            !p.chosen.starts_with(query_prefix)
        });
        stats.echo_removed = before - pairs.len();

        // Stage 6: Role marker filter
        let before = pairs.len();
        pairs.retain(|p| !contains_role_markers(&p.chosen) && !contains_role_markers(&p.rejected));
        stats.role_marker_removed = before - pairs.len();

        stats.final_count = pairs.len();
        stats.total_removed = stats.initial_count - stats.final_count;
        stats
    }

    /// Filter preference pairs with a caller-provided scratch buffer.
    ///
    /// Same as [`filter`](Self::filter) but reuses `scratch` across calls to avoid
    /// per-call allocation of the delta percentile buffer. The scratch buffer
    /// grows as needed but never shrinks.
    ///
    /// Use this variant in training loops where `filter` is called every round.
    pub fn filter_with_scratch(
        &self,
        pairs: &mut Vec<PreferencePair>,
        all_deltas: &[f32],
        scratch: &mut Vec<f32>,
    ) -> FilterStats {
        let initial_count = pairs.len();
        let mut stats = FilterStats {
            initial_count,
            ..Default::default()
        };

        // Stage 1: δ percentile filter — reuses scratch buffer
        let before = pairs.len();
        let (d_low, d_high) = self.delta_bounds(all_deltas, scratch);
        pairs.retain(|p| p.delta >= d_low && p.delta <= d_high);
        stats.delta_percentile_removed = before - pairs.len();

        // Stages 2-6: identical to filter()
        let before = pairs.len();
        pairs.retain(|p| {
            let len = p.chosen.len();
            len >= self.chosen_min_chars && len <= self.chosen_max_chars
        });
        stats.length_quality_removed = before - pairs.len();

        let before = pairs.len();
        let ratio_max = self.length_ratio_max;
        pairs.retain(|p| {
            let rejected_len = p.rejected.len().max(1);
            (p.chosen.len() as f32 / rejected_len as f32) <= ratio_max
        });
        stats.length_ratio_removed = before - pairs.len();

        let before = pairs.len();
        let threshold = self.zlib_threshold;
        pairs.retain(|p| zlib_ratio(&p.chosen) >= threshold);
        stats.zlib_repetition_removed = before - pairs.len();

        let before = pairs.len();
        let prefix_len = self.echo_prefix_len;
        pairs.retain(|p| {
            let prefix_end = prefix_len.min(p.query.len());
            if prefix_end == 0 {
                return true;
            }
            let query_prefix = &p.query[..prefix_end];
            !p.chosen.starts_with(query_prefix)
        });
        stats.echo_removed = before - pairs.len();

        let before = pairs.len();
        pairs.retain(|p| !contains_role_markers(&p.chosen) && !contains_role_markers(&p.rejected));
        stats.role_marker_removed = before - pairs.len();

        stats.final_count = pairs.len();
        stats.total_removed = stats.initial_count - stats.final_count;
        stats
    }

    /// Compute delta bounds from percentiles of all deltas.
    fn delta_bounds(&self, all_deltas: &[f32], scratch: &mut Vec<f32>) -> (f32, f32) {
        if all_deltas.is_empty() {
            return (0.0, f32::MAX);
        }

        // Reuse caller-provided scratch buffer instead of allocating per call.
        scratch.clear();
        scratch.extend_from_slice(all_deltas);
        let n = scratch.len();
        let cmp = |a: &f32, b: &f32| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal);

        // select_nth_unstable_by: O(n) average per call vs O(n log n) full sort
        let low_idx = (self.delta_percentile.0.clamp(0.0, 1.0) * (n - 1) as f32).round() as usize;
        let low_idx = low_idx.min(n - 1);
        scratch.select_nth_unstable_by(low_idx, cmp);
        let d_low = scratch[low_idx];

        let high_idx = (self.delta_percentile.1.clamp(0.0, 1.0) * (n - 1) as f32).round() as usize;
        let high_idx = high_idx.min(n - 1);
        scratch.select_nth_unstable_by(high_idx, cmp);
        let d_high = scratch[high_idx];

        (d_low, d_high)
    }

    /// Apply only the zlib repetition filter (for standalone use).
    pub fn filter_zlib_only(&self, text: &str) -> bool {
        zlib_ratio(text) >= self.zlib_threshold
    }

    /// Apply only the role marker filter (for standalone use).
    pub fn filter_role_markers_only(text: &str) -> bool {
        !contains_role_markers(text)
    }
}

