/// Game types supported by the replay training pipeline.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
#[repr(u8)]
pub enum ReplayGameType {
    Bomber,
    Go,
}

impl ReplayGameType {
    /// All supported game types.
    pub const ALL: [ReplayGameType;

impl ReplayFormat {
    /// Detect format from file extension.
    pub fn from_path(path: &Path) -> Option<Self> {
        let name = path.file_name()?.to_str()?;
        // Order matters: check more specific extensions first
        if name.ends_with(".go.jsonl") {
            return Some(ReplayFormat::GoJsonl);
        }
        if name.ends_with(".flat.zip") {
            return Some(ReplayFormat::GoFlatZip);
        }
        if name.ends_with(".jsonl") {
            return Some(ReplayFormat::BomberJsonl);
        }
        if name.ends_with(".json") {
            // Heuristic: Go JSON files contain move records
            return Some(ReplayFormat::GoJson);
        }
        None
    }

    /// Which game type this format belongs to.
    pub fn game_type(&self) -> ReplayGameType {
        match self {
            ReplayFormat::BomberJsonl => ReplayGameType::Bomber,
            ReplayFormat::GoJson | ReplayFormat::GoJsonl | ReplayFormat::GoFlatZip => {
                ReplayGameType::Go
            }
        }
    }

    /// Human-readable format name.
    pub fn name(&self) -> &'static str {
        match self {
            ReplayFormat::BomberJsonl => "Bomber JSONL",
            ReplayFormat::GoJson => "Go JSON",
            ReplayFormat::GoJsonl => "Go JSONL",
            ReplayFormat::GoFlatZip => "Go FlatZip",
        }
    }
}

impl ReplayFilter {
    /// Accept everything.
    pub fn accept_all() -> Self {
        Self {
            min_quality: 0.0,
            max_quality: 1.0,
            player_types: Vec::new(),
            max_samples: None,
        }
    }

    /// Only high-quality samples (quality > 0.5).
    pub fn high_quality() -> Self {
        Self {
            min_quality: 0.5,
            ..Self::accept_all()
        }
    }

    /// Check if a quality score passes the filter.
    pub fn passes_quality(&self, quality: f32) -> bool {
        quality >= self.min_quality && quality <= self.max_quality
    }

    /// Check if a player type passes the filter (empty list = accept all).
    pub fn passes_player_type(&self, player_type: &str) -> bool {
        self.player_types.is_empty() || self.player_types.iter().any(|p| p == player_type)
    }

    /// Check if the sample count limit has been reached.
    pub fn at_limit(&self, count: u64) -> bool {
        self.max_samples.is_some_and(|max| count >= max)
    }
}

impl ReplayManifest {
    /// Scan a directory for replay files, auto-detecting formats.
    ///
    /// Returns manifests sorted by path. Non-replay files are silently skipped.
    pub fn scan_dir(dir: &Path) -> Vec<Self> {
        let Ok(entries) = std::fs::read_dir(dir) else {
            return Vec::new();
        };

        let mut manifests: Vec<Self> = entries
            .filter_map(|entry| entry.ok())
            .filter_map(|entry| {
                let path = entry.path();
                let format = ReplayFormat::from_path(&path)?;
                Some(Self {
                    format,
                    path,
                    sample_count: None,
                    blake3_hash: None,
                })
            })
            .collect();

        manifests.sort_by(|a, b| a.path.cmp(&b.path));
        manifests
    }

    /// Compute BLAKE3 hash of the file contents.
    ///
    /// Returns the hex-encoded hash string. Used for integrity verification
    /// against a manifest sidecar file.
    pub fn compute_hash(&mut self) -> std::io::Result<String> {
        let mut file = std::fs::File::open(&self.path)?;
        let mut hasher = blake3::Hasher::new();
        let mut buf = [0u8; 8192];
        loop {
            let n = file.read(&mut buf)?;
            if n == 0 {
                break;
            }
            hasher.update(&buf[..n]);
        }
        let hash = hasher.finalize().to_hex().to_string();
        self.blake3_hash = Some(hash.clone());
        Ok(hash)
    }

    /// Verify file integrity against a stored BLAKE3 hash.
    ///
    /// Returns Ok(()) if hash matches, Err if mismatch or missing.
    pub fn verify(&mut self, expected: &str) -> std::io::Result<()> {
        let actual = self.compute_hash()?;
        if actual == expected {
            Ok(())
        } else {
            Err(std::io::Error::new(
                std::io::ErrorKind::InvalidData,
                format!(
                    "BLAKE3 mismatch for {}: expected {}, got {}",
                    self.path.display(),
                    expected,
                    actual
                ),
            ))
        }
    }

    /// Count samples in the file without converting them.
    ///
    /// For JSONL: counts lines. For Go JSON: counts moves. For FlatZip: reads header.
    pub fn count_samples(&mut self) -> std::io::Result<u64> {
        let count = match self.format {
            ReplayFormat::BomberJsonl | ReplayFormat::GoJsonl => count_jsonl_lines(&self.path)?,
            ReplayFormat::GoJson => {
                // Go JSON is one object — count moves inside it
                count_go_json_moves(&self.path)?
            }
            ReplayFormat::GoFlatZip => {
                // FlatZip: not counting without loading, mark unknown
                0
            }
        };
        self.sample_count = Some(count);
        Ok(count)
    }
}

