/// GDSD training mode for dLLM self-play rounds.
///
/// Controls when GDSD squared logit matching replaces DPO in the
/// GZeroLoop round pipeline. GDSD is the D2F-native loss — no softmax,
/// no log-softmax, just squared error on centralized logits.
///
/// DPO remains the default for autoregressive models; GDSD is only
/// activated when the model uses discrete diffusion (dLLM) architecture.
#[cfg(feature = "gdsd_loss")]
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub enum GdsdMode {
    /// Standard DPO for autoregressive models (default).
    /// Phase 2 uses preference-pair DPO training.
    #[default]
    Dpo,
    /// GDSD replaces DPO for dLLM self-play training.
    /// Phase 2 uses squared logit matching with TLC instead of DPO.
    /// Requires `gdsd_config` to be set on GZeroLoop.
    Gdsd,
}

