/// RecFM curriculum schedule for G-Zero self-play (Plan 185 T1).
///
/// Inspired by Recursive Flow Matching (RecFM, arXiv:2605.26535v1):
/// the scale parameter α attenuates the model's confidence signal during
/// early self-play rounds, producing a natural curriculum:
/// - Low α (e.g. 0.3): model explores "general direction" of good play
/// - High α (e.g. 1.0): model plays at full strength
///
/// The schedule is linear by default. RecFM Theorem 3.1 implies that
/// training across multiple α levels produces smoother action distributions
/// (lower trajectory curvature in action-probability space).
///
/// **Usage:** Set `recfm_schedule` on `GZeroRound` to enable. When `None`,
/// α=1.0 for all rounds (no curriculum, backward-compatible).
#[allow(dead_code)]
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RecfmSchedule {
    /// Starting α for round 0. Default: 0.3
    pub alpha_start: f32,
    /// Ending α for the final round. Default: 1.0
    pub alpha_end: f32,
    /// Total number of curriculum rounds.
    /// After `total_rounds`, α stays at `alpha_end`.
    pub total_rounds: usize,
}

impl Default for RecfmSchedule {
    fn default() -> Self {
        Self {
            alpha_start: 0.3,
            alpha_end: 1.0,
            total_rounds: 1000,
        }
    }

#[allow(dead_code)]
impl RecfmSchedule {
    /// Create a new schedule with custom start/end.
    pub fn new(alpha_start: f32, alpha_end: f32, total_rounds: usize) -> Self {
        Self {
            alpha_start,
            alpha_end,
            total_rounds: total_rounds.max(1),
        }
    }

impl GZeroRound {
    pub fn new(round: usize) -> Self {
        Self {
            round,
            ..Default::default()
        }
    }

    /// Compute the RecFM curriculum α for the given round.
    ///
    /// Returns 1.0 when no RecFM schedule is configured (backward-compatible).
    /// When configured, delegates to `RecfmSchedule::alpha(round)`.
    ///
    /// The returned α should be used to scale model confidence during
    /// action selection: `softmax(logits / temperature * alpha)`.
    /// At α=1.0, normal temperature. At α<1.0, effectively higher
    /// temperature → more exploration → easier curriculum.
    #[cfg(feature = "recfm_loss")]
    pub fn alpha_for_round(&self, round: usize) -> f32 {
        match &self.recfm_schedule {
            Some(schedule) => schedule.alpha(round),
            None => 1.0,
        }
    }

    /// RecFM α for the current round (convenience wrapper).
    /// Uses `self.round` as the round number.
    #[cfg(feature = "recfm_loss")]
    pub fn current_alpha(&self) -> f32 {
        self.alpha_for_round(self.round)
    }

    /// Whether this round uses GDSD instead of DPO for Phase 2.
    /// Returns false when the `gdsd_loss` feature is not enabled.
    #[cfg(feature = "gdsd_loss")]
    pub fn is_gdsd(&self) -> bool {
        self.gdsd_mode == GdsdMode::Gdsd
    }

    #[cfg(not(feature = "gdsd_loss"))]
    pub fn is_gdsd(&self) -> bool {
        false
    }
}

