/// GPU uniform params for DPO loss kernels.
/// Layout must match `dpo_loss.wgsl::DpoParams` exactly.
#[repr(C)]
#[derive(Clone, Copy, bytemuck::Pod, bytemuck::Zeroable)]
struct DpoParams {
    num_pairs: u32,
    seq_len: u32,
    beta: f32,
    _pad: u32,
}

// ── Public types ───────────────────────────────────────────────────

/// Length-normalized DPO-sigmoid loss configuration.
///
/// L = -E[log σ(β·(r̄_chosen - r̄_rejected))]
/// where r̄ = dot(logπθ - logπref, mask) / mask_sum
///
/// The length normalization prevents the gradient from favoring longer responses.
/// Default β=2.0 is lower than typical DPO because the chosen/rejected gap is small
/// (both are responses to the same query, differing only by hint assistance).
pub struct LengthNormalizedDpo {
    /// KL penalty coefficient. Default: 2.0
    pub beta: f32,
}

impl Default for LengthNormalizedDpo {
    fn default() -> Self {
        Self { beta: 2.0 }
    }

impl LengthNormalizedDpo {
    /// Create with default hyperparameters.
    pub fn new() -> Self {
        Self::default()
    }

    /// Compute DPO loss from per-token log-probabilities (CPU reference).
    ///
    /// # Arguments
    /// - `policy_chosen`: per-token log πθ(chosen_t | q), shape `[seq_len]`
    /// - `policy_rejected`: per-token log πθ(rejected_t | q), shape `[seq_len]`
    /// - `ref_chosen`: per-token log πref(chosen_t | q), shape `[seq_len]`
    /// - `ref_rejected`: per-token log πref(rejected_t | q), shape `[seq_len]`
    /// - `chosen_mask`: 1.0 for response tokens, 0.0 for prompt, shape `[seq_len]`
    /// - `rejected_mask`: same layout as chosen_mask, shape `[seq_len]`
    ///
    /// # Returns
    /// (scalar_loss, DpoMetrics)
    pub fn loss(
        &self,
        policy_chosen: &[f32],
        policy_rejected: &[f32],
        ref_chosen: &[f32],
        ref_rejected: &[f32],
        chosen_mask: &[f32],
        rejected_mask: &[f32],
    ) -> (f32, DpoMetrics) {
        let chosen_ratio = Self::norm_ratio(policy_chosen, ref_chosen, chosen_mask);
        let rejected_ratio = Self::norm_ratio(policy_rejected, ref_rejected, rejected_mask);

        let logits = self.beta * (chosen_ratio - rejected_ratio);
        let loss = -log_sigmoid(logits);

        let margin = logits;
        let accuracy = if chosen_ratio > rejected_ratio {
            1.0f32
        } else {
            0.0f32
        };

        let metrics = DpoMetrics {
            loss,
            accuracy,
            margin,
            chosen_reward: self.beta * chosen_ratio,
            rejected_reward: self.beta * rejected_ratio,
        };

        (loss, metrics)
    }

    /// Compute DPO loss for a batch of pairs (CPU reference).
    ///
    /// All slices are flat: [num_pairs × seq_len] in row-major order.
    /// Returns mean loss and aggregate metrics across the batch.
    pub fn loss_batch(&self, input: &DpoBatchInput) -> (f32, DpoMetrics) {
        let mut total_loss = 0.0f32;
        let mut total_accuracy = 0.0f32;
        let mut total_margin = 0.0f32;
        let mut total_chosen_reward = 0.0f32;
        let mut total_rejected_reward = 0.0f32;

        for i in 0..input.num_pairs {
            let offset = i * input.seq_len;
            let seq = input.seq_len;
            let (pair_loss, metrics) = self.loss(
                &input.policy_chosen[offset..offset + seq],
                &input.policy_rejected[offset..offset + seq],
                &input.ref_chosen[offset..offset + seq],
                &input.ref_rejected[offset..offset + seq],
                &input.chosen_mask[offset..offset + seq],
                &input.rejected_mask[offset..offset + seq],
            );
            total_loss += pair_loss;
            total_accuracy += metrics.accuracy;
            total_margin += metrics.margin;
            total_chosen_reward += metrics.chosen_reward;
            total_rejected_reward += metrics.rejected_reward;
        }

        let n = input.num_pairs as f32;
        let metrics = DpoMetrics {
            loss: total_loss / n,
            accuracy: total_accuracy / n,
            margin: total_margin / n,
            chosen_reward: total_chosen_reward / n,
            rejected_reward: total_rejected_reward / n,
        };

        (metrics.loss, metrics)
    }

    /// Length-normalized log-ratio: dot(policy - reference, mask) / mask_sum.
    ///
    /// This is the core of length-normalized DPO: instead of summing raw log-ratios
    /// (which favors longer sequences), we divide by the number of response tokens.
    fn norm_ratio(policy: &[f32], reference: &[f32], mask: &[f32]) -> f32 {
        let n = policy.len().min(reference.len()).min(mask.len());
        let mask_sum: f32 = mask[..n].iter().copied().sum::<f32>().max(1.0);
        let dot: f32 = (0..n).map(|i| (policy[i] - reference[i]) * mask[i]).sum();
        dot / mask_sum
    }
}

impl GpuDpoLoss {
    /// Create a new GPU DPO loss computation context.
    pub fn new(ctx: Arc<GpuContext>, pipelines: Arc<GpuPipelines>) -> Result<Self, GpuError> {
        let device = &ctx.device;

        let uniform_dpo = device.create_buffer(&BufferDescriptor {
            label: Some("u_dpo"),
            size: 64,
            usage: BufferUsages::UNIFORM | BufferUsages::COPY_DST,
            mapped_at_creation: false,
        });

        Ok(Self {
            ctx,
            pipelines,
            uniform_dpo,
        })
    }

    fn write_uniform<T: bytemuck::Pod>(&self, buffer: &Buffer, data: &T) {
        let bytes = bytemuck::cast_slice(std::slice::from_ref(data));
        self.ctx.queue.write_buffer(buffer, 0, bytes);
    }

    /// Compute DPO loss on GPU.
    ///
    /// # Arguments
    /// - `input`: [`GpuDpoInput`] grouping logprob buffers, masks, shape, and β
    ///
    /// # Returns
    /// DpoMetrics with loss, accuracy, margin, rewards
    pub fn compute_dpo_loss(&self, input: &GpuDpoInput) -> Result<DpoMetrics, GpuError> {
        if input.num_pairs == 0 {
            return Ok(DpoMetrics {
                loss: 0.0,
                accuracy: 0.0,
                margin: 0.0,
                chosen_reward: 0.0,
                rejected_reward: 0.0,
            });
        }

        let device = &self.ctx.device;
        let queue = &self.ctx.queue;

        // Output buffers
        // dpo_log_ratio outputs: chosen_partial_sum + rejected_partial_sum per pair
        let total_samples = input.num_pairs * 2; // chosen + rejected
        let partial_sums = create_buffer(device, total_samples, "dpo_partial_sums");

        // dpo_reduce outputs: [loss, accuracy, margin, chosen_reward, rejected_reward] (5 f32s)
        let metrics_buf = create_buffer(device, 5, "dpo_metrics");

        // Upload uniform params
        self.write_uniform(
            &self.uniform_dpo,
            &DpoParams {
                num_pairs: input.num_pairs as u32,
                seq_len: input.seq_len as u32,
                beta: input.beta,
                _pad: 0,
            },
        );

        // Dispatch 1: dpo_log_ratio — per-token log-ratio × mask, accumulate partial sums
        let bg_log_ratio = simple_bind_group(
            device,
            &self.pipelines.dpo_log_ratio.bind_group_layout,
            &[
                (0, input.policy_chosen_logprobs),
                (1, input.policy_rejected_logprobs),
                (2, input.ref_chosen_logprobs),
                (3, input.ref_rejected_logprobs),
                (4, input.chosen_mask),
                (5, input.rejected_mask),
                (6, &partial_sums),
                (7, &self.uniform_dpo),
            ],
            Some("bg_dpo_log_ratio"),
        );

        let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor {
            label: Some("dpo_log_ratio"),
        });

        {
            let mut pass = encoder.begin_compute_pass(&ComputePassDescriptor {
                label: Some("dpo_log_ratio"),
                timestamp_writes: None,
            });
            pass.set_pipeline(&self.pipelines.dpo_log_ratio.pipeline);
            pass.set_bind_group(0, &bg_log_ratio, &[]);
            // One invocation per pair (processes chosen + rejected together)
            pass.dispatch_workgroups(dispatch_1d(input.num_pairs, 64)[0], 1, 1);
        }

        // Dispatch 2: dpo_reduce — sigmoid loss + metrics from pre-computed ratios
        let bg_reduce = simple_bind_group(
            device,
            &self.pipelines.dpo_reduce.bind_group_layout,
            &[
                (0, &partial_sums),
                (1, &metrics_buf),
                (2, &self.uniform_dpo),
            ],
            Some("bg_dpo_reduce"),
        );

        {
            let mut pass = encoder.begin_compute_pass(&ComputePassDescriptor {
                label: Some("dpo_reduce"),
                timestamp_writes: None,
            });
            pass.set_pipeline(&self.pipelines.dpo_reduce.pipeline);
            pass.set_bind_group(0, &bg_reduce, &[]);
            // One workgroup handles all pairs (tree reduction pattern)
            pass.dispatch_workgroups(dispatch_1d(input.num_pairs, 256)[0], 1, 1);
        }

        queue.submit(std::iter::once(encoder.finish()));

        // Download metrics: [loss, accuracy, margin, chosen_reward, rejected_reward]
        let metrics_data = download_f32(device, queue, &metrics_buf, 5)?;

        Ok(DpoMetrics {
            loss: metrics_data[0],
            accuracy: metrics_data[1],
            margin: metrics_data[2],
            chosen_reward: metrics_data[3],
            rejected_reward: metrics_data[4],
        })
    }
}

