use crate::optimizer_laprop_gpu::{LaPropGpuConfig, LaPropOptimizer, LaPropParams, NuSchedule};

/// Which optimizer a GPU LoRA trainer drives.
///
/// The LaProp arm carries an OPTIONAL explicit config: `None` derives one from
/// the trainer's own [`AdamWConfig`] at matched schedule (see
/// [`laprop_config_from_adamw`]), which is what Phase 2 T2's "2 arms at equal
/// compute" needs; `Some` overrides every hyperparameter, which is what Phase 4
/// T1 (nu-schedule) and T2 (equal-effective-decay isolation) need.
#[derive(Clone, Copy, Debug, Default)]
pub enum OptimizerChoice {
    /// The incumbent. Unchanged behaviour, unchanged kernel.
    #[default]
    AdamW,
    /// Plan 354's LaProp — division inside the momentum EMA, no clip pass.
    #[cfg(feature = "laprop_optimizer")]
    LaProp(Option<LaPropGpuConfig>),
}

impl OptimizerChoice {
    /// Short arm label for logs and benchmark tables.
    #[must_use]
    pub fn label(&self) -> &'static str {
        match self {
            Self::AdamW => "adamw",
            #[cfg(feature = "laprop_optimizer")]
            Self::LaProp(_) => "laprop",
        }
    }

impl CpuOptimizerChoice {
    #[must_use]
    pub fn label(&self) -> &'static str {
        match self {
            Self::AdamW => "adamw",
            #[cfg(feature = "laprop_optimizer")]
            Self::LaProp => "laprop",
        }
    }
}

impl LoraOptimizer {
    /// Build the arm named by `choice`, deriving LaProp HP from `adamw` when
    /// the choice carries no explicit config.
    #[must_use]
    pub fn new(
        choice: OptimizerChoice,
        ctx: Arc<GpuContext>,
        pipelines: Arc<GpuPipelines>,
        adamw: AdamWConfig,
    ) -> Self {
        match choice {
            OptimizerChoice::AdamW => Self::AdamW(AdamWOptimizer::new(ctx, adamw, pipelines)),
            #[cfg(feature = "laprop_optimizer")]
            OptimizerChoice::LaProp(explicit) => Self::LaProp(LaPropOptimizer::new(
                ctx,
                pipelines,
                explicit.unwrap_or_else(|| laprop_config_from_adamw(&adamw)),
            )),
        }
    }

    /// The arm's label, for logs and benchmark tables.
    #[must_use]
    pub fn label(&self) -> &'static str {
        match self {
            Self::AdamW(_) => "adamw",
            #[cfg(feature = "laprop_optimizer")]
            Self::LaProp(_) => "laprop",
        }
    }

    /// One optimizer step over every LoRA adapter's A and B matrices.
    pub fn step(&mut self, lora: &GpuLoraBuffers) -> Result<(), GpuError> {
        match self {
            Self::AdamW(o) => o.step(lora),
            #[cfg(feature = "laprop_optimizer")]
            Self::LaProp(o) => o.step(lora),
        }
    }

    /// Gradient clipping. An explicit no-op on the LaProp arm (Prop-1 bound),
    /// so a caller that clips unconditionally still gets a correct step — it
    /// just does not get to attribute a slowdown to LaProp.
    pub fn clip_gradients(&self, lora: &GpuLoraBuffers, grad_clip: f32) -> Result<f32, GpuError> {
        match self {
            Self::AdamW(o) => o.clip_gradients(lora, grad_clip),
            #[cfg(feature = "laprop_optimizer")]
            Self::LaProp(o) => o.clip_gradients(lora, grad_clip),
        }
    }

    #[must_use]
    pub fn current_lr(&self) -> f32 {
        match self {
            Self::AdamW(o) => o.current_lr(),
            #[cfg(feature = "laprop_optimizer")]
            Self::LaProp(o) => o.current_lr(),
        }
    }

    /// Warmup + cosine-decay LR. Both arms honour the same contract, which is
    /// what makes "equal schedule, different optimizer" a true statement.
    #[must_use]
    pub fn effective_lr(&self) -> f32 {
        match self {
            Self::AdamW(o) => o.effective_lr(),
            #[cfg(feature = "laprop_optimizer")]
            Self::LaProp(o) => o.effective_lr(),
        }
    }

    #[must_use]
    pub fn current_step(&self) -> u32 {
        match self {
            Self::AdamW(o) => o.current_step(),
            #[cfg(feature = "laprop_optimizer")]
            Self::LaProp(o) => o.current_step(),
        }
    }

    /// Enable cosine decay to `total_steps` with an LR floor of
    /// `min_lr_ratio * base_lr`, on whichever arm is live.
    pub fn set_cosine_schedule(&mut self, total_steps: usize, min_lr_ratio: f32) {
        match self {
            Self::AdamW(o) => o.set_cosine_schedule(total_steps, min_lr_ratio),
            #[cfg(feature = "laprop_optimizer")]
            Self::LaProp(o) => o.set_cosine_schedule(total_steps, min_lr_ratio),
        }
    }

    /// The AdamW optimizer, if this is the AdamW arm. For the AdamW-only entry
    /// points (`step_ia3`, `step_moa`, `step_domain_latent`, ...) that LaProp
    /// has no counterpart for yet: `None` says so instead of a silent skip.
    #[must_use]
    pub fn as_adamw(&self) -> Option<&AdamWOptimizer> {
        match self {
            Self::AdamW(o) => Some(o),
            #[cfg(feature = "laprop_optimizer")]
            Self::LaProp(_) => None,
        }
    }

    #[must_use]
    pub fn as_adamw_mut(&mut self) -> Option<&mut AdamWOptimizer> {
        match self {
            Self::AdamW(o) => Some(o),
            #[cfg(feature = "laprop_optimizer")]
            Self::LaProp(_) => None,
        }
    }

    /// The uniform the LAST [`Self::step`] wrote, when this is the LaProp arm.
    ///
    /// A trainer with non-LoRA parameters (dflash's FC weight + RMSNorm gamma,
    /// DFlare's fusion weights) drives the `laprop_step` kernel inline for
    /// those, and must use the SAME per-step `inv_bc2` / `step_size`
    /// recurrences as the LoRA half — recomputing them locally would be a
    /// second copy of the state, free to drift. `None` before the first step,
    /// or on the AdamW arm.
    #[cfg(feature = "laprop_optimizer")]
    #[must_use]
    pub fn laprop_step_params(&self) -> Option<LaPropParams> {
        match self {
            Self::AdamW(_) => None,
            Self::LaProp(o) => o.last_step_params(),
        }
    }
}

