impl TemplateProposerAdapter {
    pub fn new(config: GrpoConfig) -> Self {
        Self {
            patterns: TemplatePattern::all_patterns(),
            next_pattern_idx: 0,
            config,
        }
    }

    /// Create with default GRPO config.
    pub fn default_config() -> Self {
        Self::new(GrpoConfig::default())
    }

    /// Get the number of available template patterns.
    pub fn pattern_count(&self) -> usize {
        self.patterns.len()
    }

    /// Get template distribution (for logging).
    pub fn template_distribution(&self) -> Vec<(QueryTemplate, f32)> {
        let n = QueryTemplate::all().len() as f32;
        QueryTemplate::all().iter().map(|t| (*t, 1.0 / n)).collect()
    }

    fn fill_placeholder(template: &str, idx: usize) -> String {
        // Pre-allocate: placeholders add ~30 chars each, template is ~50 chars
        let estimated_len = template.len() + 30;
        let mut result = String::with_capacity(estimated_len);

        // Process template character by character, replacing placeholders inline
        let mut chars = template.chars().peekable();
        while let Some(ch) = chars.next() {
            if ch == '{' {
                // Try to read a placeholder
                let placeholder: String = chars.by_ref().take_while(|&c| c != '}').collect();
                match placeholder.as_str() {
                    "style" => {
                        result.push_str(match idx % 4 {
                            0 => "concise",
                            1 => "formal",
                            2 => "engaging",
                            _ => "technical",
                        });
                    }
                    "audience" => {
                        result.push_str(match idx % 3 {
                            0 => "beginner",
                            1 => "intermediate",
                            _ => "expert",
                        });
                    }
                    "context" => result.push_str("the provided text passage"),
                    "concept" => result.push_str("abstraction"),
                    "alt_concept" => result.push_str("encapsulation"),
                    "domain" => result.push_str("software engineering"),
                    "problem" => result.push_str("the given challenge"),
                    "option_a" => result.push_str("option A"),
                    "option_b" => result.push_str("option B"),
                    "use_case" => result.push_str("the specified scenario"),
                    "approach" => result.push_str("the proposed method"),
                    "functionality" => result.push_str("the required feature"),
                    "language" => result.push_str("Rust"),
                    "code_snippet" => result.push_str("the code"),
                    "unexpected" => result.push_str("the error"),
                    "premise" => result.push_str("the given assumption"),
                    // Unknown placeholder — preserve original
                    other => {
                        result.push('{');
                        result.push_str(other);
                        result.push('}');
                    }
                }
            } else {
                result.push(ch);
            }
        }

        result
    }
}

