impl ScreeningResult {
    /// Analyze gradient norm history from a probe and produce a ranking.
    ///
    /// The `tracker` should contain snapshots from each probe step.
    /// Targets are ranked by average gradient L2 norm (descending).
    /// Top-K targets are recommended for full training.
    pub fn from_probe(tracker: &GradNormTracker, screening_config: &ScreeningConfig) -> Self {
        if tracker.is_empty() {
            return Self {
                probe_steps: 0,
                rankings: Vec::new(),
                recommended_targets: Vec::new(),
                skipped_targets: Vec::new(),
                total_targets: 0,
            };
        }

        let snapshots = tracker.snapshots();
        let probe_steps = snapshots.len();

        // Determine the number of adapters from the first snapshot.
        let n_adapters = snapshots.first().map_or(0, |s| s.norms.len());

        // Compute per-target statistics across probe steps in a single pass
        // (avoids allocating a Vec<f32> per adapter)
        let mut entries: Vec<TargetGradRank> = (0..n_adapters)
            .map(|adapter_idx| {
                let mut sum = 0.0f32;
                let mut count = 0usize;
                let mut max = 0.0f32;
                let mut min = f32::MAX;

                for s in snapshots {
                    if let Some(&norm) = s.norms.get(adapter_idx) {
                        sum += norm;
                        count += 1;
                        max = norm.max(max);
                        min = norm.min(min);
                    }
                }

                let avg = if count > 0 { sum / count as f32 } else { 0.0 };

                TargetGradRank {
                    target: format!("adapter{adapter_idx}"),
                    avg_grad_norm: avg,
                    max_grad_norm: max,
                    min_grad_norm: if min == f32::MAX { 0.0 } else { min },
                    rank: 0, // assigned below
                }
            })
            .collect();

        // Sort by average gradient norm descending
        entries.sort_by(|a, b| {
            b.avg_grad_norm
                .partial_cmp(&a.avg_grad_norm)
                .unwrap_or(std::cmp::Ordering::Equal)
        });

        // Assign ranks
        for (i, entry) in entries.iter_mut().enumerate() {
            entry.rank = i + 1;
        }

        let total_targets = entries.len();

        // Select top-K
        let k = screening_config
            .top_k
            .unwrap_or(total_targets)
            .min(total_targets);

        let recommended_targets: Vec<String> =
            entries.iter().take(k).map(|e| e.target.clone()).collect();

        let skipped_targets: Vec<String> =
            entries.iter().skip(k).map(|e| e.target.clone()).collect();

        Self {
            probe_steps,
            rankings: entries,
            recommended_targets,
            skipped_targets,
            total_targets,
        }
    }

    /// Get the top-K targets from the ranking.
    pub fn top_k(&self, k: usize) -> &[TargetGradRank] {
        let end = k.min(self.rankings.len());
        &self.rankings[..end]
    }

    /// Get recommended target keys as `LoraTarget` enums.
    ///
    /// Parses target keys like "layer0_q" → LoraTarget::Q.
    /// Returns only targets that could be parsed (ignores malformed keys).
    pub fn recommended_lora_targets(&self) -> Vec<(usize, LoraTarget)> {
        let mut result = Vec::with_capacity(self.recommended_targets.len());

        for key in &self.recommended_targets {
            if let Some((layer, target)) = parse_target_key(key) {
                result.push((layer, target));
            }
        }

        result
    }

    /// Compute the fraction of compute saved by skipping targets.
    ///
    /// Returns (skipped_count / total_count) as a fraction.
    pub fn compute_savings_fraction(&self) -> f32 {
        if self.total_targets == 0 {
            return 0.0;
        }
        self.skipped_targets.len() as f32 / self.total_targets as f32
    }

    /// Summary string for logging.
    pub fn summary(&self) -> String {
        let savings_pct = self.compute_savings_fraction() * 100.0;
        format!(
            "Screening: {recommended}/{total} targets selected, {skipped} skipped ({savings_pct:.0}% compute savings)",
            recommended = self.recommended_targets.len(),
            total = self.total_targets,
            skipped = self.skipped_targets.len(),
        )
    }
}

impl BetaConfig {
    pub fn learning_rate(&self) -> f32 {
        1e-4 + 9e-4 * self.beta
    }

    pub fn lora_rank(&self) -> usize {
        (4.0 + 28.0 * self.beta) as usize
    }

