        0.01 - 0.009 * self.beta
    }

    pub fn epochs(&self) -> usize {
        (1.0 + 9.0 * self.beta) as usize
    }

    pub fn draft_rank(&self) -> usize {
        (2.0 + 6.0 * self.beta) as usize
    }

    /// OFT block size derived from beta.
    /// Plan 160: block_size = 32 + 96 * beta → 32 at beta=0, 128 at beta=1.
    /// Larger blocks = more expressive but more parameters per block.
    pub fn oft_block_size(&self) -> u32 {
        (32.0 + 96.0 * self.beta) as u32
    }

    /// SPEFT density (ρ): fraction of trainable params.
    /// Plan 162: 0.001 + 0.004 * beta → 0.1% at beta=0, 0.5% at beta=1.
    /// Only meaningful when `tuning_method` is `TuningMethod::Speft`.
    #[cfg(feature = "speft_training")]
    pub fn speft_density(&self) -> f32 {
        0.001 + 0.004 * self.beta
    }
}

impl ReviewMetrics {
    /// Ratio of helpful to harmful epochs. Returns `helpful / max(harmful, 1)`.
    pub fn benefit_ratio(&self) -> f64 {
        self.helpful_epochs as f64 / self.harmful_epochs.max(1) as f64
    }

    /// Record a single epoch's loss change and classify it.
    ///
    /// - Sets `baseline_loss` on first call (when it is 0.0).
    /// - `delta > tolerance` → helpful
    /// - `delta < -tolerance` → harmful
    /// - otherwise → neutral
    /// - Tracks `best_loss` as the minimum observed `curr_loss`.
    pub fn record_epoch(&mut self, prev_loss: f32, curr_loss: f32, tolerance: f32) {
        if self.baseline_loss == 0.0 {
            self.baseline_loss = prev_loss;
        }

        let delta = prev_loss - curr_loss;

        match delta {
            d if d > tolerance => self.helpful_epochs += 1,
            d if d < -tolerance => self.harmful_epochs += 1,
            _ => self.neutral_epochs += 1,
        }

        if self.best_loss == 0.0 || curr_loss < self.best_loss {
            self.best_loss = curr_loss;
        }
    }
}

impl GameMetrics {
    /// Training was helpful if final win rate exceeds baseline.
    pub fn helpful(&self) -> bool {
        self.final_win_rate > self.baseline_win_rate
    }

    /// Improvement in win rate from baseline to final.
    pub fn win_delta(&self) -> f32 {
        self.final_win_rate - self.baseline_win_rate
    }
}

