/// Loss masking strategy for multi-turn training data.
///
/// Controls which tokens contribute to the SFT gradient.
/// From Plan 074: Interventional SFT Token Masking.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
#[repr(u8)]
pub enum LossMask {
    /// Standard SFT: supervise every token uniformly.
    /// Corresponds to L_obs from the paper — treats agent outputs as evidence.
    /// Safe for single-turn data. Causes self-confirmation on multi-turn agent data.
    #[default]
    Observational,
    /// Interventional SFT: mask agent-written tokens from loss.
    /// Corresponds to L_do from the paper — treats agent outputs as interventions.
    /// Requires `role_gates` in training data. Agent tokens still appear in context.
    Interventional,
}

